INSERT INTO public.ingredients VALUES (1669, '2025-11-20 17:11:00.0399', '2025-11-20 17:11:00.0399', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 'cá tràu (cá quả, cá lóc đồng) cỡ vừa 600 - 650 gram', NULL, NULL);
INSERT INTO public.ingredients VALUES (1670, '2025-11-20 17:11:00.073041', '2025-11-20 17:11:00.073041', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 'Nước vo gạo, chanh, muối hạt để sơ chế, khử mùi', NULL, NULL);
INSERT INTO public.ingredients VALUES (1671, '2025-11-20 17:11:00.109179', '2025-11-20 17:11:00.109179', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 'khế chua (một nửa giã vắt nước, 1 nửa thái lát mỏng hình sao)', NULL, NULL);
INSERT INTO public.ingredients VALUES (1672, '2025-11-20 17:11:00.142549', '2025-11-20 17:11:00.142549', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 'Hành lá, mùi tàu (ngò gai)', NULL, NULL);
INSERT INTO public.ingredients VALUES (1673, '2025-11-20 17:11:00.18063', '2025-11-20 17:11:00.18063', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 'hành tím, băm nhỏ (ở Nghệ An thường dùng hành tăm)', NULL, NULL);
INSERT INTO public.ingredients VALUES (1674, '2025-11-20 17:11:00.214339', '2025-11-20 17:11:00.214339', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 'sả (cách nấu miền Nam thường thêm vào, nhưng miền Trung không cho sả)', NULL, NULL);
INSERT INTO public.ingredients VALUES (1675, '2025-11-20 17:11:00.24705', '2025-11-20 17:11:00.24705', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 'ớt hiểm (gia giảm theo khẩu vị, nếu nhà có trẻ em thì không cho ớt)', NULL, NULL);
INSERT INTO public.ingredients VALUES (1676, '2025-11-20 17:11:00.370852', '2025-11-20 17:11:00.370852', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 'ngan khoảng 2,4 - 2,5 kg, chọn ngan nuôi lúa, già tháng sẽ ngon hơn vì thịt dày chắc, ít mỡ', NULL, NULL);
INSERT INTO public.ingredients VALUES (1677, '2025-11-20 17:11:00.404627', '2025-11-20 17:11:00.404627', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 'sả (một nửa băm nhuyễn, một nửa giã nhỏ để khi ướp nhanh thấm)', NULL, NULL);
INSERT INTO public.ingredients VALUES (1678, '2025-11-20 17:11:00.442', '2025-11-20 17:11:00.442', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 'riềng vừa (một nửa băm nhuyễn, một nửa giã nhỏ), nên chọn riềng bánh tẻ', NULL, NULL);
INSERT INTO public.ingredients VALUES (1679, '2025-11-20 17:11:00.476028', '2025-11-20 17:11:00.476028', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 'hành tăm (hành nhỏ, đặc trưng ở Nghệ An), nếu không có thì thay bằng hành tím, băm nhỏ', NULL, NULL);
INSERT INTO public.ingredients VALUES (1680, '2025-11-20 17:11:00.50933', '2025-11-20 17:11:00.50933', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 'lá tắt (lá quýt hôi). Nếu ở nước ngoài không có, bạn có thể mua vỏ quýt khô (trần bì) của châu Á', NULL, NULL);
INSERT INTO public.ingredients VALUES (1681, '2025-11-20 17:11:00.542136', '2025-11-20 17:11:00.542136', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 'nước chè xanh om (vừa giúp khử mùi tanh của ngan hiệu quả, vừa quyện với mật mía tạo cho thịt vị đậm đà). Nếu không có chè xanh, có thể thay thế bằng nước trà', NULL, NULL);
INSERT INTO public.ingredients VALUES (1682, '2025-11-20 17:11:00.575467', '2025-11-20 17:11:00.575467', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 'lá sắn (tùy chọn, một số huyện như Thanh Chương, Nghệ An thường cho thêm lá sắn vào)', NULL, NULL);
INSERT INTO public.ingredients VALUES (1683, '2025-11-20 17:11:00.611578', '2025-11-20 17:11:00.611578', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 'ruốc hôi (mắm tôm). Chọn mắm tôm có màu hơi ửng hồng hoặc tím xám là loại mắm ngon, dậy mùi thơm đặc trưng', NULL, NULL);
