INSERT INTO public.ingredients VALUES (1861, '2025-11-20 17:11:09.017976', '2025-11-20 17:11:09.017976', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 'Trang trí', NULL, NULL);
INSERT INTO public.ingredients VALUES (1862, '2025-11-20 17:11:09.121667', '2025-11-20 17:11:09.121667', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 'a) Phần cá và gia vị ướp', NULL, NULL);
