INSERT INTO public.ingredients VALUES (1867, '2025-11-20 17:11:09.295184', '2025-11-20 17:11:09.295184', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 'Bột chiên giòn (nếu không có thì bạn dùng bột mì số 11 hoặc 13 để có độ giòn lâu)', NULL, NULL);
