INSERT INTO public.ingredients VALUES (1870, '2025-11-20 17:11:09.475232', '2025-11-20 17:11:09.475232', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 'a) Phần thịt và nguyên liệu sơ chế khử mùi (để thịt thơm ngon hơn)', NULL, NULL);
