INSERT INTO public.ingredients VALUES (1872, '2025-11-20 17:11:09.566858', '2025-11-20 17:11:09.566858', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 'b) Nguyên liệu khác', NULL, NULL);
