INSERT INTO public.ingredients VALUES (1875, '2025-11-20 17:11:09.668004', '2025-11-20 17:11:09.668004', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 'c) Gia vị', NULL, NULL);
INSERT INTO public.ingredients VALUES (1876, '2025-11-20 17:11:09.701902', '2025-11-20 17:11:09.701902', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 'd) Vật dụng đựng', NULL, NULL);
INSERT INTO public.ingredients VALUES (1877, '2025-11-20 17:11:09.808701', '2025-11-20 17:11:09.808701', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 'a) Chuẩn bị phần nhân', NULL, NULL);
INSERT INTO public.ingredients VALUES (1878, '2025-11-20 17:11:09.843703', '2025-11-20 17:11:09.843703', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 'ốc nhồi tươi hoặc ốc hạt mít tươi (sau khi làm sạch, lấy ruột ốc thì còn khoảng 350-400 gram)', NULL, NULL);
