INSERT INTO public.ingredients VALUES (1885, '2025-11-20 17:11:10.086275', '2025-11-20 17:11:10.086275', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 'giá đậu, cắt nhỏ', NULL, NULL);
