INSERT INTO public.recipe_steps VALUES (169, '2025-11-20 17:09:47.839383', '2025-11-20 17:09:47.839383', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 39, 2, 'Sơ chế
INSERT INTO public.recipe_steps VALUES (170, '2025-11-20 17:09:47.841656', '2025-11-20 17:09:47.841656', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 39, 1, 'Tré là món ăn đặc sản của một số tỉnh miền Trung, đặc biệt là Bình Định. Tré được làm từ thịt đầu heo, tai heo, mũi heo, thịt ba rọi  (ba chỉ) cùng  với thịt bò theo tỉ lệ nhất định. Sau khi đã thực hiện qua các bước sơ chế, chúng được gói một lớp lá ổi, một lớp lá chuối bên ngoài. Để tré lên men người dân sẽ dùng một lớp rơm vàng, sau đó đặt chúng ở vị trí khô ráo khoảng 3 đến 4 ngày là có thể dùng.', 10);
INSERT INTO public.recipe_steps VALUES (171, '2025-11-20 17:09:48.035018', '2025-11-20 17:09:48.035018', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 40, 2, 'Thực hiện
