INSERT INTO public.recipe_steps VALUES (177, '2025-11-20 17:09:48.17696', '2025-11-20 17:09:48.17696', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 41, 3, 'Chiên gà và xóc bơ tỏi
INSERT INTO public.recipe_steps VALUES (178, '2025-11-20 17:09:48.267317', '2025-11-20 17:09:48.267317', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 42, 3, 'Dưa món giòn ngon, đậm vị mặn ngọt. Đây là món ăn truyền thống nhiều gia đình miền Trung, miền Nam vào ngày Tết cùng bánh chưng, bánh tét cho cân bằng vị.', 10);
INSERT INTO public.recipe_steps VALUES (179, '2025-11-20 17:09:48.269426', '2025-11-20 17:09:48.269426', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 42, 2, 'Thực hiện
INSERT INTO public.recipe_steps VALUES (180, '2025-11-20 17:09:48.272142', '2025-11-20 17:09:48.272142', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 42, 1, 'Sơ chế
INSERT INTO public.recipe_steps VALUES (181, '2025-11-20 17:09:48.377717', '2025-11-20 17:09:48.377717', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 43, 2, 'Cho mực vào ngâm trong hỗn hợp rượu trắng cùng gừng giã dập để khử mùi tanh. Sau đó nướng sơ, xé mực thành các sợi nhỏ, đều tay. Ướp mực cùng chút mắm, muối, đường, hạt nêm cho đậm vị.', 10);
INSERT INTO public.recipe_steps VALUES (182, '2025-11-20 17:09:48.381204', '2025-11-20 17:09:48.381204', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 43, 4, 'Tiếp tục phi thơm 1/2 lượng hành khô băm nhỏ còn lại, cho su hào và cà rốt vào xào. Nêm nếm mắm, muối, hạt nêm vừa vị.', 10);
INSERT INTO public.recipe_steps VALUES (183, '2025-11-20 17:09:48.383344', '2025-11-20 17:09:48.383344', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 43, 5, 'Khi su hào, cà rốt vừa chín tới thì trút mực đã xào săn vào, đảo đều tay. Nêm nếm lại gia vị, thêm rau thơm và tắt bếp, múc ra rắc chút hạt tiêu và thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (184, '2025-11-20 17:09:48.385464', '2025-11-20 17:09:48.385464', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 43, 1, 'Su hào gọt bỏ vỏ, rửa sạch, thái sợi nhỏ. Cà rốt gọt vỏ, bào sợi. Có 2 cách để làm su hào, cà rốt giòn, khô ráo: Cách 1: Cho su hào, cà rốt vào âu/thau ướp với một chút muối hạt để trong 10-15 phút, sau đó rửa sạch nhiều lần, vắt nhẹ (bằng tay hoặc khăn xô) để giúp khô ráo. Cách 2: Cho su hào, cà rốt cùng chút nước, muối vào chảo, đảo liên tục. Khi bốc hơi thì tắt bếp, vắt ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (185, '2025-11-20 17:09:48.388141', '2025-11-20 17:09:48.388141', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 43, 6, 'Yêu cầu thành phẩm: Su hào, cà rốt khô ráo, ngọt tự nhiên; mực giòn sần sật, không dai hay tanh. Đây là món ăn quen thuộc trong các dịp đặc biệt của người dân Bát Tràng, Hà Nội.', 10);
INSERT INTO public.recipe_steps VALUES (186, '2025-11-20 17:09:48.390205', '2025-11-20 17:09:48.390205', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 43, 3, 'Phi thơm 1/2 lượng hành băm nhỏ, cho mực vào xào săn, ráo nước. Múc ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (187, '2025-11-20 17:09:48.461148', '2025-11-20 17:09:48.461148', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 44, 4, 'Yêu cầu thành phẩm
