INSERT INTO public.recipe_steps VALUES (190, '2025-11-20 17:09:48.466775', '2025-11-20 17:09:48.466775', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 44, 2, 'Tẩm ướp
INSERT INTO public.recipe_steps VALUES (191, '2025-11-20 17:09:48.555813', '2025-11-20 17:09:48.555813', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 45, 3, 'Sên mứt
INSERT INTO public.recipe_steps VALUES (192, '2025-11-20 17:09:48.557943', '2025-11-20 17:09:48.557943', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 45, 1, 'Sơ chế
INSERT INTO public.recipe_steps VALUES (193, '2025-11-20 17:09:48.560058', '2025-11-20 17:09:48.560058', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 45, 4, 'Yêu cầu thành phẩm
INSERT INTO public.recipe_steps VALUES (194, '2025-11-20 17:09:48.562197', '2025-11-20 17:09:48.562197', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 45, 2, 'Ướp đường
INSERT INTO public.recipe_steps VALUES (195, '2025-11-20 17:09:48.679765', '2025-11-20 17:09:48.679765', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 46, 8, 'Đổ nước mắm đường đã để nguội (hoặc lạnh) vào xâm xấp mặt và ngâm. Sau khoảng 4 - 6 giờ là ăn được. Nên đậy kín, để ngâm qua đêm trong ngăn mát tủ lạnh hôm sau ăn gia vị thấm sẽ ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (196, '2025-11-20 17:09:48.681881', '2025-11-20 17:09:48.681881', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 46, 3, 'Khi sôi vớt bọt, hạ lửa nhỏ vừa luộc trong 3 phút rồi tắt bếp, đậy vung om 5 phút thì chân gà sẽ chín mà không bị đỏ xương.', 10);
INSERT INTO public.recipe_steps VALUES (197, '2025-11-20 17:09:48.683933', '2025-11-20 17:09:48.683933', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 46, 5, 'Nấu nước mắm ngâm chân gà theo tỷ lệ 1:1:1:3 (gồm 1 bát nhỏ nước mắm 30-40 độ đạm, 1 bát đường, 1 bát giấm, 3 bát nước). Thêm 1 thìa cà phê muối. Khi sôi, hạ lửa vớt bọt, tắt bếp, để nguội rồi cho vào ngăn mát tủ lạnh. Nước ngâm càng mát lạnh thì chân gà càng giòn.', 10);
INSERT INTO public.recipe_steps VALUES (198, '2025-11-20 17:09:48.686342', '2025-11-20 17:09:48.686342', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 46, 9, 'Yêu cầu thành phẩm: Chân gà trắng giòn, thơm mùi sả tắc, ngấm vị chua cay mặn ngọt hài hòa rất hấp dẫn. Đảm bảo chân gà không đắng, không nhớt.', 10);
INSERT INTO public.recipe_steps VALUES (199, '2025-11-20 17:09:48.689051', '2025-11-20 17:09:48.689051', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 46, 4, 'Vớt chân gà ra tô/hoặc thau nước đun sôi để nguội, thêm chút đường bóp cho hết váng mỡ. Sau đó, cho chân gà vào ngâm nước đá, thêm vài lát chanh và để ngăn mát tủ lạnh 1-2 giờ cho giòn trắng. Vớt ra để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (200, '2025-11-20 17:09:48.691163', '2025-11-20 17:09:48.691163', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 46, 1, 'Chân gà làm sạch, cắt móng, bóp chanh và muối hạt rửa sạch. Sau đó, chặt đôi hoặc để nguyên tùy sở thích.', 10);
INSERT INTO public.recipe_steps VALUES (201, '2025-11-20 17:09:48.69328', '2025-11-20 17:09:48.69328', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 46, 2, 'Cho chân gà vào nồi cùng lượng nước xâm xấp, thêm vài lát gừng, sả đập dập, 1/2 củ hành tây, 2 củ hành tím, chút muối hạt, hạt tiêu và chút rượu trắng để đảm bảo chân gà được thơm ngon.', 10);
INSERT INTO public.recipe_steps VALUES (202, '2025-11-20 17:09:48.69541', '2025-11-20 17:09:48.69541', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 46, 6, 'Tỏi thái lát, sả thái vát mỏng, 2/3 lượng quất vắt lấy nước cốt, 1/2 thì cắt lát bỏ hạt (để không bị đắng), gừng thái sợi, ớt sừng bỏ hạt thái mỏng, ớt hiểm để nguyên trái hoặc thái nhỏ tùy theo sở thích.', 10);
INSERT INTO public.recipe_steps VALUES (203, '2025-11-20 17:09:48.696989', '2025-11-20 17:09:48.696989', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 46, 7, 'Xếp lần lượt một lớp chân gà xen kẽ một lớp sả, tắc, ớt, tỏi.', 10);
INSERT INTO public.recipe_steps VALUES (204, '2025-11-20 17:09:48.784549', '2025-11-20 17:09:48.784549', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 47, 3, 'Yêu cầu thành phẩm
INSERT INTO public.recipe_steps VALUES (205, '2025-11-20 17:09:48.786684', '2025-11-20 17:09:48.786684', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 47, 1, 'Sơ chế
INSERT INTO public.recipe_steps VALUES (3884, '2025-11-20 17:11:52.620631', '2025-11-20 17:11:52.620631', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 617, 2, 'Bọc kín lại, ủ bột trong 15 phút.', 10);
INSERT INTO public.recipe_steps VALUES (206, '2025-11-20 17:09:48.788643', '2025-11-20 17:09:48.788643', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 47, 2, 'Chế biến
INSERT INTO public.recipe_steps VALUES (207, '2025-11-20 17:09:48.883072', '2025-11-20 17:09:48.883072', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 48, 6, 'Xếp thịt vào hũ thủy tinh sạch (đã tiệt trùng, để ráo), thêm hành tím thái lát, ớt, dùng vỉ nén chèn miệng hũ, rồi đổ hỗn hợp nước mắm đường vào ngập thịt, đậy nắp kín, để ở nơi thoáng mát.', 10);
INSERT INTO public.recipe_steps VALUES (208, '2025-11-20 17:09:48.885238', '2025-11-20 17:09:48.885238', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 48, 4, 'Đun sôi hỗn hợp nước mắm, đường, giấm cho đường tan hết. Thêm hạt tiêu nguyên hạt, tắt bếp, để nguội hoàn toàn.', 10);
INSERT INTO public.recipe_steps VALUES (209, '2025-11-20 17:09:48.887373', '2025-11-20 17:09:48.887373', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 48, 5, 'Hành tím bóc vỏ, thái mỏng. Ớt rửa sạch, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (210, '2025-11-20 17:09:48.889487', '2025-11-20 17:09:48.889487', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 48, 7, 'Thịt ngâm mắm khoảng 1 tuần là ăn được. Sau đó, bạn cho vào ngăn mát tủ lạnh để bảo quản được lâu hơn.', 10);
INSERT INTO public.recipe_steps VALUES (211, '2025-11-20 17:09:48.89215', '2025-11-20 17:09:48.89215', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 48, 2, 'Chần thịt với nước sôi để loại bỏ tạp chất, sau đó rửa sạch lại bằng nước sôi để nguội, thấm khô hoặc để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (212, '2025-11-20 17:09:48.893732', '2025-11-20 17:09:48.893732', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 48, 8, 'Yêu cầu thành phẩm: Thịt giò, da ánh lên màu vàng nâu đẹp mắt, vị mặn ngọt hài hòa. Món này ăn kèm bánh tét hoặc cuốn rau thơm, bánh tráng đều rất thu hút và tiện lợi.', 10);
INSERT INTO public.recipe_steps VALUES (213, '2025-11-20 17:09:48.896095', '2025-11-20 17:09:48.896095', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 48, 1, 'Thịt ba chỉ cắt thành khúc dài, chà xát chanh và muối hạt khử mùi, rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (214, '2025-11-20 17:09:48.897266', '2025-11-20 17:09:48.897266', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 48, 3, 'Đeo găng tay thoa chút đường lên các bề mặt thịt để giúp thịt giòn hơn.', 10);
INSERT INTO public.recipe_steps VALUES (215, '2025-11-20 17:09:48.980097', '2025-11-20 17:09:48.980097', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 49, 6, 'Đun sôi nồi nước dùng gà, nêm nếm gia vị mắm, muối, hạt nêm lại theo khẩu vị. Bạn nhớ hớt bỏ bọt nếu có.', 10);
INSERT INTO public.recipe_steps VALUES (216, '2025-11-20 17:09:48.9828', '2025-11-20 17:09:48.9828', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 49, 5, 'Tiếp tục phi thơm hành khô, cho mộc nhĩ và nấm hương vào xào, nêm nêm chút mắm, muối cho săn rồi trút sang nồi nước dùng gà.', 10);
INSERT INTO public.recipe_steps VALUES (217, '2025-11-20 17:09:48.985538', '2025-11-20 17:09:48.985538', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 49, 2, 'Mộc nhĩ, nấm hương ngâm nở, rửa sạch, thái sợi nhỏ. Hành củ băm nhỏ. Hành lá và rau mùi, rửa sạch, thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (218, '2025-11-20 17:09:48.988206', '2025-11-20 17:09:48.988206', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 49, 4, 'Phi thơm hành khô, cho lòng mề gà vào xào, đảo nhẹ tay cho thấm đều gia vị rồi trút sang nồi nước luộc gà.', 10);
INSERT INTO public.recipe_steps VALUES (219, '2025-11-20 17:09:48.990354', '2025-11-20 17:09:48.990354', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 49, 7, 'Khi nước dùng gà sôi 2 -3 phút, cho miến vào nấu vài phút. Khi miến nở (tùy từng loại miến khác nhau mà độ nở nhanh hay chậm), thêm rau mùi, hành lá vào, tắt bếp, múc ra thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (220, '2025-11-20 17:09:48.992508', '2025-11-20 17:09:48.992508', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 49, 3, 'Miến rửa sạch, cắt khúc vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (221, '2025-11-20 17:09:48.995319', '2025-11-20 17:09:48.995319', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 49, 1, 'Lòng gà chà xát muối hạt, chanh để khử mùi, rửa sạch, để ráo. Trong khi luộc gà lễ, cho lòng mề gà vào luộc cùng để cúng đủ bộ. Sau đó, để nguội thái miếng vừa ăn và ướp 1 thìa cà phê nước mắm, 1/2 thìa cà phê muối, 1/2 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu cho đậm đà.', 10);
INSERT INTO public.recipe_steps VALUES (222, '2025-11-20 17:09:49.091823', '2025-11-20 17:09:49.091823', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 50, 2, 'Hoa chuối bóc bỏ phần già, xếp các lớp cánh bắp hoa chuối chồng lên nhau thái mỏng, đặt cạnh thau nước pha nước cốt chanh. Thái tới đâu cho vào thau nước đến đó.', 10);
INSERT INTO public.recipe_steps VALUES (223, '2025-11-20 17:09:49.095146', '2025-11-20 17:09:49.095146', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 50, 4, 'Hành tây thái mỏng, ngâm nước đá lạnh cho bớt hăng và giòn hơn, vớt ra, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (224, '2025-11-20 17:09:49.097107', '2025-11-20 17:09:49.097107', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 50, 5, 'Để tăng thêm màu sắc có thể bào thêm cà rốt, cắt sợi dưa chuột.', 10);
INSERT INTO public.recipe_steps VALUES (225, '2025-11-20 17:09:49.099806', '2025-11-20 17:09:49.099806', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 50, 9, 'Yêu cầu thành phẩm: Thịt gà dai ngọt, hoa chuối, cà rốt giòn ngon, hành tây không hăng, các vị chua, cay, mặn, ngọt hài hòa rất hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (226, '2025-11-20 17:09:49.102356', '2025-11-20 17:09:49.102356', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 50, 1, 'Tận dụng phần thịt gà luộc còn dư ngày Tết, bạn xé nhỏ thành miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (227, '2025-11-20 17:09:49.105528', '2025-11-20 17:09:49.105528', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 50, 7, 'Pha hỗn hợp sốt trộn nộm gồm: 2 thìa canh đường, 2 thìa canh nước mắm, 1 thìa canh nước cốt chanh, khuấy đều cho hỗn hợp tan. Sau đó, thêm 1 thìa canh tỏi băm, 1/2 thìa canh ớt băm (nếu ăn được cay). Điều chỉnh gia vị theo khẩu vị cá nhân.', 10);
INSERT INTO public.recipe_steps VALUES (228, '2025-11-20 17:09:49.10764', '2025-11-20 17:09:49.10764', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 50, 8, 'Cho thịt gà, bắp chuối, cà rốt, hành tây cùng nước sốt trộn nộm vào âu, đeo găng tay và trộn đều cho ngấm gia vị. Để cho ngấm tầm 6- 8 phút, chắt nước. Sau đó thêm rau thơm và lạc rang giã dập vào là hoàn thành.', 10);
INSERT INTO public.recipe_steps VALUES (229, '2025-11-20 17:09:49.109775', '2025-11-20 17:09:49.109775', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 50, 3, 'Ngâm hoa chuối với nước lạnh pha nước cốt chanh trong 20-30 phút để giúp hoa chuối không bị thâm và giòn ngon hơn. Sau đó, vớt ra rửa sạch, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (230, '2025-11-20 17:09:49.111983', '2025-11-20 17:09:49.111983', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 50, 6, 'Trộn đều hoa chuối, hành tây và cà rốt, dưa chuột.', 10);
INSERT INTO public.recipe_steps VALUES (394, '2025-11-20 17:09:51.769601', '2025-11-20 17:09:51.769601', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 73, 4, 'Đeo găng tay, thoa chút dầu ăn hoặc bơ, rồi chia hỗn hợp nhân phô mai thành các khối bằng nhau.', 10);
INSERT INTO public.recipe_steps VALUES (232, '2025-11-20 17:09:49.194063', '2025-11-20 17:09:49.194063', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 51, 6, 'Sau khi vắt ráo nước, gỡ tơi đu đủ cà rốt. Sau đó cho rau thơm, lạc rang vào trộn/đảo đều là hoàn thành. Bạn có thể thêm các topping yêu thích như bò khô, gan bò chiên tỏi, da heo chiên giòn... tùy thích.', 10);
INSERT INTO public.recipe_steps VALUES (233, '2025-11-20 17:09:49.197631', '2025-11-20 17:09:49.197631', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 51, 3, 'Vớt đu đủ, cà rốt rửa sạch, vắt ráo nước, gỡ tơi.', 10);
INSERT INTO public.recipe_steps VALUES (234, '2025-11-20 17:09:49.20118', '2025-11-20 17:09:49.20118', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 51, 2, 'Cho đu đủ, cà rốt bào sợi vào ngâm với nước muối loãng khoảng 30 phút để ra bớt nhựa và giúp giòn hơn.', 10);
INSERT INTO public.recipe_steps VALUES (235, '2025-11-20 17:09:49.204406', '2025-11-20 17:09:49.204406', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 51, 4, 'Pha hỗn hợp nước trộn nộm gồm 1 thìa canh nước cốt chanh, 2 thìa canh giấm trắng, 3 thìa canh đường, 1/2 thìa canh muối. Sau đó trộn đều cho hỗn hợp tan hoàn toàn rồi thêm tỏi ớt băm vào.', 10);
INSERT INTO public.recipe_steps VALUES (236, '2025-11-20 17:09:49.208009', '2025-11-20 17:09:49.208009', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 51, 5, 'Cho hỗn hợp nước trộn nộm cùng đu đủ, cà rốt vào âu, trộn đều, để cho ngấm gia vị khoảng 6- 8 phút, vắt ráo. Lúc này nếm thử và điều chỉnh lại gia vị theo khẩu vị.', 10);
INSERT INTO public.recipe_steps VALUES (237, '2025-11-20 17:09:49.210761', '2025-11-20 17:09:49.210761', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 51, 7, 'Yêu cầu thành phẩm: Nộm đu đủ giòn ngon, khô ráo, lạc giòn ngon, gia vị hài hòa chua mặn ngọt làm nên món ăn thanh mát cho mâm cỗ ngày Tết.', 10);
INSERT INTO public.recipe_steps VALUES (238, '2025-11-20 17:09:49.319864', '2025-11-20 17:09:49.319864', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 52, 1, 'Cá làm sạch, chà xát chanh và muối hạt khử tanh rồi rửa thật sạch, để ráo hoặc thấm khô. Sau đó, ướp cá với 1 thìa canh muối hạt trong 30 phút cho cá cứng và đậm vi.', 10);
INSERT INTO public.recipe_steps VALUES (239, '2025-11-20 17:09:49.322005', '2025-11-20 17:09:49.322005', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 52, 2, 'Riềng rửa sạch, lấy 1/2 thái lát, còn 1/2 thì giã nát; khế chua rửa sạch, thái lát hình ngôi sao; ớt rửa sạch; hành khô rửa sạch, giữ cả phần vỏ hành rửa sạch để kho sẽ ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (240, '2025-11-20 17:09:49.324131', '2025-11-20 17:09:49.324131', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 52, 3, 'Cách thắng nước hàng màu hổ phách đẹp mắt, không đắng: Cho đường vào nồi inox đế dày, đun lửa vừa, lắc nhẹ nồi cho đường tan dần. Khi đường bốc hơi thì hạ lửa nhỏ và tiếp tục lắc đều (không khuấy). Khi xuất hiện các bong bóng li ti và đạt tới màu hổ phách (nâu đỏ đẹp mắt) thì thêm 1/2 - 1 bát nước nóng vào đảo đều. Lúc này tiếp tục đun và khuấy đều cho tới khi cạn bớt nước và hơi sánh là đạt. Cho vào hũ thủy tinh bảo quản và dùng dần.', 10);
INSERT INTO public.recipe_steps VALUES (241, '2025-11-20 17:09:49.32625', '2025-11-20 17:09:49.32625', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 52, 7, 'Để có nồi cá ngon nên kho 2 - 3 lần lửa thì cá sẽ đậm đà, săn chắc và thơm ngon, xương nhừ. Lần kho 1: Bật lửa to cho cá sôi khoảng 10 phút, hớt bỏ bọt rồi hạ lửa liu riu trong khoảng 1 tiếng. Lúc này, bạn nêm nếm lại gia vị cho phù hợp, cá kho nên đậm vị. Tắt bếp để cá nguội, đây cũng là lúc giúp ''''cá hồi'''' và dẻo hơn. Sau đó, tiếp tục kho lửa lần 2, 3 với cách tương tự. Chú ý thêm nước sôi vào khi nước kho gần cạn, tránh không để cá bén cháy. Kho cá tối thiểu 3 tiếng, càng kho lâu cá càng săn chắc, đậm đà.', 10);
INSERT INTO public.recipe_steps VALUES (242, '2025-11-20 17:09:49.329045', '2025-11-20 17:09:49.329045', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 52, 5, 'Cá kho bằng nồi đất hoặc nồi gang là ngon nhất. Xếp riềng và khế thái lát xuống đáy nồi.', 10);
INSERT INTO public.recipe_steps VALUES (243, '2025-11-20 17:09:49.331865', '2025-11-20 17:09:49.331865', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 52, 4, 'Pha hỗn hợp nước sốt kho: 1,5 bát con nước sôi, 4 - 5 thìa thìa canh nước hàng, 4 - 5 thìa canh nước mắm, 1 thìa canh đường, 2 thìa cà phê muối, 1 thìa cà phê hạt nêm, 1 thìa cà phê hạt tiêu. Khuấy đều cho hỗn hợp nước sốt tan ra.', 10);
INSERT INTO public.recipe_steps VALUES (244, '2025-11-20 17:09:49.333899', '2025-11-20 17:09:49.333899', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 52, 6, 'Lần lượt cho cá, thịt ba chỉ, riềng lát, khế lát, ớt đan xen rồi trên cùng rải riềng giã nhuyễn. Cuối cùng rưới nước sốt kho vào nồi cho xâm xấp.', 10);
INSERT INTO public.recipe_steps VALUES (245, '2025-11-20 17:09:49.336545', '2025-11-20 17:09:49.336545', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 52, 8, 'Yêu cầu thành phẩm: Thịt cá màu nâu cánh gián đẹp mắt, thịt săn, đậm vị mà không khô, xương rục, nước kho sóng sánh, thơm mùi riềng rất hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (246, '2025-11-20 17:09:49.428159', '2025-11-20 17:09:49.428159', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 53, 3, 'Sau khi ngâm, vớt hành ra rửa nhiều lần cho sạch rễ. Tiếp đến, ngâm vào nước muối loãng 30 phút. Vớt ra, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (247, '2025-11-20 17:09:49.430841', '2025-11-20 17:09:49.430841', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 53, 1, 'Hành củ rửa sơ, ngâm nước 30 phút để dễ bóc vỏ.', 10);
INSERT INTO public.recipe_steps VALUES (248, '2025-11-20 17:09:49.433518', '2025-11-20 17:09:49.433518', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 53, 5, 'Cho hành vào hũ/lọ (đã rửa sạch, để khô ráo), đổ nước muối ngập mặt, dùng vỉ nén hoặc buộc 1 túi nilon nước lên trên để chèn. Đậy nắp và để nơi thoáng mát. Sau một tuần là ăn được. Khi ăn, lấy lượng vừa đủ theo bữa, dùng dao cắt bỏ rễ.', 10);
INSERT INTO public.recipe_steps VALUES (249, '2025-11-20 17:09:49.436752', '2025-11-20 17:09:49.436752', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 53, 2, 'Dùng dao nhỏ sắc, cắt gần sát rễ (không cắt hết), bóc lớp vỏ già ngoài. Sau đó, ngâm hành vào nước vo gạo (hoặc nước tro bếp) khoảng một ngày giúp cho hành trắng và không bị hăng.', 10);
INSERT INTO public.recipe_steps VALUES (250, '2025-11-20 17:09:49.439411', '2025-11-20 17:09:49.439411', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 53, 4, 'Pha 1 - 1,2 lít nước sôi để nguội với 4 - 5 thìa canh muối hạt, 1 thìa canh đường, khuấy tan.', 10);
INSERT INTO public.recipe_steps VALUES (251, '2025-11-20 17:09:49.442606', '2025-11-20 17:09:49.442606', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 53, 6, 'Yêu cầu thành phẩm: Hành trắng giòn, thơm ngon, không nổi váng. Đây là món ăn giúp tiêu hóa tốt, cân bằng vị, chống ngán trong mâm cỗ ngày Tết.', 10);
INSERT INTO public.recipe_steps VALUES (252, '2025-11-20 17:09:49.503615', '2025-11-20 17:09:49.503615', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 54, 5, 'Cho hỗn hợp nước sốt ướp vào phần dưa góp đã vắt ráo, đảo đều cho ngấm gia vị là được.', 10);
INSERT INTO public.recipe_steps VALUES (253, '2025-11-20 17:09:49.506269', '2025-11-20 17:09:49.506269', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 54, 3, 'Rửa sạch, dùng khăn xô vắt nhẹ (tránh bị gãy su hào, cà rốt đã tỉa hoa) để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (254, '2025-11-20 17:09:49.510046', '2025-11-20 17:09:49.510046', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 54, 4, 'Hòa hỗn hợp nước sốt ướp dưa góp gồm đường: giấm: muối là 2 thìa canh đường: 2 thìa canh giấm: 1/2 thìa cà phê muối. Thêm tỏi, ớt băm nhuyễn vào và khuấy đều cho tan đường. Nếu làm dưa góp cúng thì không nên cho tỏi vào.', 10);
INSERT INTO public.recipe_steps VALUES (255, '2025-11-20 17:09:49.513286', '2025-11-20 17:09:49.513286', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 54, 6, 'Yêu cầu thành phẩm: Su hào, cà rốt giòn ngon, vị mặn ngọt chua cay hài hòa, cách tỉa hoa đẹp mắt. Nếu ăn ngay, bạn có thể thêm chút rau mùi (ngò rí) vào tăng thêm hương vị. Còn nếu chưa ăn tới, bạn cho vào hũ thủy tinh sạch, để vào ngăn mát tủ lạnh.', 10);
INSERT INTO public.recipe_steps VALUES (256, '2025-11-20 17:09:49.516411', '2025-11-20 17:09:49.516411', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 54, 1, 'Su hào, cà rốt gọt bỏ vỏ, pha khối rồi tỉa hoa tùy chọn.', 10);
INSERT INTO public.recipe_steps VALUES (257, '2025-11-20 17:09:49.51919', '2025-11-20 17:09:49.51919', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 54, 2, 'Cho 1 thìa canh muối hạt vào su hào, cà rốt vừa tỉa hoa, đảo/xóc đều để trong 10 phút cho ra bớt nước. Việc này vừa giúp giảm vị ngái của su hào, vừa giúp món ăn trở nên giòn ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (258, '2025-11-20 17:09:49.672534', '2025-11-20 17:09:49.672534', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 55, 1, 'Sơ chế
INSERT INTO public.recipe_steps VALUES (259, '2025-11-20 17:09:49.677106', '2025-11-20 17:09:49.677106', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 55, 2, 'Trộn nhân nem
INSERT INTO public.recipe_steps VALUES (260, '2025-11-20 17:09:49.681414', '2025-11-20 17:09:49.681414', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 55, 5, 'Yêu cầu thành phẩm
INSERT INTO public.recipe_steps VALUES (261, '2025-11-20 17:09:49.686131', '2025-11-20 17:09:49.686131', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 55, 4, 'Chiên nem
INSERT INTO public.recipe_steps VALUES (262, '2025-11-20 17:09:49.690954', '2025-11-20 17:09:49.690954', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 55, 3, 'Gói nem
INSERT INTO public.recipe_steps VALUES (263, '2025-11-20 17:09:49.896575', '2025-11-20 17:09:49.896575', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 56, 3, 'Ướp thịt với 3 - 4 muỗng canh đường trước để giúp phần mỡ của thịt trong, bùi và ăn giòn hơn.', 10);
INSERT INTO public.recipe_steps VALUES (264, '2025-11-20 17:09:49.902333', '2025-11-20 17:09:49.902333', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 56, 7, 'Thịt sau khi ướp, cho lên bếp xào săn rồi hạ lửa vừa cho gia vị ngấm vào thịt. Chú ý canh và lật trở các mặt cho tới khi thịt hơi ngả vàng.', 10);
INSERT INTO public.recipe_steps VALUES (265, '2025-11-20 17:09:49.908599', '2025-11-20 17:09:49.908599', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 56, 6, 'Trứng vịt luộc với chút muối hoặc giấm, khi chín vớt ra ngâm nước lạnh cho dễ bóc. Xăm bằng tăm vài lỗ để khi kho trứng ngấm nước thịt vào trứng vị đậm đà, thơm ngon.', 10);
INSERT INTO public.recipe_steps VALUES (266, '2025-11-20 17:09:49.919514', '2025-11-20 17:09:49.919514', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 56, 9, 'Thịt kho 2 - 3 lần lửa thì nước dừa và đường sẽ tự lên màu nâu đỏ đẹp mắt mà không cần dùng nước hàng.', 10);
INSERT INTO public.recipe_steps VALUES (267, '2025-11-20 17:09:49.925472', '2025-11-20 17:09:49.925472', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 56, 10, 'Thành phẩm: Từng miếng thịt màu nâu cánh gián đẹp mắt, thịt mềm rệu (rục) như tan trong miệng khi ăn, nước trong, hột vịt ngấm trọn gia vị hài hòa, dậy mùi thơm từ các gia vị rất hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (268, '2025-11-20 17:09:49.945763', '2025-11-20 17:09:49.945763', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 56, 1, 'Thịt ba chỉ (ba rọi) cạo sạch, cắt miếng vuông 4 - 5cm (nếu thích to hơn thì bạn thái miếng to). Chà muối hạt và chanh khử mùi, rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (269, '2025-11-20 17:09:49.953443', '2025-11-20 17:09:49.953443', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 56, 5, 'Tiếp tục ướp thịt với 1/2 nước cốt chanh, 2 muỗng canh nước mắm, 1/2 muỗng canh muối (bột canh) cùng tỏi, ớt giã ở trên, trộn đều ướp trong 1 giờ. Nếu có thời gian và nắng đẹp thì đem thịt phơi nắng trong 2 giờ giúp cho mỡ trong, thịt săn và khi kho thịt mềm rệu (rục) nhưng vẫn giữ nguyên miếng.', 10);
INSERT INTO public.recipe_steps VALUES (270, '2025-11-20 17:09:49.957909', '2025-11-20 17:09:49.957909', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 56, 8, 'Đun sôi nước dừa để loại bỏ vị chua trong nước dừa và nước lạnh (căn lượng nước xâm xấp mặt thịt) rồi cho vào thịt kho. Khi nước sôi, hớt bỏ bọt và hạ lửa nhỏ, mở vung và kho thịt. Nếu có lá mít hay lá chuối thì cho lên bề mặt nồi thịt kho. Việc này vừa giúp thịt kho lên màu đẹp, vừa làm nước trong hơn. Trong quá trình kho, châm thêm nước dừa hoặc nước lạnh.', 10);
INSERT INTO public.recipe_steps VALUES (271, '2025-11-20 17:09:49.963396', '2025-11-20 17:09:49.963396', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 56, 2, 'Chần sơ thịt với nước sôi để loại bỏ tạp chất, vớt ra, rửa nhiều lần cho sạch rồi để ráo nước/hoặc thấm khô.', 10);
INSERT INTO public.recipe_steps VALUES (272, '2025-11-20 17:09:49.966803', '2025-11-20 17:09:49.966803', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 56, 4, 'Giã nát tỏi, ớt và hành khô để tiết ra tinh dầu giúp khi ướp thịt được thơm ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (273, '2025-11-20 17:09:50.073295', '2025-11-20 17:09:50.073295', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 57, 4, 'Dùng muỗng múc hỗn hợp thịt và cá thác lác dồn (nhồi) vào quả khổ qua với lượng vừa đủ. Cuối cùng dùng cọng hành lá chần sơ nước buộc lại.', 10);
INSERT INTO public.recipe_steps VALUES (274, '2025-11-20 17:09:50.076048', '2025-11-20 17:09:50.076048', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 57, 3, 'Cho thịt nạc vai xay, cá thác lác cùng mộc nhĩ, hành lá, rau mùi vào âu trộn, nêm thêm 2 muỗng cà phê nước mắm, 1 muỗng cà phê đường, 1/2 muỗng cà phê muối, 1/2 muỗng cà phê hạt nêm, 1/2 muỗng cà phê hạt tiêu, trộn đều cho tới khi quyện quết dẻo lại với nhau. Bọc màng bọc thực phẩm để vào ngăn mát tủ lạnh khoảng 30 phút cho thịt dẻo hơn.', 10);
INSERT INTO public.recipe_steps VALUES (275, '2025-11-20 17:09:50.078706', '2025-11-20 17:09:50.078706', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 57, 2, 'Mộc nhĩ ngâm nở, rửa sạch, thái nhỏ. Hành lá, rau mùi rửa sạch, để ráo, cắt nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (276, '2025-11-20 17:09:50.081393', '2025-11-20 17:09:50.081393', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 57, 5, 'Đun sôi nước dùng. Khi nước sôi già thì cho khổ qua vào hầm, mở vung. Thỉnh thoảng hớt bỏ bọt cho nước trong. Khi khổ qua mềm thì nêm nếm lại gia vị cho phù hợp và thêm hành, ngò, hạt tiêu và tắt bếp, múc ra thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (277, '2025-11-20 17:09:50.084223', '2025-11-20 17:09:50.084223', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 57, 6, 'Yêu cầu thành phẩm: Khổ qua mềm ngon vẫn giữ màu xanh, thịt và cá thác lác dẻo dai, dính vào trái, nước canh hài hòa vị ngọt, đắng rất hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (278, '2025-11-20 17:09:50.087444', '2025-11-20 17:09:50.087444', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 57, 1, 'Dùng dao nhỏ rạch một đường dọc, dùng muỗng cà phê tách nhẹ, rồi lấy cán muỗng nhẹ nhàng tách phần ruột và hạt ra. Bạn nhớ cạo hết phần màng trắng bên trong vì đây là lớp có vị đắng nhiều. Đồng thời giúp khi nhồi thịt kết dính tốt hơn. Sau đó, ngâm khổ qua đã sơ chế vào nước muối loãng, rửa sạch, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (279, '2025-11-20 17:09:50.159669', '2025-11-20 17:09:50.159669', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 58, 4, 'Các loại rau thơm rửa sạch, thái rối. Lạc rang giã dập.', 10);
INSERT INTO public.recipe_steps VALUES (280, '2025-11-20 17:09:50.162291', '2025-11-20 17:09:50.162291', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 58, 2, 'Ướp su hào cà rốt đã thái sợi với 1 thìa cà phê muối tinh trong 10 phút để tiết nước. Sau đó đem rửa sạch nhiều nước để hết vị mặn, dùng khăn xô vắt nhẹ để khô ráo và tránh làm gãy sợi su hào, cà rốt.', 10);
INSERT INTO public.recipe_steps VALUES (281, '2025-11-20 17:09:50.164445', '2025-11-20 17:09:50.164445', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 58, 5, 'Cho su hào, cà rốt đã vắt kiệt nước vào âu, thêm 1/2 nước nộm ở trên và trộn đều cho thấm gia vị trong 3 phút. Dùng khăn xô tiếp tục vắt bỏ nước. Cho 1/2 lượng nước trộn nộm còn lại vào đảo đều cho gia vị chua cay mặn ngọt thấm đượm vào từng sợi nộm. Sau 2-3 phút, su hào cà rốt đã ngậm đủ gia vị, tiếp tục vắt khô ráo. Cuối cùng đảo tơi nộm và cho rau thơm cùng lạc rang giã dập vào đảo đều là hoàn thành.', 10);
INSERT INTO public.recipe_steps VALUES (282, '2025-11-20 17:09:50.166607', '2025-11-20 17:09:50.166607', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 58, 3, 'Pha hỗn hợp nước trộn nộm gồm 1 thìa canh nước cốt chanh, 2 thìa canh giấm trắng, 3 thìa canh đường, 1 thìa cà phê muối. Sau đó trộn đều cho hỗn hợp tan hoàn toàn rồi thêm tỏi ớt băm.', 10);
INSERT INTO public.recipe_steps VALUES (283, '2025-11-20 17:09:50.168723', '2025-11-20 17:09:50.168723', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 58, 6, 'Yêu cầu thành phẩm: Đĩa nộm khô ráo, su hào, cà rốt giòn sần sật, vị chua cay mặn ngọt hài hòa quyện với lạc rang bùi bùi hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (284, '2025-11-20 17:09:50.170865', '2025-11-20 17:09:50.170865', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 58, 1, 'Su hào gọt vỏ, rửa sạch, dùng dao sắc cắt từng lát mỏng rồi chồng lên nhau từng tệp thái sợi nhỏ. Vì su hào giòn nên nếu bào sợi sẽ hay bị đứt gãy. Cà rốt bào sợi hoặc thái sợi nhỏ tùy chọn.', 10);
INSERT INTO public.recipe_steps VALUES (285, '2025-11-20 17:09:50.248355', '2025-11-20 17:09:50.248355', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 59, 2, 'Xiên cóc vào queDùng xiên tre hoặc dĩa ăn châm đều trên bề mặt quả cóc để giúp khi ướp đường thẩm thấu nhanh hơn. Hoặc bạn có thể bổ đôi trái cóc.', 10);
INSERT INTO public.recipe_steps VALUES (286, '2025-11-20 17:09:50.250706', '2025-11-20 17:09:50.250706', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 59, 7, 'Hong khô cócVớt cóc chần qua nước ấm (80-90 độ) cho bớt đường và bỏ bọt. Sau đó, cho cóc để lên giá hong hoặc mâm đem phơi nắng đẹp hai ngày hoặc đem sấy trong lò nướng ở nhiệt độ 60 độ C cho tới khi khô, dẻo là được.', 10);
INSERT INTO public.recipe_steps VALUES (287, '2025-11-20 17:09:50.253378', '2025-11-20 17:09:50.253378', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 59, 3, 'Ngâm cócCho một lớp cóc xuống thau/âu đựng, rải một lớp đường, làm lần lượt cho tới hết và trên cùng là lớp đường. Để ngâm tối thiểu 6 tiếng hoặc qua đêm càng tốt.', 10);
INSERT INTO public.recipe_steps VALUES (288, '2025-11-20 17:09:50.256001', '2025-11-20 17:09:50.256001', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 59, 6, 'Rim nước dứa với cócKhi hỗn hợp cóc rút nước còn 1/3 và hơi sánh kẹo lại thì cho nước dứa (thơm) vào rim cho tới khi lên màu nâu đỏ thẫm là được.', 10);
INSERT INTO public.recipe_steps VALUES (289, '2025-11-20 17:09:50.258151', '2025-11-20 17:09:50.258151', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 59, 4, 'Nấu cóc với đườngCho hỗn hợp cóc và nước đường đã tan vào chảo sên ở lửa nhỏ vừa. Thỉnh thoảng hớt bỏ bọt và đảo nhẹ tay tránh bị nát.', 10);
INSERT INTO public.recipe_steps VALUES (290, '2025-11-20 17:09:50.260277', '2025-11-20 17:09:50.260277', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 59, 5, 'Làm nước dứaÉp hoặc xay 1/2 quả dứa (thơm) chín rồi lọc lấy nước.', 10);
INSERT INTO public.recipe_steps VALUES (291, '2025-11-20 17:09:50.262405', '2025-11-20 17:09:50.262405', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 59, 1, 'Sơ chế cócCóc gọt vỏ, ngâm nước muỗi loãng cho ra bớt nhựa và giữ không bị thâm. Sau đó vớt ra rửa sạch, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (292, '2025-11-20 17:09:50.264482', '2025-11-20 17:09:50.264482', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 59, 8, 'Yêu cầu thành phẩmMứt cóc se dẻo, ráo nước, hạt teo lại, vị chua ngọt hài hòa, thoảng mùi thơm của dứa rất hấp dẫn. Một món ngon đãi khách ngày Tết. Bảo quản trong hũ thủy tinh để trong ngăn mát tủ lạnh khi ăn sẽ ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (293, '2025-11-20 17:09:50.34736', '2025-11-20 17:09:50.34736', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 60, 8, 'Khi mứt quánh lại, nặng tay thì phải hạ lửa nhỏ nhất và đảo liên tục cho tới khi đường kết tinh thành hạt nhỏ mịn bám đều các mặt dừa là được. Đảo cho tới khi sợi mứt khô ráo, tắt bếp và lấy ra để nguội, cho vào hũ thủy tinh bảo quản.', 10);
INSERT INTO public.recipe_steps VALUES (294, '2025-11-20 17:09:50.349472', '2025-11-20 17:09:50.349472', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 60, 1, 'Cùi dừa bánh tẻ (không quá già, không quá non) gọt sạch vỏ màu nâu, chia ra các phần bào sợi và phần tạo hình cánh hoa cúc (tùy chọn). Ngâm vào nước muối loãng 10 phút, rửa nhiều lần để sạch tinh dầu dừa cho tới khi nước trong vắt.', 10);
INSERT INTO public.recipe_steps VALUES (295, '2025-11-20 17:09:50.351036', '2025-11-20 17:09:50.351036', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 60, 5, 'Thanh long, cà rốt ép hoặc xay lọc lấy nước màu.', 10);
INSERT INTO public.recipe_steps VALUES (296, '2025-11-20 17:09:50.353041', '2025-11-20 17:09:50.353041', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 60, 3, 'Chần sơ dừa với nước ấm để loại bỏ tinh dầu dừa.', 10);
INSERT INTO public.recipe_steps VALUES (297, '2025-11-20 17:09:50.355127', '2025-11-20 17:09:50.355127', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 60, 2, 'Nếu muốn tạo hình hoa cúc, bạn cắt từng khối chữ nhật 6cm*4cm.', 10);
INSERT INTO public.recipe_steps VALUES (298, '2025-11-20 17:09:50.357863', '2025-11-20 17:09:50.357863', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 60, 4, 'Tiếp tục ngâm rửa lại lần nữa cho sạch. Việc này làm kỹ càng thì giúp cho mứt khô ráo và để được lâu.', 10);
INSERT INTO public.recipe_steps VALUES (395, '2025-11-20 17:09:51.772255', '2025-11-20 17:09:51.772255', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 73, 1, 'Cho 30 gr bơ vào chảo, để ở lửa nhỏ cho tới khi bơ tan chảy hoàn toàn.', 10);
INSERT INTO public.recipe_steps VALUES (299, '2025-11-20 17:09:50.361654', '2025-11-20 17:09:50.361654', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 60, 6, 'Chia đều các mẻ dừa vào âu/tô đựng, thêm đường (chú ý tỷ lệ dừa và đường tối thiểu là 2:1). Thêm màu củ quả vào ngâm cùng, tối thiểu 6-8 tiếng cho tới khi đường tan hoàn toàn.', 10);
INSERT INTO public.recipe_steps VALUES (300, '2025-11-20 17:09:50.364357', '2025-11-20 17:09:50.364357', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 60, 7, 'Cho các mẻ vào chảo sên, chú ý điều chỉnh lượng lửa rất quan trọng. Ban đầu có thể để lửa to, sau đó hạ lửa nhỏ vừa và đảo đều tay để đường bám đều và tránh bị bén mứt.', 10);
INSERT INTO public.recipe_steps VALUES (301, '2025-11-20 17:09:50.433362', '2025-11-20 17:09:50.433362', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 61, 1, 'Món kẹo mít được bạn Phương Oliver - người sáng tạo nội dung một kênh You Tube cuộc sống điền viên, tại Bến Tre, chia sẻ.', 10);
INSERT INTO public.recipe_steps VALUES (302, '2025-11-20 17:09:50.493013', '2025-11-20 17:09:50.493013', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 62, 3, 'Cho gấc đã đánh nhuyễn vào nếp và trộn thật đều. Chú ý không bóp mạnh, tránh nếp bị nát.', 10);
INSERT INTO public.recipe_steps VALUES (303, '2025-11-20 17:09:50.495225', '2025-11-20 17:09:50.495225', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 62, 4, 'Để có đĩa xôi gấc ngon căng mẩy, bóng mượt cần đồ 2 lần lửa. Lần 1: Đun sôi nước, làm nóng chõ đồ xôi, hạ nhiệt và cho gạo nếp vào chõ, dàn đều. Sau 20 - 30 phút khi xôi chín được 80% thì dỡ ra giá, dàn đều. Cho 100 gr đường (điều chỉnh theo khẩu vị), chút dầu ăn vào xôi rồi đảo đều.', 10);
INSERT INTO public.recipe_steps VALUES (304, '2025-11-20 17:09:50.496753', '2025-11-20 17:09:50.496753', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 62, 5, 'Tiếp tục cho xôi vào chõ để đồ lần 2, chú ý giữa lửa thật đều. Sau 15 phút tính từ khi nước sôi, tắt bếp và ủ tiếp 5 - 6 phút cho xôi dẻo mềm. Chú ý khi đồ xôi đặt thêm khăn xô bên trên để hứng nước từ vung rơi xuống tránh nhão xôi. Tắt bếp, múc xôi ra đĩa. Nếu muốn đơm vào khuôn tạo hình thì làm khi xôi còn nóng sẽ dễ hơn.', 10);
INSERT INTO public.recipe_steps VALUES (305, '2025-11-20 17:09:50.499753', '2025-11-20 17:09:50.499753', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 62, 6, 'Yêu cầu thành phẩm: Xôi căng mẩy, bóng đẹp, dẻo thơm, nổi bật bởi màu đỏ tươi thắm rất hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (306, '2025-11-20 17:09:50.501823', '2025-11-20 17:09:50.501823', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 62, 1, 'Gạo nếp đãi sạch cho tới khi nước trong, ngâm với nước lạnh 6 - 8 giờ (nếu muốn nhanh hơn thì ngâm nước ấm 4 giờ). Sau đó, đổ ra rá dội lại nước lã, để cho ráo nước, cho 1 thìa cà phê muối tinh vào xóc nhẹ/hoặc trộn nhẹ tay (tránh làm hạt nếp bị gãy nát).', 10);
INSERT INTO public.recipe_steps VALUES (307, '2025-11-20 17:09:50.504439', '2025-11-20 17:09:50.504439', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 62, 2, 'Bổ đôi quả gấc, lấy thìa nạo lấy phần ruột gấc cùng một chút phần cùi vàng cho vào tô, thêm 1 thìa canh rượu trắng vào đánh nhuyễn hoặc đeo găng tay bóp nhẹ để thịt gấc bong khỏi hạt.', 10);
INSERT INTO public.recipe_steps VALUES (308, '2025-11-20 17:09:50.542115', '2025-11-20 17:09:50.542115', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 63, 7, 'Sên mứt nhẹ nhàng và đều tay ở lửa nhỏ vừa để mứt giữ nguyên sợi và bám đều đường các mặt.', 10);
INSERT INTO public.recipe_steps VALUES (309, '2025-11-20 17:09:50.543708', '2025-11-20 17:09:50.543708', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 63, 5, 'Cho cà rốt vào âu/thố và ngâm với 500 gr đường trong 3-4  giờ.', 10);
INSERT INTO public.recipe_steps VALUES (310, '2025-11-20 17:09:50.54584', '2025-11-20 17:09:50.54584', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 63, 1, 'Cà rốt gọt bỏ vỏ, dùng dao cắt sợi vừa phải (không thái nhỏ quá vì khi ngâm đường, cà rốt sẽ teo nhỏ lại). Đem ngâm với nước muối loãng trong 30 phút để khử bớt mùi hăng.', 10);
INSERT INTO public.recipe_steps VALUES (311, '2025-11-20 17:09:50.547997', '2025-11-20 17:09:50.547997', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 63, 3, 'Đun sôi một nồi nước, vắt thêm nửa quả chanh (hoặc quất) rồi cho cà rốt vào chần sơ trong 2-3 phút nhằm loại bỏ mùi hăng.', 10);
INSERT INTO public.recipe_steps VALUES (312, '2025-11-20 17:09:50.550104', '2025-11-20 17:09:50.550104', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 63, 9, 'Yêu cầu thành phẩm: Sợi mứt khô ráo, đường trắng li ti bám đều, màu cam đỏ đẹp mắt, khi ăn dẻo ngon rất hấp dẫn. Mứt cà rốt sẽ làm thêm phong phú cho khay mứt vào ngày Tết.', 10);
INSERT INTO public.recipe_steps VALUES (313, '2025-11-20 17:09:50.551705', '2025-11-20 17:09:50.551705', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 63, 8, 'Khi thấy nặng tay thì hạ lửa nhỏ, đảo liên tục để đường kết tinh từng hạt trắng li ti bám đều vào từng sợi cà rốt. Tiếp tục sên ở lửa nhỏ cho tới khi mứt khô ráo hoàn toàn. Tắt bếp, đeo găng tay xóc đảo cho mứt thẳng sợi và khô ráo hoàn toàn. Để mứt nguội hoàn toàn rồi cho vào hũ thủy tinh sạch hoặc túi, bảo quản nơi thoáng mát.', 10);
INSERT INTO public.recipe_steps VALUES (314, '2025-11-20 17:09:50.55384', '2025-11-20 17:09:50.55384', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 63, 6, 'Khi đường tan hết, chắt lấy phần nước đường cho vào chảo chống dính đế dày, phần cà rốt sợi giữ lại. Đun sôi nước đường ở lửa vừa và khi nước rút gần cạn (còn 1/3) thì cho cà rốt vào đảo đều.', 10);
INSERT INTO public.recipe_steps VALUES (315, '2025-11-20 17:09:50.555794', '2025-11-20 17:09:50.555794', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 63, 4, 'Vớt cà rốt đã chần ra thau nước đá ngâm cho giòn, rồi vớt ra để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (316, '2025-11-20 17:09:50.561583', '2025-11-20 17:09:50.561583', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 63, 2, 'Tiếp tục cho cà rốt ngâm vào nước vo gạo khoảng 4-5 giờ để giúp cà rốt dẻo dai khi sên không bị đứt gãy. Sau đó đem rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (317, '2025-11-20 17:09:50.737603', '2025-11-20 17:09:50.737603', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 64, 5, 'Rán nem: Nên rán 2 lần thì nem sẽ giòn rụm, thơm ngon. Lần thứ nhất cho dầu ăn nóng (thử đầu đũa sủi tăm là đạt), cho nem vào rán ở lửa nhỏ vừa, khi nem se mặt và chín khoảng 70- 80% thì vớt ra để giấy thấm dầu cho nguội. Sau đó, chia ra các mẻ (tương đương mỗi bữa ăn), rồi đem cấp đông.', 10);
INSERT INTO public.recipe_steps VALUES (318, '2025-11-20 17:09:50.742077', '2025-11-20 17:09:50.742077', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 64, 3, 'Gói nem: Đặt lá bánh đa nem lên mặt phẳng, dùng khăn xô thấm chút bia cho hơi ẩm thoa đều cho bánh đa nem mềm, thêm 1/2 lá đa nem nữa lót để tránh vỡ nhân khi rán. Múc lượng nhân vừa phải vào, lúc này cho 2-3 miếng tôm tươi đã thái hạt lựu vào và gói đều tay.', 10);
INSERT INTO public.recipe_steps VALUES (319, '2025-11-20 17:09:50.744737', '2025-11-20 17:09:50.744737', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 64, 7, 'Vớt nem ra cho vào giấy thấm dầu và thưởng thức nóng. Món này ăn kèm cơm nóng, bún đều rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (320, '2025-11-20 17:09:50.747425', '2025-11-20 17:09:50.747425', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 64, 4, 'Nem gói đẹp là đảm bảo đều tay, kích thước bằng nhau, không nên gói chặt quá sẽ làm nem bị vỡ khi rán.', 10);
INSERT INTO public.recipe_steps VALUES (321, '2025-11-20 17:09:50.749545', '2025-11-20 17:09:50.749545', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 64, 8, 'Yêu cầu thành phẩm: Vỏ nem vàng giòn đẹp mắt, nhân nem không hề khô mà mềm ngọt từ thịt, tôm quyện cùng rau củ quả hài hòa.', 10);
INSERT INTO public.recipe_steps VALUES (322, '2025-11-20 17:09:50.752213', '2025-11-20 17:09:50.752213', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 64, 2, 'Trộn nhân: Cho thịt vào nồi/hoặc âu thêm 1 thìa canh dầu ăn, 1 thìa cà phê hạt nêm, 1 thìa cà phê muối (bột canh), 1 thìa cà phê mắm, 2 thìa cà phê hạt tiêu, trộn đều. Sau đó tiếp tục cho hỗn hợp rau củ vào trộn. Khi nào chuẩn bị gói nem thì mới cho trứng gà để tránh nhân bị chảy nước.', 10);
INSERT INTO public.recipe_steps VALUES (323, '2025-11-20 17:09:50.755615', '2025-11-20 17:09:50.755615', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 64, 6, 'Trước khi ăn, đem chiên nem lần 2 cho tới khi vàng giòn.', 10);
INSERT INTO public.recipe_steps VALUES (324, '2025-11-20 17:09:50.758358', '2025-11-20 17:09:50.758358', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 64, 1, 'Sơ chế nguyên liệu: Mộc nhĩ, nấm hương ngâm nở, rửa sạch, để ráo và thái nhỏ. Cà rốt, su hào, củ đậu, hành tây thái sợi mỏng nhỏ. Miến ngâm mềm, để khô ráo, cắt nhỏ (không nên ngâm nhũn quá). Rau mùi, hành hoa rửa sạch thái nhỏ. Hành khô băm nhỏ. Tôm tươi bóc vỏ, rồi thái hạt lựu.', 10);
INSERT INTO public.recipe_steps VALUES (325, '2025-11-20 17:09:50.846182', '2025-11-20 17:09:50.846182', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 65, 7, 'Thành phẩm: Gà luộc vàng ươm, thế ngẩng cao đầu, cánh vươn lên, da căng bóng, không bị nứt đùi.', 10);
INSERT INTO public.recipe_steps VALUES (326, '2025-11-20 17:09:50.849217', '2025-11-20 17:09:50.849217', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 65, 4, 'Đậy vung và om gà từ 25-30 phút để giúp gà ngậm nước vừa chín đều, không bị đỏ xương, không bị rách da.', 10);
INSERT INTO public.recipe_steps VALUES (327, '2025-11-20 17:09:50.851908', '2025-11-20 17:09:50.851908', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 65, 6, 'Phết mỡ gà để tạo màu vàng ươm đẹp mắt và căng bóng. (Cách làm mỡ gà: cho mỡ gà vào rán, khi mỡ chảy nước và tóp mỡ vàng thì cho nghệ tươi giã dập hoặc bột nghệ, kèm vài lát hành tím vào phi thơm, đổ qua rây lọc lấy mỡ).', 10);
INSERT INTO public.recipe_steps VALUES (328, '2025-11-20 17:09:50.854047', '2025-11-20 17:09:50.854047', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 65, 5, 'Sau khi om, vớt gà ra ngâm vào thau nước sôi để nguội cho đá viên để giúp da giòn, rửa sạch các màng bám nếu có. Khi nguội, vớt ra để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (329, '2025-11-20 17:09:50.856162', '2025-11-20 17:09:50.856162', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 65, 1, 'Chọn và sơ chế gà: Gà lễ chọn gà trống hoa khỏe mạnh với mào cờ 5 khía tươi, chân nhỏ màu vàng, đuôi dài, lông màu mận, ức đầy đặn, đủ móng. Gà sau khi mổ và vặt lông thì xát nhẹ chanh và muối hạt khử mùi và rửa mấy nước cho sạch, để ráo, sau đó buộc cánh tiên.', 10);
INSERT INTO public.recipe_steps VALUES (330, '2025-11-20 17:09:50.859094', '2025-11-20 17:09:50.859094', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 65, 3, 'Sau khi luộc 4-5 phút (tùy gà to hay nhỏ), thì tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (331, '2025-11-20 17:09:50.863415', '2025-11-20 17:09:50.863415', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 65, 2, 'Cho gà cùng lòng mề vào nồi sâu lòng đế dày, đổ ngập nước lạnh (hoặc tối thiểu ngập 2/3 gà để không bị thâm). Thêm vài lát gừng, hành khô cùng chút muối (bột canh) và hạt nêm để gà luộc được thơm ngon hơn. Chú ý nếu dùng nước luộc gà dùng để nấu canh măng hay bún thang thì không nên cho gừng vào làm át (phá) mùi. Đậy vung bật bếp đun sôi. Đun lửa vừa từ đầu để nước luộc nóng lên chậm. Khi nước sôi lăn tăn thì mở vung, hớt bỏ bọt và hạ lửa nhỏ luộc gà. Nhẹ nhàng lật gà cho chín đều. Dùng muôi múc nước xối lên nếu gà chưa ngập nước.', 10);
INSERT INTO public.recipe_steps VALUES (332, '2025-11-20 17:09:50.933614', '2025-11-20 17:09:50.933614', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 66, 2, 'Nước hàng sẽ quyết định màu đẹp cho món ăn. Cách thắng nước hàng màu hổ phách đẹp mắt, không đắng: Cho đường vào nồi inox đế dày đun lửa nhỏ vừa, lắc nhẹ nồi cho đường tan chảy dần. Khi đường bốc hơi thì hạ lửa nhỏ và tiếp tục lắc đều (không khuấy). Khi đường xuất hiện các bong bóng li ti và đạt tới màu hổ phách (nâu đỏ đẹp mắt) thì thêm 1/2 - 1 bát con nước nóng vào đảo đều. Sở dĩ cho nước nóng vì đường thắng đang nhiệt độ cao, nếu cho nước lạnh sẽ bắn tung tóe. Lúc này tiếp tục đun và khuấy đều cho tới khi cạn bớt nước và hơi sánh là đạt. Cho vào hũ thủy tinh bảo quản và dùng dần.', 10);
INSERT INTO public.recipe_steps VALUES (333, '2025-11-20 17:09:50.936606', '2025-11-20 17:09:50.936606', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 66, 1, 'Thịt ba chỉ chà xát chanh, muối hạt, rửa sạch rồi chần qua nước sôi cùng vài lát hành khô, gừng để loại bỏ tạp chất và giúp thịt thơm hơn. Sau đó, rửa thịt nhiều lần cho thật sạch, rồi để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (334, '2025-11-20 17:09:50.938729', '2025-11-20 17:09:50.938729', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 66, 5, 'Nên kho 2 lần lửa thì thịt sẽ thơm ngon, lên màu đẹp hơn. Lần 1 cho nước ướp thịt và thêm nước lọc vào xâm xấp bề mặt thịt, đun sôi, hớt bỏ bọt và hạ lửa nhỏ kho cho tới khi nước rút cạn còn 1/3. Nêm nếm lại gia vị cho phù hợp, tắt bếp, để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (335, '2025-11-20 17:09:50.941958', '2025-11-20 17:09:50.941958', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 66, 6, 'Trước khi ăn thì kho lần 2 cho tới khi lớp da trong, thịt nổi màu hổ phách đẹp mắt, nước kho sánh lại là được. Tắt bếp, múc ra rắc thêm chút hạt tiêu và thưởng thức cùng cơm nóng rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (336, '2025-11-20 17:09:50.944621', '2025-11-20 17:09:50.944621', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 66, 4, 'Phi thơm 1/2 lượng hành khô còn lại, cho thịt đã ướp vào xào săn (chưa cho nước ướp vào). Việc này giúp cho miếng thịt ngậm tròn gia vị vào trong, khi kho đậm vị và thơm ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (337, '2025-11-20 17:09:50.947296', '2025-11-20 17:09:50.947296', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 66, 3, 'Ướp thịt với 3 thìa canh nước mắm 35 - 40 độ, 3 thìa canh nước hàng, 1/2 thìa canh bột canh (muối tinh), 1/2 thìa canh đường (tùy chọn), 1 thìa canh hạt nêm, 1 thìa cà phê hạt tiêu, 1 thìa cà phê rượu trắng cùng 1/2 lượng hành khô băm nhỏ và vỏ hành khô rửa sạch vào. Đảo đều và ướp tối thiểu trong 1 giờ. Nếu có thời gian bọc màng bọc thực phẩm để qua đêm trong ngăn mát tủ lạnh sẽ ngấm đượm gia vị ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (338, '2025-11-20 17:09:51.004741', '2025-11-20 17:09:51.004741', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 67, 1, 'Ngày Tết nhâm nhi tách trà, thưởng thức các loại mứt khác nhau là một thú vui tao nhã.', 10);
INSERT INTO public.recipe_steps VALUES (339, '2025-11-20 17:09:51.007683', '2025-11-20 17:09:51.007683', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 67, 2, 'Gọt vỏ, ngâm muối một lúc, sau đó vớt ra rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (340, '2025-11-20 17:09:51.011015', '2025-11-20 17:09:51.011015', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 67, 6, 'Nếu muốn làm món mứt cóc chua cay thì vớt cóc ra trộn muối tôm và ớt bột.', 10);
INSERT INTO public.recipe_steps VALUES (341, '2025-11-20 17:09:51.015079', '2025-11-20 17:09:51.015079', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 67, 5, 'Khi cóc hơi kẹo lại đổ nước ép thơm vào rim tới khi màu đỏ nâu thẫm là được.', 10);
INSERT INTO public.recipe_steps VALUES (342, '2025-11-20 17:09:51.018841', '2025-11-20 17:09:51.018841', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 67, 3, 'Bổ đôi trái, trái bé có thể để nguyên, cho đường vào ngâm qua đêm.', 10);
INSERT INTO public.recipe_steps VALUES (343, '2025-11-20 17:09:51.021787', '2025-11-20 17:09:51.021787', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 67, 7, 'Nếu muốn làm cóc dẻo chua ngọt thì vớt cóc trần qua nồi nước ấm để ráo bớt đường, sau đó mang phơi nắng hai ngày. Thành phẩm mứt sẽ khô, dẻo dai chua ngọt.', 10);
INSERT INTO public.recipe_steps VALUES (344, '2025-11-20 17:09:51.025562', '2025-11-20 17:09:51.025562', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 67, 4, 'Bắc nồi lên bếp, cho âu cóc đã ngâm vào để sên. Cứ để lửa vừa cho sôi bớt nước, khi nào cóc bắt đầu chuyển đỏ thì nhỏ lửa sên liên tục (đảo nhẹ tay lúc này cóc mềm kẻo nát).', 10);
INSERT INTO public.recipe_steps VALUES (345, '2025-11-20 17:09:51.101831', '2025-11-20 17:09:51.101831', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 68, 1, 'Quất (tắc) bỏ quả dập nát, nhặt bỏ cuống, ngâm trong nước muối loãng, rửa sạch, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (346, '2025-11-20 17:09:51.106995', '2025-11-20 17:09:51.106995', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 68, 8, 'Đến lúc nước đường hơi keo lại, tắt bếp, vớt quất ra đặt lên giá hong/rack. Cho vào lò sấy ở nhiệt độ 100 độ C trong 1 giờ hoặc đem phơi nắng to trong 4 - 6 giờ mứt trở nên trong dẻo là được. Bảo quản trong hũ/lọ thủy tinh sạch, để trong ngăn mát tủ lạnh mứt càng khô dẻo ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (347, '2025-11-20 17:09:51.1103', '2025-11-20 17:09:51.1103', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 68, 6, 'Ngâm quất với đường: Cứ một lớp quất, một lớp đường rồi thêm nước cốt gừng giã, nước quất vào. Để trong 6 - 8 giờ, cho tới khi đường tan hoàn toàn.', 10);
INSERT INTO public.recipe_steps VALUES (348, '2025-11-20 17:09:51.113502', '2025-11-20 17:09:51.113502', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 68, 7, 'Cho quất và nước đường ngâm vào chảo sên. Khi sôi, hạ lửa nhỏ vừa, thỉnh thoảng lật trở mặt cho đường thấm đều. Khi nước đường cạn bớt 1/3 hơi sánh lại và quả quất chuyển màu trong thì hạ lửa nhỏ nhất, thỉnh thoảng lật trở miếng quất.', 10);
INSERT INTO public.recipe_steps VALUES (349, '2025-11-20 17:09:51.116756', '2025-11-20 17:09:51.116756', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 68, 9, 'Yêu cầu thành phẩm: Mứt dẻo mềm, không dính tay, vàng cam óng ánh trong veo đẹp mắt. Mứt tắc có vị chua ngọt thanh nhẹ, hơi the, thơm mùi gừng. Đây là món mứt tốt cho sức khỏe và giúp chống ngán trong ngày Tết.', 10);
INSERT INTO public.recipe_steps VALUES (350, '2025-11-20 17:09:51.120193', '2025-11-20 17:09:51.120193', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 68, 5, 'Vớt quất ra ngâm vào tô nước lạnh giúp quất giòn hơn, rửa sạch, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (351, '2025-11-20 17:09:51.123391', '2025-11-20 17:09:51.123391', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 68, 3, 'Làm lần lượt cho tới hết, để riêng phần quả quất đã sơ chế. Phần nước lọc để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (352, '2025-11-20 17:09:51.125509', '2025-11-20 17:09:51.125509', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 68, 4, 'Đun một nồi nước sôi, thêm 1 thìa cà phê muối hạt và cho quất vào ngâm trong 8 - 10 phút cho ra bớt tinh dầu. Việc này giúp quất hạn chế chất the đắng từ vỏ.', 10);
INSERT INTO public.recipe_steps VALUES (353, '2025-11-20 17:09:51.128752', '2025-11-20 17:09:51.128752', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 68, 2, 'Khứa nhẹ theo chiều dọc quả quất 4 - 5 đường từ giữa ra, chừa hai bên. Ấn nhẹ tay cho quất ra hạt và nước (giữ nước riêng vào bát), ép xuống tạo hình cánh hoa đẹp mắt.', 10);
INSERT INTO public.recipe_steps VALUES (354, '2025-11-20 17:09:51.276623', '2025-11-20 17:09:51.276623', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 69, 2, 'Muối trắng, hạt dổi, mắc khén rang thơm, giã nhỏ', 10);
INSERT INTO public.recipe_steps VALUES (355, '2025-11-20 17:09:51.27873', '2025-11-20 17:09:51.27873', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 69, 3, 'Ướp tất cả gia vị trên vào thịt trong 1-2 tiếng. Riêng bột điều tùy sở thích của gia đình để cho vào ướp.', 10);
INSERT INTO public.recipe_steps VALUES (356, '2025-11-20 17:09:51.280314', '2025-11-20 17:09:51.280314', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 69, 4, 'Làm các móc sắt móc vào đầu miếng thịt treo lên phơi 2-3 nắng to.', 10);
INSERT INTO public.recipe_steps VALUES (357, '2025-11-20 17:09:51.282435', '2025-11-20 17:09:51.282435', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 69, 5, '[Caption]', 10);
INSERT INTO public.recipe_steps VALUES (358, '2025-11-20 17:09:51.284545', '2025-11-20 17:09:51.284545', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 69, 1, 'Thịt rửa sạch để ráo nước, cắt miếng dọc', 10);
INSERT INTO public.recipe_steps VALUES (359, '2025-11-20 17:09:51.355813', '2025-11-20 17:09:51.355813', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 70, 4, 'Tiếp tục luộc gừng lần 2 trong 5 - 6 phút để giảm độ cay nồng.', 10);
INSERT INTO public.recipe_steps VALUES (360, '2025-11-20 17:09:51.358464', '2025-11-20 17:09:51.358464', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 70, 6, 'Ướp gừng với 500 gr đường trong 6 - 8 tiếng cho thấm đều và đường tan chảy, gừng trở nên trong hơn.', 10);
INSERT INTO public.recipe_steps VALUES (361, '2025-11-20 17:09:51.36113', '2025-11-20 17:09:51.36113', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 70, 7, 'Cho gừng và nước đường ngâm vào chảo. Ban đầu để lửa vừa cho hỗn hợp sôi, sau đó hạ lửa nhỏ vừa và sên đều tay.', 10);
INSERT INTO public.recipe_steps VALUES (362, '2025-11-20 17:09:51.363887', '2025-11-20 17:09:51.363887', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 70, 8, 'Khi đường cạn sánh thì hạ lửa nhỏ và đảo liên tục đều tay cho tới khi đường kết tinh bám đều các mặt miếng gừng.', 10);
INSERT INTO public.recipe_steps VALUES (363, '2025-11-20 17:09:51.366495', '2025-11-20 17:09:51.366495', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 70, 9, 'Để bảo quản được lâu thì cho mứt gừng vào lò nướng sấy 15 phút ở 80 độ C. Muốn mứt gừng thẳng đẹp thì dàn gừng ra mâm và ép thẳng. Để mứt nguội hẳn thì cho vào hũ thủy tinh đậy kín bảo quản dùng dần.', 10);
INSERT INTO public.recipe_steps VALUES (364, '2025-11-20 17:09:51.36914', '2025-11-20 17:09:51.36914', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 70, 10, 'Yêu cầu thành phẩm: Mứt màu vàng đẹp, phủ đều lớp đường trắng kết tinh, khô. Khi ăn, gừng cay nhẹ, thơm ngọt dễ ăn.', 10);
INSERT INTO public.recipe_steps VALUES (365, '2025-11-20 17:09:51.371264', '2025-11-20 17:09:51.371264', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 70, 1, 'Gừng ngâm vào nước khoảng 20 - 30 phút rồi rửa sạch. Dùng dao nhỏ cạo sạch lớp vỏ bên ngoài, ngâm vào nước muối loãng.', 10);
INSERT INTO public.recipe_steps VALUES (366, '2025-11-20 17:09:51.37394', '2025-11-20 17:09:51.37394', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 70, 3, 'Luộc gừng lần 1 với chút muối và chanh trong 8 - 10 phút, vớt ra rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (367, '2025-11-20 17:09:51.376046', '2025-11-20 17:09:51.376046', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 70, 2, 'Thái gừng thành từng lát vừa phải, ngâm vào nước muối loãng, pha chút nước cốt chanh để giữ màu tươi, không bị thâm.', 10);
INSERT INTO public.recipe_steps VALUES (368, '2025-11-20 17:09:51.379283', '2025-11-20 17:09:51.379283', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 70, 5, 'Vớt gừng ra rửa sạch, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (369, '2025-11-20 17:09:51.442181', '2025-11-20 17:09:51.442181', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 71, 2, 'Công thức làm món mứt me được bạn Ngô Văn Nhanh, quê ở Bến Tre gửi đến bạn bè ba miền có thể làm cho Tết này. Ưu điểm mứt me dễ làm, ăn ngon và chi phí còn rất rẻ.', 10);
INSERT INTO public.recipe_steps VALUES (396, '2025-11-20 17:09:51.886373', '2025-11-20 17:09:51.886373', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 74, 2, 'Cho 250 gr kẹo marshmallow vào đun ở lửa nhỏ, đảo đều tay cho tới khi marshmallow tan hết.', 10);
INSERT INTO public.recipe_steps VALUES (397, '2025-11-20 17:09:51.889132', '2025-11-20 17:09:51.889132', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 74, 4, 'Cho 80 gr bột trứng muối vào và trộn đều, hỗn hợp trở nên vàng ươm như kén tằm rất đẹp mắt.', 10);
INSERT INTO public.recipe_steps VALUES (370, '2025-11-20 17:09:51.444887', '2025-11-20 17:09:51.444887', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 71, 8, 'Rửa lại me với nước ba lần, để ráo. Cân số lượng me còn lại bao nhiêu để trộn đường cát. Tỷ lệ một kg me tách hạt trộn 650-700 gram đường, nếu muốn chua nhiều thì có thể giảm lượng đường. Để qua đêm cho đường tan hết, sau đó chắt nước đường đã tan ra nồi nấu đến khi sánh lại, để nguội, rồi trộn vào me.', 10);
INSERT INTO public.recipe_steps VALUES (371, '2025-11-20 17:09:51.447024', '2025-11-20 17:09:51.447024', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 71, 9, 'Cho me ra khay hoặc mâm, phơi trực tiếp ngoài ánh nắng mặt trời. Việc phơi ngoài nắng giúp me ngấm đường, lên màu đẹp và giữ được mùi thơm đặc trưng. Phơi liên tục bốn ngày đến khi phần nước sánh đặc lại là đã ăn được.', 10);
INSERT INTO public.recipe_steps VALUES (372, '2025-11-20 17:09:51.449141', '2025-11-20 17:09:51.449141', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 71, 5, 'Dùng dao nhỏ tách vỏ me, sau đó tiếp tục ngâm me đã tách vỏ trong 800 gram muối hột pha loãng 8-12 tiếng. Độ mặn trung bình của muối sẽ giúp me giảm bớt độ chua, quả me sẽ dẻo và dễ dàng cho việc tách hạt mà không làm me bị gãy.', 10);
INSERT INTO public.recipe_steps VALUES (373, '2025-11-20 17:09:51.451808', '2025-11-20 17:09:51.451808', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 71, 6, 'Kiểm tra quả me, dùng tay sờ vào thấy quả dẻo hơi ngả màu là đã tách hạt được. Dùng dao nhọn rạch phần bụng quả me, tách nhẹ theo đường cắt để lấy hạt ra.', 10);
INSERT INTO public.recipe_steps VALUES (374, '2025-11-20 17:09:51.454943', '2025-11-20 17:09:51.454943', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 71, 1, 'Quả me gắn với những bát canh chua, món mứt dẻo ngọt, gắn với tuổi thơ trèo cây me, ôm bát muối ướt, lựa những quả chín dốt bột, cắn miếng nào chua chảy nước mắt miếng ấy nhưng là ký ức chẳng bao giờ quên.', 10);
INSERT INTO public.recipe_steps VALUES (375, '2025-11-20 17:09:51.458227', '2025-11-20 17:09:51.458227', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 71, 4, 'Dùng dao gọt hai sống lưng của quả me, sau đó ngâm vào nước muối hạt pha loãng trong 6-8 tiếng tỉ lệ 10 kg me với 800 gram muối hột. Việc ngâm me trong nước muối pha loãng giúp dễ tách vỏ.', 10);
INSERT INTO public.recipe_steps VALUES (376, '2025-11-20 17:09:51.460894', '2025-11-20 17:09:51.460894', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 71, 7, 'Quả me sau khi tách hạt tiếp tục ngâm trong nước pha với một muỗng canh phèn chua trong 3 tiếng. Việc ngâm me trong phèn chua giúp giữ được độ giòn khi phơi. Lưu ý có thể không dùng phèn chua vẫn được nhưng khi phơi quả me sẽ teo, dai và không giữ được dáng.', 10);
INSERT INTO public.recipe_steps VALUES (377, '2025-11-20 17:09:51.464148', '2025-11-20 17:09:51.464148', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 71, 3, 'Chọn những quả me tròn đầy, dáng thẳng sẽ dễ tách hạt hơn quả cong. Dùng móng tay cạo thử lớp vỏ cám bên ngoài nếu thấy xanh thì me còn sống có thể làm mứt, nếu thấy ngả màu hơi nâu là me đã chín không làm được.', 10);
INSERT INTO public.recipe_steps VALUES (378, '2025-11-20 17:09:51.466893', '2025-11-20 17:09:51.466893', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 71, 10, 'Mang cất me vào hộp. Bảo quản điều kiện thường tối đa hai tháng, trong ngăn mát được cả năm.', 10);
INSERT INTO public.recipe_steps VALUES (379, '2025-11-20 17:09:51.633035', '2025-11-20 17:09:51.633035', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 72, 10, 'Trời mùa đông thì để lọ bắp bò bên ngoài một ngày cho ngấm gia vị rồi hôm sau cất ngăn mát tủ lạnh. Mùa hè làm xong phải cất ngăn mát tủ lạnh luôn.', 10);
INSERT INTO public.recipe_steps VALUES (380, '2025-11-20 17:09:51.636589', '2025-11-20 17:09:51.636589', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 72, 11, 'Sau 5 ngày mang ra ăn được, thái lát mỏng, rưới phần nước ngâm xì dầu lên trên, trang trí thêm gừng tỏi ớt hạt tiêu và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (381, '2025-11-20 17:09:51.64151', '2025-11-20 17:09:51.64151', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 72, 9, 'Xếp bắp bò vào hũ thuỷ tinh, xen kẽ là một lớp tỏi gừng, ớt và tiêu xanh. Làm lần lượt đến hết và đổ ngập phần hỗn hợp xì dầu vào.', 10);
INSERT INTO public.recipe_steps VALUES (382, '2025-11-20 17:09:51.643654', '2025-11-20 17:09:51.643654', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 72, 1, 'Bắp bò mua về rửa sạch, lọc hết phần mỡ, xơ bám xung quanh, nên dùng chỉ buộc chặt để thịt luộc xong được săn chắc.', 10);
INSERT INTO public.recipe_steps VALUES (383, '2025-11-20 17:09:51.647343', '2025-11-20 17:09:51.647343', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 72, 7, 'Đun sôi phần hỗn hợp nước ngâm: 700 ml nước+ 250 ml xì dầu+ 100 g đường cát vàng + 100 ml giấm ăn+ 1/2 thìa cà phê hạt tiêu bắc giã rối (nếu có tiêu xanh bỏ qua tiêu khô). Có thể nêm nếm lại hỗn hợp ngâm cho vừa miệng hơn. Để thật nguội phần nước ngâm.', 10);
INSERT INTO public.recipe_steps VALUES (384, '2025-11-20 17:09:51.650036', '2025-11-20 17:09:51.650036', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 72, 3, 'Thịt chín vớt ra bát nước đá (dùng nước đun sôi để nguội) rửa qua một lượt cho sạch rồi để thịt thật khô ráo.', 10);
INSERT INTO public.recipe_steps VALUES (385, '2025-11-20 17:09:51.653084', '2025-11-20 17:09:51.653084', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 72, 5, 'Gừng thái sợi, rửa qua một lần nước đun sôi để nguội để thật ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (386, '2025-11-20 17:09:51.655373', '2025-11-20 17:09:51.655373', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 72, 8, 'Hũ thuỷ tinh ngâm bắp bò rửa thật sạch, tráng lại nước sôi già và để thật ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (387, '2025-11-20 17:09:51.658093', '2025-11-20 17:09:51.658093', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 72, 2, 'Xếp thịt vào nồi, thêm vào một thìa cà phê bột canh, một nhánh gừng đập dập, một khúc xả đập dập, luộc thịt trong khoảng 30 phút.', 10);
INSERT INTO public.recipe_steps VALUES (388, '2025-11-20 17:09:51.660796', '2025-11-20 17:09:51.660796', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 72, 4, 'Thịt nguội cắt khúc dài khoảng 7 cm.', 10);
INSERT INTO public.recipe_steps VALUES (389, '2025-11-20 17:09:51.662927', '2025-11-20 17:09:51.662927', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 72, 6, 'Tỏi thái lát mỏng, ớt cay thái lát mỏng.Nếu dùng hạt tiêu xanh thì phải rửa sạch và để thật khô ráo.', 10);
INSERT INTO public.recipe_steps VALUES (390, '2025-11-20 17:09:51.759998', '2025-11-20 17:09:51.759998', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 73, 6, 'Yêu cầu thành phẩm: Bánh mằn mặn, giòn tan hòa cùng kẹo nougat dẻo, phô mai béo thơm kéo sợi dễ dàng ''''gây nghiện'''' cho các tín đồ ẩm thực. Khi nhân đông lại thì có thể dùng bánh được luôn. Để bảo quản thì cho bánh vào túi zip hoặc lọ kín, để ở ngăn mát tủ lạnh dùng trong 1 - 2 tháng.', 10);
INSERT INTO public.recipe_steps VALUES (391, '2025-11-20 17:09:51.762655', '2025-11-20 17:09:51.762655', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 73, 5, 'Đặt phần nhân lên mặt trong của bánh, rồi up một bánh khác lên trên là hoàn thiện được một bánh hành kẹp phô mai. Làm lần lượt cho tới hết.', 10);
INSERT INTO public.recipe_steps VALUES (392, '2025-11-20 17:09:51.765328', '2025-11-20 17:09:51.765328', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 73, 3, 'Thêm 30 g bột phô mai vào trộn đều cho tới khi quyện lại thành khối dai dẻo, kéo được màng mỏng là đạt. Tắt bếp, để nguội bớt.', 10);
INSERT INTO public.recipe_steps VALUES (393, '2025-11-20 17:09:51.767999', '2025-11-20 17:09:51.767999', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 73, 2, 'Thêm 150 gr kẹo marshmallow vào, hạ lửa nhỏ và đảo đều tay cho tới khi kẹo marshmallow tan hết.', 10);
INSERT INTO public.recipe_steps VALUES (398, '2025-11-20 17:09:51.891798', '2025-11-20 17:09:51.891798', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 74, 6, 'Rải đều 1/2 lượng chà bông cay và rong biển sấy vụn (hoặc cắt nhỏ) dưới đáy hộp/khuôn.', 10);
INSERT INTO public.recipe_steps VALUES (399, '2025-11-20 17:09:51.893384', '2025-11-20 17:09:51.893384', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 74, 1, 'Cho 80 gr bơ vào chảo đun ở lửa vừa cho tới khi bơ tan chảy hết.', 10);
INSERT INTO public.recipe_steps VALUES (400, '2025-11-20 17:09:51.89714', '2025-11-20 17:09:51.89714', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 74, 9, 'Phủ giấy nến hoặc tấm chống dính lên, dùng cây lăn bột cán nhẹ để nén giúp phẳng phiu mặt bánh. Sau đó để vào ngăn mát tủ lạnh 2-3 giờ cho bánh cứng lại rồi lấy ra cắt miếng vừa ăn. Nếu muốn bảo quản lâu thì bạn cho bánh vào túi hoặc lọ kín và để ngăn mát tủ lạnh 1- 2 tháng.', 10);
INSERT INTO public.recipe_steps VALUES (401, '2025-11-20 17:09:51.900419', '2025-11-20 17:09:51.900419', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 74, 3, 'Cho 120 gr sữa bột từ từ vào đảo đều. Lượng sữa bột sẽ quyết định độ giòn hay mềm của bánh. Nếu thích ăn mềm thì lượng sữa bột ít, còn nếu tăng lên sẽ giúp bánh cứng hơn.', 10);
INSERT INTO public.recipe_steps VALUES (402, '2025-11-20 17:09:51.903606', '2025-11-20 17:09:51.903606', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 74, 5, 'Cuối cùng thêm 200 gr bánh quy mặn vào đảo đều cho tới khi hỗn hợp quyện đều bánh quy lại thành một khối dẻo kết dính thì tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (403, '2025-11-20 17:09:51.906536', '2025-11-20 17:09:51.906536', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 74, 7, 'Cho hỗn hợp marshmallow bánh quy mặn vào dàn đều, ấn chặt.', 10);
INSERT INTO public.recipe_steps VALUES (404, '2025-11-20 17:09:51.909247', '2025-11-20 17:09:51.909247', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 74, 10, 'Yêu cầu thành phẩm: Bánh là sự hòa quyện giữa các mặt đối lập nhưng hài hòa, tạo dư vị rất riêng: Bánh quy giòn, marshmallow mềm dẻo, trứng muối béo ngậy, chà bông cay cay, bơ và bột sữa thơm tạo nên món bánh mới lạ, hấp dẫn cho dịp Tết.', 10);
INSERT INTO public.recipe_steps VALUES (405, '2025-11-20 17:09:51.914991', '2025-11-20 17:09:51.914991', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 74, 8, 'Tiếp tục rải đều 1/2 lượng chà bông, rong biển sấy vụn lên trên bề mặt.', 10);
INSERT INTO public.recipe_steps VALUES (406, '2025-11-20 17:09:52.114687', '2025-11-20 17:09:52.114687', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 75, 7, 'Nếu không có lò nướng thì hạ lửa nhỏ nhất, cho lườn gà vào chảo sao đến khi khô là được.[Caption]', 10);
INSERT INTO public.recipe_steps VALUES (407, '2025-11-20 17:09:52.116812', '2025-11-20 17:09:52.116812', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 75, 1, 'Lườn gà (ức gà) rửa sạch, bóc màng. Cho hai nhánh sả đập dập, một củ gừng đập dập, 10 lá chanh vò nát, hai thìa cà phê muối tinh, 1 thìa canh rượu trắng, đổ nước ngập lườn gà, đun sôi hạ bớt lửa, mở vung, hớt bọt.Luộc lườn gà trong 10-15 phút sau đó tắt bếp đậy vung để nguyên trong nồi om thêm 30 phút.', 10);
INSERT INTO public.recipe_steps VALUES (408, '2025-11-20 17:09:52.1195', '2025-11-20 17:09:52.1195', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 75, 2, 'Vớt lườn gà ra dùng chày đập dập nhẹ lúc đang nóng, tránh đập mạnh quá làm nát lườn gà. Xé nhỏ vừa, tránh nhỏ quá khi sao sẽ bị bông nát.', 10);
INSERT INTO public.recipe_steps VALUES (409, '2025-11-20 17:09:52.12326', '2025-11-20 17:09:52.12326', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 75, 6, 'Trải thịt lườn gà lên khay có lót giấy nến, sấy trong một tiếng rưỡi ở nhiệt độ 120 độ, cứ 30 phút lại bỏ ra đảo một lần. Muốn khô giòn thì tăng thêm thời gian.', 10);
INSERT INTO public.recipe_steps VALUES (410, '2025-11-20 17:09:52.126633', '2025-11-20 17:09:52.126633', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 75, 5, 'Cho chút dầu ăn vào chảo, đổ nốt chỗ tỏi băm vào phi gần vàng, tiếp đến đổ hết phần nước sốt đã xay nhỏ mịn, đợi sôi lại thì trút hết phần lườn gà xé nhỏ, lá chanh đã cắt dọc làm đôi, chỗ ớt quả cắt làm đôi, đảo đều, lúc này có thể nêm nếm lại cho vừa khẩu vị (nên nêm nhạt hơn một chút để khi sấy xong thịt ăn vừa miệng). Hạ lửa nhỏ vừa, thỉnh thoảng đảo đến khi cạn nước, khô ráo là tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (411, '2025-11-20 17:09:52.132334', '2025-11-20 17:09:52.132334', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 75, 4, 'Trộn nước sốt ướp gồm: sả, nước mắm, 1/2 chỗ tỏi băm, hành củ băm nhỏ, ớt băm nhỏ, bột canh, bột nêm, ớt bột Hàn Quốc, đường, dầu ăn, 100 ml nước luộc lườn gà. Cho tất cả vào máy xay sinh tố xay nhỏ mịn.', 10);
INSERT INTO public.recipe_steps VALUES (412, '2025-11-20 17:09:52.135791', '2025-11-20 17:09:52.135791', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 75, 3, 'Tỏi, hành tím lột vỏ băm nhỏ.Lá chanh thái dọc làm đôi.Hai nhánh sả bào mỏng.Ớt quả cay một nửa băm nhỏ, một nửa cắt làm đôi.', 10);
INSERT INTO public.recipe_steps VALUES (413, '2025-11-20 17:09:52.246509', '2025-11-20 17:09:52.246509', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 76, 7, 'Rắc nhẹ một lớp đường xay lên bánh. Để bánh nguội thêm rồi rắc tiếp lớp đường xay nữa là thưởng thức được. Để nguội rồi bảo quản trong hộp kín.', 10);
INSERT INTO public.recipe_steps VALUES (414, '2025-11-20 17:09:52.249253', '2025-11-20 17:09:52.249253', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 76, 3, 'Dùng tay nhào và trộn bột cho tới khi thành một khối mịn. Bọc màng bọc thực phẩm, để ngăn mát tủ lạnh khoảng 1 tiếng.', 10);
INSERT INTO public.recipe_steps VALUES (415, '2025-11-20 17:09:52.251998', '2025-11-20 17:09:52.251998', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 76, 4, 'Chia bột thành từng khối đều nhau.', 10);
INSERT INTO public.recipe_steps VALUES (416, '2025-11-20 17:09:52.254671', '2025-11-20 17:09:52.254671', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 76, 8, 'Yêu cầu thành phẩm: Bánh giòn xốp, khi ăn như tơi mịn ra trong miệng, dậy mùi thơm của bơ và vani rất hấp dẫn. Sau khi nướng thì bánh chưa ngấm đủ vị ngọt mềm xốp. Nên lấy một ít để ăn, số còn lại thì cho vào hộp đậy kín. Để tránh dính thì ngăn bằng các lớp giấy nến theo lớp. Có thể thêm một miếng táo nhỏ vào hộp để bánh giữ hương thơm tự nhiên, nên thay miếng táo hàng ngày. Sử dụng bánh trong 1-1,5 tháng.', 10);
INSERT INTO public.recipe_steps VALUES (417, '2025-11-20 17:09:52.258349', '2025-11-20 17:09:52.258349', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 76, 1, 'Dùng dao nhỏ nhọn rạch quả vani theo chiều dọc, rồi cạo lấy phần thịt đen phía trong.', 10);
INSERT INTO public.recipe_steps VALUES (418, '2025-11-20 17:09:52.261672', '2025-11-20 17:09:52.261672', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 76, 6, 'Bật lò nướng trước 10 phút. Cho bánh vào nướng ở khay giữa ở 170 độ C trong vòng 15 phút. Khi viền bánh chuyển màu nâu vàng thì lấy ra.', 10);
INSERT INTO public.recipe_steps VALUES (419, '2025-11-20 17:09:52.265073', '2025-11-20 17:09:52.265073', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 76, 5, 'Lăn từng viên bột trên bàn tay thành hình ống có hai đầu nhỏ nhọn, nhẹ nhàng ấn và nắn thành hình vầng trăng khuyết hoặc hình lưỡi liềm. Rồi đặt lên khay nướng đã lót giấy nến. Làm lần lượt cho tới hết.', 10);
INSERT INTO public.recipe_steps VALUES (420, '2025-11-20 17:09:52.26817', '2025-11-20 17:09:52.26817', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 76, 2, 'Cho tất cả hỗn hợp gồm 200 gr bột mì, 160 - 180 gr bơ lạt, 150 gr hạt nhân xay nhuyễn, 100 gr đường xay, 1 lọ vani bột (3,5 gr), 1/4 thìa cà phê muối cùng thịt đen của quả vani vào trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (445, '2025-11-20 17:09:52.65735', '2025-11-20 17:09:52.65735', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 80, 2, 'Cắt cam thành các lát đều nhau dày khoảng 0,6 - 0,7 cm.', 10);
INSERT INTO public.recipe_steps VALUES (421, '2025-11-20 17:09:52.355884', '2025-11-20 17:09:52.355884', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 77, 1, 'Măng khô rửa sạch, ngâm nước vo gạo 3 - 4 hôm và thay nước mỗi ngày để loại bỏ độc tố và vị đắng sau đó đem rửa sạch nhiều lần.', 10);
INSERT INTO public.recipe_steps VALUES (422, '2025-11-20 17:09:52.359159', '2025-11-20 17:09:52.359159', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 77, 4, 'Măng sau khi ngâm thì đem xé sợi nhỏ, phần cuống thái miếng bao diêm vừa ăn. Đem luộc măng 3-4 nước, khi luộc nhớ mở vung. Rửa sạch, đem ướp măng với chút mắm, muối, hạt nêm cho đỡ nhạt vị sau đó, phi thơm hành khô cùng mỡ gà hoặc vớt bề mặt mỡ vàng óng nước nước luộc gà (nếu không có dùng mỡ lợn) rồi cho măng vào xào săn lại. Măng ngấm trọn vị tinh túy từ cái ngọt béo của mỡ gà trở nên vàng đẹp và ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (423, '2025-11-20 17:09:52.361255', '2025-11-20 17:09:52.361255', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 77, 7, 'Yêu cầu thành phẩm: Thịt chân giò mềm ngon, măng giòn sần sật, ngấm mỡ đủ vị, nước vàng óng ả rất hấp dẫn. Đây là món ăn truyền thống trong ngày Tết ở miền Bắc.', 10);
INSERT INTO public.recipe_steps VALUES (424, '2025-11-20 17:09:52.364899', '2025-11-20 17:09:52.364899', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 77, 5, 'Mộc nhĩ, nấm hương ngâm nở, rửa sạch, thái miếng vừa ăn. Phi thơm hành tím rồi đem xào săn mộc nhĩ nấm hương.', 10);
INSERT INTO public.recipe_steps VALUES (425, '2025-11-20 17:09:52.368375', '2025-11-20 17:09:52.368375', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 77, 3, 'Xào săn móng giò, thêm nước luộc gà, nếu không có thì cho nước đun sôi vào ninh cho mềm. Thỉnh thoảng hớt bỏ bọt cho nước trong.', 10);
INSERT INTO public.recipe_steps VALUES (426, '2025-11-20 17:09:52.370379', '2025-11-20 17:09:52.370379', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 77, 6, 'Cho măng và mộc nhĩ, nấm hương vào nồi hầm móng giò và tiếp tục ninh cho tới khi móng chín mềm (theo khẩu vị), măng ngấm vị là được. Nêm nếm lại gia vị cho vừa miệng, thêm hành ngò và tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (427, '2025-11-20 17:09:52.374585', '2025-11-20 17:09:52.374585', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 77, 2, 'Móng giò làm sạch, ngâm nước vo gạo hoặc nước muối loãng 30 phút, đem chần sơ nước sôi cùng củ hành tím đập dập, vớt ra rửa sạch lại. Sau đó, đem ướp cùng 1 thìa canh nước mắm, 1 thìa cà phê muối, 1 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu trong 30 phút.', 10);
INSERT INTO public.recipe_steps VALUES (428, '2025-11-20 17:09:52.513578', '2025-11-20 17:09:52.513578', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 78, 3, 'Cho kem tươi, bơ, mạch nha (hoặc siro ngô) vào đảo đều ở lửa nhỏ cho tới khi bơ tan hết và hỗn hợp hòa quyện. Khi hỗn hợp đạt 120 độ thì tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (429, '2025-11-20 17:09:52.515259', '2025-11-20 17:09:52.515259', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 78, 2, 'Cho đường vào nồi/chảo đế dày, thêm lượng nước xâm xấp rồi bật bếp đun sôi trên lửa vừa, không khuấy, mà chỉ lắc nhẹ nồi/chảo để đường tan chảy. Khi đường chuyển màu caramel hơi nâu đỏ thì hạ lửa nhỏ đun cho tới khi bọt đường nhỏ lại.', 10);
INSERT INTO public.recipe_steps VALUES (430, '2025-11-20 17:09:52.517847', '2025-11-20 17:09:52.517847', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 78, 5, 'Đeo găng tay và lấy hỗn hợp hạt cho vào đế bánh thuyền, dàn đều, ấn bám chặt.', 10);
INSERT INTO public.recipe_steps VALUES (431, '2025-11-20 17:09:52.520227', '2025-11-20 17:09:52.520227', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 78, 6, 'Làm nóng lò nướng trước 10 phút, đem nướng bánh ở 160 độ trong 15-18 phút là được. Lấy bánh ra, để nguội, đóng gói trong hộp hoặc túi kín và dùng được trong 2-3 tuần.', 10);
INSERT INTO public.recipe_steps VALUES (432, '2025-11-20 17:09:52.522365', '2025-11-20 17:09:52.522365', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 78, 1, 'Rang chín các loại hạt tùy thích (hạt điều, hạnh nhân, hạt bí xanh...) bằng chảo hoặc cho vào nướng chín.', 10);
INSERT INTO public.recipe_steps VALUES (433, '2025-11-20 17:09:52.524614', '2025-11-20 17:09:52.524614', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 78, 4, 'Thêm muối, nước cốt chanh vào đảo đều. Hỗn hợp đang ấm thì cho các loại hạt đã rang vào đảo đều.', 10);
INSERT INTO public.recipe_steps VALUES (434, '2025-11-20 17:09:52.526774', '2025-11-20 17:09:52.526774', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 78, 7, 'Yêu cầu thành phẩm: Đế bánh xốp, các loại hạt giòn bùi, dậy mùi thơm của caramel, bơ rất hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (435, '2025-11-20 17:09:52.592507', '2025-11-20 17:09:52.592507', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 79, 2, 'Ức gà lọc bỏ xương, ngâm vào nước muối loãng pha ít nước cốt chanh để khử mùi, rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (436, '2025-11-20 17:09:52.594085', '2025-11-20 17:09:52.594085', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 79, 5, 'Phi thơm hành, tỏi, cho nước sốt vào đảo đều cho hòa quyện cho tới khi hỗn hợp sánh lại, thêm ớt khô đảo đều.', 10);
INSERT INTO public.recipe_steps VALUES (437, '2025-11-20 17:09:52.595862', '2025-11-20 17:09:52.595862', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 79, 1, 'Làm hỗn hợp nước sốt gồm 8 thìa canh đường, 2 thìa canh nước mắm, 2 thìa canh nước lọc, 2 thìa cà phê muối, 1 thìa canh tương ớt, 1 thìa canh ớt bột Hàn Quốc, 1 thìa canh dầu màu điều, 1 thìa cà phê bột cà ri, 1 thìa cà phê ngũ vị hương. Khuấy đều cho tan hỗn hợp nước sốt.', 10);
INSERT INTO public.recipe_steps VALUES (438, '2025-11-20 17:09:52.59808', '2025-11-20 17:09:52.59808', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 79, 7, 'Đem gà cho ra khay dàn đều để sấy khô. Bật lò trước, đem gà sấy ở 150 độ C trong 10 phút.', 10);
INSERT INTO public.recipe_steps VALUES (439, '2025-11-20 17:09:52.599667', '2025-11-20 17:09:52.599667', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 79, 6, 'Cho gà đã xé vào hỗn hợp sốt đảo đều, thêm lá chanh vò sơ vào và để ướp tối thiểu 30 phút cho thấm gia vị, nếu để lâu hơn càng ngon. Sau đó, bật lửa vừa và đảo để gà săn lại, nêm nếm lại gia vị cho phù hợp khẩu vị gia đình. Khi gà se lại, thoát hơi nước trở nên khô dần thì tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (440, '2025-11-20 17:09:52.601791', '2025-11-20 17:09:52.601791', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 79, 8, 'Đem gà ra đảo đều, tiếp tục cho vào sấy 10 phút nữa ở 150 độ C là được. Nếu muốn ăn khô hơn thì bạn tiếp tục sấy tiếp 1-2 lần nữa.', 10);
INSERT INTO public.recipe_steps VALUES (441, '2025-11-20 17:09:52.603306', '2025-11-20 17:09:52.603306', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 79, 3, 'Cho ức gà vào nồi cùng lượng nước xâm xấp, thêm sả, gừng đập dập, hành tây, vài lát chanh cùng 1 thìa cà phê muối hạt vào luộc gà. Khi nước sôi, hớt bỏ bọt và hạ lửa vừa luộc trong 15 phút, ngâm gà thêm 10 phút cho chín ngọt.', 10);
INSERT INTO public.recipe_steps VALUES (442, '2025-11-20 17:09:52.605553', '2025-11-20 17:09:52.605553', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 79, 4, 'Vớt gà ra ngâm vào nước đá lạnh hoặc nước lạnh cho nguội, rửa sạch, vớt ra để ráo và xé sợi theo thớ dọc.', 10);
INSERT INTO public.recipe_steps VALUES (443, '2025-11-20 17:09:52.653493', '2025-11-20 17:09:52.653493', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 80, 4, 'Để ướp trong 6-8 tiếng cho đường tan chảy, cam trở nên mọng nước đậm màu trong hơn.', 10);
INSERT INTO public.recipe_steps VALUES (444, '2025-11-20 17:09:52.655076', '2025-11-20 17:09:52.655076', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 80, 5, 'Cho cam và hỗn hợp nước đường vào chảo sên ở lửa vừa, thỉnh thoảng lật trở nhẹ. Bạn không nên đảo nhiều tránh làm gãy nát lát cam.', 10);
INSERT INTO public.recipe_steps VALUES (446, '2025-11-20 17:09:52.658954', '2025-11-20 17:09:52.658954', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 80, 1, 'Cam rửa sạch, chần sơ nước nóng trong 1-2 phút, vớt ra ngâm vào nước lạnh pha muối loãng 15 - 20 phút, rồi rửa sạch. Mục đích việc chần và ngâm nước muối để giảm tinh dầu ở vỏ giúp mứt cam không bị đắng và đảm bảo loại bỏ chất bẩn.', 10);
INSERT INTO public.recipe_steps VALUES (447, '2025-11-20 17:09:52.661075', '2025-11-20 17:09:52.661075', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 80, 3, 'Xếp vào âu một lớp cam rải một lớp đường, làm lần lượt. Phủ một lớp đường ở trên cùng. Thêm phần nước cam khi cắt còn dư (nếu có).', 10);
INSERT INTO public.recipe_steps VALUES (448, '2025-11-20 17:09:52.662648', '2025-11-20 17:09:52.662648', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 80, 6, 'Khi thấy nước đường gần sánh lại thì vớt cam ra. Bạn cho thêm chút nước và tiếp tục sên phần nước đường cho tới khi sền sệt quánh dẻo và màu hơi ngả vàng, trong thì hạ lửa thật nhỏ, cho cam vào đảo nhẹ tay để bám đường đều các mặt.', 10);
INSERT INTO public.recipe_steps VALUES (449, '2025-11-20 17:09:52.664803', '2025-11-20 17:09:52.664803', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 80, 7, 'Gắp các lát cam cho lên rack/giá hong đem phơi nắng 2 ngày hoặc cho vào lò sấy 4-5 tiếng ở 70 độ C. Bảo quản trong lọ thủy tinh hoặc gói kín. Phần syrup (nước sên cam còn lại) thì bạn cho vào lọ thủy tinh, dùng pha trà gừng uống rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (450, '2025-11-20 17:09:52.713215', '2025-11-20 17:09:52.713215', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 81, 1, 'Thịt lợn và bì ngâm nước muối loãng, rửa sạch, thái miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (451, '2025-11-20 17:09:52.714795', '2025-11-20 17:09:52.714795', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 81, 2, 'Chần sơ thịt và bì vào chần sơ kèm vài lát gừng, hành tím cùng chút muối hạt để loại bỏ tạp chất. Sau đó, vớt ra rửa nhiều lần cho tới khi thịt và bì sạch sẽ. Việc này giúp cho khi nấu thịt đông sẽ trong, thơm ngon và đẹp mắt hơn.', 10);
INSERT INTO public.recipe_steps VALUES (452, '2025-11-20 17:09:52.71706', '2025-11-20 17:09:52.71706', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 81, 10, 'Yêu cầu thành phẩm: Thịt đông chắc kết dính thành khối như thạch trong veo, đẹp mắt. Từng miếng thịt mềm mướt, mộc nhĩ nấm hương sần sật, dậy mùi thơm của hạt tiêu, tròn vị. Khi ăn chấm chút vào nước mắm hạt tiêu tất cả như tan ra trong miệng, ăn kèm dưa cải muối rất ngon, làm phong phú thêm thực đơn ngày Tết.', 10);
INSERT INTO public.recipe_steps VALUES (453, '2025-11-20 17:09:52.719197', '2025-11-20 17:09:52.719197', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 81, 5, 'Phi thơm 1/2 lượng hành khô, cho thịt và bì đã ướp vào xào săn. Thêm nước đun sôi vào ngập thịt. Khi nước sôi thì hạ lửa nhỏ vừa, đun trong 1-1,5 giờ cho thịt mềm. Thỉnh thoảng hớt bỏ bọt cho nước trong.', 10);
INSERT INTO public.recipe_steps VALUES (454, '2025-11-20 17:09:52.720784', '2025-11-20 17:09:52.720784', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 81, 8, 'Cà rốt chần sơ, xếp dưới đáy bát đựng (nếu có chữ nhớ xoay ngược để khi úp sẽ thành chữ xuôi).', 10);
INSERT INTO public.recipe_steps VALUES (455, '2025-11-20 17:09:52.72294', '2025-11-20 17:09:52.72294', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 81, 3, 'Ướp thịt và bì với 1 thìa canh nước mắm,1 thìa cà phê muối, 1 thìa cà phê hạt nêm, 1 thìa cà phê hạt tiêu đảo đều cho thấm gia vị, để trong 20-30 phút.', 10);
INSERT INTO public.recipe_steps VALUES (456, '2025-11-20 17:09:52.724527', '2025-11-20 17:09:52.724527', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 81, 7, 'Khi thịt chín mềm, thêm mộc nhĩ nấm hương đã xào vào, nêm nếm mắm, muối, hạt nêm theo khẩu vị. Đun 3 - 4 phút thì thêm chút hạt tiêu, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (457, '2025-11-20 17:09:52.72665', '2025-11-20 17:09:52.72665', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 81, 4, 'Mộc nhĩ ngâm nở, rửa sạch, thái sợi dài; nấm hương ngâm nở, tỉa hoa trên mũ, cà rốt tỉa hình hoa đào (tùy chọn); hành khô băm nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (458, '2025-11-20 17:09:52.728231', '2025-11-20 17:09:52.728231', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 81, 9, 'Nhẹ nhàng múc thịt, bì cùng mộc nhĩ, nấm hương xen kẽ ra bát. Để thật nguội rồi bọc màng bọc thực phẩm, cho vào ngăn mát tủ lạnh 4 - 6 tiếng cho tới khi đông lại là được.', 10);
INSERT INTO public.recipe_steps VALUES (459, '2025-11-20 17:09:52.729868', '2025-11-20 17:09:52.729868', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 81, 6, 'Phi thơm 1/2 lượng hành khô còn lại rồi cho mộc nhĩ, nấm hương vào xào. Nêm chút mắm, hạt nêm cho vừa miệng, xào trong 2 phút là được.', 10);
INSERT INTO public.recipe_steps VALUES (460, '2025-11-20 17:09:52.83048', '2025-11-20 17:09:52.83048', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 82, 2, 'Gọt sạch phần vỏ rám bên ngoài, xong rửa sạch với nước sạch, đến khi nước trong thì thôi.[Caption]', 10);
INSERT INTO public.recipe_steps VALUES (461, '2025-11-20 17:09:52.832635', '2025-11-20 17:09:52.832635', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 82, 6, 'Sau khi đường tan hết, chúng ta cho nước đường lên chảo nấu sôi vớt bọt sạch, sau đó mới để cơm dừa vào, sên với lửa trung bình to.', 10);
INSERT INTO public.recipe_steps VALUES (462, '2025-11-20 17:09:52.836288', '2025-11-20 17:09:52.836288', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 82, 3, 'Cắt thành miếng to để khi ăn cảm nhận được sự dẻo dai của mứt.', 10);
INSERT INTO public.recipe_steps VALUES (463, '2025-11-20 17:09:52.839281', '2025-11-20 17:09:52.839281', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 82, 9, '[Caption]', 10);
INSERT INTO public.recipe_steps VALUES (464, '2025-11-20 17:09:52.842576', '2025-11-20 17:09:52.842576', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 82, 4, 'Chần sơ qua nước sôi 3 phút rồi vớt ra. Trong miếng cùi dừa còn nhiều tinh dầu, nếu xào trực tiếp mứt sẽ nhanh hư và hôi dầu, không bảo quản được lâu. Sau khi chần nước sôi rửa lại lần nữa với nước sạch.[Caption]', 10);
INSERT INTO public.recipe_steps VALUES (465, '2025-11-20 17:09:52.846438', '2025-11-20 17:09:52.846438', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 82, 1, 'Công thức làmmứtdừa non được chị Phương Oliver, ở Đồng Tháp, người sáng tạo nội dung một kênh ẩm thực chia sẻ chi tiết. Cách làm đơn giản, song vẫn cần kinh nghiệm và sự kiên nhẫn canh lửa khi sên mứt dừa.', 10);
INSERT INTO public.recipe_steps VALUES (466, '2025-11-20 17:09:52.849127', '2025-11-20 17:09:52.849127', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 82, 5, 'Cứ 5 kg cơm dừa cho vào 2 kg đường cát trắng mịn, ngâm 2 tiếng. Phần nào cần ướp màu tự nhiên thì để màu vào luôn cho dừa ngấm màu đều.', 10);
INSERT INTO public.recipe_steps VALUES (467, '2025-11-20 17:09:52.851832', '2025-11-20 17:09:52.851832', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 82, 8, 'Cho mứt ra mâm, mẹt để nguội, ráo. Mang phơi nắng 2 giờ là mứt dừa đạt và không bị chảy nước. Thành phẩm miếng mứt khô, dẻo, ngọt nhẹ.', 10);
INSERT INTO public.recipe_steps VALUES (468, '2025-11-20 17:09:52.853615', '2025-11-20 17:09:52.853615', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 82, 7, 'Thỉnh thoảng đảo đều một lần, đến khi đường ráo gần hết nước thì để lửa thật nhỏ, xào đều tay, liên tục. Đến khi có phấn trắng đóng nhẹ xung quanh miếng dừa thì nhấc chảo xuống, tắt bếp và tiếp tục đảo đều tay, đến khi đường thành bột, mịn và miếng dừa khô ráo.', 10);
INSERT INTO public.recipe_steps VALUES (469, '2025-11-20 17:09:52.990525', '2025-11-20 17:09:52.990525', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 83, 3, 'Cho bơ ở nhiệt độ phòng vào bánh mì nhồi cho tới khi tạo thành khối bột mịn dẻo, không dính tay. Bọc màng bọc thực phẩm cho bột nghỉ cho tới khi nở gấp đôi.', 10);
INSERT INTO public.recipe_steps VALUES (470, '2025-11-20 17:09:52.993766', '2025-11-20 17:09:52.993766', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 83, 7, 'Úp ở giữa cái bát nhỏ hoặc hình trụ nhỏ làm nhụy hoa. Chia khối bột thành 16 phần bằng nhau.', 10);
INSERT INTO public.recipe_steps VALUES (471, '2025-11-20 17:09:52.996386', '2025-11-20 17:09:52.996386', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 83, 9, 'Phủ màng bọc thực phẩm cho bông hoa tuyết nở 90%. Sau đó đánh tan lòng đỏ trứng và 2 thìa canh sữa tươi không đường, phết lên bánh.', 10);
INSERT INTO public.recipe_steps VALUES (472, '2025-11-20 17:09:52.99959', '2025-11-20 17:09:52.99959', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 83, 4, 'Làm phần nhân: Cho vào bát nhỏ gồm 40 ml whipping cream, 40 g socola chip, 30 g cream cheese rồi đặt lên bát tô đựng nước nóng bên dưới, dùng dùng phới khuấy đều cho hỗn hợp tan và sánh mịn. Để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (473, '2025-11-20 17:09:53.001722', '2025-11-20 17:09:53.001722', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 83, 11, 'Lấy bánh ra, rắc thêm đường bột trang trí và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (474, '2025-11-20 17:09:53.004365', '2025-11-20 17:09:53.004365', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 83, 1, 'Yêu cầu thành phẩm:Bánh mềm xốp, nhân socola thơm, hình bông tuyết xinh xắn mang đậm không khí Giáng Sinh.', 10);
INSERT INTO public.recipe_steps VALUES (475, '2025-11-20 17:09:53.007286', '2025-11-20 17:09:53.007286', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 83, 5, 'Bột sau khi ủ, ấn xẹp bọt khí, đập nhẹ và chia thành 4 phần đều nhau. Với mỗi phần, gấp mép bột và vê tròn. Bọc màng bọc thực phẩm cho bột nghỉ 15 phút. Thoa chút bột mì lên bàn và cây cán bột, lần lượt cán các khối thành hình tròn.', 10);
INSERT INTO public.recipe_steps VALUES (476, '2025-11-20 17:09:53.010491', '2025-11-20 17:09:53.010491', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 83, 10, 'Làm nóng trước lò nướng 10 phút, đem nướng bánh ở 170 độ trong 18-20 phút ở rãnh giữa. Tùy từng loại lò nướng, nhớ canh nhiệt để điều chỉnh thời gian phù hợp. Nếu dùng nồi chiên không dầu thì nướng bánh 160-170 độ trong 25-28 phút, sau 10 phút thì dùng giấy bạc đậy lên mặt bánh, rồi nướng tiếp.', 10);
INSERT INTO public.recipe_steps VALUES (477, '2025-11-20 17:09:53.013158', '2025-11-20 17:09:53.013158', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 83, 2, 'Nhồi bột mì: Làm ấm 150 ml sữa tươi không đường, cho 30 g đường xay, 1 thìa cà phê men nở vào khuấy đều để nghỉ một lúc cho men kích hoạt. Cho 1 quả trứng gà vào 300 gr bột mì, thêm 1/2 thìa cà phê muối trộn đều. Sau đó, rót lần lượt từng ít một hỗn hợp sữa cùng men đã kích hoạt vào trộn đều cho tới khi hòa quyện thành khối, bọc màng bọc thực phẩm để bột nghỉ 15 phút.', 10);
INSERT INTO public.recipe_steps VALUES (478, '2025-11-20 17:09:53.01586', '2025-11-20 17:09:53.01586', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 83, 6, 'Đặt một miếng bột hình tròn lên giấy nến hoặc tấm nướng, phết hỗn hợp sốt socola lên trên. Rồi tiếp tục đặt miếng bột tròn thứ 2 lên và phết socola. Làm lần lượt cho cả miếng bột tròn thứ 3. Cuối cùng up trên cùng là tấm bột thứ 4. Sau đó thoa chút nước vào tay và gấp chặt mép dính lại 4 lớp bánh để tránh bị bung khi tạo hình và nướng.', 10);
INSERT INTO public.recipe_steps VALUES (479, '2025-11-20 17:09:53.017975', '2025-11-20 17:09:53.017975', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 83, 8, 'Lật và xoắn 2 phần cạnh nhau, cuộn vào tạo thành một cánh hoa. Làm lần lượt cho tới hết là được 8 cánh hoa bông tuyết xoáy. Rắc thêm vụn dừa bào sợi, nhân thêm phần nho hạt trang trí nếu thích.', 10);
INSERT INTO public.recipe_steps VALUES (480, '2025-11-20 17:09:53.112873', '2025-11-20 17:09:53.112873', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 84, 1, 'Làm ấm 160-180 ml sữa tươi không đường ở 32-38 độ, cho 5 gr men nở vào sữa để trong 10 phút cho men kích hoạt. Cho tiếp 40 gr đường vào khuấy đều cho men hoạt động tốt nhất.', 10);
INSERT INTO public.recipe_steps VALUES (481, '2025-11-20 17:09:53.116228', '2025-11-20 17:09:53.116228', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 84, 2, 'Cho 1 quả trứng gà vào bột mì, thêm 3gr muối trộn đều. Sau đó, rót hỗn hợp sữa và men đã kích hoạt vào trộn đều cho tới khi hòa quyện. Để bột nghỉ khoảng 15- 20 phút. Rồi thêm 30gr bơ lạt (ở nhiệt độ phòng) rồi nhồi cho tới khi tạo thành khối bột mịn, không dính tay. Bọc màng bọc thực phẩm cho bột nghỉ trong 1 giờ cho tới khi nở gấp đôi.', 10);
INSERT INTO public.recipe_steps VALUES (482, '2025-11-20 17:09:53.117821', '2025-11-20 17:09:53.117821', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 84, 3, 'Bột sau khi ủ, ấn xẹp bọt khí, đập nhẹ và nhồi trong 1 phút rồi chia làm 2 phần bằng nhau.', 10);
INSERT INTO public.recipe_steps VALUES (483, '2025-11-20 17:09:53.120185', '2025-11-20 17:09:53.120185', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 84, 9, 'Bọc màng bọc thực phẩm cho bánh mì cây thông nghỉ một giờ cho tới khi bột nở 90%. Sau đó đánh tan lòng đỏ trứng và 2 thìa canh sữa tươi không đường, phết lên bánh.', 10);
INSERT INTO public.recipe_steps VALUES (484, '2025-11-20 17:09:53.121771', '2025-11-20 17:09:53.121771', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 84, 11, 'Yêu cầu thành phẩm: Bánh hình cây thông Noel đẹp mắt, bánh nở mềm xốp, nhân mứt dâu quyện cùng quả sấy rất hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (485, '2025-11-20 17:09:53.123377', '2025-11-20 17:09:53.123377', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 84, 10, 'Làm nóng lò trước 10 phút ở 180 độ C. Cho bánh vào nướng ở 180 độ trong 25 phút ở rãnh giữa. Sau đó, lấy ra phết bơ lên bề mặt bánh khi bánh còn nóng ấm.', 10);
INSERT INTO public.recipe_steps VALUES (486, '2025-11-20 17:09:53.125479', '2025-11-20 17:09:53.125479', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 84, 4, 'Cán từng khối bột thành hình chữ nhật. Rắc chút bột khô lên giấy nến hoặc tấm nướng, để phần bột thứ nhất lên. Tiếp tục cán phần bột thứ 2 thành hình chữ nhật.', 10);
INSERT INTO public.recipe_steps VALUES (487, '2025-11-20 17:09:53.127066', '2025-11-20 17:09:53.127066', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 84, 5, 'Chuẩn bị phần nhân (tùy chọn, linh hoạt thay đổi theo khẩu vị): mứt dâu và cắt nhỏ các loại hoa quả sấy.', 10);
INSERT INTO public.recipe_steps VALUES (488, '2025-11-20 17:09:53.13123', '2025-11-20 17:09:53.13123', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 84, 6, 'Phết mứt dâu lên một mặt của một miếng bột, rải đều các loại hoa quả sấy đã cắt nhỏ, rồi xếp chồng miếng bột hình chữ nhật còn lại phủ lên trên.', 10);
INSERT INTO public.recipe_steps VALUES (489, '2025-11-20 17:09:53.133367', '2025-11-20 17:09:53.133367', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 84, 7, 'Kẻ 2 đường thẳng ở giữa tạo thân cây thông, rồi kẻ 2 đường chéo bên cạnh tạo hình tam giác định hình cây thông. Sau đó cắt chia đều các nhánh. Nhớ mím chặt các mép.', 10);
INSERT INTO public.recipe_steps VALUES (490, '2025-11-20 17:09:53.136078', '2025-11-20 17:09:53.136078', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 84, 8, 'Xoay hình xoắn ốc mỗi nhánh thông tạo cành và thành cây thông Noel.', 10);
INSERT INTO public.recipe_steps VALUES (491, '2025-11-20 17:09:53.261259', '2025-11-20 17:09:53.261259', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 85, 3, 'Thịt chín vừa tới thì gắp ra để nguội xé nhỏ dọc theo thớ (đừng xé nhỏ quá, đập miếng thịt heo hơi dập rồi xé to một chút).', 10);
INSERT INTO public.recipe_steps VALUES (522, '2025-11-20 17:09:53.966085', '2025-11-20 17:09:53.966085', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 90, 7, 'Khi vỏ cam nguội hẳn vớt ra rổ, vắt nhẹ cho ra bớt nước rồitrộn với đường.', 10);
INSERT INTO public.recipe_steps VALUES (1258, '2025-11-20 17:10:17.203148', '2025-11-20 17:10:17.203148', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 224, 7, 'Nêm vào nồi nước dùng chút muối, bột ngọt, hạt nêm... sao cho vừa miệng là được.', 10);
INSERT INTO public.recipe_steps VALUES (492, '2025-11-20 17:09:53.263376', '2025-11-20 17:09:53.263376', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 85, 5, 'Cho các nguyên liệu sả, tỏi, gừng, ớt, 1/2 bát ăn cơm nước rim thịt vào máy xay sinh tố, xay thật nhỏ. Sau khi xay đem trộn với 1 gói ngũ vị hương, 1 thìa canh nước mắm, 2 thìa cà phê bột canh, dầu điều, ớt bột Hàn Quốc, đường, 1/2 gói gia vị bò kho. Đổ tất cả vào âu thịt đã xé rồi trộn đều. Nêm nếm lại theo khẩu vị (nên nêm nhạt hơn chút thì khi sấy xong sẽ vừa ăn).', 10);
INSERT INTO public.recipe_steps VALUES (493, '2025-11-20 17:09:53.265481', '2025-11-20 17:09:53.265481', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 85, 2, 'Cho thịt vào nồi với chút nước, một nhánh gừng, 2 cây sả, 1 thìa cà phê muối đặt lên bếp rim thịt. Thỉnh thoảng lật đều. Thịt sẽ tiết ra nước trong quá trình rim nên không cần cho quá nhiều nước làm cho thịt bị nhạt.', 10);
INSERT INTO public.recipe_steps VALUES (494, '2025-11-20 17:09:53.268333', '2025-11-20 17:09:53.268333', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 85, 6, 'Cho chảo đế dầy lên bếp, đổ phần thịt đã trộn gia vị vào sên (lưu ý không nên ướp thịt).', 10);
INSERT INTO public.recipe_steps VALUES (495, '2025-11-20 17:09:53.270487', '2025-11-20 17:09:53.270487', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 85, 7, 'Lúc đầu thịt còn nhiều nước thì để lửa to vừa, thịt gần cạn thì hạ lửa nhỏ. Tránh đảo nhiều làm thịt bị bông.', 10);
INSERT INTO public.recipe_steps VALUES (496, '2025-11-20 17:09:53.273154', '2025-11-20 17:09:53.273154', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 85, 8, 'Thịt hơi khô lại thì tắt bếp luôn.Cho thịt ra khay có lót giấy nến, trải đều. Sấy thịt bằng lò nướng 120 độ trong 20 phút. Sau đó lật mặt sấy thêm 20 phút nữa. Nếu thịt vẫn chưa khô thì tăng thêm thời gian sấy lên đến khi thịt khô theo ý muốn.', 10);
INSERT INTO public.recipe_steps VALUES (497, '2025-11-20 17:09:53.276534', '2025-11-20 17:09:53.276534', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 85, 1, 'Thịt nạc mông rửa sạch, thấm khô, thái miếng mỏng 1 cm, dọc thớ.', 10);
INSERT INTO public.recipe_steps VALUES (498, '2025-11-20 17:09:53.279706', '2025-11-20 17:09:53.279706', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 85, 4, 'Phần nước rim thịt xong không đổ đi mà để lại để xay cùng các gia vị làm nước sốt.', 10);
INSERT INTO public.recipe_steps VALUES (499, '2025-11-20 17:09:53.4192', '2025-11-20 17:09:53.4192', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 86, 7, 'Sườn sau khi hấp (hoặc nướng lần 1) mềm thì lấy ra, phết đều hỗn hợp nước sốt lên các mặt. Thêm các lát cam cắt mỏng và rắc chút lá xạ hương (thyme) rồi cho vào lò nướng ở 250 độ C trong 15 phút. Sau đó, lấy ra trở mặt còn lại nướng tiếp 15 phút là sườn chín và lên màu nâu bóng đẹp.', 10);
INSERT INTO public.recipe_steps VALUES (500, '2025-11-20 17:09:53.423615', '2025-11-20 17:09:53.423615', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 86, 5, 'Làm mềm sườn bằng một trong hai cách sau. Cách 1: Đem sườn đã ướp và gói trong giấy bạc nướng trong 1,5 -2 giờ ở 160-170 độ C. Cách 2: nhanh hơn thì đem hấp khoảng 40-45 phút (nếu dùng nồi Instant Pot hấp thì chỉ trong 20 phút).', 10);
INSERT INTO public.recipe_steps VALUES (501, '2025-11-20 17:09:53.42687', '2025-11-20 17:09:53.42687', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 86, 2, 'Bào và lấy phần vỏ cam màu vàng khoảng 2 thìa canh.', 10);
INSERT INTO public.recipe_steps VALUES (502, '2025-11-20 17:09:53.430066', '2025-11-20 17:09:53.430066', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 86, 8, 'Yêu cầu thành phẩm: Thịt sườn mềm ngon, róc thịt, nước sốt sánh nâu đỏ quyện với hương thơm đặc trưng của cam góp phần tạo nên bữa tiệc Giáng sinh hoàn hảo.', 10);
INSERT INTO public.recipe_steps VALUES (503, '2025-11-20 17:09:53.43283', '2025-11-20 17:09:53.43283', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 86, 4, 'Đeo găng tay, thoa đều hỗn hợp bột ướp khô ở trên vào hai mặt sườn. Sau đó, bọc kín bằng giấy bạc. Ướp tối thiểu trong 2 giờ hoặc để qua đêm trong ngăn mát tủ lạnh sẽ thấm vị ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (504, '2025-11-20 17:09:53.436713', '2025-11-20 17:09:53.436713', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 86, 1, 'Sườn ngâm nước muối loãng, rửa sạch, thấm khô. Lật ngửa miếng sườn bóc lớp màng (mỡ và gân), khía nhẹ các dẻ vừa tránh sườn bị co khi nướng và giúp róc thịt hơn.', 10);
INSERT INTO public.recipe_steps VALUES (505, '2025-11-20 17:09:53.43885', '2025-11-20 17:09:53.43885', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 86, 3, 'Pha hỗn hợp khô ướp sườn gồm: 1 muỗng canh bột tỏi (hoặc nước cốt tỏi giã, vắt), 1 muỗng canh bột hành (hoặc nước cốt hành giã, vắt), 1 muỗng canh bột ớt Hàn Quốc, 1/2 muỗng canh muối. Rồi thêm 1 muỗng canh vỏ cam bào vào trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (506, '2025-11-20 17:09:53.442384', '2025-11-20 17:09:53.442384', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 86, 6, 'Làm nước sốt sườn: Phi thơm tỏi, cho 1 cup hành tây cắt hạt lựu vào xào mềm. Sau đó thêm 1 cup nước cam vắt,  1/2 cup đường vàng, 2 thìa canh tương cà (ketchup), 2 thìa canh tương ớt, 2 thìa canh dầu hào, 2 thìa canh giấm, 1 thìa canh mật ong, 1 thìa canh vỏ cam bào, 1 thìa canh tỏi bằm, 2 thìa cà phê muối, 1 thìa cà phê hạt tiêu trộn đều. Hạ lửa nhỏ vừa, đun cho sôi và khuấy đều cho tới khi trở thành hỗn hợp sền sệt, tắt bếp, múc ra bát để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (507, '2025-11-20 17:09:53.644147', '2025-11-20 17:09:53.644147', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 87, 1, 'Chuẩn bị
INSERT INTO public.recipe_steps VALUES (523, '2025-11-20 17:09:53.968231', '2025-11-20 17:09:53.968231', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 90, 10, 'Thỉnh thoảng mới đảo, đến khi đường keo lại gần kết tinh đảo nhanh tay hơn. Có thể nhấc chảo ra ngoài vài phút để đảo sau đó lại cho chảo trở lại bếp đảo đến khi đường kết tinh hoàn toàn là được.', 10);
INSERT INTO public.recipe_steps VALUES (524, '2025-11-20 17:09:53.970634', '2025-11-20 17:09:53.970634', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 90, 3, 'Dùng dao cắt thành bốn miếng theo chiều dọc, nhẹ nhàng tách từng miếng vỏ cam ra.', 10);
INSERT INTO public.recipe_steps VALUES (525, '2025-11-20 17:09:53.972222', '2025-11-20 17:09:53.972222', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 90, 4, 'Lược nhẹ bớt phần xơ trắng xốp bên trong phía vỏ cam.Thái thành những miếng nhỏ vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (526, '2025-11-20 17:09:53.974988', '2025-11-20 17:09:53.974988', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 90, 9, 'Cho vỏ cam vào chảo đế dày để nấu. Vỏ cam sôi thì hạ bớt lửa, gần cạn thì đổ nước vắt của nửa quả cam vào đảo đều.', 10);
INSERT INTO public.recipe_steps VALUES (797, '2025-11-20 17:10:06.920108', '2025-11-20 17:10:06.920108', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 151, 3, 'Phi thơm 1/2 lượng tỏi băm, cho thịt bò vào xào trên lửa lớn, đảo đều tay. Khi thịt bò chín khoảng 80% (hơi tái) thì trút ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (508, '2025-11-20 17:09:53.64685', '2025-11-20 17:09:53.64685', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 87, 2, 'Thực hiện
INSERT INTO public.recipe_steps VALUES (509, '2025-11-20 17:09:53.650253', '2025-11-20 17:09:53.650253', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 87, 3, 'Yêu cầu thành phẩm
INSERT INTO public.recipe_steps VALUES (510, '2025-11-20 17:09:53.763631', '2025-11-20 17:09:53.763631', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 88, 2, 'Chế biến
INSERT INTO public.recipe_steps VALUES (511, '2025-11-20 17:09:53.765807', '2025-11-20 17:09:53.765807', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 88, 1, 'Chuẩn bị và tẩm ướp
INSERT INTO public.recipe_steps VALUES (512, '2025-11-20 17:09:53.768514', '2025-11-20 17:09:53.768514', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 88, 3, 'Yêu cầu thành phẩm
INSERT INTO public.recipe_steps VALUES (513, '2025-11-20 17:09:53.850923', '2025-11-20 17:09:53.850923', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 89, 4, 'Yêu cầu thành phẩm
INSERT INTO public.recipe_steps VALUES (514, '2025-11-20 17:09:53.854116', '2025-11-20 17:09:53.854116', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 89, 2, 'Tẩm ướp
INSERT INTO public.recipe_steps VALUES (515, '2025-11-20 17:09:53.85672', '2025-11-20 17:09:53.85672', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 89, 1, 'Sơ chế
INSERT INTO public.recipe_steps VALUES (516, '2025-11-20 17:09:53.858876', '2025-11-20 17:09:53.858876', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 89, 3, 'Chế biến
INSERT INTO public.recipe_steps VALUES (517, '2025-11-20 17:09:53.954453', '2025-11-20 17:09:53.954453', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 90, 1, 'Cam rửa sạch từng quả, để khô ráo', 10);
INSERT INTO public.recipe_steps VALUES (518, '2025-11-20 17:09:53.956342', '2025-11-20 17:09:53.956342', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 90, 2, 'Dùng dao sắc gọt thật mỏng lớp vỏ sần sùi bên ngoài để giảm bớt độ the đắng và làm cho vỏ cam có màu đẹp hơn.', 10);
INSERT INTO public.recipe_steps VALUES (519, '2025-11-20 17:09:53.958592', '2025-11-20 17:09:53.958592', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 90, 6, 'Đun sôi nồi nước, thả vào đó một thìa canh muối ăn (mặn hơn khẩu vị bình thường), thả toàn bộ vỏ cam vào chần khoảng 3-4 phút, vớt ra một âu nước đá.', 10);
INSERT INTO public.recipe_steps VALUES (520, '2025-11-20 17:09:53.96126', '2025-11-20 17:09:53.96126', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 90, 8, 'Để vỏ cam qua đêm hoặc vài tiếng cho đường tan, thỉnh thoảng đảo nhẹ để ngấm.', 10);
INSERT INTO public.recipe_steps VALUES (521, '2025-11-20 17:09:53.96342', '2025-11-20 17:09:53.96342', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 90, 5, 'Đem vỏ cam rửa với vài lần nước, nhớ bóp nhẹ nhàng để dầu từ vỏ cam được tiết ra, thành phẩm sẽ đỡ đắng hơn.Rửa đến khi thấy nước đỡ đục vàng của dầu vỏ cam thì vớt ra vắt nhẹ để ráo nước (rửa khoảng bốn nước)', 10);
INSERT INTO public.recipe_steps VALUES (4769, '2025-11-20 17:12:26.980187', '2025-11-20 17:12:26.980187', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 730, 9, 'Dứa xắt mỏng (nếu có)', 10);
INSERT INTO public.recipe_steps VALUES (527, '2025-11-20 17:09:53.977117', '2025-11-20 17:09:53.977117', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 90, 11, 'Sau khi đường kết tinh, hạ lửa đến mức thấp nhất. Để mứt trên chảo cứ 5 phút đảo một lần, làm như vậy trong khoảng 15-20 phút. Có lò sấy hạ xuống 100 độ, sấy trong 15-20 phút, thỉnh thoảng mở cửa lò đảo lại.', 10);
INSERT INTO public.recipe_steps VALUES (528, '2025-11-20 17:09:54.052434', '2025-11-20 17:09:54.052434', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 91, 1, 'Sơ chế
