INSERT INTO public.recipe_steps VALUES (530, '2025-11-20 17:09:54.151036', '2025-11-20 17:09:54.151036', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 92, 3, 'Yêu cầu thành phẩm
