INSERT INTO public.recipe_steps VALUES (639, '2025-11-20 17:10:00.989523', '2025-11-20 17:10:00.989523', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 123, 1, 'Sơ chế
INSERT INTO public.recipe_steps VALUES (640, '2025-11-20 17:10:00.992742', '2025-11-20 17:10:00.992742', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 123, 2, 'Tỏi bóc bỏ vỏ, băm nhỏ. Gừng băm nhỏ. Sả đập dập, cắt khúc. Quế, hoa hồi rang thơm. Hành tây cắt lát mỏng, ngâm nước đá.', 10);
INSERT INTO public.recipe_steps VALUES (641, '2025-11-20 17:10:00.996658', '2025-11-20 17:10:00.996658', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 123, 3, 'Cà rốt gọt vỏ, rửa sạch, dùng dao tỉa hoa và cắt khúc.', 10);
INSERT INTO public.recipe_steps VALUES (642, '2025-11-20 17:10:01.000508', '2025-11-20 17:10:01.000508', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 123, 5, 'Chế biến
INSERT INTO public.recipe_steps VALUES (718, '2025-11-20 17:10:04.05123', '2025-11-20 17:10:04.05123', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 138, 2, 'Tỏi bóc vỏ, chia đôi một phần đập dập, phần còn lại thì băm nhỏ. Ớt bỏ hạt, thái lát.', 10);
INSERT INTO public.recipe_steps VALUES (643, '2025-11-20 17:10:01.168607', '2025-11-20 17:10:01.168607', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 124, 3, 'Chế biến
