INSERT INTO public.recipe_steps VALUES (650, '2025-11-20 17:10:01.383481', '2025-11-20 17:10:01.383481', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 125, 2, 'Chuẩn bị
INSERT INTO public.recipe_steps VALUES (651, '2025-11-20 17:10:01.56131', '2025-11-20 17:10:01.56131', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 126, 1, 'Cà pháo muối rửa cho bớt chua, bổ đôi để khi ram nhanh chín và thấm vị.', 10);
INSERT INTO public.recipe_steps VALUES (652, '2025-11-20 17:10:01.565714', '2025-11-20 17:10:01.565714', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 126, 3, 'Lá lốt rửa sạch, thái rối. Hành, tỏi băm nhỏ. Ớt bổ đôi bỏ hạt, thái lát hoặc thái sợi dài tùy chọn.', 10);
INSERT INTO public.recipe_steps VALUES (653, '2025-11-20 17:10:01.569703', '2025-11-20 17:10:01.569703', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 126, 4, 'Rang thịt xém cạnh: Đung nóng chảo, cho thịt vào đảo đều cho tới khi chảy bớt mỡ và các bề mặt thịt xém cạnh, chắt bớt mỡ ra.', 10);
INSERT INTO public.recipe_steps VALUES (654, '2025-11-20 17:10:01.572477', '2025-11-20 17:10:01.572477', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 126, 5, 'Cho hành, tỏi vào đảo cùng thịt cho thơm. Trút phần cà pháo vào đảo đều. Nêm lại mắm, muối, đường, hạt nêm cho vừa miệng. Khi cà chín, hơi sém và quyện đủ vị thì cho lá lốt đảo đều, thêm ớt và tắt bếp, múc ra thưởng thức cùng cơm nóng.', 10);
INSERT INTO public.recipe_steps VALUES (655, '2025-11-20 17:10:01.577086', '2025-11-20 17:10:01.577086', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 126, 6, 'Yêu cầu thành phẩm: Thịt ba rọi xém cạnh đậm vị quyện với cà pháo vị chua ngọt hài hòa, dậy mùi thơm của tỏi, lá lốt kích thích vị giác.', 10);
INSERT INTO public.recipe_steps VALUES (656, '2025-11-20 17:10:01.579746', '2025-11-20 17:10:01.579746', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 126, 2, 'Thịt ba chỉ chọn nạc mỡ đan xen, rửa sạch, thái miếng vừa ăn cỡ 0,4 - 0,5cm.', 10);
INSERT INTO public.recipe_steps VALUES (657, '2025-11-20 17:10:01.815775', '2025-11-20 17:10:01.815775', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 127, 7, 'Yêu cầu thành phẩm: Xôi sau khi đồ cùng trám như khoác lớp áo mới chuyển màu hồng tím đẹp mắt, hương thơm nồng nàn tỏa khắp nhà, hạt căng mẩy, dẻo mềm. Khi ăn vị bùi béo, cộng chút sần sật từ nhân trám, chấm chút muối vừng cứ nhẩn nha mãi. Món ăn bình dân mà gây thương gây nhớ cho bao người mỗi độ thu về có trám đen.', 10);
INSERT INTO public.recipe_steps VALUES (658, '2025-11-20 17:10:01.819126', '2025-11-20 17:10:01.819126', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 127, 1, 'Gạo nếp vo sạch rồi ngâm nước từ 6 - 8 giờ để gạo ngậm no nước khi đồ xôi dẻo mềm. Sau đó đổ ra rổ cho ráo nước, xóc 1/2 thìa cà phê muối cho đậm vị và thêm chút dầu ăn trộn đều để tạo độ bóng.', 10);
INSERT INTO public.recipe_steps VALUES (659, '2025-11-20 17:10:01.825021', '2025-11-20 17:10:01.825021', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 127, 4, 'Đồ xôi lửa 1:  Đun sôi nước (khoảng 1/3 nồi), cho gạo nếp vào dàn đều, chọc mấy lỗ thủng to cho thoát nhiệt rồi đồ xôi. Thỉnh thoảng xới cho xôi chín đều. Sau khoảng 30% khi xôi chín độ 70 - 80% thì xới ra rổ hoặc mẹt, tãi đều rồi hong quạt cho nguội.', 10);
INSERT INTO public.recipe_steps VALUES (660, '2025-11-20 17:10:01.828334', '2025-11-20 17:10:01.828334', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 127, 6, 'Đồ xôi lửa 2: Vẩy chút nước lạnh vào xôi, đảo đều cho tơi hạt. Rưới chút mỡ gà trộn đều tạo độ bóng mẩy cho hạt xôi. Tiếp tục đồ xôi trong 15 phút. Khi xôi chín thì cho trám xào thịt vào đảo đều cho quyện vào nhau là được.', 10);
INSERT INTO public.recipe_steps VALUES (661, '2025-11-20 17:10:01.833168', '2025-11-20 17:10:01.833168', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 127, 3, 'Tùy theo khẩu vị, một số người thích vị hơi chát thì để nguyên vỏ trám để đồ. Còn nếu thích mịn thì bóc bỏ vỏ trám đen bên ngoài.Tỉ mỉ, cầu kỳ hơn thì lấy thêm phần nhân từ hạt trám giúp cho món xôi thêm cảm giác bùi béo hấp dẫn. Cho từng hạt trám lên thớt, đặt dưới là cái khăn để giữ hạt không bị văng hay xê dịch. Dùng dao nặng chặt đôi hạt, rồi khều phần nhân trắng ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (662, '2025-11-20 17:10:01.835838', '2025-11-20 17:10:01.835838', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 127, 5, 'Trong lúc chờ xôi nguội thì phi thơm hành khô với mỡ gà rồi cho thịt vai sấn (có lẫn chút mỡ, đã ướp chút mắm, mì chính, hạt tiêu) vào đảo cho săn thấm vị. Sau đó, cho trám, nhân trám vào đảo nhuyễn, nêm nếm lại gia vị cho vừa miệng. Thịt và trám quyện vào nhau vừa bùi béo, vừa tỏa mùi thơm hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (663, '2025-11-20 17:10:01.841864', '2025-11-20 17:10:01.841864', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 127, 2, 'Trám tươi rửa sạch, cho vào âu cùng với nước ấm (nước om trám là ''''3 sôi, 2 lạnh'''' để nước khoảng 70-80 độ là đạt), đậy vung kín cho tới khi trám mềm thì vớt ra, tách đôi, bỏ hạt. Việc om trám rất quan trọng, cần căn tỷ lệ nước ấm phù hợp, bởi nếu nước sôi già quá sẽ làm trám cứng, nếu nguội quá thì trám sượng hoặc bở nát khó tách lấy thịt.', 10);
INSERT INTO public.recipe_steps VALUES (664, '2025-11-20 17:10:01.956659', '2025-11-20 17:10:01.956659', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 128, 1, 'Sơ chế
INSERT INTO public.recipe_steps VALUES (665, '2025-11-20 17:10:01.960121', '2025-11-20 17:10:01.960121', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 128, 3, 'Chế biến
INSERT INTO public.recipe_steps VALUES (666, '2025-11-20 17:10:01.96293', '2025-11-20 17:10:01.96293', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 128, 4, 'Yêu cầu thành phẩm
INSERT INTO public.recipe_steps VALUES (667, '2025-11-20 17:10:01.965041', '2025-11-20 17:10:01.965041', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 128, 2, 'Mộc nhĩ (nấm mèo) ngâm nở, rửa sạch rồi thái nhỏ. Hành khô băm nhỏ. Hành lá, rau mùi rửa sạch, thái nhỏ. Cho thịt cùng mộc nhĩ, 1/2 lượng hành khô, chút hành lá vào âu, ướp với 1 muỗng cà phê nước mắm, 1/2 muỗng cà phê hạt nêm, 1/2 muỗng cà phê hạt tiêu trộn đều cho thấm vị.', 10);
INSERT INTO public.recipe_steps VALUES (668, '2025-11-20 17:10:02.17098', '2025-11-20 17:10:02.17098', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 129, 2, 'Tẩm ướp
