INSERT INTO public.recipe_steps VALUES (676, '2025-11-20 17:10:02.446163', '2025-11-20 17:10:02.446163', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 131, 2, 'Tẩm ướp
