INSERT INTO public.recipe_steps VALUES (682, '2025-11-20 17:10:02.678718', '2025-11-20 17:10:02.678718', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 132, 2, 'Tẩm ướp
INSERT INTO public.recipe_steps VALUES (683, '2025-11-20 17:10:02.684034', '2025-11-20 17:10:02.684034', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 132, 4, 'Yêu cầu thành phẩm
INSERT INTO public.recipe_steps VALUES (684, '2025-11-20 17:10:02.78834', '2025-11-20 17:10:02.78834', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 133, 3, 'Xúc lượng nhân vừa đủ nhồi vào phần đậu ở giữa, miết nhẹ cho mịn. Chú ý không ấn mạnh vì dễ làm đậu bị vỡ. Làm lần lượt cho tới hết.', 10);
INSERT INTO public.recipe_steps VALUES (685, '2025-11-20 17:10:02.793449', '2025-11-20 17:10:02.793449', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 133, 5, 'Cà chua khứa hình chữ thập, rồi đem chần sơ, rửa sạch rồi bóc bỏ vỏ, đem xay nhuyễn hoặc băm nhỏ. Việc lột bỏ vỏ giúp nước sốt sánh mịn, đẹp mắt và đỡ bị lợn cợn.', 10);
INSERT INTO public.recipe_steps VALUES (686, '2025-11-20 17:10:02.796606', '2025-11-20 17:10:02.796606', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 133, 2, 'Mộc nhĩ, nấm hương ngâm nở, rửa sạch, thái nhỏ. Hành lá rửa sạch, thái nhỏ. Hành khô băm nhỏ. Cho thịt xay cùng mộc nhĩ, nấm hương, 1/2 lượng hành lá, hành khô vào âu. Nêm 1 thìa cà phê nước mắm, 1/2 thìa cà phê muối, 1/2 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu đảo đều cho thấm vị.', 10);
INSERT INTO public.recipe_steps VALUES (687, '2025-11-20 17:10:02.799301', '2025-11-20 17:10:02.799301', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 133, 6, 'Phi thơm 1/2 số hành khô còn lại, cho cà chua vào, nêm 2 thìa cà phê nước mắm, 1/2 thìa cà phê muối. Thêm chút nước, đun nhỏ lửa cho tới khi cà chua mềm nhuyễn. Cho đậu phụ vào đun sôi, om vài phút cho đậu thấm vị. Cuối cùng, nêm 1/2 thìa cà phê hạt nêm, rắc chút hạt tiêu, hành lá đảo đều, múc ra thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (688, '2025-11-20 17:10:02.801434', '2025-11-20 17:10:02.801434', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 133, 7, 'Yêu cầu thành phẩm: Đậu phụ vỏ dai, bên trong dồn thịt mềm ngọt, nước sốt cà chua đỏ vàng sóng sánh, vị hài hòa dễ ''''bắt cơm'''' khi thời tiết chuyển mùa.', 10);
INSERT INTO public.recipe_steps VALUES (689, '2025-11-20 17:10:02.804176', '2025-11-20 17:10:02.804176', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 133, 1, 'Đậu phụ cắt miếng vuông, dùng dao mũi nhọn cắt hình vuông hoặc tròn (tùy chọn) ở giữa. Rồi dùng thìa nhỏ múc phần đậu bên trong ra sao vẫn giữ được phần đáy khoảng 1-1,5cm.', 10);
INSERT INTO public.recipe_steps VALUES (690, '2025-11-20 17:10:02.80747', '2025-11-20 17:10:02.80747', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 133, 4, 'Đun nóng dầu ăn, lần lượt cho đậu vào nhẹ tay và rán vàng đều hai mặt', 10);
INSERT INTO public.recipe_steps VALUES (691, '2025-11-20 17:10:03.008571', '2025-11-20 17:10:03.008571', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 134, 4, 'Phi thơm hành, tỏi và sả còn lại, cho ngan vào xào trên lửa lớn. Đảo đều cho thịt không bén chảo. Khi thịt ngan săn lại thì cho ớt, nêm nếm lại gia vị vừa miệng. Cuối cùng cho hành lá, rau ngổ vào đảo qua, tắt bếp, rắc hạt tiêu và múc ra thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (692, '2025-11-20 17:10:03.021652', '2025-11-20 17:10:03.021652', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 134, 2, 'Ngan làm sạch, chà xát chanh và muối hạt khử mùi, rửa sạch, để ráo nước. Dùng dao sắc thái thành miếng mỏng vừa ăn.Ướp ngan với phần sả băm và 1/2 lượng hành, tỏi khô cùng 1 muỗng canh dầu hào, 1/2 muỗng canh dầu ăn, 1 muỗng cà phê nước mắm, 1 muỗng cà phê hạt nêm và 1/2 muỗng cà phê hạt tiêu đảo đều. Ướp trong 30 phút cho thấm vị.', 10);
INSERT INTO public.recipe_steps VALUES (696, '2025-11-20 17:10:03.265691', '2025-11-20 17:10:03.265691', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 135, 4, 'Phi thơm 1/2 lượng hành khô băm. Hạ lửa nhỏ, cho 1/2 lượng nước sốt vào chảo đảo đều, thêm khoảng 1/3 bát nước lạnh vào. Cho bún gạo vào, đảo đều cho gia vị quyện đều vào sợi bún gạo. Sau 2 - 3 phút thì múc ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (697, '2025-11-20 17:10:03.271559', '2025-11-20 17:10:03.271559', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 135, 5, 'Phi thơm 1/2 lượng hành khô còn lại, cho rau củ quả (cà rốt, bắp cải, ớt chuông và hành tây) vào, trút 1/2 lượng nước sốt còn lại và xào trên lửa lớn cho chín tới. Thêm đậu phụ chiên vào đảo cho thấm vị.', 10);
INSERT INTO public.recipe_steps VALUES (698, '2025-11-20 17:10:03.278846', '2025-11-20 17:10:03.278846', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 135, 1, 'Đậu phụ chiên vàng giòn, cắt miếng dài. Ớt chuông đỏ, ớt chuông xanh cắt sợi dài. Cà rốt cắt sợi. Hành tây cắt lát dài. Bắp cải cắt sợi. Hành lá cắt khúc. Tùy theo sở thích thay đổi rau củ quả phù hợp theo mùa.', 10);
INSERT INTO public.recipe_steps VALUES (699, '2025-11-20 17:10:03.282876', '2025-11-20 17:10:03.282876', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 135, 7, 'Yêu cầu thành phẩm: Bún gạo mềm tơi nhưng không nhão, thấm vị hài hòa, các rau củ quả chín tới, màu sắc tươi mới, không bị ra nước.', 10);
INSERT INTO public.recipe_steps VALUES (700, '2025-11-20 17:10:03.286146', '2025-11-20 17:10:03.286146', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 135, 6, 'Cuối cùng trút phần bún gạo đã xào vào trộn đều, nêm nếm lại gia vị cho vừa miệng, cho hành lá cắt khúc, rắc chút hạt tiêu và múc ra thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (701, '2025-11-20 17:10:03.288944', '2025-11-20 17:10:03.288944', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 135, 3, 'Bún gạo ngâm nước nóng 6-7 phút hoặc trụng sơ cho nở mềm. Vớt ra rửa lại cho ráo nước, trộn chút dầu ăn để không bị dính chùm và bóng mướt.', 10);
INSERT INTO public.recipe_steps VALUES (702, '2025-11-20 17:10:03.293266', '2025-11-20 17:10:03.293266', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 135, 2, 'Làm hỗn hợp nước sốt để xào bún chay gồm 2 muỗng canh nước tương, 1 muỗng canh đường, 1 muỗng canh nước hàng, 1 muỗng cà phê muối, 1 muỗng cà phê hạt nêm chay, 1 muỗng cà phê giấm và 1/2 chén nước. Khuấy đều cho tan.', 10);
INSERT INTO public.recipe_steps VALUES (703, '2025-11-20 17:10:03.55416', '2025-11-20 17:10:03.55416', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 136, 1, 'Cá nục làm sạch, ngâm nước muối loãng hoặc nước chè xanh (chè tươi) để khử tanh, rửa sạch, để ráo nước. Ướp cá với một thìa cà phê muối hạt cho cá đanh lại và đậm vị hơn.', 10);
INSERT INTO public.recipe_steps VALUES (704, '2025-11-20 17:10:03.557664', '2025-11-20 17:10:03.557664', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 136, 5, 'Phi thơm đầu hành trắng, cho nước dừa tươi vào nấu sôi (việc kho cá bắt buộc phải nước sôi thì mới không bị tanh). Lót phần vỏ hành khô dưới đáy nồi cho đỡ bén và thơm hơn. Lần lượt xếp cá nục và dứa, cà chua đan xen. Sau đó, thêm nước dừa vào xâm xấp bề mặt. Kho cá 2 lửa sẽ ngon đậm vị. Lần 1, bật bếp đun sôi lửa liu riu, nếm nếm gia vị cho vừa miệng. Kho cho tới khi nước cạn 1/3 thì tiếp tục chêm phần nước dừa còn lại vào kho tiếp lần hai. Thỉnh thoảng múc nước kho rưới đều lên để cá kho đều vị. Khi nước kho sền sệt thì rưới 1 - 2 thìa canh mỡ lợn để cá lên màu bóng đẹp.', 10);
INSERT INTO public.recipe_steps VALUES (705, '2025-11-20 17:10:03.561202', '2025-11-20 17:10:03.561202', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 136, 3, 'Dứa (thơm) gọt bỏ vỏ, cắt miếng vừa ăn. Cà chua rửa sạch, bổ múi cau. Hành lá rửa sạch, cắt khúc.', 10);
INSERT INTO public.recipe_steps VALUES (706, '2025-11-20 17:10:03.565897', '2025-11-20 17:10:03.565897', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 136, 6, 'Yêu cầu thành phẩm: Cá bên ngoài săn lại, bên trong thịt mềm đậm vị mặn ngọt, dứa chua chua ngọt ngọt thấm vị ngọt thơm của cá.', 10);
INSERT INTO public.recipe_steps VALUES (707, '2025-11-20 17:10:03.569871', '2025-11-20 17:10:03.569871', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 136, 2, 'Hành, tỏi, ớt giã nhuyễn (giữ lại phần vỏ hành khô rửa sạch để kho cá). Pha nước sốt hỗn hợp kho gồm: 3 thìa canh nước mắm ngon, 1 thìa cà phê muối, 1 thìa canh đường, 1 thìa canh nước màu, 1 thìa cà phê hạt nêm, 1 thìa cà phê hạt tiêu khuấy đều.', 10);
INSERT INTO public.recipe_steps VALUES (708, '2025-11-20 17:10:03.573652', '2025-11-20 17:10:03.573652', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 136, 4, 'Phi thơm phần hành, tỏi, ớt giã, cho cá vào chiên sơ để khử tanh, gắp ra. Đổ sốt hỗn hợp kho vào tiếp tục ướp cá trong 30 phút cho thấm vị.', 10);
INSERT INTO public.recipe_steps VALUES (709, '2025-11-20 17:10:03.753751', '2025-11-20 17:10:03.753751', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 137, 3, 'Cà chua rửa sạch, bổ múi cau. Hành lá rửa sạch, cắt khúc.', 10);
INSERT INTO public.recipe_steps VALUES (710, '2025-11-20 17:10:03.75677', '2025-11-20 17:10:03.75677', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 137, 8, 'Bún chần qua, cho vào tô chiết yêu, gắp ốc cho vào bát, thêm rau sống, gắp 1 - 2 miếng cà chua. Múc nước dùng nóng chan lên, thêm hành phi, ớt chưng và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (711, '2025-11-20 17:10:03.761539', '2025-11-20 17:10:03.761539', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 137, 7, 'Phi thơm hành khô với nhiều dầu ăn chút, cho ớt khô vào chưng ở lửa nhỏ, nêm 1/2 thìa muối (bột canh) cho đỡ nhạt vị. Tắt bếp, múc ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (712, '2025-11-20 17:10:03.766473', '2025-11-20 17:10:03.766473', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 137, 1, 'Ốc ngâm nước vo gạo thêm vài lát ớt tươi vừa giúp ốc thêm béo và nhả hết bùn đất. Thời gian ngâm tối thiểu 2 giờ.', 10);
INSERT INTO public.recipe_steps VALUES (713, '2025-11-20 17:10:03.770356', '2025-11-20 17:10:03.770356', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 137, 5, 'Phi thơm hành, cho cà chua vào xào để tạo màu hồng nhạt - màu đặc trưng của bún ốc.', 10);
INSERT INTO public.recipe_steps VALUES (714, '2025-11-20 17:10:03.773579', '2025-11-20 17:10:03.773579', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 137, 9, 'Yêu cầu thành phẩm: Ốc béo giòn ngon, nước dùng nóng hổi vị chua thanh nhẹ. Màu sắc bắt mắt, vị chua mặn ngọt hài hòa.', 10);
INSERT INTO public.recipe_steps VALUES (715, '2025-11-20 17:10:03.777595', '2025-11-20 17:10:03.777595', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 137, 2, 'Ốc rửa sạch, cho nước vào xâm xấp bề mặt, thêm 1/2 thìa canh muối, đun sôi. Khi nước sôi bùng chỉ một phút, ốc bong vảy là tắt bếp, đổ ra rổ cho ráo nước. Để ốc nguội bớt, chặt trôn (đít) và khều lấy phần thịt ốc và trứng nếu có, bỏ phần phân, tráng rửa lại bằng nước sôi. Nước ốc lọc lấy phần nước trong để làm nước dùng.', 10);
INSERT INTO public.recipe_steps VALUES (716, '2025-11-20 17:10:03.781055', '2025-11-20 17:10:03.781055', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 137, 4, 'Các loại rau sống rửa sạch, ngâm nước muối loãng, vẩy ráo nước, thái nhỏ để ăn kèm.', 10);
INSERT INTO public.recipe_steps VALUES (717, '2025-11-20 17:10:03.785914', '2025-11-20 17:10:03.785914', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 137, 6, 'Trút phần cà chua xào sơ vào nồi nước luộc ốc, thêm nước dùng tùy chọn nếu thích thêm vị ngọt (nước hầm từ xương hom lợn). Nêm nếm mắm, muối, hạt nêm vừa miệng. Cuối cùng mới cho giấm bỗng vào, điều chỉnh vị chua phù hợp. Nước dùng bún ốc nóng là sự hài hòa sắc và vị, màu hồng từ cà chua, vị chua thanh, mùi thơm từ dấm bỗng nếp rất hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (719, '2025-11-20 17:10:04.056594', '2025-11-20 17:10:04.056594', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 138, 4, 'Phi thơm vàng trước phần tỏi băm, vớt ra để rắc lên thành phẩm cuối tăng thêm phần bắt mắt và dậy mùi thơm. Tiếp tục phi phần tỏi đập dập còn lại, cho mồng tơi vào xào trên lửa lớn. Nêm một thìa cà phê muối, một thìa cà phê nước mắm, 1/2 thìa cà phê hạt nêm (điều chỉnh lại cho vừa miệng). Đảo đều cho mồng tơi thấm vị trong 1,5 - 2 phút. Tắt bếp, múc ra đĩa, rắc tỏi phi vàng ban đầu, ớt, chút hạt tiêu và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (720, '2025-11-20 17:10:04.059927', '2025-11-20 17:10:04.059927', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 138, 3, 'Đun sôi nồi nước (đủ ngập rau), thêm 1 thìa cà phê muối hạt. Khi nước sôi già, cho rau mồng tơi vào, nhấn chìm xuống. Khi nước sôi trở lại, nhanh tay vớt rau ra ngâm vào âu nước đá lạnh. Việc chần vừa giúp rau khi xào khô ráo, việc ngâm nước đá lạnh giúp hãm nhiệt nên rau xanh giòn. Vớt rau ra, bóp nhẹ cho ráo nước, tãi tơi ra.', 10);
INSERT INTO public.recipe_steps VALUES (721, '2025-11-20 17:10:04.062565', '2025-11-20 17:10:04.062565', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 138, 1, 'Mồng tơi nhặt lấy phần lá và đọt non, bỏ phần lá già và gốc cứng. Sau đó, rửa sạch mồng tơi, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (722, '2025-11-20 17:10:04.065258', '2025-11-20 17:10:04.065258', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 138, 5, 'Yêu cầu thành phẩm: Đĩa mồng tơi xào tỏi khô ráo, rau mồng tơi xanh giòn, dậy mùi thơm của tỏi kích thích vị giác. Món này ăn chơi hay cùng cơm đều ngon.', 10);
INSERT INTO public.recipe_steps VALUES (723, '2025-11-20 17:10:04.229707', '2025-11-20 17:10:04.229707', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 139, 4, 'Yêu cầu thành phẩm: Thịt thăn lợn mềm ngọt tự nhiên, dậy mùi thơm của hành, cộng thêm chút the cay từ hạt tiêu. Đây là món ăn quý từ xưa được ưu tiên trong thực đơn cho người ốm dậy, bà đẻ, người già.', 10);
INSERT INTO public.recipe_steps VALUES (724, '2025-11-20 17:10:04.232588', '2025-11-20 17:10:04.232588', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 139, 2, 'Thăn lợn rửa sạch, thấm khô, bỏ phần gân, thái mỏng to bản. Ướp thịt với 1 thìa canh nước mắm, 1/2 thìa cà phê muối, 1/2 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu, hành khô, đảo đều và ướp 15 - 20 phút cho thấm vị.', 10);
INSERT INTO public.recipe_steps VALUES (725, '2025-11-20 17:10:04.236542', '2025-11-20 17:10:04.236542', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 139, 1, 'Hành khô thái lát, hành lá rửa sạch, thái khúc (tùy chọn).', 10);
INSERT INTO public.recipe_steps VALUES (726, '2025-11-20 17:10:04.239056', '2025-11-20 17:10:04.239056', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 139, 3, 'Cho thịt vào đảo ở lửa vừa để không bén đáy. Khi thịt ra nước, đậy vung và rim cho chín bằng hơi. Nêm nếm lại gia vị cho vừa miệng. Sau 5-6 phút nước rút cạn bớt, thịt chín thì rắc thêm hạt tiêu, hành lá (tùy chọn). Tắt bếp, múc ra đĩa ăn nóng.', 10);
INSERT INTO public.recipe_steps VALUES (727, '2025-11-20 17:10:04.48551', '2025-11-20 17:10:04.48551', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 140, 1, 'Tàu hũ cắt miếng dài, cho vào chiên vàng đều các mặt, vớt ra cho vào giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (728, '2025-11-20 17:10:04.490403', '2025-11-20 17:10:04.490403', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 140, 4, 'Sau 4-5 phút cho hỗn hợp nước sốt rim vào đảo đều. Rồi khìa ở lửa vừa, thỉnh thoảng lật trở cho tàu hủ thấm đều vị. Khìa cho tới khi hỗn hợp nước sốt sánh sệt lại là được. Gắp tàu hủ ra đĩa và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (729, '2025-11-20 17:10:04.49762', '2025-11-20 17:10:04.49762', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 140, 5, 'Yêu cầu thành phẩm: Tàu hủ lên màu đẹp mắt, đậu bên ngoài dai dai, bên trong mềm mại, nước sốt sánh sệt hài hòa vị mặn ngọt đẩy đưa vị giác. Món này ăn cùng cơm nóng, rau luộc rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (730, '2025-11-20 17:10:04.504993', '2025-11-20 17:10:04.504993', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 140, 2, 'Hành, tỏi bóc bỏ vỏ; ớt bỏ hạt cho vào cối giã nhuyễn hoặc băm nhỏ. Pha hỗn hợp nước sốt để khìa tàu hủ gồm: 1,5 muỗng canh nước mắm, 1 muỗng canh tương cà, 1 muỗng canh tương ớt, 1/2 muỗng canh đường, 1/4 muỗng cà phê muối, 1/2 muỗng cà phê hạt nêm, 1/2 muỗng cà phê hạt tiêu và khuấy đều.', 10);
INSERT INTO public.recipe_steps VALUES (731, '2025-11-20 17:10:04.511106', '2025-11-20 17:10:04.511106', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 140, 3, 'Phi thơm hành tỏi, cho tàu hủ vào đảo đều cho thơm. Sau đó, trút nước dừa vào trước, đun sôi và rim cho ngấm vị ngọt tự nhiên. Sử dụng nước dừa tươi giúp cho tàu hủ khi khìa lên màu đẹp mắt và vị ngọt tự nhiên.', 10);
INSERT INTO public.recipe_steps VALUES (732, '2025-11-20 17:10:04.82086', '2025-11-20 17:10:04.82086', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 141, 3, 'Ướp thịt với một nửa riềng, sả cùng 2 thìa canh nước mắm, 1/2 thìa cà phê muối, 1 thìa cà phê hạt nêm, 1 thìa cà phê hạt tiêu đảo đều, để trong một giờ cho thấm vị.', 10);
INSERT INTO public.recipe_steps VALUES (733, '2025-11-20 17:10:04.823774', '2025-11-20 17:10:04.823774', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 141, 4, 'Phi thơm số riềng, sả còn lại. Trút thịt ba chỉ đã ướp vào xào săn cho thấm vị.', 10);
INSERT INTO public.recipe_steps VALUES (734, '2025-11-20 17:10:04.82775', '2025-11-20 17:10:04.82775', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 141, 1, 'Thịt ba chỉ nướng cháy cạnh, phần bì ngả màu vàng, thịt săn lại, mỡ chín tới để đỡ ngấy. Nướng bằng rơm hoặc than hoa là ngon nhất. Sau đó, rửa sạch, thái con chì hoặc thái chỉ vừa miệng.', 10);
INSERT INTO public.recipe_steps VALUES (735, '2025-11-20 17:10:04.830424', '2025-11-20 17:10:04.830424', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 141, 6, 'Yêu cầu thành phẩm: Thịt liền khối, đậm vị, phần nạc săn đỏ, phần bì vàng ươm sém cạnh, phần mỡ không quá ngậy, dậy mùi thơm của riềng, sả; nước sóng sánh chút ánh vàng... ăn cùng cơm trắng hoặc bún, thêm lá mơ tam thể, húng bạc hà thì mọi cao lương mĩ vị đều nhường chỗ.', 10);
INSERT INTO public.recipe_steps VALUES (736, '2025-11-20 17:10:04.834758', '2025-11-20 17:10:04.834758', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 141, 2, 'Riềng một nửa thái chỉ, một nửa giã nhỏ. Sả thái lát, ớt bỏ hạt thái lát.', 10);
INSERT INTO public.recipe_steps VALUES (737, '2025-11-20 17:10:04.837171', '2025-11-20 17:10:04.837171', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 141, 5, 'Đổ nước xâm xấp bề mặt thịt, hạ lửa nhỏ vừa đun cho tới khi nước sóng sánh, thịt săn lại, riềng sả quyện vào thơm lừng thì nêm nếm lại gia vị cho vừa miệng, tắt bếp, múc ra thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (738, '2025-11-20 17:10:05.1417', '2025-11-20 17:10:05.1417', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 142, 2, 'Làm bột ướt: Cho 1/2 gói bột chiên giòn vào bát tô, cho 1 quả trứng gà, 1/4 thìa cà phê muối, thêm 15 - 20 ml nước, dùng khuấy đều cho tới khi thành hỗn hợp bột sánh mịn, chảy nhẹ là đạt.', 10);
INSERT INTO public.recipe_steps VALUES (739, '2025-11-20 17:10:05.144216', '2025-11-20 17:10:05.144216', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 142, 3, 'Lấy 1/2 gói bột chiên xù cho vào chày giã sơ, sau đó cho vào trộn đều với 1/2 lượng bột chiên xù còn lại. Lấy từng con tôm nhúng qua bột ướt, rồi lăn bột chiên xù bao đều các mặt. Làm lần lượt cho tới hết.', 10);
INSERT INTO public.recipe_steps VALUES (4134, '2025-11-20 17:12:03.037315', '2025-11-20 17:12:03.037315', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 643, 5, 'Rây hỗ hợp: Bột cake flour và bột nở vào một bát riêng.', 10);
INSERT INTO public.recipe_steps VALUES (740, '2025-11-20 17:10:05.146737', '2025-11-20 17:10:05.146737', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 142, 5, 'Làm sốt me: Me khô cho ra bát, thêm nước đun sôi dằm tan, lọc lấy nước cốt, bỏ hạt. Phi thơm tỏi, cho nước cốt me, đường, nước lọc, tương cà, tương ớt, mắm theo công thức: 60 gr nước cốt me, 60 gr đường, 60 gr nước lọc, 20 gr tương cà, 20 gr tương ớt, nêm nếm lại cho vừa vị khuấy tan. Nấu trên lửa nhỏ tới khi sền sệt thì tắt bếp, múc ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (741, '2025-11-20 17:10:05.148432', '2025-11-20 17:10:05.148432', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 142, 4, 'Đun nóng dầu ăn, thử đầu đũa thấy sủi tăm là đạt độ nóng. Chia tôm thành các mẻ cho vào chiên vàng giòn đều các mặt ở lửa vừa. Khi đã đạt thì tăng lửa lớn chút cho thoát dầu, vớt tôm ra cho vào giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (742, '2025-11-20 17:10:05.150639', '2025-11-20 17:10:05.150639', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 142, 1, 'Tôm bóc vỏ, rút chỉ đen ở lưng, chừa phần đuôi để khi chiên giữ hình dáng tôm cho đẹp. Ướp tôm với 1 thìa cà phê nước cốt tỏi (tỏi giã nhuyễn vắt nước cốt, hoặc dùng bột tỏi), 1/4 thìa cà phê bột canh (muối), 1/2 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt nêm cho thấm vị.', 10);
INSERT INTO public.recipe_steps VALUES (743, '2025-11-20 17:10:05.153829', '2025-11-20 17:10:05.153829', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 142, 6, 'Trình bày tôm ra đĩa, khi ăn rưới đều nước sốt me lên đều các mặt để giữ độ giòn của tôm.', 10);
INSERT INTO public.recipe_steps VALUES (744, '2025-11-20 17:10:05.311897', '2025-11-20 17:10:05.311897', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 143, 3, 'Sả thái lát, gừng thái sợi, ớt thái lát, lá chanh thái chỉ. Vừng rang thơm. Pha tương bần với chút gừng đập dập, nêm nếm đường, nước cốt chanh cho vừa vị để chấm kèm bê tái chanh.', 10);
INSERT INTO public.recipe_steps VALUES (745, '2025-11-20 17:10:05.315118', '2025-11-20 17:10:05.315118', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 143, 2, 'Dứa gọt vỏ, thái lát mỏng. Chuối xanh lột bỏ vỏ, xắt lát mỏng ngâm vào nước muối và vắt 1 quả chanh để không bị thâm đen.', 10);
INSERT INTO public.recipe_steps VALUES (746, '2025-11-20 17:10:05.317251', '2025-11-20 17:10:05.317251', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 143, 6, 'Yêu cầu thành phẩm: Thịt bê mềm ngọt tự nhiên, bì giòn, dậy mùi thơm của sả, chút the cay của ớt, vị chua cay mặn ngọt hài hòa. Cuốn bánh tráng ăn cùng khế chua, chuối xanh, dứa chấm sốt gừng tương bần rất ngon. Món này ăn chơi, ăn tiệc đều hấp dẫn, nhất là trong tiết trời nóng nực.', 10);
INSERT INTO public.recipe_steps VALUES (747, '2025-11-20 17:10:05.319303', '2025-11-20 17:10:05.319303', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 143, 1, 'Thịt bê ướp với 1/2 thìa cà phê bột canh (muối), 1/2 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu tối thiểu trong 30 phút. Sau đó, cho vào nồi hấp khoảng 15 phút cho thịt bê chín tái.', 10);
INSERT INTO public.recipe_steps VALUES (748, '2025-11-20 17:10:05.321961', '2025-11-20 17:10:05.321961', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 143, 4, 'Thịt bê sau khi hấp, để nguội thì thái lát mỏng có cả bì kèm theo. Chú ý thịt bê chín tái còn hơi hồng là giữ vị ngọt vì sau đó cho nước cốt chanh vào sẽ chín tái.', 10);
INSERT INTO public.recipe_steps VALUES (749, '2025-11-20 17:10:05.323557', '2025-11-20 17:10:05.323557', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 143, 5, 'Cho thịt bê vào tô, thêm 1/2 thìa cà phê bột canh (muối), 1/2 thìa canh đường, 1 thìa canh nước cốt chanh, cho sả, ớt, lá chanh đảo đều cho thấm vị. Điều chỉnh lại vị chua cay mặn ngọt theo khẩu vị cá nhân. Cuối cùng rắc thêm vừng rang và trình bày ra đĩa thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (750, '2025-11-20 17:10:05.62276', '2025-11-20 17:10:05.62276', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 144, 1, 'Thịt bò thái mỏng thớ ngang, ướp với một muỗng canh dầu hào, một thìa cà phê dầu ăn, 1/2 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu cùng chút tỏi, gừng. Ướp thịt trong 15 phút cho thấm vị.', 10);
INSERT INTO public.recipe_steps VALUES (751, '2025-11-20 17:10:05.625422', '2025-11-20 17:10:05.625422', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 144, 4, 'Nên chọn mì rời (mì ký) để không bị mặn. Trụng mì qua nước sôi rồi xả nước lạnh cho sợi tơi ra.', 10);
INSERT INTO public.recipe_steps VALUES (752, '2025-11-20 17:10:05.627553', '2025-11-20 17:10:05.627553', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 144, 2, 'Rau cải, cần tây, tỏi tây rửa sạch thái khúc. Cà rốt tỉa hoa hoặc thái sợi dài, thái chân hương tùy chọn. Hành tây thái múi cau.', 10);
INSERT INTO public.recipe_steps VALUES (753, '2025-11-20 17:10:05.630448', '2025-11-20 17:10:05.630448', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 144, 5, 'Phi thơm 1/2 lượng tỏi băm, cho thịt bò vào xào trên lửa lớn, đảo đều tay. Khi thịt bò chín khoảng 70 - 80% hơi tái thì trút ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (754, '2025-11-20 17:10:05.633152', '2025-11-20 17:10:05.633152', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 144, 6, 'Cho mì vào chảo vừa xào bò, hạ lửa nhỏ, múc 1/2 lượng nước sốt vào chảo đảo cho gia vị bám đều vào sợi mì rồi múc ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (755, '2025-11-20 17:10:05.635281', '2025-11-20 17:10:05.635281', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 144, 9, 'Yêu cầu thành phẩm: Mì sợi mềm dai mà vẫn tơi, không bị dính chùm; thịt bò mềm ngọt tự nhiên; các loại rau củ quả giữ màu xanh mướt, giòn ngon, vị hài hòa hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (756, '2025-11-20 17:10:05.637436', '2025-11-20 17:10:05.637436', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 144, 3, 'Pha hỗn hợp nước sốt gồm: 1 muỗng canh dầu hào, 1 muỗng canh nước tương, 1 muỗng canh tương ớt, 1/2 muỗng canh đường, 1/2 muỗng cà phê hạt tiêu, 1/2 muỗng cà phê hạt nêm, 6 - 7 muỗng canh nước lọc. Tất cả khuấy tan thành hỗn hợp sốt xào mì.', 10);
INSERT INTO public.recipe_steps VALUES (757, '2025-11-20 17:10:05.640115', '2025-11-20 17:10:05.640115', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 144, 7, 'Phi thơm 1/2 lượng tỏi còn lại, cho lần lượt từng loại rau vào xào trên lửa lớn tùy thuộc độ chín (đầu tiên là cà rốt, tiếp đến rau cải, hành tây, cần tây, tỏi tây) và trút 1/2 lượng nước sốt còn lại đảo đều.', 10);
INSERT INTO public.recipe_steps VALUES (758, '2025-11-20 17:10:05.642245', '2025-11-20 17:10:05.642245', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 144, 8, 'Trút thịt bò, mì vào đảo nhanh cùng rau củ quả, nêm nếm lại gia vị cho vừa miệng. Thêm hành lá, rắc chút hạt tiêu, tắt bếp và múc ra thưởng thức. Trang trí bằng vài lát ớt, rau mùi lên trên tăng phần bắt mắt.', 10);
INSERT INTO public.recipe_steps VALUES (759, '2025-11-20 17:10:05.769123', '2025-11-20 17:10:05.769123', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 145, 1, 'Cá rô đồng làm sạch ruột, cạo màng đen trong bụng, để nguyên hoặc cạo vảy tùy theo sở thích, xóc chút muối, rượu trắng vừa khử mùi, tẩy chất nhớt vừa giúp cá đậm vị hơn. Sau đó, rửa sạch, thấm khô hoặc để ráo nước hoàn toàn.', 10);
INSERT INTO public.recipe_steps VALUES (760, '2025-11-20 17:10:05.771248', '2025-11-20 17:10:05.771248', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 145, 4, 'Yêu cầu thành phẩm: Cá rô đồng bên ngoài giòn rụm vàng ngậy, bên trong thịt ngọt mềm. Tùy theo khẩu vị mỗi nơi mà có cách làm nước chấm khác nhau, tựu trung đều rất ngon và đưa cơm. Đơn giản nhất là chấm nước mắm nhĩ dằm vài quả ớt hiểm, cầu kỳ hơn thì giã nát gừng tỏi ớt rồi thêm mắm, đường làm mắm gừng hoặc chấm với nước mắm ngâm sấu ớt, tỏi theo cách người Hà Nội.', 10);
INSERT INTO public.recipe_steps VALUES (761, '2025-11-20 17:10:05.773356', '2025-11-20 17:10:05.773356', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 145, 2, 'Dùng mỡ lợn chiên cá rô đồng ngon hơn. Chú ý kỹ thuật canh nhiệt để không bị dính chảo. Ban đầu bật bếp lửa nhỏ vừa, đun cho chảo nóng dần và lan đều nhiệt. Sau đó, cho mỡ đủ ngập cá và tăng lửa vừa. Chờ vài phút và thử bằng cách dùng đầu đũa cho vào, thấy sủi tăm là đạt độ nóng. Nếu không có chảo chống dính thì xát chút gừng trước khi cho mỡ vào để khi chiên cá không bị bén dính.', 10);
INSERT INTO public.recipe_steps VALUES (762, '2025-11-20 17:10:05.776018', '2025-11-20 17:10:05.776018', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 145, 3, 'Chia cá rô đồng thành từng mẻ (nếu chảo nhỏ), xếp cá giãn ra để tránh dính vào nhau nhằm đảm bảo nhiệt nóng ổn định. Khi cho cá vào, cần giữ nguyên để một mặt cá vàng giòn. Sau đó, mới trở lật, chiên mặt còn lại. Khi cá vàng giòn đều hai mặt, thơm lừng thì vớt ra để giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (763, '2025-11-20 17:10:06.000939', '2025-11-20 17:10:06.000939', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 146, 2, 'Làm nước táu chim. Đây là bí kíp trong các trường dạy nghề nấu ăn chỉ dẫn giúp cho món chiên, quay, rán tăng mùi thơm, màu sắc và làm chín một phần thực phẩm. Cách làm: Rang thơm 1 thanh quế nhỏ, 1 quả thảo quả, 2 - 3 cánh hoa hồi rồi cho vào nồi nước sôi 1 lít. Nêm thêm 1 thìa cà phê ngũ vị hương, 2 thìa cà phê muối, 1 thìa cà phê đường, 1 thìa cà phê rượu trắng, 1 thìa cà phê hắc xì dầu, 1/2 củ hành tây, 1 nhánh gừng nhỏ, hạt tiêu, ớt khô. Đun sôi nước táu, cho chim cút vào, hạ lửa nhỏ và táu chim trong 10 - 12 phút tùy kích thước của chim, tắt bếp, vớt chim ra để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (764, '2025-11-20 17:10:06.00412', '2025-11-20 17:10:06.00412', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 146, 4, 'Chiên chim cút ngập dầu trên lửa vừa. Thỉnh thoảng dùng muôi múc xối mỡ lên đều các bề mặt giúp da chim cút giòn bóng. Sau khi chim vàng ươm, vớt ra để giấy thấm dầu. Tiếp tục cho số bơ còn lại ( 4 thìa canh) vào chảo đun chảy, trút chim cút vào xóc bám đều các mặt là hoàn thành.', 10);
INSERT INTO public.recipe_steps VALUES (765, '2025-11-20 17:10:06.006763', '2025-11-20 17:10:06.006763', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 146, 1, 'Chim cút sơ chế sạch lông, bỏ ruột, rửa sạch để ráo nước. Cắt đôi hoặc để nguyên con tùy chọn', 10);
INSERT INTO public.recipe_steps VALUES (766, '2025-11-20 17:10:06.008996', '2025-11-20 17:10:06.008996', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 146, 3, 'Hành, tỏi giã nhuyễn vắt lấy nước cốt. Pha hỗn hợp nước sốt: 2 thìa canh bơ đun chảy, nước cốt hành tỏi, 1 thìa canh dầu hào, 1 thìa canh dầu màu điều, 1/2 thìa canh đường (điều chỉnh theo khẩu vị), 2/3 thìa cà phê mật ong, 1 thìa cà phê hạt tiêu, 1 thìa cà phê ngũ vị hương, 1 thìa cà phê tương ớt trộn đều. Khi chim cút khô ráo, nguội thì đeo găng tay thoa đều hỗn hợp nước sốt này lên các mặt chim cút. Để ướp tối thiểu 30 phút cho thấm vị. Nếu có thời gian bọc màng bọc thực phẩm để ngăn mát tủ lạnh 3- 4 giờ sẽ ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (767, '2025-11-20 17:10:06.012574', '2025-11-20 17:10:06.012574', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 146, 5, 'Yêu cầu thành phẩm: Lớp da bên ngoài chim cút giòn bóng, màu lên nâu óng ả đẹp mắt, thịt bên trong thấm vị, mềm ngọt, dậy mùi thơm của bơ.', 10);
INSERT INTO public.recipe_steps VALUES (768, '2025-11-20 17:10:06.209555', '2025-11-20 17:10:06.209555', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 147, 7, 'Miến dong rửa sạch, cắt khúc vừa ăn, cho vào trụng nước sôi cho mềm, vớt ra chia vào các bát tô theo khẩu phần ăn.', 10);
INSERT INTO public.recipe_steps VALUES (769, '2025-11-20 17:10:06.212219', '2025-11-20 17:10:06.212219', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 147, 9, 'Yêu cầu thành phẩm: Thịt vịt mềm ngọt, nước dùng hài hòa vị, măng tươi giòn sần sần sật, miến trong dai, khi ăn chấm cùng nước mắm gừng ớt rất hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (770, '2025-11-20 17:10:06.214345', '2025-11-20 17:10:06.214345', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 147, 5, 'Phi thơm hành, tỏi cho măng vào xào. Múc nước mỡ váng khi luộc vịt cho vào xào ngấm vào măng rất ngon. Cho mộc nhĩ, nấm hương vào xào cùng. Nêm nếm chút mắm, muối, hạt nêm cho vừa vị.', 10);
INSERT INTO public.recipe_steps VALUES (771, '2025-11-20 17:10:06.218139', '2025-11-20 17:10:06.218139', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 147, 6, 'Trút phần măng và mộc nhĩ, nấm hương đã xào vào nồi nước dùng (nước luộc vịt), đun sôi, nêm nếm lại gia vị mắm, muối, hạt nêm cho vừa vị. Thêm hành lá, mùi tàu đảo đều, tắt bếp là có nồi nước dùng măng thơm ngon.', 10);
INSERT INTO public.recipe_steps VALUES (772, '2025-11-20 17:10:06.220816', '2025-11-20 17:10:06.220816', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 147, 4, 'Mộc nhĩ, nấm hương ngâm nước ấm, rửa sạch. Mộc nhĩ thái sợi dài, nấm hương khứa hình chữ thập cho đẹp mắt. Hành lá rửa sạch, thái khúc. Hành củ, tỏi băm nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (773, '2025-11-20 17:10:06.223837', '2025-11-20 17:10:06.223837', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 147, 1, 'Măng tươi bóc vỏ già, phần củ thái lát mỏng, phần đầu ngọn thái dài.', 10);
INSERT INTO public.recipe_steps VALUES (774, '2025-11-20 17:10:06.227061', '2025-11-20 17:10:06.227061', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 147, 2, 'Để khử đắng và độc tố thì luộc măng 2 - 3 lần, thêm chút muối hạt và mở vung khi luộc. Sau đó rửa sạch, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (775, '2025-11-20 17:10:06.230355', '2025-11-20 17:10:06.230355', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 147, 3, 'Vịt làm sạch, nhổ hết lông tơ, cắt bỏ phao câu (tuyến nhờn gây hôi). Chà xát chanh, muối hạt cùng rượu và chút gừng đập dập để khử mùi, rửa sạch. Cho lượng nước đủ ngập vịt, đun sôi lăn tăn thì cho vịt, vài lát gừng, 2 củ hành khô, 1 thìa cà phê muối hạt vào luộc. Thỉnh thoảng hớt bỏ bọt. Sau 20 phút tắt bếp, đậy vung ngâm thêm 10 phút cho vịt mềm ngọt, không bị đỏ xương. Tắt bếp, vớt ra để nguội, lọc thái miếng hoặc chặt miếng vừa ăn. Phần tiết, lòng cũng thái miếng vừa ăn để riêng. Phần nước dùng thì vớt bỏ hành, gừng.', 10);
INSERT INTO public.recipe_steps VALUES (776, '2025-11-20 17:10:06.233059', '2025-11-20 17:10:06.233059', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 147, 8, 'Các loại rau sống rửa sạch. Cho miến vào từng bát, gắp thịt vịt, lòng vịt để lên trên. Gắp măng, mộc nhĩ, nấm hương cho vào. Múc nước dùng nóng chan ngập bát miến.', 10);
INSERT INTO public.recipe_steps VALUES (777, '2025-11-20 17:10:06.396574', '2025-11-20 17:10:06.396574', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 148, 3, 'Pha hỗn hợp nước sốt gồm mắm: đường: chanh: nước tỷ lệ 1:1:1:2 (1,5 thìa canh nước mắm 30 độ đạm, 1,5 thìa canh đường, 1,5 thìa canh nước cốt chanh: 3 thìa canh nước lọc), khuấy đều cho tan đường hoàn toàn rồi cho tỏi, ớt băm nhuyễn vào.', 10);
INSERT INTO public.recipe_steps VALUES (778, '2025-11-20 17:10:06.399308', '2025-11-20 17:10:06.399308', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 148, 2, 'Bưởi gọt bỏ vỏ, bóc múi, tách thành miếng vừa ăn. Tôm luộc, bóc bỏ vỏ. Dưa chuột bỏ ruột, thái sợi. Cà rốt gọt bỏ vỏ, bào sợi.', 10);
INSERT INTO public.recipe_steps VALUES (4593, '2025-11-20 17:12:20.873549', '2025-11-20 17:12:20.873549', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 709, 17, 'Khi trà khô, để nguội và cất vào hộp dùng dần.', 10);
INSERT INTO public.recipe_steps VALUES (779, '2025-11-20 17:10:06.401428', '2025-11-20 17:10:06.401428', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 148, 4, 'Trộn gỏi theo quy tắc hai lần giúp cho vừa vị, nguyên liệu khô ráo. Lần 1: Cho bưởi, mực khô, tôm, dưa chuột, cà rốt cùng 1/2 nước sốt gỏi vào trộn đều trong 5 - 6 phút, chắt bỏ nước đi. Lần 2: Tiếp tục cho 1/2 nước sốt còn lại vào đảo đều cho thấm vị chua cay mặn ngọt hài hòa. Sau đó, chắt bỏ nước nộm cho khô ráo. Cuối cùng cho rau thơm, đậu phộng giã dập. Trình bày nộm vào vỏ bưởi cho bắt mắt, cho chút lạc rang lên trên.', 10);
INSERT INTO public.recipe_steps VALUES (780, '2025-11-20 17:10:06.405136', '2025-11-20 17:10:06.405136', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 148, 1, 'Mực khô ngâm chút bia cho mềm và khử mùi. Nướng mực chín thơm, dùng chày dập nhẹ, rồi xé sợi nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (781, '2025-11-20 17:10:06.408513', '2025-11-20 17:10:06.408513', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 148, 5, 'Yêu cầu thành phẩm: Món ăn là sự hài hòa sắc và vị với bưởi hồng mọng nước, vị chua the kết hợp mực ngọt thơm, đậu phộng giòn bùi chiếm trọn cảm tình trong thực đơn đãi tiệc ngày hè. Món này ăn chơi cùng phồng tôm hay ăn cùng cơm trắng đều rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (782, '2025-11-20 17:10:06.641082', '2025-11-20 17:10:06.641082', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 149, 4, 'Làm mọc viên: Mộc nhĩ và nấm hương ngâm nở, rửa sạch, vắt kiệt nước, thái nhỏ. Miến ngâm nở, hành khô và đầu hành lá cùng thái nhỏ. Trộn đều thịt nạc vai xay cùng giò sống, mộc nhĩ, nấm hương, miến, hành khô, thêm 1 thìa cà phê hạt nêm, 1 thìa cà phê hạt tiêu trộn đều cho tới khi thành hỗn hợp dẻo. Xoa chút dầu ăn vào găng tay, viên tròn thành những viên nhỏ vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (783, '2025-11-20 17:10:06.643767', '2025-11-20 17:10:06.643767', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 149, 1, 'Móng giò cạo sạch. Thịt chân giò lọc xương bó tròn. Đun sôi nước cùng một thìa cà phê muối, nhánh gừng đập dập rồi cho móng giò, sườn, thịt chân giò chần sơ loại bỏ tạp chất, vớt ra rửa sạch, thấm khô. Nghệ tươi giã nhỏ, vắt lấy nước cốt rồi ướp thịt chân giò, móng giò, sườn. Thêm 1 thìa cà phê muối, 1 thìa cà phê nước mắm, 1/2 thìa cà phê hạt nêm đảo đều, ướp trong 30 phút cho thấm gia vị và lên màu đẹp.', 10);
INSERT INTO public.recipe_steps VALUES (784, '2025-11-20 17:10:06.646863', '2025-11-20 17:10:06.646863', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 149, 6, 'Dọc mùng tước vỏ, cắt xéo ngâm qua nước muối đặc cho dọc mùng xẹp xuống.Vớt dọc mùng ra, tiếp tục thêm 1 thìa canh muối hạt bóp đều, vắt kiệt nước, rửa 3 - 4 lần cho sạch nước. Đun sôi nước, cho dọc mùng vào chần sơ, vớt ra vắt ráo nước. Khi nào ăn thì trụng qua nồi nước dùng cho vào bát bún.', 10);
INSERT INTO public.recipe_steps VALUES (785, '2025-11-20 17:10:06.650041', '2025-11-20 17:10:06.650041', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 149, 3, 'Sau 35-40 phút dùng xiên tre xiên qua được chân giò và móng giò thì đã chín, vớt ra ngâm nước đá lạnh cho giòn. Thấm khô nước và thái chân giò thành lát mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (786, '2025-11-20 17:10:06.652715', '2025-11-20 17:10:06.652715', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 149, 5, 'Đun sôi nồi nước dùng (nước hầm sườn, luộc chân giò, móng giò lúc đầu), thả mọc vào. Khi mọc nổi lên là đã chín, vớt ra để riêng. Phần nước dùng thì thêm cà chua thái múi cau, nêm nếm lại gia vị vừa miệng.', 10);
INSERT INTO public.recipe_steps VALUES (787, '2025-11-20 17:10:06.655316', '2025-11-20 17:10:06.655316', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 149, 9, 'Yêu cầu thành phẩm: Dọc mùng giòn, thịt chân giò mềm, móng giò sần sật, mọc mềm ngọt, nước dùng vàng nhẹ, vị hài hòa kích thích vị giác.', 10);
INSERT INTO public.recipe_steps VALUES (788, '2025-11-20 17:10:06.657979', '2025-11-20 17:10:06.657979', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 149, 2, 'Đun sôi nồi nước dùng khoảng 3 lít, cho thịt chân giò, móng giò và sườn vào luộc. Thêm 1 củ hành tây, 1 thìa cà phê muối tinh vào. Chú ý mở vung, để lửa nhỏ, thỉnh thoảng hớt bọt cho nước trong.', 10);
INSERT INTO public.recipe_steps VALUES (789, '2025-11-20 17:10:06.660122', '2025-11-20 17:10:06.660122', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 149, 8, 'Chần nóng bún xếp vào tô, thêm mọc, sườn, móng giò, thịt chân giò thái mỏng, dọc mùng trụng qua nồi nước dùng. Múc nước dùng thật nóng chan lên, rắc hành mùi lên trên và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (790, '2025-11-20 17:10:06.662713', '2025-11-20 17:10:06.662713', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 149, 7, 'Đun sôi nước, cho sấu cạo vỏ vào dầm nát, lọc lấy nước chua, nêm từ từ vào nồi nước dùng cho vừa vị. Nếu không có sấu thì thay thế bằng me hoặc mẻ.', 10);
INSERT INTO public.recipe_steps VALUES (791, '2025-11-20 17:10:06.797477', '2025-11-20 17:10:06.797477', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 150, 1, 'Thịt ba chỉ cạo sạch lông, dùng muối hạt hoặc chanh chà xát, rửa sạch, thấm khô. Phần hành khô, tỏi giã nhuyễn, vắt lấy nước cốt. Các loại rau sống rửa sạch, vẩy ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (792, '2025-11-20 17:10:06.800149', '2025-11-20 17:10:06.800149', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 150, 4, 'Vớt thịt ra để giấy thấm dầu. Chờ thịt nguội chút, dùng dao sắc thái mỏng và trình bày lên đĩa. Món này ăn kèm rau sống rất ''''hao cơm''''. Đây là món ăn dân dã, gắn liền với tuổi thơ của nhiều người dân miền Bắc.', 10);
INSERT INTO public.recipe_steps VALUES (793, '2025-11-20 17:10:06.802298', '2025-11-20 17:10:06.802298', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 150, 2, 'Ướp thịt với 1 thìa cà phê húng lìu, 1/2 thìa cà phê muối tinh, 1,5 thìa cà phê đường, 1 thìa cà phê hạt nêm, 1 thìa cà phê hạt tiêu xay, nước cốt hành, tỏi, 1 thìa canh dầu màu điều. Đeo găng tay thoa đều các mặt rồi dùng bọc màng bọc thực phẩm để trong ngăn mát tủ lạnh, ướp tối thiểu trong 1 giờ cho thấm vị.', 10);
INSERT INTO public.recipe_steps VALUES (794, '2025-11-20 17:10:06.806342', '2025-11-20 17:10:06.806342', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 150, 3, 'Có 2 cách làm thịt chiên. Cách 1: Đun nóng lượng dầu ăn vừa đủ, cho thịt vào rán ở lửa nhỏ vừa. Thỉnh thoảng trở đều các mặt cho vàng đều. Cách 2: Để rút ngắn thời gian thì cho thịt vào hấp trước 20 phút cho chín. Sau đó để nguội, để ráo nước và cho vào chiên vàng là được.', 10);
INSERT INTO public.recipe_steps VALUES (795, '2025-11-20 17:10:06.912976', '2025-11-20 17:10:06.912976', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 151, 1, 'Để có món xào ngon, người nội trợ nên chọn hoa thiên lý còn e ấp nụ sẽ giữ mùi thơm và ngon ngọt vừa độ, nhặt bỏ cuống già, rửa sạch và để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (796, '2025-11-20 17:10:06.916345', '2025-11-20 17:10:06.916345', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 151, 4, 'Tiếp tục phi thơm 1/2 lượng tỏi băm còn lại, cho hoa thiên lý vào xào. Cho 1/2 thìa cà phê bột canh (muối), 1/2 thìa cà phê hạt nêm. Vì hoa thiên lý nhanh chín nên chỉ xào qua rồi trút thịt bò vào đảo đều trên lửa lớn. Lúc này thịt bò và rau thiên lý chín tới, ngấm đều gia vị. Thêm chút hạt tiêu, ớt cay (tùy chọn), tắt bếp và múc ra thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1404, '2025-11-20 17:10:19.988976', '2025-11-20 17:10:19.988976', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 243, 1, 'Tán nhuyễn thịt cá, cho mỡ vào cá trộn đều rồi nêm chút muối, tiêu, hành bằm nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (798, '2025-11-20 17:10:06.923308', '2025-11-20 17:10:06.923308', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 151, 2, 'Thịt bò thái mỏng thớ ngang, ướp với 1 muỗng canh dầu hào, 1 muỗng cà phê nước mắm, 1/2 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu. Ướp trong 15 phút cho ngấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (799, '2025-11-20 17:10:06.927396', '2025-11-20 17:10:06.927396', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 151, 5, 'Yêu cầu thành phẩm: Thịt bò mềm ngọt, hoa thiên lý giữ màu xanh tươi, giòn ngon hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (800, '2025-11-20 17:10:07.054944', '2025-11-20 17:10:07.054944', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 152, 1, 'Thịt ba chỉ cắt miếng vừa ăn, chần sơ với nước sôi để loại bỏ tạp chất, rửa sạch. Ướp thịt với 1/2 thìa canh đường trước 15 phút để khi kho phần mỡ được trong. Sau đó, tiếp tục ướp thịt với 2 thìa canh nước mắm, 1 thìa cà phê muối, 1 thìa cà phê hạt nêm, 1 thìa cà phê hạt tiêu cùng đầu hành trắng.', 10);
INSERT INTO public.recipe_steps VALUES (801, '2025-11-20 17:10:07.057082', '2025-11-20 17:10:07.057082', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 152, 3, 'Hành tỏi giã nhỏ, hành lá rửa sạch cắt khúc, ớt cắt lát.', 10);
INSERT INTO public.recipe_steps VALUES (802, '2025-11-20 17:10:07.060281', '2025-11-20 17:10:07.060281', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 152, 5, 'Khi thịt săn lại thì cho nước dừa tươi vào xâm xấp, nước sôi hạ lửa nhỏ liu riu kho. Nêm nếm lại gia vị cho phù hợp. Mở vung nồi, dùng lá chuối hoặc lá mít đậy lên (vừa giúp thịt, trứng trên bề mặt không bị khô). Khi nước kho hơi sánh sệt thì đảo đều, rắc hành lá, hạt tiêu, ớt đảo đều, tắt bếp và múc ra thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (803, '2025-11-20 17:10:07.063117', '2025-11-20 17:10:07.063117', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 152, 6, 'Yêu cầu thành phẩm: Thịt lên màu hổ phách đẹp mắt, trứng cút thấm vị, bùi bùi, nước kho sóng sánh chấm cùng rau củ quả luộc rất ''''hao cơm''''.', 10);
INSERT INTO public.recipe_steps VALUES (804, '2025-11-20 17:10:07.065357', '2025-11-20 17:10:07.065357', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 152, 4, 'Cho 2 thìa canh đường vào chảo thắng nước màu (nước hàng) trên lửa nhỏ vừa. Khi đường chuyển màu cánh gián thì cho hành tỏi, trút thịt vào đảo để dậy mùi thơm và nước hàng bám đều các mặt.', 10);
INSERT INTO public.recipe_steps VALUES (805, '2025-11-20 17:10:07.068041', '2025-11-20 17:10:07.068041', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 152, 2, 'Trứng cút luộc với một muỗng cà phê muối trong 5-6 phút, vớt ra ngâm nước lạnh. Sau đó, cho trứng vào cái hộp, đậy nắp và lắc mạnh tay cho vỏ dập sơ, giúp việc bóc vỏ nhanh hơn.', 10);
INSERT INTO public.recipe_steps VALUES (806, '2025-11-20 17:10:07.228429', '2025-11-20 17:10:07.228429', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 153, 7, 'Cho thịt vào xào xém cạnh. Khi thịt tiết ra mỡ thì cho tỏi vào phi thơm, trút mực, tôm và lần lượt mộc nhĩ, cà rốt, ớt chuông xanh, đỏ vào xào chín tới. Cho lượng nước sốt còn lại vào đảo đều. Sau đó, cho miến cùng trứng thái sợi vào trộn đều, nêm nếm lại gia vị, rắc chút hạt tiêu và tắt bếp múc ra thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (807, '2025-11-20 17:10:07.231156', '2025-11-20 17:10:07.231156', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 153, 8, 'Yêu cầu thành phẩm: Miến sợi mềm tơi, không bị dính chùm, hải sản khô ráo nước, rau củ quả chín tới giòn ngọt, vị hài hòa rất hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (808, '2025-11-20 17:10:07.233857', '2025-11-20 17:10:07.233857', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 153, 2, 'Ớt chuông xanh, ớt chuông đỏ, hành tây, cà rốt thái sợi. Mộc nhĩ ngâm nở, rửa sạch, thái sợi. Hành lá, rau mùi rửa sạch, cắt khúc. Tùy theo sở thích thay đổi rau củ quả phù hợp theo mùa.', 10);
INSERT INTO public.recipe_steps VALUES (809, '2025-11-20 17:10:07.236524', '2025-11-20 17:10:07.236524', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 153, 3, 'Mực làm sạch, khía chéo, chần qua nước sôi, vớt ra để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (810, '2025-11-20 17:10:07.238634', '2025-11-20 17:10:07.238634', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 153, 1, 'Miến cắt ngắn, ngâm nước ấm 60-70 độ khoảng 10 phút cho sợi miến mềm và nở là được, vớt ra để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (811, '2025-11-20 17:10:07.240796', '2025-11-20 17:10:07.240796', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 153, 4, 'Tôm luộc chín, bóc bỏ vỏ. Để tôm thơm hơn thì cho chút rượu trắng khi luộc.', 10);
INSERT INTO public.recipe_steps VALUES (812, '2025-11-20 17:10:07.243487', '2025-11-20 17:10:07.243487', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 153, 5, 'Trứng gà đánh tan cùng chút gia vị mắm, muối, hạt nêm rồi tráng mỏng, cắt sợi dài. Pha nước sốt xào gồm 2 thìa canh dầu hào, 2 thìa canh nước tương, 1 thìa canh đường, 1 thìa cà phê hạt nêm, 1 thìa cà phê hạt tiêu khuấy đều.', 10);
INSERT INTO public.recipe_steps VALUES (813, '2025-11-20 17:10:07.245714', '2025-11-20 17:10:07.245714', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 153, 6, 'Phi thơm 1/2 lượng hành khô, tỏi băm. Hạ lửa nhỏ, cho 1/2 lượng nước sốt vào chảo đảo đều, thêm khoảng 1/2 bát nước lạnh vào. Cho miến vào, đảo đều trên lửa nhỏ nhất cho gia vị quyện đều vào sợi miến. Khi sợi miến chuyển màu trong thì tắt bếp, múc ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (814, '2025-11-20 17:10:07.34776', '2025-11-20 17:10:07.34776', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 154, 3, 'Hành lá, rau mùi rửa sạch, thái khúc. Tùy theo vùng miền và sở thích có thể cho hoặc không cho rau thơm.', 10);
INSERT INTO public.recipe_steps VALUES (815, '2025-11-20 17:10:07.35095', '2025-11-20 17:10:07.35095', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 154, 5, 'Yêu cầu thành phẩm: Bầu chín tới, giữ màu xanh, nước canh trong ngọt tự nhiên, tôm mềm. Đây là món canh giúp giải nhiệt trong ngày hè.', 10);
INSERT INTO public.recipe_steps VALUES (816, '2025-11-20 17:10:07.354347', '2025-11-20 17:10:07.354347', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 154, 4, 'Nêm nếm mắm, muối, hạt nêm cho vừa miệng. Cho bầu vào nồi nước dùng, nhấn chìm xuống, hớt bỏ bọt. Vì bầu nhanh chín nên khi nước sôi lại thì tắt bếp, múc ra thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (817, '2025-11-20 17:10:07.357766', '2025-11-20 17:10:07.357766', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 154, 1, 'Bầu gọt vỏ, rửa sạch rồi tùy theo sở thích có 3 cách sau: Băm dọc rồi thái sợi nhỏ, nạo sợi hoặc cắt lát vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (818, '2025-11-20 17:10:07.360978', '2025-11-20 17:10:07.360978', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 154, 2, 'Tôm khô rửa sạch, ngâm nước ấm cho nở. Đun sôi lượng nước vừa ăn, cho tôm cùng nước đã ngâm vào ninh khoảng 25-30 phút cho tôm mềm và ngọt nước. Chú ý cho tôm vào khi nước nóng già để không bị tanh.', 10);
INSERT INTO public.recipe_steps VALUES (819, '2025-11-20 17:10:07.433355', '2025-11-20 17:10:07.433355', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 155, 1, 'Tôm khô rửa sạch, ngâm nước ấm cho mềm. Vị ngọt thanh từ tôm khô giúp cho món ăn trở nên hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (820, '2025-11-20 17:10:07.436027', '2025-11-20 17:10:07.436027', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 155, 4, 'Cho hoa thiên lý vào. Khi nước sôi trở lại khoảng 1 phút là tắt bếp, múc ra thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (821, '2025-11-20 17:10:07.437634', '2025-11-20 17:10:07.437634', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 155, 5, 'Yêu cầu thành phẩm: Hoa thiên lý giữ màu xanh tươi, giò chín tới, tôm mềm, nước canh thanh trong, ngọt mát rất hấp dẫn. Đây là món ăn phổ biến của vùng đồng bằng Bắc bộ giúp giải nhiệt trong những ngày hè oi bức.', 10);
INSERT INTO public.recipe_steps VALUES (823, '2025-11-20 17:10:07.442566', '2025-11-20 17:10:07.442566', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 155, 3, 'Cho lượng nước vừa đủ, cho tôm khô cùng nước ngâm vào ninh mềm để lấy nước dùng ngọt tự nhiên. Chú ý hớt bỏ bọt cho nước trong. Dùng thìa tròn dấp ít dầu ăn cho đỡ dính, múc giò sống thả vào nồi nước dùng. Khi giò nổi lên mặt nước là đã chín. Nêm 1,5 thìa cà phê muối, 1 thìa cà phê nước mắm, 1/2 thìa cà phê hạt nêm vào. Điều chỉnh cho vừa khẩu vị gia đình.', 10);
INSERT INTO public.recipe_steps VALUES (824, '2025-11-20 17:10:07.524106', '2025-11-20 17:10:07.524106', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 156, 5, 'Yêu cầu thành phẩm: Ốc kho sả ớt dậy mùi thơm đặc trưng của sả, ốc giòn sần sật, vị mặn ngọt cay hài hòa, ăn cùng cơm trắng rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (825, '2025-11-20 17:10:07.526236', '2025-11-20 17:10:07.526236', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 156, 2, 'Sả đập dập, băm nhuyễn. Tỏi, hành khô, ớt bỏ hạt băm nhuyễn. Lá chanh thái chỉ nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (826, '2025-11-20 17:10:07.52834', '2025-11-20 17:10:07.52834', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 156, 4, 'Làm nóng dầu ăn, phi vàng 1/2 lượng sả, hành, tỏi băm nhuyễn cho dậy mùi thơm. Trút ốc đã ướp vào đảo đều cho săn. Sau đó, hạ lửa nhỏ để kho ốc cho tới khi nước sốt sền sệt là được. Nêm nếm lại gia vị theo khẩu vị cho phù hợp. Rắc thêm lá chanh thái chỉ, tắt bếp và múc ra thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (827, '2025-11-20 17:10:07.531551', '2025-11-20 17:10:07.531551', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 156, 3, 'Ướp ốc với 1 muỗng canh nước mắm, 1 muỗng canh nước hàng, 1 muỗng canh đường, 1/2 muỗng cà phê muối, 1/2 muỗng cà phê hạt nêm, 1/2 muỗng cà phê hạt tiêu, cùng chút sả, ớt, tỏi, hành băm nhuyễn trong 10 - 15 phút cho thấm vị.', 10);
INSERT INTO public.recipe_steps VALUES (828, '2025-11-20 17:10:07.533703', '2025-11-20 17:10:07.533703', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 156, 1, 'Ốc ngâm nước vo gạo, cắt thêm 1 - 2 quả ớt cay để nhả hết bùn đất, rửa sạch, cho ốc vào nồi luộc. Khi nước sôi bùng lên và vảy ốc bung ra thì vớt ngay, khều ốc, bỏ phân rồi rửa sạch, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (829, '2025-11-20 17:10:07.672849', '2025-11-20 17:10:07.672849', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 157, 1, 'Chần sơ sứa: Đun sôi nồi nước cùng vài lát gừng, chút muối. Cho sứa vào muôi lỗ, nhúng nhanh vào nồi nước sôi rồi vớt ra ngay để đảm bảo vệ sinh. Chú ý không chần lâu sẽ làm sứa bị co, teo nhỏ lại, mất độ giòn.', 10);
INSERT INTO public.recipe_steps VALUES (830, '2025-11-20 17:10:07.67496', '2025-11-20 17:10:07.67496', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 157, 2, 'Xoài xanh gọt vỏ, thái sợi. Cà rốt bào sợi, trộn với 1/2 thìa canh đường trong 10 phút rồi vắt kỹ cho bớt vị hăng. Hành tây thái mỏng ngâm nước đá cùng chút chanh cho giòn, bớt hăng, vớt ra để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (831, '2025-11-20 17:10:07.677092', '2025-11-20 17:10:07.677092', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 157, 5, 'Yêu cầu thành phẩm: Đĩa nộm bắt mắt với nhiều sắc màu, tổng hòa các vị hài hòa chua cay mặn ngọt, sứa giòn sần sật, xoài chua thanh, rau thơm dậy mùi rất kích thích vị giác. Món này ăn chơi hay ăn cùng cơm trắng đều rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (832, '2025-11-20 17:10:07.679746', '2025-11-20 17:10:07.679746', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 157, 3, 'Sả thái lát mỏng. Rau thơm rửa sạch, vẩy ráo nước. Lạc rang vàng giòn, đập dập. Pha nước sốt nộm gồm đường: mắm 30 độ đạm: chanh theo tỷ lệ 1:1:1 (3 thìa canh đường, 3 thìa canh nước mắm, 3 thìa canh nước cốt chanh), khuấy đều cho tan rồi thêm tỏi, ớt băm nhuyễn vào.', 10);
INSERT INTO public.recipe_steps VALUES (833, '2025-11-20 17:10:07.681379', '2025-11-20 17:10:07.681379', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 157, 4, 'Trộn nộm theo quy tắc 2 lần sẽ giúp thơm ngon, vị hài hòa, các nguyên liệu khô ráo. Lần 1: Cho sứa, xoài xanh, cà rốt, hành tây, sả rồi cho 1/2 lượng nước sốt nộm vào đảo đều trong 7 - 8 phút để giúp rau củ quả tiết nước. Chắt bỏ nước đi. Lần 2: Cho 1/2 lượng nước sốt còn lại đảo đều cho thấm vị chua cay mặn ngọt hài hòa. Sau đó cũng chắt bỏ nước cho nộm khô ráo. Cuối cùng cho rau thơm, lạc rang giã dập vào đảo đều. Trình bày nộm ra đĩa, rắc thêm chút lạc rang lên trên và thưởng thức. Pha nước sốt ăn kèm gồm tương bần, thêm chút đường, chanh khuấy cho tan.', 10);
INSERT INTO public.recipe_steps VALUES (834, '2025-11-20 17:10:07.819996', '2025-11-20 17:10:07.819996', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 158, 2, 'Mướp hương gọt vỏ, rửa sạch, thái vát dày chút vì khi xào mướp co lại. Giá đỗ rửa sạch, để ráo nước. Hành lá rửa sạch, thái khúc 3-4 cm.', 10);
INSERT INTO public.recipe_steps VALUES (835, '2025-11-20 17:10:07.82264', '2025-11-20 17:10:07.82264', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 158, 6, 'Yêu cầu thành phẩm: Đĩa mướp xào giá đỗ, lòng gà khô ráo, mướp xanh giòn, ngọt thơm; giá đỗ chín vừa tới; lòng gà vị hài hòa. Món ăn này phù hợp vào tiết trời nóng nực mùa hè vì mướp có tính mát, thanh nhiệt.', 10);
INSERT INTO public.recipe_steps VALUES (836, '2025-11-20 17:10:07.825702', '2025-11-20 17:10:07.825702', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 158, 3, 'Phi thơm 1/2 số hành củ băm nhỏ, cho lòng gà vào xào săn. Lúc này, phần mề gà tãi ra thành hình hoa khế đẹp mắt. Múc ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (837, '2025-11-20 17:10:07.828099', '2025-11-20 17:10:07.828099', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 158, 5, 'Trút phần lòng gà, giá đỗ vào, đảo nhanh tay trên lửa lớn. Nêm nếm lại gia vị mắm, muối, hạt nêm, hạt tiêu cho vừa miệng. Thêm hành lá, rắc chút hạt tiêu, tắt bếp múc ra thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (838, '2025-11-20 17:10:07.830771', '2025-11-20 17:10:07.830771', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 158, 4, 'Phi thơm lượng hành củ còn lại, cho mướp hương vào, đảo nhanh tay xào trên lửa lớn để giữ màu xanh và độ giòn ngọt.', 10);
INSERT INTO public.recipe_steps VALUES (839, '2025-11-20 17:10:07.832884', '2025-11-20 17:10:07.832884', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 158, 1, 'Lòng, mề gà bóp muối hạt để khử mùi hôi, rửa nhiều lần cho sạch. Phần tiết cho vào nồi luộc ở lửa nhỏ liu riu để tiết mịn và không bị rỗ cho tới khi chín, vớt ra thái miếng. Phần lòng gà thì chần sơ rồi vớt ra rửa sạch, thái miếng vừa ăn. Phần mề gà khứa hình hoa khế để xào cho đẹp mắt. Ướp tất cả lòng mề gà với một thìa canh nước mắm, 1/2 thìa cà phê muối, 1/2 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu cùng 1/2 lượng hành khô băm trong 10-15 phút cho thấm vị.', 10);
INSERT INTO public.recipe_steps VALUES (840, '2025-11-20 17:10:07.929247', '2025-11-20 17:10:07.929247', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 159, 5, 'Cho phần hỗn hợp nước sốt mắm tỏi vào chảo đun sôi cho sền sệt ở lửa vừa.', 10);
INSERT INTO public.recipe_steps VALUES (841, '2025-11-20 17:10:07.932028', '2025-11-20 17:10:07.932028', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 159, 1, 'Sơ chế cá mai: Cá mai cắt đầu đuôi, bỏ ruột, ngâm nước muối loãng, rồi cho lên rổ và xả nước rửa vài lần cho sạch, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (939, '2025-11-20 17:10:10.245145', '2025-11-20 17:10:10.245145', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 175, 1, 'Gà làm sạch, chà xát muối hạt và chanh khử mùi, rửa sạch để ráo nước. Các loại rau củ quả rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (842, '2025-11-20 17:10:07.934149', '2025-11-20 17:10:07.934149', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 159, 3, 'Pha hỗn hợp sốt ngào cá mai gồm 3 thìa canh nước mắm 30 độ đạm, 3 thìa canh đường, 2 thìa canh tương ớt, 2 thìa canh giấm gạo, 1 thìa cà phê hạt nêm, 1 thìa cà phê hạt tiêu, 1 thìa cà phê ớt bột khuấy đều cho tan hỗn hợp. Sau đó, cho 2/3 phần tỏi, ớt băm nhuyễn vào.', 10);
INSERT INTO public.recipe_steps VALUES (843, '2025-11-20 17:10:07.936261', '2025-11-20 17:10:07.936261', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 159, 2, 'Tỏi băm nhuyễn. Ớt bỏ hạt, băm nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (844, '2025-11-20 17:10:07.938387', '2025-11-20 17:10:07.938387', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 159, 4, 'Cho dầu ăn vào chảo đun nóng, thử đầu đũa thấy sủi tăm là đạt. Chia cá mai thành mẻ cho vào chiên. Để cá giòn một mặt rồi mới lật trở mặt chiên vàng. Nếu muốn cá giòn rụm thì chiên 2 lầ lửa. Ở lần 1, khi cá hơi vàng vớt ra. Tiếp tục cho vào chiên lần 2 ở lửa lớn hơn vừa giúp cá giòn rụm, vừa thoát dầu, không bị ngấy mỡ. Vớt ra cho lên giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (845, '2025-11-20 17:10:07.940489', '2025-11-20 17:10:07.940489', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 159, 7, 'Yêu cầu thành phẩm: Cá giòn rụm, bề mặt bao phủ lớp sốt vàng nâu óng, vị chua cay mặn ngọt hài hòa, dậy mùi thơm của tỏi, cay cay của ớt, ăn cùng cơm trắng hay nhâm nhi đều ngon.', 10);
INSERT INTO public.recipe_steps VALUES (846, '2025-11-20 17:10:07.942615', '2025-11-20 17:10:07.942615', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 159, 6, 'Trút cá mai vào chảo nước sốt đảo đều cho gia vị ngấm đều. Chú ý tăng lửa và làm nhanh ở bước này để gia vị quyện vào các mặt cá, nhưng cá vẫn giữ độ giòn rụm.', 10);
INSERT INTO public.recipe_steps VALUES (847, '2025-11-20 17:10:08.020514', '2025-11-20 17:10:08.020514', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 160, 4, 'Yêu cầu thành phẩm: Thịt cá săn lại, đậm vị mằn mặn, chua nhẹ từ cà chua, cộng chút the cay từ ớt đẩy đưa vị giác, màu đẹp mắt. Món này ăn cùng cơm nóng rất hao.', 10);
INSERT INTO public.recipe_steps VALUES (848, '2025-11-20 17:10:08.022771', '2025-11-20 17:10:08.022771', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 160, 1, 'Cà chua rửa sạch, thái múi cau. Hành củ thái lát, giữ vỏ hành rửa sạch cho vào kho cùng sẽ giúp dậy mùi thơm và khi ăn vỏ hành dẻo dai thấm vị. Gừng thái lát, ớt khô rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (849, '2025-11-20 17:10:08.024354', '2025-11-20 17:10:08.024354', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 160, 2, 'Cá trích cắt chéo bụng, moi bỏ ruột, rắc chút muối hạt và nước cốt chanh vài phút khử tanh rồi rửa nhiều lần cho sạch, để ráo nước. Ướp cá trích với 3 thìa canh nước mắm cốt, 1 muỗng canh đường, 1 muỗng canh nước hàng, 1 muỗng canh tương ớt, 1 muỗng cà phê muối, 1/2 muỗng cà phê hạt nêm, 1 muỗng cà phê hạt tiêu cùng 1/2 lượng hành, gừng, ớt. Ướp tối thiểu trong 30 phút cho thấm vị.', 10);
INSERT INTO public.recipe_steps VALUES (850, '2025-11-20 17:10:08.026009', '2025-11-20 17:10:08.026009', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 160, 3, 'Kho cá tối thiểu 2 lần lửa. Lần lửa 1: Phi thơm hành còn lại, cho cà chua vào xào sơ, cho cá cùng toàn bộ nước ướp sốt, thêm nước sôi già xâm xấp vào, nêm nếm lại gia vị cho phù hợp. Khi nước sôi hạ lửa nhỏ liu riu kho trong 40 - 45 phút rồi tắt bếp để nguội. Việc này giúp ''''cá hồi thịt'''' trở nên săn lại. Ở các lửa lần 2,3 cũng làm tương tự kho liu riu, thỉnh thoảng nghiêng nồi lấy nước kho rưới đều mặt cá. Chêm nước sôi nóng khi muốn kho lâu cho rục mềm xương. Khi cá đạt độ mềm mong muốn, cạn còn 1/3 lượng nước sốt thì rưới thêm chút mỡ lợn, có tóp mỡ càng ngon, tăng lửa, mở vung để nước kho sền sệt, bắt mắt là đạt. Rắc thêm chút hành lá, hạt tiêu là được.', 10);
INSERT INTO public.recipe_steps VALUES (851, '2025-11-20 17:10:08.164584', '2025-11-20 17:10:08.164584', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 161, 3, 'Tỏi bóc vỏ, thái lát. Ớt cắt bỏ cuống, riềng thái nhỏ hoặc thái lát. Ngâm tỏi, ớt, riềng vào chút giấm để giữ màu đồng thời để khi ngâm không bị nổi váng (Hoặc có thể cho tỏi, riềng, ớt vào chần khi hỗn hợp nước mắm đường sôi, vớt ra để nguội).', 10);
INSERT INTO public.recipe_steps VALUES (852, '2025-11-20 17:10:08.166716', '2025-11-20 17:10:08.166716', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 161, 5, 'Yêu cầu thành phẩm: Sấu giòn đượm vị chua cay mặn ngọt, thơm mùi riềng tỏi, ăn cùng thịt luộc, rau củ quả luộc rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (853, '2025-11-20 17:10:08.169388', '2025-11-20 17:10:08.169388', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 161, 1, 'Sấu cắt cuống, bỏ quả dập, rửa sạch, ngâm nước muỗi loãng. Sau đó, đun sôi nước cùng 1 thìa cà phê chút muối hạt, cho sấu vào chần nhanh 10 giây để ra bớt nhựa chát, lên màu đẹp và khi ngâm không bị nổi váng.', 10);
INSERT INTO public.recipe_steps VALUES (854, '2025-11-20 17:10:08.172045', '2025-11-20 17:10:08.172045', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 161, 4, 'Bình thủy tinh rửa sạch, dội nước sôi để khử khuẩn, để khô ráo hoàn toàn. Sau đó, xếp một lớp sấu, một lớp riềng tỏi ớt xen kẽ cho tới hết. Cuối cùng đổ hỗn hợp nước mắm đã nguội, chèn núi nilon sạch đựng nước sôi để nguội hoặc vật nặng nén sấu xuống. Đậy nắp lại sau 3 ngày là dùng được. Cho sấu ngâm mắm vào ngăn mát tủ lạnh dùng dần quanh năm.', 10);
INSERT INTO public.recipe_steps VALUES (855, '2025-11-20 17:10:08.174858', '2025-11-20 17:10:08.174858', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 161, 2, 'Cho 500 ml nước mắm 30-40 độ đạm cùng 300 g đường, 200 ml nước vào đun sôi cho tan đường. Tắt bếp để nguội hoàn toàn.', 10);
INSERT INTO public.recipe_steps VALUES (856, '2025-11-20 17:10:08.279736', '2025-11-20 17:10:08.279736', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 162, 5, 'Cho rau ngót đã vò sơ vào nồi nước riêu tép đang sôi, ấn chìm xuống, nêm nếm gia vị mắm, muối, hạt nêm cho vừa miệng. Rau chín, múc ra bát, rồi lấy thịt tép cho lên trên.', 10);
INSERT INTO public.recipe_steps VALUES (857, '2025-11-20 17:10:08.2819', '2025-11-20 17:10:08.2819', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 162, 2, 'Rau ngót nhặt, rửa sạch, vò sơ để giúp khi nấu rau mềm hơn.', 10);
INSERT INTO public.recipe_steps VALUES (858, '2025-11-20 17:10:08.284123', '2025-11-20 17:10:08.284123', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 162, 4, 'Nếu múc thịt (riêu tép) ra bát thì nghiêng bát ép chặt cho nước ra để giúp đóng kết tảng đẹp mắt.', 10);
INSERT INTO public.recipe_steps VALUES (859, '2025-11-20 17:10:08.28678', '2025-11-20 17:10:08.28678', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 162, 3, 'Cho nồi nước tép đã lọc lên bếp, bật lửa vừa và khuấy đều theo vòng tròn một chiều để thịt tép không bén đáy nồi. Khi phần thịt nổi lên và tách nước thì dùng muôi gạt sang một bên hoặc múc riêng ra bát.', 10);
INSERT INTO public.recipe_steps VALUES (860, '2025-11-20 17:10:08.288936', '2025-11-20 17:10:08.288936', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 162, 1, 'Tép đồng nhặt bỏ tạp chất, rửa sạch, cho vào cối cùng chút muối, hành khô giã nhuyễn. Muối giúp cho protein trong tép kết dính, khi nấu sẽ đóng thành tảng. Cho lượng nước vừa đủ vào bóp tan phần tép giã, rồi lọc qua rây.', 10);
INSERT INTO public.recipe_steps VALUES (1020, '2025-11-20 17:10:12.193375', '2025-11-20 17:10:12.193375', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 188, 5, 'Khi nước kho sánh sệt lại, rưới chút mỡ lợn hoặc tóp mỡ cho cá bóng đẹp, rắc hạt tiêu, hành lá xắt nhỏ là hoàn thành.', 10);
INSERT INTO public.recipe_steps VALUES (861, '2025-11-20 17:10:08.291615', '2025-11-20 17:10:08.291615', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 162, 6, 'Yêu cầu thành phẩm: Bát canh gói trọn sắc và vị, rau ngót xanh mềm, riêu tép ngọt mát, đóng tảng đẹp mắt. Món canh này không chỉ thanh mát, giải nhiệt và còn giúp nhuận tràng, giàu canxi tốt cho bà bầu, trẻ em.', 10);
INSERT INTO public.recipe_steps VALUES (862, '2025-11-20 17:10:08.429482', '2025-11-20 17:10:08.429482', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 163, 4, 'Sao vàng mực: Phi thơm tỏi, cho mực và chút mắm, muối, đường vào đảo cho ngấm vị rồi sao vàng. Tắt bếp, múc ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (863, '2025-11-20 17:10:08.431084', '2025-11-20 17:10:08.431084', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 163, 5, 'Xào măng: Phi thơm mỡ lợn và hành khô, cho măng vào xào săn, thêm 1 muôi nước dùng, xào kỹ cho măng mềm và thấm vị. Sau đó, cho mực vào xào cùng.', 10);
INSERT INTO public.recipe_steps VALUES (864, '2025-11-20 17:10:08.433244', '2025-11-20 17:10:08.433244', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 163, 6, 'Nấu nước dùng sôi, cho măng và mực đã xào vào. Khi nước sôi, vặn lửa nhỏ hầm để nước thanh trong, không bị đục. Nêm nếm gia vị cho vừa ăn. Sau 1,5 - 2 tiếng, măng mềm nhưng vẫn giòn sần sật, mực mềm mà không dai, nước ngọt thanh trong là đã được.', 10);
INSERT INTO public.recipe_steps VALUES (865, '2025-11-20 17:10:08.435462', '2025-11-20 17:10:08.435462', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 163, 3, 'Nước dùng lấy từ nước luộc gà càng ngon. Nếu không có thì ninh từ nước xương lợn và tôm nõn để lấy nước dùng.', 10);
INSERT INTO public.recipe_steps VALUES (866, '2025-11-20 17:10:08.437587', '2025-11-20 17:10:08.437587', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 163, 2, 'Sơ chế mực: Mực khô ngâm với rượu và gừng giã dập để khử mùi tanh. Nướng sơ mực cho thơm, dùng chày hoặc búa đập nhẹ giúp thớ mực tách ra. Sau đó, xé thành các sợi nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (867, '2025-11-20 17:10:08.440304', '2025-11-20 17:10:08.440304', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 163, 1, 'Sơ chế măng: Măng khô ngâm nước vo gạo qua đêm cho nở mềm rồi rửa sạch, dùng mũi dao tước thành các sợi nhỏ. Sau đó, luộc 3-4 nước cùng chút muối hạt cho tới khi nước trong, rửa sạch, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (868, '2025-11-20 17:10:08.652223', '2025-11-20 17:10:08.652223', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 164, 2, 'Phi thơm hành khô, cho sườn vào đảo đều cho săn lại. Sau đó thêm nước xâm xấp rồi hạ lửa nhỏ ninh sườn cho tới khi mềm theo ý muốn. Nêm nếm lại gia vị cho phù hợp.', 10);
INSERT INTO public.recipe_steps VALUES (869, '2025-11-20 17:10:08.653798', '2025-11-20 17:10:08.653798', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 164, 3, 'Rang sơ gạo tẻ, gạo nếp cho tới khi hạt săn lại, chuyển màu đục là được.', 10);
INSERT INTO public.recipe_steps VALUES (870, '2025-11-20 17:10:08.656393', '2025-11-20 17:10:08.656393', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 164, 6, 'Phi thơm tỏi, cho gan đã ướp vào xào nhanh tay, thêm 1/2 bát con nước. Đảo đều tay trong 2-3 phút cho gan chín và nước sốt sánh là được. Nêm nếm lại gia vị phù hợp.', 10);
INSERT INTO public.recipe_steps VALUES (871, '2025-11-20 17:10:08.660279', '2025-11-20 17:10:08.660279', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 164, 5, 'Gan rửa sạch, thái mỏng, ngâm sữa tươi không đường khoảng 15 - 20 phút để khử độc và tanh. Sau đó, vớt ra rửa nhiều lần cho sạch, để ráo nước. Ướp gan với 1 muỗng canh nước mắm, 1 muỗng canh bột bắp, 1 muỗng canh tương ớt, 1 muỗng canh tương cà, 1 muỗng canh đường, 1 muỗng canh dầu màu điều, 1 muỗng cà phê hạt tiêu, 1 muỗng cà phê hạt nêm.', 10);
INSERT INTO public.recipe_steps VALUES (872, '2025-11-20 17:10:08.661862', '2025-11-20 17:10:08.661862', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 164, 4, 'Lọc lấy nước dùng hầm từ xương heo, thêm ngô và nước luộc ngô cho ngọt. Trút phần gạo tẻ, nếp đã rang sơ vào nấu thành cháo sánh đặc.', 10);
INSERT INTO public.recipe_steps VALUES (873, '2025-11-20 17:10:08.665177', '2025-11-20 17:10:08.665177', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 164, 7, 'Múc cháo ra, thêm sườn hầm, gan, rắc chút hạt tiêu, hành lá, ớt và thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (874, '2025-11-20 17:10:08.666764', '2025-11-20 17:10:08.666764', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 164, 8, 'Yêu cầu thành phẩm: Cháo ngọt thơm, hạt gạo nở bung, gan bùi bùi, sườn đậm vị, ngô giòn ngọt, tất cả quyện hòa đa màu sắc, hương vị cuốn hút.', 10);
INSERT INTO public.recipe_steps VALUES (875, '2025-11-20 17:10:08.668878', '2025-11-20 17:10:08.668878', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 164, 1, 'Sơ chế sườn, xương bay: Sườn chặt miếng vừa ăn, chần sơ cùng chút muối để loại bỏ tạp chất, rửa sạch rồi để ráo nước. Sau đó, ướp sườn với 1 muỗng canh dầu hào, 1 muỗng canh xì dầu, 1 muỗng canh tương ớt, 1 muỗng cà phê hạt nêm, 1 muỗng cà phê hạt tiêu, đảo đều, ướp trong 30 phút cho thấm vị. Phần xương bay hoặc xương cục thì cũng chần sơ, rửa sạch và ninh lấy nước dùng nấu cháo.', 10);
INSERT INTO public.recipe_steps VALUES (876, '2025-11-20 17:10:08.810228', '2025-11-20 17:10:08.810228', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 165, 3, 'Đổ lượng nước vừa đủ vào phần cua giã, dùng tay bóp kỹ cho thịt cua tan ra, để lắng rồi lọc lấy nước. Tiếp tục giã và lọc để lấy hết thịt cua.', 10);
INSERT INTO public.recipe_steps VALUES (877, '2025-11-20 17:10:08.811812', '2025-11-20 17:10:08.811812', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 165, 6, 'Phi thơm hành khô, cho gạch cua vào đảo đều cho dậy mùi thơm ở lửa nhỏ, múc ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (878, '2025-11-20 17:10:08.814012', '2025-11-20 17:10:08.814012', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 165, 4, 'Rau muống nhặt lấy phần ngọn và cọng non, rửa sạch rồi bóp dập cuống cho mềm khi nấu. Khoai sọ rửa sạch, luộc chín, bóc vỏ.', 10);
INSERT INTO public.recipe_steps VALUES (879, '2025-11-20 17:10:08.816843', '2025-11-20 17:10:08.816843', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 165, 7, 'Cho khoai sọ vào nồi nước dùng, nêm nếm mắm, muối, hạt nêm vừa vị đun sôi. Khi khoai sọ mềm theo sở thích thì thêm rau muống, đảo đều. Múc canh ra bát, rồi lấy thịt cua, rưới gạch cua lên trên và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (880, '2025-11-20 17:10:08.818433', '2025-11-20 17:10:08.818433', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 165, 1, 'Cho cua đồng cùng chút muối hạt vào xô thành cao, thêm nước xóc mạnh để loại bỏ chất bẩn trên mình cua. Sau đó, rửa sạch, để ráo nước, bóc mai, tách yếm, khều gạch. Cho gạch lên rây rồi rửa nhẹ qua nước cho sạch (để gạch không bị hoi do dính phần nước đen khi làm cua bám vào).', 10);
INSERT INTO public.recipe_steps VALUES (881, '2025-11-20 17:10:08.820034', '2025-11-20 17:10:08.820034', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 165, 2, 'Phần thâncua rửa sạch, cho vào cối, thêm chút muối hạt và giã thật nhuyễn cho tới khi dính chày. Thêm muối ở khâu này là mẹo để giúp protein từ thịt cua kết dính, tạo tảng khi nấu.', 10);
INSERT INTO public.recipe_steps VALUES (882, '2025-11-20 17:10:08.82269', '2025-11-20 17:10:08.82269', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 165, 5, 'Cho nước thịt cua lên bếp đun ở lửa vừa, khuấy đều theo một chiều để thịt cua không bén đáy. Khi thịt cua nổi lên, nước dần trong, tách thịt ra thì hạ lửa nhỏ, dùng muôi múc thịt riêng ra bát, ém cho nước ra bớt. Lúc này thịt cua đóng tảng lại.', 10);
INSERT INTO public.recipe_steps VALUES (1021, '2025-11-20 17:10:12.293386', '2025-11-20 17:10:12.293386', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 189, 3, 'Lá lốt nhặt và rửa sạch, vẩy ráo nước, thái sợi. Ớt thái lát (tùy chọn).', 10);
INSERT INTO public.recipe_steps VALUES (883, '2025-11-20 17:10:08.82481', '2025-11-20 17:10:08.82481', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 165, 8, 'Yêu cầu thành phẩm: Thịt cua đóng tảng, gạch cua thơm lừng, khoai bùi dẻo, rau muống giòn ngon. Món này ăn cùng cà pháo muối, thịt rang cháy cạnh thì bao hương xưa vị cũ ngày hè lại ùa về.', 10);
INSERT INTO public.recipe_steps VALUES (884, '2025-11-20 17:10:08.967055', '2025-11-20 17:10:08.967055', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 166, 5, 'Kho cá cần kho tối thiểu 2 lần lửa sẽ giúp dậy màu, dậy vị và dậy mùi hấp dẫn. Lần 1: Thêm chút nước sôi xâm xấp cá, cho lên bếp đun sôi 5 - 6 phút, nêm nếm lại gia vị cho phù hợp. Sau đó, hạ lửa nhỏ liu riu kho trong 40 - 45 phút. Lúc này mật mía quyện nước mắm, nước chua từ cà pháo muối tiết ra cứ thế quyện vào nhau làm cho thịt cá dần se lại. Sau đó, tắt bếp để nguội giúp cho ''''cá hồi thịt'''' trở nên săn chắc. Ở các lửa 2,3 cũng kho tương tự ở lửa liu riu, thỉnh thoảng múc nước kho rưới đều mặt. Chêm nước nếu muốn kho lâu, xương mềm rục. Khi nước gần cạn thì rưới thêm mỡ lợn, tăng lửa, mở vung để nước kho sền sệt, ánh màu hổ phách đẹp mắt.', 10);
INSERT INTO public.recipe_steps VALUES (885, '2025-11-20 17:10:08.969468', '2025-11-20 17:10:08.969468', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 166, 3, 'Lấy 1 bát cà pháo muối chua rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (886, '2025-11-20 17:10:08.971574', '2025-11-20 17:10:08.971574', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 166, 6, 'Yêu cầu thành phẩm: Thịt cá màu nâu đỏ, chắc béo, thấm vị mằn mặn, chua chua từ cá quyện với mật mía ngòn đượm, cộng chút the cay từ ớt đẩy đưa vị giác, giúp bữa ăn ngày nóng trở nên tròn vị.', 10);
INSERT INTO public.recipe_steps VALUES (887, '2025-11-20 17:10:08.973704', '2025-11-20 17:10:08.973704', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 166, 1, 'Cá làm sạch, cạo bỏ hết màng đen trong bụng, dùng muối hạt và chanh chà xát khử tanh, rửa sạch, để ráo nước. Ướp cá với một thìa canh muối hạt trước vừa giúp cá chắc, vừa đậm vị hơn khi kho.', 10);
INSERT INTO public.recipe_steps VALUES (888, '2025-11-20 17:10:08.975836', '2025-11-20 17:10:08.975836', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 166, 2, 'Riềng rửa sạch, thái lát. Sả đập dập, cắt khúc. Hành khô ngâm rửa sạch, bóc giữ cả vỏ kho theo cách xưa. Vỏ hành vừa giúp cá lên màu óng đẹp, khi ăn cảm nhận được vị dai dai, thấm vị ngọt béo từ cá thịt. Ớt khô rửa sạch để nguyên quả.', 10);
INSERT INTO public.recipe_steps VALUES (889, '2025-11-20 17:10:08.978', '2025-11-20 17:10:08.978', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 166, 4, 'Ướp cá với 1/2 chén (bát nhỏ) mật mía, 3 - 4 thìa canh nước mắm cốt ngon, 1 thìa cà phê mì chính (hoặc hạt nêm), 1 thìa cà phê hạt tiêu tối thiểu 1 giờ. Sau đó, xếp riềng, sả dưới đáy nồi, rồi lần lượt xếp cá, thịt ba chỉ thái miếng, xen kẽ cà pháo muối chua. Trên cùng cho ớt quả, hành khô, hạt tiêu.', 10);
INSERT INTO public.recipe_steps VALUES (890, '2025-11-20 17:10:09.130358', '2025-11-20 17:10:09.130358', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 167, 1, 'Làm hỗn hợp nước sốt ướp và phết nướng: Phi thơm hành, tỏi, cho vào 3 muỗng canh tương ớt, 2 muỗng canh mật ong, 2 muỗng canh dầu hào, 1 muỗng canh giấm, 1 muỗng canh nước tương, 1 muỗng canh đường vàng (hoặc đường nâu), 1 muỗng canh dầu màu điều, 1 muỗng cà phê muối, 1 muỗng cà phê sữa đặc, 1 muỗng cà phê mật ong, 1 muỗng cà phê hạt tiêu, 1 muỗng cà phê ngũ vị hương. Nếu thích ăn cay thì thêm 1 muỗng canh ớt bột. Thêm chút nước, đun lửa nhỏ, khuấy đều cho tới khi thành hỗn hợp sền sệt là được. Tắt bếp, múc ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (891, '2025-11-20 17:10:09.132483', '2025-11-20 17:10:09.132483', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 167, 4, 'Lấy sườn ra, rắc vừng trắng rang lên bề mặt (tùy chọn). Trang trí món ăn cùng với rau sống, dưa chuột, cà chua.', 10);
INSERT INTO public.recipe_steps VALUES (892, '2025-11-20 17:10:09.134773', '2025-11-20 17:10:09.134773', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 167, 2, 'Sườn bóc bỏ mỡ và gân, ngâm nước muối loãng, rửa sạch sau đó, chần sơ để loại bỏ tạp chất, rửa sạch lại, thấm khô. Dùng dao nhọn rạch đường nhỏ sau sườn để giúp róc xương khi ăn dễ tách thịt hơn.', 10);
INSERT INTO public.recipe_steps VALUES (893, '2025-11-20 17:10:09.136433', '2025-11-20 17:10:09.136433', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 167, 3, 'Đeo găng tay, lấy 2/3 hỗn hợp nước sốt thoa đều lên 2 mặt sườn rồi cho vào túi zip bọc kín, ướp trong tủ lạnh tối thiểu 2 giờ hoặc để qua đêm càng ngon. Nướng sườn hai lần. Lần 1: bọc sườn vào giấy bạc, đem nướng ở nhiệt lò 180-200 chế độ hai lửa trong 20 phút giúp sườn chín và thịt mềm. Lấy sườn ra, phết hỗn hợp nước sốt còn lại đều khắp các mặt. Mở giấy bạc, tiếp tục cho sườn vào nướng lần 2 từ 15 phút ở nhiệt độ 220 độ, để thanh lửa trên giúp cho bề mặt sém vàng, lên màu đẹp là được.', 10);
INSERT INTO public.recipe_steps VALUES (894, '2025-11-20 17:10:09.139106', '2025-11-20 17:10:09.139106', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 167, 5, 'Yêu cầu thành phẩm: Sườn lên màu bóng đẹp, thịt mềm thấm vị đậm đà mà không bị khô, dẻ sườn dễ róc.', 10);
INSERT INTO public.recipe_steps VALUES (895, '2025-11-20 17:10:09.242206', '2025-11-20 17:10:09.242206', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 168, 6, 'Yêu cầu thành phẩm: Bát canh với nước dùng ngon ngọt tự nhiên, thịt cua đóng tảng đẹp mắt, rau xanh mướt ăn cùng cà pháo muối chua, đậu phụ chiên giòn nhanh chóng xua tan cái nóng nực, oi nồng của mùa hè.', 10);
INSERT INTO public.recipe_steps VALUES (896, '2025-11-20 17:10:09.245301', '2025-11-20 17:10:09.245301', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 168, 1, 'Cho chút muối hạt vào cua đồng, để trong chậu xóc mạnh, rồi rửa sạch chất bẩn bám trên mình cua. Bóc mai tách yếm, khều gạch vàng để riêng. Sau đó, cho gạch lên rây rồi rửa nhẹ qua nước cho sạch (do khi làm cua một phần nước đen từ cua bám vào, gây tanh khi nấu). Phần thân cua cho vào rổ rửa sạch, rồi đổ vào cối, thêm chút muối hạt, giã thật nhuyễn. Muối là bí quyết giúp cho protein từ thịt cua kết dính, khi nấu tạo thành tảng.', 10);
INSERT INTO public.recipe_steps VALUES (897, '2025-11-20 17:10:09.247101', '2025-11-20 17:10:09.247101', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 168, 2, 'Cho nước vào cối, dùng tay bóp kỹ thịt cua tan ra, để lắng rồi lọc lấy nước. Tiếp tục giã và lọc kỹ vài lần để lấy hết phần thịt cua.', 10);
INSERT INTO public.recipe_steps VALUES (898, '2025-11-20 17:10:09.250185', '2025-11-20 17:10:09.250185', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 168, 5, 'Cho rau đay, mồng tơi, mướp hương vào nấu chín. Nêm nếm gia vị theo khẩu vị. Phần gạch thì tùy theo mỗi vùng miền và sở thích có 2 cách: Ở miền Bắc thì cho gạch cua vào nồi nước riêu rồi cho rau vào sau nấu chín. Còn một số tỉnh miền Nam thì phi thơm hành, cho gạch vào chưng, nêm nếm gia vị. Sau đó mới cho vào nồi canh. Múc canh ra bát, rồi lấy thịt cua để lên trên. Nếu không vớt thịt cua ra thì đẩy vào một góc, rồi cho rau vào góc còn lại. Thịt cua vẫn đóng tảng đẹp mắt.', 10);
INSERT INTO public.recipe_steps VALUES (899, '2025-11-20 17:10:09.254259', '2025-11-20 17:10:09.254259', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 168, 3, 'Rau đay, mồng tơi nhặt lá non, rửa sạch, thái nhỏ. Mướp gọt vỏ, thái mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (900, '2025-11-20 17:10:09.255645', '2025-11-20 17:10:09.255645', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 168, 4, 'Bí quyết quan trọng nhất chính là canh nhiệt độ khi nấu canh cua. Ban đầu, sau khi cho nồi lên thì bật lửa vừa và khuấy đều vòng tròn theo một chiều nhằm giúp thịt cua không bén đáy và hòa quyện vào nhau. Khi phần thịt nổi lên hết, hạ lửa nhỏ và gạt thịt cua sang một bên hoặc múc riêng ra bát, ém chặt nước.', 10);
INSERT INTO public.recipe_steps VALUES (901, '2025-11-20 17:10:09.427534', '2025-11-20 17:10:09.427534', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 169, 1, 'Cách chưng mắm tép:Vì mắm tép nguyên bản có vị mặn nên cần pha loãng với tỷ lệ mắm tép: đường: chanh là 3:1:1. Cho 3 thìa canh mắm tép, 1 thìa canh đường cùng chút nước khuấy đều. Phi thơm hành, tỏi khô băm nhỏ cho dậy mùi. Sau đó, trút phần mắm tép cùng đường ở trên vào khuấy đều, đun lửa nhỏ vài phút. Cuối cùng nêm hạt nêm, thêm ớt (tùy khẩu vị) tắt bếp. Trước khi ăn thì cho 1 thìa canh nước cốt chanh vào đánh đều để cân bằng vị mặn ngọt hài hòa.', 10);
INSERT INTO public.recipe_steps VALUES (902, '2025-11-20 17:10:09.430843', '2025-11-20 17:10:09.430843', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 169, 4, 'Yêu cầu thành phẩm: Thịt luộc vừa chín tới mềm ngọt chấm mắm tép vàng đượm, vị mặn ngọt chua cay hài hòa rất đưa miệng.', 10);
INSERT INTO public.recipe_steps VALUES (903, '2025-11-20 17:10:09.433528', '2025-11-20 17:10:09.433528', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 169, 2, 'Cách luộc thịt:Chọn thịt ba chỉ nạc mỡ đan xen, chà xát muối hạt rửa sạch. Đun sôi nước, cho thịt vào chần sơ để loại bỏ tạp chất, rửa sạch. Cho thịt vào nồi ngập nước, thêm vài củ hành tím hoặc đầu củ hành trắng, thêm 1 thìa cà phê muối, 1/2 thìa cà phê hạt nêm cho ngọt thịt. Khi nước sôi, hạ lửa nhỏ, đậy vung, đun liu riu khoảng 15-20 phút tùy lượng nhiều hay ít. Sau đó, tắt bếp và tiếp tục để om thịt thêm 8 - 10 phút nữa cho thịt ngậm nước sẽ ngọt mềm hơn. Vớt thịt ra để nguội bớt và thái miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (904, '2025-11-20 17:10:09.436224', '2025-11-20 17:10:09.436224', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 169, 3, 'Các loại rau sống (tùy chọn) rửa sạch, vẩy ráo. Chuối xanh, khế chua, dưa chuột gọt vỏ, thái mỏng. Trình bày thịt ra đĩa, thêm chút hành lá chần, rau sống và bên cạnh đặt bát mắm tép chưng. Món này ăn kèm cơm trắng hay cuốn bún cùng bánh tráng đều rất hao trong ngày hè.', 10);
INSERT INTO public.recipe_steps VALUES (905, '2025-11-20 17:10:09.586557', '2025-11-20 17:10:09.586557', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 170, 1, 'Cà cắt bỏ cuống, rửa sạch, cắt thành từng lát vừa ăn và ngâm vào nước muối loãng, thêm chút giấm cho ra bớt nhựa, tránh cà bị thâm.', 10);
INSERT INTO public.recipe_steps VALUES (906, '2025-11-20 17:10:09.588724', '2025-11-20 17:10:09.588724', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 170, 3, 'Cà sau khi ngâm, vớt ra rửa sạch, cho vào âu rồi đeo găng tay bóp sơ với 1 thìa cà phê muối hạt, 1/2 lượng nước cốt chanh trong 2 - 3 phút cho cà bao bọc vị chua, mặn sẽ không bị thâm đen khi để lâu. Tiếp đó cho 1 thìa canh nước mắm, 1 thìa canh đường, lượng nước chanh còn lại cùng riềng, tỏi, ớt giã nhỏ, chút hạt tiêu (tùy chọn) vào trộn đều. Điều chỉnh lại theo khẩu vị cá nhân. Dùng màng bọc thực phẩm bọc lại để trong 30 phút là ăn được. Nếu chưa ăn thì cho vào ngăn mát tủ lạnh. Cà bát muối xổi chấm bát mắm tôm đánh bông lên, ăn cùng canh cua rau đay, cơm trắng thì ngon khó tả.', 10);
INSERT INTO public.recipe_steps VALUES (907, '2025-11-20 17:10:09.590851', '2025-11-20 17:10:09.590851', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 170, 2, 'Riềng, tỏi, ớt giã nhỏ. Chanh vắt lấy nước cốt, bỏ hạt.', 10);
INSERT INTO public.recipe_steps VALUES (908, '2025-11-20 17:10:09.67105', '2025-11-20 17:10:09.67105', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 171, 2, 'Lá lốt rửa sạch, thái rối. Tỏi bóc bỏ vỏ, đập dập. Ớt bổ đôi bỏ hạt, thái lát hoặc thái sợi dài tùy chọn.', 10);
INSERT INTO public.recipe_steps VALUES (909, '2025-11-20 17:10:09.673724', '2025-11-20 17:10:09.673724', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 171, 3, 'Đun sôi nước, thêm chút muối hạt và cho cà pháo vào chần sơ để giúp cà mềm. Vớt ra để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (910, '2025-11-20 17:10:09.676384', '2025-11-20 17:10:09.676384', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 171, 4, 'Phi thơm tỏi, cho cà vào xào. Thêm 1/2 chén nước xâm xấp mặt cà, nêm 1 thìa canh nước mắm, 1 thìa cà cà phê muối đảo đều. Hạ lửa nhỏ vừa, xào cho tới khi cà mềm, nước sánh lại thì thêm ớt và 1/2 thìa cà phê hạt nêm, lá lốt đảo đảo đều và tắt bếp, múc ra thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (911, '2025-11-20 17:10:09.678713', '2025-11-20 17:10:09.678713', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 171, 1, 'Cà pháo cắt bỏ cuống, bổ đôi hoặc thái lát 0,5 cm và ngâm ngay vào nước muối loãng 10-15 phút cho cà không bị thâm và loại bỏ bớt độc tố. Sau đó rửa sạch, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (912, '2025-11-20 17:10:09.681371', '2025-11-20 17:10:09.681371', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 171, 5, 'Yêu cầu thành phẩm: Cà trắng, mềm dẻo, có chút cay nhẹ từ ớt, dậy mùi thơm đặc trưng của lá lốt, nước sóng sánh rất bắt mắt. Món này hao cơm trong tiết trời mùa hè khi cà pháo đang vào độ.', 10);
INSERT INTO public.recipe_steps VALUES (913, '2025-11-20 17:10:09.761397', '2025-11-20 17:10:09.761397', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 172, 5, 'Yêu cầu thành phẩm: thịt trai giòn ngọt tự nhiên, thoảng chút chua nhẹ, thơm mùi hành răm vừa bổ dưỡng lại giải nhiệt ngày hè.', 10);
INSERT INTO public.recipe_steps VALUES (914, '2025-11-20 17:10:09.764125', '2025-11-20 17:10:09.764125', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 172, 4, 'Phi thơm 1/2 lượng hành khô, cho trai vào xào trên lửa lớn, múc ra để riêng. Tiếp tục phi thơm hành khô còn lại, cho cà chua vào xào sơ, trút phần nước luộc trai đã gạn vào. Khi canh sôi, nêm nếm gia vị lại phù hợp, trút phần thịt trai đã xào vào. Thêm hành, răm, ớt và tắt bếp, múc ra thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (915, '2025-11-20 17:10:09.7657', '2025-11-20 17:10:09.7657', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 172, 1, 'Ngâm trai cùng chút giấm, ớt cắt lát trong hai giờ để nhả hết bùn đất, sau đó rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (916, '2025-11-20 17:10:09.767808', '2025-11-20 17:10:09.767808', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 172, 2, 'Cà chua thái múi cau. Rau răm rửa sạch, thái rối. Hành lá rửa sạch, thái khúc. Ớt bỏ hạt thái lát. Hành củ bóc bỏ vỏ, thái lát.', 10);
INSERT INTO public.recipe_steps VALUES (917, '2025-11-20 17:10:09.771001', '2025-11-20 17:10:09.771001', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 172, 3, 'Cho trai vào nồi ngập nước, đun sôi. Khi trai mở miệng thì đảo đều, tắt bếp, vớt ra lọc lấy phần nước để riêng, tách lấy phần thịt trai, bỏ vỏ, nặn bỏ ruột, rửa sạch, thái miếng vừa ăn. Ướp thịt trai với 1 thìa cà phê nước mắm, 1/2 thìa cà phê muối, 1/4 thìa cà phê mì chính, 1/2 thìa cà phê hạt tiêu, đảo đều và ướp trong 10 - 15 phút cho ngấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (918, '2025-11-20 17:10:09.825063', '2025-11-20 17:10:09.825063', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 173, 1, 'Tôm cắt bỏ râu, rút chỉ đen ở lưng rồi rửa sạch, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (1216, '2025-11-20 17:10:16.129486', '2025-11-20 17:10:16.129486', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 217, 6, '[Caption]', 10);
INSERT INTO public.recipe_steps VALUES (920, '2025-11-20 17:10:09.829342', '2025-11-20 17:10:09.829342', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 173, 7, 'Yêu cầu thành phẩm: Tôm vỏ săn giòn tươm mỡ đỏ, màu au quyện với thịt ba chỉ béo ngậy, dậy mùi thơm của hành, vị mặn ngọt đậm đà. Món dân dã này ăn cùng vài ba quả cà muối, bát canh bầu nấu đầu tôm rất ''''đưa cơm'''' trong ngày hè.', 10);
INSERT INTO public.recipe_steps VALUES (921, '2025-11-20 17:10:09.832032', '2025-11-20 17:10:09.832032', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 173, 3, 'Hành lá rửa sạch thái khúc 3cm, hành củ bóc vỏ thái nhỏ, ớt thái lát (tùy chọn).', 10);
INSERT INTO public.recipe_steps VALUES (922, '2025-11-20 17:10:09.834151', '2025-11-20 17:10:09.834151', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 173, 6, 'Rang tôm lần 2 cùng với thịt ba chỉ cho đậm vị. Tôm sau khi ráo nước thì cho thịt ba chỉ, hành khô vào đảo cùng. Thịt ba chỉ tươm mỡ quyện vào giúp cho vỏ tôm óng đẹp mà không bị khô. Khi tôm và thịt săn lại, dậy mùi thơm từ hành củ thì nêm 1 thìa canh đường, 1 thìa canh nước hàng đảo đều. Sau đó, cho 2 thìa canh nước mắm, 1/2 thìa canh hạt nêm, 1/2 thìa canh hạt tiêu đảo đều cho tôm và thịt đượm vị mặn ngọt. Nêm nếm theo khẩu vị gia đình. Cuối cùng thêm hành lá cắt khúc, đảo qua và tắt bếp, múc ra thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (923, '2025-11-20 17:10:09.836739', '2025-11-20 17:10:09.836739', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 173, 4, 'Cho chút dầu ăn vào chảo, trút thịt ba chỉ vào rang cho tới khi xém cạnh và ra bớt mỡ. Múc thịt ra để riêng, còn mỡ trong chảo chừa lại khoảng 2 - 3 thìa để rang tôm.', 10);
INSERT INTO public.recipe_steps VALUES (924, '2025-11-20 17:10:09.839511', '2025-11-20 17:10:09.839511', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 173, 5, 'Rang tôm cần rang 2 lần lửa mới săn giòn và đậm vị. Ở lần 1 rang cho tôm ráo nước: Cho tôm vào chảo vừa rang thịt ở trên, đảo đều tay liên tục cho tới khi tôm ráo nước, vỏ chuyển màu hồng giòn. Chú ý không cho muối hay mắm ở lúc này vì vị mặn sẽ khiến cho tôm ra nước và lâu khô.', 10);
INSERT INTO public.recipe_steps VALUES (925, '2025-11-20 17:10:10.018473', '2025-11-20 17:10:10.018473', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 174, 3, 'Chuối xanh lấy 4 quả tước vỏ, thái con chì ngâm vào nước pha nước cốt chanh loãng hoặc nước vôi trong sẽ giúp chuối không bị thâm đen. Vớt ra để ráo, ướp chút mắm, muối, gia vị, 1/2 lượng mẻ, 1/2 nước cốt nghệ.', 10);
INSERT INTO public.recipe_steps VALUES (926, '2025-11-20 17:10:10.020062', '2025-11-20 17:10:10.020062', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 174, 7, 'Phi thơm hành khô với mỡ lợn, cho thịt ba chỉ, chuối thái con chì, chuối xay nhuyễn vào, thêm nước luộc ốc, nước sôi vừa đủ. Đun sôi rồi hạ lửa nhỏ vừa để om thịt, chuối trong 15 - 20 phút cho thịt mềm. Khi nước sốt sánh lại thì mới cho ốc và đậu phụ rán vàng vào, om tiếp 4-5 phút cho ngấm, nêm lại theo khẩu vị gia đình. Thêm hành lá, tía tô, lá lốt vào đảo đều, tắt bếp, múc ra thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (927, '2025-11-20 17:10:10.023064', '2025-11-20 17:10:10.023064', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 174, 6, 'Thịt ba chỉ thái con chì, cho vào chảo đảo cho xém cạnh, ướp với 1 thìa canh nước mắm, 1 thì cà phê mắm tôm, 1/2 thìa cà phê hạt  nêm, 1/2 thìa cà phê hạt tiêu và 1/2 mẻ, 1/2 nước cốt nghệ còn lại, đảo đều và ướp khoảng 15- 20 phút cho thấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (928, '2025-11-20 17:10:10.027591', '2025-11-20 17:10:10.027591', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 174, 8, 'Yêu cầu thành phẩm: Ốc giòn sần sật, chuối mềm bùi bùi quyện thịt ba chỉ béo ngậy, nước sóng sánh vàng ăn cùng bún hay cơm trắng đều rất hao.', 10);
INSERT INTO public.recipe_steps VALUES (929, '2025-11-20 17:10:10.030618', '2025-11-20 17:10:10.030618', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 174, 5, 'Đậu phụ cắt miếng vừa ăn, chiên giòn.', 10);
INSERT INTO public.recipe_steps VALUES (930, '2025-11-20 17:10:10.032619', '2025-11-20 17:10:10.032619', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 174, 1, 'Ngâm ốc với nước vo gạo trong thau kim loại, kèm vài lát ớt vừa giúp nhả bùn nhanh, vừa ăn nước vo gạo nên ốc béo hơn. Sau đó, rửa sạch và luộc sơ trong một phút từ khi sôi, đảo đều cho bong mày (vẩy) ốc thì vớt ra, khều phần thịt, bỏ ruột đen, rửa sạch. Lọc lấy phần nước luộc ốc trong.', 10);
INSERT INTO public.recipe_steps VALUES (931, '2025-11-20 17:10:10.036598', '2025-11-20 17:10:10.036598', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 174, 2, 'Mẻ lọc qua rây cho mịn, nghệ tươi thêm chút giấm hoặc chanh giã vắt lấy nước sẽ giữ màu vàng ươm.', 10);
INSERT INTO public.recipe_steps VALUES (932, '2025-11-20 17:10:10.039408', '2025-11-20 17:10:10.039408', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 174, 4, 'Lấy hai quả chuối xanh còn lại luộc chín, bóc vỏ, xay cùng chút nước cho nhuyễn. Đây là bí quyết cho vào cuối để giúp tạo độ sóng sánh tự nhiên mà không cần dùng bột năng.', 10);
INSERT INTO public.recipe_steps VALUES (933, '2025-11-20 17:10:10.230485', '2025-11-20 17:10:10.230485', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 175, 4, 'Cho ngô ngọt, cà rốt vào nước luộc gà đun sôi cho chín mềm. Chú ý hớt bỏ bọt để nước dùng được trong.', 10);
INSERT INTO public.recipe_steps VALUES (934, '2025-11-20 17:10:10.232617', '2025-11-20 17:10:10.232617', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 175, 6, 'Cho bột năng, bột bắp trộn chung, thêm chút nước lọc, khuấy đều cho tan. Sau đó, đổ từ từ vào nồi súp gà, vừa đổ vừa khuấy đều theo chiều kim đồng hồ để không bị vón cục. Điều chỉnh độ loãng, đặc theo sở thích bằng cách tăng lượng bột năng và bột bắp. Khi nồi súp gà sóng sánh, chuyển màu trắng trong như ý muốn thì dừng lại, hạ lửa nhỏ đun thêm vài phút. Đánh lòng trắng trứng gà và vừa cho vào nồi súp, vừa khuấy theo chiều kim đồng hồ để tạo hình vân như mây trắng đẹp mắt. Thêm rau mùi, hành lá khuấy đều và tắt bếp, múc ra thêm chút hạt tiêu và thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (935, '2025-11-20 17:10:10.235724', '2025-11-20 17:10:10.235724', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 175, 7, 'Yêu cầu thành phẩm: Thịt gà mềm, ngô ngọt xen kẽ nấm rơm thanh, trứng cút bùi bùi quyện trong nước súp sóng sánh hấp dẫn. Món súp để lâu vẫn không bị tách nước.', 10);
INSERT INTO public.recipe_steps VALUES (936, '2025-11-20 17:10:10.237918', '2025-11-20 17:10:10.237918', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 175, 2, 'Luộc gà cùng với vài củ hành tím, 1 thìa cà phê muối, 1 thìa cà phê hạt nêm. Khi sôi hớt bỏ bọt, hạ lửa nhỏ vừa luộc trong 10-15 phút, tắt bếp, đậy vung om thêm 10 - 15 phút cho gà ngậm nước sẽ ngọt mềm hơn. Vớt gà ra xé sợi. Phần xương gà cho vào ninh cho ngọt nước, lọc lấy nước dùng để nấu súp.', 10);
INSERT INTO public.recipe_steps VALUES (937, '2025-11-20 17:10:10.240338', '2025-11-20 17:10:10.240338', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 175, 3, 'Ngô ngọt tách lấy hạt, rửa sạch, bỏ mày (vảy). Cà rốt bào bỏ vỏ, cắt hạt lựu. Trứng cút luộc chín, ngâm nước lạnh rồi bóc bỏ vỏ. Nấm rơm ngâm nước muối loãng, xé sợi nhỏ. Hành lá, rau mùi rửa sạch, thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (938, '2025-11-20 17:10:10.24249', '2025-11-20 17:10:10.24249', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 175, 5, 'Tiếp tục cho cà xé sợi, nấm hương, trứng cút vào và nêm nếm gia vị mắm, muối, hạt nêm cho vừa miệng.', 10);
INSERT INTO public.recipe_steps VALUES (1217, '2025-11-20 17:10:16.131063', '2025-11-20 17:10:16.131063', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 217, 8, '[Caption]', 10);
INSERT INTO public.recipe_steps VALUES (940, '2025-11-20 17:10:10.342677', '2025-11-20 17:10:10.342677', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 176, 2, 'Thịt ba chỉ chọn nạc mỡ đan xen, cắt miếng vừa ăn rồi ướp 1 thìa canh mật mía, 1 thìa cà phê muối. Nếu có hành tăm (củ nén) là chuẩn vị Nghệ An. Nếu không dùng hành khô rửa sạch, giữ cả vỏ hành để kho theo cách xưa. Vỏ hành vừa giúp cá lên màu óng đẹp, khi ăn cảm nhận được vị dai dai, thấm vị ngọt béo từ thịt cá.', 10);
INSERT INTO public.recipe_steps VALUES (941, '2025-11-20 17:10:10.347725', '2025-11-20 17:10:10.347725', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 176, 1, 'Cá trắm làm sạch, cạo bỏ hết màng đen trong bụng. Dùng muối hạt và chanh chà xát để khử tanh, dùng nước vo gạo rửa sạch, để ráo nước. Ướp cá với 1 thìa canh muối hạt để giúp cá đanh lại, đậm vị hơn khi kho.', 10);
INSERT INTO public.recipe_steps VALUES (942, '2025-11-20 17:10:10.350344', '2025-11-20 17:10:10.350344', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 176, 4, 'Để có món cá kho ngon nên kho 2 - 3 lần lửa. Kho lửa 1: Lót dưới đáy nồi lớp vỏ hành khô, hành tăm hoặc lá chè xanh, rồi xếp cá và thịt ba chỉ xen kẽ. Đổ hết phần nước ướp cá vào. Ban đầu bật lửa vừa cho cá sôi và kho trong 5 - 6 phút. Nêm nếm lại gia vị cho phù hợp. Sau đó, hạ lửa nhỏ liu riu. Lúc này nước mật mía, nước mắm và độ nóng lan tỏa giúp cá từ từ tiết nước ra, hòa quyện vào nhau đượm vị mặn ngọt. Sau 40 - 45 phút thì tắt bếp để nguội giúp cho ''''cá hồi'''' và săn lại. Ở lần kho lửa 2,3 cũng tương tự, thỉnh thoảng múc nước kho rưới lên mặt để ngấm đều vị, Kho lửa liu riu cho tới khi cá săn chắc nịch, nước kho sánh lại, óng lên màu nâu đỏ như vân gỗ đẹp mắt. Vỏ hành khô cũng kết dẻo lại màu nâu đỏ hấp dẫn. Dù không dùng nước màu hay nước dừa nhưng mật mía kết hợp nước mắm cứ nhẩn nha thẩm thấm vào từng thớ thịt cá để tươm ra thứ màu cuốn hút. Để cá bóng đẹp thì khi kho gần xong, mở vung cho se lại, rưới thêm chút mỡ nước hoặc dầu ăn.', 10);
INSERT INTO public.recipe_steps VALUES (943, '2025-11-20 17:10:10.353036', '2025-11-20 17:10:10.353036', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 176, 3, 'Ướp cá với 1/2 chén (bát nhỏ) mật mía,  4 - 5 thìa canh nước mắm cốt ngon, 1 thìa cà phê hạt nêm, 1 thìa cà phê hạt tiêu xay và hạt tiêu sọ, ớt ướp tối thiểu trong 1 giờ.', 10);
INSERT INTO public.recipe_steps VALUES (944, '2025-11-20 17:10:10.453261', '2025-11-20 17:10:10.453261', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 177, 1, 'Lá chè xanh rửa sạch, vẩy ráo. Hành lá để riêng phần trắng, phần lá xanh thái nhỏ. Hành khô rửa sạch, giữ vỏ hành.', 10);
INSERT INTO public.recipe_steps VALUES (945, '2025-11-20 17:10:10.455368', '2025-11-20 17:10:10.455368', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 177, 3, 'Cá nục làm sạch, ngâm nước muối loãng hoặc nước trà xanh để khử tanh, rửa sạch, để ráo nước. Đeo găng tay thoa đều hỗn hợp hành, ớt, tỏi giã nhuyện với cá nục. Thêm 3 thìa canh nước mắm, 1 thìa cà phê đường, 1 thìa cà phê hạt nêm, 1 thìa cà phê hạt nêm, 1 thìa cà phê hạt tiêu, ướp tối thiểu trong 1 giờ cho thấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (946, '2025-11-20 17:10:10.457517', '2025-11-20 17:10:10.457517', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 177, 4, 'Phi thơm đầu hành trắng, cho nước dừa tươi vào nấu sôi. Nước chêm vào kho cá bắt buộc phải là nước nóng thì cá kho mới không bị tanh. Kho lửa 1: Xếp vỏ hành củ, lá chè xanh dưới đáy nồi gang hoặc nồi đất, rồi xếp cá xen kẽ thịt ba chỉ vào nồi. Trên cùng, thêm vài quả ớt tươi rồi chêm 1/2 lượng nước dừa tươi xâm xấp mặt cá và bật bếp cho sôi thì hạ lửa nhỏ liu riu, nêm nếm lại gia vị vừa miệng. Kho cho tới khi nước cạn 1/3 thì tiếp tục chêm 1/2 phần nước dừa còn lại vào kho tiếp lửa 2. Thỉnh thoảng múc nước kho rưới đều lên để cá kho đều vị. Khi nước kho sền sệt thì rưới 1-2 thìa canh mỡ lợn, thêm tóp mỡ đảo đều để cá lên màu bóng đẹp.', 10);
INSERT INTO public.recipe_steps VALUES (947, '2025-11-20 17:10:10.45912', '2025-11-20 17:10:10.45912', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 177, 2, 'Giã nhuyễn tỏi, hành khô, ớt với 1-2 thìa cà phê muối hạt.', 10);
INSERT INTO public.recipe_steps VALUES (948, '2025-11-20 17:10:10.461222', '2025-11-20 17:10:10.461222', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 177, 5, 'Yêu cầu thành phẩm: Cá bên ngoài săn lại, bên trong thịt mềm đậm vị, mềm rục xương. Món này ăn cùng cơm nóng, dưa cải chua, cháo trắng đều rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (949, '2025-11-20 17:10:10.585608', '2025-11-20 17:10:10.585608', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 178, 5, 'Yêu cầu thành phẩm: Rau muống xanh non, mềm mướt, dậy mùi thơm của tỏi, chút giòn giòn từ tóp mỡ rất ''''hao cơm'''' nhất là trong những ngày mùa hè.', 10);
INSERT INTO public.recipe_steps VALUES (950, '2025-11-20 17:10:10.588452', '2025-11-20 17:10:10.588452', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 178, 2, 'Ngâm rau muống với nước muối loãng rồi rửa sạch, vớt ra rổ để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (951, '2025-11-20 17:10:10.591134', '2025-11-20 17:10:10.591134', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 178, 1, 'Rau muống ngắt bỏ cọng cứng và phần lá già vàng gần gốc. Nên chọn rau muống nước sẽ mềm và xanh khi xào.', 10);
INSERT INTO public.recipe_steps VALUES (952, '2025-11-20 17:10:10.593787', '2025-11-20 17:10:10.593787', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 178, 4, 'Nhiều người dân miền Trung xào rau muống bằng nồi, chính độ nóng và kín của nồi sẽ giữ được nhiệt lớn được lâu nên giúp rau xào xanh mềm. Cách làm: Cho mỡ lợn vào nồi, khi mỡ nóng già thì cho phần tỏi băm nhỏ vào phi thơm. Lúc này, tăng nhiệt độ bếp lên cao, nhanh tay cho tất cả rau muống vào nồi, thêm chút nước và 1,5 thìa cà phê muối tinh vào và đậy nắp nồi lại trong 1-1,5 phút tùy rau muống non hay già. Sau đó, mở nắp nồi, dùng đũa lật trở lớp rau để chín đều. Cho phần tỏi đập dập vào đảo đều, nêm nếm lại gia vị (muối, mắm tôm tùy chọn theo khẩu vị, hạt nêm), tóp mỡ, đảo đều cho rau muống ngậm tròn gia vị, tắt bếp và múc ra thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (953, '2025-11-20 17:10:10.596433', '2025-11-20 17:10:10.596433', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 178, 3, 'Tỏi là gia vị làm nên hương thơm đặc trưng cho món rau muống xào. Tùy theo sở thích, bạn điều chỉnh nhiều hay ít. Chia đôi một phần băm nhỏ để phi thơm xào và một phần đập dập phần tép.', 10);
INSERT INTO public.recipe_steps VALUES (954, '2025-11-20 17:10:10.804765', '2025-11-20 17:10:10.804765', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 179, 7, 'Rau cần nhặt bỏ rễ, bỏ bớt lá, ngâm nước vo gạo hoặc nước muối loãng, rửa sạch lại, để ráo, bóp nhẹ cho ra tinh dầu (giúp rau mềm thơm hơn), vặn thành từng đoạn 4 - 5cm.', 10);
INSERT INTO public.recipe_steps VALUES (994, '2025-11-20 17:10:11.717248', '2025-11-20 17:10:11.717248', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 184, 5, 'Phi thơm tỏi với dầu ô liu, cho hành vào xào thơm rồi cho cà chua vào xào mềm. Nêm vào 2 muỗng canh tương cà chua, 2 muỗng cà phê muối, 2 muỗng cà phê đường, 1 muỗng cà phê giấm, lá oregano, basil, chút hạt tiêu đảo đều.', 10);
INSERT INTO public.recipe_steps VALUES (1566, '2025-11-20 17:10:22.569318', '2025-11-20 17:10:22.569318', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 261, 2, 'Gia vị: hạt nêm, muối, tiêu, đường, nước tương, dầu hào, dầu ăn.', 10);
INSERT INTO public.recipe_steps VALUES (955, '2025-11-20 17:10:10.806895', '2025-11-20 17:10:10.806895', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 179, 1, 'Cá rô đồng đánh sạch vẩy, giữ vây để khi luộc gỡ xương cho dễ. Mổ cá dọc giữa bụng, bỏ ruột, giữ trứng nếu có. Cho cá vào âu hộp thêm chút muối, chanh vào xóc đều để loại bỏ nhớt. Đeo găng tay rửa sạch. Đun sôi nước cùng vài lát gừng già, hành củ khô đập dập và chút muối hạt. Cho cá vào, khi nước sôi trở lại thì hớt bỏ bọt, hạ lửa nhỏ vừa, đun trong 3 - 4 phút tùy lượng cá nhiều hay ít. Kiểm tra cá chín bằng cách bẻ đầu cá gãy được là cá chín vừa độ. Tắt bếp, vớt cá ra ngâm nước đá lạnh cho nguội và hãm nhiệt để gỡ thịt cá dễ dàng hơn.', 10);
INSERT INTO public.recipe_steps VALUES (956, '2025-11-20 17:10:10.810104', '2025-11-20 17:10:10.810104', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 179, 4, 'Nét khác biệt và nguyên bản của canh cá Quỳnh Côi, Thái Bình là thịt cá dai, đậm vị bởi đã được rim lâu trên lửa nhỏ, chứ không phải chiên giòn như cách nấu của một số vùng khác. Cách làm: phi thơm hành, cho cá đã ướp vào, hạ lửa nhỏ rim tối thiểu 1 giờ. Khi nước rút hết, miếng cá săn lại, ngả màu vàng nâu, bề mặt hơi sem sém và dai nhưng bên trong vẫn mềm ngon là đạt.', 10);
INSERT INTO public.recipe_steps VALUES (957, '2025-11-20 17:10:10.812248', '2025-11-20 17:10:10.812248', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 179, 5, 'Cà chua rửa sạch, thái múi cau. Hành lá, thì là rửa sạch, thái khúc.', 10);
INSERT INTO public.recipe_steps VALUES (958, '2025-11-20 17:10:10.814395', '2025-11-20 17:10:10.814395', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 179, 6, 'Nước dùng canh cá Quỳnh Côi thoảng mùi cá, mang vị ngọt thanh đạm, là sự kết hợp của nước hầm xương lợn và cá. Để khử mùi tanh thì từ khi luộc cá bắt buộc nước phải sôi mới cho cá vào. Sau khi gỡ thì cho phần đầu cá, xương sống lưng cá vào hầm, thêm gừng và hành khô nướng thơm, rửa sạch cho vào để đảm bảo mùi thơm. Khi ninh, tránh khuấy nát cá làm nước đục, thỉnh thoảng hớt bỏ bọt. Sau đó, lọc nước dùng cá hòa cùng nước hầm xương đã lọc. Phi thơm hành, cho ít cà chua vào xào sơ tạo màu cho vào nước dùng. Nêm nếm lại nước mắm cốt, muối, hạt nêm cho vừa khẩu vị.', 10);
INSERT INTO public.recipe_steps VALUES (959, '2025-11-20 17:10:10.815986', '2025-11-20 17:10:10.815986', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 179, 2, 'Cách gỡ thịt cá:Đặt cá lên lòng bàn tay, tay kia lẩy nhẹ vuốt bỏ vây lưng, vây bụng. Sau đó, nhẹ nhàng tách thịt cá ra khỏi xương. Nhặt bỏ xương giữa và bụng trồi lên trong lòng mỗi mặt cá. Làm lần lượt cho tới hết. Phần đầu cá, xương sống lưng cá giữ lại ninh làm nước dùng cùng xương heo; còn xương vây dính chút thịt thì băm nhuyễn trộn cùng thịt xay, thì là, băm nhỏ, thêm mắm muối làm chả viên, chiên chín vàng là được.', 10);
INSERT INTO public.recipe_steps VALUES (960, '2025-11-20 17:10:10.818827', '2025-11-20 17:10:10.818827', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 179, 8, 'Chần sơ rau cần, bánh đa Quỳnh Côi cho vào bát tô. Cho cá, trứng cá đã rim lên trên. Múc nước dùng nóng chan vào. Rắc chút hành lá, thì là, thêm vài ba lát ớt, chút hạt tiêu (nếu thích ăn cay) và thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (961, '2025-11-20 17:10:10.820945', '2025-11-20 17:10:10.820945', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 179, 3, 'Ướp phần thịt cá với 2 muỗng canh nước mắm cốt ngon, 2 muỗng canh nước cốt nghệ giã nhỏ, 1 muỗng canh dầu màu điều, 1 thìa cà phê muối, 1 thìa cà phê hạt nêm, 1 thìa cà phê hạt tiêu cùng chút hành khô băm nhỏ tối thiểu 1 giờ cho ngấm trọn vị.', 10);
INSERT INTO public.recipe_steps VALUES (962, '2025-11-20 17:10:10.822559', '2025-11-20 17:10:10.822559', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 179, 9, 'Yêu cầu thành phẩm: thịt cá dai đậm vị mà không khô, màu nâu đỏ bắt mắt, nước dùng thanh đạm, điểm xuyết rau xanh non, bánh đa trắng… tất cả hòa quyện như bức họa đồng quê đa sắc màu, đánh thức vị giác của thực khách ngay lần đầu thưởng thức. Để rồi mọi dư vị dân dã, đồng quê cứ thế nhẩn nha, thêm yêu hơn nét giản dị, ngọt lành ấy.', 10);
INSERT INTO public.recipe_steps VALUES (963, '2025-11-20 17:10:10.919008', '2025-11-20 17:10:10.919008', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 180, 4, 'Đậu phụ cắt miếng vuông hoặc miếng dài vừa ăn, rán vàng.', 10);
INSERT INTO public.recipe_steps VALUES (964, '2025-11-20 17:10:10.921142', '2025-11-20 17:10:10.921142', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 180, 5, 'Cà chua rửa sạch, thái múi cau. Hành lá, tía tô, lá lốt rửa sạch thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (965, '2025-11-20 17:10:10.923287', '2025-11-20 17:10:10.923287', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 180, 1, 'Mẻ lọc qua rây. Nghệ tươi rửa sạch, giã nhỏ, thêm chút giấm hoặc chanh lọc lấy nước (bí quyết này giúp nước nghệ vàng tươi hơn, dễ rửa cối sạch hơn sau khi giã không còn ám vàng).', 10);
INSERT INTO public.recipe_steps VALUES (966, '2025-11-20 17:10:10.926172', '2025-11-20 17:10:10.926172', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 180, 7, 'Sau đó, cho cà chua, đậu phụ chiên vào om thêm 7 - 10 phút thì nêm nếm lại gia vị vừa miệng. Cuối cùng rắc thêm hành lá, tía tô, lá lốt đảo đều và tắt bếp, múc ra thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (967, '2025-11-20 17:10:10.928311', '2025-11-20 17:10:10.928311', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 180, 3, 'Thịt ba chỉ thái miếng vừa ăn, cho vào chảo đảo cho xém cạnh. Sau đó, ướp 2 thìa cà phê nước mắm, 1 thìa cà phê mắm tôm, 1/2 thìa cà phê hạt nêm, 1/2 nước cốt nghệ đảo đều cho thấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (968, '2025-11-20 17:10:10.93099', '2025-11-20 17:10:10.93099', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 180, 6, 'Phi thơm hành khô, tỏi cho thịt ba chỉ, cà tím đã ướp vào đảo săn, rồi thêm lượng nước xâm xấp, om 15 - 20 phút cho thịt và cà mềm.', 10);
INSERT INTO public.recipe_steps VALUES (969, '2025-11-20 17:10:10.933408', '2025-11-20 17:10:10.933408', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 180, 8, 'Yêu cầu thành phẩm: Cà tím mềm ngọt quyện thịt béo ngậy, đậu phụ bùi bùi, nước canh sóng sánh ánh vàng giúp bữa ăn ngày chớm hè trở nên ngon miệng, bổ dưỡng.', 10);
INSERT INTO public.recipe_steps VALUES (970, '2025-11-20 17:10:10.93563', '2025-11-20 17:10:10.93563', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 180, 2, 'Cà tím gọt bỏ cuống, bổ múi cau rồi ngâm vào nước muối loãng pha chút giấm hoặc nước cốt chanh trong 30 phút cho hết nhựa và trắng, không bị thâm. Vớt ra rửa sạch, để ráo. Ướp cà tím với 1/2 nước cốt nghệ, 1 thìa canh mẻ, 1 thìa canh nước mắm, 1/2 thìa cà phê muối, đảo đều để trong 10 - 15 phút để ngấm gia vị giúp cà đậm đà hơn khi ăn và lên màu vàng đẹp mắt.', 10);
INSERT INTO public.recipe_steps VALUES (971, '2025-11-20 17:10:11.033217', '2025-11-20 17:10:11.033217', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 181, 4, 'Đun nóng dầu ăn, cho cá vào rán sơ để khử tanh, vớt ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (995, '2025-11-20 17:10:11.719566', '2025-11-20 17:10:11.719566', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 184, 7, 'Phi thơm tỏi cùng bơ, cho thịt bò vào xào săn trên lửa lớn. Sau đó thêm hỗn hợp sốt cà chua vào đảo đều. Nêm nếm lại gia vị, khuấy đều sốt với thịt trở nên hơi sền sệt là được.', 10);
INSERT INTO public.recipe_steps VALUES (1567, '2025-11-20 17:10:22.571445', '2025-11-20 17:10:22.571445', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 261, 9, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (972, '2025-11-20 17:10:11.035891', '2025-11-20 17:10:11.035891', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 181, 5, 'Phi thơm hành khô, cho phần cà chua băm nhuyễn vào, thêm 1 thìa cà phê muối, chút nước để xào cà chua nhanh mềm. Đun sôi nước với lượng vừa đủ, cho phần cà chua đã xào mềm lọc qua rây để lấy màu cho vào nước canh để lấy màu đỏ đẹp mắt, bỏ phần xác. Đun sôi nồi nước dùng này, cho cá vào đun trên lửa nhỏ 15 - 20 phút là cá chín. Thêm 3 - 4 thìa canh mẻ, thêm phần cà chua thái múi cau còn lại vào. Nêm nếm mắm, muối, hạt nêm phù hợp khẩu vị và đun vài phút. Cuối cùng, thêm hành lá, thì là, ớt rồi tắt bếp, múc ra thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (973, '2025-11-20 17:10:11.039111', '2025-11-20 17:10:11.039111', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 181, 2, 'Cà chua một nửa thái múi cau, nửa còn lại thì băm nhỏ để xào tạo màu. Hành lá, thì là rửa sạch, cắt khúc. Hành khô thái lát. Ớt thái lát (nếu ăn được cay).', 10);
INSERT INTO public.recipe_steps VALUES (974, '2025-11-20 17:10:11.041242', '2025-11-20 17:10:11.041242', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 181, 1, 'Cá làm sạch, chà xát muối hạt, chanh khử mùi, rửa sạch, để ráo nước. Ướp cá với 1 thìa cà phê muối, 1/2 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu trong 15 - 20 phút cho thấm vị.', 10);
INSERT INTO public.recipe_steps VALUES (975, '2025-11-20 17:10:11.043403', '2025-11-20 17:10:11.043403', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 181, 6, 'Yêu cầu thành phẩm: Thịt cá ngọt mềm tự nhiên, nước canh chua thanh từ mẻ, màu đỏ bắt mắt từ cà chua rất bắt mắt.', 10);
INSERT INTO public.recipe_steps VALUES (976, '2025-11-20 17:10:11.045535', '2025-11-20 17:10:11.045535', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 181, 3, 'Mẻ lọc qua rây khoảng 3 - 4 thìa canh.', 10);
INSERT INTO public.recipe_steps VALUES (977, '2025-11-20 17:10:11.491964', '2025-11-20 17:10:11.491964', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 182, 2, 'Hành khô, tỏi, gừng, ớt băm nhỏ. Hạt tiêu sọ giã dập sơ.', 10);
INSERT INTO public.recipe_steps VALUES (978, '2025-11-20 17:10:11.494089', '2025-11-20 17:10:11.494089', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 182, 3, 'Pha hỗn hợp ướp sốt gà gồm: 3 muỗng canh tương cà, 3 muỗng canh tương ớt, 2 muỗng canh tiêu sọ đen, 2 muỗng canh đường (điều chỉnh theo khẩu vị), 2 muỗng canh nước mắm, 2 muỗng canh tỏi băm, 2 muỗng canh hành tím băm, 2 muỗng canh dầu màu điều, 1 muỗng canh dầu hào, 1 muỗng canh nước mắm, 1 muỗng canh mạch nha (tùy chọn), 1 muỗng canh sốt xá xíu (tùy chọn), 1/2 muỗng canh hạt nêm, 1 muỗng cà phê muối, 1 muỗng cà phê tiêu bột, 1 muỗng cà phê gừng băm nhỏ. Trộn đều hỗn hợp sánh sệt, múc riêng ra 1/3 để phết sau khi nướng giúp lên màu đẹp.', 10);
INSERT INTO public.recipe_steps VALUES (979, '2025-11-20 17:10:11.495697', '2025-11-20 17:10:11.495697', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 182, 7, 'Để giúp gà se mặt, nước sốt sánh và lên màu vàng óng đẹp mặt thì tiếp tục cho gà vào nướng 10 phút là được.', 10);
INSERT INTO public.recipe_steps VALUES (980, '2025-11-20 17:10:11.497305', '2025-11-20 17:10:11.497305', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 182, 4, 'Đeo găng tay, lấy 2/3 hỗn hợp nước sốt trên thoa đều các mặt thịt gà, bọc kín cho vào ngăn mát tủ lạnh để ướp tối thiểu 1 tiếng cho ngấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (981, '2025-11-20 17:10:11.498932', '2025-11-20 17:10:11.498932', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 182, 5, 'Bọc từng đùi gà trong giấy bạc, gập các mép kín lại. Sau đó, cho gà vào lò nướng ở 2 lửa, trong 40 phút ở nhiệt độ 190 - 200 độ C.', 10);
INSERT INTO public.recipe_steps VALUES (982, '2025-11-20 17:10:11.500532', '2025-11-20 17:10:11.500532', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 182, 8, 'Yêu cầu thành phẩm: Thịt gà da vàng óng, bên trong mềm ngọt, mọng nước quyện trong nước sốt sánh, dậy mùi thơm nồng, cay cay của tiêu đen rất hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (983, '2025-11-20 17:10:11.502144', '2025-11-20 17:10:11.502144', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 182, 6, 'Lấy gà ra, mở giấy bạc, đổ bớt nước tiết khi nướng ra. Phết 1/3 hỗn hợp nước sốt ướp còn lại lên khắp đùi gà.', 10);
INSERT INTO public.recipe_steps VALUES (984, '2025-11-20 17:10:11.504509', '2025-11-20 17:10:11.504509', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 182, 1, 'Thịt đùi gà làm sạch, chà xát chanh, muối hạt (hoặc chà xát gừng giã dập, rượu trắng) để khử mùi. Sau đó, rửa sạch, thấm khô hoặc để ráo nước. Dùng dao khía nhẹ vào đằng sau đùi gà để giúp thấm gia vị cũng như chín nhanh hơn.', 10);
INSERT INTO public.recipe_steps VALUES (985, '2025-11-20 17:10:11.568162', '2025-11-20 17:10:11.568162', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 183, 1, 'Sơ chế: Ba chỉ chọn phần nạc mỡ đan xen (dọi quế), rửa sạch, bỏ bì, thái các miếng vừa ăn cỡ 0,4- 0,5cm. Hành lá rửa sạch thái khúc, hành khô thái lát mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (986, '2025-11-20 17:10:11.570863', '2025-11-20 17:10:11.570863', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 183, 2, 'Rang thịt xém cạnh: Cho một thìa dầu ăn vào chảo lắc đều và đun nóng. Sau đó cho thịt vào đảo đều cho tới khi chảy bớt mỡ và các bề mặt thịt xém cạnh, chắt bớt mỡ ra.', 10);
INSERT INTO public.recipe_steps VALUES (987, '2025-11-20 17:10:11.57305', '2025-11-20 17:10:11.57305', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 183, 4, 'Yêu cầu thành phẩm: Thịt ba chỉ xém cạnh quyện đậm đà vị mặn ngọt, dậy mùi thơm của hành khô, hành lá. Món ăn bình dân này đơn giản mà hao cơm vào bất kể mùa nào trong năm.', 10);
INSERT INTO public.recipe_steps VALUES (988, '2025-11-20 17:10:11.575692', '2025-11-20 17:10:11.575692', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 183, 3, 'Nêm nếm gia vị: Cho 2 thìa canh nước mắm, 1 thìa canh đường, 1 thìa canh nước hàng đảo đều trên lửa nhỏ vừa cho gia vị ngấm đều vào thịt. Sau vài phút thì thêm hành khô đảo đều. Khi gia vị quyện đều, ánh lên màu vàng nâu đẹp mắt thì thêm hạt nêm, hành lá cắt khúc và tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (989, '2025-11-20 17:10:11.707106', '2025-11-20 17:10:11.707106', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 184, 8, 'Luộc mỳ spaghetti theo hướng dẫn trên bao bì trong 8-10 phút cùng chút muối và dầu ăn.', 10);
INSERT INTO public.recipe_steps VALUES (990, '2025-11-20 17:10:11.709232', '2025-11-20 17:10:11.709232', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 184, 4, 'Ướp thịt bò xay với chút muối, đường, hạt tiêu cho ngấm gia vị trong 15 phút.', 10);
INSERT INTO public.recipe_steps VALUES (991, '2025-11-20 17:10:11.711353', '2025-11-20 17:10:11.711353', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 184, 6, 'Cho hỗn hợp trên vào máy xay nhuyễn là đã được sốt cà chua đỏ tươi, sánh mượt chuẩn vị như người bản xứ cho các món như mỳ spaghetti, bánh pizza. Tranh thủ cà chua đang vào mùa mọng ngon và rẻ nên làm nhiều và tích trữ trong tủ lạnh dùng dần.', 10);
INSERT INTO public.recipe_steps VALUES (992, '2025-11-20 17:10:11.713541', '2025-11-20 17:10:11.713541', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 184, 1, 'Để có món mỳ Ý thơm ngon lên màu đẹp, nên chọn những quả cà chua chín đỏ tự nhiên, tròn trịa, vỏ căng bóng, núm còn xanh, thoảng mùi thơm tự nhiên. Đây là những quả cà nhiều bột thịt mịn, mọng nước và ngon.', 10);
INSERT INTO public.recipe_steps VALUES (993, '2025-11-20 17:10:11.715115', '2025-11-20 17:10:11.715115', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 184, 3, 'Bằm nhỏ cà chua. Hành tây bóc bỏ vỏ, cắt hạt lựu nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (996, '2025-11-20 17:10:11.721698', '2025-11-20 17:10:11.721698', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 184, 9, 'Cho mỳ ra đĩa, múc sốt cà chua thịt rưới đều lên trên, rắc thêm chút phô mai bào nếu thích và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (998, '2025-11-20 17:10:11.85733', '2025-11-20 17:10:11.85733', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 185, 3, 'Đun nước sôi bùng lên, thêm chút muối hạt và cho rau muống vào chần (trụng) nhanh vài giây với lửa lớn. Nhanh tay vớt rau ra hãm nhiệt bằng nước đá để giúp rau xanh và giòn.', 10);
INSERT INTO public.recipe_steps VALUES (999, '2025-11-20 17:10:11.859478', '2025-11-20 17:10:11.859478', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 185, 5, 'Yêu cầu thành phẩm: Rau muống xào xanh mướt, dậy mùi thơm của tỏi.', 10);
INSERT INTO public.recipe_steps VALUES (1000, '2025-11-20 17:10:11.86106', '2025-11-20 17:10:11.86106', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 185, 2, 'Tỏi bóc vỏ, một nửa băm nhỏ, một nửa thì để nguyên tép, đập dập. Nên chuẩn bị sẵn gia vị xào. Tùy theo khẩu vị mỗi người mà cho muối, mắm. Một số vùng như Thái Bình, Hải Phòng thì nêm mắm tôm hoặc mắm tép, cùng rau ngổ giúp món rau muống xào dậy mùi thơm, rất hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (1001, '2025-11-20 17:10:11.862649', '2025-11-20 17:10:11.862649', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 185, 4, 'Phi thơm phần tỏi băm bằng mỡ lợn, vớt rau muống đã ngâm đá vào xào trên lửa lớn, nhanh tay cho gia vị mắm tôm, dầu hào (tùy theo khẩu vị), hạt nêm. Thêm phần tỏi nguyên tép đã đập dập vào, rau ngổ (tùy chọn), đảo và tắt bếp, múc ra thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1002, '2025-11-20 17:10:11.864775', '2025-11-20 17:10:11.864775', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 185, 1, 'Rau muống nhặt bỏ lá vàng và cọng cứng. Nếu thích ăn giòn thì bỏ bớt lá, giữ cọng non. Ngâm nước muối loãng, rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (1003, '2025-11-20 17:10:11.929347', '2025-11-20 17:10:11.929347', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 186, 3, 'Đun nước sôi bùng lên, thêm chút muối hạt và cho rau muống vào luộc chín tới trên lửa lớn. Nhanh tay vớt rau ra hãm nhiệt bằng nước đá để giúp rau xanh và giòn. Sau đó, vớt ra rổ, ép cho ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (1004, '2025-11-20 17:10:11.930392', '2025-11-20 17:10:11.930392', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 186, 5, 'Yêu cầu thành phẩm: Rau muống xanh non, giòn sần sật quyện lạc rang bùi bùi, vị chua - cay - mặn - ngọt hài hòa làm phong phú thêm thực đơn. Món ăn giản dị này gắn liền với tuổi thơ của nhiều người.', 10);
INSERT INTO public.recipe_steps VALUES (1005, '2025-11-20 17:10:11.932429', '2025-11-20 17:10:11.932429', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 186, 2, 'Lạc rang thơm, xát vỏ, giã dập. Tỏi một phần chiên vàng để rắc thành phẩm, một phần để làm nước trộn. Pha nước trộn nộm gồm 2 thìa canh nước mắm (30-40 độ đạm), 1 thìa canh đường, 1 thìa canh nước lọc, 1 thìa canh nước cốt chanh cùng tỏi, ớt băm nhỏ, khuấy đều cho tan. Hoặc bạn điều chỉnh vị chua - cay - mặn - ngọt theo khẩu vị cá nhân. Các loại rau thơm rửa sạch, vẩy ráo, thái rối.', 10);
INSERT INTO public.recipe_steps VALUES (1006, '2025-11-20 17:10:11.934021', '2025-11-20 17:10:11.934021', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 186, 4, 'Cho rau muống vào âu/tô lớn, thêm nước sốt nộm đã pha, đeo găng tay trộn đều cho ngấm. Sau 8-10 phút thì chắt bớt nước, thêm rau thơm trộn đều. Lấy nộm ra đĩa, rắc lạc rang giã dập, tỏi phi (tùy chọn), trang trí thêm ớt và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (1007, '2025-11-20 17:10:11.936679', '2025-11-20 17:10:11.936679', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 186, 1, 'Rau muống nhặt phần lá ở cuống, để lại ít lá non, cắt khúc hoặc để nguyên tùy chọn.', 10);
INSERT INTO public.recipe_steps VALUES (1008, '2025-11-20 17:10:12.034518', '2025-11-20 17:10:12.034518', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 187, 5, 'Chiên nóng thịt bò: Đun nóng dầu ăn, cho thịt bò vào chiên nhanh trên lửa lớn. Khi thịt xém cạnh, vớt ra ngay. Lúc này thịt bò bên ngoài giòn nhưng bên chín tái, giữ vị ngọt tự nhiên.', 10);
INSERT INTO public.recipe_steps VALUES (1009, '2025-11-20 17:10:12.035555', '2025-11-20 17:10:12.035555', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 187, 4, 'Phi thơm hành, tỏi băm, cho hành tây, ớt chuông vào xào trên lửa lớn, nêm nếm chút gia vị đảo đều và múc ra.', 10);
INSERT INTO public.recipe_steps VALUES (1010, '2025-11-20 17:10:12.038164', '2025-11-20 17:10:12.038164', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 187, 6, 'Phi thơm hành tỏi băm nhỏ, thêm tỏi bỏ vỏ giữ nguyên tép, cho hỗn hợp nước sốt vào, trút thịt bò vào lắc đều trên lửa lớn. Thêm 2 thìa canh bơ vào lắc cho tan chảy, trút hành tây ớt chuông đã xào vào đảo đều, thêm chút hạt tiêu, hành lá lắc đều, tắt bếp và múc ra.', 10);
INSERT INTO public.recipe_steps VALUES (1011, '2025-11-20 17:10:12.040256', '2025-11-20 17:10:12.040256', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 187, 1, 'Thịt thăn bò mềm lọc bỏ gân mỡ, cắt miếng vuông vừa ăn. Ướp thịt bò với 1 muỗng canh xì dầu, 1 muỗng cà phê đường cát vàng, 1 thìa canh rượu nấu ăn (rượu làm dịu vị sắc của xì dầu và giúp thẩm thấu gia vị nhanh hơn), khuấy tan và cho vào thịt đảo đều. Thêm 1 thìa canh dầu ăn để giúp thịt bò mềm. Để ướp trong 10 - 15 phút cho thấm.', 10);
INSERT INTO public.recipe_steps VALUES (1012, '2025-11-20 17:10:12.042361', '2025-11-20 17:10:12.042361', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 187, 2, 'Ớt chuông xanh, đỏ, hành tây rửa sạch, cắt miếng vuông vừa ăn. Hành tím băm nhỏ, tỏi băm nhỏ 1/2, phần còn lại để nguyên tép, hành lá cắt khúc.', 10);
INSERT INTO public.recipe_steps VALUES (1013, '2025-11-20 17:10:12.04448', '2025-11-20 17:10:12.04448', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 187, 7, 'Yêu cầu thành phẩm: Thịt bò bên ngoài giòn, bên trong chín tái ngọt tự nhiên, rau của quả giòn ngon. Món này ăn kèm xà lách, khoai tây chiên rất hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (1014, '2025-11-20 17:10:12.046617', '2025-11-20 17:10:12.046617', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 187, 3, 'Pha hỗn hợp để lắc bò sau khi chiên: 1 muỗng canh xì dầu, 1 muỗng cà phê đường, 1/2 muỗng cà phê hạt tiêu, 1 muỗng cà phê dầu mè, trộn đều để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (1015, '2025-11-20 17:10:12.184268', '2025-11-20 17:10:12.184268', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 188, 1, 'Hành, tỏi bóc vỏ, băm hoặc giã nhuyễn. Ớt một phần băm nhuyễn, một phần để nguyên quả cho vào khi kho.', 10);
INSERT INTO public.recipe_steps VALUES (1016, '2025-11-20 17:10:12.185845', '2025-11-20 17:10:12.185845', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 188, 2, 'Cá lóc làm sạch, chà xát chanh và muối hạt để khử mùi tanh, rửa sạch, để ráo nước. Sau đó, ướp cá với 3 muỗng canh nước mắm ngon (40 độ đạm), 1/2 muỗng canh đường, 1 muỗng cà phê muối, 1 muỗng cà phê hạt nêm, 1 muỗng cà phê hạt tiêu và tỏi, hành băm. Để ướp trong khoảng 20 - 30 phút cho ngấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (1017, '2025-11-20 17:10:12.187446', '2025-11-20 17:10:12.187446', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 188, 4, 'Thêm nước dừa tươi vào xâm xấp mặt cá. Khi sôi thì hạ lửa nhỏ và kho liu riu cho tới lúc gần cạn thì nêm nếm lại gia vị vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1018, '2025-11-20 17:10:12.189675', '2025-11-20 17:10:12.189675', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 188, 6, 'Yêu cầu thành phẩm: Cá săn chắc thịt, vị đậm đà, nước kho sánh sệt, dậy mùi thơm của hạt tiêu, hành lá ăn rất ''''hao cơm'''' vào bất kể mùa nào.', 10);
INSERT INTO public.recipe_steps VALUES (1019, '2025-11-20 17:10:12.1918', '2025-11-20 17:10:12.1918', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 188, 3, 'Cho chút dầu ăn vào chảo, thêm 1 - 2 muỗng canh đường vào thắng nước màu. Khi đường chuyển sang màu hổ phách thì cho cá đã ướp vào đảo đều cho cá săn và nước màu bám đều các mặt.', 10);
INSERT INTO public.recipe_steps VALUES (1022, '2025-11-20 17:10:12.295481', '2025-11-20 17:10:12.295481', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 189, 4, 'Phi thơm hành khô, cho trai vào xào nhanh tay trên lửa lớn. Khi thịt vừa chín thì nhanh tay cho lá lốt vào xào chung, nêm nếm lại gia vị cho phù hợp rồi tắt bếp, múc ra thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1023, '2025-11-20 17:10:12.297704', '2025-11-20 17:10:12.297704', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 189, 5, 'Yêu cầu thành phẩm: Thịt trai chín vừa, giữ độ dai giòn, màu hơi ngả vàng, xen kẽ và dậy mùi thơm của lá lốt, điểm vài lát ớt đỏ tươi đẹp tựa bức tranh đồng quê nhiều hương sắc.', 10);
INSERT INTO public.recipe_steps VALUES (1024, '2025-11-20 17:10:12.299824', '2025-11-20 17:10:12.299824', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 189, 1, 'Ngâm trai vào thau nước. Đập dập hoặc cắt vài quả ớt cay thả vào nước, ngâm trai tối thiểu 2 giờ để trai nhả hết bùn đất, chất bẩn ra ngoài. Rửa sạch trai, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (1025, '2025-11-20 17:10:12.301946', '2025-11-20 17:10:12.301946', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 189, 2, 'Lấy thịt trai có 2 cách. Lấy trực tiếp: Dùng đầu dao nhỏ len vào khe hở của miệng trai và tách đôi, lấy phần thịt, bóp bỏ phân, rửa sạch. Cách 2 luộc sơ, khi nước bùng lên, trai vừa hé miệng thì vớt ra ngay, tách vỏ, lấy phần thịt, bỏ phân, rửa sạch, để ráo nước. Thái trai thành các miếng vừa ăn, tẩm ướp với 1 thìa canh nước mắm, 1/2 thìa cà phê muối, 1 thìa cà phê hạt nêm, 1 thìa cà phê hạt tiêu và hành tím băm.', 10);
INSERT INTO public.recipe_steps VALUES (1026, '2025-11-20 17:10:12.437101', '2025-11-20 17:10:12.437101', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 190, 5, 'Yêu cầu thành phẩm: Món ăn là kết hợp hài hòa giữa lớp vỏ dậy mùi thơm cay hăng của lá ương sông với nhân ngọt mềm của thịt, chấm cùng nước mắm chua ngọt - giản dị, mộc mạc vậy thôi mà bao cao lương mĩ vị đều nhường chỗ.', 10);
INSERT INTO public.recipe_steps VALUES (1027, '2025-11-20 17:10:12.439223', '2025-11-20 17:10:12.439223', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 190, 4, 'Đun nóng dầu ăn, cho chả vào chiên trên lửa vừa. Lật trở đều hai mặt cho tới khi phần vỏ xém vàng, chả chín dậy mùi thơm đặc trưng của lá xương sông là được.', 10);
INSERT INTO public.recipe_steps VALUES (1028, '2025-11-20 17:10:12.441365', '2025-11-20 17:10:12.441365', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 190, 2, 'Ướp thịt nạc vai xay (có cả nạc lẫn mỡ) với lá xương sông thái nhỏ, hành khô băm nhỏ, 1 thìa cà phê nước mắm, 1/2 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu, trộn đều để ướp 15 - 20 phút cho thấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (1029, '2025-11-20 17:10:12.443478', '2025-11-20 17:10:12.443478', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 190, 3, 'Trải lá xương sông ra mặt phẳng, múc lượng nhân phù hợp vào rồi cuốn lại. Cuối cùng dùng cuống ghim vào để cố định cho chả. Làm lần lượt cho tới hết.', 10);
INSERT INTO public.recipe_steps VALUES (1030, '2025-11-20 17:10:12.445566', '2025-11-20 17:10:12.445566', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 190, 1, 'Chọn lá xương sông bánh tẻ (không quá già cũng không quá non, to vừa phải), rửa sạch, để ráo nước. Đập dập phần xương lá cho mềm và dễ cuốn. Lấy một vài lá thái nhỏ để trộn ướp cùng thịt giúp nhân dậy mùi thơm đặc trưng.', 10);
INSERT INTO public.recipe_steps VALUES (1031, '2025-11-20 17:10:12.597579', '2025-11-20 17:10:12.597579', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 191, 2, 'Gạo nếp tẻ rang sơ cho thơm, đãi sạch. Đậu xanh ngâm đãi vỏ sạch. Hạt sen thông tâm, rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (1032, '2025-11-20 17:10:12.599277', '2025-11-20 17:10:12.599277', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 191, 5, 'Làm sẵn hành phi trước, xem cách làm:Tại đây', 10);
INSERT INTO public.recipe_steps VALUES (1033, '2025-11-20 17:10:12.601938', '2025-11-20 17:10:12.601938', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 191, 7, 'Yêu cầu thành phẩm: Cháo nở bung như hoa, thịt chim câu mềm ngọt tự nhiên mà không hề tanh, đậu xanh bùi bùi, hạt sen chín tới, hài hòa vị rất hấp dẫn. Theo Đông y, thịt chim bồ câu có vị mặn, tính bình, hơi ấm, có tác dụng bổ ngũ tạng, bồi bổ khí huyết, trừ cam tích, kích thích tiêu hóa rất tốt cho người mới ốm dậy, người già.', 10);
INSERT INTO public.recipe_steps VALUES (1034, '2025-11-20 17:10:12.603528', '2025-11-20 17:10:12.603528', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 191, 3, 'Cho gạo tẻ, gạo nếp, đậu xanh cùng chút muối và thêm nước vào ninh cháo. Khi hạt gạo mềm thì trút phần thịt bồ câu xào và hạt sen vào ninh tiếp cho tới khi hạt gạo nở bung như hoa, hạt sen chín tới, thịt chim câu mềm.', 10);
INSERT INTO public.recipe_steps VALUES (1035, '2025-11-20 17:10:12.605664', '2025-11-20 17:10:12.605664', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 191, 1, 'Bồ câu làm sạch, bỏ nội tạng giữ lại tim, thui sơ cho xém hết lông tơ và thơm ngon, chặt miếng vừa ăn. Ướp thịt chim với 1 thìa canh nước mắm ngon, 1 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu trong 30 phút cho thấm vị. Phi thơm hành khô, cho thịt chim câu vào xào săn.', 10);
INSERT INTO public.recipe_steps VALUES (1036, '2025-11-20 17:10:12.607252', '2025-11-20 17:10:12.607252', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 191, 6, 'Nêm nếm lại gia vị mắm, muối, hạt nêm phù hợp cho nồi cháo. Thêm rau thơm, đảo nhẹ và tắt bếp, múc cháo ra bát, rắc thêm hạt tiêu và thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1037, '2025-11-20 17:10:12.609363', '2025-11-20 17:10:12.609363', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 191, 4, 'Các loại rau thơm rửa sạch, vẩy ráo, cắt nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (1038, '2025-11-20 17:10:12.675168', '2025-11-20 17:10:12.675168', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 192, 3, 'Cá bống làm sạch, rửa nước vo gạo (hoặc nước muối loãng với chanh khử tanh), để thật ráo nước hoặc thấm khô. Phi thơm mỡ heo với hành, tỏi, đầu củ hành, sau đó cho cá vào chiên sơ cho thơm ngon.', 10);
INSERT INTO public.recipe_steps VALUES (1039, '2025-11-20 17:10:12.679965', '2025-11-20 17:10:12.679965', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 192, 5, 'Nêm nếm lại gia vị cho phù hợp và kho cho tới khi cá săn cứng, đậm gia vị, nước kho keo đặc quánh lại, rưới thêm ít mỡ nước và tóp mỡ cho bóng, thêm hành lá, rắc hạt tiêu là hoàn thành.', 10);
INSERT INTO public.recipe_steps VALUES (1040, '2025-11-20 17:10:12.682675', '2025-11-20 17:10:12.682675', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 192, 1, 'Pha hỗn hợp nước sốt kho gồm: 2 -3 muỗng cà phê nước mắm, 1 muỗng canh nước màu kho (nước hàng), 1/2 muỗng canh đường, 1 thìa cà phê muối, 1 thìa cà phê hạt tiêu, 1/2 thìa cà phê mì chính hoặc hạt nêm. Thêm 1 chén (bát nhỏ) nước dừa tươi đun nóng, khuấy đều cho hỗn hợp sốt kho tan. Điều chỉnh nước sốt kho theo khẩu vị.', 10);
INSERT INTO public.recipe_steps VALUES (1041, '2025-11-20 17:10:12.685338', '2025-11-20 17:10:12.685338', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 192, 4, 'Thêm hỗn hợp nước sốt kho vào xâm xấp mặt cá. Với cách kho nồi đất để tránh nồi bị nứt vỡ thì bí quyết là ban đầu để lửa nhỏ, rồi tăng dần nhiệt lên. Khi sôi thì lại hạ lửa và kho liu riu cho cá mềm nhừ và rút hết gia vị vào, giúp cá săn, đanh lại.', 10);
INSERT INTO public.recipe_steps VALUES (1042, '2025-11-20 17:10:12.688022', '2025-11-20 17:10:12.688022', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 192, 6, 'Yêu cầu thành phẩm: Cá săn cứng, không bị gãy nát, đậm vị, nước kho sánh keo lại chấm cùng rau củ quả luộc như món kho quẹt rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (1568, '2025-11-20 17:10:22.573581', '2025-11-20 17:10:22.573581', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 261, 3, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1043, '2025-11-20 17:10:12.691238', '2025-11-20 17:10:12.691238', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 192, 2, 'Hành khô, tỏi lột vỏ, xắt lát mỏng. Hành lá rửa sạch, cắt khúc, đầu củ hành thì đập dập.', 10);
INSERT INTO public.recipe_steps VALUES (1044, '2025-11-20 17:10:12.781352', '2025-11-20 17:10:12.781352', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 193, 7, 'Yêu cầu thành phẩm: Cá săn chắc, gói trọn hương vị từ riềng, sả thơm ngon. Su hào giòn ngọt. Nước kho sóng sánh, ăn cùng cơm nóng rất ngon, nhất là trong thời tiết lạnh.', 10);
INSERT INTO public.recipe_steps VALUES (1045, '2025-11-20 17:10:12.783245', '2025-11-20 17:10:12.783245', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 193, 3, 'Pha hỗn hợp nước sốt kho: 1,5 bát con nước sôi già cùng 4 - 5 thìa thìa canh nước hàng, 4 - 5 thìa canh nước mắm 30 - 40 độ đạm, 1 thìa canh đường, 2 thìa cà phê muối, 1 thìa cà phê hạt nêm, 1 thìa cà phê hạt tiêu. Khuấy đều cho hỗn hợp nước sốt tan ra.', 10);
INSERT INTO public.recipe_steps VALUES (1046, '2025-11-20 17:10:12.785373', '2025-11-20 17:10:12.785373', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 193, 1, 'Cá làm sạch, chà xát chanh và muối hạt rồi rửa sạch khử tanh, để ráo nước. Ướp cá trước với 1 thìa canh muối hạt để giúp cá đanh săn, đậm vị hơn khi kho.', 10);
INSERT INTO public.recipe_steps VALUES (1047, '2025-11-20 17:10:12.787496', '2025-11-20 17:10:12.787496', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 193, 6, 'Cá kho ngon nhất là từ 2 - 3 lần lửa để thịt săn chắc đậm đà và lên màu đẹp. Kho lần 1: Bật lửa to cho cá sôi khoảng 10 phút, hớt bỏ bọt rồi hạ lửa liu riu trong khoảng 1 tiếng. Lúc này, bạn nêm nếm lại gia vị cho phù hợp, cá kho nên đậm vị. Tắt bếp để cá nguội, đây cũng là lúc giúp ''''cá hồi'''' và dẻo và săn hơn. Sau đó, tiếp tục kho lửa lần 2, 3 tương tự. Chú ý canh khi cá kho gần cạn thì thêm nước sôi vào để cá bén cháy. Kho cá tối thiểu 3 tiếng mới ngon, kho trên 8 tiếng thì cá mềm rục xương. Để cá bóng đẹp thì khi kho gần xong, mở vung, rưới thêm chút mỡ nước hoặc dầu ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1048, '2025-11-20 17:10:12.790664', '2025-11-20 17:10:12.790664', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 193, 5, 'Kho cá bằng nồi đất là ngon nhất. Rải đều một lớp riềng, gừng, sả dưới đáy nồi rồi xếp xen kẽ cá và su hào. Trên cùng thêm riềng, gừng, hành củ, vỏ hành, su hào nếu còn. Cuối cùng rưới nước sốt kho vào nồi xâm xấp.', 10);
INSERT INTO public.recipe_steps VALUES (1049, '2025-11-20 17:10:12.792777', '2025-11-20 17:10:12.792777', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 193, 2, 'Su hào chọn củ non, gọt bỏ vỏ, thái con chì hoặc miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1050, '2025-11-20 17:10:12.794893', '2025-11-20 17:10:12.794893', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 193, 4, 'Riềng, gừng rửa sạch, thái lát mỏng. Sả cắt khúc đập dập nhẹ. Hành khô rửa sạch, bóc giữa lại cả vỏ kho, ớt khô rửa sạch để nguyên quả.', 10);
INSERT INTO public.recipe_steps VALUES (1051, '2025-11-20 17:10:12.938476', '2025-11-20 17:10:12.938476', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 194, 3, 'Thịt ba chỉ chà xát chanh và muối hạt, rửa sạch rồi thái con chì. Cho chút dầu vào nồi đất/chảo đun nóng, cho thịt ba chỉ vào chiên cho tới khi sém vàng và tiết mỡ.', 10);
INSERT INTO public.recipe_steps VALUES (1052, '2025-11-20 17:10:12.940986', '2025-11-20 17:10:12.940986', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 194, 4, 'Vớt thịt ra, giữ lại 3 thìa canh mỡ, cho hành khô và tỏi băm vào phi thơm. Trút tôm khô, thịt ba chỉ vào đảo đều cho săn. Pha hỗn hợp nước mắm: đường: nước lọc theo tỷ lệ 1:1:1 (6 muỗng canh nước mắm, 6 muỗng canh đường, 6 muỗng canh nước lọc), vài trái ớt hiểm cho vào nồi. Hạ lửa nhỏ đun liu riu mở nắp cho tới khi gần cạn, thêm nước cơm/hoặc nước cốt dừa và tiếp tục đun nhỏ lửa cho tới khi nước sánh kẹo lại. Lúc này, thêm hạt tiêu, hành lá, tóp mỡ (tùy chọn) vào, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (1053, '2025-11-20 17:10:12.942553', '2025-11-20 17:10:12.942553', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 194, 1, 'Hành khô, tỏi lột bỏ vỏ, bằm nhuyễn. Hành lá rửa sạch, thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (1054, '2025-11-20 17:10:12.944144', '2025-11-20 17:10:12.944144', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 194, 7, 'Dọn cơm cháy ra thưởng thức cùng kho quẹt và rau củ quả luộc. Yêu cầu thành phẩm: Kho quẹt sốt sánh kẹo, tôm mềm, vị mặn ngọt đậm đà. Cơm cháy giòn rụm. Rau củ quả luộc vừa độ giòn ngon.', 10);
INSERT INTO public.recipe_steps VALUES (1055, '2025-11-20 17:10:12.945732', '2025-11-20 17:10:12.945732', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 194, 5, 'Cho chút dầu nóng vào hành lá xắt nhỏ để phết lên cơm cháy.', 10);
INSERT INTO public.recipe_steps VALUES (1056, '2025-11-20 17:10:12.947785', '2025-11-20 17:10:12.947785', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 194, 2, 'Tôm khô rửa cho sạch, ngâm nước ấm 10 - 15 phút cho mềm, vớt ra để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (1057, '2025-11-20 17:10:12.949429', '2025-11-20 17:10:12.949429', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 194, 6, 'Cách làm cơm cháy: Phết chút dầu trên chảo, cho cơm nguội vào dàn mỏng đều, nén xuống, bật lửa nhỏ. Thỉnh thoảng xoay đều cho tới khi cơm sém vàng giòn, phết thêm mỡ hành là được.', 10);
INSERT INTO public.recipe_steps VALUES (1058, '2025-11-20 17:10:13.038902', '2025-11-20 17:10:13.038902', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 195, 6, 'Cuối cùng thêm dừa nạo, đảo đều và tắt bếp là được.', 10);
INSERT INTO public.recipe_steps VALUES (1059, '2025-11-20 17:10:13.041019', '2025-11-20 17:10:13.041019', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 195, 7, 'Yêu cầu thành phẩm: Hạt xôi căng bóng mềm dẻo quyện với ngô ngọt bùi, dừa nạo sần sật, nước cốt dừa béo ngậy rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (1060, '2025-11-20 17:10:13.04266', '2025-11-20 17:10:13.04266', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 195, 4, 'Trộn chung nếp với ngô ngọt, thêm 1 thìa cà phê muối hạt vào xóc đều để giúp xôi đậm vị hơn.', 10);
INSERT INTO public.recipe_steps VALUES (1061, '2025-11-20 17:10:13.04441', '2025-11-20 17:10:13.04441', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 195, 1, 'Gạo nếp vo sạch, ngâm nước qua đêm khoảng 6-8 tiếng (nếu là nếp cũ thì thời gian ngâm từ 9 đến 10 tiếng). Nếu muốn nấu luôn thì ngâm vào nước ấm khoảng 1-2 tiếng trước khi nấu. Sau đó, đổ gạo ra, xả nhẹ nước, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (1062, '2025-11-20 17:10:13.04686', '2025-11-20 17:10:13.04686', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 195, 3, 'Cùi dừa cạo bỏ lớp nâu cứng, bào sợi.', 10);
INSERT INTO public.recipe_steps VALUES (1063, '2025-11-20 17:10:13.048467', '2025-11-20 17:10:13.048467', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 195, 5, 'Đun sôi nước (1/2 nồi), làm nóng chõ đồ xôi, hạ lửa vừa rồi cho gạo nếp trộn ngô ngọt vào dàn đều và đồ xôi. Sau 20 phút, khi hạt nếp nở thì thêm nước cốt dừa đảo đều. Sau 10 phút tiếp tục cho đường, dầu ăn vào đảo để hạt xôi ngấm vị ngọt và trở nên căng bóng. Đồ tiếp 10 phút nữa là hạt xôi chín, dẻo mềm, ngô ngọt cũng vừa lúc chín.', 10);
INSERT INTO public.recipe_steps VALUES (1064, '2025-11-20 17:10:13.050068', '2025-11-20 17:10:13.050068', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 195, 2, 'Ngô lột vỏ, bỏ râu rồi tách lấy hạt, rửa sạch, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (1065, '2025-11-20 17:10:13.144093', '2025-11-20 17:10:13.144093', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 196, 3, 'Hành lá chần sơ, vớt ra bát nước sôi để nguội giữ màu xanh.', 10);
INSERT INTO public.recipe_steps VALUES (1405, '2025-11-20 17:10:19.990035', '2025-11-20 17:10:19.990035', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 243, 3, 'Trộn chung nếp, hành và nước lá dứa. Nấu nếp thành xôi vừa chín tới. Rải xôi ra đĩa cho mau nguội.', 10);
INSERT INTO public.recipe_steps VALUES (1066, '2025-11-20 17:10:13.145686', '2025-11-20 17:10:13.145686', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 196, 5, 'Cách cuốn: Đặt hành lá trên tay, tay còn lại cho rau sống, bún lá, tôm, thịt, trứng gọn gàng lên trên rồi khéo léo cuộn lại 2 vòng lá và thắt nút/buộc lại cố định. Làm lần lượt cho tới hết.', 10);
INSERT INTO public.recipe_steps VALUES (1067, '2025-11-20 17:10:13.147286', '2025-11-20 17:10:13.147286', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 196, 4, 'Bún lá cắt thành từng miếng nhỏ vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1068, '2025-11-20 17:10:13.14955', '2025-11-20 17:10:13.14955', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 196, 6, 'Yêu cầu thành phẩm: Từng cuốn hành xen kẽ màu sắc: màu hồng của tôm, màu trắng của thịt lợn, màu vàng ươm của trứng gà, màu trắng mịn từ bún lá và xếp xen kẽ rau thơm xanh mướt. Cuốn vừa tay để không bị đứt gãy. Món này chấm cùng mắm chắt tép nguyên chất hoặc nước mắm tỏi ớt chua ngọt đều rất ngon, thanh mát.', 10);
INSERT INTO public.recipe_steps VALUES (1069, '2025-11-20 17:10:13.151126', '2025-11-20 17:10:13.151126', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 196, 2, 'Các loại rau sống nhặt, rửa sạch, ngâm nước muối loãng, vẩy ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (1070, '2025-11-20 17:10:13.153309', '2025-11-20 17:10:13.153309', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 196, 1, 'Tôm cắt bỏ cắt vát chéo trên đầu, rút bỏ chỉ đen, rửa sạch rồi luộc hoặc hấp cùng chút sả, gừng cho thơm, bóc vỏ, bổ đôi tôm làm 2 nửa. Thịt ba chỉ chần sơ, rửa sạch, luộc vừa tới, để nguội thái lát mỏng. Trứng gà tráng mỏng, cắt miếng 4 x 6cm.', 10);
INSERT INTO public.recipe_steps VALUES (1071, '2025-11-20 17:10:13.267919', '2025-11-20 17:10:13.267919', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 197, 2, 'Riềng bánh tẻ (không non quá hay già quá) giã nhỏ; nghệ tươi giã nhỏ cho thêm chút nước cốt chanh hoặc giấm lọc lấy nước nghệ vàng ươm; mẻ lọc mịn, sả cắt nhỏ. Rau thơm (hành lá, rau răm, rau ngổ) rửa sạch, vẩy ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (1072, '2025-11-20 17:10:13.26965', '2025-11-20 17:10:13.26965', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 197, 3, 'Ướp móng giò, thịt chân giò với với riềng xay, nước cốt nghệ tươi, sả cùng 3 thìa canh mẻ, 2 thìa canh mắm tôm, 1 thìa canh nước mắm, 1/2 thìa canh rượu trắng, 1 thìa cà phê muối, 1 thìa cà phê hạt nêm (hoặc mì chính), trộn đều ướp tối thiểu trong 1 giờ hoặc có thời gian bọc màng bọc thực phẩm để tủ lạnh ướp lâu sẽ thấm vị ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (1073, '2025-11-20 17:10:13.272052', '2025-11-20 17:10:13.272052', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 197, 4, 'Nấu lửa 1: Xào săn thịt móng giò, chân giò đã ướp cho thấm gia vị trong 5 - 7 phút. Sau đó, cho nước ngập mặt thịt, đun sôi rồi hạ lửa nhỏ vừa ninh trong 25 - 30 phút. Tắt bếp cho thịt nguội.', 10);
INSERT INTO public.recipe_steps VALUES (1074, '2025-11-20 17:10:13.274219', '2025-11-20 17:10:13.274219', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 197, 5, 'Nấu tiếp lửa 2 trước khi ăn từ 20 - 25 phút (tùy ý thích ăn mềm hay gần mềm), nước sóng sánh, nêm nếm lại gia vị phù hợp, thêm hành lá, rau răm, rau ngổ, tắt bếp, múc ra thưởng thức nóng cùng bún rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (1075, '2025-11-20 17:10:13.276339', '2025-11-20 17:10:13.276339', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 197, 6, 'Yêu cầu thành phẩm: Thịt mềm đậm vị nhưng bì vẫn còn chút giòn sần sật, nước sóng sánh vàng rượi, dậy mùi thơm của mắm tôm, riềng mẻ, rau thơm. Món này ăn cùng bún vào tiết trời lạnh rất phù hợp.', 10);
INSERT INTO public.recipe_steps VALUES (1076, '2025-11-20 17:10:13.279004', '2025-11-20 17:10:13.279004', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 197, 1, 'Móng giò, thịt chân giò thui bằng bã mía hoặc rơm sẽ cho vị chuẩn và màu đẹp nhất. Nếu không có thì khò ga hoặc bọc giấy đốt cho tới khi ngả màu nâu sậm là được. Cạo hết bụi tro, rửa sạch, chặt/thái miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1077, '2025-11-20 17:10:13.463719', '2025-11-20 17:10:13.463719', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 198, 2, 'Mộc nhĩ, nấm hương ngâm nở, rửa sạch, để ráo và thái nhỏ. Cà rốt, hành tây, khoai lang thái sợi mỏng nhỏ. Củ đậu thái nhỏ, vắt ráo nước. Miến ngâm mềm, để rổ thưa cho khô ráo, cắt nhỏ. Rau mùi, hành hoa rửa sạch thái nhỏ. Hành khô băm nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (1078, '2025-11-20 17:10:13.466344', '2025-11-20 17:10:13.466344', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 198, 6, 'Trước khi ăn, đem rán nem lần 2 cho tới khi vàng giòn. Ở lần chiên thì 2 thì nên rán lửa to hơn để vừa giúp nem thoát dầu không bị ngấy, vừa giúp vỏ giòn rụm.', 10);
INSERT INTO public.recipe_steps VALUES (1079, '2025-11-20 17:10:13.468467', '2025-11-20 17:10:13.468467', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 198, 1, 'Chim bồ câu sơ chế sạch, lọc phần thịt và băm nhỏ. Nếu bạn thích sần sật thì băm cả xương. Nếu nhà có trẻ nhỏ thì nên lọc thịt băm, phần xương cùng đầu, cổ, cánh, chân thì thui qua hoặc xào sơ rồi ninh lấy nước dùng nấu cháo hoặc miến.', 10);
INSERT INTO public.recipe_steps VALUES (1080, '2025-11-20 17:10:13.471671', '2025-11-20 17:10:13.471671', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 198, 3, 'Tiến hành trộn nhân: Cho thịt chim câu đã băm nhỏ cùng thịt lợn xay và vào nồi/hoặc âu thêm 1 thìa canh dầu ăn, 1 thìa cà phê hạt nêm, 1 thìa cà phê muối (bột canh), 1 thìa cà phê mắm, 2 thìa cà phê hạt tiêu, trộn đều. Sau đó mới cho hỗn hợp rau củ ở trên vào trộn đều. Khi nào chuẩn bị gói nem thì mới cho lòng đỏ trứng gà vào trộn đều để tránh nhân bị chảy nước.', 10);
INSERT INTO public.recipe_steps VALUES (1081, '2025-11-20 17:10:13.474391', '2025-11-20 17:10:13.474391', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 198, 4, 'Gói nem: Đặt lá bánh đa nêm lên mặt phẳng, dùng khăn xô thấm chút bia cho hơi ẩm (không ướt) để bánh đa mềm gói dễ hơn, thêm 1/3 lá đa nem nữa lót để tránh vỡ nhân khi rán. Múc lượng nhân vừa phải vào, gập hai bên lại, gấp đầu và gói vừa phải, đều tay. Chú ý không nên gói chặt quá sẽ làm nem bị vỡ khi chiên.', 10);
INSERT INTO public.recipe_steps VALUES (1082, '2025-11-20 17:10:13.477066', '2025-11-20 17:10:13.477066', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 198, 5, 'Rán nem lần 1 để giúp nem vừa chín, se lại: Cho dầu ăn vào chảo, đợi dầu nóng (thử đầu đũa sủi tăm là đạt), hạ lửa nhỏ vừa và cho nem vào rán. Khi nem se mặt và chín khoảng 70- 80% thì vớt ra để giấy thấm dầu cho nguội. Nếu làm nhiều để ăn dần thì lúc này, bạn chia ra các mẻ (tương đương mỗi bữa ăn) rồi đem cấp đông.', 10);
INSERT INTO public.recipe_steps VALUES (1083, '2025-11-20 17:10:13.47934', '2025-11-20 17:10:13.47934', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 198, 7, 'Nem rán đạt chất lượng là từng miếng nem chim bồ câu với vỏ ngoài giòn vàng, bên trong nhân ngọt bùi, rất hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (1084, '2025-11-20 17:10:13.656942', '2025-11-20 17:10:13.656942', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 199, 5, 'Nướng cá bằng than hoa, lò nướng hay nồi chiên không dầu đều được, trong đó nướng trên than hoa là ngon nhất. Cách nướng bằng than hoa: Phết một lớp dầu lên vỉ nướng để cá không bị bén dính vào vỉ. Cho cá vào vỉ và nướng trên than hoa, thỉnh thoảng phết ít dầu ăn cho đỡ khô. Lật trở để cá chín đều các mặt chín đều, vàng giòn là được.', 10);
INSERT INTO public.recipe_steps VALUES (1085, '2025-11-20 17:10:13.658551', '2025-11-20 17:10:13.658551', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 199, 2, 'Lấy 3 thìa canh mẻ đã ngấu lọc qua rây; riềng, sả rửa sạch, cắt rồi xay nhỏ. Nghệ giã rồi thêm chút nước cốt chanh để màu vàng tươi rồi lọc lấy nước.', 10);
INSERT INTO public.recipe_steps VALUES (1086, '2025-11-20 17:10:13.660158', '2025-11-20 17:10:13.660158', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 199, 1, 'Cá trắm làm sạch, chà xát chanh và muối hạt khử tanh, rửa sạch, thấm khô. Sau đó, cắt khúc hoặc lọc phi lê tùy chọn.', 10);
INSERT INTO public.recipe_steps VALUES (1087, '2025-11-20 17:10:13.661867', '2025-11-20 17:10:13.661867', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 199, 4, 'Rau sống nhặt, rửa sạch, ngâm nước muối loãng, vẩy ráo. Các loại củ quả (dưa chuột, dứa, cà rốt) ngâm nước muối loãng, rửa sạch, thái sợi dài. Khế thái hình ngôi sao. Chuối xanh gọt vỏ, thái sợi dài, ngâm nước chanh loãng để không bị thâm đen, vớt ra ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (1088, '2025-11-20 17:10:13.663409', '2025-11-20 17:10:13.663409', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 199, 6, 'Trình bày cá nướng cùng các loại rau sống, khế chua, chuối xanh, dưa chuột, dứa... Khi ăn, đặt bánh tráng lên mặt phẳng rồi thêm rau sống, củ quả và gắp/xắn miếng cá nhỏ thơm nức, thêm chút bún rồi cuộn lại chặt tay chấm nước mắm chua ngọt chanh tỏi ớt rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (1089, '2025-11-20 17:10:13.664972', '2025-11-20 17:10:13.664972', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 199, 3, 'Cho cá vào âu/tô to, cho riềng sả xay, nước cốt nghệ, mẻ vào. Thêm 1 thìa canh mắm tôm, 1 thìa canh dầu hào, 1 thìa canh đường, 1 thìa canh dầu ăn hoặc mỡ lợn, 2 thìa cà phê nước mắm, 1/2 thìa cà phê muối (bột canh), 1 thìa cà phê hạt nêm, 1 thìa cà phê hạt tiêu. Đeo găng tay bóp trộn đều gia vị khắp mặt cá và để ướp tối thiểu 30 phút. Nếu có thời gian, bọc màng bọc thực phẩm để tủ lạnh ướp 2-3 giờ sẽ thấm gia vị ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (1090, '2025-11-20 17:10:13.666581', '2025-11-20 17:10:13.666581', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 199, 7, 'Yêu cầu thành phẩm: Cá da bên ngoài giòn thơm, thịt mềm chua dịu từ mẻ, màu vàng ươm hấp dẫn, dậy mùi thơm mùi riềng khiến ai một lần ăn đều nhớ mãi.', 10);
INSERT INTO public.recipe_steps VALUES (1091, '2025-11-20 17:10:13.756887', '2025-11-20 17:10:13.756887', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 200, 2, 'Gà làm và rửa sạch, chặt miếng bao diêm vừa ăn ướp với 1 thìa canh nước cốt gừng, 2 thìa canh nước mắm, 1 thìa cà phê muối, 1 thìa cà phê hạt tiêu, 1 thìa cà phê hạt nêm (hoặc mì chính), đảo đều ướp trong 10-15 phút cho ngấm gia vị. Sau đó, phi thơm hành tím, gừng giã rồi cho gà vào rang trên lửa lớn để gà rút nước, thấm trọn gia vị vào từng thớ thịt thơm ngon hơn. Nhớ đảo đều tay để chín đều.', 10);
INSERT INTO public.recipe_steps VALUES (1092, '2025-11-20 17:10:13.759058', '2025-11-20 17:10:13.759058', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 200, 3, 'Khi thịt gà săn lại thì nêm nếm gia vị lại theo khẩu vị gia đình. Thêm chút gừng thái sợi và rắc hạt tiêu đảo cho quyện lại. Khi rút hết nước, gà vàng ươm tự nhiên, tiết chút nước mỡ thì tắt bếp, múc ra thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1093, '2025-11-20 17:10:13.760634', '2025-11-20 17:10:13.760634', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 200, 1, 'Lấy 2/3 nhánh gừng giã nhuyễn vắt lấy nước cốt, phần gừng còn lại thái chỉ để rắc lên gà. Hành tím băm nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (1094, '2025-11-20 17:10:13.762225', '2025-11-20 17:10:13.762225', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 200, 4, 'Yêu cầu thành phẩm: Thịt gà săn đậm vị, dậy mùi thơm ấm nóng của gừng, hạt tiêu. Món này ăn nóng cùng cơm trắng rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (1095, '2025-11-20 17:10:13.81878', '2025-11-20 17:10:13.81878', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 201, 2, 'Riềng, gừng rửa sạch thái lát mỏng. Hành bóc vỏ rửa sạch, giữ cả vỏ hành để kho rất thơm. Ớt khô rửa sạch, để nguyên quả.', 10);
INSERT INTO public.recipe_steps VALUES (1096, '2025-11-20 17:10:13.820377', '2025-11-20 17:10:13.820377', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 201, 5, 'Kho cá bằng nồi gang hoặc nồi đất là ngon nhất. Xếp riềng, gừng thái lát xuống đáy nồi, tiếp theo là cá, trám đen và thịt ba chỉ xen kẽ. Trên cùng thêm riềng, gừng, hành củ, vỏ hành, trám đen. Cuối cùng rưới nước sốt kho vào nồi cho xâm xấp.', 10);
INSERT INTO public.recipe_steps VALUES (1097, '2025-11-20 17:10:13.821983', '2025-11-20 17:10:13.821983', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 201, 3, 'Trám rửa sạch hết nhựa. Om trám với nước ấm (tỷ lệ vàng ''''3 sôi, 2 lạnh''''), đậy vung kín cho tới khi trám mềm, vớt ra, tách đôi bỏ hạt, để riêng. Thịt ba chỉ rửa sạch, cắt miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1098, '2025-11-20 17:10:13.823054', '2025-11-20 17:10:13.823054', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 201, 7, 'Yêu cầu thành phẩm: Từng miếng cá săn chắc, đậm vị, trám đen bùi bùi, dậy mùi thơm của riềng, nước kho sóng sánh hấp dẫn, rất ''''hao cơm'''' trong thời tiết mùa đông.', 10);
INSERT INTO public.recipe_steps VALUES (1099, '2025-11-20 17:10:13.82467', '2025-11-20 17:10:13.82467', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 201, 4, 'Pha hỗn hợp nước sốt kho: 1,5 bát con nước sôi, 4 - 5 thìa thìa canh nước hàng, 4 - 5 thìa canh nước mắm, 1 thìa canh đường, 2 thìa cà phê muối, 1 thìa cà phê hạt nêm, 1 thìa cà phê hạt tiêu. Khuấy đều cho hỗn hợp nước sốt tan ra.', 10);
INSERT INTO public.recipe_steps VALUES (1100, '2025-11-20 17:10:13.826245', '2025-11-20 17:10:13.826245', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 201, 6, 'Cách kho cá ngon là nên kho 2 - 3 lần lửa để thịt săn đậm đà và xương rục mềm. Kho lần 1: Bật lửa to cho cá sôi khoảng 10 phút, hớt bỏ bọt rồi hạ lửa liu riu trong khoảng 1 tiếng. Lúc này, nêm nếm lại gia vị cho phù hợp, cá kho nên đậm vị. Tắt bếp để cá nguội, đây cũng là lúc giúp ''''cá hồi'''' và dẻo hơn. Sau đó, tiếp tục kho lửa lần 2, 3 tương tự. Chú ý thêm nước sôi vào khi nước kho gần cạn, tránh không để cá bén cháy. Kho cá tối thiểu 3 tiếng, cá mới ngon, kho trên 8 tiếng thì cá mới săn chắc bên ngoài mà bên trong mềm ngon, đậm đà và mềm rục xương. Để cá bóng đẹp thì khi kho gần xong, mở vung, rưới thêm chút mỡ nước hoặc dầu ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1101, '2025-11-20 17:10:13.827853', '2025-11-20 17:10:13.827853', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 201, 1, 'Cá làm sạch, cạo hết màng đen, máu ở bụng. Dùng chanh, muối hạt chà xát và ngâm vào nước vo gạo, rửa sạch để khử mùi tanh. Để cá thẩm thấu gia vị nhanh và chắc thịt hơn. Cho cá vào rổ thưa, dội nước nóng 80 độ để cá cong người (hoặc cho cá vào nồi đun bùng lên, tắt bếp). Sau đó, mới ướp cá với 1 thìa canh muối hạt trước để giúp cá đậm vị và săn chắc.', 10);
INSERT INTO public.recipe_steps VALUES (1102, '2025-11-20 17:10:13.942779', '2025-11-20 17:10:13.942779', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 202, 3, 'Cá chiên đạt là hai mặt bên ngoài vàng tự nhiên mà không cần tẩm bột nghệ, bên trong vẫn mềm ngon tự nhiên từ cá.', 10);
INSERT INTO public.recipe_steps VALUES (1103, '2025-11-20 17:10:13.944872', '2025-11-20 17:10:13.944872', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 202, 9, 'Rau sống rửa sạch, ngâm nước muối loãng, vớt ra vẩy ráo nước, thái rối.', 10);
INSERT INTO public.recipe_steps VALUES (1104, '2025-11-20 17:10:13.946448', '2025-11-20 17:10:13.946448', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 202, 1, 'Cá làm sạch, chà xát chanh và muối hạt để khử mùi tanh rồi lọc lấy phần thịt, thái miếng vừa ăn. Để cá thật ráo nước hoặc thấm khô rồi xóc chút muối hạt cho cá săn lại, đồng thời giúp cho thịt cá đậm vị hơn khi ăn. Không nên ướp cá với bột chiên vì khi ăn sẽ bị bã do chan nước dùng nóng vào.', 10);
INSERT INTO public.recipe_steps VALUES (1105, '2025-11-20 17:10:13.948658', '2025-11-20 17:10:13.948658', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 202, 6, 'Cà chua rửa sạch, thái múi cau. Hành lá, thì là rửa sạch, thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (1106, '2025-11-20 17:10:13.950238', '2025-11-20 17:10:13.950238', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 202, 7, 'Xào sơ cà chua nhưng vẫn giữ nguyên miếng.', 10);
INSERT INTO public.recipe_steps VALUES (1107, '2025-11-20 17:10:13.951849', '2025-11-20 17:10:13.951849', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 202, 12, 'Yêu cầu thành phẩm: Từng miếng cá chiên vàng ươm tự nhiên, bên ngoài giòn rụm mà không khô, bên trong mềm ngon ngọt, giữ vị mộc tự nhiên của cá. Nước dùng chua dịu, thanh điểm xuyết cà chua đỏ au, rau xanh tăng thêm phần hấp dẫn. Món bún cá luôn được ưu tiên lựa chọn giải ngấy sau những ngày Tết với thịt thà bánh chưng nhiều mỡ.', 10);
INSERT INTO public.recipe_steps VALUES (1108, '2025-11-20 17:10:13.95358', '2025-11-20 17:10:13.95358', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 202, 5, 'Nấu nước dùng: Xương bay (xương lợn) chần sơ, rửa sạch và cho vào ninh lấy nước dùng ngọt. Phần xương cá thì chiên sơ cho vào nồi nước dùng ninh cùng. Thêm hành tây nướng, gừng nướng rửa sạch cho thơm. Thỉnh thoảng hớt bỏ bọt. Sau khoảng 1 giờ thì lọc lấy nước dùng, nêm nếm mắm, muối, hạt nêm theo khẩu vị.', 10);
INSERT INTO public.recipe_steps VALUES (1109, '2025-11-20 17:10:13.955166', '2025-11-20 17:10:13.955166', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 202, 8, 'Khi ăn, cho cà chua vào nồi nước dùng và thêm chút giấm bỗng để tạo vị chua thanh dịu.', 10);
INSERT INTO public.recipe_steps VALUES (1110, '2025-11-20 17:10:13.95679', '2025-11-20 17:10:13.95679', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 202, 10, 'Rau cần nhặt bỏ phần rễ già, rửa sạch, vặn khúc cho ra tinh dầu thơm, chần sơ nước nóng vớt ra.', 10);
INSERT INTO public.recipe_steps VALUES (1111, '2025-11-20 17:10:13.958939', '2025-11-20 17:10:13.958939', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 202, 2, 'Bí quyết chiên cá giòn rụm, giữ nguyên vị mộc: Bật bếp ở lửa nhỏ vừa đun nóng chảo dần lên. Sau khi chảo nóng thì mới cho dầu ăn vào và tăng dầu ở lửa vừa, chờ cho dầu nóng lên bằng cách thử đầu đũa thấy sủi tăm là đạt. Chia cá thành từng mẻ (các miếng cá xếp giãn ra để tránh dính) rồi cho vào chiên. Chiên cá nguyên bản sẽ lâu hơn so với tẩm bột nhưng bù lại miếng cá giòn giữ vị mộc thơm từ cá rất ngon. Không lật trở miếng cá mà chờ khi một mặt vàng giòn (khoảng 12- 15 phút) thì lật trở, chiên mặt còn lại.', 10);
INSERT INTO public.recipe_steps VALUES (1112, '2025-11-20 17:10:13.960503', '2025-11-20 17:10:13.960503', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 202, 4, 'Vớt cá ra để vào giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (1113, '2025-11-20 17:10:13.962092', '2025-11-20 17:10:13.962092', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 202, 11, 'Trụng bún qua nước sôi xếp vào tô, thêm cá rán, cà chua, rau cần chần, hành lá, rau thì là rồi múc nước dùng chan nóng lên. Ăn kèm với rau sống, ớt chưng và nước mắm tỏi ớt rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (1114, '2025-11-20 17:10:14.072168', '2025-11-20 17:10:14.072168', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 203, 1, 'Chọn phần thịt nạc vai có lẫn mỡ (để không bị khô) đem xay. Tôm tươi bóc vỏ, băm nhuyễn, tôm giúp cho món nem ngọt thơm hơn.', 10);
INSERT INTO public.recipe_steps VALUES (1115, '2025-11-20 17:10:14.074984', '2025-11-20 17:10:14.074984', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 203, 2, 'Sả rửa sạch, bỏ vỏ già bên ngoài, cắt ngắn bớt, đập dập nhẹ đầu củ cho ra tinh dầu để khi nướng thẩm thấu vào nem lụi thơm ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (1116, '2025-11-20 17:10:14.077616', '2025-11-20 17:10:14.077616', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 203, 6, 'Trình bày nem lụi cùng rau sống, khế chua, chuối xanh, dưa chuột, dứa... Khi ăn, đặt bánh tráng lên mặt phẳng rồi cho rau sống, nem lụi, rau, bún rối và cuốn lại, chấm cùng nước mắt tỏi ớt chua ngọt rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (1117, '2025-11-20 17:10:14.07976', '2025-11-20 17:10:14.07976', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 203, 4, 'Sau khi ướp, thoa chút dầu ăn lên găng tay, múc một lượng hỗn hợp thịt vừa phải bọc quấn vào đầu gốc cây sả. Làm lần lượt cho tới hết.', 10);
INSERT INTO public.recipe_steps VALUES (1118, '2025-11-20 17:10:14.081931', '2025-11-20 17:10:14.081931', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 203, 3, 'Cho giò sống, thịt xay, tôm băm nhỏ vào âu lớn thêm bột hành, bột tỏi (hoặc dùng củ hành, củ tỏi giã nhuyễn, vắt nước cốt), 2 thìa canh dầu hào, 2 thìa canh đường, 2 thìa canh dầu màu điều, 2 thìa canh bột năng, 2 thìa cà phê bột ớt Hàn Quốc (tùy chọn), 2 thìa cà phê hạt nêm, 1 thìa cà phê nước mắm, 1 thìa cà phê hạt tiêu. Trộn và quết đều đến khi hỗn hợp quyện dẻo, bọc màng bọc thực phẩm để ngăn mát tủ lạnh 2 - 3 giờ cho thấm gia vị và hỗn hợp se dẻo hơn.', 10);
INSERT INTO public.recipe_steps VALUES (1119, '2025-11-20 17:10:14.08415', '2025-11-20 17:10:14.08415', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 203, 5, 'Nướng nem lụi bằng than hoa là ngon nhất. Nếu nướng lò, bạn cho nem lên vỉ nướng (bên dưới đặt khay nước để khi nướng nem chảy mỡ không bị cháy). Nướng ở 180 độ trong 15 phút, lấy ra quết hỗn hợp (gồm 1 thìa canh mật ong, 1 thìa canh dầu hào, 1 thìa canh dầu điều) để nem bóng đẹp và thơm ngon, không bị khô. Tiếp tục nướng thêm 15 - 20 phút là nem chín.', 10);
INSERT INTO public.recipe_steps VALUES (1120, '2025-11-20 17:10:14.205698', '2025-11-20 17:10:14.205698', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 204, 8, 'Bày gà nướng lên mẹt, trang trí rau thơm, chẩm chéo. Gà nướng kiểu Tây Băc ăn xé là ngon và thú vị nhất. Thịt gà ươm vàng, mềm ngọt, dậy mùi thơm mắc khén, hạt dổi chấm cùng chẩm chéo rất ngon, ai một lần thưởng thức đều nhớ mãi.', 10);
INSERT INTO public.recipe_steps VALUES (1121, '2025-11-20 17:10:14.207316', '2025-11-20 17:10:14.207316', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 204, 5, 'Dùng giấy bạc (2 lượt giấy) gói kín gà và để ướp trong ngăn mát tủ lạnh tối thiểu 1 giờ hoặc lâu hơn càng ngon. Nếu có lá dong hoặc lá chuối gói càng ngon vì giữ hương vị thơm mộc tự nhiên của các gia vị. Theo cách truyền thống của người dân tộc Thái thì sau khi gói lá dong hoặc lá chuối sẽ đắp/bọc kín đất sét bên ngoài.', 10);
INSERT INTO public.recipe_steps VALUES (1122, '2025-11-20 17:10:14.209516', '2025-11-20 17:10:14.209516', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 204, 6, 'Nướng gà bằng lò nướng: Bật trước lò nướng 180 - 200 độ C cả hai thanh nhiệt. Cho gà đã bọc giấy bạc vào nướng trong 60 phút để gà chín ngọt mềm. Sau đó, lấy giấy bạc ra cho gà lên giá nướng (để khay nướng bên dưới). Tiếp tục nướng gà trong khoảng 30 phút cho tới khi da vàng giòn là được. Còn cách nướng truyền thống của người Thái là đốt lửa đượm, nhiều than rồi đặt gà đắp đất sét vào, đốt đều ở lửa nhỏ vừa trong khoảng 90 phút thì gà chín mềm ngon mà không khô.', 10);
INSERT INTO public.recipe_steps VALUES (1123, '2025-11-20 17:10:14.21108', '2025-11-20 17:10:14.21108', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 204, 3, 'Cho 2 thìa cà phê hạt mắc khén, 2 hạt dổi (để lại một ít mắc khén và hạt dổi làm chẩm chéo chấm) cùng rau thơm, hành củ, tỏi, bột gừng, bột nghệ (hoặc dùng gừng, nghệ), hạt tiêu, ớt bột, ớt tươi cùng 1 thìa canh muối hạt vào cối giã nhuyễn. Thêm 2 thìa canh mật ong, 2 thìa cà phê hạt nêm trộn đều để thành hỗn hợp ướp gà.', 10);
INSERT INTO public.recipe_steps VALUES (1124, '2025-11-20 17:10:14.212837', '2025-11-20 17:10:14.212837', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 204, 7, 'Làm chẩm chéo: Cho vào cối: 1 thìa canh muối hạt, 1 thìa cà phê hạt mắc khén, 1 hạt dổi cùng rau húng lủi/bạc hà, rau mùi, rau mùi tàu, gừng, ớt, tỏi, sả, hạt nêm rồi giã nhuyễn là được chẩm chéo.', 10);
INSERT INTO public.recipe_steps VALUES (1125, '2025-11-20 17:10:14.214952', '2025-11-20 17:10:14.214952', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 204, 4, 'Đeo găng tay thoa hỗn hợp ướp đều khắp mình gà.', 10);
INSERT INTO public.recipe_steps VALUES (1126, '2025-11-20 17:10:14.217078', '2025-11-20 17:10:14.217078', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 204, 1, 'Gà làm sạch, chà xát chanh và muối hạt rửa sạch, để ráo nước. Bạn có thể để nguyên con hoặc phanh bụng, gập lưng ra. Dùng dao nhỏ hoặc xiên tre nhọn châm vào ức, đùi để giúp thấm gia vị dễ hơn.', 10);
INSERT INTO public.recipe_steps VALUES (1127, '2025-11-20 17:10:14.218137', '2025-11-20 17:10:14.218137', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 204, 2, 'Rang thơm 3 thìa cà phê hạt mắc khén, 3 hạt dổi. Rửa sạch lá chanh, húng lủi, hành lá vẩy ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (1128, '2025-11-20 17:10:14.363982', '2025-11-20 17:10:14.363982', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 205, 3, 'Luộc trai với lượng nước xâm xấp bề mặt cùng vài lát gừng. Khi trai vừa hé miệng thì vớt ra luôn vì để lâu thịt trai sẽ bị teo và dai. Trai nguội, tách lấy thịt ra khỏi vỏ, bóp bỏ phần phân (nhô ra), bóp chút chanh, rửa sạch. Phần nước luộc trai để lắng, lọc lấy nước trong dùng nấu cháo.', 10);
INSERT INTO public.recipe_steps VALUES (1129, '2025-11-20 17:10:14.366183', '2025-11-20 17:10:14.366183', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 205, 5, 'Phi thơm hành khô, cho trai vào xào nhanh trên lửa lớn, nêm nếm 2 thìa cà phê nước mắm, 1 thìa cà phê bột canh (muối), 1 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu rồi tắt bếp, múc ra để riêng. Không xào trai lâu quá sẽ tiết nước sẽ bị quắt lại và dai.', 10);
INSERT INTO public.recipe_steps VALUES (1130, '2025-11-20 17:10:14.368455', '2025-11-20 17:10:14.368455', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 205, 4, 'Thịt trai thái miếng nhỏ vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1131, '2025-11-20 17:10:14.370055', '2025-11-20 17:10:14.370055', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 205, 2, 'Dùng bàn chải cọ và rửa trai thật sạch.', 10);
INSERT INTO public.recipe_steps VALUES (1132, '2025-11-20 17:10:14.37106', '2025-11-20 17:10:14.37106', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 205, 1, 'Trai ngâm nước vo gạo kèm vài quả ớt cắt lát tối thiểu 2 giờ để làm sạch bùn đất.', 10);
INSERT INTO public.recipe_steps VALUES (1133, '2025-11-20 17:10:14.511725', '2025-11-20 17:10:14.511725', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 206, 3, 'Miến ngâm nước cho mềm, cắt vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1134, '2025-11-20 17:10:14.513895', '2025-11-20 17:10:14.513895', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 206, 8, '[Caption]', 10);
INSERT INTO public.recipe_steps VALUES (1135, '2025-11-20 17:10:14.51658', '2025-11-20 17:10:14.51658', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 206, 5, 'Hớt bọt bằng dụng cụ lọc sẽ không bị mất nước sánh vàng thịt chim tiết ra.', 10);
INSERT INTO public.recipe_steps VALUES (1136, '2025-11-20 17:10:14.519449', '2025-11-20 17:10:14.519449', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 206, 1, 'Chim câu làm sạch chặt miếng vừa ăn. Nhặt riêng cánh chân, xương cổ, xương cục ra, phần nạc, đùi để riêng. Ướp cả hai loại với hạt nêm, nước mắm, hạt tiêu 20 phút', 10);
INSERT INTO public.recipe_steps VALUES (1137, '2025-11-20 17:10:14.52157', '2025-11-20 17:10:14.52157', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 206, 2, 'Các loại rau rửa sạch, thái nhỏ[Caption]', 10);
INSERT INTO public.recipe_steps VALUES (1138, '2025-11-20 17:10:14.524225', '2025-11-20 17:10:14.524225', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 206, 4, 'Phi thơm hành khô, cho phần xương chim câu, nấm hương đã ngâm vào xào săn, nêm gia vị vừa vặn rồi chế nước sôi đủ dùng. Đập thêm 3 củ hành khô vào cho thơm nước.', 10);
INSERT INTO public.recipe_steps VALUES (1139, '2025-11-20 17:10:14.526368', '2025-11-20 17:10:14.526368', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 206, 6, 'Phần thịt chim trộn thêm chút dầu ăn rồi cho vào nướng 180 độ trong nồi chiên không dầu khoảng20-25 phút để thịt chim vàng thơm. (hoặc rán bằng chảo thông thường cho vàng).[Caption]', 10);
INSERT INTO public.recipe_steps VALUES (1140, '2025-11-20 17:10:14.528495', '2025-11-20 17:10:14.528495', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 206, 7, 'Thả miến vào nước dùng đun sôi vớt miến ra bát thêm thịt chim rán, thêm rau hành đã thái sau đó chan nước dùng lên. Ăn kèm măng ớt, vắt chanh.', 10);
INSERT INTO public.recipe_steps VALUES (1141, '2025-11-20 17:10:14.637448', '2025-11-20 17:10:14.637448', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 207, 7, 'Phi thơm hành khô với mỡ lợn, cho cà chua vào xào, thêm chút mắm muối cho cà chua nhanh chín mềm.', 10);
INSERT INTO public.recipe_steps VALUES (1142, '2025-11-20 17:10:14.639568', '2025-11-20 17:10:14.639568', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 207, 8, 'Để nước dùng thêm ngọt tự nhiên thì bạn nên ninh thêm xương bay lợn rồi lọc lấy nước.', 10);
INSERT INTO public.recipe_steps VALUES (1143, '2025-11-20 17:10:14.64138', '2025-11-20 17:10:14.64138', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 207, 12, 'Yêu cầu thành phẩm: Thịt cua đóng thành tảng, nước riêu thơm mùi đặc trưng vị cua đồng, màu váng óng đỏ tự nhiên từ cà chua và gạch cua, vị chua thanh nhẹ rất hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (1144, '2025-11-20 17:10:14.643515', '2025-11-20 17:10:14.643515', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 207, 1, 'Cua đồng xóc và rửa sạch nhiều lần bằng nước sạch để loại bỏ chất bẩn. Phần mai thì dùng đầu thìa nhỏ khều lấy gạch để riêng. Nếu kỹ hơn thì tráng qua nước lạnh mấy lần, chắt lọc giữ gạch lại để giảm bớt mùi tanh và đen từ gạch (nếu có).', 10);
INSERT INTO public.recipe_steps VALUES (1145, '2025-11-20 17:10:14.644559', '2025-11-20 17:10:14.644559', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 207, 6, 'Cà chua 2 quả khía chữ thập, cho vào nồi nước sôi trụng sơ, vớt ra ngâm nước lạnh, bóc bỏ vỏ, bằm nhuyễn. Còn 1 quả còn lại thái múi cau, để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (1146, '2025-11-20 17:10:14.648033', '2025-11-20 17:10:14.648033', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 207, 9, 'Cho nước dùng xương bay lợn vào nồi nước cua. Thêm cà chua xào chín mềm ở trên và gạch cua vàng ươm vào để tạo màu tự nhiên cho nước dùng. Cho phần cà chua thái múi cau vào nấu rồi nêm nếm gia vị mắm, muối, hạt nêm theo khẩu vị. Cuối cùng thêm dấm bỗng rượu tạo vị chua thanh nhẹ cho nước dùng.', 10);
INSERT INTO public.recipe_steps VALUES (1147, '2025-11-20 17:10:14.651251', '2025-11-20 17:10:14.651251', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 207, 10, 'Phi thơm hành khô với mỡ lợn, cho ớt hạt khô vào chưng, nêm chút muối cho đậm đà, tắt bếp, múc ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (1148, '2025-11-20 17:10:14.653381', '2025-11-20 17:10:14.653381', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 207, 11, 'Trình bày và thưởng thức: Trụng bún qua nước nóng, cho vào bát tô, múc thịt cua, thêm hành hoa thái nhỏ rồi chan nước dùng riêu cua nóng lên, rắc chút hành phi và thưởng thức nóng. Khi ăn thêm một chút mắm tôm (tùy theo khẩu vị) để dậy mùi thơm nhẹ, ăn cùng ớt chưng và rau sống thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (1149, '2025-11-20 17:10:14.655684', '2025-11-20 17:10:14.655684', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 207, 3, 'Cách nấu cua đóng tảng: Bật bếp nấu phần nước lọt thịt cua, dùng đũa (hoặc muôi) khuấy nhẹ theo chiều vòng tròn giúp riêu cua nổi lên, không bén đóng dưới đáy nồi. Khuấy liên tục và đều tay cho tới khi thịt cua nổi lên hết, tách nước trong thì dừng tay và hạ lửa nhỏ, vớt ra bát.', 10);
INSERT INTO public.recipe_steps VALUES (1150, '2025-11-20 17:10:14.65907', '2025-11-20 17:10:14.65907', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 207, 2, 'Phần thân cua cho vào cối cùng chút muối hạt, dùng chày giã nhuyễn. Việc cho muối giúp cho protein trong thịt cua được kết dính tốt hơn, khi nấu sẽ tạo tảng. Sau đó, cho từng lượng nước nhỏ để chắt lọc, rồi lại giã và lọc nhiều lần nhằm lấy hết phần thịt cua. Không nên dùng rây lọc vì thịt cua sẽ bị bám dính vào rây hết.', 10);
INSERT INTO public.recipe_steps VALUES (1151, '2025-11-20 17:10:14.661209', '2025-11-20 17:10:14.661209', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 207, 5, 'Phần thịt cua cho vào bát, ép chắt nước ra sẽ giúp kết tảng đẹp.', 10);
INSERT INTO public.recipe_steps VALUES (1152, '2025-11-20 17:10:14.663345', '2025-11-20 17:10:14.663345', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 207, 4, 'Phi thơm hành khô, cho gạch cua vào chưng, thêm chút mắm, hạt nêm rồi tắt bếp, múc ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (1153, '2025-11-20 17:10:14.899604', '2025-11-20 17:10:14.899604', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 208, 7, 'Trình  bày và thưởng thức: Múc thịt giả cầy ra mắt, ăn kèm cùng cơm trắng, bún hoặc bánh mướt (bánh cuốn Nghệ An) đều rất ngon, nhất là vào tiết trời mùa đông.', 10);
INSERT INTO public.recipe_steps VALUES (1154, '2025-11-20 17:10:14.902327', '2025-11-20 17:10:14.902327', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 208, 8, 'Yêu cầu thành phẩm: Thịt giả cầy mềm mà không bở, có vị ngọt nhẹ từ mật mía, dậy mùi thơm của lá tắt, mắm tôm và sánh màu nâu đỏ đẹp mắt.', 10);
INSERT INTO public.recipe_steps VALUES (1155, '2025-11-20 17:10:14.904407', '2025-11-20 17:10:14.904407', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 208, 2, 'Lá chè xanh (chọn lá già, xanh mướt, to) rửa sạch, vò hơi dập rồi cho vào ấm tích hoặc bình thủy tinh, cho ít nước sôi vào tráng bỏ đi. Sau đó, đổ nước sôi vào 2/3 ấm, đậy nắp kín và om 15 phút sẽ có nước chè. Nếu không có nước chè, dùng nước trà xanh cũng được.', 10);
INSERT INTO public.recipe_steps VALUES (1156, '2025-11-20 17:10:14.908444', '2025-11-20 17:10:14.908444', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 208, 3, 'Riềng, sả rửa sạch, cát lát mỏng. Lá tắt (quýt hôi) rửa sạch, vỏ quả tắt rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (1157, '2025-11-20 17:10:14.911126', '2025-11-20 17:10:14.911126', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 208, 4, 'Ướp thịt chân giò với riềng, sả cùng 1 thìa canh ruốc hôi (mắm tôm), 1 thìa canh nước mắm, 2 thìa cà phê muối hạt, 1 thìa cà phê hạt tiêu, 1/2 thìa cà phê mì chính (hoặc hạt nêm), 1/2 bát nhỏ mật mía, 1/2 bát nhỏ rượu nếp (giúp cân bằng vị và khử mùi) và ớt (nếu nhà có trẻ nhỏ thì bỏ qua ớt). Ướp tối thiểu trong 1 giờ. Nếu có thời gian bọc màng bọc thực phẩm, để qua đêm trong tủ lạnh thấm vị sẽ ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (1158, '2025-11-20 17:10:14.914084', '2025-11-20 17:10:14.914084', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 208, 6, 'Trước khi ăn thì nấu lại lần 2 sẽ giúp thịt đậm đà, dậy mùi thơm, đặc biệt nước sóng sánh màu nâu đỏ đẹp mắt.', 10);
INSERT INTO public.recipe_steps VALUES (1159, '2025-11-20 17:10:14.916144', '2025-11-20 17:10:14.916144', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 208, 5, 'Thịt sau khi ướp thì bật bếp xào săn để rút gia vị vào trong giúp đậm đà hơn. Để món ăn ngon nên nấu 2 lần lửa. Lần 1: Thêm nước chè xanh xâm xấp và đun  trên lửa nhỏ vừa trong 1 giờ cho thịt mềm. Khi nấu, nếu nước cạn thì chêm thêm nước chè xanh hoặc nước sôi. Nêm nếm lại gia vị cho phù hợp với gia đình bạn. Tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (1160, '2025-11-20 17:10:14.918142', '2025-11-20 17:10:14.918142', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 208, 1, 'Thịt móng giò cạo rửa sạch, dùng đèn khò hoặc rơm rạ thui cho vàng thơm lớp da bên ngoài. Cạo sạch lớp cháy nếu có, chặt miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1161, '2025-11-20 17:10:14.992999', '2025-11-20 17:10:14.992999', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 209, 3, 'Cho trứng cá, trứng gà, lá lốt vào tô, thêm 2 muỗng cà phê nước mắm, 1/2 muỗng cà phê bột canh, 1 muỗng cà phê hạt nêm, 1/2 muỗng cà phê hạt tiêu, 1 muỗng canh nước lọc rồi đánh đều để gia vị tan, hỗn hợp hòa quyện, không bị vón cục.', 10);
INSERT INTO public.recipe_steps VALUES (1162, '2025-11-20 17:10:14.994589', '2025-11-20 17:10:14.994589', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 209, 4, 'Đun nóng dầu ăn trong chảo, hạ lửa nhỏ vừa và cho hỗn hợp trứng cá vào. Có thể chiên từng mẻ nhỏ. Dàn đều và chờ một mặt cá vàng ươm thì trở chiên mặt còn lại. Trứng chín, chuyển qua đĩa và ăn cùng cơm nóng rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (1163, '2025-11-20 17:10:14.996716', '2025-11-20 17:10:14.996716', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 209, 5, 'Yêu cầu thành phẩm: Trứng cá vàng ươm, đượm vị, dậy mùi thơm của lá lốt.', 10);
INSERT INTO public.recipe_steps VALUES (1164, '2025-11-20 17:10:14.998419', '2025-11-20 17:10:14.998419', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 209, 1, 'Trứng cá rửa qua nước muối loãng rồi lột bỏ màng bên ngoài, dằm nát.', 10);
INSERT INTO public.recipe_steps VALUES (1165, '2025-11-20 17:10:15.000581', '2025-11-20 17:10:15.000581', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 209, 2, 'Lá lốt nhặt bỏ lá già, cuống cứng, rửa sạch, thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (1166, '2025-11-20 17:10:15.121413', '2025-11-20 17:10:15.121413', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 210, 1, 'Móng giò cạo sạch lông, chặt miếng vừa ăn, chần sơ cùng chút muối hạt, vài lát gừng để loại bỏ tạp chất, rửa sạch.
INSERT INTO public.recipe_steps VALUES (1167, '2025-11-20 17:10:15.195558', '2025-11-20 17:10:15.195558', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 211, 2, 'Phần xương gà, chân gà và bì lợn thì chần sơ, rửa sạch rồi cho nước vào ninh để lấy nước dùng chứa chất gelatine giúp cho thịt đông được dễ dàng. Chú ý mở vung trong quá trình ninh thì đun nhỏ lửa và mở vung, hớt bọt cho nước trong.', 10);
INSERT INTO public.recipe_steps VALUES (1168, '2025-11-20 17:10:15.197626', '2025-11-20 17:10:15.197626', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 211, 3, 'Cà rốt gọt vỏ, tạo hình hoa tùy thích, rồi chần chín. Mộc nhĩ, nấm hương ngâm mềm, cắt miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1169, '2025-11-20 17:10:15.199444', '2025-11-20 17:10:15.199444', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 211, 5, 'Phi thơm hành khô, cho thịt gà xào săn. Rồi sau đó cho mộc nhĩ, nấm hương vào xào cùng.', 10);
INSERT INTO public.recipe_steps VALUES (1170, '2025-11-20 17:10:15.201046', '2025-11-20 17:10:15.201046', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 211, 8, 'Yêu cầu thành phẩm: Thịt đông kết dính lại thành khối, không bị vỡ, thịt gà mềm ngọt, mộc nhĩ giòn sần sật, nấm hương thơm, phần đông trong mát mềm mượt, dậy mùi thơm của hạt tiêu. Đây là món ngon truyền thống vào mùa đông của miền Bắc, đặc biệt là dịp Tết Nguyên đán.', 10);
INSERT INTO public.recipe_steps VALUES (1171, '2025-11-20 17:10:15.203185', '2025-11-20 17:10:15.203185', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 211, 6, 'Trút phần thịt gà và nấm hương, mộc nhĩ vừa xào vào nồi nước dùng, nêm nếm gia vị phù hợp (chú ý món thịt đông thường nhạt vì nếu mặn quá sẽ khó kết dính). Ninh trên lửa nhỏ, hớt bỏ bọt thường xuyên cho nước dùng được trong.', 10);
INSERT INTO public.recipe_steps VALUES (1172, '2025-11-20 17:10:15.205999', '2025-11-20 17:10:15.205999', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 211, 7, 'Khi thịt gà chín mềm thì tắt bếp, để nguội. Xếp hoa cà rốt dưới đáy bát hoặc hộp đựng (nên chia theo phần ăn theo bữa), rồi múc thịt gà, nấm hương, mộc nhĩ vào, thêm nước xâm xấp, rắc thêm chút hạt tiêu (tùy theo khẩu vị) và bọc kín bằng màng bọc thực phẩm, cho vào ngăn mát tủ lạnh 3 - 4 tiếng là thịt đông lại. Lắc nhẹ cho phần thịt tách ra thành bát/khuôn hoặc dùng dao mỏng nhỏ lách một vòng quanh bát/khuôn rồi úp ngược ra đĩa và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (1173, '2025-11-20 17:10:15.207597', '2025-11-20 17:10:15.207597', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 211, 4, 'Nước dùng sau khi ninh khoảng 1 tiếng thì lọc bỏ xương, lấy phần nước trong cho vào nồi.', 10);
INSERT INTO public.recipe_steps VALUES (1174, '2025-11-20 17:10:15.209208', '2025-11-20 17:10:15.209208', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 211, 1, 'Thịt gà lọc lấy thịt, thái miếng nhỏ vừa ăn, ướp với 1 thìa canh nước mắm, 1/2 thìa cà phê muối, 1 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu và 1/2 lượng hành khô băm nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (1175, '2025-11-20 17:10:15.304185', '2025-11-20 17:10:15.304185', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 212, 4, 'Làm sốt sườn gồm nước mắm, đường, giấm, nước theo tỷ lệ: 1:1:1:0,5 (4 thìa canh đường, 4 thìa canh nước mắm 40 độ đạm, 4 thìa canh giấm trắng, 2 thìa canh nước lọc). Nếu dùng nước mắm độ đạm cao sẽ mặn hơn thì bạn tùy chỉnh theo khẩu vị gia đình. Khuấy đều cho tan đường. Bạn thêm ớt, tương ớt (tùy theo khẩu vị, nếu nhà có trẻ nhỏ thì không nên cho ớt).', 10);
INSERT INTO public.recipe_steps VALUES (1176, '2025-11-20 17:10:15.307632', '2025-11-20 17:10:15.307632', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 212, 6, 'Phi thơm hành tỏi (phần xác đã vắt nước), rồi cho hỗn hợp nước sốt vào. Om sườn trên lửa nhỏ vừa cho tới khi nước sốt sền sệt và hơi keo lại, sánh màu nâu đỏ đẹp mắt là được.', 10);
INSERT INTO public.recipe_steps VALUES (1177, '2025-11-20 17:10:15.311237', '2025-11-20 17:10:15.311237', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 212, 2, 'Chần sơ sườn với nước ấm với chút muối hạt, vài lát gừng, 1 củ hành đập dập, sau đó rửa sạch, thấm khô/hoặc để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (1178, '2025-11-20 17:10:15.315034', '2025-11-20 17:10:15.315034', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 212, 1, 'Sườn tách dẻ, chặt miếng vừa ăn, dùng dao nhỏ nhọn rạch một đường phía sau sườn để giúp róc xương, dễ ăn hơn.', 10);
INSERT INTO public.recipe_steps VALUES (1179, '2025-11-20 17:10:15.317177', '2025-11-20 17:10:15.317177', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 212, 3, 'Hành, tỏi bóc vỏ, cho vào cối giã nhuyễn, rồi vắt lấy nước cốt. Phần xác hành tỏi thì giữ lại. Ướp sườn với một thìa canh nước mắm ngon, hai thìa cà phê đường, một thìa cà phê muối, một thìa cà phê hạt nêm, một thìa cà phê hạt tiêu cùng nước cốt hành, tỏi giã ở trên.Bạn có thể thay thế nước cốt hành, tỏi bằng bột hành, bột tỏi. Mục đích việc ướp này là để không có xác hành, giúp cho khi chiên sườn không bị cháy khét.', 10);
INSERT INTO public.recipe_steps VALUES (1180, '2025-11-20 17:10:15.320211', '2025-11-20 17:10:15.320211', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 212, 5, 'Đun sôi dầu nóng, hạ nhỏ lửa và gắp sườn vào rán vàng đều các mặt.', 10);
INSERT INTO public.recipe_steps VALUES (1181, '2025-11-20 17:10:15.322357', '2025-11-20 17:10:15.322357', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 212, 7, 'Yêu cầu thành phẩm: Sườn mềm, dễ róc thịt, vị chua mặn ngọt hài hòa, nước sốt sánh lên màu nâu đỏ tự nhiên rất hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (1182, '2025-11-20 17:10:15.455543', '2025-11-20 17:10:15.455543', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 213, 2, 'Riềng rửa sạch thái lát, gừng củ thái lát, hành khô bóc vỏ, băm nhỏ, phần vỏ hành rửa sạch. Thịt ba chỉ cạo sạch, cắt miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1183, '2025-11-20 17:10:15.457142', '2025-11-20 17:10:15.457142', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 213, 5, 'Xếp riềng, gừng thái lát xuống đáy nồi đất, rồi đến dưa cải chua. Cho cá vào cùng nước ướp, xếp đan xen thịt ba chỉ, riềng, gừng, hành khô và dưa cải chua đan xen còn lại.', 10);
INSERT INTO public.recipe_steps VALUES (1184, '2025-11-20 17:10:15.458726', '2025-11-20 17:10:15.458726', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 213, 6, 'Kho cá nên kho tối thiểu 2 lần lửa sẽ thẩm thấu đủ vị, càng kho lâu 3 - 4 lần lửa cá càng ngấm vị săn thịt, đượm vị mà không khô. Nếu kho 10 - 12 tiếng thì ăn được cả xương, thịt cá như tan ra nhưng vẫn săn chắc. Cách kho: Ban đầu cho lửa to, khi nước ướp sôi thì mới cho nước nóng vào xâm xấp, hạ nhỏ lửa sôi đều và kho 1 giờ, tắt bếp, để nguội. Tiếp tục kho, khi hơi cạn thì chêm nước nóng và tắt bếp, kho. Lần cuối kho, khi nước sốt sánh và cạn tới 1/3 nồi thì nên nếm lại gia vị phù hợp, rưới thêm 1 thìa canh nước hàng, 2 thìa canh mỡ lợn giúp cá săn và bóng mướt. Cá nhừ rồi thì nổi lửa to lại chút cho nhanh cạn, tắt bếp và lấy ra ăn cùng cơm nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1185, '2025-11-20 17:10:15.460829', '2025-11-20 17:10:15.460829', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 213, 1, 'Sơ chế cá: Cá làm sạch, cạo bỏ hết màng đen và máu trong bụng, chà xát chanh và muối hạt, rửa sạch bằng nước vo gạo, để ráo rồi ướp trước với 1-2 thìa canh muối hạt giúp cá rắn, đậm vị.', 10);
INSERT INTO public.recipe_steps VALUES (1186, '2025-11-20 17:10:15.463309', '2025-11-20 17:10:15.463309', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 213, 4, 'Ướp cá với 3 thìa canh nước hàng, 2 thìa canh nước mắm ngon 60 độ đạm, 2 thìa canh đường, 2 thìa cà phê hạt tiêu, 1 thìa cà phê hạt nêm, để ngăn mát tủ lạnh ướp tối thiểu 1 tiếng cho ngấm gia vị. Nếu có thời gian, bọc kín màng bọc thực phẩm và để ngăn mát tủ lạnh qua đêm sẽ ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (1187, '2025-11-20 17:10:15.465412', '2025-11-20 17:10:15.465412', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 213, 7, 'Yêu cầu thành phẩm: Cá màu nâu đỏ đậm đà, chắc mà không khô, khi ăn thịt và xương như tan ra, ngấm trọn vị chua cay mặn ngọt; dưa chua ngậm tròn vị cá. Đây là món ăn được người già tới trẻ nhỏ đều yêu thích.', 10);
INSERT INTO public.recipe_steps VALUES (1188, '2025-11-20 17:10:15.467535', '2025-11-20 17:10:15.467535', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 213, 3, 'Dưa cải chua rửa, vắt ráo. Nếu như ở miền Nam dưa cải muối dài thì cắt ngắn thành khúc vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1189, '2025-11-20 17:10:15.597912', '2025-11-20 17:10:15.597912', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 214, 6, 'Thành phẩm:Xôi chín mềm, tơi xốp, cho ra đĩa hoặc vào lá chuối. Thêm gà chiên, chan mỡ hành lên trên cùng với tỏi phi, có thể trang trí dưa leo tỉa hoa để ăn kèm cho đỡ ngán.', 10);
INSERT INTO public.recipe_steps VALUES (1190, '2025-11-20 17:10:15.599996', '2025-11-20 17:10:15.599996', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 214, 3, 'Cho gạo nếp, đậu phộng, nước cốt dừa, 1 muỗng nhỏ cà phê muối vào nồi, trộn đều, nấu chínkhoảng 20 phút.', 10);
INSERT INTO public.recipe_steps VALUES (1191, '2025-11-20 17:10:15.60211', '2025-11-20 17:10:15.60211', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 214, 5, 'Cho 2 muỗng canh dầu ăn, hành lá, tỏi băm vào chảo, đảo đều khoảng 30 giây để làm mỡ hành.', 10);
INSERT INTO public.recipe_steps VALUES (1192, '2025-11-20 17:10:15.603703', '2025-11-20 17:10:15.603703', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 214, 2, 'Hành lá rửa sạch, cắt nhỏ. Thịt gà rửa sạch, ướp với 1 muỗng cà phê đường trắng, 1 muỗng canh nước tương, 1/2 muỗng cà phê tiêu, 1 muỗng cà phê tỏi băm, 1 muỗng cà phê dầu hào và dầu mai quế lộ. Ướp khoảng 10 phút.', 10);
INSERT INTO public.recipe_steps VALUES (1193, '2025-11-20 17:10:15.605303', '2025-11-20 17:10:15.605303', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 214, 1, 'Đậu phộng cho vào nồi luộc chín, xả lại với nước lạnh. Gạo nếp ngâm nước khoảng 3 giờ hoặc qua đêm cho mềm.', 10);
INSERT INTO public.recipe_steps VALUES (1194, '2025-11-20 17:10:15.607425', '2025-11-20 17:10:15.607425', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 214, 4, 'Làm nóng chảo. Cho một lượng dầu ăn vừa đủ, cho thịt má gà đã ướp vào, chiên nhỏ lửa đến khi thịt gà chín vàng đều và giòn là được. Gắp thịt gà ra đĩa, để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (1195, '2025-11-20 17:10:15.730138', '2025-11-20 17:10:15.730138', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 215, 7, 'Yêu cầu thành phẩm: Từng miếng chả ốc dai giòn sần sật, có vị ngọt tự nhiên, dậy mùi thơm của lá lốt rất hợp với thời tiết mùa lạnh.', 10);
INSERT INTO public.recipe_steps VALUES (1196, '2025-11-20 17:10:15.731718', '2025-11-20 17:10:15.731718', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 215, 4, 'Trộn đều ốc đã thái nhỏ với giò sống, thịt xay, lá lốt thái nhỏ, mộc nhĩ ngâm nở thái nhỏ cùng hành, tỏi, gừng, ớt băm nhuyễn. Thêm 1 thìa cà phê nước mắm, 1 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu, trộn đều tạo độ kết dính.', 10);
INSERT INTO public.recipe_steps VALUES (1197, '2025-11-20 17:10:15.732774', '2025-11-20 17:10:15.732774', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 215, 2, 'Lá lốt rửa sạch, để ráo, chọn ra phần lá to để riêng gói chả ốc, phần lá nhỏ thì thái nhỏ để trộn thêm vào nhân chả cho thơm.', 10);
INSERT INTO public.recipe_steps VALUES (1198, '2025-11-20 17:10:15.734241', '2025-11-20 17:10:15.734241', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 215, 1, 'Ốc ngâm nước vo gạo kèm mấy quả ớt cắt lát hoặc đập dập cho nhả hết bùn đất, rửa sạch, đập vỡ trôn ốc rồi khều lấy phần thịt. Bóp thịt ốc với muối hạt và nước cốt chanh, rửa sạch để khử mùi tanh, nhớt. Thái nhỏ thịt ốc để giữ độ sần sật cho món ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1199, '2025-11-20 17:10:15.736794', '2025-11-20 17:10:15.736794', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 215, 5, 'Dùng thìa múc nhân cho vào giữa lá lốt, gập mép hai bên lại và cuốn đều. Làm lần lượt cho tới hết.', 10);
INSERT INTO public.recipe_steps VALUES (1200, '2025-11-20 17:10:15.738356', '2025-11-20 17:10:15.738356', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 215, 6, 'Chiên chả ốc lá lốt trên lửa vừa cho tới khi chín. Gắp chả ốc ra giấy thấm dầu. Nếu không chiên, bạn quết lớp dầu mỏng rồi dùng nồi chiên không dầu hoặc nướng trên than hoa đều ngon.', 10);
INSERT INTO public.recipe_steps VALUES (1201, '2025-11-20 17:10:15.739647', '2025-11-20 17:10:15.739647', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 215, 3, 'Hành, tỏi, gừng, ớt băm nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (1202, '2025-11-20 17:10:15.998296', '2025-11-20 17:10:15.998296', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 216, 5, 'Bỏ tủ mát tầm 3-4 tiếng rồi nặn hoặcxoa dầu ăn ra tay nặn ngay chả ức gà vào cây sả.', 10);
INSERT INTO public.recipe_steps VALUES (1203, '2025-11-20 17:10:15.99991', '2025-11-20 17:10:15.99991', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 216, 8, 'Yêu cầu:Nem màu vàng bắt mắt, có mùi thơm dịu, không bở, thơm ngậy, dai giòn.', 10);
INSERT INTO public.recipe_steps VALUES (1204, '2025-11-20 17:10:16.002055', '2025-11-20 17:10:16.002055', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 216, 2, 'Cho dầu olive vào chảo, cho hạt điều vào thắng lấy dầu màu điều.', 10);
INSERT INTO public.recipe_steps VALUES (1205, '2025-11-20 17:10:16.003657', '2025-11-20 17:10:16.003657', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 216, 3, 'Chế gia vị cho món nem lụi: giã nát 1 củ tỏi, 1 củ hành tím, 1/2 cây sả cắt nhỏ, cho thêm dầu hào, 2/3 chỗ dầu màu điều bên trên, hạt tiêu, mè trắng.Tất cả trộn đều lên.', 10);
INSERT INTO public.recipe_steps VALUES (1206, '2025-11-20 17:10:16.005792', '2025-11-20 17:10:16.005792', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 216, 7, 'Xếp nem ra mẹt ăn kèm bún, cà rốt, dứa gai, dưa chuột bổ dọc và rau thơm.', 10);
INSERT INTO public.recipe_steps VALUES (1207, '2025-11-20 17:10:16.007911', '2025-11-20 17:10:16.007911', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 216, 6, 'Xếp vào khay chiên, xịt dầu, chiên nồi chiên không dầu 200 độ 15-20 phút.', 10);
INSERT INTO public.recipe_steps VALUES (1208, '2025-11-20 17:10:16.010212', '2025-11-20 17:10:16.010212', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 216, 4, 'Cho hai phần thịt gà đã sơ chế vào âu, thêm bột nở nhào đều, thêm phần gia vị trên. Đeo găng tay nilon nhào thật đều.Thành phẩm lúc này hơi nhão.', 10);
INSERT INTO public.recipe_steps VALUES (1209, '2025-11-20 17:10:16.011792', '2025-11-20 17:10:16.011792', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 216, 1, 'Cho 400 g ức gà vào máy xay.Một nửa đem nhào với bột năng, bỏ vào tủ lạnh 1,5-2 tiếng. Sau khi thịt dăm đá cho vào máy xay nhuyễn như giò.Một nửa còn lại bỏ vào âu.', 10);
INSERT INTO public.recipe_steps VALUES (1210, '2025-11-20 17:10:16.11581', '2025-11-20 17:10:16.11581', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 217, 7, 'Khi ăn chấm bắp ngâm với tương đập chút gừng.', 10);
INSERT INTO public.recipe_steps VALUES (1211, '2025-11-20 17:10:16.118143', '2025-11-20 17:10:16.118143', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 217, 1, 'Chọn bắp tươi ngon, rửa sạch trần nhanh qua nước sôi để giảm bớt mùi.', 10);
INSERT INTO public.recipe_steps VALUES (1212, '2025-11-20 17:10:16.120249', '2025-11-20 17:10:16.120249', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 217, 5, 'Xếp bắp bò, tiêu, tỏi (nên dùng tỏi đã ngâm dấm để ăn ngọt giòn hơn, nếu không có thì tỏi sống đập dập) vào lọ thuỷ tinh hoặc lọ nhựa an toàn rồi đổ ngập nước mắm đã đun dùng nẹp nén chặt xuống, đậy kín bảo quản ngăn mát một hôm với thịt đã thái ba hôm với thịt nguyên miếng.', 10);
INSERT INTO public.recipe_steps VALUES (1213, '2025-11-20 17:10:16.122396', '2025-11-20 17:10:16.122396', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 217, 2, 'Cho vào nồi nước, đập sả, gừng, 3 nhánh hồi, 1 ít quế thêm chút muối trắng luộc chín tới. Dùng dụng cụ lọc vớt bọt để tránh mất nước.', 10);
INSERT INTO public.recipe_steps VALUES (1214, '2025-11-20 17:10:16.124601', '2025-11-20 17:10:16.124601', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 217, 4, 'Ngâm cả miếng to hoặc thái miếng vừa ăn. Nước ngâm theo tỉ lệ : 1,5 mắm : 1,5 nước : 1 dấm : 1 đường đập thêm tỏi đun sôi 5 phút sau đó để thật nguội.', 10);
INSERT INTO public.recipe_steps VALUES (1215, '2025-11-20 17:10:16.127317', '2025-11-20 17:10:16.127317', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 217, 3, 'Vớt thịt đã chín ra bát nước đá ngâm đến khi nguội thì để ráo nước, bóp thật kĩ để ngâm không bị váng.', 10);
INSERT INTO public.recipe_steps VALUES (1218, '2025-11-20 17:10:16.228948', '2025-11-20 17:10:16.228948', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 218, 4, 'Làm nổ phần bì: Làm nóng lò nướng trước 10 phút ở 220 độ. Cho thịt vào nướng từ 25- 30 phút cho tới khi bì nổ.', 10);
INSERT INTO public.recipe_steps VALUES (1219, '2025-11-20 17:10:16.231101', '2025-11-20 17:10:16.231101', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 218, 3, 'Thịt ba chỉ cắt thành các miếng kích thước 10cm x 4cm, ngâm nước muối loãng khoảng 30 phút, rửa sạch, thấm thật khô. Đặt giấy bạc, rồi cho từng miếng thịt vào, úp ngược phần bì lên trên rồi gói kín, chỉ để hở phần bì. Phết giấm lên bề mặt bì để vào ngăn mát tủ lạnh cho se lại. Sau đó, rải một lớp muối hạt trắng lên phần bì.', 10);
INSERT INTO public.recipe_steps VALUES (1220, '2025-11-20 17:10:16.23378', '2025-11-20 17:10:16.23378', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 218, 2, 'b- Đồ xôi ngon: Làm song hành trong quá trình kho thịt', 10);
INSERT INTO public.recipe_steps VALUES (1221, '2025-11-20 17:10:16.236454', '2025-11-20 17:10:16.236454', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 218, 5, 'Lấy thịt ra khỏi lò, cạo bỏ phần muối, rửa sạch và cho vào nồi. Ướp thịt với: 2 thìa canh đường, 2 thìa canh nước tương (xì dầu), 2 thìa canh nước màu, 1 thìa canh nước mắm, 1 thìa canh ngũ vị hương, 1 thìa cà phê bột canh, 1 thìa cà phê hạt nêm, 3-4 miếng chao trắng và 2/3 cup nước cùng hành, tỏi băm. Trộn đều ướp trong 1 giờ.', 10);
INSERT INTO public.recipe_steps VALUES (1222, '2025-11-20 17:10:16.239281', '2025-11-20 17:10:16.239281', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 218, 6, 'Kho thịt: Kho thịt lửa nhỏ trong vòng 2 - 2,5 tiếng cho tới khi thịt mềm. Nếu muốn ăn thêm trứng chiên hay giò chả thì cho vào kho cùng. Nêm nếm gia vị lại cho phù hợp khẩu vị gia đình.', 10);
INSERT INTO public.recipe_steps VALUES (1223, '2025-11-20 17:10:16.246481', '2025-11-20 17:10:16.246481', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 218, 1, 'a- Làm phần thịt kho:', 10);
INSERT INTO public.recipe_steps VALUES (1224, '2025-11-20 17:10:16.362568', '2025-11-20 17:10:16.362568', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 219, 1, 'Cách chiên tóp mỡ giòn, béo, không khô, không đắng: Thịt mỡ cắt thành các miếng dài kích thước chiều dài rộng khoảng 3cm*6cm. Cho thịt mỡ vào chảo, thêm chút nước và chiên 2 lần giúp tóp giòn (lần 1 tóp hơi tóp vớt ra để nguội, tiếp tục cho vào chiên lần 2 vàng giòn, vớt ra).', 10);
INSERT INTO public.recipe_steps VALUES (1225, '2025-11-20 17:10:16.364136', '2025-11-20 17:10:16.364136', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 219, 5, 'Yêu cầu thành phẩm: Măng mềm ngon, vàng óng, tóp mỡ vẫn giữ được độ giòn, dậy mùi thơm của tỏi, hành lá rất hấp dẫn. Món ăn này ăn cùng cơm nóng rất ngon, nhanh chóng xua tan giá lạnh mùa đông.', 10);
INSERT INTO public.recipe_steps VALUES (1226, '2025-11-20 17:10:16.365178', '2025-11-20 17:10:16.365178', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 219, 2, 'Sơ chế măng: Măng tước hoặc cắt từng miếng vừa ăn, luộc mở vung 2-3 lần với chút muối hạt, vớt ra, rửa sạch. Ngày xưa, các bà các mẹ hay dùng kim băng để tước măng nhỏ, tước càng nhỏ càng ngon.', 10);
INSERT INTO public.recipe_steps VALUES (1227, '2025-11-20 17:10:16.366784', '2025-11-20 17:10:16.366784', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 219, 3, 'Hành lá rửa sạch, thái khúc. Mùi tàu rửa sạch, thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (1228, '2025-11-20 17:10:16.368389', '2025-11-20 17:10:16.368389', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 219, 4, 'Phi thơm tỏi cùng 2 thìa canh mỡ lợn, cho măng vào xào, nêm nếm mắm, muối vừa miệng theo khẩu vị. Khi măng thấm vị, mềm ngon thì thêm tóp mỡ, hạt nêm đảo đều. Sau đó, cho hành lá, mùi tàu cắt nhỏ vào đảo đều, tắp bếp, múc ra đĩa, rắc thêm chút hạt tiêu, ớt và thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1229, '2025-11-20 17:10:16.535405', '2025-11-20 17:10:16.535405', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 220, 2, 'Cà chua rửa sạch, khía hình chữ thập trên quả, cho vào nước sôi chần 1-2 phút cho vỏ bong, vớt ra ngâm vào nước lạnh, bóc tách bỏ vỏ, băm nhuyễn. Cà chua bỏ vỏ giúp cho sốt vang sánh mịn và hấp dẫn hơn.', 10);
INSERT INTO public.recipe_steps VALUES (1230, '2025-11-20 17:10:16.538735', '2025-11-20 17:10:16.538735', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 220, 1, 'Thịt bò dẻ sườn rửa sạch, thấm khô, thái miếng bao diêm to. Ướp thịt bò với 2 thìa canh nước mắm, 1 thìa cà phê muối (bột canh), 2 thìa cà phê hạt nêm, 2 thìa cà phê hạt tiêu, 2 thìa cà phê ớt bột paprika (tùy chọn), 3-4 thìa canh dầu màu điều giúp lên màu đẹp, gừng giã (băm) nhuyễn, 1/2 phần tỏi băm cùng quế, hồi thảo quả rang thơm cùng rượu vang đỏ (nếu không có thì dùng rượu trắng). Tất cả trộn đều và ướp tối thiểu trong 1 giờ. Nếu có thời gian, bọc màng bọc thực phẩm để qua đêm trong tủ lạnh sẽ thấm đủ vị và ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (1231, '2025-11-20 17:10:16.540866', '2025-11-20 17:10:16.540866', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 220, 5, 'Trút cà chua mềm đỏ au, cùng nước ướp vào thịt bò đã xào săn, thêm lượng nước ngập bề mặt. Nếu muốn lên màu đẹp hơn, bạn có thể cho thêm ketchup. Nêm nếm lại gia vị mắm, muối, hạt nêm theo khẩu vị gia đình. Khi nước sôi, hạ nhở lửa và ninh tối thiểu trong 1 giờ hoặc cho tới khi thịt mềm, nước dùng sốt sánh lại. Nếu muốn sánh mượt hơn, bạn có thể dùng một trong 2 cách sau: Cách gốc của người Pháp là xào chút bột mì với bơ cho vào, hoặc nhanh hơn thì cho chút bột năng hòa tan với nước rồi cho vào nồi bò sốt vang khuấy nhẹ đều cho tới khi đạt độ sánh như mong muốn. Vớt bỏ quế, hồi, thảo quả và như vậy là sốt vang đã hoàn thành.', 10);
INSERT INTO public.recipe_steps VALUES (1232, '2025-11-20 17:10:16.543011', '2025-11-20 17:10:16.543011', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 220, 6, 'Yêu cầu thành phẩm: Thịt bò mềm mà không nát, nước màu nâu đỏ hơi sánh lại, dậy mùi thơm đặc trưng của sốt vang từ quế hồi thảo quả, nổi bật với gốc hành chần, rau mùi rất hấp dẫn. Món này ăn với bánh mì hay phở đều rất ngon, nhất là vào tiết lạnh của mùa đông.', 10);
INSERT INTO public.recipe_steps VALUES (1233, '2025-11-20 17:10:16.545994', '2025-11-20 17:10:16.545994', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 220, 3, 'Phi thơm 1-2 thìa canh bơ với tỏi còn lại, cho cà chua vào, nêm chút mắm muối để cà chua nhanh mềm, trút ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (1234, '2025-11-20 17:10:16.548098', '2025-11-20 17:10:16.548098', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 220, 4, 'Cho 1-2 thìa canh bơ vào chảo, trút thịt bò đã ướp vào xào săn để ngấm trọn gia vị vào trong thịt bò.', 10);
INSERT INTO public.recipe_steps VALUES (1255, '2025-11-20 17:10:17.015119', '2025-11-20 17:10:17.015119', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 223, 3, '- Rửa thịt bò, để ráo, thái miếng dài 4 cm, ngang 1,5 cm, dày 0,2 cm. Ướp thịt bò với 1/2 thìa cà phê hạt nêm, 1/3 thìa cà phê tiêu, 1 thìa súp nước tương, 1/2 thìa cà phê bột năng và 1/2 thìa súp dầu ăn. Khoai tây gọt vỏ, rửa sạch, dùng dao răng cưa xắn thành từng khoanh dày 0,5 cm, sau đó xắn thanh dài. Đun nóng 1/2 bát dầu ăn, cho khoai tây vào rán giòn, vớt ra.', 10);
INSERT INTO public.recipe_steps VALUES (1256, '2025-11-20 17:10:17.199294', '2025-11-20 17:10:17.199294', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 224, 1, 'Thịt ba chỉ rửa sạch với muối, chanh, giấm. Dùng nước sôi trần qua thịt rồi rửa sạch lại với nước. Luộc thịt nhỏ lửa 15 - 20 phút, vớt ra ngâm nước lạnh 5 phút.', 10);
INSERT INTO public.recipe_steps VALUES (1235, '2025-11-20 17:10:16.670288', '2025-11-20 17:10:16.670288', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 221, 1, 'Trứng non cho vào nước sôi kèm chút muối hạt, vài lát hành khô, luộc trong 3 - 4 phút cho trứng chín tới, vớt ra rửa sạch, cắt phần tràng thành miếng vừa ăn, để ráo.
INSERT INTO public.recipe_steps VALUES (1236, '2025-11-20 17:10:16.833347', '2025-11-20 17:10:16.833347', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 222, 2, 'Sơ chế cá: Cá làm sạch, cạo hết màng đen, máu trong bụng cá rồi chà xát muối hạt, chanh. Sau đó, rửa bằng nước vo gạo, rồi rửa sạch lại để khử mùi tanh.', 10);
INSERT INTO public.recipe_steps VALUES (1237, '2025-11-20 17:10:16.835595', '2025-11-20 17:10:16.835595', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 222, 4, 'Sơ chế chuối: Chuối xanh gọt vỏ, thái con chì, ngâm vào nước lạnh pha chút giấm (hoặc chanh) để chuối không bị thâm.', 10);
INSERT INTO public.recipe_steps VALUES (1238, '2025-11-20 17:10:16.837738', '2025-11-20 17:10:16.837738', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 222, 7, 'Yêu cầu thành phẩm:Cá lên màu bóng đẹp, chắc thịt, đậm đà ngậm tròn trịa các vị: bùi bùi của chuối, cay cay của ớt, thơm của riềng, lá gừng non làm nên một món ngon khó chối từ trong mùa đông khi ăn cùng cơm nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1239, '2025-11-20 17:10:16.83986', '2025-11-20 17:10:16.83986', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 222, 3, 'Ướp cá với phần hành khô băm cùng 3 thìa canh nước mắm, 3 thìa canh nước hàng, 3 thìa cà phê đường, 2 thìa cà phê muối, 1 thìa cà phê hạt tiêu, 1/2 thìa cà phê mì chính (hoặc hạt nêm), 1/2 nước cốt quả chanh, để ngăn mát tủ lạnh ướp tối thiểu 1 tiếng cho thấm gia vị. Nếu ướp lâu sẽ giúp đanh cá ngon hơn, nhớ bọc màng bọc thực phẩm và để ngăn mát tủ lạnh.', 10);
INSERT INTO public.recipe_steps VALUES (1240, '2025-11-20 17:10:16.842008', '2025-11-20 17:10:16.842008', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 222, 5, 'Xếp riềng xuống đáy nồi đất, tiếp đến là gừng củ, thân cây gừng, 1/2 lá gừng non, thịt ba chỉ, rồi tới cá và chuối xen kẽ. Cuối cùng cho ớt quả cùng số lá gừng non, hành vỏ khô. Trút phần nước ướp cá vào.', 10);
INSERT INTO public.recipe_steps VALUES (1241, '2025-11-20 17:10:16.8436', '2025-11-20 17:10:16.8436', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 222, 1, 'Riềng rửa sạch thái lát, gừng củ thái lát, cây gừng và lá gừng non rửa sạch thái khúc, hành khô bóc vỏ, băm nhỏ, phần vỏ hành rửa sạch giữ lại để kho cá rất ngon. Thịt ba chỉ rửa sạch, thái miếng dài 5 - 6 cm.', 10);
INSERT INTO public.recipe_steps VALUES (1242, '2025-11-20 17:10:16.845559', '2025-11-20 17:10:16.845559', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 222, 6, 'Kho cá ít nhất 2 lần lửa sẽ thơm ngon, càng kho lâu 3  - 4 lần lửa thì cá càng chắc thịt và đậm đà.Kho lần 1: Đặt nồi cá lên bếp, thêm nước nóng vào ngập mặt cá, khi sôi thì hạ nhỏ lửa và kho cá trong 1,5 giờ. Tắt bếp, để nguội. Kho lần 2: Nếu lượng nước vơi đi thì chêm thêm nước nóng và tiếp tục kho nhỏ lửa trong 1,5 giờ nữa. Nếu có thời gian, bạn lại tiếp tục kho lần 3, càng kho cá càng đậm vị và mềm rục xương rất ngon. Khi nước kho cạn tới 1/3 nồi, nêm nếm lại gia vị cho phù hợp, rưới thêm 1 thìa canh nước hàng và 2 thìa canh mỡ lợn và đun nhỏ lửa, mở vung sẽ giúp cá săn chắc, bóng mướt và lên màu đẹp.', 10);
INSERT INTO public.recipe_steps VALUES (1243, '2025-11-20 17:10:16.993912', '2025-11-20 17:10:16.993912', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 223, 4, '- Phi thơm tỏi băm. Cho thịt bò vào xào tái trên lửa lớn. Kế đó cho khoai tây vào đảo đều, tắt bếp, rắc 1/2 thìa cà phê tiêu.', 10);
INSERT INTO public.recipe_steps VALUES (1244, '2025-11-20 17:10:16.996033', '2025-11-20 17:10:16.996033', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 223, 13, '- Bày ra đĩa. Cắt khúc rau quế rồi rắc lên.', 10);
INSERT INTO public.recipe_steps VALUES (1245, '2025-11-20 17:10:16.99764', '2025-11-20 17:10:16.99764', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 223, 9, '- Múc cá ra đĩa, rắc thêm tiêu xanh', 10);
INSERT INTO public.recipe_steps VALUES (1246, '2025-11-20 17:10:16.999494', '2025-11-20 17:10:16.999494', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 223, 12, '- Luộc chín mít non, rửa qua nước muối pha loãng, cắt bỏ cùi, xé miếng dày 1cm. Tỏi bóc vỏ, băm nhuyễn. Lạc rang chà sạch vỏ, giã giập. Phi thơm tỏi băm và 2 thìa súp dầu ăn. Cho mít vào đảo nhanh tay. Nêm 2 thìa cà phê hạt nêm, 1/4 thìa cà phê muối và 1/2 thìa cà phê đường. Đến khi mít chín, tắt bếp, rắc lạc rang vào, trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (1247, '2025-11-20 17:10:17.001095', '2025-11-20 17:10:17.001095', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 223, 2, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1248, '2025-11-20 17:10:17.002795', '2025-11-20 17:10:17.002795', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 223, 1, 'Khoai tây xào thịt bò
INSERT INTO public.recipe_steps VALUES (1249, '2025-11-20 17:10:17.004942', '2025-11-20 17:10:17.004942', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 223, 10, 'Mít non xào tỏi
INSERT INTO public.recipe_steps VALUES (1250, '2025-11-20 17:10:17.006529', '2025-11-20 17:10:17.006529', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 223, 5, 'Cá hú kho tiêu xanh
INSERT INTO public.recipe_steps VALUES (1251, '2025-11-20 17:10:17.0081', '2025-11-20 17:10:17.0081', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 223, 6, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1252, '2025-11-20 17:10:17.009684', '2025-11-20 17:10:17.009684', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 223, 7, '- Cá chà muối cho sạch, rửa lại với nước, để ráo. Tiêu xanh cắt bỏ phần cọng thừa, rửa sạch, để nguyên nhánh nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (1253, '2025-11-20 17:10:17.011375', '2025-11-20 17:10:17.011375', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 223, 8, '- Ướp cá và tiêu xanh với 4 thìa súp nước mắm, 3 thìa súp đường và 2 thìa cà phê hạt nêm trong khoảng 5 đến 10 phút cho thấm gia vị. Cho cá vào nối, đun trên lửa vừa khi nước trong nồi hơi đặc sánh lại. Cho ớt vào, đun thêm 1 phút nữa, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (1254, '2025-11-20 17:10:17.012966', '2025-11-20 17:10:17.012966', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 223, 11, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1257, '2025-11-20 17:10:17.200894', '2025-11-20 17:10:17.200894', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 224, 4, 'Đặt chảo lên bếp, cho dầu vào đun già, cho thịt heo vào quay.', 10);
INSERT INTO public.recipe_steps VALUES (1259, '2025-11-20 17:10:17.20486', '2025-11-20 17:10:17.20486', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 224, 6, 'Cho xương ống heo hầm 45 phút trong nồi cùng hành tây, sả, gừng và gói gia vị nấu phở.Hầm cho đến khi nước dùng chuyển màu vàng đục, có mùi thơm thì vớt hết các nguyên liệu trong nồi ra để nước dùng trong hơn.', 10);
INSERT INTO public.recipe_steps VALUES (1260, '2025-11-20 17:10:17.206975', '2025-11-20 17:10:17.206975', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 224, 2, 'Dùng dĩa nhọn châm lên phần bì tạo thành nhiều lỗ. Đây là cách giúp phần bì khi quay trở nên giòn hơn. Sau đó dùng khăn lau lại phần bì đã châm.', 10);
INSERT INTO public.recipe_steps VALUES (1261, '2025-11-20 17:10:17.209112', '2025-11-20 17:10:17.209112', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 224, 5, 'Chiên thịt vừa lửa cho tới khi phần da nổ lụp bụp thì để lửa to hơn. Chiên đến khi bì chuyển hẳn sang màu vàng nâu (khoảng 10 phút). Tiếp tục chiên các mặt còn lại thêm vài phút cho chín hẳn rồi tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (1262, '2025-11-20 17:10:17.210699', '2025-11-20 17:10:17.210699', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 224, 3, 'Phần mặt bì nên xát một lớp muối mỏng (khoảng 1 thìa cà phê). Sau đó cho tỏi xay nhuyễn, ngũ vị hương, dầu ăn, một thìa nước mắm vào miếng thịt rồi trộn cho gia vị ngấm đều, ướp 10 phút. Khi cho vào chảo quay, cần gạt tỏi bám trên bề mặt thịt, tránh làm tỏi bị cháy.', 10);
INSERT INTO public.recipe_steps VALUES (1263, '2025-11-20 17:10:17.2123', '2025-11-20 17:10:17.2123', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 224, 8, 'Chuẩn bị tô lớn, cho hành giá vừa chần vào đáy tô, rồi đến bánh phở. Cho thịt heo quay vào tô, cuối cùng chan nước dùng nóng hổi và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (1264, '2025-11-20 17:10:17.414911', '2025-11-20 17:10:17.414911', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 225, 4, 'Cách làm:Luộc mì Ý trong nước sôi khoảng 8 phút. Lấy ra, rửa sạch với nước ấm. Bắc chảo lên bếp cho nóng rồi xào hành tây với tỏi cho thơm, cho cà chua băm nhuyễn, thịt bò băm nhuyễn. Bỏ cà chua hộp vào xào chung cho thơm, nêm gia vị vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1265, '2025-11-20 17:10:17.41726', '2025-11-20 17:10:17.41726', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 225, 6, 'Cơm chiên nho
INSERT INTO public.recipe_steps VALUES (1266, '2025-11-20 17:10:17.419369', '2025-11-20 17:10:17.419369', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 225, 2, 'Cách làm:Xào cà chua cho thơm, đổ rượu vang vào đun sắc cho hết cồn, cho tiếp nước dùng vào. Bỏ nghệ tây, rau mùi, nêm gia vị vừa ăn. Khi dùng, đun nước sôi, cho hải sản vào. Dùng với các loại rau ưa thích. Có thể ăn với bún hay mì tùy thích.', 10);
INSERT INTO public.recipe_steps VALUES (1267, '2025-11-20 17:10:17.420955', '2025-11-20 17:10:17.420955', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 225, 5, 'Tưới sốt này lên mỳ dùng nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1268, '2025-11-20 17:10:17.423147', '2025-11-20 17:10:17.423147', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 225, 9, 'Cách làm: Hàu rửa sạch, tách vỏ ra làm đôi. Hành tây bằm nhuyễn, vắt nước chanh, sau đó hòa với đường cho tan đều. Bắc chảo lên bếp, chờ cho chảo nóng rồi xào hành tây cho thơm, cho nước chanh vào, nêm gia vị vừa ăn, sau đó cho tiếp bơ vào.', 10);
INSERT INTO public.recipe_steps VALUES (1269, '2025-11-20 17:10:17.425802', '2025-11-20 17:10:17.425802', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 225, 3, 'Mỳ bò băm
INSERT INTO public.recipe_steps VALUES (1270, '2025-11-20 17:10:17.427841', '2025-11-20 17:10:17.427841', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 225, 7, 'Cách làm:Đặt chảo lên bếp, chờ chảo nóng cho bơ vào, xào nho, cà rốt, bắp Mỹ cho thơm. Cho cơm trắng vào xào tiếp, nêm gia vị vừa ăn. Rắc ngò tây lên trên, xúc ra đĩa, dùng nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1271, '2025-11-20 17:10:17.42978', '2025-11-20 17:10:17.42978', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 225, 8, 'Hàu sốt bơ chanh
INSERT INTO public.recipe_steps VALUES (1272, '2025-11-20 17:10:17.433807', '2025-11-20 17:10:17.433807', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 225, 10, 'Đổ hỗn hợp này lên trên hàu, đem đút lò khoảng 10 phút, lấy ra dùng nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1273, '2025-11-20 17:10:17.435922', '2025-11-20 17:10:17.435922', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 225, 1, 'Lẩu hải sản Pháp
INSERT INTO public.recipe_steps VALUES (1274, '2025-11-20 17:10:17.634445', '2025-11-20 17:10:17.634445', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 226, 7, 'Yêu cầu:Thịt màu mận, mùi thơm ngọt, nước chấm vị chua ngọt, thanh vị dứa, đượm mùi tỏi, chanh.', 10);
INSERT INTO public.recipe_steps VALUES (1275, '2025-11-20 17:10:17.636028', '2025-11-20 17:10:17.636028', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 226, 4, 'Lấy ra phết hỗn hợp: 1 thìa dầu hào, chút dầu ăn, nước ướp thịt còn dư; nướng thêm 3-5 phút nữa cho thịt xém xém và màu đẹp hơn.[Caption]', 10);
INSERT INTO public.recipe_steps VALUES (1276, '2025-11-20 17:10:17.63762', '2025-11-20 17:10:17.63762', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 226, 5, 'Làm nước chấm bún:Cà rốt, dưa chuột thái vừa ăn, trộn đều với muối, đường, chanh, bỏ tủ lạnh 30 phút-một tiếng. Sau đó bỏ nước giữ lại nộm.', 10);
INSERT INTO public.recipe_steps VALUES (1277, '2025-11-20 17:10:17.640376', '2025-11-20 17:10:17.640376', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 226, 6, 'Cho 1/2 bát tô nước vào nồi, thêm đường, mắm và vài lát dứa đun nhỏ lửa, lọc bỏ dứa lấy nước mắm để nguội. Thêm nước chanh, nêm nếm mặn ngọt cho vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1278, '2025-11-20 17:10:17.642522', '2025-11-20 17:10:17.642522', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 226, 1, 'Sơ chế thịt lợn: Thịt mua về rửa sạch, thái mỏng vừa ăn. Trộn thịt với  nước mắm, mật ong, dầu điều. Ướp tầm 2-3h là hoặc để qua đêm thịt càng ngon mềm.', 10);
INSERT INTO public.recipe_steps VALUES (1279, '2025-11-20 17:10:17.64475', '2025-11-20 17:10:17.64475', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 226, 2, 'Sau khi ướp bạn xiên thịt vào que, đừng dồn quá chặt. Phần nước ướp thịt còn trong bát giữ lại.[Caption]', 10);
INSERT INTO public.recipe_steps VALUES (1280, '2025-11-20 17:10:17.646866', '2025-11-20 17:10:17.646866', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 226, 3, 'Nướng bằng nồi chiên không dầu 200 độ trong 10 phút (lật sau 5 phút nếu nồi không có chế độ nhiệt trên dưới).[Caption]', 10);
INSERT INTO public.recipe_steps VALUES (1281, '2025-11-20 17:10:17.771951', '2025-11-20 17:10:17.771951', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 227, 1, 'Nem ốc
INSERT INTO public.recipe_steps VALUES (1282, '2025-11-20 17:10:17.773542', '2025-11-20 17:10:17.773542', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 227, 4, 'Cách làm:Cá rô làm sạch, nướng chín, để nguội bóc lấy thịt xào với hành khô, tiêu, mì chính cho quyện đều. Gạo nếp ngâm kỹ, vo sạch để ráo, rắc thêm chút muối đồ chín. Sau đó rắc phủ thịt rô đồng đã xào chín lên mặt xôi sao cho đều, đẹp mắt.', 10);
INSERT INTO public.recipe_steps VALUES (1377, '2025-11-20 17:10:19.360308', '2025-11-20 17:10:19.360308', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 239, 5, 'Sau 2 phút trứng bám đều và niễng chín, thêm rau mùi, hành đảo đều, rắc hạt tiêu, tắt bếp, múc ra thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1283, '2025-11-20 17:10:17.775612', '2025-11-20 17:10:17.775612', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 227, 6, 'Cách làm:Sứa làm sạch, trần qua nước sôi. Dứa gọt vỏ, bỏ mắt, thái chỉ. Khế xanh thái chỉ. Tỏi, ớt băm nhỏ vắt lấy nước cốt. Rau kinh giới thái nhỏ. Sau đó, trộn đều các nguyên liệu trên với gia vị sao cho đều, thêm chút đường, muối vừa ăn. Để 10 phút cho ngấm rồi bày ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (1284, '2025-11-20 17:10:17.777208', '2025-11-20 17:10:17.777208', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 227, 8, 'Cách làm:Ghẹ làm sạch, chặt làm 4 (bỏ đầu chân, đầu càng). Phi thơm tỏi, cho ghẹ và gia vị vào xào lăn thật đều. Chế nước dùng vào đun sôi. Chờ ghẹ chín cho rau muống vào. Trước khi bóc ra cho thêm chút rau ngổ để dậy mùi thơm.', 10);
INSERT INTO public.recipe_steps VALUES (1285, '2025-11-20 17:10:17.778274', '2025-11-20 17:10:17.778274', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 227, 7, 'Canh ghẹ rau muống
INSERT INTO public.recipe_steps VALUES (1286, '2025-11-20 17:10:17.780325', '2025-11-20 17:10:17.780325', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 227, 2, 'Cách làm:Ốc làm sạch luộc chín, khêu ruột, rửa sạch và thái nhỏ. Mộc nhĩ đem ngâm nở, rửa sạch, thái nhỏ. Trộn đều các gia vị với giò sống, thịt ốc, sau đó, cuốn lại thành nem, chiên vàng trong dầu ăn nóng già. Nem ốc chấm với nước mắm chua ngọt rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (1287, '2025-11-20 17:10:17.781898', '2025-11-20 17:10:17.781898', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 227, 3, 'Xôi rô đồng
INSERT INTO public.recipe_steps VALUES (1288, '2025-11-20 17:10:17.783641', '2025-11-20 17:10:17.783641', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 227, 5, 'Gỏi sứa
INSERT INTO public.recipe_steps VALUES (1289, '2025-11-20 17:10:17.896143', '2025-11-20 17:10:17.896143', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 228, 6, 'Thêm đậu phụ chiên vào, đảo đều trong cho thấm gia vị trong 2 -3 phút.', 10);
INSERT INTO public.recipe_steps VALUES (1290, '2025-11-20 17:10:17.898825', '2025-11-20 17:10:17.898825', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 228, 4, 'Thịt ba chỉ ngâm nước muối loãng 30 phút, rửa sạch, thấm khô, thái con chì vừa ăn, cho thịt vào chiên sơ. Khi thịt sém cạnh, tắt bếp, ướp thịt với 1 thìa canh nước mắm, 1 thìa canh mắm tôm, 1 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu.', 10);
INSERT INTO public.recipe_steps VALUES (1291, '2025-11-20 17:10:17.901518', '2025-11-20 17:10:17.901518', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 228, 1, 'Đậu phụ cắt miếng vuông vừa ăn, chiên vàng già.', 10);
INSERT INTO public.recipe_steps VALUES (1292, '2025-11-20 17:10:17.903649', '2025-11-20 17:10:17.903649', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 228, 3, '5 quả chuối còn lại tước vỏ, thái con chì, ngâm nước pha giấm (hoặc chanh) để giữ chuối không bị thâm. Luộc sơ chuối với chút nước bột nghệ khoảng 1 phút (cho luộc sau chuối nguyên quả cũng được). Vớt ra ngâm vào nước lạnh, để ráo nước. Sử dụng luôn dầu chiên đậu phụ, cho chuối vào chiên sơ để giúp chuối vẫn giữ độ cứng, không bị nhũn khi om.', 10);
INSERT INTO public.recipe_steps VALUES (1293, '2025-11-20 17:10:17.906685', '2025-11-20 17:10:17.906685', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 228, 2, 'Sơ chế chuối xanh: Lấy riêng 2 quả đem luộc cùng chút bột nghệ, khi chuối chín, bóc vỏ, xay mịn cùng nước luộc để tạo độ sánh tự nhiên cho món ăn. Mẻ lọc qua rây cho mịn, các rau gia vị (Hành lá, tía tô, lá lốt) rửa sạch, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (1294, '2025-11-20 17:10:17.909479', '2025-11-20 17:10:17.909479', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 228, 5, 'Phi thơm hành khô, cho thịt ba chỉ đã ướp vào xào sơ. Cho nước sôi vào vừa đủ, thêm mẻ, chuối xay ở trên vào, đảo đều và om 15 -20 phút cho thịt mềm. Sau đó, cho chuối thái con chì đã chiên sơ vào, nêm nếm gia vị phù hợp và om thêm 3-4 phút cho chuối thấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (1295, '2025-11-20 17:10:17.912134', '2025-11-20 17:10:17.912134', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 228, 8, 'Yêu cầu thành phẩm: Thịt ba chỉ săn, béo ngậy, chuối chín mềm mà không bở, đậu giòn, nước sánh vàng ươm tự nhiên. Món này ăn cùng cơm nóng và bún đều rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (1296, '2025-11-20 17:10:17.914837', '2025-11-20 17:10:17.914837', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 228, 7, 'Thêm lá lốt, tía tô, hành lá thái nhỏ vào, đảo đều, tắt bếp, múc ra và thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1297, '2025-11-20 17:10:18.050508', '2025-11-20 17:10:18.050508', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 229, 9, 'Phi thơm tỏi băm với 2 thìa súp dầu ăn, cho nghêu vào đảo đều rồi cho bí đỏ và nấm đông cô vào xào cùng 3 thìa súp nước. Nêm gia vị gồm 1 thìa súp bột nêm và 2 thìa cà phê đường. Khi bí đỏ chín hơi mềm, cho hành tây vào xào thêm 1 phút, tắt bếp. Bày ra đĩa. Rắc hành lá lên.', 10);
INSERT INTO public.recipe_steps VALUES (1298, '2025-11-20 17:10:18.052108', '2025-11-20 17:10:18.052108', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 229, 1, 'Canh rong biển sườn non
INSERT INTO public.recipe_steps VALUES (1299, '2025-11-20 17:10:18.05369', '2025-11-20 17:10:18.05369', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 229, 4, 'Bò kho ớt
INSERT INTO public.recipe_steps VALUES (1300, '2025-11-20 17:10:18.054754', '2025-11-20 17:10:18.054754', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 229, 6, 'Gừng non rửa sạch, cạo vỏ, đê nguyên củ. Ớt sừng thái khúc dài 2 cm (có thể bỏ hạt). Hành tím bóc vỏ, củ nhỏ để nguyên, củ lớn chẻ đôi theo chiều ngang. Bắp bò cho vào nồi, kho trên lửa vừa. Khi bò săn lại, cho gừng và ớt vào kho chung. Khoảng 5 phút sau thì bắp bò ngấm nhưng còn hơi dai, cho tiếp hành tím vào, kho thêm 2 phút, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (1301, '2025-11-20 17:10:18.056868', '2025-11-20 17:10:18.056868', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 229, 2, 'Cách làm:Sườn non chà muối cho sạch, rửa rồi để ráo, chặt khúc dài 2cm. Rong biển ngâm vào nước cho mềm, vớt ra, để ráo. Đậu hũ trắng thái miếng vuông, cạnh 1,5cm. Gừng gọt vỏ, thái sợi nhuyễn, hành lá thái xéo.', 10);
INSERT INTO public.recipe_steps VALUES (1302, '2025-11-20 17:10:18.058473', '2025-11-20 17:10:18.058473', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 229, 12, 'Phi thơm tỏi băm và gừng thái sợi với 1,5 thìa súp dầu ăn. Cho ếch vào xào. Nêm gia vị gồm 1 thìa súp hắc xì dầu, 1 thìa súp nước tương, 2 thìa súp tương ớt, 1/2 thìa súp bột nêm và 1 thìa súp đường. 2 phút sau, cho 1/2 bát nước vào. Đun 3 phút, cho ớt chuông và hành tím vào xào, đảo đều. Trút vào thố đất, đun trên lửa liu riu đến khi ếch mềm, tắt bếp. Rắc 1/2 thìa cà phê tiêu.', 10);
INSERT INTO public.recipe_steps VALUES (1303, '2025-11-20 17:10:18.060569', '2025-11-20 17:10:18.060569', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 229, 7, 'Bí đỏ xào nghêu
INSERT INTO public.recipe_steps VALUES (1304, '2025-11-20 17:10:18.062694', '2025-11-20 17:10:18.062694', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 229, 11, 'Cách làm:Ếch rửa sạch, để ráo, chặt làm tư. Ớt chuông đỏ, xanh vàng thái miếng vuông, cạnh 1,5cm. Hành tím bóc vỏ, củ lớn chẻ đôi, củ nhỏ để nguyên. Gừng gọt vỏ, thái sợi nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (1305, '2025-11-20 17:10:18.064815', '2025-11-20 17:10:18.064815', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 229, 3, 'Đun sôi 1 lít nước, cho sườn non vào đun sôi, hớt bọt. Đun khoảng 15 phút để sườn non chín mềm, cho rong biển và đậu hũ trắng vào, đun thêm 2 phút. Nêm 1 thìa cà phê bột nêm, 1/2 thìa cà phê đường và 1 thìa cà phê nước mắm. Tắt bếp, thả gừng vào. Múc canh ra tô, bày sườn non, rong biển và đậu hũ trắng sao cho mỗi thứ một góc. Sau đó, rắc đều hành lá lên.', 10);
INSERT INTO public.recipe_steps VALUES (1306, '2025-11-20 17:10:18.066416', '2025-11-20 17:10:18.066416', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 229, 10, 'Ếch tay cầm
INSERT INTO public.recipe_steps VALUES (1307, '2025-11-20 17:10:18.068172', '2025-11-20 17:10:18.068172', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 229, 5, 'Cách làm:Bắp bò luộc chín, thái khoanh mỏng. Ướp với 4 thìa súp nước mắm, 1 thìa súp đường, 1thìa cà phê bột nêm và 1 thìa cà phê tiêu.', 10);
INSERT INTO public.recipe_steps VALUES (1308, '2025-11-20 17:10:18.07032', '2025-11-20 17:10:18.07032', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 229, 8, 'Cách làm:Nghêu rửa sạch, để ráo. Bí gọt vỏ, dùng dao răng cưa thái thành từng khoanh dài 4 cm, ngang 0,5 cm đến 1 cm. Hành lá thái khúc dài 1,5 cm', 10);
INSERT INTO public.recipe_steps VALUES (1309, '2025-11-20 17:10:18.177068', '2025-11-20 17:10:18.177068', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 230, 1, 'Rau sắn vắt bớt nước chua.', 10);
INSERT INTO public.recipe_steps VALUES (1310, '2025-11-20 17:10:18.179199', '2025-11-20 17:10:18.179199', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 230, 4, 'Cho rau sắn chua vào nồi ninh cùng sườn cho tới mềm. Điểm đặc biệt của canh này là càng hầm mềm nhừ càng ngon. Bởi bao nhiêu vị ngọt tự nhiên từ sườn sẽ ngấm vào rau sắn và ngược lại, vị chua từ rau sắn ngấm vào sườn thêm cân bằng vị. Nêm nếm gia vị phù hợp khẩu vị gia đình, múc ra thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1311, '2025-11-20 17:10:18.182527', '2025-11-20 17:10:18.182527', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 230, 2, 'Sườn chặt miếng vừa ăn, ngâm vào nước muối loãng 30 phút, rửa sạch, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (1312, '2025-11-20 17:10:18.184122', '2025-11-20 17:10:18.184122', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 230, 3, 'Phi thơm hành khô, cho sườn vào xào sơ, nêm nếm chút gia vị cho sườn đậm đà. Thêm lượng nước vừa đủ, ninh sườn trong khoảng 30 phút cho chín mềm.', 10);
INSERT INTO public.recipe_steps VALUES (1313, '2025-11-20 17:10:18.186704', '2025-11-20 17:10:18.186704', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 230, 5, 'Yêu cầu thành phẩm:Rau sắn chua nhẹ hòa quyện cùng sườn mềm ngọt, dậy mùi thơm ngai ngái đặc trưng làm nên món đặc sản của người dân Phú Thọ.', 10);
INSERT INTO public.recipe_steps VALUES (1314, '2025-11-20 17:10:18.284001', '2025-11-20 17:10:18.284001', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 231, 2, 'Cà chua bổ múi cau, dứa thái vát, hành lá, rau mùi tàu, thì là cắt nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (1315, '2025-11-20 17:10:18.286122', '2025-11-20 17:10:18.286122', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 231, 1, 'Cá khoai cắt đầu, rút ruột, bóc bỏ phần trắng bên trong bụng, rửa sạch cùng chanh vừa giúp khử tanh vừa giúp đanh cá hơn, để ráo. Cá để nguyên hoặc cắt khúc rồi ướp với 1 thìa cà phê muối, 1/2 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu, 1/4 thìa cà phê bột nghệ (hoặc chút nghệ tươi giã), hành băm trong khoảng 15-20 phút.', 10);
INSERT INTO public.recipe_steps VALUES (1316, '2025-11-20 17:10:18.288498', '2025-11-20 17:10:18.288498', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 231, 5, 'Yêu cầu thành phẩm:Cá khoai thịt chín trắng mềm, vị ngọt tự nhiên, nước canh chua nhẹ, ngọt thanh, dậy mùi thơm của thì là, hành lá. Món này ăn nóng nhanh chóng xua tan giá lạnh của mùa đông.', 10);
INSERT INTO public.recipe_steps VALUES (1317, '2025-11-20 17:10:18.291168', '2025-11-20 17:10:18.291168', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 231, 3, 'Phi thơm hành, cho 1/2 cà chua vào xào tạo màu, thêm dứa và lượng nước vừa đủ, nêm nếm gia vị phù hợp.', 10);
INSERT INTO public.recipe_steps VALUES (1318, '2025-11-20 17:10:18.292792', '2025-11-20 17:10:18.292792', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 231, 4, 'Khi nước sôi, cho cá khoai và số cà chua bổ múi cau còn lại vào. Nếu thích ăn chua có thể thêm nước cốt me hoặc tăng lượng cà chua lên, đun lửa vừa, không đảo để tránh nát cá. Khi cá chuyển sang màu trắng là đã chín, cho thì là, rau ngổ, hành lá và ớt vào, tắt bếp. Vắt thêm chút nước cốt chanh vào và thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1319, '2025-11-20 17:10:18.479682', '2025-11-20 17:10:18.479682', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 232, 12, 'Xếp gan ra đĩa, trang trí chanh, rưới xốt chanh dùng nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1320, '2025-11-20 17:10:18.481278', '2025-11-20 17:10:18.481278', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 232, 11, 'Đun nước cốt chanh, nước hành tây, đường, ớt sừng băm, muối tiêu trên lửa nhỏ. Cho bột mì pha nước vào để hỗn hợp sánh lại. Đun chảy bơ, phi thơm tỏi, cho gan vịt vào rán vàng.', 10);
INSERT INTO public.recipe_steps VALUES (1321, '2025-11-20 17:10:18.483435', '2025-11-20 17:10:18.483435', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 232, 19, 'Dùng lạnh với trái cây, xà lách.', 10);
INSERT INTO public.recipe_steps VALUES (1322, '2025-11-20 17:10:18.485556', '2025-11-20 17:10:18.485556', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 232, 10, 'Cách làm:Rửa gan vịt với nước muối, để ráo nước. Vắt hai quả chanh lấy nước cốt, 1 quả thái mỏng. Xay nhuyễn hành tây, vắt lấy nước.', 10);
INSERT INTO public.recipe_steps VALUES (1323, '2025-11-20 17:10:18.488434', '2025-11-20 17:10:18.488434', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 232, 16, 'Món này dùng với cơm trắng.', 10);
INSERT INTO public.recipe_steps VALUES (1324, '2025-11-20 17:10:18.491738', '2025-11-20 17:10:18.491738', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 232, 2, 'Cách làm:Nhặt bỏ cuống dâu tây, rửa sạch, để ráo, thái hạt lựu. Đun nóng dầu, cho hành tây vào xào vàng thơm, cho tiếp dâu tây xào trên lửa nhỏ, cho nước dùng gà vào.', 10);
INSERT INTO public.recipe_steps VALUES (1325, '2025-11-20 17:10:18.493858', '2025-11-20 17:10:18.493858', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 232, 7, 'Ướp gan với muối, tiêu, để 5 phút cho ngấm đều. Đun nóng phần dầu còn lại, cho gan vào rán trên lửa nhỏ, trở đều hai mặt.', 10);
INSERT INTO public.recipe_steps VALUES (1326, '2025-11-20 17:10:18.495426', '2025-11-20 17:10:18.495426', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 232, 15, 'Đun nóng dầu, nhúng gan vào trứng gà đã đánh tan lăn qua bột mì, cho vào chảo rán vàng, vớt ráo dầu. Đun nóng chảo, cho hành tây, tỏi, ớt gan hỗn hợp muối ớt vào đảo đều tay.', 10);
INSERT INTO public.recipe_steps VALUES (1327, '2025-11-20 17:10:18.497575', '2025-11-20 17:10:18.497575', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 232, 18, 'Cách làm:Rửa gan lợn, thái nhỏ, ngâm với sữa tươi, cho vào tủ lạnh giữ khoảng 4 giờ. Lấy gan ra xay nhuyễn với trứng gà. Trộn đều gan với bột nhục đậu khấu, bột hành tây, rượu thơm, muối tiêu. Thêm chút dầu vào khuôn tròn, cho hỗn hợp gan vào, xếp trong khay có chút nước, đặt vào lò nướng ở nhiệt độ 150 độ C khoảng 30 phút.', 10);
INSERT INTO public.recipe_steps VALUES (1328, '2025-11-20 17:10:18.499709', '2025-11-20 17:10:18.499709', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 232, 9, 'Gan vịt rán vàng xốt chanh
INSERT INTO public.recipe_steps VALUES (1329, '2025-11-20 17:10:18.501319', '2025-11-20 17:10:18.501319', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 232, 8, 'Xếp gan ra đĩa, rưới xốt giấm lên, dùng nóng với bánh mì nướng giòn.', 10);
INSERT INTO public.recipe_steps VALUES (1330, '2025-11-20 17:10:18.504093', '2025-11-20 17:10:18.504093', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 232, 17, 'Pa-tê gan lợn
INSERT INTO public.recipe_steps VALUES (1331, '2025-11-20 17:10:18.506804', '2025-11-20 17:10:18.506804', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 232, 13, 'Gan gà rán muối ớt
INSERT INTO public.recipe_steps VALUES (1332, '2025-11-20 17:10:18.509397', '2025-11-20 17:10:18.509397', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 232, 1, 'Gan ngỗng xốt dâu tây
INSERT INTO public.recipe_steps VALUES (1333, '2025-11-20 17:10:18.511582', '2025-11-20 17:10:18.511582', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 232, 3, 'Tiếp tục đun đến khi hỗn hợp dâu vừa mềm, nước sốt sánh đặc lại, nêm chút muối tiêu, cho nước cốt chanh vào. Ướp gan ngỗng với muối, tiêu vừa ăn. Đun nóng chút dầu khác, cho gan vào rán vàng trên lửa nhỏ, trở đều hai mặt.', 10);
INSERT INTO public.recipe_steps VALUES (1334, '2025-11-20 17:10:18.513991', '2025-11-20 17:10:18.513991', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 232, 14, 'Cách làm:Rửa gan gà với nước muối, thái mùi hành tây, thái khúc hành lá. Thái mỏng tỏi và một quả ớt. Giã nhuyễn muối hạt với quả ớt còn lại, tỏi, trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (1335, '2025-11-20 17:10:18.515605', '2025-11-20 17:10:18.515605', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 232, 4, 'Lấy gan ra đĩa, rưới xốt dâu lên, trang trí kem sữa tươi và rau mùi tây, dùng nóng với bánh mì.', 10);
INSERT INTO public.recipe_steps VALUES (1336, '2025-11-20 17:10:18.518433', '2025-11-20 17:10:18.518433', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 232, 5, 'Gan ngỗng xốt giấm đen
INSERT INTO public.recipe_steps VALUES (1337, '2025-11-20 17:10:18.520562', '2025-11-20 17:10:18.520562', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 232, 6, 'Cách làm:Tỏi lột vỏ, đập dập. Đun nóng nửa thìa cà phê dầu, cho tỏi vào xào vàng thơm. Cho tiếp giấm đen, đỏ, đường vào đun trên lửa nhỏ khoảng 15 phút, nêm muối.', 10);
INSERT INTO public.recipe_steps VALUES (1338, '2025-11-20 17:10:18.637944', '2025-11-20 17:10:18.637944', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 233, 3, 'Phi thơm hành, tỏi, sả còn lại và cho gà đã ướp vào xào săn. Thêm lượng nước xâm xấp mặt thịt (nếu có nước dừa tươi càng ngon). Kho gà trên lửa nhỏ vừa, nêm nếm lại gia vị cho phù hợp. Khi nồi gà kho gần cạn, nước sánh lại thì tắt bếp, múc ra thưởng thức cùng cơm nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1339, '2025-11-20 17:10:18.640802', '2025-11-20 17:10:18.640802', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 233, 1, 'Hành, sả băm nhuyễn, gừng thái sợi hoặc đập dập.', 10);
INSERT INTO public.recipe_steps VALUES (1340, '2025-11-20 17:10:18.642439', '2025-11-20 17:10:18.642439', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 233, 2, 'Gà làm sạch, chà xát muối hạt và chanh, rửa sạch, để ráo. Chặt gà từng miếng bao diêm vừa ăn. Ướp gà với 2 thìa cà phê bột nghệ, 1/2 lượng hành, sả, gừng băm, ớt cùng 2 thìa canh nước mắm, 1 thìa cà phê muối, 1 thìa cà phê hạt nêm, 1 thìa cà phê hạt tiêu, đảo đều, ướp tối thiểu trong 30 phút cho ngấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (1341, '2025-11-20 17:10:18.644539', '2025-11-20 17:10:18.644539', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 233, 4, 'Yêu cầu thành phẩm:Thịt gà mềm, vàng óng, đậm vị, dậy mùi thơm đặc trưng của sả, gừng, nước sốt sánh lại. Món này ăn cùng cơm nóng rất hợp với thời tiết mùa đông.', 10);
INSERT INTO public.recipe_steps VALUES (1342, '2025-11-20 17:10:18.695201', '2025-11-20 17:10:18.695201', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 234, 3, 'Bắc chảo lên bếp, phi thơm hành, cho thịt bò vào xào săn, cho nước lạnh vào đun sôi khoảng 15 phút. Tiếp đó cho măng, ngô, cà rốt, hạt nêm vừa ăn rồi đun sôi vặn lửa nhỏ, hầm chín mềm, gần chín cho thêm nấm hương. Trước khi tắt bếp, rắc hành, ăn nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1343, '2025-11-20 17:10:18.696798', '2025-11-20 17:10:18.696798', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 234, 6, 'Canh sôi, rắc hành tươi.', 10);
INSERT INTO public.recipe_steps VALUES (1344, '2025-11-20 17:10:18.698953', '2025-11-20 17:10:18.698953', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 234, 1, 'Canh bắp
INSERT INTO public.recipe_steps VALUES (1345, '2025-11-20 17:10:18.701265', '2025-11-20 17:10:18.701265', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 234, 2, 'Cách làm:Ngô để nguyên bắp chặt làm 5 - 6 miếng. Thịt bò diềm thăn xắt quân cờ to, ướp với một chút nước mắm, đường để khoảng 10 phút. Nấm hương ngâm nước nóng cho nở, cà rốt gọt vỏ xắt khoanh tròn, măng xắt miếng vừa phải.', 10);
INSERT INTO public.recipe_steps VALUES (1346, '2025-11-20 17:10:18.703008', '2025-11-20 17:10:18.703008', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 234, 4, 'Canh mướp trứng
INSERT INTO public.recipe_steps VALUES (1347, '2025-11-20 17:10:18.704625', '2025-11-20 17:10:18.704625', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 234, 5, 'Cách làm:Mướp gọt vỏ, bổ đôi, xắt vát. Đập trứng ra tô, đánh bông. Bắc nồi lên bếp, đun nóng dầu ăn, cho gừng, mướp vào xào, nêm hạt nêm, nước lạnh, đun sôi, từ từ cho trứng vào, vừa rót vừa quấy nhẹ tay cho trứng bông lên.', 10);
INSERT INTO public.recipe_steps VALUES (1348, '2025-11-20 17:10:18.891089', '2025-11-20 17:10:18.891089', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 235, 3, 'Xếp bắp cải, củ sen và thịt gà ra đĩa. Rưới nước sốt dầu giấm và rải ít rau mùi thái nhuyễn vào trước khi ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1349, '2025-11-20 17:10:18.894816', '2025-11-20 17:10:18.894816', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 235, 1, 'Luộc chín thịt gà, thái miếng vuông vừa ăn. Rửa bắp cải rồi thái sợi nhuyễn. Gọt vỏ củ sen, dùng dao bào bào thành lát tròn, mỏng. Chần củ sen trong nước sôi đến khi vừa chín tới, vớt ra, xả qua nước lạnh, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (1350, '2025-11-20 17:10:18.898313', '2025-11-20 17:10:18.898313', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 235, 2, 'Làm nước sốt: Hòa 4 thìa súp giấm gạo với 2 thìa súp đường và 1/4 thìa cà phê muối thành hỗn hợp chua ngọt vừa miệng. Trộn đều với tỏi xay và dầu ô-liu.', 10);
INSERT INTO public.recipe_steps VALUES (1351, '2025-11-20 17:10:18.900486', '2025-11-20 17:10:18.900486', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 235, 4, 'Bạn nên chọn loại giấm gạo nguyên chất để tạo nên hương vị đặc trưng cho món ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1352, '2025-11-20 17:10:19.026263', '2025-11-20 17:10:19.026263', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 236, 1, 'Gà nướng lá chanh
INSERT INTO public.recipe_steps VALUES (1353, '2025-11-20 17:10:19.028895', '2025-11-20 17:10:19.028895', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 236, 3, 'Vắt một miếng chanh vào, trải lá chanh ra, xếp một miếng mỡ, vài nhánh nấm kim châm, cuối cùng là một miếng gà. Gấp lá chanh lại xiên vào que. Xếp các cuốn gà vào vỉ nướng, thoa một lớp màu điều trên mặt thịt gà, nướng 10 phút với nhiệt độ 250 độ C.', 10);
INSERT INTO public.recipe_steps VALUES (1354, '2025-11-20 17:10:19.029964', '2025-11-20 17:10:19.029964', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 236, 4, 'Salad trứng cua
INSERT INTO public.recipe_steps VALUES (1355, '2025-11-20 17:10:19.031585', '2025-11-20 17:10:19.031585', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 236, 2, 'Cách làm:Mỡ lợn luộc chín xắt lát mỏng. Ướp mỡ lợn với đường và chút muối cho mỡ có độ trong. Thịt gà rửa sạch xắt miếng mỏng lớn, lá chanh xắt sợi thật nhuyễn. Nấm kim châm cắt khúc. Ướp thịt gà với tỏi băm, sả băm, hành phi, đường, nước tương, ngũ vị hương trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (1356, '2025-11-20 17:10:19.033212', '2025-11-20 17:10:19.033212', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 236, 5, 'Cách làm:Xà lách nhặt rửa sạch. Bún tàu, nấm mèo, ngâm nở xắt nhỏ. Hành lá xắt khúc ngắn. Thịt cua vắt cho ráo nước, xé nhỏ, trộn tiêu, hạt nêm, ớt băm nhỏ. Pha nước mắm với nước cốt chanh, đường và ớt băm cho sệt. Bắc bếp, phi thơm đầu hành trắng. Cho cua vào xào thơm, trộn bún tàu và nấm mèo sau đó cho trứng vào đánh đều, nêm thêm hạt nêm, tiêu. Đặt nồi hấp lên bếp, cho hỗn hợp trứng - cua vào, hấp chín, lấy ra, xắt miếng nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (1357, '2025-11-20 17:10:19.12268', '2025-11-20 17:10:19.12268', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 237, 1, 'Chè củ cải
INSERT INTO public.recipe_steps VALUES (1358, '2025-11-20 17:10:19.124304', '2025-11-20 17:10:19.124304', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 237, 2, 'Cách làm:Củ cải gọt vỏ, cắt miếng, gừng băm nhỏ. Dùng vải mỏng vắt lấy nước gừng, đun củ cải cùng với mật ong, nước sạch, nước gừng. Hầm nhỏ lửa đến khi củ cải nhừ là được.', 10);
INSERT INTO public.recipe_steps VALUES (1359, '2025-11-20 17:10:19.125908', '2025-11-20 17:10:19.125908', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 237, 3, 'Công dụng:Thích hợp với những người bị ho, thở khò khè.', 10);
INSERT INTO public.recipe_steps VALUES (1360, '2025-11-20 17:10:19.128114', '2025-11-20 17:10:19.128114', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 237, 4, 'Rau cải xào nấm
INSERT INTO public.recipe_steps VALUES (1361, '2025-11-20 17:10:19.129701', '2025-11-20 17:10:19.129701', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 237, 5, 'Cách làm:Nấm rửa sạch, thái lát mỏng, rau cải rửa sạch. Cho dầu vào chảo, xào tái rau cải, cho muối và một chút nước vào đun sôi. Cho nấm vào đảo đều, đun sôi lên là được.', 10);
INSERT INTO public.recipe_steps VALUES (1362, '2025-11-20 17:10:19.131844', '2025-11-20 17:10:19.131844', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 237, 6, 'Công dụng:Khai vị, tăng cảm giác ngon miệng.', 10);
INSERT INTO public.recipe_steps VALUES (1363, '2025-11-20 17:10:19.26975', '2025-11-20 17:10:19.26975', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 238, 8, 'Nhồi hỗn hợp óc lợn đã nêm nếm vừa ăn vào cà chua. Đem chiên trong chảo dầu ăn với lửa riu riu, thấy mặt óc lợn vàng rộm là vớt ra.', 10);
INSERT INTO public.recipe_steps VALUES (1364, '2025-11-20 17:10:19.271357', '2025-11-20 17:10:19.271357', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 238, 9, 'Món này dùng kèm tương ớt hoặc tương cà', 10);
INSERT INTO public.recipe_steps VALUES (1365, '2025-11-20 17:10:19.272977', '2025-11-20 17:10:19.272977', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 238, 7, 'Tán nhuyễn óc lợn rồi trộn chung với hỗn hợp bột mì và trứng. Nêm hạt nêm, tiêu, đường và tỏi băm, hành tím, hành lá xắt nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (1366, '2025-11-20 17:10:19.275131', '2025-11-20 17:10:19.275131', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 238, 1, 'Cà bi kho cá bống trứng
INSERT INTO public.recipe_steps VALUES (1367, '2025-11-20 17:10:19.277763', '2025-11-20 17:10:19.277763', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 238, 11, 'Muối, tiêu, hành trắng, hành lá, tỏi, dầu ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1368, '2025-11-20 17:10:19.279367', '2025-11-20 17:10:19.279367', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 238, 2, 'Cách làm:Cá bống trứng mua về lấy nước muối rửa sạch, để ra rổ cho ráo nước. Cà chua bi bỏ cuống rửa kỹ.', 10);
INSERT INTO public.recipe_steps VALUES (1369, '2025-11-20 17:10:19.281131', '2025-11-20 17:10:19.281131', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 238, 5, 'Cà chua nhồi óc lợn
INSERT INTO public.recipe_steps VALUES (1370, '2025-11-20 17:10:19.282718', '2025-11-20 17:10:19.282718', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 238, 12, 'Cách làm: Bắp hạt rửa sạch để ráo. Tán phô mai cho nhuyễn mịn, trộn chung với bột mì, trứng gà, bắp. Nêm hạt nêm và muối tiêu, hành lá, tỏi băm cho vừa miệng.', 10);
INSERT INTO public.recipe_steps VALUES (1371, '2025-11-20 17:10:19.285385', '2025-11-20 17:10:19.285385', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 238, 10, 'Bắp chiên phô mai xốt cà chua
INSERT INTO public.recipe_steps VALUES (1372, '2025-11-20 17:10:19.287628', '2025-11-20 17:10:19.287628', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 238, 3, 'Bắc nồi mỡ nóng, mỡ sôi tăm cho tỏi, hành tím, hành lá xắt nhuyễn vào. Hành tỏi vàng thơm cho nước mắm, đường. Nước mắm sôi trút cá vào. Cá cong cứng mình thì bỏ tiếp cà chua bi, nêm thêm tiêu, chừng 3 phút nhắc xuống.', 10);
INSERT INTO public.recipe_steps VALUES (1373, '2025-11-20 17:10:19.289252', '2025-11-20 17:10:19.289252', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 238, 6, 'Cách làm:Óc lợn mua về rửa sạch, để ráo. Cà chua cắt đôi, bỏ hết hạt và ruột bên trong. Trứng gà đánh nổi, cho bột mì vào khuấy đều.', 10);
INSERT INTO public.recipe_steps VALUES (1374, '2025-11-20 17:10:19.290867', '2025-11-20 17:10:19.290867', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 238, 14, 'Cà chua băm nhuyễn. Phi hành tỏi, hành trắng thơm vàng, cho cà chua vô lắc chảo, cà chua sền sệt lại là nhắc xuống rưới lên bắp, phô mai chiên. Dùng nóng giòn.', 10);
INSERT INTO public.recipe_steps VALUES (1375, '2025-11-20 17:10:19.293015', '2025-11-20 17:10:19.293015', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 238, 13, 'Bắc chảo dầu nóng, dùng thìa vê từng miếng bắp vừa ăn, cho vào chảo chiên lửa riu riu, bắp vàng đều vớt ra.', 10);
INSERT INTO public.recipe_steps VALUES (1376, '2025-11-20 17:10:19.29462', '2025-11-20 17:10:19.29462', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 238, 4, 'Dùng kèm cơm nóng và ớt hiểm.', 10);
INSERT INTO public.recipe_steps VALUES (1378, '2025-11-20 17:10:19.362908', '2025-11-20 17:10:19.362908', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 239, 1, 'Niễng bóc lớp vỏ nâu bên ngoài, rửa sạch, thái xéo vát khoảng 2 - 3 mm. Rau mùi, hành nhặt, rửa sạch, thái rối.', 10);
INSERT INTO public.recipe_steps VALUES (1379, '2025-11-20 17:10:19.365603', '2025-11-20 17:10:19.365603', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 239, 3, 'Phi thơm hành, cho niễng vào xào trên lửa vừa, thêm 1-2 thìa cà phê nước mắm, đảo đều.', 10);
INSERT INTO public.recipe_steps VALUES (1380, '2025-11-20 17:10:19.368111', '2025-11-20 17:10:19.368111', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 239, 6, 'Lưu ý:Món này cần ăn nóng mới ngon.', 10);
INSERT INTO public.recipe_steps VALUES (1381, '2025-11-20 17:10:19.371448', '2025-11-20 17:10:19.371448', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 239, 4, 'Sau 4-5 phút niễng chín tái thì cho trứng vào đảo đều cho trứng quyện cùng niễng. Nêm nếm lại gia vị phù hợp theo khẩu vị.', 10);
INSERT INTO public.recipe_steps VALUES (1382, '2025-11-20 17:10:19.374193', '2025-11-20 17:10:19.374193', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 239, 2, 'Trứng gà đánh tan cùng chút mắm, muối, hạt nêm.', 10);
INSERT INTO public.recipe_steps VALUES (1383, '2025-11-20 17:10:19.53168', '2025-11-20 17:10:19.53168', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 240, 3, 'Chuẩn bị các nguyên liệu khác: Nghệ tươi giã nhỏ lọc lấy nước cốt, mẻ thêm chút nước lọc qua rây cho mịn, cà chua thái múi cau, các loại rau gia vị rửa sạch, thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (1384, '2025-11-20 17:10:19.533849', '2025-11-20 17:10:19.533849', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 240, 7, 'Khi hoa chuối mềm thì thêm các rau gia vị (hành hoa, tía tô, lá lốt, mùi tàu) và ớt vào đảo đều, tắt bếp và múc ra thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1385, '2025-11-20 17:10:19.535972', '2025-11-20 17:10:19.535972', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 240, 1, 'Sơ chế chạch: đeo găng tay cho muối hạt vào bóp thật kỹ cho hết sạch nhớt, dùng kéo hoặc dao làm sạch (bỏ đầu, đuôi, ruột). Tiếp tục cho chanh vào bóp để khử tanh và sạch nhớt, rửa sạch, để ráo. Ướp cá chạch với 1 thìa cà phê muối, 1/2 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu, hành băm.', 10);
INSERT INTO public.recipe_steps VALUES (1386, '2025-11-20 17:10:19.538113', '2025-11-20 17:10:19.538113', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 240, 8, 'Yêu cầu thành phẩm:Cá chạch mềm ngọt tự nhiên quyện trong hoa chuối chát nhẹ, nước canh sánh vàng, chua thanh, dậy mùi thơm của các rau gia vị lá lốt, tía tô rất hấp dẫn. Món này ăn nóng cùng cơm trắng hay bún đều ngon, nhất là trong mùa đông.', 10);
INSERT INTO public.recipe_steps VALUES (1387, '2025-11-20 17:10:19.540432', '2025-11-20 17:10:19.540432', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 240, 5, 'Phi thơm hành khô, cho ba chỉ vào đảo hơi sém cạnh thì cho cà chua vào xào sơ. Cho nước cốt nghệ, nước mẻ và nước lọc vào đun sôi, nêm nếm lại gia vị cho phù hợp.', 10);
INSERT INTO public.recipe_steps VALUES (1388, '2025-11-20 17:10:19.542589', '2025-11-20 17:10:19.542589', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 240, 4, 'Cá chạch chiên sơ qua cho thơm và giúp chạch săn lại, để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (1389, '2025-11-20 17:10:19.544808', '2025-11-20 17:10:19.544808', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 240, 2, 'Hoa chuối bóc bỏ phần vỏ già, thái thật mỏng cho vào chậu nước vo gạo có pha giấm hoặc chanh ngâm cho trắng.', 10);
INSERT INTO public.recipe_steps VALUES (1390, '2025-11-20 17:10:19.546383', '2025-11-20 17:10:19.546383', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 240, 6, 'Khi nước sôi, cho cá chạch vào, đậy vung và đun nhỏ lửa cho cá chín khoảng 25 - 30 phút. Vớt hoa chuối cho vào nồi, om cùng cá chạch khoảng 10- 15 phút.', 10);
INSERT INTO public.recipe_steps VALUES (1391, '2025-11-20 17:10:19.656989', '2025-11-20 17:10:19.656989', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 241, 4, 'Dầu giấm: 1/3 chén giấm + 2 thìa cà phê đường + 1/2 thìa cà phê hạt nêm + 1/3 thìa cà phê tiêu + 1 thìa súp dầu ô-liu. Tất cả khuấy cho tan đều.', 10);
INSERT INTO public.recipe_steps VALUES (1392, '2025-11-20 17:10:19.658918', '2025-11-20 17:10:19.658918', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 241, 2, 'Cách làm:Tôm lột vỏ, chừa đuôi, ướp với tỏi băm, hạt nêm, tiêu và hai thìa súp coca cola. Bắc chảo nóng cho dầu ăn vào phi tỏi cho thơm, cho tôm vào xào. Tôm chín cho thêm hai thìa súp coca cola vào, nấu sôi lại, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (1393, '2025-11-20 17:10:19.661874', '2025-11-20 17:10:19.661874', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 241, 7, 'Cách làm:Măng chua rửa sạch vắt ráo nước, cà chua xắt múi. Rau om, ngò gai xắt nhuyễn, ớt xắt lát. Bắc nồi nóng, cho dầu vào phi tỏi cho thơm. Vớt tỏi ra, dùng lại nồi đó cho cà chua vào xào sơ. Cho 2 chén nước, thêm măng vào nấu sôi vài phút cho măng ra nước chua. Nêm hạt nêm và đường rồi cho tôm vào nấu sôi bùng, thêm nước mắm cho vừa ăn rồi tắt bếp. Bày ra tô. Cho ngò gai, ngò om, ớt và tỏi phi lên mặt.', 10);
INSERT INTO public.recipe_steps VALUES (1394, '2025-11-20 17:10:19.664876', '2025-11-20 17:10:19.664876', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 241, 6, 'Canh chua tôm nõn
INSERT INTO public.recipe_steps VALUES (1395, '2025-11-20 17:10:19.668174', '2025-11-20 17:10:19.668174', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 241, 1, 'Tôm xốt coca cola
INSERT INTO public.recipe_steps VALUES (1396, '2025-11-20 17:10:19.670306', '2025-11-20 17:10:19.670306', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 241, 3, 'Tôm trộn cải mầm dầu giấm
INSERT INTO public.recipe_steps VALUES (1397, '2025-11-20 17:10:19.672443', '2025-11-20 17:10:19.672443', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 241, 5, 'Cách làm:Tôm ướp với hạt nêm để khoảng 5 phút cho thấm. Bắc nước dừa lên, cho tôm vào luộc chín. Cải mầm rửa sạch, vẩy ráo, xếp ra đĩa, xếp tôm lên trên. Khi ăn rưới dầu giấm lên, trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (1398, '2025-11-20 17:10:19.820348', '2025-11-20 17:10:19.820348', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 242, 3, 'Cà chua chín, chọn trái còn cứng, cắt lát mỏng theo chiều ngang. Dưa leo cắt lát. Hành tây cắt lát mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (1399, '2025-11-20 17:10:19.823024', '2025-11-20 17:10:19.823024', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 242, 1, 'Trứng gà luộc chín, bóc vỏ, cắt lát.', 10);
INSERT INTO public.recipe_steps VALUES (1400, '2025-11-20 17:10:19.824637', '2025-11-20 17:10:19.824637', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 242, 4, 'Hòa hỗn hợp muối, đường, giấm, dầu ăn, tiêu. Trộn đậu, cà chua, dưa leo và một ít hành tây với hỗn hợp trên.', 10);
INSERT INTO public.recipe_steps VALUES (1401, '2025-11-20 17:10:19.827832', '2025-11-20 17:10:19.827832', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 242, 2, 'Đậu couvert chọn trái xanh đậm, thân đậu nhỏ, tước bỏ sơ hai bên thân đậu, cắt khúc vừa ăn, luộc chín (khi luộc cho một ít muối và đường vào nồi nước luộc để màu xanh). Đậu chín, vớt ra. Cho vào tô nước đá lạnh cho đậu được giòn.', 10);
INSERT INTO public.recipe_steps VALUES (1402, '2025-11-20 17:10:19.830089', '2025-11-20 17:10:19.830089', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 242, 5, 'Xúc ra đĩa, trên cùng xếp trứng và rắc hành tây lên, thêm vài lá ngò.', 10);
INSERT INTO public.recipe_steps VALUES (1403, '2025-11-20 17:10:19.98736', '2025-11-20 17:10:19.98736', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 243, 2, 'Nếp vo sạch, để ráo. Lá dứa giã nhuyễn, lọc lại để lấy nước màu xanh.', 10);
INSERT INTO public.recipe_steps VALUES (1406, '2025-11-20 17:10:19.991629', '2025-11-20 17:10:19.991629', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 243, 4, 'Viên cá thành hình tròn vừa ăn. Bọc xôi xung quanh viên cá thành một lớp dày. Cho cá vào xửng để hấp đến khi chín. Trong khi hấp, cần mở nắp xửng cho nước chảy ra ngoài.', 10);
INSERT INTO public.recipe_steps VALUES (1407, '2025-11-20 17:10:19.993287', '2025-11-20 17:10:19.993287', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 243, 5, 'Xếp cá ra đĩa, bày xà lách xung quanh.', 10);
INSERT INTO public.recipe_steps VALUES (1408, '2025-11-20 17:10:20.165371', '2025-11-20 17:10:20.165371', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 244, 1, 'Giò lợn hầm
INSERT INTO public.recipe_steps VALUES (1409, '2025-11-20 17:10:20.167523', '2025-11-20 17:10:20.167523', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 244, 2, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1410, '2025-11-20 17:10:20.169701', '2025-11-20 17:10:20.169701', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 244, 12, 'Mẹo nhỏ: Chè không được quá đặc cũng không nên quá loãng. Nêm đường vừa phải, không gắt để cảm nhận được vị thanh và ngọt nhẹ của cam thảo.', 10);
INSERT INTO public.recipe_steps VALUES (1411, '2025-11-20 17:10:20.171301', '2025-11-20 17:10:20.171301', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 244, 9, '- Rửa sạch các loại đậu. Nếu có thời gian, bạn nên ngâm qua đêm cho đậu nở mềm. Cam thảo rửa sạch, chặt thành khúc ngắn hay lát xéo. Đun sôi khoảng 1 lít nước, cho đậu vào nấu đến khi vừa chín, cho lửa liu riu, tránh sôi bùng.', 10);
INSERT INTO public.recipe_steps VALUES (1412, '2025-11-20 17:10:20.172903', '2025-11-20 17:10:20.172903', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 244, 10, '- Khi đậu vừa chín tới, cho cam thảo, đường, 1/2 thìa cà phê muối vào nấu đến khi đậu nở mềm, vừa ăn. Thêm nước nếu chè quá đặc.', 10);
INSERT INTO public.recipe_steps VALUES (1413, '2025-11-20 17:10:20.175034', '2025-11-20 17:10:20.175034', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 244, 6, 'Mẹo nhỏ: Chọn giò trước, ít mỡ để tránh gây ngán. Trong khi nấu, nên vớt lượng mỡ thừa tiết ra từ giò lợn để nước trong, thanh hơn.', 10);
INSERT INTO public.recipe_steps VALUES (1414, '2025-11-20 17:10:20.176638', '2025-11-20 17:10:20.176638', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 244, 7, 'Chè đậu cam thảo
INSERT INTO public.recipe_steps VALUES (1415, '2025-11-20 17:10:20.178236', '2025-11-20 17:10:20.178236', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 244, 11, 'Chè này có thể dùng nóng hoặc thêm đá, tùy thích. Đây là món có tác dụng giải nhiệt khi tiết trời nắng nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1416, '2025-11-20 17:10:20.179845', '2025-11-20 17:10:20.179845', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 244, 3, '- Rửa sạch các loại thảo mộc, cho vào nồi nấu với 3 tô nước, để lửa vừa, nấu còn khoảng 1/2 lượng nước. Giò lợn cạo hết lông, rửa sạch, rút xương, dùng chỉ bó tròn lại. Gừng thái sợi hay thái lát. Hành lá tước sợi, đầu hành đập giập.', 10);
INSERT INTO public.recipe_steps VALUES (1417, '2025-11-20 17:10:20.181513', '2025-11-20 17:10:20.181513', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 244, 4, '- Đun nóng khoảng 1/2 thìa súp dầu ăn, cho gừng, đầu hành vào xào thơm. Cho giò lợn vào đảo đều cho săn lại. Thêm nước hầm thảo dược vào. Nêm 1/2 thìa cà phê muối, 2 thìa cà phê đường sao cho vừa miệng rồi nấu đến khi giò lợn chín vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1418, '2025-11-20 17:10:20.183327', '2025-11-20 17:10:20.183327', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 244, 8, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1419, '2025-11-20 17:10:20.18495', '2025-11-20 17:10:20.18495', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 244, 5, '- Lấy giò lợn ra, rút bỏ chỉ, thái khoanh tròn, cho vào tô hoặc bát. Thêm nước hầm, hành lá, tiêu. Dùng nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1420, '2025-11-20 17:10:20.299738', '2025-11-20 17:10:20.299738', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 245, 8, 'Mực làm sạch, khía xéo, xắt miếng vừa ăn, ướp mực với hạt nêm, tiêu, đường. Sả băm, sả cây xắt khoanh. Bắc chảo dầu nóng, cho mực vào chiên vàng, vớt ra để ráo, tiếp tục cho sả xắt khoanh vào chảo dầu chiên vàng vớt ra.', 10);
INSERT INTO public.recipe_steps VALUES (1421, '2025-11-20 17:10:20.302914', '2025-11-20 17:10:20.302914', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 245, 10, 'Gắp mực ra đĩa, trên bày sả chiên.', 10);
INSERT INTO public.recipe_steps VALUES (1422, '2025-11-20 17:10:20.305532', '2025-11-20 17:10:20.305532', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 245, 2, 'Dọn ra ăn với cơm. Đây là món ăn chính có thể dọn trong bữa cơm thường ngày.', 10);
INSERT INTO public.recipe_steps VALUES (1423, '2025-11-20 17:10:20.307679', '2025-11-20 17:10:20.307679', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 245, 5, 'Làm nước trộn salad: Pha giấm với đường và 2 thìa nước đun sôi để nguội, hòa cho tan đường, cho ngò tây băm nhuyễn vào. Đặt chảo lên bếp, cho dầu vào, phi thơm hành, cho hỗn hợp nước trộn vào nấu sôi. Nhắc xuống để nguội. Xếp đậu cô ve ra đĩa, trên bày ớt chuông xắt khoanh, chế nước trộn vào. Khi ăn trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (1424, '2025-11-20 17:10:20.310194', '2025-11-20 17:10:20.310194', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 245, 6, 'Mực chiên sả
INSERT INTO public.recipe_steps VALUES (1425, '2025-11-20 17:10:20.312203', '2025-11-20 17:10:20.312203', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 245, 7, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1426, '2025-11-20 17:10:20.314363', '2025-11-20 17:10:20.314363', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 245, 3, 'Salad đậu cô ve
INSERT INTO public.recipe_steps VALUES (1427, '2025-11-20 17:10:20.317413', '2025-11-20 17:10:20.317413', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 245, 4, 'Cách làm:Đậu cô ve nhặt, tước bỏ phần xơ, rửa sạch. Luộc nhanh trong nước có pha chút muối cho đậu vừa chín và xanh. Hành lá xắt nhuyễn, ớt chuông bỏ hạt, xắt khoanh, ngò tây băm nhuyễn', 10);
INSERT INTO public.recipe_steps VALUES (1428, '2025-11-20 17:10:20.320623', '2025-11-20 17:10:20.320623', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 245, 1, 'Đặt khoảng 1/2 lít nước lên bếp, nấu sôi. Cho cá, cà chua, ớt và đầu hành trắng đập dập, củ hành tím xắt lát mỏng và nước mắm vào. Để lửa nhỏ khoảng 20 phút, không đậy nắp cho cá thấm gia vị và xương mềm nhừ. Nêm lại vừa ăn, cho hành lá xắt khúc vào, nấu sôi trở lại thì nhắc xuống.', 10);
INSERT INTO public.recipe_steps VALUES (1429, '2025-11-20 17:10:20.322226', '2025-11-20 17:10:20.322226', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 245, 9, 'Trút hết dầu trong chảo ra, cho sả băm vào xào cho thơm, thêm tương cà, tương ớt vào xào, trút mực vào chảo đảo đều. Tắt bếp, nhắc xuống.', 10);
INSERT INTO public.recipe_steps VALUES (1430, '2025-11-20 17:10:20.417815', '2025-11-20 17:10:20.417815', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 246, 2, 'Cách làm:Bí xanh chọn quả thẳng, còn non, hột ít. Gọt vỏ, dùng dao bào, bào bí thành từng lát mỏng. Tôm băm nhuyễn trộn chung với tỏi, giò sống, nêm muối, tiêu, đường. Trải miếng bí ra, trét nhân tôm lên rồi cuộn lại. Xếp vào đĩa rồi đem hấp chín, khoảng 5 phút. Dọn kèm nước mắm ớt. Ăn chung với cơm, vị nhẹ và thanh.', 10);
INSERT INTO public.recipe_steps VALUES (1702, '2025-11-20 17:10:24.839721', '2025-11-20 17:10:24.839721', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 274, 3, 'Rắc thêm hành lá, dùng ngay.', 10);
INSERT INTO public.recipe_steps VALUES (1431, '2025-11-20 17:10:20.419972', '2025-11-20 17:10:20.419972', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 246, 5, 'Cà chua băm nhỏ. Xào tỏi cho thơm, cho cà chua vào xào chín, nêm ước mắm, đường, muối, giấm, vừa ăn, cho thêm chút bột bắp pha loãng để sauce có độ sánh vừa phải. Chan sauce lên đĩa đậu dùng nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1432, '2025-11-20 17:10:20.422133', '2025-11-20 17:10:20.422133', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 246, 1, 'Bí cuốn tôm thịt
INSERT INTO public.recipe_steps VALUES (1433, '2025-11-20 17:10:20.42392', '2025-11-20 17:10:20.42392', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 246, 4, 'Cách làm:Đậu hũ cắt miếng chữ nhật 2x3cm, dùng dao khoét một lỗ ổ chính giữa miếng đậu. Tôm bóc vỏ dùng dao đập dập rồi mới băm nhỏ. Trộn tôm với tỏi, muối, tiêu, đường. Cho nhân vào chỗ khoét miếng đậu, lăn qua bột năng chiên chín vàng, xếp ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (1434, '2025-11-20 17:10:20.42552', '2025-11-20 17:10:20.42552', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 246, 3, 'Đậu hũ nhồi tôm sốt chua cay
INSERT INTO public.recipe_steps VALUES (1435, '2025-11-20 17:10:20.537165', '2025-11-20 17:10:20.537165', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 247, 3, 'Bì lợn cạo sạch, luộc khoảng 10 phút, rửa sạch, thái nhỏ. Bì giúp pate có độ kết dính.', 10);
INSERT INTO public.recipe_steps VALUES (1436, '2025-11-20 17:10:20.538744', '2025-11-20 17:10:20.538744', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 247, 7, 'Quết mỏng lớp dầu ăn hoặc bơ, lót vài lát mỡ phần thái mỏng dưới đáy hộp đựng, múc hỗn hợp gan vừa xay vào dàn đều, bọc giấy bạc để tránh hấp hơi nước và đem hấp cách thủy 4 - 6 tiếng là được. Để nguội, cho pate vào ngăn mát tủ lạnh dùng dần.', 10);
INSERT INTO public.recipe_steps VALUES (1437, '2025-11-20 17:10:20.540347', '2025-11-20 17:10:20.540347', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 247, 6, 'Cho hỗn hợp trên vào xay. Nếu thích ăn còn thịt rối thì xay 1 lần, còn thích mịn hơn thì xay nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (1438, '2025-11-20 17:10:20.542486', '2025-11-20 17:10:20.542486', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 247, 8, 'Thành phẩm:Pate mềm mịn, thơm ngon, không khô, không tanh mùi của gan heo. Món này ăn cùng xôi nóng, bánh mì đều ngon.', 10);
INSERT INTO public.recipe_steps VALUES (1439, '2025-11-20 17:10:20.544066', '2025-11-20 17:10:20.544066', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 247, 2, 'Bánh mì xé nhỏ, ngâm với 100 ml sữa tươi. Bánh mì giúp pate mềm mịn hơn.', 10);
INSERT INTO public.recipe_steps VALUES (1440, '2025-11-20 17:10:20.546255', '2025-11-20 17:10:20.546255', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 247, 1, 'Gan rửa sạch, nướng sơ, thái miếng, ngâm cùng 100 ml sữa tươi không đường trong 30 phút để khử tanh và độc, vớt ra, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (1441, '2025-11-20 17:10:20.548368', '2025-11-20 17:10:20.548368', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 247, 5, 'Phi thơm hành, tỏi, cho hành tây thái hạt lựu vào xào. Nếu muốn thơm hơn thì cho thêm bơ động vật. Cho gan, thịt vào xào sơ, nêm nếm mắm, muối, hạt nêm theo khẩu vị. Thêm bánh mì ngâm sữa, bì lợn, mỡ thái hạt lựu, hạt tiêu vào đảo đều để hỗn hợp quyện vào nhau, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (1442, '2025-11-20 17:10:20.549945', '2025-11-20 17:10:20.549945', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 247, 4, 'Mỡ phần luộc sơ, lấy 1/2 thái hạt lựu nhỏ, và 1/2 còn lại thái miếng mỏng dài để lót đế. Mỡ giúp pate không bị khô, mướt mềm hơn.', 10);
INSERT INTO public.recipe_steps VALUES (1443, '2025-11-20 17:10:20.672753', '2025-11-20 17:10:20.672753', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 248, 6, 'Mực nang làm sạch, lau khô, xay nhuyễn. Trộn mực nang đã xay với mỡ heo và đầu hành, ướp bột ngọt, đường, tiêu cho thấm gia vị. Trải bánh tráng ra, cho hỗn hợp trên vào, cuốn lại thành chả giò. Bắc chảo dầu nóng, cho chả giò vào chiên vàng đều 2 mặt, vớt ra để ráo. Dọn ăn với nước mắm me và xà lách, rau thơm.', 10);
INSERT INTO public.recipe_steps VALUES (1444, '2025-11-20 17:10:20.675685', '2025-11-20 17:10:20.675685', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 248, 2, 'Cách làm:Măng tây luộc chín vừa tới. Tôm càng luộc chín tới, lột vỏ, dùng hành lá cột chung với măng tây. Ngắt đầu tôm để trang trí, cá ngừ phi - lê ướp hạt nêm cho thấm. Trải rong biển ra rồi đặt cá ngừ lên, cuốn tròn, đem nướng vừa chín.', 10);
INSERT INTO public.recipe_steps VALUES (1445, '2025-11-20 17:10:20.677911', '2025-11-20 17:10:20.677911', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 248, 1, 'Tôm càng cá ngừ cuộn rong biển
INSERT INTO public.recipe_steps VALUES (1446, '2025-11-20 17:10:20.680068', '2025-11-20 17:10:20.680068', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 248, 3, 'Bắc chảo nóng, cho hành tây, tỏi và gừng bằm vào chảo cho vừa vàng không khét. Cho hỗn hợp vào xào nhanh tay, sau đó cho nước tương vào, nêm đường và tiêu cho vừa ăn. Chú ý, không nêm muối vì sốt đã mặn sẵn. Dùng chung với khoai tây hấp và rau xà lách.', 10);
INSERT INTO public.recipe_steps VALUES (1447, '2025-11-20 17:10:20.682421', '2025-11-20 17:10:20.682421', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 248, 4, 'Chả giò mực
INSERT INTO public.recipe_steps VALUES (1448, '2025-11-20 17:10:20.685701', '2025-11-20 17:10:20.685701', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 248, 5, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1449, '2025-11-20 17:10:20.818385', '2025-11-20 17:10:20.818385', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 249, 6, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1450, '2025-11-20 17:10:20.820635', '2025-11-20 17:10:20.820635', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 249, 7, 'Mực ống làm sạch khứa nhẹ mặt. Hành tây xắt múi nhỏ. Gừng đập dập. Cho gừng vào nước đun sôi, trụng mực khoảng 2 phút cho chín. Bắc chảo dầu, xào thơm hành tây rồi cho ra đĩa, xếp mực lên trên. Phi thơm tỏi băm, cho 1/2 chén nước vào nấu sôi. Cho ớt băm, tiêu, dầu hào, nước tương vào nêm vừa ăn. Cho nước bột bắp vào từ từ để tạo độ sánh, rưới xốt mực lên.', 10);
INSERT INTO public.recipe_steps VALUES (1451, '2025-11-20 17:10:20.823325', '2025-11-20 17:10:20.823325', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 249, 4, 'Xếp cải vào đĩa chế nước xốt lên.', 10);
INSERT INTO public.recipe_steps VALUES (1452, '2025-11-20 17:10:20.824917', '2025-11-20 17:10:20.824917', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 249, 8, 'Cải thảo xào khô
INSERT INTO public.recipe_steps VALUES (1453, '2025-11-20 17:10:20.827544', '2025-11-20 17:10:20.827544', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 249, 1, 'Cải thìa xốt bắp Mỹ
INSERT INTO public.recipe_steps VALUES (1454, '2025-11-20 17:10:20.829697', '2025-11-20 17:10:20.829697', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 249, 9, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1455, '2025-11-20 17:10:20.831284', '2025-11-20 17:10:20.831284', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 249, 10, 'Hành lá, ớt tỉa hoa, ngò trang trí. Tôm khô ngâm khoảng 10 phút, để ráo. Cải thảo nhặt rửa sạch, xắt sợi dài 10 cm. Cà rốt, ớt chuông xanh xắt sợi. Ớt sừng xắt sợi mỏng, bỏ hạt. Hành lá xắt nhuyễn. Phi thơm tỏi, hành, cho tôm khô vào xào cho thơm và săn tôm. Nêm gia vị cho thấm, tiếp tục cho cà rốt, cải thảo, ớt chuông vào xào chín. Cho hành lá vào, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (1456, '2025-11-20 17:10:20.833979', '2025-11-20 17:10:20.833979', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 249, 2, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1457, '2025-11-20 17:10:20.836594', '2025-11-20 17:10:20.836594', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 249, 3, 'Nấu sôi một ít nước, thêm 1 thìa cà phê hạt nêm và 1 thìa cà phê dầu ăn, cho cải thìa vào trụng chín, vớt để ráo. Phi thơm tỏi băm, cho cà rốt, nấm mèo, củ cải trắng, bắp và ớt chuông vào xào. Nêm 1/2 thìa cà phê hạt nêm, cho nước dùng vào nấu. Cho nước bột bắp vào từ từ cho có độ sánh là được', 10);
INSERT INTO public.recipe_steps VALUES (1458, '2025-11-20 17:10:20.838749', '2025-11-20 17:10:20.838749', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 249, 5, 'Mực hấp xốt cay
INSERT INTO public.recipe_steps VALUES (1459, '2025-11-20 17:10:21.067103', '2025-11-20 17:10:21.067103', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 250, 5, 'Cắt đôi trái thanh long, múc bỏ bớt ruột.', 10);
INSERT INTO public.recipe_steps VALUES (1460, '2025-11-20 17:10:21.070326', '2025-11-20 17:10:21.070326', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 250, 1, 'Bắp cải rửa sạch, bào sợi để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (1461, '2025-11-20 17:10:21.072487', '2025-11-20 17:10:21.072487', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 250, 2, 'Cà rốt, củ hành tây, ớt cắt sợi.', 10);
INSERT INTO public.recipe_steps VALUES (1462, '2025-11-20 17:10:21.074644', '2025-11-20 17:10:21.074644', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 250, 3, 'Pha hai muỗng xúp nước mắm, hai muỗng xúp đường và một muỗng xúp chanh thành nước mắm trộn gỏi.', 10);
INSERT INTO public.recipe_steps VALUES (1463, '2025-11-20 17:10:21.076747', '2025-11-20 17:10:21.076747', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 250, 7, 'Gỏi cua ăn với bánh phồng tôm.', 10);
INSERT INTO public.recipe_steps VALUES (1464, '2025-11-20 17:10:21.078919', '2025-11-20 17:10:21.078919', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 250, 6, 'Cho rau trộn vào, để thịt cua lên trên, rắc đậu phộng và trang trí thêm rau húng.', 10);
INSERT INTO public.recipe_steps VALUES (1465, '2025-11-20 17:10:21.081245', '2025-11-20 17:10:21.081245', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 250, 4, 'Trộn đều các loại rau củ rồi rưới nước mắm vào.', 10);
INSERT INTO public.recipe_steps VALUES (1466, '2025-11-20 17:10:21.218482', '2025-11-20 17:10:21.218482', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 251, 5, 'Tiếp tục cho phi thơm tỏi và mỡ lợn, cho rau cần vào xào trên lửa lớn, vừa nhanh tay nêm gia vị vừa đảo đều. Cần chỉ xào chín tái, cọng còn giữ màu xanh thì múc ra để riêng. Xào tái vừa đảm bảo giòn bên ngoài, mềm bên trong. Nếu xào lâu sẽ bị dai và mất hương vị.', 10);
INSERT INTO public.recipe_steps VALUES (1467, '2025-11-20 17:10:21.220806', '2025-11-20 17:10:21.220806', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 251, 3, 'Bún để vào rổ, xối qua nước lạnh thật nhanh cho tơi sợi, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (1468, '2025-11-20 17:10:21.222385', '2025-11-20 17:10:21.222385', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 251, 8, 'Thành phẩm: Bún mềm mà vẫn dai không bị nát, rau cần cọng xanh chín tới giòn thơm, vị thanh nhẹ.', 10);
INSERT INTO public.recipe_steps VALUES (1469, '2025-11-20 17:10:21.223993', '2025-11-20 17:10:21.223993', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 251, 4, 'Phi thơm tỏi băm với mỡ lợn cho thơm, cho thịt bò vào xào trên lửa lớn. Khi thịt chín tái thì múc ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (1470, '2025-11-20 17:10:21.226122', '2025-11-20 17:10:21.226122', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 251, 2, 'Thịt bò thăn cắt ngang thớ thành lát mỏng, ướp với chút tỏi băm, 1 thìa canh dầu hào, 1 thìa canh nước tương, 1 thìa cà phê hạt nêm, 1/2 thìa cà phê bột năng, 1/2 thìa canh dầu ăn, trộn đều ướp tối thiểu trong 15 - 20 phút.', 10);
INSERT INTO public.recipe_steps VALUES (1471, '2025-11-20 17:10:21.227699', '2025-11-20 17:10:21.227699', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 251, 1, 'Rau cần nhặt bỏ rễ, bỏ bớt lá, ngâm nước vo gạo hoặc nước muối loãng, rửa sạch rồi để ráo, bóp nhẹ cho ra tinh dầu (giúp rau mềm thơm hơn khi xào), vặn thành từng đoạn 4 - 5cm.', 10);
INSERT INTO public.recipe_steps VALUES (1472, '2025-11-20 17:10:21.229301', '2025-11-20 17:10:21.229301', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 251, 6, 'Tiếp tục cho bún vào chảo, nêm nước mắm ngon, nước tương, hạt nêm vừa miệng, đảo cho ngấm gia vị và xào bún trên lửa nhỏ vừa.', 10);
INSERT INTO public.recipe_steps VALUES (1473, '2025-11-20 17:10:21.230874', '2025-11-20 17:10:21.230874', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 251, 7, 'Khi thấy bún hơi có tiếng lách tách, săn sợi lại thì nhanh tay cho thịt bò, rau cần đã xào vào trộn đều, tắt bếp, múc ra thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1474, '2025-11-20 17:10:21.371451', '2025-11-20 17:10:21.371451', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 252, 2, 'Cách làm:
INSERT INTO public.recipe_steps VALUES (1475, '2025-11-20 17:10:21.374278', '2025-11-20 17:10:21.374278', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 252, 1, 'Cách làm:
INSERT INTO public.recipe_steps VALUES (1476, '2025-11-20 17:10:21.513419', '2025-11-20 17:10:21.513419', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 253, 1, 'Rau muống cắt khúc. Tôm luộc, bóc vỏ. Trứng gà đánh đều pha với bột chiên giòn và 1/2 chén nước. Xoài gọt vỏ, bào mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (1477, '2025-11-20 17:10:21.515565', '2025-11-20 17:10:21.515565', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 253, 2, 'Đun chảo dầu sôi, sau đó cho rau muống cùng hỗn hợp bột, trứng vào chiên vàng.', 10);
INSERT INTO public.recipe_steps VALUES (1478, '2025-11-20 17:10:21.517205', '2025-11-20 17:10:21.517205', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 253, 3, 'Pha nước gỏi gồm: Nước cốt chanh, nước mắm, đường có độ chua ngọt vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1479, '2025-11-20 17:10:21.519377', '2025-11-20 17:10:21.519377', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 253, 4, 'Khi dọn cho rau muống đã chiên vàng ra đĩa, cho tôm và xoài vào và rưới nước gỏi lên trên. Món này dùng kèm với bánh phồng tôm.', 10);
INSERT INTO public.recipe_steps VALUES (1480, '2025-11-20 17:10:21.64864', '2025-11-20 17:10:21.64864', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 254, 5, 'Thưởng thức: Xếp nguyên liệu xung quanh đĩa cơm. Trộn đều khi ăn, dùng với nước tương, tương ớt.', 10);
INSERT INTO public.recipe_steps VALUES (1481, '2025-11-20 17:10:21.650245', '2025-11-20 17:10:21.650245', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 254, 9, 'Thưởng thức: Dùng nóng với nước tương.', 10);
INSERT INTO public.recipe_steps VALUES (1482, '2025-11-20 17:10:21.651835', '2025-11-20 17:10:21.651835', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 254, 11, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1483, '2025-11-20 17:10:21.653449', '2025-11-20 17:10:21.653449', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 254, 16, 'Thưởng thức: Dùng với cá khô, xà lách và cà.', 10);
INSERT INTO public.recipe_steps VALUES (1484, '2025-11-20 17:10:21.655057', '2025-11-20 17:10:21.655057', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 254, 10, 'Cơm hấp
INSERT INTO public.recipe_steps VALUES (5110, '2025-11-20 17:12:42.434134', '2025-11-20 17:12:42.434134', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 784, 2, 'Hành khô băm nhỏ, hành lá rửa sạch thái nhỏ, ớt thái lát.', 10);
INSERT INTO public.recipe_steps VALUES (1485, '2025-11-20 17:10:21.657722', '2025-11-20 17:10:21.657722', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 254, 4, 'Ngâm sứa, xả hết chất mặn, thái sợi, trụng sơ. Ngâm mềm nấm đông cô, rửa sạch, luộc chín, thái sợi. Gọt vỏ cà rốt, thái sợi nhỏ, trụng chín. Tách lá bắp cải, thái sợi, trụng sơ. Luộc chín đậu cô ve, thái sợi dài. Đánh tan trứng, tráng mỏng với chút dầu, thái sợi nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (1486, '2025-11-20 17:10:21.659865', '2025-11-20 17:10:21.659865', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 254, 1, 'Cơm bát bửu
INSERT INTO public.recipe_steps VALUES (1487, '2025-11-20 17:10:21.661844', '2025-11-20 17:10:21.661844', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 254, 3, 'Đun nóng dầu, phi thơm tỏi, cho hai loại cơm vào rang, nêm hạt nêm. Cho cơm vào khuôn tròn, nén chặt rồi úp ra đĩa lớn. Xiên tôm vào que tre, hấp chín, bóc vỏ, thái sợi dày. Luộc chín mực, thái sợi lớn.', 10);
INSERT INTO public.recipe_steps VALUES (1488, '2025-11-20 17:10:21.663983', '2025-11-20 17:10:21.663983', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 254, 15, 'Đun nóng dầu, phi thơm 2 thìa súp tỏi, vớt ra để nguội. Trộn tỏi phi vào cơm, nêm hạt nêm, tán nhuyễn, vo viên, nướng vàng. Rửa sạch cá cơm, để ráo. Đun nóng dầu, cho cá vào rán vàng, vớt ra để ráo. Cho cá cơm, đường, nước mắm, ớt tỏi vào trộn đều trên bếp cho hỗn hợp sánh lại. Thái khoanh cà chua.', 10);
INSERT INTO public.recipe_steps VALUES (1489, '2025-11-20 17:10:21.66609', '2025-11-20 17:10:21.66609', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 254, 8, 'Ướp thịt với nước tương, hạt nêm, dầu ăn, đường, tiêu. Đun nóng dầu, cho thịt vào rán, để nguội, thái mỏng. Cà-rốt thái hạt lựu. Phi thơm tỏi, cho cơm vào xào, nêm hạt nêm, cho ngô, nấm, đậu, cà rốt vào, trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (1490, '2025-11-20 17:10:21.667657', '2025-11-20 17:10:21.667657', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 254, 12, 'Ngâm mềm táo đỏ, rửa sạch. Luộc chín hạt sen, bạch quả, đậu Hà Lan. Trộn cơm với thịt cua, gạch cua, táo đỏ, hạt sen, bạch quả, đậu Hà Lan, nêm hạt nêm vừa ăn. Tiếp tục cho nước cốt dừa vào cơm, trộn đều. Cho cơm vào xửng tre, hấp khoảng 10 phút', 10);
INSERT INTO public.recipe_steps VALUES (1491, '2025-11-20 17:10:21.669255', '2025-11-20 17:10:21.669255', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 254, 13, 'Thưởng thức: Dùng nóng, chấm kèm nước tương, giấm đỏ.', 10);
INSERT INTO public.recipe_steps VALUES (1492, '2025-11-20 17:10:21.670856', '2025-11-20 17:10:21.670856', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 254, 2, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1493, '2025-11-20 17:10:21.672972', '2025-11-20 17:10:21.672972', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 254, 7, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1494, '2025-11-20 17:10:21.675678', '2025-11-20 17:10:21.675678', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 254, 6, 'Cơm xá xíu
INSERT INTO public.recipe_steps VALUES (1495, '2025-11-20 17:10:21.677979', '2025-11-20 17:10:21.677979', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 254, 14, ':
INSERT INTO public.recipe_steps VALUES (1496, '2025-11-20 17:10:21.816797', '2025-11-20 17:10:21.816797', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 255, 3, 'Nồi nước sôi, cho cá và măng đã xào vào nồi. Nêm 3 thìa cà phê hạt nêm từ thịt, 1/2 thìa súp nước mắm ngon. Sau cùng, cho khế và cà chua vào, đợi cho nước canh sôi lại, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (1497, '2025-11-20 17:10:21.817861', '2025-11-20 17:10:21.817861', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 255, 2, 'Phi thơm củ hành tím với ớt màu, cho cá trê vào, xốc đều cho thịt cá săn lại. Sau đó, cho tiếp măng chua và chuối chát vào chảo trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (1498, '2025-11-20 17:10:21.819455', '2025-11-20 17:10:21.819455', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 255, 1, 'Ướp cá trê với nước mắm và một ít tiêu xay, để thấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (1499, '2025-11-20 17:10:21.821057', '2025-11-20 17:10:21.821057', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 255, 4, 'Dùng nóng. Dọn kèm với bát nước mắm chấm và ớt cắt khoanh.', 10);
INSERT INTO public.recipe_steps VALUES (1500, '2025-11-20 17:10:21.964573', '2025-11-20 17:10:21.964573', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 256, 1, 'Nghêu để nguyên con, ngâm trong nước gạo có pha chút ớt tươi giã nát cho sạch cát. Rửa sạch, luộc chín, tách thịt ra, để riêng. Cải mầm nhặt sạch, ngâm nước muối pha loãng, rồi rửa lại.', 10);
INSERT INTO public.recipe_steps VALUES (1501, '2025-11-20 17:10:21.9667', '2025-11-20 17:10:21.9667', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 256, 4, 'Thưởng thức: Dọn kèm nước mắm nguyên chất, dùng nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1502, '2025-11-20 17:10:21.96965', '2025-11-20 17:10:21.96965', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 256, 2, 'Đun sôi 800 ml nước, nêm gia vị gồm 1 thìa súp bột nêm, 1/2 thìa súp đường, 2 thìa cà phê nước mắm, và 1/2 thìa súp dầu ăn. Vặn lửa thật to, cho cải mầm vào. Khi cải chín, tắt bếp, cho nghêu vào.', 10);
INSERT INTO public.recipe_steps VALUES (1503, '2025-11-20 17:10:21.971823', '2025-11-20 17:10:21.971823', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 256, 3, 'Múc ra tô, rắc 1/2 thìa cà phê tiêu vào. Nếu không có thời gian , bạn có thể mua thịt nghêu sống tách sẵn (150 g). Cho nghêu vào trước cải mầm, sau khi nêm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (1504, '2025-11-20 17:10:22.095627', '2025-11-20 17:10:22.095627', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 257, 4, 'Khi ăn: Rưới sốt lên khoai, dùng nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1505, '2025-11-20 17:10:22.097232', '2025-11-20 17:10:22.097232', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 257, 9, 'Bò cuộn khoai môn bán xù
INSERT INTO public.recipe_steps VALUES (1506, '2025-11-20 17:10:22.098841', '2025-11-20 17:10:22.098841', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 257, 10, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1507, '2025-11-20 17:10:22.100685', '2025-11-20 17:10:22.100685', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 257, 2, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1508, '2025-11-20 17:10:22.102302', '2025-11-20 17:10:22.102302', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 257, 15, '- Gọt vỏ khoai mỳ, rửa sạch, hấp chín, tán nhuyễn. - Cho dừa nạo vào trộn, tiếp tục cho 2 thìa cà phê đường, trộn đều tay- Nén khoai vào khuôn, cho vào lò nướng khoảng 5 phút- Đun sôi nước cốt dừa, nước gião, cho 2 thìa súp đường, từ từ cho bột năng vào tạo độ sánh.', 10);
INSERT INTO public.recipe_steps VALUES (1509, '2025-11-20 17:10:22.103902', '2025-11-20 17:10:22.103902', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 257, 11, '- Khoai môn gọt vỏ, hấp chín, thái que lớn.- Rửa thịt bò, để ráo, đập dẹp.- Trộn đều giò sống, cá thác lác, gia vị- Trải thịt bò ra khay, quết hỗn hợp giò sống, đặt khoai môn lên trên, cuộn lại.- Đánh tan trứng gà- Lăn bò cuộn qua trứng gà, bột rán xù, rán vàng.', 10);
INSERT INTO public.recipe_steps VALUES (1538, '2025-11-20 17:10:22.352536', '2025-11-20 17:10:22.352536', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 259, 13, 'Nguyên liệu:500 g thịt gà già, 2 trái cà chua, 1 muỗng cà phê ớt bột, 1 muỗng canh nước mắm, hạt nêm, dầu ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1510, '2025-11-20 17:10:22.105488', '2025-11-20 17:10:22.105488', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 257, 5, 'Chả khoai
INSERT INTO public.recipe_steps VALUES (1511, '2025-11-20 17:10:22.107781', '2025-11-20 17:10:22.107781', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 257, 1, 'Khoai tây bi sốt cà
INSERT INTO public.recipe_steps VALUES (1512, '2025-11-20 17:10:22.109365', '2025-11-20 17:10:22.109365', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 257, 13, 'Bánh mì khoai nướng
INSERT INTO public.recipe_steps VALUES (1513, '2025-11-20 17:10:22.110948', '2025-11-20 17:10:22.110948', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 257, 3, '- Rửa khoai tây, gọt vỏ, ngâm nước để không bị đen.- Trụng sơ khoai, lấy ra khoét ruột, tỉa răng cưa phần miệng.- Trộn thịt xay, giò sống, mộc nhĩ thái nhuyễn, gia vị, nhồi vào khoai, hấp 15 phút.- Phi tỏi với chút dầu, cho cà chua thái nhuyễn vào, nêm gia vị. Cho bột năng pha loãng vào tạo độ sánh.', 10);
INSERT INTO public.recipe_steps VALUES (1514, '2025-11-20 17:10:22.112603', '2025-11-20 17:10:22.112603', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 257, 6, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1515, '2025-11-20 17:10:22.114189', '2025-11-20 17:10:22.114189', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 257, 7, '- Khoai hấp chín, gọt vỏ. Tán nhuyễn khoai tây, khoai sọ, khoai môn.- Thái hạt lựu khoai mỡ.- Hấp tôm, mực thái hạt lựu.- Trộn thịt, giò sống, cá, cho vào khoai đã tán.- Cho mực, tôm, khoai mỡ, gia vịt vào.- Quết dầu vào khuôn, cho hỗn hợp khoai vào, nướng vàng.- Sau 10 phút, quết trứng, nướng tiếp 5 phút.', 10);
INSERT INTO public.recipe_steps VALUES (1516, '2025-11-20 17:10:22.115923', '2025-11-20 17:10:22.115923', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 257, 12, 'Dùng nóng với tương ớt, cà chua, dưa chuột.', 10);
INSERT INTO public.recipe_steps VALUES (1517, '2025-11-20 17:10:22.117542', '2025-11-20 17:10:22.117542', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 257, 14, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1518, '2025-11-20 17:10:22.119161', '2025-11-20 17:10:22.119161', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 257, 16, 'Khi ăn, bày bánh ra đĩa, rưới nước cốt dừa lên, rắc vừng rang, dùng nóng hoặc lạnh đều ngon.', 10);
INSERT INTO public.recipe_steps VALUES (1519, '2025-11-20 17:10:22.120761', '2025-11-20 17:10:22.120761', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 257, 8, 'Dùng nóng với cơm.', 10);
INSERT INTO public.recipe_steps VALUES (1520, '2025-11-20 17:10:22.228804', '2025-11-20 17:10:22.228804', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 258, 3, 'Cách làm:Thịt gà chà muối, rửa sạch, để ráo, chặt miếng bản to 1 cm. Ướp với 1/2 thìa cà phê hạt nêm, 1 thìa cà phê đường, 1/2 thìa cà phê muối, hành tím băm.', 10);
INSERT INTO public.recipe_steps VALUES (1521, '2025-11-20 17:10:22.230922', '2025-11-20 17:10:22.230922', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 258, 4, 'Đun sôi 800 ml nước, cho thịt gà vào nấu sôi, hớt bọt. Nêm 1 thìa cà phê hạt nêm, 1 thìa cà phê muối, 3 thìa cà phê đường, 1/2 thìa súp nước mắm.', 10);
INSERT INTO public.recipe_steps VALUES (1522, '2025-11-20 17:10:22.232531', '2025-11-20 17:10:22.232531', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 258, 12, 'Gia vị: hạt nêm, đường, tiêu, nước mắm, dầu ăn', 10);
INSERT INTO public.recipe_steps VALUES (1523, '2025-11-20 17:10:22.234704', '2025-11-20 17:10:22.234704', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 258, 5, 'Khi gà chín mềm, cho lá giang vào nấu thêm khoảng 1 phút, tắt bếp. Múc canh ra tô, rắc tiêu.', 10);
INSERT INTO public.recipe_steps VALUES (1524, '2025-11-20 17:10:22.236824', '2025-11-20 17:10:22.236824', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 258, 10, 'Khuấy 2,5 thìa súp đường, 1,5 thìa súp nước mắm, 1,5 thìa súp nước cốt chanh, ớt băm. Cho dưa leo, cà rốt, hành tím, gừng, húng lủi, sò lông ra đĩa. Rưới nước mắm đã pha lên trên.', 10);
INSERT INTO public.recipe_steps VALUES (1525, '2025-11-20 17:10:22.238428', '2025-11-20 17:10:22.238428', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 258, 8, 'Cách làm:Sò lông luộc chín, gỡ thịt, ướp với 1 thìa cà phê, 1/2 thìa cà phê đường, 1/2 thìa cà phê tiêu. Dưa leo chẻ dọc, bỏ ruột, thái xéo dày 0,5 cm. Cà rốt thái sợi dài 4 cm. gừng thái sợi nhuyễn. Hành tím thái lát. Chanh vắt lấy nước. Ớt sừng băm nhuyễn. Húng lủi lấy lá.', 10);
INSERT INTO public.recipe_steps VALUES (1526, '2025-11-20 17:10:22.241128', '2025-11-20 17:10:22.241128', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 258, 15, 'Cho bò viên sốt ca chua ra đĩa, rắc 1/2 thìa cà phê tiêu lên mặt cho thơm.', 10);
INSERT INTO public.recipe_steps VALUES (1527, '2025-11-20 17:10:22.242152', '2025-11-20 17:10:22.242152', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 258, 9, 'Trộn dưa leo và cà rốt với 1/2 thìa súp muối, để 5 phút, rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (1528, '2025-11-20 17:10:22.245706', '2025-11-20 17:10:22.245706', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 258, 6, 'Mách bạn: Ngoài ức gà, bạn cũng có thể dùng cánh gà, đùi gà để nấu canh.', 10);
INSERT INTO public.recipe_steps VALUES (1529, '2025-11-20 17:10:22.247753', '2025-11-20 17:10:22.247753', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 258, 16, 'Mách bạn: Nên cho bò viên có mùi thơm, khô ráo, không bị nhớt.', 10);
INSERT INTO public.recipe_steps VALUES (1530, '2025-11-20 17:10:22.249839', '2025-11-20 17:10:22.249839', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 258, 14, 'Phi thơm hành, tỏi băm với 1,5 thìa súp dầu ăn, cho cà chua vào xào. Nêm 1 thìa súp nước mắm, 1 thìa cà phê hạt nêm, 1 thìa cà phê đường. Khi nước cà chua sôi, cho bào viên vào, vặn lửa nhỏ lại. Đun thêm 2 phút, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (1531, '2025-11-20 17:10:22.251276', '2025-11-20 17:10:22.251276', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 258, 1, 'Canh gà lá giang
INSERT INTO public.recipe_steps VALUES (1532, '2025-11-20 17:10:22.253278', '2025-11-20 17:10:22.253278', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 258, 7, 'Gia vị: hạt nêm, đường, tiêu, muối, nước mắm.', 10);
INSERT INTO public.recipe_steps VALUES (1533, '2025-11-20 17:10:22.255277', '2025-11-20 17:10:22.255277', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 258, 13, 'Cách làm:Bò viên trụng sơ với nước sôi cho sạch, để ráo. Cà chua: một quả bỏ cuống, bỏ hạt, băm nhuyễn, một quả thái hạt lựu. Hành củ, tỏi boc vỏ, băm nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (1534, '2025-11-20 17:10:22.256796', '2025-11-20 17:10:22.256796', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 258, 2, 'Gia vị: hạt nêm, muối, tiêu xay, đường, nước mắm.', 10);
INSERT INTO public.recipe_steps VALUES (1535, '2025-11-20 17:10:22.260212', '2025-11-20 17:10:22.260212', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 258, 11, 'Bò viên sốt cà chua
INSERT INTO public.recipe_steps VALUES (1536, '2025-11-20 17:10:22.348688', '2025-11-20 17:10:22.348688', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 259, 2, 'Nguyên liệu:200 g sò điệp, 50 g nấm thông (nấm hương), 200 g ngô hạt, 10 g ớt khô, 50 g đậu Hà Lan, 2 muỗng canh nước dùng, 1 muỗng cà phê tỏi bằm, 10 g bột chiên giòn, 1 muỗng canh bột năng, hạt nêm, dầu ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1537, '2025-11-20 17:10:22.350931', '2025-11-20 17:10:22.350931', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 259, 6, 'Bắc chảo lên bếp, đun nóng dầu ăn, phi thơm tỏi, cho ngô hạt vào xào sơ, cho tiếp đậu Hà Lan, ớt khô, nấm vào xào, nêm nước dùng xào chín, cho sò điệp chiên vào đảo đều tay, bày ra đĩa, ăn nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1539, '2025-11-20 17:10:22.354324', '2025-11-20 17:10:22.354324', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 259, 8, 'Nguyên liệu:1/2 củ cà rốt, 100 g cải bó xôi, 20 ml sữa tươi không đường, 15 ml kem, hạt nêm.', 10);
INSERT INTO public.recipe_steps VALUES (1540, '2025-11-20 17:10:22.356442', '2025-11-20 17:10:22.356442', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 259, 12, 'Gà già sốt cà chua
INSERT INTO public.recipe_steps VALUES (1541, '2025-11-20 17:10:22.35806', '2025-11-20 17:10:22.35806', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 259, 3, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1542, '2025-11-20 17:10:22.359676', '2025-11-20 17:10:22.359676', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 259, 11, 'Ăn kèm bánh mì sand-wich chiên sơ qua dầu, xắt hạt lựu.', 10);
INSERT INTO public.recipe_steps VALUES (1543, '2025-11-20 17:10:22.361266', '2025-11-20 17:10:22.361266', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 259, 7, 'Súp kem hai màu
INSERT INTO public.recipe_steps VALUES (1544, '2025-11-20 17:10:22.362871', '2025-11-20 17:10:22.362871', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 259, 5, 'Nấm thông, ớt ngâm nước nóng cho nở, bỏ chân, xắt miếng mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (1545, '2025-11-20 17:10:22.364469', '2025-11-20 17:10:22.364469', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 259, 10, 'Cà rốt gọt vỏ, xắt khúc nhỏ, luộc chín cho vào máy xay sinh tố xay nhuyễn. Cải bó xôi nhặt rửa sạch, luộc chín xay nhuyễn. Bắc nồi lên bếp, cho cà rốt và bó xôi xay vào, nêm hạt nêm vừa miệng, đun sôi, vặn nhỏ lửa đun thêm 5 phút rồi cho sữa tươi và kem vào, quấy đều tay bắc xuống.', 10);
INSERT INTO public.recipe_steps VALUES (1546, '2025-11-20 17:10:22.366758', '2025-11-20 17:10:22.366758', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 259, 1, 'Sò điệp xào ớt
INSERT INTO public.recipe_steps VALUES (1547, '2025-11-20 17:10:22.368882', '2025-11-20 17:10:22.368882', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 259, 4, 'Sò điệp làm sạch, để ráo lăn qua bột năng rồi thả vào chiên chín giòn, vớt ra, để ráo dầu ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1548, '2025-11-20 17:10:22.37104', '2025-11-20 17:10:22.37104', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 259, 14, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1549, '2025-11-20 17:10:22.372652', '2025-11-20 17:10:22.372652', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 259, 15, 'Thịt gà rửa sạch, chặt miếng vừa ăn, ướp với hạt nêm, ớt bột khoảng 15 phút. Cà chua ngâm rửa sạch xắt miếng. Bắc chảo lên bếp, đun nóng dầu ăn, cho cà chua vào xào, cho tiếp thịt gà vào, nêm nước mắm om khoảng 25 phút.', 10);
INSERT INTO public.recipe_steps VALUES (1550, '2025-11-20 17:10:22.374245', '2025-11-20 17:10:22.374245', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 259, 9, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1551, '2025-11-20 17:10:22.417861', '2025-11-20 17:10:22.417861', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 260, 3, 'Gừng cạo vỏ, băm nhuyễn lấy 1 thìa cà phê, phần còn lại đập dập, riềng làm tương tự. Nghêu hấp vừa há miệng, giữ lại 1/2 chén nước luộc. Phi thơm tỏi, sả, gừng, riềng, ớt băm với 1 thìa súp dầu ăn và một ít dầu màu điều. Cho nước dùng, nước nghêu, thơm, gừng, riềng, sả khúc, lá chanh nấu sôi 5 phút. Nêm 1 thìa súp giấm cùng hạt nêm, đường cho có vị chua ngọt.', 10);
INSERT INTO public.recipe_steps VALUES (1552, '2025-11-20 17:10:22.419478', '2025-11-20 17:10:22.419478', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 260, 1, 'Nghêu hấp thái
INSERT INTO public.recipe_steps VALUES (1553, '2025-11-20 17:10:22.421087', '2025-11-20 17:10:22.421087', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 260, 10, 'Đun nóng dầu màu điều, cho sa tế vào cùng lúc với nghêu và hành tây, đảo qua 1 phút, nêm hạt nêm và đường cho vừa ăn, bày ra đĩa trang trí với ngò, ớt, hành tỉa hoa.', 10);
INSERT INTO public.recipe_steps VALUES (1554, '2025-11-20 17:10:22.423648', '2025-11-20 17:10:22.423648', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 260, 5, 'Nghêu hấp sả
INSERT INTO public.recipe_steps VALUES (1555, '2025-11-20 17:10:22.424726', '2025-11-20 17:10:22.424726', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 260, 11, 'Có thể coi đây là một món mặn dùng với cơm hoặc thưởng thức với bánh tráng nướng.', 10);
INSERT INTO public.recipe_steps VALUES (1556, '2025-11-20 17:10:22.426754', '2025-11-20 17:10:22.426754', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 260, 6, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1557, '2025-11-20 17:10:22.428762', '2025-11-20 17:10:22.428762', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 260, 7, 'Rửa sạch nghêu, cho vào nồi đất cùng với nước dừa, 3 loại sả và hạt nêm. Nấu cho đến khi nghêu mở miệng. Dùng nóng kèm muối tiêu chanh.', 10);
INSERT INTO public.recipe_steps VALUES (1558, '2025-11-20 17:10:22.429761', '2025-11-20 17:10:22.429761', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 260, 9, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1559, '2025-11-20 17:10:22.430877', '2025-11-20 17:10:22.430877', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 260, 2, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1560, '2025-11-20 17:10:22.43347', '2025-11-20 17:10:22.43347', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 260, 4, 'Cho nước dùng đã nấu vào nồi đất, để sôi lại rồi cho nghêu vào, tắt bếp, dùng nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1561, '2025-11-20 17:10:22.435062', '2025-11-20 17:10:22.435062', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 260, 8, 'Nghêu xào sa tế
INSERT INTO public.recipe_steps VALUES (1562, '2025-11-20 17:10:22.561302', '2025-11-20 17:10:22.561302', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 261, 7, 'Canh măng chua cá lóc
INSERT INTO public.recipe_steps VALUES (1563, '2025-11-20 17:10:22.563402', '2025-11-20 17:10:22.563402', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 261, 5, 'Phi 1/2 thìa cà phê tỏi với 1/2 thìa súp dầu ăn, xào nhanh thịt bò. Phi phần tỏi còn lại với 1,5 thìa súp dầu ăn, cho bông cải vào. Thêm 1/2 bát nước, 2 thìa cà phê hạt nêm, 1/2 thìa cà phê đường. Đậy nắp, xào trên lửa vừa cho chín. Cho 1,5 thìa súp dầu hào, thịt bò vào, tắt bếp. Rắc 1/2 thìa cà phê tiêu lên.', 10);
INSERT INTO public.recipe_steps VALUES (1564, '2025-11-20 17:10:22.564998', '2025-11-20 17:10:22.564998', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 261, 13, 'Cá rô kho khế chua
INSERT INTO public.recipe_steps VALUES (1565, '2025-11-20 17:10:22.567726', '2025-11-20 17:10:22.567726', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 261, 4, 'Thịt bò thái miếng dày 0,2 cm, ướp 1/2 thìa cà phê hạt nêm, 1/2 thìa cà phê đường, 1/2 thìa súp nước tương, 1/2 thìa súp dầu ăn. Bông cải tách nhỏ, rửa sạch bằng nước muối loãng. Tỏi băm nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (1569, '2025-11-20 17:10:22.575675', '2025-11-20 17:10:22.575675', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 261, 16, 'Cá rô đánh vảy, rửa sạch, bỏ đầu, khứa xéo trên mình cá. Khế gọt phần rìa, thái lát dày 0,5 cm, ướp 1 thìa cà phê đường. Ớt tỏi băm nhuyễn. Đầu hành trắng giã nát.', 10);
INSERT INTO public.recipe_steps VALUES (1570, '2025-11-20 17:10:22.577794', '2025-11-20 17:10:22.577794', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 261, 17, 'Ướp cá với đầu hành, 1/2 thìa cà phê tỏi băm, ớt băm, 1/2 thìa cà phê hạt nêm, 1 thìa cà phê đường, 1,5 thìa súp nước mắm, 1/2 thìa cà phê muối.', 10);
INSERT INTO public.recipe_steps VALUES (1571, '2025-11-20 17:10:22.579941', '2025-11-20 17:10:22.579941', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 261, 14, 'Gia vị: hạt nêm, muối, tiêu, đường, nước mắm, dầu ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1572, '2025-11-20 17:10:22.582136', '2025-11-20 17:10:22.582136', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 261, 18, 'Thắng 1 thìa cà phê đường với 1 thìa súp dầu ăn cho nâu vàng. Cho tỏi băm vào phi, cho cá vào kho trên lửa nhỏ. Thêm 4 thìa súp nước sôi và khế vào kho đến lúc nước cá hơi sánh. Tắt bếp, cho 1/2 thìa cà phê tiêu vào.', 10);
INSERT INTO public.recipe_steps VALUES (1573, '2025-11-20 17:10:22.584258', '2025-11-20 17:10:22.584258', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 261, 10, 'Cá lóc chà muối, rửa sạch. Măng chua xả sạch với nước, vắt ráo. Cà chua thái hình múi cau. Ngò gai, rau om thái nhuyễn. Me dầm với nước sôi, bỏ xác, lấy nước cốt (3 thìa súp).', 10);
INSERT INTO public.recipe_steps VALUES (1574, '2025-11-20 17:10:22.586944', '2025-11-20 17:10:22.586944', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 261, 1, 'Bông cải xào thịt bò
INSERT INTO public.recipe_steps VALUES (1575, '2025-11-20 17:10:22.588512', '2025-11-20 17:10:22.588512', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 261, 6, 'Mách bạn: Nên trụng sơ bông cải trước khi xào để bông cải xào có màu tươi hơn.', 10);
INSERT INTO public.recipe_steps VALUES (1576, '2025-11-20 17:10:22.590632', '2025-11-20 17:10:22.590632', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 261, 8, 'Gia vị: hạt nêm, đường, muối, nước mắm.', 10);
INSERT INTO public.recipe_steps VALUES (1577, '2025-11-20 17:10:22.592773', '2025-11-20 17:10:22.592773', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 261, 12, 'Mách bạn: Để món canh thơm ngon hơn, bạn nên cho thêm tỏi băm phi vàng vào.', 10);
INSERT INTO public.recipe_steps VALUES (1578, '2025-11-20 17:10:22.594363', '2025-11-20 17:10:22.594363', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 261, 15, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1579, '2025-11-20 17:10:22.59658', '2025-11-20 17:10:22.59658', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 261, 19, 'Mách bạn: Cá rô loại nhỏ thịt sẽ ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (1580, '2025-11-20 17:10:22.598152', '2025-11-20 17:10:22.598152', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 261, 11, 'Đun sôi 800 ml nước, thả cá vào nấu sôi, hớt bọt. Cho tiếp măng chua và cà chua vào. Nêm 1 thìa cà phê hạt nêm, 1/2 thìa cà phê muối, nước cốt me, 1,5 thìa súp đường, 1 thìa súp nước mắm cho vừa miệng. Nấu sôi trở lại, tắt bếp. Múc canh ra tô, rắc ngò gai và rau om.', 10);
INSERT INTO public.recipe_steps VALUES (1581, '2025-11-20 17:10:22.705334', '2025-11-20 17:10:22.705334', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 262, 12, 'Mách nhỏ: Nên cho cá vào nồi khi nước đang sôi để canh không bị tanh.', 10);
INSERT INTO public.recipe_steps VALUES (1582, '2025-11-20 17:10:22.70696', '2025-11-20 17:10:22.70696', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 262, 18, 'Dọn kèm với nước mắm pha ớt thái khoanh.', 10);
INSERT INTO public.recipe_steps VALUES (1583, '2025-11-20 17:10:22.709166', '2025-11-20 17:10:22.709166', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 262, 4, 'Phi thơm tỏi băm với 2 thìa súp dầu ăn, cho cải vào xào nhanh tay trên lửa lớn. Nêm 2 thìa cà phê hạt nêm, 1/2 thìa cà phê đường. Tắt bếp, rắc thêm 1/2 thìa cà phê tiêu. Cho món ăn ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (1584, '2025-11-20 17:10:22.711849', '2025-11-20 17:10:22.711849', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 262, 9, 'Cá chép bỏ mang, cắt vây, đánh vảy. Sau đó, xát muối, rửa sạch, để ráo. Cà chua rửa sạch thái múi cau. Thì là và hành lá nhặt rửa sạch, thái khúc dài 3 cm. Me dầm nước sôi, lược bỏ xác, lấy nước.', 10);
INSERT INTO public.recipe_steps VALUES (1585, '2025-11-20 17:10:22.714024', '2025-11-20 17:10:22.714024', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 262, 23, 'Phi thơm hành tím băm với 1/2 thìa súp dầu ăn, cho chả vào. Nêm 1/2 thìa cà phê hạt nêm, 1/2 thìa súp nước mắm, 1/2 thìa cà phê đường, 1/2 thìa súp tương ớt, 1/3 bát nước sôi. Kho chả trên lửa nhỏ. Khi nước gần cạn, cho 1 thìa cà phê tiêu sọ vào, đảo đều, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (1586, '2025-11-20 17:10:22.715614', '2025-11-20 17:10:22.715614', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 262, 25, 'Mách nhỏ: Ngoài tiêu, bạn cũng có thể kho chả lụa với cà chua.', 10);
INSERT INTO public.recipe_steps VALUES (1587, '2025-11-20 17:10:22.718027', '2025-11-20 17:10:22.718027', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 262, 6, 'Mách nhỏ: Đối với những cây cải to,bạn nên chẻ ra để cải dễ thấm gia vị và không bị cứng.', 10);
INSERT INTO public.recipe_steps VALUES (1588, '2025-11-20 17:10:22.719038', '2025-11-20 17:10:22.719038', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 262, 7, ':
INSERT INTO public.recipe_steps VALUES (1589, '2025-11-20 17:10:22.721625', '2025-11-20 17:10:22.721625', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 262, 8, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1590, '2025-11-20 17:10:22.723634', '2025-11-20 17:10:22.723634', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 262, 14, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1591, '2025-11-20 17:10:22.725654', '2025-11-20 17:10:22.725654', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 262, 22, 'Chả lụa thái miếng hình bán nguyệt dày 0,5 cm. Hành lá bỏ rễ, rửa sạch, thái xéo dài 1 cm. Hành tím bóc vỏ, băm nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (1592, '2025-11-20 17:10:22.727737', '2025-11-20 17:10:22.727737', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 262, 20, 'Chả lụa kho tiêu
INSERT INTO public.recipe_steps VALUES (1593, '2025-11-20 17:10:22.729254', '2025-11-20 17:10:22.729254', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 262, 24, 'Xếp chả lụa kho ra đĩa, rắc 1/2 thìa cà phê tiêu xay và hành lá lên.', 10);
INSERT INTO public.recipe_steps VALUES (1594, '2025-11-20 17:10:22.731524', '2025-11-20 17:10:22.731524', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 262, 10, 'Đun sôi 800 ml nước, thả cá vào. Nước sôi lại, nêm 2 thìa cà phê hạt nêm, 1 thìa súp nước mắm', 10);
INSERT INTO public.recipe_steps VALUES (1595, '2025-11-20 17:10:22.733305', '2025-11-20 17:10:22.733305', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 262, 3, 'Đun sôi khoảng 1 lít nước, cho 1/2 thìa cà phê muối và 1 thìa súp dầu ăn vào. Thả cải vào trần sơ, vớt ra để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (1596, '2025-11-20 17:10:22.735431', '2025-11-20 17:10:22.735431', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 262, 19, 'Mách nhỏ: Khi mua hành lá, bạn nên chọn loại hành hương (cọng nhỏ) sẽ thơm ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (1597, '2025-11-20 17:10:22.73703', '2025-11-20 17:10:22.73703', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 262, 21, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1598, '2025-11-20 17:10:22.738627', '2025-11-20 17:10:22.738627', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 262, 2, 'Cách làm:Cải rửa sạch, để ráo, thái khúc dài 6 cm. Tỏi bóc sạch vỏ lụa, băm nhuyễn 2 tép, 3 lát còn lại thái lát dày 0,2 cm.', 10);
INSERT INTO public.recipe_steps VALUES (1599, '2025-11-20 17:10:22.740227', '2025-11-20 17:10:22.740227', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 262, 15, 'Đậu hũ rửa sạch, thái miếng theo chiều ngang, dày 0,5 cm. Hành lá bỏ rễ, rửa sạch, thái nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (2025, '2025-11-20 17:10:35.227006', '2025-11-20 17:10:35.227006', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 331, 3, 'Đặt cá vào đĩa rồi dội sốt đều lên trên 1/2 bề mặt của cá.', 10);
INSERT INTO public.recipe_steps VALUES (1600, '2025-11-20 17:10:22.741949', '2025-11-20 17:10:22.741949', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 262, 16, 'Đun nóng 3 thìa súp dầu ăn trong chảo không dính, cho đậu hũ vào rán vàng giòn. Sau đó vớt ra để ráo dầu.', 10);
INSERT INTO public.recipe_steps VALUES (1601, '2025-11-20 17:10:22.744077', '2025-11-20 17:10:22.744077', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 262, 1, ':
INSERT INTO public.recipe_steps VALUES (1602, '2025-11-20 17:10:22.74566', '2025-11-20 17:10:22.74566', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 262, 5, 'Phi vàng tỏi thái lát với 1/2 thìa súp dầu ăn rồi cho lên đĩa cải xào.', 10);
INSERT INTO public.recipe_steps VALUES (1603, '2025-11-20 17:10:22.747247', '2025-11-20 17:10:22.747247', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 262, 13, 'Đậu hũ rán tẩm hành
INSERT INTO public.recipe_steps VALUES (1604, '2025-11-20 17:10:22.749708', '2025-11-20 17:10:22.749708', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 262, 11, 'Xào sơ cà chua cùng 1/2 thìa súp dầu ăn, nêm 1/2 thìa cà phê hạt nêm. Cho cà chua vừa xào, hành lá và thì là vào nồi canh, tắt bếp. Chấm cá với nước mắm pha ớt thái khoanh.', 10);
INSERT INTO public.recipe_steps VALUES (1605, '2025-11-20 17:10:22.752354', '2025-11-20 17:10:22.752354', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 262, 17, 'Đun nóng 2 thìa súp dầu ăn, cho hành lá thái nhuyễn vào phi thơm, cho đậu hũ vào đảo đều. Nêm 1,5 thìa súp nước mắm, 1 thìa cà phê hạt nêm, 1/2 thìa cà phê đường. Để 5 phút cho đậu hũ thấm gia vị, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (1606, '2025-11-20 17:10:22.904942', '2025-11-20 17:10:22.904942', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 263, 7, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1607, '2025-11-20 17:10:22.907059', '2025-11-20 17:10:22.907059', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 263, 4, 'Làm xốt me: Phi thơm tỏi, cho nước me vào nồi nhỏ, đun sôi, nêm đường, tiêu, hạt nêm và nước mắm. Khuấy đều cho đến khi xốt sệt lại và có vị chua, mặn , ngọt vừa ăn là được.', 10);
INSERT INTO public.recipe_steps VALUES (1608, '2025-11-20 17:10:22.908988', '2025-11-20 17:10:22.908988', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 263, 6, 'Canh khoai sọ rau nhút
INSERT INTO public.recipe_steps VALUES (1609, '2025-11-20 17:10:22.910566', '2025-11-20 17:10:22.910566', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 263, 17, 'Đậu ngâm nở, nấu chín xay nhuyễn. Xào nhân đậu xanh cho ráo, nêm chút muối, chia nhân làm 25 viên nhỏ. Mè rang vàng, lá dừa rửa sạch, bó lại. Gừng cạo sạch, xắt lát mỏng. Bột nếp dã nhuyễn, nhồi mịn, chia làm 25 viên, ủ trong 20 phút. Nắn bột mỏng ra, cho nhân vào bao kín.', 10);
INSERT INTO public.recipe_steps VALUES (1610, '2025-11-20 17:10:22.912157', '2025-11-20 17:10:22.912157', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 263, 1, 'Cá trứng nướng xốt me
INSERT INTO public.recipe_steps VALUES (1611, '2025-11-20 17:10:22.913755', '2025-11-20 17:10:22.913755', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 263, 5, 'Đặt chảo không dính lên bếp, cho khoảng 1/2 thìa cà phê dầu ăn vào. Tẩm cá trứng với bột năng khô, lần lượt xếp cá vào chảo. Để lửa nhỏ, chiên vàng cả hai mặt. Xếp cá ra đĩa, rưới xốt me lên cá. Dùng nóng với cơm.', 10);
INSERT INTO public.recipe_steps VALUES (1612, '2025-11-20 17:10:22.915895', '2025-11-20 17:10:22.915895', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 263, 16, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1613, '2025-11-20 17:10:22.917492', '2025-11-20 17:10:22.917492', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 263, 18, 'Cho viên bột vào luộc, khi nổi lên thì vớt ra ngâm vào nước nguội. Cho đường thẻ, lá dứa vào nồi với 1 lít nước, nấu sôi đến khi hơi sánh lại. Cho các viên trôi nước vào nước đường', 10);
INSERT INTO public.recipe_steps VALUES (1614, '2025-11-20 17:10:22.91974', '2025-11-20 17:10:22.91974', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 263, 14, 'Khi thịt vừa chín, cho cải thảo, bắp cải vào xào, nêm lại gia vị vừa ăn. Cho rau cần vào trộn đều, tắt bếp. Gắp cải thảo xào ra đĩa, dùng với cơm, chấm nước tương pha ớt.', 10);
INSERT INTO public.recipe_steps VALUES (1615, '2025-11-20 17:10:22.92133', '2025-11-20 17:10:22.92133', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 263, 9, 'Bắc nồi nước sôi, nêm nước mắm rồi vo thịt nạc thành viên nhỏ thả vào nồi. Khi nước sôi trở lại, vớt bọt, cho khoai vào nấu chín mềm, nêm gia vị vừa ăn. Cho rau nhút vào nồi, đợi canh sôi trở lại nhắc xuống.', 10);
INSERT INTO public.recipe_steps VALUES (1616, '2025-11-20 17:10:22.923513', '2025-11-20 17:10:22.923513', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 263, 3, 'Cá trứng để nguyên con, rửa sạch, để ráo. Me vắt bóp nhuyễn với chút nước, bỏ hột.', 10);
INSERT INTO public.recipe_steps VALUES (1617, '2025-11-20 17:10:22.925119', '2025-11-20 17:10:22.925119', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 263, 2, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1618, '2025-11-20 17:10:22.926683', '2025-11-20 17:10:22.926683', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 263, 10, 'Múc canh khoai ra tô, rắc tiêu lên mặt. Món này dọn dùng với cơm.', 10);
INSERT INTO public.recipe_steps VALUES (1619, '2025-11-20 17:10:22.928283', '2025-11-20 17:10:22.928283', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 263, 12, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1620, '2025-11-20 17:10:22.93012', '2025-11-20 17:10:22.93012', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 263, 11, 'Cải thảo xào thịt nạc
INSERT INTO public.recipe_steps VALUES (1621, '2025-11-20 17:10:22.931721', '2025-11-20 17:10:22.931721', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 263, 8, 'Hành lá rửa sạch, lấy phần cọng trắng đập dập, phần lá xắt nhỏ để riêng. Thịt nạc xắt lát mỏng, băm nhỏ. Ướp thịt với đầu hành trắng, tiêu, hạt nêm. Khoai sọ gọt vỏ, rửa sạch, củ nhỏ để nguyên, củ lớn chẻ đôi. Rau nhút nhặt bỏ phần già, rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (1622, '2025-11-20 17:10:22.9328', '2025-11-20 17:10:22.9328', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 263, 19, 'Múc chè ra chén, chan nước dừa lên, rắc gừng và mè rang vào.', 10);
INSERT INTO public.recipe_steps VALUES (1623, '2025-11-20 17:10:22.934598', '2025-11-20 17:10:22.934598', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 263, 13, 'Thịt rửa sạch, xắt miếng mỏng, ướp hạt nêm, tiêu, đường, tỏi băm. Cải thảo tách từng lá, rửa sạch, để ráo, bắp cải tím xắt sợi. Cần tây rửa sạch, bỏ lá già, thái mỏng. Đặt chảo lên bếp, cho dầu vào, phi thơm tỏi,trút thịt vào đảo nhanh tay cho thịt chín kỹ.', 10);
INSERT INTO public.recipe_steps VALUES (1624, '2025-11-20 17:10:22.936181', '2025-11-20 17:10:22.936181', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 263, 15, 'Chè trôi nước
INSERT INTO public.recipe_steps VALUES (1625, '2025-11-20 17:10:23.029993', '2025-11-20 17:10:23.029993', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 264, 10, 'Làm sốt: đun nóng dầu hào, cho nước dùng pha loãng với bột năng vào, nêm 2 thìa cà phê đường và 2 thìa cà phê bột nêm. Rưới sốt lên cá, rải gừng, ớt, hành lá lên. Đem hấp thêm 1 phút là được.', 10);
INSERT INTO public.recipe_steps VALUES (1755, '2025-11-20 17:10:26.485502', '2025-11-20 17:10:26.485502', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 284, 1, 'Tôm tươi đập dập, ướp với một chút muối. Mướp gọt vỏ, cắt miếng. Miến ngâm mềm, cắt sợi.', 10);
INSERT INTO public.recipe_steps VALUES (1626, '2025-11-20 17:10:23.031581', '2025-11-20 17:10:23.031581', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 264, 14, 'Chim cút bỏ ruột, rửa sạch. Sau đó rửa lại với rượu trắng, để ráo. Ướp với nước mắm và 1/5 thìa súp dầu ăn. Rán sơ chim cút với nửa bát dầu ăn. Rửa sạch hạt sen, táo tàu đỏ. Củ năng, bạch quả bỏ vỏ. Táo đỏ và táo xanh bỏ hạt, thái hình mũi cam. Bỏ chim cút vào nồi, đổ ngập nước, cắt gói tiềm cho vào. Nước sôi, cho táo tàu đỏ, hạt sen, củ năng và bạch quả vào. Nêm đường, muối, bột nêm. Khi chim cút chín mềm, cho táo đỏ và táo xanh vào, nấu thêm 1 phút để nước dùng ngọt hơn.', 10);
INSERT INTO public.recipe_steps VALUES (1627, '2025-11-20 17:10:23.033684', '2025-11-20 17:10:23.033684', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 264, 13, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1628, '2025-11-20 17:10:23.036572', '2025-11-20 17:10:23.036572', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 264, 5, 'Làm sốt: Phi hành tây với 1 thìa súp dầu ăn. Cho nấm đông cô, cà rốt, đậu Hà Lan vào xào. Nêm hết tương cà, tương ớt, nước mắm, 2 thìa cà phê đường, 1/2 thìa cà phê bột nêm.', 10);
INSERT INTO public.recipe_steps VALUES (1629, '2025-11-20 17:10:23.038503', '2025-11-20 17:10:23.038503', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 264, 6, 'Dùng với bánh mì và nước sốt chua ngọt.', 10);
INSERT INTO public.recipe_steps VALUES (1630, '2025-11-20 17:10:23.041053', '2025-11-20 17:10:23.041053', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 264, 4, 'Trụng chín cà rốt và đậu Hà Lan. Đánh trứng gà với 1 thìa cà phê bột nêm. Nhúng từng lát lưỡi heo qua hỗn hợp trứng, lăn qua bột rán xù, rán trong chảo ngập dầu khoảng 5 phút, vớt ráo dầu.', 10);
INSERT INTO public.recipe_steps VALUES (1631, '2025-11-20 17:10:23.043187', '2025-11-20 17:10:23.043187', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 264, 3, 'Lưỡi heo trụng qua nước sôi, cạo lớp trắng, rửa sạch, thái lát ngang dày khoảng 0,5 cm. Hành tây bóc vỏ, thái hạt lựu. Nấm đông cô và cà rốt thái miếng vuông.', 10);
INSERT INTO public.recipe_steps VALUES (1632, '2025-11-20 17:10:23.045848', '2025-11-20 17:10:23.045848', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 264, 2, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1633, '2025-11-20 17:10:23.048527', '2025-11-20 17:10:23.048527', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 264, 12, 'Chim cút tiềm ngũ quả
INSERT INTO public.recipe_steps VALUES (1634, '2025-11-20 17:10:23.050675', '2025-11-20 17:10:23.050675', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 264, 9, 'Cá làm sạch, lọc phần phi lê thái miếng, ướp với 1 thìa cà phê tiêu, 1 thìa cà phê bột nêm, 1/3 thìa súp muối, 1 thìa súp dầu ăn. Thịt ba chỉ luộc, thái mỏng, cà rốt gọt vỏ, thái khúc, trụng sơ. Gừng gọt vỏ, thái sợi nhuyễn, ớt sừng thái sợi. Hành lá trụng sơ một nửa, phần còn lại cắt khúc dài 6-7cm. Dùng hành lá trụng buộc miếng cá, thịt ba chỉ và cà rốt, hấp 10 phút.', 10);
INSERT INTO public.recipe_steps VALUES (1635, '2025-11-20 17:10:23.052789', '2025-11-20 17:10:23.052789', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 264, 11, 'Ăn với bún, rau sống, nước mắm chua ngọt.', 10);
INSERT INTO public.recipe_steps VALUES (1636, '2025-11-20 17:10:23.054378', '2025-11-20 17:10:23.054378', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 264, 15, 'Dùng nóng với mì trứng.', 10);
INSERT INTO public.recipe_steps VALUES (1637, '2025-11-20 17:10:23.056669', '2025-11-20 17:10:23.056669', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 264, 7, 'Cá bống mú hấp hành lá
INSERT INTO public.recipe_steps VALUES (1638, '2025-11-20 17:10:23.058646', '2025-11-20 17:10:23.058646', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 264, 8, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1639, '2025-11-20 17:10:23.060217', '2025-11-20 17:10:23.060217', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 264, 1, 'Lưỡi heo sốt chua ngọt
INSERT INTO public.recipe_steps VALUES (1640, '2025-11-20 17:10:23.151126', '2025-11-20 17:10:23.151126', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 265, 2, 'Cho 2 muỗng dầu vào chảo, đun nóng già rồi cho cá vào rán chín vàng. Mặt da cá có thể rán hơi già một chút thì khi ăn sẽ rất ngon và dai thịt.', 10);
INSERT INTO public.recipe_steps VALUES (1641, '2025-11-20 17:10:23.152721', '2025-11-20 17:10:23.152721', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 265, 4, 'Cà chua rửa sạch rồi nghiền nát. Trút bớt dầu ở chảo ra chỉ để lại một ít, cho cà chua vào đun nhỏ lửa. Nêm nước mắm hoặc bột canh cho vừa rồi đậy vung lại. Để nước sốt sôi khoảng 10 phút thì nêm chút gia vị và dội đều lên đĩa cá.', 10);
INSERT INTO public.recipe_steps VALUES (1642, '2025-11-20 17:10:23.154219', '2025-11-20 17:10:23.154219', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 265, 3, 'Khi cá chín bày ra đĩa hình bầu dục, tỉa ớt trang trí cùng với vài cọng rau thì là.', 10);
INSERT INTO public.recipe_steps VALUES (1643, '2025-11-20 17:10:23.155871', '2025-11-20 17:10:23.155871', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 265, 1, 'Cá rô phi làm sạch lọc bỏ xương, khía hình mắt sàng lên các miếng thịt ở mặt trong con cá, tẩm ướp với chút gia vị, hạt tiêu khoảng 15 phút.', 10);
INSERT INTO public.recipe_steps VALUES (1644, '2025-11-20 17:10:23.158008', '2025-11-20 17:10:23.158008', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 265, 5, 'Có thể bày vài cọng rau mùi lên trên cho đẹp, món này ăn nóng sẽ ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (1645, '2025-11-20 17:10:23.366324', '2025-11-20 17:10:23.366324', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 266, 9, 'Trình bày: Cho ra đĩa, rắc ớt đã bằm nhỏ lên trên.', 10);
INSERT INTO public.recipe_steps VALUES (1646, '2025-11-20 17:10:23.36793', '2025-11-20 17:10:23.36793', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 266, 5, 'Cách làm:Hoa quả rửa sạch thái hạt lựu (thái vuông). Cho tất cả các hỗn hợp vào bát, đổ sữa chua, mật ong lên trên (vừa đủ tuỳ theo khẩu vị của bạn, thích nhiều ngọt hay chua).', 10);
INSERT INTO public.recipe_steps VALUES (1647, '2025-11-20 17:10:23.369536', '2025-11-20 17:10:23.369536', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 266, 8, 'Cách làm:Rau, cà chua, dưa chuột rửa sạch. Cà chua, dưa chuột thái mỏng, nêm muối cho vừa miệng. Trộn đều với nước sốt chua ngọt.', 10);
INSERT INTO public.recipe_steps VALUES (1648, '2025-11-20 17:10:23.370874', '2025-11-20 17:10:23.370874', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 266, 4, 'Salad hoa quả
INSERT INTO public.recipe_steps VALUES (1649, '2025-11-20 17:10:23.372451', '2025-11-20 17:10:23.372451', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 266, 3, 'Trình bày: Bày ra đĩa trắng. Cắt thêm cà chua trang trí cho đẹp.', 10);
INSERT INTO public.recipe_steps VALUES (1650, '2025-11-20 17:10:23.373527', '2025-11-20 17:10:23.373527', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 266, 6, 'Trình bày: Trộn đều các nguyên liệu trên rồi cho ra đĩa. Rắc lớp ngũ cốc lên trên cùng.', 10);
INSERT INTO public.recipe_steps VALUES (1651, '2025-11-20 17:10:23.37522', '2025-11-20 17:10:23.37522', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 266, 1, 'Salad rau
INSERT INTO public.recipe_steps VALUES (1652, '2025-11-20 17:10:23.377875', '2025-11-20 17:10:23.377875', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 266, 7, 'Salad cà chua, dưa chuột
INSERT INTO public.recipe_steps VALUES (1653, '2025-11-20 17:10:23.379487', '2025-11-20 17:10:23.379487', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 266, 2, 'Cách làm:Carrot, dưa chuột rửa sạch, thái chỉ. Rau xà lách thái rối. Cho tất cả vào bát trộn đều với 1 ít sốt mayonnaise, muối và dầu ăn. Để chừng 5 phút cho các gia vị ngấm.', 10);
INSERT INTO public.recipe_steps VALUES (1654, '2025-11-20 17:10:23.483015', '2025-11-20 17:10:23.483015', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 267, 6, 'Miến trộn dưa chuột
INSERT INTO public.recipe_steps VALUES (1655, '2025-11-20 17:10:23.484605', '2025-11-20 17:10:23.484605', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 267, 8, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1656, '2025-11-20 17:10:23.48619', '2025-11-20 17:10:23.48619', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 267, 5, 'Ớt quả khô xắt lát, bỏ hột, cho vào bát cùng với hạt tiêu. Đun nóng dầu ăn, đổ lên bát tiêu, ớt, sau đó đổ hỗn hợp này lên đĩa cà rốt, dưa chuột, măng tây, cần tây.', 10);
INSERT INTO public.recipe_steps VALUES (1657, '2025-11-20 17:10:23.487811', '2025-11-20 17:10:23.487811', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 267, 7, 'Gia vị: trộn đều các nguyên liệu sau: 4 muỗng cà phê nước ép chanh, 2 muỗng canh dầu ăn, hạt nêm, tiêu xay, rau thì là.', 10);
INSERT INTO public.recipe_steps VALUES (1658, '2025-11-20 17:10:23.4895', '2025-11-20 17:10:23.4895', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 267, 13, 'Đun nóng dầu ăn, cho trứng gà vào xóc nhẹ để trứng tơi vừa, xúc ra đĩa. Bắc chảo, đun nóng dầu ăn, cho thịt vào xào khoảng 2 phút, cho dưa chuột vào đảo đều, cho tiếp nấm mèo, trứng vào đảo đều, nêm hạt nêm vừa miệng, cho ớt vào đảo qua, xúc ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (1659, '2025-11-20 17:10:23.490578', '2025-11-20 17:10:23.490578', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 267, 10, 'Dưa chuột xào thịt
INSERT INTO public.recipe_steps VALUES (1660, '2025-11-20 17:10:23.492177', '2025-11-20 17:10:23.492177', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 267, 12, 'Thịt heo xắt miếng vừa ăn, ướp với bột năng, nước tương. Dưa chuột rửa sạch, bổ đôi, xắt lát khoảng 5 mm. Nấm mèo ngâm nước cho nở, rửa sạch, bỏ gốc, để nguyên tai nấm.', 10);
INSERT INTO public.recipe_steps VALUES (1661, '2025-11-20 17:10:23.493758', '2025-11-20 17:10:23.493758', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 267, 1, 'Dưa chuột dầm mật ong
INSERT INTO public.recipe_steps VALUES (1662, '2025-11-20 17:10:23.495322', '2025-11-20 17:10:23.495322', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 267, 4, 'Trộn đều cà rốt, măng, dưa chuột, cần tây với hạt nêm, mật ong, giấm trắng, cho vào hộp đậy kín và cho vào ngăn mát đến khi nước của các nguyên liệu trở nên sánh, bày ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (1663, '2025-11-20 17:10:23.497573', '2025-11-20 17:10:23.497573', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 267, 11, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1664, '2025-11-20 17:10:23.501971', '2025-11-20 17:10:23.501971', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 267, 3, 'Cà rốt, măng gọt bỏ vỏ, dưa chuột rửa sạch. Xắt cà rốt, măng, dưa chuột thành khúc 1 cm x 8 cm, trụng cà rốt qua nước sôi. Cần tây bỏ rễ, rửa sạch, xắt khúc tương tự.', 10);
INSERT INTO public.recipe_steps VALUES (1665, '2025-11-20 17:10:23.504159', '2025-11-20 17:10:23.504159', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 267, 9, 'Trộn miến và đậu Hà Lan với hỗn hợp gia vị đến 30 phút. Dưa chuột bổ ngang, bỏ ruột, xắt lát dày 3 mm. Cam lột vỏ, tách lấy ruột. Một nửa ớt xắt lát, một nửa xắt sợi. Đem các nguyên liệu này trộn với miến và đậu Hà Lan đã trộn gia vị. Tôm lột vỏ, bổ đôi, cho vào chiên vàng. Xúc miến trộn ra đĩa, xếp tôm lên, rưới đều nước gia vị lên trên và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (1666, '2025-11-20 17:10:23.506303', '2025-11-20 17:10:23.506303', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 267, 2, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1667, '2025-11-20 17:10:23.762124', '2025-11-20 17:10:23.762124', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 268, 3, 'Bày món ăn ra đĩa, xếp trứng gà lên trên.', 10);
INSERT INTO public.recipe_steps VALUES (1668, '2025-11-20 17:10:23.763729', '2025-11-20 17:10:23.763729', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 268, 1, 'Trứng gà luộc chín, bóc vỏ, bổ dọc làm 4. Cà chua bỏ núm, bổ múi. Đậu cô ve nhặt rồi chần qua nước sôi. Ớt chuông đỏ bỏ hạt, thái miếng, đậu phụ chần qua nước sôi.', 10);
INSERT INTO public.recipe_steps VALUES (1669, '2025-11-20 17:10:23.765336', '2025-11-20 17:10:23.765336', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 268, 2, 'Cho cà chua, đậu cô ve, ớt chuông, đậu phụ, mộc nhĩ, rau xà lách vào một cái âu to. Hòa muối với đường và nước cốt chanh, đổ vào các nguyên liệu trên, trộn đều và để một lúc cho ngấm.', 10);
INSERT INTO public.recipe_steps VALUES (1670, '2025-11-20 17:10:23.964149', '2025-11-20 17:10:23.964149', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 269, 2, 'Dùng phần nước dừa để nấu cơm. Đặt trái dừa đã cho gạo và nước vào một chiếc nồi to, chưng cách thủy 45 phút.', 10);
INSERT INTO public.recipe_steps VALUES (1671, '2025-11-20 17:10:23.965737', '2025-11-20 17:10:23.965737', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 269, 7, 'Món này dùng nóng hay nguội đều ngon, có thể ăn với cháo trắng hay với cơm.', 10);
INSERT INTO public.recipe_steps VALUES (1672, '2025-11-20 17:10:23.967338', '2025-11-20 17:10:23.967338', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 269, 1, 'Cắt phần đầu của quả dừa, đổ hết nước ra ngoài. Phần đầu vừa cắt đi thay thế cho phần nắp nồi. Gạo trắng lựa loại gạo ngon, vo sạch vài lần với nước, trút vào phần quả dừa.', 10);
INSERT INTO public.recipe_steps VALUES (1673, '2025-11-20 17:10:23.969464', '2025-11-20 17:10:23.969464', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 269, 3, 'Tômlàm sạch để khô nước, ướp hành, tiêu, bột ngọt, đường khoảng 30 phút.', 10);
INSERT INTO public.recipe_steps VALUES (1674, '2025-11-20 17:10:23.971105', '2025-11-20 17:10:23.971105', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 269, 5, 'Dừa khô sẽ tạo thành một lớp áo bên ngoài và thấm đượm vào từng con tôm.', 10);
INSERT INTO public.recipe_steps VALUES (1675, '2025-11-20 17:10:23.973374', '2025-11-20 17:10:23.973374', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 269, 4, 'Cho 1/2 chén nước ấm vào dừa nạo, rồi vắt lấy nước cốt. Phi hành khô vàng thơm, đổ tôm vào xào cho thấm gia vị, nước cạn chế nước cốt dừa vào rim cho đến khi sệt lại, nêm chút nước mắm, đường cho đậm đà .', 10);
INSERT INTO public.recipe_steps VALUES (1676, '2025-11-20 17:10:23.974447', '2025-11-20 17:10:23.974447', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 269, 6, 'Trang trí hoa, hành lá cho món ăn và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (1677, '2025-11-20 17:10:24.105225', '2025-11-20 17:10:24.105225', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 270, 3, 'Tiếp đến, luộc một ít hành lá để nguyên cọng dài để hành không bị gãy.', 10);
INSERT INTO public.recipe_steps VALUES (1678, '2025-11-20 17:10:24.106824', '2025-11-20 17:10:24.106824', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 270, 2, 'Sau đó, cuộn hỗn hợp tôm trong bánh tráng sống, chiên ở chảo dầu sôi đến khi bánh tráng vàng là chín.', 10);
INSERT INTO public.recipe_steps VALUES (1679, '2025-11-20 17:10:24.10899', '2025-11-20 17:10:24.10899', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 270, 1, 'Tôm thái nhỏ ướp với gia vị, xào qua với hỗn hợp tỏi, hành lá, nêm nước gừng, nước chanh, đường, nước tương đến khi tôm săn lại.', 10);
INSERT INTO public.recipe_steps VALUES (1680, '2025-11-20 17:10:24.362581', '2025-11-20 17:10:24.362581', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 271, 1, 'Đầu tiên, bạn phải làm sạch ếch, chặt làm bốn, rút bỏ xương lấy thịt ướp với bột nêm, tiêu bột, bột đao cho ngấm. Sau đó lấy ếch tẩm vào bột mỳ khô rán vàng.', 10);
INSERT INTO public.recipe_steps VALUES (1681, '2025-11-20 17:10:24.364502', '2025-11-20 17:10:24.364502', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 271, 2, 'Hành tỏi khô bóc vỏ, băm nhỏ, cà chua rửa sạch bỏ hạt, băm nhỏ. Dấm, đường hoà với nhau cho đủ độ chua ngọt, thêm một ít phẩm hoa hiên để màu đẹp.', 10);
INSERT INTO public.recipe_steps VALUES (1682, '2025-11-20 17:10:24.366084', '2025-11-20 17:10:24.366084', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 271, 3, 'Phi thơm hành tỏi, trút cà chua, cho thêm một ít bột nêm vào xào kỹ rồi cho nước đường dấm vào. Thêm một chút bột đao cho nước sốt được sánh, rồi thả ếch vào đảo đều, đun nhỏ lửa khoảng năm phút cho ngấm, rắc hành hoa thái nhỏ vào là được.', 10);
INSERT INTO public.recipe_steps VALUES (1683, '2025-11-20 17:10:24.485455', '2025-11-20 17:10:24.485455', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 272, 5, 'Trình bày và thưởng thức:Chần bún cho vào tô, thêm rau ngót (đã chần hoặc xào vào), cá chiên vàng giòn, rau thơm, múc nước dùng nóng chan vào và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (1684, '2025-11-20 17:10:24.487056', '2025-11-20 17:10:24.487056', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 272, 1, 'Sơ chế cá: Cá rô làm sạch, cạo sạch màng đen ở bụng, chà xát chanh và muối hạt, ngâm nước vo gạo rồi rửa sạch, để ráo. Dùng dao sắc lạng lấy phần thịt phi lê cá, thái miếng vừa ăn. Phần xương và đầu cá rửa sạch, để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (1685, '2025-11-20 17:10:24.488663', '2025-11-20 17:10:24.488663', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 272, 6, 'Yêu cầu thành phẩm: Cá chiên vàng giòn bên ngoài, mềm bên trong, rau ngót xanh mềm, nước dùng ngọt thanh nóng hổi, thơm ngon kích thích vị giác. Ăn kèm tỏi ớt ngâm giấm, măng chua ngâm, rau sống (tùy chọn).', 10);
INSERT INTO public.recipe_steps VALUES (1686, '2025-11-20 17:10:24.490252', '2025-11-20 17:10:24.490252', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 272, 2, 'Cách chiên phi lê cá:Đun nóng dầu trong chảo, thử đầu đũa sủi bọt tăm là đạt độ nóng, hạ lửa vừa và chia cá phi lê theo mẻ vào rán. Nên để nguyên (không lật trở) cho tới khi miếng vàng một mặt thì mới trở mặt còn lại. Khi cá vàng giòn thì tăng lửa, đảo nhanh để giúp miếng cá thoát dầu sẽ giòn hơn và không bị ngấy. Vớt ra để lên giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (1687, '2025-11-20 17:10:24.491846', '2025-11-20 17:10:24.491846', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 272, 3, 'Cách nấu nước dùng thơm ngon:Phần đầu và xương cá đem chiên vàng sơ, thêm nước sôi già, gừng và hành củ nướng vào ninh, thỉnh thoảng hớt bỏ bọt giúp nước dùng trong, không bị tanh, vị ngọt thanh. Nếu có thời gian thì ninh thêm xương bay (heo) để thêm vào nước dùng sẽ ngọt hơn. Ninh khoảng 60 phút thì lược bỏ xương và đầu cá, giữ lại nước, nêm nếm mắm, muối, hạt nêm theo khẩu vị gia đình.', 10);
INSERT INTO public.recipe_steps VALUES (1688, '2025-11-20 17:10:24.493417', '2025-11-20 17:10:24.493417', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 272, 4, 'Rau ngót:Nhặt và rửa sạch, vò nhẹ. Khi nào ăn thì có 2 cách: chần vào nồi nước dùng vớt ra luôn hoặc phi thơm hành, xào trên lửa lớn, thêm vào chút nước dùng cho mềm rau rồi mới cho vào tô để rau xanh ngon.', 10);
INSERT INTO public.recipe_steps VALUES (1689, '2025-11-20 17:10:24.578569', '2025-11-20 17:10:24.578569', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 273, 1, 'Sa lát gà - rau
INSERT INTO public.recipe_steps VALUES (1690, '2025-11-20 17:10:24.580173', '2025-11-20 17:10:24.580173', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 273, 5, 'Bột lê rau quả
INSERT INTO public.recipe_steps VALUES (1691, '2025-11-20 17:10:24.58179', '2025-11-20 17:10:24.58179', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 273, 7, 'Gọt vỏ và bỏ lõi lê rồi xay nhuyễn. Đổ vào bát các nguyên liệu gồm phó mát, nước cam và đường với hỗn hợp lê xay, có thể thêm một ít khoai tây nghiền. Trộn đều cho đến khi hỗn hợp nhuyễn, mượt. Cho bé ăn kèm món này với rau sạch tươi.', 10);
INSERT INTO public.recipe_steps VALUES (1692, '2025-11-20 17:10:24.583418', '2025-11-20 17:10:24.583418', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 273, 2, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1693, '2025-11-20 17:10:24.584487', '2025-11-20 17:10:24.584487', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 273, 8, 'Súp cà chua
INSERT INTO public.recipe_steps VALUES (1694, '2025-11-20 17:10:24.586557', '2025-11-20 17:10:24.586557', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 273, 11, '- Nghiền món súp bằng máy xay rồi đổ vào nồi và đun lại. Có thể cho bé ăn kèm món này với sữa chua nếu thích.', 10);
INSERT INTO public.recipe_steps VALUES (1695, '2025-11-20 17:10:24.588074', '2025-11-20 17:10:24.588074', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 273, 3, '- Trộn đều mayonnaise, mù tạc, đường, nước ép hành muối và hạt tiêu trong một bạt nhỏ. Lấy một chiếc bát khác, đổ thịt gà, cà rốt và cần tây vào và cũng trộn đều cùng mayonaise.', 10);
INSERT INTO public.recipe_steps VALUES (1696, '2025-11-20 17:10:24.59026', '2025-11-20 17:10:24.59026', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 273, 6, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1697, '2025-11-20 17:10:24.591769', '2025-11-20 17:10:24.591769', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 273, 9, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1698, '2025-11-20 17:10:24.593274', '2025-11-20 17:10:24.593274', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 273, 10, '- Bắc chảo lên bếp, đun nóng dầu ăn, cho hành vào phi rồi đổ tiếp cà rốt và tỏi vào nấu thêm một phút. Khuấy cà chua đã nghiền với nước luộc gà, muối, rau thơm và hạt tiêu, đun đến khi sôi rồi vặn nhỏ lửa để sôi từ từ 15 phút. Bắc ra, để nguội 10 phút, cho giấm vào khuấy đều.', 10);
INSERT INTO public.recipe_steps VALUES (1699, '2025-11-20 17:10:24.595787', '2025-11-20 17:10:24.595787', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 273, 4, '- Cắt phần đầu của các quả cà chua (bạn chớ bỏ đi mà hãy giữ lại để làm những chiếc nắp xinh xắn). Xúc thịt và các loại rau vào, đậy nắp lại. Có thể cho bé ăn món này kèm bánh quy giòn.', 10);
INSERT INTO public.recipe_steps VALUES (1700, '2025-11-20 17:10:24.835956', '2025-11-20 17:10:24.835956', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 274, 1, 'Gọt vỏ bí đỏ, củ dền, su su, dùng thìa tròn múc từng viên, cho vào nước sôi chần sơ, vớt ra để ráo nước. Làm sạch mực, lột bỏ lớp da ngoài, cắt khoanh vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1701, '2025-11-20 17:10:24.837562', '2025-11-20 17:10:24.837562', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 274, 2, 'Đun nóng dầu, phi thơm tỏi, hành, cho mực vào xào, nêm bột nêm, dầu hào, tương ớt sa tế, đường. Tiếp tục cho rau củ vào trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (1703, '2025-11-20 17:10:24.991322', '2025-11-20 17:10:24.991322', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 275, 1, 'Ếch lọc da, thịt chặt miếng, để riêng, ướp với hạt nêm khoảng 10 phút. Da ếch bóp muối, rửa sạch, xắt miếng vừa ăn, trụng qua nước sôi. Măng tước nhỏ, luộc qua, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (1704, '2025-11-20 17:10:24.992792', '2025-11-20 17:10:24.992792', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 275, 2, 'Bắc chảo lên bếp, phi thơm hành, cho thịt ếch vào xào lăn, cho ra tô.', 10);
INSERT INTO public.recipe_steps VALUES (1705, '2025-11-20 17:10:24.994926', '2025-11-20 17:10:24.994926', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 275, 3, 'Nêm thêm ít dầu ăn vào chảo, cho măng vào xào, nêm gia vị vừa miệng, gần chín cho thịt ếch, da ếch vào xào. Trước khi tắt bếp, rắc hành tươi, ăn nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1706, '2025-11-20 17:10:25.167417', '2025-11-20 17:10:25.167417', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 276, 3, 'Cho thịt băm nhỏ vào giữa lá lốt, gói kín lại từng miếng rồi xếp vào vỉ sắt, đặt lên bếp than hoa nướng chín vàng đều, xếp ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (1707, '2025-11-20 17:10:25.170069', '2025-11-20 17:10:25.170069', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 276, 4, 'Phi hành mỡ, rưới đều lên đĩa thịt nướng. Khi ăn dùng với nước chấm dấm đường, nước mắm, tỏi.', 10);
INSERT INTO public.recipe_steps VALUES (1708, '2025-11-20 17:10:25.173504', '2025-11-20 17:10:25.173504', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 276, 1, 'Thịt bò, thịt lợn, gan lọc hết gân, xơ, thái nhỏ, băm lẫn với hành, tỏi khô sau đó ướp cùng hạt tiêu, mỡ nước, nước mắm, đường, mì chính, dấm, trộn đều rồi để cho ngấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (1709, '2025-11-20 17:10:25.175725', '2025-11-20 17:10:25.175725', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 276, 2, 'Lá lốt cắt bỏ cuống rửa sạch rồi để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (1710, '2025-11-20 17:10:25.297454', '2025-11-20 17:10:25.297454', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 277, 1, 'Gan xắt miếng mỏng vừa ăn, ướp với ít hạt nêm khoảng 5 phút.', 10);
INSERT INTO public.recipe_steps VALUES (1711, '2025-11-20 17:10:25.300163', '2025-11-20 17:10:25.300163', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 277, 4, 'Bắc chảo lên bếp, phi thơm tỏi, cho gan vào xào tái, cho ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (1712, '2025-11-20 17:10:25.30231', '2025-11-20 17:10:25.30231', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 277, 2, 'Nấm mèo ngâm nước nóng cho nở, rửa sạch, xắt nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (1713, '2025-11-20 17:10:25.305019', '2025-11-20 17:10:25.305019', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 277, 3, 'Dưa leo rửa sạch, bổ đôi, xắt lát mỏng, rắc ít hạt nêm, xóc đều lên.', 10);
INSERT INTO public.recipe_steps VALUES (1714, '2025-11-20 17:10:25.307156', '2025-11-20 17:10:25.307156', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 277, 5, 'Cho tiếp dưa leo vào xào gần chín, cho gan vào xào trở lại, trước khi tắt bếp, rắc hành tươi.', 10);
INSERT INTO public.recipe_steps VALUES (1715, '2025-11-20 17:10:25.491959', '2025-11-20 17:10:25.491959', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 278, 4, 'Khi ăn xếp lại cải xoong cà chua bi và hành tây quanh đĩa thịt.', 10);
INSERT INTO public.recipe_steps VALUES (1716, '2025-11-20 17:10:25.493573', '2025-11-20 17:10:25.493573', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 278, 1, 'Hành tây bóc vỏ thái mỏng ngâm với giấm đường. Cải xoong nhặt rửa sạch, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (1717, '2025-11-20 17:10:25.495175', '2025-11-20 17:10:25.495175', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 278, 3, 'Thịt bò thái mỏng ướp với nước tương (hoặc gia vị nước tỏi), rồi xào tái chín, cho nước cốt chanh vào, trộn đều xếp thịt bò lên đĩa salad.', 10);
INSERT INTO public.recipe_steps VALUES (1718, '2025-11-20 17:10:25.496238', '2025-11-20 17:10:25.496238', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 278, 2, 'Cà chua bi chẻ đôi. Xếp cải xoong và cà chua ra đĩa, rưới giấm ngâm hành lên trên.', 10);
INSERT INTO public.recipe_steps VALUES (1719, '2025-11-20 17:10:25.685861', '2025-11-20 17:10:25.685861', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 279, 2, 'Thịt gà lọc lấy nạc, thái miếng hơi dày. Nấm ngâm nở, cắt bỏ chân. Tôm nõn khô ngâm nước nóng cho mềm.', 10);
INSERT INTO public.recipe_steps VALUES (1720, '2025-11-20 17:10:25.688551', '2025-11-20 17:10:25.688551', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 279, 4, 'Múc vào bát to, rắc thêm hạt tiêu, rau mùi. Ăn nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1721, '2025-11-20 17:10:25.690451', '2025-11-20 17:10:25.690451', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 279, 3, 'Đun sôi nước dùng, nêm gia vị vừa đủ ngọt, bỏ thịt gà và nấm vào nấu chín mới cho cà rốt, xúp-lơ. Cuối cùng, trút hải sâm, tôm khô, đậu Hà Lan vào để sôi lại là được.', 10);
INSERT INTO public.recipe_steps VALUES (1722, '2025-11-20 17:10:25.692096', '2025-11-20 17:10:25.692096', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 279, 1, 'Chọn loại hải sâm khô, đều con và dày mình, ngâm nước lã qua đêm, hôm sau rửa sạch bằng nhiều nước rồi đem luộc chín, thái miếng quả trám. Sau đó xào thơm với gừng, hành và rượu trắng, nêm đủ gia vị cho ngấm, để sẵn.', 10);
INSERT INTO public.recipe_steps VALUES (1723, '2025-11-20 17:10:25.775797', '2025-11-20 17:10:25.775797', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 280, 3, 'Cá trê om hoa chuối
INSERT INTO public.recipe_steps VALUES (1724, '2025-11-20 17:10:25.77796', '2025-11-20 17:10:25.77796', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 280, 4, 'Cách làm:Chuối chát xắt khoanh dài. Hoa chuối rửa sạch, để ráo. Rau om, mùi tàu (ngò gai) rửa sạch, xắt nhuyễn. Cá trê làm sạch ướp với bột nghệ, sả, tỏi, gừng, giềng, mẻ, hạt nêm cho thấm gia vị khoảng 20 phút.', 10);
INSERT INTO public.recipe_steps VALUES (1725, '2025-11-20 17:10:25.780122', '2025-11-20 17:10:25.780122', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 280, 10, 'Cách làm:Hành khô bóc vỏ để nguyên củ. Lạc trụng sơ qua nước sôi, để ráo. Nấm mèo ngâm nước ấm cho nở, bỏ chân, xắt làm bốn miếng. Giò làm sạch, chặt miếng cỡ bao diêm, ướp với sả, giềng, bột nghệ, hành, tỏi, hạt nêm, nước mắm, đường trong vòng 30 phút.', 10);
INSERT INTO public.recipe_steps VALUES (1726, '2025-11-20 17:10:25.781875', '2025-11-20 17:10:25.781875', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 280, 1, 'Cà tím om thịt lợn
INSERT INTO public.recipe_steps VALUES (1727, '2025-11-20 17:10:25.784242', '2025-11-20 17:10:25.784242', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 280, 6, 'Sườn non om dưa (cải) chua
INSERT INTO public.recipe_steps VALUES (1728, '2025-11-20 17:10:25.786395', '2025-11-20 17:10:25.786395', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 280, 8, 'Cho dầu ăn vào nồi, phi thơm tỏi cho sườn non vào xào sơ, tiếp tục cho dưa chua vào. Nêm đường, hạt nêm và một chén nước lạnh, để lửa vừa đến khi ngấm đầu gia vị. Cho ra bát, rắc rau om, mùi tau và hành khô lên. Dùng nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1729, '2025-11-20 17:10:25.787992', '2025-11-20 17:10:25.787992', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 280, 9, 'Giò lợn om mía đậu
INSERT INTO public.recipe_steps VALUES (1876, '2025-11-20 17:10:30.560296', '2025-11-20 17:10:30.560296', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 306, 2, 'Chần mỳ tôm qua nước sôi, vớt ra rổ để ráo, cà chua bổ cau.', 10);
INSERT INTO public.recipe_steps VALUES (1730, '2025-11-20 17:10:25.790694', '2025-11-20 17:10:25.790694', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 280, 14, 'Đun nóng dầu ăn, cho nốt hành vào xào sơ đến khi dầu trong và láng chảo thì cho tiếp chỗ tỏi, ớt bột, sả bằm xào khoảng 1 phút. Cho sả cây vào nồi, cho tiếp gà vào xào sơ, đảo đều, đậy nắp để khoảng vài ba phút thì cho nước dừa vào, quậy và đun nhỏ lửa để nước dừa đặc lại và hơi sền sệt, giảm lửa, đậy vung trong khoảng 10 phút nữa. Dùng nóng với bánh mì hoặc cơm trắng.', 10);
INSERT INTO public.recipe_steps VALUES (1731, '2025-11-20 17:10:25.793387', '2025-11-20 17:10:25.793387', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 280, 13, 'Cách làm:Gà chặt miếng vừa ăn, ướp với một nửa hành, tỏi, sả bằm, bột nghệ, hạt nêm khoảng 15 phút.', 10);
INSERT INTO public.recipe_steps VALUES (1732, '2025-11-20 17:10:25.795541', '2025-11-20 17:10:25.795541', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 280, 2, 'Cách làm:Cà tím ngắt cuống, rửa sạch, chẻ dọc làm bốn, bỏ bớt phần ruột, xắt quân cờ. Thịt ướp với hạt nêm, tỏi khoảng 10 phút. Cho dầu ăn vào nồi, phi thơm tỏi, hành khô, cho cà tím vào đảo khoảng 1 phút rồi cho thịt vào, đảo đều trên lửa nhỏ. Nêm tiếp nước dùng heo, nấu lửa riu riu đến khi cà tím mềm nhừ nhưng không nát. Nêm vừa miệng, rắc tiêu. Dọn ra bát, dùng nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1733, '2025-11-20 17:10:25.798544', '2025-11-20 17:10:25.798544', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 280, 11, 'Đun nóng dầu ăn trong nồi, phi thơm tỏi, cho giò vào xào qua. Đổ vào nồi khoảng hai chén nước, cho mía, lạc, nấm mèo vào đậy vung, để lửa vừa đến khi nước sanh sánh là được. (Trang trí món ăn với ớt đỏ và mùi tàu).', 10);
INSERT INTO public.recipe_steps VALUES (1734, '2025-11-20 17:10:25.800697', '2025-11-20 17:10:25.800697', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 280, 7, 'Cách làm:Sườn non rửa sạch, chặt miếng vừa ăn, ướp với hạt nêm, nước mắm, đường trong khoảng 20 phút. Dưa chua xắt bớt cuống, bỏ bớt lá, cắt ngắn rồi xả nước lạnh, để ráo. Rau om, mùi tàu rửa sạch, xắt nhỏ. Hành khô lột vỏ, bào mỏng, phi vàng.', 10);
INSERT INTO public.recipe_steps VALUES (1735, '2025-11-20 17:10:25.80339', '2025-11-20 17:10:25.80339', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 280, 12, 'Gà om nước dừa
INSERT INTO public.recipe_steps VALUES (1736, '2025-11-20 17:10:25.805519', '2025-11-20 17:10:25.805519', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 280, 5, 'Phi thơm tỏi, cho cá trê vào xào sơ, đổ nước dừa vào nồi xâm xấp. Om khoảng 30 phút cho thêm chút nước và hoa chuối, chuối chát vào, om tiếp 10 phút nữa là được. Cho món om ra bát, rắc rau om, rau mùi lên, dùng nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1737, '2025-11-20 17:10:25.988738', '2025-11-20 17:10:25.988738', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 281, 4, 'Lấy bánh rế cuộn hỗn hợp trên, mỗi cuộn thêm một con tôm.', 10);
INSERT INTO public.recipe_steps VALUES (1738, '2025-11-20 17:10:25.990337', '2025-11-20 17:10:25.990337', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 281, 5, 'Bắc dầu ăn lên bếp, cho chả giò vào chiên đến khi chín vàng.', 10);
INSERT INTO public.recipe_steps VALUES (1739, '2025-11-20 17:10:25.991955', '2025-11-20 17:10:25.991955', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 281, 2, 'Hạt sen luộc chín.', 10);
INSERT INTO public.recipe_steps VALUES (1740, '2025-11-20 17:10:25.993015', '2025-11-20 17:10:25.993015', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 281, 1, 'Khoai môn cắt sợi.', 10);
INSERT INTO public.recipe_steps VALUES (1741, '2025-11-20 17:10:25.995238', '2025-11-20 17:10:25.995238', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 281, 3, 'Trộn tất cả các thành phần cho đều.', 10);
INSERT INTO public.recipe_steps VALUES (1742, '2025-11-20 17:10:25.996763', '2025-11-20 17:10:25.996763', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 281, 6, 'Bày ra đĩa với xà lách, dùng nóng với tương xí muội.', 10);
INSERT INTO public.recipe_steps VALUES (1743, '2025-11-20 17:10:26.181842', '2025-11-20 17:10:26.181842', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 282, 1, 'Trộn thịt xay với giò sống, nấm đông cô, hành tây. Nêm nước mắm, tiêu, đường vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1744, '2025-11-20 17:10:26.183428', '2025-11-20 17:10:26.183428', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 282, 4, 'Ăn nóng với nước mắm ớt, kèm cơm, canh.', 10);
INSERT INTO public.recipe_steps VALUES (1745, '2025-11-20 17:10:26.184614', '2025-11-20 17:10:26.184614', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 282, 2, 'Nhồi nhân vào ruột dưa leo, hấp khoảng 15 phút, xếp ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (1746, '2025-11-20 17:10:26.186167', '2025-11-20 17:10:26.186167', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 282, 3, 'Xào thơm hành tây, tỏi, cho cà chua vào xào, nêm nước mắm, đường, bột ngô cho hơi sánh. Rưới lên đĩa dưa leo, rắc rau mùi lên trên.', 10);
INSERT INTO public.recipe_steps VALUES (1747, '2025-11-20 17:10:26.298483', '2025-11-20 17:10:26.298483', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 283, 1, 'Tôm rán lúa mạch
INSERT INTO public.recipe_steps VALUES (1748, '2025-11-20 17:10:26.300595', '2025-11-20 17:10:26.300595', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 283, 3, 'Atiso trộn
INSERT INTO public.recipe_steps VALUES (1749, '2025-11-20 17:10:26.302836', '2025-11-20 17:10:26.302836', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 283, 5, 'Pha sốt:Trộn giấm với mù tạt vàng, tỏi băm, dầu ôliu, rau mùi tây, muối và tiêu. Rưới sốt lên rau củ, trộn đều. Trút ra đĩa, xếp trứng và quả ôliu lên. Dùng thìa múc cá ngừ lên trên cùng.', 10);
INSERT INTO public.recipe_steps VALUES (1750, '2025-11-20 17:10:26.304427', '2025-11-20 17:10:26.304427', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 283, 2, ':
INSERT INTO public.recipe_steps VALUES (1751, '2025-11-20 17:10:26.306099', '2025-11-20 17:10:26.306099', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 283, 4, 'Cách làm:Luộc chín trứng, cắt múi cau. Luộc chín khoai tây, cắt miếng vuông, cạnh 1,5cm. Luộc chín đậu cô ve, ngâm với nước lạnh cho xanh. Rửa cà chua, cắt múi cau. Ớt Đà Lạt cắt miếng dài khoảng 3cm, hành tím cắt khoanh. Tỏi bóc vỏ, băm nhuyễn. Rau mùi tây thái nhuyễn. Atiso thái miếng vừa ăn. Trộn đều khoai tây, đậu cô-ve, ớt, hành tím, atiso và cà chua.', 10);
INSERT INTO public.recipe_steps VALUES (1752, '2025-11-20 17:10:26.480181', '2025-11-20 17:10:26.480181', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 284, 4, 'Món canh này dùng nóng hay nguội đều ngon.', 10);
INSERT INTO public.recipe_steps VALUES (1753, '2025-11-20 17:10:26.481784', '2025-11-20 17:10:26.481784', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 284, 2, 'Lấy nước vừa đủ một tô canh (khoảng 4 người ăn) đun sôi, thả tôm vào nấu 5 phút, hớt bọt.', 10);
INSERT INTO public.recipe_steps VALUES (1754, '2025-11-20 17:10:26.483913', '2025-11-20 17:10:26.483913', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 284, 3, 'Cho mướp vào nấu sôi, mướp mềm, cho miến, nấm mèo, nêm nước mắm, muối, vừa ăn. Múc ra tô, rắc hành ngò.', 10);
INSERT INTO public.recipe_steps VALUES (1930, '2025-11-20 17:10:32.770821', '2025-11-20 17:10:32.770821', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 317, 5, 'Thịt bò chín mềm vớt ra để nguội, gỡ lạt thái mỏng vừa bày đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (1756, '2025-11-20 17:10:26.593657', '2025-11-20 17:10:26.593657', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 285, 1, 'Càng cua đồng mua về, rửa sạch, sau đó đem luộc sơ với nước sôi, mang ra để cho ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (1757, '2025-11-20 17:10:26.595768', '2025-11-20 17:10:26.595768', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 285, 3, 'Cứ rang khô cho đến khi càng cua chín vàng, giòn là được.', 10);
INSERT INTO public.recipe_steps VALUES (1758, '2025-11-20 17:10:26.597356', '2025-11-20 17:10:26.597356', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 285, 2, 'Kế đến, bắc chảo lên bếp (không cần dầu mỡ) bỏ càng cua vào chảo và rắc muối ớt vào (tùy càng cua ít nhiều mà rắc muối cho vừa ăn).', 10);
INSERT INTO public.recipe_steps VALUES (1759, '2025-11-20 17:10:26.719954', '2025-11-20 17:10:26.719954', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 286, 1, 'Cá đánh sạch vẩy, rửa sạch, bỏ đầu, ruột, ướp muối, tiêu.', 10);
INSERT INTO public.recipe_steps VALUES (1760, '2025-11-20 17:10:26.722141', '2025-11-20 17:10:26.722141', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 286, 5, 'Pha nước chấm: Hoà nước sôi để nguội với nước mắm, đường, dấm, mì chính, tỏi, ớt băm nhỏ để có gia vị chua, mặn, ngọt, cay.', 10);
INSERT INTO public.recipe_steps VALUES (1761, '2025-11-20 17:10:26.723759', '2025-11-20 17:10:26.723759', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 286, 4, 'Ăn nóng với nước chấm chua ngọt.', 10);
INSERT INTO public.recipe_steps VALUES (1762, '2025-11-20 17:10:26.726246', '2025-11-20 17:10:26.726246', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 286, 3, 'Đun mỡ nóng già, nhúng cá vào bột ngập kín, thả vào rán ngập mỡ, cá màu vàng đều là được.', 10);
INSERT INTO public.recipe_steps VALUES (1763, '2025-11-20 17:10:26.727836', '2025-11-20 17:10:26.727836', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 286, 6, 'Cá rán vàng rơm, mùi thơm, không tanh, vị ngon, bột bao kín, giòn, xốp. Nước chấm nổi vị chua, cay, mặn, ngọt, dậy mùi.', 10);
INSERT INTO public.recipe_steps VALUES (1764, '2025-11-20 17:10:26.729958', '2025-11-20 17:10:26.729958', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 286, 2, 'Trứng lấy lòng trắng đánh nổi bọt rồi trộn bột, muối, nước, lòng đỏ trứng thành bột sánh.', 10);
INSERT INTO public.recipe_steps VALUES (1765, '2025-11-20 17:10:26.916512', '2025-11-20 17:10:26.916512', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 287, 1, 'Tôm he lột vỏ, giã nhuyễn, trộn đều với giò sống và hạt nêm. Hòa bột năng vớ ít nước lạnh. Bông cải xanh rửa sạch, trụng qua nước sôi.', 10);
INSERT INTO public.recipe_steps VALUES (1766, '2025-11-20 17:10:26.918194', '2025-11-20 17:10:26.918194', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 287, 2, 'Bầu gọt vỏ, xắt thành những miếng dày khoảng 2 cm, dùng khuôn tròn ấn nhẹ tay, bỏ ruột, nhồi nhân tôm vào giữa, cho vào nồi hấp chín.', 10);
INSERT INTO public.recipe_steps VALUES (1767, '2025-11-20 17:10:26.919291', '2025-11-20 17:10:26.919291', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 287, 3, 'Đun sôi nước dùng heo, nêm gia vị vừa miệng, xuống bột năng, ớt bằm, đun sôi, nêm dầu mè, rưới lên đĩa bầu. Trang trí với bông cải xanh.', 10);
INSERT INTO public.recipe_steps VALUES (1768, '2025-11-20 17:10:27.150731', '2025-11-20 17:10:27.150731', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 288, 2, 'Chắt nước hầm trên vào một nồi khác, đun nóng lại cho đến khi sủi bọt. Cho hành lá, rau mùi, cải thìa và đậu hũ vào trong nồi, nấu trong khoảng 3 phút.', 10);
INSERT INTO public.recipe_steps VALUES (1769, '2025-11-20 17:10:27.151798', '2025-11-20 17:10:27.151798', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 288, 1, 'Cho gừng, hoa hồi, ớt, bột nêm (hay bột canh) vào nồi nước lớn, đun lửa nhỏ cho đến khi nước sôi. Giảm nhiệt độ và ninh trong khoảng 10 phút.', 10);
INSERT INTO public.recipe_steps VALUES (1770, '2025-11-20 17:10:27.153943', '2025-11-20 17:10:27.153943', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 288, 3, 'Trong một tô nhỏ, khuấy đều bột nêm Miso và nước súp vừa nấu cho đến khi hòa tan. Đổ hỗn hợp trở lại trong nồi. Cho một ít nước tương và nêm cho vừa ăn. Khi dọn ra tô, rắc lên trên súp một ít hành lá và rau mùi, cùng một chút ớt tươi nếu thích.', 10);
INSERT INTO public.recipe_steps VALUES (1771, '2025-11-20 17:10:27.360413', '2025-11-20 17:10:27.360413', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 289, 3, 'Nấu sôi nước dùng và nước ép kiwi, nêm đường, hạt nêm vừa ăn. Sau cùng cho kiwi và ớt, hạt lựu vào, thêm ít bột năng để tạo độ sánh. Thịt cuộn đã chín cắt đôi, xếp ra đĩa tưới nước xốt lên trên.', 10);
INSERT INTO public.recipe_steps VALUES (1772, '2025-11-20 17:10:27.362033', '2025-11-20 17:10:27.362033', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 289, 1, 'Thịt rửa sạch thái mỏng, đập dẹp. Xoài, cà rốt gọt vỏ cắt sợi dài, to. Hành lá cắt khúc. Ớt cắt hạt lựu. Kiwi một trái cắt hạt lựu, trái kia ép lấy nước.', 10);
INSERT INTO public.recipe_steps VALUES (1773, '2025-11-20 17:10:27.363637', '2025-11-20 17:10:27.363637', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 289, 2, 'Cho cà rốt, xoài và hành vào giữa miếng thịt, cuộn lại, lăn qua bột năng, dầu nóng cho vào chiên chín vàng.', 10);
INSERT INTO public.recipe_steps VALUES (1774, '2025-11-20 17:10:27.58385', '2025-11-20 17:10:27.58385', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 290, 2, 'Ngò gai, rửa sạch, để ráo, xắt thật nhuyễn, để cọng và lá riêng.', 10);
INSERT INTO public.recipe_steps VALUES (1775, '2025-11-20 17:10:27.585996', '2025-11-20 17:10:27.585996', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 290, 3, 'Hành tây, bóc vỏ, thái mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (1776, '2025-11-20 17:10:27.587559', '2025-11-20 17:10:27.587559', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 290, 1, 'Phi lê bò mềm, thái miếng mỏng theo xớ ngang.', 10);
INSERT INTO public.recipe_steps VALUES (1777, '2025-11-20 17:10:27.589877', '2025-11-20 17:10:27.589877', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 290, 4, 'Me chín, dằm với nước nóng và lược lấy nước me.', 10);
INSERT INTO public.recipe_steps VALUES (1778, '2025-11-20 17:10:27.591475', '2025-11-20 17:10:27.591475', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 290, 7, 'Nấu sôi nước me, nêm 1/2 muỗng cà phê hạt nêm từ thịt, 1 muỗng cà phê đường. Cho thịt bò vào trụng vừa chín tái vớt ra, để cho ráo, rồi cho ra tô. Thêm cọng ngò gai đã xắt nhuyễn, củ hành tây và tỏi phi vào, trộn đều lên rồi cho ra đĩa. Rắc lá ngò gai đã xắt nhuyễn, đậu phộng, tỏi phi... Trang trí quả ớt sừng đã tỉa hoa ở giữa.', 10);
INSERT INTO public.recipe_steps VALUES (1779, '2025-11-20 17:10:27.592541', '2025-11-20 17:10:27.592541', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 290, 5, 'Đậu phộng rang, đãi vỏ, giã dập.', 10);
INSERT INTO public.recipe_steps VALUES (1780, '2025-11-20 17:10:27.59355', '2025-11-20 17:10:27.59355', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 290, 6, 'Nấu nước mắm và đường cho đến khi đường tan và sánh lại là được.', 10);
INSERT INTO public.recipe_steps VALUES (1781, '2025-11-20 17:10:27.595608', '2025-11-20 17:10:27.595608', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 290, 8, 'Dùng với nước mắm ớt và bánh tráng nướng hoặc chiên.', 10);
INSERT INTO public.recipe_steps VALUES (1782, '2025-11-20 17:10:27.729108', '2025-11-20 17:10:27.729108', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 291, 2, 'Cho vào chảo 2 thìa súp dầu ăn, đợi dầu nóng, cho củ hành vào phi thơm, cho tôm vào xào chín, rồi thịt ba chỉ vào xào chín. Nêm nước mắm, nước tương hạt nêm từ thịt. Tiếp tục xào vài phút cho thấm gia vị. Cho tiếp đường vào đảo đều trước khi nước sốt sệt lại.', 10);
INSERT INTO public.recipe_steps VALUES (1783, '2025-11-20 17:10:27.730742', '2025-11-20 17:10:27.730742', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 291, 3, 'Cuối cùng, cho tôm thịt ra đĩa, rắc tiêu. Dùng nóng với cơm trắng.', 10);
INSERT INTO public.recipe_steps VALUES (1784, '2025-11-20 17:10:27.731818', '2025-11-20 17:10:27.731818', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 291, 1, 'Tôm bạc cắt bỏ râu, để nguyên vỏ. Thịt ba rọi rửa nước muối, để ráo, cắt miếng mỏng vừa ăn. Ướp tôm, thịt với muối.', 10);
INSERT INTO public.recipe_steps VALUES (1931, '2025-11-20 17:10:32.772381', '2025-11-20 17:10:32.772381', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 317, 3, 'Khoai tây thái hạt lựu rồi rán qua để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (1785, '2025-11-20 17:10:27.900757', '2025-11-20 17:10:27.900757', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 292, 7, 'Bạn có thể thay bầu bằng rau muống. Khi đó, có thể nêm vào canh 1/3 muỗng súp gừng non cắt sợi thật nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (1786, '2025-11-20 17:10:27.902371', '2025-11-20 17:10:27.902371', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 292, 1, 'Bầu gọt vỏ, cắt khoanh dày chừng nửa phân rồi cắt lại thành dạng sợi dày.', 10);
INSERT INTO public.recipe_steps VALUES (1787, '2025-11-20 17:10:27.904524', '2025-11-20 17:10:27.904524', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 292, 2, 'Nghêu rửa sạch đun với 2 chén nước đến khi vừa hé miệng. Đợi nghêu nguội thì cạy lấy nạc, để riêng nước luộc.', 10);
INSERT INTO public.recipe_steps VALUES (1788, '2025-11-20 17:10:27.906637', '2025-11-20 17:10:27.906637', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 292, 6, 'Nếu dùng ruốc tươi để nêm thay vì ruốc làm khô thì hoà tan chừng 2 muỗng cà phê ruốc (hoặc gia giảm tùy chất lượng ruốc đang có) với lưng chén nước rồi mới châm từ từ nước ruốc vào canh cho vừa đậm đà, sau cùng mới cho thêm ít muối.', 10);
INSERT INTO public.recipe_steps VALUES (1789, '2025-11-20 17:10:27.908795', '2025-11-20 17:10:27.908795', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 292, 5, 'Múc canh ra tô, rắc hành ngò và chút tiêu bột lên canh, ăn nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1790, '2025-11-20 17:10:27.910374', '2025-11-20 17:10:27.910374', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 292, 3, 'Ướp trộn đều vào nạc nghêu: 1/4 muỗng cà phê ớt bột (nếu thích ăn cay) + 1/2 muỗng cà phê muối + 1/2 muỗng nhỏ tiêu + 2 muỗng cà phê hành băm thật nhuyễn. Để khoảng 10 phút, làm nóng 1-2 muỗng súp dầu ăn (hoặc mỡ nước) cho nghêu vào, đảo đều trong khoảng 15 giây.', 10);
INSERT INTO public.recipe_steps VALUES (1791, '2025-11-20 17:10:27.912118', '2025-11-20 17:10:27.912118', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 292, 4, 'Lược lại nước luộc nghêu, thêm vào ít nước vừa ăn. Nấu sôi, thả bầu vào, thăm chừng bầu vừa chín dòn thì nêm lại với chút muối và vài muỗng bột ruốc đã làm khô. Sau đó, cho phần nghêu xào vào, cho sôi lại.', 10);
INSERT INTO public.recipe_steps VALUES (1792, '2025-11-20 17:10:28.106299', '2025-11-20 17:10:28.106299', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 293, 1, 'Sách bò rửa sạch, bóp với giấm bỗng, sau đó rửa lại với rượu, gừng cho sạch, xắt miếng vừa ăn, trụng nước sôi khoảng 2 phút cho chín, vớt ra, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (1793, '2025-11-20 17:10:28.107357', '2025-11-20 17:10:28.107357', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 293, 3, 'Trộn đều sách với ngó sen, hành tây, dưa leo, giá đỗ, cà rốt, rau răm. Pha đường, giấm, ớt, tỏi, muối với ít nước lạnh rồi rưới lên tô sách, trộn đều lên, để khoảng 5 phút cho ngấm, bày ra đĩa, rắc đậu phộng.', 10);
INSERT INTO public.recipe_steps VALUES (1794, '2025-11-20 17:10:28.108951', '2025-11-20 17:10:28.108951', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 293, 2, 'Ngó sen ngâm cho hết đen, rửa sạch, chẻ đôi. Hành tây lột vỏ, xắt khoanh tròn, dưa leo ngâm, rửa sạch, bỏ ruột, xắt sợi to. Cà rốt gọt vỏ, xắt sợi to.', 10);
INSERT INTO public.recipe_steps VALUES (1795, '2025-11-20 17:10:28.339512', '2025-11-20 17:10:28.339512', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 294, 2, 'Cho thịt cua, giò sống, thịt gà bằm, củ hành, nấm rơm, bún tàu và bảy cái trứng gà vào một cái tô lớn, nêm gia vị muối, đường, hạt nêm, tiêu xay, rồi trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (1796, '2025-11-20 17:10:28.341811', '2025-11-20 17:10:28.341811', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 294, 1, 'Cua rửa sạch, mai cua và vài cái chân cua để riêng. Dùng nồi hấp chín cua, gỡ lấy thịt (không hấp chân và mai cua).', 10);
INSERT INTO public.recipe_steps VALUES (1797, '2025-11-20 17:10:28.343403', '2025-11-20 17:10:28.343403', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 294, 3, 'Cho hỗn hợp trứng này vào một cái tô có đáy phẳng, xếp mai và chân cua lên mặt trứng.', 10);
INSERT INTO public.recipe_steps VALUES (1798, '2025-11-20 17:10:28.345102', '2025-11-20 17:10:28.345102', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 294, 4, 'Đốt nóng lò nướng, sau đó cho tộ trứng vào nướng 200 độ C, nhớ canh lửa trên dưới, nếu thấy quá nóng thì giảm bớt lửa.', 10);
INSERT INTO public.recipe_steps VALUES (1799, '2025-11-20 17:10:28.347268', '2025-11-20 17:10:28.347268', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 294, 5, 'Khi chả gần chín, dùng quả trứng còn lại đánh tan cho lên mặt, tráng lại cho đều, nướng tiếp đến khi trứng chín', 10);
INSERT INTO public.recipe_steps VALUES (1800, '2025-11-20 17:10:28.458266', '2025-11-20 17:10:28.458266', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 295, 9, 'Bày trứng, trút nước salad dội lên trên. Ăn kèm các món nướng, rán.', 10);
INSERT INTO public.recipe_steps VALUES (1801, '2025-11-20 17:10:28.459853', '2025-11-20 17:10:28.459853', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 295, 2, 'Dưa chuột thái vát mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (1802, '2025-11-20 17:10:28.462001', '2025-11-20 17:10:28.462001', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 295, 5, 'Cà chua thái mỏng vừa.', 10);
INSERT INTO public.recipe_steps VALUES (1803, '2025-11-20 17:10:28.463058', '2025-11-20 17:10:28.463058', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 295, 4, 'Dứa xanh bỏ vỏ mắt, thái mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (1804, '2025-11-20 17:10:28.4655', '2025-11-20 17:10:28.4655', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 295, 3, 'Hành tây thái mỏng', 10);
INSERT INTO public.recipe_steps VALUES (1805, '2025-11-20 17:10:28.467113', '2025-11-20 17:10:28.467113', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 295, 7, 'Hòa 1 bát nước gồm: giấm + đường + tỏi ớt + nước và 1 chút muối, cuối cùng cho dầu ô liu (dầu ăn) đảo đều.', 10);
INSERT INTO public.recipe_steps VALUES (1806, '2025-11-20 17:10:28.468721', '2025-11-20 17:10:28.468721', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 295, 6, 'Hành tây, giá đỗ, ngâm một chút muối trước khi trộn 5 phút, gạn bỏ nước dư để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (1807, '2025-11-20 17:10:28.469797', '2025-11-20 17:10:28.469797', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 295, 8, 'Xếp rau salad xuống dưới, xếp xen kẽ các nguyên liệu khác cho đẹp.', 10);
INSERT INTO public.recipe_steps VALUES (1808, '2025-11-20 17:10:28.471381', '2025-11-20 17:10:28.471381', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 295, 1, 'Trứng gà luộc chín bổ làm 6 miếng.', 10);
INSERT INTO public.recipe_steps VALUES (1809, '2025-11-20 17:10:28.713026', '2025-11-20 17:10:28.713026', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 296, 3, 'Xếp tôm ra đĩa, trang trí với xà lách, cà chua và ăn kèm muối tiêu chanh.', 10);
INSERT INTO public.recipe_steps VALUES (1810, '2025-11-20 17:10:28.714228', '2025-11-20 17:10:28.714228', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 296, 2, 'Tôm chiên sơ qua trong dầu nóng, xếp ra khay. Trộn đều hỗn hợp phô mai, ớt sừng và ngò tây rồi rắc lên lưng tôm. Cho tôm vào lò nướng với lửa vừa. Khi phô mai vàng, rắc ít bột xù tán mịn lên trên. Nướng thêm một phút rồi cho ra.', 10);
INSERT INTO public.recipe_steps VALUES (1811, '2025-11-20 17:10:28.715306', '2025-11-20 17:10:28.715306', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 296, 1, 'Tôm sú rửa sạch, để ráo, chẻ lưng hơi sâu, dùng que tre xiên từ đuôi lên. Phô mai băm nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (1812, '2025-11-20 17:10:28.794308', '2025-11-20 17:10:28.794308', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 297, 4, 'Tôm luộc chín với ít rượu trắng cho thơm, lột vỏ chừa đuôi. Thịt luộc chín, thái lát.', 10);
INSERT INTO public.recipe_steps VALUES (1813, '2025-11-20 17:10:28.795892', '2025-11-20 17:10:28.795892', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 297, 15, 'Món này trộn 1 ngày sau dùng được, bảo quản trong tủ lạnh ăn cả tuần.', 10);
INSERT INTO public.recipe_steps VALUES (1814, '2025-11-20 17:10:28.798117', '2025-11-20 17:10:28.798117', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 297, 17, 'Ngó sen cắt khúc, ngâm chanh, dùng đũa lấy xơ, rửa lại nước cho sạch. Tôm lột vỏ chừa đuôi, xẻ sống lưng lấy bỏ chỉ.', 10);
INSERT INTO public.recipe_steps VALUES (1990, '2025-11-20 17:10:34.755481', '2025-11-20 17:10:34.755481', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 328, 17, 'Cho thịt ếch và gừng vào hấp chín.', 10);
INSERT INTO public.recipe_steps VALUES (1815, '2025-11-20 17:10:28.799735', '2025-11-20 17:10:28.799735', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 297, 27, 'Ngó sen cắt khúc, ngâm chanh, lấy xơ. Me cho ít nước nóng vào tán cho ra nước chua. Tôm cắt bỏ đầu đuôi và chân, rửa sạch. Ngò gai, rau om rửa sạch, cắt nhuyễn, ớt cắt khoanh.', 10);
INSERT INTO public.recipe_steps VALUES (1816, '2025-11-20 17:10:28.802475', '2025-11-20 17:10:28.802475', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 297, 10, 'Gia vị: Đường, bột ngọt, nước mắm, dấm, muối bột.', 10);
INSERT INTO public.recipe_steps VALUES (1817, '2025-11-20 17:10:28.804614', '2025-11-20 17:10:28.804614', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 297, 1, 'Gỏi ngó sen
INSERT INTO public.recipe_steps VALUES (1818, '2025-11-20 17:10:28.806218', '2025-11-20 17:10:28.806218', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 297, 5, 'Ngó sen cắt khúc, ngâm nước chanh cho không đen, dùng đũa quậy lấy xơ, ngâm với dấm đường (pha ít chua ngọt) trước 1 ngày (có thể mua ngó sen ngâm chua sẵn ở chợ). Chắt bỏ nước dấm, xóc với ít đường cho ra bớt chất chua, vắt sơ.', 10);
INSERT INTO public.recipe_steps VALUES (1819, '2025-11-20 17:10:28.807817', '2025-11-20 17:10:28.807817', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 297, 6, 'Cà rốt ướp ít muối cho ra nước, xả nước lại, vắt ráo. Rau răm thái nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (1820, '2025-11-20 17:10:28.809438', '2025-11-20 17:10:28.809438', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 297, 20, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1821, '2025-11-20 17:10:28.811042', '2025-11-20 17:10:28.811042', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 297, 22, 'Hạt sen rửa sạch, luộc mềm. Táo rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (1822, '2025-11-20 17:10:28.812119', '2025-11-20 17:10:28.812119', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 297, 11, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1823, '2025-11-20 17:10:28.81428', '2025-11-20 17:10:28.81428', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 297, 28, 'Bắc nồi nước đun sôi lên, cho tôm vào nấu chín sơ, vớt bọt. Cho ngó sen vào nấu vừa sôi vài dạo. Nêm gia vị, nước me cho vừa ăn. Tắt lửa, cho rau om ngò gai, ớt vào.', 10);
INSERT INTO public.recipe_steps VALUES (1824, '2025-11-20 17:10:28.816522', '2025-11-20 17:10:28.816522', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 297, 16, ':
INSERT INTO public.recipe_steps VALUES (1825, '2025-11-20 17:10:28.818584', '2025-11-20 17:10:28.818584', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 297, 2, 'Gia vị: đường, bột ngọt, nước mắm, dấm, 2 muỗng súp tỏi băm.', 10);
INSERT INTO public.recipe_steps VALUES (1826, '2025-11-20 17:10:28.820742', '2025-11-20 17:10:28.820742', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 297, 13, 'Dưa chuột xóc đường cho ra dấm, chắt bỏ dấm. Cà rốt cắt khoanh dày 2mm, xóc muối cho ra nước, rửa lại, vắt thật ráo.', 10);
INSERT INTO public.recipe_steps VALUES (1827, '2025-11-20 17:10:28.822907', '2025-11-20 17:10:28.822907', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 297, 25, 'Canh ngó sen
INSERT INTO public.recipe_steps VALUES (1828, '2025-11-20 17:10:28.825074', '2025-11-20 17:10:28.825074', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 297, 9, 'Kim chi củ sen
INSERT INTO public.recipe_steps VALUES (1829, '2025-11-20 17:10:28.826657', '2025-11-20 17:10:28.826657', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 297, 14, 'Gừng củ cắt sợi, gừng băm vắt lấy nước. Cho tất cả vào thau, cho gia vị, ớt bột, tỏi băm vào nêm cho chua ngọt, có chút ít mặn cho vừa ăn theo khẩu vị.', 10);
INSERT INTO public.recipe_steps VALUES (1830, '2025-11-20 17:10:28.82827', '2025-11-20 17:10:28.82827', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 297, 8, '1 muỗng súp tỏi còn lại phi vàng thơm, cho vào gỏi. Cho gỏi ra đĩa, trên rắc mè và rau răm.', 10);
INSERT INTO public.recipe_steps VALUES (1831, '2025-11-20 17:10:28.829887', '2025-11-20 17:10:28.829887', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 297, 3, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1832, '2025-11-20 17:10:28.832462', '2025-11-20 17:10:28.832462', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 297, 21, 'Củ sen bào vỏ, cắt khoanh dày 5 mm, ngâm rửa chanh cho không bị đen. Cà rốt tỉa khía, cắt khoang dày 1 cm.', 10);
INSERT INTO public.recipe_steps VALUES (1833, '2025-11-20 17:10:28.834056', '2025-11-20 17:10:28.834056', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 297, 26, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (1834, '2025-11-20 17:10:28.836203', '2025-11-20 17:10:28.836203', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 297, 12, 'Củ sen bào vỏ, cắt khoanh dày khoảng 3 mm, ngâm nước chanh cho không đen, hòa dấm đường ngâm cho chua (khoảng 2 ngày), vắt bỏ dấm, cho 4 muỗng súp đường xóc đều, để cho ráo nước, chắt bỏ (làm 2 lần).', 10);
INSERT INTO public.recipe_steps VALUES (1835, '2025-11-20 17:10:28.838328', '2025-11-20 17:10:28.838328', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 297, 24, 'Sau cùng cho hạt sen vào, nêm gia vị cho vừa ăn. Cho hành ngò.', 10);
INSERT INTO public.recipe_steps VALUES (1836, '2025-11-20 17:10:28.839957', '2025-11-20 17:10:28.839957', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 297, 23, 'Giò heo hầm sơ, cho củ sen vào hầm chung một lúc cho cà rốt vào hầm, một chút sau cho táo vào.', 10);
INSERT INTO public.recipe_steps VALUES (1837, '2025-11-20 17:10:28.841579', '2025-11-20 17:10:28.841579', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 297, 18, 'Phi tỏi băm cho thơm, cho tôm vào xào với lửa lớn cho săn, cho tiếp ngó sen, gia vị vào xào vừa chín tới, nêm lại cho vừa ăn, tắt lửa múc ra đĩa, cho tiêu và hành ngò lên mặt.', 10);
INSERT INTO public.recipe_steps VALUES (1838, '2025-11-20 17:10:28.843176', '2025-11-20 17:10:28.843176', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 297, 19, 'Canh củ sen hầm giò heo
INSERT INTO public.recipe_steps VALUES (1839, '2025-11-20 17:10:28.844793', '2025-11-20 17:10:28.844793', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 297, 7, 'Trộn ngó sen, cà rốt, tôm thịt với 1 muỗng súp tỏi băm, ớt, đường, bột ngọt, nước mắm, chanh cho vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1840, '2025-11-20 17:10:29.057706', '2025-11-20 17:10:29.057706', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 298, 2, 'Xào sơ tương cà với dầu ăn rồi cho tỏi gà vào xào đều. Thêm nước dùng vào đun sôi lên. Nêm với hạt nêm và đường cát trắng cho vừa ăn. Nấu lửa nhỏ khoảng 25 phút cho tỏi gà mềm.', 10);
INSERT INTO public.recipe_steps VALUES (1841, '2025-11-20 17:10:29.059333', '2025-11-20 17:10:29.059333', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 298, 1, 'Tỏi gà ướp với hạt nêm và tiêu xay cho ngấm, sau đó chiên vàng rồi vớt ra để ráo dầu.', 10);
INSERT INTO public.recipe_steps VALUES (1842, '2025-11-20 17:10:29.060466', '2025-11-20 17:10:29.060466', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 298, 3, 'Tiếp đó, thêm cà rốt, hành tím, nấm rơm vào nấu tiếp 15 phút nữa cho mềm và thấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (1843, '2025-11-20 17:10:29.062625', '2025-11-20 17:10:29.062625', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 298, 4, 'Cuối cùng, múc gà hầm nấm vào đĩa, dùng nóng với cơm hoặc bánh mì.', 10);
INSERT INTO public.recipe_steps VALUES (1844, '2025-11-20 17:10:29.218312', '2025-11-20 17:10:29.218312', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 299, 2, 'Cà rốt cạo vỏ, cắt khoanh, tỉa hoa. Súp lơ tách nhánh nhỏ; đậu tước xơ, để cả quả.', 10);
INSERT INTO public.recipe_steps VALUES (1845, '2025-11-20 17:10:29.219932', '2025-11-20 17:10:29.219932', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 299, 3, 'Khi sườn chín mềm, thả cà rốt vào khoảng 5 phút thì cho súp lơ và đậu vào nấu chín.', 10);
INSERT INTO public.recipe_steps VALUES (2024, '2025-11-20 17:10:35.224411', '2025-11-20 17:10:35.224411', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 331, 1, 'Cá hồi tẩm ướp gia vị rồi lăn qua bột mỳ cho vào rán đều các mặt.', 10);
INSERT INTO public.recipe_steps VALUES (1846, '2025-11-20 17:10:29.221009', '2025-11-20 17:10:29.221009', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 299, 1, 'Các nguyên liệu rửa sạch. Sườn lợn chặt miếng vừa ăn, đem chần qua nước sôi rồi đổ nước đó đi, thêm lượng nước khác vào đun sôi, ninh nhỏ lửa.', 10);
INSERT INTO public.recipe_steps VALUES (1847, '2025-11-20 17:10:29.223203', '2025-11-20 17:10:29.223203', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 299, 4, 'Nêm gia vị rồi tắt bếp, rắc rau mùi lên trên.', 10);
INSERT INTO public.recipe_steps VALUES (1848, '2025-11-20 17:10:29.437738', '2025-11-20 17:10:29.437738', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 300, 3, 'Cho măng vào, tiếp tục hầm cho vịt mềm và măng thấm.', 10);
INSERT INTO public.recipe_steps VALUES (1849, '2025-11-20 17:10:29.439367', '2025-11-20 17:10:29.439367', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 300, 4, 'Vớt vịt ra chặt miếng vừa ăn, cho lại vào nồi nước hầm, nấu sôi, cho đầu hành trắng và hành phi vào. Tắt bếp, nhắc xuống.', 10);
INSERT INTO public.recipe_steps VALUES (1850, '2025-11-20 17:10:29.440982', '2025-11-20 17:10:29.440982', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 300, 2, 'Nấu nước sôi, nêm nước mắm, cho vịt vào luộc chín, để lửa nhỏ, cho vài cọng ngò gai, nêm hạt nêm, đường, cho thịt vịt thấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (1851, '2025-11-20 17:10:29.44266', '2025-11-20 17:10:29.44266', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 300, 6, 'Múc canh vịt hầm măng ra tô, rắc tiêu. Dọn chung với nước mắm gừng.', 10);
INSERT INTO public.recipe_steps VALUES (1852, '2025-11-20 17:10:29.444268', '2025-11-20 17:10:29.444268', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 300, 1, 'Vịt làm sạch xát gừng để ráo, măng le tươi cắt bỏ phần gốc già, xắt sợi, luộc măng, vớt ra xả lại nước lạnh, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (1853, '2025-11-20 17:10:29.44638', '2025-11-20 17:10:29.44638', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 300, 5, 'Làm nước chấm: Gừng giã nhỏ, cho nước mắm, đưòng, tỏi, chanh, ớt vào, trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (1854, '2025-11-20 17:10:29.593785', '2025-11-20 17:10:29.593785', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 301, 1, 'Gừng cạo vỏ, rửa sạch, một nửa xắt sợi, còn lại giã nhỏ với tỏi, nêm ít nước lạnh, vắt lấy nước. Cà rốt gọt vỏ, xắt quân cờ to.', 10);
INSERT INTO public.recipe_steps VALUES (1855, '2025-11-20 17:10:29.595906', '2025-11-20 17:10:29.595906', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 301, 3, 'Bắc chảo lên bếp, đun nóng dầu ăn, cho thịt vịt vào xào, tiếp đến cho cà rốt, nêm hạt nêm. Thịt vịt ngấm đều gia vị, cho nước dừa và nước lạnh vào, đậy vung, om nhỏ lửa khoảng 25 phút. Múc ra tô, ăn kèm với bún.', 10);
INSERT INTO public.recipe_steps VALUES (1856, '2025-11-20 17:10:29.598624', '2025-11-20 17:10:29.598624', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 301, 2, 'Thịt vịt bóp với gừng, rượu cho hết mùi, rửa lại bằng nước sạch, chặt miếng cỡ bao diêm, ướp với nước gừng, tỏi và hạt nêm khoảng 15 phút.', 10);
INSERT INTO public.recipe_steps VALUES (1857, '2025-11-20 17:10:29.800616', '2025-11-20 17:10:29.800616', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 302, 4, 'Múc thịt kho dừa ra đĩa, rắc thêm một chút tiêu xay. Dùng với cơm nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1858, '2025-11-20 17:10:29.801674', '2025-11-20 17:10:29.801674', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 302, 2, 'Đặt nồi lên bếp, đợi nóng, cho thịt vào nồi xào đều cho đến khi thịt chuyển sang màu vàng nâu.', 10);
INSERT INTO public.recipe_steps VALUES (1859, '2025-11-20 17:10:29.803264', '2025-11-20 17:10:29.803264', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 302, 3, 'Cho tiếp nước nóng vào nồi, đợi sôi lại, cho tiếp cơm dừa đã xắt sợi vào nồi, cùng với củ hành tím. Để lửa nhỏ và tiếp tục kho cho đến khi thịt mềm là được.', 10);
INSERT INTO public.recipe_steps VALUES (1860, '2025-11-20 17:10:29.804871', '2025-11-20 17:10:29.804871', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 302, 1, 'Cho thịt ba chỉ vào tô, nêm vào 2 muỗng canh nước mắm chấm , 1 muỗng cà phê hạt nêm từ thịt và 1 muỗng cà phê đường thôi, trộn đều lên cho thịt ngấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (1861, '2025-11-20 17:10:30.037926', '2025-11-20 17:10:30.037926', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 303, 3, 'Bạn cần chú ý đến mức nước trong nồi khi nấu. Nếu thấy nước cạn, bạn phải cho thêm nước dừa vào.', 10);
INSERT INTO public.recipe_steps VALUES (1862, '2025-11-20 17:10:30.039506', '2025-11-20 17:10:30.039506', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 303, 4, 'Món này dùng nóng với bún, chấm nước ngắm nguyên chất pha ớt thái khoanh.', 10);
INSERT INTO public.recipe_steps VALUES (1863, '2025-11-20 17:10:30.041086', '2025-11-20 17:10:30.041086', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 303, 1, 'Sườn non rửa sạch, để ráo, chặt miếng dài 3 cm rồi ướp với tất cả các loại gia vị, để khoảng 30 phút. Đậu hũ rán thái miếng vuông, cạnh 1,5 cm. Dọc mùng tước vỏ, thái miếng xéo, bóp muối, rửa sạch. Ngò gai thái nhuyễn, dừa xiêm chặt lấy nước.', 10);
INSERT INTO public.recipe_steps VALUES (1864, '2025-11-20 17:10:30.042786', '2025-11-20 17:10:30.042786', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 303, 2, 'Đun nóng 1 thìa súp dầu ăn, trút sườn non vào xào sẵn. Cho nước dừa xiêm vào ngập mặt sườn, đun đến khi sườn chín mềm. Cho đậu hũ rán và dọc mùng vào nấu thêm 1 phút trên lửa lớn, tắt bếp. Bày sườn ra tô, rắc ngò gai thái nhuyễn lên mặt.', 10);
INSERT INTO public.recipe_steps VALUES (1865, '2025-11-20 17:10:30.249475', '2025-11-20 17:10:30.249475', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 304, 1, 'Giò heo thui (nướng vàng), cạo sạch lông, rửa sạch, chặt miếng cỡ bao diêm, ướp với nước mắm.', 10);
INSERT INTO public.recipe_steps VALUES (1866, '2025-11-20 17:10:30.251157', '2025-11-20 17:10:30.251157', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 304, 2, 'Bắc nồi nước lạnh lên bếp, cho sả, một nửa số ớt sừng trâu vào, đun sôi, cho giò heo vào hầm nhừ, vớt bỏ bọt và váng mỡ, nêm vừa miệng.', 10);
INSERT INTO public.recipe_steps VALUES (1867, '2025-11-20 17:10:30.252772', '2025-11-20 17:10:30.252772', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 304, 3, 'Bày giò heo ra tô, số ớt còn lại, lá chanh, rưới nước cốt tắc, nước dùng lên, rắc rau ngò.', 10);
INSERT INTO public.recipe_steps VALUES (1868, '2025-11-20 17:10:30.386627', '2025-11-20 17:10:30.386627', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 305, 2, 'Dưa chuột muối cắt hột lựu nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (1869, '2025-11-20 17:10:30.388273', '2025-11-20 17:10:30.388273', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 305, 3, 'Cà rốt thái chỉ, xắt nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (1870, '2025-11-20 17:10:30.390397', '2025-11-20 17:10:30.390397', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 305, 1, 'Tỏi gà (cánh gà) rút xương, không để rách da.', 10);
INSERT INTO public.recipe_steps VALUES (1871, '2025-11-20 17:10:30.392639', '2025-11-20 17:10:30.392639', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 305, 4, 'Giò sống trộn đều với gia vị, thêm cà rốt và dưa chuột muối, nhồi vào tỏi gà. Lấy tăm ghim lại, xếp vào khay, dưới lót hành và tỏi tây, quét chút dầu ăn lên gà, bỏ lò 180º C trong 20’(hoặc nướng trên than hoa) cho chín vàng. Cắt làm đôi, trình bày ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (1872, '2025-11-20 17:10:30.55124', '2025-11-20 17:10:30.55124', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 306, 10, 'Trang trí bằng lá húng, rau mùi tuỳ ý.', 10);
INSERT INTO public.recipe_steps VALUES (1873, '2025-11-20 17:10:30.555452', '2025-11-20 17:10:30.555452', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 306, 6, 'Lật mỳ cho mặt kia cũng săn lại thì rắc đều một ít gia vị hoặc bột nêm lên mỳ, cho ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (1874, '2025-11-20 17:10:30.557024', '2025-11-20 17:10:30.557024', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 306, 1, 'Thái thịt bò mỏng, ướp cùng gia vị, bột nêm, hạt tiêu và tỏi phi (phi thơm tỏi sau đó lấy tỏi phi để ướp) khoảng 15 phút.', 10);
INSERT INTO public.recipe_steps VALUES (1875, '2025-11-20 17:10:30.558622', '2025-11-20 17:10:30.558622', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 306, 9, 'Cho toàn bộ rau cải, hành tây, cà chua đã xào vào đảo cùng, múc lên trên mặt mỳ.', 10);
INSERT INTO public.recipe_steps VALUES (1877, '2025-11-20 17:10:30.561932', '2025-11-20 17:10:30.561932', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 306, 5, 'Cho dầu láng chảo, khi dầu nóng cho mỳ vào, dàn đều mỳ, không đảo nhiều, vặn lửa nhỏ vừa để mỳ tự săn xém lại, rắc đều 1 ít gia vị hoặc bột nêm lên mỳ.', 10);
INSERT INTO public.recipe_steps VALUES (1878, '2025-11-20 17:10:30.563563', '2025-11-20 17:10:30.563563', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 306, 4, 'Pha nước sốt: 1 thìa súp dầu hào, 2 thìa súp nước lọc, 1/2 thìa đường, 1 thìa xì dầu, 1 chút muối, 1 chút bột năng, hoà tan các nguyên liệu.', 10);
INSERT INTO public.recipe_steps VALUES (1879, '2025-11-20 17:10:30.565189', '2025-11-20 17:10:30.565189', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 306, 8, 'Để dầu nóng già mới cho thịt bò vào, không đảo nhiều, dàn mỏng thịt bò trên mặt chảo cho thịt hơi xém cạnh thì lật mặt.', 10);
INSERT INTO public.recipe_steps VALUES (1880, '2025-11-20 17:10:30.567282', '2025-11-20 17:10:30.567282', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 306, 3, 'Đun nước sôi chần qua rau cải chíp và hành tây để khi xào rau nhanh ngấm gia vị và không bị đổi màu.', 10);
INSERT INTO public.recipe_steps VALUES (1881, '2025-11-20 17:10:30.568601', '2025-11-20 17:10:30.568601', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 306, 7, 'Cho tiếp dầu vào chảo, phi thơm tỏi và cho rau cải, hành tây và cà chua vào xào, cho thêm một chút bột nêm. Cho tiếp nước sốt vào đảo đều cho ra đĩa riêng.', 10);
INSERT INTO public.recipe_steps VALUES (1882, '2025-11-20 17:10:30.79583', '2025-11-20 17:10:30.79583', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 307, 2, 'Miến ngâm mềm, cắt ngắn, để ráo nước. Hành hoa cắt ngắn 3cm.', 10);
INSERT INTO public.recipe_steps VALUES (1883, '2025-11-20 17:10:30.796891', '2025-11-20 17:10:30.796891', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 307, 5, 'Mộc nhĩ ngâm nở rửa sạch thái chỉ.', 10);
INSERT INTO public.recipe_steps VALUES (1884, '2025-11-20 17:10:30.798506', '2025-11-20 17:10:30.798506', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 307, 6, 'Phi thơm hành khô, cho trứng đảo qua, cho miến vào xào săn. Cho lươn, giá đỗ, hành hoa, mộc nhĩ nêm vừa ăn, rắc hạt tiêu.', 10);
INSERT INTO public.recipe_steps VALUES (1885, '2025-11-20 17:10:30.800095', '2025-11-20 17:10:30.800095', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 307, 7, 'Bày đĩa rắc rau mùi ăn nóng. Ăn kèm tương ớt, chanh quả.', 10);
INSERT INTO public.recipe_steps VALUES (1886, '2025-11-20 17:10:30.802369', '2025-11-20 17:10:30.802369', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 307, 3, 'Giá đỗ rửa sạch để riêng, hành khô thái mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (1887, '2025-11-20 17:10:30.803976', '2025-11-20 17:10:30.803976', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 307, 1, 'Lươn sơ chế sạch, mổ bỏ ruột, thái vát nhỏ, ướp gia vị, mì chính, hạt tiêu để 10 phút, sau đó xào chín xém cạnh để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (1888, '2025-11-20 17:10:30.806129', '2025-11-20 17:10:30.806129', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 307, 4, 'Trứng đập ra bát đánh nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (1889, '2025-11-20 17:10:30.877617', '2025-11-20 17:10:30.877617', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 308, 1, 'Thịt loại bỏ bạc nhạc, rửa sạch, cắt miếng vuông mỗi chiều 2-3 cm, ướp với mắm, hạt tiêu, tỏi (băm nhỏ), muối, đường và ít mỡ nước.', 10);
INSERT INTO public.recipe_steps VALUES (1890, '2025-11-20 17:10:30.879326', '2025-11-20 17:10:30.879326', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 308, 4, 'Nhắc nhỏ: Bạn nên xào thịt bò từng ít một để thịt mềm, không bị dai, khô.', 10);
INSERT INTO public.recipe_steps VALUES (1891, '2025-11-20 17:10:30.880929', '2025-11-20 17:10:30.880929', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 308, 3, 'Lúc chuẩn bị ăn, bắc chảo mỡ lên bếp đun thật nóng, cho tỏi đã băm nhỏ vào phi thơm, cho thêm ít đường, bỏ một phần thịt vào đảo đều tay. Thịt vừa tái, nhắc chảo xuống, trút thịt lên đĩa rau xà lách. Tiếp tục xào lượt khác.', 10);
INSERT INTO public.recipe_steps VALUES (1892, '2025-11-20 17:10:30.882531', '2025-11-20 17:10:30.882531', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 308, 5, 'Món này ăn nóng chấm với muối, hạt tiêu.', 10);
INSERT INTO public.recipe_steps VALUES (1893, '2025-11-20 17:10:30.884086', '2025-11-20 17:10:30.884086', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 308, 2, 'Hành củ bóc vỏ, thái lát dầy, ngâm vào giấm, đường, hạt tiêu. Rau xà lách nhặt rửa sạch, để ráo, bày ra đĩa. Múc hành ngâm giấm rưới lên rau.', 10);
INSERT INTO public.recipe_steps VALUES (1894, '2025-11-20 17:10:31.073233', '2025-11-20 17:10:31.073233', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 309, 6, 'Trải lá trứng trên thớt hoặc khay, dàn một lớp giò mỏng đều, xếp nấm hương mộc nhĩ lên trên, phết một chút giò lên nấm hương, mộc nhĩ. Lá trứng thứ hai làm tương tự.', 10);
INSERT INTO public.recipe_steps VALUES (1895, '2025-11-20 17:10:31.074829', '2025-11-20 17:10:31.074829', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 309, 1, 'Đập trứng ra bát, tách riêng lòng đỏ, lòng trắng, đánh tan.', 10);
INSERT INTO public.recipe_steps VALUES (1896, '2025-11-20 17:10:31.077285', '2025-11-20 17:10:31.077285', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 309, 4, 'Nấm hương ngâm nở, rửa sạch cắt bỏ chân, để ráo nước (cánh nấm dầy quả thì lạng mỏng bớt).', 10);
INSERT INTO public.recipe_steps VALUES (1897, '2025-11-20 17:10:31.079406', '2025-11-20 17:10:31.079406', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 309, 8, 'Trứng chín lấy ra để nguội, tháo bỏ dây, giấy, thái khoanh dầy khoảng 0,8 – 1cm, bầy vào đĩa trang trí rau mùi (có thể bày thêm các loại hoa được tỉa từ cà chua, cà rốt, dưa chuột).', 10);
INSERT INTO public.recipe_steps VALUES (1898, '2025-11-20 17:10:31.082273', '2025-11-20 17:10:31.082273', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 309, 3, 'Giò tôm thúc nước mắm, hạt tiêu, mì chính ( nếu giò sống chỉ trộn mì chính, hạt tiêu).', 10);
INSERT INTO public.recipe_steps VALUES (1899, '2025-11-20 17:10:31.084387', '2025-11-20 17:10:31.084387', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 309, 7, 'Đặt hai lá trứng so le nhau rồi cuộn tròn lại, dùng giấy trắng hoặc lá chuối cuốn bên ngoài và dùng dây buộc xung quanh. Đem hấp chín, thời gian khoảng 20 phút.', 10);
INSERT INTO public.recipe_steps VALUES (1900, '2025-11-20 17:10:31.086639', '2025-11-20 17:10:31.086639', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 309, 5, 'Mộc nhĩ ngâm nở, rửa sạch, cánh nhỏ để nguyên, cánh to cắt làm 2 hay 3.', 10);
INSERT INTO public.recipe_steps VALUES (1901, '2025-11-20 17:10:31.088818', '2025-11-20 17:10:31.088818', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 309, 2, 'Bắc chảo lên bếp, xoa một lớp mỡ mỏng cho khỏi dính, đổ trứng vào tráng mỏng vừa (tráng riêng lòng đỏ, lòng trắng).', 10);
INSERT INTO public.recipe_steps VALUES (1902, '2025-11-20 17:10:31.314795', '2025-11-20 17:10:31.314795', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 310, 1, 'Chần qua nấm tươi bằng nước nóng, để nguyên cây không cắt.', 10);
INSERT INTO public.recipe_steps VALUES (1903, '2025-11-20 17:10:31.316373', '2025-11-20 17:10:31.316373', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 310, 4, 'Sau đó, lấy miến đã luộc trộn với dầu vừng rồi trộn tất cả các nguyên liệu đã sơ chế trên cùng với miến, cho miến vào đĩa và cuối cùng rắc vừng lên, thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (1904, '2025-11-20 17:10:31.318516', '2025-11-20 17:10:31.318516', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 310, 2, 'Luộc miến: Cho miến vào nước cùng với nước tương và dầu đậu nành, đun sôi nước. Sau đó, vớt miến ra rửa sạch bằng nước lạnh cho hết dầu.', 10);
INSERT INTO public.recipe_steps VALUES (1905, '2025-11-20 17:10:31.32014', '2025-11-20 17:10:31.32014', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 310, 3, 'Cắt rau cải khoảng 6 cm chần qua nước sôi. Trứng tráng mỏng, cuộn lại và thái nhỏ. Xé mỏng thịt cua chay.', 10);
INSERT INTO public.recipe_steps VALUES (1906, '2025-11-20 17:10:31.44342', '2025-11-20 17:10:31.44342', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 311, 1, 'Thịt lợn rửa sạch, xắt miếng vừa ăn, ướp với hạt nêm, đường, hành khô, nước màu.', 10);
INSERT INTO public.recipe_steps VALUES (1907, '2025-11-20 17:10:31.445023', '2025-11-20 17:10:31.445023', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 311, 2, 'Dừa gọt vỏ, rửa sạch, xắt lát mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (1908, '2025-11-20 17:10:31.446604', '2025-11-20 17:10:31.446604', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 311, 3, 'Thịt heo rang cháy cạnh, nêm nước mắm, 1/2 chén con nước lạnh vào đun nhỏ lửa, gần cạn cho dừa vào đảo đều, kho thêm 5 phút. Trang trí với ớt xắt lát.', 10);
INSERT INTO public.recipe_steps VALUES (1909, '2025-11-20 17:10:31.695642', '2025-11-20 17:10:31.695642', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 312, 1, 'Phi thơm tỏi và hành tím, ớt khô.', 10);
INSERT INTO public.recipe_steps VALUES (1910, '2025-11-20 17:10:31.697758', '2025-11-20 17:10:31.697758', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 312, 2, 'Cho tôm và gia vị, tương ớt, hắc xì dầu vào xào nhanh tay. Cho tiếp tương ớt vào xào nhanh.', 10);
INSERT INTO public.recipe_steps VALUES (1911, '2025-11-20 17:10:31.69987', '2025-11-20 17:10:31.69987', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 312, 3, 'Tắt bếp, cho hành lá vào.', 10);
INSERT INTO public.recipe_steps VALUES (1912, '2025-11-20 17:10:31.701987', '2025-11-20 17:10:31.701987', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 312, 4, 'Cho tôm ra đĩa, trang trí ngò, ớt tỉa hoa…', 10);
INSERT INTO public.recipe_steps VALUES (1913, '2025-11-20 17:10:31.858319', '2025-11-20 17:10:31.858319', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 313, 1, 'Thịt lợn thái miếng nhỏ vừa ăn, ướp với nước mắm. Hành khô băm nhỏ. Giá đỗ rửa sạch; ớt chuông đỏ bỏ cuống, bổ dọc, bỏ hạt, thái sợi. Hành lá nhặt rửa sạch, cắt đoạn dài.', 10);
INSERT INTO public.recipe_steps VALUES (1914, '2025-11-20 17:10:31.860386', '2025-11-20 17:10:31.860386', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 313, 2, 'Cho dầu ăn vào chảo đun nóng, phi thơm hành, đổ thịt vào xào chín, xúc để riêng. Cho dầu ăn vào chảo, đổ ớt chuông đỏ vào đảo trước, sau đó cho giá vào đảo nhanh tay và trút thịt lợn vào cùng đảo nhanh. Cho hành lá vào, nêm thêm gia vị vừa ăn rồi tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (1915, '2025-11-20 17:10:32.102002', '2025-11-20 17:10:32.102002', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 314, 4, 'Nấu xôi bằng nồi cơm điện:Cho gạo nếp vào nồi cơm điện, dàn đều và cho đủ lượng nước xâm xấp (hoặc ít hơn hạt gạo một chút), thêm 2 thìa cà phê mỡ gà rồi bật chế độ như nấu cơm bình thường. Khi nồi cơm điện bật sang chế độ warm (hâm nóng) thì đùng đũa xới đều nhẹ nhàng. Tiếp tục đậy nồi thêm 15 - 20 phút để xôi chín dẻo mềm, tơi hạt.', 10);
INSERT INTO public.recipe_steps VALUES (1916, '2025-11-20 17:10:32.103828', '2025-11-20 17:10:32.103828', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 314, 5, 'Trình bày và thưởng thức:Múc xôi ra đĩa, dùng dao cắt lát mỏng đậu xanh đặt lên trên, rưới thêm chút mỡ hành, rắc thêm hành phi, ruốc (chà bông) lên trên là có ngay món xôi xéo dẻo thơm.', 10);
INSERT INTO public.recipe_steps VALUES (1917, '2025-11-20 17:10:32.107018', '2025-11-20 17:10:32.107018', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 314, 1, 'Nấu đỗ xanh:Đỗ nhặt bỏ hạt lép, rửa sạch, ngâm tối thiểu 3 giờ rồi cho vào nồi cơm điện cùng lượng nước xâm xấp và bật nấu bình thường. Khi đỗ chín, ráo nước thì dùng muôi (vá) cơm miết tán mịn, để nguội và đeo găng tay nắm tròn lại để khi ăn thát lát mỏng lên xôi xéo.', 10);
INSERT INTO public.recipe_steps VALUES (1918, '2025-11-20 17:10:32.108614', '2025-11-20 17:10:32.108614', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 314, 6, 'Yêu cầu thành phẩm:Hạt xôi dẻo mềm, vàng ươm, bóng mượt quyện với đậu xanh mịn màng bùi bùi cùng hành phi giòn rụm, béo ngậy rất hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (1919, '2025-11-20 17:10:32.109665', '2025-11-20 17:10:32.109665', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 314, 3, 'Ngâm gạo nếp:Gạo nếp vo sạch, cho nước xâm xấp và nước cốt nghệ tươi giã (hoặc 1 thìa cà phê bột nghệ) ngâm ít nhất 6 tiếng. Sau đó, rửa sơ/đãi sơ nhẹ tay (để bớt mùi hăng của nghệ), để ráo nước, xóc cùng 1 thìa cà phê muối tinh.', 10);
INSERT INTO public.recipe_steps VALUES (1920, '2025-11-20 17:10:32.111761', '2025-11-20 17:10:32.111761', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 314, 2, 'Làm hành phi(nên làm sẵn nhiều và dự trữ trong hũ thủy tinh dùng dần): Hành bóc vỏ, cho vào ngăn đá tủ lạnh 30 phút (hoặc ngăn mát 2 tiếng) để giúp không bị cay mắt khi thái hành, chú ý thái đều tay. Trước khi chiên hành thì thêm vài giọt nước cốt chanh cùng chút muối giúp hành rút nước nhanh, giòn hơn. Cần thử độ nóng của dầu (sủi tăm đầu đũa là đạt) mới cho hành vào, trong khi chiên thì đảo đều tay để hành chín đều. Quan trọng nhất là canh thời điểm hành đạt: hành chiên se lại, hơi ngả vàng thì tắt bếp, vớt nhanh ra để vào giấy thấm dầu, dàn đều. Khi nguội, hành sẽ vàng và giòn rụm.', 10);
INSERT INTO public.recipe_steps VALUES (1921, '2025-11-20 17:10:32.308844', '2025-11-20 17:10:32.308844', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 315, 2, 'Đun mỡ nóng già rồi phi thơm hành, cho mực vào chiên vàng, sau đó gạn bớt mỡ nêm mắm, đường, gừng, ớt, hạt tiêu đảo đều, xúc ra để riêng. Thịt lợn, thịt gà, giò lụa thái chỉ xào săn. Trứng tráng mỏng, thái chỉ. Đậu Hà Lan, củ đậu, su hào, nấm hương thái chỉ xào săn.', 10);
INSERT INTO public.recipe_steps VALUES (1922, '2025-11-20 17:10:32.310428', '2025-11-20 17:10:32.310428', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 315, 3, 'Đun mỡ nóng già, phi thơm hành, cho su hào, củ đậu, đậu Hà Lan, cà rốt, nấm hương xào chín tới, nêm gia vị, mì chính vừa ăn, trút thịt gà, mực, thịt lợn, giò lụa, trứng gà vào đảo đều, cho hành hoa bắc cuống. Xúc ra bày ra đĩa, trên bày rau mùi ăn nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1923, '2025-11-20 17:10:32.312098', '2025-11-20 17:10:32.312098', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 315, 1, 'Mực ngâm nước lạnh khoảng 4 giờ cho mềm, bóc vỏ màng, da, rửa sạch bóp kỹ với gừng, rượu, vớt để ráo, lạng mỏng, thái chỉ.', 10);
INSERT INTO public.recipe_steps VALUES (1924, '2025-11-20 17:10:32.524017', '2025-11-20 17:10:32.524017', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 316, 1, 'Cá chép đánh vẩy mổ bụng rửa sạch cho hết nhớt sau đó khía vảy rồng tẩm ướp tiêu muối mì chính để 10 phút cho ngấm.', 10);
INSERT INTO public.recipe_steps VALUES (1925, '2025-11-20 17:10:32.52508', '2025-11-20 17:10:32.52508', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 316, 3, 'Cho dầu ăn vào chảo phi thơm tỏi, cho dưa vào xào săn và cho các loại gia vị ở trên vào. Tiếp đó cho nước dùng om cho dưa chín mềm, sau đó cho cá chép đã chao qua dầu vào và om đến khi cá chín, nêm lại vị chua mặn vừa ăn, cho hành, thì là vào bầy ra đĩa trang trí.', 10);
INSERT INTO public.recipe_steps VALUES (1926, '2025-11-20 17:10:32.526136', '2025-11-20 17:10:32.526136', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 316, 2, 'Dưa chua vắt ráo nước (nước dưa để nấu sau cùng), tỏi củ băm nhỏ vừa, hành thì là cắt khúc 4 cm, ớt quả tỉa hoa, 1 quả thái lát, cà chua bổ cau.', 10);
INSERT INTO public.recipe_steps VALUES (1927, '2025-11-20 17:10:32.766146', '2025-11-20 17:10:32.766146', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 317, 4, 'Nấm hộp để nguyên.', 10);
INSERT INTO public.recipe_steps VALUES (1928, '2025-11-20 17:10:32.767709', '2025-11-20 17:10:32.767709', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 317, 1, 'Bò lọc bỏ gân xơ, lạng mỏng to bản, dần mềm, ướp gia vị, mì chính, hạt tiêu, hành tỏi khô, gừng, rồi cuộn tròn lấy dây lạt buộc chặt. Sau đó rán qua, cho vào xoong chế nước dùng ngập thịt đun nhỏ lửa, nêm vừa ăn, hơi ngọt.', 10);
INSERT INTO public.recipe_steps VALUES (1929, '2025-11-20 17:10:32.769261', '2025-11-20 17:10:32.769261', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 317, 2, 'Cà chua thái nhỏ xào mềm chế vào xoong nước dùng. Cà rốt thái hạt lựu để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (1932, '2025-11-20 17:10:32.774466', '2025-11-20 17:10:32.774466', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 317, 6, 'Phi thơm hành tỏi khô, cho cà rốt, khoai tây, nấm xào qua, cho nước hầm bò, sốt tiêu nêm lại sau đó xuống chút bột đao hơi sánh, múc dội lên đĩa bò ăn nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1933, '2025-11-20 17:10:32.886094', '2025-11-20 17:10:32.886094', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 318, 1, 'Sơ chế cá:Cá quả đánh sạch vẩy, bóc mang, mổ bụng, chà xát muối hạt và chanh rửa sạch nhớt khử tanh, để ráo nước. Dùng dao sắc lạng dọc xương sống để lọc lấy thịt, thái miếng vừa ăn, ướp thịt cá với 2 thìa canh mẻ đã lọc, 1 thìa canh mắm tôm, 1 thìa cà phê muối, 1 thìa canh nước nghệ (nghệ tươi giã nhuyễn, thêm nước vắt lấy lấy nước cốt, một phần ướp cá, phần còn lại xào chuối để lên màu đẹp), ớt (nếu ăn được cay) và hành khô băm nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (1934, '2025-11-20 17:10:32.887694', '2025-11-20 17:10:32.887694', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 318, 2, 'Làm viên cá:Phần đầu và xương còn lại thì dùng dao băm kỹ. Cách băm: Dùng thớt gỗ mặt rộng, chắc và dùng dao nặng, dày sống dần mềm đầu và xương cá rồi băm nhanh tay. Khi cá hơi nhuyễn thì thêm rau răm, lá lốt, hành khô, ớt (nếu nhà có trẻ nhỏ nên bỏ ớt) cùng chút bột canh, hạt nêm, hạt tiêu. Băm cho tới khi trở thành hỗn hợp nhuyễn thì thêm chút mỡ hoặc dầu ăn trộn đều để kết dính, nhuyễn dẻo hơn rồi vo viên tròn như quả táo ta nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (1935, '2025-11-20 17:10:32.889296', '2025-11-20 17:10:32.889296', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 318, 5, 'Nấu cá:Cho nước đủ lượng ăn vào nồi nấu sôi, thêm cá và tai chua vào trước nấu một lúc, sau đó cho chuối xanh vào để chuối ngấm nước cá nhiều sẽ ngon hơn. Nêm nếm mắm muối, vị chua vừa vị. Với món ăn này, vị chua càng đậm thì càng ngon. Khi chuối chín mềm thì món ăn đã hoàn thành, thêm chút rau răm, hành hoa, lá lốt, tía tô thái rối, đảo nhẹ rồi múc ra bát tô.', 10);
INSERT INTO public.recipe_steps VALUES (1936, '2025-11-20 17:10:32.890874', '2025-11-20 17:10:32.890874', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 318, 3, 'Sơ chế chuối xanhgọt vỏ, cắt khúc 3 - 4 cm rồi bổ làm tư, ngâm nước muối loãng để không bị thâm và hết nhựa, rửa sạch. Nếu cầu kỳ thì xào sơ chuối với chút nước nghệ tươi và mẻ, mắm tôm cho đậm vị và lấy màu vàng ươm, múc ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (1937, '2025-11-20 17:10:32.892461', '2025-11-20 17:10:32.892461', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 318, 4, 'Chiên cá miếng và cá viên: Phi thơm hành khô với mỡ lợn cho dậy mùi thơm, rồi cho cá miếng và cá viên và rán. Chú ý lật trở các mặt khéo léo để cá không bị vỡ, nát. Gắp ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (1938, '2025-11-20 17:10:32.894073', '2025-11-20 17:10:32.894073', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 318, 6, 'Thành phẩm: Cá quả nấu ám màu vàng sóng sánh, thịt cá dai ngọt tự nhiên, cá viên đậm vị, chuối mềm bùi, vị chua cay mặn chát kết hợp hài hòa tròn vị, rất dễ ăn với mọi lứa tuổi. Món này ăn cùng cơm trắng hay bún đều rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (1939, '2025-11-20 17:10:33.066832', '2025-11-20 17:10:33.066832', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 319, 1, 'Măng thái chỉ, luộc qua nước sôi, vớt ra rửa sạch, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (1940, '2025-11-20 17:10:33.068225', '2025-11-20 17:10:33.068225', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 319, 4, 'Pha đường, nước mắm, ớt, tỏi cho vừa ăn trộn vào măng và thịt lợn, nêm vừa cho tiếp lạc và lá chanh thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (1941, '2025-11-20 17:10:33.06985', '2025-11-20 17:10:33.06985', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 319, 2, 'Thịt ba chỉ luộc chín, thái chỉ.', 10);
INSERT INTO public.recipe_steps VALUES (1942, '2025-11-20 17:10:33.071519', '2025-11-20 17:10:33.071519', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 319, 3, 'Vừng, lạc rang vàng, giã nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (1943, '2025-11-20 17:10:33.345612', '2025-11-20 17:10:33.345612', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 320, 4, 'Pha nước muối sao cho hơi mặn, đổ ngập cải, lấy đồ nặng dằn lên. Thường tối ngâm sáng xả nước để ráo là vừa.', 10);
INSERT INTO public.recipe_steps VALUES (1944, '2025-11-20 17:10:33.347212', '2025-11-20 17:10:33.347212', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 320, 2, 'Củ cải bào sợi cho vào thau nước muối luôn.', 10);
INSERT INTO public.recipe_steps VALUES (1945, '2025-11-20 17:10:33.349931', '2025-11-20 17:10:33.349931', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 320, 5, 'Cải sau khi ngâm qua vớt ra xả sơ bằng nước lạnh rồi để vào rổ cho thật ráo nước. (Bạn nhớ đừng vắt vì như thế cải mềm sẽ không ngon)', 10);
INSERT INTO public.recipe_steps VALUES (1946, '2025-11-20 17:10:33.35208', '2025-11-20 17:10:33.35208', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 320, 6, 'Nước gừng + nước tỏi (hoặc tỏi xay) + nước mắm + đường + bột ngọt pha làm sao nếm ngon và dậy mùi thơm.', 10);
INSERT INTO public.recipe_steps VALUES (1947, '2025-11-20 17:10:33.354208', '2025-11-20 17:10:33.354208', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 320, 8, 'Cho hành, gừng thái sợi và củ cải thái sợi vào trộn, sau đó, trộn tất cả các gia vị đó vào từng tép cải cho đều. Cuối cùng, lấy giấy foil bao kín lại để ở ngoài một đêm rồi cho vào tủ lạnh ăn dần.', 10);
INSERT INTO public.recipe_steps VALUES (1948, '2025-11-20 17:10:33.356302', '2025-11-20 17:10:33.356302', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 320, 1, 'Hành lá rửa sạch, đầu hành thái sợi hoặc cắt khúc nhỏ đập dập, lá cho vào nước muối ngâm cải tối hôm trước', 10);
INSERT INTO public.recipe_steps VALUES (1949, '2025-11-20 17:10:33.357884', '2025-11-20 17:10:33.357884', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 320, 7, 'Sau khi nêm nếm nước pha vừa miệng, cho 1 muỗng canh dầu mè và 1 muỗng hạt mè vào trộn đều rồi cho 3 muỗng ớt màu của Korean vào (tùy theo ý thích ăn cay nhiều hay ít mà bạn cho ớt này).', 10);
INSERT INTO public.recipe_steps VALUES (1950, '2025-11-20 17:10:33.358937', '2025-11-20 17:10:33.358937', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 320, 3, 'Hành lá, củ cải thái sợi sau khi ngâm sơ nuớc muối đem xả lại bằng nước lạnh rồi vắt khô.', 10);
INSERT INTO public.recipe_steps VALUES (1951, '2025-11-20 17:10:33.646134', '2025-11-20 17:10:33.646134', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 321, 3, 'Xào tỏi bằm cho thơm, thêm thịt bò cho vừa chín, để qua một bên', 10);
INSERT INTO public.recipe_steps VALUES (1952, '2025-11-20 17:10:33.647722', '2025-11-20 17:10:33.647722', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 321, 7, 'Món này dùng nóng với nước tương và ớt.', 10);
INSERT INTO public.recipe_steps VALUES (1953, '2025-11-20 17:10:33.649314', '2025-11-20 17:10:33.649314', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 321, 4, 'Xào hành tây cho thơm, thêm cà chua, khoai tây vào xào đều, nêm với phần hạt nêm còn lại cho vừa ăn', 10);
INSERT INTO public.recipe_steps VALUES (1954, '2025-11-20 17:10:33.650902', '2025-11-20 17:10:33.650902', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 321, 1, 'Ướp thịt bò với 1/2 muỗng cà phê hạt nêm, tiêu xay và dầu ăn', 10);
INSERT INTO public.recipe_steps VALUES (1955, '2025-11-20 17:10:33.651948', '2025-11-20 17:10:33.651948', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 321, 5, 'Cho tiếp thịt bò vào chảo, xào đều cho tất cả nguyên liệu thấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (1956, '2025-11-20 17:10:33.652955', '2025-11-20 17:10:33.652955', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 321, 2, 'Chiên vàng khoai tây, vớt khoai tây ra khỏi chảo, để ráo dầu ăn', 10);
INSERT INTO public.recipe_steps VALUES (1957, '2025-11-20 17:10:33.655175', '2025-11-20 17:10:33.655175', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 321, 6, 'Múc thịt bò xào khoai tây vào đĩa, rắc ít tiêu xay lên trên và trang trí với tiêu ngò rí.', 10);
INSERT INTO public.recipe_steps VALUES (1958, '2025-11-20 17:10:33.944296', '2025-11-20 17:10:33.944296', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 322, 1, 'Trứng muối luộc chín lấy lòng đỏ bỏ lòng trắng nghiền nhỏ rồi trộn với gia vị, hạt tiêu, hành khô băm nhỏ, dầu ớt (ớt băm nhỏ) để riêng. Bột cà mỳ cho ra khay.', 10);
INSERT INTO public.recipe_steps VALUES (1959, '2025-11-20 17:10:33.945346', '2025-11-20 17:10:33.945346', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 322, 4, 'Phi thơm hành khô, cho hỗn hợp trứng muối xào thơm dội lên trên đĩa đậu chiên. Ăn nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1960, '2025-11-20 17:10:33.946967', '2025-11-20 17:10:33.946967', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 322, 2, 'Các loại rau rửa sạch. Bột mì hoà một chút nước sánh đặc. Sau đó cho trứng gà đánh nhuyễn (sánh như cháo đặc).', 10);
INSERT INTO public.recipe_steps VALUES (1961, '2025-11-20 17:10:33.948574', '2025-11-20 17:10:33.948574', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 322, 3, 'Đậu khay (đậu phụ) thái miếng vuông (khoảng 2 x 2 cm) trộn đều nhẹ tay với bột mỳ. Nhặt từng miếng lăn vào bột cà mỳ rán vàng bày ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (1962, '2025-11-20 17:10:34.147252', '2025-11-20 17:10:34.147252', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 323, 4, 'Rau kinh giới nhặt rửa sạch, vừng trắng rang vàng giã dập.', 10);
INSERT INTO public.recipe_steps VALUES (1963, '2025-11-20 17:10:34.148846', '2025-11-20 17:10:34.148846', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 323, 5, 'Bì lợn luộc chín thái sợi ( hoặc dùng nem chạo).', 10);
INSERT INTO public.recipe_steps VALUES (1964, '2025-11-20 17:10:34.150483', '2025-11-20 17:10:34.150483', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 323, 6, 'Pha chanh, đường, tỏi ớt, nước mắm cho vừa ăn rồi trộn lẫn rau muống, rau rút, giá đỗ với với nhau, sau đó, cho nem chạo, vừng rang bày ra đĩa, cho rau kinh giới lên trên.', 10);
INSERT INTO public.recipe_steps VALUES (1965, '2025-11-20 17:10:34.152106', '2025-11-20 17:10:34.152106', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 323, 2, 'Rau rút nhặt sạch, cắt bằng rau muống, chần qua.', 10);
INSERT INTO public.recipe_steps VALUES (1966, '2025-11-20 17:10:34.153945', '2025-11-20 17:10:34.153945', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 323, 3, 'Giá đỗ nhặt rửa sạch, chần qua.', 10);
INSERT INTO public.recipe_steps VALUES (1967, '2025-11-20 17:10:34.155529', '2025-11-20 17:10:34.155529', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 323, 1, 'Rau muống ngắt bỏ lá, để nguyên hoặc chẻ dọc làm đôi, cắt khúc ngắn khoảng 6 cm rồi chần qua.', 10);
INSERT INTO public.recipe_steps VALUES (1968, '2025-11-20 17:10:34.206193', '2025-11-20 17:10:34.206193', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 324, 1, 'Bí xanh gọt vỏ, bỏ ruột, thái miếng hoặc thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (1969, '2025-11-20 17:10:34.207864', '2025-11-20 17:10:34.207864', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 324, 2, 'Tôm nõn khô rửa sạch, ngâm nước ấm khoảng 10 phút vớt ra giã dập với 1 chút gừng.', 10);
INSERT INTO public.recipe_steps VALUES (1970, '2025-11-20 17:10:34.210053', '2025-11-20 17:10:34.210053', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 324, 4, 'Cho bí xanh đun cho bí chín tới là được rắc một chút hành hoa thái nhỏ. Ăn nóng với cơm.', 10);
INSERT INTO public.recipe_steps VALUES (1971, '2025-11-20 17:10:34.212499', '2025-11-20 17:10:34.212499', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 324, 3, 'Nước ngâm tôm gạn lấy nước trong cho tôm vào đun nhỏ lửa khoảng 10 phút nêm nước mắm mỳ chính vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1972, '2025-11-20 17:10:34.362078', '2025-11-20 17:10:34.362078', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 325, 2, 'Đun sôi nước và cho lòng vào trần qua rồi vuốt cho bớt phần bột bên trong, cắt khúc 3 cm.', 10);
INSERT INTO public.recipe_steps VALUES (1973, '2025-11-20 17:10:34.363255', '2025-11-20 17:10:34.363255', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 325, 1, 'Lòng non rửa sạch bằng dấm, muối sau đó rửa lại nhiều lần bằng nước sạch.', 10);
INSERT INTO public.recipe_steps VALUES (1974, '2025-11-20 17:10:34.364838', '2025-11-20 17:10:34.364838', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 325, 3, 'Dưa chua vắt khô nước (nếu mặn rửa qua)', 10);
INSERT INTO public.recipe_steps VALUES (1975, '2025-11-20 17:10:34.365877', '2025-11-20 17:10:34.365877', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 325, 4, 'Cho dầu vào chảo phi thơm tỏi rồi đổ dưa vào xào săn, sau đó nêm gia vị và tiếp tục cho lòng vào xào gần chín thì thêm tiết, hành, răm vào. Cuối cùng, bắc nồi ra, đổ vào đĩa, rắc chút hạt tiêu, ăn nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1976, '2025-11-20 17:10:34.491586', '2025-11-20 17:10:34.491586', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 326, 4, 'Bột cà mỳ, đỗ xanh, gạo nếp, hạt tiêu xay, tôm khô, muối trộn đều để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (1977, '2025-11-20 17:10:34.493144', '2025-11-20 17:10:34.493144', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 326, 3, 'Đun dầu nóng già cho gà đã ướp rán chín xém cạnh để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (1978, '2025-11-20 17:10:34.494732', '2025-11-20 17:10:34.494732', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 326, 5, 'Phi thơm hành tỏi khô, cho gà đã rán vào xào thơm, đổ hỗn hợp bột vào chảo gà đảo đều, sau đó xúc bày ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (1979, '2025-11-20 17:10:34.496957', '2025-11-20 17:10:34.496957', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 326, 2, 'Bột cà mỳ (cháo ăn liền) lọc lấy cánh nhỏ. Hạt tiêu rang thơm xay nhỏ, tôm khô rang thơm giã hoặc xay nhỏ. Muối tinh rang khô.', 10);
INSERT INTO public.recipe_steps VALUES (1980, '2025-11-20 17:10:34.499097', '2025-11-20 17:10:34.499097', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 326, 1, 'Gà chặt miếng bằng bao diêm, ướp gia vị, mì chính, hạt tiêu, hành khô băm nhỏ. Gạo nếp, đỗ xanh rang thơm rồi xay nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (1981, '2025-11-20 17:10:34.672261', '2025-11-20 17:10:34.672261', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 327, 2, 'Hành tây lột vỏ, xắt mỏng, ngâm nước đá 5 - 10 phút để làm giảm độ hăng', 10);
INSERT INTO public.recipe_steps VALUES (1982, '2025-11-20 17:10:34.674417', '2025-11-20 17:10:34.674417', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 327, 4, 'Chanh vắt lấy nước cốt', 10);
INSERT INTO public.recipe_steps VALUES (1983, '2025-11-20 17:10:34.676001', '2025-11-20 17:10:34.676001', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 327, 6, 'Trộn ớt chuông xanh, đỏ, vàng, hành tây, thịt gà xé, rưới hỗn hợp sốt mayonaise lên, trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (1984, '2025-11-20 17:10:34.678173', '2025-11-20 17:10:34.678173', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 327, 3, 'Ớt chuông xanh, đỏ, vàng, bỏ hột, xắt mỏng, ngâm nước đá', 10);
INSERT INTO public.recipe_steps VALUES (1985, '2025-11-20 17:10:34.679921', '2025-11-20 17:10:34.679921', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 327, 5, 'Trộn mayonaise, nước cốt tỏi, nước chanh, đường, cho vào tủ lạnh từ 5 - 10 phút.', 10);
INSERT INTO public.recipe_steps VALUES (1986, '2025-11-20 17:10:34.68206', '2025-11-20 17:10:34.68206', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 327, 1, 'Thịt ức gà rửa sạch, luộc trong nước sôi có ít muối cho thịt gà vừa chín, vớt ra để nguội xé miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (1987, '2025-11-20 17:10:34.750576', '2025-11-20 17:10:34.750576', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 328, 27, 'Cho ếch vào thố, khi gần đến bữa ăn, bạn cho nồi lên bếp đun sôi với lửa liu riu để nước mắm sệt lại. Sau đó, rắc 1 thìa cà phê tiêu lên mặt.', 10);
INSERT INTO public.recipe_steps VALUES (1988, '2025-11-20 17:10:34.752173', '2025-11-20 17:10:34.752173', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 328, 13, 'Đổ 1 lít nước mẻ vào nồi, nấu sôi. Sau đó cho thịt ếch và cà chua vào, nêm 1 thìa súp nước mắm, 1 thìa súp hạt nêm, 1 thìa cà phê đường, đun sôi một lúc. Tắt bếp, cho hành và thì là vào. Bạn có thể rắc một chút tiêu lên cho thơm.', 10);
INSERT INTO public.recipe_steps VALUES (1989, '2025-11-20 17:10:34.753766', '2025-11-20 17:10:34.753766', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 328, 26, 'Cho chảo lên bếp, cho 1 thìa súp dầu ăn vào, dầu sôi, cho 1/2 thìa cà phê tỏi băm vào phi thơm. Sau đó cho ếch vào, đảo sơ qua để thịt ếch săn. Rắc ớt khô lên, đảo đều.', 10);
INSERT INTO public.recipe_steps VALUES (1991, '2025-11-20 17:10:34.756523', '2025-11-20 17:10:34.756523', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 328, 25, 'Ướp thịt ếch trong 20 phút, thỉnh thoảng dùng đũa đảo đều nhiều lần để thịt ếch ngấm đều gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (1992, '2025-11-20 17:10:34.75807', '2025-11-20 17:10:34.75807', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 328, 20, 'Trước khi ăn nên trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (1993, '2025-11-20 17:10:34.759626', '2025-11-20 17:10:34.759626', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 328, 28, 'Lưu ý: Bạn có thể tăng giảm gia vị sao cho phù hợp với khẩu vị của mình.', 10);
INSERT INTO public.recipe_steps VALUES (1994, '2025-11-20 17:10:34.760633', '2025-11-20 17:10:34.760633', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 328, 29, 'Dùng nóng với cơm.', 10);
INSERT INTO public.recipe_steps VALUES (1995, '2025-11-20 17:10:34.761631', '2025-11-20 17:10:34.761631', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 328, 23, 'Cách làm:Thịt ếch rửa sạch, để ráo, chặt miếng vừa ăn. Ớt khô ngâm nước ấm, ớt nở, vớt ra để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (1996, '2025-11-20 17:10:34.763705', '2025-11-20 17:10:34.763705', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 328, 7, 'Dọn món ăn ra đĩa, rắc 1/2 thìa cà phê tiêu lên bề mặt cho thơm.', 10);
INSERT INTO public.recipe_steps VALUES (1997, '2025-11-20 17:10:34.765447', '2025-11-20 17:10:34.765447', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 328, 5, 'Cho chảo lên bếp, chảo nóng, đổ dầu vào. Dầu sôi, cho hành và tỏi băm vào phi thơm.', 10);
INSERT INTO public.recipe_steps VALUES (1998, '2025-11-20 17:10:34.767076', '2025-11-20 17:10:34.767076', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 328, 14, 'Múc canh ra tô, dùng nóng.', 10);
INSERT INTO public.recipe_steps VALUES (1999, '2025-11-20 17:10:34.768684', '2025-11-20 17:10:34.768684', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 328, 10, 'Cách làm:Thịt ếch rửa sạch, để ráo nước, chặt miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2000, '2025-11-20 17:10:34.771172', '2025-11-20 17:10:34.771172', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 328, 16, 'Cách làm:Ếch mua về rửa sạch, để ráo nước, chặt miếng vừa ăn. Rau nhút rửa sạch, để ráo. Tỏi bóc vỏ, băm nhuyễn. Ớt rửa sạch, thái sợi. Cà rốt gọt vỏ, thái sợi. Gừng một nhánh, cạo sạch vỏ, thái lát.', 10);
INSERT INTO public.recipe_steps VALUES (2001, '2025-11-20 17:10:34.772789', '2025-11-20 17:10:34.772789', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 328, 1, 'Ếch xào cải chua
INSERT INTO public.recipe_steps VALUES (2002, '2025-11-20 17:10:34.774951', '2025-11-20 17:10:34.774951', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 328, 3, 'Tỏi, hành bóc vỏ, rửa sạch. Tỏi băm nhuyễn. Hành tím 2 củ bổ đôi, củ còn lại băm nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (2003, '2025-11-20 17:10:34.777112', '2025-11-20 17:10:34.777112', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 328, 24, 'Cho ếch vào tô, rưới 2 thìa súp nước mắm và 1 thìa cà phê tương ớt, 1 thìa cà phê đường.', 10);
INSERT INTO public.recipe_steps VALUES (2004, '2025-11-20 17:10:34.778697', '2025-11-20 17:10:34.778697', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 328, 2, 'Cách làm:Ếch mua về rửa sạch, để ráo nước, chặt miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2005, '2025-11-20 17:10:34.780279', '2025-11-20 17:10:34.780279', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 328, 12, 'Cho nồi lên bếp, nồi khô đổ 1 thìa súp dầu ăn vào. Dầu sôi, cho tỏi băm vào phi thơm. Sau đó cho ếch và cà chua vào đảo đến khi thịt ếch săn lại.', 10);
INSERT INTO public.recipe_steps VALUES (2006, '2025-11-20 17:10:34.781874', '2025-11-20 17:10:34.781874', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 328, 22, 'Gia vị: nước mắm, tỏi băm, hành băm, đường, tiêu, tương ớt, dầu ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2007, '2025-11-20 17:10:34.783496', '2025-11-20 17:10:34.783496', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 328, 15, 'Ếch trộn rau nhút
INSERT INTO public.recipe_steps VALUES (2008, '2025-11-20 17:10:34.785089', '2025-11-20 17:10:34.785089', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 328, 8, 'Bạn cũng có thể trang trí thêm vài nhánh hành tươi thái sợi, ngâm nước lên trên cho đẹp mắt.', 10);
INSERT INTO public.recipe_steps VALUES (2009, '2025-11-20 17:10:34.786882', '2025-11-20 17:10:34.786882', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 328, 21, 'Ếch kho tộ
INSERT INTO public.recipe_steps VALUES (2010, '2025-11-20 17:10:34.788453', '2025-11-20 17:10:34.788453', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 328, 18, 'Hòa tan 1 thìa súp nước mắm với 1 thìa súp tương ớt, 1 thìa súp nước cốt chanh và tỏi băm.', 10);
INSERT INTO public.recipe_steps VALUES (2011, '2025-11-20 17:10:34.790557', '2025-11-20 17:10:34.790557', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 328, 6, 'Sau đó, cho thịt ếch vào đảo đều khoảng 3 phút. Khi ếch săn lại, trút dưa cải chua, cà chua và hành tím vào đảo chín. Nêm 1 thìa súp đường, 1 thìa súp nước mắm, 1 thìa súp hạt nêm sao cho vừa miệng ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2012, '2025-11-20 17:10:34.79214', '2025-11-20 17:10:34.79214', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 328, 9, 'Canh ếch
INSERT INTO public.recipe_steps VALUES (2013, '2025-11-20 17:10:34.793237', '2025-11-20 17:10:34.793237', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 328, 11, 'Tỏi, lột vỏ, rửa sạch, băm nhuyễn. Thì là, hành lá nhặt bỏ lá úa, rửa sạch, thái khúc ngắn 0,5cm. Cà chua bi rửa sạch, bổ đôi. Mẻ đem lọc qua rây, lấy nước.', 10);
INSERT INTO public.recipe_steps VALUES (2014, '2025-11-20 17:10:34.795379', '2025-11-20 17:10:34.795379', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 328, 4, 'Dưa cải chua rửa sạch, để ráo nước, thái miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2015, '2025-11-20 17:10:34.796954', '2025-11-20 17:10:34.796954', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 328, 19, 'Sau đó, cho rau nhút, thịt ếch, cà rốt, ớt vào thố, rưới nước mắm đã hòa tan cùng với gia vị trên, dùng đũa trộn đều. Ướp khoảng 15 20 phút, cứ 5 phút đảo một lần để rau nhút và thịt ếch ngấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (2016, '2025-11-20 17:10:34.949636', '2025-11-20 17:10:34.949636', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 329, 1, 'Thịt gà thái hạt lựu, ướp muối, hạt tiêu, húng lìu.', 10);
INSERT INTO public.recipe_steps VALUES (2017, '2025-11-20 17:10:34.951756', '2025-11-20 17:10:34.951756', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 329, 5, 'Bày vào đĩa sâu lòng hoặc bát to.', 10);
INSERT INTO public.recipe_steps VALUES (2018, '2025-11-20 17:10:34.95425', '2025-11-20 17:10:34.95425', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 329, 2, 'Hạnh nhân chao dòn (nếu lạc thì ngâm mềm, bóc vỏ chao qua).', 10);
INSERT INTO public.recipe_steps VALUES (2019, '2025-11-20 17:10:34.956372', '2025-11-20 17:10:34.956372', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 329, 3, 'Su hào, cà rốt, nấm hương thái hạt lựu.', 10);
INSERT INTO public.recipe_steps VALUES (2020, '2025-11-20 17:10:34.957967', '2025-11-20 17:10:34.957967', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 329, 4, 'Phi thơm hành, cho tất cả các nguyên liệu trên vào xào chín, cho thêm bột đao, nêm vừa. Trước khi bắc ra cho hành hoa thái khúc. Xúc ra đĩa rắc hạt tiêu, rau mùi.', 10);
INSERT INTO public.recipe_steps VALUES (2021, '2025-11-20 17:10:35.111427', '2025-11-20 17:10:35.111427', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 330, 1, 'Cá lóc làm sạch và cắt khoanh, ướp các với tương bắc, để ngấm', 10);
INSERT INTO public.recipe_steps VALUES (2022, '2025-11-20 17:10:35.113012', '2025-11-20 17:10:35.113012', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 330, 2, 'Xếp giềng và gừng dưới đáy nồi, cho cá lên trên rồi nêm nước mắm, hạt nêm từ thịt, xếp thêm gừng và riềng trên mặt. Chế nước sôi xâm xấp mặt cá kho trên lửa nhỏ cho đến khi nước cá sánh lại.', 10);
INSERT INTO public.recipe_steps VALUES (2023, '2025-11-20 17:10:35.114073', '2025-11-20 17:10:35.114073', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 330, 3, 'Món này dùng nóng với cơm trắng.', 10);
INSERT INTO public.recipe_steps VALUES (2026, '2025-11-20 17:10:35.22803', '2025-11-20 17:10:35.22803', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 331, 4, 'Cách làm sốt: Phi thơm hành tỏi, lá thơm, cho nước dùng cá + chanh leo + bơ, nêm vừa gia vị vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2027, '2025-11-20 17:10:35.23003', '2025-11-20 17:10:35.23003', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 331, 2, 'Sau đó để vào lò khoảng 15 phút thì cho ra.', 10);
INSERT INTO public.recipe_steps VALUES (2028, '2025-11-20 17:10:35.435782', '2025-11-20 17:10:35.435782', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 332, 5, 'Phi thơm tỏi, cho sườn vào xào săn, cho thêm ít nước đun nhỏ lửa. Khi nước cạn, cho tiếp nước đã pha trên vào đảo đều.', 10);
INSERT INTO public.recipe_steps VALUES (2029, '2025-11-20 17:10:35.437389', '2025-11-20 17:10:35.437389', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 332, 3, 'Hạt điều cho vào chảo cùng ít dầu đun khoảng 3 phút cho thêm nước, lọc lấy nước cho vào bột cà chua.', 10);
INSERT INTO public.recipe_steps VALUES (2030, '2025-11-20 17:10:35.439657', '2025-11-20 17:10:35.439657', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 332, 4, 'Pha dấm, đường, tỏi, ớt, nước mắm, nước lọc, bột đao cho vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2031, '2025-11-20 17:10:35.44125', '2025-11-20 17:10:35.44125', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 332, 2, 'Cà chua băm nhỏ, đun chín mềm, lọc lấy bột.', 10);
INSERT INTO public.recipe_steps VALUES (2032, '2025-11-20 17:10:35.443375', '2025-11-20 17:10:35.443375', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 332, 1, 'Sườn chặt miếng bằng bao diêm, ướp muối. Rán chín vàng.', 10);
INSERT INTO public.recipe_steps VALUES (2033, '2025-11-20 17:10:35.445086', '2025-11-20 17:10:35.445086', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 332, 6, 'Trước khi bắc ra cho hành củ tươi (bổ làm đôi) vào đảo lẫn. Xúc ra đĩa, rắc rau mùi ăn nóng.', 10);
INSERT INTO public.recipe_steps VALUES (2034, '2025-11-20 17:10:35.700933', '2025-11-20 17:10:35.700933', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 333, 3, 'Buộc khăn ủ kín giữ nhiệt khoảng 30 phút.Khi nguội trút vào âu trộn lẫn với hạt điều đã băm nhỏ, cho vào ngăn để rau quả của tủ lạnh khoảng một tiếng.', 10);
INSERT INTO public.recipe_steps VALUES (2035, '2025-11-20 17:10:35.702513', '2025-11-20 17:10:35.702513', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 333, 5, 'Bày ra từng đĩa sâu lòng, trang trí dâu tây xung quanh, kem tươi phủ phía trên, cuối cùng rắc thêm lớp mỏng hạnh nhân.', 10);
INSERT INTO public.recipe_steps VALUES (2036, '2025-11-20 17:10:35.704659', '2025-11-20 17:10:35.704659', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 333, 4, 'Đánh tan kem tươi với 3 thìa đường, cũng để lạnh một tiếng.', 10);
INSERT INTO public.recipe_steps VALUES (2037, '2025-11-20 17:10:35.70625', '2025-11-20 17:10:35.70625', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 333, 1, 'Dâu tây rửa sạch, bổ đôi. Hạnh nhân rang vàng. Hạt điều băm nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2038, '2025-11-20 17:10:35.708487', '2025-11-20 17:10:35.708487', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 333, 2, 'Cho nước (ngập khoảng 0,5 cm) vào nồi đun sôi, đổ sữa tươi vào khuấy đều, (theo cách này sữa không bị cháy và lắng cặn) cho sôi lại rồi cho tiếp gạo nếp, mật ong, tinh đường Vanille, 1 nhúm muối vào, nấu khi gạo nếp chín bắc ra.', 10);
INSERT INTO public.recipe_steps VALUES (2039, '2025-11-20 17:10:36.030355', '2025-11-20 17:10:36.030355', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 334, 3, 'Xào tỏi bằm, hành tím, tiêu sọ với bơ cho thơm, thêm nước dùng bò vào chảo đun sôi lên. Nêm với hạt nêm cho vừa ăn sau đó làm sệt nước xốt với bột bắp.', 10);
INSERT INTO public.recipe_steps VALUES (2040, '2025-11-20 17:10:36.031954', '2025-11-20 17:10:36.031954', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 334, 5, 'Món này dùng nóng với nước tương và ớt.', 10);
INSERT INTO public.recipe_steps VALUES (2041, '2025-11-20 17:10:36.03354', '2025-11-20 17:10:36.03354', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 334, 4, 'Sắp đậu hũ chiên ra đĩa, rưới nước xốt tiêu lên trên và trang trí với xà lách, cà chua, dưa leo.', 10);
INSERT INTO public.recipe_steps VALUES (2042, '2025-11-20 17:10:36.035149', '2025-11-20 17:10:36.035149', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 334, 2, 'Trộn đều cá thác lác, thịt heo, hành lá, hạt nêm và tiêu xay. Nhồi hỗn hợp cá thác lác vào trong đậu hũ sau đó đem chiên vàng.', 10);
INSERT INTO public.recipe_steps VALUES (2043, '2025-11-20 17:10:36.03676', '2025-11-20 17:10:36.03676', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 334, 1, 'Đậu hũ chiên vàng, để nguội, cắt làm đôi, khoét bỏ một phần ruột.', 10);
INSERT INTO public.recipe_steps VALUES (2044, '2025-11-20 17:10:36.226224', '2025-11-20 17:10:36.226224', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 335, 5, 'Đậu phụ thái con chì rán vàng.', 10);
INSERT INTO public.recipe_steps VALUES (2045, '2025-11-20 17:10:36.228557', '2025-11-20 17:10:36.228557', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 335, 4, 'Ngô bao tử chẻ đôi.', 10);
INSERT INTO public.recipe_steps VALUES (2046, '2025-11-20 17:10:36.229635', '2025-11-20 17:10:36.229635', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 335, 6, 'Cà rốt gọt vỏ thái lát mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (2047, '2025-11-20 17:10:36.23179', '2025-11-20 17:10:36.23179', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 335, 8, 'Trần tất cả các loại rau để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (2048, '2025-11-20 17:10:36.232859', '2025-11-20 17:10:36.232859', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 335, 1, 'Nấm hương ngâm rửa sạch, om chín', 10);
INSERT INTO public.recipe_steps VALUES (2049, '2025-11-20 17:10:36.234459', '2025-11-20 17:10:36.234459', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 335, 3, 'Mộc nhĩ ngâm rửa sạch thái miếng 2 x 2 cm.', 10);
INSERT INTO public.recipe_steps VALUES (2050, '2025-11-20 17:10:36.236048', '2025-11-20 17:10:36.236048', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 335, 7, 'Cải ngọt lấy phần cuống.', 10);
INSERT INTO public.recipe_steps VALUES (2051, '2025-11-20 17:10:36.237624', '2025-11-20 17:10:36.237624', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 335, 9, 'Cho dầu vào chảo, phi thơm hành, sau đó cho tất cả các nguyên liệu trên vào nêm gia vị vừa ăn, nếu có nhiều nước xuống ít bột ngô cho sánh, bỏ ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (2052, '2025-11-20 17:10:36.238679', '2025-11-20 17:10:36.238679', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 335, 2, 'Nấm Đông cô ngâm rửa sạch, om chín.', 10);
INSERT INTO public.recipe_steps VALUES (2053, '2025-11-20 17:10:36.51247', '2025-11-20 17:10:36.51247', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 336, 4, 'Cho ớt chuông, nấm linh chi, đầu hành vào chần nước sôi trong 1 phút, cho vào ngâm trong nước và đá đập nhỏ trong 5 phút, rồi cho ra rổ để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (2054, '2025-11-20 17:10:36.514048', '2025-11-20 17:10:36.514048', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 336, 5, 'Chờ dầu sôi, cho cá vào chiên vàng trên lửa vừa, cho ra đĩa có lót giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (2055, '2025-11-20 17:10:36.515104', '2025-11-20 17:10:36.515104', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 336, 1, 'Cá chim làm sạch, rửa, để ráo ướp tỏi, muối ớt, để ngấm trong 1 giờ.', 10);
INSERT INTO public.recipe_steps VALUES (2056, '2025-11-20 17:10:36.517501', '2025-11-20 17:10:36.517501', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 336, 6, 'Xào thơm hành tây với dầu, rồi cho nấm linh chi, ớt chuông, đầu hành lá, hạt nêm, tương ớt, xốt cà vào trộn đều 1 phút, cho nước dùng và nước bột bắp vào trộn đều 1 phút sau đó nhấc xuống.', 10);
INSERT INTO public.recipe_steps VALUES (2057, '2025-11-20 17:10:36.519044', '2025-11-20 17:10:36.519044', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 336, 7, 'Bày cá vào đĩa, trải đều xốt nấm lên cá, dọn dùng nóng với tương ớt.', 10);
INSERT INTO public.recipe_steps VALUES (2058, '2025-11-20 17:10:36.520809', '2025-11-20 17:10:36.520809', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 336, 3, 'Ớt chuông vàng và đỏ rửa sạch, bỏ cuống, hạt, ruột trắng, sau đó cắt sợi.', 10);
INSERT INTO public.recipe_steps VALUES (2059, '2025-11-20 17:10:36.521877', '2025-11-20 17:10:36.521877', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 336, 2, 'Nấm linh chi cắt gốc, rửa để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (2060, '2025-11-20 17:10:36.800708', '2025-11-20 17:10:36.800708', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 337, 3, 'Xắt phô mai thành lát chữ nhật vừa ăn rồi láng lên bề mặt trứng.', 10);
INSERT INTO public.recipe_steps VALUES (2115, '2025-11-20 17:10:38.4612', '2025-11-20 17:10:38.4612', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 347, 1, 'Tôm ướp: gia vị mì chính, hạt tiêu, hành khô băm nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2061, '2025-11-20 17:10:36.802291', '2025-11-20 17:10:36.802291', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 337, 1, 'Đập trứng ra tô, đánh bông với ít hạt nêm. Cà chua bỏ hạt, xắt hạt lựu nhỏ. Cà rốt, đậu cô-ve, đậu Hà lan rửa sạch, chần sơ. Hành tây xắt nhỏ. Thịt nạc vai bằm nhỏ, nêm ít hạt nêm, trộn đều. Bắc chảo lên bếp, phi thơm tỏi, cho hành tây vào đảo sơ, tiếp tục cho thịt bằm, cà chua vào, nêm chút nước mắm cho vừa miệng. Đợi thịt xào cạn nước, ngấm gia vị thì rắc ngò vào, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (2062, '2025-11-20 17:10:36.803351', '2025-11-20 17:10:36.803351', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 337, 2, 'Bắc một chảo khác lên bếp, láng dầu ăn, đổ trứng vào chiên, để lửa nhỏ khi trứng chín se mặt, cho thịt xào vào giữa, tiếp tục cho cà rốt, đậu cô-ve, đậu Hà Lan vào, gấp một góc trứng rồi cuộn tròn lại, xúc ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (2063, '2025-11-20 17:10:36.943902', '2025-11-20 17:10:36.943902', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 338, 3, 'Đậu xanh ngâm nước ấm trong vòng 30 phút, vớt lên xả sạch', 10);
INSERT INTO public.recipe_steps VALUES (2064, '2025-11-20 17:10:36.946012', '2025-11-20 17:10:36.946012', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 338, 4, 'Ngò rí cắt bỏ gốc, rửa sạch, xắt nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2065, '2025-11-20 17:10:36.947618', '2025-11-20 17:10:36.947618', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 338, 1, 'Sườn non rửa sạch chặt khúc dài 3 cm rồi ướp với 1/2 muỗng cà phê muối + 1/2 muỗng hạt nêm từ thịt, để khoảng 10 phút cho ngấm đều gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (2066, '2025-11-20 17:10:36.949235', '2025-11-20 17:10:36.949235', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 338, 2, 'Nha đam gọt vỏ, xắt thành miếng dài 3 cm, đem xả sạch nhớt bằng nước lạnh. Đun 1 chén cho thêm 1 muỗng súp muối vào nồi nước, đun sôi. Cho nha đam vào trụng vớt lên ngay rồi thả vào nước đá. Nha đam sẽ hết đắng và không còn mùi hôi của nhựa.', 10);
INSERT INTO public.recipe_steps VALUES (2067, '2025-11-20 17:10:36.951521', '2025-11-20 17:10:36.951521', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 338, 5, 'Cho 1,5 lít nước lạnh vào nồi nấu sôi, cho sườn non vào, hầm lửa riu riu, vớt bọt. Sườn mềm, cho đậu xanh vào hầm mềm, nêm lại hạt nêm từ thịt, tiêu, muối, nước mắm vừa ăn. Cuối cùng, cho nha đam vào, nhấc xuống ngay.', 10);
INSERT INTO public.recipe_steps VALUES (2068, '2025-11-20 17:10:37.242193', '2025-11-20 17:10:37.242193', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 339, 4, 'Thêm nước lọc vào nồi, đun sôi lên.', 10);
INSERT INTO public.recipe_steps VALUES (2069, '2025-11-20 17:10:37.244756', '2025-11-20 17:10:37.244756', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 339, 6, 'Múc canh vào tô, thêm tiêu xay, ngò ôm, ngò gai và ớt sừng vào tô. Dùng nóng.', 10);
INSERT INTO public.recipe_steps VALUES (2070, '2025-11-20 17:10:37.246658', '2025-11-20 17:10:37.246658', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 339, 5, 'Nêm nước canh với hạt nêm và đường cát trắng cho vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2071, '2025-11-20 17:10:37.248745', '2025-11-20 17:10:37.248745', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 339, 3, 'Cho tiếp cà chua vào nồi xào sơ để lấy màu rồi cho khế vào.', 10);
INSERT INTO public.recipe_steps VALUES (2072, '2025-11-20 17:10:37.250354', '2025-11-20 17:10:37.250354', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 339, 1, 'Xào hành tím với dầu ăn cho thơm.', 10);
INSERT INTO public.recipe_steps VALUES (2073, '2025-11-20 17:10:37.252526', '2025-11-20 17:10:37.252526', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 339, 2, 'Thêm thịt bò vào nồi, xào chín.', 10);
INSERT INTO public.recipe_steps VALUES (2074, '2025-11-20 17:10:37.380005', '2025-11-20 17:10:37.380005', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 340, 5, 'Chiên chả cốm: Chiên chả cốm ở lửa nhỏ vừa, trở đều để các mặt giòn vàng đều, vớt ra để giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (2075, '2025-11-20 17:10:37.381652', '2025-11-20 17:10:37.381652', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 340, 2, 'Trộn và quết chả cốm:Cho giò sống, thịt nạc vai xay, mỡ lợn thái hạt lựu, cốm vào tô trộn. Thêm 1 thìa cà phê nước mắm (vì giò sống đậm vị rồi nên nêm ít mắm), 1 thìa cà phê hạt nêm, 1 thìa cà phê hạt tiêu và hành khô băm nhỏ vào trộn đều. Chia từng phần rồi quết thật đều để giúp miếng chả được dẻo mềm, có chút dai bằng cách nắm từng nắm đập mạnh xuống lòng tô trộn, hoặc cho tất cả nguyên liệu vào túi nilon dày bôi chút dầu cho đỡ dính, để hé miệng rồi đập mạnh xuống bàn nhiều lần. Cho tới khi hỗn hợp thành một khối dẻo mịn, kết dính là đạt.', 10);
INSERT INTO public.recipe_steps VALUES (2076, '2025-11-20 17:10:37.383247', '2025-11-20 17:10:37.383247', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 340, 4, 'Hấp chả cốm:Cho chả cốm vào hấp khoảng 9-10 phút, lấy ra để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (2077, '2025-11-20 17:10:37.384311', '2025-11-20 17:10:37.384311', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 340, 1, 'Chuẩn bị:Cốm để mềm. Nếu bạn sử dụng cốm khô thì vẩy thêm chút nước cho mềm ra. Cho mỡ phần cùng chút đường vào nồi nước và luộc chín, vớt ra, rửa sạch, thấm khô, thái hạt lựu nhỏ. Hành khô băm nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2078, '2025-11-20 17:10:37.385903', '2025-11-20 17:10:37.385903', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 340, 3, 'Nặn chả cốm:Đeo găng tay, lấy thìa múc từng ít một, vo tròn rồi ấn dẹp để lên lá chuối hoặc lá sen có quết lớp dầu nhẹ, làm lần lượt cho tới hết.', 10);
INSERT INTO public.recipe_steps VALUES (2079, '2025-11-20 17:10:37.433255', '2025-11-20 17:10:37.433255', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 341, 6, 'Cách làm: Tôm lột vỏ bỏ đầu đuôi. Gừng gọt vỏ, một nửa đập giập, nửa còn lại xắt chỉ. Đặt nước dùng lên bếp, cho 2 thứ gừng vào nấu cùng, khi nước sôi cho hạt nêm và tôm vào. Khuấy bột năng với ít nước lạnh cho vào nước đang sôi. Chờ soup sôi lại, múc vào chén, rắc tiêu, ngò và tỏi phi trên mặt, dùng nóng.', 10);
INSERT INTO public.recipe_steps VALUES (2080, '2025-11-20 17:10:37.434853', '2025-11-20 17:10:37.434853', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 341, 2, 'Cách làm: Tôm lột vỏ, bỏ đầu đuôi. Cà chua cắt múi cau. Phi thơm hành và gừng với dầu ăn. Cho cà vào xào đến khi lên màu, trút 1 bát nước nhỏ vào, nêm hạt nêm và đường. Khi nước sôi cho tôm vào nấu khoảng 2 phút, cho hành và thìa là vào, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (2081, '2025-11-20 17:10:37.436439', '2025-11-20 17:10:37.436439', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 341, 3, 'Canh nấm thịt bò
INSERT INTO public.recipe_steps VALUES (2082, '2025-11-20 17:10:37.438082', '2025-11-20 17:10:37.438082', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 341, 1, 'Tôm nấu riêu
INSERT INTO public.recipe_steps VALUES (2083, '2025-11-20 17:10:37.439677', '2025-11-20 17:10:37.439677', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 341, 4, 'Cách làm: Nấm cắt gốc, ngâm nước muối rửa sạch. Thịt bò xắt mỏng, ướp thịt bò với hành tím, tiêu, dầu ăn. Cà rốt tỉa hoa xắt mỏng. Nấu sôi nước dùng, cho cà rốt và gừng vào nấu. Cà rốt vừa mềm cho tiếp nấm, thịt bò vào, nêm muối vừa ăn. Chờ sôi lại tắt bếp, rắc hành ngò, dùng nóng.', 10);
INSERT INTO public.recipe_steps VALUES (2084, '2025-11-20 17:10:37.440744', '2025-11-20 17:10:37.440744', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 341, 5, 'Soup tôm vị gừng
INSERT INTO public.recipe_steps VALUES (2085, '2025-11-20 17:10:37.693063', '2025-11-20 17:10:37.693063', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 342, 5, 'Đun nước dùng sôi, thả khoai vào, nêm gia vị rồi đun nhừ. Tiếp theo, cho nhân tôm + nhân bắp cải đun chín. Nêm lại gia vị + các loại rau thơm cắt nhỏ. Múc vào bát ăn nóng.', 10);
INSERT INTO public.recipe_steps VALUES (2086, '2025-11-20 17:10:37.694116', '2025-11-20 17:10:37.694116', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 342, 1, 'Khoai mỡ gọt vỏ hoặc nạo vỏ sạch lấy hết các mắt đen và thâm, cắt mỏng hoặc bào sợi. Một phần nhỏ cắt hạt lựu .', 10);
INSERT INTO public.recipe_steps VALUES (2087, '2025-11-20 17:10:37.69574', '2025-11-20 17:10:37.69574', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 342, 2, 'Tôm tươi bóc vỏ, bỏ phần lưng để đầu đuôi cho đẹp, lấy chỉ đen ở lưng, rửa sạch tẩm ướp hành khô, tiêu dập, nước mắm.', 10);
INSERT INTO public.recipe_steps VALUES (2088, '2025-11-20 17:10:37.696794', '2025-11-20 17:10:37.696794', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 342, 3, 'Một phần tôm chỉ lấy thịt băm nhuyễn trộn cùng giò sống, hành khô, nấm hương, mộc nhĩ, tiêu, nước mắm, bột nêm.', 10);
INSERT INTO public.recipe_steps VALUES (2089, '2025-11-20 17:10:37.698427', '2025-11-20 17:10:37.698427', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 342, 4, 'Bắp cải trần sơ cho mềm, cho nhân tôm thịt vào gói, buộc hành.', 10);
INSERT INTO public.recipe_steps VALUES (2090, '2025-11-20 17:10:37.859639', '2025-11-20 17:10:37.859639', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 343, 4, 'Hành hoa cắt dài 3 cm.', 10);
INSERT INTO public.recipe_steps VALUES (2091, '2025-11-20 17:10:37.861783', '2025-11-20 17:10:37.861783', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 343, 7, 'Bày đồ ăn ra đĩa, trang trí rau mùi, ớt tỉa hoa.', 10);
INSERT INTO public.recipe_steps VALUES (2092, '2025-11-20 17:10:37.863374', '2025-11-20 17:10:37.863374', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 343, 3, 'Cà rốt thái mỏng, ớt Đà Lạt bỏ hạt thái mỏng vừa.', 10);
INSERT INTO public.recipe_steps VALUES (2093, '2025-11-20 17:10:37.864967', '2025-11-20 17:10:37.864967', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 343, 5, 'Đun dầu nóng già cho thịt đã tẩm ướp vào xào săn, để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (2094, '2025-11-20 17:10:37.866011', '2025-11-20 17:10:37.866011', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 343, 6, 'Phi thơm hành tỏi, cho cà rốt, ớt vào đảo chín tới. Sau đó cho hành, nấm và thịt bò đảo đều, nêm vừa ăn. Cuối cùng cho sa tế vào.', 10);
INSERT INTO public.recipe_steps VALUES (2095, '2025-11-20 17:10:37.868136', '2025-11-20 17:10:37.868136', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 343, 2, 'Nấm rơm ngâm nước có hoà chút muối, vớt ra để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (2096, '2025-11-20 17:10:37.869197', '2025-11-20 17:10:37.869197', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 343, 1, 'Thịt bò lọc bỏ gân xơ, thái mỏng to bản ngang thớ, ướp với: gia vị, hạt tiêu, dầu hào, tỏi băm.', 10);
INSERT INTO public.recipe_steps VALUES (2097, '2025-11-20 17:10:38.004078', '2025-11-20 17:10:38.004078', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 344, 2, 'Mỡ rửa sạch, xắt thành thỏi dài bằng chiều dài miếng thịt.', 10);
INSERT INTO public.recipe_steps VALUES (2098, '2025-11-20 17:10:38.005131', '2025-11-20 17:10:38.005131', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 344, 1, 'Thịt thăn bò khi mua chọn nguyên khối. Rửa thịt sạch, lạng theo sớ dọc thành miếng dày 1 cm, rộng bản. Ướp thịt với nước mắm, muối, tiêu, đường, hành tỏi băm nhỏ, ngũ vị hương, 1 muỗng dầu ăn, để 15 phút cho thấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (2099, '2025-11-20 17:10:38.00723', '2025-11-20 17:10:38.00723', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 344, 4, 'Bắc chảo dầu đun sôi, chiên cuốn thịt vàng xung quanh.', 10);
INSERT INTO public.recipe_steps VALUES (2100, '2025-11-20 17:10:38.010348', '2025-11-20 17:10:38.010348', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 344, 5, 'Sả chặt khúc, lót đáy nồi. Xếp cuốn thịt lên trên, đổ nước ngập phân nửa cuốn thịt, đậy nắp đun nhỏ lửa, thỉnh thoảng trở thịt cho chín đều. Khi thịt chín mềm, nước còn lại chừng 1/3 thì cho đậu rang giã nhỏ vào. Đun sôi lại, nhắc xuống để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (2101, '2025-11-20 17:10:38.013047', '2025-11-20 17:10:38.013047', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 344, 3, 'Trải miếng thịt ra mâm, đặt miếng mỡ vào giữa, cuốn lại giống thịt bò kho quế rồi lấy dây gai quấn xung quanh cho chặt.', 10);
INSERT INTO public.recipe_steps VALUES (2102, '2025-11-20 17:10:38.01517', '2025-11-20 17:10:38.01517', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 344, 7, 'Yêu cầu thành phẩm: Miếng thịt tròn đều, màu sẫm, điểm miếng mỡ ở giữa. Vị mặn, ngọt đậm đà.', 10);
INSERT INTO public.recipe_steps VALUES (2103, '2025-11-20 17:10:38.016761', '2025-11-20 17:10:38.016761', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 344, 6, 'Trình bày: Tháo bỏ dây buộc, xắt thịt thành từng khoanh tròn, bề dày khoảng 0,5 - 1 cm, xếp vào giữa đĩa, múc nước thịt rưới lên. Rải đậu phộng lên trên. Cam gọt vỏ, xắt khoanh, bỏ hột, bày xung quanh đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (2104, '2025-11-20 17:10:38.169537', '2025-11-20 17:10:38.169537', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 345, 1, 'Mực tươi sơ chế sạch thái miếng 5x5 cm. Đun sôi nước, cho một chút rượu trắng và gừng đập dập vào rồi đổ mực vào chần qua.', 10);
INSERT INTO public.recipe_steps VALUES (2105, '2025-11-20 17:10:38.171652', '2025-11-20 17:10:38.171652', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 345, 4, 'Đun sôi dầu, mỡ, thả miếng mực vào, rán chín vàng vớt ra bày đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (2106, '2025-11-20 17:10:38.172711', '2025-11-20 17:10:38.172711', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 345, 3, 'Đập trứng ra bát, đánh nhuyễn trộn cùng mực đã tẩm ướp. Nhặt từng miếng mực lăn vào bột đao để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (2107, '2025-11-20 17:10:38.174296', '2025-11-20 17:10:38.174296', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 345, 2, 'Mực đã chần để ráo nước ướp: gia vị, mỳ chính, hạt tiêu, rau thì là ớt tươi băm nhỏ để 10 phút cho ngấm.', 10);
INSERT INTO public.recipe_steps VALUES (2108, '2025-11-20 17:10:38.343948', '2025-11-20 17:10:38.343948', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 346, 2, 'Rán thịt bò chín tới, xếp ra đĩa, dội sốt lên trên bề mặt của thịt bò, ăn nóng.', 10);
INSERT INTO public.recipe_steps VALUES (2109, '2025-11-20 17:10:38.34509', '2025-11-20 17:10:38.34509', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 346, 1, 'Làm sốt: Đun nóng dầu, hành tây, tiêu hạt phi thơm, cho bột cà chua vào xào sau đó cho vang đỏ đun nhỏ lửa rồi cho muối, tiêu, gia vị, bơ, nêm vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2110, '2025-11-20 17:10:38.346679', '2025-11-20 17:10:38.346679', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 346, 3, 'Yêu cầu: Sốt thơm mùi bơ, hạt tiêu, rượu vang, thịt bò chín tới, không dai.', 10);
INSERT INTO public.recipe_steps VALUES (2111, '2025-11-20 17:10:38.454547', '2025-11-20 17:10:38.454547', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 347, 4, 'Đun dầu nóng già, cho tôm đã ướp rán chín xém cạnh để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (2112, '2025-11-20 17:10:38.456163', '2025-11-20 17:10:38.456163', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 347, 6, 'Phi thơm hành tỏi khô cho tôm đã rán vào xào thơm, xúc hỗn hợp bột vào chảo tôm đảo đều. Sau đó xúc bày ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (2113, '2025-11-20 17:10:38.45777', '2025-11-20 17:10:38.45777', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 347, 2, 'Gạo nếp, đỗ xanh rang thơm, xay nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2114, '2025-11-20 17:10:38.458833', '2025-11-20 17:10:38.458833', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 347, 5, 'Bột cà mỳ, đỗ xanh, gạo nếp, hạt tiêu xay, tôm khô, muối trộn đều để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (2116, '2025-11-20 17:10:38.462785', '2025-11-20 17:10:38.462785', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 347, 3, 'Bột cà mỳ (cháo ăn liền) lọc lấy cánh nhỏ. Hạt tiêu rang thơm xay nhỏ, tôm khô rang thơm giã hoặc xay nhỏ. Muối tinh rang khô.', 10);
INSERT INTO public.recipe_steps VALUES (2117, '2025-11-20 17:10:38.59163', '2025-11-20 17:10:38.59163', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 348, 8, 'Bày đĩa trang trí rau thơm mùi, ớt tỉa hoa ăn nóng.', 10);
INSERT INTO public.recipe_steps VALUES (2118, '2025-11-20 17:10:38.593761', '2025-11-20 17:10:38.593761', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 348, 5, 'Đun dầu nóng già cho thịt bò vào xào nhanh tay xém cạnh để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (2119, '2025-11-20 17:10:38.595523', '2025-11-20 17:10:38.595523', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 348, 7, 'Phi thơm tỏi khô rồi cho các rau nguyên liệu xào chín tái, cho thịt bò đảo đều nêm vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2120, '2025-11-20 17:10:38.596558', '2025-11-20 17:10:38.596558', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 348, 4, 'Mộc nhĩ ngâm nở rồi thái con chì.', 10);
INSERT INTO public.recipe_steps VALUES (2121, '2025-11-20 17:10:38.598141', '2025-11-20 17:10:38.598141', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 348, 6, 'Cà chua + hành tây + mộc nhĩ xào chín đến 80 % thì nêm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (2122, '2025-11-20 17:10:38.599206', '2025-11-20 17:10:38.599206', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 348, 2, 'Các loại rau rửa sạch, cà rốt thái tỉa con giống rồi thái mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (2123, '2025-11-20 17:10:38.600796', '2025-11-20 17:10:38.600796', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 348, 1, 'Thịt bò lọc bỏ gân xơ, thái mỏng to bản ngang thớ ướp: gia vị, hạt tiêu, nước mắm, 1/2 tỏi khô băm nhỏ + 1 chút bột đao.', 10);
INSERT INTO public.recipe_steps VALUES (2124, '2025-11-20 17:10:38.6025', '2025-11-20 17:10:38.6025', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 348, 3, 'Cà chua bổ miếng cau, cần, tỏi tây, hành hoa cắt dài 3 cm.', 10);
INSERT INTO public.recipe_steps VALUES (2125, '2025-11-20 17:10:38.695577', '2025-11-20 17:10:38.695577', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 349, 1, 'Nấm thái mỏng, ngâm nước có hoà chút muối. Vớt ra để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (2126, '2025-11-20 17:10:38.69776', '2025-11-20 17:10:38.69776', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 349, 4, 'Trứng đập ra bát đánh nhuyễn, nêm tiêu, muối, nước mắm, hành hoa. Đun dầu nóng cho trứng vào rán xếp nấm lên trên. Rán vàng đều hai mặt.', 10);
INSERT INTO public.recipe_steps VALUES (2127, '2025-11-20 17:10:38.699559', '2025-11-20 17:10:38.699559', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 349, 2, 'Hành hoa cắt khúc.', 10);
INSERT INTO public.recipe_steps VALUES (2128, '2025-11-20 17:10:38.70116', '2025-11-20 17:10:38.70116', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 349, 5, 'Trứng chín bày đĩa. Trang trí rau mùi, cà chua, dưa chuột.', 10);
INSERT INTO public.recipe_steps VALUES (2129, '2025-11-20 17:10:38.703328', '2025-11-20 17:10:38.703328', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 349, 3, 'Cà chua, dưa chuột, rau mùi rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (2130, '2025-11-20 17:10:38.851795', '2025-11-20 17:10:38.851795', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 350, 6, 'Hoà 1 bát gồm: 5 thìa dấm + 4 thìa đường + 1 muối + tỏi ớt băm nhỏ + 1 thìa cốt chanh đảo đều. Lấy âu sạch cho các loại nguyên liệu đảo đều, cho bát hỗn hợp dấm đường. Cuối cùng cho rau, lạc rang, hành khô. Bầy đĩa trang trí cà rốt tỉa hoa rau thơm mùi.', 10);
INSERT INTO public.recipe_steps VALUES (2131, '2025-11-20 17:10:38.852863', '2025-11-20 17:10:38.852863', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 350, 1, 'Miến ngâm mềm, chần qua nước sôi, rửa lại bằng nước lạnh để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (2132, '2025-11-20 17:10:38.85445', '2025-11-20 17:10:38.85445', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 350, 4, 'Hành tây thái mỏng bóp một chút dấm.', 10);
INSERT INTO public.recipe_steps VALUES (2133, '2025-11-20 17:10:38.855523', '2025-11-20 17:10:38.855523', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 350, 3, 'Thịt pha khối rồi rán chín vàng, thái mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (2134, '2025-11-20 17:10:38.857103', '2025-11-20 17:10:38.857103', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 350, 5, 'Cà chua bổ miếng cau. Hành khô thái mỏng phi thơm, lạc rang xát vỏ giã dập. Tỏi ớt băm nhỏ. Rau thơm mùi cắt khúc ngắn.', 10);
INSERT INTO public.recipe_steps VALUES (2135, '2025-11-20 17:10:38.85818', '2025-11-20 17:10:38.85818', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 350, 7, 'Trộn dấm, đường, tỏi, ớt và nước mắm trong âu, quấy tan, cho các loại rau vào trộn đều, vắt nước chanh, các loại rau thơm và thịt vào. Bày lên đĩa, trang trí bằng rau thơm.', 10);
INSERT INTO public.recipe_steps VALUES (2136, '2025-11-20 17:10:38.860822', '2025-11-20 17:10:38.860822', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 350, 2, 'Tôm tươi bóc bỏ vỏ, lấy nõn rồi hấp chín.', 10);
INSERT INTO public.recipe_steps VALUES (2137, '2025-11-20 17:10:39.032002', '2025-11-20 17:10:39.032002', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 351, 4, 'Làm nước chấm: Cho hành tây bằm + tỏi bằm phi thơm, thêm 250 ml nước sốt cà chua + 125 ml nước lọc + 2 muỗng đường + 1 muỗng bột ngọt rồi đun sôi đều là được.', 10);
INSERT INTO public.recipe_steps VALUES (2138, '2025-11-20 17:10:39.033059', '2025-11-20 17:10:39.033059', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 351, 5, 'Trình bày: Cho salad xoong dưới đĩa rồi xếp tôm đều ra, trang trí thêm lá ngò.', 10);
INSERT INTO public.recipe_steps VALUES (2139, '2025-11-20 17:10:39.03464', '2025-11-20 17:10:39.03464', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 351, 1, 'Tôm lột vỏ lấy chỉ, khứa ở vùng bụng 3 khứa để cho tôm thẳng rồi rửa sạch để ráo nước (tôm để đuôi)', 10);
INSERT INTO public.recipe_steps VALUES (2140, '2025-11-20 17:10:39.036185', '2025-11-20 17:10:39.036185', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 351, 2, 'Pha bột: Cho 2 muỗng bột mì + 1muỗng muối +1 muỗng bột nêm + 2 lòng đỏ trứng vào bột + 2 lòng trắng trứng cho vào tô đánh sủi bọt, cho 1/2 chén nước vào bột với 2 lòng đỏ quậy đều rồi cho hai lòng trắng trứng đã quậy vào (không quậy nhiều).', 10);
INSERT INTO public.recipe_steps VALUES (2141, '2025-11-20 17:10:39.037869', '2025-11-20 17:10:39.037869', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 351, 3, 'Chiên tôm: Cho chảo lên bếp đổ dầu vào, dầu sôi nhúng tôm vào hỗn hợp bột và chiên thấy tôm vàng đều là được.', 10);
INSERT INTO public.recipe_steps VALUES (2142, '2025-11-20 17:10:39.241573', '2025-11-20 17:10:39.241573', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 352, 2, 'Salad: trứng gà luộc chín bổ đôi, lấy lòng đỏ riêng trộn đều với dưa chuột muối băm nhỏ + sốt mayonnaise rồi nhồi trở lại lòng trắng.', 10);
INSERT INTO public.recipe_steps VALUES (2143, '2025-11-20 17:10:39.243151', '2025-11-20 17:10:39.243151', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 352, 1, 'Làm sốt Mayonaise: Cho trứng gà, mù tạt, muối tiêu vào âu, dùng máy hoặc phới đánh chậm, từ từ rót dầu vào đánh cùng cho dầu tan đều trong trứng, đến khi hết dầu thì cho nước cốt chanh vào đánh đều là được.', 10);
INSERT INTO public.recipe_steps VALUES (2144, '2025-11-20 17:10:39.244746', '2025-11-20 17:10:39.244746', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 352, 3, 'Bày ra đĩa, trang trí cho đẹp mắt.', 10);
INSERT INTO public.recipe_steps VALUES (2145, '2025-11-20 17:10:39.328728', '2025-11-20 17:10:39.328728', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 353, 7, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (2146, '2025-11-20 17:10:39.330344', '2025-11-20 17:10:39.330344', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 353, 5, 'Thiên lý xào chung với trứng gà đã đánh tan trên chảo dầu nóng để lửa nhỏ, chỉ cần 1 phút là vừa ăn. Trộn thiên lý đã xào với thịt bò, dùng nóng.', 10);
INSERT INTO public.recipe_steps VALUES (2147, '2025-11-20 17:10:39.331395', '2025-11-20 17:10:39.331395', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 353, 1, 'Thiên lý xào trứng và thịt bò
INSERT INTO public.recipe_steps VALUES (2148, '2025-11-20 17:10:39.332978', '2025-11-20 17:10:39.332978', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 353, 11, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (2149, '2025-11-20 17:10:39.334029', '2025-11-20 17:10:39.334029', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 353, 18, 'Đun nước dùng cua, cho thêm 2 muỗng hạt nêm. Khi nước sôi lăn tăn, dùng muỗng khuấy đều theo một chiều để xác cua đông kết tạo thành gạch cua và gạch không bị bám vào đáy nồi và không bị vỡ nát. Nước sôi, cho hoa thiên lý vào nấu chung, đảo nhẹ tay để hoa không bị nát cánh. Khi nước sôi lại là được. Múc ra bát, ăn nóng.', 10);
INSERT INTO public.recipe_steps VALUES (2150, '2025-11-20 17:10:39.335633', '2025-11-20 17:10:39.335633', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 353, 6, 'Thiên lý xào sò điệp
INSERT INTO public.recipe_steps VALUES (2151, '2025-11-20 17:10:39.337233', '2025-11-20 17:10:39.337233', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 353, 15, '150 g cua đồng, 200 g hoa thiên lý, gia vị: muối, bột ngọt, hạt nêm.', 10);
INSERT INTO public.recipe_steps VALUES (2152, '2025-11-20 17:10:39.33882', '2025-11-20 17:10:39.33882', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 353, 13, 'Cho nước mắm + đường + nước cốt chanh + tương ớt vào chén, khuấy đều làm nước trộn gỏi. Cho thiên lý, tôm, nghêu, ớt vào tô, trộn đều. Đổ nước trộn gỏi vào, dùng đũa trộn đều, nêm lại cho vừa ăn. Món này dùng ngay.', 10);
INSERT INTO public.recipe_steps VALUES (2153, '2025-11-20 17:10:39.339878', '2025-11-20 17:10:39.339878', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 353, 16, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (2154, '2025-11-20 17:10:39.341492', '2025-11-20 17:10:39.341492', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 353, 8, 'Hoa thiên lý trụng sơ, ngâm nước lạnh, vớt ra, để ráo. Sò điệp trụng chín, tách thịt để riêng. Cà chua bi cắt làm bốn. Cà rốt thái mỏng, trụng sơ. Tỏi thái mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (2155, '2025-11-20 17:10:39.342545', '2025-11-20 17:10:39.342545', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 353, 14, 'Canh thiên lý cua đồng
INSERT INTO public.recipe_steps VALUES (2156, '2025-11-20 17:10:39.344179', '2025-11-20 17:10:39.344179', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 353, 17, 'Cua đồng bóc mai, bỏ yếm, rửa sạch, cho vào một thìa muối, xay nhuyễn. Lọc xác cua với nước sạch qua rây từ 3 đến 4 lần, gạn bỏ cấn để làm nước dùng. Lấy gạch cua từ mai cua, cho chút nước vào lọc vài lần để gạn bỏ hoi và chất bẩn. Hoa thiên lý rửa sạch, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (2157, '2025-11-20 17:10:39.345777', '2025-11-20 17:10:39.345777', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 353, 12, 'Hoa thiên lý trụng chín, ngâm nước lạnh cho xanh, vớt ra, để ráo. Tôm sú luộc chín, bóc vỏ, lấy bỏ chỉ lưng chẻ đôi. Nghêu hấp chín, tách thịt để riêng. Ởt thái chỉ, hành tím thái lát mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (2158, '2025-11-20 17:10:39.346928', '2025-11-20 17:10:39.346928', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 353, 2, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (2159, '2025-11-20 17:10:39.34853', '2025-11-20 17:10:39.34853', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 353, 4, 'Xào thịt bò trên chảo nóng dầu ăn, vừa tái thì thả hành tây vào, trộn đều nhanh tay, vừa chín tái tắt lửa ngay và cho thịt ra tô riêng.', 10);
INSERT INTO public.recipe_steps VALUES (2160, '2025-11-20 17:10:39.350127', '2025-11-20 17:10:39.350127', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 353, 10, 'Gỏi thiên lý nghêu và tôm
INSERT INTO public.recipe_steps VALUES (2161, '2025-11-20 17:10:39.351727', '2025-11-20 17:10:39.351727', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 353, 9, 'Đun nóng dầu, cho tỏi vào phi vàng, cho sò điệp vào đảo nhanh tay. Cho cà rốt, cà chua bi vào xào rồi nêm đường, nước mắm, hạt nêm, cho hoa thiên lý vào xốc đều rồi nêm lại lần nữa cho vừa ăn. Cho ra đĩa, rắc tiêu lên trên dùng nóng.', 10);
INSERT INTO public.recipe_steps VALUES (2162, '2025-11-20 17:10:39.353337', '2025-11-20 17:10:39.353337', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 353, 3, 'Hoa thiên lý giữ nguyên chùm, rửa nhẹ tay trong nước lạnh rồi thả nhanh vào nước sôi, vớt ra, dội nước nguội, để ráo. Thịt bò cắt mỏng ngang thớ, ướp muối, tiêu, đường và tỏi giã nhuyễn, ướp 10-15 phút. Củ hành tây lột bỏ vỏ, cắt mỏng dọc múi cam.', 10);
INSERT INTO public.recipe_steps VALUES (2163, '2025-11-20 17:10:39.490713', '2025-11-20 17:10:39.490713', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 354, 4, 'Cần tây rửa sạch, thái khúc. Ớt xanh, ớt đỏ chín rửa sạch, thái chân hương nhỏ. Gừng thái chỉ. Tỏi khô chiên sơ.', 10);
INSERT INTO public.recipe_steps VALUES (2164, '2025-11-20 17:10:39.492273', '2025-11-20 17:10:39.492273', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 354, 5, 'Cho thịt bò vào âu cùng hành tây, cà rốt, dưa chuột, gừng, ớt xanh, ớt cay, tỏi chiên, gừng và 2 thìa tương ớt, 1 thìa đường, 2 thìa nước chanh, đảo đều để ngấm trong 10 phút. Bày ra đĩa, rắc mùi thơm.', 10);
INSERT INTO public.recipe_steps VALUES (2165, '2025-11-20 17:10:39.494167', '2025-11-20 17:10:39.494167', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 354, 1, 'Bò sơ chế sạch, lọc bỏ gân, xơ, dùng tăm xiên đều khắp mặt miếng thịt, ướp nước gừng, tỏi, gia vị, hạt tiêu, để ngấm khoảng 10 phút. Kẹp thịt vào vỉ nướng chín trên than hoa hoặc cho thịt vào lò nướng hay rán thịt chín để nguội thái con chì.', 10);
INSERT INTO public.recipe_steps VALUES (2166, '2025-11-20 17:10:39.495192', '2025-11-20 17:10:39.495192', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 354, 2, 'Hành tây bổ dọc nhỏ ướp ít muối để ngấm vắt bỏ nước cay.', 10);
INSERT INTO public.recipe_steps VALUES (2167, '2025-11-20 17:10:39.497234', '2025-11-20 17:10:39.497234', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 354, 3, 'Dưa chuột gọt vỏ, lấy cùi thái sợi mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (2168, '2025-11-20 17:10:39.623175', '2025-11-20 17:10:39.623175', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 355, 4, 'Chanh cắt lát.', 10);
INSERT INTO public.recipe_steps VALUES (2169, '2025-11-20 17:10:39.624779', '2025-11-20 17:10:39.624779', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 355, 6, 'Cho thêm dầu ăn vào chảo, cho khoai tây vào xào, nêm thêm gia vị vừa ăn. Múc khoai tây ra đĩa, bày đùi gà lên trên, xếp cà rốt và chanh bên cạnh', 10);
INSERT INTO public.recipe_steps VALUES (2170, '2025-11-20 17:10:39.626351', '2025-11-20 17:10:39.626351', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 355, 3, 'Cà rốt cạo vỏ, thái chỉ to vừa đen chần qua nước sôi cho chín.', 10);
INSERT INTO public.recipe_steps VALUES (2171, '2025-11-20 17:10:39.627429', '2025-11-20 17:10:39.627429', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 355, 5, 'Cho dầu ăn vào chảo đun nóng, cho hành, tỏi khô và phi thơm, cho đùi gà vào rán nhỏ lửa để thịt chín mềm, vàng rồi lấy ra.', 10);
INSERT INTO public.recipe_steps VALUES (2172, '2025-11-20 17:10:39.629078', '2025-11-20 17:10:39.629078', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 355, 2, 'Khoai tay gọt bỏ vỏ, thái miếng vuông nhỏ, đem chần qua nước sôi và ướp với chút bột gà, bột ngọt.', 10);
INSERT INTO public.recipe_steps VALUES (2173, '2025-11-20 17:10:39.63014', '2025-11-20 17:10:39.63014', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 355, 1, 'Ướp thịt gà với hạt nêm, bột ngọt và tỏi, hành bóc vỏ giã nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2174, '2025-11-20 17:10:39.720396', '2025-11-20 17:10:39.720396', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 356, 10, 'Ớt chuông nhồi thịt
INSERT INTO public.recipe_steps VALUES (2175, '2025-11-20 17:10:39.722061', '2025-11-20 17:10:39.722061', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 356, 16, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (2176, '2025-11-20 17:10:39.723119', '2025-11-20 17:10:39.723119', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 356, 9, 'Làm xốt: Trộn đều olive trái, hành tỏi, ớt chuông, sa tế, dầu olive, muối, tiêu. Bắc chảo lên bếp, cho tất cả nguyên liệu vào xào to lửa cho đến khi dậy mùi thơm. Xếp mì Ý ra đĩa, bày hai cây xả và cá lên rồi cho bông cải để bên cạnh, chan xốt ớt lên, 1/2 cá còn lại rải đều trên đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (2177, '2025-11-20 17:10:39.724729', '2025-11-20 17:10:39.724729', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 356, 3, 'Sò điệp ngâm nước lạnh có thả vài lát ớt cho sạch rồi cho vào nồi luộc chín, ướp với chút nước mắm. Hành tây lột vỏ, bổ cau. Ớt vàng, ớt đỏ rửa sạch, bỏ cuống, hạt, xắt dài.', 10);
INSERT INTO public.recipe_steps VALUES (2178, '2025-11-20 17:10:39.726291', '2025-11-20 17:10:39.726291', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 356, 5, 'Cá nướng sốt ớt chuông
INSERT INTO public.recipe_steps VALUES (2179, '2025-11-20 17:10:39.728477', '2025-11-20 17:10:39.728477', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 356, 7, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (2180, '2025-11-20 17:10:39.729528', '2025-11-20 17:10:39.729528', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 356, 2, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (2181, '2025-11-20 17:10:39.731096', '2025-11-20 17:10:39.731096', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 356, 15, 'Ớt chuông xào chay
INSERT INTO public.recipe_steps VALUES (2182, '2025-11-20 17:10:39.733192', '2025-11-20 17:10:39.733192', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 356, 11, 'Thực hiện:', 10);
INSERT INTO public.recipe_steps VALUES (2183, '2025-11-20 17:10:39.734863', '2025-11-20 17:10:39.734863', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 356, 1, 'Sò điệp xào ớt chuông
INSERT INTO public.recipe_steps VALUES (2184, '2025-11-20 17:10:39.736444', '2025-11-20 17:10:39.736444', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 356, 6, '300 g cá điêu hồng xắt phi lê, 1/2 trái ớt chuông đỏ, 50 g bông cải trắng, 50 g bông cải xanh, 2 cây xả, 1 muỗng canh hành khô bằm nhỏ, 1 muỗng cà phê ớt sa tế, 1 muỗng cà phê trái olive bằm nhỏ, 1 muỗng cà phê dầu olive, 100 g mì Ý luộc chín, 1/2 muỗng cà phê ngò tây bằm nhỏ, muối, hạt tiêu, hạt nêm, vỉ nướng.', 10);
INSERT INTO public.recipe_steps VALUES (2185, '2025-11-20 17:10:39.737958', '2025-11-20 17:10:39.737958', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 356, 14, 'Tuỳ theo sở thích, bạn có thể thay thế giò sống bằng thịt nạc vai băm nhỏ. Món ăn vẫn rất ngon và bổ.', 10);
INSERT INTO public.recipe_steps VALUES (2186, '2025-11-20 17:10:39.74024', '2025-11-20 17:10:39.74024', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 356, 12, 'Ớt chuông rửa sạch, xắt đôi khoảng 1/2 trái, giữ lại để làm nắp đậy, dùng dao nhọn moi sạch ruột ớt.', 10);
INSERT INTO public.recipe_steps VALUES (2187, '2025-11-20 17:10:39.741745', '2025-11-20 17:10:39.741745', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 356, 8, 'Cá điêu hồng ướp sơ với chút muối, tiêu rồi đem nướng trên vỉ đến khi chín vàng. Sả cây để nguyên cọng dài chiên sơ. Bông cải xanh, trắng rửa sạch, trụng qua rồi đem xào với ít dầu ăn, nêm chút hạt nêm cho vừa ăn. Ớt chuông đỏ bỏ hạt, bằm nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (2188, '2025-11-20 17:10:39.74275', '2025-11-20 17:10:39.74275', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 356, 4, 'Bắc chảo lên bếp, đun nóng dầu ăn, phi thơm một nửa số tỏi và hành khô, cho sò điệp vào xào, đảo nhanh tay, cho ra đĩa. Phi nốt số tỏi, hành khô còn lại, cho sả, ớt đỏ, ớt vàng vào đảo đều, cho hành tây vào xào đến khi hành chuyển màu hơi trong, nêm hạt nêm vừa miệng, rắc hành tươi, rau răm, cho ra đĩa, rắc tiêu. Ăn nóng.', 10);
INSERT INTO public.recipe_steps VALUES (2189, '2025-11-20 17:10:39.744393', '2025-11-20 17:10:39.744393', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 356, 17, 'Cà rốt rửa sạch, xắt lát mỏng. Cà tím rửa sạch, bổ đôi, xắt miếng vừa. Bông cải trắng, bông cải xanh rửa sạch, xắt miếng vừa ăn. Ớt chuông rửa sạch, bỏ hạt, xắt miếng dài.', 10);
INSERT INTO public.recipe_steps VALUES (2190, '2025-11-20 17:10:39.746906', '2025-11-20 17:10:39.746906', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 356, 18, 'Trụng sơ cà rốt, ớt chuông, bông cải. Bắc chảo lên bếp, cho ít dầu vào đợi nóng cho cà tím vào xào sơ rồi cho ớt chuông, cà rốt, bông cải vào. Nêm nước tương, muối vừa ăn. Rắc mè trắng lên và ăn nóng.', 10);
INSERT INTO public.recipe_steps VALUES (2191, '2025-11-20 17:10:39.749577', '2025-11-20 17:10:39.749577', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 356, 13, 'Giò sống trộn với nước mắm, hạt nêm, tỏi, hành khô, tiêu cho thật đều, nhồi vào trái ớt. Đặt những trái ớt vào xửng hấp (không bỏ phần nắp ớt vào) cho đến khi chín thì lấy ra đĩa, trang trí hành tươi, dùng kèm nước tương.', 10);
INSERT INTO public.recipe_steps VALUES (2192, '2025-11-20 17:10:39.899131', '2025-11-20 17:10:39.899131', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 357, 3, 'Đậu phụ rán vàng, thái miếng con chì.', 10);
INSERT INTO public.recipe_steps VALUES (2193, '2025-11-20 17:10:39.900201', '2025-11-20 17:10:39.900201', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 357, 6, 'Cho mỡ vào chảo phi thơm hành khô, cho thịt ốc vào xào nhanh tay trút ra bát, cho tiếp mỡ vào chảo đổ thịt đã ướp vào xào cho ngấm gia vị, trút ra. Tiếp tục xào chuối cũng như trên. Đổ thịt đã xào cho vào xoong, chế nước sôi ngập thịt đun sôi 10 phút rồi cho tiếp chuối, đậu phụ nêm gia vị, mẻ vừa ăn. Đun tiếp khoảng 5 phút, đến khi chuối mềm, đậu mềm thì trút ốc đã xào vào đun sôi lại và bắc ra, cho hành hoa, tía tô thái nhỏ, múc vào bát.', 10);
INSERT INTO public.recipe_steps VALUES (2194, '2025-11-20 17:10:39.901255', '2025-11-20 17:10:39.901255', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 357, 4, 'Chuối xanh tước vỏ, thái con chì, ngâm trong nước có pha mẻ, sau đó chần qua nước nóng. Nghệ giã lọc lấy nước. Mắm tôm, mẻ lọc lấy nước đặc. Hành hoa, tía tô rửa sạch thái nhỏ 1 cm.', 10);
INSERT INTO public.recipe_steps VALUES (2195, '2025-11-20 17:10:39.902937', '2025-11-20 17:10:39.902937', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 357, 2, 'Thịt ba chỉ cạo rửa sạch, thái miếng con chì.', 10);
INSERT INTO public.recipe_steps VALUES (2196, '2025-11-20 17:10:39.904555', '2025-11-20 17:10:39.904555', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 357, 1, 'Ốc sơ chế sạch.', 10);
INSERT INTO public.recipe_steps VALUES (2197, '2025-11-20 17:10:39.905618', '2025-11-20 17:10:39.905618', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 357, 5, 'Ướp thịt ốc với nước mắm, hạt tiêu, nước nghệ, mẻ, mắm tôm. Thịt ba chỉ rán cháy cạnh ướp tiêu, nước mắm, nước nghệ, mẻ. Đậu phụ ướp như ốc.', 10);
INSERT INTO public.recipe_steps VALUES (2198, '2025-11-20 17:10:39.907195', '2025-11-20 17:10:39.907195', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 357, 7, 'Trình bày hoa ớt trang trí cho đẹp.', 10);
INSERT INTO public.recipe_steps VALUES (2199, '2025-11-20 17:10:40.00024', '2025-11-20 17:10:40.00024', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 358, 2, 'Gừng gọt vỏ, thái mỏng. ả đập dập, chặt khúc.', 10);
INSERT INTO public.recipe_steps VALUES (2200, '2025-11-20 17:10:40.003043', '2025-11-20 17:10:40.003043', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 358, 4, 'Thịt bắp bò chín mềm, vớt ra để nguội, cất tủ dùng dần. Khi ăn thái ngang thớ mỏng, bày ra đĩa. Chấm tương ớt ngọt.', 10);
INSERT INTO public.recipe_steps VALUES (2201, '2025-11-20 17:10:40.005245', '2025-11-20 17:10:40.005245', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 358, 1, 'Bắp bò tách từng khối thớ, ngâm nước, rửa sạch rồi ướp nước mắm, gia vị, hạt tiêu hơi đậm.', 10);
INSERT INTO public.recipe_steps VALUES (2202, '2025-11-20 17:10:40.007366', '2025-11-20 17:10:40.007366', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 358, 3, 'Cho ít dầu vào xoong phi thơm gừng thái mỏng cho khô, cho xả và thịt bò vào cùng. Chế nước xâm xấp mặt thịt, nêm thêm ít nước mắm, đun sôi. Nếm vị mặn hơi đậm, đun om trong khoảng 60 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2203, '2025-11-20 17:10:40.174589', '2025-11-20 17:10:40.174589', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 359, 1, 'Hạt thông băm nhỏ, dưa chuột, cà rốt thái chỉ.', 10);
INSERT INTO public.recipe_steps VALUES (2204, '2025-11-20 17:10:40.176703', '2025-11-20 17:10:40.176703', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 359, 4, 'Lấy ly to (loại ly champain): xếp rau xuống dưới và cho 2 con tôm lên trên, dội sốt lên, ăn nguội.', 10);
INSERT INTO public.recipe_steps VALUES (2205, '2025-11-20 17:10:40.178302', '2025-11-20 17:10:40.178302', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 359, 3, 'Tôm luộc chín, ngâm vào nước sôi để nguội rồi bóc hết vỏ (nhớ giữ lại phần đuôi và đầu cho đẹp).', 10);
INSERT INTO public.recipe_steps VALUES (2206, '2025-11-20 17:10:40.17989', '2025-11-20 17:10:40.17989', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 359, 2, 'Làm sốt: lấy sốt mayonaise cùng hạt thông băm nhỏ + mù tạt trộn đều lên với nhau sau đó cho mạch nha đánh đều với 1/2 quả chanh, rồi cho 1/2 vào sốt trước còn lại sẽ cho nốt khi bày cùng tôm.', 10);
INSERT INTO public.recipe_steps VALUES (2207, '2025-11-20 17:10:40.320867', '2025-11-20 17:10:40.320867', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 360, 6, 'Lần lượt đặt tôm, thịt cua, giò sống, cá thác lác, khoai môn vào 1/2 miếng bánh đa và gập lại, bỏ vào chảo dầu nóng, chiên vàng.', 10);
INSERT INTO public.recipe_steps VALUES (2208, '2025-11-20 17:10:40.322466', '2025-11-20 17:10:40.322466', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 360, 2, 'Tôm luộc chín, bóc vỏ, chẻ đôi bỏ chỉ đen.', 10);
INSERT INTO public.recipe_steps VALUES (2209, '2025-11-20 17:10:40.323507', '2025-11-20 17:10:40.323507', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 360, 5, 'Giò sống, cá thác lác quết thật mịn. Tất cả nêm gia vị vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2210, '2025-11-20 17:10:40.325099', '2025-11-20 17:10:40.325099', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 360, 3, 'Khoai môn gọt sạch, thái chỉ.', 10);
INSERT INTO public.recipe_steps VALUES (2211, '2025-11-20 17:10:40.326831', '2025-11-20 17:10:40.326831', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 360, 4, 'Cua luộc chín gỡ lấy phần thịt.', 10);
INSERT INTO public.recipe_steps VALUES (2212, '2025-11-20 17:10:40.327963', '2025-11-20 17:10:40.327963', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 360, 1, 'Bánh đa (bánh tráng nướng) chọn loại có nhiều mè (vừng) nhúng nước, để ráo, cắt miếng khoảng 15cm x 5cm.', 10);
INSERT INTO public.recipe_steps VALUES (2213, '2025-11-20 17:10:40.444916', '2025-11-20 17:10:40.444916', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 361, 1, 'Vịt làm sạch, chặt đầu, cổ, 2 phần ngoài của cánh, bộ lòng để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (2214, '2025-11-20 17:10:40.445953', '2025-11-20 17:10:40.445953', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 361, 2, 'Khoai gọt vỏ, chẻ làm 2, chiên chín khoảng 70%.', 10);
INSERT INTO public.recipe_steps VALUES (2215, '2025-11-20 17:10:40.447547', '2025-11-20 17:10:40.447547', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 361, 5, 'Cách làm nước chao chấm vịt: 1 muỗng chao + gừng ớt đâm nhuyễn, quậy cho vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2216, '2025-11-20 17:10:40.449214', '2025-11-20 17:10:40.449214', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 361, 7, 'Trụng bún:nước sôi + 1 muỗng muối + hành lá cắt nhuyễn + gừng thái chỉ + bún, đổ ra để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (2217, '2025-11-20 17:10:40.450811', '2025-11-20 17:10:40.450811', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 361, 4, 'Cho dầu ăn (hay mỡ) vào nồi + hành tím bào mỏng vắt nước + gừng đâm nhuyễn, cho vịt vào xào cho nóng + nước chao còn lại và tiếp tục nấu chín 80% mới cho khoai sọ + nước của 2 trái dừa, nấu cho đến khi thịt vịt mềm.', 10);
INSERT INTO public.recipe_steps VALUES (2218, '2025-11-20 17:10:40.451869', '2025-11-20 17:10:40.451869', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 361, 3, '1/2 hũ chao + 2 muỗng bột ngọt + 1 muỗng đường + 1 muỗng tiêu. Dùng hỗn hợp này ướp trong và ngoài con vịt, ướp sơ chừa lại nước chao. Hai chân vịt bẻ chéo ngược lên. Sau đó đem vịt nướng lên rồi chặt miếng.', 10);
INSERT INTO public.recipe_steps VALUES (2219, '2025-11-20 17:10:40.453513', '2025-11-20 17:10:40.453513', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 361, 6, 'Xào rau muống:Rau muống rửa sạch, bỏ bớt lá, trụng qua nước sôi + 1 muỗng dầu ăn, vớt ra để ráo. Cho mỡ vào chảo trắng + 1 muỗng muối + 1 muỗng dầu mè. Lăn tiếp qua bột khô chiên cho giòn vàng.', 10);
INSERT INTO public.recipe_steps VALUES (2220, '2025-11-20 17:10:40.813149', '2025-11-20 17:10:40.813149', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 362, 3, 'Nước cốt chanh + hắc xì dầu + mạch nha + xì dầu, trộn dều thành hỗn hợp.', 10);
INSERT INTO public.recipe_steps VALUES (2221, '2025-11-20 17:10:40.815294', '2025-11-20 17:10:40.815294', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 362, 2, 'Salad rửa sạch, cà rốt tỉa hoa ngâm giấm đường. Ớt một trái tỉa hoa, một trái thái khoanh mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (2222, '2025-11-20 17:10:40.81634', '2025-11-20 17:10:40.81634', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 362, 5, 'Đem gà xối dầu, gà vàng là được, chặt miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2223, '2025-11-20 17:10:40.818008', '2025-11-20 17:10:40.818008', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 362, 1, 'Gà làm sạch, xát muối, rửa sạch, để ráo, ướp bột nêm + gừng, chà xát vào thịt gà, để cho thấm 30 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2224, '2025-11-20 17:10:40.819629', '2025-11-20 17:10:40.819629', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 362, 4, 'Nước luộc gà: Lượng nước phải ngập gà + gừng đập dập + hành tím đập dập + muối + bột ngọt. Nước sôi thả gà vào, nấu cho sôi bùng đậy nắp tắt lửa. Gà mềm vừa vớt ra để ráo, thoa bột năng chà xát vào da gà, thoa tiếp hỗn hợp mạch nha khoảng 2, 3 lần.', 10);
INSERT INTO public.recipe_steps VALUES (2225, '2025-11-20 17:10:40.895992', '2025-11-20 17:10:40.895992', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 363, 8, 'Trộn phần khoai tán nhuyễn này với phần giò sống và hạt nêm. Bọc hỗn hợp giò quanh mình tôm, quấn khoai môn bào sợi xung quanh, rắc ít bột năng quanh cuốn tôm. Bắc chảo dầu lên bếp đun nóng , thả tôm vào chiên vàng rồi vớt ra để lên giấy thấm dầu cho ra đĩa là xong.', 10);
INSERT INTO public.recipe_steps VALUES (2226, '2025-11-20 17:10:40.897055', '2025-11-20 17:10:40.897055', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 363, 11, 'Tôm bóc vỏ, bỏ chỉ lưng, cắt hạt lựu nhỏ. Mực làm sạch, cắt hạt lựu. Cà rốt gọt vỏ, rửa sạch. Đậu que tước xơ, cà chua bỏ hạt. Tất cả cắt hạt lựu nhỏ. Dưa leo rửa sạch, cắt khúc khoảng 5cm, khoét bỏ ruột, tỉa răng cưa quanh mép.', 10);
INSERT INTO public.recipe_steps VALUES (2227, '2025-11-20 17:10:40.898669', '2025-11-20 17:10:40.898669', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 363, 2, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (2228, '2025-11-20 17:10:40.899734', '2025-11-20 17:10:40.899734', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 363, 4, 'Bắc chảo cho dầu vào, dầu sôi cho chả mực vào chiên vàng, vớt ra để lên giấy thấm dầu. Cắt mực thành khoanh, cho ra đĩa rưới ít tương cà lên mặt là có thể cho trẻ thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (2272, '2025-11-20 17:10:42.560725', '2025-11-20 17:10:42.560725', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 372, 2, 'Thịt cá băm ướp với hạt nêm, thì là, ớt, hành khô, gừng khoảng 10 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2229, '2025-11-20 17:10:40.901329', '2025-11-20 17:10:40.901329', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 363, 12, 'Trụng chín tất cả các nguyên liệu (trừ dưa leo), sau đó trộn đều với xốt mayonnaise và xốt tương cà, nhồi vào dưa leo, đem hấp cách thuỷ khoảng 5 phút. Món này trước khi ăn có thể cho vào tủ lạnh để mát.', 10);
INSERT INTO public.recipe_steps VALUES (2230, '2025-11-20 17:10:40.902906', '2025-11-20 17:10:40.902906', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 363, 6, 'Cách làm', 10);
INSERT INTO public.recipe_steps VALUES (2231, '2025-11-20 17:10:40.904519', '2025-11-20 17:10:40.904519', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 363, 5, 'Tôm chiên khoai môn
INSERT INTO public.recipe_steps VALUES (2232, '2025-11-20 17:10:40.90559', '2025-11-20 17:10:40.90559', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 363, 3, 'Trứng gà đánh tan, nêm vào một thìa cà phê hạt nêm. Nhúng thanh chả vào hỗn hợp trứng, rồi lăn qua bột chiên xù.', 10);
INSERT INTO public.recipe_steps VALUES (2233, '2025-11-20 17:10:40.907204', '2025-11-20 17:10:40.907204', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 363, 1, 'Chả mực chiên xù
INSERT INTO public.recipe_steps VALUES (2234, '2025-11-20 17:10:40.908327', '2025-11-20 17:10:40.908327', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 363, 9, 'Hải sản nhồi dưa leo
INSERT INTO public.recipe_steps VALUES (2235, '2025-11-20 17:10:40.909893', '2025-11-20 17:10:40.909893', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 363, 10, 'Cách làm', 10);
INSERT INTO public.recipe_steps VALUES (2236, '2025-11-20 17:10:40.912419', '2025-11-20 17:10:40.912419', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 363, 7, 'Tôm lột vỏ, chừa đuôi, khứa bụng. Khoai môn gọt vỏ, rửa sạch, một nửa bào sợi dài, một nửa luộc chín, tán nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (2237, '2025-11-20 17:10:40.996169', '2025-11-20 17:10:40.996169', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 364, 3, 'Khi ăn chấm với xốt chua ngọt.', 10);
INSERT INTO public.recipe_steps VALUES (2238, '2025-11-20 17:10:40.998263', '2025-11-20 17:10:40.998263', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 364, 1, 'Tôm sú lột vỏ bỏ đầu, chừa đuôi. Trứng gà đập ra tô, đánh bông lên với ít hạt nêm, dừa nạo, bột chiên giòn.', 10);
INSERT INTO public.recipe_steps VALUES (2239, '2025-11-20 17:10:41.00042', '2025-11-20 17:10:41.00042', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 364, 2, 'Nhúng tôm vào hỗn hợp bột mỳ sao cho bám đều cơm dừa, thả vào chảo chiên chín vàng.', 10);
INSERT INTO public.recipe_steps VALUES (2240, '2025-11-20 17:10:41.220468', '2025-11-20 17:10:41.220468', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 365, 6, 'Cơm chín ém vào khuôn chén, xung quanh khung trình bày thịt luộc, rau thơm, trứng, dưa leo, nem chua, thịt nướng. Phía trên phần cơm cho tôm. Khi dùng trộn đều các thứ lại.', 10);
INSERT INTO public.recipe_steps VALUES (2241, '2025-11-20 17:10:41.223155', '2025-11-20 17:10:41.223155', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 365, 2, 'Nạc dăm cắt lát mỏng, ướp hành, tỏi, nước mắm, mè, tiêu, xả băm, nước màu, để khoảng 2 giờ rồi đem nướng.', 10);
INSERT INTO public.recipe_steps VALUES (2242, '2025-11-20 17:10:41.224787', '2025-11-20 17:10:41.224787', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 365, 4, 'Dưa leo cắt mỏng, bóp muối, vắt khô, trộn dầu phi tỏi + chanh + muối + tiêu.', 10);
INSERT INTO public.recipe_steps VALUES (2243, '2025-11-20 17:10:41.226427', '2025-11-20 17:10:41.226427', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 365, 1, 'Gạo vo sạch đem nấu cơm.', 10);
INSERT INTO public.recipe_steps VALUES (2244, '2025-11-20 17:10:41.228042', '2025-11-20 17:10:41.228042', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 365, 3, 'Thịt ba rọi đem luộc cắt sợi. Chả lụa cắt sợi. Trứng vịt chiên xong cũng đem cắt sợi. Nem chua cắt sợi. Tôm bóc vỏ đem tán mịn, cho lên lửa xào cho đến khi khô lại.', 10);
INSERT INTO public.recipe_steps VALUES (2245, '2025-11-20 17:10:41.229656', '2025-11-20 17:10:41.229656', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 365, 5, 'Rau thơm cắt nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (2246, '2025-11-20 17:10:41.435883', '2025-11-20 17:10:41.435883', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 366, 5, 'Đun sôi dầu, thả cá vào chiên xù.', 10);
INSERT INTO public.recipe_steps VALUES (2247, '2025-11-20 17:10:41.437499', '2025-11-20 17:10:41.437499', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 366, 4, 'Rắc bột ngô bám 1 lớp đều, mỏng lên cá. Nhúng cá vào bột mì, cho ra khay. Rắc bánh mì đã xắt nhỏ bám đều lên cá.', 10);
INSERT INTO public.recipe_steps VALUES (2248, '2025-11-20 17:10:41.439096', '2025-11-20 17:10:41.439096', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 366, 3, 'Bánh mì gối thái lát mỏng, xắt hạt lựu. Bột mì hoà cùng 100 ml nước', 10);
INSERT INTO public.recipe_steps VALUES (2249, '2025-11-20 17:10:41.440732', '2025-11-20 17:10:41.440732', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 366, 2, 'Tẩm ướp cá với gia vị, hạt tiêu, muối vừa đủ + lòng trắng trứng', 10);
INSERT INTO public.recipe_steps VALUES (2250, '2025-11-20 17:10:41.441904', '2025-11-20 17:10:41.441904', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 366, 1, 'Cá quả lấy phần phi lê, rửa sạch thấm khô. Dùng dao khía quả trám trên thân cá, lưu ý khía sâu vừa phải, không làm đứt cá, không khía mặt da.', 10);
INSERT INTO public.recipe_steps VALUES (2251, '2025-11-20 17:10:41.645069', '2025-11-20 17:10:41.645069', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 367, 1, 'Gà làm sạch, chà xát muối hạt, chanh khử mùi rồi rửa lại. Nghệ tươi giã dập chà xát lên mình gà để tạo màu cho đẹp.', 10);
INSERT INTO public.recipe_steps VALUES (2252, '2025-11-20 17:10:41.646775', '2025-11-20 17:10:41.646775', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 367, 2, 'Luộc gà cùng chút gừng, hành khô đập dập, muối và hạt nêm trong 7-10 phút, tắt bếp ngâm 15-20 phút tùy vào kích thước gà lớn hay bé. Vớt gà ra, để nguội, lọc phần thịt, cắt hoặc xé nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2253, '2025-11-20 17:10:41.648401', '2025-11-20 17:10:41.648401', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 367, 4, 'Làm nước sốt xì dầu:Phi thơm tỏi, thêm 4 muỗng canh nước luộc gà, 3 muỗng canh nước tương, 2 muỗng canh đường khuấy tan, tắt bếp để nguội thêm 1 muỗng canh nước cốt chanh.', 10);
INSERT INTO public.recipe_steps VALUES (2254, '2025-11-20 17:10:41.649449', '2025-11-20 17:10:41.649449', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 367, 5, 'Làm phở gà trộn xì dầu: Cho bánh phở, thịt gà xé nhỏ, dưa chuột, giá đỗ chần, hành phi, dầu hành lá, rau thơm. Sau đó, rưới nước sốt xì dầu, thêm lạc rang giã dập, trộn đều và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (2255, '2025-11-20 17:10:41.651037', '2025-11-20 17:10:41.651037', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 367, 3, 'Rửa sạch các rau thơm, chần giá đỗ, làm dầu hành phi, lạc rang giã dập, chần qua bánh phở.', 10);
INSERT INTO public.recipe_steps VALUES (2256, '2025-11-20 17:10:41.765296', '2025-11-20 17:10:41.765296', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 368, 5, 'Chuẩn bị các nguyên liệu khác:Miến rửa sạch, ngâm mềm, cắt đôi, chần qua nước sôi hoặc nồi nước dùng, cho vào bát tô. Hành lá và rau thơm rửa sạch, cắt nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2257, '2025-11-20 17:10:41.767436', '2025-11-20 17:10:41.767436', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 368, 4, 'Nước dùng:Vịt nếu lọc xương thì cho xương, chân, cổ cánh vào ninh lấy nước dùng ngọt tự nhiên. Sau đó, vớt ra và nêm thêm chút nước mắm, hạt nêm cho theo khẩu vị. Bạn có thể cho măng vào lúc này (hoặc để riêng cho vào bát khi ăn). Nếu cho măng vào nồi nước dùng thì nên nấu hai lửa (đun sôi, tắt rồi lại đun sôi, tắt) giúp măng ngon và đậm vì hơn.', 10);
INSERT INTO public.recipe_steps VALUES (2273, '2025-11-20 17:10:42.562748', '2025-11-20 17:10:42.562748', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 372, 4, 'Bắc chảo lên bếp, đun nóng dầu ăn, thả cá viên vào chảo dầu chiên chín vàng. Chấm với nước mắm chanh tỏi.', 10);
INSERT INTO public.recipe_steps VALUES (2258, '2025-11-20 17:10:41.769175', '2025-11-20 17:10:41.769175', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 368, 1, 'Sơ chế măng khô: Măng khô rửa sạch, ngâm nước vo gạo qua đêm cho nở, tước nhỏ. Sau đó, luộc măng 3-4 lần cho tới khi măng mềm, nước trong, rửa sạch, để ráo nước. Phi thơm tỏi với chút mỡ lợn, cho măng vào xào, có thể thêm chút nước luộc vịt vào để xào cho ngon hơn, nêm nếm mắm muối, hạt nêm theo khẩu vị, múc ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (2259, '2025-11-20 17:10:41.771303', '2025-11-20 17:10:41.771303', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 368, 2, 'Sơ chế vịt:Vịt làm sạch, cắt bỏ phao câu, chà muối hạt cùng gừng giã nát để một lúc rồi thêm chút rượu chà lần nữa, đổ nước hơi xâm xấp ngâm 15 – 20 phút, rửa sạch cho hết mùi hôi.', 10);
INSERT INTO public.recipe_steps VALUES (2260, '2025-11-20 17:10:41.77291', '2025-11-20 17:10:41.77291', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 368, 6, 'Trình bày và thưởng thức:Cho miến vào tô, xếp thịt vịt, măng, rau mùi tàu, hành lá thái nhỏ và múc nước dùng nóng chan vào. Khi ăn, rắc thêm chút hạt tiêu, giấm ớt và thưởng thức nóng rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (2261, '2025-11-20 17:10:41.775028', '2025-11-20 17:10:41.775028', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 368, 3, 'Cách luộc vịt:Đun nước hơi hơi âm ấm thì cho vịt vào luộc. Thêm gừng, hành khô nướng, chút muối hạt và luộc vịt trên lửa nhỏ, thỉnh thoảng hớt bỏ bọt cho nước trong. Sau 25 – 30 phút tắt bếp, ngâm thêm 10 – 15 phút giúp vịt mọng nước và chín mềm. Vịt chín, vớt ra để nguội, chặt miếng. Nếu nhà có trẻ nhỏ, không thích ăn vịt dính xương thì bạn lọc và thái mỏng miếng thịt.', 10);
INSERT INTO public.recipe_steps VALUES (2262, '2025-11-20 17:10:41.926347', '2025-11-20 17:10:41.926347', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 369, 1, 'Thưởng thức: Xếp ra đĩa, dùng với rau sống và nước mắm pha chua ngọt.', 10);
INSERT INTO public.recipe_steps VALUES (2263, '2025-11-20 17:10:41.927411', '2025-11-20 17:10:41.927411', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 369, 3, 'Bánh tráng trải ra, quyết mực lên, cuộn lại, thả vào chảo dầu, chiên vàng rồi vớt ra, để ráo dầu.', 10);
INSERT INTO public.recipe_steps VALUES (2264, '2025-11-20 17:10:41.929006', '2025-11-20 17:10:41.929006', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 369, 2, 'Mực trộn đều với giò sống, hành tỏi, một muỗng cà phê bột nêm, 1/2 muỗng cà phê tiêu.', 10);
INSERT INTO public.recipe_steps VALUES (2265, '2025-11-20 17:10:42.229431', '2025-11-20 17:10:42.229431', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 370, 4, 'Cho hành tây vào rồi thêm nước mắm đảo đều. Cuối cùng, cho mè + rau húng lủi + hạt điều đập dập + hành phi vào trộn đều lên là được.', 10);
INSERT INTO public.recipe_steps VALUES (2266, '2025-11-20 17:10:42.231001', '2025-11-20 17:10:42.231001', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 370, 2, 'Pha nước mắm gỏi: Lấy bát tô cho chanh dây + chanh giấy + cam sành (lấy một chén nước cốt) + 1 chén đường + 1/2 chén mật ong + 1 chén nước mắm quậy đều lên + ít muối cho ớt + tỏi bằm.', 10);
INSERT INTO public.recipe_steps VALUES (2267, '2025-11-20 17:10:42.232056', '2025-11-20 17:10:42.232056', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 370, 3, 'Cho 5 muỗng súp nước mắm gỏi vào tô + củ sen + cà rốt + thịt ba rọi, trộn đều, ướp khoảng 5 - 10 phút sau đó cho ra để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (2268, '2025-11-20 17:10:42.233639', '2025-11-20 17:10:42.233639', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 370, 1, 'Pha nước dấm: Cho dấm + nước + đường + ít muối + củ cà rốt và củ sen vào ngâm trong bát.', 10);
INSERT INTO public.recipe_steps VALUES (2269, '2025-11-20 17:10:42.383791', '2025-11-20 17:10:42.383791', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 371, 3, 'Tôm sú còn sống rửa sạch nhúng vào nồi thuốc bắc cho chín vớt ra ăn, chấm muối tiêu, xà lách soong. Ăn bao nhiêu nhúng bấy nhiêu.', 10);
INSERT INTO public.recipe_steps VALUES (2270, '2025-11-20 17:10:42.385907', '2025-11-20 17:10:42.385907', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 371, 1, 'Yêu cầu: Nước dùng có mùi thuốc bắc nhẹ, vị ngọt của tôm, giòn của xà lách soong.', 10);
INSERT INTO public.recipe_steps VALUES (2271, '2025-11-20 17:10:42.387504', '2025-11-20 17:10:42.387504', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 371, 2, 'Lấy nước dùng nấu thuốc bắc tiềm gà riu lửa khoảng 1 giờ, nêm muối, bột gà vào (đừng nêm vừa ăn vì tôm hoặc hải sản có chất mặn nên bạn chỉ cần nêm hơi nhạt).', 10);
INSERT INTO public.recipe_steps VALUES (2274, '2025-11-20 17:10:42.564397', '2025-11-20 17:10:42.564397', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 372, 1, 'Cá lóc làm sạch, lọc bỏ da, xương, băm nhỏ. Rau thì là nhặt bỏ gốc, băm nhỏ. Phi vàng hành khô, vớt ra để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (2275, '2025-11-20 17:10:42.565449', '2025-11-20 17:10:42.565449', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 372, 3, 'Viên thịt cá thành những viên tròn dẹt, cho vào lửng tre hấp khoảng 5 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2276, '2025-11-20 17:10:42.665441', '2025-11-20 17:10:42.665441', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 373, 1, 'Yêu cầu thành phẩm: Xôi chín mềm dẻo thơm, khô ráo, hạt đậu đen giữ nguyên hạt nhưng mềm bở bên trong.', 10);
INSERT INTO public.recipe_steps VALUES (2277, '2025-11-20 17:10:42.666476', '2025-11-20 17:10:42.666476', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 373, 7, 'Xôi chín, xới xôi ra đĩa thưởng thức cùng muối vừng, dừa bào sợi hoặc đồ ăn kèm tùy chọn.', 10);
INSERT INTO public.recipe_steps VALUES (2278, '2025-11-20 17:10:42.668122', '2025-11-20 17:10:42.668122', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 373, 5, 'Lót lá dứa dưới đáy nồi cơm điện để tạo mùi thơm và chống bén đáy nồi. Nếu không có lá dứa, bạn có thể lót đáy bằng giấy bạc.', 10);
INSERT INTO public.recipe_steps VALUES (2279, '2025-11-20 17:10:42.669716', '2025-11-20 17:10:42.669716', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 373, 2, 'Gạo nếp vo sạch, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (2280, '2025-11-20 17:10:42.671363', '2025-11-20 17:10:42.671363', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 373, 6, 'Cho gạo nếp và đậu đen vào nồi cơm điện, đổ lượng nước luộc đậu vào xâm xấp mặt gạo nếp và bật chế độ nấu cơm bình thường. Khi sôi, mở vung, dùng đũa đảo nhẹ để hạt nếp ngấm đều và lên màu đẹp mắt. Đậy nồi cơm điện tiếp tục nấu cho tới khi nồi bật sang chế độ warm, để 15 phút nữa là xôi dẻo mềm.', 10);
INSERT INTO public.recipe_steps VALUES (2281, '2025-11-20 17:10:42.67296', '2025-11-20 17:10:42.67296', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 373, 3, 'Đậu đen nhặt bỏ hạt lép, hạt sâu rồi rửa sạch, thêm nước nấu trong 10 phút, chắt lấy nước đậu cho vào ngâm gạo nếp cùng chút muối để lấy màu đẹp cho xôi. Phần hạt đậu, tiếp tục cho vào nồi cùng nước, nấu trên lửa nhỏ vừa cho tới khi hạt đậu mềm.', 10);
INSERT INTO public.recipe_steps VALUES (2282, '2025-11-20 17:10:42.674539', '2025-11-20 17:10:42.674539', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 373, 4, 'Đậu đen chín, vớt ra để ráo nước và se hạt đậu. Nếp vớt ra, để ráo nước. Trộn đều nếp và đậu, thêm 1 thìa canh dầu ăn, 1/2 thìa cà phê muối, đảo nhẹ đều tránh hạt nếp vỡ.', 10);
INSERT INTO public.recipe_steps VALUES (2283, '2025-11-20 17:10:42.823118', '2025-11-20 17:10:42.823118', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 374, 1, 'Cá điêu hồng để nguyên miếng philê, giữ vẩy cá, chiên vàng. Cà chua cắt múi cam, hành lá, thì là cắt nhỏ. Cơm mẻ lược mịn', 10);
INSERT INTO public.recipe_steps VALUES (2284, '2025-11-20 17:10:42.826486', '2025-11-20 17:10:42.826486', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 374, 3, 'Cuối cùng cho mẻ, nước sôi lại là được. Múc ra tô cho hành lá, thì là. Dùng nóng với cơm hay bún, có thể dọn kèm rau xà lách và rau húng cây thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2285, '2025-11-20 17:10:42.830232', '2025-11-20 17:10:42.830232', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 374, 2, 'Nấu nước thật sôi. Xào cà chua, cho vào nước sôi, nêm nếm gia vị vừa ăn (nước mắm, muối, hạt nêm). Cho cá đã chiên vào nấu khoảng 5 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2286, '2025-11-20 17:10:42.958178', '2025-11-20 17:10:42.958178', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 375, 4, 'Lấy lòng đỏ trứng gà đánh tan, nhúng cánh gà rồi lăn qua cốm cho dính đều. Rán vàng hoặc rán cho cốm nở màu trắng là được.', 10);
INSERT INTO public.recipe_steps VALUES (2287, '2025-11-20 17:10:42.959761', '2025-11-20 17:10:42.959761', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 375, 2, 'Cánh gà rửa sạch, lọc lấy xương để dính một đầu. Nấm hương ngâm nở, băm nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2288, '2025-11-20 17:10:42.960823', '2025-11-20 17:10:42.960823', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 375, 1, 'Yêu cầu: Cánh gà không vỡ, thơm mùi cốm.', 10);
INSERT INTO public.recipe_steps VALUES (2289, '2025-11-20 17:10:42.962999', '2025-11-20 17:10:42.962999', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 375, 3, 'Hành khô băm nhỏ trộn lẫn với nấm hương, giò sống, cốm, hạt tiêu rồi nhồi vào cánh gà hấp khoảng 10 phút, lấy ra để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (2290, '2025-11-20 17:10:43.119546', '2025-11-20 17:10:43.119546', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 376, 2, 'Phi thơm hành tím, cho măng vàng, nấm rơm vào, xào thơm. Cho tất cả vào nồi nước cua, nêm nếm vừa ăn. Cho thịt cua vào lại khi ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2291, '2025-11-20 17:10:43.121674', '2025-11-20 17:10:43.121674', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 376, 1, 'Cua đồng làm sạch, xay nhuyễn, lọc qua rây cho sạch xác cua. Cho cua đã lọc sạch vào nồi, nấu sôi với 1,5 lít nước. Chờ khi thịt cua nổi lên, dùng vợt vớt ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (2292, '2025-11-20 17:10:43.122948', '2025-11-20 17:10:43.122948', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 376, 3, 'Dùng nóng với rau sống, bánh đa (hoặc bún) và nước mắm ớt.', 10);
INSERT INTO public.recipe_steps VALUES (2293, '2025-11-20 17:10:43.236832', '2025-11-20 17:10:43.236832', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 377, 2, 'Xiên thịt vào những que tre rồi nướng trên than hồng.', 10);
INSERT INTO public.recipe_steps VALUES (2294, '2025-11-20 17:10:43.238442', '2025-11-20 17:10:43.238442', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 377, 3, 'Làm nước sốt: 300 ml nước cốt dừa và 100 g lạc rang cho vào máy xay nhuyễn. Cho hỗn hợp trên vào nồi, đun sôi, cho tiếp 25 ml dấm, 25 ml nước mắm, tương ớt Thái và 100 g đường (dùng đường mật sẽ ngon hơn) đun tiếp cho đến khi cạn, nước còn sền sệt là được.', 10);
INSERT INTO public.recipe_steps VALUES (2295, '2025-11-20 17:10:43.240585', '2025-11-20 17:10:43.240585', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 377, 1, 'Ướp thịt: Thịt thái thành những miếng dài, ướp cùng hỗn hợp gồm 50 ml nước cốt dừa, 100 g đường, nước mắm, 30 ml nước lọc, bột cà ri, khoảng 3 tiếng.', 10);
INSERT INTO public.recipe_steps VALUES (2296, '2025-11-20 17:10:43.422198', '2025-11-20 17:10:43.422198', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 378, 1, 'Cá nục làm sạch, chà xát nhẹ muối hạt, chanh khử mùi, rửa sạch, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (2297, '2025-11-20 17:10:43.424305', '2025-11-20 17:10:43.424305', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 378, 3, 'Cho 2 muỗng canh đường vào chảo, thêm 2 muỗng canh mỡ lợn hoặc dầu ăn để thắng nước màu trên lửa nhỏ vừa, nhớ lắc đều để đường chảy hết. Khi đường chuyển màu hổ phách thì cho hành tỏi còn lại vào phi thơm, gắp cá ướp vào đảo sơ 1- 2 để bám nước màu vào giúp cá đậm đà và lên màu đẹp hơn.', 10);
INSERT INTO public.recipe_steps VALUES (2298, '2025-11-20 17:10:43.426735', '2025-11-20 17:10:43.426735', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 378, 4, 'Kho lần 1:Lót lá chè xanh hoặc lá ổi dưới đáy nồi đất, xếp cá vào nồi, trút hết phần nước ướp và nước hàng vào. Thêm ớt khô, vỏ hành củ khô (đã rửa sạch) và thêm 1 bát nước sôi xâm xấp bề mặt, kho lửa liu riu cho tới khi gần cạn, tắt bếp, để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (2299, '2025-11-20 17:10:43.428334', '2025-11-20 17:10:43.428334', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 378, 2, 'Giã nhuyễn 1 muỗng canh muối hạt, 4 muỗng canh đường, 1 muỗng canh hạt nêm, 4 củ hành khô, 4 tép tỏi, ớt tươi (nếu thích ăn cay). Sau khi giã, thêm 4 - 5 muỗng canh nước mắm, hạt tiêu khuấy đều cho tan hẳn, rồi cho vào ướp cá, đeo găng tay xoa đều cho thấm gia vị. Để ướp tối thiểu 30 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2300, '2025-11-20 17:10:43.429997', '2025-11-20 17:10:43.429997', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 378, 5, 'Kho lửa lần 2: Thêm nước sôi và bật bếp tiếp tục kho lửa liu riu, nêm nếm lại gia vị theo sở thích. Chú ý khi kho thỉnh thoảng đậy vung, lắc nhẹ nồi để gia vị thấm đều. Khi gần cạn nước, thêm chút mỡ lợn và tóp mỡ vào, rắc thêm hạt tiêu, hành lá, tắt bếp, múc ra đĩa thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (2301, '2025-11-20 17:10:43.520914', '2025-11-20 17:10:43.520914', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 379, 3, 'Cho dầu ăn vào chảo, khi dầu nóng hạ lửa nhỏ vừa và cho hỗn hợp trứng, thịt và lá lốt vào (có thể chia 2 mẻ nhỏ), lắc và dàn đều mặt chảo. Chiên một mặt cho tới khi trứng chín vàng thì dùng muôi lật mặt trứng còn lại và rán vàng mặt dưới. Trứng chín, chuyển qua đĩa và thưởng thức với cơm nóng rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (2302, '2025-11-20 17:10:43.522527', '2025-11-20 17:10:43.522527', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 379, 4, 'Yêu cầu thành phẩm: Bề mặt trứng chiên vàng ươm xen kẽ màu xanh của lá lốt, chút hồng sậm của thịt xay, đặc biệt dậy mùi thơm mộc mạc của lá lốt rất đưa cơm dù bất cứ mùa nào.', 10);
INSERT INTO public.recipe_steps VALUES (2303, '2025-11-20 17:10:43.525185', '2025-11-20 17:10:43.525185', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 379, 1, 'Lá lốt nhặt bỏ lá già, cuống cứng, rửa sạch, thái nhỏ. Hành khô thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2304, '2025-11-20 17:10:43.527282', '2025-11-20 17:10:43.527282', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 379, 2, 'Cho trứng, thịt băm, lá lốt, hành khô vào tô, thêm 2 muỗng cà phê nước mắm, 1/2 muỗng cà phê bột canh, 1 muỗng cà phê hạt nêm, 1/2 muỗng cà phê hạt tiêu, 1 muỗng canh nước lọc rồi đánh đều để gia vị tan, hỗn hợp hòa quyện, không bị vón cục.', 10);
INSERT INTO public.recipe_steps VALUES (2305, '2025-11-20 17:10:43.696333', '2025-11-20 17:10:43.696333', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 380, 3, 'Nấu sôi nước dùng, cho nấm hương vào, nêm hạt nêm vừa ăn. Trút vào tô thịt bò, rắc rau răm lên mặt.', 10);
INSERT INTO public.recipe_steps VALUES (2306, '2025-11-20 17:10:43.698589', '2025-11-20 17:10:43.698589', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 380, 1, 'Thịt bò rửa sạch, thái mỏng. Nấm hương rửa sạch, cắt miếng vừa ăn. Rau răm thái nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (2307, '2025-11-20 17:10:43.700715', '2025-11-20 17:10:43.700715', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 380, 2, 'Phi thơm đầu hành lá với dầu ăn, cho thịt bò vào xào tái với nước tương, trút ra tô.', 10);
INSERT INTO public.recipe_steps VALUES (2308, '2025-11-20 17:10:43.936591', '2025-11-20 17:10:43.936591', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 381, 3, 'Cho tất cả các thành phần rau củ, nụ bạch hoa, gherkin vào tô lớn, nêm thêm muối, tiêu, trộn đều cùng với xốt mayonnaise.', 10);
INSERT INTO public.recipe_steps VALUES (2309, '2025-11-20 17:10:43.938759', '2025-11-20 17:10:43.938759', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 381, 4, 'Khi ăn, cho vào khuôn tròn ấn nhẹ để tạo hình khối đẹp, trang trí với rau củ tỉa hoa.', 10);
INSERT INTO public.recipe_steps VALUES (2310, '2025-11-20 17:10:43.939823', '2025-11-20 17:10:43.939823', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 381, 2, 'Bắc nồi nước lên bếp, cho vào 1/2 thìa cà phê muối, 1/2 thìa cà phê đường, đun sôi, cho cà rốt, khoai tây, đậu Hòa Lan, hạt bắp vào trụng sơ, vớt ra, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (2311, '2025-11-20 17:10:43.942604', '2025-11-20 17:10:43.942604', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 381, 1, 'Khoai tây, cà rốt gọt vỏ, rửa sạch, cắt miếng vuông.', 10);
INSERT INTO public.recipe_steps VALUES (2312, '2025-11-20 17:10:44.067969', '2025-11-20 17:10:44.067969', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 382, 6, 'Trình bày và thưởng thức:Chần phở cho vào mỗi tô, thêm thịt gà, giá đỗ chần, hành chẻ, hành lá xắt nhỏ, rau mùi, chan nước dùng sôi. Rắc thêm chút lá chanh thái chỉ và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (2313, '2025-11-20 17:10:44.069022', '2025-11-20 17:10:44.069022', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 382, 1, 'Chuẩn bị nguyên liệu: Hành tây, hành củ rửa sạch, gừng nướng thơm. Rau mùi nhặt rửa sạch (phần rễ giữ lại rửa sạch cho vào nước dùng cho thơm nếu không có hạt mùi), hành lá rửa sạch (phần gốc trắng chẻ dọc, phần lá xanh cắt nhỏ), lá chanh thái chỉ.', 10);
INSERT INTO public.recipe_steps VALUES (2314, '2025-11-20 17:10:44.070611', '2025-11-20 17:10:44.070611', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 382, 3, 'Luộc gà: Cho gà vào nồi đế dày, đổ nước ngập hoặc tối thiểu 2/3 gà, thêm 2-3 củ hành khô đập dập, 1 nhánh gừng nhỏ, 1 thìa canh muối. Khi sôi, hạ lửa nhỏ vừa luộc gà 10-15 phút rồi tắt bếp, đậy vung om gà 25-30 phút tùy kích thước gà to hay nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2315, '2025-11-20 17:10:44.071669', '2025-11-20 17:10:44.071669', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 382, 2, 'Sơ chế gà: Gà làm sạch, xát muối hạt, chanh rửa sạch. Bóc tách phần mỡ gà ở bụng áp chảo lấy mỡ gà, cho vào chút bột nghệ để phết gà sau khi luộc cho đẹp, hấp dẫn hơn.', 10);
INSERT INTO public.recipe_steps VALUES (2316, '2025-11-20 17:10:44.073282', '2025-11-20 17:10:44.073282', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 382, 4, 'Lọc và thái thịt gà:Gà chín, vớt ra ngâm nước sôi để nguội thêm chút đá lạnh giúp da giòn. Gà nguội, vớt ra thấm khô, phết mỡ gà nghệ để tạo màu vàng ươm đẹp mắt, ​lọc thịt thái thớ mỏng dài theo bề ngang, giữ da sẽ đẹp hơn. Bạn có thể xé thịt tùy theo sở thích.', 10);
INSERT INTO public.recipe_steps VALUES (2317, '2025-11-20 17:10:44.074892', '2025-11-20 17:10:44.074892', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 382, 5, 'Nước dùng: Phần xương gà sau khi lọc cho vào nồi nước dùng ninh tiếp cho ngọt nước. Thêm hành tây nướng, gừng nướng, hạt mùi rang, ninh ở lửa nhỏ, thỉnh thoảng hớt bỏ bọt, mở vung để giúp nước dùng trong hơn. Sau 2 giờ, vớt hết xương, hành, gừng, hạt mùi ra. Nêm nếm lại gia vị mắm, muối, hạt nêm theo khẩu vị. Nếu không có hạt mùi, bạn nên tận dụng rễ rau mùi rửa sạch, cho gần vào khi nước dùng gần đạt để lấy mùi thơm.', 10);
INSERT INTO public.recipe_steps VALUES (2318, '2025-11-20 17:10:44.269881', '2025-11-20 17:10:44.269881', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 383, 5, 'Cam vắt lấy nước, nêm muối, đường, giấm cho có vị chua ngọt, nấu tan cho bột bắp cho hơi sánh, cho vào chút bơ.', 10);
INSERT INTO public.recipe_steps VALUES (2319, '2025-11-20 17:10:44.271488', '2025-11-20 17:10:44.271488', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 383, 2, 'Cà rốt cắt cọng dài bằng chiếc đũa, luộc chín. Trứng gà đánh tan, lá bó xôi luộc sơ ngâm trong nước đá, khoảng năm phút vớt ra vắt ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (2320, '2025-11-20 17:10:44.273129', '2025-11-20 17:10:44.273129', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 383, 4, 'Lăn qua bột mì, nhúng qua trứng gà, lăn tròn qua bột xù, chiên vàng.', 10);
INSERT INTO public.recipe_steps VALUES (2321, '2025-11-20 17:10:44.275259', '2025-11-20 17:10:44.275259', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 383, 1, 'Ức gà lạng thành miếng mỏng lớn, ướp muối, bột nêm cho thấm.', 10);
INSERT INTO public.recipe_steps VALUES (2322, '2025-11-20 17:10:44.276894', '2025-11-20 17:10:44.276894', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 383, 6, 'Gà sau khi chiên xong cắt khoanh trang trí tưới sốt cam xung quanh.', 10);
INSERT INTO public.recipe_steps VALUES (2323, '2025-11-20 17:10:44.278498', '2025-11-20 17:10:44.278498', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 383, 3, 'Đặt lá bó xôi lên miếng gà, cho cọng cà rốt ở giữa, cuốn tròn miếng gà lại gài tăm.', 10);
INSERT INTO public.recipe_steps VALUES (2324, '2025-11-20 17:10:44.61762', '2025-11-20 17:10:44.61762', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 384, 3, 'Nui luộc chín, vớt ra, xốc với bơ cho thơm, trút ra tô hay đĩa sâu lòng, cho thịt bò và nước súp lên, rắc ít ngò cho đẹp.', 10);
INSERT INTO public.recipe_steps VALUES (2325, '2025-11-20 17:10:44.619264', '2025-11-20 17:10:44.619264', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 384, 2, 'Cho cà chua, sữa tươi và 250 ml nước vào nồi nấu sôi, thả thịt bò đã viên vào, nấu nhỏ lửa khoảng 20 phút là chín.', 10);
INSERT INTO public.recipe_steps VALUES (2326, '2025-11-20 17:10:44.62037', '2025-11-20 17:10:44.62037', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 384, 1, 'Trộn thịt bò với hành tây, tỏi, cà rốt, ngò, bột bánh mì khô, muối, đường, viên thành 15 viên nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2327, '2025-11-20 17:10:45.107293', '2025-11-20 17:10:45.107293', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 385, 3, 'Xếp rau sống các loại (tuỳ ý thích) thái nhỏ bên dưới, cho bánh đa, thịt gà, lạc rang, hành phi. Cuối cùng là chan mắm chua ngọt đã pha vừa khẩu vị vào, trộn đều và thường thức.', 10);
INSERT INTO public.recipe_steps VALUES (2328, '2025-11-20 17:10:45.108878', '2025-11-20 17:10:45.108878', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 385, 1, 'Thịt gà luộc chín, cắt miếng vừa ăn. Nước luộc gà nên cho chút hạt nêm, hành và gừng khô đập dập cùng chút hoa hồi, thảo quả.', 10);
INSERT INTO public.recipe_steps VALUES (2329, '2025-11-20 17:10:45.110449', '2025-11-20 17:10:45.110449', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 385, 2, 'Sử dụng nước luộc gà để trần bánh đa cho mềm, vớt ra, cho một chút dầu olive vào để sợi bánh đa không dính vào nhau.', 10);
INSERT INTO public.recipe_steps VALUES (2330, '2025-11-20 17:10:45.250489', '2025-11-20 17:10:45.250489', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 386, 2, 'Cầm vỏ bánh tròn lên tay, cho khoảng 2 thìa nhân thịt vào, chú ý phải để hở khoảng 1 cm mép bánh, để có thể cuộn bánh lại được. Thấm nước lã ở mép miếng vỏ bánh, sau đó gập đôi vỏ bánh lại thành nửa hình tròn, vặn mép bánh theo kiểu xoắn thừng.', 10);
INSERT INTO public.recipe_steps VALUES (2331, '2025-11-20 17:10:45.252634', '2025-11-20 17:10:45.252634', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 386, 3, 'Đổ dầu vào nồi (nên cho nhiều dầu, ngập được bánh) khi nào dầu nóng thì thả bánh vào. Đừng để bếp ở nhiệt độ cao quá, bánh dễ bị cháy đen và nổ. Khi nào thấy bánh rán giòn có màu nâu vàng đều thì vớt ra, mỗi mặt rán khoảng 3 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2332, '2025-11-20 17:10:45.254224', '2025-11-20 17:10:45.254224', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 386, 1, 'Hành tây, củ đậu rửa sạch, thái chỉ rồi cắt nhỏ. Miến, mộc nhĩ ngâm mềm, rửa sạch, để ráo cắt nhỏ, đều. Trộn tất cả nguyên liệu vừa sơ chế với thịt xay trong âu. Cho muối, hạt tiêu vừa ăn. Để trong tủ lạnh cho ngấm đều gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (2333, '2025-11-20 17:10:45.255319', '2025-11-20 17:10:45.255319', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 386, 4, 'Lấy bánh ra ăn nóng chấm với sốt tương ớt hoặc nước mắm pha chanh, đường, tỏi, và ớt.', 10);
INSERT INTO public.recipe_steps VALUES (2334, '2025-11-20 17:10:45.542384', '2025-11-20 17:10:45.542384', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 387, 2, 'Trộn thịt cá, rau mùi, trứng, bột ngô, lá chanh, gừng, hành xanh, mù tạt và bột cà mỳ. Thêm 2 thìa muối tiêu rồi trộn cho thật đều.', 10);
INSERT INTO public.recipe_steps VALUES (2335, '2025-11-20 17:10:45.544027', '2025-11-20 17:10:45.544027', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 387, 3, 'Đun nóng dầu ăn. Nặn hỗn hợp thịt cá thành những miếng tròn dẹt, lăn qua bột cà mỳ một lần nữa sao cho bột bao đều bên ngoài. Cho chả cá vào chảo rán trong vài phút, đến khi chả chín vàng hai mặt là được.', 10);
INSERT INTO public.recipe_steps VALUES (2336, '2025-11-20 17:10:45.545637', '2025-11-20 17:10:45.545637', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 387, 4, 'Cho chả đã chín ra đĩa có giấy thầm dầu. Ăn nóng với xì dầu, tương ớt hoặc nước mắm tỏi.', 10);
INSERT INTO public.recipe_steps VALUES (2337, '2025-11-20 17:10:45.547217', '2025-11-20 17:10:45.547217', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 387, 1, 'Cá lọc bỏ xương, phần thịt thái lát rồi băm hoặc xay nhỏ. Thái nhỏ lá chanh, rau mùi và hành xanh, băm nhỏ gừng.', 10);
INSERT INTO public.recipe_steps VALUES (2338, '2025-11-20 17:10:45.783707', '2025-11-20 17:10:45.783707', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 388, 7, 'Chiên gà: Nên chiên 2 lần: Đun nóng dầu ở trên, hạ lửa vừa, cho gà vào chiên 2-3 phút, vớt ra, để nguội. Tiếp tục đun nóng dầu ăn, chia các mẻ, cho gà vào chiên nhanh để tách dầu và giúp gà giòn rụm. Khi gà vàng giòn, vớt ra để giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (2339, '2025-11-20 17:10:45.784776', '2025-11-20 17:10:45.784776', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 388, 3, 'Đùi gà lọc xương, ngâm nước muối ấm loãng, vắt thêm ít chanh khử mùi, rồi rửa sạch, để ráo nước. Cắt miếng vuông vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2340, '2025-11-20 17:10:45.786347', '2025-11-20 17:10:45.786347', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 388, 2, 'Lá húng quế nhặt, rửa sạch, để ráo nước hoặc thấm khô.', 10);
INSERT INTO public.recipe_steps VALUES (2341, '2025-11-20 17:10:45.788063', '2025-11-20 17:10:45.788063', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 388, 4, 'Ướp gà với: 1 muỗng canh xì dầu, 1 muỗng canh đường, 1/2 muỗng cà phê muối, 1 muỗng cà phê dầu mè, 1 muỗng cà phê ngũ vị hương, 1/2 muỗng cà phê hạt tiêu, 1 quả trứng và tỏi, gừng băm nhuyễn. Đeo găng tay trộn đều để gà thấm gia vị, ướp tối thiểu 30 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2342, '2025-11-20 17:10:45.789187', '2025-11-20 17:10:45.789187', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 388, 5, 'Bao áo bột cho gà: Chia đôi hỗn hợp bột chiên giòn: 1/2 cho vào bát ướp gà trộn đều. 1/2 số bột còn lại cho vào túi zip hoặc vào đĩa. Gắp từng miếng gà lăn qua bột khô để bao áo bột xung quanh.', 10);
INSERT INTO public.recipe_steps VALUES (2343, '2025-11-20 17:10:45.790786', '2025-11-20 17:10:45.790786', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 388, 1, 'Yêu cầu thành phẩm: Vỏ ngoài giòn rụm, thịt bên trong mềm ngọt, hài hòa các vị cay mặn ngọt, dậy mùi thơm của lá húng quế rất hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (2344, '2025-11-20 17:10:45.792432', '2025-11-20 17:10:45.792432', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 388, 6, 'Chiên lá húng quế: Rắc một lớp bột chiên giòn lên lá húng quế. Cho dầu vào chảo sâu lòng, đun nóng, khi thử đầu đũa sủi tăm thì hạ lửa nhỏ vừa và cho lá húng quế vào chiên giòn, vớt ra giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (2345, '2025-11-20 17:10:45.793487', '2025-11-20 17:10:45.793487', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 388, 9, 'Cho gà chiên vào hộp rồi cho gia vị rắc vào xóc đều cho thấm gia vị. Thêm lá húng quế chiên và cho ra đĩa thưởng thức cùng tương ớt.', 10);
INSERT INTO public.recipe_steps VALUES (2346, '2025-11-20 17:10:45.795095', '2025-11-20 17:10:45.795095', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 388, 8, 'Gia vị rắc gà: 1 muỗng cà phê muối biển mịn, 1 muỗng cà phê ngũ vị hương, 1/2 muỗng cà phê hạt tiêu trắng xay. Cho lên chảo rang thơm, tắt bếp, để nguội, thêm bột ớt (điều chỉnh loại cay theo khẩu vị), trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (2347, '2025-11-20 17:10:46.027089', '2025-11-20 17:10:46.027089', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 389, 2, 'Sau đó đem kẹp những thức trên trong vỉ, nướng chín vừa trên than lửa mạnh (thịt bò không nên nướng quá lâu).', 10);
INSERT INTO public.recipe_steps VALUES (2348, '2025-11-20 17:10:46.028157', '2025-11-20 17:10:46.028157', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 389, 4, 'Bò và rau củ sau khi nướng xong đặt vào đĩa đã sắp sẵn xà lách, cà chua.', 10);
INSERT INTO public.recipe_steps VALUES (2349, '2025-11-20 17:10:46.029215', '2025-11-20 17:10:46.029215', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 389, 3, 'Hành lá thái cho vào chén, thêm chút muối, (và bột ngọt nếu thích), cho một muỗng dầu nóng chế vào hành trộn điều.', 10);
INSERT INTO public.recipe_steps VALUES (2350, '2025-11-20 17:10:46.030248', '2025-11-20 17:10:46.030248', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 389, 1, 'Bò thái lát mỏng trộn cùng cà tím, đậu bắp ướp chao, đường, bột gà, một muỗng dầu ăn tiêu xay, tỏi bằm khoảng 10 phút', 10);
INSERT INTO public.recipe_steps VALUES (2351, '2025-11-20 17:10:46.031781', '2025-11-20 17:10:46.031781', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 389, 5, 'Chan dầu hành lên bò, rắc đều đậu phộng lên trên. Món này dùng nóng chấm muối tiêu chanh.', 10);
INSERT INTO public.recipe_steps VALUES (2352, '2025-11-20 17:10:46.173075', '2025-11-20 17:10:46.173075', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 390, 2, 'Xếp một lớp chè, một lớp riềng, một lớp gừng rồi xếp cá lên trên cho kín nồi rồi lại một lớp giềng và gừng trên bề mặt.', 10);
INSERT INTO public.recipe_steps VALUES (2353, '2025-11-20 17:10:46.174212', '2025-11-20 17:10:46.174212', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 390, 5, 'Dùng nước chè đã hãm dội vào nồi, sâm sấp mặt cá rồi cứ đun vậy cho sôi, vặn thật nhỏ lửa, đun liu riu cho đến khi cạn nước, cá có màu cánh gián là được.', 10);
INSERT INTO public.recipe_steps VALUES (2354, '2025-11-20 17:10:46.176315', '2025-11-20 17:10:46.176315', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 390, 1, 'Rửa sạch cá, cắt khúc dày. Riềng và gừng rửa sạch đem cắt lát mỏng. Chè tươi rửa sạch, một nửa xếp xuống đáy nồi, một nửa đem hãm nước.', 10);
INSERT INTO public.recipe_steps VALUES (2355, '2025-11-20 17:10:46.177941', '2025-11-20 17:10:46.177941', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 390, 3, 'Lấy chừng 2 thìa đường lớn vào một chảo nhỏ, cứ thế đảo đến khi đường chảy chuyển sang màu cánh gián rồi dội lên bề mặt cá.', 10);
INSERT INTO public.recipe_steps VALUES (2356, '2025-11-20 17:10:46.179563', '2025-11-20 17:10:46.179563', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 390, 4, 'Cho nước mắm vào bát (chừng nửa tô ) + bột nêm + 1/2 thìa đường rồi khuấy đều cho tan và dội lên bề mặt cá, cho lên bếp đun chừng 5 phút cho cá ngấm mắm muối, trong khi đun nghiêng nồi cho nước mắm ngấm đều cá.', 10);
INSERT INTO public.recipe_steps VALUES (2357, '2025-11-20 17:10:46.445096', '2025-11-20 17:10:46.445096', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 391, 2, 'Trộn khoai tây nghiền với nửa thìa cà phê muối và 2 thìa cà phê hạt nêm. Chia khoai thành nhiều phần nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2358, '2025-11-20 17:10:46.446154', '2025-11-20 17:10:46.446154', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 391, 4, 'Lăn bánh qua bột mì, rồi thả vào chảo chiên vàng mặt, vớt ra cho vào giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (2359, '2025-11-20 17:10:46.447741', '2025-11-20 17:10:46.447741', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 391, 1, 'Bắc chảo lên bếp, cho vào 4 thìa súp dầu ăn, cho củ hành băm vào phi thơm vàng, rồi cho thịt bò băm vào xào trên lửa lớn cho chín. Khi thịt ráo nước cho tiếp nho khô và ngò rí vào, nêm 2 thìa cà phê hạt nêm, trộn đều, tắt bếp. Múc nhân ra tô và để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (2360, '2025-11-20 17:10:46.449317', '2025-11-20 17:10:46.449317', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 391, 3, 'Thoa một ít bột mì vào lòng bàn tay. Múc khoai nghiền cho vào lòng bàn tay, ép dẹp, rồi múc nhân cho vào giữa, gói lại, vo tròn và ép hơi dẹp cho dễ chiên.', 10);
INSERT INTO public.recipe_steps VALUES (2361, '2025-11-20 17:10:46.730316', '2025-11-20 17:10:46.730316', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 392, 2, 'Cho thịt vịt vào chảo, lật phần da xuống áp chảo. Ở bước này bạn có thể không cần cho dầu ăn để phần da vịt đỡ béo. Rán vịt ở mức lửa trung bình đến khi chuyển màu vàng.', 10);
INSERT INTO public.recipe_steps VALUES (2362, '2025-11-20 17:10:46.732447', '2025-11-20 17:10:46.732447', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 392, 1, 'Thịt vịt làm sạch, chặt miếng và chần qua nước sôi. Khoai tây gọt vỏ, cắt miếng vuông rồi ngâm nước cho khỏi thâm.', 10);
INSERT INTO public.recipe_steps VALUES (2363, '2025-11-20 17:10:46.734568', '2025-11-20 17:10:46.734568', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 392, 4, 'Cho một thìa đường và một chai bia vào chảo vịt. Cho khoai tây vào, đun sôi sau đó để nhỏ lửa, đậy vung om trong khoảng 40 - 50 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2364, '2025-11-20 17:10:46.736147', '2025-11-20 17:10:46.736147', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 392, 5, 'Nêm nếm lại gia vị cho vừa ăn, thử thấy khoai và vịt chín mềm là được.', 10);
INSERT INTO public.recipe_steps VALUES (2365, '2025-11-20 17:10:46.738283', '2025-11-20 17:10:46.738283', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 392, 3, 'Cho ớt khô, lá quế, hạt tiêu, gừng vào xào chung với thịt. Tiếp đến cho xì dầu, 2 thìa muối và đảo liên tục đến khi thịt vịt vàng đều.', 10);
INSERT INTO public.recipe_steps VALUES (2366, '2025-11-20 17:10:46.964924', '2025-11-20 17:10:46.964924', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 393, 7, 'Múc ra tô, cho hành ngò lên trên.', 10);
INSERT INTO public.recipe_steps VALUES (2367, '2025-11-20 17:10:46.967036', '2025-11-20 17:10:46.967036', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 393, 5, 'Cho củ cải vào nồi có nước dùng gà, hầm cho đến khi củ cải mềm. Thỉnh thoảng vớt bọt bỏ đi. Nêm vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2368, '2025-11-20 17:10:46.968597', '2025-11-20 17:10:46.968597', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 393, 6, 'Thử bằng cách châm tăm vào, tăm xuyên qua củ cải trắng là được.', 10);
INSERT INTO public.recipe_steps VALUES (2369, '2025-11-20 17:10:46.970753', '2025-11-20 17:10:46.970753', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 393, 2, 'Thịt gà cắt nhỏ vừa cho dễ xay. Hành hương thái mỏng, phi với dầu cho thơm. Tỏi lột vỏ sạch. Hành ngò cắt nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2370, '2025-11-20 17:10:46.972867', '2025-11-20 17:10:46.972867', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 393, 4, 'Dùng muỗng múc hỗn hợp nhét vào củ cải trắng.', 10);
INSERT INTO public.recipe_steps VALUES (2371, '2025-11-20 17:10:46.974593', '2025-11-20 17:10:46.974593', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 393, 3, 'Xay nhuyễn: thịt, tỏi, hành hương phi dầu, một chút tiêu, muối, lòng trắng trứng.', 10);
INSERT INTO public.recipe_steps VALUES (2372, '2025-11-20 17:10:46.976687', '2025-11-20 17:10:46.976687', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 393, 1, 'Củ cải trắng gọt vỏ sạch, khoét một lỗ tròn sâu vào củ cải, ngâm vào nước lạnh có pha một tí muối.', 10);
INSERT INTO public.recipe_steps VALUES (2373, '2025-11-20 17:10:47.090629', '2025-11-20 17:10:47.090629', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 394, 2, 'Trộn đều thịt heo và râu mực với bún tàu và nấm mèo đã cắt nhuyễn. Nêm thêm tiêu, bột nêm, và dầu ăn trong khi trộn.', 10);
INSERT INTO public.recipe_steps VALUES (2374, '2025-11-20 17:10:47.092216', '2025-11-20 17:10:47.092216', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 394, 1, 'Mực mua về rửa sạch và tách ống mực ra khỏi đầu mực. Bằm nhuyễn râu mực (nếu có).', 10);
INSERT INTO public.recipe_steps VALUES (2375, '2025-11-20 17:10:47.093801', '2025-11-20 17:10:47.093801', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 394, 4, 'Cho mực vào nồi hấp cách thủy trong vòng 20-25 phút đến khi chín đều rồi đem chiên sơ từng con mực trên bếp dầu để da săn lại.', 10);
INSERT INTO public.recipe_steps VALUES (2376, '2025-11-20 17:10:47.094865', '2025-11-20 17:10:47.094865', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 394, 3, 'Dồn thịt vào từng ống mực sau khi đã trộn đều hỗn hợp thịt.', 10);
INSERT INTO public.recipe_steps VALUES (2377, '2025-11-20 17:10:47.097001', '2025-11-20 17:10:47.097001', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 394, 5, 'Nếu ăn với sốt cà chua, bạn nên trộn mực vào chung với nước sốt khi gần xong để thấm đều.', 10);
INSERT INTO public.recipe_steps VALUES (2378, '2025-11-20 17:10:47.229701', '2025-11-20 17:10:47.229701', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 395, 1, 'Món này mát, vị ngọt nhẹ tự nhiên lại thêm mùi thơm cay của gừng rất dễ chịu, giúp bạn tránh bị cảm hoặc đỡ mệt mỏi trong tiết trời giao mùa này.', 10);
INSERT INTO public.recipe_steps VALUES (2379, '2025-11-20 17:10:47.231817', '2025-11-20 17:10:47.231817', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 395, 5, 'Khi mướp mềm thì cho tôm trở lại chảo, nếu món xào hơi nhiều nước bạn có thể hòa chút bột đao, cho từ từ vào để nước sánh vừa phải. Nêm nếm lại cho vừa khẩu vị của bạn rồi tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (2380, '2025-11-20 17:10:47.233996', '2025-11-20 17:10:47.233996', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 395, 4, 'Đặt chảo trở lại bếp, thêm chút dầu ăn. Khi dầu nóng cho gừng vào đảo, gừng thơm thì cho mướp vào xào, để to lửa, đảo nhanh tay để mướp không ra nhiều nước. Nêm một chút gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (2381, '2025-11-20 17:10:47.235571', '2025-11-20 17:10:47.235571', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 395, 2, 'Tôm bỏ đầu, bóc vỏ và bỏ chỉ đen ở lưng tôm. Cho tôm vào bát ướp một chút gia vị cho ngấm. Nạo vỏ mướp và cắt miếng hơi dầy một chút. Gừng rửa sạch thái chỉ.', 10);
INSERT INTO public.recipe_steps VALUES (2382, '2025-11-20 17:10:47.237147', '2025-11-20 17:10:47.237147', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 395, 3, 'Đặt chảo lên bếp, đun nóng một chút dầu ăn rồi cho tôm vào xào. Khi thấy tôm bắt đầu chín, chuyển màu hồng thì đổ tôm ra bát.', 10);
INSERT INTO public.recipe_steps VALUES (2383, '2025-11-20 17:10:47.559864', '2025-11-20 17:10:47.559864', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 396, 1, 'Ức gà (hoặc đùi gà) cắt thành miếng mỏng vừa ăn, ướp với một muỗng xúp dầu hào, 1/2 muỗng xúp hành tím băm, 1/2 muỗng cà phê muối tiêu, 1/2 muỗng cà phê đường, 1/2 muỗng cà phê dầu mè đen.', 10);
INSERT INTO public.recipe_steps VALUES (2384, '2025-11-20 17:10:47.560916', '2025-11-20 17:10:47.560916', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 396, 3, 'Nấm đông cô ngâm nước cho mềm, cắt bỏ gốc rễ, cắt miếng nhỏ hoặc nấm rơm làm sạch, cắt mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (2385, '2025-11-20 17:10:47.56198', '2025-11-20 17:10:47.56198', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 396, 5, 'Vo gạo, cho vào thố nấu với nước dừa tươi ngọt vừa đủ + 1/2 muỗng cà phê muối + một muỗng bột nêm, canh chừng nước cạn vừa sấp mặt gạo, trút phần gà xào vào nồi cơm, không trộn lên, đậy nắp, hạ lửa nấu tiếp cho cơm chín.', 10);
INSERT INTO public.recipe_steps VALUES (2386, '2025-11-20 17:10:47.563567', '2025-11-20 17:10:47.563567', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 396, 2, 'Lòng gà làm sạch, gan mề cắt nhỏ, ruột non cắt khúc.', 10);
INSERT INTO public.recipe_steps VALUES (2387, '2025-11-20 17:10:47.565158', '2025-11-20 17:10:47.565158', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 396, 4, 'Làm nóng hai muỗng xúp dầu ăn hoặc mỡ nước gà, phi thơm với hai tép hành tím đập dập, cho thịt gà, lòng và nấm vào xào chín, cho vào một vá nhỏ nước sôi để thịt không quá khô, nêm lại tùy ý cho đậm đà.', 10);
INSERT INTO public.recipe_steps VALUES (2388, '2025-11-20 17:10:47.5662', '2025-11-20 17:10:47.5662', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 396, 6, 'Dọn nguyên thố cơm nóng, mở nắp, trải hành gừng lên, rắc thêm ít tiêu bột.', 10);
INSERT INTO public.recipe_steps VALUES (2389, '2025-11-20 17:10:47.568329', '2025-11-20 17:10:47.568329', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 396, 7, 'Khi ăn trộn đều, kèm ớt tươi, đu đủ xanh, dưa leo cắt mỏng ngâm giấm đường, xì dầu.', 10);
INSERT INTO public.recipe_steps VALUES (2390, '2025-11-20 17:10:47.660078', '2025-11-20 17:10:47.660078', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 397, 5, 'Cho ra bát ăn nóng với cơm.', 10);
INSERT INTO public.recipe_steps VALUES (2391, '2025-11-20 17:10:47.661678', '2025-11-20 17:10:47.661678', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 397, 3, 'Đặt chảo lên bếp, đun nóng một ít dầu ăn, cho hành thái nhỏ và gừng, tỏi vào phi thơm. Cho sa tế vào đảo qua cho nóng rồi cho tiếp cánh gà vào chảo.', 10);
INSERT INTO public.recipe_steps VALUES (2392, '2025-11-20 17:10:47.663274', '2025-11-20 17:10:47.663274', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 397, 2, 'Cánh gà cắt thành từng miếng (cắt ở các chỗ khớp). Cho gà vào nồi, thêm một chút muối, gừng, đổ nước vừa ngập rồi đun trong 10 phút. Tắt bếp, vớt gà ra.', 10);
INSERT INTO public.recipe_steps VALUES (2393, '2025-11-20 17:10:47.664305', '2025-11-20 17:10:47.664305', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 397, 4, 'Nêm một thìa đường, một thìa xì dầu, một thìa muối tiêu, đảo đều đến khi thịt gà ngấm và da gà bắt đầu chín vàng, cho tiếp ớt chuông xanh vào. Đảo thêm 2 phút rồi tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (2394, '2025-11-20 17:10:47.66596', '2025-11-20 17:10:47.66596', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 397, 1, 'Ớt xanh thái miếng, hành thái nhỏ, gừng và tỏi băm nhỏ để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (2395, '2025-11-20 17:10:47.667004', '2025-11-20 17:10:47.667004', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 397, 6, 'Nếu nhà bạn có trẻ nhỏ hoặc người không ăn được cay thì bạn có thể bớt phần sa tế đi.', 10);
INSERT INTO public.recipe_steps VALUES (2396, '2025-11-20 17:10:47.760099', '2025-11-20 17:10:47.760099', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 398, 2, 'Sả tước nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2397, '2025-11-20 17:10:47.761662', '2025-11-20 17:10:47.761662', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 398, 4, 'Cho sả vào chảo vừa chiên sườn, để một lúc cho sả vàng thì vớt ra. Tắt bếp, chắt dầu trong chảo vào bát con.', 10);
INSERT INTO public.recipe_steps VALUES (2398, '2025-11-20 17:10:47.762702', '2025-11-20 17:10:47.762702', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 398, 5, 'Đổ sườn, sả cùng khoảng 3 thìa canh muối vào chảo, xóc đều lên để sườn thấm muối.', 10);
INSERT INTO public.recipe_steps VALUES (2399, '2025-11-20 17:10:47.764272', '2025-11-20 17:10:47.764272', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 398, 6, 'Cho sườn ra đĩa, dùng nóng, chấm muối chanh ớt hoặc tương ớt tuỳ thích.', 10);
INSERT INTO public.recipe_steps VALUES (2400, '2025-11-20 17:10:47.765841', '2025-11-20 17:10:47.765841', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 398, 1, 'Sườn chặt miếng vừa ăn, rửa sạch, cho vào luộc qua một lần nước rồi đổ nước đi, rửa lại sườn.', 10);
INSERT INTO public.recipe_steps VALUES (2401, '2025-11-20 17:10:47.766871', '2025-11-20 17:10:47.766871', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 398, 3, 'Cho dầu vào chảo, đun nóng dầu thì thả sườn vào chiên. Đến khi sườn vàng gắp ra đĩa có lót giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (2402, '2025-11-20 17:10:47.878895', '2025-11-20 17:10:47.878895', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 399, 4, 'Phi thơm hành khô, cho cánh gà xào qua cho thơm. Cho nước dùng nêm vừa ăn cho nấm hương đun sôi hớt bọt vặn nhỏ lửa đun cho gà mềm. Khi gà mềm cho hạt sen, hành hoa, cà rốt tỉa con giống. Múc bày vào bát, rắc rau mùi.', 10);
INSERT INTO public.recipe_steps VALUES (2403, '2025-11-20 17:10:47.881193', '2025-11-20 17:10:47.881193', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 399, 1, 'Cánh gà sơ chế sạch, cắt bỏ đầu cánh ướp với gia vị, hạt nêm, hạt tiêu, một chút đường (nước hàng), đem rán vàng để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (2404, '2025-11-20 17:10:47.882777', '2025-11-20 17:10:47.882777', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 399, 2, 'Nấm hương ngâm mềm cắt bỏ chân, hành hoa cắt dài 3 cm (lấy phần gốc). Hạt sen ninh bở. Hành khô thái mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (2405, '2025-11-20 17:10:47.884363', '2025-11-20 17:10:47.884363', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 399, 3, 'Gừng thái mỏng rán qua (nướng). Cà rốt tỉa hình con giống thái mỏng vừa.', 10);
INSERT INTO public.recipe_steps VALUES (2406, '2025-11-20 17:10:47.987238', '2025-11-20 17:10:47.987238', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 400, 4, 'Cho thịt kho ra đĩa, rắc 1/3 muỗng cà phê tiêu, ớt lên.', 10);
INSERT INTO public.recipe_steps VALUES (2407, '2025-11-20 17:10:47.98882', '2025-11-20 17:10:47.98882', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 400, 1, 'Thịt nạc rửa sạch, thái miếng dày 0,5 cm, ướp 2 muỗng cà phê hạt nêm, một muỗng cà phê đường, 2 muỗng súp nước mắm, 1/2 muỗng cà phê muối, 1/2 muỗng cà phê tiêu.', 10);
INSERT INTO public.recipe_steps VALUES (2408, '2025-11-20 17:10:47.990417', '2025-11-20 17:10:47.990417', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 400, 3, 'Phi thơm tỏi băm với 1,5 muỗng súp dầu ăn. Cho thịt vào đảo đều, khi thịt săn lại cho nấm rơm vào kho. Nêm 2 muỗng súp tương ớt, 1/2 muỗng súp nước mắm, 1/2 muỗng cà phê đường. Kho thêm 5 phút, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (2409, '2025-11-20 17:10:47.992033', '2025-11-20 17:10:47.992033', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 400, 2, 'Nấm rơm cắt chân, ngâm nước muối pha loãng, rửa sạch bằng nước sạch. Nấm nhỏ để nguyên, nấm lớn chẻ đôi. Ớt sừng thái khoanh.', 10);
INSERT INTO public.recipe_steps VALUES (2410, '2025-11-20 17:10:48.178334', '2025-11-20 17:10:48.178334', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 401, 3, 'Rửa ngao, ngâm và dùng bàn chải cọ sạch vỏ rồi để ngao vào rổ cho ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (2411, '2025-11-20 17:10:48.179649', '2025-11-20 17:10:48.179649', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 401, 2, 'Ớt rửa sạch, cắt dọc quả ớt bỏ hết hạt, nếu bạn không ăn được cay thì có thể thay ớt này bằng ớt chuông.', 10);
INSERT INTO public.recipe_steps VALUES (2412, '2025-11-20 17:10:48.180709', '2025-11-20 17:10:48.180709', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 401, 1, 'Món này ăn nóng mới ngon.', 10);
INSERT INTO public.recipe_steps VALUES (2413, '2025-11-20 17:10:48.1823', '2025-11-20 17:10:48.1823', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 401, 4, 'Đặt chảo lên bếp, đun nóng dầu ăn, cho tỏi và ớt vào phi thơm.', 10);
INSERT INTO public.recipe_steps VALUES (2414, '2025-11-20 17:10:48.183358', '2025-11-20 17:10:48.183358', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 401, 5, 'Tiếp đến cho ngào vào xào, nước từ con ngao sẽ bắt đầu chảy ra. Đảo đến khi ngao mở miệng hết (thường đun khoảng 3- 4 phút với lửa to là ngao mở miệng).', 10);
INSERT INTO public.recipe_steps VALUES (2415, '2025-11-20 17:10:48.184983', '2025-11-20 17:10:48.184983', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 401, 7, 'Cuối cùng cho rau húng vào, đảo đều một lần nữa rồi tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (2416, '2025-11-20 17:10:48.186644', '2025-11-20 17:10:48.186644', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 401, 6, 'Cho nước mắm, đường và tiếp đục đảo để thịt ngao ngấm gia vị. Lưu ý vì vị ngao đã mặn sẵn nên lượng nước mắm có thể bớt đi tùy khẩu vị của bạn.', 10);
INSERT INTO public.recipe_steps VALUES (2417, '2025-11-20 17:10:48.32534', '2025-11-20 17:10:48.32534', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 402, 1, 'Sườn lợn rửa sạch, chặt khúc vừa miệng. Hành lá rửa sạch, tước sợi. Hành tây thái lát mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (2418, '2025-11-20 17:10:48.32691', '2025-11-20 17:10:48.32691', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 402, 4, 'Để món ăn thơm ngon hơn, khi cho phần bia còn lại vào, bạn không nên hấp lâu, chỉ cần vừa nóng thì tắt bếp ngay. Trang trí thêm hành lá cho món ăn thêm hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (2419, '2025-11-20 17:10:48.328538', '2025-11-20 17:10:48.328538', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 402, 3, 'Rán sườn cho chín vàng hai mặt. Cho sườn ra đĩa, đổ nửa phần bia vào cùng với khoai tây, hấp trong 20 phút. Khi gần ăn, cho nốt phần bia còn lại vào hấp nóng.', 10);
INSERT INTO public.recipe_steps VALUES (2420, '2025-11-20 17:10:48.329591', '2025-11-20 17:10:48.329591', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 402, 2, 'Ướp sườn với hạt nêm, đường, tiêu khoảng 10 phút cho ngấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (2421, '2025-11-20 17:10:48.537188', '2025-11-20 17:10:48.537188', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 403, 6, 'Cho dưa chuột, cà rốt, lá hẹ vào âu trộn, đổ nước sốt hỗn hợp trên vào, đeo găng tay trộn đều và để khoảng 10 phút cho ngấm gia vị, thêm chút dầu mè đảo đều, rắc vừng rang và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (2422, '2025-11-20 17:10:48.538242', '2025-11-20 17:10:48.538242', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 403, 4, 'Táo tây gọt vỏ, hành tây xắt nhỏ, tỏi bóc bỏ vỏ, gừng cạo vỏ, cho vào xay nhuyễn cùng chút nước.', 10);
INSERT INTO public.recipe_steps VALUES (2423, '2025-11-20 17:10:48.539874', '2025-11-20 17:10:48.539874', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 403, 3, 'Cà rốt gọt bỏ vỏ, bào sợi, trộn chút đường.', 10);
INSERT INTO public.recipe_steps VALUES (2424, '2025-11-20 17:10:48.541471', '2025-11-20 17:10:48.541471', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 403, 2, 'Hẹ rửa sạch, cắt khúc 3 - 4 cm.', 10);
INSERT INTO public.recipe_steps VALUES (2425, '2025-11-20 17:10:48.543035', '2025-11-20 17:10:48.543035', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 403, 1, 'Dưa chuột ngâm nước muỗi loãng, rửa sạch, thấm khô, gọt và chà nhựa hai đầu, thái lát 0,5 cm, thêm 1 thìa cà phê muối trộn đều để ướp 10 phút trong tủ lạnh, vắt sơ bỏ phần nước.', 10);
INSERT INTO public.recipe_steps VALUES (2426, '2025-11-20 17:10:48.544096', '2025-11-20 17:10:48.544096', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 403, 5, 'Nước sốt muối kim chi: cho hỗn hợp nước táo, hành tây xay nhuyễn vào nồi, thêm 2/3 chén nước, 4 thìa canh nước tương, 2 thìa canh mật ong, 2 thìa canh ớt bột đỏ Hàn Quốc, 1 thìa canh giấm, 1 thìa canh bột nếp, khuấy đều cho tan, cho lên bếp ở lửa vừa, vừa đun vừa khuấy cho tới khi thành hỗn hợp sền sệt, tắt bếp, để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (2427, '2025-11-20 17:10:48.71138', '2025-11-20 17:10:48.71138', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 404, 3, 'Bắc chảo dầu nóng, cho chả giò cuộn bánh đa vào chiên chín vàng.', 10);
INSERT INTO public.recipe_steps VALUES (2428, '2025-11-20 17:10:48.712971', '2025-11-20 17:10:48.712971', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 404, 2, 'Bánh đa dấp nước cho mềm, cắt miếng chữ nhật 8cm x 5cm, cho nhân mực vào, gấp đôi lại, ấn dính các mép.', 10);
INSERT INTO public.recipe_steps VALUES (2429, '2025-11-20 17:10:48.714567', '2025-11-20 17:10:48.714567', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 404, 4, 'Xà lách rửa sạch, bày ra đĩa, xếp chả giò xung quanh.', 10);
INSERT INTO public.recipe_steps VALUES (2430, '2025-11-20 17:10:48.71563', '2025-11-20 17:10:48.71563', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 404, 5, 'Món này dùng nóng với tương ớt.', 10);
INSERT INTO public.recipe_steps VALUES (2431, '2025-11-20 17:10:48.717733', '2025-11-20 17:10:48.717733', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 404, 1, 'Mực làm rửa sạch, để thật ráo, cắt nhỏ, quết nhuyễn với đầu hành, nêm tiêu, hạt nêm, tỏi xay và ớt xay.', 10);
INSERT INTO public.recipe_steps VALUES (2432, '2025-11-20 17:10:48.923197', '2025-11-20 17:10:48.923197', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 405, 3, 'Trứng đánh đều hấp chín thành khối vuông dài gần bằng miếng thăn heo. Hành tây cắt vuông dài.', 10);
INSERT INTO public.recipe_steps VALUES (2433, '2025-11-20 17:10:48.92488', '2025-11-20 17:10:48.92488', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 405, 1, 'Thưởng thức: Thịt thăn heo rôti cắt khoanh ăn kèm với rau củ vừa tăng hương vị vừa giảm vị ngậy của thịt.', 10);
INSERT INTO public.recipe_steps VALUES (2434, '2025-11-20 17:10:48.926967', '2025-11-20 17:10:48.926967', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 405, 4, 'Xếp trứng, hành tây, xúc xích, đậu đũa, tiêu hạt dọc theo miếng thịt. Cuộn thịt lại, dùng chỉ quấn tròn cuộn thịt. Ướp thịt với gia vị để cho thấm khoảng nửa ngày.', 10);
INSERT INTO public.recipe_steps VALUES (2435, '2025-11-20 17:10:48.92856', '2025-11-20 17:10:48.92856', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 405, 2, 'Chọn miếng thăn heo dài khoảng 2,5-3 tấc. Lạng mỏng và trải miếng thịt ra.', 10);
INSERT INTO public.recipe_steps VALUES (2436, '2025-11-20 17:10:48.930095', '2025-11-20 17:10:48.930095', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 405, 5, 'Cho thịt vào lò rôti cho đến khi thấy chín vàng là được.', 10);
INSERT INTO public.recipe_steps VALUES (2437, '2025-11-20 17:10:49.039494', '2025-11-20 17:10:49.039494', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 406, 4, 'Giò sống + lòng trắng trứng + hạt tiêu, gia vị quyết dẻo.', 10);
INSERT INTO public.recipe_steps VALUES (2438, '2025-11-20 17:10:49.041087', '2025-11-20 17:10:49.041087', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 406, 7, 'Trang trí: rau thơm mùi, lá chanh, hoa các loại.', 10);
INSERT INTO public.recipe_steps VALUES (2439, '2025-11-20 17:10:49.042148', '2025-11-20 17:10:49.042148', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 406, 6, 'Đun nước sôi cho thịt đã gói vào hấp chín cách thuỷ, thời gian khoảng 30- 35 phút là được. Để nguội gỡ dây lạt thái miếng dày một cm, bày ra đĩa, chấm nước mắm chanh ớt.', 10);
INSERT INTO public.recipe_steps VALUES (2440, '2025-11-20 17:10:49.043197', '2025-11-20 17:10:49.043197', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 406, 3, 'Lá chuối trần qua nước nóng cho mềm, dây lạt ngâm mềm.', 10);
INSERT INTO public.recipe_steps VALUES (2441, '2025-11-20 17:10:49.044795', '2025-11-20 17:10:49.044795', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 406, 1, 'Gà sơ chế sạch, xát muối để 5 phút rửa lại cho sạch, lọc lấy thịt ướp nước mắm, hạt tiêu, hành khô băm nhỏ để 10 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2442, '2025-11-20 17:10:49.046413', '2025-11-20 17:10:49.046413', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 406, 2, 'Trứng đập ra bát tách riêng lòng đỏ, lòng trắng.', 10);
INSERT INTO public.recipe_steps VALUES (2443, '2025-11-20 17:10:49.04814', '2025-11-20 17:10:49.04814', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 406, 5, 'Lá chuối lau sạch, trải ra khay. Xếp thịt gà dàn mỏng đều, phết giò sống cuộn tròn gói trong lá chuối, dùng dây lạt buộc chặt như gói giò.', 10);
INSERT INTO public.recipe_steps VALUES (2444, '2025-11-20 17:10:49.130417', '2025-11-20 17:10:49.130417', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 407, 2, 'Phần thịt rạm ướp với một thìa canh nước mắm, 1/2 thìa cà phê muối, 1/2 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu và 1/2 thìa cà phê ớt bột (nếu ăn được cay). Để ướp 10 - 15 phút cho ngấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (2445, '2025-11-20 17:10:49.132022', '2025-11-20 17:10:49.132022', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 407, 5, 'Cuối cùng thêm lá lốt đảo đều cho chín, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (2446, '2025-11-20 17:10:49.133628', '2025-11-20 17:10:49.133628', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 407, 1, 'Rạm xóc muối rửa sạch, để ráo, bóc bỏ mai, yếm, cắt chân và càng để riêng (giã nấu canh), khều gạch để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (2447, '2025-11-20 17:10:49.134719', '2025-11-20 17:10:49.134719', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 407, 4, 'Phi thơm hành khô bằng mỡ lợn, cho gạch rạm vào xào tạo màu, thêm chút nước. Tiếp tục, cho rạm vào đảo đều, thêm chút nước để kho/rim cho tới khi rạm mềm, nước sền sệt là đạt. Nêm lại gia vị phù hợp.', 10);
INSERT INTO public.recipe_steps VALUES (2448, '2025-11-20 17:10:49.135774', '2025-11-20 17:10:49.135774', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 407, 3, 'Lá lốt rửa sạch, thái sợi dài nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2449, '2025-11-20 17:10:49.191412', '2025-11-20 17:10:49.191412', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 408, 1, 'Cà rốt cạo vỏ, rửa sạch cắt miếng nhỏ. Bắp ngô rửa sạch, cắt dọc thành nhiều miếng. Gừng gọt vỏ thái lát. Sườn rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (2450, '2025-11-20 17:10:49.192986', '2025-11-20 17:10:49.192986', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 408, 2, 'Đặt nửa nồi nước lên bếp, đun sôi rồi cho sườn vào chần. Đổ nước chần sườn đi, rửa sạch lại sườn lần nữa.', 10);
INSERT INTO public.recipe_steps VALUES (2451, '2025-11-20 17:10:49.194046', '2025-11-20 17:10:49.194046', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 408, 3, 'Tiếp đến cho sườn và gừng tươi vào nồi, đổ nước ngập, đun sôi rồi để nhỏ lửa âm ỉ trong 10 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2452, '2025-11-20 17:10:49.196136', '2025-11-20 17:10:49.196136', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 408, 4, 'Sau đó cho cà rốt và ngô ngọt vào hầm cùng. Nêm muối cho vừa miệng. Hầm nhỏ lửa trong 30 phút là được.', 10);
INSERT INTO public.recipe_steps VALUES (2453, '2025-11-20 17:10:49.288659', '2025-11-20 17:10:49.288659', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 409, 4, 'Dùng mạch nha pha với nước cốt chanh và nửa chén nước phết lên giò heo nhiều lần, hong khô giò heo.', 10);
INSERT INTO public.recipe_steps VALUES (2454, '2025-11-20 17:10:49.290256', '2025-11-20 17:10:49.290256', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 409, 1, 'Chọn chân giò sau, lấy phần bắp đùi, làm sạch, xăm đều.', 10);
INSERT INTO public.recipe_steps VALUES (2455, '2025-11-20 17:10:49.291896', '2025-11-20 17:10:49.291896', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 409, 2, 'Pha muối và nước, ngâm giò heo ngập trong nước muối, để vào tủ mát một ngày rồi lấy giò heo ra hấp vừa chín (khoảng 70-80%).', 10);
INSERT INTO public.recipe_steps VALUES (2456, '2025-11-20 17:10:49.294029', '2025-11-20 17:10:49.294029', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 409, 5, 'Bắc dầu sôi, xối dầu lên giò heo, thấy da heo vàng, nổ bung, đều là được.', 10);
INSERT INTO public.recipe_steps VALUES (2457, '2025-11-20 17:10:49.295633', '2025-11-20 17:10:49.295633', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 409, 6, 'Giò heo muối chiên giòn ăn với bắp cải và cần tây trộn dầu giấm.', 10);
INSERT INTO public.recipe_steps VALUES (2458, '2025-11-20 17:10:49.297231', '2025-11-20 17:10:49.297231', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 409, 3, 'Cho giò heo vào lò sấy 70 độ C trong 15 phút để da heo khô.', 10);
INSERT INTO public.recipe_steps VALUES (2459, '2025-11-20 17:10:49.50033', '2025-11-20 17:10:49.50033', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 410, 1, 'Thịt gà luộc chín, xé nhỏ, ướp chút tiêu muối.', 10);
INSERT INTO public.recipe_steps VALUES (2460, '2025-11-20 17:10:49.501877', '2025-11-20 17:10:49.501877', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 410, 2, 'Cà rốt bào ra.', 10);
INSERT INTO public.recipe_steps VALUES (2461, '2025-11-20 17:10:49.503391', '2025-11-20 17:10:49.503391', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 410, 3, 'Trộn dấm, đường, đánh tan xong cho tỏi băm, ớt băm, muối, nước mắm, nước chanh, nêm vừa chua ngọt.', 10);
INSERT INTO public.recipe_steps VALUES (2462, '2025-11-20 17:10:49.504396', '2025-11-20 17:10:49.504396', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 410, 4, 'Hoa chuối rửa sạch, vắt khô trộn với cà rốt.', 10);
INSERT INTO public.recipe_steps VALUES (2463, '2025-11-20 17:10:49.506399', '2025-11-20 17:10:49.506399', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 410, 6, 'Trang trí hoa cà chua, xà lách.', 10);
INSERT INTO public.recipe_steps VALUES (2464, '2025-11-20 17:10:49.507511', '2025-11-20 17:10:49.507511', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 410, 5, 'Cho nước sốt chua ngọt vào hỗn hợp trên. Nộm đã vừa chua, cay, mặn, ngọt thì cho rau thơm thái 1cm, rồi cho ra đĩa rắc lạc rang, vừng rang lên trên.', 10);
INSERT INTO public.recipe_steps VALUES (2465, '2025-11-20 17:10:49.64585', '2025-11-20 17:10:49.64585', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 411, 5, 'Cho gà ra đĩa, dùng kèm dưa leo, xà lách và xốt gừng chua ngọt.', 10);
INSERT INTO public.recipe_steps VALUES (2466, '2025-11-20 17:10:49.647459', '2025-11-20 17:10:49.647459', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 411, 2, 'Hòa bột chiên giòn với một chén nước, đập trứng gà vào đánh tan đều.', 10);
INSERT INTO public.recipe_steps VALUES (2467, '2025-11-20 17:10:49.649043', '2025-11-20 17:10:49.649043', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 411, 1, 'Gà cắt miếng vừa ăn, ướp hạt nêm và dầu mè, để thấm 10 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2468, '2025-11-20 17:10:49.650217', '2025-11-20 17:10:49.650217', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 411, 3, 'Nhúng gà vào hỗn hợp bột chiên giòn, sau đó lăn qua bột chiên xù.', 10);
INSERT INTO public.recipe_steps VALUES (2469, '2025-11-20 17:10:49.651806', '2025-11-20 17:10:49.651806', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 411, 4, 'Bắc chảo dầu nóng, cho gà đã lăn bột vào chiên, hạ nhỏ lửa để gà chín vàng đều, vớt ra để trên giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (2470, '2025-11-20 17:10:49.828283', '2025-11-20 17:10:49.828283', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 412, 6, 'Cho nước đun sôi có hương sả và 1/2 phần cà chua còn lại vào, nêm vừa ăn, hơi nhạt một chút. Đun thêm khoảng 5-10 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2471, '2025-11-20 17:10:49.829873', '2025-11-20 17:10:49.829873', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 412, 7, 'Nếu muốn ăn thịt tái thì bạn chỉ xào 1/2 số thịt, còn lại 1/2 lúc này bỏ vào. Thịt vừa tái thì tắt lửa. Lúc này mới nêm mắm vào sao cho vừa miệng ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2472, '2025-11-20 17:10:49.831513', '2025-11-20 17:10:49.831513', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 412, 1, 'Bắc nồi lên bếp, cho dầu vào, dầu nóng, cho hành vào phi xém vàng, dậy mùi thơm.', 10);
INSERT INTO public.recipe_steps VALUES (2473, '2025-11-20 17:10:49.832832', '2025-11-20 17:10:49.832832', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 412, 8, 'Cho bún và hành ngò vào tô. Múc nước dùng và cà chua vào, thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (2474, '2025-11-20 17:10:49.834437', '2025-11-20 17:10:49.834437', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 412, 2, 'Cho hành đã phi thơm + tỏi, muối, tiêu vào thịt bò trộn đều, ướp khoảng 30 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2475, '2025-11-20 17:10:49.835491', '2025-11-20 17:10:49.835491', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 412, 3, 'Trong một nồi khác, cho sả đập dập và 2 bát nước, đun sôi khoảng 20-30 phút để sả ra nước thơm, xong vớt sả bỏ đi.', 10);
INSERT INTO public.recipe_steps VALUES (2476, '2025-11-20 17:10:49.837095', '2025-11-20 17:10:49.837095', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 412, 4, 'Cho lại nồi dầu ăn lên bếp, nồi nóng thì cho thịt bò vào xào săn lại rồi đổ ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (2477, '2025-11-20 17:10:49.838672', '2025-11-20 17:10:49.838672', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 412, 5, 'Cho nửa quả cà chua cắt nhỏ vào nồi đã xào thịt, xào cho cà chua ra màu đẹp. Cho thịt trở lại nồi.', 10);
INSERT INTO public.recipe_steps VALUES (2478, '2025-11-20 17:10:50.191385', '2025-11-20 17:10:50.191385', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 413, 1, 'Cá ba sa rửa sạch, để ráo. Ướp cá với hạt nêm, sả băm, tỏi băm, mè trắng, bột nghệ, bột bắp, để khoảng 20 phút cho thấm.', 10);
INSERT INTO public.recipe_steps VALUES (2479, '2025-11-20 17:10:50.19297', '2025-11-20 17:10:50.19297', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 413, 5, 'Cho cá ra đĩa, xếp xà lách, cà chua và cà rốt xung quanh. Dọn ăn kèm với rau và bánh tráng, chấm nước mắm tỏi ớt.', 10);
INSERT INTO public.recipe_steps VALUES (2480, '2025-11-20 17:10:50.195091', '2025-11-20 17:10:50.195091', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 413, 2, 'Cà rốt gọt vỏ tỉa hoa. Cà chua rửa sạch xắt khoanh.', 10);
INSERT INTO public.recipe_steps VALUES (2481, '2025-11-20 17:10:50.196665', '2025-11-20 17:10:50.196665', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 413, 3, 'Xà lách, rau thơm các loại nhặt rửa sạch, để ráo nước. Bánh tráng nhúng nước vẩy ráo.', 10);
INSERT INTO public.recipe_steps VALUES (2482, '2025-11-20 17:10:50.198239', '2025-11-20 17:10:50.198239', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 413, 4, 'Đặt chảo lên bếp, cho dầu vào, dầu sôi cho cá đã ướp vào chiên vàng đều hai mặt. Vớt ra để trên giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (2483, '2025-11-20 17:10:50.344518', '2025-11-20 17:10:50.344518', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 414, 3, 'Bắc chảo lên bếp, cho dầu ăn vào, đợi dầu lăn tăn sôi, cho chả giò vào chiên. Khi chiên trở vàng đều hai mặt chả giò, vớt ra để vào đĩa lớn có lót khăn giấy cho ráo dầu.', 10);
INSERT INTO public.recipe_steps VALUES (2484, '2025-11-20 17:10:50.34611', '2025-11-20 17:10:50.34611', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 414, 4, 'Cho bún và rau vào tô, cắt chả giò vào. Món này dọn ăn với nước mắm chua ngọt.', 10);
INSERT INTO public.recipe_steps VALUES (2485, '2025-11-20 17:10:50.347691', '2025-11-20 17:10:50.347691', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 414, 2, 'Trải bánh tráng ra, cho nhân vào theo chiều ngang, cuốn tròn lại. Khi cuốn xong thoa lòng trắng trứng cho bánh tráng dính chặt vào cuốn chả giò.', 10);
INSERT INTO public.recipe_steps VALUES (2486, '2025-11-20 17:10:50.349273', '2025-11-20 17:10:50.349273', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 414, 1, 'Tôm, thịt nạc bằm nhuyễn. Trứng gà tách lấy lòng trắng. Khoai môn bào sợi trộn với gia vị, để 20 phút cho thấm.', 10);
INSERT INTO public.recipe_steps VALUES (2487, '2025-11-20 17:10:50.465214', '2025-11-20 17:10:50.465214', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 415, 1, 'Gà rửa sạch, chặt miếng vừa ăn, cho gà vào bát ướp với một thìa dầu hào và một thìa bột canh. Để 10 phút cho ngấm.', 10);
INSERT INTO public.recipe_steps VALUES (2488, '2025-11-20 17:10:50.467383', '2025-11-20 17:10:50.467383', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 415, 2, 'Nấm hương ngâm nở, rửa sạch. Khoai tây gọt vỏ thái miếng.', 10);
INSERT INTO public.recipe_steps VALUES (2489, '2025-11-20 17:10:50.469505', '2025-11-20 17:10:50.469505', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 415, 4, 'Thêm một thìa xì dầu và một thìa đường nhỏ cho đậm đà và màu sắc đẹp hơn. Xào gà đến khi ngả vàng.', 10);
INSERT INTO public.recipe_steps VALUES (2490, '2025-11-20 17:10:50.471088', '2025-11-20 17:10:50.471088', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 415, 5, 'Cho một bát nước vào nồi gà (lượng nước không ngập thịt gà), cho tiếp khoai tây, vài cái hoa hồi và nấm hương vào rồi vặn to lửa đun sôi.', 10);
INSERT INTO public.recipe_steps VALUES (2491, '2025-11-20 17:10:50.472658', '2025-11-20 17:10:50.472658', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 415, 6, 'Nêm nếm gia vị lại (nếu cần). Nhỏ lửa hầm trong 30 phút cho khoai và gà chín nhừ. Khi nước trong nồi cạn bớt và sánh lại như súp là được.', 10);
INSERT INTO public.recipe_steps VALUES (2492, '2025-11-20 17:10:50.474895', '2025-11-20 17:10:50.474895', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 415, 3, 'Đặt nồi lên bếp, cho 3 thìa dầu ăn vào đun nóng rồi cho hành và gừng thái nhỏ vào phi thơm. Tiếp đến cho thịt gà đã ướp ngấm vào nồi xào.', 10);
INSERT INTO public.recipe_steps VALUES (2493, '2025-11-20 17:10:50.580656', '2025-11-20 17:10:50.580656', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 416, 2, 'Rau răm rửa sạch, thái nhỏ. Hành tây bóc vỏ, thái mảnh. Tỏi bóc vỏ giã nhỏ. Chanh vắt lấy nước cốt.', 10);
INSERT INTO public.recipe_steps VALUES (2494, '2025-11-20 17:10:50.582293', '2025-11-20 17:10:50.582293', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 416, 4, 'Pha nước mắm ngon với chút nước cốt chanh, đường, ớt, tỏi sao cho có vị chua ngọt.', 10);
INSERT INTO public.recipe_steps VALUES (2495, '2025-11-20 17:10:50.5839', '2025-11-20 17:10:50.5839', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 416, 3, 'Luộc chín bao tử, vớt ra để nguội rồi thái thật mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (2496, '2025-11-20 17:10:50.584965', '2025-11-20 17:10:50.584965', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 416, 1, 'Rửa sạch bao tử với nước muối pha loãng, xả sạch lại bằng nước lạnh, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (2497, '2025-11-20 17:10:50.586661', '2025-11-20 17:10:50.586661', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 416, 5, 'Cho bao tử, hành tây, rau răm vào thố lớn, trộn đều với nước mắm chua ngọt.', 10);
INSERT INTO public.recipe_steps VALUES (2498, '2025-11-20 17:10:50.848471', '2025-11-20 17:10:50.848471', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 417, 3, 'Khuấy tan bột bắp trong nước nguội.', 10);
INSERT INTO public.recipe_steps VALUES (2499, '2025-11-20 17:10:50.850071', '2025-11-20 17:10:50.850071', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 417, 5, 'Múc thịt bò hầm vào nồi đất, trang trí ngò và hành lá chẻ sợi, đặt lên bếp cồn giữ nóng, dọn dùng với bánh mì.', 10);
INSERT INTO public.recipe_steps VALUES (2500, '2025-11-20 17:10:50.85115', '2025-11-20 17:10:50.85115', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 417, 2, 'Phi vàng sả + ớt + tỏi với dầu, để nguội xát đều lên thịt bò, để ngấm 30 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2501, '2025-11-20 17:10:50.853287', '2025-11-20 17:10:50.853287', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 417, 1, 'Thịt bò luộc với gừng đập dập 5 phút, cho ra rổ xả nước nguội, để ráo, dùng mũi dao xâm đều miếng thịt bò.', 10);
INSERT INTO public.recipe_steps VALUES (2502, '2025-11-20 17:10:50.85435', '2025-11-20 17:10:50.85435', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 417, 4, 'Nấu sôi nước dừa, cho thịt bò vào nấu sôi và hớt bọt thật kỹ, đậy nắp và hầm trên lửa nhỏ đến khi thịt bò mềm, cho cà rốt + hạt nêm vào nấu sôi, cho nước bột bắp vào khuấy đều, sôi lại nhấc xuống.', 10);
INSERT INTO public.recipe_steps VALUES (2503, '2025-11-20 17:10:51.168168', '2025-11-20 17:10:51.168168', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 418, 3, 'Đậu phộng, mè trắng rang chín, giã dập. Ớt, tỏi bằm nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2504, '2025-11-20 17:10:51.16922', '2025-11-20 17:10:51.16922', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 418, 1, 'Dưa leo ngâm, rửa sạch, bỏ hạt, xắt sợi.', 10);
INSERT INTO public.recipe_steps VALUES (2505, '2025-11-20 17:10:51.170806', '2025-11-20 17:10:51.170806', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 418, 4, 'Cho đu đủ bào, cà rốt, dưa leo, tôm vào tô, trộn đều lên. Hòa tan đường với nước mắm, nêm nước cốt chanh, ớt, tỏi rồi rưới lên tô đu đủ, trộn đều lên, rắc tóp mỡ, bày ra đĩa, rắc hành phi, mè, đậu phộng, rau thơm và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (2506, '2025-11-20 17:10:51.172424', '2025-11-20 17:10:51.172424', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 418, 2, 'Tôm đất hấp chín, lột vỏ, bỏ đầu, lạng đôi. Thịt ba rọi làm sạch, luộc chín, để nguội, xắt sợi.', 10);
INSERT INTO public.recipe_steps VALUES (2507, '2025-11-20 17:10:51.249741', '2025-11-20 17:10:51.249741', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 419, 2, 'Nếu không có ly đong đếm, cách đơn giản nhất để canh lượng nước và trứng bằng nhau là bạn hãy dùng một sợ dây thun làm dấu bên ngoài ly thủy tinh. Hòa tan hỗn hợp trứng và nước lọc, đánh đều tay rồi nêm nước mắm, lọc qua rây cho mịn. Sau đó, bạn thêm cà rốt thái hạt lựu và hành lá vào. Nếu sử dụng nồi chiên không dầu kết hợp chức năng hấp, bạn chọn chế độ hấp trong vòng 15 phút. Còn với nồi chiên không dầu bình thường, bạn đặt nhiệt độ khoảng 80-90 độ C như khi hấp món trứng chawanmushi của Nhật trong vòng 15 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2508, '2025-11-20 17:10:51.251321', '2025-11-20 17:10:51.251321', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 419, 1, 'Không cần phải chuẩn bị nồi hấp cách thủy hay tốn thời gian canh trứng chín, bạn có thể sử dụng nồi chiên không dầu để làm trứng hấp. Chỉ 30 phút chuẩn bị, bạn có ngay bát trứng hấp thịt băm mềm mịn ăn sáng. Nguyên liệu gồm trứng, nước lọc, cà rốt, hành lá và thịt băm. Để có chén trứng hấp đạt chuẩn, bạn hãy pha trứng và nước theo tỉ lệ 1-1.', 10);
INSERT INTO public.recipe_steps VALUES (2509, '2025-11-20 17:10:51.252906', '2025-11-20 17:10:51.252906', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 419, 3, 'Trong khi chờ, bạn xào thịt nạc heo băm với một chút gia vị như mắm, tiêu, bột ngọt... Nếu không thích thịt heo, bạn có thể thay đổi bằng bất kỳ loại topping yêu thích nào khác như ức gà xào, tôm luộc... Đợi trứng hấp chín thì bạn lấy ra, rải thịt băm lên trên, thêm hành phi giòn thơm là chuẩn. Chén trứng hấp mịn, mọng nước, béo ngậy khiến các bé thích mê. Ngoài ra, cách này cũng có thể áp dụng cho móntrứng hấp chawanmushicủa Nhật Bản. Tuy nhiên, đối với món chawanmushi, thay vì cho thịt băm cuối cùng thì bạn cho thẳng vào hỗn hợp trứng và nước lọc trước khi đem hấp.', 10);
INSERT INTO public.recipe_steps VALUES (2510, '2025-11-20 17:10:51.3985', '2025-11-20 17:10:51.3985', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 420, 4, 'Gạn lấy phần trong của nước luộc trai, cho gạo đã ngâm xay vỡ vào nấu sôi. Thêm 1 thìa café muối, 1 chút hành phi vào đảo đều, hạ nhỏ lửa đun riu liu ít nhất 1 tiếng cho cháo nhừ, thỉnh thoảng bạn đảo đều để tránh cháo bị vón cục, dính và cháy nồi. Bạn có thể sử dụng nồi nấu chậm hoặc nồi áp suất để nhanh và nhàn hơn.', 10);
INSERT INTO public.recipe_steps VALUES (2511, '2025-11-20 17:10:51.400101', '2025-11-20 17:10:51.400101', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 420, 7, 'Trút 1/2 số thịt trai vừa xào xong vào nồi cháo nấu cùng, vừa nấu vừa vớt bọt. Nấu đến khi cháo chín hẳn, sánh đặc vừa ý, nêm nếm lại cho vừa ăn rồi tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (2512, '2025-11-20 17:10:51.401719', '2025-11-20 17:10:51.401719', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 420, 6, 'Bắc chảo lên bếp thêm chút dầu điều vào đun nóng. Khi dầu sôi thêm hành tím phi thơm, cho thịt trai vào xào chung để thịt săn lại và dậy mùi thơm. Nêm nếm thêm chút gia vị, nước mắm, hạt tiêu cho vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2513, '2025-11-20 17:10:51.403119', '2025-11-20 17:10:51.403119', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 420, 2, 'Con trai mua về cho vào ngâm với nước vo gạo cùng vài lát gừng hoặc ớt để nhả hết chất dơ, bùn đất bẩn, bớt tanh hơn. Ngâm khoảng một tiếng, vớt ra rửa lại với nước, sau đó cho vào nồi thêm nước ngập xâm xấp cùng chút muối rồi bắc lên bếp luộc chín.', 10);
INSERT INTO public.recipe_steps VALUES (2514, '2025-11-20 17:10:51.404699', '2025-11-20 17:10:51.404699', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 420, 1, 'Gạo nếp lẫn tẻ ngâm 4-6 tiếng rồi cho vào máy xay vỡ. Bạn có thể mua gạo xay vỡ sẵn, về vo sạch rồi ngâm nước cho mềm.', 10);
INSERT INTO public.recipe_steps VALUES (2515, '2025-11-20 17:10:51.406275', '2025-11-20 17:10:51.406275', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 420, 3, 'Hành khô bóc vỏ, thái mỏng. Rau răm nhặt sạch, thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2516, '2025-11-20 17:10:51.407877', '2025-11-20 17:10:51.407877', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 420, 8, 'Múc cháo trai ra chén, cho phần trai xào còn lại lên trên, rắc thêm chút rau răm, tiêu xay, ớt bột lên trên để món ăn dậy mùi thơm và trông bắt mắt hơn. Cháo trai ăn nóng cùng quẩy giúp món ăn thêm thơm ngon và hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (2517, '2025-11-20 17:10:51.410028', '2025-11-20 17:10:51.410028', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 420, 5, 'Trai luộc chín lấy thịt bỏ vỏ. Phần thịt trai đem bóp bỏ hết phân ở rìa trai rồi rửa sạch, để ráo. Sau đó, thái miếng nhỏ vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2518, '2025-11-20 17:10:51.606778', '2025-11-20 17:10:51.606778', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 421, 2, 'Đầu tiên, bạn cho các nguyên liệu nấu nước ngâm vào chảo, đun trên lửa nhỏ trong 15 phút rồi đổ hết katsuobushi vào, giúp ngọt nước, vị thanh. Nấu khoảng 2 phút thì lọc bỏ xác, để nguội là xong.', 10);
INSERT INTO public.recipe_steps VALUES (2519, '2025-11-20 17:10:51.60837', '2025-11-20 17:10:51.60837', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 421, 1, 'Cá hồi ngâm nước tương kiểu Hàn cũng khiến nhiều người "đứng ngồi không yên" nhờ hương vị mềm, béo hấp dẫn. Cá hồi ngâm tương nổi lên từ cuối năm ngoái, ngay lập tức được các food blogger hưởng ứng nhiệt tình. Món này để được vài ngày trong tủ lạnh thích hợp ăn kèm với cơm trắng, và cách làm lại rất đơn giản. Bạn chỉ cần chuẩn bị bụng cá hồi phi lê, nước tương (xì dầu) Hàn Quốc, chanh, ớt và vài loại gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (2520, '2025-11-20 17:10:51.609955', '2025-11-20 17:10:51.609955', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 421, 4, 'Tiếp đến, xếp từng lát cá vào hộp thủy tinh, thêm các loại ớt, hành, chanh lên trên rồi rưới hỗn hợp nước ngâm ngập cá. Bạn đậy nắp lại, để trong tủ lạnh ít nhất 5 tiếng đồng hồ rồi thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (2521, '2025-11-20 17:10:51.611022', '2025-11-20 17:10:51.611022', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 421, 3, 'Hành tây cắt thành miếng dày. Ớt đỏ và ớt xanh xắt lát. Chanh cắt thành từng lát mỏng. Cá hồi sau khi mua về rửa sạch. Rưới một thìa rượu nấu ăn lên cá hồi, dùng khăn thấm khô rồi thái miếng dày vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2522, '2025-11-20 17:10:51.820982', '2025-11-20 17:10:51.820982', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 422, 3, 'Đun sôi nước dùng, thả thịt vào nồi, nước sôi lại hớt bọt. Tiếp theo cho củ cải vào, đun lửa lớn. Nêm vừa ăn, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (2523, '2025-11-20 17:10:51.8226', '2025-11-20 17:10:51.8226', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 422, 4, 'Bày ra tô. Trang trí hành ngò lên trên.', 10);
INSERT INTO public.recipe_steps VALUES (2524, '2025-11-20 17:10:51.824196', '2025-11-20 17:10:51.824196', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 422, 2, 'Ướp thịt với đầu hành lá, nửa thìa cà phê hạt nêm, tiêu, vo viên nhỏ vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2525, '2025-11-20 17:10:51.825748', '2025-11-20 17:10:51.825748', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 422, 1, 'Củ cải cắt gốc, chà sạch đất, cắt khoanh.', 10);
INSERT INTO public.recipe_steps VALUES (2526, '2025-11-20 17:10:51.991441', '2025-11-20 17:10:51.991441', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 423, 1, 'Mướp đắng rửa sạch, cắt khúc với độ dài khoảng 3 cm, loại bỏ hạt mướp đắng. Đổ lượng nước lọc thích hợp vào nồi, thêm chút muối hạt vào đun sôi. Khi nước sôi, cho mướp đắng vào chần trong 2 phút. Sau đó, vớt mướp đắng ra cho bát nước lạnh. Một lúc sau thì vớt mướp ra để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (2527, '2025-11-20 17:10:51.993543', '2025-11-20 17:10:51.993543', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 423, 4, 'Để đĩa mướp đắng nhồi thịt vào nồi hấp, hấp sôi khoảng 20 phút là chín. Sau khi hấp, đĩa mướp đắng sẽ ra nhiều nước. Đổ sốt dầu hào lên đĩa mướp đắng nhồi thịt hấp là xong.', 10);
INSERT INTO public.recipe_steps VALUES (2528, '2025-11-20 17:10:51.995148', '2025-11-20 17:10:51.995148', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 423, 2, 'Nấm hương ngâm nở rồi thái nhỏ. Cho nấm hương vào bát, thêm thịt băm, hành khô băm nhỏ, hạt nêm, hạt tiêu, dầu hào vào trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (2529, '2025-11-20 17:10:51.996255', '2025-11-20 17:10:51.996255', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 423, 3, 'Nhồi thịt băm đã trộn vào từng miếng mướp đắng, sau đó cho vào đĩa sâu lòng.', 10);
INSERT INTO public.recipe_steps VALUES (2530, '2025-11-20 17:10:52.107748', '2025-11-20 17:10:52.107748', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 424, 2, 'Trải bánh tráng ra mặt phẳng, múc nhân cho vào rồi gắp 2 mép 2 bên, cuộn kín nhân lại bình thường. Dùng nước để kết dính mép bánh tráng. Làm lần lượt cho hết nguyên liệu.', 10);
INSERT INTO public.recipe_steps VALUES (2531, '2025-11-20 17:10:52.109191', '2025-11-20 17:10:52.109191', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 424, 1, 'Khoai môn gọt vỏ rồi bào sợi nhỏ. Tôm bỏ vỏ băm nhỏ. Sau đó, trộn đều khoai môn với thịt heo bằm, tôm bằm, 1/3 muỗng cà phê tiêu, 1 muỗng hành tím băm và 1 muỗng cà phê hạt nêm.', 10);
INSERT INTO public.recipe_steps VALUES (2532, '2025-11-20 17:10:52.110788', '2025-11-20 17:10:52.110788', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 424, 3, 'Đun nóng nhiều dầu ăn, cho các cuộn chả giòn chiên với lửa nhỏ đến khi chín vàng giòn thì vớt ra để ráo dầu là có thể dùng. Khi ăn chấm với tương ớt hoặc nước mắm chua ngọt.', 10);
INSERT INTO public.recipe_steps VALUES (2533, '2025-11-20 17:10:52.226619', '2025-11-20 17:10:52.226619', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 425, 1, 'Rửa sạch tôm khô rồi ngâm nước ấm khoảng 15 phút cho tôm khô nở và mềm thì vớt ra để ráo nước. Mực làm sạch và rửa sạch lại với nước, cắt hạt lựu. Tôm tươi rửa sạch, lột bỏ vỏ và đầu, sau đó cắt hạt lựu. Lạp xưởng thái hạt lựu. Gọt vỏ cà rốt, cắt hạt lựu. Hành lá rửa sạch, cắt nhỏ. Tỏi, hành tím bóc vỏ, băm nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2534, '2025-11-20 17:10:52.228716', '2025-11-20 17:10:52.228716', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 425, 3, 'Bạn bắc chảo lên bếp mở lửa vừa, thêm một muỗng canh dầu ăn, dầu nóng bạn phi thơm tỏi băm. Cho phần lạp xưởng vào trước, đảo đều rồi cho thêm hải sản vào xào khoảng 5 phút cho hải sản chín, thêm 1/2 muỗng canh nước mắm vào, nêm nêm gia vị lại cho vừa ăn. Thêm cà rốt đảo thêm 2 phút rồi cho tôm khô vào xào, tắt bếp và cho qua rây để hỗn hợp ráo nước, nước sốt hải sản để lại chiên cơm.', 10);
INSERT INTO public.recipe_steps VALUES (2535, '2025-11-20 17:10:52.230825', '2025-11-20 17:10:52.230825', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 425, 5, 'Nêm gia vị thêm 1/2 muỗng canh nước mắm, 1/2 muỗng cà phê bột ngọt, nêm nếm gia vị lại cho vừa ăn, thêm hỗn hợp hải sản vào đảo đều thêm 2 phút. Cuối cùng thêm tiêu, hành lá vào đảo đều và tắt bếp. Cho cơm chiên ra đĩa, rắc thêm chút tiêu, bày ngò rí và hành lá lên trên cho đẹp mắt.', 10);
INSERT INTO public.recipe_steps VALUES (2536, '2025-11-20 17:10:52.232393', '2025-11-20 17:10:52.232393', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 425, 4, 'Bạn bắc chảo lên bếp mở lửa vừa, thêm 1,5 muỗng canh dầu ăn, dầu nóng thì phi thơm hành tím băm. Tiếp đó, thêm cơm vào chiên trên lửa lớn, thêm nước sốt hải sản vào, chiên khoảng 5 phút cho hạt cơm ráo, khô lại, lâu lâu đảo đều. Khi hạt cơm đã ráo, bạn đập thêm 2 quả trứng, đảo đều tay để trứng áo một lớp đều trên hạt cơm.', 10);
INSERT INTO public.recipe_steps VALUES (2537, '2025-11-20 17:10:52.233983', '2025-11-20 17:10:52.233983', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 425, 2, 'Ướp hải sản với 1/2 muỗng cà phê hạt nêm, 1/2 muỗng cà phê bột ngọt, đảo đều và để khoảng 5 phút cho hải sản thấm gia vị. Cơm nguội nêm với 1/3 muỗng canh hạt nêm, 1/3 muỗng cà phê bột ngọt, 1/3 muỗng cà phê đường, dùng muỗng đảo đều.', 10);
INSERT INTO public.recipe_steps VALUES (2538, '2025-11-20 17:10:52.384127', '2025-11-20 17:10:52.384127', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 426, 3, 'Cho vào chén 3 muỗng canh đường, 3 muỗng canh nước mắm, 3 muỗng canh nước cốt chanh, 3 muỗng canh tương ớt, 1 muỗng canh ớt sa tế, 1/2 muỗng canh ớt bột, 2 muỗng canh sả, hành, gừng, ớt băm nhuyễn. Khuấy đều. Nếm có vị chua ngọt đậm đà là được.', 10);
INSERT INTO public.recipe_steps VALUES (2539, '2025-11-20 17:10:52.386242', '2025-11-20 17:10:52.386242', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 426, 1, 'Chân gà rửa sạch với muối, để ráo. Đun sôi nước cho vào ít muối và vài lát gừng. Cho chân vào luộc mềm. Vớt chân gà ra thau nước lạnh rồi vớt ra để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (2540, '2025-11-20 17:10:52.3884', '2025-11-20 17:10:52.3884', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 426, 2, 'Cóc non bào bỏ vỏ chẻ đôi hoặc thái lát dày vừa ăn. Hành tím thái mỏng ngâm vào nước đá. Lá chanh thái sợi. Ớt, sả, hành tím, gừng băm nhuyễn, chừa một phần sả thái mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (2541, '2025-11-20 17:10:52.389986', '2025-11-20 17:10:52.389986', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 426, 4, 'Cho chân gà, cóc non, lá chanh, hành tím, sả bào mỏng vào tô, thêm sốt trộn đều là đã hoàn thành.', 10);
INSERT INTO public.recipe_steps VALUES (2542, '2025-11-20 17:10:52.618987', '2025-11-20 17:10:52.618987', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 427, 2, 'Phi thơm tỏi, cho dẻ sườn bò vào nồi, xào săn rồi thêm lượng nước vừa đủ xâm xấp, đun sôi, hạ lửa, đập vung, om dẻ sườn bò cho đến khi mềm, khoảng 40-45 phút. Nếu muốn rút ngắn thời gian, bạn ninh bằng nồi áp suất.', 10);
INSERT INTO public.recipe_steps VALUES (2543, '2025-11-20 17:10:52.620576', '2025-11-20 17:10:52.620576', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 427, 6, 'Yêu cầu thành phẩm: Thịt bò mềm mà không khô, dưa cải chua giòn, dứa', 10);
INSERT INTO public.recipe_steps VALUES (2544, '2025-11-20 17:10:52.62217', '2025-11-20 17:10:52.62217', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 427, 4, 'Trút hỗn hợp dưa cải chua, dứa vừa xào vào nồi thịt bò và tiếp tục om thêm 15-20 phút để thịt và dưa hòa quyện, ngấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (2545, '2025-11-20 17:10:52.623221', '2025-11-20 17:10:52.623221', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 427, 1, 'Thịt bò thái miếng to chút, chần sơ, rửa sạch, để ráo. Sau đó, ướp thịt với gừng, tỏi băm và 1,5-2 thìa canh nước mắm, 1 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu trong 15-20 phút cho thấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (2546, '2025-11-20 17:10:52.624987', '2025-11-20 17:10:52.624987', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 427, 3, 'Cho 2 thìa canh mỡ lợn và tóp mỡ (nếu có) vào chảo, cho hành khô vào phi thơm rồi cho dưa cải muối vào xào. Nêm nếm ít đường, mắm, muối theo khẩu vị, đảo một lúc thì thêm dứa và cà chua, hành tây vào xào.', 10);
INSERT INTO public.recipe_steps VALUES (2547, '2025-11-20 17:10:52.626613', '2025-11-20 17:10:52.626613', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 427, 5, 'Thêm hành lá, ớt (nếu ăn được cay) lên trên và tắt bếp. Múc ra bát tô và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (2548, '2025-11-20 17:10:52.889488', '2025-11-20 17:10:52.889488', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 428, 1, 'Hành khô, tỏi xay (hoặc băm) nhỏ. Củ sả giã dập, băm nhỏ. Nghệ giã nát, sau đó trộn cùng hỗn hợp hành tỏi đã xay. Măng, ớt chuông thái lát vừa ăn. Hành lá cắt khúc khoảng 1 cm. Lá lốt thái thành sợi (không nên thái nhỏ quá). Ớt tươi (cay) thái lát mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (2549, '2025-11-20 17:10:52.892149', '2025-11-20 17:10:52.892149', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 428, 2, 'Cá quả (lóc) phi lê thái miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2550, '2025-11-20 17:10:52.894799', '2025-11-20 17:10:52.894799', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 428, 6, 'Thêm một thìa cà phê ớt chưng. Khi cá chín, cho lá lốt, hành tươi vào đảo nhanh rồi xúc ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (2551, '2025-11-20 17:10:52.896365', '2025-11-20 17:10:52.896365', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 428, 4, 'Đặt chảo lên bếp, cho dầu ăn (hoặc mỡ lợn), phi thơm hành tỏi, xả và ớt bột. Tiếp đó cho măng vào xào. Nêm nếm vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2552, '2025-11-20 17:10:52.898096', '2025-11-20 17:10:52.898096', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 428, 5, 'Khi măng chín tới, cho cá đã ướp vào xào cùng. Lưu ý đảo nhẹ nhàng, tránh làm vỡ cá. Tiếp tục cho ướt chuông vào xào cùng cá và măng.', 10);
INSERT INTO public.recipe_steps VALUES (2553, '2025-11-20 17:10:52.900741', '2025-11-20 17:10:52.900741', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 428, 3, 'Ướp cá cùng với: một thìa cà phê muối, một thìa nước mắm, một thìa cà phê bột tiêu, nghệ tươi giã nát. Trộn đều để ngấm vào cá, sau đó để trong ngăn mát tủ lạnh khoảng 4 tiếng.', 10);
INSERT INTO public.recipe_steps VALUES (2554, '2025-11-20 17:10:53.190532', '2025-11-20 17:10:53.190532', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 429, 5, 'Kho cá lần 2 giúp xương sườn cá nhừ. Bật bếp, đun sôi và hạ nhỏ lửa kho cho tới khi cá mềm xương. Tắt bếp, đậy vung, để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (2555, '2025-11-20 17:10:53.192847', '2025-11-20 17:10:53.192847', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 429, 8, 'Thành phẩm: Cá nguyên con, chắc cứng nhưng xương mềm, đậm đà. Khi ăn, thịt quyện với xương mềm rục, thoảng mùi thơm như cá hộp, rất hấp dẫn và hao cơm.', 10);
INSERT INTO public.recipe_steps VALUES (2556, '2025-11-20 17:10:53.197077', '2025-11-20 17:10:53.197077', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 429, 1, 'Cá trích tươi (hoặc cá trích nướng) được cắt bỏ đầu, đánh vảy kỹ, móc ruột, rửa sạch, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (2557, '2025-11-20 17:10:53.199191', '2025-11-20 17:10:53.199191', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 429, 6, 'Kho cá lần 3, tiếp tục kho cá ở lửa nhỏ. Chú ý luôn xem lượng nước trong nồi, khi nước rút, chưa cạn hẳn thì thêm nước dừa hoặc nước sôi vào kho tiếp. Tránh để cạn nước quá mới thêm nước.', 10);
INSERT INTO public.recipe_steps VALUES (2558, '2025-11-20 17:10:53.201882', '2025-11-20 17:10:53.201882', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 429, 4, 'Kho cá lần 1 giúp thịt thấm vị: Lấy lá chè xanh lót dưới đáy nồi đất, lần lượt xếp cá đã ướp gia vị lên trên. Đổ nước dừa xâm xấp rồi đun sôi. Hạ nhỏ lửa kho 15-20 phút rồi tắt bếp, để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (2559, '2025-11-20 17:10:53.20399', '2025-11-20 17:10:53.20399', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 429, 7, 'Xào cà chua, nêm mắm, muối, đường theo khẩu vị rồi cho vào nồi cá kho, tiếp tục kho lần 4 cho rục mềm.', 10);
INSERT INTO public.recipe_steps VALUES (2560, '2025-11-20 17:10:53.205585', '2025-11-20 17:10:53.205585', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 429, 2, 'Ướp cá trong tối thiểu 30 phút với một thìa cà phê muối hạt, 1/2 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu, 3 thìa cà phê nước mắm, hành tăm đập dập.', 10);
INSERT INTO public.recipe_steps VALUES (2561, '2025-11-20 17:10:53.208686', '2025-11-20 17:10:53.208686', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 429, 3, 'Cà chua rửa sạch, thái múi cau. Lá chè xanh rửa sạch. Hành lá rửa sạch, cắt khúc.', 10);
INSERT INTO public.recipe_steps VALUES (2562, '2025-11-20 17:10:53.521349', '2025-11-20 17:10:53.521349', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 430, 1, 'Cá diếc làm sạch, bỏ ruột, giữ trứng (nếu có). Xóc một chút muối hạt, nước cốt chanh để khử mùi rồi rửa sạch, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (2563, '2025-11-20 17:10:53.522938', '2025-11-20 17:10:53.522938', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 430, 8, 'Kho cá lần 2: Bật bếp đun sôi. Lúc này, nếu thích vị chua thì bạn cho thêm khế chua thái lát mỏng hình ngôi sao vào. Khi sôi, hạ lửa nhỏ và kho liu riu lửa. Trong quá trình kho lưu ý không nên mở nắp nhiều, cũng không khuấy đảo. Kho cho tới khi nước rút cạn, cá rục, xương mềm thì thêm chút lá gừng rồi tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (2564, '2025-11-20 17:10:53.523964', '2025-11-20 17:10:53.523964', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 430, 2, 'Riềng, gừng rửa sạch, thái lát mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (2565, '2025-11-20 17:10:53.526493', '2025-11-20 17:10:53.526493', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 430, 6, 'Cách kho cá: Nên kho tối thiểu 2 lần lửa hoặc nhiều lần sẽ giúp cá diếc kho rục, ăn được cả xương đã mềm:', 10);
INSERT INTO public.recipe_steps VALUES (2566, '2025-11-20 17:10:53.529441', '2025-11-20 17:10:53.529441', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 430, 4, 'Xếp riềng, gừng, hành khô thái lát ở dưới đáy nồi. Lần lượt xếp cá lên trên.', 10);
INSERT INTO public.recipe_steps VALUES (2567, '2025-11-20 17:10:53.530687', '2025-11-20 17:10:53.530687', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 430, 3, 'Hành khô: Một nửa thái lát để lót đáy nồi, 1 nửa băm nhỏ để ướp cá.', 10);
INSERT INTO public.recipe_steps VALUES (2568, '2025-11-20 17:10:53.533779', '2025-11-20 17:10:53.533779', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 430, 5, 'Ướp gia vị gồm: 1 thìa cà phê muối, 1/2 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu, 3 thìa canh đường vàng, 2 thìa canh nước hàng, 1 thìa canh mỡ lợn (giúp cho món ăn đỡ khô), 1 chén (bát nhỏ) tương bần, ớt quả, hành khô băm nhỏ. Nên ướp tối thiểu 30 phút hoặc nếu ướp lâu hơn thì dùng màng bọc thực phẩm bọc kín cho vào ngăn mát tủ lạnh, ướp lâu thì khi kho cá sẽ đậm đà hơn.', 10);
INSERT INTO public.recipe_steps VALUES (2569, '2025-11-20 17:10:53.536417', '2025-11-20 17:10:53.536417', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 430, 7, 'Kho cá lần 1: Thêm vào nồi một lượng nước sôi xâm xắp mặt, bật bếp đun sôi. Nêm nếm lại gia vị theo khẩu vị. Khi sôi, hạ nhỏ lửa, đậy vung, kho liu riu ở lửa nhỏ khoảng 30 phút thì tắt bếp, để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (2570, '2025-11-20 17:10:53.731756', '2025-11-20 17:10:53.731756', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 431, 3, 'Cho vào nồi lượng nước đủ ngập don. Đun sôi nước, cho don vào, mở vung (để tránh sủi bọt dễ tràn nước). Chú ý: Không đảo don vì dễ vỡ làm nước đục.Khi don há miệng thì gạn lấy nước, để lắng và lọc lấy nước trong, để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (2571, '2025-11-20 17:10:53.734444', '2025-11-20 17:10:53.734444', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 431, 2, 'Don nhặt bỏ tạp chất, rửa nhiều lần cho sạch.', 10);
INSERT INTO public.recipe_steps VALUES (2572, '2025-11-20 17:10:53.73656', '2025-11-20 17:10:53.73656', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 431, 5, 'Phi thơm hành khô bằng mỡ lợn, cho thịt don vào đảo đều và nêm nước mắm, muối theo khẩu vị. Sau đó, cho nước luộc don vào.', 10);
INSERT INTO public.recipe_steps VALUES (2573, '2025-11-20 17:10:53.738148', '2025-11-20 17:10:53.738148', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 431, 1, 'Rau mồng tơi nhặt lấy phần lá và ngọn non, rửa sạch, để ráo, thái nhỏ hoặc để nguyên lá tùy chọn. Hành khô băm nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2574, '2025-11-20 17:10:53.740961', '2025-11-20 17:10:53.740961', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 431, 6, 'Khi nước sôi thì thêm rau mồng tơi vào.Canh chín, múc ra tô và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (2575, '2025-11-20 17:10:53.742543', '2025-11-20 17:10:53.742543', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 431, 4, 'Số don còn trong nồi, đậy vung, lắc mạnh để thịt don tách khỏi vỏ. Đổ don ra rá và đãi trong chậu nước để lấy phần thịt, rửa sạch cát.', 10);
INSERT INTO public.recipe_steps VALUES (2576, '2025-11-20 17:10:54.01021', '2025-11-20 17:10:54.01021', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 432, 5, 'Cho lá cà ri đã chiên giòn vào cùng thịt gà, đảo đều rồi xúc ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (2577, '2025-11-20 17:10:54.012353', '2025-11-20 17:10:54.012353', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 432, 2, 'Lườn (hoặc ức) gà thái miếng vừa ăn, ướp cùng 2 thìa cà phê muối, 1/2 thìa hạt tiêu bột, 1-2 thìa đường (tùy khẩu vị thích ngọt hay không).', 10);
INSERT INTO public.recipe_steps VALUES (2578, '2025-11-20 17:10:54.014489', '2025-11-20 17:10:54.014489', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 432, 4, 'Cho thịt gà đã ướp vào xào cùng với lửa to. Khi thịt gà chín, cho ớt chuông thái vuông vào xào cùng. Thêm 1,5 thìa nước tương (xì dầu). Đảo đều cho ngấm.', 10);
INSERT INTO public.recipe_steps VALUES (2579, '2025-11-20 17:10:54.016259', '2025-11-20 17:10:54.016259', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 432, 1, 'Lá cà ri tuốt, rửa sạch, để ráo hết nước rồi chiên nổi trong dầu ăn khi cho đến khi giòn (lá ngấm dầu, không còn màu xanh sáng). Vớt ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (2580, '2025-11-20 17:10:54.017852', '2025-11-20 17:10:54.017852', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 432, 3, 'Hành khô, tỏi xay nhuyễn, phi thơm rồi cho ớt khô (đã bẻ vụn) vào xào.', 10);
INSERT INTO public.recipe_steps VALUES (2636, '2025-11-20 17:10:55.029033', '2025-11-20 17:10:55.029033', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 439, 9, 'Đun sôi, nêm nếm lại gia vị mắm, muối, đường theo khẩu vị.', 10);
INSERT INTO public.recipe_steps VALUES (2581, '2025-11-20 17:10:54.15268', '2025-11-20 17:10:54.15268', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 433, 5, 'Chiên sơ lần 1: Cho dầu ăn vào chảo, đun nóng, lần lượt cho cánh gà vào chiên sơ. Sau đó, vớt ra để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (2582, '2025-11-20 17:10:54.155502', '2025-11-20 17:10:54.155502', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 433, 7, 'Phủ sốt mặn ngọt, bao áo cho cánh gà:Cho chút dầu ăn vào chảo, phi thơm tỏi băm. Tiếp tục, cho hỗn hợp nước sốt mặn ngọt vào, đun sôi. Khi hỗn hợp sủi bọt, tạo độ keo kết dính thì cho cánh gà đã chiên vào đảo đều để sốt bám vào các mặt cánh gà. Khi sốt sánh, bao phủ vàng óng thì tắt bếp, gắp cánh gà ra đĩa, rắc thêm tỏi phi (nếu thích).', 10);
INSERT INTO public.recipe_steps VALUES (2583, '2025-11-20 17:10:54.15813', '2025-11-20 17:10:54.15813', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 433, 2, 'Ướp cánh gà với gia vị: 1 thìa cà phê muối, 1 thìa cà phê hạt tiêu, 1 thìa cà phê hạt nêm, 2 thìa cà phê ớt bột tạo màu Hàn Quốc, 2 thìa cà phê dầu hào, 1 thìa cà phê mỡ gà hoặc mỡ lợn, 1 thìa canh bột bắp và chút gừng, hành củ đập dập (khi rán bỏ gừng, hành ra, tránh bị cháy). Đeo găng tay trộn và thoa đều các mặt cho gia vị thấm đều. Để ướp trong 15 – 20 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2584, '2025-11-20 17:10:54.160243', '2025-11-20 17:10:54.160243', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 433, 6, 'Chiên chín vàng lần 2: Tiếp tục đun nóng dầu ăn, hạ lửa vừa, cho cánh gà vào chiên vàng, chín đều. Vớt cánh gà ra, cho vào giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (2585, '2025-11-20 17:10:54.162369', '2025-11-20 17:10:54.162369', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 433, 1, 'Cánh gà làm sạch, ngâm với nước ấm pha muối loãng, thêm vài lát gừng, hành củ đập dập trong 10-15 phút để khử mùi. Sau đó, rửa sạch, thấm khô. Nếu cánh nhỏ thì để nguyên, cánh to thì cắt thành các miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2586, '2025-11-20 17:10:54.164477', '2025-11-20 17:10:54.164477', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 433, 3, 'Cách làm nước sốt mặn ngọt:Cho hỗn hợp gồm: 2 thìa canh đường, 2 thìa canh nước mắm, 1 thìa canh dầu hào, 1 thìa canh tương ớt, 1 thìa canh nước lọc vào bát rồi khuấy đều cho tan.', 10);
INSERT INTO public.recipe_steps VALUES (2587, '2025-11-20 17:10:54.166607', '2025-11-20 17:10:54.166607', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 433, 4, 'Chiên cánh gà:Nên chiên 2 lần lửa vừa giúp cánh gà chín, không bị đỏ xương và giòn hơn.', 10);
INSERT INTO public.recipe_steps VALUES (2588, '2025-11-20 17:10:54.359978', '2025-11-20 17:10:54.359978', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 434, 2, 'Hoa đậu biếc khô rửa sạch bụi bẩn.', 10);
INSERT INTO public.recipe_steps VALUES (2589, '2025-11-20 17:10:54.36164', '2025-11-20 17:10:54.36164', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 434, 1, 'Gạo nếp vo thật sạch để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (2590, '2025-11-20 17:10:54.363226', '2025-11-20 17:10:54.363226', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 434, 5, 'Đặt xửng lên bếp, cho gạo vào đồ khoảng 25 phút. Khi xôi chín, tãi đều ra mâm, quạt cho nguội.', 10);
INSERT INTO public.recipe_steps VALUES (2591, '2025-11-20 17:10:54.364285', '2025-11-20 17:10:54.364285', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 434, 8, 'Rắc vừng và dừa xào lên trên ăn kèm nước cốt dừa.', 10);
INSERT INTO public.recipe_steps VALUES (2592, '2025-11-20 17:10:54.365893', '2025-11-20 17:10:54.365893', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 434, 6, 'Trộn vài thìa nước cốt dừa vào xôi rồi cho lên xửng đồ tiếp lần hai khoảng 15 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2593, '2025-11-20 17:10:54.367461', '2025-11-20 17:10:54.367461', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 434, 4, 'Vớt gạo ra, tráng lại một lần nước. Để gạo thật ráo nước rồi trộn với một xíu muối và chút dầu ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2594, '2025-11-20 17:10:54.368521', '2025-11-20 17:10:54.368521', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 434, 7, 'Xới xôi ra đĩa đợi nguội bớt, vê tròn những viên xôi vừa đủ cho vào múi mít (mít tách hạt và rạch một đường ngang múi). Nắn nhẹ nhàng cho múi mít bao quanh nắm xôi.', 10);
INSERT INTO public.recipe_steps VALUES (2595, '2025-11-20 17:10:54.37082', '2025-11-20 17:10:54.37082', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 434, 3, 'Đun khoảng 1 lít nước sôi để ngâm hoa đậu biếc. Khi hoa lên màu đẹp theo ý muốn, dùng rây lọc lấy nước. Đợi nước nguội thì đổ gạo nếp đã vo vào ngâm trong khoảng 4-8 tiếng.', 10);
INSERT INTO public.recipe_steps VALUES (2596, '2025-11-20 17:10:54.489825', '2025-11-20 17:10:54.489825', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 435, 9, 'Cho 2 thìa dầu ăn vào chảo đun nóng, cho hành tỏi băm nhỏ vào phi thơm. Tiếp theo, cho cá đã chiên vàng vào đảo đều, cho nước sốt vào đun cùng, hạ lửa đun liu riu cho đến khi nước ngấm vào cá. Cho 1 thìa cafe nước mắm vào đảo đều, khi nước mắm keo lại, quyện vào cá là được. Lưu ý vì cá khô đã khá mặn nên chỉ cho một chút nước mắm vào bước cuối cùng để dậy mùi thơm. Nêm nếm lại cho vừa miệng', 10);
INSERT INTO public.recipe_steps VALUES (2597, '2025-11-20 17:10:54.491923', '2025-11-20 17:10:54.491923', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 435, 1, 'Xôi cá cơm là món ăn dân dã nhưng không kém phần hấp dẫn của TP Nha Trang. Với cách làm đơn giản, bạn cũng có thể trổ tài ở nhà để đãi gia đình mình. Món xôi thơm dẻo ăn kèm cá rim chua cay mặn ngọt, vị đậm đà của cá và nước sốt, một chút béo của mỡ hành, thêm chút đồ chua kích thích vị giác khiến bạn chỉ cần ăn một miếng là cứ muốn ăn mãi.', 10);
INSERT INTO public.recipe_steps VALUES (2598, '2025-11-20 17:10:54.493608', '2025-11-20 17:10:54.493608', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 435, 7, 'Cá cơm khô mua về bỏ đầu và phần sạn trong bụng cá, rửa nhiều lần cho sạch và bớt mặn, ngâm nước ấm 20 phút cho cá mềm rồi vớt ra, để ráo. Cho dầu ăn vào chảo, cho cá cơm vào rán vàng rồi vớt ra đĩa để ráo dầu.', 10);
INSERT INTO public.recipe_steps VALUES (2599, '2025-11-20 17:10:54.495202', '2025-11-20 17:10:54.495202', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 435, 6, 'Khi gạo nếp đã ngâm được 3-4 tiếng, vớt gạo ra rổ, để ráo nước, cho thêm 1 thìa café muối, xóc đều cho muối ngấm vào gạo rồi cho vào chõ đồ chín.', 10);
INSERT INTO public.recipe_steps VALUES (2600, '2025-11-20 17:10:54.496808', '2025-11-20 17:10:54.496808', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 435, 4, 'Pha hỗn hợp gồm: muối, dấm, đường, chanh, ớt băm nhỏ. Nếm chua cay mặn ngọt cân đối vừa miệng, cho củ cải và cà rốt vào xóc đều. Để khoảng 2h là ăn được.', 10);
INSERT INTO public.recipe_steps VALUES (2601, '2025-11-20 17:10:54.498432', '2025-11-20 17:10:54.498432', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 435, 2, 'Gạo nếp thơm đem vo sạch rồi ngâm nước khoảng 3-4 tiếng hoặc qua đêm để gạo mềm hơn.', 10);
INSERT INTO public.recipe_steps VALUES (2602, '2025-11-20 17:10:54.50007', '2025-11-20 17:10:54.50007', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 435, 10, 'Xới xôi nóng ra bát, dọn kèm cá khô rim, đồ chua, rắc hành phi, hành khô lên và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (2603, '2025-11-20 17:10:54.501128', '2025-11-20 17:10:54.501128', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 435, 8, 'Pha hỗn hợp nước sốt gồm: 3 thìa canh nước lọc, 1 thìa cafe tương ớt, 2 thìa canh đường, 1 thìa canh nước cốt chanh, 1/2 thìa bột ngọt, quậy đều.', 10);
INSERT INTO public.recipe_steps VALUES (2604, '2025-11-20 17:10:54.502715', '2025-11-20 17:10:54.502715', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 435, 3, 'Trong thời gian ngâm gạo. Bạn tiến hành làm đồ chua ăn kèm: Củ cải, cà rốt gọt vỏ, cắt miếng con chì hoặc tỉa hoa cho đẹp mắt. Cho vào bát xóc cùng 1 thìa canh muối để bớt chất hăng, vắt kiệt nước.', 10);
INSERT INTO public.recipe_steps VALUES (2605, '2025-11-20 17:10:54.504314', '2025-11-20 17:10:54.504314', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 435, 5, 'Hành khô thái mỏng, phi vàng, vớt ra để ráo dầu. Hành hoa thái nhỏ, cho vào bát con, dùng 3 thìa dầu ăn vừa phi nóng hành khô vào bát, trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (2606, '2025-11-20 17:10:54.652805', '2025-11-20 17:10:54.652805', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 436, 1, 'Cá làm sạch để ráo. Đậu rồng bỏ 2 đầu tước bỏ sơ thái khúc vừa ăn. Cà chua thái múi cau, hành, ngò thái khúc.', 10);
INSERT INTO public.recipe_steps VALUES (2607, '2025-11-20 17:10:54.654768', '2025-11-20 17:10:54.654768', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 436, 2, 'Phi thơm tỏi, cho cà chua vào xào. Nêm vào 1,5 muỗng canh bột canh, 1 muỗng canh đường, thêm 1 tô nước.', 10);
INSERT INTO public.recipe_steps VALUES (2608, '2025-11-20 17:10:54.656438', '2025-11-20 17:10:54.656438', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 436, 3, 'Nước sôi thì cho cá vào, cá chín thêm một chút nước mắm cho dậy hương thơm và nêm lại cho vừa miệng. Cuối cùng, cho phần đậu rồng vào nấu thêm 1 phút rồi tắt bếp cho thêm hành, ngò.', 10);
INSERT INTO public.recipe_steps VALUES (2609, '2025-11-20 17:10:54.749556', '2025-11-20 17:10:54.749556', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 437, 4, 'Cho thịt vào tô lớn, ướp với: 1 thìa canh hành tím băm, 3 thìa cà phê nước mắm, 1 thìa cà phê muối, 1/2 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu, 3 thìa cà phê nước hàng. Ướp tối thiểu trong 30 phút, hoặc ướp lâu hơn thì dùng màng bọc thực phẩm, bọc kín để tủ lạnh ướp thì thịt càng thấm gia vị, sẽ ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (2610, '2025-11-20 17:10:54.751172', '2025-11-20 17:10:54.751172', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 437, 7, 'Kho nhỏ lửa cho tới khi thịt mềm, nước hơi sánh. Lúc này, thêm măng đã xào vào, đảo đều cho thấm gia vị, nấu 5-7 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2611, '2025-11-20 17:10:54.752239', '2025-11-20 17:10:54.752239', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 437, 5, 'Cho một lớp hành khô mỏng dưới đáy nồi đất, cho thịt cùng nước ướp vào nồi. Thêm 1 bát nước dừa tươi, ít gốc hành cùng ớt để nguyên quả vào.', 10);
INSERT INTO public.recipe_steps VALUES (2612, '2025-11-20 17:10:54.753943', '2025-11-20 17:10:54.753943', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 437, 8, 'Rắc thêm hành lá, hạt tiêu và tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (2613, '2025-11-20 17:10:54.755555', '2025-11-20 17:10:54.755555', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 437, 3, 'Thịt thái miếng vừa ăn, cho vào nồi cùng lượng nước xâm xấp, thêm ít muối hạt, đun sôi, chần sơ và rửa sạch, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (2614, '2025-11-20 17:10:54.757133', '2025-11-20 17:10:54.757133', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 437, 6, 'Đun sôi, hạ nhỏ lửa, nêm nếm lại gia vị theo gia đình.', 10);
INSERT INTO public.recipe_steps VALUES (2615, '2025-11-20 17:10:54.758728', '2025-11-20 17:10:54.758728', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 437, 2, 'Cho một thìa canh mỡ lợn hoặc dầu ăn vào chảo, phi thơm tỏi rồi cho măng vào xào. Nêm một thìa canh nước mắm, 1/2 thìa cà phê hạt nêm, đảo đều, tắt bếp, múc măng ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (2616, '2025-11-20 17:10:54.760307', '2025-11-20 17:10:54.760307', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 437, 1, 'Măng cắt miếng vừa ăn, rửa sạch. Cho vào nồi, thêm nước xâm xấp, chút muối, luộc măng 2-3 lần nước cho tới khi hết nước đắng. Rửa sạch măng, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (2617, '2025-11-20 17:10:54.872127', '2025-11-20 17:10:54.872127', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 438, 11, 'Tắt bếp, múc ra thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (2618, '2025-11-20 17:10:54.873468', '2025-11-20 17:10:54.873468', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 438, 8, 'Sau đó, cho chim câu vào, đậy nắp, hầm ở lửa nhỏ khoảng 35-40 phút tùy vào độ già của chim câu.', 10);
INSERT INTO public.recipe_steps VALUES (2619, '2025-11-20 17:10:54.875124', '2025-11-20 17:10:54.875124', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 438, 9, 'Khi thịt chim đã mềm thì thêm ngải cứu còn lại vào, nấu thêm 5-6 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2620, '2025-11-20 17:10:54.876769', '2025-11-20 17:10:54.876769', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 438, 10, 'Lúc này, bạn nêm nếm lại gia vị, thêm hạt nêm rau củ (nếu thích).', 10);
INSERT INTO public.recipe_steps VALUES (2621, '2025-11-20 17:10:54.878349', '2025-11-20 17:10:54.878349', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 438, 2, 'Bồ câu làm sạch, bỏ hết ruột gan, xát muối hạt và rượu trắng rồi rửa sạch, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (2622, '2025-11-20 17:10:54.879943', '2025-11-20 17:10:54.879943', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 438, 4, 'Đeo găng tay, chà xát một ít muối và hạt nêm khắp mình bồ câu. Để ướp khoảng 30 phút cho thấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (2623, '2025-11-20 17:10:54.881542', '2025-11-20 17:10:54.881542', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 438, 1, 'Ngải cứu nhặt bỏ lá già, cuống rồi rửa sạch, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (2624, '2025-11-20 17:10:54.88313', '2025-11-20 17:10:54.88313', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 438, 5, 'Rửa sạch thuốc bắc, cắt nhỏ hoàng kỳ thành miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2625, '2025-11-20 17:10:54.884713', '2025-11-20 17:10:54.884713', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 438, 7, 'Nêm mắm, muối, đường theo khẩu vị gia đình.', 10);
INSERT INTO public.recipe_steps VALUES (2626, '2025-11-20 17:10:54.8863', '2025-11-20 17:10:54.8863', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 438, 3, 'Lấy 1/3-1/2 lượng ngải cứu và thuốc bắc nhồi vào bụng chim câu. Có thể dùng tăm cài lại để cho ngải cứu không bị rơi ra ngoài khi hầm.', 10);
INSERT INTO public.recipe_steps VALUES (2627, '2025-11-20 17:10:54.887916', '2025-11-20 17:10:54.887916', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 438, 6, 'Cho nước lượng vừa đủ vào nồi hầm. Thêm tất cả thuốc bắc vào hầm 15 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2628, '2025-11-20 17:10:55.016762', '2025-11-20 17:10:55.016762', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 439, 8, 'Thêm chút nước muối dưa chua để tạo vị chua cho canh, thêm nước đun sôi vừa đủ.', 10);
INSERT INTO public.recipe_steps VALUES (2629, '2025-11-20 17:10:55.018362', '2025-11-20 17:10:55.018362', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 439, 10, 'Cuối cùng thêm hành lá, thì là và ớt vào, đảo đều, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (2630, '2025-11-20 17:10:55.019946', '2025-11-20 17:10:55.019946', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 439, 5, 'Tiếp tục phi thơm hành, cho cà chua vào, nêm chút nước mắm để cà chua nhanh chín.', 10);
INSERT INTO public.recipe_steps VALUES (2631, '2025-11-20 17:10:55.021549', '2025-11-20 17:10:55.021549', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 439, 1, 'Moi nhặt bỏ sạn, tạp chất rồi cho vào rổ xả nước, rửa sạch, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (2632, '2025-11-20 17:10:55.022657', '2025-11-20 17:10:55.022657', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 439, 3, 'Cà chua rửa sạch, thái múi cau. Hành lá, thì là rửa sạch, thái rối hoặc thái nhỏ. Dưa muối vắt bớt nước chua, thái miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2633, '2025-11-20 17:10:55.024253', '2025-11-20 17:10:55.024253', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 439, 7, 'Sau đó, thêm moi đã xào vào đảo đều.', 10);
INSERT INTO public.recipe_steps VALUES (2634, '2025-11-20 17:10:55.02585', '2025-11-20 17:10:55.02585', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 439, 4, 'Cho 1 thìa canh mỡ lợn vào chảo, phi thơm hành khô. Sau đó, cho moi đã ướp vào đảo đều cho săn lại, múc ra để riêng (giúp cho moi không bị tanh).', 10);
INSERT INTO public.recipe_steps VALUES (2635, '2025-11-20 17:10:55.027436', '2025-11-20 17:10:55.027436', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 439, 2, 'Cho moi vào tô, ướp với 1 thìa cà phê hành tím băm, 1 thìa cà phê muối, 1/2 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu trong 10-15 phút cho ngấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (2637, '2025-11-20 17:10:55.030681', '2025-11-20 17:10:55.030681', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 439, 6, 'Cho thêm dưa cải chua vào xào mềm.', 10);
INSERT INTO public.recipe_steps VALUES (2638, '2025-11-20 17:10:55.165712', '2025-11-20 17:10:55.165712', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 440, 5, 'Cho 1,5 thìa canh mỡ lợn vào chảo đun nóng, phi thơm hành khô. Thêm thịt chim bồ câu đã băm nhuyễn vào xào trên lửa lớn. Khi thịt chim câu săn lại thì thêm nấm hương vào, đảo đều. Nêm nếm lại gia vị nếu cần.', 10);
INSERT INTO public.recipe_steps VALUES (2639, '2025-11-20 17:10:55.167926', '2025-11-20 17:10:55.167926', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 440, 10, 'Trình bày và thưởng thức: Múc xôi chim bồ câu nấm hương ra bát hoặc đĩa sâu lòng, rắc hành phi, trang trí chút rau mùi. Món này ăn nóng kèm dưa góp rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (2640, '2025-11-20 17:10:55.170655', '2025-11-20 17:10:55.170655', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 440, 2, 'Nấm hương ngâm nước nóng, rửa sạch, cắt nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2641, '2025-11-20 17:10:55.172777', '2025-11-20 17:10:55.172777', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 440, 4, 'Chim bồ câu làm sạch, chà xát với muối, rượu trắng, rửa sạch để khử mùi. Tiếp đến, thui sơ trên lửa để giúp thịt thơm hơn và không bị tanh. Lọc lấy thịt, bằm nhuyễn. Ướp phần thịt băm với 2 thìa cà phê nước mắm ngon, 1/2 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu trong 10-15 phút cho ngấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (2642, '2025-11-20 17:10:55.174373', '2025-11-20 17:10:55.174373', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 440, 1, 'Vo gạo nếp, ngâm 6-8 giờ, vớt ra để ráo. Sau đó, trộn với chút muối và dầu ăn (để tạo độ bóng).', 10);
INSERT INTO public.recipe_steps VALUES (2643, '2025-11-20 17:10:55.176518', '2025-11-20 17:10:55.176518', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 440, 3, 'Hành khô bóc vỏ, thái đều, cho hành chảo đảo đều tay. Khi hành hơi vàng, vớt ra, để giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (2644, '2025-11-20 17:10:55.178114', '2025-11-20 17:10:55.178114', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 440, 8, 'Để xôi ngon nên đồ 2 lần lửa: Lần 1 là đồ xôi tầm 30 phút thì múc ra mâm hoặc mẹt, dàn đều ra, để nguội. Đồ lần 2: Cho xôi vào, vẩy thêm chút nước, mỡ gà vào trộn đều. Đồ thêm 10 phút để mỡ gà thấm vào để xôi căng bóng, thơm ngon.', 10);
INSERT INTO public.recipe_steps VALUES (2645, '2025-11-20 17:10:55.179698', '2025-11-20 17:10:55.179698', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 440, 9, 'Cho thịt chim bồ câu và nấm hương đã xào vào, đảo đều, đồ thêm một chút cho nóng.', 10);
INSERT INTO public.recipe_steps VALUES (2646, '2025-11-20 17:10:55.181861', '2025-11-20 17:10:55.181861', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 440, 6, 'Đồ xôi: Cần điều chỉnh lượng nước phù hợp, giữ nhiệt độ ổn định và đồ 2 lần lửa sẽ giúp xôi dẻo, thơm ngon.', 10);
INSERT INTO public.recipe_steps VALUES (2647, '2025-11-20 17:10:55.183561', '2025-11-20 17:10:55.183561', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 440, 7, 'Đổ nước vào ngập 1/2 dung tích của nồi/chõ để đồ xôi. Lót một lớp vải màn vào chõ xôi. Bạn nên dùng tay hoặc bát nhỏ múc gạo nếp cho từ từ vào và dàn đều. Cách làm này giúp cho các hạt nếp không bị ‘bí’, khoảng cách dàn đều, để hơi nước lưu thông và xôi chín đều. Nên đun sôi nồi nước trước, rồi mới cho chõ xôi vào để giúp nhiệt ổn định. Sau đó, giảm lửa vừa phải để xôi chín từ từ.', 10);
INSERT INTO public.recipe_steps VALUES (2648, '2025-11-20 17:10:55.280666', '2025-11-20 17:10:55.280666', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 441, 4, 'Đặt nồi đồ xôi lên bếp, đổ nước nửa nồi đáy. Khi nước bốc hơi, đổ gạo từ từ nhẹ tay vào xửng, đậy kín, đun to lửa khoảng 40-45 phút, hạt xôi nở mọng và trong, gấc chuyển sang màu đỏ vàng là xôi chín.', 10);
INSERT INTO public.recipe_steps VALUES (2649, '2025-11-20 17:10:55.282265', '2025-11-20 17:10:55.282265', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 441, 3, 'Trộn gấc được đánh nhuyễn ở trên với gạo, bóp đều cho thịt gấc ngấm và bao quanh hạt gạo. Cho vào xửng hấp.', 10);
INSERT INTO public.recipe_steps VALUES (2650, '2025-11-20 17:10:55.283826', '2025-11-20 17:10:55.283826', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 441, 2, 'Chọn quả gấc nếp chín đỏ tươi, vỏ mỏng, gai thưa. Bổ đôi quả gấc lấy ruột, cho 1 thìa cà phê rượu vào đánh nhuyễn. (Nếu có thời gian, cho hỗn hợp gấc đã trộn với rượu vào tủ lạnh, để qua đêm, gấc sẽ lên màu đỏ đẹp hơn).', 10);
INSERT INTO public.recipe_steps VALUES (2651, '2025-11-20 17:10:55.285468', '2025-11-20 17:10:55.285468', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 441, 1, 'Gạo nếp chọn loại nếp cái, hạt trắng ngà, mẩy đều, không lẫn gạo tẻ, không có hạt mốc đen. Gạo vo đãi sạch, đem ngâm 6-8 giờ. Vớt gạo ra, dội lại nước lã, để ráo rồi cho muối trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (2652, '2025-11-20 17:10:55.287577', '2025-11-20 17:10:55.287577', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 441, 5, 'Cho 2 thìa canh đường, 1 thìa canh dầu ăn và vẩy nốt 1 thìa cà phê rượu còn lại vào đảo đều, đậy vung đun tiếp khoảng 5 phút nữa để đường tan, ngấm đều vào xôi, đơm vào đĩa hoặc nén vào khuôn tuỳ ý.', 10);
INSERT INTO public.recipe_steps VALUES (2653, '2025-11-20 17:10:55.583942', '2025-11-20 17:10:55.583942', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 442, 1, 'Móng giò và chân giò đem thui bằng rơm (nếu không có thì bọc giấy báo và đốt) sao cho lớp bì ngả màu sậm nâu vàng là được. Sau đó, rửa sạch, chặt miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2654, '2025-11-20 17:10:55.586521', '2025-11-20 17:10:55.586521', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 442, 2, 'Ướp móng giò, chân giò với: 1 bát riềng giã nhỏ, 5-6 thìa canh mẻ, 2 thìa canh mắm tôm, 2 thìa canh nước nghệ tươi (giã nhỏ, vắt lấy nước), 2 thìa canh dầu điều, 1 thìa canh rượu trắng, 1 thìa canh đường, 1 thìa canh nước mắm, 1 thìa cà phê bột canh, 1 thìa cà phê hạt nêm. Dùng đũa đảo đều và ướp tối thiểu trong 1 giờ cho ngấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (2655, '2025-11-20 17:10:55.587733', '2025-11-20 17:10:55.587733', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 442, 4, 'Cách nấu chân giò giả cầy: Nên nấu tối thiểu 2 lửa sẽ giúp món ăn tròn vị và thơm ngon:', 10);
INSERT INTO public.recipe_steps VALUES (2656, '2025-11-20 17:10:55.588753', '2025-11-20 17:10:55.588753', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 442, 3, 'Phần độn ăn thêm (tùy chọn theo khẩu vị mỗi gia đình): Măng củ tươi, thái miếng vừa ăn, luộc hết đắng và xào sơ.', 10);
INSERT INTO public.recipe_steps VALUES (2657, '2025-11-20 17:10:55.590759', '2025-11-20 17:10:55.590759', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 442, 5, 'Cho chân giò đã ướp vào nồi, bật bếp đảo thịt và móng cho săn lại để gia vị ngấm gia vị. Đổ nước xâm xấp, thêm măng đã xào vào và đun sôi, hạ lửa nhỏ ninh trong 30 phút, tắt bếp.Trước khi gần ăn 30 phút thì bật bếp, đun 30-45 phút tùy theo khẩu vị mỗi người (thích giòn sần sật hoặc mềm). Cuối cùng rắc hành lá, rau răm, rau ngổ thái rối, đảo đều và tắt bếp, múc ra thưởng thức nóng với bún hoặc cơm đều ngon.', 10);
INSERT INTO public.recipe_steps VALUES (2658, '2025-11-20 17:10:55.724531', '2025-11-20 17:10:55.724531', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 443, 1, 'Bí ngòi cắt bỏ cuống, rửa sạch, bào mỏng theo chiều dài. Hành lá chần qua nước sôi.', 10);
INSERT INTO public.recipe_steps VALUES (2659, '2025-11-20 17:10:55.726119', '2025-11-20 17:10:55.726119', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 443, 6, 'Nêm nếm lại vừa miệng rồi trình bày ra tô. Rắc chút hành lá và tiêu.', 10);
INSERT INTO public.recipe_steps VALUES (2741, '2025-11-20 17:10:58.243608', '2025-11-20 17:10:58.243608', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 455, 6, 'Phi thơm củ hành, cho nấm hương, mộc nhĩ, nấm đùi gà, ngô ngọt vào xào, tiếp đến là cà rốt, thêm hai thìa cà phê bột nêm.', 10);
INSERT INTO public.recipe_steps VALUES (2660, '2025-11-20 17:10:55.728214', '2025-11-20 17:10:55.728214', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 443, 4, 'Đổ 1 lít nước vào nồi, đặt lên bếp. Khi nước bắt đầu sôi, cho thêm chút muối, cho bí đã cuộn vào, sau đó nêm thêm chút nước chấm 3 Miền cho dậy vị.', 10);
INSERT INTO public.recipe_steps VALUES (2661, '2025-11-20 17:10:55.729273', '2025-11-20 17:10:55.729273', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 443, 5, 'Nấu trong vòng 3-5 phút, đến khi thấy tôm chín chuyển màu đỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2662, '2025-11-20 17:10:55.730884', '2025-11-20 17:10:55.730884', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 443, 2, 'Tôm tươi bóc vỏ, bỏ đầu, bỏ chỉ lưng, băm nhuyễn cùng hành tím. Nêm vào một muỗng cà phê bột nêm, hạt tiêu và chút nước chấm 3 Miền rồi trộn nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (2663, '2025-11-20 17:10:55.732519', '2025-11-20 17:10:55.732519', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 443, 3, 'Dùng muỗng múc tôm phết đều lên những lát bí. Sau đó cuộn tròn lát bí, dùng hành lá buộc lại.', 10);
INSERT INTO public.recipe_steps VALUES (2664, '2025-11-20 17:10:55.852981', '2025-11-20 17:10:55.852981', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 444, 2, 'Cho ngao và lượng nước lạnh vừa đủ vào nồi, đun sôi. Khi ngao vừa há miệng, đảo đều, vớt bỏ bọt, tắt bếp, vớt ra. Lọc lấy phần nước luộc ngao để làm nước dùng nấu canh.', 10);
INSERT INTO public.recipe_steps VALUES (2665, '2025-11-20 17:10:55.856287', '2025-11-20 17:10:55.856287', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 444, 5, 'Phi thơm hành khô với 1 thìa canh mỡ lợn hoặc dầu ăn. Cho cà chua và nêm chút nước mắm vào xào chín mềm. Sau đó thêm dứa, sấu vào xào sơ.', 10);
INSERT INTO public.recipe_steps VALUES (2666, '2025-11-20 17:10:55.858384', '2025-11-20 17:10:55.858384', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 444, 7, 'Khi sấu chín, lấy ra dằm nát cho vào nồi, bỏ phần vỏ ra ngoài.', 10);
INSERT INTO public.recipe_steps VALUES (2667, '2025-11-20 17:10:55.859971', '2025-11-20 17:10:55.859971', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 444, 6, 'Đổ nước luộc ngao vào, đun sôi, hớt bọt. Nêm nếm gia vị mắm, muối, đường, hạt nêm theo khẩu vị gia đình.', 10);
INSERT INTO public.recipe_steps VALUES (2668, '2025-11-20 17:10:55.861553', '2025-11-20 17:10:55.861553', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 444, 4, 'Dứa gọt vỏ, thái miếng vừa ăn. Cà chua rửa sạch, thái múi cau. Giá đỗ rửa sạch, để ráo nước. Rau răm, hành lá rửa sạch rồi thái nhỏ hoặc thái rối.', 10);
INSERT INTO public.recipe_steps VALUES (2669, '2025-11-20 17:10:55.863658', '2025-11-20 17:10:55.863658', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 444, 1, 'Ngao mua về ngâm vào nước vo gạo hoặc nước muối loãng, cắt thêm vài lát ớt để hết bùn đất. Sau đó, chà xát vỏ, rửa sạch ngao.', 10);
INSERT INTO public.recipe_steps VALUES (2670, '2025-11-20 17:10:55.865268', '2025-11-20 17:10:55.865268', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 444, 3, 'Tách bỏ vỏ, lấy phần thịt ngao, rửa sạch. Ướp thịt ngao với chút nước mắm, hạt nêm.', 10);
INSERT INTO public.recipe_steps VALUES (2671, '2025-11-20 17:10:55.867383', '2025-11-20 17:10:55.867383', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 444, 8, 'Cho thịt ngao vào nồi, đun sôi. Rắc thêm hành lá, rau răm và tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (2672, '2025-11-20 17:10:56.140302', '2025-11-20 17:10:56.140302', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 445, 3, 'Mộc nhĩ, nấm hương ngâm nước nóng cho nở, rửa sạch, thái nhỏ. Tôm bóc vỏ, thái hạt lựu.', 10);
INSERT INTO public.recipe_steps VALUES (2673, '2025-11-20 17:10:56.142396', '2025-11-20 17:10:56.142396', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 445, 5, 'Trải cánh hoa sen ra lòng bàn tay, đặt phần cong cánh thuyền hướng lên trên. Múc lượng nhân vừa phải cho vào rồi nhẹ nhàng cuộn đều tay.', 10);
INSERT INTO public.recipe_steps VALUES (2674, '2025-11-20 17:10:56.144338', '2025-11-20 17:10:56.144338', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 445, 2, 'Cánh hoa sen ngâm nước muỗi loãng, rửa sạch. Tách riêng các phần: Cánh sen to (lớp cánh thứ 2 từ ngoài vào) dùng để gói chả. Các cánh hoa sen nhỏ bên trong thì thái nhỏ cùng tua nhị sen để cho vào nhân chả.', 10);
INSERT INTO public.recipe_steps VALUES (2675, '2025-11-20 17:10:56.146438', '2025-11-20 17:10:56.146438', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 445, 1, 'Chọn hoa sen cánh to, mùi thơm như sen bách diệp hồng. Nên chọn sen nụ chuẩn bị nở vì lưu giữ nhiều hương thơm, giúp chả ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (2676, '2025-11-20 17:10:56.148103', '2025-11-20 17:10:56.148103', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 445, 6, 'Cho lượng dầu ăn vừa đủ vào chảo, cho chả cánh hoa sen vào chiên ở lửa vừa. Khi chả chín vàng, dậy mùi thơm thì tắt bếp, cho ra giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (2677, '2025-11-20 17:10:56.149688', '2025-11-20 17:10:56.149688', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 445, 4, 'Cho phần thịt nạc xay, tôm thái hạt lựu cùng cánh sen nhỏ thái chỉ, tua nhị sen, mộc nhĩ, nấm hương trộn đều cùng các gia vị (1 thìa cà phê muối, 1 thìa cà phê hạt nêm, 1 thìa canh mỡ lợn, 1 quả trứng gà, 1 thìa canh bột bắp). Ướp khoảng 10 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2678, '2025-11-20 17:10:56.535982', '2025-11-20 17:10:56.535982', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 446, 5, 'Để nước sốt sánh hơn, bạn pha chút bột bắp vào nước, cho từ từ và khuấy đều cho tới khi hỗn hợp nước sốt quyện sánh lại.', 10);
INSERT INTO public.recipe_steps VALUES (2679, '2025-11-20 17:10:56.53809', '2025-11-20 17:10:56.53809', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 446, 2, 'Cho me vào bát, thêm nước nóng ngâm sau đó dùng thìa dầm nát, lọc lấy nước cốt, bỏ hạt.', 10);
INSERT INTO public.recipe_steps VALUES (2680, '2025-11-20 17:10:56.539137', '2025-11-20 17:10:56.539137', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 446, 1, 'Trứng rửa sạch, đổ ngập nước, thêm chút muối hạt, giấm. Bật bếp đun sôi, hạ nhỏ lửa đun 6-8 phút, vớt ra cho vào thau nước mát hoặc nước đá rồi bóc vỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2681, '2025-11-20 17:10:56.540716', '2025-11-20 17:10:56.540716', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 446, 4, 'Cho chút mỡ lợn vào chảo, phi thơm hành tỏi băm. Thêm hỗn hợp nước sốt me vào, khuấy đều, đun nhỏ lửa cho hơi sánh. Thêm trứng cút lộn vào, đảo nhẹ tay cho ngấm đều gia vị. Có thể thêm 1 thìa cà phê dầu màu điều (tùy chọn).', 10);
INSERT INTO public.recipe_steps VALUES (2682, '2025-11-20 17:10:56.542538', '2025-11-20 17:10:56.542538', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 446, 6, 'Thêm gừng, rau răm, ớt, tắp bếp.', 10);
INSERT INTO public.recipe_steps VALUES (2683, '2025-11-20 17:10:56.543603', '2025-11-20 17:10:56.543603', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 446, 3, 'Trong một bát nhỏ, múc 3 thìa canh nước sốt me, 3 thìa canh đường, 3 thìa canh nước mắm nhạt 27-30 độ đạm, 2 thìa canh tương ớt, khuấy tan đều.', 10);
INSERT INTO public.recipe_steps VALUES (2684, '2025-11-20 17:10:56.694311', '2025-11-20 17:10:56.694311', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 447, 1, 'Dọc mùng đem phơi ở nơi râm mát cho hơi héo. Dùng khăn vải lau các mặt thân mùng, rửa nhiều lần cho sạch, để ráo nước. Cắt thành từng khúc vừa ăn. Ngâm vào nước muối loãng khoảng 30 phút (để không bị ngứa). Sau đó, rửa sạch 2-3 lần nước lã, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (2685, '2025-11-20 17:10:56.695916', '2025-11-20 17:10:56.695916', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 447, 3, 'Lọc nước vo gạo lấy phần nước trong.', 10);
INSERT INTO public.recipe_steps VALUES (2686, '2025-11-20 17:10:56.697508', '2025-11-20 17:10:56.697508', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 447, 4, 'Cho nước vo gạo vào nồi cùng 1,5 muỗng canh muối hạt, 1-1,5 muỗng canh đường, khuấy tan, bật bếp đun sôi. Khi sôi, hạ nhỏ lửa, vớt bỏ bọt, tắt bếp, để nước nguội hoàn toàn.', 10);
INSERT INTO public.recipe_steps VALUES (2687, '2025-11-20 17:10:56.699274', '2025-11-20 17:10:56.699274', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 447, 6, 'Đổ nước vo gạo (đã nguội) vào ngập, dùng đá hoặc vật nặng nén trên bề mặt cho mùng không nổi lên. Đậy nắp và để nơi thoáng mát 3-4 ngày là mùng chua và có màu hơi vàng.', 10);
INSERT INTO public.recipe_steps VALUES (2688, '2025-11-20 17:10:56.701395', '2025-11-20 17:10:56.701395', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 447, 2, 'Cho dọc mùng vào chậu, thêm 1 - 1,5 thìa canh muối hạt, đeo găng tay bóp đều.', 10);
INSERT INTO public.recipe_steps VALUES (2689, '2025-11-20 17:10:56.703551', '2025-11-20 17:10:56.703551', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 447, 5, 'Vắt bớt nước muối lúc trước khi ướp. Cho mùng vào lọ.', 10);
INSERT INTO public.recipe_steps VALUES (2690, '2025-11-20 17:10:56.850457', '2025-11-20 17:10:56.850457', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 448, 7, 'Thêm nước mắm, tương ớt, ớt bột tạo màu, sa tế (điều chỉnh theo khẩu vị gia đình. Nếu có trẻ nhỏ thì không thêm ớt, sa tế).', 10);
INSERT INTO public.recipe_steps VALUES (2691, '2025-11-20 17:10:56.852156', '2025-11-20 17:10:56.852156', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 448, 5, 'Tỏi ớt băm nhỏ, hành lá rửa sạch cắt nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2692, '2025-11-20 17:10:56.853818', '2025-11-20 17:10:56.853818', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 448, 4, 'Các loại hạt khác (nếu dùng) cũng cần rang chín, bỏ vỏ như hạt hướng dương, hạt óc chó, hạt hạnh nhân...', 10);
INSERT INTO public.recipe_steps VALUES (2693, '2025-11-20 17:10:56.855389', '2025-11-20 17:10:56.855389', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 448, 1, 'Cá nhặt bỏ sạn và tạp chất, ngâm nước ấm 5-8 phút, rửa sạch, để thật ráo (hoặc thấm khô).', 10);
INSERT INTO public.recipe_steps VALUES (2694, '2025-11-20 17:10:56.857002', '2025-11-20 17:10:56.857002', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 448, 8, 'Rim cá:Cho 2-3 thìa canh mỡ lợn vào chảo, phi thơm tỏi. Cho cá cơm sữa vào rang cho tới khi hơi ngả vàng. Cho hỗn hợp nước sốt vào, đảo đều cho tới khi keo lại, ánh lên màu nâu đỏ đẹp mắt. Thêm lạc (đậu phộng rang), vừng rang, hành lá, ớt tươi vào đảo đều, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (2695, '2025-11-20 17:10:56.858596', '2025-11-20 17:10:56.858596', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 448, 3, 'Vừng trắng rang chín.', 10);
INSERT INTO public.recipe_steps VALUES (2696, '2025-11-20 17:10:56.860678', '2025-11-20 17:10:56.860678', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 448, 6, 'Làm nước sốt:Thắng đường thành nước hàng màu hổ phách. Xem chi tiết:Tại đây.', 10);
INSERT INTO public.recipe_steps VALUES (2697, '2025-11-20 17:10:56.862258', '2025-11-20 17:10:56.862258', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 448, 2, 'Cho lạc lên chảo rang ở lửa nhỏ vừa, đảo đều tay cho tới khi chín vàng. Lấy lạc bọc vào giấy/báo kín, để một lúc tạo độ giòn và dễ bong vỏ, chà xát và bỏ vỏ lụa.', 10);
INSERT INTO public.recipe_steps VALUES (2698, '2025-11-20 17:10:57.052356', '2025-11-20 17:10:57.052356', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 449, 2, 'Rửa sạch các loại rau gia vị (lá lốt, thì là, rau răm, hành lá), vẩy ráo nước và thái nhỏ. Hành khô băm nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2699, '2025-11-20 17:10:57.053435', '2025-11-20 17:10:57.053435', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 449, 4, 'Khi dầu trong chảo đủ nóng, hạ lửa vừa. Dùng thìa múc chả cá đặt vào chiên. Trở đều hai mặt để chả chín đều. Khi chả có màu vàng ươm, dậy mùi thơm thì vớt ra để giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (2700, '2025-11-20 17:10:57.05503', '2025-11-20 17:10:57.05503', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 449, 3, 'Trong một tô trộn lớn, cho cá ngần, thịt băm cùng 2 quả trứng gà, các rau gia vị thái nhỏ và bột bắp vào trộn đều. Thêm gia vị: 1,5-2 thìa cà phê nước mắm, 1/2 thìa cà phê muối, 1 thìa cà phê hạt nêm, 1/2 thìa cà phê ớt bột hoặc ớt tươi (nếu thích cay) và chút hạt tiêu vào trộn đều, để ướp trong 12-15 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2701, '2025-11-20 17:10:57.056618', '2025-11-20 17:10:57.056618', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 449, 1, 'Nhặt sạch tạp chất, rửa sạch cá, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (2702, '2025-11-20 17:10:57.228244', '2025-11-20 17:10:57.228244', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 450, 1, 'Cá cắt khúc hoặc đầu cá chà muối hạt, chanh rửa sạch. Ướp cá với một thìa canh hành khô băm, 1 thìa cà phê muối, 1/2 thìa cà phê hạt nêm tối thiểu 15 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2703, '2025-11-20 17:10:57.230362', '2025-11-20 17:10:57.230362', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 450, 5, 'Trút tất cả rau sắn, cà chua, tóp mỡ vào nồi, đổ nước sôi cùng chút nước muối dưa sắn vào xăm xắp, cho cá đã rán sơ vào, bật bếp đun. Khi sôi, hạ nhỏ lửa nấu khoảng 30 phút. Nêm nếm lại theo khẩu vị.', 10);
INSERT INTO public.recipe_steps VALUES (2704, '2025-11-20 17:10:57.231992', '2025-11-20 17:10:57.231992', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 450, 4, 'Tiếp tục phi thơm hành khô, cho cà chua vào xào sơ. Sau đó, cho rau sắn (đã rửa sạch) vào xào 8-10 phút. Thêm tóp mỡ (tùy theo sở thích).', 10);
INSERT INTO public.recipe_steps VALUES (2705, '2025-11-20 17:10:57.234207', '2025-11-20 17:10:57.234207', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 450, 3, 'Cho 1-2 thìa canh mỡ lợn, cho cá đã ướp vào rán sơ, lấy ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (2706, '2025-11-20 17:10:57.236875', '2025-11-20 17:10:57.236875', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 450, 6, 'Khi rau nhừ, cá chín ngấm gia vị thì thêm ớt (nếu thích ăn cay), tắt bếp và múc ra ăn nóng.', 10);
INSERT INTO public.recipe_steps VALUES (2707, '2025-11-20 17:10:57.239022', '2025-11-20 17:10:57.239022', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 450, 2, 'Làm tóp mỡ:Cho chút dầu ăn vào chảo, cho mỡ vào chiên ở lửa vừa. Đảo thường xuyên cho tới khi tóp ngả vàng đều, vớt ra, phần mỡ lợn để riêng dùng cho các món xào nấu sau này.', 10);
INSERT INTO public.recipe_steps VALUES (2708, '2025-11-20 17:10:57.301824', '2025-11-20 17:10:57.301824', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 451, 4, 'Rửa lại bằng nước đun sôi để nguội cho hết nhớt, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (2709, '2025-11-20 17:10:57.304003', '2025-11-20 17:10:57.304003', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 451, 2, 'Đun sôi một nồi nước, thêm một nhánh gừng giã, một thìa cà phê muối, thả chân gà vào luộc.', 10);
INSERT INTO public.recipe_steps VALUES (2710, '2025-11-20 17:10:57.305589', '2025-11-20 17:10:57.305589', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 451, 6, 'Đổ tất cả hỗn hợp nước trộn vào chân gà, trộn thật đều (nếm lại một lần nữa cho vừa ăn).', 10);
INSERT INTO public.recipe_steps VALUES (2711, '2025-11-20 17:10:57.307692', '2025-11-20 17:10:57.307692', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 451, 3, 'Vớt ra chậu nước đá, ngâm khoảng 30 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2712, '2025-11-20 17:10:57.30974', '2025-11-20 17:10:57.30974', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 451, 5, 'Hỗn hợp trộn chân gà:4 thìa canh xì dầu + 3 thìa canh dấm ăn + 2 thìa canh đường + 1 thìa cà phê bột canh + 1 thìa canh nước cốt chanh hoặc quất + 1 thìa canh tỏi băm + 1 thìa cà phê gừng băm + 2 thìa canh vừng rang + 2 thìa canh ớt băm + 1 thìa canh dầu mè, trộn đều, nếm lại thấy chua chua, mặn, ngọt, cay vừa miệng là được.', 10);
INSERT INTO public.recipe_steps VALUES (2713, '2025-11-20 17:10:57.311835', '2025-11-20 17:10:57.311835', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 451, 1, 'Chân gà bóp gừng và rượu, rửa sạch, chặt khúc vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2714, '2025-11-20 17:10:57.313408', '2025-11-20 17:10:57.313408', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 451, 7, 'Dùng màng bọc thực phẩm bọc kín, cất ngăn mát tủ lạnh trong 2-3h trước khi ăn, hoặc để càng lâu chân gà sẽ càng ngấm gia vị và da sẽ giòn hơn.', 10);
INSERT INTO public.recipe_steps VALUES (2715, '2025-11-20 17:10:57.497092', '2025-11-20 17:10:57.497092', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 452, 2, 'Cho 2 thìa canh mỡ lợn vào chảo, thêm hành khô băm nhỏ vào phi thơm. Cho cà chua thái múi cau vào, đảo đều. Thêm 3 thìa canh mắm, 1 thìa cà phê muối, đậy vung đun lửa vừa.', 10);
INSERT INTO public.recipe_steps VALUES (2716, '2025-11-20 17:10:57.499049', '2025-11-20 17:10:57.499049', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 452, 3, 'Cho 1 bát nhỏ nước, đun sôi, hạ nhỏ lửa đun tiếp cho cà chua mềm nhuyễn, nước hơi sền sệt thì thêm tóp mỡ, nêm nếm lại gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (2717, '2025-11-20 17:10:57.500671', '2025-11-20 17:10:57.500671', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 452, 4, 'Rắc thêm hành lá, đầu hành củ chẻ (nếu có), hạt nêm, đảo đều và tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (2718, '2025-11-20 17:10:57.503886', '2025-11-20 17:10:57.503886', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 452, 1, 'Mỡ lợn cắt miếng vừa phải hoặc dài chút, chần sơ bằng nước sôi cùng chút muối. Vớt ra, rửa sạch, để ráo nước. Cho chút dầu ăn vào chảo để chống cháy. Cho mỡ lợn vào chiên ở lửa vừa. Khi tóp mỡ ngả vàng thì vớt ra, để riêng. Phần mỡ nước để dùng dần cho các món xào, nấu.', 10);
INSERT INTO public.recipe_steps VALUES (2719, '2025-11-20 17:10:57.858404', '2025-11-20 17:10:57.858404', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 453, 5, 'Khi ăn, thái lát mỏng, rưới phần nước sốt sánh lên trên rất hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (2720, '2025-11-20 17:10:57.859467', '2025-11-20 17:10:57.859467', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 453, 1, 'Lá chè chát (chè tươi, chè xanh) rửa sạch, vò và om cùng nước sôi để lấy nước ngâm, rửa thịt bò. Tinh chất từ nước chè sẽ giúp khử mùi tanh, hoi của thịt bò rất tốt. Sau đó, thấm thật khô.', 10);
INSERT INTO public.recipe_steps VALUES (2721, '2025-11-20 17:10:57.861063', '2025-11-20 17:10:57.861063', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 453, 3, 'Kho lần 1:Giúp gân bò co lại: Cho thịt cùng toàn bộ nước sốt ướp vào nồi, bật bếp đun lửa to. Khi nước sôi, hạ nhỏ lửa đun liu riu. Trở thịt để thấm đều gia vị. Sau 15 phút, tắt bếp, để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (2722, '2025-11-20 17:10:57.862711', '2025-11-20 17:10:57.862711', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 453, 4, 'Kho lần 2: Giúp ngấm sâu và rút gia vị vào thịt giúp săn chắc, đậm đà: Bật bếp, đun sôi. Lúc này nước từ tiết ra khá nhiều, hạ nhỏ lửa đun liu riu. Thỉnh thoảng lật trở để gia vị thấm đều các mặt. Sau khoảng 45 phút nước sốt mắm mật quánh sánh lại, bao phủ quanh thịt. Lúc này, tắt bếp, để nguội. Khi thịt nguội, để vào hộp, cho vào tủ lạnh dùng dần.', 10);
INSERT INTO public.recipe_steps VALUES (2723, '2025-11-20 17:10:57.863828', '2025-11-20 17:10:57.863828', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 453, 2, 'Ướp thịt bò:Thời gian ướp càng lâu thì món ăn càng ngon và đậm đà: Gừng, hành, tỏi, sả băm nhuyễn, ớt đập dập, hoa hồi, quế bẻ nhỏ. Cho thịt bò vào âu lớn, thêm tất cả gia vị ở trên cùng nước sốt ở trên (mắm, mật mía, dầu điều), hạt tiêu sọ giã dập vào trộn, đeo găng tay bóp đều. Bọc kín để tủ lạnh tối thiểu 2 giờ, tốt nhất để qua đêm thì khi kho sẽ ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (2724, '2025-11-20 17:10:58.030381', '2025-11-20 17:10:58.030381', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 454, 2, 'Các loại rau sống rửa sạch ngâm nước muối loãng vớt ra để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (2725, '2025-11-20 17:10:58.032586', '2025-11-20 17:10:58.032586', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 454, 4, 'Hành lá lấy phần lá, nhúng vào nồi nước sôi nhưng không được để lâu vớt ra bát nước lạnh, vớt ra để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (2726, '2025-11-20 17:10:58.034706', '2025-11-20 17:10:58.034706', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 454, 7, 'Có thể pha: 3 thìa canh dấm táo + 10ml dầu oliu + chút xíu muối tinh + chút hạt tiêu + ớt tươi + chút tỏi băm, hoà đều rưới từ dưới lên trên các miếng dưa chuột cuộn thịt và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (2727, '2025-11-20 17:10:58.036741', '2025-11-20 17:10:58.036741', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 454, 3, 'Cà rốt cắt thành khoanh ngắn khoảng 6 cm cắt sợi mỏng vừa.', 10);
INSERT INTO public.recipe_steps VALUES (2728, '2025-11-20 17:10:58.038761', '2025-11-20 17:10:58.038761', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 454, 1, 'Dưa chuột rửa sạch, ngâm nước muối loãng 15-20p, vớt ra để ráo nước dùng dao nạo thành các sợi dài mỏng vừa.', 10);
INSERT INTO public.recipe_steps VALUES (2729, '2025-11-20 17:10:58.041268', '2025-11-20 17:10:58.041268', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 454, 5, 'Lườn gà hoặc thịt lợn thăn rửa sạch, đem luộc với chút gừng đập dập và chút dấm để thịt dai và trắng, thịt chín vớt ra để nguội thái mỏng hoặc xé sợi to.', 10);
INSERT INTO public.recipe_steps VALUES (2730, '2025-11-20 17:10:58.042864', '2025-11-20 17:10:58.042864', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 454, 6, 'Đặt lát dưa chuột lên đĩa, sau đó lần lượt đặt rau sống, một miếng thịt, rau thơm, chút cà rốt rồi từ từ cuộn lại, để miếng dưa chuột được chắc thì các bạn buộc lại bằng lá hành đã trần (Nếu làm ăn ngay không cần buộc hành lá).', 10);
INSERT INTO public.recipe_steps VALUES (2731, '2025-11-20 17:10:58.223196', '2025-11-20 17:10:58.223196', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 455, 3, 'Ngô ngọt bóc vỏ, dùng dao gọt lấy phần thịt (vỏ để lại).', 10);
INSERT INTO public.recipe_steps VALUES (2732, '2025-11-20 17:10:58.22571', '2025-11-20 17:10:58.22571', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 455, 1, 'Đậu phụ rán vàng, cắt nhẹ một đầu, moi hết ruột mềm bên trong.', 10);
INSERT INTO public.recipe_steps VALUES (2733, '2025-11-20 17:10:58.227299', '2025-11-20 17:10:58.227299', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 455, 11, 'Xếp bao bố đậu phụ ra đĩa, rưới phần nước sốt lên trên, trang trí cho đẹp mắt và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (2734, '2025-11-20 17:10:58.229394', '2025-11-20 17:10:58.229394', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 455, 9, 'Hành hoa hoặc bông hẹ trần qua. Tháo phần dây buộc bằng vỏ bắp ở bao bố thay bằng lá hành hoặc bông hẹ để đẹp mắt hơn.', 10);
INSERT INTO public.recipe_steps VALUES (2735, '2025-11-20 17:10:58.23177', '2025-11-20 17:10:58.23177', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 455, 5, 'Cà rốt bào sợi thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2736, '2025-11-20 17:10:58.233376', '2025-11-20 17:10:58.233376', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 455, 2, 'Nấm hương, mộc nhĩ ngâm cho nở, cắt chân rửa sạch, băm nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2737, '2025-11-20 17:10:58.235505', '2025-11-20 17:10:58.235505', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 455, 7, 'Trộn ruột đậu phụ với phần nhân vừa xào xong.', 10);
INSERT INTO public.recipe_steps VALUES (2738, '2025-11-20 17:10:58.237608', '2025-11-20 17:10:58.237608', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 455, 8, 'Nhồi tất cả phần nhân vào vỏ đậu phụ đã moi hết ruột, chừa lại một đoạn để buộc. Túm nhẹ "bao bố", dùng vỏ ngô tước nhỏ buộc lại. Xếp tất cả "đậu bao bố" đã nhồi vào hấp 15 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2739, '2025-11-20 17:10:58.239725', '2025-11-20 17:10:58.239725', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 455, 4, 'Nấm đùi gà rửa sạch thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2740, '2025-11-20 17:10:58.241313', '2025-11-20 17:10:58.241313', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 455, 10, 'Phần sốt:Phi thơm tỏi băm, hòa hai thìa canh dầu hào chay, hai thìa canh xì dầu với một bát nước đổ vào nồi tỏi phi thơm, thêm 1/2 thìa canh bột năng hoà tan với chút nước, khuấy đều, đun nhỏ lửa, phần sốt hơi sền sệt là được.', 10);
INSERT INTO public.recipe_steps VALUES (2742, '2025-11-20 17:10:58.422662', '2025-11-20 17:10:58.422662', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 456, 3, 'Cho thịt vào chảo hoặc nồi rán nhỏ lửa, để tự tiết mỡ, hơi thành tóp (chú ý xém vàng và hơi tiết mỡ bớt là được). Chắt/gạn bỏ bớt mỡ rán, giữ lại tóp ba chỉ.', 10);
INSERT INTO public.recipe_steps VALUES (2743, '2025-11-20 17:10:58.424266', '2025-11-20 17:10:58.424266', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 456, 4, 'Cho 2 thìa canh mỡ lợn (đã rán ở trên) vào, phi thơm hành tím.', 10);
INSERT INTO public.recipe_steps VALUES (2744, '2025-11-20 17:10:58.425312', '2025-11-20 17:10:58.425312', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 456, 5, 'Cho tôm khô vào xào săn. Tiếp đến, cho tóp ba chỉ vào. Nêm gia vị: 8 muỗng canh nước mắm ngon, 5 muỗng canh đường, 10 muỗng canh nước và đun liu riu lửa nhỏ. Khi gần cạn, thêm nước cơm/hoặc nước cốt dừa và tiếp tục đun nhỏ lửa cho tới khi nước sánh kẹo lại. Lúc này, thêm ớt, hạt tiêu, hành lá (tùy chọn) vào, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (2745, '2025-11-20 17:10:58.4269', '2025-11-20 17:10:58.4269', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 456, 2, 'Ba chỉ bỏ bì, cắt miếng nhỏ cỡ 1 cm, rửa sạch. Sau đó, chần sơ để loại bỏ tạp chất, rửa sạch lại.', 10);
INSERT INTO public.recipe_steps VALUES (2746, '2025-11-20 17:10:58.428491', '2025-11-20 17:10:58.428491', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 456, 1, 'Ngâm tôm khô 10-15 phút, rửa sạch, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (2747, '2025-11-20 17:10:58.585667', '2025-11-20 17:10:58.585667', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 457, 2, 'Rau các loại:Lá mơ lông tam thể, lá lốt ngâm nước muối loãng, rửa sạch, vẩy ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (2748, '2025-11-20 17:10:58.587767', '2025-11-20 17:10:58.587767', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 457, 5, 'Cách 2: Với những ai thích cá giòn tan, ăn được cả xương thì chiên 2 lần. Lần 1 chiên sơ cho tới khi cá cứng, vớt ra, để nguội. Lọc dầu qua giấy ăn để lấy lại dầu trong. Lần 2 khi nào ăn thì chiên lại: Cho dầu ăn vào chảo, bật bếp. Thử đầu đũa sủi tăm là đạt độ nóng, chia cá theo mẻ, cho vào chiên vàng giòn. Trước khi vớt ra tăng lửa để thoát dầu, vớt ra để lên giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (2749, '2025-11-20 17:10:58.588845', '2025-11-20 17:10:58.588845', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 457, 8, 'Cách 2: Nước mắm tỏi ớt chua ngọt: Cho vào bát 1 muỗng canh đường, 1,5-2 muỗng canh nước cốt chanh, 4-5 muỗng canh nước mắm loại 30 độ đạm. Khuấy cho tan hết đường, thêm tỏi ớt băm nhuyễn, hạt tiêu vào.', 10);
INSERT INTO public.recipe_steps VALUES (2750, '2025-11-20 17:10:58.590427', '2025-11-20 17:10:58.590427', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 457, 3, 'Lần lượt nhúng cá qua bột chiên giòn (hoặc cho cá vào hộp nhựa, thêm bột chiên giòn lắc bám đều các mặt).', 10);
INSERT INTO public.recipe_steps VALUES (2751, '2025-11-20 17:10:58.591987', '2025-11-20 17:10:58.591987', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 457, 4, 'Chiên cá: Với những ai thích cá vừa giòn lại có chút dai thì chỉ cần chiên 1 lần.  Cho dầu vào chảo (đủ ngập cá), bật bếp đun nóng. Thử đầu đũa thấy sủi tăm là đạt độ nóng, chia cá thành các mẻ, lần lượt cho cá vào chiên trên lửa vừa cho tới khi chín vàng, giòn, vớt ra đặt lên giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (2752, '2025-11-20 17:10:58.593047', '2025-11-20 17:10:58.593047', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 457, 6, 'Pha nước chấm:Tùy theo khẩu vị ở mỗi vùng miền, có cách pha nước chấm khác nhau.', 10);
INSERT INTO public.recipe_steps VALUES (2753, '2025-11-20 17:10:58.594638', '2025-11-20 17:10:58.594638', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 457, 1, 'Dùng dao nhỏ, sắc, đánh sơ vảy, cắt xéo đầu và lẹm chút phần bụng, cấu/hoặc bóp cho ra hết ruột. Cho muối hạt và chanh vào, rửa sạch, để ráo nước. Ướp cá với chút muối, hạt nêm, hành khô tối thiểu 15 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2754, '2025-11-20 17:10:58.596223', '2025-11-20 17:10:58.596223', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 457, 7, 'Cách 1: Đơn giản nhất chỉ cần nước mắm nguyên chất, thêm tỏi, ớt tươi.', 10);
INSERT INTO public.recipe_steps VALUES (2755, '2025-11-20 17:10:58.597875', '2025-11-20 17:10:58.597875', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 457, 9, 'Cách 3: Nước sốt me chua ngọt kiểu miền Nam: Phi thơm tỏi, sả, ớt, cho nước, nước me, đường, nước mắm (điều chỉnh theo khẩu vị) vào đun với lửa vừa cho tới khi sánh lại. Nếu muốn sánh đặc hơn, có thể cho thêm một ít bột sắn dây pha nước vào quấy trên lửa vừa.', 10);
INSERT INTO public.recipe_steps VALUES (2756, '2025-11-20 17:10:59.061253', '2025-11-20 17:10:59.061253', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 458, 1, 'Gà làm sạch, xát với muối hạt và chanh để khử mùi, rửa lại bằng nước sạch, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (2757, '2025-11-20 17:10:59.062861', '2025-11-20 17:10:59.062861', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 458, 2, 'Có 2 cách xử lý gà: Để nguyên con hoặc chặt miếng vừa ăn. Tuy nhiên, để nguyên con hấp lá sen sẽ giữ nước nên thịt ngọt mềm tự nhiên, đậm vị hơn.', 10);
INSERT INTO public.recipe_steps VALUES (2758, '2025-11-20 17:10:59.064455', '2025-11-20 17:10:59.064455', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 458, 6, 'Hấp gà:Cho gà đã bọc lá sen vào nồi hấp cách thủy từ 50-55 phút tùy theo kích thước gà lớn hay nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2759, '2025-11-20 17:10:59.065517', '2025-11-20 17:10:59.065517', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 458, 3, 'Các loại rau (rau mùi tàu, rau mùi ta, hành lá, húng quế...) rửa sạch, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (2760, '2025-11-20 17:10:59.067074', '2025-11-20 17:10:59.067074', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 458, 5, 'Đặt lạt tre ở dưới bát tô lớn hoặc rổ nhỏ để tạo độ lõm, rồi trải rộng lá sen ra (có thể chần sơ lá sen mềm chút cho dễ gói), đặt gà vào, gói kín, buộc lại. Để ướp gà tối thiểu 30 phút cho thấm gia vị. Nếu muốn hương sen đậm hơn, bạn cho thêm hoa sen (cánh sen, nhụy, đài sen) vào khi ướp gà.', 10);
INSERT INTO public.recipe_steps VALUES (2761, '2025-11-20 17:10:59.068687', '2025-11-20 17:10:59.068687', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 458, 4, 'Trong một bát nhỏ, trộn đều phần hành tím băm, sả băm, dầu hào, muối, hạt tiêu, hạt nêm, chút bột nghệ. Đeo găng tay thoa đều hỗn hợp gia vị ướp này khắp mình gà, cả bên trong bụng gà. Nhồi phần hạt sen tươi, nấm hương cùng sả đập dập, hành củ, gừng và các loại rau thơm (rau mùi tàu, rau mùi ta, hành lá, húng quế...) vào bụng gà.', 10);
INSERT INTO public.recipe_steps VALUES (2762, '2025-11-20 17:10:59.181036', '2025-11-20 17:10:59.181036', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 459, 1, 'Khoai tây gọt vỏ, bỏ mắt, rửa sạch. Dùng dao lượn sóng cắt thành các thanh dài vừa ăn, ngâm vào nước muối pha loãng để không bị thâm trong 10-15 phút, rửa sạch, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (2763, '2025-11-20 17:10:59.182623', '2025-11-20 17:10:59.182623', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 459, 2, 'Chiên sơ lần 1:Cho dầu ăn vào chảo (đủ ngập khoai), bật bếp, thử đầu đũa thấy sủi bọt là đạt độ nóng. Lần lượt chia thành các mẻ, cho khoai tây vào chiên sơ, thỉnh thoảng đảo đều. Sau 4 – 5 phút thì vớt ra, để ráo và nguội.', 10);
INSERT INTO public.recipe_steps VALUES (2764, '2025-11-20 17:10:59.183744', '2025-11-20 17:10:59.183744', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 459, 3, 'Chiên giòn lần 2:Đun nóng dầu trở lại, thử đầu đũa sủi tăm là đạt. Chia từng mẻ, cho khoai tây vào chiên 8-9 phút khoai vàng giòn thì vớt ra, đặt lên giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (2765, '2025-11-20 17:10:59.43257', '2025-11-20 17:10:59.43257', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 460, 11, 'Xếp trứng vào hộp, đổ phần nước sốt vào ngâm khoảng 6 giờ là ăn được hoặc cất ngăn mát tủ lạnh qua đêm hôm sau mang ra ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2766, '2025-11-20 17:10:59.435097', '2025-11-20 17:10:59.435097', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 460, 8, 'Trộn phần sốt ngâm trứng: cho xì dầu, nước trắng, rượu, siro ngô hoặc mật ong đun sôi, nêm nếm cho vừa miệng và để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (2767, '2025-11-20 17:10:59.436625', '2025-11-20 17:10:59.436625', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 460, 9, 'Trộn hành lá hoặc hẹ thái nhỏ, hành tây, hành củ tím, ớt, dầu mè, vừng rang vào phần nước sốt.', 10);
INSERT INTO public.recipe_steps VALUES (2768, '2025-11-20 17:10:59.439224', '2025-11-20 17:10:59.439224', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 460, 4, 'Ngâm trứng đến khi nguội hẳn rồi vớt ra.', 10);
INSERT INTO public.recipe_steps VALUES (2769, '2025-11-20 17:10:59.441335', '2025-11-20 17:10:59.441335', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 460, 1, 'Trứng rửa sạch nhẹ nhàng từng quả một, nếu để trứng trong tủ lạnh thì phải để trứng trở về nhiệt độ phòng mới đem luộc.', 10);
INSERT INTO public.recipe_steps VALUES (2770, '2025-11-20 17:10:59.442331', '2025-11-20 17:10:59.442331', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 460, 6, 'Hành tây, hành củ tím thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2771, '2025-11-20 17:10:59.444958', '2025-11-20 17:10:59.444958', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 460, 7, 'Ớt thái lát.', 10);
INSERT INTO public.recipe_steps VALUES (2772, '2025-11-20 17:10:59.446543', '2025-11-20 17:10:59.446543', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 460, 5, 'Hành lá hoặc hẹ rửa sạch thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2773, '2025-11-20 17:10:59.448697', '2025-11-20 17:10:59.448697', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 460, 10, 'Trứng bóc vỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2774, '2025-11-20 17:10:59.450283', '2025-11-20 17:10:59.450283', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 460, 2, 'Đun sôi nước, cho vào 2 thìa canh giấm và 1 thìa cà phê muối, nước sôi đặt từng quả trứng vào thìa to và nhẹ nhàng thả xuống nồi.', 10);
INSERT INTO public.recipe_steps VALUES (2775, '2025-11-20 17:10:59.451873', '2025-11-20 17:10:59.451873', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 460, 3, 'Căn từ lúc thả trứng vào tính thời gian luộc, được 7-8 phút (trứng sẽ hơi lòng đào) thì vớt ra bát nước đá thật lạnh để trứng ko tiếp tục chín, sau trứng dóc vỏ dễ bóc hơn.', 10);
INSERT INTO public.recipe_steps VALUES (2776, '2025-11-20 17:10:59.985478', '2025-11-20 17:10:59.985478', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 461, 6, 'Chiên gà:Cho dầu (đủ ngập gà) vào chảo, đun nóng, thử đầu đũa thấy sủi bọt là đạt độ nóng.', 10);
INSERT INTO public.recipe_steps VALUES (2777, '2025-11-20 17:10:59.987593', '2025-11-20 17:10:59.987593', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 461, 5, 'Làm bột khô:Trộn tất cả nguyên liệu bột khô trong một tô trộn lớn khác.', 10);
INSERT INTO public.recipe_steps VALUES (2778, '2025-11-20 17:10:59.989193', '2025-11-20 17:10:59.989193', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 461, 8, 'Gà chiên trên lửa vừa từ 12- 15 phút (trở đều hai mặt) sẽ chín, vớt ra, để ráo dầu. Làm lần lượt cho tới khi hết.', 10);
INSERT INTO public.recipe_steps VALUES (2779, '2025-11-20 17:10:59.990265', '2025-11-20 17:10:59.990265', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 461, 2, 'Ngâm gà vào hỗn hợp nước muối loãng, thả đá viên cùng vài củ hành tím đập dập ngâm tối thiểu một giờ để khử mùi và giúp thịt chắc, đậm đà vị hơn. Sau đó, vớt ra, rửa sạch, thấm khô.', 10);
INSERT INTO public.recipe_steps VALUES (2780, '2025-11-20 17:10:59.991326', '2025-11-20 17:10:59.991326', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 461, 1, 'Gà làm sạch, khứa nhẹ vài lát để dễ ngấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (2781, '2025-11-20 17:10:59.994052', '2025-11-20 17:10:59.994052', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 461, 4, 'Làm bột ướt:Trong một tô trộn lớn, cho tất cả nguyên liệu làm bột ướt vào trộn đều. Chú ý nên cho từ từ nước vào để khuấy bột tránh bị vón cục.', 10);
INSERT INTO public.recipe_steps VALUES (2782, '2025-11-20 17:10:59.996259', '2025-11-20 17:10:59.996259', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 461, 7, 'Lần lượt lấy từng miếng gà nhúng qua hỗn hợp bột ướt rồi ấn phủ bột khô, lắc bỏ bột thừa, cho vào chiên theo từng mẻ 3-4 cái.', 10);
INSERT INTO public.recipe_steps VALUES (2783, '2025-11-20 17:10:59.998373', '2025-11-20 17:10:59.998373', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 461, 3, 'Tiếp tục ngâm gà với hỗn hợp buttermilk (gồm sữa tươi không đường + chanh) tối thiểu trong 1 giờ để tạo độ mềm cho thịt. Lấy gà ra, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (2784, '2025-11-20 17:11:00.317825', '2025-11-20 17:11:00.317825', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 462, 8, 'Tiếp tục cho cà chua vào xào chín, thêm nước sôi với lượng vừa đủ, thêm khế, đun sôi, hớt bỏ bọt. Cho cá vào, nêm nước mắm, muối và đường (nếu là người miền Nam) theo khẩu vị.', 10);
INSERT INTO public.recipe_steps VALUES (2785, '2025-11-20 17:11:00.318915', '2025-11-20 17:11:00.318915', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 462, 1, 'Cá tràu (cá quả) làm sạch, chà xát với muối hạt và chanh rửa sạch, tiếp tục ngâm vào nước vo gạo và chút muối hạt, rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (2786, '2025-11-20 17:11:00.320539', '2025-11-20 17:11:00.320539', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 462, 3, 'Ướp cá với 1 muỗng canh nước mắm, 1 muỗng canh hành tím băm, 1/2 muỗng cà phê bột nghệ, 1/2 muỗng cà phê hạt tiêu, 1/2 muỗng cà phê hạt nêm trong 10 -15 phút cho thấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (2787, '2025-11-20 17:11:00.322798', '2025-11-20 17:11:00.322798', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 462, 5, 'Các loại rau ăn kèm rửa sạch, vẩy ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (2788, '2025-11-20 17:11:00.32446', '2025-11-20 17:11:00.32446', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 462, 9, 'Khi cá chín và dậy mùi thơm, cho hành lá, rau mùi tàu cùng chút hạt nêm từ rau củ vào và tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (2789, '2025-11-20 17:11:00.325587', '2025-11-20 17:11:00.325587', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 462, 6, 'Hành lá, mùi tàu rửa sạch, cắt nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2790, '2025-11-20 17:11:00.327189', '2025-11-20 17:11:00.327189', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 462, 7, 'Phi thơm hành tím, cho cá vào rán sơ để săn lại và dậy mùi thơm, gắp cá ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (2791, '2025-11-20 17:11:00.328816', '2025-11-20 17:11:00.328816', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 462, 2, 'Cắt cá thành từng khúc vừa ăn, hoặc để nguyên con (tùy chọn).', 10);
INSERT INTO public.recipe_steps VALUES (2792, '2025-11-20 17:11:00.330544', '2025-11-20 17:11:00.330544', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 462, 4, 'Cà chua rửa sạch, thái múi cau.', 10);
INSERT INTO public.recipe_steps VALUES (2793, '2025-11-20 17:11:00.960401', '2025-11-20 17:11:00.960401', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 463, 5, 'Lần 1: Thêm nước chè xanh và nước sôi vào xăm xắp mặt thịt và đun trên lửa nhỏ vừa trong 40-50 phút (tùy vào ngan già thì đun lâu hơn) cho thịt vừa chín mềm là đạt. Trong quá trình nấu, nếu nước cạn thì thêm nước chè xanh om hoặc nước sôi. Nêm nếm lại gia vị cho phù hợp với gia đình bạn, thêm ớt nếu thích cay.', 10);
INSERT INTO public.recipe_steps VALUES (2794, '2025-11-20 17:11:00.962652', '2025-11-20 17:11:00.962652', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 463, 1, 'Ngan làm sạch, thui vàng lớp da bên ngoài để thơm hơn. Thui bằng rơm rạ là ngon nhất, nếu không có, dùng đèn khò bằng ga rồi rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (2826, '2025-11-20 17:11:02.009395', '2025-11-20 17:11:02.009395', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 466, 1, 'Lòng bóp với muối hạt, chanh (hoặc giấm) rửa sạch. Phần dạ dày lộn trong ra ngoài cũng bóp muối, chanh rửa sạch. Tiếp tục bóp với cà chua chín lần nữa, rửa sạch lòng khử mùi.', 10);
INSERT INTO public.recipe_steps VALUES (2795, '2025-11-20 17:11:00.964777', '2025-11-20 17:11:00.964777', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 463, 3, 'Ướp thịt ngan với riềng, sả, mắm tôm, nước mắm, muối, lá tắt, hành tăm, mật mía, hạt tiêu, nước hàng, dầu điều, hạt nêm tối thiểu trong 1 giờ cho ngấm gia vị. Nếu có thời gian, cho thịt vào hộp đậy kín để tủ lạnh, ướp lâu sẽ ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (2796, '2025-11-20 17:11:00.966922', '2025-11-20 17:11:00.966922', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 463, 2, 'Chặt ngan thành từng miếng vuông quân cờ vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2797, '2025-11-20 17:11:00.968539', '2025-11-20 17:11:00.968539', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 463, 6, 'Lần 2: Nếu có thời gian thì sau khi nấu lần một để nguội. Trước khi ăn thì nấu lại lần 2 trong vài phút thì thịt sẽ ngon đậm đà, dậy mùi hơn.', 10);
INSERT INTO public.recipe_steps VALUES (2798, '2025-11-20 17:11:00.970949', '2025-11-20 17:11:00.970949', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 463, 4, 'Sau khi ướp, lấy ngan ra xào săn trên lửa lớn để ngấm gia vị vào thịt đậm đà hơn. Nếu muốn ngon hơn thì nấu 2 lần lửa.', 10);
INSERT INTO public.recipe_steps VALUES (2799, '2025-11-20 17:11:01.322776', '2025-11-20 17:11:01.322776', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 464, 3, 'Dứa gọt vỏ, bỏ mắt, cắt từng miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2800, '2025-11-20 17:11:01.324389', '2025-11-20 17:11:01.324389', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 464, 7, 'Làm nước sốt xào:', 10);
INSERT INTO public.recipe_steps VALUES (2801, '2025-11-20 17:11:01.326586', '2025-11-20 17:11:01.326586', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 464, 8, 'Trong một cái bát, trộn các phần nước sốt (nước mắm, dầu hào, đường, hạt nêm) lại với nhau, khuấy tan đường.', 10);
INSERT INTO public.recipe_steps VALUES (2802, '2025-11-20 17:11:01.328702', '2025-11-20 17:11:01.328702', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 464, 9, 'Pha bột bắp với chút nước, khuấy tan.', 10);
INSERT INTO public.recipe_steps VALUES (2803, '2025-11-20 17:11:01.330306', '2025-11-20 17:11:01.330306', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 464, 4, 'Hành tây bóc vỏ, rửa sạch, cắt miếng vuông.', 10);
INSERT INTO public.recipe_steps VALUES (2804, '2025-11-20 17:11:01.331368', '2025-11-20 17:11:01.331368', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 464, 10, 'Phi thơm 1/2 số tỏi, cho mực vào xào trên lửa lớn, thêm 1/2 phần nước sốt, đảo đều trong 2 phút là mực chín, múc ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (2805, '2025-11-20 17:11:01.333952', '2025-11-20 17:11:01.333952', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 464, 1, 'Mực làm sạch, bóp với chanh và muối hạt, rửa sạch, cắt khoanh hoặc khứa chéo tùy chọn.', 10);
INSERT INTO public.recipe_steps VALUES (2806, '2025-11-20 17:11:01.334962', '2025-11-20 17:11:01.334962', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 464, 5, 'Cà chua rửa sạch, thái múi cau.', 10);
INSERT INTO public.recipe_steps VALUES (2807, '2025-11-20 17:11:01.336994', '2025-11-20 17:11:01.336994', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 464, 12, 'Sau đó cho mực vào, đảo đều. Lúc này mới thêm tỏi tây, cần tây, hành lá cắt khúc vào đảo sơ cho chín tái. Nếu muốn nước sốt sánh lại thì lúc này bạn thêm phần nước bột bắp khuấy tan vào đảo nhanh, sánh lại, nêm nếm lại gia vị phù hợp, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (2808, '2025-11-20 17:11:01.338567', '2025-11-20 17:11:01.338567', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 464, 2, 'Đun sôi một nồi nước cùng chút gừng đập dập, muối hạt và cho mực vào trụng sơ, vớt ra luôn, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (2809, '2025-11-20 17:11:01.340192', '2025-11-20 17:11:01.340192', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 464, 6, 'Rau cần, tỏi tây, hành lá rửa sạch, thái khúc.', 10);
INSERT INTO public.recipe_steps VALUES (2810, '2025-11-20 17:11:01.341949', '2025-11-20 17:11:01.341949', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 464, 11, 'Tiếp tục phi thơm tỏi, cho lần lượt theo mức độ chín lâu tới nhanh: dứa vào xào trước, rồi tới dưa leo, cà chua, hành tây. Cho phần nước sốt còn lại vào đảo đều trong vài phút.', 10);
INSERT INTO public.recipe_steps VALUES (2811, '2025-11-20 17:11:01.738301', '2025-11-20 17:11:01.738301', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 465, 8, 'Sau đó, thêm hành tây vào, nấu chín. Nêm nếm gia vị phù hợp gia đình.', 10);
INSERT INTO public.recipe_steps VALUES (2812, '2025-11-20 17:11:01.739891', '2025-11-20 17:11:01.739891', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 465, 4, 'Thử đầu đũa thấy sủi bọt là đạt độ nóng, lần lượt lấy các phần cua, đặt phần thịt cua nhúng qua bột chiên giòn (không cần phủ toàn bộ), cho vào chiên 4-5 phút là cua chín vừa tới. Phần mai cua, rắc chút bột vào phần gạch và chiên 3 phút. Trước khi vớt ra, tăng lửa để thoát dầu, vớt cua ra.', 10);
INSERT INTO public.recipe_steps VALUES (2813, '2025-11-20 17:11:01.742011', '2025-11-20 17:11:01.742011', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 465, 2, 'Ướp cua với: 1/2 thìa cà phê hạt tiêu, 1 thìa cà phê bột gừng (hoặc gừng băm nhỏ), 1 thìa cà phê bột tỏi (hoặc tỏi băm nhỏ), 1/2 thìa cà phê muối. Đảo đều, ướp trong 15 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2814, '2025-11-20 17:11:01.743596', '2025-11-20 17:11:01.743596', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 465, 1, 'Rửa sạch cua, dùng kéo tách mai cua ra sau đó làm sạch phần thịt, bỏ yếm, cắt/hoặc chặt thành các phần nhỏ vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2815, '2025-11-20 17:11:01.745214', '2025-11-20 17:11:01.745214', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 465, 11, 'Múc các phần thịt cua ra đĩa, cho mai cua lên trên. Sau đó, rưới nước sốt me, thêm đậu phộng rang, rau răm (tùy chọn) và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (2816, '2025-11-20 17:11:01.7468', '2025-11-20 17:11:01.7468', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 465, 9, 'Thêm hỗn hợp nước + bột năng vào, khuấy đều cho tới khi sánh lại.', 10);
INSERT INTO public.recipe_steps VALUES (2817, '2025-11-20 17:11:01.748953', '2025-11-20 17:11:01.748953', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 465, 10, 'Cho cua vào hỗn hợp sốt me, đảo đều, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (2818, '2025-11-20 17:11:01.750556', '2025-11-20 17:11:01.750556', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 465, 5, 'Trong một cái bát, cho hỗn hợp sốt me gồm nước sốt me, đường, nước mắm, tương ớt, dầu hào, dầu màu điều và nước vào, khuấy đều cho tan hẳn.', 10);
INSERT INTO public.recipe_steps VALUES (2819, '2025-11-20 17:11:01.752174', '2025-11-20 17:11:01.752174', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 465, 7, 'Cho hỗn hợp nước sốt me gồm vào, đảo đều.', 10);
INSERT INTO public.recipe_steps VALUES (2820, '2025-11-20 17:11:01.753901', '2025-11-20 17:11:01.753901', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 465, 3, 'Cho dầu ăn vào chảo (đủ ngập cua).', 10);
INSERT INTO public.recipe_steps VALUES (2821, '2025-11-20 17:11:01.755482', '2025-11-20 17:11:01.755482', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 465, 6, 'Phi thơm hành tím, tỏi, sả, gừng, ớt sừng.', 10);
INSERT INTO public.recipe_steps VALUES (2822, '2025-11-20 17:11:02.001904', '2025-11-20 17:11:02.001904', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 466, 5, 'Thêm nước dừa tươi vào, đun trên lửa vừa cho tới khi nước sốt sánh lại. Múc ra một ít nước để làm nước sốt chấm.', 10);
INSERT INTO public.recipe_steps VALUES (2823, '2025-11-20 17:11:02.004082', '2025-11-20 17:11:02.004082', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 466, 2, 'Cho vào nồi 1 thìa canh muối hạt, 2 thìa canh rượu trắng, vài lát gừng, ¼ củ hành tây cắt lát, đun sôi. Cho lòng vào chần sơ. Vớt ra, rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (2824, '2025-11-20 17:11:02.005679', '2025-11-20 17:11:02.005679', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 466, 7, 'Nêm nếm lại theo khẩu vị gia đình. Nếu muốn phần lòng đậm màu hơn thì thêm chút nước tương. Khi nước sốt sệt lại, bám vào lòng là đạt, tắt bếp, lấy lòng ra.', 10);
INSERT INTO public.recipe_steps VALUES (2825, '2025-11-20 17:11:02.007806', '2025-11-20 17:11:02.007806', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 466, 4, 'Cho dầu ăn vào chảo, phi thơm tỏi, cho lòng và toàn bộ nước sốt vào xào săn lại.', 10);
INSERT INTO public.recipe_steps VALUES (2827, '2025-11-20 17:11:02.01104', '2025-11-20 17:11:02.01104', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 466, 3, 'Ướp lòng với: 1 thìa canh tỏi băm, 3 - 4 thìa canh nước mắm ngon, 4 thìa canh đường, 1 thìa cà phê muối, 1 thìa cà phê hạt nêm, 1 thìa canh dầu hạt điều, 1/2 thìa cà phê ngũ vị hương tối thiểu 30 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2828, '2025-11-20 17:11:02.013199', '2025-11-20 17:11:02.013199', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 466, 6, 'Tiếp tục khìa lòng, thỉnh thoảng chà phần lòng trên chảo để thấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (2829, '2025-11-20 17:11:02.156592', '2025-11-20 17:11:02.156592', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 467, 5, 'Mướp gọt vỏ, bổ đôi, thái vát thành miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2830, '2025-11-20 17:11:02.158202', '2025-11-20 17:11:02.158202', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 467, 6, 'Đặt phần nước lọc cua lên, bật bếp, dùng đũa khuấy nhẹ theo 1 chiều vòng tròn giúp riêu cua nổi lên, không bén đóng dưới đáy nồi.', 10);
INSERT INTO public.recipe_steps VALUES (2831, '2025-11-20 17:11:02.159793', '2025-11-20 17:11:02.159793', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 467, 1, 'Cua đồng xóc và rửa sạch nhiều lần bằng nước để loại bỏ chất bẩn. Sau đó, bóc yếm, tách phần mai để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (2832, '2025-11-20 17:11:02.161385', '2025-11-20 17:11:02.161385', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 467, 2, 'Phần thân rửa sạch lại, cho vào cối cùng chút muối hạt, dùng chày giã nhuyễn. Nên cho từng lượng nước nhỏ để lọc, rồi lại giã và lọc nhiều lần nhằm lấy hết phần thịt cua, khi nấu phần riêu sẽ nổi lên dầy thành tảng.', 10);
INSERT INTO public.recipe_steps VALUES (2833, '2025-11-20 17:11:02.162466', '2025-11-20 17:11:02.162466', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 467, 4, 'Rau mồng tơi nhặt và rửa sạch, để nguyên lá hoặc thái nhỏ tùy theo sở thích.', 10);
INSERT INTO public.recipe_steps VALUES (2834, '2025-11-20 17:11:02.164075', '2025-11-20 17:11:02.164075', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 467, 3, 'Phần mai thì dùng đầu thìa nhỏ khều lấy gạch để riêng. Nếu kỹ hơn thì tráng qua nước lạnh mấy lần, chắt lọc giữ gạch lại để giảm bớt mùi tanh và đen từ gạch (nếu có).', 10);
INSERT INTO public.recipe_steps VALUES (2835, '2025-11-20 17:11:02.165194', '2025-11-20 17:11:02.165194', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 467, 8, 'Khi nước sôi thì dừng khuấy, nhẹ nhàng múc phần tảng thịt cua ra bát để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (2836, '2025-11-20 17:11:02.166775', '2025-11-20 17:11:02.166775', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 467, 10, 'Phần gạch chế biến tùy theo khẩu vị vùng miền và mỗi gia đình. Có 2 cách nấu:', 10);
INSERT INTO public.recipe_steps VALUES (2837, '2025-11-20 17:11:02.167845', '2025-11-20 17:11:02.167845', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 467, 7, 'Khi nước bắt đầu nóng dần lên, hạ nhỏ lửa, gạt nhẹ phần thịt cua sang một bên.', 10);
INSERT INTO public.recipe_steps VALUES (2838, '2025-11-20 17:11:02.169516', '2025-11-20 17:11:02.169516', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 467, 11, 'Cách 1: Chưng gạch khử tanh: Phi thơm hành, cho gạch vào chưng, nêm nếm chút gia vị. Sau đó mới cho phần gạch vào nồi canh.', 10);
INSERT INTO public.recipe_steps VALUES (2839, '2025-11-20 17:11:02.170578', '2025-11-20 17:11:02.170578', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 467, 12, 'Cách 2: Không chưng gạch: khi nồi riêu cua sôi thì cho gạch vào, sau đó mới cho rau xanh vào nấu chín.', 10);
INSERT INTO public.recipe_steps VALUES (2840, '2025-11-20 17:11:02.172175', '2025-11-20 17:11:02.172175', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 467, 9, 'Cho rau mồng tơi, mướp vào nấu chín. Nêm nếm khẩu vị theo gia đình.', 10);
INSERT INTO public.recipe_steps VALUES (2841, '2025-11-20 17:11:02.534468', '2025-11-20 17:11:02.534468', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 468, 9, 'Để lọ cà ở nơi thoáng mát nửa ngày cho ngấm gia vị sau đó cho vào ngăn mát tủ lạnh, cà sẽ giòn, đậm đà vị rất ngon và dùng được lâu.', 10);
INSERT INTO public.recipe_steps VALUES (2842, '2025-11-20 17:11:02.536051', '2025-11-20 17:11:02.536051', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 468, 8, 'Cho cà vào lọ thủy tinh (đã rửa sạch, để khô), đổ hỗn hợp nước mắm chua ngọt vào ngập. Đặt vỉ nén lên trên để nén cà xuống, đậy nắp.', 10);
INSERT INTO public.recipe_steps VALUES (2843, '2025-11-20 17:11:02.537105', '2025-11-20 17:11:02.537105', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 468, 4, 'Gừng, riềng rửa sạch, ngâm qua chút nước dấm để không bị thâm, xay hoặc giã nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (2844, '2025-11-20 17:11:02.538777', '2025-11-20 17:11:02.538777', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 468, 3, 'Lần lượt bổ đôi từng quả cà pháo và cho ngay vào thau nước muối ngâm trong ít nhất một giờ (tốt nhất là 3-4 giờ) tránh cho cà không bị thâm đen và bớt mùi hăng.', 10);
INSERT INTO public.recipe_steps VALUES (2845, '2025-11-20 17:11:02.540091', '2025-11-20 17:11:02.540091', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 468, 2, 'Hòa tan nước vo gạo (hoặc nước) với muối hạt để ngâm cà.', 10);
INSERT INTO public.recipe_steps VALUES (2846, '2025-11-20 17:11:02.54164', '2025-11-20 17:11:02.54164', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 468, 6, 'Cho nước mắm, đường, dấm tỷ lệ 1:1:1 (hoặc gia giảm theo khẩu vị gia đình) vào nồi, bắc lên bếp, thêm 1/2 thìa canh muối hạt khuấy đều, đun sôi, tắt bếp, để nguội hoàn toàn.', 10);
INSERT INTO public.recipe_steps VALUES (2847, '2025-11-20 17:11:02.543671', '2025-11-20 17:11:02.543671', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 468, 7, 'Cà vớt ra khỏi nước ngâm, rửa sạch mấy lần với nước, rồi tráng qua chút giấm giúp cà để được lâu.', 10);
INSERT INTO public.recipe_steps VALUES (2848, '2025-11-20 17:11:02.544671', '2025-11-20 17:11:02.544671', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 468, 5, 'Ớt bỏ hạt, băm hoặc giã nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (2849, '2025-11-20 17:11:02.54669', '2025-11-20 17:11:02.54669', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 468, 1, 'Cà pháo phơi héo sơ một nắng, cắt cuống, rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (2850, '2025-11-20 17:11:02.828069', '2025-11-20 17:11:02.828069', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 469, 3, 'Dọc mùng tước vỏ, ngâm nước muối, rửa sạch, cắt khúc vừa ăn (Nếu kỹ hơn thì bóp dọc mùng với muối hạt, rửa sạch vì nếu không biết chọn dọc mùng có thể bị ngứa).', 10);
INSERT INTO public.recipe_steps VALUES (2851, '2025-11-20 17:11:02.829677', '2025-11-20 17:11:02.829677', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 469, 1, 'Gà làm sạch, dùng dao chặt miếng vừa ăn. Để riêng phần cổ và sống lưng làm mọc gà.', 10);
INSERT INTO public.recipe_steps VALUES (2852, '2025-11-20 17:11:02.83199', '2025-11-20 17:11:02.83199', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 469, 8, 'Cho mọc gà viên vào, hạ lửa vừa và dùng đũa đảo nhẹ nhàng cho mọc chín đều, không bị vỡ. Đậy vung đun 4-5 phút cho mọc chín, vớt mọc ra.', 10);
INSERT INTO public.recipe_steps VALUES (2853, '2025-11-20 17:11:02.833594', '2025-11-20 17:11:02.833594', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 469, 9, 'Tiếp đến, cho dọc mùng vào, khuấy nhẹ. Nêm nếm lại gia vị theo khẩu vị.', 10);
INSERT INTO public.recipe_steps VALUES (2854, '2025-11-20 17:11:02.835743', '2025-11-20 17:11:02.835743', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 469, 6, 'Gà sau khi ướp, cho lên bếp đun nhỏ lửa tầm 5 phút, đảo đều cho săn lại, gia vị rút vào thịt.', 10);
INSERT INTO public.recipe_steps VALUES (2855, '2025-11-20 17:11:02.837334', '2025-11-20 17:11:02.837334', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 469, 4, 'Cách làm mọc xương gà (đặc trưng của gà xáo Thanh Chương):Dùng sống lưng dao dần phần cổ và xương lưng cho mềm, rồi băm nhỏ, thêm chút hành tăm, muối hạt, hạt tiêu, hạt nêm và nghệ băm cùng. Khi nhuyễn thì thoa chút mỡ vào găng tay và viên thành các viên tròn nhỏ vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2856, '2025-11-20 17:11:02.83895', '2025-11-20 17:11:02.83895', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 469, 10, 'Thêm chút lá chanh thái chỉ, rau răm (nếu thích), tắt bếp, múc ra tô.', 10);
INSERT INTO public.recipe_steps VALUES (2857, '2025-11-20 17:11:02.84056', '2025-11-20 17:11:02.84056', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 469, 2, 'Ướp phần thịt gà đã chặt miếng với 1,5 thìa cà phê muối hạt, 1 thìa cà phê hạt nêm, 1 thìa cà phê hạt tiêu, hành tăm, nghệ tươi giã nhỏ và lá chanh xé vào. Nếu thích cay thì thêm chút ớt, còn nhà có trẻ nhỏ không nên cho ớt. Trộn đều cho thấm gia vị, ướp trong khoảng 15 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2858, '2025-11-20 17:11:02.842704', '2025-11-20 17:11:02.842704', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 469, 5, 'Cách nấu xáo gà', 10);
INSERT INTO public.recipe_steps VALUES (2859, '2025-11-20 17:11:02.844881', '2025-11-20 17:11:02.844881', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 469, 7, 'Cho nước lã vào ngập như canh (thường tỷ lệ gà và nước là 1:1 hoặc cho nhiều nước hơn chút), tăng lửa, đậy vung, đun 2 nhịp sôi cho tới khi nước trên bề mặt canh gà vàng mướt cũng là lúc gà chín mềm và ngọt thơm vừa độ.', 10);
INSERT INTO public.recipe_steps VALUES (2860, '2025-11-20 17:11:03.040971', '2025-11-20 17:11:03.040971', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 470, 6, 'Dùng đôi đũa thử thấy sủi tăm ở đầu đũa là dầu đạt độ nóng, lần lượt cho đậu vào, hạ lửa vừa chiên, trở hai mặt cho chín vàng đều.', 10);
INSERT INTO public.recipe_steps VALUES (2861, '2025-11-20 17:11:03.042022', '2025-11-20 17:11:03.042022', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 470, 7, 'Đậu nóng đã chín vàng, lần lượt lấy ra tẩm vào hỗn hợp nước mắm hành luôn, gắp ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (2862, '2025-11-20 17:11:03.044074', '2025-11-20 17:11:03.044074', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 470, 1, 'Trong một cái bát, cho 3 muỗng canh nước mắm ngon, 8-10 muỗng canh nước đun sôi để nguội khuấy đều.', 10);
INSERT INTO public.recipe_steps VALUES (2863, '2025-11-20 17:11:03.045673', '2025-11-20 17:11:03.045673', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 470, 2, 'Hành hoa rửa sạch, lấy phần lá xanh thái nhỏ, cho vào bát, thêm 1/4 thìa canh muối (để hành giữ màu xanh), thêm 2-3 thìa dầu nóng cho vào, đảo đều để hành giảm mùi hăng. Sau đó cho hỗn hợp hành này vào bát nước mắm trên, khuấy đều, để sẵn một bên.', 10);
INSERT INTO public.recipe_steps VALUES (2864, '2025-11-20 17:11:03.046712', '2025-11-20 17:11:03.046712', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 470, 5, 'Cho chảo lên bếp đun nóng, rồi mới cho dầu ăn và chút mỡ lợn hoặc mỡ gà vào.', 10);
INSERT INTO public.recipe_steps VALUES (2865, '2025-11-20 17:11:03.048285', '2025-11-20 17:11:03.048285', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 470, 3, 'Ngâm đậu phụ vào nước muối pha loãng. Sau đó, vớt ra thấm thật khô. Nếu có thời gian thì cho đậu phụ vào ngăn đá tủ lạnh tầm 30 phút để tạo khối vuông vắn.', 10);
INSERT INTO public.recipe_steps VALUES (2866, '2025-11-20 17:11:03.049355', '2025-11-20 17:11:03.049355', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 470, 4, 'Lấy đậu phụ ra, cắt miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2867, '2025-11-20 17:11:03.350282', '2025-11-20 17:11:03.350282', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 471, 17, 'Ninh từ 1-2 giờ thì lọc qua rây, lấy nước dùng trong.', 10);
INSERT INTO public.recipe_steps VALUES (2868, '2025-11-20 17:11:03.352389', '2025-11-20 17:11:03.352389', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 471, 14, 'Cho xương và nồi và đổ lượng nước đủ dùng (chú ý nồi đáy sâu), thêm chút muối hạt, đun sôi, hớt bọt, hạ nhỏ lửa ninh từ 2 - 3 giờ, lọc lấy nước dùng ngọt thanh tự nhiên. Khi ninh, thỉnh thoảng hớt bỏ bọt.', 10);
INSERT INTO public.recipe_steps VALUES (2869, '2025-11-20 17:11:03.355058', '2025-11-20 17:11:03.355058', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 471, 9, 'Phần cá dính chút xương thì băm nhuyễn với chút hành khô, hạt tiêu, ớt (nếu ăn được cay), hạt nêm.', 10);
INSERT INTO public.recipe_steps VALUES (2870, '2025-11-20 17:11:03.357031', '2025-11-20 17:11:03.357031', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 471, 1, 'Cá mua về xóc chút muối hạt để hết nhớt, đánh sạch vảy, chà xát chanh khử mùi tanh, rửa sạch bằng nước vo gạo, rửa sạch lại.', 10);
INSERT INTO public.recipe_steps VALUES (2871, '2025-11-20 17:11:03.358608', '2025-11-20 17:11:03.358608', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 471, 13, 'Nếu có thời gian, bạn nên ngâm xương cùng nước ấm với chút muối hạt để sạch máu, rửa sạch. Sau đó, chần xương 3-4 phút loại bỏ tạp chất, rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (2872, '2025-11-20 17:11:03.360226', '2025-11-20 17:11:03.360226', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 471, 6, 'Nếu có thời gian thì cho phần cá đã ướp đặt nhẹ nhàng lên vỉ, nướng sơ trên than hoa cho thịt se lại, thịt thơm. Nếu không có thời gian bỏ qua bước này.', 10);
INSERT INTO public.recipe_steps VALUES (2873, '2025-11-20 17:11:03.361351', '2025-11-20 17:11:03.361351', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 471, 12, 'Nước dùng từ xương lợn', 10);
INSERT INTO public.recipe_steps VALUES (2874, '2025-11-20 17:11:03.362957', '2025-11-20 17:11:03.362957', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 471, 10, 'Sau đó, trộn cùng chút thịt nạc vai xay và nặn thành các viên nhỏ, đem chiên vàng 2 mặt, vớt ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (2875, '2025-11-20 17:11:03.364515', '2025-11-20 17:11:03.364515', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 471, 2, 'Cho cá vào nồi, thêm lượng nước xâm xấp cùng chút gừng đập dập, muối, đầu hành trắng, bật bếp đun sôi.', 10);
INSERT INTO public.recipe_steps VALUES (2876, '2025-11-20 17:11:03.365586', '2025-11-20 17:11:03.365586', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 471, 11, 'Cách làm nước dùng: Làm song hành thời gian rim cá:', 10);
INSERT INTO public.recipe_steps VALUES (2877, '2025-11-20 17:11:03.367147', '2025-11-20 17:11:03.367147', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 471, 7, 'Cho mỡ lợn vào chảo nóng, phi thơm hành băm và cho cá vào rim cá ở lửa nhỏ tối thiểu trong 30 phút hoặc cho tới khi thịt cá săn lại, gia vị rút vào cá.', 10);
INSERT INTO public.recipe_steps VALUES (2878, '2025-11-20 17:11:03.369288', '2025-11-20 17:11:03.369288', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 471, 18, 'Sau đó, hòa chung nước dùng (đã lọc) từ xương lợn cùng nước dùng xương cá, nêm nếm lại gia vị mắm muối, hạt nêm cho phù hợp khẩu vị gia đình. Ở một số nơi thì xào thêm chút cà chua tạo màu cho vào nồi nước dùng. Tuy nhiên, canh cá Quỳnh Côi gốc thì nước dùng thanh ngọt tự nhiên.', 10);
INSERT INTO public.recipe_steps VALUES (2879, '2025-11-20 17:11:03.369815', '2025-11-20 17:11:03.369815', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 471, 3, 'Khi cá vừa chín tới thì vớt ra cho vào bát nước lạnh hoặc thêm ít đá viên. Nhẹ nhàng gỡ phần thịt ra khỏi xương. Phần xương để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (2880, '2025-11-20 17:11:03.371947', '2025-11-20 17:11:03.371947', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 471, 4, 'Phần thịt cá gỡ ướp với gừng giã, nghệ giã, hành khô băm nhỏ, 3 thìa cà phê nước mắm ngon.', 10);
INSERT INTO public.recipe_steps VALUES (2881, '2025-11-20 17:11:03.373003', '2025-11-20 17:11:03.373003', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 471, 16, 'Xương cá cho vào nồi cùng chút gừng già (rửa sạch, đập dập để tiết ra tinh dầu giúp khử mùi tanh), chút muối hạt, khi ninh không nên khuấy tránh nát cá. Thỉnh thoảng vớt bỏ bọt.', 10);
INSERT INTO public.recipe_steps VALUES (2882, '2025-11-20 17:11:03.374647', '2025-11-20 17:11:03.374647', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 471, 15, 'Nước dùng từ xương cá:', 10);
INSERT INTO public.recipe_steps VALUES (2883, '2025-11-20 17:11:03.37619', '2025-11-20 17:11:03.37619', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 471, 5, 'Rim cá: Có 2 bước:', 10);
INSERT INTO public.recipe_steps VALUES (2884, '2025-11-20 17:11:03.377726', '2025-11-20 17:11:03.377726', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 471, 8, 'Cách làm chả cá (phần topping thêm vào, tùy chọn)', 10);
INSERT INTO public.recipe_steps VALUES (2885, '2025-11-20 17:11:04.059299', '2025-11-20 17:11:04.059299', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 472, 1, 'Nên ngâm xiên tre vào nước trong 30 phút để không bị cháy.', 10);
INSERT INTO public.recipe_steps VALUES (2886, '2025-11-20 17:11:04.060887', '2025-11-20 17:11:04.060887', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 472, 4, 'Bạn có thể nướng bằng lò nướng, bếp nướng, than hoa hoặc chiên/rán đều được. Nếu nướng bằng lò thì cần làm nóng lò trước ở nhiệt ở 200 độ và cho thịt vào nướng, lật trở đều tới khi thịt chín vàng đều các mặt là được.', 10);
INSERT INTO public.recipe_steps VALUES (2887, '2025-11-20 17:11:04.062492', '2025-11-20 17:11:04.062492', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 472, 6, 'Múc sốt bơ đậu phộng ra chén, rắc thêm hành phi, đậu phộng, ớt băm (nếu ăn cay) lên trên.', 10);
INSERT INTO public.recipe_steps VALUES (2888, '2025-11-20 17:11:04.064101', '2025-11-20 17:11:04.064101', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 472, 5, 'Cách làm nước sốt đậu phộng:Phi thơm hành tím, rồi cho nước tương đen, bơ đậu phộng, đường, nước mắm, bột ớt, nước cốt dừa (hoặc nước) vào trộn đều khi sánh lại thì thêm nước cốt chanh, khuấy đều, tắt bếp. Nếu sốt đặc thì bạn thêm nước để tạo độ sánh theo khẩu vị.', 10);
INSERT INTO public.recipe_steps VALUES (2889, '2025-11-20 17:11:04.065744', '2025-11-20 17:11:04.065744', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 472, 2, 'Ướp thịt gà với tất cả phần gia vị ướp ở trên tối thiểu trong 30 phút hoặc nếu có thời gian dùng màng bọc thực phẩm để qua đêm trong ngăn mát tủ lạnh, thịt ngấm gia vị càng ngon.', 10);
INSERT INTO public.recipe_steps VALUES (2890, '2025-11-20 17:11:04.06736', '2025-11-20 17:11:04.06736', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 472, 3, 'Xiên 4-5 miếng thịt gà mỏng vào xiên tre.', 10);
INSERT INTO public.recipe_steps VALUES (2891, '2025-11-20 17:11:04.576388', '2025-11-20 17:11:04.576388', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 473, 4, 'c) Chuẩn bị các nguyên liệu khác:Cà chua rửa sạch, hấp hoặc luộc, bóc vỏ, xay nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (2892, '2025-11-20 17:11:04.578561', '2025-11-20 17:11:04.578561', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 473, 6, 'Hỗn hợp nước sốt kho: Phi thơm số hành tỏi còn lại, cho sốt cà chua xay nhuyễn, 6 muỗng canh nước mắm, 2 muỗng canh ketchup, 2 muỗng canh tương ớt, 1 muỗng canh đường, ớt bột Hàn Quốc (để tạo màu), thêm nước và nước dừa tươi, nêm nếm lại khẩu vị phù hợp gia đình, đun sôi, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (2893, '2025-11-20 17:11:04.580269', '2025-11-20 17:11:04.580269', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 473, 7, 'd) Cách kho cá:Cho cá vào nồi kho (đã lót mía), thêm hỗn hợp nước sốt kho ở trên và cả phần nước ướp vào cùng. Bật bếp đun sôi, khi sôi hớt bỏ bọt, hạ nhỏ lửa, kho cá trong 2 giờ 30 phút hoặc cho tới khi cá chín mềm, rục xương, nước sốt cạn bớt và sánh lại.', 10);
INSERT INTO public.recipe_steps VALUES (2894, '2025-11-20 17:11:04.582444', '2025-11-20 17:11:04.582444', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 473, 2, 'Tiếp tục ngâm cá với chút rượu trắng 5 phút để khử mùi tanh, rửa sạch, thấm khô.', 10);
INSERT INTO public.recipe_steps VALUES (2895, '2025-11-20 17:11:04.584064', '2025-11-20 17:11:04.584064', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 473, 3, 'b) Cách ướp cá:Ướp cá cùng 1 thìa canh dầu tỏi phi, 1 muỗng canh nước mắm, muỗng canh đường, muỗng cà phê muối, 1 muỗng cà phê hạt nêm, 1/2 muỗng cà phê hạt tiêu, 1 muỗng canh hành tím băm, 1 muỗng canh tỏi băm, trộn đều ướp tối thiểu trong 1 giờ. Nếu có thời gian, bọc màng bọc thực phẩm kín, để ngăn mát tủ lạnh ướp càng lâu càng ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (2896, '2025-11-20 17:11:04.585652', '2025-11-20 17:11:04.585652', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 473, 1, 'a) Cách sơ chế khử mùi tanh của cá:Cá cắt bỏ mang, đuôi, ngâm nước vo gạo pha loãng với chút muối hạt vài phút, rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (2897, '2025-11-20 17:11:04.587235', '2025-11-20 17:11:04.587235', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 473, 8, 'Nếu bạn dùng nồi áp suất điện Instant Pot kho cá thì thời gian rút ngắn hơn. Sau khi kho, muốn nước sốt sánh hơn thì bạn pha chút bột bắp với nước, vừa cho vào vừa đảo nhẹ cho tới khi sánh lại theo ý muốn. Thêm hạt nêm, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (2898, '2025-11-20 17:11:04.588833', '2025-11-20 17:11:04.588833', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 473, 5, 'Mía rửa sạch, chẻ mỏng xếp vừa vào nồi kho.', 10);
INSERT INTO public.recipe_steps VALUES (2899, '2025-11-20 17:11:04.83727', '2025-11-20 17:11:04.83727', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 474, 3, 'Chưng thịt:Hạ nhỏ lửa, chưng thịt khoảng 50 phút cho tới khi cạn, thịt săn lại nhưng không bị khô, màu nâu đỏ đẹp mắt là đạt. Để ngon hơn thì tắt bếp để nguội chút, rồi bật bếp chưng lại 8- 10 phút cho thịt rút nước, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (2900, '2025-11-20 17:11:04.839367', '2025-11-20 17:11:04.839367', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 474, 2, 'Xào thịt:Cho 6-7 thìa canh mỡ lợn/hoặc dầu ăn vào chảo, cho sả vào trước, rồi cho hành khô băm nhỏ vào phi thơm, khi hành sả hơi ngả vàng thì cho thịt đã ướp vào đảo và dàn đều, xào săn để rút gia vị vào thịt.', 10);
INSERT INTO public.recipe_steps VALUES (2901, '2025-11-20 17:11:04.841126', '2025-11-20 17:11:04.841126', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 474, 1, 'Ướp thịt:Trong tô trộn lớn, cho thịt và các gia vị ướp như mắm tôm, mắm tép, đường, dầu điều cùng riềng xay vào. Dùng găng tay trộn để gia vị thấm đều, bọc kín để vào tủ lạnh ướp tối thiểu 1 giờ cho thấm gia vị. Nếu ướp lâu càng ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (2902, '2025-11-20 17:11:04.842277', '2025-11-20 17:11:04.842277', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 474, 4, 'Bảo quản:Khi thịt nguội, cho vào hũ thủy tinh sạch (rửa sạch, tráng nước sôi, để ráo nước), đậy nắp, bảo quản trong ngăn mát tủ lạnh được hàng tháng. Khi ăn, bạn lấy ra vừa đủ, quay lại lò vi sóng vài phút. Thịt chưng mắm tép ăn với xôi và cơm trắng đều rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (2903, '2025-11-20 17:11:05.086833', '2025-11-20 17:11:05.086833', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 475, 5, 'Khi thịt gà săn lại, nước nước trong chảo đã cạn sánh, lúc này mới thêm một thìa canh nước mắm, một thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu, ớt (nếu ăn được cay) vào đảo đều cho thấm gia vị, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (2904, '2025-11-20 17:11:05.088952', '2025-11-20 17:11:05.088952', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 475, 3, 'Đun nóng dầu ăn trong chảo, cho 1 thìa canh hành khô cùng 1/2 thìa canh gừng thái sợi vào phi thơm.', 10);
INSERT INTO public.recipe_steps VALUES (2905, '2025-11-20 17:11:05.090566', '2025-11-20 17:11:05.090566', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 475, 4, 'Sau đó, cho thịt gà vào rang ở lửa lớn. Nhớ đảo đều để gà chín đều và không bị bén chảo.', 10);
INSERT INTO public.recipe_steps VALUES (2906, '2025-11-20 17:11:05.092181', '2025-11-20 17:11:05.092181', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 475, 2, 'Ướp gà: Trong một cái tô lớn, cho thịt gà vào ướp cùng với 1 thìa cà phê muối, 1/2 thìa canh nước mắm, 1 thìa canh gừng băm nhuyễn, 1/2 thìa cà phê hạt tiêu, 1/2 thìa cà phê hạt nêm trong 8-10 phút cho ngấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (2907, '2025-11-20 17:11:05.094298', '2025-11-20 17:11:05.094298', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 475, 1, 'Gà làm sạch, chà xát với muối hạt và chanh cho hết mùi hôi, rửa sạch, thấm khô, chặt miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2908, '2025-11-20 17:11:05.275429', '2025-11-20 17:11:05.275429', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 476, 9, 'Tráng lòng đỏ cũng như vậy.', 10);
INSERT INTO public.recipe_steps VALUES (2909, '2025-11-20 17:11:05.276477', '2025-11-20 17:11:05.276477', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 476, 5, 'Trứng tách riêng lòng trắng, lòng đỏ ra mỗi bát.', 10);
INSERT INTO public.recipe_steps VALUES (2910, '2025-11-20 17:11:05.278075', '2025-11-20 17:11:05.278075', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 476, 6, 'Có thể cho vào xíu nước mắm hoặc bột nêm, hoặc bột canh. Dùng đũa đánh tan lòng trắng và lòng đỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2911, '2025-11-20 17:11:05.279162', '2025-11-20 17:11:05.279162', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 476, 8, 'Dầu nóng cho lòng trắng trứng vào chảo, láng thật mỏng, để lửa bé, trứng chín lật mặt trứng thêm vài giây rồi lật ra đĩa hoặc khay rộng.', 10);
INSERT INTO public.recipe_steps VALUES (2912, '2025-11-20 17:11:05.280756', '2025-11-20 17:11:05.280756', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 476, 13, 'Cho giò đã cuộn vào vỉ hấp và hấp chín trong 15-20 phút. Để nguội, gỡ giấy bạc, thái khoanh tròn.', 10);
INSERT INTO public.recipe_steps VALUES (2913, '2025-11-20 17:11:05.282369', '2025-11-20 17:11:05.282369', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 476, 3, 'Hành lá thái nhỏ (càng thái nhỏ, băm nhỏ thì giò càng dễ cuộn và ngon).', 10);
INSERT INTO public.recipe_steps VALUES (2914, '2025-11-20 17:11:05.284599', '2025-11-20 17:11:05.284599', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 476, 2, 'Nấm hương, mộc nhĩ ngâm nở, rửa sạch, bỏ chân, thái sợi, băm nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2915, '2025-11-20 17:11:05.286244', '2025-11-20 17:11:05.286244', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 476, 4, 'Trộn tất cả các nguyên liệu: giò sống, cà rốt, nấm hương, mộc nhĩ, hành lá, 1/2 thìa cà phê bột nêm, 1/2 thìa cà phê hạt tiêu. (Giò sống khi xay họ cho sẵn gia vị nên không được nêm nhiều dễ bị mặn).', 10);
INSERT INTO public.recipe_steps VALUES (2916, '2025-11-20 17:11:05.287291', '2025-11-20 17:11:05.287291', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 476, 12, 'Cuối cùng cuộn tròn lại, dùng giấy bạc bọc kín, xoắn chặt cố định hai đầu.', 10);
INSERT INTO public.recipe_steps VALUES (2917, '2025-11-20 17:11:05.288885', '2025-11-20 17:11:05.288885', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 476, 1, 'Cà rốt bào sợi băm thật nhỏ (nếu không có cà rốt mọi người có thể thay thế bằng một loại củ quả khác tương tự theo sở thích, nhưng vẫn phải bào sợi thái thật nhỏ)', 10);
INSERT INTO public.recipe_steps VALUES (2918, '2025-11-20 17:11:05.290551', '2025-11-20 17:11:05.290551', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 476, 11, 'Sau khi phết xong giò lên mặt lòng đỏ, đặt trồng phần lòng trắng trứng lên trên, tiếp tục phết thêm một lớp giò sống mỏng và đều.', 10);
INSERT INTO public.recipe_steps VALUES (2919, '2025-11-20 17:11:05.292234', '2025-11-20 17:11:05.292234', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 476, 10, 'Trứng nguội, đặt lòng đỏ lên mặt phẳng, phết phần hỗn hợp giò sống đã trộn cùng các nguyên liệu ở trên, dàn đều và thật mỏng. (càng dàn mỏng, đều thì sau đó cuốn sẽ đẹp và dễ).', 10);
INSERT INTO public.recipe_steps VALUES (2920, '2025-11-20 17:11:05.293816', '2025-11-20 17:11:05.293816', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 476, 7, 'Dùng chảo chống dính, đổ ít dầu ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2921, '2025-11-20 17:11:05.847047', '2025-11-20 17:11:05.847047', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 477, 7, 'Đậu bắp, rửa sạch, cắt chéo.', 10);
INSERT INTO public.recipe_steps VALUES (2922, '2025-11-20 17:11:05.849053', '2025-11-20 17:11:05.849053', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 477, 6, 'Dọc mùng (bạc hà) tước vỏ, rửa sạch với nước muỗi loãng, cắt lát xéo.', 10);
INSERT INTO public.recipe_steps VALUES (2923, '2025-11-20 17:11:05.850053', '2025-11-20 17:11:05.850053', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 477, 3, 'b) Chuẩn bị các nguyên liệu khác (trong lúc chờ ướp cá): Me chua ngâm với nước nóng, dằm và lọc lấy nước cốt me.', 10);
INSERT INTO public.recipe_steps VALUES (2924, '2025-11-20 17:11:05.851053', '2025-11-20 17:11:05.851053', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 477, 12, 'Cho 1-1,2 lít nước lọc và nước cốt me vào nồi, bật bếp đun sôi khi nước ấm bắt đầu sủi bọt thì cho cá vào. Nêm vào 2 muỗng canh nước mắm, 1 muỗng canh đường, 1/2 muỗng cà phê muối. Khi sôi, hạ nhỏ lửa, vớt bọt.', 10);
INSERT INTO public.recipe_steps VALUES (2925, '2025-11-20 17:11:05.853092', '2025-11-20 17:11:05.853092', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 477, 13, 'Sau 5 phút khi cá chín, cho cà chua và dứa đã xào, cùng số cà chua còn lại vào nấu tiếp. Lúc này nêm nếm lại gia vị cho phù hợp gia đình.', 10);
INSERT INTO public.recipe_steps VALUES (2926, '2025-11-20 17:11:05.854756', '2025-11-20 17:11:05.854756', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 477, 14, 'Sau vài phút, cho dọc mùng (bạc hà), đậu bắp vào đun 2 phút, rồi thêm giá đỗ, thêm 1/2 muỗng canh nước mắm cho dậy mùi thơm, 1 muỗng cà phê hạt nêm (hoặc mì chính). Thêm rau ngò gai, ngò om, khi nước sôi lại thì tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (2927, '2025-11-20 17:11:05.85643', '2025-11-20 17:11:05.85643', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 477, 11, 'Tiếp tục cho ít dầu ăn, phi thơm hành khô, cho 1/2 số cà chua vào xào trước để tạo màu. Sau đó, cho dứa vào xào cùng, nêm 1/2 muỗng cà phê muối nấu trong 3-5 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2928, '2025-11-20 17:11:05.85748', '2025-11-20 17:11:05.85748', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 477, 1, 'a) Sơ chế cá: Cá làm sạch, cắt khoanh, chà xát với chút muối hạt, chanh (hoặc rượu trắng), rửa sạch cho hết mùi tanh.', 10);
INSERT INTO public.recipe_steps VALUES (2929, '2025-11-20 17:11:05.859061', '2025-11-20 17:11:05.859061', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 477, 9, 'Các loại rau thơm (rau ngò gai, ngò om, hành lá) rửa sạch, thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (2930, '2025-11-20 17:11:05.860128', '2025-11-20 17:11:05.860128', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 477, 4, 'Dứa gọt vỏ, rửa sạch, cắt miếng tam giác.', 10);
INSERT INTO public.recipe_steps VALUES (2931, '2025-11-20 17:11:05.861754', '2025-11-20 17:11:05.861754', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 477, 10, 'c) Cách nấu canh chua cá không tanh, nước dùng thanh, hài hòa vị chua ngọt:Đun nóng chút dầu ăn trong chảo, cho tỏi vào phi thơm ở lửa nhỏ vừa, khi tỏi vàng vớt ra để riêng. Tiếp tục cho cá vào chiên sơ 2 mặt để giúp cá săn thịt và không bị tanh khi nấu. Múc cá ra bát, để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (2932, '2025-11-20 17:11:05.863354', '2025-11-20 17:11:05.863354', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 477, 8, 'Cà chua rửa sạch, bổ múi cau.', 10);
INSERT INTO public.recipe_steps VALUES (2933, '2025-11-20 17:11:05.864408', '2025-11-20 17:11:05.864408', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 477, 2, 'Ướp cá với chút nước mắm, hạt nêm, tỏi băm trong 10 phút cho thấm gia vị, để cá đậm đà hơn khi nấu.', 10);
INSERT INTO public.recipe_steps VALUES (2934, '2025-11-20 17:11:05.866515', '2025-11-20 17:11:05.866515', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 477, 5, 'Giá đỗ rửa sạch, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (2935, '2025-11-20 17:11:06.427853', '2025-11-20 17:11:06.427853', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 478, 2, 'Ngâm bò vào nước muối ấm pha loãng rồi rửa thật sạch.', 10);
INSERT INTO public.recipe_steps VALUES (2936, '2025-11-20 17:11:06.429539', '2025-11-20 17:11:06.429539', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 478, 11, 'c) Cách ngâm:Trước khi ngâm, bạn nên khử trùng hoàn toàn lại: Đun sôi lại một phần nước mắm còn lại trong nồi, cho bắp bò vào trụng qua, vớt ra. Tiếp đến cho tỏi, gừng, tiêu xanh vào trụng sơ, vớt ra.', 10);
INSERT INTO public.recipe_steps VALUES (2937, '2025-11-20 17:11:06.431134', '2025-11-20 17:11:06.431134', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 478, 1, 'a) Cách sơ chế và luộc bắp bò:Lọc bỏ phần mỡ xung quanh còn bám dính vào bắp bò, để cho khi ngâm không bị nổi váng.', 10);
INSERT INTO public.recipe_steps VALUES (2938, '2025-11-20 17:11:06.4322', '2025-11-20 17:11:06.4322', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 478, 3, 'Có thể để nguyên bắp luộc hoặc dùng chỉ buộc hình trụ lại để tạo hình bắp bò khi luộc.', 10);
INSERT INTO public.recipe_steps VALUES (2939, '2025-11-20 17:11:06.433826', '2025-11-20 17:11:06.433826', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 478, 6, 'Khi thịt nguội hoàn toàn thì vớt ra lấy khăn xô sạch thấm khô.', 10);
INSERT INTO public.recipe_steps VALUES (2940, '2025-11-20 17:11:06.434888', '2025-11-20 17:11:06.434888', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 478, 10, 'Gừng thái sợi, tỏi bóc vỏ thái mỏng, hạt tiêu xanh rửa sạch rồi cho vào ngâm với nước sôi ấm pha chút muối, vớt ra để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (2941, '2025-11-20 17:11:06.436466', '2025-11-20 17:11:06.436466', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 478, 5, 'Sau đó, vớt ra cho ngay thịt bò vào thau nước sôi để nguội có đá viên sạch (chú ý cũng ngập nước để bò không bị đen).', 10);
INSERT INTO public.recipe_steps VALUES (2942, '2025-11-20 17:11:06.43754', '2025-11-20 17:11:06.43754', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 478, 8, 'Quế, hoa hồi rang vàng. Hạt tiêu đen rang vàng.', 10);
INSERT INTO public.recipe_steps VALUES (2943, '2025-11-20 17:11:06.43914', '2025-11-20 17:11:06.43914', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 478, 7, 'b) Cách làm nước mắm ngâm: Làm song hành với khi luộc bò để cho nước mắm nguội:', 10);
INSERT INTO public.recipe_steps VALUES (2944, '2025-11-20 17:11:06.440288', '2025-11-20 17:11:06.440288', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 478, 9, 'Bắc một nồi nhỏ lên bếp, cho 200 ml nước lọc, 100 gram đường cát vàng, 40ml giấm gạo trắng 5% vào khuấy đều cho đường tan, đun sôi, hớt bọt. Sau đó, cho nước mắm, hoa hồi, quế vào nấu, bạn có thể nêm nếm lại theo khẩu vị gia đình. Sau 1-2 phút tắt bếp để nguội rồi rót vào lọ thủy tinh (nên để lại một ít nước mắm trong nồi để trụng lại thịt bò, các nguyên liệu khác khử trùng trước khi ngâm).', 10);
INSERT INTO public.recipe_steps VALUES (2945, '2025-11-20 17:11:06.441863', '2025-11-20 17:11:06.441863', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 478, 4, 'Trong một nồi đế dày, cho thịt bò vào, đổ lượng nước đủ ngập phần thịt bò. Thêm muối, đường, hạt nêm, hạt tiêu, hành tím, hành tây, sả, quế, hồi vào rồi đun sôi. Khi sôi, hớt bọt và hạ nhỏ lửa liu riu luộc cho tới khi thịt chín. Thời gian luộc khoảng từ 40-45 phút tùy vào khối lượng thịt bò. Tắt bếp, ngâm tầm 5-6 phút cho bò mềm, ngọt hơn.', 10);
INSERT INTO public.recipe_steps VALUES (2946, '2025-11-20 17:11:06.442924', '2025-11-20 17:11:06.442924', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 478, 12, 'Xếp thịt bò vào lọ thủy tinh, thêm hạt tiêu đen rang vàng, tỏi, gừng, tiêu xanh và rót hỗn hợp nước mắm đã nguội hoàn toàn vào, nén chặt. Chú ý: Nước mắm phải hoàn toàn ngập thịt.', 10);
INSERT INTO public.recipe_steps VALUES (2947, '2025-11-20 17:11:06.929634', '2025-11-20 17:11:06.929634', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 479, 2, 'Rửa sạch ốc, cho vào nồi nước cùng chút muối, bật bếp. Khi nước vừa sôi 1 phút, mày ốc vừa bong thì vớt ốc ra, ngâm vào nước lạnh. Rửa sạch, chặt trôn khều ốc, bỏ ruột đen, rửa sạch, ướp chút hành, tỏi băm và chút nước mắm, hạt nêm, hạt tiêu. Phần nước ốc lọc sạch, giữ lại.', 10);
INSERT INTO public.recipe_steps VALUES (2948, '2025-11-20 17:11:06.931215', '2025-11-20 17:11:06.931215', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 479, 9, 'c) Cách nấu ốc chuối đậu:Cho dầu ăn vào phi thơm hành tỏi, cho chuối vào xào săn lại, trút phần ốc vào nồi thịt, thêm cà chua (tùy chọn).', 10);
INSERT INTO public.recipe_steps VALUES (2949, '2025-11-20 17:11:06.933976', '2025-11-20 17:11:06.933976', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 479, 8, 'Hành lá, lá lốt và lá tía tô rửa sạch, thái nhỏ. Cà chua rửa sạch, thái múi cau.', 10);
INSERT INTO public.recipe_steps VALUES (2950, '2025-11-20 17:11:06.935596', '2025-11-20 17:11:06.935596', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 479, 4, 'Thêm chút nước vào mẻ khuấy đều, lọc qua rây để lấy mẻ mịn', 10);
INSERT INTO public.recipe_steps VALUES (2951, '2025-11-20 17:11:06.937182', '2025-11-20 17:11:06.937182', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 479, 6, 'Thịt ba chỉ rửa sạch, thái miếng con chì vừa ăn, áp chảo cho cháy cạnh và vàng đều, cho vào nồi.', 10);
INSERT INTO public.recipe_steps VALUES (2952, '2025-11-20 17:11:06.938763', '2025-11-20 17:11:06.938763', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 479, 11, 'Khi nước sốt sánh thì mới cho ốc và đậu phụ rán vàng vào, om tiếp 4-5 phút cho ngấm, nêm hạt nêm và mắm muối lại theo khẩu vị gia đình. Thêm hành lá, tía tô, lá lốt vào đảo đều, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (2953, '2025-11-20 17:11:06.940401', '2025-11-20 17:11:06.940401', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 479, 3, 'b) Chuẩn bị các nguyên liệu khác: Nghệ tươi gọt bỏ vỏ, giã nát, thêm 1/2 thìa canh nước cốt chanh để nghệ không bị thâm, vắt lấy nước cốt nghệ.', 10);
INSERT INTO public.recipe_steps VALUES (2954, '2025-11-20 17:11:06.943056', '2025-11-20 17:11:06.943056', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 479, 1, 'a) Sơ chế ốc:Dùng thau kim loại để ngâm vì ốc gặp kim loại sẽ nhả bùn nhanh. Cho nước vo gạo và vài lát ớt tươi vào ngâm ốc 2-3 giờ để nhả hết chất bẩn.', 10);
INSERT INTO public.recipe_steps VALUES (2955, '2025-11-20 17:11:06.945164', '2025-11-20 17:11:06.945164', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 479, 7, 'Đậu phụ cắt miếng vừa ăn, rán vàng.', 10);
INSERT INTO public.recipe_steps VALUES (2956, '2025-11-20 17:11:06.947382', '2025-11-20 17:11:06.947382', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 479, 10, 'Thêm nước luộc ốc (đã lọc sạch), nước vào xâm xấp mặt. Thêm gia vị: 1,5 muỗng canh nước mắm, 1/2 muỗng canh mắm tôm, 1 muỗng cà phê muối, 1 muỗng cà phê hạt nêm, phần mẻ và nước cốt nghệ còn lại vào. Bập bếp và om cho tới khi thịt, chuối chín mềm, nước sốt sánh lại.', 10);
INSERT INTO public.recipe_steps VALUES (2957, '2025-11-20 17:11:06.949537', '2025-11-20 17:11:06.949537', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 479, 5, 'Chuối xanh tước bỏ vỏ (hoặc giữ lại vỏ tùy theo sở thích), cắt khúc vừa ăn, ngâm vào nước vo gạo cùng chút muối hoặc vắt chút chanh vào để tránh bị thâm. Rửa sạch. Ướp chuối với một nửa nước cốt nghệ, nửa mẻ, đảo đều.', 10);
INSERT INTO public.recipe_steps VALUES (2958, '2025-11-20 17:11:07.458554', '2025-11-20 17:11:07.458554', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 480, 1, 'a) Cách ướp, nướng hoặc áp chảo thịt gà:Thịt đùi gà hoặc ức gà phi lê, ngâm nước muối loãng cùng chút hành tím cắt lát để khử mùi trong 10-15 phút. Sau đó, rửa sạch, thấm khô.', 10);
INSERT INTO public.recipe_steps VALUES (2959, '2025-11-20 17:11:07.460209', '2025-11-20 17:11:07.460209', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 480, 6, 'Cách 1:Nước chấm làm 1 lần dùng cả tháng', 10);
INSERT INTO public.recipe_steps VALUES (2960, '2025-11-20 17:11:07.461842', '2025-11-20 17:11:07.461842', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 480, 5, 'b) Cách làm nước chấm: Có 2 cách', 10);
INSERT INTO public.recipe_steps VALUES (2961, '2025-11-20 17:11:07.463455', '2025-11-20 17:11:07.463455', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 480, 9, 'Làm đồ chua (nêm làm sẵn trước, để tủ lạnh sẽ giòn hơn khi ăn): Cà rốt, củ cải thái sợi ngâm chút nước muối loãng, rửa nước ấm, vắt ráo. Sau đó trộn với đường, giấm/hoặc chanh theo khẩu vị, đặt vào ngăn mát tủ lạnh 15 phút cho giòn hơn.', 10);
INSERT INTO public.recipe_steps VALUES (2962, '2025-11-20 17:11:07.465047', '2025-11-20 17:11:07.465047', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 480, 10, 'Làm mỡ hành: Hành lá rửa sạch, cắt nhỏ thêm chút muối, đổ dầu ăn đun nóng vào trộn đều. Hoặc bạn trộn đều hành lá, chút muối, dầu ăn rồi cho vào lò vi sóng quay 20 giây.', 10);
INSERT INTO public.recipe_steps VALUES (2963, '2025-11-20 17:11:07.46616', '2025-11-20 17:11:07.46616', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 480, 11, 'Bún trụng sơ nước sôi. Nếu ở nước ngoài, bạn dùng bún khô thì nấu theo hướng dẫn trên bao bì.', 10);
INSERT INTO public.recipe_steps VALUES (3043, '2025-11-20 17:11:11.539334', '2025-11-20 17:11:11.539334', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 488, 2, 'Nếu có thời gian, bạn nên ướp mỡ chài với chút đường rồi đem phơi nắng để mỡ trở nên trong, ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (2964, '2025-11-20 17:11:07.467737', '2025-11-20 17:11:07.467737', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 480, 3, 'Đun nóng chút dầu ăn trong chảo, lấy thịt gà (gạt bỏ phần sả, tỏi dễ cháy khi nấu), rồi cho vào gà vào áp chảo. Chú ý trở đều hai mặt và nướng cho tới khi xém vàng và chín tới. Bạn có thể dùng lò nướng gà thay vì áp chảo.', 10);
INSERT INTO public.recipe_steps VALUES (2965, '2025-11-20 17:11:07.469899', '2025-11-20 17:11:07.469899', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 480, 8, 'c) Chuẩn bị các nguyên liệu khác:Rau sống rửa sạch, ngâm nước muối loãng, vẩy ráo nước. Dưa chuột rửa sạch, thái sợi. Giá đỗ rửa sạch, chần qua nước sôi. Lạc rang, giã dập.', 10);
INSERT INTO public.recipe_steps VALUES (2966, '2025-11-20 17:11:07.471599', '2025-11-20 17:11:07.471599', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 480, 2, 'Trong một tô trộn lớn, cho thịt gà cùng các gia vị ướp vào trộn đều, dùng màng bọc thực phẩm bọc kín, cho vào ngăn mát tủ lạnh tối thiểu 1 giờ, hoặc tốt nhất để qua đêm cho thịt ngấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (2967, '2025-11-20 17:11:07.473294', '2025-11-20 17:11:07.473294', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 480, 7, 'Cách 2: Pha nước chấm mắm: đường: chanh: nước sôi để nguội theo tỷ lệ 1:1:1:5. Trong một cái bát, cho 3 muỗng canh nước mắm (30-40 độ đạm), 3 muỗng canh nước cốt chanh, 3 muỗng canh đường và 15 muỗng canh nước lọc. Khuấy cho đến khi đường tan hẳn thì thêm tỏi, ớt băm nhuyễn vào sẽ nổi lên trên.', 10);
INSERT INTO public.recipe_steps VALUES (2968, '2025-11-20 17:11:07.474893', '2025-11-20 17:11:07.474893', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 480, 4, 'Gắp thịt gà ra, để nguội và thái miếng mỏng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (2969, '2025-11-20 17:11:08.055475', '2025-11-20 17:11:08.055475', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 481, 2, 'Bóp tai heo với một thìa canh dấm, 1 thìa canh muối trắng, 1 thìa canh rượu.', 10);
INSERT INTO public.recipe_steps VALUES (2970, '2025-11-20 17:11:08.057074', '2025-11-20 17:11:08.057074', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 481, 6, 'Thả vào đó một 1 gừng đập dập, 2 củ sả đập dập.', 10);
INSERT INTO public.recipe_steps VALUES (2971, '2025-11-20 17:11:08.058639', '2025-11-20 17:11:08.058639', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 481, 12, 'Nêm nếm gia vị cho hợp khẩu vị, không nên nêm vừa ăn vì khi cạn sẽ bị mặn.', 10);
INSERT INTO public.recipe_steps VALUES (2972, '2025-11-20 17:11:08.060238', '2025-11-20 17:11:08.060238', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 481, 4, 'Cuộn tròn tai heo:Cuộn từ phần đầu nhọn vào, giữ chặt tay, dùng chỉ hoặc dây dù cuộn chặt lại thành nhiều vòng, rồi buộc chặt lại.', 10);
INSERT INTO public.recipe_steps VALUES (2973, '2025-11-20 17:11:08.061854', '2025-11-20 17:11:08.061854', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 481, 7, 'Nước sôi sả gừng toả mùi thơm thì thả tai heo vào trần khoảng 3-4 phút.', 10);
INSERT INTO public.recipe_steps VALUES (2974, '2025-11-20 17:11:08.06286', '2025-11-20 17:11:08.06286', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 481, 11, 'Trong lúc đun thỉnh thoảng trở mặt tai heo cho gia vị ngấm đều (ai thích ăn cay cho ít ớt bột hoặc vài miếng ớt cay vào).', 10);
INSERT INTO public.recipe_steps VALUES (2975, '2025-11-20 17:11:08.064398', '2025-11-20 17:11:08.064398', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 481, 14, 'Để thật nguội cất ngăn mát tủ lạnh tầm 3-4 tiếng, rồi cắt lát mỏng chấm với tương ớt.', 10);
INSERT INTO public.recipe_steps VALUES (2976, '2025-11-20 17:11:08.065407', '2025-11-20 17:11:08.065407', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 481, 8, 'Vớt ra rửa sạch lại, lúc này tai heo đã hết mùi hôi và thơm mùi sả, gừng.', 10);
INSERT INTO public.recipe_steps VALUES (2977, '2025-11-20 17:11:08.067433', '2025-11-20 17:11:08.067433', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 481, 10, 'Cho các gia vị: xì dầu, dầu hào, hạt tiêu, bột nêm, tỏi băm, hành băm, hoa hồi, quế, thảo quả, vào nồi, đun sôi hạ nhỏ lửa, đun liu riu cho đến khi nước trong nồi cạn.', 10);
INSERT INTO public.recipe_steps VALUES (2978, '2025-11-20 17:11:08.069561', '2025-11-20 17:11:08.069561', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 481, 13, 'Nước trong nồi cạn, hơi sền sệt, chuyển sang màu cánh gián thì vớt tai heo ra.', 10);
INSERT INTO public.recipe_steps VALUES (2979, '2025-11-20 17:11:08.070607', '2025-11-20 17:11:08.070607', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 481, 3, 'Sau đó rửa lại thật sạch bằng nước trắng.', 10);
INSERT INTO public.recipe_steps VALUES (2980, '2025-11-20 17:11:08.07161', '2025-11-20 17:11:08.07161', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 481, 5, 'Đun sôi một nồi nước (ngập tai heo).', 10);
INSERT INTO public.recipe_steps VALUES (2981, '2025-11-20 17:11:08.074194', '2025-11-20 17:11:08.074194', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 481, 9, 'Cho tai heo cuộn tròn, sơ chế sạch vào nồi, đổ nước dừa tươi xâm xấp hoặc không có nước dừa tươi thì dùng nước trắng.', 10);
INSERT INTO public.recipe_steps VALUES (2982, '2025-11-20 17:11:08.075276', '2025-11-20 17:11:08.075276', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 481, 1, 'Tai heo mua về cạo sạch lông, chất bẩn, rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (2983, '2025-11-20 17:11:08.726534', '2025-11-20 17:11:08.726534', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 482, 5, 'Sau khi ướp, phần thịt miếng xiên vào que tre. Phần thịt xay và giò sống thì viên thành các viên tròn vừa ăn rồi ấn dẹt xuống cho vào vỉ nướng. Khi nướng, chú ý lửa nhỏ và trở mặt cho thịt chín đều, thỉnh thoảng phết thêm mỡ hành để thịt mềm mà không bị khô.', 10);
INSERT INTO public.recipe_steps VALUES (2984, '2025-11-20 17:11:08.729213', '2025-11-20 17:11:08.729213', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 482, 10, 'd) Cách pha nước chấm:Có 2 cách:', 10);
INSERT INTO public.recipe_steps VALUES (2985, '2025-11-20 17:11:08.731435', '2025-11-20 17:11:08.731435', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 482, 2, 'Phần thịt ba chỉ 500 grams ướp 2/3 phần nước sốt ướp.', 10);
INSERT INTO public.recipe_steps VALUES (2986, '2025-11-20 17:11:08.734127', '2025-11-20 17:11:08.734127', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 482, 6, 'b) Chuẩn bị các nguyên liệu khác:Rau sống rửa sạch, vẩy ráo. Dưa chuột rửa sạch, thái sợi. Giá đỗ rửa sạch, chần qua nước sôi. Lạc rang, giã dập.', 10);
INSERT INTO public.recipe_steps VALUES (2987, '2025-11-20 17:11:08.735731', '2025-11-20 17:11:08.735731', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 482, 1, 'a) Cách ướp và nướng thịt:Cho hành, tỏi, sả cùng nước vào máy xay nhuyễn, vắt lấy nước cốt cho vào bát. Thêm 2 muỗng canh dầu hào, 1 muỗng canh mật ong, 1 muỗng canh nước mắm, 1 muỗng canh nước màu, 1 muỗng canh dầu hành phi (hoặc dầu mè), 1/2 muỗng canh nướt cốt chanh, 1 muỗng canh tương ớt, 1/2 muỗng canh đường (tùy vào khẩu vị), 1 muỗng canh dầu điều, 1/2 muỗng cà phê muối, 1/2 muỗng cà phê hạt tiêu, 1/4 muỗng cà phê ngũ vị hương. Tất cả khuấy đều trở thành hỗn hợp sánh đặc rồi chia ra 3 phần cho vào ướp.', 10);
INSERT INTO public.recipe_steps VALUES (2988, '2025-11-20 17:11:08.737689', '2025-11-20 17:11:08.737689', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 482, 7, 'Làm đồ chua: Cà rốt, củ cải thái sợi hoặc cắt tạo hình hoa tùy thích, ngâm chút nước muối loãng trong 10 phút, rửa nước ấm, vắt ráo. Sau đó trộn với đường, giấm/hoặc chanh theo khẩu vị, đặt vào ngăn mát tủ lạnh để 15 phút cho giòn.', 10);
INSERT INTO public.recipe_steps VALUES (2989, '2025-11-20 17:11:08.739833', '2025-11-20 17:11:08.739833', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 482, 4, 'Ướp tối thiểu trong 1 giờ cho thịt ngấm. Hoặc tốt nhất bọc màng thực phẩm, để trong ngăn mát tủ lạnh ướp qua đêm sẽ ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (3018, '2025-11-20 17:11:09.771114', '2025-11-20 17:11:09.771114', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 485, 12, 'Sau 20-25 phút khi thịt đã mềm, thêm mộc nhĩ đã xào vào đun khoảng 5-6 phút thì tắt bếp, thêm hạt tiêu sọ vào đảo đều. Lúc này mới cho hạt nêm, nêm nếm lại gia vị cho phù hợp. Tắt bếp, để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (2990, '2025-11-20 17:11:08.741934', '2025-11-20 17:11:08.741934', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 482, 12, 'Nước chấm pha luôn: Theo tỷ lệ mắm: đường: chanh: nước là 1:1:1:5. Trong một cái bát, cho 3 muỗng canh nước mắm (30-40 độ), 3 muỗng canh nước cốt chanh, 3 muỗng canh đường và 15 muỗng canh nước lọc. Khuấy cho đến khi đường tan hẳn thì thêm tỏi, ớt băm nhuyễn vào sẽ nổi lên trên.', 10);
INSERT INTO public.recipe_steps VALUES (2991, '2025-11-20 17:11:08.743536', '2025-11-20 17:11:08.743536', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 482, 11, 'Làm nước chấm 1 lần dùng cả tháng:Xem tại đây', 10);
INSERT INTO public.recipe_steps VALUES (2992, '2025-11-20 17:11:08.745129', '2025-11-20 17:11:08.745129', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 482, 3, 'Phần thịt xay + giò sống trộn đều ướp với 1/3 phần nước sốt còn lại.', 10);
INSERT INTO public.recipe_steps VALUES (2993, '2025-11-20 17:11:08.746759', '2025-11-20 17:11:08.746759', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 482, 8, 'Làm dầu hành lá: Hành lá rửa sạch, cắt nhỏ thêm chút muối, đổ dầu ăn đun nóng vào trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (2994, '2025-11-20 17:11:08.748376', '2025-11-20 17:11:08.748376', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 482, 9, 'c) Cách làm chả giò:Xem tại đây', 10);
INSERT INTO public.recipe_steps VALUES (2995, '2025-11-20 17:11:09.076776', '2025-11-20 17:11:09.076776', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 483, 1, 'a) Sơ chế và khử mùi sườn: Sườn non chặt miếng vừa ăn, rửa sạch với nước vo gạo.', 10);
INSERT INTO public.recipe_steps VALUES (2996, '2025-11-20 17:11:09.078901', '2025-11-20 17:11:09.078901', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 483, 5, 'Giai đoạn 2: Ram mở nắp để thoát hơi nước, giúp nước sốt sánh lại: Sau 30 phút, mở nắp và tiếp tục đun nhỏ lửa trong 20-25 phút hoặc cho đến khi nước sốt sánh lại. Nêm nếm gia vị lại theo khẩu vị gia đình. Tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (2997, '2025-11-20 17:11:09.080496', '2025-11-20 17:11:09.080496', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 483, 2, 'Chần sườn trong nồi nước có chút muối hạt, vài lát gừng đập dập, vớt ra, rửa sạch, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (2998, '2025-11-20 17:11:09.081556', '2025-11-20 17:11:09.081556', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 483, 3, 'b) Ướp sườn:Ướp sườn với 1/2 số hành tỏi băm, 2 muỗng canh nước mắm, 1,5 muỗng canh đường (gia giảm theo khẩu vị), 1,5 muỗng canh nước màu, 1 muỗng cà phê muối, 1 muỗng cà phê mật ong, 1 muỗng cà phê hạt nêm rau củ, 1/2 muỗng cà phê tiêu đen xay tối thiểu 15 phút. Nếu ướp lâu thì sẽ thấm gia vị ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (2999, '2025-11-20 17:11:09.083206', '2025-11-20 17:11:09.083206', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 483, 4, 'c) Ram sườn: chia làm 2 giai đoạn:Giai đoạn 1: Ram đậy nắp cho sườn mềm: Cho dầu ăn vào chảo, phi thơm hành tỏi còn lại, cho sườn vào xào săn lại. Thêm nước dừa tươi, nước sốt ướp sườn, sao cho xăm xắp mặt, đun sôi, vớt bỏ bọt, hạ nhỏ lửa, đậy nắp, ram sườn trong 30 phút. Trong quá trình rim, thỉnh thoảng đảo đều.', 10);
INSERT INTO public.recipe_steps VALUES (3000, '2025-11-20 17:11:09.426351', '2025-11-20 17:11:09.426351', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 484, 7, 'Lần lượt gắp các miếng cá vào chiên, trở đều các mặt.', 10);
INSERT INTO public.recipe_steps VALUES (3001, '2025-11-20 17:11:09.42739', '2025-11-20 17:11:09.42739', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 484, 6, 'Đun nóng dầu ăn, thử bằng cách dùng đầu đũa cho vào, nếu sủi tăm ở đầu đũa là đã đạt độ nóng. Hạ lửa ở mức vừa nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3002, '2025-11-20 17:11:09.429471', '2025-11-20 17:11:09.429471', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 484, 4, '''''Bao áo'''' bột chiên xù cho cá: Đổ bột chiên xù ra hộp hoặc đĩa. Lấy đũa nhúng từng miếng cá vào hỗn hợp bột nước sánh, rồi lăn qua bột chiên xù phủ một lớp đều trên cá. Làm lần lượt cho tới hết.', 10);
INSERT INTO public.recipe_steps VALUES (3003, '2025-11-20 17:11:09.431105', '2025-11-20 17:11:09.431105', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 484, 1, 'a) Sơ chế và ướp cá: Cá làm sạch, lọc bỏ xương, thái miếng vừa ăn, rửa sạch lại, thấm khô.', 10);
INSERT INTO public.recipe_steps VALUES (3004, '2025-11-20 17:11:09.432719', '2025-11-20 17:11:09.432719', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 484, 8, 'Khi cá chín vàng đều thì gắp ra đĩa có lót giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (3005, '2025-11-20 17:11:09.434391', '2025-11-20 17:11:09.434391', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 484, 3, 'b) Làm bột và ‘bao bột áo’ cho cá: Làm hỗn hợp bột ướt: Trong một tô trộn, cho bột chiên giòn (hoặc bột mì) vào. Đánh tan trứng cho vào tô bột, thêm bia (hoặc nước) vào. Nên rót từng lượng nhỏ vào để căn chỉnh, khuấy đều làm sao tạo nên hỗn hợp bột hơi sánh (Không nên đặc hay loãng quá).', 10);
INSERT INTO public.recipe_steps VALUES (3006, '2025-11-20 17:11:09.43601', '2025-11-20 17:11:09.43601', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 484, 2, 'Ướp cá với 1 thìa cà phê rượu trắng, 1/2 thìa cà phê muối, 1/2 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu trong 10-15 phút.', 10);
INSERT INTO public.recipe_steps VALUES (3007, '2025-11-20 17:11:09.437845', '2025-11-20 17:11:09.437845', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 484, 5, 'c) Chiên cá:Cho dầu ăn vào chảo (nên ngập hoặc 2/3 miếng cá để chiên giòn và thoát dầu, đỡ ngấm vào cá).', 10);
INSERT INTO public.recipe_steps VALUES (3008, '2025-11-20 17:11:09.756454', '2025-11-20 17:11:09.756454', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 485, 2, 'Phần thịt', 10);
INSERT INTO public.recipe_steps VALUES (3009, '2025-11-20 17:11:09.758028', '2025-11-20 17:11:09.758028', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 485, 5, 'Ướp thịt với 2 muỗng canh nước mắm ngon, một chút mì chính (tùy chọn), 1/2 muỗng canh muối, 1 chút hạt tiêu, tối thiểu trong 30 phút để ngấm gia vị. Lưu ý: Không nên ướp hạt nêm lúc này vì khi ninh hạt nêm làm từ xương tan ra sẽ làm đục nước.', 10);
INSERT INTO public.recipe_steps VALUES (3010, '2025-11-20 17:11:09.759097', '2025-11-20 17:11:09.759097', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 485, 4, 'Cho thịt, bì/hoặc tai vào nồi nước thêm gừng đập dập, hành tây, 1 muỗng canh muối để chần thịt, loại bỏ tạp chất. Sau đó, đổ ra, rửa thật sạch.', 10);
INSERT INTO public.recipe_steps VALUES (3011, '2025-11-20 17:11:09.760699', '2025-11-20 17:11:09.760699', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 485, 7, 'Tiêu hạt sọ rang thơm, đập dập.', 10);
INSERT INTO public.recipe_steps VALUES (3012, '2025-11-20 17:11:09.762922', '2025-11-20 17:11:09.762922', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 485, 8, 'Cà rốt rửa sạch, tỉa hoa tùy thích, chần qua nước sôi kèm chút muối, vớt ra ngâm vào bát nước lạnh, để giữ màu sắc tự nhiên.', 10);
INSERT INTO public.recipe_steps VALUES (3013, '2025-11-20 17:11:09.763973', '2025-11-20 17:11:09.763973', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 485, 1, 'a) Sơ chế nguyên liệu', 10);
INSERT INTO public.recipe_steps VALUES (3014, '2025-11-20 17:11:09.765046', '2025-11-20 17:11:09.765046', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 485, 9, 'b) Xào và nấu thịt đông:Phi thơm hành tím với một chút dầu ăn, cho thịt đã ướp vào xào săn lại cho thấm gia vị và dậy mùi thơm.', 10);
INSERT INTO public.recipe_steps VALUES (3015, '2025-11-20 17:11:09.76665', '2025-11-20 17:11:09.76665', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 485, 6, 'Chuẩn bị các nguyên liệu khác: Mộc nhĩ ngâm nở, để ráo, cắt miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (3016, '2025-11-20 17:11:09.768268', '2025-11-20 17:11:09.768268', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 485, 3, 'Thịt chân giò và bì/hoặc tai lợn (heo) cạo sạch lông, bóp chút muối hạt/hoặc chanh, ngâm vào nước vo gạo rồi rửa sạch, cắt miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (3017, '2025-11-20 17:11:09.769875', '2025-11-20 17:11:09.769875', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 485, 11, 'Phi thơm hành, cho mộc nhĩ vào xào chín, nêm gia vị phù hợp.', 10);
INSERT INTO public.recipe_steps VALUES (3019, '2025-11-20 17:11:09.772697', '2025-11-20 17:11:09.772697', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 485, 10, 'Tiếp đến, đổ lượng nước vào vừa đủ ngập thịt. Khi sôi, hạ nhỏ lửa, vớt bỏ bọt, hé mở vung nồi (để nước được trong) và nấu từ 20 - 25 phút cho tới khi thịt mềm (đừng để thịt nhừ quá). Cần vớt bỏ bọt liên tục để nước dùng trong.', 10);
INSERT INTO public.recipe_steps VALUES (3020, '2025-11-20 17:11:10.629394', '2025-11-20 17:11:10.629394', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 486, 8, 'Lần 1: Bật bếp đun nóng dầu ăn, dùng đầu đũa thử nếu thấy sủi tăm là đã đạt độ nóng, hạ lửa nhỏ. Lần lượt cho nem ốc vào rán chín sơ, vớt ra để giấy thấm dầu. Phần dầu trong chảo, dùng 1 lòng trắng trứng vào quấy đều để lọc phần đen, lọc qua rây để lấy lại dầu trong hơn.', 10);
INSERT INTO public.recipe_steps VALUES (3021, '2025-11-20 17:11:10.630998', '2025-11-20 17:11:10.630998', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 486, 6, 'Sau khi cuộn xong, nên để nem vào tủ lạnh tầm 20-30 phút để tạo hình cứng cáp và khi rán giòn hơn.', 10);
INSERT INTO public.recipe_steps VALUES (3022, '2025-11-20 17:11:10.632593', '2025-11-20 17:11:10.632593', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 486, 4, 'Lót thêm 1/4 bánh đa nem vào mặt trong, múc nhân cho vào giữa, gấp mép hai bên rồi cuộn nhẹ nhàng (chú ý không cuộn chặt tay quá hoặc lỏng quá. Vì chặt quá sẽ bị bung/vỡ khi rán).', 10);
INSERT INTO public.recipe_steps VALUES (3023, '2025-11-20 17:11:10.634194', '2025-11-20 17:11:10.634194', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 486, 10, 'd) Cách pha nước chấm:Chi tiết tại đây', 10);
INSERT INTO public.recipe_steps VALUES (3024, '2025-11-20 17:11:10.636323', '2025-11-20 17:11:10.636323', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 486, 1, 'a) Cách sơ chế ốc:Ốc mua về ngâm với nước vo gạo kèm vài lát ớt để nhả hết bùn đất. Sau 1-2 giờ, rửa sạch và đem luộc sơ, khều thịt ốc và bóp lại với chút chanh, muối cho hết nhớt, rửa sạch và thái miếng nhỏ sẽ giúp nem giòn sần sật (không nên băm nhuyễn vì mất đi độ giòn đặc trưng của ốc).', 10);
INSERT INTO public.recipe_steps VALUES (3025, '2025-11-20 17:11:10.638272', '2025-11-20 17:11:10.638272', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 486, 2, 'Trong một tô trộn lớn, trộn đều thịt ốc với thịt heo xay, giò sống, mộc nhĩ, miến dong, giá đậu, cà rốt, hành tím băm, lá lốt thái nhỏ, sả băm, hạt nêm, hạt tiêu, dầu hành, trứng, bột bắp/hoặc bột năng. Để tầm 5 phút cho thấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (3026, '2025-11-20 17:11:10.639887', '2025-11-20 17:11:10.639887', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 486, 9, 'Lần 2: Khi nào ăn thì rán nem lần 2 với nhiệt độ cao hơn vừa giúp nem giòn rụm, vừa thoát dầu, vừa làm cho nem không bị ngấy quá. Vớt nem ra cho vào giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (3027, '2025-11-20 17:11:10.641468', '2025-11-20 17:11:10.641468', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 486, 3, 'b) Cách gói nem ốc:Dùng khăn mềm nhúng vào bia cho hơi ẩm rồi quết nhẹ lên bánh đa nem cho dễ gói.', 10);
INSERT INTO public.recipe_steps VALUES (3028, '2025-11-20 17:11:10.643078', '2025-11-20 17:11:10.643078', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 486, 7, 'c) Cách rán nem giòn rụm:Bắc chảo sâu lòng lên bếp, thêm vài giọt nước cốt chanh (để giúp nem giòn, không bị đen khi rán). Nên rán nem ốc 2 lửa sẽ giòn rụm, thơm ngon:', 10);
INSERT INTO public.recipe_steps VALUES (3029, '2025-11-20 17:11:10.644686', '2025-11-20 17:11:10.644686', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 486, 5, 'Khi cuốn đến giữa thì thêm 1 lá lốt, tiếp tục cuốn. Khi gần hết thì phết chút lòng trắng trứng lên mép tạo độ dính để gấp lại. Làm lần lượt cho tới khi hết nhân.', 10);
INSERT INTO public.recipe_steps VALUES (3030, '2025-11-20 17:11:10.98882', '2025-11-20 17:11:10.98882', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 487, 7, 'Khi sôi hạ nhỏ lửa đun liu riu trong khoảng 20 phút hoặc cho tới khi cạn, nước sốt sánh lại, nêm nếm lại gia vị theo khẩu vị gia đình.', 10);
INSERT INTO public.recipe_steps VALUES (3031, '2025-11-20 17:11:10.990394', '2025-11-20 17:11:10.990394', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 487, 1, 'a) Sơ chế phần gà:Gà làm sạch, chà xát chút chanh rồi rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (3032, '2025-11-20 17:11:10.992653', '2025-11-20 17:11:10.992653', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 487, 6, 'Trong một cái nồi, phi thơm hành, tỏi, cho gà và toàn bộ nước sốt ướp cùng nước dừa tươi, nước vào đậy vung, đun sôi.', 10);
INSERT INTO public.recipe_steps VALUES (3033, '2025-11-20 17:11:10.994244', '2025-11-20 17:11:10.994244', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 487, 3, 'Dùng xiên nhọn châm vào gà để việc ướp gia vị nhanh ngấm hơn.', 10);
INSERT INTO public.recipe_steps VALUES (3034, '2025-11-20 17:11:10.99638', '2025-11-20 17:11:10.99638', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 487, 2, 'Sau đó, ngâm gà vào chút nước muối loãng cùng chút gừng đập dập trong 10 phút để khử mùi. Vớt ra, rửa sạch, thấm khô, để nguyên đùi hoặc cắt miếng tùy chọn.', 10);
INSERT INTO public.recipe_steps VALUES (3035, '2025-11-20 17:11:10.99794', '2025-11-20 17:11:10.99794', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 487, 5, 'b) Cách nấu gà roti:Đun nóng dầu thực vật trong chảo ở lửa nhỏ vừa, gắp gà (trừ nước ướp) vào và áp chảo mỗi mặt trong vài phút để phần da săn lại và hơi xém vàng. Việc này giúp cho lên màu sẽ đẹp hơn.', 10);
INSERT INTO public.recipe_steps VALUES (3036, '2025-11-20 17:11:10.999543', '2025-11-20 17:11:10.999543', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 487, 4, 'Ướp thịt gà với nước cốt hành tỏi băm, mắm, muối, nước tương, dầu hào, nước màu, đường, mật ong, dầu mè, hạt nêm, hạt tiêu, ngũ vị hương tối thiểu trong 30 phút hoặc tốt nhất bọc kín để ngăn mát tủ lạnh qua đêm càng ngon.', 10);
INSERT INTO public.recipe_steps VALUES (3037, '2025-11-20 17:11:11.528352', '2025-11-20 17:11:11.528352', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 488, 4, 'Bún trụng sơ, các loại rau rửa sạch, vẩy ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (3038, '2025-11-20 17:11:11.53001', '2025-11-20 17:11:11.53001', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 488, 3, 'Tiếp theo, trong một tô trộn lớn, thêm thịt bò, thịt heo, mỡ chài cùng các gia vị ướp (dầu hào, lá lốt thái nhỏ, hành tím băm, sả băm, tỏi băm, hạt tiêu, đường, hạt nêm, bột bắp, tiêu xanh, dầu hành phi). Tất cả trộn đều và bọc màng thực phẩm kín, để trong tủ lạnh ít nhất 30 phút cho thịt ngấm đều gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (3039, '2025-11-20 17:11:11.531613', '2025-11-20 17:11:11.531613', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 488, 5, 'b) Cuốn và nướng thịt bò:Cho lá lốt vào lòng bàn tay hoặc mặt thớt, lật phần gân lên trên và múc hỗn hợp thịt đã ướp vào, gập hai bên lại và cuộn tròn, dùng cuống lá ghim lại hoặc xiên cố định nhiều cái bằng xiên tre. Làm lần lượt cho tới khi hết.', 10);
INSERT INTO public.recipe_steps VALUES (3040, '2025-11-20 17:11:11.533728', '2025-11-20 17:11:11.533728', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 488, 1, 'Lá lốt rửa sạch, lau khô', 10);
INSERT INTO public.recipe_steps VALUES (3041, '2025-11-20 17:11:11.53532', '2025-11-20 17:11:11.53532', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 488, 7, 'c) Cách làm mỡ hành:Hành lá rửa sạch thái nhỏ trộn đều cùng chút bột canh, đường, hạt nêm, hạt tiêu. Đun nóng dầu ăn rồi đổ vào hỗn hợp trên, lượng dầu đủ sền sệt phần hành là được.', 10);
INSERT INTO public.recipe_steps VALUES (3042, '2025-11-20 17:11:11.537218', '2025-11-20 17:11:11.537218', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 488, 10, 'Làm nước mắm nêm: Phi thơm tỏi, sả băm thêm 1 chén mắm nêm, 2/3 chén dứa (thơm) bằm nhuyễn, 3 muỗng canh đường, 3 muỗng canh nước lọc, 1 muỗng cà phê hạt nêm, khuấy đều đun sôi. Sau đó, để nguội thì mới cho 1 muỗng canh nước cốt chanh vào.', 10);
INSERT INTO public.recipe_steps VALUES (3044, '2025-11-20 17:11:11.542021', '2025-11-20 17:11:11.542021', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 488, 6, 'Nướng bằng than hoa là ngon nhất. Hoặc bạn có thể tùy chọn cách phù hợp như: Nướng lò, cho vào nồi chiên không khí hoặc chiên bằng dầu ăn cho tới khi chín đều. Lưu ý trước khi nướng nên phết một lớp nhẹ dầu ăn lên vỉ nướng hoặc lá lốt để không bị khô, cháy. Trong quá trình nướng, nhớ trở hai mặt để thịt chín đều. Còn nếu chiên thì để nhỏ lửa, trở các mặt chín đều.', 10);
INSERT INTO public.recipe_steps VALUES (3045, '2025-11-20 17:11:11.544772', '2025-11-20 17:11:11.544772', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 488, 8, 'd) Cách làm nước chấm: Tùy theo sở thích bạn có thể chấm nước mắm chua ngọt hoặc mắm nêm.', 10);
INSERT INTO public.recipe_steps VALUES (3046, '2025-11-20 17:11:11.546907', '2025-11-20 17:11:11.546907', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 488, 9, 'Cách làm nước mắm chua ngọt:Chi tiết ở đây', 10);
INSERT INTO public.recipe_steps VALUES (3047, '2025-11-20 17:11:12.261895', '2025-11-20 17:11:12.261895', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 489, 1, 'a) Để làm sốt trộn:Bạn nên dùng một cái bát, trộn đều 2 muỗng canh nước mắm, 2 muỗng canh đường, 1 muỗng canh dầu hào, 1 muỗng canh tiêu đen rồi để qua một bên.', 10);
INSERT INTO public.recipe_steps VALUES (3048, '2025-11-20 17:11:12.263663', '2025-11-20 17:11:12.263663', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 489, 2, 'b) Sơ chế và ướp tôm:Tôm được làm sạch, dùng kéo cắt xẻ ở lưng, rút chỉ, nhẹ nhàng tách một phần vỏ ra nhưng vẫn dính vào thân.', 10);
INSERT INTO public.recipe_steps VALUES (3049, '2025-11-20 17:11:12.265246', '2025-11-20 17:11:12.265246', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 489, 10, 'Sau đó, thêm hỗn hợp nước sốt ở trên vào, nêm nếm lại theo khẩu vị gia đình. Đun và quấy đều nước sốt trong 2-3 phút cho tới khi trở nên sền sệt.', 10);
INSERT INTO public.recipe_steps VALUES (3050, '2025-11-20 17:11:12.26739', '2025-11-20 17:11:12.26739', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 489, 11, 'Lúc này, nhanh tay cho tôm vào đảo, lắc đều để nước sốt bám đều các mặt tôm.', 10);
INSERT INTO public.recipe_steps VALUES (3051, '2025-11-20 17:11:12.269003', '2025-11-20 17:11:12.269003', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 489, 6, 'Chia tôm thành từng mẻ nhỏ, lần lượt cho vào chảo rồi chiên chín vàng đều các mặt trong khoảng 1 phút. Lưu ý không nên cho tôm nhiều vào một lúc vì nhiệt độ sẽ giảm, làm lớp bột bao áo bị nhão ra.', 10);
INSERT INTO public.recipe_steps VALUES (3052, '2025-11-20 17:11:12.270636', '2025-11-20 17:11:12.270636', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 489, 12, 'e) Phục vụ:Chuyển tôm ra đĩa, trang trí với rau mùi, ớt (tùy ý) và thưởng thức ngay với cơm nóng hoặc lai rai đều phù hợp.', 10);
INSERT INTO public.recipe_steps VALUES (3053, '2025-11-20 17:11:12.272247', '2025-11-20 17:11:12.272247', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 489, 4, 'c) Cách chiên tôm:Cho tôm vào túi nhựa zipper hoặc hộp nhựa lớn, thêm bột khoai tây/hoặc bột bắp, thêm bột nở, lắc đều để bột bám đều vào các mặt của con tôm.', 10);
INSERT INTO public.recipe_steps VALUES (3054, '2025-11-20 17:11:12.273838', '2025-11-20 17:11:12.273838', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 489, 3, 'Ướp tôm với 1 quả trứng đã đánh tan, 1/2 muỗng cà phê hạt nêm, 1/2 muỗng cà phê bột tỏi, 1 muỗng cà phê rượu trắng, 1/2 muỗng cà phê hạt tiêu trong khoảng 15 phút.', 10);
INSERT INTO public.recipe_steps VALUES (3055, '2025-11-20 17:11:12.275397', '2025-11-20 17:11:12.275397', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 489, 5, 'Đun nóng dầu thực vật trong chảo sâu lòng (lượng dầu đủ chiên ngập tôm). Nhúng thử đầu đũa, nếu thấy sủi bọt ở đầu đũa là dầu đạt nhiệt độ.', 10);
INSERT INTO public.recipe_steps VALUES (3056, '2025-11-20 17:11:12.276955', '2025-11-20 17:11:12.276955', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 489, 8, 'Vớt tôm ra cho vào giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (3057, '2025-11-20 17:11:12.27866', '2025-11-20 17:11:12.27866', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 489, 9, 'd) Cách xóc tôm với sốt bơ tỏi:Trong một chảo khác, bạn cho thêm một chút dầu ăn phi thơm tỏi. Khi tỏi chuyển màu hơi vàng, thêm bơ nhạt, quấy đều cho bơ tan chảy.', 10);
INSERT INTO public.recipe_steps VALUES (3058, '2025-11-20 17:11:12.280802', '2025-11-20 17:11:12.280802', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 489, 7, 'Sau khi chiên xong lần một, vớt hết các lớp bột còn dư, tăng nhiệt độ dầu trong chảo để chiên nhanh lần 2 nhằm giúp tôm giòn và thoát dầu. Thời gian chiên nhanh lần 2 chỉ trong 15-20 giây.', 10);
INSERT INTO public.recipe_steps VALUES (3059, '2025-11-20 17:11:12.812231', '2025-11-20 17:11:12.812231', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 490, 1, 'a) Làm hạt điều:Bắc chảo lên bếp, thêm bơ vào cho tới khi tan chảy hết thì cho hạt điều vào, đảo đều để bơ bám đều vào hạt. Múc riêng để ra bát.', 10);
INSERT INTO public.recipe_steps VALUES (3060, '2025-11-20 17:11:12.813834', '2025-11-20 17:11:12.813834', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 490, 6, 'Trong một chảo sâu lòng, cho dầu vào đun nóng. Khi cho đũa vào thử thấy sủi tăm ở đầu đũa là dầu đạt độ nóng. Lần lượt lấy từng con tôm nhúng vào phần bột năng để bột ướt bám đều bề mặt, rồi nhanh chóng cho vào chảo dầu nóng. Bạn nên chia ra từng mẻ nhỏ để các con tôm đỡ dính nhau. Chiên vàng giòn đều, khoảng 2 phút mỗi mặt. Nếu muốn giòn hơn thì nên chiên 2 lần.', 10);
INSERT INTO public.recipe_steps VALUES (3061, '2025-11-20 17:11:12.815434', '2025-11-20 17:11:12.815434', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 490, 2, 'Cho đường và nước vào nồi, đun sôi. Khuấy đều cho đến khi vàng sánh dẻo lại. Thêm hạt điều và nhẹ nhàng đảo đều để đường bám các mặt. Lấy hạt điều ra để lên giấy nến cho đỡ dính.', 10);
INSERT INTO public.recipe_steps VALUES (3062, '2025-11-20 17:11:12.817069', '2025-11-20 17:11:12.817069', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 490, 8, 'Trong một bát lớn, cho tôm vào rồi rưới sốt mật ong lên trên đảo đều, thêm hạt điều, rắc mè rang lên và thưởng thức!', 10);
INSERT INTO public.recipe_steps VALUES (3063, '2025-11-20 17:11:12.818805', '2025-11-20 17:11:12.818805', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 490, 3, 'Làm sốt kem mật ong: Trong một cái bát nhỏ, đánh đều sốt mayonnaise, mật ong, sữa chua nguyên chất/hoặc sữa đặc tùy khẩu vị mỗi người, nước cốt chanh cho tới khi thành hỗn hợp mịn.', 10);
INSERT INTO public.recipe_steps VALUES (3064, '2025-11-20 17:11:12.820379', '2025-11-20 17:11:12.820379', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 490, 7, 'Vớt tôm ra để lên giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (3065, '2025-11-20 17:11:12.822019', '2025-11-20 17:11:12.822019', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 490, 4, 'b) Làm tôm sốt mật ong:Tôm làm sạch, bóc vỏ, rút chỉ lưng đen, thấm khô rồi ướp với muối, hạt nêm, hạt tiêu trong 5-6 phút cho ngấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (3066, '2025-11-20 17:11:12.823607', '2025-11-20 17:11:12.823607', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 490, 5, 'Trong một bát khác, đánh bông trứng lên rồi cho bột năng, bột nở vào đánh đều cho tới khi sánh đặc.', 10);
INSERT INTO public.recipe_steps VALUES (3067, '2025-11-20 17:11:13.36669', '2025-11-20 17:11:13.36669', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 491, 4, 'Đun nóng dầu thực vật trong nồi rồi phi thơm hành tím, tỏi. Tiếp đến, cho thịt lợn vào xào trên lửa vừa. Sau đó, cho tất cả nước xốt ướp cùng nước dừa và thịt cùi dừa vào nồi, đậy vung và đun sôi, hớt bỏ vàng. Hạ nhỏ lửa và đun trong tầm nửa giờ.', 10);
INSERT INTO public.recipe_steps VALUES (3298, '2025-11-20 17:11:25.897872', '2025-11-20 17:11:25.897872', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 532, 4, 'Phần nghêu đã tách xong, xếp ra đĩa cho mỗi con nghêu khoảng 1/2 muỗng cà phê xốt dầu hào, tiếp cho hành lá và ớt lên.', 10);
INSERT INTO public.recipe_steps VALUES (3068, '2025-11-20 17:11:13.368282', '2025-11-20 17:11:13.368282', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 491, 1, 'Thịt ba chỉ cạo sạch lông, rửa sạch. Đun sôi nồi nước cùng chút muối, gừng đập dập rồi cho thịt vào chần qua, vớt ra rửa sạch để khử mùi. Sau đó, cắt miếng vuông vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (3069, '2025-11-20 17:11:13.369879', '2025-11-20 17:11:13.369879', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 491, 3, 'Cùi dừa cạo bỏ phần vỏ nâu bên ngoài, rửa sạch và thái miếng dài vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (3070, '2025-11-20 17:11:13.371589', '2025-11-20 17:11:13.371589', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 491, 2, 'Ướp thịt với một nửa hành, tỏi băm cùng nước mắm, hạt tiêu, hạt nêm, nước màu (nước hàng) để trong tủ lạnh tối thiểu 30 phút cho thấm gia vị hoặc lâu hơn càng tốt.', 10);
INSERT INTO public.recipe_steps VALUES (3071, '2025-11-20 17:11:13.373193', '2025-11-20 17:11:13.373193', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 491, 6, 'Múc thịt kho ra bát và rắc thêm tiêu đen, hành lá, ớt lên trên.', 10);
INSERT INTO public.recipe_steps VALUES (3072, '2025-11-20 17:11:13.374765', '2025-11-20 17:11:13.374765', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 491, 5, 'Sau khi thịt kho đã ngấm gia vị, thêm trứng luộc đã bóc vỏ vào, nêm nếm lại gia vị theo khẩu vị gia đình. Tiếp tục đun nhỏ lửa cho tới khi thịt mềm, nước rút bớt tầm một nửa.', 10);
INSERT INTO public.recipe_steps VALUES (3073, '2025-11-20 17:11:13.667273', '2025-11-20 17:11:13.667273', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 492, 2, 'Thịt lợn rửa sạch, xay nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3074, '2025-11-20 17:11:13.668875', '2025-11-20 17:11:13.668875', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 492, 6, 'Mộc nhĩ, miến ngâm nước, rửa sạch, thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3075, '2025-11-20 17:11:13.671042', '2025-11-20 17:11:13.671042', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 492, 7, 'Bước 2: Làm nhân', 10);
INSERT INTO public.recipe_steps VALUES (3076, '2025-11-20 17:11:13.672648', '2025-11-20 17:11:13.672648', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 492, 10, 'Cho hỗn hợp thấm và hòa quyện khoảng 15-20 phút trước khi cuốn để khi ăn có vị đậm đà hơn.', 10);
INSERT INTO public.recipe_steps VALUES (3077, '2025-11-20 17:11:13.674277', '2025-11-20 17:11:13.674277', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 492, 3, 'Tôm bóc vỏ, bỏ đầu và băm nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3078, '2025-11-20 17:11:13.675872', '2025-11-20 17:11:13.675872', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 492, 11, 'Bước 3: Cuốn', 10);
INSERT INTO public.recipe_steps VALUES (3079, '2025-11-20 17:11:13.677469', '2025-11-20 17:11:13.677469', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 492, 5, 'Khoai môn, cà rốt thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3080, '2025-11-20 17:11:13.679052', '2025-11-20 17:11:13.679052', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 492, 13, 'Cứ thế từng bước cuốn cho hết nhân.', 10);
INSERT INTO public.recipe_steps VALUES (3081, '2025-11-20 17:11:13.680668', '2025-11-20 17:11:13.680668', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 492, 15, 'Bắc chảo lên bếp, đổ dầu và đun nóng. Khi dầu sôi hạ lửa vừa. Cho chả giò vào chiên đều. Chả giò khi chiên xong có màu vàng ruộm, giòn, nhân quyện đều. Cho ra đĩa, trang trí thêm cà chua cắt lát, rau xanh cho bắt mắt. Món này có thể dùng kèm tương ớt hoặc nước chấm pha chua ngọt cay.', 10);
INSERT INTO public.recipe_steps VALUES (3082, '2025-11-20 17:11:13.682222', '2025-11-20 17:11:13.682222', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 492, 14, 'Bước 4: Chiên', 10);
INSERT INTO public.recipe_steps VALUES (3083, '2025-11-20 17:11:13.683845', '2025-11-20 17:11:13.683845', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 492, 1, 'Bước 1: Sơ chế', 10);
INSERT INTO public.recipe_steps VALUES (3084, '2025-11-20 17:11:13.685523', '2025-11-20 17:11:13.685523', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 492, 9, 'Thêm bột nêm, hạt tiêu, nước mắm và đập 2 quả trứng vào đảo đều.', 10);
INSERT INTO public.recipe_steps VALUES (3085, '2025-11-20 17:11:13.687332', '2025-11-20 17:11:13.687332', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 492, 8, 'Tất cả nguyên liệu đã sơ chế cho vào thố to, trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (3086, '2025-11-20 17:11:13.688926', '2025-11-20 17:11:13.688926', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 492, 12, 'Đặt bánh tráng rế xuống mâm hoặc một mặt phẳng, múc thìa nhân, trải đều vào giữa của bánh tráng, gấp đều 2 mép, cuộn kín lại. Chú ý không cuộn quá chặt tay dễ khiến chả giò bị khô và khi rán dễ bị vỡ.', 10);
INSERT INTO public.recipe_steps VALUES (3087, '2025-11-20 17:11:13.690542', '2025-11-20 17:11:13.690542', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 492, 4, 'Hành băm nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3088, '2025-11-20 17:11:13.830521', '2025-11-20 17:11:13.830521', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 493, 3, 'Bật bếp cho chảo nóng. Cho 700ml dầu ăn vào đun sôi.', 10);
INSERT INTO public.recipe_steps VALUES (3089, '2025-11-20 17:11:13.831761', '2025-11-20 17:11:13.831761', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 493, 4, 'Cho tỏi vào đảo đến khi thấy hơi vàng thì cho hành tím vào cùng.', 10);
INSERT INTO public.recipe_steps VALUES (3090, '2025-11-20 17:11:13.833464', '2025-11-20 17:11:13.833464', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 493, 5, 'Khi hỗn hợp tỏi và hành bắt đầu hơi khô và chuyển sang màu vàng, tiếp tục cho sả vào.', 10);
INSERT INTO public.recipe_steps VALUES (3091, '2025-11-20 17:11:13.835064', '2025-11-20 17:11:13.835064', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 493, 1, 'Đầu tiên, cho 100ml dầu ăn vào chảo đun. Đến lúc dầu sôi cho 1,5 muỗng canh hạt điều màu vào. Đun cho tới khi dầu màu điều đỏ đẹp, hạt điều chuyển sang ngả màu thì dùng rây lọc lấy phần dầu màu điều (bỏ hạt).', 10);
INSERT INTO public.recipe_steps VALUES (3092, '2025-11-20 17:11:13.836138', '2025-11-20 17:11:13.836138', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 493, 6, 'Cuối cùng cho phần ớt còn lại vào đảo cho tới khi hỗn hợp lên màu hơi đỏ và ớt bắt đầu khô.', 10);
INSERT INTO public.recipe_steps VALUES (3093, '2025-11-20 17:11:13.838242', '2025-11-20 17:11:13.838242', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 493, 2, 'Sả, ớt, tỏi, hành tím rửa sạch và xay nhuyễn (độ nhuyễn theo ý muốn)', 10);
INSERT INTO public.recipe_steps VALUES (3094, '2025-11-20 17:11:13.839297', '2025-11-20 17:11:13.839297', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 493, 7, 'Bây giờ cho 3 muỗng canh đường + 1,5 muỗng canh muối + 1 muỗng canh bột ngọt và dầu màu điều thu được ở lúc đầu vào. Tiếp tục đảo hỗn hợp thêm 5 phút nữa là đã hoàn thành.', 10);
INSERT INTO public.recipe_steps VALUES (3095, '2025-11-20 17:11:14.027011', '2025-11-20 17:11:14.027011', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 494, 2, 'Tẩm ướp
INSERT INTO public.recipe_steps VALUES (3096, '2025-11-20 17:11:14.028137', '2025-11-20 17:11:14.028137', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 494, 3, 'Hấp cá
INSERT INTO public.recipe_steps VALUES (3097, '2025-11-20 17:11:14.029742', '2025-11-20 17:11:14.029742', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 494, 4, 'Yêu cầu thành phẩm
INSERT INTO public.recipe_steps VALUES (3219, '2025-11-20 17:11:20.312144', '2025-11-20 17:11:20.312144', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 518, 1, 'Thịt gà luộc vừa chín tới mọng nước. Lọc phần thịt còn liền da thái sợi nhỏ như sợi bún, phần lườn xé nhỏ như sợi chỉ trắng. Phần xương gà giữ lại làm nước dùng.', 10);
INSERT INTO public.recipe_steps VALUES (3299, '2025-11-20 17:11:25.8995', '2025-11-20 17:11:25.8995', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 532, 2, 'Bỏ hành tây xắt hột lựu vào phi cho vàng, sau đó cho dầu hào vào, nêm lại cho vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (3098, '2025-11-20 17:11:14.031331', '2025-11-20 17:11:14.031331', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 494, 1, 'Sơ chế
INSERT INTO public.recipe_steps VALUES (3099, '2025-11-20 17:11:14.248078', '2025-11-20 17:11:14.248078', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 495, 9, 'Sau khi om vịt khoảng 15-20 phút thì thêm khoai sọ, sấu vào và hầm tiếp ở lửa nhỏ cho tới khi khoai sọ chín.', 10);
INSERT INTO public.recipe_steps VALUES (3100, '2025-11-20 17:11:14.249673', '2025-11-20 17:11:14.249673', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 495, 10, 'Sấu chín, vớt ra, dằm nhuyễn, thêm chút nước và trút lại vào nồi, điều chỉnh độ chua theo khẩu vị gia đình.', 10);
INSERT INTO public.recipe_steps VALUES (3101, '2025-11-20 17:11:14.251796', '2025-11-20 17:11:14.251796', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 495, 2, 'Chặt vịt thành các miếng to.', 10);
INSERT INTO public.recipe_steps VALUES (3102, '2025-11-20 17:11:14.253398', '2025-11-20 17:11:14.253398', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 495, 1, 'Vịt làm sạch, nhổ hết lông, cắt bỏ phao câu. Dùng muối hạt cùng với chanh hoặc rượu trắng chà xát khắp mặt da và rửa sạch để khử mùi hôi.', 10);
INSERT INTO public.recipe_steps VALUES (3103, '2025-11-20 17:11:14.254473', '2025-11-20 17:11:14.254473', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 495, 3, 'Ướp thịt vịt: 2 thìa canh sả băm, 1 thìa canh tỏi băm, 2 thìa canh nước mắm, 1 thìa cà phê muối, 1 thìa cà phê hạt tiêu, 1 thìa cà phê hạt nêm và chút dầu ăn để vịt đỡ khô. Ướp tối thiểu trong 15-20 phút.', 10);
INSERT INTO public.recipe_steps VALUES (3104, '2025-11-20 17:11:14.256068', '2025-11-20 17:11:14.256068', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 495, 7, 'Cho dầu ăn vào nồi, phi thơm sả tỏi, cho thịt vịt vào xào săn lại. Mục đích để gia vị rút, ngấm vào thịt đậm đà hơn.', 10);
INSERT INTO public.recipe_steps VALUES (3105, '2025-11-20 17:11:14.257656', '2025-11-20 17:11:14.257656', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 495, 11, 'Khi vịt mềm, nêm nếm lại gia vị, rắc thêm rau thơm và tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (3106, '2025-11-20 17:11:14.258721', '2025-11-20 17:11:14.258721', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 495, 5, 'Khoai sọ gọt bỏ vỏ, bổ đôi hoặc cắt miếng quân cờ vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (3107, '2025-11-20 17:11:14.26032', '2025-11-20 17:11:14.26032', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 495, 6, 'Các loại rau ăn kèm (tùy chọn theo sở thích) như rau rút, rau muống, nấm rơm nhặt rửa sạch, vẩy ráo.', 10);
INSERT INTO public.recipe_steps VALUES (3108, '2025-11-20 17:11:14.261906', '2025-11-20 17:11:14.261906', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 495, 8, 'Khi thịt vịt săn lại và dậy mùi thơm thì thêm nước dừa tươi, nước lạnh đủ dùng vào nồi và đun sôi, hạ nhỏ lửa, hớt bỏ bọt.', 10);
INSERT INTO public.recipe_steps VALUES (3109, '2025-11-20 17:11:14.263569', '2025-11-20 17:11:14.263569', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 495, 4, 'Rau thơm các loại (hành lá, rau mùi tàu, rau ngổ) nhặt và rửa sạch, thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3110, '2025-11-20 17:11:14.489401', '2025-11-20 17:11:14.489401', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 496, 3, 'Yêu cầu thành phẩm
INSERT INTO public.recipe_steps VALUES (3111, '2025-11-20 17:11:14.490472', '2025-11-20 17:11:14.490472', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 496, 1, 'Sơ chế, chuẩn bị
INSERT INTO public.recipe_steps VALUES (3112, '2025-11-20 17:11:14.49205', '2025-11-20 17:11:14.49205', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 496, 2, 'Chế biến
INSERT INTO public.recipe_steps VALUES (3113, '2025-11-20 17:11:14.679173', '2025-11-20 17:11:14.679173', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 497, 2, 'Nướng sườn
INSERT INTO public.recipe_steps VALUES (3114, '2025-11-20 17:11:14.680236', '2025-11-20 17:11:14.680236', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 497, 3, 'Yêu cầu thành phẩm
INSERT INTO public.recipe_steps VALUES (3127, '2025-11-20 17:11:15.403235', '2025-11-20 17:11:15.403235', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 500, 2, 'Chế biến
INSERT INTO public.recipe_steps VALUES (3300, '2025-11-20 17:11:25.90167', '2025-11-20 17:11:25.90167', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 532, 5, 'Bao đĩa nghêu lại bằng giấy kiếng, hấp trong lò vi sóng khoảng 2 phút.', 10);
INSERT INTO public.recipe_steps VALUES (3115, '2025-11-20 17:11:14.681828', '2025-11-20 17:11:14.681828', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 497, 1, 'a. Sơ chế
INSERT INTO public.recipe_steps VALUES (3116, '2025-11-20 17:11:14.938899', '2025-11-20 17:11:14.938899', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 498, 1, 'Sữa hâm hơi ấm cho vào âu lớn, thêm men bánh mì, trứng, đường đánh tan rồi cho bột mì, bơ để nhiệt độ phòng và muối vào trộn đều. Sau đó, nhồi bột cho tới khi bột quyện thành khối mịn dẻo.', 10);
INSERT INTO public.recipe_steps VALUES (3117, '2025-11-20 17:11:14.940519', '2025-11-20 17:11:14.940519', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 498, 3, 'Lần lượt lấy từng phần bột cán hình dài (nhớ bọc kín phần bột còn lại tránh bị khô). Chú ý chiều rộng phần bột cán bằng chiều dài của xúc xích. Cắt hình dọc dài như khung cửa sổ dọc giữa phần bột, miết nhẹ hai đầu. Rồi cho xúc xích vào cuộn tròn. Làm lần lượt cho tới hết. Bạn có thể tạo hình tùy thích.', 10);
INSERT INTO public.recipe_steps VALUES (3118, '2025-11-20 17:11:14.942126', '2025-11-20 17:11:14.942126', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 498, 5, 'Trước khi nướng, đánh tan 1 lòng đỏ trứng gà và 1,5 - 2 thìa canh sữa tươi không đường rồi quét nhẹ lên bề mặt bánh mì, rắc chút mè (vừng) lên trên. Làm nóng lò nướng trước 10 phút ở 180 độ C. Cho khay bánh mì vào ngăn giữa lò để nướng. Sau 18 - 20 phút bánh nở, vàng ươm mặt là đã chín. Tắt lò, lấy bánh ra, thoa chút bơ lên bề mặt cho bóng đẹp.', 10);
INSERT INTO public.recipe_steps VALUES (3119, '2025-11-20 17:11:14.943743', '2025-11-20 17:11:14.943743', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 498, 6, 'Vỏ bánh mềm mịn, vàng ươm, thơm mùi bơ và vừng, xúc xích thơm ngon. Món một ăn ngon cho các bạn nhỏ vào buổi sáng hoặc bữa xế sau các giờ học online.', 10);
INSERT INTO public.recipe_steps VALUES (3120, '2025-11-20 17:11:14.945912', '2025-11-20 17:11:14.945912', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 498, 2, 'Dùng màng bọc thực phẩm bọc và ủ bột trong khoảng 1 giờ cho tới khi bột nở gấp đôi. Lấy phần bột ra làm xẹp bọt khí, nhồi lại lần nữa và chia bột phần 6 - 8 phần bằng nhau.', 10);
INSERT INTO public.recipe_steps VALUES (3121, '2025-11-20 17:11:14.947496', '2025-11-20 17:11:14.947496', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 498, 4, 'Đặt bánh mì cuộn xúc xích lên giấy nến, đặt vào khay, phủ khăn và ủ trong 30 phút để bánh nở.', 10);
INSERT INTO public.recipe_steps VALUES (3122, '2025-11-20 17:11:15.171978', '2025-11-20 17:11:15.171978', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 499, 2, 'Làm nước dùng lẩu
INSERT INTO public.recipe_steps VALUES (3123, '2025-11-20 17:11:15.173558', '2025-11-20 17:11:15.173558', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 499, 4, 'Yêu cầu thành phẩm
INSERT INTO public.recipe_steps VALUES (3124, '2025-11-20 17:11:15.17565', '2025-11-20 17:11:15.17565', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 499, 1, 'Sơ chế nguyên liệu
INSERT INTO public.recipe_steps VALUES (3125, '2025-11-20 17:11:15.177208', '2025-11-20 17:11:15.177208', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 499, 3, 'Nhúng lẩu
INSERT INTO public.recipe_steps VALUES (3126, '2025-11-20 17:11:15.399558', '2025-11-20 17:11:15.399558', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 500, 3, 'Yêu cầu thành phẩm
INSERT INTO public.recipe_steps VALUES (3167, '2025-11-20 17:11:16.482494', '2025-11-20 17:11:16.482494', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 507, 1, 'Tỏi một nửa thái lát, một nửa băm nhỏ. Sả một nửa thái lát mỏng, một nửa cắt khúc, đập dập để tước sợi nhỏ cho dễ. Ớt tươi bỏ hạt băm nhuyễn, gừng thái sợi. Tắc bỏ hạt vắt lấy nước cốt.', 10);
INSERT INTO public.recipe_steps VALUES (3258, '2025-11-20 17:11:23.067462', '2025-11-20 17:11:23.067462', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 526, 9, 'Nha đam gọt vỏ cắt miếng vừa ăn, trụng chín. Cần cắt khúc vừa ăn, hành tây cắt khoang, ớt đỏ cát sợ, tôm cắt hạt lựu xào chín với gia vị. Nghêu luộc chín pha muối, đường, nước cốt quất sao cho vừa ăn. Trộn đều với nguyên liệu dọn ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (3128, '2025-11-20 17:11:15.405867', '2025-11-20 17:11:15.405867', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 500, 1, 'Sơ chế và chuẩn bị
INSERT INTO public.recipe_steps VALUES (3129, '2025-11-20 17:11:15.490372', '2025-11-20 17:11:15.490372', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 501, 1, 'Cá làm sạch, chà xát muối hạt và chanh rửa sạch khử mùi tanh, để ráo. Sau đó, ướp cá với gừng, 1/2 lượng hành khô băm nhỏ cùng 1 thìa canh nước mắm, 1 thìa cà phê muối, 1/2 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu. Ướp 30 phút cho cá ngấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (3130, '2025-11-20 17:11:15.491373', '2025-11-20 17:11:15.491373', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 501, 2, 'Su hào gọt vỏ, thái con chì. Cà chua thái múi cau. Các rau gia vị (hành lá, thì là, mùi tàu) rửa sạch, thái khúc.', 10);
INSERT INTO public.recipe_steps VALUES (3131, '2025-11-20 17:11:15.493738', '2025-11-20 17:11:15.493738', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 501, 6, 'Hạ lửa vừa rồi cho cá vào. Nêm nếm mắm, muối, hạt nêm vừa miệng. Nấu cho tới khi su hào mềm cũng là lúc cá chín ngọt. Thêm rau gia vị (hành lá, thì là, rau mùi tàu) vào, đảo đều, tắt bếp và múc ra bát tô rắc chút hạt tiêu, thêm vài lát ớt và thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (3132, '2025-11-20 17:11:15.495816', '2025-11-20 17:11:15.495816', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 501, 7, 'Yêu cầu thành phẩm: Canh cá nóng hổi, thịt cá mềm thơm, su hào ngọt, nước canh thanh nhẹ, điểm xuyết màu đỏ từ cà chua rất hấp dẫn. Món ăn này rất hợp vào mùa đông khi su hào vào vụ.', 10);
INSERT INTO public.recipe_steps VALUES (3133, '2025-11-20 17:11:15.496817', '2025-11-20 17:11:15.496817', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 501, 3, 'Làm nóng dầu ăn, gạt bỏ phần hành gừng băm nhỏ trên cá ướp, rồi đem chiên sơ cá cho thơm và săn lại.', 10);
INSERT INTO public.recipe_steps VALUES (3134, '2025-11-20 17:11:15.497913', '2025-11-20 17:11:15.497913', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 501, 4, 'Phi thơm 1/2 lượng hành khô còn lại, cho 1/2 lượng cà chua vào xào tạo màu. Sau đó, cho su hào vào xào khoảng 2 - 3 phút, nêm chút muối, nước mắm.', 10);
INSERT INTO public.recipe_steps VALUES (3135, '2025-11-20 17:11:15.499215', '2025-11-20 17:11:15.499215', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 501, 5, 'Trút phần cà chua và su hào đã xào vào nồi, cho 1/2 lượng cà chua bổ múi cau còn lại vào. Đổ lượng nước lọc phù hợp và bật bếp đun sôi 2 - 3 phút.', 10);
INSERT INTO public.recipe_steps VALUES (3136, '2025-11-20 17:11:15.71706', '2025-11-20 17:11:15.71706', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 502, 7, 'Cho bắp cải vào sốt cà chua, đun lửa nhỏ vừa cho tới khi sốt sánh lại, quyện đều các mặt bắp cải là được. Nêm nếm lại mắm, muối, hạt nêm theo khẩu vị. Tắt bếp, múc ra rắc hạt tiêu, hành lá và ăn nóng cùng cơm trắng rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (3137, '2025-11-20 17:11:15.718668', '2025-11-20 17:11:15.718668', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 502, 2, 'Hành khô băm nhỏ, hành lá phần còn lại thái nhỏ. Cho thịt nạc vai xay vào tô, thêm hành lá thái nhỏ, 1/2 hành khô băm nhỏ cùng 2 thìa cà phê nước mắm, 1 thìa cà phê bột canh (muối), 1 thìa cà phê hạt nêm, 1 thìa cà phê hạt tiêu, 1 thìa canh dầu ăn hoặc dầu hành, trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (3138, '2025-11-20 17:11:15.720868', '2025-11-20 17:11:15.720868', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 502, 6, 'Phi thơm số hành khô băm nhỏ còn lại, cho cà chua vào, thêm chút mắm muối cho nhanh mềm.', 10);
INSERT INTO public.recipe_steps VALUES (3139, '2025-11-20 17:11:15.722477', '2025-11-20 17:11:15.722477', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 502, 1, 'Chần mềm lá bắp cải có 2 cách. Cách 1: Dùng dao nhỏ, nhọn khoét bỏ lõi cứng bắp cải, cho vào nồi nước sôi cùng chút muối hạt, vài lát gừng, chần 3 - 4 phút, vớt ra ngâm nước lạnh, tách lấy lá. Cách 2: Khéo léo tách riêng từng lá rồi cho vào chần. Sau khi chần, bạn nhớ cắt bỏ phần cuống cứng trên lá. Hành lá chia làm 2 phần, một phần chần nhanh, cho vào nước lạnh, vớt ra để ráo dùng để buộc.', 10);
INSERT INTO public.recipe_steps VALUES (3140, '2025-11-20 17:11:15.724579', '2025-11-20 17:11:15.724579', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 502, 3, 'Cà chua khía hình chữ thập, cho vào nước sôi trụng 1-2 phút, tách bỏ vỏ, băm nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (3141, '2025-11-20 17:11:15.726171', '2025-11-20 17:11:15.726171', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 502, 4, 'Gói bắp cải cuốn thịt: Trải từng lá bắp cải lên mặt phẳng, múc nhân thịt cho vào giữa, rồi gập và cuốn như cuốn nem rán, cuối cùng dùng hành lá chần buộc lại. Làm lần lượt cho tới hết.', 10);
INSERT INTO public.recipe_steps VALUES (3142, '2025-11-20 17:11:15.727882', '2025-11-20 17:11:15.727882', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 502, 5, 'Cho bắp cải vào nồi hấp khoảng 15-20 phút cho chín. Hoặc bạn có thể đem chiên (rán), hoặc bỏ vào lò nướng như cách của người Pháp. Gắp ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (3143, '2025-11-20 17:11:15.728936', '2025-11-20 17:11:15.728936', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 502, 8, 'Yêu cầu thành phẩm: Bắp cải mềm ngọt, thịt đậm đà, cà chua sánh đỏ quyện lại tạo nên món ăn bổ dưỡng ngày đông.', 10);
INSERT INTO public.recipe_steps VALUES (3144, '2025-11-20 17:11:15.863822', '2025-11-20 17:11:15.863822', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 503, 4, 'Múc chè xoài ra bát, thêm dừa tươi nạo sợi, trang trí thêm phần xoài còn dư, rưới nước cốt dừa và thưởng thức. Món chè này thưởng thức nóng và lạnh đều ngon. Nếu muốn lạnh thì bạn để nguội chè rồi cho vào ngăn mát.', 10);
INSERT INTO public.recipe_steps VALUES (3145, '2025-11-20 17:11:15.865427', '2025-11-20 17:11:15.865427', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 503, 2, 'Cho 120 gr đường cát vào hỗn hợp xoài đã xay mịn, cho lên bếp khuấy đều cho đường tan. Thêm 1/4 thìa cà phê muối để tạo vị đậm hơn.', 10);
INSERT INTO public.recipe_steps VALUES (3146, '2025-11-20 17:11:15.867568', '2025-11-20 17:11:15.867568', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 503, 3, 'Hòa tan 30 gr bột năng với chút nước rồi từ từ cho vào nồi xoài. Vừa cho bột năng vừa khuấy đều cho tới khi đạt độ sánh như mong muốn. Hạ lửa nhỏ và nấu cho bột năng chín kỹ để tránh bị vữa.', 10);
INSERT INTO public.recipe_steps VALUES (3147, '2025-11-20 17:11:15.869182', '2025-11-20 17:11:15.869182', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 503, 1, 'Xoài gọt vỏ, lấy thịt xoài đem xay nhuyễn cùng 1 - 1,2 lít nước. Giữ lại một ít để trang trí.', 10);
INSERT INTO public.recipe_steps VALUES (3216, '2025-11-20 17:11:19.708177', '2025-11-20 17:11:19.708177', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 517, 3, 'Yêu cầu thành phẩm
INSERT INTO public.recipe_steps VALUES (3301, '2025-11-20 17:11:25.903324', '2025-11-20 17:11:25.903324', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 532, 6, 'Món này phải ăn nóng mới ngon.', 10);
INSERT INTO public.recipe_steps VALUES (3148, '2025-11-20 17:11:16.014712', '2025-11-20 17:11:16.014712', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 504, 2, 'Chế biến:
INSERT INTO public.recipe_steps VALUES (3149, '2025-11-20 17:11:16.016981', '2025-11-20 17:11:16.016981', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 504, 3, 'Yêu cầu thành phẩm
INSERT INTO public.recipe_steps VALUES (3150, '2025-11-20 17:11:16.018583', '2025-11-20 17:11:16.018583', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 504, 1, 'Sơ chế:
INSERT INTO public.recipe_steps VALUES (3151, '2025-11-20 17:11:16.186981', '2025-11-20 17:11:16.186981', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 505, 3, 'Gạo nếp vo sạch, ngâm qua đêm, vớt để ráo nước, xóc đều cùng 1 thìa cà phê muối. Cho sắn vào gạo, đảo nhẹ đều.', 10);
INSERT INTO public.recipe_steps VALUES (3152, '2025-11-20 17:11:16.188572', '2025-11-20 17:11:16.188572', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 505, 1, 'Trình bày và thưởng thức:Múc xôi ra bát, thêm mỡ hành, hành khô và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (3153, '2025-11-20 17:11:16.19026', '2025-11-20 17:11:16.19026', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 505, 2, 'Sắn lột bỏ vỏ, rửa sạch, bổ đôi bỏ phần xơ, cắt thành miếng vuông vừa ăn. Ngâm sắn trong nước muối loãng hoặc nước vo gạo 3-4 tiếng cho bớt độc tố.', 10);
INSERT INTO public.recipe_steps VALUES (3154, '2025-11-20 17:11:16.191852', '2025-11-20 17:11:16.191852', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 505, 5, 'Hành lá rửa sạch, thái nhỏ, cho 2-3 thìa canh mỡ lợn (nếu có thêm tóp mỡ càng hấp dẫn), chút muối đảo đều cho vào lò vi sóng quay 20 giây là có mỡ hành.', 10);
INSERT INTO public.recipe_steps VALUES (3155, '2025-11-20 17:11:16.194006', '2025-11-20 17:11:16.194006', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 505, 4, 'Có 2 cách làm xôi sắn: Nếu ít thời gian thì bạn cho gạo và sắn vào nồi cơm điện, thêm nước hơi xâm xấp bề mặt (không nhiều quá sẽ bị nhão) và bật chế độ như nấu cơm bình thường, thêm lá dứa nếu thích mùi thơm hơn.Khi nồi bật thì xới nhẹ rồi ấn lại lần nữa, khi sắn chín mềm, xôi căng mẩy là đạt. Nếu có nhiều thời gian thì đồ bằng chõ sẽ ngon hơn.Chú ý cho lượng nước bằng 1/2 dung tích nồi, lót tấm vải màn vào chõ, múc từng ít gạo cho vào dàn đều, nên đun nước sôi rồi hạ nhiệt và cho xôi vào đồ để giữ ổn định nhiệt. Đồ xôi trong khoảng 35-40 phút là chín. Rưới thêm 1 thìa canh mỡ gà trộn đều giúp hạt xôi căng mẩy, dẻo mềm.', 10);
INSERT INTO public.recipe_steps VALUES (3156, '2025-11-20 17:11:16.332568', '2025-11-20 17:11:16.332568', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 506, 5, 'Yêu cầu thành phẩm: Hạt cơm vàng tơi, bên ngoài săn nhưng bên trong dẻo mềm, tóp mỡ giòn giòn béo ngậy, dưa cải chua vừa vị rất hấp dẫn. Món ăn này nguyên liệu và cách làm nhanh gọn, thích hợp cho bữa sáng ngày đông lạnh giá.', 10);
INSERT INTO public.recipe_steps VALUES (3157, '2025-11-20 17:11:16.334584', '2025-11-20 17:11:16.334584', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 506, 2, 'Trước khi chiên, ướp cơm với 2 thìa cà phê nước mắm, 1 thìa cà phê muối, 1 thìa cà phê hạt nêm, 1 thìa cà phê hạt tiêu, 1-2 quả trứng, đeo găng tay bóp đều để hạt cơm tơi ra. Việc ướp vừa giúp cơm thấm vị, vừa giúp khi chiên hạt cơm tơi ra và lên màu vàng đẹp mắt.', 10);
INSERT INTO public.recipe_steps VALUES (3158, '2025-11-20 17:11:16.335649', '2025-11-20 17:11:16.335649', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 506, 3, 'Dưa cải chua rửa bớt nước chua, vắt ráo, cắt miếng vừa ăn. Phi thơm mỡ lợn với ít hành khô, cho dưa cải vào xào chín, nêm nếm gia vị vừa miệng.', 10);
INSERT INTO public.recipe_steps VALUES (3159, '2025-11-20 17:11:16.337194', '2025-11-20 17:11:16.337194', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 506, 4, 'Rang cơm: Phi thơm hành khô với chút mỡ lợn cho dậy mùi thơm, cho cơm vào rang trên lửa vừa. Đảo liên tục để hạt cơm tơi. Khi hạt cơm săn lại, thì cho dưa chua đã xào, tóp mỡ vào đảo đều, nêm nếm mắm, muối, hạt nêm theo khẩu vị. Thêm hành lá cắt nhỏ nếu thích, đảo đều và tắt bếp, múc ra bát.', 10);
INSERT INTO public.recipe_steps VALUES (3160, '2025-11-20 17:11:16.339349', '2025-11-20 17:11:16.339349', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 506, 1, 'Cơm nguội đánh tơi đều, bọc màng bọc thực phẩm cho vào ngăn mát tủ lạnh cho hạt cơm săn lại, khi chiên sẽ ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (3161, '2025-11-20 17:11:16.471098', '2025-11-20 17:11:16.471098', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 507, 7, 'Đổ nước sốt Thái ở trên vào trộn đều, cho vào ngăn mát tủ lạnh qua đêm sẽ ăn được, còn nếu để một ngày sau sẽ đậm vị quyện vào ngon hơn. Bảo quản trong ngăn mát tủ lạnh được 1 tuần.', 10);
INSERT INTO public.recipe_steps VALUES (3162, '2025-11-20 17:11:16.474017', '2025-11-20 17:11:16.474017', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 507, 5, 'Cóc non và xoài xanh rửa sạch, cắt khoanh hoặc miếng vuông vừa ăn. Sau đó, ngâm vào nước sôi để nguội pha chút muối loãng, vớt ra, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (3163, '2025-11-20 17:11:16.47561', '2025-11-20 17:11:16.47561', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 507, 6, 'Xếp chân gà và cóc, xoài xanh xen kẽ cùng sả tước sợi vào hộp hoặc lọ thủy tinh.', 10);
INSERT INTO public.recipe_steps VALUES (3164, '2025-11-20 17:11:16.477747', '2025-11-20 17:11:16.477747', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 507, 3, 'Chân gà làm sạch, cho vào ngâm nước muối loãng và vắt thêm quả chanh (hoặc giấm) trong 15 - 20 phút để khử mùi hôi, rửa sạch. Chặt đôi, rút xương hoặc để nguyên tùy theo sở thích.', 10);
INSERT INTO public.recipe_steps VALUES (3165, '2025-11-20 17:11:16.479327', '2025-11-20 17:11:16.479327', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 507, 2, 'Phi thơm tỏi băm nhuyễn và sả, cho vào 1 chén (bát nhỏ) nước mắm 30 độ đạm (nếu bạn dùng nước mắm mặn hơn thì giảm lượng), 1 chén đường, 1/3 chén tương ớt, 1/3 chén ớt bột cùng sả, ớt tươi băm nhuyễn và gừng vào. Nấu hỗn hợp trên lửa nhỏ vừa, khuấy đều cho tới khi đường tan hết, nước sốt sánh lại thì tắt bếp để nguội rồi mới cho nước cốt quả tắc vào, khuấy đều.', 10);
INSERT INTO public.recipe_steps VALUES (3166, '2025-11-20 17:11:16.480906', '2025-11-20 17:11:16.480906', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 507, 8, 'Nước chấm: Cho vào cối 1,5 muỗng canh muối hạt, 1 muỗng canh đường, 1/2 muỗng canh hạt tiêu giã nhuyễn. Rồi thêm 1 muỗng canh sữa đặc, 1 muỗng canh nướt cốt tắc và 1/2 muỗng canh tương ớt trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (3168, '2025-11-20 17:11:16.484609', '2025-11-20 17:11:16.484609', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 507, 4, 'Luộc chân gà với vài lát gừng, chút sả đập dập, chút muối hạt. Với chân gà công nghiệp nhanh chín, bạn chỉ cần luộc 3 phút, rồi tắt bếp đậy vung tiếp tục om trong 5 phút là đảm bảo chân chín vừa độ giòn mà không bị đỏ xương. Sau đó, vớt chân ra cho vào nước sôi để nguội kèm đá lạnh cho tới khi nguội, cắt móng chân. Việc này giúp cho da gà săn lại và trở nên giòn ngon hơn. Sau đó, vớt ra để ráo nước. Hoặc bạn cho vào ngăn mát tủ lạnh 1-2 tiếng hoặc nhanh hơn thì cho vào ngăn đá 30 phút cho giòn.', 10);
INSERT INTO public.recipe_steps VALUES (3169, '2025-11-20 17:11:16.61997', '2025-11-20 17:11:16.61997', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 508, 5, 'Đun sôi nước, làm nóng chõ đồ xôi, hạ nhiệt rồi cho gạo và hạt dẻ vào chõ, dàn đều và tiến hành đồ xôi. Sau khoảng 15-20 phút khi hạt gạo nở, thêm một muỗng canh dầu ăn vào đảo đều giúp hạt xôi căng mẩy. Đậy vung, tiếp tục đồ xôi thêm 20 phút nữa để xôi chín đều, dẻo mềm.', 10);
INSERT INTO public.recipe_steps VALUES (3170, '2025-11-20 17:11:16.624858', '2025-11-20 17:11:16.624858', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 508, 2, 'Hạt dẻ rửa sạch, lau khô, dùng dao khứa nhẹ một lát ngang trên vỏ. Cho hạt dẻ cùng lượng nước xâm xấp và luộc 10-12 phút hoặc cho tới khi phần cắt nứt nhẹ, vớt ra ngâm vào nước lạnh để vỏ mềm, dễ bóc. Sau đó, bóc lớp vỏ ngoài và vỏ lụa, cắt thành miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (3171, '2025-11-20 17:11:16.628047', '2025-11-20 17:11:16.628047', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 508, 4, 'Cho hạt dẻ vào gạo, thêm một thìa cà phê muối tinh và trộn đều để giúp xôi đậm đà hơn.', 10);
INSERT INTO public.recipe_steps VALUES (3172, '2025-11-20 17:11:16.630716', '2025-11-20 17:11:16.630716', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 508, 3, 'Gạo nếp vo sạch, ngâm nước qua đêm khoảng 6-8 tiếng. Nếu muốn nấu luôn thì ngâm vào nước ấm khoảng một tiếng trước khi nấu. Sau đó, đổ gạo ra, xả nhẹ nước, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (3173, '2025-11-20 17:11:16.632733', '2025-11-20 17:11:16.632733', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 508, 6, 'Xới xôi ra đĩa, ăn kèm lạp xưởng, ruốc hoặc vừng lạc rang đều ngon.Hạt xôi căng mẩy, dẻo mềm quyện hạt dẻ bở bùi, ngọt dịu.', 10);
INSERT INTO public.recipe_steps VALUES (3174, '2025-11-20 17:11:16.634325', '2025-11-20 17:11:16.634325', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 508, 1, 'Hạt dẻ được ví là "vua của loài quả khô'''' trong mùa đông. Theo Đông y, hạt dẻ có vị ngọt tính ôn, vào vị, tỳ, giúp bồi bổ cơ thể, chống mệt mỏi, tốt cho dạ dày, cầm máu. Có nhiều món ăn từ hạt dẻ rất tốt cho cơ thể như: Hạt dẻ nướng mật ong, xôi hạt dẻ, gà hầm hạt dẻ, cơm rang hạt dẻ...', 10);
INSERT INTO public.recipe_steps VALUES (3175, '2025-11-20 17:11:16.820286', '2025-11-20 17:11:16.820286', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 509, 2, 'Hạt sen tươi thông tâm, luộc chín cùng chút muối, đem xào với 1/2 thìa canh đường cho thấm vị ngọt, để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (3176, '2025-11-20 17:11:16.821923', '2025-11-20 17:11:16.821923', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 509, 3, 'Dừa nạo xào cùng 1,5 thìa canh đường cùng chút dầu ăn cho tới khi sợi chuyển màu trong, múc ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (3177, '2025-11-20 17:11:16.824223', '2025-11-20 17:11:16.824223', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 509, 4, 'Làm xôi cốm: Cốm mua về, dàn đều, thêm 1 thìa canh dầu ăn trộn đều để giúp hạt cốm tơi ra. Nếu bạn dùng cốm khô thì nên vẩy thêm chút nước cho mềm hạt. Thêm 2 thìa canh nước cốt dừa vào cốm đảo đều, rồi cho vào xửng (đã thoa chút dầu ăn), hấp trong 4-5 phút cho hạt cốm hơi mềm là lấy ra. Dùng dao thái nắm đậu xanh thành lát mỏng (giống cách làm xôi xéo để giúp đậu mịn) rồi đảo đều cùng cốm. Thêm hạt sen, dừa xào trộn đều là hoàn thành.', 10);
INSERT INTO public.recipe_steps VALUES (3178, '2025-11-20 17:11:16.825751', '2025-11-20 17:11:16.825751', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 509, 6, 'Yêu cầu thành phẩm: Xôi cốm thơm mùi đặc trưng của cốm, hạt xôi dẻo mềm mà vẫn tơi, vị ngọt dịu, cộng chút bùi bùi của đậu xanh, hạt sen, chút béo ngậy của dừa xào làm nên món ăn tinh tế, đượm vị thu Hà Nội.', 10);
INSERT INTO public.recipe_steps VALUES (3179, '2025-11-20 17:11:16.826777', '2025-11-20 17:11:16.826777', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 509, 1, 'Đậu xanh rửa sạch, ngâm nước 3 - 4 giờ, hấp chín, giã hoặc xay nhuyễn, nắm thành nắm tròn.', 10);
INSERT INTO public.recipe_steps VALUES (3180, '2025-11-20 17:11:16.829657', '2025-11-20 17:11:16.829657', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 509, 5, 'Trình bày và thưởng thức: Cho xôi cốm vào lá sen rồi bọc và gói lại ủ để tạo hương thơm thanh tao – mùi hương gây thương nhớ cho người thưởng thức, để rồi một lần ăn thử sẽ không thể nào quên dư vị rất riêng.', 10);
INSERT INTO public.recipe_steps VALUES (3181, '2025-11-20 17:11:17.183133', '2025-11-20 17:11:17.183133', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 510, 1, 'Sơ chế và ướp thịt:Thịt lợn vai đầu giòn rửa sạch, thấm khô hoặc để ráo nước, thái miếng khoảng 0,5cm (không nên thái mỏng sẽ bị khô tóp lại khi nướng, cũng không nên thái dày sẽ lâu ngấm gia vị).', 10);
INSERT INTO public.recipe_steps VALUES (3182, '2025-11-20 17:11:17.184192', '2025-11-20 17:11:17.184192', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 510, 2, 'Ướp thịt với 2 thìa canh dầu hào, 2 thìa canh nước hàng, 2 thìa canh dầu ăn, 2 thìa canh nước mắm ngon, 1 thìa canh nước tương (xì dầu), 1 thìa canh sữa đặc có đường, 1 thìa canh đường, 1 thìa canh mật ong, 2 thìa cà phê hạt tiêu, 1-2 thìa cà phê dầu mè (sẽ thơm hơn), 1 thìa cà phê bột điều (hoặc 1 thìa canh dầu điều).', 10);
INSERT INTO public.recipe_steps VALUES (3183, '2025-11-20 17:11:17.1858', '2025-11-20 17:11:17.1858', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 510, 7, 'Yêu cầu thành phẩm:Thịt xiên mềm, vị mặn - ngọt hài hòa, bóng đẹp, mùi thơm các gia vị đầy ''''mê hoặc'''', dùng ăn chơi hay ăn kèm bún đều rất phù hợp trong tiết trời lạnh.', 10);
INSERT INTO public.recipe_steps VALUES (3184, '2025-11-20 17:11:17.188275', '2025-11-20 17:11:17.188275', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 510, 4, 'Ngâm xiên trevào nước trước 30 phút để khi nướng không bị cháy.', 10);
INSERT INTO public.recipe_steps VALUES (3185, '2025-11-20 17:11:17.189581', '2025-11-20 17:11:17.189581', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 510, 6, 'Nướng thịt:Bạn có thể nướng thịt bằng lò nướng, nồi chiên không dầu, nhưng ngon nhất là bằng than hoa. Phết nhẹ lớp dầu ăn lên vỉ nướng, xếp lần lượt xiên thịt lên dàn đều ra. Nếu dùng lò nướng thì cho thêm nước vào khay đen (hoặc lót giấy bạc), bật trước lò 10 phút ở 180- 200 độ, sau đó cho vỉ nướng xếp thịt xiên vào. Sau 10 phút, lấy thịt ra, quết hỗn hợp nước sốt ở trên. Lặp lại lần nữa, trở (lật) xiên thịt, quết rồi nướng cho tới khi thịt chín vàng, hơi sém là được. Tổng thời gian khoảng 35 - 40 phút. Với nồi chiên không dầu, bạn cũng căn chỉnh nhiệt độ và thời gian như trên.', 10);
INSERT INTO public.recipe_steps VALUES (3259, '2025-11-20 17:11:23.069601', '2025-11-20 17:11:23.069601', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 526, 12, 'Nha đam thái miếng vừa ăn, dâu tây cắt lát. Đun sôi đường, nước cho nha đam vào nấu chín, tắt bếp. Cho dâu tây vào dọn ra chén.', 10);
INSERT INTO public.recipe_steps VALUES (3186, '2025-11-20 17:11:17.191705', '2025-11-20 17:11:17.191705', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 510, 5, 'Xiên thịt: Thịt sau khi ướp đủ thời gian, thêm 1 thìa canh nước cốt chanh và mè trắng (vừng trắng, tùy chọn) vào đảo đều. Lần lượt xiên thịt vào xiên tre với nạc mỡ xen kẽ, nếu miếng nào dài thì gập đôi, dàn ra để thịt chín đều khi nướng. Phần nước ướp còn dư thì giữ lại, thêm 2 thìa canh mật ong, 2 thìa canh dầu điều (hoặc dầu ăn), 1 thìa canh dầu hào trộn đều, dùng để phết lên thịt khi nướng giúp tạo độ bóng và lên màu đẹp.', 10);
INSERT INTO public.recipe_steps VALUES (3187, '2025-11-20 17:11:17.193302', '2025-11-20 17:11:17.193302', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 510, 3, 'Sả, hành khô, tỏi giã nhuyễn, vắt lấy nước cốt cho vào ướp thịt (nếu có bột tỏi, bột hành, bột sả sẽ tiện hơn). Đeo găng tay bóp, trộn đều gia vị, bọc màng bọc thực phẩm để ngăn mát tủ lạnh ướp tối thiểu 2 giờ, nếu để ướp qua đêm sẽ ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (3188, '2025-11-20 17:11:17.424448', '2025-11-20 17:11:17.424448', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 511, 2, 'Hành lá rửa sạch, phần gốc hành trắng cắt để riêng, phần lá xanh cắt nhỏ. Chuẩn bị sẵn hành phi. Xem cách làm hành phi giòn rụmtại đây.', 10);
INSERT INTO public.recipe_steps VALUES (3189, '2025-11-20 17:11:17.426031', '2025-11-20 17:11:17.426031', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 511, 5, 'Yêu cầu thành phẩm: Ngô dẻo mềm, tép khô thơm giòn, đậm vị, dậy mùi thơm quyến rũ từ bơ, hành lá. Đây là món ăn đường phố được nhiều bạn trẻ yêu thích.', 10);
INSERT INTO public.recipe_steps VALUES (3190, '2025-11-20 17:11:17.427609', '2025-11-20 17:11:17.427609', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 511, 3, 'Phi thơm đầu trắng hành lá với chút dầu ăn, cho ngô vào xào trên lửa nhỏ. Nêm nếm đường, nước tương, tương ớt, hạt tiêu theo khẩu vị, đập vung, thỉnh thoảng mở ra đảo cho tới khi ngô chín. Thêm bơ động vật, tép khô vào đảo đều để dậy lên mùi thơm của bơ.', 10);
INSERT INTO public.recipe_steps VALUES (3191, '2025-11-20 17:11:17.429215', '2025-11-20 17:11:17.429215', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 511, 1, 'Tách lấy hạt bắp, loại bỏ phần bắp vụn, râu và mày bắp, rửa sạch, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (3192, '2025-11-20 17:11:17.430278', '2025-11-20 17:11:17.430278', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 511, 4, 'Thêm hành lá, ớt đảo đều, tắt bếp, xúc ra thưởng thức kèm ruốc bông, hành phi.', 10);
INSERT INTO public.recipe_steps VALUES (3193, '2025-11-20 17:11:17.626227', '2025-11-20 17:11:17.626227', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 512, 3, 'Cho sắn vào đun nhỏ lửa trong 4-5 phút cho vị ngọt thấm vào sắn. Hòa tan bột năng với chút nước lọc, vừa cho vào nồi vừa khuấy đều để không bị bén nồi. Khi chè sánh và trong, đun thêm vài phút cho bột năng chín hẳn rồi tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (3194, '2025-11-20 17:11:17.627752', '2025-11-20 17:11:17.627752', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 512, 5, 'Yêu cầu thành phẩm: Chè có vị dịu ngọt ấm nóng của gừng, màu nâu vàng sánh mịn quyện với từng miếng sắn dẻo mềm rất hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (3195, '2025-11-20 17:11:17.629281', '2025-11-20 17:11:17.629281', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 512, 2, 'Cho 900ml vào nồi, thêm 100 gram đường vàng hoa mai (điều chỉnh theo khẩu vị ngọt mỗi người), khuấy tan đường, thêm 1/4 thìa cà phê muối tinh, gừng thái sợi, lá dứa đun nhỏ lửa để đường tan hoàn toàn rồi vớt lá dứa ra.', 10);
INSERT INTO public.recipe_steps VALUES (3196, '2025-11-20 17:11:17.630287', '2025-11-20 17:11:17.630287', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 512, 1, 'Sắn bóc bỏ vỏ, ngâm nước muối loãng hoặc nước vo gạo 6 - 7 tiếng cho hết độc tố, đem hấp chín, bỏ gân lõi, cắt miếng vuông hoặc quân cờ vừa miệng.', 10);
INSERT INTO public.recipe_steps VALUES (3197, '2025-11-20 17:11:17.632293', '2025-11-20 17:11:17.632293', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 512, 4, 'Trình bày và thưởng thức: Múc chè sắn nóng ra bát, thêm dừa tươi nạo sợi, vừng rang, rưới thêm chút nước cốt dừa và thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (3198, '2025-11-20 17:11:17.886392', '2025-11-20 17:11:17.886392', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 513, 2, 'Nghệ và hành tăm rửa sạch, cho vào cối hoặc máy xay nhuyễn. Riềng rửa sạch, cắt lát.', 10);
INSERT INTO public.recipe_steps VALUES (3199, '2025-11-20 17:11:17.887958', '2025-11-20 17:11:17.887958', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 513, 4, 'Xếp riềng thái lát dưới đáy nồi đất để chống bén nồi, lần lượt cho cá lên, trên cùng rải lớp hành tăm và nghệ giã nhuyễn. Nêm 3- 4 thìa canh nước mắm cốt ngon, 2-3 thìa canh mật mía, 1 thìa cà phê muối, ớt tươi ướp khoảng 30 phút.', 10);
INSERT INTO public.recipe_steps VALUES (3200, '2025-11-20 17:11:17.890133', '2025-11-20 17:11:17.890133', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 513, 5, 'Kho cá nên kho 3 lần lửa và 3 lần châm nước: Sau khi ướp, cho thêm nước sôi vào xâm xấp và bật bếp kho cá trên lửa nhỏ. Sau 1 giờ tắt bếp, để nguội cho cá đanh lại, rồi lại tiếp tục kho cá trên lửa nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3201, '2025-11-20 17:11:17.891724', '2025-11-20 17:11:17.891724', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 513, 3, 'Cá còm làm sạch, bỏ ruột, rửa sạch, để ráo. Làm nóng chảo, cho lượng dầu vừa phải vào rồi hạ lửa vừa, nhẹ nhàng cho cá còm vào chiên hơi vàng các mặt, vớt ra.', 10);
INSERT INTO public.recipe_steps VALUES (3202, '2025-11-20 17:11:17.894062', '2025-11-20 17:11:17.894062', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 513, 1, 'Cá còm là loài cá tự nhiên, kích thước bé bằng ngón tay, thịt chắc, xương mềm, sinh sản quanh năm ở vùng sông Lam, Nghệ An. Cá còm được chế biến thành nhiều món ăn dân dã như: Cá còm kho tương, cá còm chiên, cá còm nấu canh nhút... đặc biệt ngon nhất là cá còm kho nghệ vừa bổ dưỡng lại thơm ngon. Cá kho vàng ươm, đậm đà rất ''''hao cơm'''' trong những ngày mùa đông lạnh giá.', 10);
INSERT INTO public.recipe_steps VALUES (3203, '2025-11-20 17:11:17.896196', '2025-11-20 17:11:17.896196', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 513, 6, 'Lặp lại 3 lần thì cá kho bên ngoài săn lại nhưng bên trong thịt thơm, xương mềm là đạt. Thời gian tối thiểu kho là 3 giờ. Trước khi hoàn thành, rưới thêm chút mỡ lợn và lá nghệ tươi xắt nhỏ lên trên để tạo độ bóng cho món ăn và dậy mùi thơm đặc trưng lá nghệ, tạo cho món ăn thơm ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (3217, '2025-11-20 17:11:20.308187', '2025-11-20 17:11:20.308187', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 518, 9, 'Yêu cầu thành phẩm:Bát bún thang hội tụ tròn trịa sắc – hương - vị như một bức tranh lập thể nhiều màu sắc: Thịt gà vàng ươm, lườn gà xé nhỏ trắng thơm, trứng mỏng manh như sợi tơ, giò lụa thái chỉ hồng nhạt, rau răm xanh tươi, ruốc sỏi màu nâu rám nắng, ở giữa trứng muối tựa mặt trời. Đặc biệt, nước dùng thanh ngọt mà đậm đà, dậy mùi thơm cà cuống gây thương nhớ về hương vị xưa cũ.', 10);
INSERT INTO public.recipe_steps VALUES (3218, '2025-11-20 17:11:20.310489', '2025-11-20 17:11:20.310489', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 518, 5, 'Phần tôm khô sau khi ninh cùng xương gà, xương heo cho giúp nổi vị thanh ngọt, đậm đà thì vớt ra, giã nhỏ, cà qua rổ tre cho bông và đem sao vàng làm 1 thang ruốc tôm.', 10);
INSERT INTO public.recipe_steps VALUES (3326, '2025-11-20 17:11:26.485061', '2025-11-20 17:11:26.485061', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 534, 7, 'Dùng với bún, rau sống, chuối xanh và khế chua. Chấm mắm nêm.', 10);
INSERT INTO public.recipe_steps VALUES (3204, '2025-11-20 17:11:18.399042', '2025-11-20 17:11:18.399042', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 514, 1, 'Sơ chế sườn:Sườn bóc bỏ mỡ và gân, ngâm nước muối loãng ấm 15 phút, rửa sạch, để ráo.
INSERT INTO public.recipe_steps VALUES (3205, '2025-11-20 17:11:18.889654', '2025-11-20 17:11:18.889654', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 515, 1, 'Sơ chế
INSERT INTO public.recipe_steps VALUES (3206, '2025-11-20 17:11:18.890718', '2025-11-20 17:11:18.890718', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 515, 2, 'Nấu nước lẩu
INSERT INTO public.recipe_steps VALUES (3207, '2025-11-20 17:11:18.892296', '2025-11-20 17:11:18.892296', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 515, 4, 'Yêu cầu thành phẩm
INSERT INTO public.recipe_steps VALUES (3208, '2025-11-20 17:11:18.893888', '2025-11-20 17:11:18.893888', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 515, 3, 'Trình bày và thưởng thức
INSERT INTO public.recipe_steps VALUES (3209, '2025-11-20 17:11:19.284509', '2025-11-20 17:11:19.284509', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 516, 5, 'Trình bày nồi lẩu bò ớt xiêm xanh, rau nhúng lên bàn, vẫn để lửa nhỏ, nêm nếm thêm đường, mắm muối, tiêu sao cho vừa khẩu vị. Thái nạm bò, chả cá xếp lên đĩa cùng với bò viên và ba chỉ bò,bắt đầu nhúng chín và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (3210, '2025-11-20 17:11:19.286129', '2025-11-20 17:11:19.286129', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 516, 2, 'Nấm mỡ thái miếng vừa ăn cũng ngâm với nước muối loãng để khử mùi hôi của nấm, rau muống cũng rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (3211, '2025-11-20 17:11:19.288235', '2025-11-20 17:11:19.288235', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 516, 3, 'Cho xương bò, nạm bò và hành tây vào hầm khoảng 30 phút sau đó vớt cục nạm bò ra, cho vào tô nước đá để cho nạm bò săn lại ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (3212, '2025-11-20 17:11:19.289842', '2025-11-20 17:11:19.289842', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 516, 4, 'Tiếp theo phi tỏi băm với ớt tươi đã rửa sạch, thái lát nhỏ sau đó băm thật nhuyễn. Nếu được cho vào máy xay là tốt nhất.Cho phần tỏi với ớt vừa phi vào trong nồi nước dùng.', 10);
INSERT INTO public.recipe_steps VALUES (3213, '2025-11-20 17:11:19.291962', '2025-11-20 17:11:19.291962', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 516, 1, 'Thịt bò nạm, xương bò sau khi mua về bạn rửa qua bằng nước pha muối loãng, sau đó rửa lại bằng nước sạch.', 10);
INSERT INTO public.recipe_steps VALUES (3214, '2025-11-20 17:11:19.704502', '2025-11-20 17:11:19.704502', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 517, 1, 'Sơ chế
INSERT INTO public.recipe_steps VALUES (3215, '2025-11-20 17:11:19.706125', '2025-11-20 17:11:19.706125', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 517, 2, 'Chế biến
INSERT INTO public.recipe_steps VALUES (3220, '2025-11-20 17:11:20.314286', '2025-11-20 17:11:20.314286', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 518, 8, 'Trình bày và chan thang: Bún rối sợi nhỏ chần 1 nắm nhỏ cho vào bát chiết yêu. Xếp đan xen các thang sao cho màu sắc hài hòa, cân đối: thịt gà thái nhỏ, trứng, giò lụa thái chỉ, ruốc sỏi, ruốc tôm bông, rau răm và ở giữa đặt một lát trứng muối tựa mặt trời. Bún thang lối cổ xưa không có hành lá, rau mùi. Chan thang cũng cần lắm những tinh tế. Múc muôi nước dùng thang nóng rẫy rưới nhẹ nhàng một vòng quanh bát lần thứ nhất, dùng cái muôi chặn lên bát thang và chắt nước đầu tiên đi. Tiếp tục múc nước thang lần hai rồi chan nhẹ nhàng, vòng quanh sao cho các nguyên liệu giữ nguyên vẻ đẹp. Các nguyên liệu ăn kèm như mắm cà cuống, mắm tôm, củ cải dầm, ớt tươi để riêng ăn kèm.', 10);
INSERT INTO public.recipe_steps VALUES (3221, '2025-11-20 17:11:20.316456', '2025-11-20 17:11:20.316456', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 518, 6, 'Thịt thăn lợn thái hạt lựu nhỏ, ướp chút gia vị rồi rang thơm tạo nên 1 vị thang ruốc sỏi cho món bún. Giò lụa thái chỉ như sợi bún. Rau răm rửa sạch, thái rối. Củ cải khô hoặc củ cải tươi ngâm giấm, mắm 30 độ đạm, đường theo tỷ lệ 1:1:1 thêm chút gừng cho thơm. Trứng muối cắt miếng vừa ăn. Ớt tươi bỏ bớt hạt, thái khoanh. Bún thang lối cổ không có chanh, tùy theo khẩu vị thêm cho vừa miệng.', 10);
INSERT INTO public.recipe_steps VALUES (3222, '2025-11-20 17:11:20.318041', '2025-11-20 17:11:20.318041', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 518, 7, 'Cà cuống và mắm tôm là hai hương vị tôn thêm nét đặc trưng cho bún thang. Đặc biệt hương thơm từ bọng tinh dầu của cà cuống đực ngâm mắm tỏa ra-đây là gia vị làm nên nét đặc trưng của nhiều món ăn nổi tiếng Hà thành như bún chả, bún thang, bánh cuốn.', 10);
INSERT INTO public.recipe_steps VALUES (3223, '2025-11-20 17:11:20.319646', '2025-11-20 17:11:20.319646', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 518, 3, 'Sự khéo léo, tỉ mỉ nhất là phần tráng và thái trứng gà sao cho mềm mại và mịn mỏng như tơ tằm. Trứng gà đánh tan cùng chút gia vị, rượu trắng cho thơm, thêm chút nước cho mềm mại. Sau đó, đun lửa vừa cho nóng chảo mặt phẳng, láng qua chút mỡ hoặc dầu ăn. Múc muôi nhỏ trứng lắc láng trải đều khắp mặt chảo, hạ nhỏ lửa đun liu riu để chín mịn màng. Chú ý không để lửa to làm trứng phồng rộp khô xác.', 10);
INSERT INTO public.recipe_steps VALUES (3224, '2025-11-20 17:11:20.32065', '2025-11-20 17:11:20.32065', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 518, 2, 'Nước dùng để chan bún thang rất đặc biệt, là sự kết hợp vị ngọt tự nhiên từ xương gà, xương hom lợn, tôm khô và sá sùng. Một số người cầu kỳ hơn thì thêm râu mực nướng. Ngày xưa, các bà các mẹ chọn kỹ tôm he khô loại xâu que tre, cứ 1 xâu có 5 con và 10 xâu thì làm 1 bó. Bóc phần đầu vỏ nấu nước dùng, còn phần thịt tôm rang lên làm ruốc bông cho 1 phần thang. Phần nước luộc gà thì hớt bọt, mỡ cho trong. Phần xương hom cũng rửa kỹ, chần sơ, ninh xương gà, xương hom cùng tôm ở lửa nhỏ liu riu, mở vung cho ngọt và trong nước. Thêm gừng, hành khô nướng rửa sạch ninh cùng cho thơm.', 10);
INSERT INTO public.recipe_steps VALUES (3225, '2025-11-20 17:11:20.323364', '2025-11-20 17:11:20.323364', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 518, 4, 'Khi trứng chín vàng ươm, lắc rồi bóc nhẹ đặt lên thớt mặt phẳng. Cứ thế làm lần lượt cho tới hết. Xếp các tấm trứng chồng lên nhau, cuốn tròn và dùng dao sắc thái nhỏ sợi tơ như sợi. Chi tiết dẫu nhỏ nhưng thể hiện nét tinh tế, cầu kỳ và ý nhị của ẩm thực Hà Nội xưa.', 10);
INSERT INTO public.recipe_steps VALUES (3226, '2025-11-20 17:11:20.663834', '2025-11-20 17:11:20.663834', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 519, 3, 'Yêu cầu thành phẩm
INSERT INTO public.recipe_steps VALUES (3227, '2025-11-20 17:11:20.666523', '2025-11-20 17:11:20.666523', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 519, 2, 'Phết sốt phô mai vào tôm
INSERT INTO public.recipe_steps VALUES (3228, '2025-11-20 17:11:20.66918', '2025-11-20 17:11:20.66918', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 519, 1, 'Chuẩn bị
INSERT INTO public.recipe_steps VALUES (3229, '2025-11-20 17:11:21.144992', '2025-11-20 17:11:21.144992', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 520, 3, 'Trình bày và thưởng thức
INSERT INTO public.recipe_steps VALUES (3230, '2025-11-20 17:11:21.147093', '2025-11-20 17:11:21.147093', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 520, 4, 'Yêu cầu thành phẩm
INSERT INTO public.recipe_steps VALUES (3243, '2025-11-20 17:11:22.0764', '2025-11-20 17:11:22.0764', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 522, 2, 'b. Tẩm ướp
INSERT INTO public.recipe_steps VALUES (3260, '2025-11-20 17:11:23.071202', '2025-11-20 17:11:23.071202', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 526, 7, 'Gỏi nha đam
INSERT INTO public.recipe_steps VALUES (3231, '2025-11-20 17:11:21.14929', '2025-11-20 17:11:21.14929', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 520, 1, 'Sơ chế
INSERT INTO public.recipe_steps VALUES (3232, '2025-11-20 17:11:21.151615', '2025-11-20 17:11:21.151615', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 520, 2, 'Nấu nước lẩu
INSERT INTO public.recipe_steps VALUES (3233, '2025-11-20 17:11:21.735441', '2025-11-20 17:11:21.735441', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 521, 4, 'Hành khô bóc bỏ vỏ, thái đều tay và chiên vàng giòn. Quan trọng nhất khi làm hành phi là canh thời điểm hành đạt: hành chiên se lại, hơi ngả vàng thì tắt bếp, vớt nhanh ra để vào giấy thấm dầu, dàn đều. Khi nguội, hành sẽ vàng và giòn rụm.Xem cách làm hành phi tại đây', 10);
INSERT INTO public.recipe_steps VALUES (3234, '2025-11-20 17:11:21.738127', '2025-11-20 17:11:21.738127', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 521, 5, 'Làm nước dùng lẩu:Xương hom chần sơ, rửa sạch rồi đem ninh nhỏ lửa 1 tiếng để lấy nước dùng ngọt tự nhiên, lọc lấy nước dùng trong. Cà chua rửa sạch, thái múi cau. Cho 3 thìa canh dầu màu điều phi thơm cùng hành khô, trút 1/2 lượng cà chua vào, nêm chút nước mắm xào sơ tạo màu. Đổ nước ninh xương, nước dùng cua vào nồi, trút phần cà chua đã xào và số cà chua còn lại vào. Thêm đậu phụ rán, váng đậu, thịt riêu cua, gạch cua chưng, chút hành phi vào. Nêm nếm muối, nước mắm, mắm tôm, hạt nêm, chút đường cho dịu vị rồi xuống từ từ giấm bỗng nếp sao cho vừa miệng là được. Giấm bỗng nêm sau cùng để tạo vị chua thanh và giữ mùi vị cho món lẩu.', 10);
INSERT INTO public.recipe_steps VALUES (3235, '2025-11-20 17:11:21.74036', '2025-11-20 17:11:21.74036', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 521, 2, 'Phi chút dầu màu điều với hành khô, cho gạch cua vào chưng cho dậy mùi thơm và lên màu nâu vàng đẹp mắt.', 10);
INSERT INTO public.recipe_steps VALUES (3236, '2025-11-20 17:11:21.742493', '2025-11-20 17:11:21.742493', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 521, 3, 'Đậu phụ cắt miếng vừa ăn, rán vàng giòn đều, vớt ra đĩa để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (3237, '2025-11-20 17:11:21.74514', '2025-11-20 17:11:21.74514', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 521, 1, 'Sơ chế cua:Cua đồng mua về cho vào thau/chậu cùng chút muối hạt xóc mạnh rồi rửa nhiều lần cho sạch. Bóc mai tách yếm, khều gạch vàng để riêng. Rửa sạch phần thân của lần nữa, cho vào cối cùng chút muối hạt, giã nhuyễn cho tới khi dính lại. Muối giúp cho protein trong thịt cua kết dính lại. Cho khoảng 1,5 - 1,8 lít nước, dùng tay bóp kỹ cho thịt cua tan ra, để lắng và lọc lấy nước. Tiếp tục giã và lọc kỹ vài lần để lấy hết phần thịt cua. Sau đó, cho vào nồi bật lửa vừa và khuấy đều theo 1 chiều để thịt riêu cua không bén đáy nồi. Khi thịt riêu cua tách nước, nổi dần lên thì hạ lửa nhỏ, dùng muôi múc riêng ra bát, ép chặt nước để thịt riêu cua riêng. Phần nước dùng cua để làm nước dùng lẩu.', 10);
INSERT INTO public.recipe_steps VALUES (3238, '2025-11-20 17:11:21.747239', '2025-11-20 17:11:21.747239', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 521, 6, 'Chuẩn bị đồ nhúng lẩu:Thịt bò thái ngang thớ miếng mỏng, ướp chút gừng thái sợi và dầu ăn cho bò mềm ngọt. Sườn sụn thái mỏng. Giò tai cắt miếng vừa ăn. Thêm xúc xích cho các bạn nhỏ (tùy chọn).', 10);
INSERT INTO public.recipe_steps VALUES (3239, '2025-11-20 17:11:21.74936', '2025-11-20 17:11:21.74936', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 521, 7, 'Các loại rau củ quả rửa sạch, vẩy ráo nước, bày ra đĩa. Thêm trứng vịt lộn để món lẩu thêm ngọt nước (tùy chọn).', 10);
INSERT INTO public.recipe_steps VALUES (3240, '2025-11-20 17:11:21.751948', '2025-11-20 17:11:21.751948', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 521, 8, 'Khi ăn đun sôi nước dùng riêu cua. Rồi nhúng thịt bò, sườn sụn, giò tai và các loại rau ăn nóng.', 10);
INSERT INTO public.recipe_steps VALUES (3241, '2025-11-20 17:11:21.753574', '2025-11-20 17:11:21.753574', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 521, 9, 'Yêu cầu thành phẩm: Nước lẩu có vị chua dịu, thanh nhẹ từ giấm bỗng, dậy mùi thơm đặc trưng của riêu cua. Khi ăn, nhúng thịt bò chín tái ngọt mềm, sườn sụn sần sật, đậu phụ vàng giòn, các rau củ quả xanh tươi mang tới một hương vị rất riêng, đượm nét dân dã nét đồng quê.', 10);
INSERT INTO public.recipe_steps VALUES (3242, '2025-11-20 17:11:22.074169', '2025-11-20 17:11:22.074169', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 522, 1, 'Sơ chế
INSERT INTO public.recipe_steps VALUES (3256, '2025-11-20 17:11:23.064291', '2025-11-20 17:11:23.064291', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 526, 10, 'Chè nha đam
INSERT INTO public.recipe_steps VALUES (3257, '2025-11-20 17:11:23.065891', '2025-11-20 17:11:23.065891', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 526, 5, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (3261, '2025-11-20 17:11:23.072789', '2025-11-20 17:11:23.072789', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 526, 11, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (3262, '2025-11-20 17:11:23.07385', '2025-11-20 17:11:23.07385', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 526, 2, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (3244, '2025-11-20 17:11:22.079576', '2025-11-20 17:11:22.079576', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 522, 3, 'c. Nướng
INSERT INTO public.recipe_steps VALUES (3245, '2025-11-20 17:11:22.38369', '2025-11-20 17:11:22.38369', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 523, 1, 'Sơ chế
INSERT INTO public.recipe_steps VALUES (3246, '2025-11-20 17:11:22.385838', '2025-11-20 17:11:22.385838', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 523, 3, 'Yêu cầu thành phẩm
INSERT INTO public.recipe_steps VALUES (3247, '2025-11-20 17:11:22.387564', '2025-11-20 17:11:22.387564', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 523, 2, 'Chế biến
INSERT INTO public.recipe_steps VALUES (3248, '2025-11-20 17:11:22.52568', '2025-11-20 17:11:22.52568', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 524, 1, 'Sơ chế
INSERT INTO public.recipe_steps VALUES (3249, '2025-11-20 17:11:22.527279', '2025-11-20 17:11:22.527279', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 524, 2, 'Chế biến
INSERT INTO public.recipe_steps VALUES (3250, '2025-11-20 17:11:22.529544', '2025-11-20 17:11:22.529544', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 524, 3, 'Yêu cầu thành phẩm
INSERT INTO public.recipe_steps VALUES (3251, '2025-11-20 17:11:22.835902', '2025-11-20 17:11:22.835902', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 525, 2, 'Dùng dầu màu điều để xào sả, hành cho thơm, sau đó cho tôm vào nấu săn. Tiếp tục cho 1/2 chén nước cốt dừa và 1 muỗng nước me. Nêm thêm muối, đường. Cho đậu bắp, ớt xanh, hành tây, cho nước cốt dừa vào đảo đều rồi nhấc xuống.', 10);
INSERT INTO public.recipe_steps VALUES (3252, '2025-11-20 17:11:22.838025', '2025-11-20 17:11:22.838025', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 525, 3, 'Dọn cà ri tôm càng ra đĩa, để lên trên vài lát đậu bắp sống. Món này ăn chung với bún.', 10);
INSERT INTO public.recipe_steps VALUES (3253, '2025-11-20 17:11:22.839102', '2025-11-20 17:11:22.839102', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 525, 1, 'Dừa vắt lấy một chén cốt, sả băm nhuyễn phi vàng. Tôm bóc vỏ, ướp muối, đường, bột ngọt, tiêu, hành tỏi băm và cà ri. Phi hạt điều màu để lấy dầu màu điều.', 10);
INSERT INTO public.recipe_steps VALUES (3254, '2025-11-20 17:11:23.061086', '2025-11-20 17:11:23.061086', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 526, 4, 'Nha đam nấu đuôi bò
INSERT INTO public.recipe_steps VALUES (3255, '2025-11-20 17:11:23.062724', '2025-11-20 17:11:23.062724', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 526, 3, 'Nha đam cắt hạt lựu. Tôm, mực, luộc chín cắt hạt lựu vừa ăn. Cho trứng gà vào đánh tan, cho thịt cua, tôm, mực, nha đam vào nấu chín cho ít bột năng tạo độ sánh.', 10);
INSERT INTO public.recipe_steps VALUES (3263, '2025-11-20 17:11:23.075552', '2025-11-20 17:11:23.075552', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 526, 8, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (3264, '2025-11-20 17:11:23.077683', '2025-11-20 17:11:23.077683', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 526, 6, 'Đuôi bò rửa sạch, hầm chung với nước dùng và củ cải cho mềm, cà rốt tỉa hoa thái mỏng. Nha đam cắt vừa ăn. Nêm gia vị cho vừa ăn, cho cà rốt, nha đam vào nấu chín, dọn ra tô, dùng nóng.', 10);
INSERT INTO public.recipe_steps VALUES (3265, '2025-11-20 17:11:23.079286', '2025-11-20 17:11:23.079286', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 526, 1, 'Súp nha đam hải sản
INSERT INTO public.recipe_steps VALUES (3266, '2025-11-20 17:11:23.358313', '2025-11-20 17:11:23.358313', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 527, 1, 'Hàu tách bỏ một bên vỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3267, '2025-11-20 17:11:23.360475', '2025-11-20 17:11:23.360475', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 527, 3, 'Chan hỗn hợp trên vào thịt hàu rồi cho vào lò điều chỉnh nhiệt độ vừa phải để hàu không bị khô. Khi thấy gia vị tan đều, thịt hàu vừa chín tới và phồng lên là được.', 10);
INSERT INTO public.recipe_steps VALUES (3268, '2025-11-20 17:11:23.362618', '2025-11-20 17:11:23.362618', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 527, 2, 'Trộn đều hỗn hợp gồm: phô mai + bơ + tỏi phi + trứng gà + bột nêm.', 10);
INSERT INTO public.recipe_steps VALUES (3269, '2025-11-20 17:11:23.364761', '2025-11-20 17:11:23.364761', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 527, 4, 'Dùng nóng với muối tiêu chanh pha ớt băm.', 10);
INSERT INTO public.recipe_steps VALUES (3270, '2025-11-20 17:11:23.513976', '2025-11-20 17:11:23.513976', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 528, 3, 'Ngô bóc vỏ, rửa sạch rồi bào mỏng. Hành lá rửa sạch, thái nhuyễn. Trộn giò sống với cá thát lát, thịt nạc, tiêu, hành lá và bột nêm, dùng thìa đầu tròn tán thật nhuyễn để hỗn hợp dẻo và mịn.', 10);
INSERT INTO public.recipe_steps VALUES (3271, '2025-11-20 17:11:23.515559', '2025-11-20 17:11:23.515559', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 528, 7, 'Súp kem ngô
INSERT INTO public.recipe_steps VALUES (3272, '2025-11-20 17:11:23.517164', '2025-11-20 17:11:23.517164', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 528, 1, 'Chả hấp ngô
INSERT INTO public.recipe_steps VALUES (3273, '2025-11-20 17:11:23.518771', '2025-11-20 17:11:23.518771', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 528, 6, 'Mách bạn: Không nên rưới nước vào chả vì trong khi hấp, ngô sẽ tiết ra nước.', 10);
INSERT INTO public.recipe_steps VALUES (3274, '2025-11-20 17:11:23.52035', '2025-11-20 17:11:23.52035', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 528, 11, 'Mách bạn: Sau khi cho sữa tươi và bột năng pha loãng, đun vừa sôi lại tắt bếp ngay vì đun lâu quá sữa sẽ vón cục.', 10);
INSERT INTO public.recipe_steps VALUES (3275, '2025-11-20 17:11:23.522089', '2025-11-20 17:11:23.522089', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 528, 4, 'Thoa chút dầu ăn vào lòng bàn tay rồi lần lượt vo viên hỗn hợp chả ở bước 2, cỡ gần bằng nắm tay. Lăn viên chả qua ngô bào, đặt vào xửng, hấp khoảng 15 phút. Củ cải đỏ tỉa hoa để trang trí.', 10);
INSERT INTO public.recipe_steps VALUES (3276, '2025-11-20 17:11:23.523691', '2025-11-20 17:11:23.523691', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 528, 5, 'Dùng nóng với cơm và xà lách, chấm ớt tương, tương đen.', 10);
INSERT INTO public.recipe_steps VALUES (3277, '2025-11-20 17:11:23.526825', '2025-11-20 17:11:23.526825', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 528, 8, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (3278, '2025-11-20 17:11:23.529016', '2025-11-20 17:11:23.529016', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 528, 9, 'Ngô rửa sạch, bào nhuyễn. Thịt gà luộc chín, xé sợi nhỏ. Đun nóng bơ trong chảo, cho bột mì vào đảo nhanh tay. Sau đó, cho 2 bát nước dùng gà vào đun sôi, cho tiếp ngô bào vào. Khi nước sôi lại, nêm bột nêm rồi cho sữa tươi cùng bột năng pha với ít nước vào, khuấy đều, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (3279, '2025-11-20 17:11:23.531685', '2025-11-20 17:11:23.531685', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 528, 2, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (3280, '2025-11-20 17:11:23.533809', '2025-11-20 17:11:23.533809', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 528, 10, 'Múc súp ra bát, cho gà xé lên. Dùng nóng.', 10);
INSERT INTO public.recipe_steps VALUES (3281, '2025-11-20 17:11:24.366122', '2025-11-20 17:11:24.366122', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 529, 4, 'Bột chiên quậy với nước không đặc quá. Dầu cho vào chảo cho nóng, nhúng cánh gà vào bột rồi bỏ vào chiên vàng.', 10);
INSERT INTO public.recipe_steps VALUES (3282, '2025-11-20 17:11:24.36814', '2025-11-20 17:11:24.36814', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 529, 1, 'Cánh gà rút xương làm hai đoạn, lận thịt ra ngoài, sau đó ướp bột canh, đường, rượu trắng để ngấm.', 10);
INSERT INTO public.recipe_steps VALUES (3283, '2025-11-20 17:11:24.370138', '2025-11-20 17:11:24.370138', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 529, 2, 'Thịt heo xay, nấm hương băm nhỏ, trộn với tiêu xanh, hành tím và gia vị còn lại.', 10);
INSERT INTO public.recipe_steps VALUES (3284, '2025-11-20 17:11:24.371648', '2025-11-20 17:11:24.371648', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 529, 3, 'Lận cánh gà lại rồi nhồi nhân vừa trộn vào nhưng nhớ đừng nhồi cứng quá. Sau đó, lấy tăm cài lại và xăm đều cánh gà, đem hấp khoảng 10 phút mang ra rút tăm, để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (3285, '2025-11-20 17:11:24.37465', '2025-11-20 17:11:24.37465', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 529, 5, 'Bạn có thể dùng xà lách, cà chua tỉa bông hồng để trang trí đĩa. Khi cánh gà chiên xong cắt lát, bày lên và dùng nóng.', 10);
INSERT INTO public.recipe_steps VALUES (3286, '2025-11-20 17:11:25.010243', '2025-11-20 17:11:25.010243', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 530, 3, 'Bắc chảo dầu nóng phi thơm tỏi, cho trứng muối và cua vào xào nêm muối, bột ngọt, nước tương tiêu.', 10);
INSERT INTO public.recipe_steps VALUES (3287, '2025-11-20 17:11:25.012899', '2025-11-20 17:11:25.012899', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 530, 4, 'Cho cơm, trứng gà vào trộn đều. Sau cùng cho cà rốt và đậu Hà Lan vào, nêm lại vừa ăn. Nén chặt cơm vào khuôn rồi bày ra đĩa, trang trí ngò và cà chua tỉa hoa.', 10);
INSERT INTO public.recipe_steps VALUES (3288, '2025-11-20 17:11:25.014509', '2025-11-20 17:11:25.014509', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 530, 1, 'Hấp chín lòng đỏ trứng muối rồi tán nhuyễn. Đánh tan lòng đỏ trứng gà.', 10);
INSERT INTO public.recipe_steps VALUES (3289, '2025-11-20 17:11:25.017785', '2025-11-20 17:11:25.017785', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 530, 2, 'Cà rốt cắt hạt lựu. Đậu Hà Lan trụng chín trong nước sôi, sau đó ngâm ngay vào nước đá lạnh để giữ mầu, vớt ra.', 10);
INSERT INTO public.recipe_steps VALUES (3290, '2025-11-20 17:11:25.02012', '2025-11-20 17:11:25.02012', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 530, 5, 'Dùng nóng với nước tương ớt.', 10);
INSERT INTO public.recipe_steps VALUES (3291, '2025-11-20 17:11:25.687002', '2025-11-20 17:11:25.687002', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 531, 1, 'Xương ống hầm với nước trong khoảng 40 phút.', 10);
INSERT INTO public.recipe_steps VALUES (3292, '2025-11-20 17:11:25.689147', '2025-11-20 17:11:25.689147', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 531, 6, 'Dùng đến đâu cho hoa và hải sản vào đến đấy, dùng kèm với bún.', 10);
INSERT INTO public.recipe_steps VALUES (3293, '2025-11-20 17:11:25.691263', '2025-11-20 17:11:25.691263', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 531, 2, 'Nêm hạt nêm, đường, muối.', 10);
INSERT INTO public.recipe_steps VALUES (3294, '2025-11-20 17:11:25.693035', '2025-11-20 17:11:25.693035', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 531, 3, 'Tôm, bò, mực, nghêu rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (3295, '2025-11-20 17:11:25.69517', '2025-11-20 17:11:25.69517', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 531, 5, 'Các loại hoa xếp ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (3302, '2025-11-20 17:11:25.904578', '2025-11-20 17:11:25.904578', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 532, 1, 'Nghêu tách đôi, rửa sạch bỏ vỏ còn một bên có thịt để lại. Bắc chảo lên bếp, cho một ít dầu ăn vào rồi bỏ sả băm.', 10);
INSERT INTO public.recipe_steps VALUES (3303, '2025-11-20 17:11:26.138839', '2025-11-20 17:11:26.138839', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 533, 5, 'Ốc mỡ rang me
INSERT INTO public.recipe_steps VALUES (3304, '2025-11-20 17:11:26.140424', '2025-11-20 17:11:26.140424', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 533, 7, 'Sườn non sốt me
INSERT INTO public.recipe_steps VALUES (3305, '2025-11-20 17:11:26.142568', '2025-11-20 17:11:26.142568', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 533, 8, 'Gia vị ướp sườn: 1 muỗng canh vun hành tỏi bằm, 3 muỗng canh cà phê đường, 1 muỗng cà phê tiêu, 1 muỗng cà phê bột ngọt, 4 muỗng cà phê nước mắm ngon.', 10);
INSERT INTO public.recipe_steps VALUES (3306, '2025-11-20 17:11:26.144164', '2025-11-20 17:11:26.144164', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 533, 10, 'Cách làm:Sườn ướp gia vị cho thấm, lăn qua bột chiên giòn, chiên vàng. Cho 1 muỗng canh dầu ăn vào phi tỏi cho thơm, cho nước dùng, nước me, gia vị vào. Đun sôi hỗn hợp cho nước bột năng vào quậy đến chín trong.', 10);
INSERT INTO public.recipe_steps VALUES (3307, '2025-11-20 17:11:26.145762', '2025-11-20 17:11:26.145762', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 533, 2, 'Cách làm:Cua tách mai, bỏ yếm, chà rửa sạch, xẻ đôi. Ướp gia vị (trừ đường), hành tỏi băm, hành tím phi vàng, mỡ phi, để tóp riêng. Cho cua vào chiên vàng thơm (mai chiên riêng), cho đường vào đảo sơ, cho nước me vào xào cho thấm, cho hành tây, tóp mỡ, hành phi. Cho cua ra đĩa, úp mai lên cho đẹp', 10);
INSERT INTO public.recipe_steps VALUES (3308, '2025-11-20 17:11:26.147872', '2025-11-20 17:11:26.147872', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 533, 11, 'Cho sườn vào chảo, chế nước xốt vào đảo đều cho thấm, cho hành tây xào sơ.', 10);
INSERT INTO public.recipe_steps VALUES (3309, '2025-11-20 17:11:26.149446', '2025-11-20 17:11:26.149446', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 533, 1, 'Cua rang me
INSERT INTO public.recipe_steps VALUES (3310, '2025-11-20 17:11:26.151014', '2025-11-20 17:11:26.151014', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 533, 6, 'Cách làm:Ốc rửa sạch, luộc chín, hành tây cắt làm 8 miếng, mỡ thắng lấy tóp để riêng. Phi tỏi vàng thơm, cho ốc vào xào cho thơm, cho gia vị và nước me vào xào cho thấm, cho tóp mỡ, hành tây.', 10);
INSERT INTO public.recipe_steps VALUES (3311, '2025-11-20 17:11:26.152318', '2025-11-20 17:11:26.152318', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 533, 3, 'Tôm rang me
INSERT INTO public.recipe_steps VALUES (3312, '2025-11-20 17:11:26.154837', '2025-11-20 17:11:26.154837', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 533, 4, 'Cách làm:Tôm cắt đầu, đuôi, rửa sạch, để ráo, ướp gia vị, xả cho thấm. Bắc chảo cho 2 muỗng canh dầu phi tỏi hơi vàng, cho tôm vào xào cho thơm xả, cho nước me vào xào thấm, cho hành tây, đảo đều, tắt lửa.', 10);
INSERT INTO public.recipe_steps VALUES (3313, '2025-11-20 17:11:26.155833', '2025-11-20 17:11:26.155833', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 533, 9, 'Gia vị nấu sốt: 1 muỗng cà phê bột ngọt, 2 muỗng cà phê bột nêm, 3 muỗng cà phê đường, 1 muỗng cà phê tiêu, 2 muỗng cà phê tỏi băm, dầu ăn.', 10);
INSERT INTO public.recipe_steps VALUES (3314, '2025-11-20 17:11:26.442785', '2025-11-20 17:11:26.442785', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 534, 17, '- Luộc chín mỡ, thái hạt lựu. Xay nhuyễn thịt nghêu. Rửa lá dứa, để ráo. Trộn đều thịt nghêu với giò sống, mỡ, 2 thìa cà phê bột nêm, 1 thìa cà phê tiêu và 1 thìa cà phê tỏi băm. Quét 1 lớp dầu ăn vào khuôn nhôm hình chữ nhật, cho nghêu vào hấp khoảng 15 phút. Cắt chả nghêu thành miếng hình chữ nhật ngang 2 cm, dài 4 cm, dày 1 cm. Quấn lá dứa ở giữa. Cho vào lò nướng 10 phút ở nhiệt độ 200 độ C.', 10);
INSERT INTO public.recipe_steps VALUES (3315, '2025-11-20 17:11:26.44508', '2025-11-20 17:11:26.44508', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 534, 18, '- Làm nước chấm: Hòa 3 thìa súp nước mắm với 2 thìa súp đường, 2 thìa súp nước cốt chanh, 1 thìa súp tỏi băm và 1/4 thìa súp ớt băm.', 10);
INSERT INTO public.recipe_steps VALUES (3316, '2025-11-20 17:11:26.447809', '2025-11-20 17:11:26.447809', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 534, 11, '- Gà đã rút xương bỏ đầu, cổ cánh và đùi. Sau đó chà muối, rửa sạch, để ráo. Da heo luộc chín, thái lát mỏng 0,2 cm. Jambon thái lát như da heo. Trộn đều giò sống với da heo, jambon, 1 thìa súp tiêu sọ hạt, 1/2 thìa súp bột nêm, 2 thìa cà phê đường và 2 thìa cà phê nước mắm.', 10);
INSERT INTO public.recipe_steps VALUES (3317, '2025-11-20 17:11:26.450618', '2025-11-20 17:11:26.450618', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 534, 16, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (3318, '2025-11-20 17:11:26.453371', '2025-11-20 17:11:26.453371', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 534, 23, '- Ếch bỏ da, chặt làm tư. Mộc nhĩ ngâm nở mềm, thái sợi nhuyễn, hạt sen luộc chín mềm. Gừng gọt vỏ, thái sợi nhuyễn. Ớt chuông thái miếng vuông, cạnh cỡ đốt ngón tay. Phi thơm tỏi băm, cho ếch vào xào.', 10);
INSERT INTO public.recipe_steps VALUES (3319, '2025-11-20 17:11:26.455521', '2025-11-20 17:11:26.455521', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 534, 8, 'Gà rút xương nhồi
INSERT INTO public.recipe_steps VALUES (3320, '2025-11-20 17:11:26.45911', '2025-11-20 17:11:26.45911', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 534, 19, 'Dùng với bún, rau sống và nước mắm chua ngọt', 10);
INSERT INTO public.recipe_steps VALUES (3321, '2025-11-20 17:11:26.462694', '2025-11-20 17:11:26.462694', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 534, 12, '- Nhồi hỗn hợp trên vào gà, khâu kín lại. Cho gà vào nồi xửng đang sôi hấp khoảng 45 phút. Thỉnh thoảng mở nắp, dùng tăm châm vài lỗ để gà chảy nước và không bị nứt da', 10);
INSERT INTO public.recipe_steps VALUES (3322, '2025-11-20 17:11:26.466353', '2025-11-20 17:11:26.466353', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 534, 6, '- Pha mắm nêm: Hòa 4 thìa súp mắm nêm với 2 thìa súp đường, 2 thìa súp giấm nuôi, dứa băm, ớt băm và 2 thìa cà phê tỏi băm.', 10);
INSERT INTO public.recipe_steps VALUES (3323, '2025-11-20 17:11:26.470175', '2025-11-20 17:11:26.470175', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 534, 10, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (3324, '2025-11-20 17:11:26.474458', '2025-11-20 17:11:26.474458', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 534, 14, 'Nghêu nướng lá dứa
INSERT INTO public.recipe_steps VALUES (3325, '2025-11-20 17:11:26.479337', '2025-11-20 17:11:26.479337', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 534, 9, 'Gia vị: bột nêm, đường, hạt tiêu sọ, nước mắm.', 10);
INSERT INTO public.recipe_steps VALUES (3327, '2025-11-20 17:11:26.493533', '2025-11-20 17:11:26.493533', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 534, 20, 'Ếch gói lá sen
INSERT INTO public.recipe_steps VALUES (3328, '2025-11-20 17:11:26.499025', '2025-11-20 17:11:26.499025', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 534, 1, 'Vịt nướng lá lốt
INSERT INTO public.recipe_steps VALUES (3329, '2025-11-20 17:11:26.502918', '2025-11-20 17:11:26.502918', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 534, 13, 'Dùng nguội với xà lách và bánh mì sandwich nướng bơ tỏi. Ngoài ra, còn có thể dùng với khoai tây luộc xay nhuyễn, xào bơ.', 10);
INSERT INTO public.recipe_steps VALUES (3330, '2025-11-20 17:11:26.506096', '2025-11-20 17:11:26.506096', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 534, 4, '- Thịt vịt chà muối, rửa sạch, để ráo, bỏ xương và da, băm nhuyễn. Luộc chín mỡ heo, thái hạt lựu. Rửa sạch lá lốt, để ráo, băm nhuyễn dứa. Mộc nhĩ ngâm nở mềm, thái sợi nhuyễn. Tỏi, hành tím và ớt băm nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (3331, '2025-11-20 17:11:26.509294', '2025-11-20 17:11:26.509294', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 534, 25, 'Gói hỗn hợp ếch vào lá sen, hấp khoảng 10 phút.', 10);
INSERT INTO public.recipe_steps VALUES (3332, '2025-11-20 17:11:26.513271', '2025-11-20 17:11:26.513271', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 534, 26, 'Dùng với cơm chiên và nước tương ớt.', 10);
INSERT INTO public.recipe_steps VALUES (3333, '2025-11-20 17:11:26.515943', '2025-11-20 17:11:26.515943', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 534, 3, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (3334, '2025-11-20 17:11:26.518797', '2025-11-20 17:11:26.518797', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 534, 15, 'Gia vị: bột nêm, đường, tiêu, nước mắm, dầu ăn.', 10);
INSERT INTO public.recipe_steps VALUES (3335, '2025-11-20 17:11:26.522174', '2025-11-20 17:11:26.522174', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 534, 24, '- Nêm 1 thìa súp bột nêm, 2 thìa súp dầu vừng, 1 thìa súp dầu hào, 1 thìa súp nước mắm, 1 thìa súp đường, 1/2 thìa cà phê tiêu và 1 thìa súp rượu trắng, đảo đều. Sau đó, cho hạt sen, gừng, mộc nhĩ, ớt chuông, 1/2 bát nước dùng và 1,5 thìa cà phê bột năng pha loãng vào, đảo 4 phút.', 10);
INSERT INTO public.recipe_steps VALUES (3336, '2025-11-20 17:11:26.525089', '2025-11-20 17:11:26.525089', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 534, 5, '- Trộn đều thịt vịt với mỡ heo, mộc nhĩ, 1/2 thìa súp nước mắm, 1 thìa súp hành tỏi băm và 2 thìa cà phê bột nêm, 1 thìa cà phê tiêu, 1 thìa súp dầu hào và sả băm. Cho hỗn hợp thịt vịt vào lá lốt cuốn lại. Đặt lên bếp than nướng chín thơm.', 10);
INSERT INTO public.recipe_steps VALUES (3337, '2025-11-20 17:11:26.528826', '2025-11-20 17:11:26.528826', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 534, 2, 'Gia vị: bột nêm, đường, tiêu, giấm, giấm nuôi, nước mắm, mắm nêm, dầu hào.', 10);
INSERT INTO public.recipe_steps VALUES (3338, '2025-11-20 17:11:26.531504', '2025-11-20 17:11:26.531504', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 534, 21, 'Gia vị: bột nêm, bột năng, đường, tiêu, nước mắm, dầu vừng, dầu hào, dầu ăn, rượu trắng.', 10);
INSERT INTO public.recipe_steps VALUES (3339, '2025-11-20 17:11:26.534329', '2025-11-20 17:11:26.534329', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 534, 22, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (3340, '2025-11-20 17:11:26.616568', '2025-11-20 17:11:26.616568', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 535, 3, 'Gỏi bưởi chanh dây
INSERT INTO public.recipe_steps VALUES (3341, '2025-11-20 17:11:26.618153', '2025-11-20 17:11:26.618153', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 535, 5, 'Cho bưởi vào vỏ bưởi, bày tôm, tỏi phi, mực ở ba góc trên mặt, rắc hành phi răm, nước mắm chanh dây cho vào ly có chân, gác tôm và vỏ cam lên miệng ly để trang trí.', 10);
INSERT INTO public.recipe_steps VALUES (3342, '2025-11-20 17:11:26.619817', '2025-11-20 17:11:26.619817', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 535, 2, 'Cách làm:Bưởi lột vỏ, tách múi, bỏ hạt lần lượt cho vào máy ép lấy nước. Trút ra ly, cho một muỗng đường và ít muối vào, khuấy đều, cho thêm ít đá bào vào thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (3343, '2025-11-20 17:11:26.621969', '2025-11-20 17:11:26.621969', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 535, 1, 'Nước ép bưởi
INSERT INTO public.recipe_steps VALUES (3344, '2025-11-20 17:11:26.623584', '2025-11-20 17:11:26.623584', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 535, 6, 'Đặt tất cả vào đĩa vuông, khi ăn mới rưới nước mắm chanh dây vào.', 10);
INSERT INTO public.recipe_steps VALUES (3345, '2025-11-20 17:11:26.6264', '2025-11-20 17:11:26.6264', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 535, 4, 'Cách làm:Bưởi gọt vỏ, tách khéo để lấy vỏ đựng, tỉa răng cưa, tách nhỏ các tép bưởi. Tôm sú luộc chín, lột vỏ, bỏ đầu đuôi. Mực ống trụng chín, xắt sợi. Chanh dây bổ đôi, chừa lại 1/2 trái, còn lại lọc lấy nước pha với 2 muỗng canh đường, 2 muỗng canh nước mắm, 1 muỗng cà phê ớt bằm.', 10);
INSERT INTO public.recipe_steps VALUES (3346, '2025-11-20 17:11:26.882659', '2025-11-20 17:11:26.882659', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 536, 1, 'Tôm cắt đầu, ướp tiêu muối, rang chín.Trứng tráng mỏng, thái chỉ, thịt ba chỉ luộc chín thái miếng mỏng, giò lụa thái mỏng, lạc rang vàng, bỏ vỏ, đập giập. Bún cắt ngắn bằng chiều dài của miếng trứng. Hành hoa bỏ rễ, rửa sạch tẽ lá, chần qua.', 10);
INSERT INTO public.recipe_steps VALUES (3347, '2025-11-20 17:11:26.883688', '2025-11-20 17:11:26.883688', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 536, 2, 'Rau xà lách, húng, mùi rửa sạch, vẩy khô. Chưng dấm bỗng với mật, cho lạc rang vào quấy đều, thêm ít mì chính.', 10);
INSERT INTO public.recipe_steps VALUES (3348, '2025-11-20 17:11:26.885834', '2025-11-20 17:11:26.885834', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 536, 3, 'Xếp một miếng bún vào rau xà lách với ít dấm bỗng đã được chế biến, một miếng thịt ba chỉ, một miếng trứng, một miếng giò, một con tôm, ít rau húng, rau mùi, dùng lá hành đã chần cuốn lại. Khi ăn chấm với nước mắm có tinh dầu cà cuống.', 10);
INSERT INTO public.recipe_steps VALUES (3349, '2025-11-20 17:11:27.238008', '2025-11-20 17:11:27.238008', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 537, 2, 'Nấm hương rửa sạch thái lát, ớt rửa sạch, bỏ hạt, thái thành miếng. Cá hồi và cá thu rửa sạch, lọc xương, cắt thành lát, ướp qua hạt tiêu và bột canh.', 10);
INSERT INTO public.recipe_steps VALUES (3350, '2025-11-20 17:11:27.240792', '2025-11-20 17:11:27.240792', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 537, 1, 'Làm nước tương: Cỏ thơm, chanh, rau húng quế rửa sạch, thái nhỏ. Cắt chanh làm đôi vắt lấy nước cốt chanh. Trộn đều tất cả với nước và bơ. Cho thịt bò và tất cả các nguyên liệu trên vào nồi đun sôi nhỏ lửa đến khi thịt bò chín nhừ và nước suýt có mùi thơm là được.', 10);
INSERT INTO public.recipe_steps VALUES (3351, '2025-11-20 17:11:27.242371', '2025-11-20 17:11:27.242371', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 537, 3, 'Dùng xiên xiên các miếng thịt và rau quả xen kẽ với nhau, sau đó rắc lên trên một ít hạt tiêu và muối, để một lát cho ngấm rồi đem nướng chín. Khi ăn cùng nước tương sẽ cho ta món ăn thật hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (3352, '2025-11-20 17:11:27.370897', '2025-11-20 17:11:27.370897', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 538, 2, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (3353, '2025-11-20 17:11:27.372489', '2025-11-20 17:11:27.372489', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 538, 5, '- Ướp cá với hỗn hợp trên trong 30 phút.', 10);
INSERT INTO public.recipe_steps VALUES (3354, '2025-11-20 17:11:27.373563', '2025-11-20 17:11:27.373563', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 538, 9, 'Ba chỉ cuộn cá hồi nướng
INSERT INTO public.recipe_steps VALUES (3355, '2025-11-20 17:11:27.375428', '2025-11-20 17:11:27.375428', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 538, 16, '- Cá chín tới, vàng đều, cuốn đều nhau.', 10);
INSERT INTO public.recipe_steps VALUES (3356, '2025-11-20 17:11:27.379252', '2025-11-20 17:11:27.379252', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 538, 17, '- Ăn kèm salad , đồ chua.', 10);
INSERT INTO public.recipe_steps VALUES (3357, '2025-11-20 17:11:27.382298', '2025-11-20 17:11:27.382298', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 538, 6, '- Nướng trực tiếp hoặc bỏ lò 220ºC trong 15’ cho chín tới.', 10);
INSERT INTO public.recipe_steps VALUES (3358, '2025-11-20 17:11:27.385685', '2025-11-20 17:11:27.385685', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 538, 4, '- Hành, tỏi ớt xay nhỏ+ gia vị +chilli sauce.', 10);
INSERT INTO public.recipe_steps VALUES (3359, '2025-11-20 17:11:27.387638', '2025-11-20 17:11:27.387638', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 538, 8, 'Lưu ý: Có thể dùng các loại cá khác hoặc mực.', 10);
INSERT INTO public.recipe_steps VALUES (3360, '2025-11-20 17:11:27.389307', '2025-11-20 17:11:27.389307', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 538, 11, '- Cá lọc da, cắt con chì dài 3cm. Ướp muối, tiêu, bột ngọt', 10);
INSERT INTO public.recipe_steps VALUES (3361, '2025-11-20 17:11:27.391429', '2025-11-20 17:11:27.391429', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 538, 15, 'Yêu cầu:', 10);
INSERT INTO public.recipe_steps VALUES (3362, '2025-11-20 17:11:27.393048', '2025-11-20 17:11:27.393048', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 538, 13, '- Cho cá, ớt xanh đỏ, tỏi tây lên miếng ba chỉ. Cuộn tròn và ghim lại bằng tăm. Đem nướng hoặc bỏ lò.', 10);
INSERT INTO public.recipe_steps VALUES (3363, '2025-11-20 17:11:27.394761', '2025-11-20 17:11:27.394761', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 538, 14, '+ Vừa chín tới, bày ra đĩa và trang trí', 10);
INSERT INTO public.recipe_steps VALUES (3364, '2025-11-20 17:11:27.395825', '2025-11-20 17:11:27.395825', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 538, 12, '- Tỏi tây, ớt xanh, ớt đỏ cắt khúc, thái chỉ.', 10);
INSERT INTO public.recipe_steps VALUES (3365, '2025-11-20 17:11:27.397404', '2025-11-20 17:11:27.397404', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 538, 1, 'Cá hồi nướng muối ớt (kiểu Indo)
INSERT INTO public.recipe_steps VALUES (3366, '2025-11-20 17:11:27.399001', '2025-11-20 17:11:27.399001', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 538, 10, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (3367, '2025-11-20 17:11:27.400056', '2025-11-20 17:11:27.400056', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 538, 7, '- Sắp ra đĩa va trang trí. Ăn kèm chilli sauce', 10);
INSERT INTO public.recipe_steps VALUES (3368, '2025-11-20 17:11:27.401153', '2025-11-20 17:11:27.401153', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 538, 3, '- Cá lọc da, cắt miếng vừa.', 10);
INSERT INTO public.recipe_steps VALUES (3369, '2025-11-20 17:11:27.402791', '2025-11-20 17:11:27.402791', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 538, 18, 'Lưu ý: Các nguyên liệu có thể thay đổi: tôm, mực, ức gà…', 10);
INSERT INTO public.recipe_steps VALUES (3370, '2025-11-20 17:11:27.752838', '2025-11-20 17:11:27.752838', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 539, 1, 'Hành lá, ớt băm nhuyễn. Tôm thấm ráo nước, đặt lên thớt dùng dao đập dẹp, trộn với cá thác lác, hành ớt, tiêu và nước mắm ngon, quết đều.', 10);
INSERT INTO public.recipe_steps VALUES (3371, '2025-11-20 17:11:27.754445', '2025-11-20 17:11:27.754445', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 539, 4, 'Món này dùng nóng với tương ớt rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (3372, '2025-11-20 17:11:27.755508', '2025-11-20 17:11:27.755508', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 539, 3, 'Lấy chả tôm quết lên miếng sen. Cho hạt đậu Hà Lan lên trên "lỗ" của sen, lăn sơ qua bột năng rồi đem chiên vàng.', 10);
INSERT INTO public.recipe_steps VALUES (3373, '2025-11-20 17:11:27.757082', '2025-11-20 17:11:27.757082', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 539, 2, 'Củ sen gọt vỏ, cắt miếng, luộc chín.', 10);
INSERT INTO public.recipe_steps VALUES (3374, '2025-11-20 17:11:27.974682', '2025-11-20 17:11:27.974682', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 540, 1, 'Chạch trấu cho vào niêu đất cùng với một chút giấm và muối đậy vung để 15 phút để chạch chết và hết nhớt, sau đó rửa sạch cho hết mùi tanh, cắt đầu, bỏ ruột.', 10);
INSERT INTO public.recipe_steps VALUES (3375, '2025-11-20 17:11:27.976832', '2025-11-20 17:11:27.976832', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 540, 3, 'Cho chạch trấu, trám vào niêu đất cùng với tương Bần, gừng, hành khô. Bắc lên bếp đun nhỏ lửa đến khi cạn nước, thêm chút dầu ăn và hạt tiêu ăn nóng hoặc nguội.', 10);
INSERT INTO public.recipe_steps VALUES (3376, '2025-11-20 17:11:27.978483', '2025-11-20 17:11:27.978483', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 540, 2, 'Trám tách đôi bỏ hột sau đó chần kỹ với nước sôi (giúp trám mềm và loại bỏ nước đen của trám).', 10);
INSERT INTO public.recipe_steps VALUES (3377, '2025-11-20 17:11:27.980118', '2025-11-20 17:11:27.980118', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 540, 4, 'Chạch có mầu nâu đỏ, nổi vị thơm của tương Bần, trám, không tanh. Thịt chạch chắc, xương mềm nhừ, ít nước hơi sánh.', 10);
INSERT INTO public.recipe_steps VALUES (3378, '2025-11-20 17:11:28.191287', '2025-11-20 17:11:28.191287', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 541, 5, 'Cho tất cả các nguyên liệu trên vào thau trộn đều. Trong quá trình trộn cho thêm nước mắm chanh, gừng ớt, đường.', 10);
INSERT INTO public.recipe_steps VALUES (3379, '2025-11-20 17:11:28.193001', '2025-11-20 17:11:28.193001', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 541, 1, 'Để làm món này phải chọn loại bò non để da non và mềm. 1 kg da bò có thể đủ cho 10 -12 người ăn.', 10);
INSERT INTO public.recipe_steps VALUES (3380, '2025-11-20 17:11:28.195123', '2025-11-20 17:11:28.195123', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 541, 3, 'Các nguyên liệu ăn kèm có rau húng quế, rau răm, lá củ hành tươi, ngò thơm, rau bắp chuối, củ hành tây, ít lá chanh non, tất cả thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3381, '2025-11-20 17:11:28.196719', '2025-11-20 17:11:28.196719', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 541, 2, 'Rửa thật sạch da bò nhiều lần bằng nước muối sinh lý 9% và có ít nước chanh tươi. Sau đó, dùng dao lam cạo hoặc nhổ sạch lông và rửa lại 2-3 lần nữa. Da bò khô, sạch, thái mỏng (càng mỏng càng ngon, càng dẻo, giòn). Thắng dầu phụng có hành khô và tỏi thái mỏng giã nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3382, '2025-11-20 17:11:28.198295', '2025-11-20 17:11:28.198295', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 541, 4, 'Đậu phộng rang giòn, giã nhỏ, vài lát gừng giã nhỏ pha với nước chanh tươi (nếu không có chanh thì thay bằng giấm thanh), bột hạt tiêu khô, bột ngọt, ít đường ăn và muối, vài lát ớt đỏ thái mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (3383, '2025-11-20 17:11:28.419549', '2025-11-20 17:11:28.419549', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 542, 2, 'Tôm quết với đầu hành, nước mắm, tiêu cho dai, vo lại thành từng viên nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3384, '2025-11-20 17:11:28.421106', '2025-11-20 17:11:28.421106', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 542, 3, 'Cho nước dùng, tôm viên, bột nêm vào trái bí. Mang hấp đến khi bí chín.', 10);
INSERT INTO public.recipe_steps VALUES (3385, '2025-11-20 17:11:28.422675', '2025-11-20 17:11:28.422675', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 542, 4, 'Dọn cả trái bí ra đĩa, rắc hành tiêu lên mặt.', 10);
INSERT INTO public.recipe_steps VALUES (3386, '2025-11-20 17:11:28.426426', '2025-11-20 17:11:28.426426', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 542, 5, 'Khi ăn dùng muỗng múc phần thịt bí đã chín bên trong.', 10);
INSERT INTO public.recipe_steps VALUES (3387, '2025-11-20 17:11:28.429545', '2025-11-20 17:11:28.429545', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 542, 1, 'Dùng dao vạt ngang trái bí, lấy muỗng múc bỏ phần hột, chừa thịt bí lại.', 10);
INSERT INTO public.recipe_steps VALUES (3388, '2025-11-20 17:11:28.686954', '2025-11-20 17:11:28.686954', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 543, 2, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (3538, '2025-11-20 17:11:36.448468', '2025-11-20 17:11:36.448468', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 572, 5, 'Cà rốt thái hình chân hương', 10);
INSERT INTO public.recipe_steps VALUES (3389, '2025-11-20 17:11:28.688551', '2025-11-20 17:11:28.688551', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 543, 13, 'Tôm sú luộc chín cắt hạt lựu. Các loại quả cắt hạt lựu. Trộn quả, tôm, xốt mayonnaise và gia vị đều nhau. Dùng bánh tráng cho nhân đã trộn vào, nhúng trứng gà, lăn qua bột xù. Rán chả giò ngập dầu, thấy vừa vàng là được.', 10);
INSERT INTO public.recipe_steps VALUES (3390, '2025-11-20 17:11:28.690157', '2025-11-20 17:11:28.690157', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 543, 8, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (3391, '2025-11-20 17:11:28.69224', '2025-11-20 17:11:28.69224', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 543, 11, 'Chả giò hoa quả
INSERT INTO public.recipe_steps VALUES (3392, '2025-11-20 17:11:28.693838', '2025-11-20 17:11:28.693838', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 543, 3, '- Thịt ba chỉ luộc chín cắt sợi. Tôm khô ngâm nước sôi cho nở, xả sạch, để ráo. Mãng cầu xiêm cắt miếng 2 x 3cm, ngâm nước muối, xả sạch, để ráo. Cà rốt, hành tây cắt mỏng tỉa hoa. Ớt sừng cắt sợi.', 10);
INSERT INTO public.recipe_steps VALUES (3393, '2025-11-20 17:11:28.696211', '2025-11-20 17:11:28.696211', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 543, 12, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (3394, '2025-11-20 17:11:28.697808', '2025-11-20 17:11:28.697808', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 543, 4, '- Nước xốt trộn gỏi: nước mắm khuấy tan đều với đường, nước cốt chanh, cho tỏi và ớt băm vào sau cùng.', 10);
INSERT INTO public.recipe_steps VALUES (3395, '2025-11-20 17:11:28.699473', '2025-11-20 17:11:28.699473', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 543, 10, 'Lẩu hoa quả ăn với rau và bún gạo, nước tương.', 10);
INSERT INTO public.recipe_steps VALUES (3396, '2025-11-20 17:11:28.701086', '2025-11-20 17:11:28.701086', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 543, 9, 'Xương heo nấu với củ năng, táo đỏ lấy nước dùng, nêm muối, đường. Tôm, mực, cá, cắt miếng xếp ra đĩa. Các loại quả cắt miếng, xếp ra đĩa. Tuyết nhĩ ngâm nở cho vào nồi nước lẩu. Lẩu nấu sôi cho các thứ quả vào, sau đó cho tôm, cá, mực vào.', 10);
INSERT INTO public.recipe_steps VALUES (3397, '2025-11-20 17:11:28.703239', '2025-11-20 17:11:28.703239', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 543, 6, 'Gỏi mãng cầu ăn với bánh phồng tôm và nước mắm chua ngọt.', 10);
INSERT INTO public.recipe_steps VALUES (3398, '2025-11-20 17:11:28.704846', '2025-11-20 17:11:28.704846', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 543, 5, '- Trộn rau củ, trái cây, rưới nước xốt trộn gỏi vào cho đều. Cho tôm khô lên mặt, rắc mè rang và hành phi.', 10);
INSERT INTO public.recipe_steps VALUES (3399, '2025-11-20 17:11:28.705932', '2025-11-20 17:11:28.705932', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 543, 14, 'Dọn ra đĩa trang trí thêm rau cho bắt mắt.', 10);
INSERT INTO public.recipe_steps VALUES (3400, '2025-11-20 17:11:28.708578', '2025-11-20 17:11:28.708578', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 543, 1, 'Gỏi mãng cầu
INSERT INTO public.recipe_steps VALUES (3401, '2025-11-20 17:11:28.710724', '2025-11-20 17:11:28.710724', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 543, 7, 'Lẩu hoa quả
INSERT INTO public.recipe_steps VALUES (3402, '2025-11-20 17:11:28.974617', '2025-11-20 17:11:28.974617', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 544, 2, 'Cho lươn, thịt ba chỉ ướp riềng, mẻ, hành lá, răm, tiêu, muối, mì chính. Cứ một miếng lươn cho một miếng ba chỉ cuộn với lá nếp, phết mỡ lợn hoặc dầu ăn rồi đem nướng trên than hoa, đến khi dậy mùi thơm, lươn chín vàng đều bỏ ra đĩa, ăn nóng.', 10);
INSERT INTO public.recipe_steps VALUES (3403, '2025-11-20 17:11:28.976293', '2025-11-20 17:11:28.976293', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 544, 1, 'Lươn chọn con to, bụng vàng, khỏe, còn sống, rửa sạch, lọc bỏ xương sống, cắt khúc 7 cm. Thịt ba chỉ thái mỏng dài 3 cm.', 10);
INSERT INTO public.recipe_steps VALUES (3404, '2025-11-20 17:11:29.149742', '2025-11-20 17:11:29.149742', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 545, 1, 'Sườn chặt khúc, ướp muối, tiêu, đường, bột nêm, tỏi, hành để 20 phút cho ngấm. Nho lấy phân nửa băm nhỏ, còn phân nửa cắt đôi bỏ hạt.', 10);
INSERT INTO public.recipe_steps VALUES (3405, '2025-11-20 17:11:29.150957', '2025-11-20 17:11:29.150957', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 545, 2, 'Đổ nước dùng, nho băm, vang đỏ vào nấu với sườn. Khi sườn mềm, bạn thêm bột bắp khuấy với chút nước vào để tạo độ sánh. Sau cùng, cho nho tươi vào, nêm lại cho vừa.', 10);
INSERT INTO public.recipe_steps VALUES (3406, '2025-11-20 17:11:29.512395', '2025-11-20 17:11:29.512395', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 546, 3, 'Bánh mì cắt chiều dọc, dồn thịt gà, xà lách, cà chua, dưa leo vào dùng ngay.', 10);
INSERT INTO public.recipe_steps VALUES (3407, '2025-11-20 17:11:29.513457', '2025-11-20 17:11:29.513457', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 546, 1, 'Ức gà luộc sơ, sau đó rửa sạch bằng nước lạnh. Ướp ức gà với hạt nêm, nước mắm chấm, đường cát trắng và tiêu xay.', 10);
INSERT INTO public.recipe_steps VALUES (3408, '2025-11-20 17:11:29.515039', '2025-11-20 17:11:29.515039', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 546, 2, 'Xào hành tím và tỏi bằm cho thơm. Cho ức gà vào chảo xào cho vàng, sau đó cho nước dừa vào nấu lửa nhỏ đến khi nước xốt sệt lại là được. Xé thịt gà thành những miếng nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3409, '2025-11-20 17:11:29.801739', '2025-11-20 17:11:29.801739', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 547, 2, 'Trộn đều nghêu, thịt nạc, mỡ gáy cắt nhỏ, giò sống, cá thác lác và các gia vị, để thấm khoảng 10 phút.', 10);
INSERT INTO public.recipe_steps VALUES (3410, '2025-11-20 17:11:29.80335', '2025-11-20 17:11:29.80335', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 547, 1, 'Nghêu thịt rửa sạch, hấp chín, cắt nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3411, '2025-11-20 17:11:29.804945', '2025-11-20 17:11:29.804945', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 547, 3, 'Mỡ chài rửa sạch, để ráo, cuốn hỗn hợp đã trộn bằng mỡ chài thành cuốn dài 10 cm, mang hấp chín.', 10);
INSERT INTO public.recipe_steps VALUES (3412, '2025-11-20 17:11:29.805999', '2025-11-20 17:11:29.805999', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 547, 4, 'Nướng cuốn nghêu vàng đều, cắt đôi, dùng lá dứa bọc ngoài, dọn ra dĩa. Nghêu cuốn ăn với bún, rau thơm và nước mắm chua ngọt.', 10);
INSERT INTO public.recipe_steps VALUES (3413, '2025-11-20 17:11:29.996601', '2025-11-20 17:11:29.996601', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 548, 3, 'Cho một ít dầu hành và đậu phộng rang lên mặt thịt bò. Bò nướng kiệu ăn với bún, rau thơm và mắm nêm.', 10);
INSERT INTO public.recipe_steps VALUES (3414, '2025-11-20 17:11:29.998211', '2025-11-20 17:11:29.998211', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 548, 1, 'Cắt thịt bò mỏng 5 x 10 cm. Ướp thịt bò với nước vắt tỏi và hành tím cùng với dầu hào, nước tương, đường, tiêu, húng lủi và dầu ăn, để thấm khoảng 10 phút.', 10);
INSERT INTO public.recipe_steps VALUES (3415, '2025-11-20 17:11:29.999883', '2025-11-20 17:11:29.999883', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 548, 2, 'Trải thịt bò cho thịt xay và củ kiệu vào cuộn thành cuốn tròn. Nướng thịt bò thấy vàng mặt là được.', 10);
INSERT INTO public.recipe_steps VALUES (3416, '2025-11-20 17:11:30.231841', '2025-11-20 17:11:30.231841', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 549, 2, 'Nấm hương, mộc nhĩ ngâm nở, rửa sạch thái chỉ. Hành củ khô băm nhỏ. Hành tươi cắt lấy phần củ và thân rửa sạch trần qua nước sôi.', 10);
INSERT INTO public.recipe_steps VALUES (3417, '2025-11-20 17:11:30.233953', '2025-11-20 17:11:30.233953', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 549, 1, 'Cua bể cọ rửa sạch, bỏ yếm, luộc chín, gỡ lấy thịt và gạch, mai cua cạo rửa sạch, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (3418, '2025-11-20 17:11:30.235013', '2025-11-20 17:11:30.235013', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 549, 4, 'Bày cua ra bát, sắp chân cua và càng cua như con cua còn nguyên cho đẹp đổ nước dùng xăm xắp. Bày hành trần ở trên. Rắc hạt tiêu.', 10);
INSERT INTO public.recipe_steps VALUES (3419, '2025-11-20 17:11:30.236618', '2025-11-20 17:11:30.236618', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 549, 3, 'Thịt lợn giã nhuyễn như giò trộn lẫn một thìa súp nước mắm ngon, mì chính, hạt tiêu, nấm hương, mộc nhĩ, hành khô, thịt cua trộn ở trên vào đem hấp chín. Nước luộc cua lọc lấy nước trong nêm mắm, muối, mì chính, đun sôi.', 10);
INSERT INTO public.recipe_steps VALUES (3420, '2025-11-20 17:11:30.408793', '2025-11-20 17:11:30.408793', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 550, 6, 'Cách làm:Rửa sạch xương và sườn lợn rồi hầm nhỏ lửa với 1,5 lít nước trong khoảng 20 phút. Cho cà rốt, củ cải cắt lát, táo tau, kỳ tử, sâm vào. Nêm nửa thìa muối, 1 thìa nước mắm, 1 thìa cà phê bột nêm rồi đun thêm 15 phút. Thịt lợn rửa sạch, thái lát mỏng, đậu hũ thái miếng vuông. Rửa tôm, nấm, đậu hũ, xếp ra đĩa. Khi ăn, cho các nguyên liệu vào nồi lẩu.', 10);
INSERT INTO public.recipe_steps VALUES (3421, '2025-11-20 17:11:30.410465', '2025-11-20 17:11:30.410465', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 550, 1, 'Salad nấm kim châm
INSERT INTO public.recipe_steps VALUES (3422, '2025-11-20 17:11:30.412049', '2025-11-20 17:11:30.412049', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 550, 2, 'Cách làm:Thịt thăn luộc chín, thái chỉ. Dưa chuột, cà rốt, thái chỉ trộn lẫn nước salad pha sẵn. Bóp nhẹ, đều tay sao cho nước salad ngấm đều vào dưa chuột, cà rốt. Cho thêm nấm kim trâm đã được chần qua nước sôi rồi trộn đều. Rắc rau mùi, thịt thăn thái chỉ lên trên.', 10);
INSERT INTO public.recipe_steps VALUES (3423, '2025-11-20 17:11:30.413167', '2025-11-20 17:11:30.413167', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 550, 4, 'Cách làm:Nấm canba nhặt kỹ, rửa sạch, trứng đánh đều và đảo qua mỡ. Đảo nấm canba và ớt xanh qua mỡ xôi đến khi có mùi thơm của nấm và ớt thì lấy ra trộn đều với trứng gà. Thịt lợn hun khói thái nhỏ, đảo qua chảo mỡ sôi đến khi có mùi thơm thì cho cơm vào đảo đều. Tiếp theo cho nấm canba, ớt, trứng gà vào đảo cùng với cơm và thịt đến khi cơm có mùi thơm hấp dẫn là được.', 10);
INSERT INTO public.recipe_steps VALUES (3424, '2025-11-20 17:11:30.415314', '2025-11-20 17:11:30.415314', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 550, 5, 'Lẩu nấm bụng dê
INSERT INTO public.recipe_steps VALUES (3425, '2025-11-20 17:11:30.416358', '2025-11-20 17:11:30.416358', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 550, 3, 'Cơm rang nấm canba
INSERT INTO public.recipe_steps VALUES (3426, '2025-11-20 17:11:30.761914', '2025-11-20 17:11:30.761914', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 551, 4, 'Dọn thịt gà xào ra đĩa oval lớn, trang trí các loại nấm xung quanh, có thể rắc thêm gừng, ớt thái sợi và ngò lên trên thịt gà. Đun sôi nước lẩu, dùng đến đâu thì thả thịt gà và nấm vào. Dùng nóng với bún gạo và nước mắm ớt.', 10);
INSERT INTO public.recipe_steps VALUES (3427, '2025-11-20 17:11:30.763509', '2025-11-20 17:11:30.763509', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 551, 2, 'Xương gà đun với 3 lít nước khoảng 30 phút để làm nước lẩu. Hành ba rô cắt xéo cho vào nồi, nêm bột canh, bột ngọt, nước mắm, muối, dầu ăn vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (3428, '2025-11-20 17:11:30.76537', '2025-11-20 17:11:30.76537', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 551, 3, 'Các loại nấm rửa sạch. Đầu hành cắt khúc 5 cm. Bún gạo ngâm nước cho mềm. Hành tím cắt nhỏ, phi với dầu ăn để rắc lên bún gạo.', 10);
INSERT INTO public.recipe_steps VALUES (3429, '2025-11-20 17:11:30.766961', '2025-11-20 17:11:30.766961', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 551, 1, 'Gà chặt khúc 5 cm ướp với bột nêm và sa tế tôm, để khoảng 15 phút cho thấm, xào với tỏi bằm và hành tím bằm cho thịt vừa gần chín.', 10);
INSERT INTO public.recipe_steps VALUES (3430, '2025-11-20 17:11:30.910832', '2025-11-20 17:11:30.910832', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 552, 1, 'Mực làm sạch, ớt chuông cắt hạt lựu, nấm đông cô thái sợi. Trộn đều ớt, nấm vào xôi cùng bột nêm.', 10);
INSERT INTO public.recipe_steps VALUES (3431, '2025-11-20 17:11:30.912414', '2025-11-20 17:11:30.912414', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 552, 2, 'Nhồi xôi đã trộn vào thân mực. Hấp chín mực, rồi chiên vàng. Cắt mực thành khoanh, trang trí ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (3432, '2025-11-20 17:11:30.914012', '2025-11-20 17:11:30.914012', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 552, 3, 'Mực nhồi xôi ăn với tương ớt.', 10);
INSERT INTO public.recipe_steps VALUES (3433, '2025-11-20 17:11:31.123063', '2025-11-20 17:11:31.123063', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 553, 1, 'Cá đánh vẩy, làm ruột, rửa sạch để ráo nước rồi cho vào nồi đất cùng với các loại gia vị xốc đều lên, ướp 15 phút.', 10);
INSERT INTO public.recipe_steps VALUES (3434, '2025-11-20 17:11:31.124664', '2025-11-20 17:11:31.124664', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 553, 2, 'Để cá lên bếp nấu sôi kỹ, cho nước dừa vào nấu sôi lại, hạ lửa thật nhỏ kho cá liu riu trong khoảng 3 tiếng đồng hồ. Khi mở nắp sẽ thấy mình cá vàng óng nước kho, xương mềm nhừ.', 10);
INSERT INTO public.recipe_steps VALUES (3435, '2025-11-20 17:11:31.126257', '2025-11-20 17:11:31.126257', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 553, 3, 'Nếu kho bằng bếp củi, ủ nồi cá trong tro rải trấu lên trên cho cháy âm ỷ một đêm là ngon nhất.', 10);
INSERT INTO public.recipe_steps VALUES (3436, '2025-11-20 17:11:31.480847', '2025-11-20 17:11:31.480847', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 554, 2, 'Nấm mèo ngâm nước ấm cho nở, bỏ chân, xắt làm 3, 4 miếng. Trụng qua hạt sen và đậu phộng cho hết nước thâm, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (3437, '2025-11-20 17:11:31.482459', '2025-11-20 17:11:31.482459', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 554, 3, 'Bày chân giò vào âu chuyên dụng, cho hạt sen, đậu phộng, nấm mèo, mía, đổ nước xâm xấp, bọc giấy bảo quản, cho vào lò vi sóng, đặt chế độ micro khoảng 25-30 phút. Trang trí với ớt và hành tươi.', 10);
INSERT INTO public.recipe_steps VALUES (3438, '2025-11-20 17:11:31.484062', '2025-11-20 17:11:31.484062', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 554, 1, 'Giò heo làm sạch, chặt miếng cỡ bao diêm, ướp với sả, giềng, hành khô, hạt nêm, đường khoảng 1 giờ.', 10);
INSERT INTO public.recipe_steps VALUES (3439, '2025-11-20 17:11:31.746782', '2025-11-20 17:11:31.746782', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 555, 5, 'Món này ăn kèm với dưa leo, đồ chua và tương ớt.', 10);
INSERT INTO public.recipe_steps VALUES (3440, '2025-11-20 17:11:31.747841', '2025-11-20 17:11:31.747841', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 555, 3, 'Thấm đùi ếch đã nhồi vào phần gia vị còn lại.', 10);
INSERT INTO public.recipe_steps VALUES (3441, '2025-11-20 17:11:31.750017', '2025-11-20 17:11:31.750017', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 555, 2, 'Dùng dao rạch khéo léo một đường dài trên đùi. Nhồi thịt vào chỗ trống của đùi ếch.', 10);
INSERT INTO public.recipe_steps VALUES (3442, '2025-11-20 17:11:31.752176', '2025-11-20 17:11:31.752176', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 555, 4, 'Cho thịt ếch vào lò nướng đến khi vàng đều là được.', 10);
INSERT INTO public.recipe_steps VALUES (3443, '2025-11-20 17:11:31.753775', '2025-11-20 17:11:31.753775', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 555, 1, 'Trộn chung thịt heo với tỏi bằm, giấm, đường nâu và gia vị muối, tiêu.', 10);
INSERT INTO public.recipe_steps VALUES (3444, '2025-11-20 17:11:31.937563', '2025-11-20 17:11:31.937563', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 556, 3, 'Cho củ sen vào hầm tiếp 10 phút nữa để củ sen và giò mềm, nêm với hạt nêm cho vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (3445, '2025-11-20 17:11:31.939851', '2025-11-20 17:11:31.939851', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 556, 1, 'Móng giò làm sạch, chặt miếng vừa ăn. Củ sen bỏ vỏ, cắt lát ngâm trong nước có vắt chanh cho trắng. Đỗ đen vo sạch, cho vào nồi nấu chín, vớt ra bát nghiền nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3446, '2025-11-20 17:11:31.940882', '2025-11-20 17:11:31.940882', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 556, 2, 'Gừng và đầu hành băm nhỏ. Cho một muỗng canh dầu vào nồi phi với gừng và hành cho thơm, cho đỗ đen vào xào, cho tiếp móng giò và 1 muỗng canh rượu trắng, 1 muỗng canh nước tương vào xào cho móng giò săn lại. Cho 2 tô nước vào nấu sôi, hạ nhỏ lửa hầm 30 phút.', 10);
INSERT INTO public.recipe_steps VALUES (3447, '2025-11-20 17:11:31.942475', '2025-11-20 17:11:31.942475', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 556, 4, 'Múc ra tô, nêm hành lá và tiêu ăn nóng với cơm.', 10);
INSERT INTO public.recipe_steps VALUES (3448, '2025-11-20 17:11:32.502548', '2025-11-20 17:11:32.502548', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 557, 1, 'Thịt bò và gân thăn thái vừa miếng ướp với hành tỏi băm nhỏ, 3 thìa canh nước sốt cà chua, 2 thìa canh bột gia vị bò kho, 2 viên bò kho, 1 thìa canh rượu vang, hạt tiêu.', 10);
INSERT INTO public.recipe_steps VALUES (3449, '2025-11-20 17:11:32.504158', '2025-11-20 17:11:32.504158', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 557, 4, 'Tiếp đó, bắc chảo lên bếp, phi thơm hành tỏi với bơ rồi cho bột mỳ đã hòa tan với một chút nước vào xào vàng rồi cho vào nồi sốt vang, đun sôi. Nêm nếm và cho 1 thìa canh rượu vang và rau húng láng, mùi ta, hành thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3450, '2025-11-20 17:11:32.50577', '2025-11-20 17:11:32.50577', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 557, 3, 'Bắc một cái nồi khác phi thơm hành tỏi với 1 chút bơ, sau đó phi cà chua, rồi trút thịt đã ướp vào xào thơm. Cho nước sôi vào nồi + khoai tây, cà rốt, nấm, nếu dùng nồi áp suất thì để 15 phút bắc ra.', 10);
INSERT INTO public.recipe_steps VALUES (3451, '2025-11-20 17:11:32.507925', '2025-11-20 17:11:32.507925', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 557, 2, 'Khoai tây thái móng giò (như để nấu canh), cà rốt tỉa hoa xắt khúc dầy, nấm bổ đôi, tất cả cho vào xào với 1 chút bơ và gia vị thật kỹ cho ngấm mắm muối.', 10);
INSERT INTO public.recipe_steps VALUES (3452, '2025-11-20 17:11:32.757963', '2025-11-20 17:11:32.757963', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 558, 1, 'Bước 1: Hấp gà', 10);
INSERT INTO public.recipe_steps VALUES (3453, '2025-11-20 17:11:32.759562', '2025-11-20 17:11:32.759562', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 558, 6, 'Để cho nước trong nồi sôi, thêm khoảng 1/2 muỗng cà phê muối và 1 muỗng súp dầu ăn rồi mới cho cải thìa vào trụng để cải có màu xanh mướt đẹp mắt.', 10);
INSERT INTO public.recipe_steps VALUES (3454, '2025-11-20 17:11:32.761151', '2025-11-20 17:11:32.761151', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 558, 7, 'Bước 3: Trang trí', 10);
INSERT INTO public.recipe_steps VALUES (3455, '2025-11-20 17:11:32.762743', '2025-11-20 17:11:32.762743', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 558, 2, 'Rải đều 1 kg muối hột dưới nồi đất. Lưu ý là gà không cần ướp với gia vị gì. Đặt nguyên con gà lên trên lớp muối, không cần đổ thêm nước vào.', 10);
INSERT INTO public.recipe_steps VALUES (3456, '2025-11-20 17:11:32.764388', '2025-11-20 17:11:32.764388', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 558, 4, 'Muối giữ nóng rất lâu, sức nóng được giữ kín trong nồi đất sẽ làm cho gà chín mà không cần đổ nước.', 10);
INSERT INTO public.recipe_steps VALUES (3457, '2025-11-20 17:11:32.765973', '2025-11-20 17:11:32.765973', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 558, 5, 'Bước 2: Trụng cải thìa', 10);
INSERT INTO public.recipe_steps VALUES (3458, '2025-11-20 17:11:32.767559', '2025-11-20 17:11:32.767559', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 558, 8, 'Xếp cọng cải xoay vào trong tâm đĩa, phần lá hướng ra ngoài vành đĩa, cứ thế, xếp xoay tròn cho đến hết đĩa. Thịt gà chín chặt ra và xếp lên đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (3459, '2025-11-20 17:11:32.769244', '2025-11-20 17:11:32.769244', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 558, 3, 'Rải rau răm lên mình gà rồi dùng lá chuối phủ kín (đậy càng kín thì gà càng nhanh chín). Sau cùng, đậy nắp nồi lại và đặt lên bếp, bật lửa. Sau 20 phút gà sẽ chín.', 10);
INSERT INTO public.recipe_steps VALUES (3460, '2025-11-20 17:11:33.006446', '2025-11-20 17:11:33.006446', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 559, 2, 'Cho 2 thìa súp dầu ăn vào chảo, cho tỏi vào phi thơm, rồi cho tiếp ớt, nước mắm và đường vào, khuấy cho tan đường.', 10);
INSERT INTO public.recipe_steps VALUES (3461, '2025-11-20 17:11:33.009557', '2025-11-20 17:11:33.009557', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 559, 1, 'Cho ốc vào nước sôi luộc sơ, tách bỏ một bên vỏ, chừa lại một bên vỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3462, '2025-11-20 17:11:33.012244', '2025-11-20 17:11:33.012244', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 559, 3, 'Khi hỗn hợp gia vị đã sánh lại, cho ốc vào và xốc đều lên cho thấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (3463, '2025-11-20 17:11:33.016533', '2025-11-20 17:11:33.016533', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 559, 4, 'Cho ra đĩa, dùng nóng.', 10);
INSERT INTO public.recipe_steps VALUES (3464, '2025-11-20 17:11:33.258567', '2025-11-20 17:11:33.258567', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 560, 1, 'Giăm bông thái con chì. Tai lợn sơ chế sạch, luộc chín', 10);
INSERT INTO public.recipe_steps VALUES (3465, '2025-11-20 17:11:33.260704', '2025-11-20 17:11:33.260704', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 560, 2, 'Gà làm sạch, rút xương, để nguyên con. Ướp tiêu, mì chính, rượu.', 10);
INSERT INTO public.recipe_steps VALUES (3466, '2025-11-20 17:11:33.262952', '2025-11-20 17:11:33.262952', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 560, 5, 'Khi ăn cắt miếng.', 10);
INSERT INTO public.recipe_steps VALUES (3467, '2025-11-20 17:11:33.265177', '2025-11-20 17:11:33.265177', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 560, 3, 'Lấy 1/2 số giò phết vào gà. Tai lợn luộc chín xếp tiếp lên rồi tiếp tục phết nốt số giò còn lại lên trên. Xếp giăm bông thái con chì dài dọc thân gà.', 10);
INSERT INTO public.recipe_steps VALUES (3468, '2025-11-20 17:11:33.266795', '2025-11-20 17:11:33.266795', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 560, 4, 'Cuối cùng, gói tròn lại (sao cho phần da gà bao xung quanh) bằng một khăn vải trắng sạch (kích thước 50 x 50 cm), quấn chặt, dùng dây vải 4,5 m buộc chặt rồi đem hấp chín (khoảng 30-45 phút). Cuối cùng, tháo dây, bó lại cho chặt.', 10);
INSERT INTO public.recipe_steps VALUES (3469, '2025-11-20 17:11:33.545123', '2025-11-20 17:11:33.545123', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 561, 5, 'Pha một bát nước gồm dấm, đường, tỏi, ớt, nước mắm vị cân đối.', 10);
INSERT INTO public.recipe_steps VALUES (3470, '2025-11-20 17:11:33.547233', '2025-11-20 17:11:33.547233', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 561, 6, 'Cho các nguyên liệu đã trộn trở lại khay, cho tiếp 3/4 thịt lợn, lạc, vừng, đổ nốt bát nước đã pha trộn đều các nguyên liệu, cho rau thơm vào trộn đều, bày ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (3471, '2025-11-20 17:11:33.548856', '2025-11-20 17:11:33.548856', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 561, 1, 'Đu đủ, cà rốt rửa bằng nước sôi để nguội, vớt ra rổ để ráo. Dưa chuột rửa sạch bổ đôi, bỏ ruột, thái vát.', 10);
INSERT INTO public.recipe_steps VALUES (3472, '2025-11-20 17:11:33.551012', '2025-11-20 17:11:33.551012', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 561, 2, 'Giá đỗ rửa sạch để ráo nước, rau thơm, mùi, kinh giới nhặt rửa sạch, cắt khúc ngắn.', 10);
INSERT INTO public.recipe_steps VALUES (3473, '2025-11-20 17:11:33.552656', '2025-11-20 17:11:33.552656', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 561, 7, 'Trên đĩa nộm bày trứng, thịt, giò, lạc mỗi thứ một góc, xen kẽ bày rau thơm, ớt tỉa hoa cho đẹp.', 10);
INSERT INTO public.recipe_steps VALUES (3474, '2025-11-20 17:11:33.554786', '2025-11-20 17:11:33.554786', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 561, 3, 'Thịt lợn thái mỏng, ướp muối, đường, tiêu để ngấm, rán vàng rồi để nguội và thái chân hương. Vừng, lạc rang thơm, bóc vỏ, giã dập.', 10);
INSERT INTO public.recipe_steps VALUES (3475, '2025-11-20 17:11:33.55713', '2025-11-20 17:11:33.55713', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 561, 4, 'Đu đủ, cà rốt, dưa chuột, giá đỗ cho vào khay, dội 1/2 bát nước đã pha vào trộn đều để ngấm 5 phút rồi vớt ra để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (3476, '2025-11-20 17:11:33.693035', '2025-11-20 17:11:33.693035', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 562, 2, 'Giò lụa thái như thịt ba chỉ.', 10);
INSERT INTO public.recipe_steps VALUES (3477, '2025-11-20 17:11:33.694684', '2025-11-20 17:11:33.694684', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 562, 4, 'Tôm luộc chín bóc vỏ thái mỏng làm đôi (theo chiều dọc)', 10);
INSERT INTO public.recipe_steps VALUES (3478, '2025-11-20 17:11:33.696273', '2025-11-20 17:11:33.696273', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 562, 1, 'Thịt ba chỉ luộc chín thái miếng bằng đầu đũa dài khoảng 15cm.', 10);
INSERT INTO public.recipe_steps VALUES (3479, '2025-11-20 17:11:33.697874', '2025-11-20 17:11:33.697874', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 562, 3, 'Trứng tráng mỏng thái chỉ.', 10);
INSERT INTO public.recipe_steps VALUES (3480, '2025-11-20 17:11:33.699483', '2025-11-20 17:11:33.699483', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 562, 7, 'Khi ăn chấm với nước mắm có pha thêm chanh, ớt, tỏi, đường, nước lọc, vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (3481, '2025-11-20 17:11:33.701042', '2025-11-20 17:11:33.701042', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 562, 6, 'Bánh đa nem ủ mềm, cắt miếng hình chữ nhật khoảng 10 x 20 cm. Cho tất cả nguyên liệu thịt, tôm, giò, rau sống, rau thơm vào cuộn tròn lại như chiếc nem.', 10);
INSERT INTO public.recipe_steps VALUES (3482, '2025-11-20 17:11:33.70267', '2025-11-20 17:11:33.70267', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 562, 5, 'Rau xà lách, rau thơm rửa sạch để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (3483, '2025-11-20 17:11:33.991892', '2025-11-20 17:11:33.991892', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 563, 3, 'Dọn kèm thịt gà với nước tương hoặc muối tiêu chanh và bánh mì nếu muốn ăn no.', 10);
INSERT INTO public.recipe_steps VALUES (3484, '2025-11-20 17:11:33.993475', '2025-11-20 17:11:33.993475', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 563, 1, 'Ướp gia vị trong và ngoài con gà gồm: 2 muỗng canh tỏi băm, 2 muỗng canh nước tương, 1 muỗng canh đường, 1 muỗng cà phê tiêu và 1 muỗng cà phê hạt nêm từ thịt. Để 1 giờ cho thấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (3485, '2025-11-20 17:11:33.995096', '2025-11-20 17:11:33.995096', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 563, 2, 'Cho nguyên con gà vào nồi, để lửa riu riu 1 phút, mở hé nắp nồi cho vào 200 ml rượu nếp, đậy kín nắp lại. Tiếp tục nấu trên lửa riu riu trong vòng 15 - 20 phút thì gà sẽ chín mềm và thấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (3486, '2025-11-20 17:11:34.156673', '2025-11-20 17:11:34.156673', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 564, 3, 'Hành khô băm nhỏ trộn lẫn với nấm hương, giò sống, cốm, hạt tiêu rồi nhồi vào cánh gà, đem hấp khoảng 10 phút, lấy ra để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (3487, '2025-11-20 17:11:34.158286', '2025-11-20 17:11:34.158286', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 564, 5, 'Yêu cầu: Cánh gà không vỡ, thơm mùi cốm.', 10);
INSERT INTO public.recipe_steps VALUES (3488, '2025-11-20 17:11:34.159893', '2025-11-20 17:11:34.159893', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 564, 4, 'Lấy lòng đỏ trứng gà đánh tan rồi nhúng cánh gà vào, sau đó lăn qua cốm cho dính đều. Rán vàng hoặc rán cho cốm nở màu trắng là được.', 10);
INSERT INTO public.recipe_steps VALUES (3489, '2025-11-20 17:11:34.161326', '2025-11-20 17:11:34.161326', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 564, 2, 'Nấm hương ngâm nở, băm nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3490, '2025-11-20 17:11:34.162925', '2025-11-20 17:11:34.162925', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 564, 1, 'Cánh gà rửa sạch, cắt làm 3, bỏ phần cuối, lọc bỏ xương.', 10);
INSERT INTO public.recipe_steps VALUES (3491, '2025-11-20 17:11:34.318929', '2025-11-20 17:11:34.318929', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 565, 2, 'Trộn gia vị, mì chính, hạt tiêu, húng lìu và 1/2 hành khô băm nhỏ vào một bát, đem tẩm ướp vào bụng gà.', 10);
INSERT INTO public.recipe_steps VALUES (3492, '2025-11-20 17:11:34.320807', '2025-11-20 17:11:34.320807', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 565, 4, 'Đun mỡ nóng già, phi tiếp số hành khô còn lại vớt ra để riêng. Thả gà vào quay vàng đều rồi vớt chuyển sang xoong cùng một chút nước dùng, gia vị, mì chính, hành củ phi và nấm hương, đậy vung om nhỏ lửa.', 10);
INSERT INTO public.recipe_steps VALUES (3493, '2025-11-20 17:11:34.322421', '2025-11-20 17:11:34.322421', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 565, 5, 'Khi gà chín mềm, vớt gà ra để nguội, chặt miếng bày lên đĩa, ở dưới bày rau xà lách, múc nước om và nấm hương rưới đều lên trên gà, rắc hạt tiêu, bày rau thơm, cà chua, dưa chuột, ớt trang trí xung quanh.', 10);
INSERT INTO public.recipe_steps VALUES (3494, '2025-11-20 17:11:34.324566', '2025-11-20 17:11:34.324566', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 565, 1, 'Gà sơ chế sạch, mổ moi, bỏ nội tạng, rửa sạch để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (3495, '2025-11-20 17:11:34.32566', '2025-11-20 17:11:34.32566', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 565, 3, 'Lấy khăn lau khô da gà, hoà mạch nha vào nước nóng khoảng 400 độ C xoa lên da gà, để 15 phút sau đó xoa tiếp lần thứ hai.', 10);
INSERT INTO public.recipe_steps VALUES (3496, '2025-11-20 17:11:34.543564', '2025-11-20 17:11:34.543564', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 566, 3, 'Cà rốt, su hào gọt vỏ thái chỉ ướp muối để 10 phút vắt bớt nước.', 10);
INSERT INTO public.recipe_steps VALUES (3497, '2025-11-20 17:11:34.545164', '2025-11-20 17:11:34.545164', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 566, 1, 'Miến ngâm nở, rửa sạch để ráo nước, cắt khúc ngắn khoảng 10 cm.', 10);
INSERT INTO public.recipe_steps VALUES (3498, '2025-11-20 17:11:34.546743', '2025-11-20 17:11:34.546743', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 566, 5, 'Pha nước lọc, đường, chanh, ớt cho vừa trộn vào trứng, thịt, tôm, su hào, cà rốt và miến (đã chần qua nước sôi) và rau mùi thái nhỏ. Trình bày ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (3499, '2025-11-20 17:11:34.548317', '2025-11-20 17:11:34.548317', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 566, 4, 'Thịt ba chỉ luộc chín thái mỏng. Trứng tráng mỏng, thái chỉ. Lạc rang giã dập.', 10);
INSERT INTO public.recipe_steps VALUES (3500, '2025-11-20 17:11:34.549984', '2025-11-20 17:11:34.549984', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 566, 2, 'Tôm luộc chín, bóc vỏ bỏ đầu thái mỏng làm đôi theo chiều dài của tôm, ướp muối.', 10);
INSERT INTO public.recipe_steps VALUES (3501, '2025-11-20 17:11:34.863362', '2025-11-20 17:11:34.863362', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 567, 2, 'Giã ớt và tỏi, hòa với nước mắm, đường, dấm, nước lọc. Nếu thích vị đậm, bạn có thể không cho thêm nước lọc.', 10);
INSERT INTO public.recipe_steps VALUES (3569, '2025-11-20 17:11:39.038076', '2025-11-20 17:11:39.038076', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 579, 2, 'Cho dầu vào chảo phi thơm hành khô băm nhỏ, sau đó để nguội cho hành thái nhỏ vào trộn đều, để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (3502, '2025-11-20 17:11:34.865621', '2025-11-20 17:11:34.865621', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 567, 3, 'Cho thịt bò vào lọ, đổ nước mắm vào ngập thịt, thêm hạt tiêu vào. Nếu trời rét, ngâm trong 3 ngày là ăn được, trời nóng chỉ cần một ngày. Có thể bảo quản trong tủ lạnh vài tuần.', 10);
INSERT INTO public.recipe_steps VALUES (3503, '2025-11-20 17:11:34.866691', '2025-11-20 17:11:34.866691', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 567, 4, 'Thái mỏng khi ăn. Miếng thịt bắp bò giòn có vị đậm và mùi thơm của mắm, ớt, tỏi, rất kích thích vị giác, dễ ăn, lâu ngán.', 10);
INSERT INTO public.recipe_steps VALUES (3504, '2025-11-20 17:11:34.8686', '2025-11-20 17:11:34.8686', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 567, 1, 'Thịt bò lọc sạch mỡ để khi ngâm không bị nổi váng, luộc chín, để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (3505, '2025-11-20 17:11:35.317331', '2025-11-20 17:11:35.317331', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 568, 4, 'Bắc nồi nước cua lên bếp, thêm vào một muỗng cà phê hạt nêm. Để lửa nhỏ nấu cho thịt cua nổi lên trên mặt nước cua. Vớt thịt cua để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (3506, '2025-11-20 17:11:35.319216', '2025-11-20 17:11:35.319216', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 568, 2, 'Me dầm với nước sôi để lấy nước me.', 10);
INSERT INTO public.recipe_steps VALUES (3507, '2025-11-20 17:11:35.320899', '2025-11-20 17:11:35.320899', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 568, 1, 'Cua đồng rửa sạch, xay nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (3508, '2025-11-20 17:11:35.322479', '2025-11-20 17:11:35.322479', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 568, 5, 'Xào sả bào, tỏi bằm cho thơm. Thêm gạch cua vào đảo đều.', 10);
INSERT INTO public.recipe_steps VALUES (3509, '2025-11-20 17:11:35.324595', '2025-11-20 17:11:35.324595', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 568, 6, 'Cho tiếp nước cua vào đun sôi lên, nêm với phần hạt nêm còn lại, nước mắm chấm và nước me cho vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (3510, '2025-11-20 17:11:35.326204', '2025-11-20 17:11:35.326204', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 568, 8, 'Dọn ăn kèm với bún tươi, rau sống và nước mắm ớt.', 10);
INSERT INTO public.recipe_steps VALUES (3511, '2025-11-20 17:11:35.327968', '2025-11-20 17:11:35.327968', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 568, 7, 'Thêm cà chua và phần thịt cua trở lại nồi lẩu.', 10);
INSERT INTO public.recipe_steps VALUES (3512, '2025-11-20 17:11:35.330122', '2025-11-20 17:11:35.330122', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 568, 3, 'Hòa tan thịt cua với 1,2 lít nước lọc, lược ba lần cho sạch cát và xương cua đồng.', 10);
INSERT INTO public.recipe_steps VALUES (3513, '2025-11-20 17:11:35.630111', '2025-11-20 17:11:35.630111', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 569, 2, 'Thịt nạc vai, tôm, gan vịt, cá tất cả giã nhỏ rồi viên như quả táo.', 10);
INSERT INTO public.recipe_steps VALUES (3514, '2025-11-20 17:11:35.632295', '2025-11-20 17:11:35.632295', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 569, 1, 'Vịt làm sạch, lọc lấy thịt, thái hạt lựu, ướp tiêu, muối, mỳ chính, hành thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3515, '2025-11-20 17:11:35.634478', '2025-11-20 17:11:35.634478', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 569, 3, 'Củ ấu luộc chín lấy nhân.', 10);
INSERT INTO public.recipe_steps VALUES (3516, '2025-11-20 17:11:35.636106', '2025-11-20 17:11:35.636106', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 569, 5, 'Khi làm xong, cam đều quả lành lặn, nổi vị thơm của cam, vị hơi ngọt, béo bùi không đắng.', 10);
INSERT INTO public.recipe_steps VALUES (3517, '2025-11-20 17:11:35.63822', '2025-11-20 17:11:35.63822', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 569, 4, 'Phi thơm hành cho thịt vịt vào xào lăn, chế nước dùng xăm xắp, đun sôi nhỏ lửa cho thịt chín mềm. Sau đó, cho thịt viên và củ ấu vào. Cam khoét mũ, lấy nước cho vào nồi thịt, nêm vừa gia vị. Sau đó múc đầy nhân vào vỏ quả cam, đậy mũ lại rồi lấy lá canh xanh để trang trí.', 10);
INSERT INTO public.recipe_steps VALUES (3518, '2025-11-20 17:11:35.639826', '2025-11-20 17:11:35.639826', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 569, 6, 'Có thể thay củ ấu bằng hạt sen đã luộc chín mềm.', 10);
INSERT INTO public.recipe_steps VALUES (3519, '2025-11-20 17:11:35.8343', '2025-11-20 17:11:35.8343', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 570, 9, 'Sau khi làm sốt xong cho các nguyên liệu trên trộn đều cùng với nước sốt.', 10);
INSERT INTO public.recipe_steps VALUES (3520, '2025-11-20 17:11:35.835896', '2025-11-20 17:11:35.835896', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 570, 1, 'Khoai tây gọt vỏ luộc chín, thái lát mỏng 1,5 x 1,5 cm.', 10);
INSERT INTO public.recipe_steps VALUES (3521, '2025-11-20 17:11:35.836971', '2025-11-20 17:11:35.836971', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 570, 7, 'Dưa chuột muối + thịt nguội thái lát mỏng như trên.', 10);
INSERT INTO public.recipe_steps VALUES (3522, '2025-11-20 17:11:35.838574', '2025-11-20 17:11:35.838574', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 570, 2, 'Táo gọt vỏ thái lát mỏng như khoai tây.', 10);
INSERT INTO public.recipe_steps VALUES (3523, '2025-11-20 17:11:35.840157', '2025-11-20 17:11:35.840157', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 570, 3, 'Pha nước ngâm táo tỉ lệ 2 lít nước + 1 quả chanh vắt lấy nước cốt + 50 g đường + 1/2 thìa cà phê muối.', 10);
INSERT INTO public.recipe_steps VALUES (3524, '2025-11-20 17:11:35.841217', '2025-11-20 17:11:35.841217', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 570, 4, 'Ngâm táo đã thái vào hỗn hợp trên khoảng 15 phút rồi vớt ra để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (3525, '2025-11-20 17:11:35.842958', '2025-11-20 17:11:35.842958', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 570, 6, 'Trứng gà luộc chín thái lát mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (3526, '2025-11-20 17:11:35.844033', '2025-11-20 17:11:35.844033', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 570, 8, 'Làm nước sốt: Vắt lấy nước 1/4 chanh + 1 thìa cà phê đường + 1thìa cà phê mù tạt vàng. Cho sốt mayonnaise vào hỗn hộp trên trộn đều (nêm gia vị vừa ăn).', 10);
INSERT INTO public.recipe_steps VALUES (3527, '2025-11-20 17:11:35.846157', '2025-11-20 17:11:35.846157', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 570, 5, 'Thịt cua xào khô (chỉ cho ít dầu ăn).', 10);
INSERT INTO public.recipe_steps VALUES (3528, '2025-11-20 17:11:36.190164', '2025-11-20 17:11:36.190164', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 571, 1, 'Sườn rửa sạch chặt hai dẻ một miếng dài 8 cm, ướp một chút tiêu muối để ngấm. Hành tỏi khô băm nhỏ. Khoai tây gọt vỏ thái chì rán chín vàng để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (3529, '2025-11-20 17:11:36.191734', '2025-11-20 17:11:36.191734', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 571, 5, 'Ăn kèm khoai tây rán.', 10);
INSERT INTO public.recipe_steps VALUES (3530, '2025-11-20 17:11:36.19335', '2025-11-20 17:11:36.19335', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 571, 3, 'Sốt BBQ cho thêm hạt tiêu rau mùi thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3531, '2025-11-20 17:11:36.195015', '2025-11-20 17:11:36.195015', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 571, 4, 'Sườn đã mềm cho sốt BBQ bao đều để 2 phút rồi cho vào lò nướng ở nhiệt độ 160 độ C trong 5 phút lấy ra bày đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (3532, '2025-11-20 17:11:36.197192', '2025-11-20 17:11:36.197192', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 571, 2, 'Sườn cho lên bếp chế nước dùng xâm xấp nêm chút muối đun nhỏ lửa cho sườn chín mềm.', 10);
INSERT INTO public.recipe_steps VALUES (3533, '2025-11-20 17:11:36.440763', '2025-11-20 17:11:36.440763', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 572, 2, 'Thịt tai lợn cho vào xoong nước lạnh luộc chín tới, để nguội thái miếng mỏng ướp muối, mì chính, lá chanh, nước chanh.', 10);
INSERT INTO public.recipe_steps VALUES (3534, '2025-11-20 17:11:36.442446', '2025-11-20 17:11:36.442446', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 572, 7, 'Lạc rang vàng, giã dập', 10);
INSERT INTO public.recipe_steps VALUES (3535, '2025-11-20 17:11:36.443451', '2025-11-20 17:11:36.443451', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 572, 6, 'Tỏi, ớt băm nhỏ ngâm dấm. Rau mùi, rau răm thái khúc ngắn.', 10);
INSERT INTO public.recipe_steps VALUES (3536, '2025-11-20 17:11:36.445048', '2025-11-20 17:11:36.445048', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 572, 4, 'Dưa chuột bổ đôi nạo bớt ruột thái lát mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (3537, '2025-11-20 17:11:36.446374', '2025-11-20 17:11:36.446374', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 572, 3, 'Hành tây thái miếng mỏng theo chiều dọc củ ngâm với dấm, cải thảo tách riêng từng lá thái vát.', 10);
INSERT INTO public.recipe_steps VALUES (3539, '2025-11-20 17:11:36.449474', '2025-11-20 17:11:36.449474', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 572, 9, 'Cho tiếp tỏi, ớt, đường chanh vắt lấy nước, nước mắm, hành tây vào khay các nguyên liệu trộn đều nêm vị nổi chua ngọt, cho thêm muối, tai heo đã thái vào trộn đều nêm vị nổi chua ngọt. Trước khi ăn 15 phút cho lạc, rau răm, rau mùi trộn đều bày vào đĩa. Bạn có thể trang trí thêm hoa ớt và rau mùi, rau răm cho hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (3540, '2025-11-20 17:11:36.450481', '2025-11-20 17:11:36.450481', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 572, 8, 'Dùng khay sạch cho dưa chuột, cà rốt, cải thảo đã thái vào khay, cho dấm, đường vào trộn đều để ngấm khoảng 5 phút chắt bỏ nước.', 10);
INSERT INTO public.recipe_steps VALUES (3541, '2025-11-20 17:11:36.452804', '2025-11-20 17:11:36.452804', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 572, 1, 'Các nguyên liệu sơ chế sạch.', 10);
INSERT INTO public.recipe_steps VALUES (3542, '2025-11-20 17:11:36.897138', '2025-11-20 17:11:36.897138', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 573, 2, 'Tẩm ướp hành khô băm nhỏ, tiêu, nước mắm, bột nêm, nước nghệ, giềng, mẻ, mắm tôm, nước cốt dừa, mỡ lợn chưng với bã riềng + nghệ.', 10);
INSERT INTO public.recipe_steps VALUES (3543, '2025-11-20 17:11:36.89926', '2025-11-20 17:11:36.89926', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 573, 1, 'Ba rọi cắt miếng mỏng vừa hoặc thái con chì.', 10);
INSERT INTO public.recipe_steps VALUES (3544, '2025-11-20 17:11:36.901396', '2025-11-20 17:11:36.901396', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 573, 3, 'Để ngấm khoảng 15 - 20 phút rồi xếp vào vỉ nướng chín trên than hoa.', 10);
INSERT INTO public.recipe_steps VALUES (3545, '2025-11-20 17:11:37.282223', '2025-11-20 17:11:37.282223', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 574, 1, 'Thịt ba rọi rửa sạch, xay nhuyễn. Lươn làm sạch, lọc xương, chẻ đôi, thái mỏng. Rau om, dưa leo, cà chua rửa sạch để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (3546, '2025-11-20 17:11:37.284244', '2025-11-20 17:11:37.284244', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 574, 2, 'Thịt ba rọi + thịt lươn đã làm xong nêm sa tế + hành tím + tỏi bằm + tiêu xanh + bột ngọt + đường + muối. Trộn đều các hỗn hợp trên xong nhồi vào ruột heo khô, đem đi hấp khoảng 5 phút, trong lúc hấp dùng tăm xăm cho nước thấm. Cuối cùng đem dồi đã hấp nướng cho vàng.', 10);
INSERT INTO public.recipe_steps VALUES (3547, '2025-11-20 17:11:37.754986', '2025-11-20 17:11:37.754986', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 575, 1, 'Thịt bò lọc bỏ gân xơ, thái miếng mỏng to bản, ngang thớ.', 10);
INSERT INTO public.recipe_steps VALUES (3548, '2025-11-20 17:11:37.756576', '2025-11-20 17:11:37.756576', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 575, 4, 'Xếp thịt bò vào vỉ đặt lên bếp than hoa nướng chín tới xém cạnh là được. Bày thịt vào đĩa, xung quanh trang trí rau ngổ, dưa chuột. Món này ăn nóng chấm với nước chấm tương gừng.', 10);
INSERT INTO public.recipe_steps VALUES (3549, '2025-11-20 17:11:37.758241', '2025-11-20 17:11:37.758241', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 575, 2, 'Gừng, củ xả, ớt, hành tỏi khô băm nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3550, '2025-11-20 17:11:37.759825', '2025-11-20 17:11:37.759825', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 575, 3, 'Ướp thịt bò với muối, tiêu, mì chính, xả, ớt, hành, tỏi khô, đường, gừng và mỡ nước để 20 phút cho ngấm.', 10);
INSERT INTO public.recipe_steps VALUES (3551, '2025-11-20 17:11:38.341959', '2025-11-20 17:11:38.341959', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 576, 3, 'Cắt cải chíp làm đôi và bày vào quanh bát tô trong nồi hấp. Tiếp tục hấp thêm khoảng 5 phút cho cải chíp và cá vừa chín tới. Hấp xong, bày cải chíp vào đĩa sâu lòng, đặt cá Tầm lên trên.', 10);
INSERT INTO public.recipe_steps VALUES (3552, '2025-11-20 17:11:38.34303', '2025-11-20 17:11:38.34303', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 576, 1, 'Tẩm ướp phi lê cá Tầm với muối, hạt tiêu, xì dầu và gừng thái chỉ.', 10);
INSERT INTO public.recipe_steps VALUES (3553, '2025-11-20 17:11:38.344106', '2025-11-20 17:11:38.344106', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 576, 2, 'Cho cá đã tẩm ướp vào bát, rắc một ít gừng lên trên. Để tô cá vào nồi và hấp cách thuỷ khoảng 12 phút.', 10);
INSERT INTO public.recipe_steps VALUES (3554, '2025-11-20 17:11:38.345718', '2025-11-20 17:11:38.345718', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 576, 4, 'Pha chế xốt xì dầu: gồm hỗn hợp xì dầu, đường và nước đun sôi. Dội xốt xì dầu vào đĩa cá. Đun nóng dầu ăn trên chảo rán và rưới dầu lên các miếng cá hấp, rắc hành hoa, rau mùi, ớt tươi lên trên, ăn nóng.', 10);
INSERT INTO public.recipe_steps VALUES (3555, '2025-11-20 17:11:38.43687', '2025-11-20 17:11:38.43687', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 577, 1, 'Khoai tây rửa sạch, gọt vỏ bỏ mắt ngâm rửa sạch đem đồ đến khi chín nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (3556, '2025-11-20 17:11:38.438475', '2025-11-20 17:11:38.438475', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 577, 2, 'Cho khoai ra bát cùng với bơ nghiền nhuyễn sau đó cho sữa tươi, kem tươi, cho ít muối tinh nếm vừa là được.', 10);
INSERT INTO public.recipe_steps VALUES (3557, '2025-11-20 17:11:38.89462', '2025-11-20 17:11:38.89462', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 578, 10, 'Làm nước trộn gỏi: Chanh vắt nước cốt + 3 muỗng đường + 1 muỗng muối + 1 muỗng tỏi băm + 1 muỗng ớt bằm +3 muỗng nước mắm ngon, trộn tất cả lại với nhau nêm vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (3558, '2025-11-20 17:11:38.896308', '2025-11-20 17:11:38.896308', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 578, 1, 'Rau nhút nhặt bỏ lá chỉ lấy cọng, luộc qua cho chút muối và nước chanh (dấm) vào nước luộc, vừa chín tới thì vớt ra trụng qua nước đá (hoặc nước lạnh)', 10);
INSERT INTO public.recipe_steps VALUES (3559, '2025-11-20 17:11:38.89789', '2025-11-20 17:11:38.89789', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 578, 5, 'Bánh đa hoặc bánh phồng tôm chiên vàng.', 10);
INSERT INTO public.recipe_steps VALUES (3560, '2025-11-20 17:11:38.899485', '2025-11-20 17:11:38.899485', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 578, 8, 'Rau nhút đặp dập vắt ráo nước, bỏ nước gỏi vào trộn đều', 10);
INSERT INTO public.recipe_steps VALUES (3561, '2025-11-20 17:11:38.900491', '2025-11-20 17:11:38.900491', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 578, 7, 'Mực, tôm, nghêu ướp nước gỏi 30 phút', 10);
INSERT INTO public.recipe_steps VALUES (3562, '2025-11-20 17:11:38.902134', '2025-11-20 17:11:38.902134', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 578, 6, 'Nghêu chần sơ cho há miệng, lấy ruột.', 10);
INSERT INTO public.recipe_steps VALUES (3563, '2025-11-20 17:11:38.903774', '2025-11-20 17:11:38.903774', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 578, 2, 'Hành tây cắt sợi', 10);
INSERT INTO public.recipe_steps VALUES (3564, '2025-11-20 17:11:38.906292', '2025-11-20 17:11:38.906292', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 578, 4, 'Tôm chần sơ rồi cũng trụng qua nước đá, cho ít hành lá vào nước luộc. Sau đó, bóc vỏ đầu, đuôi, chân tôm.', 10);
INSERT INTO public.recipe_steps VALUES (3565, '2025-11-20 17:11:38.907799', '2025-11-20 17:11:38.907799', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 578, 9, 'Rau răm xắt nhuyễn. Cà rốt xắt sợi mỏng. Củ cải trắng tỉa cò. Mè trắng giã nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3566, '2025-11-20 17:11:38.909808', '2025-11-20 17:11:38.909808', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 578, 3, 'Mực cắt khía ngang và dọc sau đó xắt lát mỏng vừa ăn, chần sơ rồi trụng qua nước đá.', 10);
INSERT INTO public.recipe_steps VALUES (3567, '2025-11-20 17:11:38.911325', '2025-11-20 17:11:38.911325', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 578, 11, 'Bày gỏi ra đĩa vào một bên, xếp tôm lên và rắc mè hạt, xếp rau húng lại quanh đĩa, xếp cò lên.', 10);
INSERT INTO public.recipe_steps VALUES (3568, '2025-11-20 17:11:39.036502', '2025-11-20 17:11:39.036502', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 579, 4, 'Tẩm muối, tiêu, mì chính, vào ngao rồi đặt lên trên bếp than hoa nướng. Khi ngao bắt đầu tiết nước thì rưới dầu đã trộn hành lên trên, tiếp tục nướng đến chín.', 10);
INSERT INTO public.recipe_steps VALUES (3656, '2025-11-20 17:11:42.51173', '2025-11-20 17:11:42.51173', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 594, 4, 'Múc canh giò heo ra tô, ăn nóng.', 10);
INSERT INTO public.recipe_steps VALUES (3570, '2025-11-20 17:11:39.040309', '2025-11-20 17:11:39.040309', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 579, 1, 'Ngao cạy miệng rửa sạch, hành khô băm nhỏ.Hành hoa 1/2 thái nhỏ, 1/2 để nguyên nhặt sạch.', 10);
INSERT INTO public.recipe_steps VALUES (3571, '2025-11-20 17:11:39.041931', '2025-11-20 17:11:39.041931', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 579, 3, 'Chao dầu hoặc xào chỗ hành còn lại, lót xuống đáy đĩa để bày ngao.', 10);
INSERT INTO public.recipe_steps VALUES (3572, '2025-11-20 17:11:39.043526', '2025-11-20 17:11:39.043526', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 579, 5, 'Bày ra đĩa đã lót hành, rau mùi, ăn nóng.', 10);
INSERT INTO public.recipe_steps VALUES (3573, '2025-11-20 17:11:39.242497', '2025-11-20 17:11:39.242497', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 580, 10, 'Ốc giác nấu cà ri
INSERT INTO public.recipe_steps VALUES (3574, '2025-11-20 17:11:39.244094', '2025-11-20 17:11:39.244094', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 580, 2, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (3575, '2025-11-20 17:11:39.245704', '2025-11-20 17:11:39.245704', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 580, 11, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (3576, '2025-11-20 17:11:39.247298', '2025-11-20 17:11:39.247298', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 580, 1, 'Ốc móng tay trộn chua cay
INSERT INTO public.recipe_steps VALUES (3577, '2025-11-20 17:11:39.248882', '2025-11-20 17:11:39.248882', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 580, 4, 'Trụng ốc thật nhanh, vớt ra, tách một bên vỏ, chừa lại phần vỏ gắn với nạc ốc, để ráo. Trộn đều hành, ớt, tỏi xắt lát với tương ớt, nước mắm, đường, hạt nêm và nước cốt chanh làm nước trộn. Cho ốc đã luộc vào thố, rưới nước trộn, cho thêm rau húng lủi vào, trộn đều, gắp ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (3578, '2025-11-20 17:11:39.250861', '2025-11-20 17:11:39.250861', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 580, 3, 'Ốc rửa sạch. Rau húng lủi nhặt lấy lá, rửa sạch. Ớt, hành tím, tỏi xắt lát mỏng. Bắc nồi nước lên bếp, nấu thật sôi, cho vào ít gừng giã giập.', 10);
INSERT INTO public.recipe_steps VALUES (3579, '2025-11-20 17:11:39.251963', '2025-11-20 17:11:39.251963', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 580, 12, 'Ốc giác trụng sơ với ít gừng giã giập, vớt ra, để ráo, vít lấy phần thịt ốc. Ớt sừng xắt lát. Sả cây cắt khúc, đập giập. Bắc chảo, phi thơm tỏi, sả, ớt, củ hành băm với dầu ăn, cho sả cây và bột cà ri vào xào sau đó đổ nước cốt dừa vào nấu sôi.', 10);
INSERT INTO public.recipe_steps VALUES (3580, '2025-11-20 17:11:39.253557', '2025-11-20 17:11:39.253557', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 580, 6, 'Ốc đỏ nấu sữa
INSERT INTO public.recipe_steps VALUES (3581, '2025-11-20 17:11:39.255248', '2025-11-20 17:11:39.255248', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 580, 14, 'Mách nhỏ:Ốc giác chọn con vừa ăn, không nên chọn con quá to sẽ bị nhớt. Khi vít lấy thịt ốc nên nhẹ tay, tránh làm vỡ mật sẽ làm món bị đắng mất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (3582, '2025-11-20 17:11:39.257394', '2025-11-20 17:11:39.257394', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 580, 13, 'Cho tiếp ốc vào, nêm hạt nêm, đường, nước mắm, nước cốt me vừa ăn, để lửa riu riu. Nấu đến khi nước sền sệt là được, tắt bếp, nhấc xuống. Trút ốc ra đĩa, rắc đậu phộng giã giập và ớt lên. Dùng kèm rau răm.', 10);
INSERT INTO public.recipe_steps VALUES (3583, '2025-11-20 17:11:39.259012', '2025-11-20 17:11:39.259012', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 580, 7, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (3584, '2025-11-20 17:11:39.260081', '2025-11-20 17:11:39.260081', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 580, 9, 'Mách nhỏ:Nếu mua ốc đỏ đông lạnh nên chịu khó chọn và ngửi từng con để đảm bảo ốc thật tươi. Có thể dùng tay bấm vào thịt ốc, cảm thấy cứng và chắc là được.', 10);
INSERT INTO public.recipe_steps VALUES (3585, '2025-11-20 17:11:39.261801', '2025-11-20 17:11:39.261801', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 580, 8, 'Ốc đỏ làm sạch. Sả cây cắt khúc, đập giập. Bắc chảo lên bếp, cho bơ vào, đợi bơ tan cho tỏi, sả băm vào phi thơm. Cho sả cây vào xào sau đó cho ốc vào xóc đều. Đổ tiếp sữa vào, nêm thêm hạt nêm, đường vừa ăn, để lửa riu riu. Khi ốc chín, trút ra đĩa, trang trí thêm rau húng lủi lên mặt.', 10);
INSERT INTO public.recipe_steps VALUES (3586, '2025-11-20 17:11:39.263951', '2025-11-20 17:11:39.263951', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 580, 5, 'Mách nhỏ:Ốc móng tay phải chọn ốc sống, tức những con bạn thấy còn ngọ nguậy. Khi trụng ốc phải đợi nước thật sôi, vừa cho vào là vớt ra ngay.', 10);
INSERT INTO public.recipe_steps VALUES (3587, '2025-11-20 17:11:39.547481', '2025-11-20 17:11:39.547481', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 581, 1, 'Thịt bê lọc bỏ gân sơ, pha khối thịt khoảng 200 g, ướp với nước riềng, một chút tương, gừng, mỡ để 15 phút cho ngấm.', 10);
INSERT INTO public.recipe_steps VALUES (3588, '2025-11-20 17:11:39.549656', '2025-11-20 17:11:39.549656', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 581, 2, 'Củ sả băm nhỏ, vừng rang vàng, lá chanh thái chỉ, hạt mùi rang vàng, giã nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3589, '2025-11-20 17:11:39.551242', '2025-11-20 17:11:39.551242', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 581, 4, 'Cho thịt vào vỉ nướng trên than hoa, chín tái. Chú ý: Nếu làm số lượng nhiều, muốn nhanh, bạn có thể cho thịt vào chao qua mỡ.', 10);
INSERT INTO public.recipe_steps VALUES (3590, '2025-11-20 17:11:39.552848', '2025-11-20 17:11:39.552848', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 581, 3, 'Tương pha lẫn với gừng giã nhỏ, đường, ớt.', 10);
INSERT INTO public.recipe_steps VALUES (3591, '2025-11-20 17:11:39.555003', '2025-11-20 17:11:39.555003', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 581, 5, 'Để thịt nguội, thái miếng mỏng, to bản ngang thớ, ướp thịt với nước riềng, sả, hạt tiêu, hạt mùi, mì chính, vừng, lá chanh + gừng, ăn kèm với rau thơm, mùi, rau ngổ, khế, chuối, dứa (đã sơ chế sạch, thái mỏng ), chấm nước tương gừng.', 10);
INSERT INTO public.recipe_steps VALUES (3592, '2025-11-20 17:11:39.677782', '2025-11-20 17:11:39.677782', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 582, 4, 'Tẩm ướp tiêu, gia vị vào sò đặt lên than hoa nướng. Khi sò bắt đầu tiết nước thì rưới dầu đã trộn hành lên trên, tiếp tục nướng đến chín thì bày ra đĩa đã lót hành rắc rau mùi ăn nóng.', 10);
INSERT INTO public.recipe_steps VALUES (3593, '2025-11-20 17:11:39.679302', '2025-11-20 17:11:39.679302', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 582, 1, 'Sò cậy miệng, rửa sạch, hành khô băm nhỏ, hành hoa một nửa thái nhỏ, nửa kia để nguyên, nhặt sạch.', 10);
INSERT INTO public.recipe_steps VALUES (3594, '2025-11-20 17:11:39.680422', '2025-11-20 17:11:39.680422', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 582, 3, 'Chao dầu hoặc xào chỗ hành còn lại lót xuống đáy đĩa để bày sò.', 10);
INSERT INTO public.recipe_steps VALUES (3595, '2025-11-20 17:11:39.681419', '2025-11-20 17:11:39.681419', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 582, 2, 'Cho dầu vào chảo, phi thơm hành băm, để nguội rồi cho hành thái nhỏ vào trộn đều để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (3596, '2025-11-20 17:11:40.006884', '2025-11-20 17:11:40.006884', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 583, 5, 'Trộn lẫn bơ cắt lát, hải sản vào hỗn hợp salad là được món ăn thơm ngon bổ dưỡng.', 10);
INSERT INTO public.recipe_steps VALUES (3597, '2025-11-20 17:11:40.009047', '2025-11-20 17:11:40.009047', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 583, 3, 'Hải sản xào bơ, tỏi cho chín tới rồi nêm hạt tiêu', 10);
INSERT INTO public.recipe_steps VALUES (3598, '2025-11-20 17:11:40.010631', '2025-11-20 17:11:40.010631', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 583, 2, 'Xà lách xé miếng vừa ăn, trộn với hỗn hợp trên.', 10);
INSERT INTO public.recipe_steps VALUES (3599, '2025-11-20 17:11:40.012238', '2025-11-20 17:11:40.012238', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 583, 1, 'Trộn đều 200 ml dầu hồ đào, muối ăn, hạt tiêu, mật ong, nước cốt chanh và dầu olive với nhau.', 10);
INSERT INTO public.recipe_steps VALUES (3600, '2025-11-20 17:11:40.013879', '2025-11-20 17:11:40.013879', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 583, 4, 'Bơ thái lát mỏng vừa ăn', 10);
INSERT INTO public.recipe_steps VALUES (3601, '2025-11-20 17:11:40.210465', '2025-11-20 17:11:40.210465', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 584, 5, 'Trang trí dưa chuột cà chua. Khi ăn chấm sốt chua ngọt.', 10);
INSERT INTO public.recipe_steps VALUES (3602, '2025-11-20 17:11:40.211972', '2025-11-20 17:11:40.211972', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 584, 1, 'Khoai gọt vỏ, rửa sạch, cắt miếng vuông vừa ăn độ dày khoảng 0,4 cm, đem luộc chín (không vỡ nát).', 10);
INSERT INTO public.recipe_steps VALUES (3603, '2025-11-20 17:11:40.213202', '2025-11-20 17:11:40.213202', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 584, 2, 'Trộn bột mỳ, bột năng, men nở với 300 ml nước, ủ khoảng 20 phút.', 10);
INSERT INTO public.recipe_steps VALUES (3604, '2025-11-20 17:11:40.215204', '2025-11-20 17:11:40.215204', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 584, 3, 'Tôm, thịt băm nhỏ. Nấm hương, mộc nhĩ ngâm nở băm nhỏ, hành hoa, rau mùi thái nhỏ, tất cả trộn đều với nhau cùng các loại gia vị và hạt mắc mật.', 10);
INSERT INTO public.recipe_steps VALUES (3605, '2025-11-20 17:11:40.216203', '2025-11-20 17:11:40.216203', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 584, 4, 'Phết nhân lên miếng khoai, sau đó dùng miếng khoai khác ép lên trên rồi nhúng vào bột đã ủ và cho vào dầu nóng vừa, rán vàng mặt là được.', 10);
INSERT INTO public.recipe_steps VALUES (3606, '2025-11-20 17:11:40.468529', '2025-11-20 17:11:40.468529', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 585, 5, 'Khi ăn chấm chạo với tương gừng ăn kèm lá sung và các loại rau thơm.', 10);
INSERT INTO public.recipe_steps VALUES (3607, '2025-11-20 17:11:40.470711', '2025-11-20 17:11:40.470711', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 585, 4, 'Tương gừng giã nhỏ thêm ớt bột, đường.', 10);
INSERT INTO public.recipe_steps VALUES (3608, '2025-11-20 17:11:40.472321', '2025-11-20 17:11:40.472321', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 585, 3, 'Trộn lẫn thịt dê với mỡ phần, bì lợn, đường, muối, thính gạo và vừng. Bày chạo vào đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (3609, '2025-11-20 17:11:40.473913', '2025-11-20 17:11:40.473913', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 585, 1, 'Thịt dê thái miếng mỏng, to (miếng khoảng 100 g), ướp gừng, hành tỏi giã nhỏ, muối, ớt bột, cho vào rán mỡ vàng, thái chỉ nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3610, '2025-11-20 17:11:40.476046', '2025-11-20 17:11:40.476046', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 585, 2, 'Gạo rang vàng, sát vỏ giã dập.', 10);
INSERT INTO public.recipe_steps VALUES (3611, '2025-11-20 17:11:40.627625', '2025-11-20 17:11:40.627625', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 586, 1, 'Bò khô tước nhỏ, đu đủ xanh và cà rốt thái sợ, ngâm giấm đường. Chanh vắt lấy nước.', 10);
INSERT INTO public.recipe_steps VALUES (3612, '2025-11-20 17:11:40.629242', '2025-11-20 17:11:40.629242', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 586, 3, 'Quấy hỗn hợp giấm + đường + muối + bột ngọt (nếu thích) cho tan.', 10);
INSERT INTO public.recipe_steps VALUES (3613, '2025-11-20 17:11:40.630845', '2025-11-20 17:11:40.630845', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 586, 5, 'Trộn khô bò với nước cốt chanh và lá chanh thái sợi rồi trộn chung với các thức trên.', 10);
INSERT INTO public.recipe_steps VALUES (3614, '2025-11-20 17:11:40.632453', '2025-11-20 17:11:40.632453', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 586, 2, 'Đánh cho tơi sợi đu đủ.', 10);
INSERT INTO public.recipe_steps VALUES (3615, '2025-11-20 17:11:40.634518', '2025-11-20 17:11:40.634518', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 586, 4, 'Trộn hỗn hợp trên vào đu đủ + cà rốt thái sợi + rau thơm xắt nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3616, '2025-11-20 17:11:40.885298', '2025-11-20 17:11:40.885298', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 587, 5, 'Tiếp theo, lăn tôm đã có vỏ bột năng đó qua bột chiên giòn, bóp chặt và tròn đều rồi chiên vàng.', 10);
INSERT INTO public.recipe_steps VALUES (3617, '2025-11-20 17:11:40.886897', '2025-11-20 17:11:40.886897', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 587, 2, 'Tôm lột vỏ, xâu tăm từ đầu đến đuôi rồi luộc chín, lột vỏ', 10);
INSERT INTO public.recipe_steps VALUES (3618, '2025-11-20 17:11:40.888497', '2025-11-20 17:11:40.888497', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 587, 1, 'Hấp khoai môn chín, bóp nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (3619, '2025-11-20 17:11:40.89011', '2025-11-20 17:11:40.89011', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 587, 4, 'Tôm ướp 1 muỗng tiêu xay, 1/2 muỗng bột nêm rồi lăn qua bột năng, bóp chặt lại.', 10);
INSERT INTO public.recipe_steps VALUES (3620, '2025-11-20 17:11:40.891165', '2025-11-20 17:11:40.891165', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 587, 6, 'Món này chấm tương ớt.', 10);
INSERT INTO public.recipe_steps VALUES (3621, '2025-11-20 17:11:40.892768', '2025-11-20 17:11:40.892768', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 587, 3, 'Trộn đều các thứ sau: Bột năng 100-200 g, 1 lòng đỏ trứng gà, 1/3 muỗng ngũ vị hương, 1/2 muỗng bột nêm', 10);
INSERT INTO public.recipe_steps VALUES (3622, '2025-11-20 17:11:41.269646', '2025-11-20 17:11:41.269646', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 588, 3, 'Đổ 1 muỗng mỡ vào nồi, cho tỏi vào phi thơm. Tiếp đó, cho sả, ớt đã trộn chung vào rồi xào vàng. Sau cùng, đổ ốc hương vào nồi, đợi khoảng 30 phút rồi cho 1 muỗng hèm rượu đã lọc vào.', 10);
INSERT INTO public.recipe_steps VALUES (3623, '2025-11-20 17:11:41.271269', '2025-11-20 17:11:41.271269', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 588, 2, 'Hèm lọc lấy nước. Rau răm rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (3624, '2025-11-20 17:11:41.27291', '2025-11-20 17:11:41.27291', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 588, 5, 'Cách làm nước mắm gừng: Cho 2 muỗng nước mắm + 1/2 muỗng bột ngọt + 1 muỗng đường. Nấu hỗn hợp này cho hơi keo lại rồi cho gừng đã giã nát và ớt đập giập vào.', 10);
INSERT INTO public.recipe_steps VALUES (3625, '2025-11-20 17:11:41.274494', '2025-11-20 17:11:41.274494', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 588, 4, 'Cuối cùng, nêm thêm 1 muỗng cà phê đường + 1 muỗng cà phê bột ngọt + 1 muỗng cà phê muối.', 10);
INSERT INTO public.recipe_steps VALUES (3626, '2025-11-20 17:11:41.276102', '2025-11-20 17:11:41.276102', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 588, 1, 'Ốc hương rửa sạch (nhưng không lôi cả con ra khỏi vỏ), cho vào nồi luộc sơ cho chín rồi đổ ra đĩa, mỗi phần nửa kg.', 10);
INSERT INTO public.recipe_steps VALUES (3627, '2025-11-20 17:11:41.510083', '2025-11-20 17:11:41.510083', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 589, 3, 'Nước luộc ốc gạn nước trong cho vào xoong nước dùng, nêm: gia vị, dấm bỗng vừa ăn hơi chua.', 10);
INSERT INTO public.recipe_steps VALUES (3628, '2025-11-20 17:11:41.511163', '2025-11-20 17:11:41.511163', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 589, 4, 'Dấm bỗng còn lại đun sôi, cho ra bát để riêng. Cà chua thái miếng cau xào qua, cho vào xoong nước dùng.', 10);
INSERT INTO public.recipe_steps VALUES (3629, '2025-11-20 17:11:41.512771', '2025-11-20 17:11:41.512771', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 589, 1, 'Ốc ngâm nước gạo một đêm cho sạch rồi rửa sạch, luộc chín tới vớt ra khêu lấy ruột, tỉa bỏ đường phân, hòn hoi, để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (3657, '2025-11-20 17:11:42.513312', '2025-11-20 17:11:42.513312', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 594, 1, 'Giò heo chặt khoanh, cạo, rửa sạch, ướp hành tím, tiêu, hạt nêm, bột ngọt, muối, đường. Bắp chuối bào mỏng, rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (3630, '2025-11-20 17:11:41.514381', '2025-11-20 17:11:41.514381', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 589, 5, 'Hành khô thái mỏng phi thơm, cho ớt bột vào chưng 1/2 cho vào nước dùng, 1/2 để riêng. Hành hoa phần lá thái nhỏ, phần củ chẻ mỏng. Bún chần nước nóng khoảng 80 độ C để róc nước bày vào bát rắc hành hoa, rau tía tô thái nhỏ bên trên bày ốc hành củ chẻ.', 10);
INSERT INTO public.recipe_steps VALUES (3631, '2025-11-20 17:11:41.515993', '2025-11-20 17:11:41.515993', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 589, 2, 'Xương lợn (gà) rửa sạch, ninh nước dùng.', 10);
INSERT INTO public.recipe_steps VALUES (3632, '2025-11-20 17:11:41.517586', '2025-11-20 17:11:41.517586', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 589, 6, 'Chan nước dùng ngập bát bún, ăn nóng. Ăn kèm: Các loại rau ghém, ớt chưng và dẫm bỗng đã đun.', 10);
INSERT INTO public.recipe_steps VALUES (3633, '2025-11-20 17:11:41.744628', '2025-11-20 17:11:41.744628', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 590, 5, 'Bún trần qua nước nóng, chia ra bát, lót rau răm. Bày thịt gà, giò lụa thái sợi, tôm bông, trứng tráng mỏng, khoanh trứng muối, chan nước dùng ngập bún.', 10);
INSERT INTO public.recipe_steps VALUES (3634, '2025-11-20 17:11:41.746228', '2025-11-20 17:11:41.746228', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 590, 2, 'Tôm bóc vỏ, đầu cho đun cùng nước dùng, thân giã bông. Trứng tráng mỏng, thái chỉ.', 10);
INSERT INTO public.recipe_steps VALUES (3635, '2025-11-20 17:11:41.747281', '2025-11-20 17:11:41.747281', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 590, 6, 'Ăn kèm mắm tôm, chanh, ớt, củ cải dầm.', 10);
INSERT INTO public.recipe_steps VALUES (3636, '2025-11-20 17:11:41.748331', '2025-11-20 17:11:41.748331', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 590, 1, 'Gà luộc chín, gỡ lấy thịt, xé nhỏ. Ninh xương gà và xương lợn lấy nước dùng.', 10);
INSERT INTO public.recipe_steps VALUES (3637, '2025-11-20 17:11:41.749919', '2025-11-20 17:11:41.749919', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 590, 4, 'Nước dùng ninh lọc lấy 3 lít, nêm vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (3638, '2025-11-20 17:11:41.751498', '2025-11-20 17:11:41.751498', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 590, 3, 'Trứng muối luộc chín, lấy lòng đỏ, thái khoanh tròn. Ngâm củ cải khô, dầm nước mắm.', 10);
INSERT INTO public.recipe_steps VALUES (3639, '2025-11-20 17:11:41.885785', '2025-11-20 17:11:41.885785', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 591, 3, 'Cho nhiều dầu hoặc mỡ vào chảo đun nóng già. Thả thịt gà vào chiên chín vớt ra, để hơi nguội thái miếng vừa ăn. Bày thịt chia đôi trên cùng một đĩa, khi ăn chấm với hai loại xốt (xốt chua ngọt, xốt nấm) dội lên trên, trang trí đường diềm và hoa.', 10);
INSERT INTO public.recipe_steps VALUES (3640, '2025-11-20 17:11:41.887387', '2025-11-20 17:11:41.887387', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 591, 6, 'Yêu cầu: Gà chín săn, hơi khô. Hai loại xốt sánh đều, trang trí hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (3641, '2025-11-20 17:11:41.888436', '2025-11-20 17:11:41.888436', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 591, 5, 'Cách làm xốt nấm: Nấm hương ngâm rửa sạch, thái chỉ cho vào xoong cùng 1 môi nước, 1 thìa dầu hào, ít gia vị, đường, đun sôi. Nếm vị mặn ngọt vừa ăn, hoà bột đao rót vào xoong nấm đảo đều, sánh.', 10);
INSERT INTO public.recipe_steps VALUES (3642, '2025-11-20 17:11:41.890035', '2025-11-20 17:11:41.890035', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 591, 2, 'Khi gà ngấm gia vị cho lòng đỏ trứng và một thìa bột đao đảo đều.', 10);
INSERT INTO public.recipe_steps VALUES (3643, '2025-11-20 17:11:41.891658', '2025-11-20 17:11:41.891658', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 591, 1, 'Gà sơ chế rửa sạch, lọc bỏ xương, khía phần cơ ướp gia vị, hạt tiêu để ngấm 10 phút.', 10);
INSERT INTO public.recipe_steps VALUES (3644, '2025-11-20 17:11:41.893746', '2025-11-20 17:11:41.893746', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 591, 4, 'Cách làm xốt chua ngọt: Cho 2 thìa đường và 3 thìa dấm, 1 thìa bột cà chua, 1/10 thìa muối, 2 thìa nước, 1 nhánh tỏi đập dập giã nhuyễn vào xoong đun sôi. Nếm có vị mặn ngọt, hơi chua cân đối. Hoà ít bột đao rót vào xoong nước xốt rồi đảo đều cho hơi sánh.', 10);
INSERT INTO public.recipe_steps VALUES (3645, '2025-11-20 17:11:42.158668', '2025-11-20 17:11:42.158668', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 592, 2, 'Cho 1 muỗng muối + 1 muỗng hạt nêm + 1/4 muỗng tiêu xay + tỏi + ớt bằm + 1 muỗng dầu ăn trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (3646, '2025-11-20 17:11:42.160269', '2025-11-20 17:11:42.160269', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 592, 4, 'Nướng cá: Cá đã ướp cho lên bếp than nướng sơ, sau đó trải miếng giấy bạc rồi đập dập sả cắt khúc bao dưới mặt, đặt cá lên, tiếp tục cho sả ở phần trên rồi bao cá lại cho chặt, tiếp tục nướng lửa vừa 15 phút là được', 10);
INSERT INTO public.recipe_steps VALUES (3647, '2025-11-20 17:11:42.16187', '2025-11-20 17:11:42.16187', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 592, 1, 'Cá để nguyên, moi mang, bỏ ruột, đánh vẩy, làm sạch', 10);
INSERT INTO public.recipe_steps VALUES (3648, '2025-11-20 17:11:42.163472', '2025-11-20 17:11:42.163472', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 592, 3, 'Khứa hai bên phi lê cá rồi thoa đều hỗn hợp gia vị hai bên 5 phút', 10);
INSERT INTO public.recipe_steps VALUES (3649, '2025-11-20 17:11:42.164581', '2025-11-20 17:11:42.164581', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 592, 5, 'Trang trí: Đặt nguyên con cá đã nướng bên đĩa hạt xoài, dùng kéo cắt 1 đường khui giấy bạc ra tạo giấy bạc thành hình dáng thuyền. Xung quanh cá bỏ 1 ít ngò Đà Lạt.', 10);
INSERT INTO public.recipe_steps VALUES (3650, '2025-11-20 17:11:42.324242', '2025-11-20 17:11:42.324242', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 593, 1, 'Thịt dẻ sườn bò rửa sạch kỹ, thái vuông 3 cm, ướp gia vị, hạt tiêu.', 10);
INSERT INTO public.recipe_steps VALUES (3651, '2025-11-20 17:11:42.32535', '2025-11-20 17:11:42.32535', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 593, 4, 'Cho ít dầu vào xoong, cho thịt bò vào xào săn. Sau đó chế nước xâm sấp thịt, cho gừng hành vào cùng, đun sôi, hớt bọt, nêm vị mặn ngọt vừa ăn. Om thịt trong 60 phút.', 10);
INSERT INTO public.recipe_steps VALUES (3652, '2025-11-20 17:11:42.326942', '2025-11-20 17:11:42.326942', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 593, 3, 'Lá lốt tách rửa, thái sợi nhỏ đều.', 10);
INSERT INTO public.recipe_steps VALUES (3653, '2025-11-20 17:11:42.328549', '2025-11-20 17:11:42.328549', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 593, 2, 'Gừng, hành khô nướng thơm, rửa sạch, đập dập.', 10);
INSERT INTO public.recipe_steps VALUES (3654, '2025-11-20 17:11:42.330151', '2025-11-20 17:11:42.330151', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 593, 6, 'Yêu cầu: Thịt bò mềm, giòn nước hơi chua, thơm vị lá lốt.', 10);
INSERT INTO public.recipe_steps VALUES (3655, '2025-11-20 17:11:42.331749', '2025-11-20 17:11:42.331749', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 593, 5, 'Thịt chín mềm, nhừ gắp bỏ gừng hành, để nguội, cất tủ, dùng dần. Khi ăn múc thịt cùng nước vào xoong đun sôi lại nêm vị vừa ăn, thêm vài thìa dấm bỗng và lá lốt đảo đều, múc ra bát, ăn nóng.', 10);
INSERT INTO public.recipe_steps VALUES (5111, '2025-11-20 17:12:42.437808', '2025-11-20 17:12:42.437808', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 784, 4, 'Đun nóng 3 thìa canh dầu ăn, cho cà vào chiên sơ. Khi cà săn và hơi sém cạnh là được. Vớt cà ra để vào giấy thấm dầu. Việc này giúp cho khi kho cà không bị nhũn mà vẫn giữ nguyên hình dạng.', 10);
INSERT INTO public.recipe_steps VALUES (5112, '2025-11-20 17:12:42.440962', '2025-11-20 17:12:42.440962', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 784, 5, 'Phi thơm hành khô, trút phần hỗn hợp nước sốt vào, khuấy đều trên lửa nhỏ. Nêm nếm điều chỉnh lại gia vị cho vừa miệng. Cho cà vào và kho trên lửa vừa, lật trở nhẹ để các mặt cà thấm đều sốt kho. Kho cho tới khi nước sánh sệt là được, rắc thêm hành lá, hạt tiêu cho thơm. Tắt bếp và múc ra thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (5137, '2025-11-20 17:12:45.098291', '2025-11-20 17:12:45.098291', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 789, 6, 'Làm lần lượt cho tới hết, đểchả giògói đều thì nên múc lượng nhân đều nhau.', 10);
INSERT INTO public.recipe_steps VALUES (3658, '2025-11-20 17:11:42.514889', '2025-11-20 17:11:42.514889', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 594, 3, 'Khi giò heo mềm, nêm thêm hạt nêm cho vừa ăn. Cho bắp chuối vào nấu thêm khoảng 10 phút, nêm thêm ít nước mắm, trộn đều, nhắc xuống.', 10);
INSERT INTO public.recipe_steps VALUES (3659, '2025-11-20 17:11:42.516467', '2025-11-20 17:11:42.516467', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 594, 2, 'Đặt nồi lên bếp, cho dầu ăn vào, phi thơm đầu hành, cho giò heo vào xào lửa lớn cho xăn và thấm gia vị. Đổ nước vào nồi ngập giò heo, hầm lửa nhỏ cho mềm.', 10);
INSERT INTO public.recipe_steps VALUES (3660, '2025-11-20 17:11:42.766856', '2025-11-20 17:11:42.766856', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 595, 2, 'Cho thêm ít ngũ vị hương, chờ sườn cừu vào ướp cho thấm đều trong 20 phút. Sau đó nướng sườn trên lửa than hồng cho chín vàng.', 10);
INSERT INTO public.recipe_steps VALUES (3661, '2025-11-20 17:11:42.769334', '2025-11-20 17:11:42.769334', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 595, 3, 'Sườn nướng chín ăn kèm với nước chấm sốt Hoisin và tương ớt trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (3662, '2025-11-20 17:11:42.770976', '2025-11-20 17:11:42.770976', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 595, 1, 'Hành tím bằm nhỏ trộn đều với sốt tương ngọt Hoisin, tương ớt, mù tạt, dầu hào và 200ml bia đen.', 10);
INSERT INTO public.recipe_steps VALUES (3663, '2025-11-20 17:11:43.140096', '2025-11-20 17:11:43.140096', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 596, 3, 'Làm nước nhúng bắp bò: Hòa một thìa súp nước mẻ với 2 chén nước. Lọc lấy nước mẻ, bỏ phần xác. Bắc chảo nóng, cho dầu ăn vào phi thơm hành tím, sả, cà chua. Cho nước mẻ vào đun sôi. Nêm gia vị vừa ăn. Khi ăn cho từng ít bắp bò vào nhúng tái, vớt ra đĩa. Ăn tới đâu nhúng tới đó.', 10);
INSERT INTO public.recipe_steps VALUES (3664, '2025-11-20 17:11:43.142197', '2025-11-20 17:11:43.142197', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 596, 2, 'Xếp bắp bò thái lát, hành tây lên đĩa, đập một trứng gà trang trí ở giữa. Khế xanh, chuối xanh, dưa leo cắt lát mỏng xếp ra đĩa. Bún xếp ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (3665, '2025-11-20 17:11:43.143813', '2025-11-20 17:11:43.143813', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 596, 1, 'Bắp bò hoa rửa sạch thái lát mỏng. Hành tây thái lát. Cà chua, sả, thơm bằm nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (3666, '2025-11-20 17:11:43.145413', '2025-11-20 17:11:43.145413', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 596, 4, 'Làm mắm nêm: Phi thơm hành tím với dầu ăn, cho thơm vào xào qua, nêm ít đường, trút ra. Hòa tan ớt, tỏi với nước sôi để nguội, cho mắm nêm sau đó cho tiếp thơm đã xào vào quậy đều tay. Bắp bò nhúng mẻ ăn kèm với bún tươi, cuốn bánh tráng, khế, chuối xanh, dưa leo, rau sống.', 10);
INSERT INTO public.recipe_steps VALUES (3667, '2025-11-20 17:11:43.472421', '2025-11-20 17:11:43.472421', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 597, 10, 'Cắt nhỏ xúc xích, tách hạt ngô ngọt, hành tây hoặc ớt chuông thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3668, '2025-11-20 17:11:43.473996', '2025-11-20 17:11:43.473996', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 597, 3, 'Nhồi bột cho tới khi mịn dẻo, không bết tay, thoa chút dầu ăn dưới đáy âu, đặt bột đã nhào vào, dùng khăn ẩm phủ lên, ủ bột 30 phút.', 10);
INSERT INTO public.recipe_steps VALUES (3669, '2025-11-20 17:11:43.475614', '2025-11-20 17:11:43.475614', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 597, 6, 'Phủ chút bột mì và cán, sao cho phần giữa mỏng hơn viền ngoài bánh. Nặn phần viền để tạo ngăn nhân bánh không bị tràn ra ngoài.', 10);
INSERT INTO public.recipe_steps VALUES (3670, '2025-11-20 17:11:43.477225', '2025-11-20 17:11:43.477225', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 597, 8, 'Phết chút bơ hoặc dầu ăn lên chảo, cho đế vào nướng chín ở lửa nhỏ vừa. Lấy ra, để một bên.', 10);
INSERT INTO public.recipe_steps VALUES (3671, '2025-11-20 17:11:43.478804', '2025-11-20 17:11:43.478804', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 597, 12, 'Sau khi phô mai chảy (khoảng 5 phút), nên mở vung để tránh hấp hơi nước, tăng lửa lên vừa để đế giòn hơn.', 10);
INSERT INTO public.recipe_steps VALUES (3672, '2025-11-20 17:11:43.480409', '2025-11-20 17:11:43.480409', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 597, 13, 'Khi viền bánh màu vàng nâu, nhân chín tới, phô mai chảy ra hết, dậy mùi thơm đặc trưng là đã hoàn thiện.', 10);
INSERT INTO public.recipe_steps VALUES (3673, '2025-11-20 17:11:43.481481', '2025-11-20 17:11:43.481481', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 597, 2, 'Rây bột mì vào âu to, thêm 1/4 thìa cà phê muối, 1 muỗng canh dầu olive, cho hỗn hợp men nở, sữa tươi không đường vào từ từ.', 10);
INSERT INTO public.recipe_steps VALUES (3674, '2025-11-20 17:11:43.482487', '2025-11-20 17:11:43.482487', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 597, 9, 'Phần sốt nền: Cà chua khía nhẹ hình chữ thập trên đầu, đem luộc vài phút, ngâm nước lạnh, bỏ vỏ, xay nhuyễn. Phi thơm tỏi cùng bơ, cho hành tây xắt hạt lựu, thêm cà chua xay vào, nêm đường, muối, chút tương cà ketchup và nước, nấu cho tới khi hỗn hợp sền sệt, thêm hạt tiêu, múc ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (3675, '2025-11-20 17:11:43.484257', '2025-11-20 17:11:43.484257', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 597, 11, 'Phết sốt nền lên đế bánh, thêm 1 lớp phô mai, kế đến là phần topping tùy chọn (xúc xích, ngô ngọt, hành tây, ớt chuông...) rồi thêm 1 lớp phô mai, đặt lên chảo chống dính có phết sẵn ít dầu hoặc bơ, nướng ở lửa nhỏ. Nên đậy nắp để phô mai tan chảy và các nguyên liệu nhanh chín.', 10);
INSERT INTO public.recipe_steps VALUES (3676, '2025-11-20 17:11:43.486358', '2025-11-20 17:11:43.486358', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 597, 7, 'Dùng nĩa châm kín bề mặt phần đế để nướng không bị phồng.', 10);
INSERT INTO public.recipe_steps VALUES (3677, '2025-11-20 17:11:43.487878', '2025-11-20 17:11:43.487878', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 597, 1, 'Pha men nở với chút nước ấm, khuấy tan để kích hoạt men hoạt động tốt.', 10);
INSERT INTO public.recipe_steps VALUES (3678, '2025-11-20 17:11:43.489026', '2025-11-20 17:11:43.489026', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 597, 4, 'Sau đó, tiếp tục nhào bột cho mịn, phủ khăn ẩm, ủ tiếp 30 phút.', 10);
INSERT INTO public.recipe_steps VALUES (3679, '2025-11-20 17:11:43.490533', '2025-11-20 17:11:43.490533', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 597, 5, 'Sau khi bột nở phồng gấp đôi, ấn xẹp bớt, nhào nhẹ bột 15 giây và cho bột nghỉ 5 phút và chia làm 2 phần (2 đế).', 10);
INSERT INTO public.recipe_steps VALUES (3680, '2025-11-20 17:11:43.697758', '2025-11-20 17:11:43.697758', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 598, 2, 'Khứa lên mình cá vài lát chéo để khi ướp thấm gia vị nhanh cũng như khi hấp nhanh chín và chín đều hơn.', 10);
INSERT INTO public.recipe_steps VALUES (3681, '2025-11-20 17:11:43.699355', '2025-11-20 17:11:43.699355', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 598, 10, 'Nước chấm:Có 2 kiểu nước chấm, tùy theo khẩu vị gia đình mà bạn điều chỉnh cho hợp lý:', 10);
INSERT INTO public.recipe_steps VALUES (3682, '2025-11-20 17:11:43.700963', '2025-11-20 17:11:43.700963', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 598, 6, 'Trải một lớp giấy bạc, lót một ít lá sấu non bên dưới, đặt cá lên. Tiếp tục lấy ít lá sấu non phủ lên mình cá. Sau đó, gói kín giấy bạc lại.', 10);
INSERT INTO public.recipe_steps VALUES (3683, '2025-11-20 17:11:43.702642', '2025-11-20 17:11:43.702642', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 598, 9, 'Lấy cá cho vào nồi hấp khoảng 25 - 30 phút là chín, tùy vào khối lượng, kích thước cá lớn hay bé.', 10);
INSERT INTO public.recipe_steps VALUES (3684, '2025-11-20 17:11:43.704859', '2025-11-20 17:11:43.704859', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 598, 3, 'Chọn những cành sấu non, nhặt lấy phần lá, ngâm nước muối loãng, rửa lại sạch, để ráo nước. Chú ý không lấy lá già vì có vị chát.', 10);
INSERT INTO public.recipe_steps VALUES (3741, '2025-11-20 17:11:45.143372', '2025-11-20 17:11:45.143372', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 603, 4, 'Tiếp tục ninh xương ống để lấy nước dùng.', 10);
INSERT INTO public.recipe_steps VALUES (3685, '2025-11-20 17:11:43.706468', '2025-11-20 17:11:43.706468', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 598, 5, 'Đeo găng tay, lấy hỗn hợp lá sấu non đã giã, thoa đều khắp mình cá. Thêm cả vào trong bụng cá. Rưới thêm 1 thìa canh mỡ lợn (hoặc dầu ăn) để giúp cá khi hấp không bị khô thịt.', 10);
INSERT INTO public.recipe_steps VALUES (3686, '2025-11-20 17:11:43.708586', '2025-11-20 17:11:43.708586', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 598, 7, 'Ướp tối thiểu 15-20 phút hoặc lâu hơn thì cho vào ngăn mát tủ lạnh để cá thấm đều gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (3687, '2025-11-20 17:11:43.710182', '2025-11-20 17:11:43.710182', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 598, 12, 'Nếu cuốn bánh tráng cùng rau củ thì bạn chấm với nước mắm tỏi ớt, thì là: 1 thìa canh đường + 1 thìa canh nước cốt chanh + 3 thìa canh nước lọc. Khuấy tan đường hoàn toàn rồi mới cho nước mắm và tỏi, ớt bằm nhuyễn, thì là cắt nhỏ vào cuối (đường tan hẳn sẽ giúp tỏi ớt, thì là nổi lên bề mặt).', 10);
INSERT INTO public.recipe_steps VALUES (3688, '2025-11-20 17:11:43.711808', '2025-11-20 17:11:43.711808', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 598, 8, 'Hấp cá:Cho lượng nước vừa đủ vào nồi hấp.', 10);
INSERT INTO public.recipe_steps VALUES (3689, '2025-11-20 17:11:43.714025', '2025-11-20 17:11:43.714025', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 598, 4, 'Cho lá sấu non vào cối, thêm 1 thìa canh muối hạt, chút hạt mắc khén, hạt dổi, 1-2 quả ớt, 1-2 thìa cà phê hạt nêm và giã nát.', 10);
INSERT INTO public.recipe_steps VALUES (3690, '2025-11-20 17:11:43.716241', '2025-11-20 17:11:43.716241', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 598, 1, 'Cá chép đánh vẩy, mổ bụng và làm sạch. Dùng muối hạt và chanh chà xát để khử mùi, rửa sạch, thấm khô.', 10);
INSERT INTO public.recipe_steps VALUES (3691, '2025-11-20 17:11:43.717327', '2025-11-20 17:11:43.717327', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 598, 11, 'Nếu chấm trực tiếp thì chấm với hỗn hợp muối hạt + hạt mắc khén + ớt + chút hạt nêm giã nát. Vắt thêm chút nước cốt chanh vào trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (3692, '2025-11-20 17:11:44.071401', '2025-11-20 17:11:44.071401', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 599, 2, 'Gà làm lông rửa sạch để ráo. Cà chua rửa sạch tỉa bông. Xà lách rửa sạch để ráo. Sau khi gà đã ráo ta dùng gia vị ướp gà trong ngoài để khoảng 20 phút.', 10);
INSERT INTO public.recipe_steps VALUES (3693, '2025-11-20 17:11:44.073655', '2025-11-20 17:11:44.073655', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 599, 3, 'Nước phá lấu đã đun một giờ xong thì thả gà vào nấu khoảng 10 phút. Gà nấu đã thấm gia vị, vớt ra, để ráo rồi cho vào lò điện lu hoặc lò quay 20 phút thì lấy ra, xối dầu nóng xối lên gà cho da giòn.', 10);
INSERT INTO public.recipe_steps VALUES (3694, '2025-11-20 17:11:44.075261', '2025-11-20 17:11:44.075261', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 599, 4, 'Xếp xà lách + dưa leo + cà chua vào một góc đĩa rồi chặt gà ra từng miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (3695, '2025-11-20 17:11:44.076861', '2025-11-20 17:11:44.076861', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 599, 1, 'Chế biến nước phá lấu: Cho quế + tai vị + đinh hương + tiêu sọ vào xoong cùng nước đun sôi, tiếp tục cho rượu + mật ong + kíp chấp + muối đun một giờ.', 10);
INSERT INTO public.recipe_steps VALUES (3696, '2025-11-20 17:11:44.307662', '2025-11-20 17:11:44.307662', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 600, 6, 'Bột bánh canh sau khi đã ủ 30 phút. Dùng một cán chày cán mỏng tầm 0,5 cm, sau đó dùng dao cắt thành từng sợi dài. Hoặc bạn cũng có thể bao bột quanh một chai thủy tinh, rồi cắt trực tiếp từng sợi vào nồi nước dùng. Cứ như vậy bạn cắt cho đến hết bột hoặc điều chỉnh độ đặc của món ăn theo ý thích. Lúc này bạn để lửa vừa, không để sôi mạnh quá bánh sẽ bị nát, khi sợi bánh nổi lên, bột trong là đã chín. Nêm nếm lại cho vừa ăn. Múc ra bát, rắc thêm hành lá, hành phi và một chút tiêu rồi thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (3697, '2025-11-20 17:11:44.309261', '2025-11-20 17:11:44.309261', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 600, 4, 'Cà rốt, củ cải gọt vỏ, cắt miếng dày 1cm. Hành lá rửa sạch thái nhỏ. Hành khô một nửa thái mỏng phi vàng để ra bát, một nửa băm nhỏ để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (3698, '2025-11-20 17:11:44.310331', '2025-11-20 17:11:44.310331', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 600, 2, 'Vịt xiêm (con ngan) mua về sơ chế sạch, dùng rượu, gừng và muối chà xát mạnh lên da vịt cho tiết bã nhờn, rửa sạch nhiều lần cho hết mùi hôi. Chặt miếng bằng cỡ bao diêm.', 10);
INSERT INTO public.recipe_steps VALUES (3699, '2025-11-20 17:11:44.311934', '2025-11-20 17:11:44.311934', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 600, 1, 'Khoai lang rửa sạch cho vào nồi luộc chín. Khi khoai còn nóng, dùng muôi nghiền cho khoai nhuyễn mịn. Cho bột khoai ra mâm rộng, trộn đều bột năng, bột gạo tẻ và khoai với nhau. Nhồi cho bột mịn thành một khối dẻo, không dính tay. Đậy một chiếc khăn mỏng sạch cho bột nghỉ 30 phút.', 10);
INSERT INTO public.recipe_steps VALUES (3700, '2025-11-20 17:11:44.313567', '2025-11-20 17:11:44.313567', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 600, 3, 'Ướp với 2 thìa cà phê muối, 1/2 thìa cà phê tiêu, 1/2 thìa cà phê hạt nêm. Để 30 phút cho ngấm.', 10);
INSERT INTO public.recipe_steps VALUES (3701, '2025-11-20 17:11:44.314626', '2025-11-20 17:11:44.314626', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 600, 5, 'Cho 2 thìa canh dầu ăn vào đun nóng, cho hành băm nhỏ vào phi thơm. Cho vịt vào xào săn. Khi thịt đã săn và ngấm gia vị. Cho nước vào ngập thịt. Đun sôi tầm 7 phút, cho cà rốt và củ cải vào, hạ nhỏ lửa đun liu riu thêm 20 phút cho thịt mềm.', 10);
INSERT INTO public.recipe_steps VALUES (3702, '2025-11-20 17:11:44.479672', '2025-11-20 17:11:44.479672', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 601, 8, 'Vớt ngan ra cho vào nước đá để giúp da giòn, hoặc phủ khăn xô để nguội. Tùy theo sở thích mỗi người mà có thể: lọc xương, thái miếng hoặc xé, chặt miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (3703, '2025-11-20 17:11:44.481302', '2025-11-20 17:11:44.481302', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 601, 14, 'Chuẩn bị các nguyên liệu khác:Rửa sạch rau sống, ngâm nước muối loãng, vẩy ráo', 10);
INSERT INTO public.recipe_steps VALUES (3704, '2025-11-20 17:11:44.482883', '2025-11-20 17:11:44.482883', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 601, 11, 'Cách làm mọc (tùy chọn để phần topping thêm phong phú):Ngâm nở nấm hương, rửa sạch, để ráo, thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3705, '2025-11-20 17:11:44.484479', '2025-11-20 17:11:44.484479', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 601, 5, 'Đun nước hơi ấm và cho ngan vào. Luộc ngan từ nước ấm sẽ giúp thịt không bị đỏ thịt và thịt ngan đậm đà, mọng nước hơn. Thêm gừng, hành khô (nếu nướng sẽ giúp nước dùng thơm ngon hơn).', 10);
INSERT INTO public.recipe_steps VALUES (3706, '2025-11-20 17:11:44.486103', '2025-11-20 17:11:44.486103', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 601, 12, 'Trộn giò sống với nấm hương, thêm chút hạt tiêu, hạt nêm (nếu nhà có trẻ nhỏ thì không nên cho hạt tiêu).', 10);
INSERT INTO public.recipe_steps VALUES (3707, '2025-11-20 17:11:44.487744', '2025-11-20 17:11:44.487744', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 601, 18, 'Trình bày và thưởng thức: Xếp miến chần vào bát tô, xếp thịt ngan, lòng ngan, mọc, hành chần, măng, rau mùi tàu thái nhỏ, hành lá thái nhỏ và múc nước dùng nóng chan vào và thưởng thức nóng. Khi ăn, rắc thêm chút hạt tiêu, giấm ớt, ăn kèm rau sống tùy chọn.', 10);
INSERT INTO public.recipe_steps VALUES (3803, '2025-11-20 17:11:46.674269', '2025-11-20 17:11:46.674269', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 608, 14, 'Xếp tất cả dưa chuột vào lọ, sau 1-2 ngày là ăn được.', 10);
INSERT INTO public.recipe_steps VALUES (3708, '2025-11-20 17:11:44.489346', '2025-11-20 17:11:44.489346', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 601, 10, 'Nước dùng: Vớt bỏ xương, nêm nếm theo khẩu vị. Bạn có thể cho măng đã xào vào lúc này (hoặc để riêng cho vào bát khi ăn). Nếu cho măng vào nồi nước dùng thì bạn nên nấu hai lửa (đun sôi, tắt rồi lại đun sôi, tắt) giúp măng ngon và đậm vị hơn.', 10);
INSERT INTO public.recipe_steps VALUES (3709, '2025-11-20 17:11:44.490944', '2025-11-20 17:11:44.490944', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 601, 9, 'Riêng phần xương và chân, cổ cánh, đầu tiếp tục ninh để ngọt nước dùng. Phần tiết, lòng ngan thì luộc chín, vớt ra, thái miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (3710, '2025-11-20 17:11:44.492025', '2025-11-20 17:11:44.492025', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 601, 7, 'Sau 25-30 phút luộc, tắt bếp, ngâm 10-15 phút.', 10);
INSERT INTO public.recipe_steps VALUES (3711, '2025-11-20 17:11:44.493632', '2025-11-20 17:11:44.493632', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 601, 16, 'Hành lá cắt đầu gốc trắng và chần để riêng, phần ngọn thái nhỏ. Mùi tàu thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3712, '2025-11-20 17:11:44.494709', '2025-11-20 17:11:44.494709', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 601, 6, 'Thêm chút muối, hạt nêm để ngan luộc đậm vị. Khi nước sôi, hớt bỏ bọt, hạ nhỏ lửa, đậy vung.', 10);
INSERT INTO public.recipe_steps VALUES (3713, '2025-11-20 17:11:44.496301', '2025-11-20 17:11:44.496301', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 601, 3, 'Ngan làm sạch, cắt bỏ phao câu vì phần này chứa tuyến nhờn gây hôi.', 10);
INSERT INTO public.recipe_steps VALUES (3714, '2025-11-20 17:11:44.497357', '2025-11-20 17:11:44.497357', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 601, 13, 'Cho hỗn hợp giò sống và nấm hương vào túi nilon, buộc một đầu, cắt 1 góc nhọn. Lần lượt bóp, vắt thả mọc, dùng đũa gạt vào nồi nước dùng đang sôi. Khi mọc nổi lên là đã chín.', 10);
INSERT INTO public.recipe_steps VALUES (3715, '2025-11-20 17:11:44.498953', '2025-11-20 17:11:44.498953', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 601, 15, 'Hành tây thái lát mỏng, ngâm nước đá cho bớt hăng.', 10);
INSERT INTO public.recipe_steps VALUES (3716, '2025-11-20 17:11:44.500559', '2025-11-20 17:11:44.500559', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 601, 2, 'Cho một thìa canh mỡ lợn, phi thơm tỏi và cho măng vào xào, múc chút váng mỡ trong nồi nước luộc ngan cho vào tạo vị ngọt, nêm nếm mắm muối, hạt nêm theo khẩu vị. Múc ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (3717, '2025-11-20 17:11:44.501618', '2025-11-20 17:11:44.501618', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 601, 1, 'Măng khô rửa sạch, ngâm nước vo gạo qua đêm cho nở. Sau đó, luộc 3 - 4 lần cho tới khi măng mềm, nước trong, rửa sạch, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (3718, '2025-11-20 17:11:44.503328', '2025-11-20 17:11:44.503328', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 601, 17, 'Miến rửa sạch, ngâm mềm, rồi chần qua nồi nước dùng.', 10);
INSERT INTO public.recipe_steps VALUES (3719, '2025-11-20 17:11:44.504919', '2025-11-20 17:11:44.504919', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 601, 4, 'Chà xát muối hạt, chanh khắp mình ngan, rồi rửa sạch để khử mùi.', 10);
INSERT INTO public.recipe_steps VALUES (3720, '2025-11-20 17:11:44.812147', '2025-11-20 17:11:44.812147', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 602, 1, 'Thịt bò rửa sạch, thấm khô, đem thái thành sợi nhỏ, hoặc thái mỏng hay băm nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3721, '2025-11-20 17:11:44.813735', '2025-11-20 17:11:44.813735', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 602, 20, 'Đậy vung nồi, đặt nồi lên bếp đun 5-7 phút, để lửa nhỏ để phần cơm ở dưới được giòn, phần lòng đỏ trứng gà chín tới là được.', 10);
INSERT INTO public.recipe_steps VALUES (3722, '2025-11-20 17:11:44.81532', '2025-11-20 17:11:44.81532', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 602, 18, 'Xếp lần lượt các nguyên liệu đã chuẩn bị ở trên vào phía trên cơm.', 10);
INSERT INTO public.recipe_steps VALUES (3723, '2025-11-20 17:11:44.816932', '2025-11-20 17:11:44.816932', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 602, 21, 'Phần nước sốt:1 thìa canh tương ớt Hàn Quốc Gochujang, 1 thìa cà phê dầu mè, 1/2 thìa cà phê tỏi băm, 1 thìa cà phê giấm, 1 thìa canh nước trắng, 1 thìa cà phê đường, 1/2 thìa cà phê hạt tiêu, 1 thìa cà phê xì dầu, 1 thìa cà phê vừng rang chín.', 10);
INSERT INTO public.recipe_steps VALUES (3724, '2025-11-20 17:11:44.818516', '2025-11-20 17:11:44.818516', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 602, 9, 'Thịt bò ướp gia vị đã ngấm, cho dầu ăn vào chảo, đổ thịt bò vào xào nhanh tay ở lửa lớn.', 10);
INSERT INTO public.recipe_steps VALUES (3725, '2025-11-20 17:11:44.82066', '2025-11-20 17:11:44.82066', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 602, 10, 'Thịt chín tới thì đổ ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (3726, '2025-11-20 17:11:44.822252', '2025-11-20 17:11:44.822252', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 602, 14, 'Thả giá đỗ vào nồi nước vừa luộc rau cải, trần giá đỗ chín tới, vớt ra để riêng và để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (3727, '2025-11-20 17:11:44.823828', '2025-11-20 17:11:44.823828', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 602, 5, 'Bí ngòi thái sợi hoặc bào sợi.', 10);
INSERT INTO public.recipe_steps VALUES (3728, '2025-11-20 17:11:44.825526', '2025-11-20 17:11:44.825526', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 602, 11, 'Vẫn dùng cái chảo thịt bò vừa xong, cho chút dầu ăn vào, dầu nóng đổ bí ngòi vào xào chín tới, không xào kĩ bí dễ bị nhũn, thêm vào xíu bột canh hoặc bột nêm.', 10);
INSERT INTO public.recipe_steps VALUES (3729, '2025-11-20 17:11:44.827135', '2025-11-20 17:11:44.827135', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 602, 7, 'Nấm đông cô thái nhỏ, nếu dùng nấm kim châm thì cắt rễ, rửa sạch để ráo. (Không có nấm tươi thì thay bằng nấm hương khô).', 10);
INSERT INTO public.recipe_steps VALUES (3730, '2025-11-20 17:11:44.829263', '2025-11-20 17:11:44.829263', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 602, 6, 'Rau cải nó xôi rửa sạch, cắt khúc.', 10);
INSERT INTO public.recipe_steps VALUES (3731, '2025-11-20 17:11:44.830898', '2025-11-20 17:11:44.830898', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 602, 2, 'Ướp thịt bò với: 1 thìa cà phê tỏi băm, 1 thìa cà phê gừng băm, 1 thìa cà phê dầu mè, 1 thìa cà phê dầu hào, 1 thìa cà phê nước tương, 1 chút tiêu.', 10);
INSERT INTO public.recipe_steps VALUES (3732, '2025-11-20 17:11:44.831955', '2025-11-20 17:11:44.831955', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 602, 17, 'Chuẩn bị một cái nồi đất, cho vào nồi khoảng 1 thìa canh dầu ăn, đổ cơm vào và dàn đều.', 10);
INSERT INTO public.recipe_steps VALUES (3733, '2025-11-20 17:11:44.833562', '2025-11-20 17:11:44.833562', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 602, 13, 'Đun sôi nồi nước, thả rau cải vào luộc, rau cải chín thì vớt ra rổ cho ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (3734, '2025-11-20 17:11:44.835156', '2025-11-20 17:11:44.835156', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 602, 15, 'Rau cải nguội và ráo nước thì vắt qua một lần nữa cho hết nước hẳn. Tương tự giá đỗ cũng làm vậy cho khô nước.', 10);
INSERT INTO public.recipe_steps VALUES (3735, '2025-11-20 17:11:44.836742', '2025-11-20 17:11:44.836742', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 602, 8, 'Kim chi thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3736, '2025-11-20 17:11:44.837791', '2025-11-20 17:11:44.837791', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 602, 12, 'Tiếp tục dùng chảo đó để xào lần lượt: cà rốt, nấm và để riêng từng loại.', 10);
INSERT INTO public.recipe_steps VALUES (3737, '2025-11-20 17:11:44.839393', '2025-11-20 17:11:44.839393', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 602, 16, 'Trộn vào rau cải, giá đỗ một chút dầu mè và xì dầu.', 10);
INSERT INTO public.recipe_steps VALUES (3738, '2025-11-20 17:11:44.840511', '2025-11-20 17:11:44.840511', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 602, 19, 'Cho một lòng đỏ trứng gà lên trên cùng, rắc chút mè lên trên.', 10);
INSERT INTO public.recipe_steps VALUES (3739, '2025-11-20 17:11:44.842125', '2025-11-20 17:11:44.842125', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 602, 3, 'Trộn thật đều và để ngấm gia vị trong 15 phút.', 10);
INSERT INTO public.recipe_steps VALUES (3740, '2025-11-20 17:11:44.84426', '2025-11-20 17:11:44.84426', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 602, 4, 'Cà rốt thái sợi nhỏ hoặc bào sợi.', 10);
INSERT INTO public.recipe_steps VALUES (3742, '2025-11-20 17:11:45.14496', '2025-11-20 17:11:45.14496', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 603, 1, 'Rửa sạch xương ống, móng giò, thịt chân giò, cho vào nồi cùng một nhánh gừng cùng chút muối và chần trong vài phút để loại bỏ tạp chất. Lấy ra, rửa sạch lại.', 10);
INSERT INTO public.recipe_steps VALUES (3743, '2025-11-20 17:11:45.146018', '2025-11-20 17:11:45.146018', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 603, 3, 'Sau 30 phút thì vớt thịt chân giò và móng giò ra cho vào bát nước sôi để nguội kèm đá viên và vài lát chanh. Khi nguội, vớt ra thấm khô. Riêng phần thịt chân giò phủ khăn xô cho vào ngăn mát tủ lạnh để giúp se kết dính lại giúp thái dễ và đẹp hơn.', 10);
INSERT INTO public.recipe_steps VALUES (3744, '2025-11-20 17:11:45.147686', '2025-11-20 17:11:45.147686', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 603, 8, 'Trộn phần thịt dăm xay cùng mộc nhĩ đã ngâm nở, rửa sạch, thái nhỏ và chút hành khô băm nhỏ cùng chút hạt nêm, hạt tiêu ướp trong 15 phút. Phần thịt này tùy theo sở thích có thể chia làm 2 chả: Chả thịt lá xương sông và chả viên rán.', 10);
INSERT INTO public.recipe_steps VALUES (3745, '2025-11-20 17:11:45.149291', '2025-11-20 17:11:45.149291', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 603, 14, 'Phần khác:Rau thơm các loại rửa sạch, thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3746, '2025-11-20 17:11:45.150886', '2025-11-20 17:11:45.150886', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 603, 7, 'Phần topping:Chả thịt lá xương sông:', 10);
INSERT INTO public.recipe_steps VALUES (3747, '2025-11-20 17:11:45.152485', '2025-11-20 17:11:45.152485', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 603, 11, 'Nếu thích làm thêm chả viên rán thì bạn trừ một nửa thịt và múc các thìa nhỏ viên tròn lại, đem chiên chín.', 10);
INSERT INTO public.recipe_steps VALUES (3748, '2025-11-20 17:11:45.153749', '2025-11-20 17:11:45.153749', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 603, 5, 'Phần hoa chuối: Dùng dao sắc thái mỏng và ngâm vào nước vo gạo pha chút nước cốt chanh để giúp hoa chuối không bị thâm và bớt chát.', 10);
INSERT INTO public.recipe_steps VALUES (3749, '2025-11-20 17:11:45.155349', '2025-11-20 17:11:45.155349', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 603, 10, 'Sau đó, chiên sơ chả xương sông và cho vào nồi nước dùng, nấu cho tới khi chả chín mềm thì vớt ra.', 10);
INSERT INTO public.recipe_steps VALUES (3750, '2025-11-20 17:11:45.156931', '2025-11-20 17:11:45.156931', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 603, 2, 'Cho xương ống, móng giò, thịt chân giò vào nồi cùng vài lát gừng đập dập, đầu hành trắng (hoặc hành tím), chút muối hạt, thêm lượng nước ngập mặt và bật bếp. Khi sôi, hớt bỏ bọt và hạ nhỏ lửa luộc chín.', 10);
INSERT INTO public.recipe_steps VALUES (3751, '2025-11-20 17:11:45.157981', '2025-11-20 17:11:45.157981', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 603, 9, 'Lá xương sông rửa sạch, múc thịt cho vào giữa và gói thành các viên vừa ăn, chú ý gói làm sao để không hở thịt ra để tránh bị vỡ khi nấu (có thể gói nhiều lớp và dùng lạt hoặc chỉ buộc lại).', 10);
INSERT INTO public.recipe_steps VALUES (3752, '2025-11-20 17:11:45.159561', '2025-11-20 17:11:45.159561', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 603, 6, 'Cà chua thái múi cau. Phi thơm hành, cho cà chua vào xào sơ, thêm hoa chuối xào cùng, nêm chút gia vị. Sau đó, vớt phần xương ống ra, cho hoa chuối vào nấu ''''bung'''' chín mềm. Nêm vào chút dấm bỗng cùng mắm muối, hạt nêm phù hợp khẩu vị gia đình.', 10);
INSERT INTO public.recipe_steps VALUES (3753, '2025-11-20 17:11:45.161161', '2025-11-20 17:11:45.161161', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 603, 13, 'Xếp thịt chân giò, móng giò ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (3754, '2025-11-20 17:11:45.162826', '2025-11-20 17:11:45.162826', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 603, 15, 'Bún trụng qua nước sôi cho bớt chua.', 10);
INSERT INTO public.recipe_steps VALUES (3755, '2025-11-20 17:11:45.164423', '2025-11-20 17:11:45.164423', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 603, 12, 'Phần thịt chân giò: Dùng dao sắc thái thịt chân giò mỏng theo khoanh.', 10);
INSERT INTO public.recipe_steps VALUES (3756, '2025-11-20 17:11:45.518428', '2025-11-20 17:11:45.518428', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 604, 4, 'Trộn đều cơm nguội với trứng cùng 2 thìa cà phê nước mắm, 1/2 thìa cà phê hạt nêm, 1/2 thìa cà phê bột cà ri Thái Lan.', 10);
INSERT INTO public.recipe_steps VALUES (3757, '2025-11-20 17:11:45.519436', '2025-11-20 17:11:45.519436', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 604, 5, 'Cho dầu ăn vào chảo, phi thơm 1/2 số lượng hành tỏi băm nhỏ, thêm tôm đã bóc vỏ vào xào săn. Tiếp đến, cho cà rốt, đậu Hà Lan, dứa cùng mắm muối, hạt nêm cho đậm đà. Thêm lạp xưởng vào đảo nhanh, khi lạp xưởng hơi se lại là tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (3758, '2025-11-20 17:11:45.522249', '2025-11-20 17:11:45.522249', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 604, 3, 'Lạp xưởng thái lát hoặc thái hạt lựu tùy chọn.', 10);
INSERT INTO public.recipe_steps VALUES (3759, '2025-11-20 17:11:45.523755', '2025-11-20 17:11:45.523755', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 604, 6, 'Rang cơm: Phi thơm số hành tỏi còn lại, cho cơm vào rang trên lửa vừa. Khi hạt cơm săn, khô lại thì thêm phần topping đã xào vào, thêm hạt điều rang. Nêm nếm lại gia vị cho phù hợp khẩu vị gia đình. Rắc thêm chút hành lá, đảo đều, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (3760, '2025-11-20 17:11:45.524772', '2025-11-20 17:11:45.524772', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 604, 2, 'Cà rốt thái hạt lựu.', 10);
INSERT INTO public.recipe_steps VALUES (3761, '2025-11-20 17:11:45.526856', '2025-11-20 17:11:45.526856', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 604, 7, 'Múc cơm rang ra cho vào vỏ quả dứa, trang trí thêm vài nhánh rau mùi, ớt (tùy chọn) và thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (3762, '2025-11-20 17:11:45.52785', '2025-11-20 17:11:45.52785', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 604, 1, 'Dứa để nguyên vỏ, bổ đôi, khoét lấy ruột và thái hạt lựu. Phần còn lại dùng thìa múc nếu còn, giữ phần vỏ để đựng cơm chiên.', 10);
INSERT INTO public.recipe_steps VALUES (3763, '2025-11-20 17:11:45.856484', '2025-11-20 17:11:45.856484', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 605, 6, 'Rau cải bó xôi rửa sạch, cắt khúc vừa ăn đem trần qua với nước sôi.', 10);
INSERT INTO public.recipe_steps VALUES (3764, '2025-11-20 17:11:45.857576', '2025-11-20 17:11:45.857576', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 605, 10, 'Pha hỗn hợp nước trộn: 4 thìa canh nước tương (xì dầu), 1 thìa canh đường, 2 thìa canh dầu mè, 1 bát con nước (bát ăn cơm), 2 thìa cà phê vừng rang thơm, 1 thìa canh dầu ăn.', 10);
INSERT INTO public.recipe_steps VALUES (3765, '2025-11-20 17:11:45.85863', '2025-11-20 17:11:45.85863', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 605, 14, 'Bày ra đĩa và rắc thêm chút vừng rang lên trên cho hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (3766, '2025-11-20 17:11:45.861309', '2025-11-20 17:11:45.861309', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 605, 7, 'Mộc nhĩ ngâm nở, rửa sạch, thái sợi nhỏ. Cà rốt bào sợi hoặc thái chỉ. Nấm hương tươi rửa sạch thái mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (3767, '2025-11-20 17:11:45.862316', '2025-11-20 17:11:45.862316', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 605, 12, 'Cho hỗn hợp nước trộn lên chảo, đun sôi rồi cho miến đã trần vào xào với lửa to, đảo liên tục, nước cạn, sợi miến dính chảo là được.', 10);
INSERT INTO public.recipe_steps VALUES (3768, '2025-11-20 17:11:45.863334', '2025-11-20 17:11:45.863334', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 605, 3, 'Đun sôi nồi nước cho vào chút muối, cho miến vào chần khoảng 3 phút vớt ra để ráo, trộn với chút dầu ăn để không dính vào nhau.', 10);
INSERT INTO public.recipe_steps VALUES (3769, '2025-11-20 17:11:45.865373', '2025-11-20 17:11:45.865373', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 605, 11, 'Khuấy đều các nguyên liệu.', 10);
INSERT INTO public.recipe_steps VALUES (3770, '2025-11-20 17:11:45.866451', '2025-11-20 17:11:45.866451', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 605, 9, 'Làm nóng chảo xào nhanh tay từng loại, xào với lửa to, chín tới.', 10);
INSERT INTO public.recipe_steps VALUES (3771, '2025-11-20 17:11:45.86806', '2025-11-20 17:11:45.86806', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 605, 1, 'Thịt bò rửa sạch thái con chì sợi dài ướp với một thìa canh xì dầu, một thìa canh dầu ăn, 1/4 thìa cà phê hạt tiêu, một thìa canh dầu hào, hai tép tỏi.', 10);
INSERT INTO public.recipe_steps VALUES (3772, '2025-11-20 17:11:45.870176', '2025-11-20 17:11:45.870176', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 605, 2, 'Ướp trong 15 phút cho ngấm.', 10);
INSERT INTO public.recipe_steps VALUES (3773, '2025-11-20 17:11:45.871764', '2025-11-20 17:11:45.871764', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 605, 13, 'Đợi miến gần nguội thì cho tất cả các nguyên liệu vào âu to hoặc bát to, riêng lòng trắng và lòng đỏ trứng để riêng trộn sau cùng để tránh bị nát. Đi bao tay vào trộn thật đều, nếu nhạt thì cho thêm chút nước tương.', 10);
INSERT INTO public.recipe_steps VALUES (3774, '2025-11-20 17:11:45.873396', '2025-11-20 17:11:45.873396', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 605, 4, 'Tách riêng lòng trắng và lòng đỏ của hai quả trứng gà, rồi tráng riêng lòng đỏ, lòng trắng sau đó thái chỉ. (Hoặc đánh tan lòng trắng với lòng đỏ tráng rồi thái chỉ).', 10);
INSERT INTO public.recipe_steps VALUES (3775, '2025-11-20 17:11:45.875012', '2025-11-20 17:11:45.875012', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 605, 5, 'Thịt bò sau khi ướp gia vị trong 15 phút, cho chút dầu vào chảo và xào thịt bò với lửa to, chín tới.', 10);
INSERT INTO public.recipe_steps VALUES (3776, '2025-11-20 17:11:45.876668', '2025-11-20 17:11:45.876668', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 605, 8, 'Dưa chuột bỏ ruột thái sợi. Hành tây thái nhỏ. Ớt chuông bỏ ruột thái sợi.', 10);
INSERT INTO public.recipe_steps VALUES (3777, '2025-11-20 17:11:46.049999', '2025-11-20 17:11:46.049999', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 606, 4, 'Nước súp thịt bò rau củ đã nấu được 40 phút. Vớt sả, củ cải ra rồi cho nước trong mắm ruốc Huế và 400 ml nước dừa vào.', 10);
INSERT INTO public.recipe_steps VALUES (3778, '2025-11-20 17:11:46.052733', '2025-11-20 17:11:46.052733', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 606, 5, 'Cho 2 muỗng canh đường phèn (nếu không có sử dụng đường cát) vào nồi nước dùng. Thêm 2 muỗng cà phê muối, 2 muỗng cà phê bột nêm. Nấu nước dùng ở lửa nhỏ cho sôi lại.', 10);
INSERT INTO public.recipe_steps VALUES (3779, '2025-11-20 17:11:46.054241', '2025-11-20 17:11:46.054241', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 606, 7, 'Cho dầu ăn vào nồi, bật lửa nhỏ, cho tương cà chua vào nấu cho ra nước màu đẹp. Khi thấy dầu ra màu đỏ của tương cà chua thì đã đạt.', 10);
INSERT INTO public.recipe_steps VALUES (3780, '2025-11-20 17:11:46.055248', '2025-11-20 17:11:46.055248', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 606, 3, 'Mắm ruốc Huế hòa với một ít nước, cho lên bếp nấu tan. Vớt bọt, để lắng rồi lọc lấy nước trong.', 10);
INSERT INTO public.recipe_steps VALUES (3781, '2025-11-20 17:11:46.05778', '2025-11-20 17:11:46.05778', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 606, 6, 'Làm dầu màu:Chọn nồi có chiều cao tương đối để khi nấu dầu màu, không bị văng tung tóe ra ngoài.', 10);
INSERT INTO public.recipe_steps VALUES (3782, '2025-11-20 17:11:46.06035', '2025-11-20 17:11:46.06035', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 606, 9, 'Hoàn thành', 10);
INSERT INTO public.recipe_steps VALUES (3783, '2025-11-20 17:11:46.062047', '2025-11-20 17:11:46.062047', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 606, 2, 'Thịt bò rửa sạch, củ cải cắt khúc, thêm 3-4 củ sả vào nồi nước, nấu nước dùng.', 10);
INSERT INTO public.recipe_steps VALUES (3784, '2025-11-20 17:11:46.064209', '2025-11-20 17:11:46.064209', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 606, 8, 'Cho tất cả dầu màu vào nồi nước dùng đã chuẩn bị.', 10);
INSERT INTO public.recipe_steps VALUES (3785, '2025-11-20 17:11:46.065816', '2025-11-20 17:11:46.065816', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 606, 1, 'Làm nước dùng: Hành tím và gừng đập dập cho vào nồi chiên không dầu nướng vàng thơm.', 10);
INSERT INTO public.recipe_steps VALUES (3786, '2025-11-20 17:11:46.067422', '2025-11-20 17:11:46.067422', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 606, 10, 'Cắt thịt bò bày lên tô bún, đổ nước dùng, thêm hành lá hoặc rau thơm để trang trí.', 10);
INSERT INTO public.recipe_steps VALUES (3787, '2025-11-20 17:11:46.317549', '2025-11-20 17:11:46.317549', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 607, 3, 'Trộn đều thịt với các gia vị và ướp trong 20-30 phút cho ngấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (3788, '2025-11-20 17:11:46.319142', '2025-11-20 17:11:46.319142', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 607, 2, 'Ướp thịt bò với 100 ml sốt cà chua, 40 ml rượu vang đỏ hoặc 30 ml rượu gạo trắng, một gói gia vị bò kho hoặc chút ngũ vị hương, 5-6 thìa canh nước mắm ngon, 1 thìa cà phê hạt tiêu, 1 thìa canh đường (đường có thể cho hoặc không, tùy khẩu vị), tỏi băm, một nhánh gừng thái mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (3789, '2025-11-20 17:11:46.320735', '2025-11-20 17:11:46.320735', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 607, 5, 'Cà rốt gọt vỏ, rửa sạch, khía khoa cắt dầy 2 cm.', 10);
INSERT INTO public.recipe_steps VALUES (3790, '2025-11-20 17:11:46.321784', '2025-11-20 17:11:46.321784', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 607, 7, 'Sau 20 -30 phút ướp thịt, cho cà chua vào nồi xào cho chín mềm, tiếp tục đổ hết phần nạm bò đã ướp gia vị vào xào qua.', 10);
INSERT INTO public.recipe_steps VALUES (3791, '2025-11-20 17:11:46.323347', '2025-11-20 17:11:46.323347', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 607, 8, 'Đổ khoảng 2 bát con nước vào hầm khoảng 20 phút, thử thấy thịt bò gần mềm thì đổ khoai tây vào trước, đợi khoai tây gần chín mềm tiếp tục đổ nốt cà rốt vào hầm.', 10);
INSERT INTO public.recipe_steps VALUES (3792, '2025-11-20 17:11:46.325012', '2025-11-20 17:11:46.325012', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 607, 4, 'Cà chua rửa sạch, gạt bớt hạt, thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3793, '2025-11-20 17:11:46.32618', '2025-11-20 17:11:46.32618', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 607, 6, 'Khoai tây gọt vỏ ngâm nước cho đỡ thâm, vớt ra bổ làm bốn.', 10);
INSERT INTO public.recipe_steps VALUES (3794, '2025-11-20 17:11:46.327744', '2025-11-20 17:11:46.327744', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 607, 1, 'Thịt bò rửa thật sạch, đun sôi nồi nước, chần qua một lần cho hết mùi hôi, rửa lại một lần nữa và thái miếng vuông vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (3795, '2025-11-20 17:11:46.66303', '2025-11-20 17:11:46.66303', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 608, 6, 'Gừng,tỏi, hành tây xay nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3796, '2025-11-20 17:11:46.664698', '2025-11-20 17:11:46.664698', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 608, 15, 'Sau đó cất ngăn mát tủ lạnh, dùng được trong một tuần.', 10);
INSERT INTO public.recipe_steps VALUES (3797, '2025-11-20 17:11:46.665768', '2025-11-20 17:11:46.665768', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 608, 4, 'Lá hẹ, hành lá rửa sạch cắt khúc dài khoảng 3 cm.', 10);
INSERT INTO public.recipe_steps VALUES (3798, '2025-11-20 17:11:46.667364', '2025-11-20 17:11:46.667364', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 608, 5, 'Cà rốt, củ cải gọt vỏ cắt hoặc bào sợi dài 3 cm.', 10);
INSERT INTO public.recipe_steps VALUES (3799, '2025-11-20 17:11:46.668939', '2025-11-20 17:11:46.668939', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 608, 13, 'Dùng tay (đeo găng) phết phần xốt trộn vào từng kẽ của quả dưa, nhẹ nhàng tránh bị gẫy, sau đó nhét tiếp chút lá hẹ, cà rốt, củ cải, hành lá vào giữa các nhánh của quả dưa.', 10);
INSERT INTO public.recipe_steps VALUES (3800, '2025-11-20 17:11:46.67', '2025-11-20 17:11:46.67', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 608, 3, 'Cho 2 thìa canh muối vào dưa xóc đều để 30 phút sau đó chắt bỏ hết phần nước muối, không rửa lại như cách muối kim chi cải thảo.', 10);
INSERT INTO public.recipe_steps VALUES (3801, '2025-11-20 17:11:46.671624', '2025-11-20 17:11:46.671624', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 608, 8, 'Cá cơm ngâm nước ấm cho mềm, rửa thật sạch.', 10);
INSERT INTO public.recipe_steps VALUES (3802, '2025-11-20 17:11:46.67268', '2025-11-20 17:11:46.67268', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 608, 2, 'Chẻ dưa chuột làm bốn nhưng không chẻ hết mà chừa ra ở phần đuôi khoảng 3cm (những quả dài nên cắt làm đôi trước khi chẻ).', 10);
INSERT INTO public.recipe_steps VALUES (3804, '2025-11-20 17:11:46.676399', '2025-11-20 17:11:46.676399', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 608, 9, 'Cho 2,5 bát (chén) nước cùng 15 gram cá cơm khô vào đun sôi trong 20-30 phút, vớt bã lấy nước cốt, đun nhỏ lửa.', 10);
INSERT INTO public.recipe_steps VALUES (3805, '2025-11-20 17:11:46.677991', '2025-11-20 17:11:46.677991', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 608, 1, 'Dưa chuột rửa sạch, cắt bỏ đầu và đuôi, lau khô từng quả.', 10);
INSERT INTO public.recipe_steps VALUES (3806, '2025-11-20 17:11:46.67919', '2025-11-20 17:11:46.67919', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 608, 10, 'Hoà 2 thìa bột nếp với chút nước cho tan rồi đổ vào nồi nước cốt cá cơm, sôi lăn tăn rồi tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (3807, '2025-11-20 17:11:46.680769', '2025-11-20 17:11:46.680769', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 608, 12, 'Trộn đều các nguyên liệu là đã xong hỗn hợp xốt trộn (lúc này có thể nêm nếm lại gia vị cho vừa ăn để điều chỉnh thêm)', 10);
INSERT INTO public.recipe_steps VALUES (3808, '2025-11-20 17:11:46.682376', '2025-11-20 17:11:46.682376', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 608, 7, 'Táo, lê gọt vỏ, bỏ lõi, xay nhỏ ép lấy nước cốt.', 10);
INSERT INTO public.recipe_steps VALUES (3809, '2025-11-20 17:11:46.68353', '2025-11-20 17:11:46.68353', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 608, 11, 'Cho hết cả phần ớt bột Hàn Quốc vào cùng và khuấy đều, tiếp đến là nước mắm, đường, muối, gừng tỏi xay, nước ép táo lê, nước mơ ngâm, cuối cùng mới cho cà rốt bào sợi, củ cải bào sợi, hành lá, hẹ cắt khúc.', 10);
INSERT INTO public.recipe_steps VALUES (3810, '2025-11-20 17:11:47.277826', '2025-11-20 17:11:47.277826', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 609, 4, 'Nước luộc ốc giữ lại, lọc lấy nước trong, để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (3811, '2025-11-20 17:11:47.279343', '2025-11-20 17:11:47.279343', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 609, 7, 'Cho xương vào nồi sâu cùng lượng nước vừa đủ, thêm chút muối, vài củ hành tím, đun sôi, hớt bỏ bọt, hạ nhỏ lửa lăn tăn, hé mở vung ninh từ 2,5 giờ để lấy nước dùng ngọt tự nhiên, thanh trong. Thỉnh thoảng hớt bỏ bọt.', 10);
INSERT INTO public.recipe_steps VALUES (3812, '2025-11-20 17:11:47.280351', '2025-11-20 17:11:47.280351', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 609, 2, 'Tiếp đến, cho ốc vào nồi đổ thêm 250ml nước và 100ml bỗng rượu xăm xấp, đun sôi bồng lên thì mở vung, hạ lửa, rồi tăng lửa bồng lên đến khi ốc mở miệng bong vảy là vừa đủ chín (ốc giòn ngon), tắt bếp, vớt ra.', 10);
INSERT INTO public.recipe_steps VALUES (3813, '2025-11-20 17:11:47.28287', '2025-11-20 17:11:47.28287', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 609, 3, 'Chặt trôn khều ốc, bỏ ruột đen, để riêng vào bát.', 10);
INSERT INTO public.recipe_steps VALUES (3814, '2025-11-20 17:11:47.283872', '2025-11-20 17:11:47.283872', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 609, 1, 'a) Cách làm ốc:Ngâm ốc trong thau kim loại (sẽ nhả bùn nhanh) cùng nước vo gạo kèm vài ớt tươi, thêm chút bỗng rượu trong 2-3 giờ để nhả hết bùn bẩn, khử mùi tanh mà ốc lại béo. Rửa sạch ốc.', 10);
INSERT INTO public.recipe_steps VALUES (3815, '2025-11-20 17:11:47.285877', '2025-11-20 17:11:47.285877', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 609, 8, 'Khi đã ninh xong, lọc nước xương trong thanh.', 10);
INSERT INTO public.recipe_steps VALUES (3816, '2025-11-20 17:11:47.287898', '2025-11-20 17:11:47.287898', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 609, 11, 'Phi thơm hành khô và mỡ lợn, cho cà chua vào xào cho tới khi vơi bớt nước và hơi sánh thì cho ớt bột vào chưng, nêm muối. Tắt bếp để ớt ngấm mỡ vài phút, tiếp tục bật bếp chưng lại lần nữa để lên màu tự nhiên, đẹp và thơm mùi đặc trưng.', 10);
INSERT INTO public.recipe_steps VALUES (3817, '2025-11-20 17:11:47.289083', '2025-11-20 17:11:47.289083', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 609, 5, 'b) Cách làm nước riêu ốc:Là sự kết hợp hài hòa của nước ninh xương lợn ngọt trong, nước luộc ốc và dấm bỗng nếp chua thanh', 10);
INSERT INTO public.recipe_steps VALUES (3818, '2025-11-20 17:11:47.290672', '2025-11-20 17:11:47.290672', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 609, 6, 'Cách ninh nước xương lợn: Ngâm xương cùng nước ấm (hoặc nước vo gạo càng sạch) và muối hạt 1 giờ để loại bỏ tạp chất, sạch máu, rửa sạch. Tiếp tục cho xương vào chần, rửa sạch lại lần nữa.', 10);
INSERT INTO public.recipe_steps VALUES (3819, '2025-11-20 17:11:47.292291', '2025-11-20 17:11:47.292291', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 609, 9, 'Pha nước riêu ốc: Kết hợp nước ninh xương (đã lọc) với nước luộc ốc (đã lọc) và thêm từ từ dấm bỗng (theo khẩu vị), đun sôi và nêm nếm gia vị (muối, mắm, hạt nêm theo khẩu vị gia đình), tắt bếp, để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (3820, '2025-11-20 17:11:47.293895', '2025-11-20 17:11:47.293895', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 609, 10, 'c) Cách làm nước màu:Cà chua bổ đôi trụng qua nước sôi, bóc vỏ, dằm nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (3821, '2025-11-20 17:11:47.949911', '2025-11-20 17:11:47.949911', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 610, 2, 'Cho tai heo vào nồi ngập nước, thêm 1 thìa canh giấm, 1-2 thìa cà phê muối, 1 thìa cà phê hạt nêm, 2 củ hành tím đập dập, 1 củ gừng nhỏ rửa sạch đập dập, bật bếp đun sôi. Khi sôi, hạ nhỏ lửa, luộc tai heo trong 20 phút.', 10);
INSERT INTO public.recipe_steps VALUES (3822, '2025-11-20 17:11:47.951539', '2025-11-20 17:11:47.951539', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 610, 7, 'Sau đó, vừa cho lần lượt từng thìa thính vào, vừa bóp thính ngấm đều vào tai heo. Rắc chút lá chanh và ớt thái khoanh lên trên.', 10);
INSERT INTO public.recipe_steps VALUES (3823, '2025-11-20 17:11:47.953148', '2025-11-20 17:11:47.953148', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 610, 6, 'c) Cách trộn tai heo và thính:Dùng dao sắc thái mỏng tai heo, ướp với 1 thìa cà phê muối, 1 thìa cà phê mì chính hoặc hạt nêm, 1/2 thìa cà phê hạt tiêu, 1 thìa canh tỏi giã nhỏ, lá chanh thái chỉ, đeo gang tay trộn đều cho tai heo thấm gia vị. Nếu thích ăn cay thì bạn cho ớt vào lúc này. Còn nhà có trẻ nhỏ không nên cho ớt và giảm hạt tiêu.', 10);
INSERT INTO public.recipe_steps VALUES (3824, '2025-11-20 17:11:47.954785', '2025-11-20 17:11:47.954785', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 610, 3, 'Vớt tai heo ra ngâm ngập vào nước đun sôi để nguội, thêm đá viên, vài lát chanh để hãm nhiệt, giúp tai heo giòn, trắng hơn.', 10);
INSERT INTO public.recipe_steps VALUES (3825, '2025-11-20 17:11:47.955843', '2025-11-20 17:11:47.955843', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 610, 1, 'a) Cách sơ chế và luộc tai heo trắng, giòn, thơm:Tai heo cạo sạch, ngâm nước vo gạo 10 phút. Sau đó, dùng chanh và muối hạt chà xát, bóp kỹ, rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (3826, '2025-11-20 17:11:47.957448', '2025-11-20 17:11:47.957448', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 610, 4, 'Nếu có thời gian thì khi tai nguội, vớt ra, thấm khô, dùng khăn vải xô sạch ủ và để vào hộp cho vào ngăn mát tủ lạnh 1,5 - 2 giờ cho thịt săn giúp khi thái mỏng và dễ hơn.', 10);
INSERT INTO public.recipe_steps VALUES (3827, '2025-11-20 17:11:47.959047', '2025-11-20 17:11:47.959047', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 610, 5, 'b) Cách làm thính gạo thơm:Bạn nên làm sẵn dùng dần, tỷ lệ gạo tẻ: đỗ xanh: gạo nếp là 1:1: 3 (50 gram gạo tẻ, 50 gram đậu xanh không vỏ, 150 gram gạo nếp): Gạo nếp, gạo tẻ, đỗ xanh để riêng, rửa sạch, ngâm 1 giờ, để thật ráo nước, rang vàng thơm từng loại, xay riêng mịn, lọc qua rây, rồi trộn chung.', 10);
INSERT INTO public.recipe_steps VALUES (3828, '2025-11-20 17:11:48.666473', '2025-11-20 17:11:48.666473', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 611, 6, 'b) Cách nấu cơm:Phi thơm tỏi cùng chút mỡ gà, cho gạo (đã ráo nước) vào xào, thêm chút muối, lá dứa (lá nếp) và nước luộc gà vừa đủ, nấu chín cơm.', 10);
INSERT INTO public.recipe_steps VALUES (3829, '2025-11-20 17:11:48.668041', '2025-11-20 17:11:48.668041', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 611, 9, 'e) Trình bày và thưởng thức:Xới cơm ra đĩa, bày gà luộc đã chặt, trang trí dưa chuột cắt lát. Ăn kèm với nước sốt gừng hành và nước canh gà.', 10);
INSERT INTO public.recipe_steps VALUES (3830, '2025-11-20 17:11:48.669645', '2025-11-20 17:11:48.669645', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 611, 1, 'Cách luộc gà da giòn, thịt chín vừa độ mềm ngọt, không đỏ xương:Gà làm sạch, xát muối hạt, chanh rửa sạch. Lọc riêng mỡ gà, rán lấy mỡ nước, để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (3831, '2025-11-20 17:11:48.671258', '2025-11-20 17:11:48.671258', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 611, 8, 'd) Phần nước dùng: Đun sôi nước luộc gà còn lại, thêm phần hành lá xanh cắt nhỏ, nêm nếm gia vị phù hợp khẩu vị, múc ra bát.', 10);
INSERT INTO public.recipe_steps VALUES (3832, '2025-11-20 17:11:48.672317', '2025-11-20 17:11:48.672317', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 611, 2, 'Cho gà cùng nước ngập vào nồi sâu lòng, thêm chút muối, hạt nêm, đường phèn, hành tím, gừng bật bếp đun. Khi sôi, hạ nhỏ lửa đun tiếp khoảng 7-8 phút, sau đó, tắt bếp om/ngâm gà 20-30 phút tùy vào kích thước lớn nhỏ. Trong khi om, lật gà một lần cho chín đều. Om sẽ giúp gà không bị đỏ xương.', 10);
INSERT INTO public.recipe_steps VALUES (3833, '2025-11-20 17:11:48.673902', '2025-11-20 17:11:48.673902', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 611, 7, 'c) Cách làm sốt gừng hành:Cho gừng, hành và muối vào cối giã nhuyễn. Phi thơm chút tỏi, cho hỗn hợp trên vào xào, thêm ít nước luộc gà, nêm nếm muối, đường, hạt tiêu, hạt nêm theo khẩu vị, thêm dầu mè trộn đều, tắt bếp, múc ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (3834, '2025-11-20 17:11:48.675533', '2025-11-20 17:11:48.675533', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 611, 5, 'Nếu muốn gà vàng ươm thì làm thêm bước sau: Cho chút nghệ tươi băm nhỏ (hoặc bột nghệ) xào với mỡ gà, lọc lấy hỗn hợp mỡ nghệ. Khi gà nguội thoa hỗn hợp mỡ nghệ lên để gà bóng vàng, đẹp mắt. Chặt miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (3835, '2025-11-20 17:11:48.67714', '2025-11-20 17:11:48.67714', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 611, 4, 'Thịt gà trong cơm gà Hải Nam nguyên bản không có màu.', 10);
INSERT INTO public.recipe_steps VALUES (3836, '2025-11-20 17:11:48.678174', '2025-11-20 17:11:48.678174', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 611, 3, 'Vớt gà, ngâm vào nước đá sạch, khi nguội lấy ra phủ khăn xô ủ ẩm giúp bóng mượt. Việc ngâm gà vào nước lạnh tạo thành lớp thạch trong thơm ngon giữa da và thịt, mọng nước, ngọt thơm.', 10);
INSERT INTO public.recipe_steps VALUES (3837, '2025-11-20 17:11:50.033904', '2025-11-20 17:11:50.033904', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 612, 9, 'Nguyên liệu tạo mùi: Nên cho vào khi hầm xương được 1/2 thời gian hoặc 1 tiếng sau cùng: Rang thơm các gia vị khô (hồi, quế, thảo quả, đinh hương, hạt mùi, tiêu sọ) cho vào túi đựng gia vị nấu phở. Gừng, hành khô, hành tây để vỏ đem nướng trong 15 - 20 phút cho tới khi cháy xém và bên trong trong lại là đạt. Sau đó, rửa sạch phần đen. Phần rễ mùi rửa sạch và cho vào cùng lúc này.', 10);
INSERT INTO public.recipe_steps VALUES (3838, '2025-11-20 17:11:50.035831', '2025-11-20 17:11:50.035831', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 612, 8, 'Sau 40-45 phút, nhẹ nhàng vớt phần thịt luộc ra, ngâm vào nước sôi để nguội kèm đá lạnh để thịt không bị khô, thâm mặt. Khi thịt nguội thấm khô, bọc khăn ẩm để vào hộp rồi cho vào tủ lạnh. Khi ăn, lấy ra thái miếng mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (3839, '2025-11-20 17:11:50.036902', '2025-11-20 17:11:50.036902', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 612, 3, 'Chần xương để loại bỏ tạp chất: Sau khi ngâm, cho xương vào nồi đổ ngập nước, thêm nhánh gừng đập dập, muối hạt, chút rượu và bật bếp đun sôi vài phút, tắt bếp ngâm thêm 2-3 phút thì đổ xương ra, rửa thật sạch.', 10);
INSERT INTO public.recipe_steps VALUES (3840, '2025-11-20 17:11:50.037951', '2025-11-20 17:11:50.037951', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 612, 5, 'Phần thịt luộc (nạm) cũng nên ngâm, chần và rửa sạch cùng lúc này để cho vào luộc khi ninh xương.', 10);
INSERT INTO public.recipe_steps VALUES (3841, '2025-11-20 17:11:50.039545', '2025-11-20 17:11:50.039545', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 612, 13, 'Chanh thái miếng, ớt bỏ hạt thái khoanh.', 10);
INSERT INTO public.recipe_steps VALUES (3842, '2025-11-20 17:11:50.04116', '2025-11-20 17:11:50.04116', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 612, 4, 'Nướng xương: Nếu có thời gian thì bạn nên nướng xương sẽ giúp nước dùng thơm và màu đẹp.', 10);
INSERT INTO public.recipe_steps VALUES (3843, '2025-11-20 17:11:50.042218', '2025-11-20 17:11:50.042218', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 612, 6, 'Cách ninh xương: Trong một nồi lớn sạch, đế dày, cho xương vào thêm 6-6,5 lít nước, 1 muỗng canh muối biển, 1 muỗng canh đường phèn vào bật bếp đun sôi. Phần thịt (nạm) cũng cho vào lúc này để luộc cùng.', 10);
INSERT INTO public.recipe_steps VALUES (3844, '2025-11-20 17:11:50.043884', '2025-11-20 17:11:50.043884', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 612, 2, 'Ngâm xương để khử mùi, loại bỏ máu đỏ: Trộn chút rượu, muối và gừng đập dập, đeo găng tay cho xương bò vào thau lớn rồi chà xát trong vài phút. Tiếp đến, dùng nước ấm rửa sạch. Tiếp tục cho xương vào thau, đổ nước đầy thêm giấm, chanh cắt lát, muối loãng ngâm tối thiểu 2 tiếng. Nếu kỹ hơn thì nên ngâm 4 - 5 tiếng (cứ mỗi tiếng thay nước một lần) để khử mùi.', 10);
INSERT INTO public.recipe_steps VALUES (3845, '2025-11-20 17:11:50.045522', '2025-11-20 17:11:50.045522', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 612, 7, 'Khi sôi, hớt bỏ bọt, hạ nhỏ lửa và mở vung ninh tối thiểu trong 4 giờ, tốt nhất là 6-8 giờ hoặc để qua đêm thì các tinh túy từ xương sẽ tiết dần ra giúp cho nước dùng ngọt thơm tự nhiên. Lưu ý: Trong quá trình ninh xương không được đậy vung, không khuấy hay đảo xương sẽ làm vẩn đục nước dùng. Đồng thời cũng không nêm nếm gia vị hay nước mắm vì dễ làm chua nước dùng.', 10);
INSERT INTO public.recipe_steps VALUES (3846, '2025-11-20 17:11:50.047133', '2025-11-20 17:11:50.047133', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 612, 14, 'Phở chần qua nước sôi để loại bỏ mùi chua.', 10);
INSERT INTO public.recipe_steps VALUES (3847, '2025-11-20 17:11:50.048718', '2025-11-20 17:11:50.048718', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 612, 12, 'Các loại rau sống rửa sạch, đầu gốc hành trắng chẻ ngâm nước. Hành lá, rau mùi, rau thơm thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3848, '2025-11-20 17:11:50.050329', '2025-11-20 17:11:50.050329', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 612, 1, 'Cách làm nước dùng:Để nước dùng trong, ngọt thơm tự nhiên, bạn cần xử lý kỹ phần xương:', 10);
INSERT INTO public.recipe_steps VALUES (3849, '2025-11-20 17:11:50.051936', '2025-11-20 17:11:50.051936', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 612, 11, 'Chuẩn bị các nguyên liệu khác:Phần thịt bò tái: Thái mỏng theo thớ ngang, dùng búa đập thịt dập sơ hoặc sống dao băm nhẹ thịt giúp giãn mô liên kết thịt, làm cho thịt mềm hơn. Sau đó, ướp chút gừng băm, hạt tiêu, nước mắm, bọc màng bọc thực phẩm cho vào ngăn mát tủ lạnh.', 10);
INSERT INTO public.recipe_steps VALUES (3850, '2025-11-20 17:11:50.053536', '2025-11-20 17:11:50.053536', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 612, 10, 'Xương hầm xong thì lọc lấy nước dùng trong. Sau đó, mới nêm nếm gia vị (nước mắm, hạt nêm) theo khẩu vị gia đình. Nên múc ra một nồi nhỏ một ít nước để chần phần thịt tái (vì nếu nhúng liên tục vào nồi nước dùng sẽ dẫn tới vẩn đục nước).', 10);
INSERT INTO public.recipe_steps VALUES (3852, '2025-11-20 17:11:50.543707', '2025-11-20 17:11:50.543707', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 613, 3, 'Gạt hết gia vị còn đọng trên cá, thấm khô mặt cá, thái lát mỏng (kích thước 5 cm x 3 cm)', 10);
INSERT INTO public.recipe_steps VALUES (3853, '2025-11-20 17:11:50.544713', '2025-11-20 17:11:50.544713', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 613, 5, 'Cà rốt và hành tây tím trộn cùng dấm, ít đường, nước mắm, ướp 10 phút sau đó vắt kiệt nước.', 10);
INSERT INTO public.recipe_steps VALUES (3854, '2025-11-20 17:11:50.546721', '2025-11-20 17:11:50.546721', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 613, 7, 'Gấp hai bên bánh phở và từ từ cuộn tròn lại.', 10);
INSERT INTO public.recipe_steps VALUES (3855, '2025-11-20 17:11:50.548765', '2025-11-20 17:11:50.548765', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 613, 4, 'Cho nước mắm, wasabi, lạc rang, nước cốt chanh, nước lọc vào máy xay sinh tố, xay khoảng 20 giây để làm nước chấm.', 10);
INSERT INTO public.recipe_steps VALUES (3856, '2025-11-20 17:11:50.54998', '2025-11-20 17:11:50.54998', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 613, 1, 'Trộn đều gừng, muối, đường và tiêu, sau đó phủ hỗn hợp này lên miếng cá hồi phi lê nguyên khối.', 10);
INSERT INTO public.recipe_steps VALUES (3857, '2025-11-20 17:11:50.552253', '2025-11-20 17:11:50.552253', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 613, 2, 'Bọc kín cá đã ướp để vào tủ lạnh khoảng 5 tiếng cho cá ngấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (3858, '2025-11-20 17:11:50.553825', '2025-11-20 17:11:50.553825', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 613, 6, 'Lần lượt cho rau xà lách, bún rối, cà rốt, hành tây tím, rau mùi ta và 2 lát cá hồi vào giữa bánh.', 10);
INSERT INTO public.recipe_steps VALUES (3859, '2025-11-20 17:11:50.885255', '2025-11-20 17:11:50.885255', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 614, 7, 'Thái vát vừa miếng và bày lên bát nộm.', 10);
INSERT INTO public.recipe_steps VALUES (3860, '2025-11-20 17:11:50.886923', '2025-11-20 17:11:50.886923', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 614, 5, 'Lưu ý:Nên để chảo nóng già rồi áp thịt vào khoảng 20 giây mỗi mặt, lúc này thịt đạt đến độ chín vừa.', 10);
INSERT INTO public.recipe_steps VALUES (3861, '2025-11-20 17:11:50.889053', '2025-11-20 17:11:50.889053', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 614, 2, 'Rau thơm thái rối cho xuống đáy bát, cho đu đủ và cà rốt lên trên, sau đó', 10);
INSERT INTO public.recipe_steps VALUES (3862, '2025-11-20 17:11:50.890104', '2025-11-20 17:11:50.890104', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 614, 1, 'Cà rốt và đu đủ bào sợi. Ngâm đu đủ trong nước muối loãng khoảng 5 phút để làm sạch nhựa.', 10);
INSERT INTO public.recipe_steps VALUES (3863, '2025-11-20 17:11:50.89172', '2025-11-20 17:11:50.89172', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 614, 3, 'rưới nước nộm và hai thìa dầu tỏi.', 10);
INSERT INTO public.recipe_steps VALUES (3864, '2025-11-20 17:11:50.893348', '2025-11-20 17:11:50.893348', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 614, 4, 'Ướp chút tỏi băm, muối tiêu và dầu ăn với thịt bò, sau đó nướng nhanh bằng chảo nướng.', 10);
INSERT INTO public.recipe_steps VALUES (3865, '2025-11-20 17:11:50.894949', '2025-11-20 17:11:50.894949', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 614, 6, 'Cho thịt ra đĩa để thịt nghỉ khoảng 10 phút để miếng thịt không bị chảy nước ngọt ra ngoài, không bị khô thịt.', 10);
INSERT INTO public.recipe_steps VALUES (3866, '2025-11-20 17:11:51.451487', '2025-11-20 17:11:51.451487', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 615, 2, 'Đậu phụ rán vàng, để nguội, thái chỉ.', 10);
INSERT INTO public.recipe_steps VALUES (3867, '2025-11-20 17:11:51.452545', '2025-11-20 17:11:51.452545', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 615, 3, 'Trứng đánh tan chút bột canh, hạt nêm rán mỏng, thái sợi nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3868, '2025-11-20 17:11:51.454151', '2025-11-20 17:11:51.454151', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 615, 7, 'Xào thịt bò (Nên xào tái lăn để để thịt giữ vị ngọt mềm tự nhiên, không khô): Đặt chảo lên bếp, cho 3-4 muỗng canh dầu ăn vào, khi dầu nóng thêm phần tỏi băm còn lại vào phi thơm. Tiếp tục cho thịt bò đã ướp vào xào trên lửa lớn, đảo nhanh đều tay cho tới khi thịt chín tới là đạt, xúc ra bát riêng. Bạn đừng xào lâu quá, thịt bò ra nước sẽ bị khô, dai.', 10);
INSERT INTO public.recipe_steps VALUES (3869, '2025-11-20 17:11:51.455745', '2025-11-20 17:11:51.455745', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 615, 4, 'Giò lụa thái chỉ.', 10);
INSERT INTO public.recipe_steps VALUES (3870, '2025-11-20 17:11:51.456795', '2025-11-20 17:11:51.456795', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 615, 6, 'Các loại rau sống nhặt, rửa sạch, ngâm nước muối loãng, vẩy ráo.', 10);
INSERT INTO public.recipe_steps VALUES (3871, '2025-11-20 17:11:51.458533', '2025-11-20 17:11:51.458533', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 615, 9, 'c) Cách làm nước chấm: Xem chi tiết ở đây', 10);
INSERT INTO public.recipe_steps VALUES (3872, '2025-11-20 17:11:51.460262', '2025-11-20 17:11:51.460262', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 615, 1, 'a) Cách làm phở cuốn thập cẩm:Ướp thịt bò với một nửa tỏi băm, dầu hào, nước mắm, hạt nêm, hạt tiêu xay, dầu mè (hoặc dầu hành phi), chút bột năng, trộn đều. Ướp ít nhất 15 phút cho ngấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (3873, '2025-11-20 17:11:51.462382', '2025-11-20 17:11:51.462382', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 615, 5, 'Cà rốt, dưa chuột rửa sạch, ngâm nước vo gạo có pha chút muối, rửa sạch lại và thái sợi.', 10);
INSERT INTO public.recipe_steps VALUES (3874, '2025-11-20 17:11:51.463452', '2025-11-20 17:11:51.463452', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 615, 8, 'b) Cách cuốn:Nhúng bánh phở qua nước ấm cho dễ tách, lấy từng miếng bánh phở rồi xếp lần lượt xà lách rồi thịt bò, giò lụa, trứng, cà rốt, dưa chuột, dứa, rau thơm rồi cuộn lại chặt tay. Làm lần lượt cho tới khi hết.', 10);
INSERT INTO public.recipe_steps VALUES (3875, '2025-11-20 17:11:51.997094', '2025-11-20 17:11:51.997094', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 616, 1, 'a) Bước 1: Chuẩn bị nguyên liệu:Ướp thịt bò: Trộn đều hỗn hợp dầu hào, nước mắm, đường rồi đổ đều lên thịt bò, đeo găng tay nilon và bóp đều để nước sốt ngấm đều các mặt.', 10);
INSERT INTO public.recipe_steps VALUES (3876, '2025-11-20 17:11:51.998678', '2025-11-20 17:11:51.998678', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 616, 4, 'c) Bước 3: Áp chảo thịt bò: Cho một chút dầu ăn vào chảo trên lửa lớn, cho thịt bò vào áp chảo, trở các mặt thường xuyên để bên ngoài hơi xém, có màu nâu đẹp trong 2 - 3 phút. Sau đó, hạ nhỏ lửa, tiếp tục nấu và trở các mặt trong 2-3 phút (lúc này đạt độ mềm, thịt bên trong hồng), hoặc áp bạn để cho tới khi chín theo ý thích của mỗi người. Bạn có thể nướng trên bếp than cũng rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (3877, '2025-11-20 17:11:52.00036', '2025-11-20 17:11:52.00036', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 616, 3, 'b) Bước 2: Làm nước sốt:Trong một cái bát, cho nước cốt me, nước mắm, nước cốt chanh, đường, bột thính, bột ớt, ớt tươi, trộn đều cho tới khi sánh lại. Sau đó, cho hành tím, rau mùi cắt nhỏ vào.', 10);
INSERT INTO public.recipe_steps VALUES (3878, '2025-11-20 17:11:52.001847', '2025-11-20 17:11:52.001847', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 616, 2, 'Các loại rau ăn kèm rửa sạch, ngâm nước muối loãng, vẩy ráo nước, thái lát vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (3879, '2025-11-20 17:11:52.003982', '2025-11-20 17:11:52.003982', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 616, 5, 'Tắt bếp, lấy thịt bò ra thớt trong 3 phút cho nguội bớt rồi thái lát.', 10);
INSERT INTO public.recipe_steps VALUES (3880, '2025-11-20 17:11:52.614512', '2025-11-20 17:11:52.614512', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 617, 1, 'Trộn bột khô, muối đường và cho từ từ nước sôi vào trộn bằng đũa đến khi bột thấm đều nước.', 10);
INSERT INTO public.recipe_steps VALUES (3881, '2025-11-20 17:11:52.616154', '2025-11-20 17:11:52.616154', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 617, 5, 'Lấy một phần ra trong 15 phần để tạo màu cam đỏ bằng bột gạo đỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3882, '2025-11-20 17:11:52.617751', '2025-11-20 17:11:52.617751', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 617, 4, 'Chia bột thành 15 phần bằng nhau.', 10);
INSERT INTO public.recipe_steps VALUES (3885, '2025-11-20 17:11:52.622221', '2025-11-20 17:11:52.622221', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 617, 3, 'Sau khi bột nghỉ, cho dầu ăn vào và nhồi bột đến khi mịn màng.', 10);
INSERT INTO public.recipe_steps VALUES (3886, '2025-11-20 17:11:52.623809', '2025-11-20 17:11:52.623809', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 617, 6, 'Sau đó tạo hình con cá theocác bước theo hình bên dưới:', 10);
INSERT INTO public.recipe_steps VALUES (3887, '2025-11-20 17:11:52.624862', '2025-11-20 17:11:52.624862', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 617, 8, 'Bày ra đĩa cùng nước chấm là có thể thưởng thức ngay.', 10);
INSERT INTO public.recipe_steps VALUES (3888, '2025-11-20 17:11:53.45896', '2025-11-20 17:11:53.45896', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 618, 8, 'Phủ một khăn xô và cho gà vào tủ lạnh tầm 30 phút để da săn lại và dễ lọc và thái thịt đẹp hơn.', 10);
INSERT INTO public.recipe_steps VALUES (3889, '2025-11-20 17:11:53.46066', '2025-11-20 17:11:53.46066', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 618, 6, 'Cho gà vào nồi sâu lòng, đế dày, đổ nước lạnh vào ngập gà (Không nên cho tiết vào luộc cùng vì dễ làm gà bám màng đen). Thêm chút bột canh/hoặc muối hạt, hành tím, gừng nướng (cạo rửa sạch) rồi đun sôi. Khi sôi, vớt bọt, hạ nhỏ lửa luộc trong 7-8 phút tắt bếp và ngâm gà 15-25 phút tùy kích thước to hay nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3890, '2025-11-20 17:11:53.462269', '2025-11-20 17:11:53.462269', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 618, 19, 'Bún rối trụng sơ nước.', 10);
INSERT INTO public.recipe_steps VALUES (3891, '2025-11-20 17:11:53.463486', '2025-11-20 17:11:53.463486', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 618, 14, 'Trứng: Trong một cái bát, cho 2 quả trứng gà ta, 1 quả trứng vịt, 1 muỗng canh rượu trắng, 1/2 muỗng canh dầu ăn, 1/2 muỗng canh nước, chút bột canh đánh đều cho tan. Sau đó, lọc qua rây để lọc bỏ bọt cũng như phần trứng chưa tan hết. Phết chút dầu ăn vào chảo chống dính, để nhỏ lửa, khi chảo hơi nóng thì cho trứng vào láng nhẹ đều mặt, nhanh tay đổ phần còn dư ra ngay bát trứng, chỉ để lại lớp mỏng dính vào chảo. Chờ trứng chín và tách ra được, trở mặt. Làm lần lượt cho tới khi hết. Chồng trứng tráng mỏng lên nhau, dùng dao sắc thái sợi mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (3892, '2025-11-20 17:11:53.465073', '2025-11-20 17:11:53.465073', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 618, 15, 'Nếu làm thêm ruốc sỏi (thịt heo nạc) thì thái hạt lựu thịt thăn heo, ướp chút nước mắm, hạt nêm rồi phi thơm hành, xào cho săn lại.', 10);
INSERT INTO public.recipe_steps VALUES (3893, '2025-11-20 17:11:53.466155', '2025-11-20 17:11:53.466155', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 618, 5, 'Gà làm sạch, xát với muối hạt và chanh để khử mùi, rửa lại bằng nước sạch.', 10);
INSERT INTO public.recipe_steps VALUES (3894, '2025-11-20 17:11:53.467207', '2025-11-20 17:11:53.467207', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 618, 11, 'Thêm hương liệu từ mực khô, sá sùng, tôm khô vào nước dùng để dậy mùi thơm đặc trưng của bún thang: Rang thơm tôm he khô, nướng râu mực, rửa sạch sá sùng rồi nướng thơm. Sau đó, cho tất cả nguyên liệu này để vào túi lọc, cho vào nồi nướng dùng đang hầm.', 10);
INSERT INTO public.recipe_steps VALUES (3895, '2025-11-20 17:11:53.469641', '2025-11-20 17:11:53.469641', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 618, 18, 'Chanh thái miếng, ớt bỏ hạt thái khoanh.', 10);
INSERT INTO public.recipe_steps VALUES (3896, '2025-11-20 17:11:53.47128', '2025-11-20 17:11:53.47128', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 618, 20, 'Quay trở lại nồi nước dùng, lọc bỏ phần xương heo và xương gà cũng như gừng, hành nướng. Cho nấm hương khô (đã ngâm nước nóng, rửa sạch) vào. Nêm nếm thêm nước mắm ngon, bột canh, hạt nêm (nếu thích) theo khẩu vị gia đình.', 10);
INSERT INTO public.recipe_steps VALUES (3897, '2025-11-20 17:11:53.472913', '2025-11-20 17:11:53.472913', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 618, 17, 'Rau răm rửa sạch, thái rối. Nếu thích thì thêm hành lá, rau mùi thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3898, '2025-11-20 17:11:53.473966', '2025-11-20 17:11:53.473966', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 618, 4, 'Song hành thì luộc gà và lấy nước dùng từ gà.', 10);
INSERT INTO public.recipe_steps VALUES (3899, '2025-11-20 17:11:53.475066', '2025-11-20 17:11:53.475066', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 618, 9, 'Sau đó, lấy gà ra lọc xương. Phần thịt tùy theo sở thích có thể xé nhỏ bằng tay như cách ngày xưa, hoặc thái mỏng dài có cả da cho đẹp mắt.', 10);
INSERT INTO public.recipe_steps VALUES (3900, '2025-11-20 17:11:53.476731', '2025-11-20 17:11:53.476731', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 618, 13, 'Giò lụa thái chỉ.', 10);
INSERT INTO public.recipe_steps VALUES (3901, '2025-11-20 17:11:53.478344', '2025-11-20 17:11:53.478344', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 618, 1, 'a) Cách làm phần nước dùng: Nên làm song hành các loại nước dùng từ xương bay lợn, nước dùng (từ luộc gà). Trước khi ăn thì cho chung vào nhau hài hòa các vị:', 10);
INSERT INTO public.recipe_steps VALUES (3902, '2025-11-20 17:11:53.479412', '2025-11-20 17:11:53.479412', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 618, 3, 'Sau đó, cho xương bay vào nồi nước 4 - 4,5 lít nước (nồi đáy sâu), thêm 1 muỗng canh muối (chú ý không nêm hạt nêm vào lúc này vì hạt nêm làm từ xương khi hầm sẽ tan ra làm đục nước dùng). Đun sôi, hớt bỏ bọt, hạ nhỏ lửa lăn tăn, mở hé vung ninh xương từ 2,5 - 3 giờ để vị ngọt từ xương tiết ra tạo vị tự nhiên cho nước dùng. Thỉnh thoảng hớt bỏ bọt cho nước dùng trong.', 10);
INSERT INTO public.recipe_steps VALUES (3903, '2025-11-20 17:11:53.481138', '2025-11-20 17:11:53.481138', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 618, 16, 'c) Hoàn thiện và trình bày, thưởng thức:', 10);
INSERT INTO public.recipe_steps VALUES (3904, '2025-11-20 17:11:53.483256', '2025-11-20 17:11:53.483256', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 618, 2, 'Nước dùng từ xương bay lợn: Nếu có thời gian, nên ngâm xương cùng nước ấm (hoặc nước vo gạo càng sạch), thêm chút muối hạt tầm 1 giờ cho sạch tạp chất rồi rửa sạch lần một. Tiếp tục, đun sôi một nồi nước, thêm muối hạt và nhánh nhỏ gừng đập dập rồi cho xương bay vào chần 3-4 phút cho hết phần tạp chất, đổ ra, rửa nhiều nước cho thật sạch lần hai. Việc xử lý xương kỹ sẽ giúp cho nước dùng thơm, thanh, trong.', 10);
INSERT INTO public.recipe_steps VALUES (3905, '2025-11-20 17:11:53.484826', '2025-11-20 17:11:53.484826', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 618, 10, 'Cho phần xương gà và 2 lít nước luộc gà vào nồi nước xương bay lợn đang hầm.', 10);
INSERT INTO public.recipe_steps VALUES (3906, '2025-11-20 17:11:53.486445', '2025-11-20 17:11:53.486445', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 618, 12, 'b) Làm các phần topping:Làm ruốc tôm: Sau tầm 50 phút thì lấy phần tôm khô ra, dùng cối giã sơ sơ, đổ lên rổ và dùng đế bát cơm cà nhẹ cho bông tơi ruốc tôm. Tiếp đến, cho ruốc tôm vào chảo cùng 1 muỗng cà phê dầu hạt điều, để nhỏ lửa, đảo đũa sao cho tới khi ruốc hơi se lại là được.', 10);
INSERT INTO public.recipe_steps VALUES (3907, '2025-11-20 17:11:53.487806', '2025-11-20 17:11:53.487806', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 618, 7, 'Sau đó, vớt gà ra cho vào thau nước đá, rửa gà sạch sẽ rồi vớt ra để ráo. Khi nguội, phết thêm mỡ nghệ gà cho da vàng ươm đẹp mắt.', 10);
INSERT INTO public.recipe_steps VALUES (3908, '2025-11-20 17:11:54.119835', '2025-11-20 17:11:54.119835', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 619, 9, 'b) Cách chiên bánh tôm:Nên chiên 2 lần lửa thì bánh sẽ giòn lâu hơn:', 10);
INSERT INTO public.recipe_steps VALUES (3937, '2025-11-20 17:11:54.687215', '2025-11-20 17:11:54.687215', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 25, 'Phết một chút dầu ăn lên từng xiên, rồi cho vào lò nướng chín. Lưu ý: Khi nướng, thỉnh thoảng lật mặt để thịt chín đều.', 10);
INSERT INTO public.recipe_steps VALUES (3909, '2025-11-20 17:11:54.122748', '2025-11-20 17:11:54.122748', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 619, 4, 'Cách làm dưa góp giòn, ngon: Su hào non cắt khối hoặc tỉa hoa tùy thích, thái lát mỏng. Sau đó trộn với 1 thìa cà phê muối tinh 4-5 phút để su hào, cà rốt ''''nhả nước'' giúp cho giòn ngon hơn. Sau đó, rửa sạch mấy nước, vắt nhẹ tay cho ráo (chú ý không vắt mạnh quá dễ vỡ).', 10);
INSERT INTO public.recipe_steps VALUES (3910, '2025-11-20 17:11:54.126022', '2025-11-20 17:11:54.126022', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 619, 14, 'Sau đó, chiên lại lần hai cho vàng giòn, đặt lên giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (3911, '2025-11-20 17:11:54.128665', '2025-11-20 17:11:54.128665', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 619, 11, 'Đặt chảo lên bếp, cho lượng dầu ngập bánh, bật bếp. Dùng đầu đũa thử nếu thấy sủi bọt tăm là dầu đã đạt độ nóng.', 10);
INSERT INTO public.recipe_steps VALUES (3912, '2025-11-20 17:11:54.131974', '2025-11-20 17:11:54.131974', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 619, 1, 'a) Chuẩn bị nguyên liệu:Cách pha bột:', 10);
INSERT INTO public.recipe_steps VALUES (3913, '2025-11-20 17:11:54.134094', '2025-11-20 17:11:54.134094', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 619, 8, 'Cách gọt khoai: Khoai lang gọt vỏ, cắt thành hình que diêm nhỏ rồi ngâm vào nước vôi trong hoặc nước muối loãng để không bị thâm. Sau đó, rửa sạch nhiều lần.', 10);
INSERT INTO public.recipe_steps VALUES (3914, '2025-11-20 17:11:54.137017', '2025-11-20 17:11:54.137017', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 619, 10, 'Vớt khoai lang cho vào bột trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (3915, '2025-11-20 17:11:54.139589', '2025-11-20 17:11:54.139589', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 619, 2, 'Trong một tô trộn lớn, đánh tan trứng. Dùng rây để rây bột mì, bột gạo, bột bắp vào. Thêm chút muối, bột nghệ, bột nở vào bát trứng rồi trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (3916, '2025-11-20 17:11:54.141134', '2025-11-20 17:11:54.141134', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 619, 6, 'Pha nước mắm: Theo tỷ lệ mắm: đường: giấm: nước là 1:1:1:5. Trong một cái bát, cho nước sôi để nguội, đường, giấm vào và khuấy cho tan hẳn đường, sau đó mới cho nước mắm vào. Cuối cùng, thêm tỏi ớt băm nhỏ vào sẽ nổi lên trông đẹp mắt (bí quyết là đường phải tan hẳn thì tỏi ớt mới nổi).', 10);
INSERT INTO public.recipe_steps VALUES (3917, '2025-11-20 17:11:54.143134', '2025-11-20 17:11:54.143134', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 619, 13, 'Sau đó, cho vào chiên cho tới khi ngả màu vàng cánh gián là đạt. Chú ý: Trở các mặt để bánh chín đều, nếu tôm rơi ra thì múc thêm bột nước để tôm dính vào bánh. Làm lần lượt cho tới hết.', 10);
INSERT INTO public.recipe_steps VALUES (3918, '2025-11-20 17:11:54.145816', '2025-11-20 17:11:54.145816', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 619, 7, 'Tôm rút chỉ đen ở lưng, rửa sạch, ướp chút hạt nêm, hạt tiêu.', 10);
INSERT INTO public.recipe_steps VALUES (3919, '2025-11-20 17:11:54.14783', '2025-11-20 17:11:54.14783', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 619, 12, 'Dùng vá (chuyên dùng chiên bánh tôm) hoặc muôi múc canh, múc bột và khoai lang, gắp tôm nhúng vào bột, rồi đặt lên trên (1-2 con tùy thích).', 10);
INSERT INTO public.recipe_steps VALUES (3920, '2025-11-20 17:11:54.149879', '2025-11-20 17:11:54.149879', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 619, 3, 'Thêm 1,5 lon nước có ga (7 Up hoặc bia), 70ml nước rồi đánh tan đều, để bột nghỉ 1-2 giờ.', 10);
INSERT INTO public.recipe_steps VALUES (3921, '2025-11-20 17:11:54.151478', '2025-11-20 17:11:54.151478', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 619, 5, 'Thêm 2 thìa canh đường, 2 thìa canh giấm, 1/2 thìa cà phê muối tinh, thêm tỏi, ớt băm vào và trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (3922, '2025-11-20 17:11:54.664754', '2025-11-20 17:11:54.664754', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 8, 'Cà rốt thái nhỏ hình que diêm dài. Mộc nhĩ thái sợi dài. Ớt chuông đỏ, xanh thái hình que diêm dài. Đậu que rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (3923, '2025-11-20 17:11:54.666356', '2025-11-20 17:11:54.666356', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 2, 'Đùi gà làm sạch, khứa đằng sau vài lát để ngấm gia vị và chín nhanh.', 10);
INSERT INTO public.recipe_steps VALUES (3924, '2025-11-20 17:11:54.667928', '2025-11-20 17:11:54.667928', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 27, 'Pha hỗn hợp nước sốt gồm: nước, xì dầu, dầu hào, đường, dấm, tỏi chiên, ớt khô (chú ý nêm theo khẩu vị).', 10);
INSERT INTO public.recipe_steps VALUES (3925, '2025-11-20 17:11:54.669515', '2025-11-20 17:11:54.669515', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 22, 'Lườn gà xiên rau củ nướng kiểu Nhật
INSERT INTO public.recipe_steps VALUES (3926, '2025-11-20 17:11:54.671098', '2025-11-20 17:11:54.671098', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 11, 'Phi thơm tỏi, ớt khô (nếu thích cay), cho gà vào xào cho tới khi ngả màu vàng là đạt, múc ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (3927, '2025-11-20 17:11:54.672159', '2025-11-20 17:11:54.672159', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 14, 'Trong một cái bát, trộn đều bột mì, bột năng, bột nở. Sau đó, từ từ cho nước vào đánh đều sao cho trở thành hỗn hợp sền sệt.', 10);
INSERT INTO public.recipe_steps VALUES (3928, '2025-11-20 17:11:54.674273', '2025-11-20 17:11:54.674273', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 15, 'Húng quế nhặt lá, rửa sạch, vẩy ráo/hoặc thấm khô.', 10);
INSERT INTO public.recipe_steps VALUES (3929, '2025-11-20 17:11:54.675353', '2025-11-20 17:11:54.675353', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 30, 'Phần xương gà rửa sạch, cho vào nồi ninh cùng chút gừng, hành nướng (đã cạo rửa sạch) rồi lọc lấy nước dùng trong, ngọt tự nhiên.', 10);
INSERT INTO public.recipe_steps VALUES (3930, '2025-11-20 17:11:54.677044', '2025-11-20 17:11:54.677044', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 10, 'Một nửa ức gà xào hạt điều kiểu Thái Lan
INSERT INTO public.recipe_steps VALUES (3931, '2025-11-20 17:11:54.678624', '2025-11-20 17:11:54.678624', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 29, 'Súp gà nấm
INSERT INTO public.recipe_steps VALUES (3932, '2025-11-20 17:11:54.680237', '2025-11-20 17:11:54.680237', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 26, 'Chân gà om xì dầu kiểu Hoa
INSERT INTO public.recipe_steps VALUES (3933, '2025-11-20 17:11:54.681377', '2025-11-20 17:11:54.681377', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 5, 'Vắt nửa quả cam lấy nước, trộn cùng chút rượu, muối, hạt tiêu, mật ong, đinh hương, ớt bột, bột tỏi. Sau đó, thoa hỗn hợp này lên đùi gà và ướp 1 giờ và đem nướng chín cùng vài lát cam thái mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (3934, '2025-11-20 17:11:54.682965', '2025-11-20 17:11:54.682965', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 28, 'Đổ hỗn hợp này vào nồi cùng chân gà, đun nhỏ lửa ninh từ 40-45 phút cho tới khi chân chín mềm, ngấm đều gia vị, sền sệt nước là được.', 10);
INSERT INTO public.recipe_steps VALUES (3935, '2025-11-20 17:11:54.684029', '2025-11-20 17:11:54.684029', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 12, 'Tiếp tục cho ớt chuông, hành tây vào xào, nêm chút gia vị. Khi vừa chín tới thì đổ gà vào, thêm hạt điều rang (đã bóc vỏ lụa) và đảo đều. Nêm nếm gia vị cho phù hợp.', 10);
INSERT INTO public.recipe_steps VALUES (3936, '2025-11-20 17:11:54.685628', '2025-11-20 17:11:54.685628', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 3, 'Trút hỗn hợp nước sốt gừng vào gà rồi đem hấp. Khi gần chín thêm hành lá vào rồi hấp chín, tổng thời gian khoảng 15 phút.', 10);
INSERT INTO public.recipe_steps VALUES (3938, '2025-11-20 17:11:54.688867', '2025-11-20 17:11:54.688867', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 36, 'Lòng gà xào miến
INSERT INTO public.recipe_steps VALUES (3939, '2025-11-20 17:11:54.690444', '2025-11-20 17:11:54.690444', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 24, 'Sau đó, lấy xiên tre (đã ngâm nước để khi nướng không bị cháy), lần lượt cho gà và ớt chuông xanh, đỏ, hành tây xiên vào xen kẽ.', 10);
INSERT INTO public.recipe_steps VALUES (3940, '2025-11-20 17:11:54.691583', '2025-11-20 17:11:54.691583', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 19, 'Cánh gà chiên giòn cay
INSERT INTO public.recipe_steps VALUES (3941, '2025-11-20 17:11:54.692626', '2025-11-20 17:11:54.692626', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 35, 'Sau đó, cho lòng trứng gà đã đánh vào và khuấy đều một chiều rồi đun trong 1 phút, thêm trứng cút luộc, rau mùi, tắt bếp và múc ra bát.', 10);
INSERT INTO public.recipe_steps VALUES (3942, '2025-11-20 17:11:54.694157', '2025-11-20 17:11:54.694157', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 4, 'Một đùi gà nướng cam, mật ong kiểu Âu
INSERT INTO public.recipe_steps VALUES (3943, '2025-11-20 17:11:54.695699', '2025-11-20 17:11:54.695699', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 39, 'Cuối cùng, cho miến vào đảo đều, thêm chút nước để miến đỡ dính. Nêm gia vị cho phù hợp khẩu vị, tắt bếp, múc ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (3944, '2025-11-20 17:11:54.698211', '2025-11-20 17:11:54.698211', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 17, 'Gà chia từng mẻ, nhúng qua hỗn hợp bột ướt sánh ở trên và lần lượt cho vào chảo chiên giòn, vớt ra.', 10);
INSERT INTO public.recipe_steps VALUES (3945, '2025-11-20 17:11:54.698211', '2025-11-20 17:11:54.698211', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 7, 'Cổ gà làm dồi hoa ngũ sắc
INSERT INTO public.recipe_steps VALUES (3946, '2025-11-20 17:11:54.700934', '2025-11-20 17:11:54.700934', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 32, 'Nấm (tùy chọn theo sở thích: nấm hương, nấm hải sản), rửa nước muối loãng, vẩy ráo, tước/xé sợi nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3947, '2025-11-20 17:11:54.700934', '2025-11-20 17:11:54.700934', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 20, 'Cho lượng dầu vào chảo sâu lòng (đủ ngập gà), khi thử thấy đầu đũa sủi bọt tăm là dầu đạt, cho gà vào chiên vàng giòn, vớt ra để giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (3948, '2025-11-20 17:11:54.703544', '2025-11-20 17:11:54.703544', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 34, 'Hòa tan bột năng rồi rót từ từ vào nồi súp, vừa rót vừa khuấy đều để tạo độ sánh cho món ăn.', 10);
INSERT INTO public.recipe_steps VALUES (3949, '2025-11-20 17:11:54.705134', '2025-11-20 17:11:54.705134', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 16, 'Cho dầu vào chảo, thử đầu đũa sủi bọt tăm thì cho lá húng quế vào chiên giòn, vớt ra.', 10);
INSERT INTO public.recipe_steps VALUES (3950, '2025-11-20 17:11:54.706781', '2025-11-20 17:11:54.706781', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 31, 'Phần thịt gà dư, bạn cho vào luộc, xé nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3951, '2025-11-20 17:11:54.708364', '2025-11-20 17:11:54.708364', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 1, 'Một đùi gà hấp gừng hành
INSERT INTO public.recipe_steps VALUES (3952, '2025-11-20 17:11:54.709429', '2025-11-20 17:11:54.709429', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 21, 'Trong một cái bát, trộn ớt bột, chút muối, đường, hạt tiêu theo khẩu vị. Sau đó, cho gà vào hộp cùng hỗn hợp muối ớt và lắc đều để bám đều các mặt.', 10);
INSERT INTO public.recipe_steps VALUES (3953, '2025-11-20 17:11:54.711057', '2025-11-20 17:11:54.711057', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 23, 'Hành tây, ớt chuông xanh, ớt chuông đỏ rửa sạch, cắt miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (3954, '2025-11-20 17:11:54.712654', '2025-11-20 17:11:54.712654', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 33, 'Phi thơm hành khô, cho thịt gà và nấm vào xào sơ. Thêm nước dùng gà nấu sôi, nêm nếm gia vị mắm muối, hạt nêm cho phù hợp.', 10);
INSERT INTO public.recipe_steps VALUES (3955, '2025-11-20 17:11:54.713717', '2025-11-20 17:11:54.713717', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 6, 'Lưu ý để ngon hơn nên chia nhỏ thời gian: cứ 9-10 phút thì lấy gà ra, quết hỗn hợp nước sốt rồi cho vào nướng tiếp.', 10);
INSERT INTO public.recipe_steps VALUES (3956, '2025-11-20 17:11:54.714834', '2025-11-20 17:11:54.714834', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 38, 'Phi thơm hành tỏi, cho lòng gà vào xào chín. Sau đó, thêm nấm hương, mộc nhĩ, cà rốt, hành tây vào xào săn lại.', 10);
INSERT INTO public.recipe_steps VALUES (3957, '2025-11-20 17:11:54.716419', '2025-11-20 17:11:54.716419', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 9, 'Cho giò sống trộn cùng rau mùi, hạt nêm rồi nhồi vào cổ gà cùng với rau củ quả. Sau đó, buộc đầu còn lại và đem luộc ở lửa nhỏ (nhớ châm kim để dồi không bị vỡ). Khi chín, vớt ra để nguội, thái khoanh mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (3958, '2025-11-20 17:11:54.717989', '2025-11-20 17:11:54.717989', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 37, 'Miến dong ngâm mềm, cắt khúc. Mộc nhĩ, nấm hương ngâm mềm, rửa sạch, thái chỉ. Cà rốt thái chỉ, hành tây thái múi cau nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (3959, '2025-11-20 17:11:54.719578', '2025-11-20 17:11:54.719578', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 13, 'Một nửa ức gà chiên giòn húng quế kiểu Đài Loan
INSERT INTO public.recipe_steps VALUES (3960, '2025-11-20 17:11:54.720646', '2025-11-20 17:11:54.720646', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 620, 18, 'Bày gà ra đĩa kèm húng quế chiên, khi ăn chấm cùng tương ớt.', 10);
INSERT INTO public.recipe_steps VALUES (3961, '2025-11-20 17:11:55.433457', '2025-11-20 17:11:55.433457', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 621, 9, 'd) Cách ngâm:Xếp xen kẽ tai heo thái mỏng với cà rốt, hành, tỏi, hạt tiêu đen rang, hạt tiêu xanh, ớt, quất cắt lát. Sau đó, đổ ngập nước chua ngọt đã nguội hoàn toàn, nén phần tai heo xuống. Để tai heo vào tủ lạnh sau 2-3 ngày là ăn được.', 10);
INSERT INTO public.recipe_steps VALUES (3962, '2025-11-20 17:11:55.434501', '2025-11-20 17:11:55.434501', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 621, 1, 'a) Cách làm tai heo:Sơ chế: Tai heo làm sạch (cạo sạch lông, cạo sạch phần chất bẩn bên trong lỗ tai). Sau đó, ngâm vào nước vo gạo 10 phút, rửa sạch. Tiếp tục, dùng giấm/hoặc chanh và muối bóp kỹ để khử mùi, rửa sạch lại lần nữa.', 10);
INSERT INTO public.recipe_steps VALUES (3963, '2025-11-20 17:11:55.436106', '2025-11-20 17:11:55.436106', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 621, 4, 'Khi tai heo nguội hẳn, vớt tai ra, để thật ráo nước/hoặc thấm khô, dùng khăn xô phủ kín và cho tai vào tủ lạnh 1-2 giờ cho săn lại (mục đích không bị nhớt, nhờn khi ngâm cũng như dễ thái mỏng hơn). Lấy tai heo ra, dùng dao sắc thái mỏng, nên bỏ phần nhiều mỡ.', 10);
INSERT INTO public.recipe_steps VALUES (4135, '2025-11-20 17:12:03.038314', '2025-11-20 17:12:03.038314', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 643, 4, 'Sau khi trứng đã tan đều, tiếp tục cho nước cốt chanh và tinh chất vani vào âu bơ và đảo tiếp.', 10);
INSERT INTO public.recipe_steps VALUES (3964, '2025-11-20 17:11:55.438244', '2025-11-20 17:11:55.438244', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 621, 2, 'Luộc tai heo: Cho tai heo vào nồi đế dày, đổ lượng nước ngập tai heo (nếu không ngập thì tai dễ bị đen), thêm 1 muỗng canh muối/bột canh, 2 muỗng canh giấm, 1 muỗng cà phê hạt nêm, 1/2 muỗng cà phê hạt tiêu, 2-3 củ hành tím đập dập, 1 nhánh gừng nhỏ rửa sạch đập dập. Bật bếp đun sôi tầm 15-16 phút.', 10);
INSERT INTO public.recipe_steps VALUES (3965, '2025-11-20 17:11:55.440382', '2025-11-20 17:11:55.440382', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 621, 3, 'Vớt tai heo ra ngâm vào nước sôi để nguội pha với đá viên sạch và chút nước chanh để tai trắng, giòn và thơm hơn.', 10);
INSERT INTO public.recipe_steps VALUES (3966, '2025-11-20 17:11:55.441462', '2025-11-20 17:11:55.441462', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 621, 7, 'Nấu một chút nước giấm và đường, cho hành, tỏi, cà rốt và hạt tiêu xanh vào trụng sơ khử trùng để khi ngâm được lâu.', 10);
INSERT INTO public.recipe_steps VALUES (3967, '2025-11-20 17:11:55.443072', '2025-11-20 17:11:55.443072', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 621, 8, 'Quất rửa sạch bằng nước sôi để nguội ngâm muối loãng.', 10);
INSERT INTO public.recipe_steps VALUES (3968, '2025-11-20 17:11:55.444833', '2025-11-20 17:11:55.444833', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 621, 6, 'c) Chuẩn bị các nguyên liệu khác:Hành, tỏi bóc vỏ và thái lát mỏng, cà rốt tạo hình hoa yêu thích. Nếu có thời gian phơi nắng cho hơi héo khi ngâm sẽ giòn và ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (3969, '2025-11-20 17:11:55.447121', '2025-11-20 17:11:55.447121', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 621, 5, 'b) Cách nấu nước chua ngọt để ngâm:Cho nước, đường, giấm, nước mắm, muối vào nồi đun sôi tầm 8-10 phút cho bay bớt mùi giấm, nêm nếm lại theo khẩu vị gia đình. Tắt bếp, để thật nguội.', 10);
INSERT INTO public.recipe_steps VALUES (3970, '2025-11-20 17:11:56.425329', '2025-11-20 17:11:56.425329', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 622, 14, 'Cho đu đủ, cà rốt vào bát tô, thêm muối, đường, nước cốt chanh, hành phi, rau răm theo khẩu vị gia đình. Trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (3971, '2025-11-20 17:11:56.427036', '2025-11-20 17:11:56.427036', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 622, 11, 'd) Cách làm gỏi gà hành tây:Hành tây sau khi ngâm nước đá (cho hết mùi hăng), vớt ra, để ráo. Sau đó, trộn với phần thịt gà xé đã ướp gia vị, trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (3972, '2025-11-20 17:11:56.428097', '2025-11-20 17:11:56.428097', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 622, 7, 'b) Cách nấu cơm gà vàng ươm:Gạo nếp, tẻ vo sạch, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (3973, '2025-11-20 17:11:56.429699', '2025-11-20 17:11:56.429699', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 622, 16, 'Phi thơm tỏi, cho lòng gà vào xào chín, thêm chút dầu hạt điều lên màu cho đẹp, múc nước luộc gà đun thêm 10-15 phút là được, nêm nếm lại theo khẩu vị gia đình.', 10);
INSERT INTO public.recipe_steps VALUES (3974, '2025-11-20 17:11:56.430757', '2025-11-20 17:11:56.430757', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 622, 8, 'Phi thơm tỏi trong một chảo với chút dầu ăn, cho gạo đã ráo hẳn nước vào rang thơm tầm 30 giây.', 10);
INSERT INTO public.recipe_steps VALUES (3975, '2025-11-20 17:11:56.431763', '2025-11-20 17:11:56.431763', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 622, 10, 'c) Cách làm tương ớt Hội An:Công thức chi tiết', 10);
INSERT INTO public.recipe_steps VALUES (3976, '2025-11-20 17:11:56.433346', '2025-11-20 17:11:56.433346', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 622, 5, 'Chờ gà nguội, một phần chặt miếng vừa ăn, một phần (ức) xé nhỏ ướp với 1/2 muỗng canh nước mắm, 1/2 muỗng canh đường, 1/2 muỗng canh nước cốt chanh/hoặc quất, 1/2 muỗng cà phê hạt tiêu, 2 tép tỏi băm nhuyễn. Trộn đều tất cả, sau đó bọc lại với màng bọc thực phẩm.', 10);
INSERT INTO public.recipe_steps VALUES (3977, '2025-11-20 17:11:56.434353', '2025-11-20 17:11:56.434353', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 622, 6, 'Số xương gà thì tiếp tục cho vào nồi nước dùng cho ngọt nước.', 10);
INSERT INTO public.recipe_steps VALUES (3978, '2025-11-20 17:11:56.436363', '2025-11-20 17:11:56.436363', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 622, 12, 'e) Cách làm gỏi đu đủ, cà rốt:Nên làm song hành khi luộc gà', 10);
INSERT INTO public.recipe_steps VALUES (3979, '2025-11-20 17:11:56.436363', '2025-11-20 17:11:56.436363', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 622, 4, 'Khi nước hơi nguội, vớt gà ra, lấy một khăn ẩm ủ kín gà sẽ giúp da bóng mượt hơn. Muốn da vàng hơn, bạn nên dùng mỡ gà nóng trộn với bột nghệ, thoa đều lên da.', 10);
INSERT INTO public.recipe_steps VALUES (3980, '2025-11-20 17:11:56.438883', '2025-11-20 17:11:56.438883', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 622, 17, 'Nếu không thích làm nước mạ thì có thể dùng lòng gà xào dứa hoặc giá đậu tùy theo sở thích để ăn kèm.', 10);
INSERT INTO public.recipe_steps VALUES (3981, '2025-11-20 17:11:56.440391', '2025-11-20 17:11:56.440391', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 622, 2, 'Cho gà vào nồi đáy sâu, thêm nước lạnh sao cho ngập gà. Thêm gừng đập dập, hành khô vào và đun sôi. Khi nước sôi, hạ lửa vớt bọt, đun liu riu.', 10);
INSERT INTO public.recipe_steps VALUES (3982, '2025-11-20 17:11:56.441895', '2025-11-20 17:11:56.441895', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 622, 18, 'g) Nước canh ăn kèm:Dùng nước luộc gà đun nóng, thêm hành lá cắt nhỏ, nêm nếm lại khẩu vị phù hợp.', 10);
INSERT INTO public.recipe_steps VALUES (3983, '2025-11-20 17:11:56.442903', '2025-11-20 17:11:56.442903', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 622, 3, 'Sau 5-7 phút tắt bếp, ngâm gà tầm 15-20 phút tùy theo khối lượng. Việc này vừa giúp gà ngậm nước sẽ mọng thịt, ngọt thơm hơn, đồng thời giúp cho thịt gà không bị đỏ nước.', 10);
INSERT INTO public.recipe_steps VALUES (3984, '2025-11-20 17:11:56.444904', '2025-11-20 17:11:56.444904', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 622, 13, 'Đu đủ, cà rốt bào sợi ngâm với nước đá lạnh pha chút đường cho giòn tầm 15 phút, vớt ra, đều ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (3985, '2025-11-20 17:11:56.445901', '2025-11-20 17:11:56.445901', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 622, 15, 'f) Cách làm nước mạ:Lòng gà làm sạch, cắt miếng vừa ăn rồi ướp với chút mắm, muối, hạt tiêu trong 10 phút cho ngấm.', 10);
INSERT INTO public.recipe_steps VALUES (3986, '2025-11-20 17:11:56.446902', '2025-11-20 17:11:56.446902', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 622, 1, 'a) Cách làm gà luộc, gà xé: Gà làm sạch, xát nhẹ với chút muối hạt và chanh khử mùi, rửa sạch. Dùng nghệ già tươi giã dập, xát nhẹ lên da sẽ giúp gà khi luộc trở nên vàng tự nhiên.', 10);
INSERT INTO public.recipe_steps VALUES (3987, '2025-11-20 17:11:56.448951', '2025-11-20 17:11:56.448951', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 622, 9, 'Sau đó, cho gạo này vào nồi cơm điện, thêm nước luộc gà, lá dứa, chút muối và chút bột nghệ nữa (nếu muốn vàng hơn) rồi nấu chín. Cơm nấu xong vừa dẻo, vừa tơi lại vàng óng, thơm thoang thoảng mùi lá dứa (lá nếp), lại hơi béo rất hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (3988, '2025-11-20 17:11:57.116759', '2025-11-20 17:11:57.116759', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 623, 3, 'Rửa sạch rau cải, hành tây, cà rốt, cà chua rồi tạo hình hoặc cắt miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (3989, '2025-11-20 17:11:57.118405', '2025-11-20 17:11:57.118405', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 623, 2, 'Thịt bò rửa sạch, thấm khô, thái mỏng, ướp với đường, dầu hào, hạt nêm, hạt tiêu, một chút dầu ăn và bột năng trong 15-20 phút. Việc ướp này sẽ giúp thịt bò không bị ra nước, mềm hơn khi xào mà lại đậm đà.', 10);
INSERT INTO public.recipe_steps VALUES (4136, '2025-11-20 17:12:03.039372', '2025-11-20 17:12:03.039372', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 643, 16, 'Tiếp tục nướng ở nhiệt độ 160 độ C trong 40 phút còn lại.', 10);
INSERT INTO public.recipe_steps VALUES (3990, '2025-11-20 17:11:57.119601', '2025-11-20 17:11:57.119601', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 623, 6, 'Xào rau củ: Cũng trên chảo đã xào thịt bò, thêm chút dầu ăn rồi cho 1/2 tỏi băm còn lại vào phi thơm. Lần lượt cho cà rốt và cà chua vào xào trước, rồi tới rau cải, cuối cùng thêm hành tây vào xào chín. Nêm nếm gia vị theo khẩu vị gia đình. Hòa tan bột bắp với chút nước rồi từ từ rót vào chảo xào, nhớ đảo đều để hỗn hợp trở nên sánh lại. Tiếp đến, nhanh tay trút thịt bò đã xào vào đảo đều rồi tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (3991, '2025-11-20 17:11:57.121211', '2025-11-20 17:11:57.121211', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 623, 4, 'b) Cách làm:Chiên phở phồng: Cho dầu ăn vào chảo, dùng đũa thử thấy dầu sủi tăm ở đầu đũa là đạt. Chia từng mẻ nhỏ, lần lượt cho từng miếng bánh phở vào chiên cho tới khi vàng ươm đều hai mặt, giòn rụm là được.', 10);
INSERT INTO public.recipe_steps VALUES (3992, '2025-11-20 17:11:57.124466', '2025-11-20 17:11:57.124466', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 623, 5, 'Xào thịt bò: Nên chia thịt bò thành mẻ nhỏ. Đun nóng dầu ăn trong chảo, cho 1/2 số tỏi băm vào phi thơm. Thêm thịt bò vào chảo và xào trên lửa lớn. Nhớ đảo nhanh và đều tay để thịt bò không ra nước sẽ giúp thịt mềm, ngọt tự nhiên. Khi thịt vừa chín tới thì tắt bếp, múc để riêng ra bát.', 10);
INSERT INTO public.recipe_steps VALUES (3993, '2025-11-20 17:11:57.126096', '2025-11-20 17:11:57.126096', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 623, 1, 'a) Sơ chế nguyên liệu: Bánh phở để 3-4 lá dính liền nhau, dùng dao sắc cắt thành từng khối vuông hoặc dùng khuôn cắt ấn tạo hình tùy thích.', 10);
INSERT INTO public.recipe_steps VALUES (3994, '2025-11-20 17:11:58.09648', '2025-11-20 17:11:58.09648', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 624, 8, 'e) Chuẩn bị các loại rau, quả: Rửa sạch, ngâm nước muối pha loãng, vẩy ráo.', 10);
INSERT INTO public.recipe_steps VALUES (3995, '2025-11-20 17:11:58.09804', '2025-11-20 17:11:58.09804', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 624, 2, 'Dùng dao sắc khứa chéo 2-3 đường lên mỗi bên thân cá để nhanh ngấm gia vị khi ướp, chín đều khi nướng.', 10);
INSERT INTO public.recipe_steps VALUES (3996, '2025-11-20 17:11:58.099662', '2025-11-20 17:11:58.099662', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 624, 7, 'd) Cách pha nước chấm: Trong một cái bát, cho nước, đường, chanh vào quấy đều cho tới khi đường tan hẳn thì mới cho nước mắm vào. Sau đó, thêm tỏi ớt gừng băm nhuyễn và thì là thái nhỏ vào quấy đều.', 10);
INSERT INTO public.recipe_steps VALUES (3997, '2025-11-20 17:11:58.101245', '2025-11-20 17:11:58.101245', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 624, 5, 'c) Cách nướng cá:Cá nướng trên bếp than hoa là ngon nhất. Nếu không có, bạn nướng bằng lò nướng, nồi nướng chuyên dụng đều được.', 10);
INSERT INTO public.recipe_steps VALUES (3998, '2025-11-20 17:11:58.10231', '2025-11-20 17:11:58.10231', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 624, 3, 'b) Ướp cá: Trong một cái bát, trộn tất cả hỗn hợp ướp cá gồm riềng, sả xay nhuyễn với mắm tôm, mẻ đã lọc qua rây, nước mắm, dầu hào, riềng, nghệ, sả, hành tỏi băm nhỏ, hạt tiêu, đường, hạt nêm, dầu ăn và ớt. Trộn đều cho tới khi trở thành hỗn hợp sốt riềng mẻ sền sệt, dậy mùi thơm đặc trưng.', 10);
INSERT INTO public.recipe_steps VALUES (3999, '2025-11-20 17:11:58.103933', '2025-11-20 17:11:58.103933', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 624, 1, 'a) Sơ chế cá: Cá làm sạch, bỏ hết ruột, dùng muối và chanh chà xát khắp mình rồi rửa thật sạch, thấm khô.', 10);
INSERT INTO public.recipe_steps VALUES (4000, '2025-11-20 17:11:58.105655', '2025-11-20 17:11:58.105655', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 624, 4, 'Đổ hỗn hợp này lên cá đã làm sạch, đeo bao tay nilon chà xát gia vị khắp mình cá và cả trong bụng cá. Dùng màng bọc thực phẩm bọc kín và để vào tủ lạnh tối thiểu 1 tiếng cho cá ngấm đều gia vị. Nếu có thời gian ướp lâu hơn thì cá khi nướng sẽ thơm ngon, đậm đà hơn.', 10);
INSERT INTO public.recipe_steps VALUES (4001, '2025-11-20 17:11:58.106833', '2025-11-20 17:11:58.106833', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 624, 6, 'Quết một lớp dầu mỏng vào vỉ (để đỡ dính cá), cho cá vào và nướng cho tới khi chín vàng, trở mặt kia lại tiếp tục nướng chín đều. Thời gian nướng tùy thuộc vào khối lượng và kích thước của cá. Trong khi nướng thỉnh thoảng bạn nên quết thêm dầu hoặc mỡ lợn để da cá được bóng đẹp và thịt cá không bị khô. Chú ý đừng nướng cá quá lửa hay cháy quá thịt cá sẽ bị khô.', 10);
INSERT INTO public.recipe_steps VALUES (4002, '2025-11-20 17:11:58.759514', '2025-11-20 17:11:58.759514', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 625, 1, 'Cách làm nước hoa đậu biếc: Cho lượng nước (ước lượng sẽ ngập sợi miến tầm 3 cm, không nên cho quá nhiều nước quá sẽ làm cho màu bị loãng). Thêm hoa đậu biếc đã rửa sạch vào và đậy nắp và đun nhỏ lửa trong 10 phút hoặc cho tới khi ra màu xanh đậm coban.', 10);
INSERT INTO public.recipe_steps VALUES (4003, '2025-11-20 17:11:58.76121', '2025-11-20 17:11:58.76121', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 625, 6, 'Trộn miến: Vớt miến để ráo cho vào tô, thêm tôm, mực, thịt heo, hành, cà rốt, dưa chuột, rau mùi, hành phi, tỏi phi trộn đều. Sau đó, rưới nước sốt chua ngọt đậm đà lên miến, trộn đều. Miến đang xanh khi gặp hỗn hợp nước sốt có nồng độ axit cao từ chanh sẽ dần dà chuyển màu từ xanh sang tím/hoặc hồng tùy vào lượng chanh cho vào. Một món ngon nên thử vào dịp vào cuối tuần, đảm bảo các bạn nhỏ sẽ rất thích thú.', 10);
INSERT INTO public.recipe_steps VALUES (4004, '2025-11-20 17:11:58.762811', '2025-11-20 17:11:58.762811', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 625, 4, 'Thịt băm ướp chút hạt tiêu, muối, hạt nêm. Sau đó, phi thơm hành cho thịt băm vào xào chín.', 10);
INSERT INTO public.recipe_steps VALUES (4005, '2025-11-20 17:11:58.763879', '2025-11-20 17:11:58.763879', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 625, 3, 'Tôm, mực sơ chế sạch rồi luộc với chút muối, gừng, sả cho thơm. Sau đó vớt ra để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (4006, '2025-11-20 17:11:58.764934', '2025-11-20 17:11:58.764934', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 625, 2, 'Cách luộc (trụng) miến lên màu xanh coban: Miến rửa sạch, cắt khoảng vừa ăn, cho vào nước hoa đậu biếc luộc trụng cho tới khi màu xanh bám đều và miến chín tầm 1-2 phút, không nên lâu quá khiến miến bị bở nhão. Vớt miến ra cho vào bát nước sôi để nguội có thêm chút đá để giữ màu xanh đẹp mắt, miến lại dai ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (4007, '2025-11-20 17:11:58.7661', '2025-11-20 17:11:58.7661', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 625, 5, 'Cách làm nước sốt: Hòa hỗn hợp nước, nước mắm, chanh, tỏi, ớt và khuấy tan. Nếu thích nước sốt đậm đà có thể thêm cà chua bi, dứa rồi giã nhuyễn, khuấy tan hỗn hợp.', 10);
INSERT INTO public.recipe_steps VALUES (4008, '2025-11-20 17:11:59.194681', '2025-11-20 17:11:59.194681', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 626, 10, 'Sau đó, bạn lấy gà ra lọc thịt, thái miếng mỏng vừa ăn, để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (4009, '2025-11-20 17:11:59.196396', '2025-11-20 17:11:59.196396', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 626, 12, 'Sau đó, vớt bỏ xương gà, củ cải, hành tây, gừng, túi đựng hạt mùi, sá sùng... rồi nêm nếm mắm, muối, hạt nêm hoặc đường tùy theo khẩu vị mỗi gia đình. Nếu thích nấm hương thì ngâm nấm hương khô với nước nóng, rửa sạch, cho vào nồi nước dùng. Như vậy đã có nồi nước dùng thơm ngon, thanh trong.', 10);
INSERT INTO public.recipe_steps VALUES (4010, '2025-11-20 17:11:59.198541', '2025-11-20 17:11:59.198541', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 626, 7, 'Trong quá trình đun liu riu, thỉnh thoảng hớt bọt để nước dùng trong. Không nên cho lòng, mề và tiết gà vào lúc này vì dễ làm gà bị đen. Cũng chưa cho hạt nêm vào vì khi hầm sẽ làm đục nước.', 10);
INSERT INTO public.recipe_steps VALUES (4011, '2025-11-20 17:11:59.199625', '2025-11-20 17:11:59.199625', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 626, 1, 'a) Cách sơ chế gà và xương gà:Gà làm sạch, xát nhẹ với chút muối hạt và chanh khử mùi, rửa sạch. Dùng nghệ già tươi xát nhẹ lên da gà sẽ giúp gà khi luộc trở nên vàng tự nhiên.', 10);
INSERT INTO public.recipe_steps VALUES (4012, '2025-11-20 17:11:59.201345', '2025-11-20 17:11:59.201345', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 626, 11, 'Số xương gà thì tiếp tục cho vào nồi nước dùng hầm tiếp tầm 45 phút. Phần lòng gà (tim, gan, mề, tiết cho vào nồi nước hầm luộc tầm 8-10 phút vớt ra).', 10);
INSERT INTO public.recipe_steps VALUES (4013, '2025-11-20 17:11:59.203136', '2025-11-20 17:11:59.203136', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 626, 13, 'c) Chần phở:Với bánh phở tươi, chần nhanh qua nước sôi, vớt ra để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (4014, '2025-11-20 17:11:59.204724', '2025-11-20 17:11:59.204724', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 626, 14, 'Với bánh phở khô ngâm vài phút cho mềm, rồi chần qua theo hướng dẫn trên túi.', 10);
INSERT INTO public.recipe_steps VALUES (4015, '2025-11-20 17:11:59.205786', '2025-11-20 17:11:59.205786', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 626, 3, 'Xương gà ngâm với nước ấm pha chút muối hạt và chanh tối thiểu 10 phút để loại bỏ máu, tạp chất rồi rửa sạch. Để nước dùng trong và thơm, nên cho xương gà vào nồi nước sôi kèm chút muối hạt, gừng đập dập trụng sơ nhằm loại bỏ tạp chất. Vớt ra rửa sạch lại lần nữa.', 10);
INSERT INTO public.recipe_steps VALUES (4016, '2025-11-20 17:11:59.207432', '2025-11-20 17:11:59.207432', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 626, 6, 'Sá sùng rửa sạch cho vào nồi nước dùng.', 10);
INSERT INTO public.recipe_steps VALUES (4017, '2025-11-20 17:11:59.209647', '2025-11-20 17:11:59.209647', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 626, 8, 'Sau 15-20 phút tắt bếp, ngâm gà tầm 10-15 phút tùy theo khối lượng. Việc này vừa giúp gà ngậm nước sẽ mọng thịt, ngọt thơm hơn. Đồng thời, giúp cho thịt gà không bị đỏ nước.', 10);
INSERT INTO public.recipe_steps VALUES (4018, '2025-11-20 17:11:59.211265', '2025-11-20 17:11:59.211265', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 626, 15, 'd) Chuẩn bị các loại rau:Rau mùi rửa sạch, hành lá chẻ, lá chanh thái sợi nhỏ, chanh cắt ra, ớt thái khoanh.', 10);
INSERT INTO public.recipe_steps VALUES (4019, '2025-11-20 17:11:59.212352', '2025-11-20 17:11:59.212352', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 626, 2, 'Trứng non ngâm chút nước muối pha loãng, rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (4020, '2025-11-20 17:11:59.214072', '2025-11-20 17:11:59.214072', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 626, 5, 'Cho hạt mùi rang, gốc rau mùi rửa sạch, hành khô nướng (đã lột vỏ đen, rửa sạch), gừng nướng rửa sạch để vào túi vải sạch buộc lại rồi cho vào nồi luộc gà cùng với củ hành tây chẻ đôi, củ cải trắng.', 10);
INSERT INTO public.recipe_steps VALUES (4021, '2025-11-20 17:11:59.215695', '2025-11-20 17:11:59.215695', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 626, 9, 'Khi nước hơi nguội, vớt gà ra, lấy một khăn ẩm ủ kín gà sẽ giúp da bóng mượt hơn. Chờ gà nguội, cho vào tủ lạnh một lúc tầm 30 phút để da săn lại, giúp cho việc lọc và thái thịt dễ dàng, đẹp mắt hơn.', 10);
INSERT INTO public.recipe_steps VALUES (4022, '2025-11-20 17:11:59.217308', '2025-11-20 17:11:59.217308', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 626, 4, 'b) Cách nấu nước dùng và luộc gà:Cho gà và xương gà vào nồi có đáy sâu, thêm nước sao cho ngập gà.', 10);
INSERT INTO public.recipe_steps VALUES (4023, '2025-11-20 17:11:59.455584', '2025-11-20 17:11:59.455584', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 627, 8, '- Bạn lót tấm bạc lên khay, cho gà lên, đặt ngay ngắn. Nướng gà trong khoảng 15 phút đầu, sau đó lấy gà ra và quét thêm một lớp mật ong xung quanh bên ngoài con gà, tiếp tục nướng thêm trong khoảng 15-20 phút là bạn hoàn tất món ăn.', 10);
INSERT INTO public.recipe_steps VALUES (4024, '2025-11-20 17:11:59.457127', '2025-11-20 17:11:59.457127', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 627, 10, '- Cho gà ra đĩa và trang trí theo ý thích. Gà nướng mật ong có thể dùng với bánh mì hay cơm trắng, chấm nước mắm chua cay hoặc muối ớt chanh đều ngon.', 10);
INSERT INTO public.recipe_steps VALUES (4025, '2025-11-20 17:11:59.458704', '2025-11-20 17:11:59.458704', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 627, 1, 'Nếu ngán gà luộc, chiên, bạn có thể đổi vị cùng món gà nướng mật ong, với cách làm đơn giản như sau:', 10);
INSERT INTO public.recipe_steps VALUES (4026, '2025-11-20 17:11:59.460302', '2025-11-20 17:11:59.460302', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 627, 9, 'Bước 3: Thưởng thức', 10);
INSERT INTO public.recipe_steps VALUES (4027, '2025-11-20 17:11:59.462109', '2025-11-20 17:11:59.462109', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 627, 3, 'Thực hiện:
INSERT INTO public.recipe_steps VALUES (4028, '2025-11-20 17:11:59.463182', '2025-11-20 17:11:59.463182', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 627, 4, '- Gà mua về, lấy nội tạng bên trong và rửa thật sạch với rượu, gừng, muối để khử mùi hôi. Sau đó rửa lại thật sạch dưới nước, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (4029, '2025-11-20 17:11:59.465338', '2025-11-20 17:11:59.465338', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 627, 2, 'Nguyên liệu:
INSERT INTO public.recipe_steps VALUES (4030, '2025-11-20 17:11:59.466946', '2025-11-20 17:11:59.466946', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 627, 7, '- Bạn rưới phần hỗn hợp gia vị lên khắp con gà (cả trong và ngoài), dùng bao tay chà sát cho phần gia vị hỗn hợp thấm đều vào gà, để trong khoảng 2-3 giờ.', 10);
INSERT INTO public.recipe_steps VALUES (4031, '2025-11-20 17:11:59.468546', '2025-11-20 17:11:59.468546', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 627, 11, 'Lưu ý: Để làm món gà nướng mật ong thơm ngon phải chọn con gà tơ không quá già, cũng không quá non, khoảng 15,-2 kg là vừa. Nếu bạn thích vị béo, nồng thì có thể cho thêm bơ sữa vào trong nước xốt ướp gà. Ngoài ra, bạn có thể vắt chút chanh hoặc cam lên gà sẽ giúp gà nướng không bị khô, hương vị thơm ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (4032, '2025-11-20 17:11:59.471316', '2025-11-20 17:11:59.471316', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 627, 5, '- Hành và tỏi bóc vỏ, đập dập, băm nhỏ rồi cho chén vùng với bột nêm, ngũ vị hương, tiêu, dầu hào trộn đều cho các gia vị ướp hòa quyện vào nhau.', 10);
INSERT INTO public.recipe_steps VALUES (4033, '2025-11-20 17:11:59.473435', '2025-11-20 17:11:59.473435', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 627, 6, 'Bước 2: Ướp gà', 10);
INSERT INTO public.recipe_steps VALUES (4034, '2025-11-20 17:11:59.47503', '2025-11-20 17:11:59.47503', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 627, 12, 'Nếu nhà có không gian thoáng đoãng, bạn cũng có thể chọn cách nướng gà bằng than. Tuy nhiên, với những gia đình trong thành phố, việc chuẩn bị một lò nướng than khá khó khăn thì có thể dùng lò nướng điện.', 10);
INSERT INTO public.recipe_steps VALUES (4054, '2025-11-20 17:12:00.772812', '2025-11-20 17:12:00.772812', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 633, 7, 'Làm nước chấm gừng: Giã nát tỏi, ớt, gừng, cho 2 thìa canh nước mắm, 2 thìa canh đường, 2 thìa canh nước, 1 thìa canh giấm khuấy đều. Thêm lá chanh thái sợi. Nêm nếm lại gia vị cho vừa miệng.', 10);
INSERT INTO public.recipe_steps VALUES (4168, '2025-11-20 17:12:04.439379', '2025-11-20 17:12:04.439379', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 648, 3, 'Rau răm rửa sạch thái rối.', 10);
INSERT INTO public.recipe_steps VALUES (4035, '2025-11-20 17:11:59.620187', '2025-11-20 17:11:59.620187', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 628, 2, 'Tẩm ướp
INSERT INTO public.recipe_steps VALUES (4036, '2025-11-20 17:11:59.622271', '2025-11-20 17:11:59.622271', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 628, 3, 'Yêu cầu thành phẩm
INSERT INTO public.recipe_steps VALUES (4037, '2025-11-20 17:11:59.624313', '2025-11-20 17:11:59.624313', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 628, 1, 'Sơ chế
INSERT INTO public.recipe_steps VALUES (4038, '2025-11-20 17:11:59.885379', '2025-11-20 17:11:59.885379', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 629, 4, 'Yêu cầu thành phẩm
INSERT INTO public.recipe_steps VALUES (4039, '2025-11-20 17:11:59.887088', '2025-11-20 17:11:59.887088', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 629, 3, 'Chế biến
INSERT INTO public.recipe_steps VALUES (4040, '2025-11-20 17:11:59.889766', '2025-11-20 17:11:59.889766', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 629, 1, 'Sơ chế
INSERT INTO public.recipe_steps VALUES (4041, '2025-11-20 17:11:59.891877', '2025-11-20 17:11:59.891877', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 629, 2, 'Tẩm ướp
INSERT INTO public.recipe_steps VALUES (4055, '2025-11-20 17:12:00.774414', '2025-11-20 17:12:00.774414', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 633, 6, 'Chế biến
INSERT INTO public.recipe_steps VALUES (4056, '2025-11-20 17:12:00.775462', '2025-11-20 17:12:00.775462', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 633, 2, 'Đập nhẹ trôn ốc, khều lấy phần thịt ốc, bỏ phân, bóp chanh và muối hạt khử mùi và hết nhớt. Sau đó, rửa sạch nhiều lần, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (4042, '2025-11-20 17:12:00.157628', '2025-11-20 17:12:00.157628', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 630, 1, 'Sơ chế
INSERT INTO public.recipe_steps VALUES (4043, '2025-11-20 17:12:00.159737', '2025-11-20 17:12:00.159737', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 630, 2, 'Chế biến
INSERT INTO public.recipe_steps VALUES (4044, '2025-11-20 17:12:00.285737', '2025-11-20 17:12:00.285737', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 631, 1, 'Sơ chế
INSERT INTO public.recipe_steps VALUES (4045, '2025-11-20 17:12:00.287607', '2025-11-20 17:12:00.287607', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 631, 2, 'Ướp cá rô đồng với 1/2 phần hành, tỏi, ớt giã nhuyễn cùng nước sốt kho tối thiểu trong 30 phút cho thấm vị.', 10);
INSERT INTO public.recipe_steps VALUES (4046, '2025-11-20 17:12:00.289173', '2025-11-20 17:12:00.289173', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 631, 3, 'Chế biến
INSERT INTO public.recipe_steps VALUES (4047, '2025-11-20 17:12:00.605277', '2025-11-20 17:12:00.605277', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 632, 1, 'Sơ chế
INSERT INTO public.recipe_steps VALUES (4048, '2025-11-20 17:12:00.606865', '2025-11-20 17:12:00.606865', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 632, 3, 'Chế biến
INSERT INTO public.recipe_steps VALUES (4049, '2025-11-20 17:12:00.608446', '2025-11-20 17:12:00.608446', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 632, 2, 'Tẩm ướp
INSERT INTO public.recipe_steps VALUES (4050, '2025-11-20 17:12:00.610175', '2025-11-20 17:12:00.610175', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 632, 4, 'Yêu cầu thành phẩm
INSERT INTO public.recipe_steps VALUES (4051, '2025-11-20 17:12:00.767974', '2025-11-20 17:12:00.767974', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 633, 3, 'Tẩm ướp
INSERT INTO public.recipe_steps VALUES (4052, '2025-11-20 17:12:00.769609', '2025-11-20 17:12:00.769609', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 633, 4, 'Thịt ốc thái hạt lựu. Mộc nhĩ, nấm hương ngâm nở rửa sạch, thái nhỏ. Hành khô băm nhỏ, ớt bỏ hạt băm nhỏ, gừng thái nhỏ. Cho tất cả hỗn hợp thịt vai xay cùng giò sống, ốc và mộc nhĩ, hành khô, ớt, gừng vào âu lớn. Thêm 1 thìa cà phê nước mắm, 2 thìa cà phê hạt nêm, 2 thìa cà phê hạt tiêu. Đeo găng tay quết quật liên tục để nhân hòa quyện đều thành khối kết dính, dẻo dai.', 10);
INSERT INTO public.recipe_steps VALUES (4053, '2025-11-20 17:12:00.771209', '2025-11-20 17:12:00.771209', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 633, 5, 'Đặt 2 lá gừng chéo vào đầu miệng ốc, lấy thìa múc lượng nhân ấn vào cho đầy con ốc. Sau đó, thoa chút nước xoa đều ấn chặt cho đẹp, không bị dính, giúp cho khi hấp phần mọc ốc này không bị bung rời ra. Làm lần lượt cho tới hết.', 10);
INSERT INTO public.recipe_steps VALUES (4057, '2025-11-20 17:12:00.777046', '2025-11-20 17:12:00.777046', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 633, 1, 'Sơ chế
INSERT INTO public.recipe_steps VALUES (4058, '2025-11-20 17:12:00.908819', '2025-11-20 17:12:00.908819', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 634, 1, 'Chuẩn bị
INSERT INTO public.recipe_steps VALUES (4059, '2025-11-20 17:12:00.910428', '2025-11-20 17:12:00.910428', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 634, 3, 'Chế biến
INSERT INTO public.recipe_steps VALUES (4060, '2025-11-20 17:12:00.912567', '2025-11-20 17:12:00.912567', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 634, 2, 'Trước khi chiên, lấy ra ướp cơm với 2 thìa cà phê nước mắm, 1 thìa cà phê hạt nêm, 1 thìa cà phê hạt tiêu, 1-2 quả trứng, đeo găng tay bóp đều để hạt cơm tơi. Việc ướp như này vừa giúp cơm thấm vị, vừa giúp khi chiên hạt cơm tơi, bùi ngậy thơm ngon.
INSERT INTO public.recipe_steps VALUES (4061, '2025-11-20 17:12:01.050076', '2025-11-20 17:12:01.050076', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 635, 3, 'Ướp giò heo với tương hột, chao cùng 1 muỗng canh sa tế, 1/2 muỗng canh đường, 1/2 muỗng canh dầu màu điều, 1 muỗng cà phê muối, 1/2 muỗng cà phê hạt nêm, 1/2 muỗng cà phê ngũ vị hương cùng 1/2 lượng hành, tỏi, sả, ớt băm. Trộn đều ướp trong 30 phút cho thấm vị.', 10);
INSERT INTO public.recipe_steps VALUES (4062, '2025-11-20 17:12:01.051682', '2025-11-20 17:12:01.051682', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 635, 4, 'Phi thơm lượng hành, tỏi, sả còn lại. Cho giò heo đã ướp vào đảo đều cho săn lại.', 10);
INSERT INTO public.recipe_steps VALUES (4063, '2025-11-20 17:12:01.053856', '2025-11-20 17:12:01.053856', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 635, 6, 'Yêu cầu thành phẩm: Giò heo mềm mà vẫn giữ độ giòn sần sật, vị mặn ngọt bùi béo hài hòa, dậy mùi thơm quyến rũ từ chao.', 10);
INSERT INTO public.recipe_steps VALUES (4064, '2025-11-20 17:12:01.055993', '2025-11-20 17:12:01.055993', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 635, 1, 'Giò heo cạo sạch, thui bằng rơm hoặc dùng đèn khò cho xém vàng, ngả màu nâu sậm. Cạo hết bụi tro, rửa sạch, chặt miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (4065, '2025-11-20 17:12:01.057669', '2025-11-20 17:12:01.057669', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 635, 5, 'Sau đó, thêm lượng nước dừa tươi xâm xấp bề mặt và ninh ở lửa nhỏ vừa. Nêm nếm gia vị vừa ăn. Khi giò heo đạt độ mềm mong muốn, nước sóng sánh thì tắt bếp, múc ra thêm đậu phộng rang, thưởng thức nóng cùng bánh mì, bún hay cơm trắng.', 10);
INSERT INTO public.recipe_steps VALUES (4066, '2025-11-20 17:12:01.059786', '2025-11-20 17:12:01.059786', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 635, 2, 'Hành, tỏi, ớt, sả băm nhuyễn. Lấy 80 gr tương hột tán đều, chao tán nhuyễn 2 muỗng canh.', 10);
INSERT INTO public.recipe_steps VALUES (4067, '2025-11-20 17:12:01.204673', '2025-11-20 17:12:01.204673', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 636, 3, 'Ướp cá linh với 3-4 muỗng canh nước mắm, 2 muỗng canh nước màu, 1 muỗng canh đường, 1 muỗng cà phê muối, 1 muỗng cà phê hạt nêm, 1 muỗng cà phê hạt tiêu cùng 1/2 lượng hành, tỏi, ớt, đảo đều ướp trong 30 phút cho thấm vị.', 10);
INSERT INTO public.recipe_steps VALUES (4068, '2025-11-20 17:12:01.206271', '2025-11-20 17:12:01.206271', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 636, 5, 'Yêu cầu thành phẩm: Thịt cá mềm béo, nước dừa tươi ngọt thanh quyện với vị chua nhẹ từ me, chút the cay từ ớt đậm chất dân dã miền Tây mùa nước nổi. Món này ăn nóng với bún hoặc cơm đều ngon.', 10);
INSERT INTO public.recipe_steps VALUES (4069, '2025-11-20 17:12:01.207898', '2025-11-20 17:12:01.207898', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 636, 1, 'Cá linh cắt ngang rốn đoạn nhỏ, nặn ruột bên trong, rửa sạch để ráo nước. Cá kho nguyên con, không cần đánh vảy vì thịt cá ngọt mềm, nhanh chín.', 10);
INSERT INTO public.recipe_steps VALUES (4070, '2025-11-20 17:12:01.209494', '2025-11-20 17:12:01.209494', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 636, 4, 'Phi thơm lượng hành, tỏi còn lại rồi cho nước dừa, nước cốt me vào đun sôi. Cho cá linh cùng nước ướp vào kho ở lửa nhỏ liu riu. Hớt bỏ bọt và nêm nếm lại gia vị cho vừa miệng. Cá linh mau chín, khi thấy dậy mùi thơm là được. Thêm hành lá, rắc chút hạt tiêu rồi múc ra thưởng thức nóng, ăn cùng bông điên điển, bông súng, tai tượng, đọt lá cách... Kho lạt chuẩn vị là không để nước cạn.', 10);
INSERT INTO public.recipe_steps VALUES (4071, '2025-11-20 17:12:01.211161', '2025-11-20 17:12:01.211161', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 636, 2, 'Hành, tỏi băm nhỏ. Hành lá cắt nhỏ. Ớt băm nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (4072, '2025-11-20 17:12:01.524706', '2025-11-20 17:12:01.524706', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 637, 3, 'Cho dầu ăn vào nồi, đợi dầu nóng, cho củ hành tím và ớt màu vào phi thơm, rồi cho thịt hến vào xào.', 10);
INSERT INTO public.recipe_steps VALUES (4073, '2025-11-20 17:12:01.525763', '2025-11-20 17:12:01.525763', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 637, 4, 'Cho tiếp vào nồi 1 lít nước sôi, cho bầu vào nồi nấu chín. Nêm hạt nêm từ thịt.', 10);
INSERT INTO public.recipe_steps VALUES (4074, '2025-11-20 17:12:01.52742', '2025-11-20 17:12:01.52742', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 637, 1, 'Bầu, gọt vỏ, băm nhuyễn hoặc cắt que', 10);
INSERT INTO public.recipe_steps VALUES (4075, '2025-11-20 17:12:01.529123', '2025-11-20 17:12:01.529123', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 637, 5, 'Múc canh ra tô, rắc hành ngò, tiêu xay. Dùng nóng với nước mắm mặn và ớt.', 10);
INSERT INTO public.recipe_steps VALUES (4076, '2025-11-20 17:12:01.530188', '2025-11-20 17:12:01.530188', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 637, 2, 'Làm hến: Đầu tiên, bạn bắc một nồi nước chờ cho sôi bùng rồi múc hến cho vào nồi, dùng đũa khuấy cho thịt hến rơi ra. Gặp nước sôi thịt hến sẽ nổi lên và bạn dùng vợt vớt thịt hến để vào bát, còn vỏ hến chìm xuống dưới vì vớt bỏ đi.', 10);
INSERT INTO public.recipe_steps VALUES (4077, '2025-11-20 17:12:01.598527', '2025-11-20 17:12:01.598527', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 638, 3, 'Rửa sạch cà, để ráo rồi xóc muối hạt, tỷ lệ 1 kg cà, 500 gr muối hạt (hoặc mặn hơn, cà càng mặn thì càng giòn), để khoảng 1 - 2 giờ. Vì quy tắc trong ẩm thực ''''Muối tách, đường giữ'''', việc ướp muối giúp nước bên trong củ quả tiết ra sẽ giòn hơn, muối cũng giúp việc bảo quản được lâu.', 10);
INSERT INTO public.recipe_steps VALUES (4078, '2025-11-20 17:12:01.600146', '2025-11-20 17:12:01.600146', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 638, 4, 'Nước đun sôi để nguội âm ấm khoảng 35-40 độ.', 10);
INSERT INTO public.recipe_steps VALUES (4079, '2025-11-20 17:12:01.601784', '2025-11-20 17:12:01.601784', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 638, 1, 'Chọn những quả cà pháo vừa, cứng cáp, đều tay (không quá to hay quá nhỏ). Việc gọt cuống đòi hỏi sự tỉ mỉ, dùng dao nhỏ sắc gọt hớt chéo sao cho không lẹm vào thịt cà mà vẫn tròn trĩnh, dư chút đầu cuống.', 10);
INSERT INTO public.recipe_steps VALUES (4080, '2025-11-20 17:12:01.603383', '2025-11-20 17:12:01.603383', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 638, 2, 'Rải đều cà lên mẹt hoặc mặt phẳng đem phơi, hong gió hoặc ngày xưa các bà các mẹ đặt gầm giường cho cà héo, rút bớt nước.', 10);
INSERT INTO public.recipe_steps VALUES (4081, '2025-11-20 17:12:01.60496', '2025-11-20 17:12:01.60496', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 638, 6, 'Hũ thủy tinh rửa sạch, tráng nước sôi, để ráo nước. Trút tất cả cà và nước muối ướp vào, xen kẽ tỏi, riềng, ớt rồi dội nước ấm lên xâm xấp bề mặt. Dùng vỉ nan tre tròn úp và lấy hòn đá cuội nặng chèn cho cà không nổi bề mặt. Nếu không có thì cho nước vào túi nilon sạch, buộc chặt chèn lên để cà không nổi gây thâm đen. Sau một tuần cà sẽ chín vừa ăn. Cà muốn để lâu thì tăng lượng muối.', 10);
INSERT INTO public.recipe_steps VALUES (4082, '2025-11-20 17:12:01.6068', '2025-11-20 17:12:01.6068', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 638, 7, 'Yêu cầu thành phẩm: Từng quả cà trắng ngà, ăn giòn vang cửa miệng, vị mặn đậm đà. Bữa cơm mùa hè trở nên đưa miệng hơn bao giờ hết khi có dăm ba quả cà muối mặn ăn cùng bát canh rau vặt hoặc rau muống luộc. Không phải sơn hào hải vị gì, chỉ mặn mòi vị đồng quê mà cà muối mặn xứ Nghệ lại được nhiều người yêu thích, trở thành đặc sản bình dân.', 10);
INSERT INTO public.recipe_steps VALUES (4083, '2025-11-20 17:12:01.608413', '2025-11-20 17:12:01.608413', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 638, 5, 'Riềng tỏi cắt lát hoặc giã nhỏ. Ớt cay rửa sạch, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (4084, '2025-11-20 17:12:01.847129', '2025-11-20 17:12:01.847129', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 639, 5, 'Múc chè cốm ra bát, rưới thêm chút nước cốt dừa, rắc dừa nạo là hoàn thành. Chè cốm thưởng thức nóng hay nguội đều rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (4085, '2025-11-20 17:12:01.84872', '2025-11-20 17:12:01.84872', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 639, 6, 'Yêu cầu thành phẩm: Chè cốm mộc còn nguyên hạt, sánh trong, hạt cốm quyện đều không bị chìm, thoảng mùi thơm của cốm và lá dứa rất hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (4086, '2025-11-20 17:12:01.850325', '2025-11-20 17:12:01.850325', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 639, 1, 'Cốm nhặt bỏ hạt lép, xấu bỏ đi. Lá dứa rửa sạch, buộc/bó lại.', 10);
INSERT INTO public.recipe_steps VALUES (4087, '2025-11-20 17:12:01.852463', '2025-11-20 17:12:01.852463', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 639, 3, 'Hòa 2 thìa canh bột năng với 2-3 thìa canh nước, khuấy đều. Hạ nhỏ lửa nồi nước đường, vừa chế bột năng, vừa khuấy đều tay một chiều để bột không bị vón cục.', 10);
INSERT INTO public.recipe_steps VALUES (4088, '2025-11-20 17:12:01.854091', '2025-11-20 17:12:01.854091', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 639, 4, 'Khi bột năng sánh lại, chuyển màu trong thì cho cốm vào khuấy đều, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (4089, '2025-11-20 17:12:01.856286', '2025-11-20 17:12:01.856286', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 639, 2, 'Hòa 1 lít nước với 150 g đường phèn, thêm lá dứa đun sôi, khuấy đều cho đường tan hẳn, vớt lá dứa ra.', 10);
INSERT INTO public.recipe_steps VALUES (4090, '2025-11-20 17:12:02.051235', '2025-11-20 17:12:02.051235', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 640, 5, 'Chiên sơ cho mặt chả ốc xém vàng (hoặc có thể hấp, tùy chọn), vớt ra.', 10);
INSERT INTO public.recipe_steps VALUES (4091, '2025-11-20 17:12:02.052288', '2025-11-20 17:12:02.052288', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 640, 3, 'Trộn đều ốc với giò sống, thịt xay, mỡ phần, mộc nhĩ, nấm hương, gừng, sả, ớt cùng lá lốt, tía tô,  Thêm 1 thìa cà phê nước mắm, 1 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu, quết trộn đều tạo độ kết dính. Để tạo ngăn mát tủ lạnh khoảng 30 phút cho dễ tạo hình.', 10);
INSERT INTO public.recipe_steps VALUES (4092, '2025-11-20 17:12:02.05387', '2025-11-20 17:12:02.05387', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 640, 4, 'Đeo găng tay, thoa một chút dầu ăn và múc lượng vừa phải, nặn và vê tròn thành các viên chả khoảng 4 - 5 cm.', 10);
INSERT INTO public.recipe_steps VALUES (4093, '2025-11-20 17:12:02.055601', '2025-11-20 17:12:02.055601', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 640, 2, 'Ốc thái mỏng hoặc hạt lựu (không nên nhỏ quá) để tạo độ giòn cho món ăn. Mỡ phần luộc và thái nhỏ để giúp món ăn không bị khô. Mộc nhĩ và nấm hương ngâm nở, rửa sạch, thái nhỏ. Sả, gừng, ớt băm nhỏ. Lá lốt, tía tô rửa sạch, thái nhỏ (1/2 trộn chả, 1/2 còn lại để lót vào gói chả ốc giấy bạc).', 10);
INSERT INTO public.recipe_steps VALUES (4094, '2025-11-20 17:12:02.056637', '2025-11-20 17:12:02.056637', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 640, 1, 'Ốc ngâm nước vo gạo, cắt thêm ớt cay để nhả hết bùn đất, rửa sạch, cho ốc vào luộc. Khi nước sôi bùng lên và mày ốc bung ra thì vớt ra ngay, chặt trôn và khều ốc, bỏ phân, rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (4095, '2025-11-20 17:12:02.058229', '2025-11-20 17:12:02.058229', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 640, 6, 'Đánh tan trứng gà, nêm nếm chút mắm, muối, hạt nêm. Lót giấy bạc lên mặt phẳng, phết chút dầu ăn rồi rải đều một lớp lá lốt, tía tô thái nhỏ lên. Sau đó, cho 6 - 8 viên chả lá lốt vào, rưới trứng lên rồi gập giấy bạc gói lại theo hình chữ nhật hoặc hình vuông, bao mép kín lại.', 10);
INSERT INTO public.recipe_steps VALUES (4096, '2025-11-20 17:12:02.059874', '2025-11-20 17:12:02.059874', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 640, 8, 'Yêu cầu thành phẩm: Khi ăn chả ốc cảm nhận được vị sần sật của ốc mà không dai, hài hòa vị ngọt, béo, bùi, thơm rất đẩy đưa vị giác. Khi ăn chấm cùng mắm gừng cay cay khiến mọi giác quan như bùng nổ đầy mê hoặc.', 10);
INSERT INTO public.recipe_steps VALUES (4097, '2025-11-20 17:12:02.060962', '2025-11-20 17:12:02.060962', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 640, 7, 'Đem gói chả ốc giấy bạc cho vào lò nướng ở 170 độ trong 10 phút. Hoặc ở một số nhà hàng thì đem chiên ngập dầu trong 1 - 2 phút là dùng được.', 10);
INSERT INTO public.recipe_steps VALUES (4098, '2025-11-20 17:12:02.311247', '2025-11-20 17:12:02.311247', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 641, 6, 'Hành nướng bóc vỏ băm nhuyễn, tỏi băm nhỏ, lá chanh thái chỉ nhỏ, ớt bỏ hạt băm nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (4099, '2025-11-20 17:12:02.313407', '2025-11-20 17:12:02.313407', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 641, 12, 'Yêu cầu thành phẩm: Nem ngọt bởi thịt đã chín vừa độ quyện bì sần sật, thêm mỡ béo ngậy mà không khô, dậy mùi thơm của thính chấm nước mắm chua ngọt rất hấp dẫn. Đây là món ăn phổ biến trong các mâm cỗ của người dân quê lúa Thái Bình.', 10);
INSERT INTO public.recipe_steps VALUES (4100, '2025-11-20 17:12:02.315526', '2025-11-20 17:12:02.315526', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 641, 8, 'Lá sung, lá đinh lăng nhặt và rửa sạch, ngâm nước muối loãng, vẩy ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (4132, '2025-11-20 17:12:03.034314', '2025-11-20 17:12:03.034314', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 643, 7, 'Cho một nửa lượng sữa vào và trộn đều cùng số bột trong âu chưa quyện hết', 10);
INSERT INTO public.recipe_steps VALUES (4133, '2025-11-20 17:12:03.035315', '2025-11-20 17:12:03.035315', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 643, 12, 'Trước khi bắt tay vào trộn nguyên liệu chúng ta cần bật lò trước để làm nóng lò ở nhiệt độ 160 độ', 10);
INSERT INTO public.recipe_steps VALUES (4101, '2025-11-20 17:12:02.317132', '2025-11-20 17:12:02.317132', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 641, 9, 'Cho tất cả nguyên liệu (thịt lợn dần nhuyễn, bì thái mỏng, mỡ cùng hành, tỏi, lá chanh, ớt) vào tô trộn. Nêm 2 thìa canh nước mắm ngon, 2 thìa cà phê hạt tiêu, 2 thìa cà phê nước cốt chanh, 1-2 thìa cà phê mì chính vào, trộn đều, đeo găng tay bóp nhuyễn. Đây là công đoạn quyết định món nem ngon hay không. Bóp liên tục cho nóng, tới khi quyện lại thành hỗn hợp dẻo và thịt từ màu hồng dần sang màu tái chín do có tỏi ớt và các gia vị hòa vào nhau.', 10);
INSERT INTO public.recipe_steps VALUES (4102, '2025-11-20 17:12:02.319376', '2025-11-20 17:12:02.319376', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 641, 5, 'Hành củ khô nướng chín để tạo mùi thơm và không bị hăng.', 10);
INSERT INTO public.recipe_steps VALUES (4103, '2025-11-20 17:12:02.321078', '2025-11-20 17:12:02.321078', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 641, 3, 'Sau đó để nghiêng và thái mỏng bì, càng mỏng càng tốt.', 10);
INSERT INTO public.recipe_steps VALUES (4104, '2025-11-20 17:12:02.322828', '2025-11-20 17:12:02.322828', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 641, 10, 'Từ từ cho thêm thính vào, bóp đều để dậy mùi thơm đặc trưng cho tới khi nem kết dính, không chảy rót, rời rạc là đạt.', 10);
INSERT INTO public.recipe_steps VALUES (4105, '2025-11-20 17:12:02.324916', '2025-11-20 17:12:02.324916', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 641, 2, 'Bì luộc chín, vớt ra để ráo, lạng (lọc) mỡ ra để riêng. Ban đầu khứa vát ngửa (thái giả) nhưng không đứt bì.', 10);
INSERT INTO public.recipe_steps VALUES (4106, '2025-11-20 17:12:02.325919', '2025-11-20 17:12:02.325919', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 641, 1, 'Chọn thịt lợn tươi mới, còn nóng hổi (không rửa nước) mà cho vào nồi nước sôi già kèm vài củ hành tím, chút muối để luộc/chần sơ. Theo kiểu truyền thống của người dân Thái Bình thì luộc/chần sơ để làm sao thịt bên trong vẫn còn màu hồng (dễ nắm hơn). Vớt ra, để ráo nước rồi thái mỏng thịt và dùng sống dao băm nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (4107, '2025-11-20 17:12:02.32692', '2025-11-20 17:12:02.32692', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 641, 4, 'Phần mỡ thì băm nhuyễn để cho vào nem không bị khô.', 10);
INSERT INTO public.recipe_steps VALUES (4108, '2025-11-20 17:12:02.329438', '2025-11-20 17:12:02.329438', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 641, 11, 'Nắm nem lại thành các nắm (bằng lòng bàn tay), gói vào lá chuối để trong ngăn mát tủ lạnh ăn trong 2 -3 ngày.', 10);
INSERT INTO public.recipe_steps VALUES (4109, '2025-11-20 17:12:02.330821', '2025-11-20 17:12:02.330821', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 641, 7, 'Rang gạo nếp và gạo tẻ (tỷ lệ 4:1) cho vàng thơm rồi xay còn hạt li ti nhỏ (không xay mịn như thính các vùng khác, thính Thái Bình vẫn xay vẫn còn hạt li ti để khi bóp trộn các nguyên liệu dậy mùi thơm, kết dính mà không bết lại).', 10);
INSERT INTO public.recipe_steps VALUES (4110, '2025-11-20 17:12:02.615932', '2025-11-20 17:12:02.615932', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 642, 2, 'Nghệ tươi rửa sạch, cạo bỏ vỏ, cắt miếng nhỏ, đem hấp sơ để giảm bớt mùi hăng.', 10);
INSERT INTO public.recipe_steps VALUES (4111, '2025-11-20 17:12:02.617528', '2025-11-20 17:12:02.617528', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 642, 8, 'Cho tóp mỡ vào chảo, rán sơ thành tóp, vớt ra để nguội và cắt nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (4112, '2025-11-20 17:12:02.619665', '2025-11-20 17:12:02.619665', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 642, 14, 'Đặt bánh vào nồi hấp khoảng 25 – 30 phút cho tới khi chín mềm, dẻo thơm là được. Lấy bánh ra và ăn nóng.', 10);
INSERT INTO public.recipe_steps VALUES (4113, '2025-11-20 17:12:02.621278', '2025-11-20 17:12:02.621278', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 642, 12, 'Đeo găng tay, thoa chút dầu ăn vào để chống dính.', 10);
INSERT INTO public.recipe_steps VALUES (4114, '2025-11-20 17:12:02.622343', '2025-11-20 17:12:02.622343', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 642, 4, 'Trong một tô trộn lớn, cho bột gạo tẻ vào tô cùng 1/2 thìa cà phê muối.', 10);
INSERT INTO public.recipe_steps VALUES (4115, '2025-11-20 17:12:02.624462', '2025-11-20 17:12:02.624462', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 642, 7, 'Làm nhân bánh:', 10);
INSERT INTO public.recipe_steps VALUES (4116, '2025-11-20 17:12:02.626056', '2025-11-20 17:12:02.626056', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 642, 10, 'Cho chút mỡ lợn vào chảo, phi thơm hành khô, thêm nấm hướng, mộc nhĩ, tóp ba chỉ vào xào. Nêm nước mắm, muối, hạt nêm, bột quế theo khẩu vị, tắt bếp, múc ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (4117, '2025-11-20 17:12:02.627749', '2025-11-20 17:12:02.627749', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 642, 5, 'Thêm từ từ nước cốt nghệ và nước ấm vào bột gạo tẻ, nhào bột cho tới khi trở thành hỗn hợp dẻo mịn.', 10);
INSERT INTO public.recipe_steps VALUES (4118, '2025-11-20 17:12:02.629334', '2025-11-20 17:12:02.629334', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 642, 9, 'Nấm hương, mộc nhĩ ngâm nước ấm cho nở, rửa sạch, cắt nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (4119, '2025-11-20 17:12:02.630913', '2025-11-20 17:12:02.630913', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 642, 13, 'Chia bột thành các miếng nhỏ, vê tròn lại, ấn dẹt. Sau đó, múc 1 thìa nhân cho vào giữa, gập và viên tròn lại.', 10);
INSERT INTO public.recipe_steps VALUES (4120, '2025-11-20 17:12:02.632513', '2025-11-20 17:12:02.632513', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 642, 6, 'Bọc màng bọc thực phẩm để bột nghỉ 30 phút.', 10);
INSERT INTO public.recipe_steps VALUES (4121, '2025-11-20 17:12:02.633592', '2025-11-20 17:12:02.633592', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 642, 1, 'Làm vỏ bánh:', 10);
INSERT INTO public.recipe_steps VALUES (4122, '2025-11-20 17:12:02.635179', '2025-11-20 17:12:02.635179', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 642, 11, 'Nặn và hấp bánh:', 10);
INSERT INTO public.recipe_steps VALUES (4123, '2025-11-20 17:12:02.636781', '2025-11-20 17:12:02.636781', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 642, 3, 'Cho nghệ đã hấp vào cối giã nhuyễn. Sau đó, thêm chút nước sôi, dùng rây để lọc lấy nước cốt.', 10);
INSERT INTO public.recipe_steps VALUES (4124, '2025-11-20 17:12:03.023774', '2025-11-20 17:12:03.023774', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 643, 9, 'Nếu muốn thêm nho khô thì bước cuối cùng là trộn 50g nho khô. Có thể trang trí nho khô trên mặt bánh tùy ý.', 10);
INSERT INTO public.recipe_steps VALUES (4125, '2025-11-20 17:12:03.024835', '2025-11-20 17:12:03.024835', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 643, 10, 'Đổ hỗn hợp bột vào khuôn. Thả nhẹ và đều khuôn xuống mặt phẳng 2-3 lần để vỡ các lỗ khí lớn trong lòng bánh.', 10);
INSERT INTO public.recipe_steps VALUES (4126, '2025-11-20 17:12:03.026424', '2025-11-20 17:12:03.026424', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 643, 11, 'Cách nướng:', 10);
INSERT INTO public.recipe_steps VALUES (4127, '2025-11-20 17:12:03.028071', '2025-11-20 17:12:03.028071', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 643, 6, 'Trộn một nửa bột vào âu bơ ở trên. Không trộn quá lâu, chỉ cần bột và hỗn hợp bơ đồng nhất khoảng 70% là được.', 10);
INSERT INTO public.recipe_steps VALUES (4128, '2025-11-20 17:12:03.028587', '2025-11-20 17:12:03.028587', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 643, 2, 'Cho 110 gram đường vào đánh cùng bơ. Nên chia làm 3 lần cho để đường có quyện đều vào bơ nhất. Tiếp tục trộn đều cho đến khi hỗn hợp bơ đường chuyển sang màu sáng, bông nhẹ.', 10);
INSERT INTO public.recipe_steps VALUES (4129, '2025-11-20 17:12:03.030119', '2025-11-20 17:12:03.030119', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 643, 8, 'Lại tiếp tục trộn nốt lượng bột, sau đó là nốt lượng sữa còn lại vào.', 10);
INSERT INTO public.recipe_steps VALUES (4130, '2025-11-20 17:12:03.032125', '2025-11-20 17:12:03.032125', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 643, 14, 'Sau 20 phút mở lò, dùng rao rạch một đường thẳng lên mặt bánh (cách mỗi đầu bánh tầm 3cm)', 10);
INSERT INTO public.recipe_steps VALUES (4131, '2025-11-20 17:12:03.033127', '2025-11-20 17:12:03.033127', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 643, 3, 'Cho tất cả lượng trứng vào bơ đã đánh bông. Chia làm 2 lần cho. Vừa cho vừa khuấy trộn nhẹ.', 10);
INSERT INTO public.recipe_steps VALUES (4137, '2025-11-20 17:12:03.040971', '2025-11-20 17:12:03.040971', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 643, 13, 'Sau khi đổ hỗn hợp bột vào khuôn sẽ nướng 20 phút đầu ở nhiệt độ 160 độ C', 10);
INSERT INTO public.recipe_steps VALUES (4138, '2025-11-20 17:12:03.042538', '2025-11-20 17:12:03.042538', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 643, 15, 'Phết nhẹ một chút bơ lạt lên đường rạch bánh vừa làm. Thao tác này làm mặt bánh vỡ ra nhanh chóng, giúp bánh thoát được hơi ẩm để không bị co lại.', 10);
INSERT INTO public.recipe_steps VALUES (4139, '2025-11-20 17:12:03.045058', '2025-11-20 17:12:03.045058', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 643, 1, 'Trước khi làm, chúng ta để 175g bơ ở nhiệt độ phòng đến lúc ấn vào bơ thấy mềm tay (bơ không cứng quá hoặc không chảy thành dạng lỏng). Sau đó cho toàn bộ bơ vào tô sạch khô, cho muối vào và dùng phới lồng đánh nhẹ cho đến khi bơ mềm ra.', 10);
INSERT INTO public.recipe_steps VALUES (4140, '2025-11-20 17:12:03.336652', '2025-11-20 17:12:03.336652', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 644, 8, 'Trình bày: Cho bánh canh ra bát, trên xếp thịt giò heo, múc nước lèo vào, cho thêm chút hành lá, hành phi và chút tiêu.', 10);
INSERT INTO public.recipe_steps VALUES (4141, '2025-11-20 17:12:03.338467', '2025-11-20 17:12:03.338467', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 644, 2, 'Giò heo chà muối rửa sạch, dùng dây nylon hoặc dây lạt buộc chặt, chần qua nước sôi', 10);
INSERT INTO public.recipe_steps VALUES (4142, '2025-11-20 17:12:03.340031', '2025-11-20 17:12:03.340031', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 644, 6, 'Bánh canh trụng qua nước sôi, cắt ngắn vừa ăn', 10);
INSERT INTO public.recipe_steps VALUES (4143, '2025-11-20 17:12:03.341628', '2025-11-20 17:12:03.341628', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 644, 7, 'Thịt giò heo xắt lát', 10);
INSERT INTO public.recipe_steps VALUES (4144, '2025-11-20 17:12:03.343215', '2025-11-20 17:12:03.343215', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 644, 5, 'Nấm rơm xào sơ với chút tỏi, cho vào nồi nước lèo. Giò heo chín vớt ra. Nêm vào nồi nước lèo: tiêu, muối, đường phèn, bột ngọt cho vừa ăn. Tiếp đó, cho hành tây và hành phi vào.', 10);
INSERT INTO public.recipe_steps VALUES (4145, '2025-11-20 17:12:03.34481', '2025-11-20 17:12:03.34481', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 644, 4, 'Nấu 5 lít nước cho đến khi hơi lăn tăn thì cho xương heo và giò heo vào. Để lửa trung bình, không đậy nắp và vớt bọt thường xuyên.', 10);
INSERT INTO public.recipe_steps VALUES (4146, '2025-11-20 17:12:03.346409', '2025-11-20 17:12:03.346409', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 644, 1, 'Xương heo chà muối, rửa sạch, chần qua nước sôi', 10);
INSERT INTO public.recipe_steps VALUES (4147, '2025-11-20 17:12:03.348504', '2025-11-20 17:12:03.348504', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 644, 3, 'Tỏi băm nhuyễn. Hành tây xắt khoanh mỏng. Hành lá thái nhuyễn. Nấm rơm gọt sạch chân, ngâm nước lạnh pha chút bột năng 15 phút, vớt ráo.', 10);
INSERT INTO public.recipe_steps VALUES (4148, '2025-11-20 17:12:03.561179', '2025-11-20 17:12:03.561179', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 645, 2, 'Ướp nước mắm, tiêu, mì chính', 10);
INSERT INTO public.recipe_steps VALUES (4149, '2025-11-20 17:12:03.562787', '2025-11-20 17:12:03.562787', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 645, 5, 'Dọc mùng tước bỏ vỏ, bóp muối.', 10);
INSERT INTO public.recipe_steps VALUES (4150, '2025-11-20 17:12:03.564947', '2025-11-20 17:12:03.564947', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 645, 4, 'Me đun lọc nước', 10);
INSERT INTO public.recipe_steps VALUES (4151, '2025-11-20 17:12:03.567729', '2025-11-20 17:12:03.567729', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 645, 3, 'Cà chua phi thơm cùng với hành', 10);
INSERT INTO public.recipe_steps VALUES (4152, '2025-11-20 17:12:03.569867', '2025-11-20 17:12:03.569867', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 645, 6, 'Đầu cá đun nước dùng trong, thả cà chua vào đun sôi, nêm gia vị, cho me vào, sau đó cho cá, đun sôi lên cùng với dọc mùng.', 10);
INSERT INTO public.recipe_steps VALUES (4153, '2025-11-20 17:12:03.572026', '2025-11-20 17:12:03.572026', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 645, 7, 'Cuối cùng cho rau ngổ, mùi tàu, húng chó, ăn nóng.', 10);
INSERT INTO public.recipe_steps VALUES (4154, '2025-11-20 17:12:03.573653', '2025-11-20 17:12:03.573653', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 645, 1, 'Cá sơ chế sạch, lọc lấy thái mỏng 4cm.', 10);
INSERT INTO public.recipe_steps VALUES (4155, '2025-11-20 17:12:03.777853', '2025-11-20 17:12:03.777853', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 646, 6, 'Thành phẩm: Cá màu nâu đỏ đẹp mắt, thịt cá săn chắc, dai dai, vị mặn ngọt cay quyện lại đậm vị hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (4156, '2025-11-20 17:12:03.779441', '2025-11-20 17:12:03.779441', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 646, 5, 'Kho lửa lần 2: Bật bếp kho cá lửa liu riu cho tới khi nước kho sánh keo lại, cá săn chắc đậm vị là được. Rắc thêm hạt tiêu, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (4157, '2025-11-20 17:12:03.781064', '2025-11-20 17:12:03.781064', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 646, 2, 'Chiên sơ: Cho cá vào chiên sơ các mặt.', 10);
INSERT INTO public.recipe_steps VALUES (4158, '2025-11-20 17:12:03.782761', '2025-11-20 17:12:03.782761', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 646, 3, 'Ướp cá: Lót dưới đáy nồi 1 lớp gừng lá chè xanh, gừng thái lát rồi lần lượt xếp các khúc cá lên trên. Ướp cá với: 3 thìa canh nước mắm, 1/2 thìa canh muối (bột canh), 1 thìa cà phê hạt nêm, 1 thìa cà phê hạt tiêu, thêm hành tăm đập dập, ớt. Ướp trong 30 phút cho ngấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (4159, '2025-11-20 17:12:03.784364', '2025-11-20 17:12:03.784364', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 646, 1, 'Sơ chế: Cá làm sạch, bỏ ruột, cắt khúc vừa ăn, rửa sạch, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (4160, '2025-11-20 17:12:03.785968', '2025-11-20 17:12:03.785968', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 646, 4, 'Kho lửa lần 1: Thêm nước nóng xâm xấp và kho lửa lớn trong 5 phút. Sau đó, cho 4-5 thìa canh mật mía vào, hạ nhỏ lửa và kho nhỏ lửa 30 phút, tắt bếp, để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (4161, '2025-11-20 17:12:04.275919', '2025-11-20 17:12:04.275919', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 647, 1, 'Bưởi móc ruột, tạo hoa văn. Tách bưởi ra từng múi, cắt lát mỏng. Thịt heo đem luộc, thái mỏng. Tôm luộc (bỏ 1 ít vỏ chanh vào), bóc vỏ. Mực xấy cắt sợi nhỏ, đem chiên sơ. Mè trắng rang vàng. Ớt bằm và thái sợi 1 ít dùng để trang trí. Tỏi băm nhuyễn. Chanh vắt lấy nước cốt. Rau răm thái nhỏ', 10);
INSERT INTO public.recipe_steps VALUES (4162, '2025-11-20 17:12:04.277554', '2025-11-20 17:12:04.277554', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 647, 3, 'Trộn gỏi: Cho bưởi đã tách tép nhỏ vào tô + tôm + thịt ba rọi + rau răm. Tiếp theo, đổ nước trộn gỏi vào, nếm vừa ăn rồi cho gỏi vào trái bưởi đã tạo hoa văn. Rắc mè rang + cho mực đã xé nhỏ lên mặt.', 10);
INSERT INTO public.recipe_steps VALUES (4163, '2025-11-20 17:12:04.278616', '2025-11-20 17:12:04.278616', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 647, 4, 'Món này ăn kèm bánh phồng tôm và có thêm nước mắm.', 10);
INSERT INTO public.recipe_steps VALUES (4164, '2025-11-20 17:12:04.280213', '2025-11-20 17:12:04.280213', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 647, 2, 'Làm nước trộn gỏi: Chanh vắt nước cốt + 3 muỗng đường + 1 muỗng muối + 1 muỗng tỏi băm + 1 muỗng ớt bằm + 3 muỗng nước mắm ngon trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (4165, '2025-11-20 17:12:04.435729', '2025-11-20 17:12:04.435729', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 648, 4, 'Trộn tất cả hỗn hợp tôm khô, vả, rau răm cùng chút nước mắm, hạt tiêu, bột nêm... Sau đó rắc hạt mè và bày tôm tươi lên trên cho đẹp mắt.', 10);
INSERT INTO public.recipe_steps VALUES (4166, '2025-11-20 17:12:04.436775', '2025-11-20 17:12:04.436775', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 648, 1, 'Vả chọn mua loại bánh tẻ đem luộc chín. Gọt lớp vỏ ngoài rồi thái mỏng theo chiều dọc của thân quả.', 10);
INSERT INTO public.recipe_steps VALUES (4167, '2025-11-20 17:12:04.438341', '2025-11-20 17:12:04.438341', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 648, 2, 'Tôm khô thái hạt lựu, tôm tươi luộc chín, bóc vỏ và chỉ đen để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (4169, '2025-11-20 17:12:04.674286', '2025-11-20 17:12:04.674286', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 649, 2, 'Đun sôi nồi nước thả vào một miếng gừng đập dập, một thìa canh dấm, 1 thìa canh rượu, 1 thìa cà phê muối... thả lòng vào trần qua cho hết mùi hôi. Rồi rửa lại bằng một lần nước nữa, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (4170, '2025-11-20 17:12:04.675879', '2025-11-20 17:12:04.675879', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 649, 8, 'Đun đến khi các nguyên liệu chín mềm, vớt bỏ phần riềng và sả, rồi đổ nước cốt dừa vào (không cho nước cốt dừa ngay từ đầu).', 10);
INSERT INTO public.recipe_steps VALUES (4171, '2025-11-20 17:12:04.677512', '2025-11-20 17:12:04.677512', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 649, 9, 'Nêm nếm lại gia vị cho vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (4172, '2025-11-20 17:12:04.679712', '2025-11-20 17:12:04.679712', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 649, 1, 'Lòng bóp qua với bột mỳ, lộn trong lộn ngoài, rửa lại thật sạch.', 10);
INSERT INTO public.recipe_steps VALUES (4173, '2025-11-20 17:12:04.681326', '2025-11-20 17:12:04.681326', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 649, 6, 'Đổ nước dừa ngập lòng, không có hoặc không thích nước dừa tươi thì thay thế bằng nước trắng.', 10);
INSERT INTO public.recipe_steps VALUES (4174, '2025-11-20 17:12:04.682398', '2025-11-20 17:12:04.682398', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 649, 5, 'Cho dầu ăn vào nồi, phi thơm chút tỏi, đổ phần lòng đã ướp gia vị vào xào cho săn.', 10);
INSERT INTO public.recipe_steps VALUES (4175, '2025-11-20 17:12:04.684001', '2025-11-20 17:12:04.684001', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 649, 7, 'Đun sôi nồi phá lấu, sau đó hạ nhỏ lửa đun liu riu, hớt bọt.', 10);
INSERT INTO public.recipe_steps VALUES (4176, '2025-11-20 17:12:04.685071', '2025-11-20 17:12:04.685071', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 649, 3, 'Cho lòng ướp cùng 1 thìa canh ớt bột Hàn Quốc (không có bỏ qua), 1 thìa cà phê ngũ vị hương, 1 thìa cà phê bột gia vị bò kho, 1 thìa canh dầu diều, 1 thìa cà phê bột nghệ, 1 thìa cà phê bột nêm, 1 thìa cà phê bột canh, 1/2 thìa cà phê hạt tiêu, tỏi đập dập băm nhỏ, hành củ đập dập băm nhỏ, sả đập dập cắt khúc, riềng thái lát mỏng (ớt hoặc đường nếu muốn), 1 thìa canh ăn phở.', 10);
INSERT INTO public.recipe_steps VALUES (4177, '2025-11-20 17:12:04.686683', '2025-11-20 17:12:04.686683', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 649, 4, 'Trộn thật đều các nguyên liệu với nhau, để ngấm trong vòng 1 giờ.', 10);
INSERT INTO public.recipe_steps VALUES (4178, '2025-11-20 17:12:04.938863', '2025-11-20 17:12:04.938863', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 650, 4, 'Trình bày và thưởng thức: Múc chẻo ra bát, ăn cùng xôi hoặc để chấm chuối xanh, rau sống, măng luộc đều rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (4179, '2025-11-20 17:12:04.939897', '2025-11-20 17:12:04.939897', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 650, 1, 'Lạc (đậu phộng) rang trên lửa nhỏ cho tới khi vàng, giòn thơm. Bọc lạc vào giấy báo để tạo độ giòn. Chia đôi lạc (một nửa lạc xoa, bỏ vỏ lụa, nửa còn lại giữ nguyên). Cho tất cả lạc vào cối giã nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (4180, '2025-11-20 17:12:04.941488', '2025-11-20 17:12:04.941488', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 650, 5, 'Yêu cầu thành phẩm: Chẻo lạc sánh vàng, béo bùi, vị mặn - ngọt đậm đà, dậy mùi thơm của sả.', 10);
INSERT INTO public.recipe_steps VALUES (4181, '2025-11-20 17:12:04.94413', '2025-11-20 17:12:04.94413', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 650, 2, 'Phi thơm sả, ớt, gừng (đã băm nhuyễn), cho lạc đã giã nhuyễn vào nồi, thêm nước hầm xương (hoặc nước lọc) gần xâm xấp mặt lạc. Nêm nếm gia vị: 8 thìa canh mật mía, 3 thìa canh nước mắm, 1 thìa canh mắm tôm, 1 thìa cà phê muối. Bạn có thể điều chỉnh mặn ngọt theo khẩu vị mỗi gia đình.', 10);
INSERT INTO public.recipe_steps VALUES (4182, '2025-11-20 17:12:04.945381', '2025-11-20 17:12:04.945381', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 650, 3, 'Đun lửa liu riu cho tới khi chẻo trở thành hỗn hợp sền sệt, sóng sánh là được. Thêm ớt nếu bạn thích ăn cay.', 10);
INSERT INTO public.recipe_steps VALUES (4183, '2025-11-20 17:12:05.086446', '2025-11-20 17:12:05.086446', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 651, 2, 'Làm nhân bánh:Thịt băm ướp chút mắm, muối, hạt nêm, hạt tiêu. Phi thơm hành, cho thịt vào xào săn. Sau đó cho tôm đồng (đã cắt râu, rửa sạch, để ráo) vào xào. Khi tôm khô ráo, thêm chút dầu điều, nêm nếm lại mắm muối, đường theo khẩu vị, thêm hạt tiêu, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (4184, '2025-11-20 17:12:05.087498', '2025-11-20 17:12:05.087498', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 651, 5, 'Luộc bánh:Đun sôi nồi nước, thêm 1 thìa dầu ăn cho bánh không dính nhau. Cho bánh vào luộc. Khi bánh nổi lên và chuyển màu trắng trong thì vớt ra cho vào bát nước sôi để nguội để không bị dính, vớt ra.', 10);
INSERT INTO public.recipe_steps VALUES (4185, '2025-11-20 17:12:05.089158', '2025-11-20 17:12:05.089158', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 651, 8, 'Yêu cầu thành phẩm: Vỏ bánh bèo dẻo dai, trong veo, nhân tôm thịt thơm ngọt, quyện với hành phi giòn thơm, rau sống tươi mát làm nên món ăn vặt hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (4186, '2025-11-20 17:12:05.090202', '2025-11-20 17:12:05.090202', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 651, 7, 'Trình bày và thưởng thức:Chia bánh bèo ra các bát, thêm hành phi, rau mùi, rau húng, ớt chưng (nếu thích) và rưới nước mắm chua ngọt ngập và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (4187, '2025-11-20 17:12:05.091258', '2025-11-20 17:12:05.091258', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 651, 4, 'Thêm tôm, thịt băm đã xào vào nửa vỏ bánh, gấp đôi và miết mép để tạo hình bán nguyệt.', 10);
INSERT INTO public.recipe_steps VALUES (4188, '2025-11-20 17:12:05.092879', '2025-11-20 17:12:05.092879', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 651, 1, 'Làm vỏ bánh:Chia bột ra 2 phần: Lấy trước 250 grams bột năng vào tô, thêm 1/2 muỗng canh muối, 1 muỗng canh dầu ăn trộn đều. Một tay rót từ từ nước nóng vào, tay còn lại dùng đũa hoặc phới khuấy đều bột và nước cho tan. Sau đó, thêm 150 grams bột năng còn lại vào, chờ nguội chút, đeo găng tay và nhào bột kỹ cho tới khi mịn dẻo, không dính tay. Bọc màng bọc thực phẩm để bột nghỉ 30 phút.', 10);
INSERT INTO public.recipe_steps VALUES (4189, '2025-11-20 17:12:05.094475', '2025-11-20 17:12:05.094475', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 651, 3, 'Nặn bánh:bột sau khi ủ, chia vê dài và chia nhỏ các khối bằng nhau. Mỗi phần thì vê tròn như hình cầu 5-6 cm, rồi ấn dẹp hoặc cán mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (4190, '2025-11-20 17:12:05.095538', '2025-11-20 17:12:05.095538', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 651, 6, 'Nước chấm(nêm nếm theo khẩu vị): Cho 200ml nước vào nồi, thêm 5 muỗng canh nước mắm 30 độ đạm, 3 muỗng canh đường, nấu và khuấy tan đường. Nếu dùng giấm thì bạn cho luôn vào lúc này, nếu dùng nước cốt chanh thì để nguội bớt cho thêm nước cốt chanh để không bị đắng. Thêm ớt băm nếu ăn được cay.', 10);
INSERT INTO public.recipe_steps VALUES (4191, '2025-11-20 17:12:05.271953', '2025-11-20 17:12:05.271953', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 652, 4, 'Múc nước lá tía tô vào cốc, thêm chút đá và thưởng thức như nước uống thanh nhiệt vào những ngày nắng nóng. Phần còn lại thì cho vào chai/hũ thủy tinh cho vào ngăn mát tủ lạnh bảo quản và dùng dần.', 10);
INSERT INTO public.recipe_steps VALUES (4192, '2025-11-20 17:12:05.274083', '2025-11-20 17:12:05.274083', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 652, 2, 'Đun sôi nồi nước 2 - 2,5 lít nước, thêm 1/2 thìa cà phê muối tinh. Sau đó, cho lá tía tô vào, dùng đũa ấn chìm xuống. Luộc lá tía tô ở lừa vừa 2 - 3 phút rồi lọc qua rây lấy nước, bỏ bã đi.', 10);
INSERT INTO public.recipe_steps VALUES (4193, '2025-11-20 17:12:05.276243', '2025-11-20 17:12:05.276243', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 652, 3, 'Cho đường phèn (hoặc đường cát trắng tùy chọn) vào nước tía tô đã lọc, điều chỉnh vị ngọt theo khẩu vị cá nhân. Khuấy cho đường tan hoàn toàn. Để nguội thì cho nước cốt chanh (điều chỉnh vị chua theo sở thích). Lúc này nước sẽ chuyển màu sang đỏ hồng đẹp mắt.', 10);
INSERT INTO public.recipe_steps VALUES (4194, '2025-11-20 17:12:05.278369', '2025-11-20 17:12:05.278369', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 652, 1, 'Tía tô nhặt bỏ lá già, cuống cứng, ngâm nước muỗi loãng 10 phút. Sau đó, vớt ra, rửa sạch, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (4195, '2025-11-20 17:12:05.493863', '2025-11-20 17:12:05.493863', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 653, 3, 'Rau má nhặt bỏ lá già úa, ngâm nước muỗi loãng 30 phút, vớt ra rửa nhiều lần cho sạch, để ráo nước, cắt nhỏ cho dễ xay.', 10);
INSERT INTO public.recipe_steps VALUES (4196, '2025-11-20 17:12:05.495514', '2025-11-20 17:12:05.495514', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 653, 1, 'Đậu xanh rửa sạch, ngâm nước ấm hai giờ. Cho đậu vào nồi cùng 400 ml nước xâm xấp, thêm 100 gr đường phèn, 1/4 thìa cà phê muối đun lửa nhỏ, chú ý mở vung để không bị trào và hớt bỏ bọt.', 10);
INSERT INTO public.recipe_steps VALUES (4197, '2025-11-20 17:12:05.496591', '2025-11-20 17:12:05.496591', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 653, 4, 'Cho rau má cùng 1 lít nước lọc hoặc nước dừa tươi càng ngon vào máy xay mịn. Sau đó, lọc qua rây lấy nước cốt rau má, bỏ phần bã. Nếu xay nhiều, chưa dùng hết thì cho phần nước cốt rau má vào ngăn mát tủ lạnh.', 10);
INSERT INTO public.recipe_steps VALUES (4198, '2025-11-20 17:12:05.499396', '2025-11-20 17:12:05.499396', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 653, 6, 'Cho nước sốt đậu xanh vào cốc, thêm đá viên, rót nước cốt rau má, nước cốt dừa và khuấy tan thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (4199, '2025-11-20 17:12:05.501002', '2025-11-20 17:12:05.501002', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 653, 7, 'Yêu cầu thành phẩm: Rau má thanh mát quyện với đậu xanh bùi bùi, nước cốt dừa béo ngậy tạo nên ly đồ uống hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (4200, '2025-11-20 17:12:05.502619', '2025-11-20 17:12:05.502619', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 653, 5, 'Nước cốt dừa đóng lon có thể dùng trực tiếp hoặc nếu muốn sánh hơn thì cho nước cốt dừa vào nồi đun lửa nhỏ, thêm đường nếu muốn ngọt. Pha chút bột năng với nước cho tan và từ từ khuấy đều cho tới khi sánh là được.', 10);
INSERT INTO public.recipe_steps VALUES (4201, '2025-11-20 17:12:05.503627', '2025-11-20 17:12:05.503627', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 653, 2, 'Để đậu xanh nguội bớt, cho vào máy xay nhuyễn mịn, sánh sệt là được hỗn hợp sốt đậu xanh.', 10);
INSERT INTO public.recipe_steps VALUES (4202, '2025-11-20 17:12:05.627955', '2025-11-20 17:12:05.627955', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 654, 1, 'Sấu nhặt bỏ các quả bị thâm dập. Dùng dao cạo sạch vỏ, cạo tới đâu thì cho vào chậu nước muối loãng tới đó để không bị thâm. Sau đó, dùng dao nhỏ khía từng quả sấu đường tròn xoắn ốc và cũng cho vào nước muối loãng ngâm 30 phút.', 10);
INSERT INTO public.recipe_steps VALUES (4203, '2025-11-20 17:12:05.629548', '2025-11-20 17:12:05.629548', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 654, 4, 'Chuẩn bị hũ/lọ thủy tinh sạch, tráng qua nước sôi để nguội sau đó, cho sấu đã nguội vào. Rót nước đường gừng vào và ngâm 3 - 4 ngày là dùng được. Cho vào tủ lạnh dùng dần.', 10);
INSERT INTO public.recipe_steps VALUES (4204, '2025-11-20 17:12:05.632211', '2025-11-20 17:12:05.632211', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 654, 3, 'Đun sôi nồi nước, thêm 1/2 thìa cà phê muối, cho sấu vào chần 10-15 giây. Đảo đều khi thấy sấu chuyển từ màu xanh sang vàng thì vớt ra ngay.', 10);
INSERT INTO public.recipe_steps VALUES (4205, '2025-11-20 17:12:05.633844', '2025-11-20 17:12:05.633844', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 654, 2, 'Cho vào nồi 1 kg đường và 400 ml nước, vừa đun vừa khuấy đều cho đường không bén nồi và tan hẳn. Thêm 1/3 thìa cà phê muối tinh. Khi nước sôi lăn tăn thì cho gừng thái sợi hoặc đập dập vào rồi tắt bếp, để nguội hoàn toàn.', 10);
INSERT INTO public.recipe_steps VALUES (4206, '2025-11-20 17:12:06.044889', '2025-11-20 17:12:06.044889', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 655, 5, 'Hỗn hợp sôi nhẹ thì cho ống vani vào khuấy đều, để nguội hoàn toàn, lọc lại thêm một lần rồi cho vào chai thuỷ tinh hoặc nhựa để dùng dần. Bảo quản ngăn mát tủ lạnh. Dùng được trong khoảng 2-3 ngày.', 10);
INSERT INTO public.recipe_steps VALUES (4207, '2025-11-20 17:12:06.045946', '2025-11-20 17:12:06.045946', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 655, 4, 'Lá dứa rửa sạch, vò nhẹ cuộn gọn lại và cho vào luôn ở bước này để tạo mùi thơm thoảng.', 10);
INSERT INTO public.recipe_steps VALUES (4208, '2025-11-20 17:12:06.047553', '2025-11-20 17:12:06.047553', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 655, 1, 'Hạt sen khô sau khi ngâm một tiếng với nước ấm, cho lên xửng hấp chín mềm, cho ra ráo nguội.', 10);
INSERT INTO public.recipe_steps VALUES (4209, '2025-11-20 17:12:06.048669', '2025-11-20 17:12:06.048669', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 655, 3, 'Đổ ra lọc lần một rồi cho hỗn hợp vào nồi hoặc chảo dày chống dính. Vì hạt sen chứa tinh bột nhiều, nên nồi đế mỏng dễ bị bén lửa và khét.Thêm sữa đặc, muối, sữa tươi, đường phèn khuấy thật đều. Xong bật bếp đun nhỏ lửa, vừa nấu vừa khuấy đều tay để không bị lắng cặn.', 10);
INSERT INTO public.recipe_steps VALUES (4210, '2025-11-20 17:12:06.050314', '2025-11-20 17:12:06.050314', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 655, 2, 'Chia đôi phần nước lọc và hạt sen, xay làm hai mẻ bằng máy xay sinh tố. Mỗi lần xay khoảng ba phút. Việc chia nhỏ sẽ giúp giảm công suất xay cho máy.', 10);
INSERT INTO public.recipe_steps VALUES (4211, '2025-11-20 17:12:06.051386', '2025-11-20 17:12:06.051386', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 655, 6, 'Thành phẩm sữa hạt sen không quá ngọt, thơm, dậy mùi của sen, thanh trong, rất ngon mà còn rẻ nữa.', 10);
INSERT INTO public.recipe_steps VALUES (4212, '2025-11-20 17:12:06.213294', '2025-11-20 17:12:06.213294', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 656, 4, 'Sau 10-12 phút hạt sen chín, vớt ra để riêng cho nguội. Phần nước luộc hạt sen lọc lấy nước trong giữ lại, thêm đường phèn vào nấu cho tan làm nước chan chè.', 10);
INSERT INTO public.recipe_steps VALUES (4213, '2025-11-20 17:12:06.214896', '2025-11-20 17:12:06.214896', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 656, 6, 'Cho vào mỗi bát khoảng 6-7 quả nhãn lồng hạt sen, thêm vài hạt sen còn dư rồi múc nước đường nhẹ nhàng rưới lên bát chè. Thêm đá lạnh và rắc chút cơm gạo từ hoa sen (tùy chọn) để tăng hương vị và thêm phần bắt mắt cho món chè nhãn lồng hạt sen.', 10);
INSERT INTO public.recipe_steps VALUES (4214, '2025-11-20 17:12:06.216488', '2025-11-20 17:12:06.216488', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 656, 1, 'Chọn hạt sen tươi ngon: Hạt sen tươi đang vào vụ ngon và rẻ, chọn mua hạt sen bánh tẻ với các dấu hiệu: hạt tròn mẩy, da trắng vàng, ở giữa hơi nứt và nhú ra tâm sen. Đây là sen tươi ngon, lượng tinh bột đủ đầy nên khi nấu bùi bùi, giàu giá trị dinh dưỡng. Hạt sen đem bóc bỏ vỏ giấy (vỏ lụa), dùng xiên tre to thông tâm sen bỏ riêng ra, phần hạt sen rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (4228, '2025-11-20 17:12:06.765846', '2025-11-20 17:12:06.765846', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 659, 9, 'Pudding dâu
INSERT INTO public.recipe_steps VALUES (4215, '2025-11-20 17:12:06.217563', '2025-11-20 17:12:06.217563', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 656, 7, 'Yêu cầu thành phẩm:Từng trái nhãn mọng nước, bọc hạt sen bên trong bùi bùi, nước chè ngọt diụ, thanh mát, thoảng mùi thơm của hương sen. Đây là món ăn quý tộc thời trân giải khát ngày hè của người Hà Nội xưa.', 10);
INSERT INTO public.recipe_steps VALUES (4216, '2025-11-20 17:12:06.219644', '2025-11-20 17:12:06.219644', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 656, 5, 'Lồng hạt sen vào quả nhãn: Rửa sạch tay, lấy phần hạt sen lồng vào bên trong quả nhãn. Chú ý quay đầu hạt sen hơi nâu xuống dưới, để hạt sen vàng mơ trồi lên bề mặt cho đẹp. Làm lần lượt cho tới hết. Quả nhãn nào to lựa hạt sen to cho vào cùi, quả nhỏ cho hạt sen nhỏ để làm sao hạt sen khít trong cùi thịt nhãn. Sau khi xong nhẹ nhàng cho nhãn lồng hạt sen vào nồi nước đường chan chè, đun sôi trở lại tắt bếp vớt ra ngay để nhãn vẫn giữ độ giòn. Phần nước chè cũng lọc lại cho trong thanh, để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (4217, '2025-11-20 17:12:06.220717', '2025-11-20 17:12:06.220717', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 656, 3, 'Luộc hạt sen: Hạt sen cho vào nồi cùng 1 - 1,2 lít nước đun sôi, mở vung rồi hạ lửa, thỉnh thoảng hớt bỏ bọt.', 10);
INSERT INTO public.recipe_steps VALUES (4218, '2025-11-20 17:12:06.222316', '2025-11-20 17:12:06.222316', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 656, 2, 'Tách hạt lấy cùi nhãn: Chè nhãn lồng hạt sen nên chọn nhãn lồng tươi của Hưng Yên mới chuẩn vị vì nhiều cơm (thịt nhãn), ráo nước và miệng trái nhãn vừa độ, hạt nhãn khi lấy ra thay thế bằng hạt sen lồng vào thì vừa vặn nhất. Nhãn rửa sạch, bóc bỏ vỏ, dùng đầu nhọn dao nhỏ hoặc tăm nhọn khía quanh núm hạt để tách cùi bong ra hạt rồi nhẹ nhàng đẩy hạt ra ngoài. Chú ý giữ cùi nhãn không bị rách. Khâu này đòi hỏi sự tỉ mỉ, cầu  kỳ để giữ miệng hạt sen giữ nguyên khi lồng hạt sen vào cố định được. Sau đó tráng qua bằng nước lọc sạch để loại bỏ các bụi bẩn còn vương lại trên cùi nhãn nếu có.', 10);
INSERT INTO public.recipe_steps VALUES (4219, '2025-11-20 17:12:06.4083', '2025-11-20 17:12:06.4083', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 657, 1, 'Mận hậu chọn các quả to đều, nên chọn mận chín nhưng vỏ vẫn còn cứng để làm ô mai giữ được hình dạng và siro nấu có màu đỏ đẹp tự nhiên. Mận nhặt bỏ cuống, rửa sạch rồi ngâm nước muối loãng khoảng 30 phút. Sau đó, vớt ra cho ráo nước.
INSERT INTO public.recipe_steps VALUES (4220, '2025-11-20 17:12:06.540143', '2025-11-20 17:12:06.540143', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 658, 2, 'Nhặt bỏ lá già, cuống cứng rồi ngâm nước muối loãng vài phút, rửa sạch, cắt khúc để dễ cho vào nồi.', 10);
INSERT INTO public.recipe_steps VALUES (4221, '2025-11-20 17:12:06.541741', '2025-11-20 17:12:06.541741', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 658, 1, 'Tía tô có 2 loại (tía tô xanh và tía tô tím). Nên chọn mua loại có mặt sau lá màu tím đậm, khi nấu nước sẽ ra nhiều tinh dầu, lên màu đẹp hơn. Ngoài ra, chú ý chọn tía tô tươi mới, bề mặt trơn láng. Không mua tía tô bị dập nát, màu ngả vàng hoặc bị héo.', 10);
INSERT INTO public.recipe_steps VALUES (4222, '2025-11-20 17:12:06.543889', '2025-11-20 17:12:06.543889', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 658, 4, 'Vớt bỏ phần lá, lọc lấy phần nước cốt tía tô để nguội là được nước trà tía tô. Nếu làm nhiều trữ ngăn mát tủ lạnh dùng dần. Đơn giản nhất là pha thêm nước cốt chanh, chút đường phèn là có ngay ly tía tô giải nhiệt ngày hè. Ngoài ra, có thể kết hợp thêm các topping phong phú để biến tấu thành các loại trà như: trà tía tô kết hợp vải ngâm đường phèn, trà tía tô hạt sen, trà tía tô hạt chia...', 10);
INSERT INTO public.recipe_steps VALUES (4223, '2025-11-20 17:12:06.545471', '2025-11-20 17:12:06.545471', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 658, 5, 'Mùa hè, vải đang vào vụ chính nên nhiều và rẻ, nên làm vải ngâm đường phèn để quanh năm, dùng kết hợp được cho nhiều món trà giải nhiệt. 1 kg vải cắt cuống, rửa sạch rồi chần sơ nước sôi 1,5 - 2 phút, vớt ra ngâm vào thau nước đá. Khi nguội, vớt ra ráo nước rồi bóc vỏ, dùng kéo hoặc dao nhỏ mũi nhọn khứa quanh đầu hạt rồi gẩy hoặc gắp hạt ra ngoài. Ngâm thịt vải vào âu nước đá. Đun sôi 400 ml nước, cho 400 gr đường phèn cùng chút muối vào khuấy đều cho tan hết đường, để nguội hoàn toàn. Nước đường lạnh, sánh (độ ngọt cao) sẽ giúp vải ngâm giữ được độ giòn, không bị lên men. Cho thịt vải đã ráo nước vào lọ thủy tinh sạch, trút phần nước đường và đậy nắp cho vào ngăn mát tủ lạnh 2-3 ngày là dùng được.', 10);
INSERT INTO public.recipe_steps VALUES (4224, '2025-11-20 17:12:06.547187', '2025-11-20 17:12:06.547187', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 658, 7, 'Yêu cầu thành phẩm:Một ly trà tía tô, vải ngâm với màu đỏ bắt mắt, vị chua ngọt hài hòa, topping vải ngâm giòn giọt, thanh mát.', 10);
INSERT INTO public.recipe_steps VALUES (4225, '2025-11-20 17:12:06.549862', '2025-11-20 17:12:06.549862', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 658, 3, 'Cho 1,2 - 1,5 lít nước vào nồi, thêm 1/4 thìa cà phê muối tinh rồi bật bếp đun sôi. Khi nước sôi, cho lá tía tô vào, dùng đũa nhấn chìm xuống. Luộc lá tía tô ở lửa vừa trong 2 - 3 phút rồi tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (4226, '2025-11-20 17:12:06.551452', '2025-11-20 17:12:06.551452', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 658, 6, 'Pha trà tía tô, vải ngâm: Cho 150 ml nước cốt tía tô vào ly, thêm 40 ml nước vải ngâm, 5 ml nước cốt chanh, điều chỉnh lại vị chua ngọt theo khẩu vị cá nhân, thêm đá viên. Nếu thích thêm hạt sen luộc chín ngâm đường hoặc hạt chia, trân châu đều được. Trên cùng trang trí các miếng vải ngâm, lát chanh và lá bạc hà thêm phần bắt mắt.', 10);
INSERT INTO public.recipe_steps VALUES (4227, '2025-11-20 17:12:06.764785', '2025-11-20 17:12:06.764785', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 659, 8, 'Đánh nổi đặc kem sữa tươi. Trét kem lên mặt bánh, chồng bánh lên kem (thực hiện khoảng 4-5 lớp). Đặt bánh chocolate vào giữa 2 cái bánh lạt. Để lạnh trước khi ăn', 10);
INSERT INTO public.recipe_steps VALUES (4321, '2025-11-20 17:12:09.935554', '2025-11-20 17:12:09.935554', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 674, 1, 'Bổ đôi chanh dây theo chiều ngang, múc lấy phần ruột.', 10);
INSERT INTO public.recipe_steps VALUES (4229, '2025-11-20 17:12:06.767432', '2025-11-20 17:12:06.767432', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 659, 1, 'Nguyên liệu:
INSERT INTO public.recipe_steps VALUES (4230, '2025-11-20 17:12:06.768471', '2025-11-20 17:12:06.768471', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 659, 6, 'Cách làm:Tách lòng đỏ và lòng trắng trứng gà. Đánh lòng trắng trứng với 2/3 lượng đường cho nổi đặc. Đánh tan bơ với 1/3 lượng đường còn lại và lòng đỏ trứng. Cho bột mì, bột nổi và 1/2 ống va-ni vào trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (4231, '2025-11-20 17:12:06.770077', '2025-11-20 17:12:06.770077', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 659, 10, 'Cách làm:Dâu bỏ cuống, rửa rồi thái khoanh, dày 0,2 cm. Khuấy đều sữa tươi, kem sữa béo và bột gelatine, cho lên bếp nấu sôi, vặn lửa nhỏ rồi cho đường vào nấu tan. Tắy bếp, để hơi nguội, cho hương dâu vào.', 10);
INSERT INTO public.recipe_steps VALUES (4232, '2025-11-20 17:12:06.771688', '2025-11-20 17:12:06.771688', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 659, 2, 'Bánh kem xoài
INSERT INTO public.recipe_steps VALUES (4233, '2025-11-20 17:12:06.772737', '2025-11-20 17:12:06.772737', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 659, 11, 'Xếp từng khoanh dâu vào thành ly, rót hỗn hợp kem sữa vào ly, để thật nguội, đặt vào ngăn mát tủ lạnh.', 10);
INSERT INTO public.recipe_steps VALUES (4234, '2025-11-20 17:12:06.774329', '2025-11-20 17:12:06.774329', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 659, 4, 'Cho kem sữa tươi và nước cốt dừa vào máy đánh trứng, đánh thật nổi, cho nước gelatine vào trộn đều. Lót một lớp nilon xung quanh khuôn. Trút xoài xanh vào (khoảng 1/2 khuôn), cho hỗn hợp kem vào đầy khuôn. Đặt vào ngăn mát tủ lạnh. Khi dùng, lấy bánh ra khỏi khuôn, gỡ bỏ bao nilon lót.', 10);
INSERT INTO public.recipe_steps VALUES (4235, '2025-11-20 17:12:06.775413', '2025-11-20 17:12:06.775413', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 659, 3, 'Cách làm:Xoài gọt vỏ, bỏ hạt, lấy phần thịt. Chanh vắt lấy nước. Bột gelatine hòa tan với 1/2 bát nước, bắc lên bếp đun tan. Cho xoài và một thìa cà-phê nước cốt chanh vào máy xay nhuyễn mịn. Trộn với 2 thìa súp nước gelatine.', 10);
INSERT INTO public.recipe_steps VALUES (4236, '2025-11-20 17:12:06.776469', '2025-11-20 17:12:06.776469', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 659, 5, 'Bánh sôcôla nhân kem
INSERT INTO public.recipe_steps VALUES (4237, '2025-11-20 17:12:06.777523', '2025-11-20 17:12:06.777523', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 659, 7, 'Sau cùng, cho lòng trắng trứng đã đánh nổi và bột ca cao đã hòa tan với 2 thìa súp nước vào, trộn nhẹ tay. Trút hỗn hợp bột vào khuôn 30×15 cm đã thoa ít dầu ăn, lớp bột dày cỡ 1 cm rồi cho vào lò nướng khoảng 15 phút ở nhiệt độ 180°C. Khi bánh nguội, lấy ra, cắt miếng vuông, cạnh 5cm.', 10);
INSERT INTO public.recipe_steps VALUES (4238, '2025-11-20 17:12:07.065527', '2025-11-20 17:12:07.065527', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 660, 3, 'Làm trân châu: Cùi dừa non cắt hạt lựu nhỏ để làm nhân. Cho 200 gr bột năng vào tô lớn, thêm 30 gr đường, 1/2 thìa cà phê nước cốt chanh để trân châu được trong. Đun sôi 200 ml nước, rồi múc cho vào hỗn hợp bột, dùng muỗng trộn đều cho bột chín. Để nguội rồi đeo găng tay nhào bột cho tới khi thành khối mịn dẻo, không dính tay là được. Chia thành từng khối nhỏ vê tròn ấn dẹt, cho nhân dừa vào vê tròn.', 10);
INSERT INTO public.recipe_steps VALUES (4239, '2025-11-20 17:12:07.066612', '2025-11-20 17:12:07.066612', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 660, 1, 'Đỗ đen nhặt bỏ hạt lép, vo rửa sạch, cho vào nồi cùng 2 lít nước, 1/2 thìa cà phê muối và đun sôi, hớt bỏ bọt. Sau đó, hạ lửa nhỏ ninh trong 20-25 phút cho mềm. Vớt hạt đậu ra, ướp với 200 gr đường cho ngấm vị ngọt. Phần nước ninh đậu chắt ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (4240, '2025-11-20 17:12:07.069191', '2025-11-20 17:12:07.069191', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 660, 7, 'Yêu cầu thành phẩm: Hạt đậu mềm bùi, đượm vị ngọt kết hợp cùng trân châu nhân dừa mềm dẻo sần sật, thạch đen mát lành. Đây là món ăn giải nhiệt ngày hè truyền thống của Hà Nội.', 10);
INSERT INTO public.recipe_steps VALUES (4241, '2025-11-20 17:12:07.069191', '2025-11-20 17:12:07.069191', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 660, 2, 'Cho đậu đen đã ướp đường vào xào nhẹ tay trong vài phút, sau đó, cho phần nước chè đã chắt vào, đun sôi trở lại, hớt bỏ bọt và để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (4242, '2025-11-20 17:12:07.071846', '2025-11-20 17:12:07.071846', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 660, 4, 'Luộc trân châu để lâu vẫn mềm dẻo: Đun sôi nước, cho trân châu vào luộc 20 phút, tắt bếp đậy vung và tiếp tục ủ trong  20 phút là trân châu chín, trong, dai mà vẫn mềm dẻo. Sau đó, vớt ra tráng qua nước đun sôi để nguội, vớt ra bát trộn thêm 20 gr đường áo cho thấm ngọt (tùy thích).', 10);
INSERT INTO public.recipe_steps VALUES (4243, '2025-11-20 17:12:07.072858', '2025-11-20 17:12:07.072858', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 660, 5, 'Thạch đen cắt miếng vừa ăn, dừa nạo sợi để làm topping.', 10);
INSERT INTO public.recipe_steps VALUES (4244, '2025-11-20 17:12:07.073947', '2025-11-20 17:12:07.073947', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 660, 6, 'Cho đá đập nhỏ vào cốc, múc chè, cho trân châu, thạch đen, rắc thêm dừa nạo, rưới chút tinh dầu chuối và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (4245, '2025-11-20 17:12:07.470901', '2025-11-20 17:12:07.470901', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 661, 6, 'Cách làm trà đào cam sả:Sả rửa sạch, đập dập và cho vào cùng 50 ml nước, đun sôi để tinh dầu sả tiết ra, tắt bếp để nguội. Trà lọc hương đào ngâm với 50 ml nước nóng, bỏ túi lọc. Cam bổ đôi, cắt 1 lát trang trí, vắt lấy nước cốt. Cho vào bình nước cốt trà, nước cốt sả, nước cam cùng 80-100 ml nước đào ngâm, đường (điều chỉnh theo khẩu vị), đậy nắp lắc đều. Rót ra ly, thêm đá viên, trang trí kèm lát cam, nhánh sả thêm phần bắt mắt.', 10);
INSERT INTO public.recipe_steps VALUES (4246, '2025-11-20 17:12:07.471959', '2025-11-20 17:12:07.471959', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 661, 5, 'Lọ thủy tinh rửa sạch, tráng nước sôi tiệt trùng, để khô ráo. Sau đó, cho đào đã nguội, nước đường đã nguội hoàn toàn vào ngâm. Đậy nắp để vào ngăn mát tủ lạnh dùng quanh năm.', 10);
INSERT INTO public.recipe_steps VALUES (4247, '2025-11-20 17:12:07.473559', '2025-11-20 17:12:07.473559', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 661, 2, 'Cho đào vào âu ngâm với 500 gr đường (1/2 lượng đường) trong 6-8 tiếng. Việc này vừa giúp đào tiết nước thơm mùi đặc trưng, vừa làm thịt đào giòn, đượm vị ngọt ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (4322, '2025-11-20 17:12:09.937134', '2025-11-20 17:12:09.937134', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 674, 5, 'Để nguội hẳn, cho vào ngăn mát tủ lạnh. Dùng lạnh.', 10);
INSERT INTO public.recipe_steps VALUES (4248, '2025-11-20 17:12:07.474634', '2025-11-20 17:12:07.474634', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 661, 1, 'Dùng dao hoặc cái nạo (bí, mướp) gọt vỏ, cắt đào thành miếng ngâm vào nước muối loãng. Làm lần lượt cho tới hết. Sau đó, rửa sạch lại, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (4249, '2025-11-20 17:12:07.476238', '2025-11-20 17:12:07.476238', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 661, 3, 'Cho 500 gr còn lại vào nồi đế dày cùng 50 ml nước, để lửa vừa thắng màu hổ phách cho đẹp. Cho 1 lít nước vào đun sôi, khuấy đều cho tan hết đường đã thắng. Sau đó, cho trút phần đào đã ngâm cùng nước vào đun sôi khoảng 3-4 phút. Việc này giúp đào ngâm không bị nổi váng. Vớt ra để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (4250, '2025-11-20 17:12:07.477927', '2025-11-20 17:12:07.477927', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 661, 4, 'Phần nước đường và nước cốt đào để nguội. Vắt lấy nước cốt 1 quả chanh cho vào để tăng thêm hương vị.', 10);
INSERT INTO public.recipe_steps VALUES (4251, '2025-11-20 17:12:07.592803', '2025-11-20 17:12:07.592803', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 662, 4, 'Hũ/lọ thủy tinh rửa sạch, trụng nước sôi tiệt trùng, để ráo nước hoàn toàn. Cho vải vào, rồi trút phần nước đường đã làm mát vào, đậy nắp cho vào ngăn mát tủ lạnh 2-3 ngày là dùng được.', 10);
INSERT INTO public.recipe_steps VALUES (4252, '2025-11-20 17:12:07.594404', '2025-11-20 17:12:07.594404', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 662, 1, 'Vải cắt bỏ cuống, rửa sạch. Đun sôi nước, cho vải vào chần sơ trong 1,5 - 2 phút để thịt vải dịu vị chua khi ngâm và ngấm đường. Vớt quả vải ra ngâm vào thau nước đá. Khi nguội, đổ ra rổ cho ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (4253, '2025-11-20 17:12:07.595468', '2025-11-20 17:12:07.595468', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 662, 3, 'Bóc vỏ vải, dùng kéo hoặc dao nhỏ mũi nhọn nhẹ nhàng khứa sát quanh đầu hạt, rồi gẩy/hoặc gắp hạt ra ngoài. Cách làm này đảm bảo thịt vải vẫn nguyên quả đẹp mắt. Ngâm thịt vải vào bát có ướp đá. Làm lần lượt cho tới hết. Trước khi cho vào lọ ngâm đường thì đổ vải ra rổ cho ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (4254, '2025-11-20 17:12:07.597069', '2025-11-20 17:12:07.597069', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 662, 5, 'Yêu cầu thành phẩm: Thịt vải giữ nguyên hình dáng, giòn giọt mà không gắt, thanh mát. Từ vải ngâm, chế biến được nhiều món giải khát thơm ngon như trà vải truyền thống, trà mận vải, trà vải hoa đậu biếc, trà thạch vải.', 10);
INSERT INTO public.recipe_steps VALUES (4255, '2025-11-20 17:12:07.597595', '2025-11-20 17:12:07.597595', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 662, 2, 'Cho đường phèn cùng nước và 1/4 thìa cà phê muối vào nồi đun sôi, khuấy cho đường tan hẳn. Nấu trên lửa nhỏ trong khoảng 8 -10 phút cho nước đường hơi sánh thì tắt bếp, để nguội, cho vào ngăn mát tủ lạnh. Nước đường lạnh, sánh (độ ngọt cao) sẽ giúp ngâm vải giữ được độ giòn, không bị lên men.', 10);
INSERT INTO public.recipe_steps VALUES (4256, '2025-11-20 17:12:07.796033', '2025-11-20 17:12:07.796033', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 663, 2, 'Khi đun cho 1 nhúm muối, khi cháo đã nhừ đến sánh thì lúc đó xuống đường (lượng đường tuỳ theo mình ăn ngọt hay vừa phải, đảo đều và bắc xuống, lưu ý cho đường vào không được đun lâu sẽ bị lại gạo, để nguội cho vào tủ lạnh. Khi ăn được khoảng 4 - 5 ngày.', 10);
INSERT INTO public.recipe_steps VALUES (4257, '2025-11-20 17:12:07.798696', '2025-11-20 17:12:07.798696', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 663, 3, 'Khi ăn cho ra cốc, đổ sữa chua lên trên.', 10);
INSERT INTO public.recipe_steps VALUES (4258, '2025-11-20 17:12:07.800945', '2025-11-20 17:12:07.800945', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 663, 1, 'Gạo nếp cẩm vo thật sạch, ngâm 3 - 4h sau đó đổ cả gạo và nước vào xoong, cho ½ lon nước cốt dừa vào đun lửa vừa phải gần giống như cháo, dạng đặc, hết nước lại tiếp thêm và cho vài lá nếp vào.', 10);
INSERT INTO public.recipe_steps VALUES (4259, '2025-11-20 17:12:07.887358', '2025-11-20 17:12:07.887358', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 664, 3, 'Công dụng:Thức uống này có tác dụng nhuận trường, thúc đấy quá trình trao đổi chất, bài tiết chất độc trong cơ thể.', 10);
INSERT INTO public.recipe_steps VALUES (4260, '2025-11-20 17:12:07.888402', '2025-11-20 17:12:07.888402', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 664, 4, 'Yoghurt và rau cần
INSERT INTO public.recipe_steps VALUES (4261, '2025-11-20 17:12:07.890003', '2025-11-20 17:12:07.890003', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 664, 9, 'Công dụng:Loại nước này có tác dụng bồi dưỡng cơ thể, giảm huyết, bổ sung vitamin A và khoáng chất, chất xơ.', 10);
INSERT INTO public.recipe_steps VALUES (4262, '2025-11-20 17:12:07.89161', '2025-11-20 17:12:07.89161', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 664, 6, 'Công dụng:Yoghurt, cần chứa vitamin B1, B2, chất khoáng và chất xơ. Giúp giảm stress, căng thẳng.', 10);
INSERT INTO public.recipe_steps VALUES (4263, '2025-11-20 17:12:07.893249', '2025-11-20 17:12:07.893249', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 664, 8, 'Cách làm:Cà rốt bào vỏ, rửa sạch, thái thành thanh dài, ép lấy nước cốt. Cần tây lấy thân, tước bỏ xơ bên ngoài, rửa sạch, thái lát mỏng. Cho cần tây và nước cà-rốt vào máy xay ở tốc độ cao. Thêm mật ong và đá viên vào xay chung đến khi hỗn hợp thật mịn.', 10);
INSERT INTO public.recipe_steps VALUES (4264, '2025-11-20 17:12:07.894851', '2025-11-20 17:12:07.894851', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 664, 5, 'Cách làm:Rau cần bỏ lá sâu, rửa sạch. Cà chua rửa sạch, bổ đôi, cho vào máy xay nhuyễn cùng rau cần, lược lấy nước cốt, bỏ xác. Cho yoghurt vào ly, thêm nước rau ép. Tùy theo sở thích mà thêm đường, đá viên.', 10);
INSERT INTO public.recipe_steps VALUES (4265, '2025-11-20 17:12:07.896462', '2025-11-20 17:12:07.896462', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 664, 12, 'Công dụng:Loại sinh tố này giúp thanh mát cơ thể. Đu đủ chứa nhiều enzyme, rất tốt cho hệ tiêu hóa.', 10);
INSERT INTO public.recipe_steps VALUES (4266, '2025-11-20 17:12:07.898061', '2025-11-20 17:12:07.898061', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 664, 2, 'Cách làm:Bắp cải rửa sạch, thái sợi, cho vào máy xay ép lấy nước. Táo bỏ vỏ, cuống và hạt, thái miếng nhỏ. Dùng máy xay táo thật nhuyễn, thêm nước ép bắp cải, nước cốt chanh. Thêm vào một ít đường và đá viên, tùy theo sở thích.', 10);
INSERT INTO public.recipe_steps VALUES (4267, '2025-11-20 17:12:07.899684', '2025-11-20 17:12:07.899684', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 664, 10, 'Đu đủ và bắp cải tím
INSERT INTO public.recipe_steps VALUES (4268, '2025-11-20 17:12:07.901292', '2025-11-20 17:12:07.901292', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 664, 11, 'Cách làm:Đu đủ gọt bỏ vỏ, hạt, thái miếng nhỏ. Bắp cải tím rửa sạch trong nước muối, vẩy ráo, thái nhỏ. Cho đu đủ, bắp cải, sữa tươi vào máy xay nhuyễn. Nếu muốn ngọt hơn, bạn có thể cho thêm đường, thêm đá viên hay đá bào vào.', 10);
INSERT INTO public.recipe_steps VALUES (4269, '2025-11-20 17:12:07.902368', '2025-11-20 17:12:07.902368', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 664, 7, 'Cà rốt và cần tây
INSERT INTO public.recipe_steps VALUES (4270, '2025-11-20 17:12:07.903971', '2025-11-20 17:12:07.903971', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 664, 1, 'Bắp cải và táo
INSERT INTO public.recipe_steps VALUES (4271, '2025-11-20 17:12:08.112571', '2025-11-20 17:12:08.112571', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 665, 1, 'Đậu nành ngâm nước khoảng 8 - 10 giờ, rửa sạch, để ráo', 10);
INSERT INTO public.recipe_steps VALUES (4272, '2025-11-20 17:12:08.11428', '2025-11-20 17:12:08.11428', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 665, 5, 'Cho đậu vừa nấu vào túi vải nhồi và vắt lọc lấy phần nước', 10);
INSERT INTO public.recipe_steps VALUES (4273, '2025-11-20 17:12:08.115885', '2025-11-20 17:12:08.115885', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 665, 3, 'Đậu nành đã rửa sạch, xay từng ít một với lượng nước vừa đủ cho máy hoạt động được, xay nát cho đến khi hết lượng đậu và lượng nước', 10);
INSERT INTO public.recipe_steps VALUES (4274, '2025-11-20 17:12:08.117494', '2025-11-20 17:12:08.117494', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 665, 4, 'Cho đậu nành vừa xay lên bếp nấu cho đến khi sờ vào thấy nóng tay là được. Tắt bếp, để khoảng 15- 30 phút', 10);
INSERT INTO public.recipe_steps VALUES (4275, '2025-11-20 17:12:08.119615', '2025-11-20 17:12:08.119615', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 665, 2, 'Mè rửa sạch, để ráo. Lá dứa rửa sạch để ráo, cột lại thành bó', 10);
INSERT INTO public.recipe_steps VALUES (4276, '2025-11-20 17:12:08.121236', '2025-11-20 17:12:08.121236', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 665, 6, 'Cho sữa đậu nành vừa vắt vào nồi cùng với bó lá dứa, đun sữa vừa sôi, hạ nhỏ lửa cho sữa không bị trào ra ngoài. Nấu khoảng 20 phút thì tắt bếp, vớt bọt, bỏ xác lá dứa.', 10);
INSERT INTO public.recipe_steps VALUES (4277, '2025-11-20 17:12:08.124181', '2025-11-20 17:12:08.124181', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 665, 7, 'Có thể uống sữa nóng hoặc để nguội chiết vào chai đậy kín và bảo quản trong tủ lạnh. Tuỳ theo ý thích uống ngọt hay nhạt của mỗi người mà cho thêm đường nhiều hay ít.', 10);
INSERT INTO public.recipe_steps VALUES (4278, '2025-11-20 17:12:08.329825', '2025-11-20 17:12:08.329825', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 666, 1, 'Khoai môn chà rửa sạch rồi hấp chín, lột vỏ và cắt miếng nhỏ cho dễ xay (chừa lại vài khoanh để trang trí trên miệng ly). Cho nước cốt dừa vào nồi, khuấy trên lửa nhỏ cho nước dừa sôi và hơi sệt.', 10);
INSERT INTO public.recipe_steps VALUES (4279, '2025-11-20 17:12:08.330897', '2025-11-20 17:12:08.330897', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 666, 2, 'Cho khoai môi vào máy xay cùng với nước dừa, đường để thật nhuyễn rồi cho tiếp đá bào vào xay vụn.', 10);
INSERT INTO public.recipe_steps VALUES (4280, '2025-11-20 17:12:08.332495', '2025-11-20 17:12:08.332495', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 666, 3, 'Đổ sinh tố khoai môn ra ly rưới sữa đặc lên bề mặt, trang trí thêm ống hút và một miếng khoai môn ở miệng ly (hoặc có thể trang trí trên miệng ly một bông hoa lan tím).', 10);
INSERT INTO public.recipe_steps VALUES (4281, '2025-11-20 17:12:08.509025', '2025-11-20 17:12:08.509025', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 667, 2, 'Cho đỗ cùng 750 ml nước, thêm 1/2 thìa cà phê muối và nấu ở lửa nhỏ cho tới khi đậu mềm nát. Ngày xưa người Hà Nội dùng muôi (vá) đánh đậu lúc còn nóng cho tới khi quánh mềm rồi cho lên chảo sên bằng đường. Hiện nay, để đậu mịn hơn, bạn nên cho đậu vào máy xay cùng 150 - 200 ml nước cho nhuyễn. Sau đó, cho ra chảo, thêm 200 gr đường vào khuấy đảo liên tục (sên) ở lửa nhỏ cho tới khi đậu sánh đặc lại là được. Thêm 1 ống vani đảo đều cho dậy mùi thơm.', 10);
INSERT INTO public.recipe_steps VALUES (4282, '2025-11-20 17:12:08.510633', '2025-11-20 17:12:08.510633', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 667, 8, 'Yêu cầu thành phẩm: Đậu xanh mềm bùi, dậy mùi thơm tinh dầu chuối, trân châu dẻo sần sật, thạch đen mát lành. Đây là món ăn chơi quen thuộc của người Hà Nội xưa.', 10);
INSERT INTO public.recipe_steps VALUES (4283, '2025-11-20 17:12:08.511693', '2025-11-20 17:12:08.511693', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 667, 5, 'Thạch đen cắt miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (4284, '2025-11-20 17:12:08.512746', '2025-11-20 17:12:08.512746', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 667, 3, 'Luộc trân châu: Đun sôi nước, cho trân châu vào luộc 20 phút, tắt bếp đậy vung ủ tiếp 20 phút là trân châu chín, trong, dai mà vẫn mềm dẻo.', 10);
INSERT INTO public.recipe_steps VALUES (4285, '2025-11-20 17:12:08.513803', '2025-11-20 17:12:08.513803', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 667, 6, 'Dừa nạo sợi để làm topping phong phú.', 10);
INSERT INTO public.recipe_steps VALUES (4286, '2025-11-20 17:12:08.51488', '2025-11-20 17:12:08.51488', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 667, 1, 'Đỗ xanh rửa sạch, ngâm nước thêm 1/2 thìa cà phê muối cho đậu nở trong khoảng 3-4 tiếng sau đó rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (4287, '2025-11-20 17:12:08.516489', '2025-11-20 17:12:08.516489', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 667, 4, 'Vớt trân châu ra tráng qua nước đun sôi để nguội, vớt ra bát trộn thêm 2 thìa canh đường áo cho thấm ngọt (tùy thích).', 10);
INSERT INTO public.recipe_steps VALUES (4288, '2025-11-20 17:12:08.517552', '2025-11-20 17:12:08.517552', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 667, 7, 'Múc đá đập nhỏ vào cốc, múc chè đỗ xanh vào, thêm trân châu, thạch đen, rắc thêm dừa nạo, rưới chút tinh dầu chuối và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (4289, '2025-11-20 17:12:08.748278', '2025-11-20 17:12:08.748278', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 668, 3, 'Khi ăn, múc chè ra bát, cho vào tủ giữ lạnh hoặc dùng kèm với đá rất mát.', 10);
INSERT INTO public.recipe_steps VALUES (4290, '2025-11-20 17:12:08.749332', '2025-11-20 17:12:08.749332', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 668, 1, 'Nha đam gọt vỏ, thái hạt lựu, ngâm nước muối, vớt ráo. Ngâm mềm bo bo, phổ tai. Thái sợi phổ tai. Gọt vỏ củ sen, thái hạt lựu.', 10);
INSERT INTO public.recipe_steps VALUES (4291, '2025-11-20 17:12:08.750905', '2025-11-20 17:12:08.750905', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 668, 2, 'Cho củ sen, hạt sen, bo bo vào nồi nước, nấu mềm. Tiếp tục cho đường vào nấu tan, rồi cho nhãn nhục, táo đỏ, phổ tai, cuối cùng cho nha đam vào.', 10);
INSERT INTO public.recipe_steps VALUES (4292, '2025-11-20 17:12:08.927263', '2025-11-20 17:12:08.927263', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 669, 1, 'Trứng 4 quả + 120g đường đánh bông trắng. Sau đó cho 120g bột, dùng phới đánh nổi mịn đều. Cho hỗn hợp đã trộn vào 1/2 khuôn, cho vào nướng nhiệt độ 2500c nở đều phồng. Giảm 2000c. Khi được mang ra cắt làm 3 lớp.', 10);
INSERT INTO public.recipe_steps VALUES (4293, '2025-11-20 17:12:08.928834', '2025-11-20 17:12:08.928834', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 669, 3, 'Khi được bạt ta làm kem Topping: 150g kem Topping dùng máy đánh bông ( + 200g lần 2).', 10);
INSERT INTO public.recipe_steps VALUES (4294, '2025-11-20 17:12:08.929917', '2025-11-20 17:12:08.929917', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 669, 2, 'Chú ý: khi nướng phải để bạt chín hẳn. Nếu chưa chín mang ra bánh sẽ bị xẹp không có độ xốp của bánh. Cách thử độ chín của bánh: lấy 1 con dao thăm vào giữa bánh nếu không thấy dính tức là đã chín.', 10);
INSERT INTO public.recipe_steps VALUES (4295, '2025-11-20 17:12:08.931517', '2025-11-20 17:12:08.931517', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 669, 4, 'Dùng 2/3 cốc nước lọc cho đường và 1 chút rượu Rum đánh tan. Cho 1 lớp bạt, phết nước đường + rượu rum, phết kem Topping. Sau đó tiếp tục làm cho đến hết, phết 1 lớp kem Topping ngoài cùng, trang trí. Có thể trang trí hoa quả lên trên và các lớp của bánh thì thành bánh gato hoa quả', 10);
INSERT INTO public.recipe_steps VALUES (4433, '2025-11-20 17:12:16.24571', '2025-11-20 17:12:16.24571', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 696, 10, 'Sau 10 phút, mở nắp ra xả hơi rồi hấp thêm 8 phút nữa.', 10);
INSERT INTO public.recipe_steps VALUES (4296, '2025-11-20 17:12:09.189224', '2025-11-20 17:12:09.189224', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 670, 4, 'Cho đá viên vào ly, rót 100ml nước cốt trà, nước đường, nước cốt tắc, thêm tắc cắt lát vào lắc đều là đã có một ly trà tắc ngon như ngoài hiệu. Nếu thích thêm hương vị thì bạn thêm chút mật ong, tắc xí muội và trang trí nhánh nhỏ bạc hà.', 10);
INSERT INTO public.recipe_steps VALUES (4297, '2025-11-20 17:12:09.1914', '2025-11-20 17:12:09.1914', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 670, 3, 'Cho 1 chén nước và 100 gr đường cát vàng (hoặc đường cát trắng) vào nấu tan, để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (4298, '2025-11-20 17:12:09.193017', '2025-11-20 17:12:09.193017', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 670, 2, 'Tắc (quất) rửa sạch, ngâm vào nước đá (hoặc cho vào ngăn đá) một lúc, cắt đôi vắt lấy nước cốt, bỏ hạt. Việc ngâm nước đá trước khi vắt giúp tinh dầu ở vỏ không ra nhiều để hạn chế đắng. Lấy vài quả, cắt thành lát mỏng, bỏ hạt để trang trí.', 10);
INSERT INTO public.recipe_steps VALUES (4299, '2025-11-20 17:12:09.19468', '2025-11-20 17:12:09.19468', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 670, 1, 'Cho 2 gói trà túi lọc cùng 200 ml nước sôi vào ủ khoảng 9-10 phút. Sau đó, lọc lấy nước cốt trà.', 10);
INSERT INTO public.recipe_steps VALUES (4300, '2025-11-20 17:12:09.400067', '2025-11-20 17:12:09.400067', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 671, 6, 'Trường hợp bị nổi một lớp meo trắng trên mặt là do hũ không thật sạch hoặc bị vật lạ rơi vào. Khi ấy hớt bỏ lớp váng, đổ vào một thìa súp rượu đế. Khi lấy chanh ra dùng, nên lau thìa thật khô, không để thìa dính nước.', 10);
INSERT INTO public.recipe_steps VALUES (4301, '2025-11-20 17:12:09.402188', '2025-11-20 17:12:09.402188', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 671, 2, 'Pha phèn chua với 1 lít nước và 1 thìa súp muối hạt, đun sôi, thả chanh vào chần qua rồi vớt ra ngay. Phèn chua sẽ giúp chanh có màu trắng và vỏ chanh khi muối xong sẽ giòn, không bở.', 10);
INSERT INTO public.recipe_steps VALUES (4302, '2025-11-20 17:12:09.403251', '2025-11-20 17:12:09.403251', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 671, 1, 'Đặt chừng 10 quả chanh vào rá, dùng một rá nhỏ khác, (hoặc xòe tay đặt lên trên) xát nhẹ cho vỏ chanh ra bớt nước chua và dễ thấm.', 10);
INSERT INTO public.recipe_steps VALUES (4303, '2025-11-20 17:12:09.404825', '2025-11-20 17:12:09.404825', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 671, 4, 'Xếp chanh vào lọ thủy tinh sạch, nén một chiếc đĩa nhựa nhỏ lên trên để chanh khỏi nổi lên, đổ nước muối phủ ngập mặt chanh cách khoảng 2 cm. Dùng vải thưa làm nắp đậy tránh bụi rơi vào và hũ chanh vẫn thoáng khí. Phơi nắng cho đến khi thấy vỏ chanh trở màu trắng ngà, có thể đậy nắp kín. Khi phơi nhớ trở mặt lọ cho đều.', 10);
INSERT INTO public.recipe_steps VALUES (4304, '2025-11-20 17:12:09.406508', '2025-11-20 17:12:09.406508', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 671, 5, 'Chanh muối phơi nắng khoảng 1 tháng là dùng được, tuy nhiên để đến khoảng 3 tháng trở đi mới thật ngon.', 10);
INSERT INTO public.recipe_steps VALUES (4305, '2025-11-20 17:12:09.408129', '2025-11-20 17:12:09.408129', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 671, 3, 'Nấu 1 lít nước với phần muối còn lại (thả vài hạt cơm vào nước muối, nếu cơm chìm là còn nhạt, hạt cơm nổi lên thì mới đạt yêu cầu về độ mặn), lọc cho hết bọt đen, để nguội, lọc hết cặn muối.', 10);
INSERT INTO public.recipe_steps VALUES (4306, '2025-11-20 17:12:09.629296', '2025-11-20 17:12:09.629296', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 672, 4, 'Vỏ bưởi cắt sợi nhuyễn hoặc cắt hạt lựu rồi ngâm qua nước muối đậm đặc, nhồi bóp và xả kỹ bằng nước lạnh cho hết vị đắng và mặn. Nấu nước sôi với ít phèn chua, cho vỏ bưởi vào luộc, vớt ra xả sạch và vắt ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (4307, '2025-11-20 17:12:09.6309', '2025-11-20 17:12:09.6309', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 672, 6, 'Nấu chè: Đun sôi 3 lít nước, cho 500 g đường vào khuấy tan, cho lá dứa vào để làm tăng mùi hương, vớt lá dứa ra, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (4308, '2025-11-20 17:12:09.631981', '2025-11-20 17:12:09.631981', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 672, 1, 'Vỏ bưởi gọt bỏ lớp xanh, chỉ lấy phần vỏ xốp trắng bên trong', 10);
INSERT INTO public.recipe_steps VALUES (4309, '2025-11-20 17:12:09.633057', '2025-11-20 17:12:09.633057', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 672, 7, 'Khuấy tan 100 g bột năng với 1 chén nước rồi rót từ từ vào nồi nước đường. Bật bếp trở lại và khuấy đều tay trên lửa nhỏ cho bột trong và có độ sánh vừa.', 10);
INSERT INTO public.recipe_steps VALUES (4310, '2025-11-20 17:12:09.634116', '2025-11-20 17:12:09.634116', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 672, 8, 'Cho vỏ bưởi vào nồi, trộn đều lên rồi cho tiếp đậu xanh vào, khuấy nhẹ tay. Tắt bếp và cho tinh dầu bưởi vào, khuấy nhẹ.', 10);
INSERT INTO public.recipe_steps VALUES (4311, '2025-11-20 17:12:09.635209', '2025-11-20 17:12:09.635209', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 672, 5, 'Sên vỏ bưởi với đường: Trộn vỏ bưởi đã sơ chế với đường, rồi sên trên lửa nhỏ cho đến khi ráo đường. Rắc bột áo lên xốc đều cho miếng vỏ bưởi khô và rây bỏ bột thừa.', 10);
INSERT INTO public.recipe_steps VALUES (4312, '2025-11-20 17:12:09.637358', '2025-11-20 17:12:09.637358', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 672, 2, 'Đậu xanh ngâm qua đêm cho mềm, rồi hấp chín', 10);
INSERT INTO public.recipe_steps VALUES (4313, '2025-11-20 17:12:09.638452', '2025-11-20 17:12:09.638452', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 672, 3, 'Dừa nạo vắt với nước ấm lấy một chén nước cốt và một tô nước dão', 10);
INSERT INTO public.recipe_steps VALUES (4314, '2025-11-20 17:12:09.640063', '2025-11-20 17:12:09.640063', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 672, 9, 'Nấu nước cốt dừa: Nấu nước dão dừa với đường và một chút muối rồi cho bột gạo vào khuấy đều cho nước dừa hơi sánh đặc, sau cùng mới cho nước cốt dừa vào, khuấy đều và tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (4315, '2025-11-20 17:12:09.641241', '2025-11-20 17:12:09.641241', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 672, 10, 'Múc chè vào chén, chan một chút nước cốt dừa lên, rồi rắc đậu phộng rang. Dùng lạnh ngon hon.', 10);
INSERT INTO public.recipe_steps VALUES (4316, '2025-11-20 17:12:09.856688', '2025-11-20 17:12:09.856688', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 673, 3, 'Hộp nước cốt dừa đun lên, chuối cắt miếng vừa ăn. Cho 250g đường, sau đó cho tiếp nước dừa xay. Tiếp theo cho 2 lá thơm vào (lá thơm thắt cà vạt). Cho thêm một chút muối (nửa thìa cafe), nước sôi lên đổ chuối vào sau đó cho nửa bát con nước vào. Đun sôi tiếp khoảng 5 phút là xong.', 10);
INSERT INTO public.recipe_steps VALUES (4317, '2025-11-20 17:12:09.857933', '2025-11-20 17:12:09.857933', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 673, 2, 'Nước cốt dừa: Dừa xay lên rồi chắt lấy nước.', 10);
INSERT INTO public.recipe_steps VALUES (4318, '2025-11-20 17:12:09.860156', '2025-11-20 17:12:09.860156', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 673, 1, 'Chuối để nguyên cả vỏ cho vào luộc. Luộc nhiều nước, cho ít muối, vắt 1 quả chanh vào nước cho ra hết nhựa. Nước sôi thì vớt vỏ chanh ra, khi nước sôi thì không đậy vung. Đun chuối ít nhất là 1 giờ. Chuối được thì đổ ra sả nước lạnh cho nguội rồi bóc vỏ.', 10);
INSERT INTO public.recipe_steps VALUES (4319, '2025-11-20 17:12:09.932498', '2025-11-20 17:12:09.932498', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 674, 3, 'Cho nửa lượng chanh dây vào rau câu, khuấy đều.', 10);
INSERT INTO public.recipe_steps VALUES (4320, '2025-11-20 17:12:09.934114', '2025-11-20 17:12:09.934114', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 674, 4, 'Cho một lớp mỏng chanh dây vào khuôn, đổ rau câu vào gần đầy khuôn, cho phần chanh dây còn lại vào đầy khuôn.', 10);
INSERT INTO public.recipe_steps VALUES (4323, '2025-11-20 17:12:09.93874', '2025-11-20 17:12:09.93874', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 674, 2, 'Ngâm bột rau câu vào 1 lít nước trong 10 - 15 phút, nấu tan, cho đường vào khuấy trên lửa nhỏ. Đường tan, tắt bếp, để nguội bớt.', 10);
INSERT INTO public.recipe_steps VALUES (4324, '2025-11-20 17:12:10.100967', '2025-11-20 17:12:10.100967', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 675, 2, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (4325, '2025-11-20 17:12:10.102574', '2025-11-20 17:12:10.102574', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 675, 5, 'Cách làm:', 10);
INSERT INTO public.recipe_steps VALUES (4326, '2025-11-20 17:12:10.104271', '2025-11-20 17:12:10.104271', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 675, 6, 'Đào rửa sạch, tách hạt, xắt hạt lựu. Trộn đều đào với đường, nêm nước cốt chanh và rượu vang trắng, đảo đều cho ngấm, cho vào ngăn mát tủ lạnh, để khoảng 1 giờ. Hòa rượu vang với nước sôi để nguội rồi đổ vào âu đào, trộn đều và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (4327, '2025-11-20 17:12:10.106461', '2025-11-20 17:12:10.106461', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 675, 4, 'Đào dầm rượu vang
INSERT INTO public.recipe_steps VALUES (4328, '2025-11-20 17:12:10.108104', '2025-11-20 17:12:10.108104', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 675, 1, 'Dưa hấu trộn mật ong
INSERT INTO public.recipe_steps VALUES (4329, '2025-11-20 17:12:10.110239', '2025-11-20 17:12:10.110239', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 675, 3, 'Dưa hấu gọt vỏ, bỏ hạt, xắt hạt lựu (hoặc có thể miết nhuyễn tùy vào khẩu vị từng gia đình), trộn đều với ít muối tinh và mật ong. Cho vào tủ lạnh trước khi dùng.', 10);
INSERT INTO public.recipe_steps VALUES (4330, '2025-11-20 17:12:10.417453', '2025-11-20 17:12:10.417453', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 676, 3, 'Kem sữa tươi đánh nổi cứng, cho vào bao nylon để tạo bông kem, bảo quản lạnh.', 10);
INSERT INTO public.recipe_steps VALUES (4331, '2025-11-20 17:12:10.419053', '2025-11-20 17:12:10.419053', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 676, 4, 'Đun sôi nước, cho đường vào nấu tan + vani, quậy đều, để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (4332, '2025-11-20 17:12:10.420661', '2025-11-20 17:12:10.420661', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 676, 5, 'Xếp khoảng 8 viên thanh long (2 màu) vào bát, chan nước đường + đá đập nhuyễn + nước dừa sữa, tạo bông hoa bằng kem sữa trang trí lên trên.', 10);
INSERT INTO public.recipe_steps VALUES (4333, '2025-11-20 17:12:10.421722', '2025-11-20 17:12:10.421722', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 676, 6, 'Món này dùng lạnh.', 10);
INSERT INTO public.recipe_steps VALUES (4334, '2025-11-20 17:12:10.423287', '2025-11-20 17:12:10.423287', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 676, 1, 'Thanh long, rửa sạch, lột vỏ, dùng muỗng múc thành từng viên tròn.', 10);
INSERT INTO public.recipe_steps VALUES (4335, '2025-11-20 17:12:10.424869', '2025-11-20 17:12:10.424869', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 676, 2, 'Dừa khô vắt lấy nước cốt, pha chung với 30 ml kem sữa tươi, quậy đều, cho vào tủ lạnh, ngăn mát.', 10);
INSERT INTO public.recipe_steps VALUES (4336, '2025-11-20 17:12:10.745839', '2025-11-20 17:12:10.745839', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 677, 3, 'Khuấy rượu, đồ uống có ga, các lát chanh và cam cùng những loại hoa quả vừa chuẩn bị. Khuấy nhẹ nhàng để hoa quả không bị nát.', 10);
INSERT INTO public.recipe_steps VALUES (4337, '2025-11-20 17:12:10.747432', '2025-11-20 17:12:10.747432', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 677, 2, 'Vắt lấy nước cốt của những miếng còn lại vào một chiếc bình.', 10);
INSERT INTO public.recipe_steps VALUES (4338, '2025-11-20 17:12:10.748482', '2025-11-20 17:12:10.748482', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 677, 1, 'Cắt chanh và cam thành 4 miếng mỗi quả. Sau đó, cắt 2 miếng chanh và 2 miếng cam vừa xong thành những lát dày khoảng 2,5 cm.', 10);
INSERT INTO public.recipe_steps VALUES (4339, '2025-11-20 17:12:10.750081', '2025-11-20 17:12:10.750081', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 677, 4, 'Cuối cùng cho thêm đá nếu muốn uống lạnh hơn.', 10);
INSERT INTO public.recipe_steps VALUES (4340, '2025-11-20 17:12:10.970781', '2025-11-20 17:12:10.970781', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 678, 1, 'Ngô nếp non bào hoặc cắt vát, (không lấy mày) cho nước vào đun cùng lá nếp. Khi hạt ngô dừ, dẻo thì đổ đường, bột sắn dây hoà ra bát lấy nước.', 10);
INSERT INTO public.recipe_steps VALUES (4341, '2025-11-20 17:12:10.972353', '2025-11-20 17:12:10.972353', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 678, 2, 'Đun tiếp đến khi sôi thì xuống bột từ từ lấy độ sánh, đun nhỏ lửa một lúc đến khi trong thì bắc ra cho cốm tươi vào ăn kèm với dừa nạo, hoặc nước cốt dừa.', 10);
INSERT INTO public.recipe_steps VALUES (4342, '2025-11-20 17:12:11.411016', '2025-11-20 17:12:11.411016', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 679, 2, 'Kem sữa tươi để cho rã đông rồi đổ ra dùng máy đánh trứng đánh bông mịn lên. Sau đó cho hỗn hợp dừa vào trộn cho thật đều.', 10);
INSERT INTO public.recipe_steps VALUES (4343, '2025-11-20 17:12:11.41314', '2025-11-20 17:12:11.41314', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 679, 4, 'Cơm dừa bào mỏng cho vào chảo chiên vàng, để nguội, có thể vừa dùng để trang trí vừa ăn cùng kem rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (4344, '2025-11-20 17:12:11.414779', '2025-11-20 17:12:11.414779', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 679, 1, 'Cho cơm dừa đã xắt thành từng miếng nhỏ và nước dừa vào máy xay sinh tố xay cho nhuyễn, sau đó cho đường và sữa tươi vào.', 10);
INSERT INTO public.recipe_steps VALUES (4345, '2025-11-20 17:12:11.416476', '2025-11-20 17:12:11.416476', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 679, 3, 'Cho vào máy làm kem, đổ đá và muối hột xung quanh, khoảng nửa tiếng là được. Lấy kem ra cho vào khuôn, đặt vào tủ đông.', 10);
INSERT INTO public.recipe_steps VALUES (4346, '2025-11-20 17:12:11.540731', '2025-11-20 17:12:11.540731', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 680, 5, 'Phết hỗn hợp trên lên bạt gato và cuộn lại giống như hình khúc củi. Dùng dao cắt vát 2/3 "khúc củi" trên, dựng khúc ngắn lên khúc dài.', 10);
INSERT INTO public.recipe_steps VALUES (4347, '2025-11-20 17:12:11.542891', '2025-11-20 17:12:11.542891', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 680, 3, 'Cho kem tươi vào âu to, dùng máy đánh trứng đánh tan đến khi kem tươi bông lên, sánh lại (đánh khi lạnh sẽ dễ bông hơn).', 10);
INSERT INTO public.recipe_steps VALUES (4348, '2025-11-20 17:12:11.544479', '2025-11-20 17:12:11.544479', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 680, 4, 'Cho hỗn hợp vừa đun (để nguội) vào cùng với kem tươi đã đánh tan rồi dùng máy đánh trứng trộn hỗn hợp cho đều.', 10);
INSERT INTO public.recipe_steps VALUES (4349, '2025-11-20 17:12:11.546075', '2025-11-20 17:12:11.546075', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 680, 1, 'Bạt (vỏ) gato: Trứng và đường cho vào đánh bông. Bột rây mịn đổ vào hỗn hợp trên. Sau đó lấy phới trộn đều bằng tay, tạo thành thể đồng nhất, bột không vón. Đổ tất cả vào vào khuôn có lót giấy dưới đáy rồi cho vào lò nướng khoảng 180 - 200 độ C trong khoảng 30 phút.', 10);
INSERT INTO public.recipe_steps VALUES (4350, '2025-11-20 17:12:11.54715', '2025-11-20 17:12:11.54715', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 680, 6, 'Phết kem lên toàn bộ "khúc củi", dùng dĩa cào lên tạo thành rãnh xước tự nhiên như vỏ cây.', 10);
INSERT INTO public.recipe_steps VALUES (4351, '2025-11-20 17:12:11.548745', '2025-11-20 17:12:11.548745', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 680, 2, 'Đun chảy sữa tươi với chocolate đen. Đun nhỏ lửa, tán cho chocolate tan mịn (Luu ý: đun to lửa là chocolate bị vón cục).', 10);
INSERT INTO public.recipe_steps VALUES (4352, '2025-11-20 17:12:11.55089', '2025-11-20 17:12:11.55089', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 680, 7, 'Dùng đường xay (icing ) rắc lên trên tạo tuyết. Trang trí thêm bằng những loại kẹo hoặc quả cheri.', 10);
INSERT INTO public.recipe_steps VALUES (4353, '2025-11-20 17:12:11.73531', '2025-11-20 17:12:11.73531', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 681, 4, 'Để nguội bớt rồi rót hỗn hợp vào từng nửa vỏ cam đã vắt lúc đầu. Bạn nên để vỏ cam lên một cái khay hoặc khuôn để cố định, khi đổ thạch vào sẽ dễ dàng và an toàn hơn.', 10);
INSERT INTO public.recipe_steps VALUES (4354, '2025-11-20 17:12:11.736944', '2025-11-20 17:12:11.736944', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 681, 2, 'Ngâm bột gelatin trong nước khoảng 15 phút.', 10);
INSERT INTO public.recipe_steps VALUES (4355, '2025-11-20 17:12:11.739124', '2025-11-20 17:12:11.739124', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 681, 1, 'Bổ đôi quả cam. Dùng thìa nạo hết ruột và nước ra một cái bát to hoặc vắt nước cam bằng dụng cụ hỗ trợ, rồi tách hết các các xơ, múi còn lại bên trong, cố gắng giữ cho vỏ quả cam nguyên vẹn.', 10);
INSERT INTO public.recipe_steps VALUES (4356, '2025-11-20 17:12:11.74072', '2025-11-20 17:12:11.74072', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 681, 5, 'Để thạch nguội và đông lại rồi cho vào tủ lạnh, vài giờ sau là bạn có món thạch cam chính hiệu cả về hình dáng và mùi vị.', 10);
INSERT INTO public.recipe_steps VALUES (4357, '2025-11-20 17:12:11.742293', '2025-11-20 17:12:11.742293', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 681, 3, 'Cho nước cam vào nồi đun gần sôi, nếu thấy hơi ít nước bạn có thể cho thêm nước lọc, thêm đường hoặc mật ong nếu muốn ăn ngọt hơn. Sau đó cho chỗ nước gelatin vào nồi nước cam. Ngoáy đều cho tan hết. Đun sôi thì tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (4358, '2025-11-20 17:12:11.743905', '2025-11-20 17:12:11.743905', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 681, 6, 'Lấy cam ra khỏi tủ lạnh, dùng dao cắt thành miếng hình múi cau.', 10);
INSERT INTO public.recipe_steps VALUES (4359, '2025-11-20 17:12:12.083284', '2025-11-20 17:12:12.083284', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 682, 1, 'Đường kính, dầu ăn, nước cốt chanh trộn đều. Đổ bột mì, mứt nho khô vào trộn lẫn. Cho bột nở và tinh đường hương cam khuấy tan ra, cuối cùng cho bột cà rốt vào trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (4360, '2025-11-20 17:12:12.084895', '2025-11-20 17:12:12.084895', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 682, 2, 'Đổ hỗn hợp trên vào khuôn nướng (nên bôi 1 lớp dầu mỏng trước khi đổ bột vào khuôn) bày lê bổ theo chiều dọc dày khoảng 2 cm lên trên, cho vào lò nướng 190 - 200 độ C trong khoảng 40 - 50 phút.', 10);
INSERT INTO public.recipe_steps VALUES (4361, '2025-11-20 17:12:12.400898', '2025-11-20 17:12:12.400898', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 683, 3, 'Cho bánh vào tủ lạnh giữ khoảng một giờ. Khi nào dùng, lấy bánh ra đĩa, cho ca cao nước lên trên.', 10);
INSERT INTO public.recipe_steps VALUES (4362, '2025-11-20 17:12:12.402482', '2025-11-20 17:12:12.402482', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 683, 1, 'Cho sữa tươi vào bát thủy tinh, sau đó cho tiếp bột rau câu và bột quế vào quậy tan. Xoài gọt bỏ vỏ, cắt nhỏ một phần, còn một phần giữ lại, dùng để trang trí.', 10);
INSERT INTO public.recipe_steps VALUES (4363, '2025-11-20 17:12:12.403579', '2025-11-20 17:12:12.403579', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 683, 2, 'Đổ sữa vào máy xay sinh tố, cho phần xoài đã cắt nhỏ vào, xay nát cùng với sữa và trộn với hỗn hợp rau câu, bột quế, sữa. Đun sôi hỗn hợp xoài - rau câu, sau đó cho vào khuôn, để thật nguội.', 10);
INSERT INTO public.recipe_steps VALUES (4364, '2025-11-20 17:12:12.473235', '2025-11-20 17:12:12.473235', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 684, 1, 'Dâu tây rửa sạch, bổ làm tư, trộn đường để trong 10 phút.', 10);
INSERT INTO public.recipe_steps VALUES (4365, '2025-11-20 17:12:12.474839', '2025-11-20 17:12:12.474839', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 684, 2, 'Dùng máy sinh tố xay nhuyễn, thêm sữa tươi vào tuỳ sở thích của bạn.', 10);
INSERT INTO public.recipe_steps VALUES (4366, '2025-11-20 17:12:12.475887', '2025-11-20 17:12:12.475887', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 684, 3, 'Rót ra cốc, có thể trang trí thêm cho đẹp mắt và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (4367, '2025-11-20 17:12:12.689326', '2025-11-20 17:12:12.689326', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 685, 2, 'Xay nhuyễn khoai lang tím với nước lọc, lọc qua rây để bỏ xơ khoai còn dư.', 10);
INSERT INTO public.recipe_steps VALUES (4368, '2025-11-20 17:12:12.690996', '2025-11-20 17:12:12.690996', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 685, 3, 'Thêm 220 ml sữa tươi, 2/3 hộp sữa đặc, lá dứa và khuấy đều. Đun nóng hỗn hợp này ở lửa vừa trong 6-8 phút và khuấy đều (chỉ đun nóng, không sôi), tắt bếp, để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (4369, '2025-11-20 17:12:12.693094', '2025-11-20 17:12:12.693094', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 685, 5, 'Yêu cầu thành phẩm: Sữa có màu tím đẹp mộng mơ, vị bùi bùi của khoai lang quyện vị ngọt béo của sữa rất thơm ngon và bổ dưỡng.', 10);
INSERT INTO public.recipe_steps VALUES (4370, '2025-11-20 17:12:12.694769', '2025-11-20 17:12:12.694769', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 685, 1, 'Khoai lang tím gọt vỏ, rửa qua nước muối, luộc/hấp chín.', 10);
INSERT INTO public.recipe_steps VALUES (4371, '2025-11-20 17:12:12.695833', '2025-11-20 17:12:12.695833', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 685, 4, 'Rót sữa vào bình thủy tinh, bảo quản trong tủ lạnh dùng dần.', 10);
INSERT INTO public.recipe_steps VALUES (4372, '2025-11-20 17:12:13.229084', '2025-11-20 17:12:13.229084', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 686, 1, 'Nhựa đào, tuyết yến, bồ mễ ngâm 24h cho nở đều rồi đãi sạch hết cặn bẩn, tạp chất (có thể ngâm 12h rồi rửa sạch lần 1, tiếp tục ngâm đến 24h thì rửa lại lần nữa cho sạch hẳn). Nấm tuyết ngâm 2h cho nở.', 10);
INSERT INTO public.recipe_steps VALUES (4373, '2025-11-20 17:12:13.230677', '2025-11-20 17:12:13.230677', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 686, 3, 'Đun sôi 3-4 lít nước rồi cho hạt sen vào; tiếp đó là hết phần táo và nấm đông trùng. Cho hết phần đường vào khuấy tan (lượng đường gia giảm tuỳ khẩu vị). Kế đến là phần nhựa đào, bồ mễ, nấm tuyết, lá dứa vào. Nước sôi lại thì cho hết phần tuyết yến. Chè sau khi nguội sẽ bảo quản lạnh.', 10);
INSERT INTO public.recipe_steps VALUES (4374, '2025-11-20 17:12:13.232339', '2025-11-20 17:12:13.232339', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 686, 5, 'Chè sau khi nguội thì bảo quản lạnh.', 10);
INSERT INTO public.recipe_steps VALUES (4375, '2025-11-20 17:12:13.234032', '2025-11-20 17:12:13.234032', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 686, 2, 'Hạt sen rửa sạch cho vào nước nấu cho vừa mềm tới. Long nhãn, táo đỏ, kỷ tử rửa sạch bụi bẩn, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (4376, '2025-11-20 17:12:13.235639', '2025-11-20 17:12:13.235639', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 686, 4, 'Nấu 3-5 phút thì tắt bếp (Nấu lâu tuyết yến sẽ tan thành nước). Cuối cùng, cho hạt chia vào khuấy đều rồi để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (4377, '2025-11-20 17:12:13.363857', '2025-11-20 17:12:13.363857', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 687, 3, 'Cho tiếp kem sữa tươi và dâu ép nước vào trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (4378, '2025-11-20 17:12:13.365535', '2025-11-20 17:12:13.365535', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 687, 2, 'Sữa tươi: đun nóng, chế từ từ vào hỗn hợp trứng, trộn đều cho chín trứng.', 10);
INSERT INTO public.recipe_steps VALUES (4379, '2025-11-20 17:12:13.367171', '2025-11-20 17:12:13.367171', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 687, 4, 'Cho hỗn hợp kem vào thùng quay kem, quay đến khi kem đặc, múc kem cho vào vào hộp nhựa, bảo quản trong tủ đông.', 10);
INSERT INTO public.recipe_steps VALUES (4380, '2025-11-20 17:12:13.368761', '2025-11-20 17:12:13.368761', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 687, 1, 'Trứng gà: dùng máy đánh trứng đánh nổi đứng, thêm đường vào từ từ.', 10);
INSERT INTO public.recipe_steps VALUES (4381, '2025-11-20 17:12:13.757', '2025-11-20 17:12:13.757', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 688, 5, 'Trước khi bắc ra, cho nước hương bưởi vào. Khi thưởng thức, múc đá xáy vào khuấy đều.', 10);
INSERT INTO public.recipe_steps VALUES (4382, '2025-11-20 17:12:13.758581', '2025-11-20 17:12:13.758581', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 688, 2, 'Khi đã làm sạch cho hết mặn lần thứ 2 thì vắt nhẹ tay. Hoà 1 ít phèn chua vào nước lạnh để ngâm cùi bưởi khoảng 15 phút rồi xả sạch và ngâm vào nước vôi trong khoảng 1 ngày. Sau đó, vớt ra rửa sạch hết mùi vôi rồi vắt nhẹ, cho vào âu.', 10);
INSERT INTO public.recipe_steps VALUES (4383, '2025-11-20 17:12:13.760759', '2025-11-20 17:12:13.760759', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 688, 4, 'Đỗ sau khi đã đồ chín, để nguyên hạt, đun nước đường rồi cho cùi bưởi đã tẩm bột vào luộc tới khi trong là được. Cuối cùng, cho đỗ vào và xuống bột năng khi nào sánh là được.', 10);
INSERT INTO public.recipe_steps VALUES (4384, '2025-11-20 17:12:13.762908', '2025-11-20 17:12:13.762908', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 688, 3, 'Ngâm cùi bưởi đó vào nước đường rồi đun nhỏ lửa cho cạn. Tiếp đó, bỏ cùi bưởi ra phơi trên mâm cho tự khô để cùi ròn rồi tẩm bột năng vào.', 10);
INSERT INTO public.recipe_steps VALUES (4385, '2025-11-20 17:12:13.763993', '2025-11-20 17:12:13.763993', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 688, 1, 'Cùi bưởi cắt vuông hay sợi theo ý mình sau đó vẩy chút muối + 1 ít nước lạnh, bóp nhẹ tay cho hết hăng rồi sả nhẹ dưới vòi nước và tiếp tục làm như thế lần thứ 2.', 10);
INSERT INTO public.recipe_steps VALUES (4386, '2025-11-20 17:12:14.119363', '2025-11-20 17:12:14.119363', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 689, 7, 'Khi hạt sen chín, cho táo đỏ khô vào nấu cùng, đợi sôi lại thì cho đường thốt nốt hoặc đường phèn. Cuối cùng, cho nấm tuyết và long nhãn khô vào nấu, đợi sôi vài phút tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (4387, '2025-11-20 17:12:14.120947', '2025-11-20 17:12:14.120947', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 689, 4, 'Long nhãn ngâm nước ấm cho nở mềm và rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (4388, '2025-11-20 17:12:14.122518', '2025-11-20 17:12:14.122518', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 689, 1, 'Nấm tuyết ngâm vào nước cho nở, cắt gốc, rửa sạch thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (4389, '2025-11-20 17:12:14.124154', '2025-11-20 17:12:14.124154', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 689, 2, 'Hạt sen tươi bỏ nhuỵ xanh bên trong, rửa sạch. Nếu dùng hạt sen khô thì rửa sạch ngâm nước ấm cho nở.', 10);
INSERT INTO public.recipe_steps VALUES (4390, '2025-11-20 17:12:14.125216', '2025-11-20 17:12:14.125216', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 689, 6, 'Thỉnh thoảng hớt bọt cho nước trong (không nên đậy vung kín khi sôi)', 10);
INSERT INTO public.recipe_steps VALUES (4391, '2025-11-20 17:12:14.127373', '2025-11-20 17:12:14.127373', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 689, 10, 'Múc chè ra bát, thêm đá và hạt é đảo đều thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (4392, '2025-11-20 17:12:14.128989', '2025-11-20 17:12:14.128989', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 689, 8, 'Đợi chè nguội cho vào ngăn mát tủ lạnh (cất ngăn mát tủ lạnh ăn dần trong 2-3 ngày, càng lạnh sâu ăn càng mát và ngon)', 10);
INSERT INTO public.recipe_steps VALUES (4393, '2025-11-20 17:12:14.130604', '2025-11-20 17:12:14.130604', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 689, 9, 'Hạt é hoặc hạt chia ngâm nước cho nở.', 10);
INSERT INTO public.recipe_steps VALUES (4394, '2025-11-20 17:12:14.132217', '2025-11-20 17:12:14.132217', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 689, 3, 'Táo đỏ khô ngâm nước rửa sạch để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (4395, '2025-11-20 17:12:14.133822', '2025-11-20 17:12:14.133822', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 689, 5, 'Cho hạt sen vào nồi cùng khoảng 1,5 lít nước, ninh đến khi mềm nhừ.', 10);
INSERT INTO public.recipe_steps VALUES (4396, '2025-11-20 17:12:14.393314', '2025-11-20 17:12:14.393314', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 690, 2, 'Cho 1 túi sữa tươi, 1 hộp sữa đặc vào nồi nước trà đã lọc, khuấy đều cho tan, bắc lên bếp nấu lửa nhỏ 1-2 phút, tắt bếp, để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (4397, '2025-11-20 17:12:14.394895', '2025-11-20 17:12:14.394895', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 690, 5, 'Yêu cầu thành phẩm:Trà sữa Thái xanh hấp dẫn bởi hương thơm đặc trưng của trà sữa quyện với vị ngọt béo của sữa, chút giòn sần sật từ thạch.', 10);
INSERT INTO public.recipe_steps VALUES (4398, '2025-11-20 17:12:14.396491', '2025-11-20 17:12:14.396491', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 690, 3, 'Làm thạch trà xanh:Trộn đều 1 gói bột rau câu con cá dẻo với 180-200 gram đường (điều chỉnh theo khẩu vị ngọt mỗi người). Cho vào nồi 300 ml nước cốt trà, thêm 900 ml nước lọc đun sôi, hạ lửa vừa, rồi từ từ vừa cho bột rau câu đường vào vừa khuấy đều để không bị vón cục. Tiếp tục nấu khoảng 5 - 7 phút cho rau câu nở, tắt bếp, đổ thạch rau câu ra hộp/khuôn. Khi thạch rau câu nguội và đông lại thì cho vào ngăn mát tủ lạnh 1 giờ.', 10);
INSERT INTO public.recipe_steps VALUES (4399, '2025-11-20 17:12:14.398604', '2025-11-20 17:12:14.398604', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 690, 4, 'Trình bày và thưởng thức:Cắt thạch thành từng miếng nhỏ đều cho vào trà sữa trộn đều. Múc hỗn hợp trà sữa và thạch ra cốc (ly) thêm đá lạnh và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (4400, '2025-11-20 17:12:14.400754', '2025-11-20 17:12:14.400754', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 690, 1, 'Nấu trà sữa:Nấu 2,5 lít nước sôi, cho 40 g trà Thái xanh vào khuấy đều, tắt bếp, ủ trà 5 - 6 phút cho ra nước cốt, lọc qua rây lấy nước. Múc ra 300ml nước cốt trà riêng để làm thạch rau câu có màu xanh đẹp hơn.', 10);
INSERT INTO public.recipe_steps VALUES (4401, '2025-11-20 17:12:14.785503', '2025-11-20 17:12:14.785503', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 691, 3, 'Trộn đều ướp 15 phút cho ngấm.', 10);
INSERT INTO public.recipe_steps VALUES (4402, '2025-11-20 17:12:14.786578', '2025-11-20 17:12:14.786578', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 691, 1, 'Trộn đều bột gạo, bột năng và 1/2 thìa cà phê muối. Thêm 600-650 ml nước, đổ từ từ cho bột tan hết. Để bột trong 1-1,5 giờ hoặc qua đêm (để bột nở đều).', 10);
INSERT INTO public.recipe_steps VALUES (4403, '2025-11-20 17:12:14.788579', '2025-11-20 17:12:14.788579', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 691, 10, 'Khi ăn múc bánh đúc ra bát, thêm phần thịt băm xào thơm, hành khô, rau mùi thái nhỏ, chan nước chan đã đun sôi, tất cả các nguyên liệu phải nóng bánh sẽ luôn mềm thơm ngon.', 10);
INSERT INTO public.recipe_steps VALUES (4404, '2025-11-20 17:12:14.790092', '2025-11-20 17:12:14.790092', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 691, 5, 'Hành tây băm nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (4405, '2025-11-20 17:12:14.791092', '2025-11-20 17:12:14.791092', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 691, 2, 'Ướp thịt băm với 1 thìa cà phê bột nêm, 1/2 thìa cà phê bột canh, 1/2 thìa cà phê bột tiêu.', 10);
INSERT INTO public.recipe_steps VALUES (4406, '2025-11-20 17:12:14.793092', '2025-11-20 17:12:14.793092', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 691, 4, 'Mộc nhĩ, nấm hương ngâm nở, rửa sạch, thái sợi, băm nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (4407, '2025-11-20 17:12:14.795169', '2025-11-20 17:12:14.795169', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 691, 7, 'Đun nóng dầu ăn trong chào, đổ hành tây vào xào qua, tiếp đến xào thịt băm chín tới thì đổ nấm hương mộc nhĩ vào. Cho hành lá thái nhỏ, đảo qua rồi tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (4408, '2025-11-20 17:12:14.796911', '2025-11-20 17:12:14.796911', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 691, 8, 'Phần bột sau khi để 1-1,5h thì sẽ thấy có nước trắng phía trên, chắt bỏ phần nước này, thêm nước khác. Cho bột vào nồi khuấy đều, khi hơi đặc thì hạ nhỏ lửa, thêm 60 ml dầu ăn. Tiếp tục đảo cho đến khi bột quện với dầu ăn mịn màng và chín thì tắt bếp.(Có thể cho thêm nước nếu thấy bột quá đặc).', 10);
INSERT INTO public.recipe_steps VALUES (4434, '2025-11-20 17:12:16.247327', '2025-11-20 17:12:16.247327', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 696, 5, 'Thịt ướp với gia vị và bột xá xíu, thêm 1 cái trứng gà', 10);
INSERT INTO public.recipe_steps VALUES (4409, '2025-11-20 17:12:14.798484', '2025-11-20 17:12:14.798484', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 691, 9, 'Đổ nước ninh xương vào nồi, thêm nước mắm, đường, dấm khuấy đều, đun sôi, nêm nếm cho vừa khẩu vị rồi tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (4410, '2025-11-20 17:12:14.800071', '2025-11-20 17:12:14.800071', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 691, 6, 'Rau mùi, hành lá thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (4411, '2025-11-20 17:12:15.013527', '2025-11-20 17:12:15.013527', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 692, 4, 'Cho đá, trân châu vào ly (cốc), rót hồng trà sữa vào là bạn đã có ngay món hồng trà sữa thơm ngon như ngoài tiệm.', 10);
INSERT INTO public.recipe_steps VALUES (4412, '2025-11-20 17:12:15.01457', '2025-11-20 17:12:15.01457', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 692, 1, 'Trộn 150 g bột năng, 2 muỗng canh bột gạo và 1 muỗng canh bột ca cao, 1 muỗng canh đường và thêm từ từ nước sôi vào, trộn đều. Khi hỗn hợp nguội bớt, đeo găng tay nhồi cho tới khi bột dẻo mềm, không dính tay là được.', 10);
INSERT INTO public.recipe_steps VALUES (4413, '2025-11-20 17:12:15.016152', '2025-11-20 17:12:15.016152', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 692, 3, 'Đun sôi 2,5 - 3 lít nước, cho 50 g hồng trà vào ủ trong 10 phút, lọc bỏ bã trà, lấy nước cốt. Hòa tan nước cốt hồng trà còn ấm với 1 hộp sữa đặc, 1 túi sữa tươi (220ml), 180 - 200 g đường (điều chỉnh theo khẩu vị ngọt mỗi người).', 10);
INSERT INTO public.recipe_steps VALUES (4414, '2025-11-20 17:12:15.017216', '2025-11-20 17:12:15.017216', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 692, 2, 'Chia thành các khối nhỏ, vo tròn, thoa một lớp bột áo bên ngoài để không dính vào nhau. Đun nước hơi sủi tăm (lượng nước gấp 4 lần trân châu), cho trân châu vào luộc, hạ nhỏ lửa đun 20 phút cho tới khi trân châu nổi lên là chín, vớt ra cho vào tô nước đá cho nguội, vớt ra ngâm vào bát nước đường (tùy khẩu vị mỗi người để điều chỉnh). Khi dùng sẽ múc trân châu cho vào trà sữa.', 10);
INSERT INTO public.recipe_steps VALUES (4415, '2025-11-20 17:12:15.145173', '2025-11-20 17:12:15.145173', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 693, 1, 'Ngô nếp non, bào hoặc cắt vát, (không lấy mày) cho nước vào đun cùng lá nếp (nếu có). Khi hạt ngô nhừ, dẻo thì đổ đường, bột sắn dây hoà ra bát lấy nước.', 10);
INSERT INTO public.recipe_steps VALUES (4416, '2025-11-20 17:12:15.146792', '2025-11-20 17:12:15.146792', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 693, 2, 'Khi nồi ngô sôi, xuống bột từ từ lấy độ sánh, đun nhỏ lửa một lúc đến khi trong thì bắc ra, cho cốm tươi vào ăn kèm với dừa nạo, hoặc nước cốt dừa', 10);
INSERT INTO public.recipe_steps VALUES (4417, '2025-11-20 17:12:15.316721', '2025-11-20 17:12:15.316721', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 694, 4, 'Giống với trà sữa, món sữa trà tốt nhất là nên uống ngay sau khi làm, không nên để ngoài trời nóng và để qua đêm. Hương vị ngọt ngậy của sữa tươi, quyện với thạch trà mát mát, thơm thơm, giải toả cơn khát mùa hè.', 10);
INSERT INTO public.recipe_steps VALUES (4418, '2025-11-20 17:12:15.317805', '2025-11-20 17:12:15.317805', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 694, 2, 'Đã có khá nhiều cách làm trà sữa tại nhà vừa ngon, vừa đảm bảo sức khoẻ lại dễ làm. Tuy nhiên, nếu muốn đổi vị, bạn có thể đổi phương pháp làm, vẫn là những nguyên liệu đó nhưng có thể chế biến ra một món "ngược đời" là sữa thạch trà, thay vì trà sữa thông thường.', 10);
INSERT INTO public.recipe_steps VALUES (4419, '2025-11-20 17:12:15.319913', '2025-11-20 17:12:15.319913', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 694, 6, 'Tiếp theo, cho 20 gr bột thạch agar, khuấy đều cho tan rồi rót ra bát, để nguội cho tới khi đông lại; dùng thìa để cắt hoặc làm vỡ thạch.', 10);
INSERT INTO public.recipe_steps VALUES (4420, '2025-11-20 17:12:15.32159', '2025-11-20 17:12:15.32159', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 694, 3, 'Với món đồ uống này, phần nước trà sẽ được đem làm thạch, còn phần sữa tươi sẽ là thành phần chính. Món này dành cho những ai thích vị béo ngậy của sữa, ngoài ra, khi trà đem làm thạch sẽ giảm độ "mất ngủ" hơn so với trà sữa thông thường, phù hợp với những ai thường xuyên thành "cú đêm" vì uống trà sữa.', 10);
INSERT INTO public.recipe_steps VALUES (4421, '2025-11-20 17:12:15.322631', '2025-11-20 17:12:15.322631', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 694, 5, 'Cho 3 lát chanh, một chút trà đen (tuỳ khẩu vị thích ăn thạch đậm hay nhạt vị trà), một chút đường phèn (tuỳ theo khẩu vị) rồi rót 500 ml vào trong nồi, đun sôi rồi dùng vợt, vớt hết phần chanh và lá trà.', 10);
INSERT INTO public.recipe_steps VALUES (4422, '2025-11-20 17:12:15.32422', '2025-11-20 17:12:15.32422', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 694, 7, 'Rót loại sữa tươi vào là hoàn thành món sữa trà lạ miệng. Trước đó, bạn có thể cho sữa vào tủ lạnh cho mát, hoặc để nhiệt độ bình thường và cho thêm đá.', 10);
INSERT INTO public.recipe_steps VALUES (4423, '2025-11-20 17:12:15.3258', '2025-11-20 17:12:15.3258', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 694, 1, 'Trà sữa là món giải khát quen thuộc ngày hè, không chỉ ở Việt Nam mà còn ở nhiều quốc gia châu Á. Tình hình dịch bệnh có nhiều diễn biến phức tạp, nhiều hàng quán phải đóng cửa, dịch vụ giao hàng tận nhà cũng bị giới hạn, do đó, không ít người đã dành thời gian thử nghiệm làm trà sữa tại nhà.', 10);
INSERT INTO public.recipe_steps VALUES (4424, '2025-11-20 17:12:15.507669', '2025-11-20 17:12:15.507669', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 695, 7, 'Yêu cầu thành phẩm: Bí đỏ mềm dẻo, quyện trong nước cốt dừa sóng sánh béo ngậy, đậu phộng giòn bùi làm nên món chè thơm ngon.', 10);
INSERT INTO public.recipe_steps VALUES (4425, '2025-11-20 17:12:15.509293', '2025-11-20 17:12:15.509293', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 695, 2, 'Bí đỏ gọt vỏ, cắt miếng, hấp (hoặc luộc) chín, tán nhuyễn hoặc xay mịn.', 10);
INSERT INTO public.recipe_steps VALUES (4426, '2025-11-20 17:12:15.51093', '2025-11-20 17:12:15.51093', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 695, 6, 'Múc chè ra bát, rưới thêm nước cốt dừa, rắc đậu phộng hoặc mè rang, thêm dừa khô nếu thích và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (4427, '2025-11-20 17:12:15.51202', '2025-11-20 17:12:15.51202', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 695, 4, 'Chia bột thành từng khối nhỏ đều nhau, viên tròn hoặc tạo hình tùy thích.', 10);
INSERT INTO public.recipe_steps VALUES (4428, '2025-11-20 17:12:15.513622', '2025-11-20 17:12:15.513622', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 695, 1, 'Làm nước sốt cốt dừa: Hòa tan nước cốt dừa, 2 thìa canh bột năng, 2-3 thìa canh đường, 1/4 thìa cà phê muối, khuấy đều cho tan. Bật bếp vừa đun sôi nhỏ lửa, vừa khuấy đều cho tới khi trở thành hỗn hợp hơi sền sệt là đạt, tắt bếp, để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (4429, '2025-11-20 17:12:15.515246', '2025-11-20 17:12:15.515246', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 695, 3, 'Từ từ trộn bột năng vào bí đỏ đã nghiền, trộn đều, đeo găng tay nhào cho tới khi trở thành một khối bột dẻo mịn, không dính tay là đạt.', 10);
INSERT INTO public.recipe_steps VALUES (4430, '2025-11-20 17:12:15.516836', '2025-11-20 17:12:15.516836', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 695, 5, 'Cho lượng nước đủ dùng vào nồi, thêm đường phèn nấu tan, rồi cho bí đỏ viên tròn vào đun sôi. Khi các viên chè bí đỏ nổi lên là đã chín, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (4431, '2025-11-20 17:12:16.242372', '2025-11-20 17:12:16.242372', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 696, 4, 'Cách làm nhân', 10);
INSERT INTO public.recipe_steps VALUES (4432, '2025-11-20 17:12:16.24401', '2025-11-20 17:12:16.24401', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 696, 9, 'Cho giấm với vỏ chanh (để bánh trắng và thơm) vào nước, hấp bánh', 10);
INSERT INTO public.recipe_steps VALUES (4436, '2025-11-20 17:12:16.251168', '2025-11-20 17:12:16.251168', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 696, 8, 'Bột lấy ra tạo hình cán bánh thành 22 cái. Làm xong cho bánh vào lò nướng ủ 15 phút nhiệt độ 50 độ C.', 10);
INSERT INTO public.recipe_steps VALUES (4437, '2025-11-20 17:12:16.25224', '2025-11-20 17:12:16.25224', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 696, 2, 'Cho bột đã nhào kỹ vào bát tô, đậy kín bằng màng bọc thực phẩm sau đó lấy một cái xoong to cho nước nóng vào (mực nước làm sao không ngập tô bột)', 10);
INSERT INTO public.recipe_steps VALUES (4438, '2025-11-20 17:12:16.25382', '2025-11-20 17:12:16.25382', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 696, 12, 'Bánh trắng, bột mịn, tơi xốp nhưng không bở', 10);
INSERT INTO public.recipe_steps VALUES (4439, '2025-11-20 17:12:16.255607', '2025-11-20 17:12:16.255607', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 696, 7, 'Trộn thịt sống với phần nhân đã xào chính rồi cho hạt sen và lạp xưởng vào trộn đều rồi vo tròn 22 cái.', 10);
INSERT INTO public.recipe_steps VALUES (4440, '2025-11-20 17:12:16.257143', '2025-11-20 17:12:16.257143', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 696, 6, 'Xào củ hành trắng với nấm hương trước cho thơm rồi mới cho củ sắn với củ cà rốt vào, nếm gia vị vừa ăn, xào chính để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (4441, '2025-11-20 17:12:16.258846', '2025-11-20 17:12:16.258846', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 696, 1, 'Trộn tất cả nguyên liệu lại với nhau cho bột dẻo mịn.', 10);
INSERT INTO public.recipe_steps VALUES (4442, '2025-11-20 17:12:16.260999', '2025-11-20 17:12:16.260999', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 696, 3, 'Đặt tô bột vào nồi nước nóng đó đậy vung chờ 30 phút cho bột nở xốp.', 10);
INSERT INTO public.recipe_steps VALUES (4443, '2025-11-20 17:12:16.263187', '2025-11-20 17:12:16.263187', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 696, 13, 'Khi ăn có vị ngọt ngon của thịt, thơm của hạt sen...', 10);
INSERT INTO public.recipe_steps VALUES (4444, '2025-11-20 17:12:16.433701', '2025-11-20 17:12:16.433701', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 697, 5, 'Vải tách lấy phần cùi thịt. Sau 20 phút, cho vải vào nồi chè nấu chung khoảng 10 phút. Thêm chút đường phèn vào, đun cho đường tan rồi tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (4445, '2025-11-20 17:12:16.434755', '2025-11-20 17:12:16.434755', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 697, 4, 'Đổ lượng nước thích hợp vào nồi nấm tuyết, đun sôi rồi hạ nhỏ lửa đun trong 20 phút.', 10);
INSERT INTO public.recipe_steps VALUES (4446, '2025-11-20 17:12:16.436349', '2025-11-20 17:12:16.436349', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 697, 2, 'Nấm tuyết ngâm trong nước cho nở sau đó rửa sạch lại nấm.', 10);
INSERT INTO public.recipe_steps VALUES (4447, '2025-11-20 17:12:16.437457', '2025-11-20 17:12:16.437457', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 697, 3, 'Xé nhỏ nấm rồi cho vào nồi. Táo tàu rửa qua cho sạch sau đó bỏ hạt rồi thái miếng.', 10);
INSERT INTO public.recipe_steps VALUES (4448, '2025-11-20 17:12:16.438497', '2025-11-20 17:12:16.438497', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 697, 1, 'Chè vải nấm tuyết là một món chè đơn giản, dễ chế biến mà lại ngon miệng. Món chè có thể ăn nóng hoặc lạnh tùy theo sở thích. Chè có vị thanh ngọt tự nhiên của vải, vị giòn giòn của nấm tuyết, rất tốt cho sức khỏe, thích hợp để giải nhiệt ngày hè.', 10);
INSERT INTO public.recipe_steps VALUES (4449, '2025-11-20 17:12:16.717729', '2025-11-20 17:12:16.717729', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 698, 9, 'Ấn dẹt viên bột, cho nhân vào giữa gấp các mép vo tròn lại, có thể tạo hình thành quả bí nếu thích.', 10);
INSERT INTO public.recipe_steps VALUES (4450, '2025-11-20 17:12:16.719291', '2025-11-20 17:12:16.719291', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 698, 15, 'Đun sôi, đập dập một nhánh gừng thả vào nồi nước, hớt bọt, khi thấy có mùi đường gừng, hạ nhỏ lửa.', 10);
INSERT INTO public.recipe_steps VALUES (4451, '2025-11-20 17:12:16.720854', '2025-11-20 17:12:16.720854', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 698, 4, 'Cách làm nhân đậu xanh: Đậu xanh vo sạch, ngâm nước 2-5 tiếng, vớt ra để ráo, trộn với xíu muối, đem hấp chín.', 10);
INSERT INTO public.recipe_steps VALUES (4452, '2025-11-20 17:12:16.722891', '2025-11-20 17:12:16.722891', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 698, 11, 'Dùng đầu đũa ấn nhẹ phần đầu quả bí, nặn cuống, quét chút nước tạo độ dính rồi đặt cuống vào.', 10);
INSERT INTO public.recipe_steps VALUES (4453, '2025-11-20 17:12:16.725101', '2025-11-20 17:12:16.725101', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 698, 6, 'Trộn vào 2 thìa canh đường, tuỳ độ ngọt mà cho, một xíu vani, trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (4454, '2025-11-20 17:12:16.72724', '2025-11-20 17:12:16.72724', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 698, 8, 'Nặn bánh theo tỉ lệ: Bột: 30 gr, nhân 20 gr', 10);
INSERT INTO public.recipe_steps VALUES (4455, '2025-11-20 17:12:16.72937', '2025-11-20 17:12:16.72937', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 698, 13, 'Đun sôi nồi nước, thả các viên bí đỏ vào luộc đến khi viên bột nổi lên trên mặt nước, vớt ra cho vào bát nước lạnh.', 10);
INSERT INTO public.recipe_steps VALUES (4456, '2025-11-20 17:12:16.730435', '2025-11-20 17:12:16.730435', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 698, 1, 'Bí đỏ gọt vỏ, cắt nhỏ, luộc hoặc hấp chín, vớt ra để nguội (cần đợi cho bí nguội mới trộn và tuyệt đối không cho thêm nước trong lúc nghiền và xay bí).', 10);
INSERT INTO public.recipe_steps VALUES (4457, '2025-11-20 17:12:16.732015', '2025-11-20 17:12:16.732015', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 698, 3, 'Cho từ từ bột nếp vào nhào cùng bí đỏ đến khi bột dẻo mịn, không dính tay là được.', 10);
INSERT INTO public.recipe_steps VALUES (4458, '2025-11-20 17:12:16.733597', '2025-11-20 17:12:16.733597', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 698, 14, 'Cách nấu nước đường gừng:Cho 500 ml nước trắng vào nồi, thêm 200 gr đường.', 10);
INSERT INTO public.recipe_steps VALUES (4459, '2025-11-20 17:12:16.734665', '2025-11-20 17:12:16.734665', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 698, 18, 'Hoà tan, đun nhỏ lửa sôi nhẹ lăn tăn thì tắt bếp múc ra để nguội, thu được phần nước cốt dừa sền sệt và béo ngậy.[Caption]', 10);
INSERT INTO public.recipe_steps VALUES (4460, '2025-11-20 17:12:16.736249', '2025-11-20 17:12:16.736249', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 698, 2, 'Tán thật nhuyễn bí đỏ hoặc đem xay mịn, thêm vào một thìa canh ăn phở đường.', 10);
INSERT INTO public.recipe_steps VALUES (4461, '2025-11-20 17:12:16.737824', '2025-11-20 17:12:16.737824', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 698, 7, 'Chia bột và nhân để vo viên.', 10);
INSERT INTO public.recipe_steps VALUES (4462, '2025-11-20 17:12:16.738972', '2025-11-20 17:12:16.738972', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 698, 12, 'Phần cuống nhồi bột màu xanh, nếu ngại làm cuống có thể tìm các loại lá nhỏ có cuống cắm vào.', 10);
INSERT INTO public.recipe_steps VALUES (4463, '2025-11-20 17:12:16.740559', '2025-11-20 17:12:16.740559', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 698, 5, 'Bỏ đậu ra ngoài đến khi còn ấm thì đem giã hoặc xay mịn.', 10);
INSERT INTO public.recipe_steps VALUES (4464, '2025-11-20 17:12:16.742157', '2025-11-20 17:12:16.742157', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 698, 16, 'Vớt các viên bí đỏ thả vào nồi nước đường gừng, đun thêm khoảng 10 phút lửa nhỏ thì tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (4465, '2025-11-20 17:12:16.743838', '2025-11-20 17:12:16.743838', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 698, 10, 'Cách tạo hình quả bí đỏ:Vo tròn, ấn hơi dẹt, dùng que hoặc sống dao, ấn thành các múi quả bí.', 10);
INSERT INTO public.recipe_steps VALUES (4466, '2025-11-20 17:12:16.744898', '2025-11-20 17:12:16.744898', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 698, 17, 'Cách nấu nước cốt dừa:Đổ 200 ml nước cốt dừa đóng hộp vào nồi nhỏ, thêm vào 2 thìa canh ăn phở đường, 50ml nước trắng, một thìa canh ăn phở bột năng, một xíu muối (bằng đầu đũa không lại mặn).', 10);
INSERT INTO public.recipe_steps VALUES (4467, '2025-11-20 17:12:16.745952', '2025-11-20 17:12:16.745952', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 698, 19, 'Khi ăn múc vài viên bí đỏ ra bát, chan nước đường gừng, rưới vài thìa nước cốt dừa lên trên, rắc lạc rang và dừa nạo, ăn nóng hay lạnh đều được.', 10);
INSERT INTO public.recipe_steps VALUES (4468, '2025-11-20 17:12:17.011096', '2025-11-20 17:12:17.011096', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 699, 4, 'Hoà bột năng với chút nước, từ từ đổ vào nồi nước cam, khuấy đều đến khi nồi nước cam sôi và hơi sánh lại trút phần tép cam vào, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (4469, '2025-11-20 17:12:17.013238', '2025-11-20 17:12:17.013238', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 699, 5, 'Đổ tào phớ vào nồi nước cam, khuấy nhẹ tay.', 10);
INSERT INTO public.recipe_steps VALUES (4470, '2025-11-20 17:12:17.014812', '2025-11-20 17:12:17.014812', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 699, 6, 'Để nguội múc ra bát, có thêm đá hoặc cho vào ngăn mát tủ lạnh ăn dần.', 10);
INSERT INTO public.recipe_steps VALUES (4471, '2025-11-20 17:12:17.016321', '2025-11-20 17:12:17.016321', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 699, 3, 'Cho nước lọc, nước ép cam tươi hoặc nước cam đóng hộp và đường vào nồi bắc lên bếp đun sôi.', 10);
INSERT INTO public.recipe_steps VALUES (4472, '2025-11-20 17:12:17.018838', '2025-11-20 17:12:17.018838', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 699, 1, 'Cam gọt vỏ, bóc lấy phần tép cam.', 10);
INSERT INTO public.recipe_steps VALUES (4473, '2025-11-20 17:12:17.020867', '2025-11-20 17:12:17.020867', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 699, 2, 'Lấy một ít vỏ cam rửa thật sạch, thái nhỏ cho vào nồi chè cam cho thơm.', 10);
INSERT INTO public.recipe_steps VALUES (4474, '2025-11-20 17:12:17.349366', '2025-11-20 17:12:17.349366', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 700, 5, 'Lần lượt xếp 1 lớp chuối, thêm đậu phộng rang và dừa nạo. Làm từng lớp cho tới khi hết.', 10);
INSERT INTO public.recipe_steps VALUES (4475, '2025-11-20 17:12:17.350494', '2025-11-20 17:12:17.350494', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 700, 4, 'Làm kem:Lót giấy nến vào hộp đựng, múc hỗn hợp nước sữa và cốt dừa vào, láng đều hộp.', 10);
INSERT INTO public.recipe_steps VALUES (4476, '2025-11-20 17:12:17.352079', '2025-11-20 17:12:17.352079', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 700, 1, 'Lạc rang chín, bọc vào giấy kín để giữ độ giòn và dễ tách vỏ. Khi nguội thì chà xát, bỏ vỏ.', 10);
INSERT INTO public.recipe_steps VALUES (4477, '2025-11-20 17:12:17.353708', '2025-11-20 17:12:17.353708', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 700, 2, 'Trong một tô trộn lớn, cho 200 ml sữa đặc, 2 hộp sữa chua không đường, 300 ml nước cốt dừa, một chút tinh dầu chuối, 1/4 thìa cà phê muối, rồi khuấy đều.', 10);
INSERT INTO public.recipe_steps VALUES (4478, '2025-11-20 17:12:17.354766', '2025-11-20 17:12:17.354766', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 700, 6, 'Lớp trên cùng phủ dừa nạo và đậu phộng rang. Đậy kín hoặc dùng màng bọc thực phẩm bọc kín.', 10);
INSERT INTO public.recipe_steps VALUES (4479, '2025-11-20 17:12:17.356342', '2025-11-20 17:12:17.356342', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 700, 3, 'Chuối bóc bỏ vỏ, dùng dao cắt theo chiều dọc, thành 3 lát.', 10);
INSERT INTO public.recipe_steps VALUES (4480, '2025-11-20 17:12:17.357393', '2025-11-20 17:12:17.357393', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 700, 7, 'Đặt hộp kem vào ngăn đá tủ lạnh 6-8 tiếng để kem đông lại.', 10);
INSERT INTO public.recipe_steps VALUES (4481, '2025-11-20 17:12:17.696972', '2025-11-20 17:12:17.696972', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 701, 3, 'Chia đều đậu ra bốn bát nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (4482, '2025-11-20 17:12:17.698565', '2025-11-20 17:12:17.698565', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 701, 6, 'Chia hỗn hợp vừa pha ra 5 cái bát nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (4483, '2025-11-20 17:12:17.699626', '2025-11-20 17:12:17.699626', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 701, 9, 'Lớp đầu tiên hấp 5 phút, lớp thứ hai 6 phút, cách mỗi lớp lại tăng thêm một phút. Khi cho lớp cuối cùng vào, hấp trong vòng 13 phút.', 10);
INSERT INTO public.recipe_steps VALUES (4484, '2025-11-20 17:12:17.701239', '2025-11-20 17:12:17.701239', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 701, 4, 'Lá dứa cắt nhỏ xay với 350 ml nước, lọc lấy nước cốt.', 10);
INSERT INTO public.recipe_steps VALUES (4485, '2025-11-20 17:12:17.702325', '2025-11-20 17:12:17.702325', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 701, 10, 'Bánh chín để thật nguội mới lấy ra khỏi khuôn.', 10);
INSERT INTO public.recipe_steps VALUES (4486, '2025-11-20 17:12:17.703937', '2025-11-20 17:12:17.703937', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 701, 1, 'Vo sạch đỗ, ngâm nước nóng khoảng một tiếng, nấu với 100 ml nước và chút muối như cơm.', 10);
INSERT INTO public.recipe_steps VALUES (4487, '2025-11-20 17:12:17.70554', '2025-11-20 17:12:17.70554', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 701, 5, 'Pha hỗn hợp nước cốt lá dứa với 300 g bột năng + 60 g bột gạo + 220 g đường + 400 g nước cốt dừa đậm đặc + một chút muối.', 10);
INSERT INTO public.recipe_steps VALUES (4488, '2025-11-20 17:12:17.706723', '2025-11-20 17:12:17.706723', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 701, 7, 'Khuôn hấp tròn 27cm, cao 4cm. Cột khăn vào nắp nồi để không bị nhỏ nước xuống mặt bánh.', 10);
INSERT INTO public.recipe_steps VALUES (4489, '2025-11-20 17:12:17.708334', '2025-11-20 17:12:17.708334', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 701, 8, 'Lấy dầu ăn thoa khắp khuôn để bánh không bị dính, hấp khuôn 5 phút rồi đổ bột màu xanh trước, đến lớp bột đậu xanh. Đổ từng lớp bột xen kẽ và đều nhau.', 10);
INSERT INTO public.recipe_steps VALUES (4490, '2025-11-20 17:12:17.709418', '2025-11-20 17:12:17.709418', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 701, 2, 'Khi đỗ chín, cho vào xay chung với 250 ml nước cốt dừa đậm đặc + 200 g bột năng + 20 g bột gạo + 130 g đường cát + muối.', 10);
INSERT INTO public.recipe_steps VALUES (4491, '2025-11-20 17:12:17.823288', '2025-11-20 17:12:17.823288', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 702, 6, 'Nước chanh việt quất có vị ngọt vừa phải, thơm nức hương việt quất tươi. Hơn thế khi thưởng thức nước chanh việt quất, được cảm giác nếm thử những trái việt quất giòn giòn vô cùng thích thú.', 10);
INSERT INTO public.recipe_steps VALUES (4492, '2025-11-20 17:12:17.824361', '2025-11-20 17:12:17.824361', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 702, 3, 'Cho nước cốt chanh vào khuấy đều để nước có màu đẹp hơn và có vị chua ngọt dễ uống.', 10);
INSERT INTO public.recipe_steps VALUES (4493, '2025-11-20 17:12:17.825439', '2025-11-20 17:12:17.825439', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 702, 5, 'Bảo quản nước trong ngăn mát tủ lạnh uống dần.', 10);
INSERT INTO public.recipe_steps VALUES (4494, '2025-11-20 17:12:17.827049', '2025-11-20 17:12:17.827049', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 702, 2, 'Cho nước, việt quất, đường phèn vào nấu cho việt quất ra nước màu rồi lọc bỏ phần vỏ, bã.', 10);
INSERT INTO public.recipe_steps VALUES (4495, '2025-11-20 17:12:17.828144', '2025-11-20 17:12:17.828144', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 702, 4, 'Để nước thật nguội rồi cho vào chai sạch đậy nắp kín.', 10);
INSERT INTO public.recipe_steps VALUES (4496, '2025-11-20 17:12:17.829793', '2025-11-20 17:12:17.829793', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 702, 1, 'Việt quất rửa sạch để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (4497, '2025-11-20 17:12:18.090255', '2025-11-20 17:12:18.090255', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 703, 4, 'Lần lượt cho từng hạt sen vào trong mỗi cùi nhãn cho tới khi hết.', 10);
INSERT INTO public.recipe_steps VALUES (4498, '2025-11-20 17:12:18.091872', '2025-11-20 17:12:18.091872', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 703, 1, 'Hạt sen tươi bóc vỏ lụa, thông bỏ tâm sen (vì đắng), cho hạt sen và nước vào luộc, thỉnh thoảng hớt bọt cho nước trong.', 10);
INSERT INTO public.recipe_steps VALUES (4499, '2025-11-20 17:12:18.093494', '2025-11-20 17:12:18.093494', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 703, 3, 'Nhãn rửa sạch, bóc bỏ vỏ, dùng đầu nhọn dao nhỏ hoặc tăm nhọn khứa quanh núm hạt để tách cùi ra hạt, lật ngược lại lấy tăm nhọn đẩy hạt ra ngoài. Chú ý giữ cùi nhãn không bị rách.', 10);
INSERT INTO public.recipe_steps VALUES (4500, '2025-11-20 17:12:18.09457', '2025-11-20 17:12:18.09457', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 703, 6, 'Trình bày và thưởng thức: Cho hạt sen lồng nhãn ra bát, chan lượng nước chè vào, thêm đá và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (4536, '2025-11-20 17:12:19.072333', '2025-11-20 17:12:19.072333', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 43, 'Chuẩn bị một âu nước đá to, đặt khuôn vào âu nước đá, tránh không để bị ngập khuôn.', 10);
INSERT INTO public.recipe_steps VALUES (4501, '2025-11-20 17:12:18.095649', '2025-11-20 17:12:18.095649', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 703, 2, 'Sau 10 phút, sen chín thì vớt ra. Thêm lượng nước (căn đủ cho phần chè ăn), cho đường phèn vào khuấy đều cho tan. Bỏ hạt sen trở lại đun nhỏ lửa khoảng 3-4 phút để hạt sen ngấm đường, vớt sen ra, để nguội. Phần nước luộc sen, giữ lại.', 10);
INSERT INTO public.recipe_steps VALUES (4502, '2025-11-20 17:12:18.09727', '2025-11-20 17:12:18.09727', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 703, 5, 'Cho phần nhãn đã lồng hạt sen trở lại nồi nước đường, đun sôi thì tắt bếp, vớt nhãn lồng sen ra để nguội, cho vào ngăn mát tủ lạnh cho giòn. Phần nước chè thì lọc cho trong, để nguội, thêm chút tinh dầu bưởi hoặc vani tạo mùi thơm.', 10);
INSERT INTO public.recipe_steps VALUES (4503, '2025-11-20 17:12:19.018702', '2025-11-20 17:12:19.018702', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 6, 'Thêm sữa tươi khuấy đều rồi cất tủ lạnh.', 10);
INSERT INTO public.recipe_steps VALUES (4504, '2025-11-20 17:12:19.02129', '2025-11-20 17:12:19.02129', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 13, 'Pha nước với đường ngô (hoặc đường cát) cho lên bếp đun.', 10);
INSERT INTO public.recipe_steps VALUES (4505, '2025-11-20 17:12:19.022797', '2025-11-20 17:12:19.022797', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 27, 'Cách làm Flan cheese', 10);
INSERT INTO public.recipe_steps VALUES (4506, '2025-11-20 17:12:19.023806', '2025-11-20 17:12:19.023806', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 31, 'Cho cream cheese hoặc phomai con bò cười vào một cái nồi, đổ sữa tươi vào khuấy đều và cho lên bếp đun nhỏ lửa.', 10);
INSERT INTO public.recipe_steps VALUES (4507, '2025-11-20 17:12:19.025805', '2025-11-20 17:12:19.025805', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 40, 'Hoà 12gr bột cà phê hoà tan vào chút nước nóng rồi đổ vào nồi rau câu đã đun sôi.', 10);
INSERT INTO public.recipe_steps VALUES (4508, '2025-11-20 17:12:19.027373', '2025-11-20 17:12:19.027373', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 34, 'Khuấy đều tất cả rồi dùng rây lọc hỗn hợp để hỗn hợp được mịn đẹp.', 10);
INSERT INTO public.recipe_steps VALUES (4509, '2025-11-20 17:12:19.029005', '2025-11-20 17:12:19.029005', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 8, 'Cho 300 ml nước sôi và trà vào ấm, để 10 phút cho trà ngấm.', 10);
INSERT INTO public.recipe_steps VALUES (4510, '2025-11-20 17:12:19.030597', '2025-11-20 17:12:19.030597', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 35, 'Tiếp tục đổ lại nồi (nên dùng nồi khác để tránh phần cream cheese còn sót lại, hoặc dùng sang nồi mới).', 10);
INSERT INTO public.recipe_steps VALUES (4511, '2025-11-20 17:12:19.032187', '2025-11-20 17:12:19.032187', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 2, 'Có hai cách pha là dùng trà túi lọc hoặc trà khô:', 10);
INSERT INTO public.recipe_steps VALUES (4512, '2025-11-20 17:12:19.033769', '2025-11-20 17:12:19.033769', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 4, 'Bỏ trà vào bình chứa300ml nước sôi, để 5-10 phút cho ngấm.', 10);
INSERT INTO public.recipe_steps VALUES (4513, '2025-11-20 17:12:19.035538', '2025-11-20 17:12:19.035538', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 42, 'Chuẩn bị khuôn to hoặc nhỏ tuỳ thích.', 10);
INSERT INTO public.recipe_steps VALUES (4514, '2025-11-20 17:12:19.036887', '2025-11-20 17:12:19.036887', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 22, 'Đặt nồi lên bếp, thêm nước, đợi nước lăn tăn sôi thì đổ đường cát trắng và bột thạch vào, khuấy đều cho tan bột, hớt bọt nếu có, đợi sôi lại tắt bếp luôn không nên khuấy nhiều.', 10);
INSERT INTO public.recipe_steps VALUES (4515, '2025-11-20 17:12:19.038463', '2025-11-20 17:12:19.038463', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 29, 'Chuẩn bị flan cheese:', 10);
INSERT INTO public.recipe_steps VALUES (4516, '2025-11-20 17:12:19.04005', '2025-11-20 17:12:19.04005', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 36, 'Cho lên bếp đun nhỏ lửa, vừa đun vừa khuấy đến khi hỗn hợp sền sệt thì bắc ra, để sang một bên.', 10);
INSERT INTO public.recipe_steps VALUES (4517, '2025-11-20 17:12:19.041651', '2025-11-20 17:12:19.041651', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 38, 'Múc 550ml hỗn hợp đổ sang nồi hỗn hợp cream cheese và trứng, sữa đặc đã để sang một bên', 10);
INSERT INTO public.recipe_steps VALUES (4518, '2025-11-20 17:12:19.043273', '2025-11-20 17:12:19.043273', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 39, 'Khuấy đều là hoàn thiện cream cheese (luôn giữ hỗn hợp ấm).', 10);
INSERT INTO public.recipe_steps VALUES (4519, '2025-11-20 17:12:19.044901', '2025-11-20 17:12:19.044901', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 20, 'Cách làm thạch phô mai', 10);
INSERT INTO public.recipe_steps VALUES (4520, '2025-11-20 17:12:19.046523', '2025-11-20 17:12:19.046523', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 30, 'Đổ sữa đặc vào phần lòng đỏ và khuấy đều không cần khuấy quá kĩ.', 10);
INSERT INTO public.recipe_steps VALUES (4521, '2025-11-20 17:12:19.04764', '2025-11-20 17:12:19.04764', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 11, 'Cách làm trân châu:', 10);
INSERT INTO public.recipe_steps VALUES (4522, '2025-11-20 17:12:19.049754', '2025-11-20 17:12:19.049754', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 46, 'Cắt miếng vuông hay chữ nhật nhỏ tuỳ ý.', 10);
INSERT INTO public.recipe_steps VALUES (4523, '2025-11-20 17:12:19.051765', '2025-11-20 17:12:19.051765', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 24, 'Sau đó lại đổ một lớp thạch ngập kín miếng pho mai.', 10);
INSERT INTO public.recipe_steps VALUES (4524, '2025-11-20 17:12:19.053371', '2025-11-20 17:12:19.053371', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 3, 'Với trà túi lọc:', 10);
INSERT INTO public.recipe_steps VALUES (4525, '2025-11-20 17:12:19.054959', '2025-11-20 17:12:19.054959', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 32, 'Vừa đun vừa khuấy cho cream cheese tan rồi tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (4526, '2025-11-20 17:12:19.056529', '2025-11-20 17:12:19.056529', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 16, 'Đổ vài thìa dầu vào bát nước đá.', 10);
INSERT INTO public.recipe_steps VALUES (4527, '2025-11-20 17:12:19.05809', '2025-11-20 17:12:19.05809', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 33, 'Đổ từ từ hỗn hợp lòng đỏ trứng và sữa đặc đã khuấy đều vào nồi cream cheese sữa tươi vừa đun xong.', 10);
INSERT INTO public.recipe_steps VALUES (4528, '2025-11-20 17:12:19.059616', '2025-11-20 17:12:19.059616', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 17, 'Dùng xi lanh hoặc lọ bóp tương cà, cắt phần đầu rồi đổ thạch vào, bơm hoặc bóp nhẹ vào phần có váng dầu nổi lên, thạch gặp dầu lạnh sẽ đông lại và chìm xuống đáy.', 10);
INSERT INTO public.recipe_steps VALUES (4529, '2025-11-20 17:12:19.060971', '2025-11-20 17:12:19.060971', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 19, 'Để tránh trân châu không bị vón cục nên trộn cùng chút đường rồi bọc lại, cất ngăn mát tủ lạnh.', 10);
INSERT INTO public.recipe_steps VALUES (4530, '2025-11-20 17:12:19.062477', '2025-11-20 17:12:19.062477', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 26, 'Thạch nguội để vào ngăn mát 30 phút-1h là bỏ ra dùng được.', 10);
INSERT INTO public.recipe_steps VALUES (4531, '2025-11-20 17:12:19.0639', '2025-11-20 17:12:19.0639', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 12, 'Trộn đều bột thạch với đường, với tỉ lệ 300-350 ml nước như trên, nếu sử dụng gói thạch konyaku thì dùng một gói, nếu dùng bột rau câu jelly thì dùng 6gr. (để tránh thạch làm xong bị đổ mồ hôi hay chảy nước, có thể pha theo tỉ lệ: 4gr thạch jelly+2gr thạch aga).', 10);
INSERT INTO public.recipe_steps VALUES (4532, '2025-11-20 17:12:19.064898', '2025-11-20 17:12:19.064898', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 37, 'Đổ 1,5l nước đã ngâm rau câu và đường sau 10-15p ở trên vào nồi, đun sôi, vừa đun vừa khuấy đến khi sôi thì tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (4533, '2025-11-20 17:12:19.067156', '2025-11-20 17:12:19.067156', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 10, 'Lưu ý:Để trà sữa lên bọt nhanh, màu đẹp, nên cho vào bình thêm 2-3 viên đá, lắc thật mạnh.', 10);
INSERT INTO public.recipe_steps VALUES (4534, '2025-11-20 17:12:19.069168', '2025-11-20 17:12:19.069168', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 28, 'Đổ 1,5 lít nước ra một cái âu to, trộn bột rau câu với đường và đổ vào âu nước,hoà tan(để 10-15p cho rau câu nở)', 10);
INSERT INTO public.recipe_steps VALUES (4535, '2025-11-20 17:12:19.070744', '2025-11-20 17:12:19.070744', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 1, 'Cách pha trà', 10);
INSERT INTO public.recipe_steps VALUES (4537, '2025-11-20 17:12:19.073914', '2025-11-20 17:12:19.073914', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 44, 'Dùng một loại thìa hoặc muôi để múc cho đều, lần lượt múc hỗn hợp rau câu cà phê vào trước, để nguội rồi tiếp tục múc hỗn hợp cream cheese đổ lên trên (đổ khoảng 5 lớp, tránh dầy quá sẽ bị tách lớp khi hoàn thiện).', 10);
INSERT INTO public.recipe_steps VALUES (4538, '2025-11-20 17:12:19.075513', '2025-11-20 17:12:19.075513', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 5, 'Vớt túi lọc ra, cho sữa đặc vào khuấy tan.', 10);
INSERT INTO public.recipe_steps VALUES (4539, '2025-11-20 17:12:19.076579', '2025-11-20 17:12:19.076579', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 21, 'Đọc hướng dẫn ở mặt sau mỗi gói thạch để có tỉ lệ chuẩn.', 10);
INSERT INTO public.recipe_steps VALUES (4540, '2025-11-20 17:12:19.078157', '2025-11-20 17:12:19.078157', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 15, 'Đun sôi lại, tắt bếp và để phần thạch bớt nóng nhưng không để nguội, tránh bị đông. (Nếu không làm kịp mà thạch đông thì lại cho lên bếp để lửa thật nhỏ sẽ tan ra).', 10);
INSERT INTO public.recipe_steps VALUES (4541, '2025-11-20 17:12:19.079742', '2025-11-20 17:12:19.079742', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 25, 'Đợi thạch đông cho vào tủ lạnh (nếu khuôn như khay đá sau khi thạch lấy ra không phải xắt, còn nếu khuôn là hộp nhựa to thì khi làm các bạn xếp từng hàng hình dung sao cho sau dễ cắt thành miếng vuông nhỏ phía trong có miếng phomai).', 10);
INSERT INTO public.recipe_steps VALUES (4542, '2025-11-20 17:12:19.081432', '2025-11-20 17:12:19.081432', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 14, 'Khi nước sôi thì đổ từ từ gói bột thạch vào, vừa đổ vừa khuấy đều tránh vón cục.', 10);
INSERT INTO public.recipe_steps VALUES (4543, '2025-11-20 17:12:19.083018', '2025-11-20 17:12:19.083018', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 23, 'Đổ một lớp thạch mỏng vào khuôn, đợi cho nguội rồi đặt từng miếng pho mai con bò cười vào.', 10);
INSERT INTO public.recipe_steps VALUES (4544, '2025-11-20 17:12:19.084611', '2025-11-20 17:12:19.084611', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 9, 'Lọc bỏ bã, cho sữa đặc và sữa tươi vào khuấy đều.', 10);
INSERT INTO public.recipe_steps VALUES (4545, '2025-11-20 17:12:19.086207', '2025-11-20 17:12:19.086207', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 18, 'Vớt thạch ra rửa lại vài lần nước, cất tủ lạnh.', 10);
INSERT INTO public.recipe_steps VALUES (4546, '2025-11-20 17:12:19.087808', '2025-11-20 17:12:19.087808', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 7, 'Với trà khô:', 10);
INSERT INTO public.recipe_steps VALUES (4547, '2025-11-20 17:12:19.08983', '2025-11-20 17:12:19.08983', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 41, 'Khuấy đều là hoàn thiện ra câu cà phê.', 10);
INSERT INTO public.recipe_steps VALUES (4548, '2025-11-20 17:12:19.091399', '2025-11-20 17:12:19.091399', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 704, 45, 'Để vào tủ lạnh ngăn mát, khi ăn lấy dao nhẹ nhàng lách xung quanh rau câu rồi đổ ra đĩa rộng.', 10);
INSERT INTO public.recipe_steps VALUES (4549, '2025-11-20 17:12:19.381784', '2025-11-20 17:12:19.381784', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 705, 3, 'Đổ củ mã thầy đã sên màu củ dền vào bát to, đổ bột năng vào xóc cho bột năng bao đều xung quanh củ. (Các hạt sương sa bắt đầu khô ráo và tách rời nhau là được). Cho củ mã thầy vào rổ, rây cho sạch phần bột năng còn thừa.', 10);
INSERT INTO public.recipe_steps VALUES (4550, '2025-11-20 17:12:19.383381', '2025-11-20 17:12:19.383381', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 705, 8, 'Cho đường, bột béo, nước cốt dừa... và đậu vào máy xay sinh tố xay thật mịn. Bắc chảo lên bếp, để chế độ lửa trung bình, sên thêm một lúc cho đậu xanh hơi đặc lại. Đổ ra bát để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (4551, '2025-11-20 17:12:19.384973', '2025-11-20 17:12:19.384973', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 705, 2, 'Ngâm củ mã thầy vào nước cốt củ dền trong 15 phút, sau đó đổ vào chảo sên lửa vừa cho màu củ dền ngấm vào củ mã thầy, nhờ vậy, thành phẩm màu sương sa hạt lựu đẹp hơn. Sau khi thấy màu củ mã thầy chuyển sang màu hồng đậm hơn trước thì vớt ra cho ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (4552, '2025-11-20 17:12:19.387183', '2025-11-20 17:12:19.387183', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 705, 6, 'Mua sẵn thạch đen Cao Bằng hoặc thạch đen từ lá găng. Ngoài ra, mua sẵn gói bột làm thạch đen trong siêu thị về nấu theo hướng dẫn. Thạch nguội để ngăn mát tủ lạnh ít nhất 2h, đem ra cắt nhỏ theo ý thích.', 10);
INSERT INTO public.recipe_steps VALUES (4553, '2025-11-20 17:12:19.389293', '2025-11-20 17:12:19.389293', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 705, 1, 'Củ mã thầy gọt vỏ, thái hạt lựu. Củ dền gọt vỏ, cắt nhỏ xay nhuyễn lọc lấy nước cốt.', 10);
INSERT INTO public.recipe_steps VALUES (4554, '2025-11-20 17:12:19.390885', '2025-11-20 17:12:19.390885', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 705, 10, 'Khi ăn, múc thạch, sương sa hạt lựu, sương sáo, đậu xanh, đá bào, nước cốt dừa, trộn đều và thưởng thức', 10);
INSERT INTO public.recipe_steps VALUES (4555, '2025-11-20 17:12:19.392483', '2025-11-20 17:12:19.392483', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 705, 9, 'Trộn hỗn hợp gồm: 200ml nước cốt dừa, 3 thìa canh bột béo, 20gr đường, 15gr bột năng, 20ml nước trắng, 1/4 thìa cà phê muối tinh. Khuấy đều cho tan, để lửa nhỏ vừa, sôi lăn tăn là được, để nguội phần cốt dừa sẽ đặc sánh lại. Cốt dừa cho luôn phần bột béo vào sẽ thơm ngon, béo ngậy hơn (gói bột béo cũng mua trong siêu thị).', 10);
INSERT INTO public.recipe_steps VALUES (4556, '2025-11-20 17:12:19.394151', '2025-11-20 17:12:19.394151', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 705, 4, 'Đem luộc chín vớt ra bát nước lạnh, khi luộc thấy phần sương sa hạt lựu nổi lên là chín. Vớt ra bát nước lạnh, phần sương sa hạt lựu trong suốt có màu hồng bên trong là đạt.', 10);
INSERT INTO public.recipe_steps VALUES (4557, '2025-11-20 17:12:19.395777', '2025-11-20 17:12:19.395777', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 705, 5, 'Tương tự làm phần sương sa màu lá nếp hay lá dứa cũng như trên: chỉ xay phần lá thêm chút nước và lọc lấy nước cốt, hoặc nếu lấy màu vàng từ hạt dành dành thì ngâm hạt này với nước sôi già, lọc lấy nước sau khi màu vàng đã tiết ra.', 10);
INSERT INTO public.recipe_steps VALUES (4558, '2025-11-20 17:12:19.397402', '2025-11-20 17:12:19.397402', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 705, 7, 'Đậu xanh vo thật sạch, ngâm nước ít nhất 2 giờ. Cho đậu vào nồi thêm 400ml nước, nấu chín mềm.', 10);
INSERT INTO public.recipe_steps VALUES (4559, '2025-11-20 17:12:19.513201', '2025-11-20 17:12:19.513201', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 706, 6, 'Phần nước tía tô còn lại cho vào chai đậy nắp kín bảo quản trong tủ lạnh uống dần.', 10);
INSERT INTO public.recipe_steps VALUES (4560, '2025-11-20 17:12:19.514756', '2025-11-20 17:12:19.514756', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 706, 1, 'Cành tía tô cắt lấy lá. Rửa thật sạch, ngâm qua nước muối loãng rồi để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (4561, '2025-11-20 17:12:19.516366', '2025-11-20 17:12:19.516366', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 706, 3, 'Cho 500g đường phèn vào nồi nước tía tô, nấu lửa nhỏ khuấy đều cho đường tan hết. Nếu không có đường phèn, thay thế bằng đường cát trắng. Nấu cho nước sôi nhẹ khoảng 3 phút thì tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (4562, '2025-11-20 17:12:19.517422', '2025-11-20 17:12:19.517422', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 706, 4, 'Cho nước cốt chanh vào nồi nước tía tô và khuấy đều, nước sẽ chuyển màu rất đẹp.', 10);
INSERT INTO public.recipe_steps VALUES (4563, '2025-11-20 17:12:19.518467', '2025-11-20 17:12:19.518467', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 706, 2, 'Cho 2 lít nước vào nồi, đun sôi. Cho lá tía tô vào, nấu khoảng 3- 5 phút cho lá ra hết màu (chỉ còn lại màu xanh) thì vớt ra.', 10);
INSERT INTO public.recipe_steps VALUES (4564, '2025-11-20 17:12:19.52006', '2025-11-20 17:12:19.52006', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 706, 5, 'Để nước thật nguội, khi uống cho thêm vài cục đá vào ly rồi cho nước lá tía tô vào thưởng thức. Có thể cho thêm nước có gas tùy theo sở thích.', 10);
INSERT INTO public.recipe_steps VALUES (4565, '2025-11-20 17:12:19.779791', '2025-11-20 17:12:19.779791', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 707, 7, 'Màu hoa đậu biếc: cho vào bát thứ 2: 65 gram bột gạo tẻ, 20 gram bột năng, 45 gram đường cát trắng, 25ml nước hoa đậu biếc, 100ml nước cốt dừa sau đó cho nửa phần men nở còn lại vào và trộn đều lên. Lọc qua rây để hỗn hợp bột được mịn hơn. Dùng màng bọc thực phẩm bọc lại để bột nghỉ trong 1,5 tiếng.', 10);
INSERT INTO public.recipe_steps VALUES (4566, '2025-11-20 17:12:19.781367', '2025-11-20 17:12:19.781367', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 707, 14, 'Khi bánh chính bạn dùng mũi dao để tách bánh ra, để hấp dẫn hơn có thể ăn kèm cùng nước cốt dừa và mè rang.', 10);
INSERT INTO public.recipe_steps VALUES (4567, '2025-11-20 17:12:19.782953', '2025-11-20 17:12:19.782953', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 707, 9, 'Nước lá dứa: Dùng 8 gram lá dứa đổ cho 30ml nước lọc vào máy xay nhuyễn, lọc qua rây thu được 25ml nước lá dứa.', 10);
INSERT INTO public.recipe_steps VALUES (4568, '2025-11-20 17:12:19.784006', '2025-11-20 17:12:19.784006', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 707, 1, 'Bước 1:Sơ chế men nở', 10);
INSERT INTO public.recipe_steps VALUES (4569, '2025-11-20 17:12:19.785063', '2025-11-20 17:12:19.785063', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 707, 12, 'Bột sau khi nghỉ 1,5 tiếng mở màng bọc và khuấy đều bột. Chuẩn bị khuôn để hấp (nếu không có khuôn có thể thay bằng các chén đựng nước chấm) quét sơ qua một ít dầu lên khuôn sau đó đặt lên xửng và cho vào nồi hấp nóng khuôn lên. Khi nước trong nồi sôi lên đổ lần lượt phần hỗn hợp bột vào khuôn và hấp trên lửa vừa khoảng 7 phút khi bánh trong là được.', 10);
INSERT INTO public.recipe_steps VALUES (4570, '2025-11-20 17:12:19.786684', '2025-11-20 17:12:19.786684', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 707, 5, 'Chuẩn bị hai cái bát và chia đều các nguyên liệu ra làm hai phần bằng nhau:', 10);
INSERT INTO public.recipe_steps VALUES (4571, '2025-11-20 17:12:19.788266', '2025-11-20 17:12:19.788266', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 707, 3, 'Sau khi men nghỉ 10 phút mở ra và trộn đều lên cho thêm 1 thìa cà phê muối khuấy đều.', 10);
INSERT INTO public.recipe_steps VALUES (4572, '2025-11-20 17:12:19.789841', '2025-11-20 17:12:19.789841', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 707, 10, 'Nước hoa đậu biếc: Dùng 5 lá khô hoa đậu biếc, đổ vào 25ml nước sôi ngâm trong 10 phút. Sau khi nước chuyển sang màu hoa đậu biếc là được.', 10);
INSERT INTO public.recipe_steps VALUES (4573, '2025-11-20 17:12:19.790894', '2025-11-20 17:12:19.790894', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 707, 2, 'Chuẩn bị 50 ml nước ấm cho vào 10 gram đường và trộn đều cho tan đường, thêm vào 2 gram men nở sau đó khuấy đều. Dùng màng bọc thực phẩm bọc lại để nghỉ trong 10 phút.', 10);
INSERT INTO public.recipe_steps VALUES (4574, '2025-11-20 17:12:19.792468', '2025-11-20 17:12:19.792468', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 707, 13, 'Bước 4:Hoàn thành và thưởng thức', 10);
INSERT INTO public.recipe_steps VALUES (4575, '2025-11-20 17:12:19.794058', '2025-11-20 17:12:19.794058', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 707, 4, 'Bước 2:Ủ bột', 10);
INSERT INTO public.recipe_steps VALUES (4576, '2025-11-20 17:12:19.795149', '2025-11-20 17:12:19.795149', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 707, 8, 'Lưu ý khi sơ chế nước lá dứa và nước hoa đậu biếc:', 10);
INSERT INTO public.recipe_steps VALUES (4577, '2025-11-20 17:12:19.796234', '2025-11-20 17:12:19.796234', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 707, 11, 'Bước 3:Hấp bánh', 10);
INSERT INTO public.recipe_steps VALUES (4578, '2025-11-20 17:12:19.797861', '2025-11-20 17:12:19.797861', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 707, 6, 'Màu xanh lá dứa: cho vào bát thứ nhất: 65 gram bột gạo tẻ, 20 gram bột năng, 45 gram đường cát trắng, 25ml nước lá dứa, 100ml nước cốt dừa sau đó cho nửa phần men nở đã trộn đều vào và trộn đều lên. Lọc qua rây để hỗn hợp bột được mịn hơn. Dùng màng bọc thực phẩm bọc lại để bột nghỉ trong 1,5 tiếng.', 10);
INSERT INTO public.recipe_steps VALUES (4579, '2025-11-20 17:12:20.322665', '2025-11-20 17:12:20.322665', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 708, 3, 'Chú ý:Không được dùng tay để trộn vì nhiệt ở tay làm chảy bơ sẽ không thành công.', 10);
INSERT INTO public.recipe_steps VALUES (4580, '2025-11-20 17:12:20.324271', '2025-11-20 17:12:20.324271', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 708, 1, 'Bơ lạt cắt nhỏ, càng nhỏ càng tốt.', 10);
INSERT INTO public.recipe_steps VALUES (4581, '2025-11-20 17:12:20.326014', '2025-11-20 17:12:20.326014', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 708, 7, 'Bột sau khi để lạnh một tiếng lấy ra cán mỏng, gấp lại làm 3, xoay chiều rồi tiếp tục cán mỏng gấp lại làm 3, bọc kín rồi cho vào ngăn mát tủ lạnh để một tiếng. Cứ làm như vậy 4 lần.', 10);
INSERT INTO public.recipe_steps VALUES (4582, '2025-11-20 17:12:20.327602', '2025-11-20 17:12:20.327602', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 708, 8, 'Để tạo hình quả táo sử dụng vỏ giấy hộp sữa tươi vẽ hình quả táo rồi cắt ra.', 10);
INSERT INTO public.recipe_steps VALUES (4583, '2025-11-20 17:12:20.32918', '2025-11-20 17:12:20.32918', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 708, 12, 'Xếp đều táo lên giữa bột bánh đã được tạo hình.', 10);
INSERT INTO public.recipe_steps VALUES (4584, '2025-11-20 17:12:20.330239', '2025-11-20 17:12:20.330239', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 708, 11, 'Dùng nĩa xăm lên phần đế bánh để cho không khí thoát ra, làm cho bánh giòn hơn.', 10);
INSERT INTO public.recipe_steps VALUES (4585, '2025-11-20 17:12:20.331841', '2025-11-20 17:12:20.331841', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 708, 13, 'Khuấy tan lòng đỏ trứng gà và sữa. Dùng cọ quét đều hỗn hợp này lên phần bột vành, lá của bánh.', 10);
INSERT INTO public.recipe_steps VALUES (4586, '2025-11-20 17:12:20.333444', '2025-11-20 17:12:20.333444', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 708, 4, 'Cho đường, muối vào một ca nước lạnh khuấy tan.', 10);
INSERT INTO public.recipe_steps VALUES (4587, '2025-11-20 17:12:20.335037', '2025-11-20 17:12:20.335037', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 708, 10, 'Bột cắt thành hình quả táo theo mẫu giấy đã được cắt. Dùng phần mềm của đầu ngón tay ấn nhẹ lên phần bột tạo thành vành cho táo. Tạo lá, cuống táo từ bột tùy theo sở thích.', 10);
INSERT INTO public.recipe_steps VALUES (4588, '2025-11-20 17:12:20.336219', '2025-11-20 17:12:20.336219', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 708, 2, 'Sử dụng bột mì đa dụng, có thể thay thế bằng 1/2 bột mì làm bánh ngọt và 1/2 bột mì làm bánh mì. Cho vào thau có bơ đã cắt nhỏ. Dùng phới trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (4589, '2025-11-20 17:12:20.337808', '2025-11-20 17:12:20.337808', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 708, 9, 'Bột sau khi đã nghỉ mát 4 lần (4 lần cán) đem ra cán mỏng (độ dày của đế tuỳ thích) .', 10);
INSERT INTO public.recipe_steps VALUES (4590, '2025-11-20 17:12:20.339434', '2025-11-20 17:12:20.339434', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 708, 5, 'Đổ hỗn hợp nước vào thau bột đang trộn. Nên chia nước ra làm 3 lần cho vào từ từ. Trộn đều thành khối. Bọc màng bọc thực phẩm cán mỏng bột, cho vào ngăn mát tủ lạnh để bột nghỉ 1 tiếng.', 10);
INSERT INTO public.recipe_steps VALUES (4591, '2025-11-20 17:12:20.341098', '2025-11-20 17:12:20.341098', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 708, 6, 'Táo bỏ phần cuống và ruột, thái lát mỏng, cho vào thau. Đường, bột quế trộn đều rắc lên táo, sau đó rưới cốt chanh và rượu rum lên táo. Dùng màng bọc thực phẩm đậy kín chậu táo, cho vào lò vi sóng quay 800W trong 6 phút. Lấy ra để nguội rồi cho vào ngăn mát tủ lạnh chờ làm bột.', 10);
INSERT INTO public.recipe_steps VALUES (4592, '2025-11-20 17:12:20.342706', '2025-11-20 17:12:20.342706', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 708, 14, 'Nướng 210°C từ 15-17phút.', 10);
INSERT INTO public.recipe_steps VALUES (4594, '2025-11-20 17:12:20.875689', '2025-11-20 17:12:20.875689', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 709, 2, 'Chuẩn bị lọ/hũ thủy tinh sạch (rửa sạch, tráng qua nước sôi rồi úp ngược cho khô ráo).', 10);
INSERT INTO public.recipe_steps VALUES (4595, '2025-11-20 17:12:20.877442', '2025-11-20 17:12:20.877442', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 709, 4, 'Sau 10-15 ngày thì tinh dầu từ cánh hoa bưởi tiết ra quyện với đường tạo nên hỗn hợp siro sánh, trong và có vị hơi đắng (đây là tinh dầu hoa bưởi, rất tốt cho giải cảm, thanh nhiệt).', 10);
INSERT INTO public.recipe_steps VALUES (4596, '2025-11-20 17:12:20.879634', '2025-11-20 17:12:20.879634', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 709, 11, 'Trà hoa bưởi:', 10);
INSERT INTO public.recipe_steps VALUES (4597, '2025-11-20 17:12:20.88178', '2025-11-20 17:12:20.88178', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 709, 22, 'Cho mía vào hộp cùng các cánh hoa bưởi đã sơ chế rồi đậy nắp cho vào ngăn mát tủ lạnh 1 tiếng.', 10);
INSERT INTO public.recipe_steps VALUES (4598, '2025-11-20 17:12:20.883373', '2025-11-20 17:12:20.883373', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 709, 10, 'Mật ong ngâm hoa bưởi có tác dụng bị viêm họng, tiêu đờm hoặc pha loãng với nước ấm, pha trà đều rất tốt.', 10);
INSERT INTO public.recipe_steps VALUES (4599, '2025-11-20 17:12:20.884963', '2025-11-20 17:12:20.884963', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 709, 14, 'Cách ướp: Lót lớp giấy báo bên dưới thạp gốm, sứ để hút ẩm. Sau đó, lần lượt cho rải một lớp trà và lớp cánh hoa mỏng xen kẽ cho tới khi hết. Trên cùng phủ lớp giấy báo, đậy nắp.', 10);
INSERT INTO public.recipe_steps VALUES (4600, '2025-11-20 17:12:20.886539', '2025-11-20 17:12:20.886539', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 709, 15, 'Khoảng 2-3 tiếng thì đảo trà để bay bớt hơi ẩm, ướp tối thiểu 8 tiếng hoặc tốt nhất 2 ngày.', 10);
INSERT INTO public.recipe_steps VALUES (4601, '2025-11-20 17:12:20.888128', '2025-11-20 17:12:20.888128', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 709, 8, 'Cách làm cũng tương tự như ướp đường nhưng tỷ lệ hoa bưởi ít hơn vì chủ yếu là lấy mùi hương và chút tinh dầu từ hoa bưởi.', 10);
INSERT INTO public.recipe_steps VALUES (4602, '2025-11-20 17:12:20.889722', '2025-11-20 17:12:20.889722', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 709, 18, 'Chú ý: Nên bỏ phần nhụy chứa nước khi ủ dễ bị thối nhũn, làm trà bị đắng, mùi ôi.', 10);
INSERT INTO public.recipe_steps VALUES (4603, '2025-11-20 17:12:20.89133', '2025-11-20 17:12:20.89133', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 709, 12, 'Chọn trà loại ngon, khô ráo.', 10);
INSERT INTO public.recipe_steps VALUES (4604, '2025-11-20 17:12:20.893488', '2025-11-20 17:12:20.893488', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 709, 16, 'Sau khi ướp thì nhặt bỏ hoa và sấy khô bằng chảo gang ở nhiệt độ tầm 90 độ hoặc máy sấy trà chuyên dụng.', 10);
INSERT INTO public.recipe_steps VALUES (4605, '2025-11-20 17:12:20.895101', '2025-11-20 17:12:20.895101', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 709, 13, 'Tỷ lệ ướp hoa bưởi và trà là 1:3.', 10);
INSERT INTO public.recipe_steps VALUES (4606, '2025-11-20 17:12:20.89722', '2025-11-20 17:12:20.89722', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 709, 6, 'Hoa bưởi ướp mật ong:', 10);
INSERT INTO public.recipe_steps VALUES (4607, '2025-11-20 17:12:20.899346', '2025-11-20 17:12:20.899346', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 709, 21, 'Dùng dao róc vỏ, tiện thành những miếng nhỏ, chẻ làm ba hoặc bốn.', 10);
INSERT INTO public.recipe_steps VALUES (4608, '2025-11-20 17:12:20.900943', '2025-11-20 17:12:20.900943', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 709, 3, 'Lần lượt cho 1 lớp hoa bưởi và 1 lớp đường xen kẽ nhau theo tỷ lệ 1:1 hoặc phần đường nhiều hơn chút. Trên cùng phủ một lớp đường.', 10);
INSERT INTO public.recipe_steps VALUES (4609, '2025-11-20 17:12:20.902546', '2025-11-20 17:12:20.902546', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 709, 5, 'Dùng rây lọc lấy nước siro này và lưu giữ ngăn mát tủ lạnh, dùng quanh năm cho các món: Tào phớ, chè, nước uống.', 10);
INSERT INTO public.recipe_steps VALUES (4610, '2025-11-20 17:12:20.904681', '2025-11-20 17:12:20.904681', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 709, 19, 'Mía ướp hoa bưởi:', 10);
INSERT INTO public.recipe_steps VALUES (4611, '2025-11-20 17:12:20.906268', '2025-11-20 17:12:20.906268', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 709, 9, 'Cho hoa bưởi vào lọ thủy tinh sạch, đổ mật ong vào ngâm 7-10 ngày là hoa se lại. Bạn có thể vớt cánh hoa ra hoặc để lại, bảo quản ngăn mát tủ lạnh dùng dần.', 10);
INSERT INTO public.recipe_steps VALUES (4612, '2025-11-20 17:12:20.908112', '2025-11-20 17:12:20.908112', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 709, 1, 'Siro tinh dầu hoa bưởi:', 10);
INSERT INTO public.recipe_steps VALUES (4613, '2025-11-20 17:12:20.910215', '2025-11-20 17:12:20.910215', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 709, 7, 'Nên chọn mật ong rừng nguyên chất.', 10);
INSERT INTO public.recipe_steps VALUES (4614, '2025-11-20 17:12:20.911818', '2025-11-20 17:12:20.911818', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 709, 20, 'Mía chọn khúc to tròn, thẳng, không bị sâu hay nứt và ở giữa sẽ mềm, ngọt ngon nhất.', 10);
INSERT INTO public.recipe_steps VALUES (4615, '2025-11-20 17:12:21.439447', '2025-11-20 17:12:21.439447', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 710, 1, 'Bước 1:Sơ chế đậu xanh, khoai lang', 10);
INSERT INTO public.recipe_steps VALUES (4616, '2025-11-20 17:12:21.441025', '2025-11-20 17:12:21.441025', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 710, 3, 'Hấp đậu xanh và khoai lang trong khoảng 20-25 phút, để nguội rồi rây nhuyễn khoai lang, riêng đậu xanh cho vào máy xay cùng ít nước (khoảng 20ml nước ấm).', 10);
INSERT INTO public.recipe_steps VALUES (4617, '2025-11-20 17:12:21.442609', '2025-11-20 17:12:21.442609', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 710, 11, 'Bước 4:Nấu chè', 10);
INSERT INTO public.recipe_steps VALUES (4618, '2025-11-20 17:12:21.444215', '2025-11-20 17:12:21.444215', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 710, 10, 'Chuẩn bị 1 lít nước đổ vào nồi và cho 200 gram đường thốt nốt thêm 1 thìa cà phê muối đun sôi cho tan đường. Cho thêm gừng đã thái sợi, 1 ít lá dứa vào đun đến khi thấy gừng đã trong hơn và mùi gừng tỏa khắp thì vớt lá dứa ra ngoài.', 10);
INSERT INTO public.recipe_steps VALUES (4619, '2025-11-20 17:12:21.446468', '2025-11-20 17:12:21.446468', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 710, 14, 'Sau khi nồi chè trôi nước đã được nấu xong, múc chè ra chén cùng với nước đường, gừng và thêm vào một ít dừa thái sợi, rắc một ít mè, chan thêm một ít nước cốt dừa lên trên là có thể thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (4620, '2025-11-20 17:12:21.448046', '2025-11-20 17:12:21.448046', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 710, 5, 'Bước 2:Nhồi bột và tạo hình viên chè', 10);
INSERT INTO public.recipe_steps VALUES (4621, '2025-11-20 17:12:21.449616', '2025-11-20 17:12:21.449616', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 710, 7, 'Tiếp theo chia nhỏ bột ra từng phần và vo tròn lại. Cho đậu xanh vào chính giữa bột bánh, nặn thật khéo để làm sao phần nhân không bị lộ và rơi ra ngoài khi luộc. Nếu phần bột còn dư thì có thể vo thành những viên tròn không nhân.', 10);
INSERT INTO public.recipe_steps VALUES (4622, '2025-11-20 17:12:21.451213', '2025-11-20 17:12:21.451213', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 710, 8, 'Bước 3:Nấu nước cốt dừa, nước gừng', 10);
INSERT INTO public.recipe_steps VALUES (4623, '2025-11-20 17:12:21.452801', '2025-11-20 17:12:21.452801', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 710, 6, 'Cho từ từ 250ml nước ấm vào 350 gram bột, cho thêm ¼ thìa cà phê muối, 50 gram khoai lang vào, nhồi bột đến khi bột không còn dính trên tay. Sau đó dùng màng bọc thực phẩm ủ bột trong khoảng thời gian 20 phút nếu có thời gian ủ càng lâu thì viên chè sẽ càng ngon hơn.', 10);
INSERT INTO public.recipe_steps VALUES (4624, '2025-11-20 17:12:21.453873', '2025-11-20 17:12:21.453873', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 710, 13, 'Bước 6:Hoàn thành và thưởng thức chè trôi nước', 10);
INSERT INTO public.recipe_steps VALUES (4625, '2025-11-20 17:12:21.456442', '2025-11-20 17:12:21.456442', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 710, 2, 'Đậu xanh rửa sạch, tốt nhất nên mua đậu xanh đã cà hết vỏ xanh bên ngoài. Ngâm đậu xanh trong nước nóng từ 1 đến 2 tiếng, khoai lang cạo sạch vỏ.', 10);
INSERT INTO public.recipe_steps VALUES (4626, '2025-11-20 17:12:21.457551', '2025-11-20 17:12:21.457551', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 710, 12, 'Thả hết số viên chè đã làm vào nồi, đun trong khoảng thời gian từ 10-15 phút đến khi thấy những viên chè nổi lên trên mặt nước và đường đã thấm vào từng viên chè thì tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (4627, '2025-11-20 17:12:21.460152', '2025-11-20 17:12:21.460152', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 710, 4, 'Bắc chảo lên bếp cho đậu xanh đã rây nhuyễn vào sên trên lửa vừa, cho tiếp 80ml nước cốt dừa, 2 thìa canh đường, dừa thái sợi vào sên cùng, nêm nếm chút muối sao cho hợp khẩu vị. Sên đến khi thấy phần đậu xanh đã thành khối dẻo, mịn thì sau đó tắt bếp. Cho đậu xanh ra bát, để nguội rồi vò thành những viên nhỏ để làm nhân bánh (khoảng 2- 3 cm). Dùng màng bọc thực phẩm bọc lại để phần nhân không bị khô.', 10);
INSERT INTO public.recipe_steps VALUES (4628, '2025-11-20 17:12:21.461196', '2025-11-20 17:12:21.461196', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 710, 15, 'Lưu ý: Mỗi người sẽ có khẩu vị và sở thích khác nhau nên bạn có thể điều chỉnh lượng đường hoặc gừng cho vào thật phù hợp.', 10);
INSERT INTO public.recipe_steps VALUES (4629, '2025-11-20 17:12:21.463224', '2025-11-20 17:12:21.463224', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 710, 9, 'Đổ 120ml nước cốt dừa vào nồi cho thêm 100ml nước lọc, ½ thìa cà phê muối, 1 thìa canh bột năng giúp cho phần nước cốt được sánh hơn không bị béo và quá ngậy. Đảo đều và đun trên lửa vừa đến khi phần nước cốt sôi nhẹ thì tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (4630, '2025-11-20 17:12:21.610699', '2025-11-20 17:12:21.610699', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 711, 3, 'Trứng đánh tan cùng với 1 thìa cà phê nước mắm, 1/2 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu cho đậm vị.', 10);
INSERT INTO public.recipe_steps VALUES (4631, '2025-11-20 17:12:21.612286', '2025-11-20 17:12:21.612286', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 711, 2, 'Tỏi băm nhỏ, hành lá và rau mùi rửa sạch thái khúc. Ớt bỏ hạt thái vát (nếu nhà có trẻ nhỏ không nên cho ớt).', 10);
INSERT INTO public.recipe_steps VALUES (4632, '2025-11-20 17:12:21.613349', '2025-11-20 17:12:21.613349', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 711, 1, 'Bầu gọt bỏ vỏ, tùy theo sở thích có thể cắt khúc hoặc băm dọc rồi thái sợi nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (4633, '2025-11-20 17:12:21.61502', '2025-11-20 17:12:21.61502', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 711, 4, 'Phi thơm gốc hành trắng, cho trứng vào khuấy đều cho săn và tơi mảnh rồi múc ra để riêng. Tiếp tục phi thơm tỏi, cho bầu xào trên lửa lớn, nêm nếm gia vị mắm, muối, hạt nêm cho vừa miệng. Khi bầu chín tái thì trút trứng vào đảo đều, thêm hành lá, rau mùi, rắc chút hạt tiêu tắt bếp. Múc bầu xào trứng ra đĩa và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (4634, '2025-11-20 17:12:21.616647', '2025-11-20 17:12:21.616647', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 711, 5, 'Yêu cầu thành phẩm: Đĩa bầu xào trứng khô ráo nước, không bị nhũn. Bầu chín tới, thanh mát quyện với trứng bùi bùi, dậy mùi thơm của hành lá, tỏi.', 10);
INSERT INTO public.recipe_steps VALUES (4635, '2025-11-20 17:12:21.698919', '2025-11-20 17:12:21.698919', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 712, 2, 'Trứng lấy 6 lòng đỏ + cả 4 quả + 150 g đường. Đánh tan hỗn hợp trên rồi đổ sữa vào khuấy đều, lọc qua lưới lọc, sau đó đổ vào cốc đã có đường caramel.', 10);
INSERT INTO public.recipe_steps VALUES (4636, '2025-11-20 17:12:21.700526', '2025-11-20 17:12:21.700526', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 712, 3, 'Cho các hộp vào chõ hấp, từ lúc sôi đến khi chín là khoảng 7 phút. Đổ ngược chiếc cốc lên đĩa sẽ được món caramel rất đẹp mắt.', 10);
INSERT INTO public.recipe_steps VALUES (4637, '2025-11-20 17:12:21.702727', '2025-11-20 17:12:21.702727', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 712, 1, 'Cho một ít nước vào 100 g đường, đun sôi tới khi đường có màu vàng nâu thành đường caramel thì cho ra các khuôn (cốc).', 10);
INSERT INTO public.recipe_steps VALUES (4638, '2025-11-20 17:12:21.922194', '2025-11-20 17:12:21.922194', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 713, 4, 'Yêu cầu thành phẩm
INSERT INTO public.recipe_steps VALUES (4639, '2025-11-20 17:12:21.923808', '2025-11-20 17:12:21.923808', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 713, 2, 'Tẩm ướp
INSERT INTO public.recipe_steps VALUES (4640, '2025-11-20 17:12:21.924841', '2025-11-20 17:12:21.924841', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 713, 1, 'Sơ chế
INSERT INTO public.recipe_steps VALUES (4641, '2025-11-20 17:12:21.926494', '2025-11-20 17:12:21.926494', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 713, 3, 'Chế biến
INSERT INTO public.recipe_steps VALUES (4642, '2025-11-20 17:12:22.232725', '2025-11-20 17:12:22.232725', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 714, 1, 'a) Chuẩn bị và sơ chế nguyên liệu:Cơm đánh tơi, thêm dầu mè, chút bột canh và vừng rang, trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (4643, '2025-11-20 17:12:22.234318', '2025-11-20 17:12:22.234318', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 714, 11, 'Sau đó, gập cạnh đầu tiên theo lát cát rồi gập tiếp theo chiều kim đồng hồ cho tới khi hoàn thành ở cả 4 góc.', 10);
INSERT INTO public.recipe_steps VALUES (4644, '2025-11-20 17:12:22.235906', '2025-11-20 17:12:22.235906', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 714, 12, 'Dùng màng bọc thực phẩm quấn gói chặt lại, dùng dao sắc cắt đôi và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (4645, '2025-11-20 17:12:22.237493', '2025-11-20 17:12:22.237493', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 714, 9, 'Đặt tấm rong biển lên, ước lượng chia 4 phần đều nhau, rồi dùng kéo cắt ở giữa một cạnh (1/2 phần tấm rong biển).', 10);
INSERT INTO public.recipe_steps VALUES (4646, '2025-11-20 17:12:22.239077', '2025-11-20 17:12:22.239077', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 714, 7, 'Kim chi cắt miếng vừa ăn, xào chín.', 10);
INSERT INTO public.recipe_steps VALUES (4647, '2025-11-20 17:12:22.240147', '2025-11-20 17:12:22.240147', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 714, 4, 'Trứng đánh tan với chút mắm muối, hạt nêm rồi rán mỏng, cắt hình vuông (có cạnh bằng 1/4 miếng rong biển).', 10);
INSERT INTO public.recipe_steps VALUES (4648, '2025-11-20 17:12:22.241751', '2025-11-20 17:12:22.241751', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 714, 10, 'Lần lượt cho cơm vào 1 góc và dàn mỏng, tiếp đến cho thịt Spam, rau xà lách, dưa chuột, trứng, kim chi dàn đều ở các góc còn lại (xem ảnh cách gập). Chú ý cho các nguyên liệu với số lượng vừa phải, đừng quá nhiều.', 10);
INSERT INTO public.recipe_steps VALUES (4649, '2025-11-20 17:12:22.243362', '2025-11-20 17:12:22.243362', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 714, 5, 'Thịt Spam cắt thành từng lát, chiên chín vàng.', 10);
INSERT INTO public.recipe_steps VALUES (4650, '2025-11-20 17:12:22.244973', '2025-11-20 17:12:22.244973', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 714, 3, 'Rau xà lách nhặt rửa sạch, ngâm nước muối loãng, vớt ra vẩy ráo.', 10);
INSERT INTO public.recipe_steps VALUES (4651, '2025-11-20 17:12:22.246568', '2025-11-20 17:12:22.246568', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 714, 6, 'Cà rốt cắt hình que diêm hoặc tỉa hoa tùy thích, luộc chín.', 10);
INSERT INTO public.recipe_steps VALUES (4652, '2025-11-20 17:12:22.248289', '2025-11-20 17:12:22.248289', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 714, 8, 'b) Cách làm kimbap gấp:Đặt màng bọc thực phẩm trên đĩa vuông.', 10);
INSERT INTO public.recipe_steps VALUES (4653, '2025-11-20 17:12:22.249862', '2025-11-20 17:12:22.249862', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 714, 2, 'Dưa chuột rửa sạch, ngâm nước muối loãng, cắt miếng vừa ăn hoặc bào mỏng tùy chọn.', 10);
INSERT INTO public.recipe_steps VALUES (4654, '2025-11-20 17:12:22.436653', '2025-11-20 17:12:22.436653', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 715, 1, 'Lá hẹ nhặt rửa sạch, xắt khúc, để ráo. Đậu hũ dằm nát, trộn đều với thịt heo băm, nêm hạt nêm, hành khô, đường, viên thành những viên tròn.', 10);
INSERT INTO public.recipe_steps VALUES (4655, '2025-11-20 17:12:22.438249', '2025-11-20 17:12:22.438249', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 715, 2, 'Cho nước lạnh vào nồi, đun sôi, thả viên thịt đậu hũ, cho lá hẹ vào, nêm hạt nêm, múc ra tô, rắc tiêu.', 10);
INSERT INTO public.recipe_steps VALUES (4656, '2025-11-20 17:12:22.62899', '2025-11-20 17:12:22.62899', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 716, 3, 'Giá đỗ rửa sạch, thịt nạc vai luộc chín, thái chỉ, ướp hạt tiêu, muối.', 10);
INSERT INTO public.recipe_steps VALUES (4657, '2025-11-20 17:12:22.630694', '2025-11-20 17:12:22.630694', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 716, 6, 'Bày ra đĩa, 1/2 thịt, rau thơm, rau mùi, hoa ớt lên trên.', 10);
INSERT INTO public.recipe_steps VALUES (4658, '2025-11-20 17:12:22.631781', '2025-11-20 17:12:22.631781', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 716, 5, 'Cho hoa chuối, giá đỗ, 1/2 thịt, tai lợn, ớt vào liễn rưới nước mắm, chanh, đường, muối, rau thơm, mùi thái nhỏ, cuối cùng trộn đều lạc, vừng.', 10);
INSERT INTO public.recipe_steps VALUES (4659, '2025-11-20 17:12:22.633405', '2025-11-20 17:12:22.633405', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 716, 1, 'Hoa chuối sơ chế sạch, thái mỏng ngâm nước có pha dấm, ngâm 15 phút vớt ra để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (4660, '2025-11-20 17:12:22.635006', '2025-11-20 17:12:22.635006', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 716, 2, 'Tai lợn sơ chế luộc chín, thái mỏng, ướp hạt tiêu, muối, lá chanh, nước cốt chanh.', 10);
INSERT INTO public.recipe_steps VALUES (4661, '2025-11-20 17:12:22.636711', '2025-11-20 17:12:22.636711', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 716, 4, 'Lạc, vừng rang vàng, sát vỏ, giã dập, ớt bỏ hạt băm nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (4662, '2025-11-20 17:12:23.119751', '2025-11-20 17:12:23.119751', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 717, 2, 'Cà rốt, su hào gọt vỏ rửa sạch, xắt lát dùng dao hoặc khuôn nhôm ấn thành hình ngôi sao hay hoa hồng, trụng vừa chín. Đậu đỏ luộc chín. Nem, chả quế, giò thủ, jambon bò cắt hình ngôi sao hay hoa hồng.', 10);
INSERT INTO public.recipe_steps VALUES (4663, '2025-11-20 17:12:23.12134', '2025-11-20 17:12:23.12134', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 717, 3, 'Dùng khuôn hoa hồng đổ một lớp rau câu vào khoảng 5 mm, để ngay lên nước đá hoặc tủ lạnh cho rau câu hơi cứng mình. Xếp cà rốt, su hào, nem, chả quế, jambon bò, giò thủ tuỳ ý sao cho đẹp và hình hoa xòe cánh rắc đậu đỏ rải rác, chế rau câu vào cho đầy khuôn.', 10);
INSERT INTO public.recipe_steps VALUES (4664, '2025-11-20 17:12:23.123535', '2025-11-20 17:12:23.123535', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 717, 1, 'Nước dùng nấu từ xương gà hoặc heo phải thật trong, nêm muối, tiêu trắng vừa miệng ăn. Ngâm 10 g rau câu bột trong 200 ml nước lọc cho tan, bắc lên bếp. Hòa chung 500 ml nước dùng vào nước rau câu.', 10);
INSERT INTO public.recipe_steps VALUES (4665, '2025-11-20 17:12:23.125136', '2025-11-20 17:12:23.125136', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 717, 4, 'Chừng 20 phút là lấy rau câu bày ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (4666, '2025-11-20 17:12:23.606434', '2025-11-20 17:12:23.606434', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 718, 2, 'Trộn 1 muỗng canh giấm, 1/2 muỗng canh đường và 1/4 muỗng canh muối đến khi đường và muối tan hết trong giấm. Tiếp theo, trộn đều cơm nóng với giấm và 1 muỗng dầu mè. Sau đó, dùng khăn ẩm đậy cơm lại, để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (4667, '2025-11-20 17:12:23.608025', '2025-11-20 17:12:23.608025', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 718, 4, 'Cắt kimbap thành những khoanh tròn vừa ăn, xếp ra đĩa sao cho đẹp mắt. Rắc thêm mè rang lên mặt. Món kimbap chấm với tương ớt, tương cà hoặc sốt mayonnaise.', 10);
INSERT INTO public.recipe_steps VALUES (4668, '2025-11-20 17:12:23.610666', '2025-11-20 17:12:23.610666', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 718, 1, 'Dưa leo rửa sạch, bỏ ruột thái sợi nhỏ hoặc thái thành thanh dài tuỳ thích. Cá ngừ vớt ra chén, thêm 2 muỗng canh sốt mayonnaise vào trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (4669, '2025-11-20 17:12:23.61279', '2025-11-20 17:12:23.61279', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 718, 3, 'Đặt mành tre lên trên một mặt phẳng sạch, sau đó đặt lá rong biển lên (chú ý hướng mặt nhám của rong biển lên trên). Tiếp theo, trải đều một lớp cơm mỏng lên trên lá rong biển, lần lượt đặt xà lách, dưa leo, củ cải muối vàng, cá thu vào lớp cơm theo chiều ngang. Giữ các nguyên liệu để không bị xô lệch, từ từ cuộn tròn, vừa cuộn vừa nắn chỉnh cho cuộn cơm thật chặt. Cứ thế cuốn đến hết tấm rong biển.', 10);
INSERT INTO public.recipe_steps VALUES (4670, '2025-11-20 17:12:23.833796', '2025-11-20 17:12:23.833796', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 719, 4, 'Lạc rang vàng giã dập. Hành khô phi vàng để riêng. Rau thơm mùi cắt khúc ngắn.', 10);
INSERT INTO public.recipe_steps VALUES (4671, '2025-11-20 17:12:23.83508', '2025-11-20 17:12:23.83508', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 719, 1, 'Xoài rửa sạch, gọt vỏ, thái sợi. Cà rốt thái sợi. Dưa chuột bỏ hạt thái sợi.', 10);
INSERT INTO public.recipe_steps VALUES (4672, '2025-11-20 17:12:23.836153', '2025-11-20 17:12:23.836153', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 719, 6, 'Trang trí bằng số lạc, hành khô còn lại và rau mùi, ớt tỉa hoa.', 10);
INSERT INTO public.recipe_steps VALUES (4673, '2025-11-20 17:12:23.837776', '2025-11-20 17:12:23.837776', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 719, 3, 'Thịt lạng mỏng ướp với tiêu, muối, đường rồi rán vàng.', 10);
INSERT INTO public.recipe_steps VALUES (4674, '2025-11-20 17:12:23.839381', '2025-11-20 17:12:23.839381', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 719, 2, 'Tôm hấp chín bóc bỏ vỏ, chẻ làm đôi.', 10);
INSERT INTO public.recipe_steps VALUES (4675, '2025-11-20 17:12:23.840459', '2025-11-20 17:12:23.840459', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 719, 5, 'Lấy âu sạch, cho cà rốt, dưa, xoài xanh, tôm, thịt, 1/2 lạc, 1/2 hành khô, nêm đường, muối, nước mắm, nước cốt chanh, ớt bột hơi chua ngọt rồi trộn đều bày vào đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (4736, '2025-11-20 17:12:25.46533', '2025-11-20 17:12:25.46533', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 726, 7, 'Cho tép đã rang ráo nước vào, đảo đều tay, thêm đường, mắm, muối, hạt nêm theo khẩu vị. Đảo đều tay để gia vị bám đều vào tép và không bị cháy.', 10);
INSERT INTO public.recipe_steps VALUES (4676, '2025-11-20 17:12:24.093352', '2025-11-20 17:12:24.093352', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 720, 3, 'Đun nóng 2 thìa canh dầu điều, cho sả vào phi thơm. Trút hết số rau củ và chao vào, chế nước dừa đun sôi, sau đó hạ lửa vừa. Đun đến khi phần nước sánh lại, chao bám đều vào rau củ, nêm nếm cho vừa ăn, nếu nhạt có thể cho thêm nước ngâm chao, nếu mặn thì thêm chút đường. Khi phần nước chỉ còn sền sệt, nêm bột ngọt, đảo đều rồi tắt bếp', 10);
INSERT INTO public.recipe_steps VALUES (4677, '2025-11-20 17:12:24.09546', '2025-11-20 17:12:24.09546', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 720, 1, 'Su hào, cà rốt, củ cải, khổ qua, nấm đùi gà, đậu đũa, dứa... hoặc bất kì loại củ nào bạn thích đem sơ chế sạch, cắt miếng vuông quân cờ. Đun nước sôi, cho tất cả rau củ vào trụng sơ, vớt ra ngâm ngay vào nước lạnh để giữ được màu sắc.', 10);
INSERT INTO public.recipe_steps VALUES (4678, '2025-11-20 17:12:24.09705', '2025-11-20 17:12:24.09705', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 720, 4, 'Món rau củ có vị béo ngậy và thơm đặc trưng của chao, vị ngọt của nước dừa tươi, thơm mùi sả. Mỗi loại rau củ lại đem đến một hương vị khác nhau và nhiều màu sắc bắt mắt: miếng khổ qua nhẫn đắng, miếng dứa chua chua ngọt ngọt, miếng nấm đùi gà giòn sần sật... sẽ là một món chay hấp dẫn và rất đưa cơm.', 10);
INSERT INTO public.recipe_steps VALUES (4679, '2025-11-20 17:12:24.098613', '2025-11-20 17:12:24.098613', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 720, 2, 'Chao cho vào bát dằm nhuyễn. Sả đập dập, cắt khúc', 10);
INSERT INTO public.recipe_steps VALUES (4680, '2025-11-20 17:12:24.301031', '2025-11-20 17:12:24.301031', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 721, 12, 'Nêm nếm mắm, muối, hạt nêm vừa khẩu vị.', 10);
INSERT INTO public.recipe_steps VALUES (4681, '2025-11-20 17:12:24.302695', '2025-11-20 17:12:24.302695', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 721, 7, 'Bún chần sơ.', 10);
INSERT INTO public.recipe_steps VALUES (4682, '2025-11-20 17:12:24.3043', '2025-11-20 17:12:24.3043', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 721, 8, 'Xào cà chua tạo màu cho nước dùng: Phi thơm hành khô băm nhỏ, cho cà chua vào xào, nêm chút nước mắm cho cà chua nhanh mềm.', 10);
INSERT INTO public.recipe_steps VALUES (4683, '2025-11-20 17:12:24.305923', '2025-11-20 17:12:24.305923', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 721, 1, 'Sườn chặt miếng vừa ăn, cho vào nồi, đổ nước lạnh xâm xấp, thêm chút muối hạt, đun chần sơ, loại bỏ tạp chất. Vớt ra rửa sạch, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (4684, '2025-11-20 17:12:24.306988', '2025-11-20 17:12:24.306988', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 721, 2, 'Ướp sườn để đậm vị hơn: 1 thìa canh hành tím băm, 3 thìa cà phê nước mắm, 1 thìa cà phê muối, 1 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu. Ướp tối thiểu 15-20 phút cho sườn đậm đà.', 10);
INSERT INTO public.recipe_steps VALUES (4685, '2025-11-20 17:12:24.309103', '2025-11-20 17:12:24.309103', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 721, 11, 'Thêm sấu vào, đun sôi. Khi sấu mềm, vớt ra, dầm, cho nước vào nồi và điều chỉnh độ chua phù hợp với khẩu vị mỗi gia đình.', 10);
INSERT INTO public.recipe_steps VALUES (4686, '2025-11-20 17:12:24.310217', '2025-11-20 17:12:24.310217', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 721, 4, 'Các loại rau thơm, rau sống rửa sạch, vẩy ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (4687, '2025-11-20 17:12:24.311225', '2025-11-20 17:12:24.311225', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 721, 13, 'Trình bày và thưởng thức: Cho bún đã chần vào bát tô, gắp sườn, thêm rau thơm và chan nước dùng nóng và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (4688, '2025-11-20 17:12:24.312868', '2025-11-20 17:12:24.312868', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 721, 6, 'Quả sấu cạo vỏ, khứa nhẹ vài đường trên quả để khi nấu nhanh chín hơn.', 10);
INSERT INTO public.recipe_steps VALUES (4689, '2025-11-20 17:12:24.314874', '2025-11-20 17:12:24.314874', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 721, 5, 'Hành lá, mùi tàu rửa sạch, cắt nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (4690, '2025-11-20 17:12:24.315875', '2025-11-20 17:12:24.315875', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 721, 14, 'Yêu cầu thành phẩm: Sườn thịt mềm, róc xương, đậm vị; nước dùng chua thanh vừa phải.', 10);
INSERT INTO public.recipe_steps VALUES (4691, '2025-11-20 17:12:24.317385', '2025-11-20 17:12:24.317385', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 721, 3, 'Cà chua, thái múi cau.', 10);
INSERT INTO public.recipe_steps VALUES (4692, '2025-11-20 17:12:24.317385', '2025-11-20 17:12:24.317385', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 721, 9, 'Cho 1 thìa canh mỡ lợn (hoặc dầu ăn) vào nồi, cho sườn đã ướp vào đảo cho săn lại rút gia vị vào sườn đậm đà hơn. Thêm lượng nước vừa đủ vào nồi, đun sôi. Khi sôi, hớt bọt, đậy vung, đun nhỏ lửa hầm sườn cho tới khi chín mềm.', 10);
INSERT INTO public.recipe_steps VALUES (4693, '2025-11-20 17:12:24.319953', '2025-11-20 17:12:24.319953', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 721, 10, 'Cho cà chua xào vào nước hầm sườn.', 10);
INSERT INTO public.recipe_steps VALUES (4694, '2025-11-20 17:12:24.534951', '2025-11-20 17:12:24.534951', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 722, 3, 'Rau muống nhặt sạch, vặn rau theo từng đoạn ngắn, rửa sạch, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (4695, '2025-11-20 17:12:24.536567', '2025-11-20 17:12:24.536567', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 722, 5, 'Thêm lượng nước vừa đủ dùng vào nồi, đun sôi.Nêm nếm lại gia vị mắm, muối theo khẩu vị.', 10);
INSERT INTO public.recipe_steps VALUES (4696, '2025-11-20 17:12:24.537645', '2025-11-20 17:12:24.537645', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 722, 1, 'Dùng kéo lật, bỏ yếm và dùng bàn chải chà, rửa sạch chất bẩn bên ngoài con ghẹ. Bóc mai tráng nước sạch, bóc bỏ phần phổi xám. Phần thân ghẹ rửa sạch và cắt đôi, đập dập chân càng để cho thấm gia vị và khi ăn dễ dàng bóc tách hơn.', 10);
INSERT INTO public.recipe_steps VALUES (4697, '2025-11-20 17:12:24.539371', '2025-11-20 17:12:24.539371', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 722, 7, 'Thành phẩm: Bát canh ghẹ nóng hổi, ghẹ đỏ hồng xen lẫn màu xanh mướt của rau muống, nước canh ngọt tự nhiên, giàu giá trị dinh dưỡng. Món này nên ăn nóng rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (4698, '2025-11-20 17:12:24.541018', '2025-11-20 17:12:24.541018', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 722, 6, 'Thêm rau muống vào, đảo nhẹ và nhấn chìm để rau chín và giữ màu xanh.Thêm hạt nêm phù hợp, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (4699, '2025-11-20 17:12:24.542641', '2025-11-20 17:12:24.542641', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 722, 2, 'Ướp ghẹ với hành tím băm nhỏ, đầu hành lá cùng chút nước mắm, muối, hạt nêm, hạt tiêu tối thiểu 15 phút.', 10);
INSERT INTO public.recipe_steps VALUES (4700, '2025-11-20 17:12:24.543714', '2025-11-20 17:12:24.543714', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 722, 4, 'Phi thơm hành khô, cho thịt ghẹ cùng mai vào xào cho tới khi ghẹ đổi màu đỏ hồng, om 8-10 phút để ghẹ ra nước ngọt.', 10);
INSERT INTO public.recipe_steps VALUES (4701, '2025-11-20 17:12:24.833291', '2025-11-20 17:12:24.833291', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 723, 11, 'Chiên lần 2 giúp nem giòn và thoát dầu: Đun nóng dầu ăn, cho nem vào rán. Khi nem vàng giòn thì vớt ra đặt lên giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (4702, '2025-11-20 17:12:24.835515', '2025-11-20 17:12:24.835515', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 723, 1, 'Cá rô đánh vảy, mổ bụng bỏ ruột (giữ lại trứng nếu có), rắc muối hạt, chanh chà xát rồi rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (4703, '2025-11-20 17:12:24.837688', '2025-11-20 17:12:24.837688', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 723, 9, 'Dùng thìa múc lượng nhân vừa phải cho vào, rồi gấp các mép và gói đều tay. Gói tới khi hết lượng nhân.', 10);
INSERT INTO public.recipe_steps VALUES (4768, '2025-11-20 17:12:26.978089', '2025-11-20 17:12:26.978089', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 730, 4, 'Hành củ cắt mỏng phi vàng', 10);
INSERT INTO public.recipe_steps VALUES (4704, '2025-11-20 17:12:24.838694', '2025-11-20 17:12:24.838694', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 723, 7, 'Làm nước phết vỏ bánh đa nem:Trong bát nhỏ, cho vào 1/2 bát nước, 1/2 quả chanh, 2 thìa canh đường rồi khuấy tan hẳn. Hỗn hợp nước phết này giúp vỏ bánh đa nem giòn và lên màu đẹp khi chiên.', 10);
INSERT INTO public.recipe_steps VALUES (4705, '2025-11-20 17:12:24.840279', '2025-11-20 17:12:24.840279', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 723, 10, 'Chiên sơ lần 1: Cho dầu vào chảo, đun nóng, chia từng mẻ nem cho vào chiên sơ. Khi bề mặt nem hơi săn lại thì vớt ra để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (4706, '2025-11-20 17:12:24.843022', '2025-11-20 17:12:24.843022', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 723, 4, 'Các loại rau củ (cà rốt, hành lá, thìa là, giá đỗ) rửa sạch, cắt nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (4707, '2025-11-20 17:12:24.844683', '2025-11-20 17:12:24.844683', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 723, 6, 'Làm nhân nem:Trong một tô trộn lớn, cho thịt cá rô, thịt nạc vai xay, tôm cắt hạt lựu vào. Thêm các loại rau, mộc nhĩ, nấm hương đã cắt nhỏ. Thêm trứng, hạt nêm, hạt tiêu, chút bột bắp (để tạo độ kết dính cũng như giúp nhân nem khô ráo). Thêm 1 thìa canh mỡ hành để giúp nem ngon hơn. Trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (4708, '2025-11-20 17:12:24.846828', '2025-11-20 17:12:24.846828', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 723, 8, 'Trải bánh đa nem lên mặt phẳng. Dùng khăn sạch nhúng hỗn hợp nước chanh, đường, vắt bớt nước cho ẩm rồi lau bề mặt bánh đa nem cho mềm.', 10);
INSERT INTO public.recipe_steps VALUES (4709, '2025-11-20 17:12:24.848991', '2025-11-20 17:12:24.848991', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 723, 5, 'Tôm tươi bóc vỏ, rút chỉ đen ở lưng, cắt hạt lựu.', 10);
INSERT INTO public.recipe_steps VALUES (4710, '2025-11-20 17:12:24.851137', '2025-11-20 17:12:24.851137', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 723, 2, 'Luộc chín cá cùng vài lát gừng, hành khô đập dập, muối. Vớt cá ra, ngâm vào nước đá lạnh, gỡ lấy thịt và trứng (nếu có) để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (4711, '2025-11-20 17:12:24.852746', '2025-11-20 17:12:24.852746', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 723, 3, 'Nấm hương, mộc nhĩ, miến ngâm mềm, rửa sạch, để ráo nước, cắt nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (4712, '2025-11-20 17:12:25.069272', '2025-11-20 17:12:25.069272', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 724, 2, 'Ngâm ngao trong nước kèm vài miếng ớt hoặc ngâm với nước vo gạo, sau đó rửa sạch, luộc với lượng nước xâm xấp', 10);
INSERT INTO public.recipe_steps VALUES (4713, '2025-11-20 17:12:25.070855', '2025-11-20 17:12:25.070855', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 724, 6, 'Hành lá, rau răm, rửa sạch thái nhỏ. Hành củ cắt nhỏ phi vàng. Gừng thái sợi, xay nhỏ lọc lấy nước cốt.', 10);
INSERT INTO public.recipe_steps VALUES (4714, '2025-11-20 17:12:25.072414', '2025-11-20 17:12:25.072414', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 724, 3, 'Tách thịt ngao để riêng. Nước luộc ngao để lắng, lọc lấy phần nước trong bên trên.', 10);
INSERT INTO public.recipe_steps VALUES (4715, '2025-11-20 17:12:25.073993', '2025-11-20 17:12:25.073993', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 724, 9, 'Cháo chín múc ra bát thêm hành lá, rau răm, hành khô và ngao, hạt tiêu vào, có thể pha thêm bát nước mắm ớt nếu ai thích ăn cay và đậm đà.', 10);
INSERT INTO public.recipe_steps VALUES (4716, '2025-11-20 17:12:25.075544', '2025-11-20 17:12:25.075544', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 724, 4, 'Thịt ngao ướp với bột canh, nước mắm, dầu hào, mỗi thứ 1 thìa cà phê, một chút đầu hành lá băm nhỏ, vài sợi gừng thái nhỏ, 1/2 thìa cà phê hạt tiêu', 10);
INSERT INTO public.recipe_steps VALUES (4717, '2025-11-20 17:12:25.077121', '2025-11-20 17:12:25.077121', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 724, 5, 'Sử dụngnồi cơm điện để nấu cháo. Đổ gạo, đậu xanh cùng với chỗ nước luộc ngao, thêm nước trắng (gấp 4 lần nước nấu cơm). Nếu không thích nước ngao có thể dùng nước ninh xương.', 10);
INSERT INTO public.recipe_steps VALUES (4718, '2025-11-20 17:12:25.079192', '2025-11-20 17:12:25.079192', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 724, 7, 'Khi phi xong hành để lại chút mỡ hành để xào thịt ngao cho thơm, thêm chút hành lá, rau răm thái nhỏ và đổ ra đĩa', 10);
INSERT INTO public.recipe_steps VALUES (4719, '2025-11-20 17:12:25.080902', '2025-11-20 17:12:25.080902', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 724, 8, 'Khi cháo chín mở nồi, khuấy đều để cháo sánh, để sôi như vậy một lúc, thỉnh thoảng khuấy cho sánh. Nêm nếm cháo cho vừa, thêm một thìa canh nước cốt gừng để cháo thơm, không bị tanh và tránh lạnh bụng.', 10);
INSERT INTO public.recipe_steps VALUES (4720, '2025-11-20 17:12:25.081948', '2025-11-20 17:12:25.081948', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 724, 1, 'Gạo tẻ, gạo nếp, đậu xanh ngâm nước trong một giờ.', 10);
INSERT INTO public.recipe_steps VALUES (4721, '2025-11-20 17:12:25.26854', '2025-11-20 17:12:25.26854', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 725, 5, 'Đem tất cả các nguyên liệu cho vào một bát to (trừ rau mùi để cho sau)', 10);
INSERT INTO public.recipe_steps VALUES (4722, '2025-11-20 17:12:25.270136', '2025-11-20 17:12:25.270136', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 725, 6, 'Pha hỗn hợp trộn salad: 2 thìa canh nước cốt chanh, 1 thìa canh đường (có thể dùng đường ăn kiêng) + 2 thìa cà phê ớt bột + 1 thìa cà phê nước mắm + 1/2 thìa cà phê muối tinh.', 10);
INSERT INTO public.recipe_steps VALUES (4723, '2025-11-20 17:12:25.271745', '2025-11-20 17:12:25.271745', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 725, 7, 'Trộn đều hỗn hợp cho tan rưới lên các nguyên liệu đã thái ở trên, trộn đều, thêm rau mùi thái nhỏ, cho ra đĩa và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (4724, '2025-11-20 17:12:25.27333', '2025-11-20 17:12:25.27333', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 725, 3, 'Dưa chuột bỏ ruột thái hạt lựu', 10);
INSERT INTO public.recipe_steps VALUES (4725, '2025-11-20 17:12:25.274919', '2025-11-20 17:12:25.274919', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 725, 2, 'Hành tây, ớt chuông thái hạt lựu', 10);
INSERT INTO public.recipe_steps VALUES (4726, '2025-11-20 17:12:25.276526', '2025-11-20 17:12:25.276526', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 725, 4, 'Rau mùi ta rửa sạch, thái nhỏ', 10);
INSERT INTO public.recipe_steps VALUES (4727, '2025-11-20 17:12:25.277714', '2025-11-20 17:12:25.277714', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 725, 1, 'Xoài gọt vỏ thái to hơn hạt lựu một chút', 10);
INSERT INTO public.recipe_steps VALUES (4728, '2025-11-20 17:12:25.453354', '2025-11-20 17:12:25.453354', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 726, 9, 'Khi khế chín, nêm nếm lại gia vị, rắc hành lá, đảo đều và tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (4729, '2025-11-20 17:12:25.454939', '2025-11-20 17:12:25.454939', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 726, 8, 'Khi tép đã ngấm gia vị, cho khế vào đảo đều.', 10);
INSERT INTO public.recipe_steps VALUES (4730, '2025-11-20 17:12:25.456549', '2025-11-20 17:12:25.456549', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 726, 1, 'Tép đồng cắt bỏ râu, xả nước xóc và rửa sạch, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (4731, '2025-11-20 17:12:25.457632', '2025-11-20 17:12:25.457632', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 726, 3, 'Hành lá rửa sạch, cắt nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (4732, '2025-11-20 17:12:25.459298', '2025-11-20 17:12:25.459298', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 726, 4, 'Hành khô bóc vỏ, băm nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (4733, '2025-11-20 17:12:25.460939', '2025-11-20 17:12:25.460939', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 726, 2, 'Khế chua rửa sạch, gọt bỏ viền cạnh, cắt lát hình ngôi sao.', 10);
INSERT INTO public.recipe_steps VALUES (4734, '2025-11-20 17:12:25.461994', '2025-11-20 17:12:25.461994', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 726, 5, 'Cho tép vào chảo, khéo léo điều chỉnh nhiệt độ cao và đảo đều tay để tép nhanh ráo nước. Khi vỏ tép chuyển màu hồng và giòn thì tắt bếp, múc ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (4735, '2025-11-20 17:12:25.463687', '2025-11-20 17:12:25.463687', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 726, 6, 'Cho 1-2 thìa canh mỡ lợn vào chảo, phi thơm hành khô.', 10);
INSERT INTO public.recipe_steps VALUES (4737, '2025-11-20 17:12:25.692197', '2025-11-20 17:12:25.692197', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 727, 2, 'Cho trai vào nồi cùng lượng nước đủ ngập và đun sôi, khi trai mở miệng thì đảo đều, tắt bếp. Lọc lấy nước để riêng. Tách lấy phần thịt trai, bóp bỏ túi phân, rửa sạch, thái miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (4738, '2025-11-20 17:12:25.693793', '2025-11-20 17:12:25.693793', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 727, 1, 'Ngâm trai vào chậu nước, thêm chút giấm và ớt cắt lát, ngâm tối thiểu trong 2 giờ để trai nhả hết bùn đất. Vớt ra chà vỏ, rửa sạch trai.', 10);
INSERT INTO public.recipe_steps VALUES (4739, '2025-11-20 17:12:25.695514', '2025-11-20 17:12:25.695514', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 727, 5, 'Xào săn thịt trai: Cho chút mỡ lợn (hoặc dầu ăn) vào chảo, phi thơm 1/2 lượng hành khô băm nhỏ. Cho trai vào xào trên lửa lớn vài phút. Tắt bếp, múc ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (4740, '2025-11-20 17:12:25.697161', '2025-11-20 17:12:25.697161', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 727, 3, 'Ướp thịt trai với 1 thìa cà phê nước mắm, 1/2 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu, đảo đều và ướp trong 10-15 phút cho ngấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (4741, '2025-11-20 17:12:25.698224', '2025-11-20 17:12:25.698224', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 727, 6, 'Phi thơm số hành khô còn lại, cho cà chua thái múi cau vào xào, nêm chút mắm muối để cà chua nhanh mềm.', 10);
INSERT INTO public.recipe_steps VALUES (4742, '2025-11-20 17:12:25.699811', '2025-11-20 17:12:25.699811', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 727, 4, 'Rửa sạch cà chua, thái múi cau. Rửa sạch rau răm, hành lá, thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (4743, '2025-11-20 17:12:25.700866', '2025-11-20 17:12:25.700866', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 727, 7, 'Khi cà chua mềm, thêm nước luộc trai (gạn, bỏ phần nước đục). Khi canh sôi, thêm thịt trai xào vào, nêm nếm lại gia vị, cho dấm bỗng, hành lá, rau răm thái nhỏ vào, đảo đều, tắt bếp. Nếu không có dấm bỗng, có thể thay thế vị chua bằng quả dọc, sấu, thanh trà hoặc me, (nên cho vào trước), khi chín mềm thì mới thêm thịt trai vào sau.', 10);
INSERT INTO public.recipe_steps VALUES (4744, '2025-11-20 17:12:26.021277', '2025-11-20 17:12:26.021277', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 728, 6, 'Đun nóng 2 muỗng cà phê dầu olive, cho phần nấm, ớt xanh đỏ còn lại vào xào thơm, nêm nhẹ chút hạt nêm từ thịt, cho 1 thìa cà phê bột năng pha loãng vào để tạo độ sánh.', 10);
INSERT INTO public.recipe_steps VALUES (4745, '2025-11-20 17:12:26.022857', '2025-11-20 17:12:26.022857', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 728, 1, 'Rửa nấm rơm, ớt chuông rồi thái hạt lựu từng thứ', 10);
INSERT INTO public.recipe_steps VALUES (4746, '2025-11-20 17:12:26.024958', '2025-11-20 17:12:26.024958', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 728, 2, 'Dùng dao xẻ dọc miếng thăn heo ra, đập nhẹ cho thịt mềm. Ướp thịt với 1 muỗng cà phê hạt nêm, 1 muỗng cà phê tiêu, 1 muỗng cà phê dầu olive, để 15 phút cho ngấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (4747, '2025-11-20 17:12:26.026014', '2025-11-20 17:12:26.026014', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 728, 7, 'Rưới sốt lên đĩa thịt thăn nhồi đã xắt lát. Dùng nóng với cơm trắng, nước mắm ngon pha vài lát ớt.', 10);
INSERT INTO public.recipe_steps VALUES (4748, '2025-11-20 17:12:26.027597', '2025-11-20 17:12:26.027597', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 728, 4, 'Trải miếng thăn heo ra, cho nhân vào cuộn lại, dùng tăm ghim 2 đầu để thịt dính vào nhau. Cho thịt vừa nhồi vào xửng, hấp chín.', 10);
INSERT INTO public.recipe_steps VALUES (4749, '2025-11-20 17:12:26.02864', '2025-11-20 17:12:26.02864', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 728, 5, 'Lấy thịt hấp ra để nguội, cắt lát vừa ăn, bày ra đĩa.', 10);
INSERT INTO public.recipe_steps VALUES (4750, '2025-11-20 17:12:26.029159', '2025-11-20 17:12:26.029159', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 728, 3, 'Quết thật dẻo cá thác lác với 1 muỗng súp dầu olive, sau đó ướp với 1/2 muỗng cà phê hạt nêm, 1 muỗng cà phê nước mắm ngon, 1/2 muỗng cà phê đường, 1 thìa cà phê hành, tỏi băm, 1/2 nấm rơm, ớt Đà Lạt cắt hạt lựu, trộn đều, để làm nhân.', 10);
INSERT INTO public.recipe_steps VALUES (4751, '2025-11-20 17:12:26.693536', '2025-11-20 17:12:26.693536', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 729, 1, 'Đu đủ gọt vỏ, bào sợi, ngâm vào nước đá 15 phút để giòn hơn. Vớt ra, vắt ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (4752, '2025-11-20 17:12:26.696347', '2025-11-20 17:12:26.696347', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 729, 5, 'Nêm nếm theo khẩu vị gia đình lai lần nữa.', 10);
INSERT INTO public.recipe_steps VALUES (4753, '2025-11-20 17:12:26.697951', '2025-11-20 17:12:26.697951', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 729, 3, 'Tiếp tục cho đu đủ bào sợi, cà rốt, đậu đũa, cà chua vào giã dập để nhanh ngấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (4754, '2025-11-20 17:12:26.698998', '2025-11-20 17:12:26.698998', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 729, 4, 'Sau đó, cho đường thốt nốt, nước mắm, nước cốt chanh, nước cốt me vào, dùng chày giã nhẹ, đảo đều để tất cả các nguyên liệu hòa quyện vào gia vị đậm đà.', 10);
INSERT INTO public.recipe_steps VALUES (4755, '2025-11-20 17:12:26.700593', '2025-11-20 17:12:26.700593', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 729, 2, 'Cho tỏi, ớt, tôm khô, muối hạt vào cối, giã nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (4756, '2025-11-20 17:12:26.701849', '2025-11-20 17:12:26.701849', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 729, 6, 'Rắc đậu phộng lên và dùng ngay với xôi và gà nướng BBQ kiểu Thái.', 10);
INSERT INTO public.recipe_steps VALUES (4757, '2025-11-20 17:12:26.961415', '2025-11-20 17:12:26.961415', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 730, 2, 'Trộn đều với gia vị ướp trong 10-15 phút.', 10);
INSERT INTO public.recipe_steps VALUES (4758, '2025-11-20 17:12:26.962477', '2025-11-20 17:12:26.962477', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 730, 8, 'Khế bỏ gân cắt mỏng ngâm trong nước pha chút giấm và muối cho đỡ thâm.', 10);
INSERT INTO public.recipe_steps VALUES (4759, '2025-11-20 17:12:26.964066', '2025-11-20 17:12:26.964066', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 730, 14, 'Có thể chần qua thịt bò nếu không thích xào (xào thịt đậm đà hơn).', 10);
INSERT INTO public.recipe_steps VALUES (4760, '2025-11-20 17:12:26.965689', '2025-11-20 17:12:26.965689', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 730, 17, 'Trộn một thìa canh nước trộn gỏi vào bát thịt bò đợi cho ngấm.', 10);
INSERT INTO public.recipe_steps VALUES (4761, '2025-11-20 17:12:26.967261', '2025-11-20 17:12:26.967261', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 730, 5, 'Tỏi xắt lát mỏng vừa chiên vàng giòn (không thích ăn tỏi chiên có thể bỏ qua bước này, chỉ cần hành phi, lạc rang, mè rang)', 10);
INSERT INTO public.recipe_steps VALUES (4762, '2025-11-20 17:12:26.968855', '2025-11-20 17:12:26.968855', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 730, 15, 'Vớt khế, chuối, hành tây ra cho ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (4763, '2025-11-20 17:12:26.970469', '2025-11-20 17:12:26.970469', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 730, 13, 'Thịt chín đổ ra bát cho nguội.', 10);
INSERT INTO public.recipe_steps VALUES (4764, '2025-11-20 17:12:26.972057', '2025-11-20 17:12:26.972057', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 730, 6, 'Hành tây bỏ lõi xắt mỏng ngâm với nước đá cho hành bớt cay và giòn.', 10);
INSERT INTO public.recipe_steps VALUES (4765, '2025-11-20 17:12:26.973774', '2025-11-20 17:12:26.973774', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 730, 19, 'Cuối cùng cho rau thơm vào trộn đều và rắc lạc, vừng, hành khô, tỏi chiên giòn lên trên là xong.', 10);
INSERT INTO public.recipe_steps VALUES (4766, '2025-11-20 17:12:26.975395', '2025-11-20 17:12:26.975395', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 730, 12, 'Thịt bò sau khi ướp xong ngấm gia vị, bắc chảo lên bếp, đợi chảo nóng cho thịt bò vào xào chín tới, không cần cho thêm dầu ăn vì trước đó đã ướp thịt với dầu ăn.', 10);
INSERT INTO public.recipe_steps VALUES (4767, '2025-11-20 17:12:26.976986', '2025-11-20 17:12:26.976986', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 730, 3, 'Lạc rang chín giã dập', 10);
INSERT INTO public.recipe_steps VALUES (4770, '2025-11-20 17:12:26.981862', '2025-11-20 17:12:26.981862', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 730, 18, 'Sau đó đổ bát thịt bò vào bát có chuối, khế, hành tây, dứa... đổ nước trộn gỏi vào, trộn nhẹ nhàng, thật đều, nêm nếm lại cho vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (4771, '2025-11-20 17:12:26.983444', '2025-11-20 17:12:26.983444', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 730, 7, 'Chuối xanh bỏ gân, lột vỏ cắt mỏng ngâm nước muối thêm chút giấm cho bớt chát và đỡ thâm.', 10);
INSERT INTO public.recipe_steps VALUES (4772, '2025-11-20 17:12:26.985048', '2025-11-20 17:12:26.985048', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 730, 10, 'Các loại rau thơm rửa sạch cắt khúc nhỏ vừa ăn', 10);
INSERT INTO public.recipe_steps VALUES (4773, '2025-11-20 17:12:26.98665', '2025-11-20 17:12:26.98665', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 730, 11, 'Pha nước trộn gỏi: 2 thìa canh đường + 1 thìa canh nước cốt chanh + 2 thìa canh nước mắm hoà cho tan đường, thêm tỏi ớt băm nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (4774, '2025-11-20 17:12:26.988532', '2025-11-20 17:12:26.988532', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 730, 1, 'Thịt bò thái mỏng ướp với 2 thìa cà phê tỏi băm, 1 thìa cà phê bột nêm, 1 thìa cà phê dầu hào, 1/2 thìa cà phê hạt tiêu, 1 thìa canh dầu ăn, 1 thìa canh nước ép dứa (có nước ép dứa thịt bò sẽ mềm và thơm ngon hơn).', 10);
INSERT INTO public.recipe_steps VALUES (4775, '2025-11-20 17:12:26.990096', '2025-11-20 17:12:26.990096', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 730, 16, 'Khế vắt bớt nước cho đỡ chua.', 10);
INSERT INTO public.recipe_steps VALUES (4776, '2025-11-20 17:12:27.858459', '2025-11-20 17:12:27.858459', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 19, 'Phi thơm hành tím, cho hàu vào xào săn lại, thêm nước mắm, muối, hạt nêm cho vừa khẩu vị. Chú ý: Chỉ cần hàu săn lại là được, đừng xào lâu/chín quá, hàu bị ra nước, teo lại khi ăn bị dai, không ngon.', 10);
INSERT INTO public.recipe_steps VALUES (4777, '2025-11-20 17:12:27.860062', '2025-11-20 17:12:27.860062', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 33, 'Gạo nếp, gạo tẻ vo sạch, ngâm nước 2,5-3 giờ rồi xay vỡ sơ.', 10);
INSERT INTO public.recipe_steps VALUES (4778, '2025-11-20 17:12:27.861716', '2025-11-20 17:12:27.861716', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 3, 'Gạo nếp, gạo tẻ rang sơ cho thơm. Sau đó, rửa sạch, cho gạo ngâm với nước tối thiểu 30 phút để ngậm nước cho nở mềm, vớt ra.', 10);
INSERT INTO public.recipe_steps VALUES (4779, '2025-11-20 17:12:27.863308', '2025-11-20 17:12:27.863308', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 7, 'Cách 1:', 10);
INSERT INTO public.recipe_steps VALUES (4780, '2025-11-20 17:12:27.864436', '2025-11-20 17:12:27.864436', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 17, 'Cách làm hàu:', 10);
INSERT INTO public.recipe_steps VALUES (4781, '2025-11-20 17:12:27.866031', '2025-11-20 17:12:27.866031', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 35, 'Cho nước hầm xương (đã lọc), sườn non cùng gạo tẻ gạo nếp đã ngâm vào nồi, bật bếp đun sôi. Khi sôi, hạ nhỏ lửa, ninh cho cháo chín nhừ và sánh. Tùy theo sở thích mà bạn có thể nấu đặc hay loãng. Nêm nếm lại gia vị phù hợp.', 10);
INSERT INTO public.recipe_steps VALUES (4782, '2025-11-20 17:12:27.867104', '2025-11-20 17:12:27.867104', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 36, 'Trình bày và thưởng thức: Khi cháo chín, múc ra bát, thêm hành lá cắt nhỏ, hành khô phi, ruốc bông, rắc chút hạt tiêu ăn kèm cùng quẩy giòn tan.', 10);
INSERT INTO public.recipe_steps VALUES (4783, '2025-11-20 17:12:27.868167', '2025-11-20 17:12:27.868167', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 4, 'Cho gạo vào nồi cùng lượng nước lạnh vào nồi, bật bếp đun (nhớ không đảo, không quấy dễ bén đáy nồi).', 10);
INSERT INTO public.recipe_steps VALUES (4784, '2025-11-20 17:12:27.869566', '2025-11-20 17:12:27.869566', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 21, 'Trình bày và thưởng thức: Múc cháo ra bát, thêm hành lá thái nhỏ, hành phi thơm lừng, rắc chút hạt tiêu, ớt bột và thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (4785, '2025-11-20 17:12:27.870626', '2025-11-20 17:12:27.870626', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 15, 'Cháo hàu', 10);
INSERT INTO public.recipe_steps VALUES (4786, '2025-11-20 17:12:27.872209', '2025-11-20 17:12:27.872209', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 14, '* Khi ăn, múc cháo ra bát, thêm hành lá, rau mùi, gừng sợi và thưởng thức nóng!', 10);
INSERT INTO public.recipe_steps VALUES (4787, '2025-11-20 17:12:27.873279', '2025-11-20 17:12:27.873279', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 11, 'Cách 2:', 10);
INSERT INTO public.recipe_steps VALUES (4788, '2025-11-20 17:12:27.874951', '2025-11-20 17:12:27.874951', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 9, 'Khi tôm chín, vớt phần tôm ra, bóc vỏ lấy thịt, ướp chút mắm muối và xào thơm. Phần nước luộc tôm thì cho vào hầm cháo cho ngọt.', 10);
INSERT INTO public.recipe_steps VALUES (4789, '2025-11-20 17:12:27.876041', '2025-11-20 17:12:27.876041', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 34, 'Sườn non, xương hom rửa sạch bằng nước vo gạo, cho vào nồi nước sôi chần, rửa sạch loại bỏ tạp chất, khử mùi. Sau đó, cho xương hom vào nồi cùng nước, thêm chút muối, hành tây và hầm nhỏ lửa, lọc lấy nước hầm xương trong.', 10);
INSERT INTO public.recipe_steps VALUES (4790, '2025-11-20 17:12:27.87705', '2025-11-20 17:12:27.87705', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 26, 'Cho gạo đã ngâm vào nồi nước hầm xương. Khi sôi, hạ nhỏ lửa lăn tăn, hé chút vung, ninh cho tới khi cháo chín nhừ, sánh lại là đạt.', 10);
INSERT INTO public.recipe_steps VALUES (4791, '2025-11-20 17:12:27.879099', '2025-11-20 17:12:27.879099', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 6, 'Phần tôm:Có 2 cách', 10);
INSERT INTO public.recipe_steps VALUES (4792, '2025-11-20 17:12:27.880106', '2025-11-20 17:12:27.880106', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 18, 'Rửa sạch hàu bằng nước muối pha loãng, vớt ra, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (4793, '2025-11-20 17:12:27.881613', '2025-11-20 17:12:27.881613', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 5, 'Khi sôi, hạ nhỏ lửa đun cho tới khi cháo chín nhừ.', 10);
INSERT INTO public.recipe_steps VALUES (4794, '2025-11-20 17:12:27.882619', '2025-11-20 17:12:27.882619', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 16, 'Nấu cháo:Gạo tẻ, gạo nếp vo sạch, để ráo. Sau đó, cho gạo vào nồi đun sôi cùng với nước. Khi sôi, hạ nhỏ lửa ninh cho tới khi gạo nở bung ra như cánh hoa là đạt.', 10);
INSERT INTO public.recipe_steps VALUES (4795, '2025-11-20 17:12:27.88462', '2025-11-20 17:12:27.88462', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 1, 'Cháo tôm', 10);
INSERT INTO public.recipe_steps VALUES (4796, '2025-11-20 17:12:27.885622', '2025-11-20 17:12:27.885622', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 24, 'Gạo tẻ, gạo nếp vo sạch, ngâm nước 30 phút để cho gạo mềm.', 10);
INSERT INTO public.recipe_steps VALUES (4797, '2025-11-20 17:12:27.887132', '2025-11-20 17:12:27.887132', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 23, 'Nấu cháo:', 10);
INSERT INTO public.recipe_steps VALUES (4798, '2025-11-20 17:12:27.88871', '2025-11-20 17:12:27.88871', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 25, 'Xương hom lợn: Rửa sạch với nước vo gạo, chần qua nước sôi rồi rửa sạch lần 2 để loại bỏ tạp chất. Cho xương vào nồi nước hầm nhỏ lửa, mở vung, thêm chút muối và củ hành tây cho thơm, thỉnh thoảng hớt bọt cho nước trong. Sau 2 giờ, vớt xương, hành tây ra, lọc lấy nước hầm.', 10);
INSERT INTO public.recipe_steps VALUES (4799, '2025-11-20 17:12:27.890477', '2025-11-20 17:12:27.890477', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 32, 'Cháo sườn non', 10);
INSERT INTO public.recipe_steps VALUES (4800, '2025-11-20 17:12:27.891537', '2025-11-20 17:12:27.891537', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 10, 'Khi cháo chín thì thêm phần tôm đã xào vào đảo đều. Nêm nếm lại mắm, muối, hạt nêm theo khẩu vị. Rắc thêm hành lá, rau mùi, hành phi là đã hoàn thành.', 10);
INSERT INTO public.recipe_steps VALUES (4801, '2025-11-20 17:12:27.893172', '2025-11-20 17:12:27.893172', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 8, 'Tôm làm sạch, rút chỉ đen ở lưng, luộc cùng chút hành, gừng, chút bột canh/muối.', 10);
INSERT INTO public.recipe_steps VALUES (4802, '2025-11-20 17:12:27.894239', '2025-11-20 17:12:27.894239', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 2, 'Phần gạo', 10);
INSERT INTO public.recipe_steps VALUES (4803, '2025-11-20 17:12:27.895309', '2025-11-20 17:12:27.895309', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 13, 'Khi cháo đã ninh nhừ, cho tôm vào đảo đều. Nêm nếm gia vị cho phù hợp.', 10);
INSERT INTO public.recipe_steps VALUES (4804, '2025-11-20 17:12:27.896898', '2025-11-20 17:12:27.896898', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 30, 'Trút phần thịt bò vào nồi cháo đã chín. Nêm nếm lại gia vị cho phù hợp.', 10);
INSERT INTO public.recipe_steps VALUES (4805, '2025-11-20 17:12:27.897964', '2025-11-20 17:12:27.897964', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 31, 'Trình bày và thưởng thức: Múc cháo ra bát, thêm hành lá thái nhỏ, rắc chút hạt tiêu, gừng thái sợi và thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (4806, '2025-11-20 17:12:27.899015', '2025-11-20 17:12:27.899015', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 29, 'Phi thơm tỏi, cho thịt bò vào xào trên lửa lớn, khi chín tới thì tắt bếp. Chú ý: Không nên xào lâu, thịt bò sẽ bị dai và mất vị ngọt tự nhiên.', 10);
INSERT INTO public.recipe_steps VALUES (4807, '2025-11-20 17:12:27.900081', '2025-11-20 17:12:27.900081', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 12, 'Tôm sơ chế sạch, bóc vỏ, cắt nhỏ và ướp chút với mắm, muối, hạt nêm, hạt tiêu. Phi thơm hành, cho tôm vào xào săn lại, tắt bếp, múc ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (4808, '2025-11-20 17:12:27.90169', '2025-11-20 17:12:27.90169', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 20, 'Sau khi cháo chín, thêm hàu đã xào vào đảo đều. Nêm nếm lại gia vị phù hợp gia đình.', 10);
INSERT INTO public.recipe_steps VALUES (4809, '2025-11-20 17:12:27.903333', '2025-11-20 17:12:27.903333', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 28, 'Thịt bò lọc gân, băm nhỏ, ướp chút nước mắm, hạt tiêu, hạt nêm và dầu ăn cho mềm.', 10);
INSERT INTO public.recipe_steps VALUES (4810, '2025-11-20 17:12:27.904654', '2025-11-20 17:12:27.904654', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 22, 'Cháo thịt bò', 10);
INSERT INTO public.recipe_steps VALUES (4811, '2025-11-20 17:12:27.90628', '2025-11-20 17:12:27.90628', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 731, 27, 'Xào thịt bò:Làm khi cháo đã chín', 10);
INSERT INTO public.recipe_steps VALUES (4812, '2025-11-20 17:12:28.279312', '2025-11-20 17:12:28.279312', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 732, 6, 'Cho thịt chân giò vào nồi, đổ nước lạnh ngập thịt, thêm 2-3 củ hành tím đập dập, 1 nhánh gừng nhỏ đập dập, 1 muỗng cà phê muối, 1/2 muỗng cà phê hạt tiêu, 1/2 muỗng cà phê hạt nêm rau củ. Bật bếp, đun sôi.', 10);
INSERT INTO public.recipe_steps VALUES (4813, '2025-11-20 17:12:28.280899', '2025-11-20 17:12:28.280899', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 732, 7, 'Sau khi sôi, hớt bỏ bọt, hạ nhỏ lửa và luộc 20-25 phút (tùy theo kích thước chân giò lớn hay nhỏ). Dùng xiên tre hoặc đầu đũa chọc vào thấy thịt không tiết ra nước hồng là đã chín. Tắt bếp ngâm chân giò thêm 5-8 phút để cho thịt ngậm nước ngọt thơm hơn và không bị đỏ thịt.', 10);
INSERT INTO public.recipe_steps VALUES (4814, '2025-11-20 17:12:28.281953', '2025-11-20 17:12:28.281953', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 732, 5, 'b) Cách luộc thịt:', 10);
INSERT INTO public.recipe_steps VALUES (4815, '2025-11-20 17:12:28.283537', '2025-11-20 17:12:28.283537', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 732, 2, 'Thịt chân giò lọc/rút xương, rửa sạch, để ráo nước hoặc thấm khô, ướp với chút hạt tiêu, bột canh bên trong.', 10);
INSERT INTO public.recipe_steps VALUES (4816, '2025-11-20 17:12:28.28512', '2025-11-20 17:12:28.28512', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 732, 9, 'Chờ chân giò nguội, lấy ra, thấm khô, dùng khăn xô sạch ủ hoặc cho vào hộp kín để vào tủ lạnh 1,5-2 giờ cho thịt săn, kết dính lại, săn chắc giúp cho khi thái sẽ mỏng dính, dễ dàng hơn.', 10);
INSERT INTO public.recipe_steps VALUES (4817, '2025-11-20 17:12:28.286195', '2025-11-20 17:12:28.286195', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 732, 8, 'Sau đó, vớt thịt ra cho vào nước sôi để nguội có đá lạnh, vài lát chanh tươi giúp thịt săn lại và giữ màu trắng tinh.', 10);
INSERT INTO public.recipe_steps VALUES (4818, '2025-11-20 17:12:28.28778', '2025-11-20 17:12:28.28778', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 732, 3, 'Tiếp đến, cuộn tròn lớp da bên ngoài tiếp giáp lại với nhau đều tay, dùng chỉ cotton quấn hình trụ, bó tròn và buộc lại. Mục đích để khi thái sẽ tạo nên các khoanh tròn đẹp mắt. Lưu ý: Không bó chặt quá vì khi luộc thịt nở, ngấm nước sẽ dễ bị nứt.', 10);
INSERT INTO public.recipe_steps VALUES (4819, '2025-11-20 17:12:28.28923', '2025-11-20 17:12:28.28923', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 732, 1, 'a) Sơ chế:', 10);
INSERT INTO public.recipe_steps VALUES (4820, '2025-11-20 17:12:28.290928', '2025-11-20 17:12:28.290928', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 732, 4, 'Khử mùi và làm sạch thịt: Cho thịt chân giò vào nồi nước lạnh, thêm 1 nhánh gừng đập dập, chút muối hạt, dấm đun sôi để chần qua, nhằm loại bỏ hết các tạp chất. Đổ ra, rửa sạch lại. Làm thế này giúp thịt thơm ngon hơn sau khi luộc.', 10);
INSERT INTO public.recipe_steps VALUES (4821, '2025-11-20 17:12:28.469311', '2025-11-20 17:12:28.469311', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 733, 6, 'Yêu cầu thành phẩm: Vỏ khoai giòn vàng, bám sốt caramel đều, ánh lên màu hổ phách đẹp mắt, vị mặn ngọt hài hòa. Đây là món ăn vặt được nhiều bạn trẻ ở Nhật Bản yêu thích, hiện có trong thực đơn nhiều quán ăn vặt ở Việt Nam.', 10);
INSERT INTO public.recipe_steps VALUES (4822, '2025-11-20 17:12:28.47092', '2025-11-20 17:12:28.47092', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 733, 1, 'Khoai lang rửa sạch, để nguyên vỏ rồi cắt miếng vừa ăn, ngâm vào nước muỗi loãng 10 - 15 phút cho ra bớt nhựa và không bị thâm. Sau đó, rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (4823, '2025-11-20 17:12:28.47198', '2025-11-20 17:12:28.47198', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 733, 4, 'Cho khoai đã nguội vào chiên ngập dầu cho tới khi vàng xém cạnh.', 10);
INSERT INTO public.recipe_steps VALUES (4824, '2025-11-20 17:12:28.473599', '2025-11-20 17:12:28.473599', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 733, 5, 'Trong lúc chiên khoai gần được thì nấu sốt trộn. Cho hỗn hợp sốt xì dầu, mật ong ở trên vào chảo hoặc xoong nhỏ nấu trên lửa nhỏ. Khuấy đều cho hỗn hợp sánh đặc và lên màu caramel đẹp mắt. Khi khoai chiên vàng giòn thì vớt ra cho ngay vào chảo sốt, trộn đều cho ngấm vị. Múc ra đĩa, rắc vừng rang lên và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (4825, '2025-11-20 17:12:28.475314', '2025-11-20 17:12:28.475314', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 733, 2, 'Vừng rang chín. Pha hỗn hợp nước sốt gồm xì dầu: mật ong theo tỷ lệ 1:1 gồm 3 muỗng canh xì dầu, 3 muỗng canh mật ong, 1 muỗng canh mạch nha (không có thì bỏ qua), 1/2 thìa cà phê nước cốt chanh.', 10);
INSERT INTO public.recipe_steps VALUES (4826, '2025-11-20 17:12:28.476885', '2025-11-20 17:12:28.476885', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 733, 3, 'Làm chín sơ khoai bằng một trong hai cách sau: Luộc sơ khoai vài phút, xả nước lạnh cho ráo nước, nguội hẳn. Hoặc cho khoai vào lò vi sóng quay 3 - 4 phút.', 10);
INSERT INTO public.recipe_steps VALUES (4827, '2025-11-20 17:12:28.896673', '2025-11-20 17:12:28.896673', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 734, 6, 'Yêu cầu thành phẩm: Bánh mềm xốp, dậy mùi thơm của chuối. Đặc biệt thời gian làm chỉ 10 phút thao tác, không phải ủ hay nhào bột.', 10);
INSERT INTO public.recipe_steps VALUES (4828, '2025-11-20 17:12:28.898285', '2025-11-20 17:12:28.898285', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 734, 4, 'Làm nóng lò trước 10 phút ở 175°C ở chế độ 2 lửa, nướng bánh 55-60 phút cho tới khi mặt trên chuyển màu vàng nâu, thử tăm xâm vào rút ra bột không dính là bánh đã chín.', 10);
INSERT INTO public.recipe_steps VALUES (4886, '2025-11-20 17:12:31.459515', '2025-11-20 17:12:31.459515', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 744, 7, 'Yêu cầu thành phẩm: Bánh rán vỏ vàng ruộm, vừa giòn vừa dẻo; nhân bên trong tách vỏ, mềm thơm ngon ngọt rất hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (4829, '2025-11-20 17:12:28.899337', '2025-11-20 17:12:28.899337', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 734, 1, 'Chọn chuối sứ chín. Nếu có thời gian thì để 3 quả chuối vào ngăn đá tủ lạnh, khi nào làm bánh lấy ra ra đông thì chuối sẽ mềm dễ nghiền nhuyễn hơn. Còn lại một quả thì để cắt lát trang trí lên mặt bánh khi nướng.', 10);
INSERT INTO public.recipe_steps VALUES (4830, '2025-11-20 17:12:28.900933', '2025-11-20 17:12:28.900933', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 734, 3, 'Phết một lớp dầu ăn hoặc bơ vào khuôn, rắc chút bột mỏng rồi đổ hỗn hợp bột trên vào. Cắt quả chuối còn lại thành các lát mỏng trang trí lên trên. Thêm nho khô hoặc hạnh nhân lát nếu thích.', 10);
INSERT INTO public.recipe_steps VALUES (4831, '2025-11-20 17:12:28.902524', '2025-11-20 17:12:28.902524', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 734, 5, 'Để 2-3 phút rồi lấy bánh ra khỏi khuôn, cắt lát ăn nóng là ngon nhất.', 10);
INSERT INTO public.recipe_steps VALUES (4832, '2025-11-20 17:12:28.904125', '2025-11-20 17:12:28.904125', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 734, 2, 'Tùy theo sở thích, nếu thích bánh mịn thì xay 3 quả chuối. Hoặc nếu thích còn thớ chuối nhỏ thì dùng thìa nghiền nhuyễn là được. Cho hỗn hợp chuối, đường, bơ (hoặc dầu ăn), trứng, muối, bột nở, muối nở, rây bột mì, bột ca cao (hoặc milo) rồi thêm sữa từ từ vào khuấy, trộn đều cho tới khi thành hỗn hợp đồng nhất, sánh mịn. Tùy theo sở thích, bạn thêm chocolate hoặc nho khô vào trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (4833, '2025-11-20 17:12:29.163876', '2025-11-20 17:12:29.163876', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 735, 2, 'Trộn và tạo hình bánh
INSERT INTO public.recipe_steps VALUES (4834, '2025-11-20 17:12:29.16549', '2025-11-20 17:12:29.16549', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 735, 1, 'Sơ chế
INSERT INTO public.recipe_steps VALUES (4835, '2025-11-20 17:12:29.167101', '2025-11-20 17:12:29.167101', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 735, 3, 'Nướng bánh
INSERT INTO public.recipe_steps VALUES (4836, '2025-11-20 17:12:29.169168', '2025-11-20 17:12:29.169168', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 735, 4, 'Yêu cầu thành phẩm
INSERT INTO public.recipe_steps VALUES (4837, '2025-11-20 17:12:29.432899', '2025-11-20 17:12:29.432899', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 736, 2, 'Dùng dao sắc, thái nghiêng tai heo thành các lát mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (4838, '2025-11-20 17:12:29.434568', '2025-11-20 17:12:29.434568', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 736, 1, 'Tai heo chà xát chanh, muối hạt, rửa sạch. Cho tai heo vào nồi ngập nước, thêm vài lát gừng, 1 thìa canh giấm gạo, 1 thìa cà phê muối, 1/2 thìa cà phê hạt nêm, 1-2 củ hành khô đập dập, đun sôi, hạ lửa nhỏ, thỉnh thoảng hớt bỏ bọt. Sau 15 phút, vớt ra cho vào thau nước đun sôi để nguội kèm đá, vài lát chanh để hãm nhiệt và giúp tai trắng, giòn, thơm. Khi nguội, vớt ra thấm khô.', 10);
INSERT INTO public.recipe_steps VALUES (4839, '2025-11-20 17:12:29.436183', '2025-11-20 17:12:29.436183', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 736, 3, 'Xoài xanh gọt vỏ, thái sợi. Cà rốt bào sợi, trộn với 1/2 thìa canh đường trong 10 phút rồi vắt kỹ cho bớt vị hăng.', 10);
INSERT INTO public.recipe_steps VALUES (4840, '2025-11-20 17:12:29.438304', '2025-11-20 17:12:29.438304', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 736, 4, 'Các loại rau thơm nhặt rửa sạch, vẩy ráo nước, thái nhỏ. Lạc rang giã dập. Pha nước sốt nộm tỷ lệ gồm đường: nước: mắm là 1:1:1 (cho vào nồi 4 thìa canh đường: 4 thìa canh nước: 4 thìa canh nước mắm 30 độ đạm, đun sôi cho tan, để nguội). Sau đó cho tỏi, ớt băm nhuyễn vào.', 10);
INSERT INTO public.recipe_steps VALUES (4841, '2025-11-20 17:12:29.43936', '2025-11-20 17:12:29.43936', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 736, 5, 'Trộn nộm 2 lần. Lần 1: cho tai heo, xoài, cà rốt vào tô, cho 1/2 lượng nước trộn nộm vào đảo đều. Sau 7-8 phút, rau củ quả ra nước, chắt bỏ nước đi. Lần 2: Cho 1/2 nước sốt nộm còn lại vào đảo đều cho ngấm vị. Sau đó, chắt nước cho nộm khô ráo. Cuối cùng cho rau thơm, lạc rang giã dập vào đảo đều. Trình bày nộm ra đĩa, rắc thêm chút lạc rang lên trên và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (4842, '2025-11-20 17:12:29.440957', '2025-11-20 17:12:29.440957', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 736, 6, 'Yêu cầu thành phẩm: Tai heo trắng giòn sần sật, xoài và cà rốt khô ráo nước, vị chua cay mặn ngọt hài hòa, lạc rang thơm bùi rất hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (4843, '2025-11-20 17:12:29.639156', '2025-11-20 17:12:29.639156', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 737, 1, 'Sơ chế
INSERT INTO public.recipe_steps VALUES (4844, '2025-11-20 17:12:29.64076', '2025-11-20 17:12:29.64076', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 737, 2, 'Bao bột áo cho ngô
INSERT INTO public.recipe_steps VALUES (4845, '2025-11-20 17:12:29.642356', '2025-11-20 17:12:29.642356', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 737, 3, 'Yêu cầu thành phẩm
INSERT INTO public.recipe_steps VALUES (4846, '2025-11-20 17:12:29.842645', '2025-11-20 17:12:29.842645', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 738, 4, 'Cho dầu ăn nhiều chút vào chảo sâu lòng, bật lửa vừa. Cho tỏi vào đảo liên tục, đều tay. Sau 1 phút cho ớt vào, tiếp tục đảo đều tay. Khi tỏi, ớt chuyển màu vàng đều thì tắt bếp, lọc qua rây để riêng phần tỏi ớt.', 10);
INSERT INTO public.recipe_steps VALUES (4847, '2025-11-20 17:12:29.843714', '2025-11-20 17:12:29.843714', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 738, 1, 'Để có món lạc rang tỏi ớt thơm ngon, bạn cần lựa chọn các hạt lạc tròn đều, chắc mẩy, vỏ màu sáng. Nhặt bỏ các hạt lép, mọt, mốc.', 10);
INSERT INTO public.recipe_steps VALUES (4848, '2025-11-20 17:12:29.845305', '2025-11-20 17:12:29.845305', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 738, 3, 'Pha hỗn hợp nước sốt gồm 2 muỗng canh nước mắm (30-35 độ đạm), 2 muỗng canh đường, 1 muỗng canh tương ớt, 1/2 muỗng canh bột ớt khô, 1/2 muỗng cà phê hạt nêm, khuấy đều cho tan hỗn hợp.', 10);
INSERT INTO public.recipe_steps VALUES (4849, '2025-11-20 17:12:29.846925', '2025-11-20 17:12:29.846925', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 738, 8, 'Đổ lạc rang tỏi ớt ra mẹt tre hoặc rổ thoáng khí. Khi nguội bớt thì đeo găng tay tách nhẹ các hạt rời ra. Để cho lạc rang tỏi ớt nguội hoàn toàn thì bảo quản trong hộp kín, để ngăn mát tủ lạnh dùng dần.', 10);
INSERT INTO public.recipe_steps VALUES (4850, '2025-11-20 17:12:29.847998', '2025-11-20 17:12:29.847998', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 738, 7, 'Bật nóng chảo ở lửa vừa, trút phần hỗn hợp nước mắm đường vào đảo đều cho tới khi sốt bám kẹo lại khắp bề mặt lạc thì tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (4851, '2025-11-20 17:12:29.849601', '2025-11-20 17:12:29.849601', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 738, 9, 'Yêu cầu thành phẩm: Lạc vàng giòn, tỏi ớt bám đều mặt, vị mặn ngọt cay hài hòa, vỏ không bị bong. Món này dùng ăn xôi, cơm trắng hay nhâm nhi tụ họp cùng bạn bè cũng rất hao.', 10);
INSERT INTO public.recipe_steps VALUES (4852, '2025-11-20 17:12:29.850658', '2025-11-20 17:12:29.850658', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 738, 5, 'Lấy 1-2 thìa dầu tỏi ớt ở trên tiếp tục cho vào chảo, đổ lạc vào rang ở lửa nhỏ, đảo đều tay cho tới khi thử thấy lạc chín giòn thì tắt bếp, để lạc vài phút cho giòn.', 10);
INSERT INTO public.recipe_steps VALUES (4853, '2025-11-20 17:12:29.851734', '2025-11-20 17:12:29.851734', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 738, 2, 'Món ăn này cần nhiều tỏi quyện với ớt tạo hương vị đặc trưng khó quên. Bí quyết để bóc tỏi nhanh là cắt đầu tỏi, dùng đầu nhọn mũi dao luồn nhẹ, tách gỡ tép tỏi ra khỏi vỏ. Sau đó băm nhuyễn. Ớt bổ dọc, bỏ hạt, băm nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (4854, '2025-11-20 17:12:29.853325', '2025-11-20 17:12:29.853325', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 738, 6, 'Trong lúc này, rắc đều qua rây 1/2 muỗng canh bột mì, đảo đều cho bám vào lạc và giúp lạc khô ráo. Sau đó, tiếp tục cho 1/2 muỗng canh bột bắp (hoặc bột sắn dây) đảo tiếp để lạc trữ lâu vẫn giòn.', 10);
INSERT INTO public.recipe_steps VALUES (4855, '2025-11-20 17:12:30.182426', '2025-11-20 17:12:30.182426', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 739, 4, 'Rây 200 gr bột nếp chín cho mịn vào cái âu lớn, thêm từ từ 450 gr nước đường bánh dẻo, 15 ml nước hoa bưởi, 15 ml dầu ăn vào trộn đều. Lúc này bột hơi ướt, để bột nghỉ 10 phút cho nở ra rồi tiếp tục từ từ cho 50 gr bột khô nhồi tiếp. Rải chút bột áo lên mặt phẳng, cho bột ra rồi nhồi cho tới khi bột thành hỗn hợp mịn dẻo, không bị vón cục là được.', 10);
INSERT INTO public.recipe_steps VALUES (4856, '2025-11-20 17:12:30.184023', '2025-11-20 17:12:30.184023', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 739, 6, 'Bao một lớp bột nếp chín mỏng vào khuôn và vào bánh. Cho bánh ấn vào lòng khuôn rồi dùng bàn tay dàn đều bánh. Nén chặt khuôn xuống 15-18 giây rồi ấn đẩy bánh ra. Làm lần lượt cho tới hết. Bánh sau khi làm xong thì ăn ngay được. Nếu để lâu thì cho bánh vào túi. Sau 1- 2 ngày bánh sẽ chuyển trong dẻo, ăn ngon đỡ ngọt hơn. Bảo quản bánh ở nhiệt độ phòng khoảng 4 - 5 ngày.', 10);
INSERT INTO public.recipe_steps VALUES (4857, '2025-11-20 17:12:30.185611', '2025-11-20 17:12:30.185611', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 739, 5, 'Chia bột bánh dẻo thành 6 phần bằng nhau rồi vê tròn lại. Lấy mỗi phần bột bánh dẻo ấn hoặc cán dẹt, cho nhân đậu xanh trứng muối vào giữa rồi vê tròn lại để bao kín nhân. Làm lần lượt cho tới hết. Tỷ lệ vỏ và nhân bánh thường là 2:1.', 10);
INSERT INTO public.recipe_steps VALUES (4858, '2025-11-20 17:12:30.187185', '2025-11-20 17:12:30.187185', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 739, 2, 'Đậu xanh rửa sạch, ngâm 3-4 tiếng cho nở rồi cho vào nồi nấu khoảng 30 phút là đậu chín mềm. Dùng máy xay sinh tố xay nhuyễn đậu xanh cùng đường, lọc qua rây cho mịn. Cho hỗn hợp ra chảo chống dính sên ở lửa vừa cho tới khi sệt lại thì từ từ cho dầu ăn vào khuấy đảo liên tục để hơi nước thoát. Sên cho tới khi hỗn hợp không dính tay (khoảng 45 phút) thì cho bột bánh dẻo vào trộn đều cho bột chín. Tổng thời gian khoảng 50 phút. Nếu muốn rút ngắn thời gian, có thể mua nhân sên sẵn ở các cửa hàng làm bánh.', 10);
INSERT INTO public.recipe_steps VALUES (4859, '2025-11-20 17:12:30.188744', '2025-11-20 17:12:30.188744', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 739, 1, 'Trứng muối rửa qua với rượu trắng, phết chút dầu ăn hoặc dầu mè cho thơm. Bật trước lò nướng 10 phút ở 150 độ C. Sau đó, cho trứng vào khay rồi nướng ở khay giữa của lò trong 6 - 7 phút ở 150 độ là trứng chín lòng đào, đỏ rực như mặt trời là được.', 10);
INSERT INTO public.recipe_steps VALUES (4860, '2025-11-20 17:12:30.190332', '2025-11-20 17:12:30.190332', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 739, 3, 'Chia phần đậu xanh làm 6 phần bằng nhau, vê tròn rồi dùng ngón tay ấn lõm chính giữa. Sau đó, cho trứng muối vào ấn đồng thời miết để nhân đậu xanh bao hết trứng rồi vê tròn. Chú ý hạn chế không khí lọt vào giữa nhân đậu và trứng. Làm lần lượt cho tới hết.', 10);
INSERT INTO public.recipe_steps VALUES (4861, '2025-11-20 17:12:30.390426', '2025-11-20 17:12:30.390426', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 740, 2, 'Đun sôi nước, cho rau câu vào nấu tan, cho đường vào, cuối cùng cho vani vào.', 10);
INSERT INTO public.recipe_steps VALUES (4862, '2025-11-20 17:12:30.391988', '2025-11-20 17:12:30.391988', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 740, 4, 'Tiếp tục đổ rau câu cho đầy khuôn, sau đó để cho khuôn rau câu nguội và đông đặc lại.', 10);
INSERT INTO public.recipe_steps VALUES (4863, '2025-11-20 17:12:30.393548', '2025-11-20 17:12:30.393548', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 740, 1, 'Các loại trái rửa sạch, để ráo nước. Kiwi, cam thái khoanh tròn, dâu, thanh long thái lát mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (4864, '2025-11-20 17:12:30.395112', '2025-11-20 17:12:30.395112', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 740, 3, 'Xếp trái cây vào đáy khuôn để làm mặt rồi đổ rau câu vào, chờ cho rau câu hơi sánh lại, tiếp tục xếp một lớp trái cây khác.', 10);
INSERT INTO public.recipe_steps VALUES (4865, '2025-11-20 17:12:30.647391', '2025-11-20 17:12:30.647391', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 741, 3, 'Thính gạo làm dùng dần hoặc mua sẵn. Cách làm thính gạo tỷ lệ gạo tẻ: đỗ xanh: gạo nếp là 1:1:3 (50 gram gạo tẻ, 50 gram đậu xanh không vỏ, 150 gram gạo nếp), rang vàng thơm từng loại, xay riêng mịn, lọc qua rây, rồi trộn chung. Tỏi giã nhuyễn, ớt thái lát, lá chanh thái chỉ nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (4866, '2025-11-20 17:12:30.648973', '2025-11-20 17:12:30.648973', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 741, 4, 'Trộn tai heo: Tai heo sau khi thái mỏng ướp với 1 thìa cà phê muối, 1/2 thìa cà phê mì chính, 1/2 thìa cà phê hạt tiêu cùng tỏi băm nhỏ, lá chanh thái chỉ vào. Đeo găng tay trộn đều cho gia vị thấm vào tai heo. Sau đó, vừa cho từng ít một thính vào, đảo bóp đều cho thính ngấm vào tai heo. Lượng thính vừa phải, không nên nhiều quá sẽ bị bứ, dính. Cho nem tai ra đĩa, rắc chút lá chanh, ớt thái lát lên trên. Nếu nhà có trẻ nhỏ thì bỏ ớt.', 10);
INSERT INTO public.recipe_steps VALUES (4867, '2025-11-20 17:12:30.650039', '2025-11-20 17:12:30.650039', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 741, 1, 'Sơ chế tai heo: Tai heo cạo sạch, chà xát chanh và muối hạt rồi rửa nhiều lần cho sạch. Cho tai heo vào nồi ngập nước, thêm gừng đập dập, hành tím, 1 thìa canh giấm, 1 thìa cà phê muối, 1 thìa cà phê hạt nêm rồi đun sôi. Chú ý vớt bỏ bọt, hạ lửa nhỏ vừa luộc tai heo trong 15 - 20 phút (tùy tai to hay nhỏ). Vớt tai heo ra ngâm vào nước sôi để nguội cùng đá viên, vài lát chanh để hãm nhiệt giúp tai vừa trắng vừa giòn lại thơm hơn.', 10);
INSERT INTO public.recipe_steps VALUES (4868, '2025-11-20 17:12:30.651626', '2025-11-20 17:12:30.651626', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 741, 2, 'Tai heo nguội vớt ra, thấm thật khô, dùng dao sắc thái thành các lát mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (4869, '2025-11-20 17:12:30.652691', '2025-11-20 17:12:30.652691', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 741, 5, 'Yêu cầu thành phẩm: Tai heo trắng hồng, giòn sần sật, nêm vị vừa đủ, dậy mùi thơm của thính gạo rất hấp dẫn. Món này ăn chơi hay ăn cùng cơm trắng đều phù hợp.', 10);
INSERT INTO public.recipe_steps VALUES (4870, '2025-11-20 17:12:30.923595', '2025-11-20 17:12:30.923595', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 742, 2, 'Cho khoai lên xửng hấp, khi khoai bung nở, nứt ra là đã chín mềm.', 10);
INSERT INTO public.recipe_steps VALUES (4871, '2025-11-20 17:12:30.925184', '2025-11-20 17:12:30.925184', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 742, 1, 'Khoai lang gọt vỏ, cắt khoanh tròn cho vào chậu nước để không bị thâm, rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (4872, '2025-11-20 17:12:30.92731', '2025-11-20 17:12:30.92731', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 742, 6, 'Vớt khoai lang kén ra để lên giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (4873, '2025-11-20 17:12:30.928902', '2025-11-20 17:12:30.928902', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 742, 5, 'Đun nóng dầu ăn (lượng dầu ăn nhiều chút), thử đầu đũa thấy sủi tăm là đạt độ nóng, chia các mẻ cho khoai vào chiên ở lửa vừa. Khi khoai vàng một mặt thì trở đều chiên mặt còn lại cho tới khi vàng giòn là được.', 10);
INSERT INTO public.recipe_steps VALUES (4874, '2025-11-20 17:12:30.930508', '2025-11-20 17:12:30.930508', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 742, 7, 'Yêu cầu thành phẩm: Khoai lang kén bên ngoài giòn vàng, bên trong ngọt mềm, thơm mùi mè. Món ăn bình dị này được nhiều người yêu thích, nhất là các bé nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (4875, '2025-11-20 17:12:30.9321', '2025-11-20 17:12:30.9321', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 742, 3, 'Cho khoai ra bát tô to nghiền nát hoặc cho vào cối giã nhuyễn lúc còn nóng thì khoai sẽ mịn hơn.', 10);
INSERT INTO public.recipe_steps VALUES (4876, '2025-11-20 17:12:30.933708', '2025-11-20 17:12:30.933708', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 742, 4, 'Cho vào khoai lang nghiền 150 gr bột chiên giòn, 50ml nước cốt dừa hoặc sữa tươi, 30 gr đường (điều chỉnh độ ngọt theo khẩu vị),1/2 thìa cà phê muối để món ăn ngon hơn. Đeo găng tay nhào kỹ cho tới khi thành hỗn hợp đồng nhất mịn màng. Để bột nghỉ tầm 20-30 phút, sau đó lấy thìa múc một lượng vừa đủ, vo viên tròn rồi nắn thành hình thoi 6 cm. Lăn qua vừng (mè đen) để bao áo cho kén.', 10);
INSERT INTO public.recipe_steps VALUES (4877, '2025-11-20 17:12:31.203455', '2025-11-20 17:12:31.203455', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 743, 1, 'Chuối sứ lột bỏ vỏ, tước bỏ các sợi gân, rửa qua nước muối loãng để không bị thâm, ướp với 2 - 3 thìa canh đường, 1/4 thìa cà phê muối khoảng 30 phút để có vị đậm đà.', 10);
INSERT INTO public.recipe_steps VALUES (4878, '2025-11-20 17:12:31.205033', '2025-11-20 17:12:31.205033', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 743, 2, 'Gạo nếp vo sạch, ngâm 6 - 8 tiếng (hoặc 2 - 3 tiếng với nước ấm nóng) rồi đồ xôi như bình thường. Khi xôi chín, rưới thêm chút nước cốt dừa trộn đều, đồ thêm 10 phút cho mềm dẻo. Hoặc cho gạo nếp đã ngâm vào nồi cơm điện, thêm nước cốt dừa xâm xấp cùng 1/2 thìa cà phê muối hạt, bật chế độ nấu chín như bình thường.', 10);
INSERT INTO public.recipe_steps VALUES (4879, '2025-11-20 17:12:31.206628', '2025-11-20 17:12:31.206628', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 743, 5, 'Cho nước cốt dừa vào nồi, thêm 3 - 4 thìa canh đường (tùy chỉnh theo khẩu vị), 2 thìa cà phê bột năng, 1/4 thìa cà phê muối, vài lá dứa cho thơm, khuấy đều trên lửa nhỏ. Khi thấy hơi sền sệt là được.', 10);
INSERT INTO public.recipe_steps VALUES (4880, '2025-11-20 17:12:31.208778', '2025-11-20 17:12:31.208778', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 743, 3, 'Múc lượng xôi phù hợp dàn mỏng đều vào lớp nilon sạch, cho chuối vào giữa rồi cuộn tròn, túm hai đầu và bao bọc lại. Làm lần lượt cho tới hết. Sau đó, bọc lá chuối ở bên ngoài.', 10);
INSERT INTO public.recipe_steps VALUES (4881, '2025-11-20 17:12:31.210396', '2025-11-20 17:12:31.210396', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 743, 4, 'Cho chuối nếp vào lò nướng hoặc nướng trên than hoa, trở đều các mặt. Khi lá chuối cháy xém, vỏ xôi giòn vàng và dậy mùi thơm là được.', 10);
INSERT INTO public.recipe_steps VALUES (4882, '2025-11-20 17:12:31.211992', '2025-11-20 17:12:31.211992', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 743, 7, 'Yêu cầu thành phẩm: Vỏ nếp nóng giòn quyện chuối dẻo ngọt, nước cốt dừa béo ngậy, đậu phộng thơm bùi tạo nên món ngon khó cưỡng.', 10);
INSERT INTO public.recipe_steps VALUES (4883, '2025-11-20 17:12:31.213714', '2025-11-20 17:12:31.213714', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 743, 6, 'Cắt chuối nếp nướng lúc còn nóng thành từng miếng vừa ăn, rưới nước cốt dừa, rắc thêm đậu phộng rang giã dập và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (4884, '2025-11-20 17:12:31.456356', '2025-11-20 17:12:31.456356', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 744, 2, 'Mộc nhĩ, miến ngâm nở, rửa sạch, để rổ thưa cho ráo nước. Sau đó, cắt nhỏ. Hành lá, rau mùi rửa sạch, vẩy ráo nước, thái nhỏ. Cà rốt thái sợi nhỏ. Hành tây cắt nhỏ. Trộn đều thịt xay cùng các nguyên liệu trên, nêm 1/2 thìa cà phê muối, 1/2 thìa cà phê hạt nêm, 1/2 thìa cà phê hạt tiêu. Trộn đều rồi chia thành 8 - 10 phần và nặn thành các viên tròn.', 10);
INSERT INTO public.recipe_steps VALUES (4885, '2025-11-20 17:12:31.457958', '2025-11-20 17:12:31.457958', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 744, 4, 'Trong lúc chờ bột nghỉ thì làm nước mắm chua ngọt và dưa góp. Cách làm dưa góp:Xem tại đây; Cách làm nước mắm chua ngọt:Xem tại đây', 10);
INSERT INTO public.recipe_steps VALUES (4887, '2025-11-20 17:12:31.461882', '2025-11-20 17:12:31.461882', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 744, 6, 'Rán bánh lần 2 cần tăng nhiệt độ cao hơn và đảm bảo ngập dầu, đảo đều cho tới khi bánh có vỏ vàng ruộm. Việc tăng nhiệt độ cũng giúp cho bánh thoát dầu, khô ráo. Vớt bánh ra để rổ thưa.', 10);
INSERT INTO public.recipe_steps VALUES (4888, '2025-11-20 17:12:31.464053', '2025-11-20 17:12:31.464053', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 744, 1, 'Khoai tây gọt vỏ, cắt lát mỏng, hấp chín, nghiền nhuyễn mịn. Cho bột gạo nếp, gạo tẻ và khoai tây nghiền vào tô lớn, thêm từ từ nước ấm (40-45 độ). Vừa đổ lượng nhỏ nước ấm, vừa dùng tay nhồi nhẹ, căn chỉnh và dừng lại nước cho tới khi đã đạt được khối bột mịn dẻo. Bọc màng bọc thực phẩm cho bột nghỉ 1 giờ.', 10);
INSERT INTO public.recipe_steps VALUES (4889, '2025-11-20 17:12:31.465108', '2025-11-20 17:12:31.465108', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 744, 5, 'Nên rán (chiên) bánh ngập dầu và 2 lần lửa sẽ giúp bánh vàng giòn. Lần 1 rán bánh ở lửa nhỏ vừa để bánh nở từ từ và chín đều từ trong ra ngoài. Chú ý đảo nhẹ để các bánh không dính vào nhau và đảm bảo luôn có dầu nóng bao quanh bánh. Khi bánh hơi ngả vàng thì vớt ra để nguội bớt.', 10);
INSERT INTO public.recipe_steps VALUES (4890, '2025-11-20 17:12:31.46721', '2025-11-20 17:12:31.46721', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 744, 3, 'Bột sau khi ủ thì đem chia thành 8 - 10 phần tương ứng phần nhân đã làm. Lấy bột vê tròn rồi ấn dẹp, nắn cho rìa mỏng hơn, rồi đặt nhân vào giữa. Chú ý vuốt bột áp bám nhân để không khí không lọt vào dễ gây nổ khi rán. Bao bột mép lại và nặn thành hình như kén tằm. Làm lần lượt cho tới khi hết. Sau đó bọc màng bọc thực phẩm cho bột nghỉ tiếp 1 giờ.', 10);
INSERT INTO public.recipe_steps VALUES (4891, '2025-11-20 17:12:31.691153', '2025-11-20 17:12:31.691153', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 745, 1, 'Sắn rửa sạch, cắt bỏ phần đầu cho bớt xơ, khía tròn rồi bóc hết phần vỏ, rửa sạch, ngâm nước muối loãng từ 2,5 - 4 tiếng cho ra nhựa, loại bỏ độc tố. Nếu kỹ hơn thì thay nước 30 phút một lần.', 10);
INSERT INTO public.recipe_steps VALUES (4892, '2025-11-20 17:12:31.693278', '2025-11-20 17:12:31.693278', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 745, 3, 'Gắp sắn vào nồi, thêm 200 ml nước cốt dừa, 60 ml nước dừa tươi, 20 g đường, 1/2 thìa cà phê muối vào lắc nhẹ đều và đun ở lửa nhỏ vừa cho thấm nước sốt vào sắn. Sau khoảng 10 -12 phút thì nước sốt sánh dần lại. Tắt bếp, lấy sắn ra, rắc dừa nạo sợi và rắc lạc rang giã dập lên thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (4893, '2025-11-20 17:12:31.69487', '2025-11-20 17:12:31.69487', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 745, 2, 'Cho sắn vào nồi hấp, thêm 2 lá dứa cho thơm. Sau khoảng 20 phút thì sắn chín nở bung đôi ra. Tắt bếp, gắp sắn ra.', 10);
INSERT INTO public.recipe_steps VALUES (4894, '2025-11-20 17:12:31.696998', '2025-11-20 17:12:31.696998', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 745, 4, 'Yêu cầu thành phẩm: Sắn mềm bở, quyện trong nước cốt dừa béo ngậy, lạc rang bùi bùi quyến rũ bao tín đồ ăn vặt Hà thành vào chiều đông.', 10);
INSERT INTO public.recipe_steps VALUES (4895, '2025-11-20 17:12:31.961584', '2025-11-20 17:12:31.961584', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 746, 4, 'Xếp bánh vào xửng, hấp chừng 10-15 phút.', 10);
INSERT INTO public.recipe_steps VALUES (4896, '2025-11-20 17:12:31.96323', '2025-11-20 17:12:31.96323', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 746, 1, 'Bột bánh: Lượng 1 chén bột với 2 chén nước + bọt ngọt + muối + dầu ăn, quậy tan đều, lọc qua rây, cho vào xoong nước, bắc lên bếp lửa to. Dùng đũa quậy luôn tay đến khi bột vừa đặc thì nhắc xuống, tiếp tục quậy cho bột mịn và mau nguội.', 10);
INSERT INTO public.recipe_steps VALUES (4897, '2025-11-20 17:12:31.964797', '2025-11-20 17:12:31.964797', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 746, 2, 'Nhân: Tôm lột vỏ, bỏ chỉ đen trên lưng, chà muối cho sạch nhớt, để ráo, băm nhỏ. Bắc chảo lên bếp, cho 1 muỗng dầu ăn vào và phi thơm với một củ hành băm. Trút tôm vào, đảo đều. Nêm gia vị vừa ăn, xào đến khi khô, tắt bếp. Cho tôm vào cối, giã cho tôm tơi ra, xong trút lại vào chảo, đặt lên bếp lửa nhỏ, dùng sạn chà cho tôm tơi bông đều.', 10);
INSERT INTO public.recipe_steps VALUES (4898, '2025-11-20 17:12:31.966385', '2025-11-20 17:12:31.966385', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 746, 3, 'Gói bánh: Lá chuối xé bề ngang chừng 25 cm, trụng sơ nước sôi, lau khô. Xếp một lá dọc nằm dưới, 1 lá ngang nằm trên. Thao dầu ăn lên lá (để dễ bóc bánh). Múc 1 muỗng bột vào lá và trải ra hình chữ nhật. Rải nhân tôm nằm giữa bánh theo chiều dọc. Xếp 2 lá lại và bẻ 2 đầu lá. Dùng ống cán đì lên bánh cho bột mỏng đều.', 10);
INSERT INTO public.recipe_steps VALUES (4899, '2025-11-20 17:12:31.968062', '2025-11-20 17:12:31.968062', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 746, 5, 'Trình bày: Bóc bánh, xếp ra đĩa. Dùng với nước mắm ngon.', 10);
INSERT INTO public.recipe_steps VALUES (4900, '2025-11-20 17:12:32.237486', '2025-11-20 17:12:32.237486', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 747, 1, 'Bước 1: Sơ chế nguyên liệu làm nhân: Ức gà lọc bỏ da, ngâm nước muối loãng, rửa sạch, thấm khô, xay sơ. Hành tây cắt, xay sơ. Trộn thịt gà, hành tây với 1 thìa canh đường, 1 thìa canh dầu hào, 1 thìa cà phê hạt nêm, 1 thìa cà phê ớt bột Hàn Quốc, 1/2 thìa cà phê muối, 1 thìa cà phê bột tỏi (hoặc tỏi băm), 1/2 thìa cà phê hạt tiêu. Đặc biệt thêm 2 thìa cà phê mỡ gà tạo độ mướt, mềm ngon cho bánh. Trộn thật đều và quết liên tục (hoặc vo tròn rồi đập mạnh để hỗn hợp trở nên dẻo dính lại, không bị bã, ướt). Bọc màng bọc thực phẩm, cho nhân vào ngăn mát tủ lạnh để ủ bột, tối thiểu 30 phút hoặc muốn nhanh thì cho lên ngăn đá 15 phút cho hỗn hợp se lại, dễ tạo hình hơn.
INSERT INTO public.recipe_steps VALUES (4901, '2025-11-20 17:12:32.444302', '2025-11-20 17:12:32.444302', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 748, 3, 'Lấy 2/3 lượng sắn giã hoặc nghiền nhuyễn cho mịn, 1/3 còn lại thì cắt miếng vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (4902, '2025-11-20 17:12:32.445878', '2025-11-20 17:12:32.445878', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 748, 2, 'Hấp chín sắn cho tới khi nở bung mềm.', 10);
INSERT INTO public.recipe_steps VALUES (4903, '2025-11-20 17:12:32.44746', '2025-11-20 17:12:32.44746', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 748, 4, 'Làm viên sắn mochi: Phần sắn nghiền nhuyễn cho thêm 150 gr bột năng, 20 gr nước cốt dừa, 20 gr đường, 1/4 thìa cà phê muối trộn đều và vo viên tròn. Bao áo bằng chút bột năng cho đỡ dính. Đun sôi nước, cho các viên sắn mochi vào, đảo nhẹ và luộc cho tới khi mochi nổi lên, bột chuyển màu trong là đã chín. Vớt ra cho vào bát nước nguội để tránh dính. Khi nào ăn thì đun nước đường gừng và cho mochi vào.', 10);
INSERT INTO public.recipe_steps VALUES (4927, '2025-11-20 17:12:33.215015', '2025-11-20 17:12:33.215015', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 752, 4, 'Dùng muỗng múc kem ra ly, trang trí thêm bánh bơ nướng, trái cây và lá bạc hà thùy theo sở thích riêng.', 10);
INSERT INTO public.recipe_steps VALUES (4904, '2025-11-20 17:12:32.449092', '2025-11-20 17:12:32.449092', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 748, 5, 'Cho 1,2 lít nước cùng 150gr đường vàng (hoặc mật mía, điều chỉnh độ ngọt theo khẩu vị), thêm gừng thái sợi, 1/4 thìa cà phê muối lên bếp đun sôi, khuấy đều cho đường tan.', 10);
INSERT INTO public.recipe_steps VALUES (4905, '2025-11-20 17:12:32.45015', '2025-11-20 17:12:32.45015', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 748, 8, 'Yêu cầu thành phẩm: Từng viên mochi sắn dẻo bùi quyện trong nước đường gừng ấm nóng, dừa sợi sần sật, đậu phộng giòn thơm khiến cho các tín đồ ăn vặt mê mẩn.', 10);
INSERT INTO public.recipe_steps VALUES (4906, '2025-11-20 17:12:32.451742', '2025-11-20 17:12:32.451742', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 748, 1, 'Sắn bóc bỏ vỏ, ngâm nước muối loãng hoặc nước vo gạo 6 - 7 tiếng cho hết độc tố và không bị thâm.', 10);
INSERT INTO public.recipe_steps VALUES (4907, '2025-11-20 17:12:32.452794', '2025-11-20 17:12:32.452794', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 748, 7, 'Hòa tan bột năng với chút nước rồi cho dần xuống nồi chè, vừa cho vừa khuấy cho tới khi sánh lại theo mong muốn. Hạ nhỏ lửa và nấu cho bột năng chín hẳn trong 9 - 10 phút. Sau đó, tắt bếp, múc chè sắn ra bát, rắc thêm dừa nạo sợi, lạc hoặc vừng rang rồi rưới nước cốt dừa và thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (4908, '2025-11-20 17:12:32.454382', '2025-11-20 17:12:32.454382', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 748, 6, 'Vớt các viên sắn mochi cho vào nồi nước đường, thêm sắn cắt miếng. Nấu khoảng 2 phút cho hỗn hợp nước đường quyện vị vào sắn mochi.', 10);
INSERT INTO public.recipe_steps VALUES (4909, '2025-11-20 17:12:32.701438', '2025-11-20 17:12:32.701438', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 749, 2, 'Thịt nạc vai băm nhỏ. Nấm hương ngâm nở thái nhỏ. Gừng một phần thái chỉ ngâm nước, còn lại giã nhỏ. Lá gừng rửa sạch để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (4910, '2025-11-20 17:12:32.7031', '2025-11-20 17:12:32.7031', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 749, 5, 'Đem hấp cách thuỷ khoảng 15 phút, thời gian phụ thuộc vào ốc to hay ốc nhỏ. Khi ốc chín lấy ra bầy vào đĩa, rắc gừng thái chỉ, ớt tỉa hoa trang trí đẹp, ăn nóng (chấm ốc với nước chấm chua cay ngọt cân đối, lá chanh gừng thái chỉ).', 10);
INSERT INTO public.recipe_steps VALUES (4911, '2025-11-20 17:12:32.704205', '2025-11-20 17:12:32.704205', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 749, 4, 'Đặt lá gong ngang miệng ốc, nhồi nhân vào cho đầy ngang miệng ốc, xoa mặt nhân cho mịn, xếp ốc vào lồng hấp.', 10);
INSERT INTO public.recipe_steps VALUES (4912, '2025-11-20 17:12:32.705804', '2025-11-20 17:12:32.705804', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 749, 1, 'Ốc nhồi chế sạch. Phần vỏ giữ nguyên, rửa sạch, luộc chín lau khô. Phần thịt ốc thái hạt lựu nhỏ để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (4913, '2025-11-20 17:12:32.707412', '2025-11-20 17:12:32.707412', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 749, 3, 'Trộn thịt ốc với một chút nước gừng, hạt tiêu, mì chính, ớt băm nhỏ, nấm hương, nạc vai, giò sống. Quật nhân cho dẻo, để ngấm 10 phút, chia nhân tương ứng số vỏ.', 10);
INSERT INTO public.recipe_steps VALUES (4914, '2025-11-20 17:12:32.845659', '2025-11-20 17:12:32.845659', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 750, 5, 'Tiếp tục cho khoai tây vào nướng ở 200 độ C cho tới khi vàng giòn trong khoảng 20 - 30 phút là được.', 10);
INSERT INTO public.recipe_steps VALUES (4915, '2025-11-20 17:12:32.847339', '2025-11-20 17:12:32.847339', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 750, 3, 'Phết đều sốt dầu bơ tỏi lên khắp củ khoai tây, rắc chút muối tinh và hạt tiêu cùng lá xạ hương.', 10);
INSERT INTO public.recipe_steps VALUES (4916, '2025-11-20 17:12:32.848394', '2025-11-20 17:12:32.848394', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 750, 2, 'Khoai tây chà sạch đất cát, ngâm nước muối loãng, rửa sạch, để ráo hoặc thấm khô. Để 2 chiếc đũa ở hai bên củ khoai tây, dùng dao sắc cắt thành các lát mỏng 5mm rồi dừng lại ở mép chạm đầu đũa. Việc này để đảm bảo không cắt rời khoai tây mà có sự bám dính ở cuối.', 10);
INSERT INTO public.recipe_steps VALUES (4917, '2025-11-20 17:12:32.849435', '2025-11-20 17:12:32.849435', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 750, 4, 'Bật nóng lò nướng trước 10 phút, cho khoai tây vào nướng ở 200 độ C. Sau 30 phút lấy ra, phết thêm sốt bơ tỏi và rắc thêm lá xạ hương.', 10);
INSERT INTO public.recipe_steps VALUES (4918, '2025-11-20 17:12:32.853716', '2025-11-20 17:12:32.853716', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 750, 6, 'Yêu cầu thành phẩm: Lớp vỏ ngoài giòn vàng, bên trong mềm, dậy mùi thơm của bơ tỏi và lá xạ hương. Món này ăn kèm với bò bít tết rất hấp dẫn, tạo nên bữa tiệc hoàn hảo nhân dịp năm mới.', 10);
INSERT INTO public.recipe_steps VALUES (4919, '2025-11-20 17:12:32.855792', '2025-11-20 17:12:32.855792', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 750, 1, 'Làm sốt bơ tỏi: Cho 1 muỗng canh dầu ô liu vào chảo, thêm tỏi và bơ lạt, một chút lá xạ hương rồi nấu trên lửa vừa cho tới khi bơ tan chảy hết và tỏi ngả vàng, dậy mùi thơm là được. Tắt bếp, lọc qua rây lấy sốt dầu bơ tỏi để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (4920, '2025-11-20 17:12:32.995002', '2025-11-20 17:12:32.995002', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 751, 4, 'Trình bày và thưởng thức: Bày cốm ra đĩa (hoặc lá sen, lá nếp, lá chuối), dàn đều, rắc thêm chút dừa nạo sợi và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (4921, '2025-11-20 17:12:32.997153', '2025-11-20 17:12:32.997153', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 751, 2, 'Xào cốm: Vẩy một chút nước dừa lên cốm, trộn đều cho cốm mềm. Cho vào chảo chống dính phần nước dừa và đường còn lại đun sôi ở lửa nhỏ vừa. Khi nước đường sánh lại thì cho cốm vào. Để lửa nhỏ, thêm chút dầu ăn, đảo đều tay cho cốm ngậm đường.', 10);
INSERT INTO public.recipe_steps VALUES (4922, '2025-11-20 17:12:32.998236', '2025-11-20 17:12:32.998236', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 751, 3, 'Tiếp tục cho phần dừa xào vào, tiếp tục đảo nhẹ trên lửa nhỏ cho tới khi được hỗn hợp cốm dừa dẻo mềm, không dính chảo là đạt.', 10);
INSERT INTO public.recipe_steps VALUES (4923, '2025-11-20 17:12:33.00037', '2025-11-20 17:12:33.00037', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 751, 1, 'Xào dừa: Hòa tan 2-3 thìa canh nước dừa tươi (hoặc nước lọc) và cho 1/2 lượng đường vào đun sôi, cho 1/2 phần dừa nạo vào xào. Hạ nhỏ lửa và sên cho tới khi dừa trong là được, múc ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (4924, '2025-11-20 17:12:33.210282', '2025-11-20 17:12:33.210282', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 752, 3, 'Cho hỗn hợp kem vào khuôn rồi để vào ngăn đá tủ lạnh, khoảng 1 giờ sau lấy kem ra trộn đều lên 1 lần nữa, rồi cho vào ngăn đá 4 - 5 giờ sau là dùng được.', 10);
INSERT INTO public.recipe_steps VALUES (4925, '2025-11-20 17:12:33.211854', '2025-11-20 17:12:33.211854', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 752, 1, 'Cho lòng đỏ trứng vào tô lớn, dùng máy đánh trứng đánh nổi rồi cho đường xay vào và tiếp tục đánh cho tan đường. Cho sữa tươi vào nồi nấu trên lửa nhỏ đến khi sữa vừa sôi tới, đóng váng trên mặt.', 10);
INSERT INTO public.recipe_steps VALUES (4926, '2025-11-20 17:12:33.213437', '2025-11-20 17:12:33.213437', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 752, 2, 'Rót từ từ sữa nóng vào hỗn hợp trứng đường, vừa rót vừa khuấy đều, đợi cho hỗn hợp này nguội, cho tiếp rượu rhum vào trộn đều lên. Cho kem tươi vào tô lớn, dùng máy đánh trứng đánh cho đến khi kem nổi mịn. Trộn đều kem tươi với hỗn hợp trứng sữa và nho khô.', 10);
INSERT INTO public.recipe_steps VALUES (4928, '2025-11-20 17:12:33.493335', '2025-11-20 17:12:33.493335', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 753, 2, 'Lá dứa, rửa sạch, xắt nhỏ, xay nhuyễn với ít nước, lược lấy nước cốt.', 10);
INSERT INTO public.recipe_steps VALUES (4929, '2025-11-20 17:12:33.494947', '2025-11-20 17:12:33.494947', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 753, 4, 'Rưới hỗn hợp nước dừa từ từ vào cốm, vừa rưới, vừa trộn đều cho hạt cốm nở, mềm.', 10);
INSERT INTO public.recipe_steps VALUES (4930, '2025-11-20 17:12:33.496616', '2025-11-20 17:12:33.496616', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 753, 3, 'Cho nước cốt dừa và đường vào nồi nấu lửa nhỏ cho tan đường. Cho nước lá dứa vào nước cốt dừa, khuấy lên, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (4931, '2025-11-20 17:12:33.49873', '2025-11-20 17:12:33.49873', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 753, 1, 'Cốm dẹp, xả nhanh qua nước lạnh cho sạch bụi bẩn, để ráo. Dừa trắng nạo.', 10);
INSERT INTO public.recipe_steps VALUES (4932, '2025-11-20 17:12:33.500845', '2025-11-20 17:12:33.500845', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 753, 5, 'Sau cùng trộn dừa vào cốm.', 10);
INSERT INTO public.recipe_steps VALUES (4933, '2025-11-20 17:12:33.836379', '2025-11-20 17:12:33.836379', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 754, 5, 'Nặn và bao nhân bánh:Đặt vỏ bánh lên mặt phẳng, cho nhân khoai lang tím, phô mai mozzarella vào, gập lại và miết bao kín, có thể nhấp chút nước để miết kín bánh dễ dàng hơn. Làm lần lượt cho tới hết.', 10);
INSERT INTO public.recipe_steps VALUES (4934, '2025-11-20 17:12:33.837437', '2025-11-20 17:12:33.837437', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 754, 1, 'Chuẩn bị nhân:Khoai lang tím gọt vỏ, cắt miếng, hấp chín mềm, tán/nghiền nhuyễn. Thêm chút mật ong (hoặc sữa đặc) tạo độ kết dính, trộn đều. Phô mai mozzarella cắt nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (4935, '2025-11-20 17:12:33.839566', '2025-11-20 17:12:33.839566', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 754, 2, 'Phần bột vỏ (bột nước):Cho120 g bột mì đa dụng, 25 ml dầu ăn, 25 g bơ lạt, 30 g đường, 50-60ml nước lọc, 1/2 muỗng cà phê muối, trộn đều rồi nhồi thành khối, bọc màng bọc thực phẩm cho bột nghỉ 30 phút sau đó nhào mịn, chia thành 8 phần bằng nhau. Nên ủ bột khi hấp khoai lang tím để giảm thời gian chờ.', 10);
INSERT INTO public.recipe_steps VALUES (4936, '2025-11-20 17:12:33.841177', '2025-11-20 17:12:33.841177', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 754, 4, 'Tạo vỏ bánh:Tùy theo sở thích bạn tạo hình tròn hoặc chữ nhật.Vo tròn bột vỏ, cán hình oval, thêm bột dầu dàn đều rồi cuộn tròn lại như bánh ốc quế. Làm lần lượt cho tới hết, để nghỉ 5 phút. Tiếp tục cán dẹt theo chiều dọc, gấp 2 đầu mép, cắt phần dư tạo thành hình chữ nhật, cán sơ lần 1, làm lần lượt cho tới hết, rồi quay trở lại cán lần nữa.', 10);
INSERT INTO public.recipe_steps VALUES (4937, '2025-11-20 17:12:33.8428', '2025-11-20 17:12:33.8428', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 754, 8, 'Yêu cầu thành phẩm:Bánh vỏ ngoài vàng xốp nhẹ, tách lớp, nhân khoai lang mềm mịn, phô mai tan chảy rất hấp dẫn và thơm ngon.', 10);
INSERT INTO public.recipe_steps VALUES (4938, '2025-11-20 17:12:33.843884', '2025-11-20 17:12:33.843884', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 754, 6, 'Phết lòng đỏ trứng:Đánh tan 1 lòng đỏ trứng và chút dầu ăn rồi phết đều lên bề mặt bánh, rắc thêm chút mè đen cho đẹp mắt.', 10);
INSERT INTO public.recipe_steps VALUES (4939, '2025-11-20 17:12:33.845508', '2025-11-20 17:12:33.845508', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 754, 3, 'Phần bột dầu: Trộn đều 100gr bột mì đa dụng, 50gr bơ lạt, nhào mịn, để bột nghỉ 30 phút, chia 8 phần bằng nhau.', 10);
INSERT INTO public.recipe_steps VALUES (4940, '2025-11-20 17:12:33.846723', '2025-11-20 17:12:33.846723', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 754, 7, 'Nướng bánh: Bật trước lò nướng trước 10 phút ở 180 độ, rồi cho bánh vào nướng khoảng 25 phút khi vỏ vàng xốp là đạt.', 10);
INSERT INTO public.recipe_steps VALUES (4941, '2025-11-20 17:12:34.039485', '2025-11-20 17:12:34.039485', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 755, 1, 'Làm hỗn hợp bột bánh giầy: Cho cơm nguội cùng 180 ml nước nóng vào xay thật nhuyễn, lọc qua rây lấy hỗn hợp bột mịn. Thêm 200 g bột nếp, 1 muỗng canh dầu ăn, 1/2 muỗng cà phê muối, trộn đều. Tùy vào bột nếp mới hay cũ với mức độ hút nước khác nhau, bạn điều chỉnh cho phù hợp. Đeo găng tay nhào bột cho tới khi thành hỗn hợp dẻo mịn, không dính tay là đạt. Để bột nghỉ 15-20 phút.', 10);
INSERT INTO public.recipe_steps VALUES (4942, '2025-11-20 17:12:34.041052', '2025-11-20 17:12:34.041052', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 755, 2, 'Tạo hình bánh:Chia bột thành các khối đều nhau, vo tròn, ấn dẹt đặt lên lá chuốt (đã thoa chút dầu ăn) hoặc giấy nến.', 10);
INSERT INTO public.recipe_steps VALUES (4943, '2025-11-20 17:12:34.042099', '2025-11-20 17:12:34.042099', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 755, 3, 'Hấp bánh:Đun nồi nước sôi, hạ lửa nhỏ vừa, cho xửng và đặt bánh lên hấp 7-10 phút là chín. Để tránh hơi nước đọng vụng nồi rơi xuống có 2 cách: Phủ khăn xô lên khăn khi hấp hoặc cứ 3 phút mở vung một lần ra ngoài cho chảy hết nước.', 10);
INSERT INTO public.recipe_steps VALUES (4944, '2025-11-20 17:12:34.043677', '2025-11-20 17:12:34.043677', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 755, 4, 'Trình bày và thưởng thức: Lấy bánh ra, kẹp với giò lụa, rắc thêm chút muối tiêu và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (4945, '2025-11-20 17:12:34.480257', '2025-11-20 17:12:34.480257', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 756, 1, 'Chọn ngày nắng ráo, mua củ cải non về gọt vỏ, thái khoanh mỏng, phơi khô (để miếng dưa giòn, hũ dưa không bị nhớt). Cà rốt tỉa hoa, phơi trước khi muối 2-3 ngày. Hành bóc vỏ, ngâm nước muối một đêm cho đỡ hăng, vớt ra để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (4946, '2025-11-20 17:12:34.482009', '2025-11-20 17:12:34.482009', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 756, 3, 'Món dưa góp có mùi thơm đậm đà, ăn giòn, ngọt, là món ăn kèm giúp bạn đỡ ngán khi ăn các món bổ dưỡng. Nếu làm đúng cách, món này có thể để hàng tháng mà hương vị vẫn nguyên như ngày đầu, không bị chua.', 10);
INSERT INTO public.recipe_steps VALUES (4947, '2025-11-20 17:12:34.484144', '2025-11-20 17:12:34.484144', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 756, 2, 'Rửa qua củ cải, cà rốt, trộn với hành củ, cho vào hũ. Nước mắm ngon đun lên, khuấy đường cho tan đều (nếu không đun, hũ dưa sẽ dễ bị mốc, chua, nước đục). Để nguội rồi rót vào hũ, thêm ớt, tỏi bóc vỏ, ngâm khoảng 15 ngày là ăn được.', 10);
INSERT INTO public.recipe_steps VALUES (4948, '2025-11-20 17:12:34.783305', '2025-11-20 17:12:34.783305', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 757, 2, 'Đãi sạch, xóc với ít muối, cho vào nồi đồ, thỉnh thoảng rưới ít nước cốt dừa lên.', 10);
INSERT INTO public.recipe_steps VALUES (4949, '2025-11-20 17:12:34.785459', '2025-11-20 17:12:34.785459', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 757, 5, 'Xôi chín, bắc xuống, đánh tơi, cho cá vào, đánh đều lên, nhẹ tay để cá không bị nát. Xúc ra đĩa, rắc hành khô.', 10);
INSERT INTO public.recipe_steps VALUES (4950, '2025-11-20 17:12:34.787609', '2025-11-20 17:12:34.787609', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 757, 1, 'Gạo nếp ngâm nước ấm khoảng 2 giờ.', 10);
INSERT INTO public.recipe_steps VALUES (4951, '2025-11-20 17:12:34.789178', '2025-11-20 17:12:34.789178', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 757, 4, 'Bắc chảo lên bếp, đun nóng dầu ăn, cho hành khô vào phi vàng, vớt ra, chắt bớt dầu, cho hành tươi vào phi thơm, cho cá vào xào ngấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (4952, '2025-11-20 17:12:34.7914', '2025-11-20 17:12:34.7914', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 757, 3, 'Cá rô phi đánh vẩy, moi bỏ ruột, rửa sạch, bóp với gừng, rượu rồi hấp chín, để nguội, gỡ thịt ướp với hạt nêm, tiêu.', 10);
INSERT INTO public.recipe_steps VALUES (4953, '2025-11-20 17:12:34.999505', '2025-11-20 17:12:34.999505', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 758, 4, 'Tạo hình bánh: Chia bột thành những phần bằng nhau khoảng 20 g, ấn dẹt, cán bột mỏng dài, gấp một đầu hình tam giác, vừa cuộn vừa dùng đầu ngón tay ấn chặt bột xuống để căng tròn, bóp mép kín lại, vê nhẹ để tạo 2 đầu bánh như hình thoi hoặc bạn tạo hình theo ý muốn.', 10);
INSERT INTO public.recipe_steps VALUES (4954, '2025-11-20 17:12:35.002187', '2025-11-20 17:12:35.002187', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 758, 2, 'Dùng một cái tô, trộn bột mì và muối, tạo vòng tròn nhỏ sâu ở bột và cho bơ lạt (đã tan chảy) hoặc dầu ăn vào trộn đều. Từ từ cho hỗn hợp nước men vào bột, trộn đều. Nhồi bột bằng máy hoặc bằng tay. Nếu nhồi bột bằng tay thì cho bột ra thảm, túm và đập bột, rồi dùng mu bàn tay miết, đẩy bột ra cho tới khi hỗn hợp thành khối bóng mịn, dai và kéo mảng mỏng là đạt.', 10);
INSERT INTO public.recipe_steps VALUES (4955, '2025-11-20 17:12:35.003853', '2025-11-20 17:12:35.003853', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 758, 3, 'Ủ bột lần 1: Phết nhẹ lớp dầu ăn trong tô và bên ngoài bột. Phủ khăn hoặc bọc màng bọc thực phẩm để ủ bột khoảng 30 phút cho tới khi bột nở gấp đôi.', 10);
INSERT INTO public.recipe_steps VALUES (4956, '2025-11-20 17:12:35.006525', '2025-11-20 17:12:35.006525', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 758, 6, 'Nướng bánh: Sau khi bánh nở, dùng dao lam nhúng nước nóng rạch 1 đường dứt khoát trên mặt bánh, xịt/phun nước và cho vào lò nướng ngay. Chú ý: Thêm đá nướng hoặc khay nước nóng. Nướng lần 1 khoảng 10 phút, cứ cách 3 phút lại xịt nước. Sau 10 phút, lấy mâm bánh ra xoay để bánh chín đều, lấy khay đá nướng/nước nóng ra. Cho bánh vào nướng thêm 5 -10 phút cho tới khi bánh vàng giòn là được.', 10);
INSERT INTO public.recipe_steps VALUES (4957, '2025-11-20 17:12:35.008265', '2025-11-20 17:12:35.008265', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 758, 7, 'Thành phẩm:Vỏ bên ngoài vàng giòn tan, ruột mềm mại, không bị khô. Bạn có thể thưởng thức bánh mì chấm cùng sữa đặc, mứt trái cây hoặc phết pate, kẹp thịt rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (4958, '2025-11-20 17:12:35.010758', '2025-11-20 17:12:35.010758', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 758, 1, 'Nhồi bột: Pha nước ấm với đường, men nở, khuấy tan và nghỉ 10 phút cho men kích hoạt và nở như gạch cua.', 10);
INSERT INTO public.recipe_steps VALUES (4959, '2025-11-20 17:12:35.012881', '2025-11-20 17:12:35.012881', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 758, 5, 'Ủ bột lần 2:Tiếp tục ủ bột trong khoảng 30 phút cho tới khi bánh nở gấp rưỡi hoặc gấp đôi. Trong lúc chờ ủ bánh thì làm nóng lò nướng.', 10);
INSERT INTO public.recipe_steps VALUES (4960, '2025-11-20 17:12:35.365464', '2025-11-20 17:12:35.365464', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 759, 1, 'Ngâm ốc vào thau/chậu bằng kim loại cùng vài lát ớt tươi trong 1 giờ giúp ốc nhả hết cặn bẩn. Sau đó rửa sạch.', 10);
INSERT INTO public.recipe_steps VALUES (4961, '2025-11-20 17:12:35.367619', '2025-11-20 17:12:35.367619', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 759, 3, 'Có 2 cách luộc ốc: Không dùng nước và dùng nước. Một số người thích ốc đậm vị thì luộc không nước vì khi luộc ốc cũng ra nước nhiều, chú ý lót dưới đáy nồi lớp sả, lá bưởi (hoặc lá chanh) rồi cho ốc vào luộc tới khi mở miệng. Nếu thích uống nước luộc ốc thì đun sôi chút nước, thêm chút muối, sả đập dập, lá chanh và cho ốc vào luộc. Khi nước sôi bùng lên thì mở nắp, đảo đều khoảng 2 - 3 phút hoặc cho tới khi ốc mở miệng là được, tắt bếp, đậy vung giữ độ nóng, khi ăn tới đâu thì múc tới đó.', 10);
INSERT INTO public.recipe_steps VALUES (4962, '2025-11-20 17:12:35.370308', '2025-11-20 17:12:35.370308', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 759, 5, 'Thành phẩm: Ốc chín vừa tới giòn dai, nước chấm ốc sánh, đậm đà tỏa mùi hương thơm của sả, lá chanh, ớt. Nếu thích uống nước ốc thì cho thêm chút nước chấm vào cho đậm vị, vị cay cay thơm nồng giúp xua tan cái lạnh của mùa đông.', 10);
INSERT INTO public.recipe_steps VALUES (4963, '2025-11-20 17:12:35.372268', '2025-11-20 17:12:35.372268', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 759, 4, 'Pha nước chấm ốc: Tỷ lệ đường, mắm (30 - 40 độ đạm), nước cốt quất (tắc) và nước lọc là: 1:1:1:3 (50 gr đường, 50 ml nước mắm, 50ml nước cốt tắc, 150 ml nước lọc). Cho nước lọc, đường và thêm 1 thìa cà phê muối vào nồi đun sôi, khuấy đều cho tan đường để giúp nước chấm sánh hơn. Cho vào cối tỏi, gừng, sả (thái ra), ớt rồi dùng chày giã nhuyễn. Lá chanh thái chỉ, vắt lấy nước tắc (quất). Khi nước đường nguội, cho 50ml nước mắm, 50ml nước cốt tắc, tỏi gừng sả ớt giã nhuyễn cùng lá chanh thái chỉ vào, khuấy đều là có nước chấm ngon đậm đà.', 10);
INSERT INTO public.recipe_steps VALUES (4964, '2025-11-20 17:12:35.374348', '2025-11-20 17:12:35.374348', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 759, 2, 'Tiếp tục ngâm ốc với nước vo gạo và đập thêm 1 quả trứng gà trong 1- 2 giờ để giúp ốc béo hơn. Sau đó, rửa sạch nhiều lần.', 10);
INSERT INTO public.recipe_steps VALUES (4965, '2025-11-20 17:12:35.598957', '2025-11-20 17:12:35.598957', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 760, 9, 'Nấu sôi nước, thả bánh vào luộc, bánh chín nổi lên, vớt ra. Nấu 2 lít nước đường cho tan, thả bánh trôi vào, cho ít gừng vào.', 10);
INSERT INTO public.recipe_steps VALUES (4966, '2025-11-20 17:12:35.600021', '2025-11-20 17:12:35.600021', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 760, 2, 'Gừng nhỏ đập dập hoặc thái lát mỏng', 10);
INSERT INTO public.recipe_steps VALUES (4967, '2025-11-20 17:12:35.601647', '2025-11-20 17:12:35.601647', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 760, 4, 'Đậu xanh ngâm mềm giã nhỏ', 10);
INSERT INTO public.recipe_steps VALUES (4968, '2025-11-20 17:12:35.602704', '2025-11-20 17:12:35.602704', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 760, 10, 'Múc chè ra chén, chan nước cốt dừa, rắc chút vừng.', 10);
INSERT INTO public.recipe_steps VALUES (4969, '2025-11-20 17:12:35.604283', '2025-11-20 17:12:35.604283', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 760, 7, 'Nấu đậu xanh với nước gião dừa cho mềm, tán nhuyễn, xào với ít mỡ, cho hành lá, nêm chút muối, đường.', 10);
INSERT INTO public.recipe_steps VALUES (4970, '2025-11-20 17:12:35.605868', '2025-11-20 17:12:35.605868', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 760, 3, 'Tôm đất băm nhỏ. Thịt băm nhỏ', 10);
INSERT INTO public.recipe_steps VALUES (4971, '2025-11-20 17:12:35.606913', '2025-11-20 17:12:35.606913', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 760, 8, 'Chia đậu xanh thành từng viên có bọc thịt tôm, chia bột thành từng viên nhỏ. Bọc bột nếp bên ngoài nhân đậu, tôm, thịt.', 10);
INSERT INTO public.recipe_steps VALUES (4972, '2025-11-20 17:12:35.607969', '2025-11-20 17:12:35.607969', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 760, 1, 'Bột nếp nhồi với nước ấm cho dẻo, mịn', 10);
INSERT INTO public.recipe_steps VALUES (4973, '2025-11-20 17:12:35.60953', '2025-11-20 17:12:35.60953', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 760, 6, 'Nhân: Tôm, thịt đảo sơ với gia vị vừa miệng.', 10);
INSERT INTO public.recipe_steps VALUES (4974, '2025-11-20 17:12:35.611219', '2025-11-20 17:12:35.611219', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 760, 5, 'Dừa nạo, vắt lấy nước cốt. Vừng rang vàng thơm, hành lá giã nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (4975, '2025-11-20 17:12:35.740766', '2025-11-20 17:12:35.740766', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 761, 1, 'Dâu tây rửa sạch nhiều lần với nước muối pha loãng, cắt nhỏ rồi cho vào máy sinh tố xay nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (5022, '2025-11-20 17:12:38.063686', '2025-11-20 17:12:38.063686', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 770, 5, 'Khi chiên khoai tây nên chiên ngập dầu, thử đầu đũa sủi tăm là đạt độ nóng, hạ nhỏ lửa và chia từng mẻ chiên.', 10);
INSERT INTO public.recipe_steps VALUES (4976, '2025-11-20 17:12:35.741878', '2025-11-20 17:12:35.741878', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 761, 2, 'Dùng máy đánh trứng đánh nổi lòng đỏ trứng, rồi cho từ từ đường vào và tiếp tục đánh cho tan đường, cho tiếp phần dâu đã xay vào đánh đều lên.', 10);
INSERT INTO public.recipe_steps VALUES (4977, '2025-11-20 17:12:35.743486', '2025-11-20 17:12:35.743486', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 761, 3, 'Cho tiếp kem tươi vào và tiếp tục đánh cho đến khi hỗn hợp này đều và nổi mịn, hoặc có thể đánh kem tươi riêng cho nổi, rồi trộn đều với hỗn hợp dâu trứng đường ở trên. Cho kem vào khuôn rồi cho vào tủ đá.', 10);
INSERT INTO public.recipe_steps VALUES (4978, '2025-11-20 17:12:35.744572', '2025-11-20 17:12:35.744572', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 761, 4, 'Dùng muỗng, múc kem ra ly. Trang trí thêm bánh và dâu tây tươi cắt hạt lựu.', 10);
INSERT INTO public.recipe_steps VALUES (4979, '2025-11-20 17:12:35.881926', '2025-11-20 17:12:35.881926', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 762, 3, 'Luộc lần 1 chín bánh: Nấu sôi nước, cho bánh ngào vào luộc. Khi bánh nổi lên, đợi 2 phút và chuyển màu là đã chín, vớt ra để vào 1 bát nước sôi để nguội cho bánh không dính nhau.', 10);
INSERT INTO public.recipe_steps VALUES (4980, '2025-11-20 17:12:35.883536', '2025-11-20 17:12:35.883536', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 762, 5, 'Thành phẩm: Bột nếp dẻo mịn quyện trong mật mía sóng sánh, vàng óng, ngọt đậm đà và dậy mùi gừng rất hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (4981, '2025-11-20 17:12:35.885079', '2025-11-20 17:12:35.885079', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 762, 1, 'Nhồi bột: Thêm 1/4 thìa cà phê muối vào bột nếp. Vừa rót nước nóng, vừa dùng muôi trộn đều thành hỗn hợp hơi ẩm thì dừng lại, để nguội. Rải lớp bột khô trên mặt phẳng, cho bột nếp lên nhào cho tới khi thành hỗn hợp dẻo mịn, không dính tay.  Đặt bột vào tô, bọc kín bằng màng bọc thực phẩm để ủ bột 30 phút.', 10);
INSERT INTO public.recipe_steps VALUES (4982, '2025-11-20 17:12:35.886858', '2025-11-20 17:12:35.886858', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 762, 2, 'Nặn bánh: chia bột ra thành các phần bằng nhau, vê tròn rồi ấn hơi dẹt như hình kén tằm. Làm lần lượt cho hết bột.', 10);
INSERT INTO public.recipe_steps VALUES (4983, '2025-11-20 17:12:35.889047', '2025-11-20 17:12:35.889047', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 762, 4, 'Luộc lần 2 thấm đẫm vị ngọt mật mía: cho mật mía vào nồi, rồi cho bánh vào đun cho tới khi sánh lại. Tùy theo sở thích ăn loãng hay đặc, ngọt đậm hay ngọt vừa, bạn cho nước vào điều chỉnh. cuối cùng thêm gừng thái sợi, đun thêm 2-3 phút và tắt bếp, múc ra bát.', 10);
INSERT INTO public.recipe_steps VALUES (4984, '2025-11-20 17:12:36.077167', '2025-11-20 17:12:36.077167', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 763, 3, 'Đặt khuôn, hấp khoảng 30 phút hoặc khi bột trong là bánh chín, để nguội mới cho ra khỏi khuôn.', 10);
INSERT INTO public.recipe_steps VALUES (4985, '2025-11-20 17:12:36.078924', '2025-11-20 17:12:36.078924', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 763, 4, 'Nước cốt dừa đã vắt chừa lại 1/2 chén, pha với 2 thìa cà phê, vun bột năng, còn bao nhiêu cho vào nồi. Đặt nồi nước dừa lên bếp cho 1 thìa cà phê muối và 2 thìa cà phê đường cát trắng khuấy đều. Nấu vừa nóng, cho dừa có bột năng vào khuấy liên tục đến khi sôi là được. Khi dùng xắt miếng vừa ăn, cho vào đĩa chan nước cốt dừa lên, rắc mè.', 10);
INSERT INTO public.recipe_steps VALUES (4986, '2025-11-20 17:12:36.080535', '2025-11-20 17:12:36.080535', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 763, 2, 'Chuối xắt lát mỏng 2 ly. Khi nước luộc chuối nguội, cho bột năng vào khuấy tan, lược qua rây. Đặt lên bếp để lửa nhỏ, khuấy bột nóng là được. Cho vào chút vani, nhấc xuống cho chuối vào trộn đều. Thoa dầu vào khuôn, đặt vào xửng nước đang sôi để khuôn nóng lên thì lấy ra, cho hỗn hợp bột chuối vào dàn đều.', 10);
INSERT INTO public.recipe_steps VALUES (4987, '2025-11-20 17:12:36.082177', '2025-11-20 17:12:36.082177', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 763, 1, 'Dừa nạo cho vào nước ấm, vắt lấy 400 ml nước. Chuối sứ cho vào nồi nấu cùng với 1 thìa súp đường vàng, đổ ngập nước. Khi nước sôi, để thêm 5 phút rồi vớt ra để nguội, xắt lát mỏng. Phần nước luộc chuối luợc qua rây, lường cho đủ 450 ml nước, cho đường còn lại vào khuấy tan, để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (4988, '2025-11-20 17:12:36.548145', '2025-11-20 17:12:36.548145', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 764, 1, 'Đánh tan trứng cùng hành lá.', 10);
INSERT INTO public.recipe_steps VALUES (4989, '2025-11-20 17:12:36.549201', '2025-11-20 17:12:36.549201', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 764, 3, 'Cho bánh tráng lên chảo chống dính ở lửa nhỏ nướng sơ, trở đều mặt để bánh không bị cong.', 10);
INSERT INTO public.recipe_steps VALUES (4990, '2025-11-20 17:12:36.550272', '2025-11-20 17:12:36.550272', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 764, 2, 'Làm sốt sa tế: 1,5 thìa canh sa tế, 2 thìa canh đường, 2 thìa canh bơ mặn nấu chảy, 1 thìa cà phê giấm, đánh tan.', 10);
INSERT INTO public.recipe_steps VALUES (4991, '2025-11-20 17:12:36.551858', '2025-11-20 17:12:36.551858', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 764, 4, 'Lấy một lượng trứng, hỗn hợp sốt sa tế vừa đủ dàn đều khắp mặt bánh tráng.', 10);
INSERT INTO public.recipe_steps VALUES (4992, '2025-11-20 17:12:36.552909', '2025-11-20 17:12:36.552909', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 764, 6, 'Tiếp tục nướng bánh tráng cho giòn rồi gấp đôi hoặc để nguyên cho ra đĩa cắt miếng như pizza và thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (4993, '2025-11-20 17:12:36.555066', '2025-11-20 17:12:36.555066', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 764, 5, 'Khi trứng gần chín, vỏ bánh tráng giòn, cho phô mai vào và dàn đều rồi thêm xúc xích thái nhỏ, bò khô xé sợi lên trên. Phủ tương ớt, sốt mayonnaise lên, rắc hành phi.', 10);
INSERT INTO public.recipe_steps VALUES (4994, '2025-11-20 17:12:36.556151', '2025-11-20 17:12:36.556151', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 764, 7, 'Yêu cầu thành phẩm: Vỏ bánh giòn rụm, nóng hổi, đa dạng sắc vị: màu vàng của trứng, màu đỏ của bò khô, hồng của xúc xích xanh hành lá, trắng của sốt mayonnaise…rất hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (4995, '2025-11-20 17:12:36.771155', '2025-11-20 17:12:36.771155', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 765, 4, 'Bơ + đường + trứng + muối, đánh bông, cho bột vào đánh tan đều.', 10);
INSERT INTO public.recipe_steps VALUES (4996, '2025-11-20 17:12:36.772739', '2025-11-20 17:12:36.772739', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 765, 5, 'Lấy dứa xếp vào trong khuôn đã đổ đường rồi đổ hỗn hợp bột lên trên. Đem nướng ở nhiệt độ 1800C, thời gian: 30 - 35 phút.', 10);
INSERT INTO public.recipe_steps VALUES (4997, '2025-11-20 17:12:36.77432', '2025-11-20 17:12:36.77432', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 765, 1, 'Yêu cầu thành phẩm: Bánh nở xốp, mềm, lớp caramel phủ đều lên mặt bánh, thơm mùi dứa, vị chua ngọt của nước đường và dứa.', 10);
INSERT INTO public.recipe_steps VALUES (4998, '2025-11-20 17:12:36.775906', '2025-11-20 17:12:36.775906', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 765, 2, 'Đường + 1 ít nước lọc đem đun đến khi keo lại, có màu vàng óng, đổ vào khuôn bánh tròn hoặc khay nướng loại không thủng đáy, để vào tủ lạnh cho đông cứng.', 10);
INSERT INTO public.recipe_steps VALUES (4999, '2025-11-20 17:12:36.776968', '2025-11-20 17:12:36.776968', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 765, 3, 'Dứa gọt sạch, đem cắt khoanh tròn, đục bỏ lõi, đem trần qua nước đường cho chín khoảng 50%, vớt ra, để nguội.', 10);
INSERT INTO public.recipe_steps VALUES (5023, '2025-11-20 17:12:38.065818', '2025-11-20 17:12:38.065818', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 770, 10, 'Cho khoai tây vào hộp nhựa, thêm hỗn hợp bột gia vị và lắc đều để bám các mặt.', 10);
INSERT INTO public.recipe_steps VALUES (5000, '2025-11-20 17:12:37.148771', '2025-11-20 17:12:37.148771', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 766, 3, 'Phần mỡ hành:Hành lá rửa sạch, vẩy ráo, thái nhỏ cho vào bát cùng chút muối, 2 thìa canh dầu ăn đảo đều, quay lò vi sóng 15-20 giây, gạn lấy hành riêng, phần dầu ăn thì cho vào hỗn hợp bột xay ở trên.', 10);
INSERT INTO public.recipe_steps VALUES (5001, '2025-11-20 17:12:37.150332', '2025-11-20 17:12:37.150332', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 766, 5, 'Nước chấm: Pha nước mắm: đường: nước lọc theo tỷ lệ 1:1:5 (2 thìa canh nước mắm 30 độ đạm, 2 thìa canh đường: 10 thìa canh nước lọc), khuấy và đun sôi, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (5002, '2025-11-20 17:12:37.150857', '2025-11-20 17:12:37.150857', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 766, 2, 'Cách làm phần topping:Phi thơm hành khô, cho thịt lợn xay, mộc nhĩ (đã ngâm nở, thái nhỏ) vào xào thơm, nêm nếm mắm, muối, hạt nêm vừa miệng. Đậu xanh rửa sạch, hấp chín mềm, để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (5003, '2025-11-20 17:12:37.152371', '2025-11-20 17:12:37.152371', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 766, 4, 'Nấu bánh đúc:Khuấy bánh đúc liên tục, đều tay trên lửa vừa để bột đặc quánh lại. Hạ nhỏ lửa rồi tiếp tục quấy đều cho tới khi bột chuyển màu trong, dẻo quánh, thời gian khoảng 15 phút.', 10);
INSERT INTO public.recipe_steps VALUES (5004, '2025-11-20 17:12:37.154651', '2025-11-20 17:12:37.154651', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 766, 7, 'Yêu cầu thành phẩm: Bánh mềm mượt, sánh dẻo quyện với thịt băm và mộc nhĩ giòn sần sật, đậu xanh bùi bùi... làm nên bữa sáng ngon tiết kiệm thời kỳ giãn cách.', 10);
INSERT INTO public.recipe_steps VALUES (5005, '2025-11-20 17:12:37.154651', '2025-11-20 17:12:37.154651', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 766, 6, 'Trình bày và thưởng thức:Múc bánh đúc ra bát, thêm thịt băm xào mộc nhĩ, đậu xanh hấp chín, mỡ hành lá, ớt (nếu ăn được cay), rưới đẫm nước mắm chua ngọt lên trên, thêm rau mùi và thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (5006, '2025-11-20 17:12:37.157177', '2025-11-20 17:12:37.157177', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 766, 1, 'Cách làm phần bột:Cho cơm nguội cùng 1/2 nước hầm xương (hoặc nước lọc và chút muối) vào máy sinh tố xay nhuyễn, lọc qua rây. Nếu còn phần bột chưa mịn thì tiếp tục cho số nước còn lại vào xay nhuyễn, lọc tiếp qua rây lấy hỗn hợp bột gạo mịn cho vào nồi. Khuấy tan bột năng với chút nước lọc rồi cho vào hỗn hợp cơm nguội xay ở trên, đánh tan, để hỗn hợp bột nghỉ một lúc trong khi chờ làm phần topping bánh.', 10);
INSERT INTO public.recipe_steps VALUES (5007, '2025-11-20 17:12:37.401374', '2025-11-20 17:12:37.401374', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 767, 2, 'Đặt chảo lên bếp, đun chảy một thìa bơ, cho tỏi vào phi thơm, cho hành tây vào xào đến khi mềm là được, thời gian xào khoảng 5 phút. Sau đó cho hành ra một cái bát.', 10);
INSERT INTO public.recipe_steps VALUES (5008, '2025-11-20 17:12:37.402456', '2025-11-20 17:12:37.402456', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 767, 3, 'Đặt chảo trở lại bếp và cho tiếp 2 thìa bơ vào, đun ở mức lửa trung bình, cho khoai vào rán, dùng thìa đảo nhẹ. Rắc chút gia vị cho ngấm, rồi dùng thìa lật các miếng khoai để các mặt đều chín vàng, hơi giòn bên ngoài, thời gian rán độ 5 – 7 phút.', 10);
INSERT INTO public.recipe_steps VALUES (5009, '2025-11-20 17:12:37.404032', '2025-11-20 17:12:37.404032', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 767, 4, 'Cho hành tây vào chảo khoai đảo qua lại trong vài phút, nêm lại gia vị, hạt tiêu cho vừa ăn rồi tắt bếp. Khoai chín mềm, thơm phức.', 10);
INSERT INTO public.recipe_steps VALUES (5010, '2025-11-20 17:12:37.405079', '2025-11-20 17:12:37.405079', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 767, 1, 'Sắp khoai tây đã thái vào một cái âu to (chọn âu thủy tinh dùng được cho lò vi sóng). Rải một thìa bơ lên trên mặt khoai và dùng nilon bọc thức ăn phủ lên miệng âu. Cho vào lò vi sóng khoảng 5 phút đến khi khoai mềm thì lấy ra, để nguyên phần nilon và xóc khoai lên để tất cả các miếng khoai đều gần chín.', 10);
INSERT INTO public.recipe_steps VALUES (5011, '2025-11-20 17:12:37.527756', '2025-11-20 17:12:37.527756', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 768, 2, 'Đầu tiên, bạn rửa sạch, gọt vỏ và thái lát mỏng. Việc này giúp khoai nhanh chín khi hấp. Sau khi hấp chín mềm khoai, bạn dùng muỗng hoặc dụng cụ chuyên dụng để nghiền thật nhuyễn. Tiếp đó, bạn cho thêm một chai sữa chua nhỏ và 2 quả trứng, lưu ý để cả lòng đỏ và lòng trắng rồi đánh đều trước khi cho vào hũ thuỷ tinh, đậy màng bọc thực phẩm. Cuối cùng, bạn chỉ việc hấp bánh trong 30 phút là hoàn thành.', 10);
INSERT INTO public.recipe_steps VALUES (5012, '2025-11-20 17:12:37.529335', '2025-11-20 17:12:37.529335', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 768, 1, 'Khoai lang tím lành tính, màu sắc đẹp, dễ nấu từ món ngọt đến món mặn. Bên cạnh cácmón cầu kỳ, yêu cầu nhiều "hoa tay", bạn cũng có thể làm bánh khoai lang tím "siêu dễ" chỉ với 3 bước, cùng các nguyên liệu sẵn có trong gian bếp mỗi nhà.', 10);
INSERT INTO public.recipe_steps VALUES (5013, '2025-11-20 17:12:37.530457', '2025-11-20 17:12:37.530457', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 768, 3, 'Chiếc bánh có màu tím "thuỷ chung" bắt mắt, có độ đàn hồi "núng nính", vị bùi bùi của khoai lang, chua nhẹ của sữa chua, dùng làm món ăn vặt vừa an toàn lại dễ làm. Nếu không thích vị chua, bạn cũng có thể thử bằng sữa tươi và thêm chút đường cũng rất hấp dẫn. Công thức làm bánh khoai nhanh, gọn, đơn giản này được nhiều Tiktoker hội yêu bếp thả tim nhiệt tình.', 10);
INSERT INTO public.recipe_steps VALUES (5014, '2025-11-20 17:12:37.854926', '2025-11-20 17:12:37.854926', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 769, 7, 'Sau 4-5 phút, mở vung ra nướng tiếp cho đế bánh giòn. Rắc thêm hành phi, rưới tương ớt, sốt mayonnaise, tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (5015, '2025-11-20 17:12:37.856572', '2025-11-20 17:12:37.856572', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 769, 2, 'Hành lá rửa sạch, cắt nhỏ. Xúc xích cắt miếng nhỏ. Bò khô xé sợi (nếu có).', 10);
INSERT INTO public.recipe_steps VALUES (5016, '2025-11-20 17:12:37.858241', '2025-11-20 17:12:37.858241', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 769, 3, 'Phô mai cắt nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (5017, '2025-11-20 17:12:37.859827', '2025-11-20 17:12:37.859827', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 769, 4, 'Làm nóng chảo, phết lớp mỏng dầu ăn hoặc bơ, hạ nhỏ lửa, cho hỗn hợp mỳ tôm trứng vào dàn đều thành hình tròn.', 10);
INSERT INTO public.recipe_steps VALUES (5018, '2025-11-20 17:12:37.861432', '2025-11-20 17:12:37.861432', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 769, 1, 'Chần sơ mỳ tôm, để ráo. Đánh tan trứng cùng chút bột canh từ mỳ tôm. Cho mỳ vào trứng trộn đều.', 10);
INSERT INTO public.recipe_steps VALUES (5019, '2025-11-20 17:12:37.86304', '2025-11-20 17:12:37.86304', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 769, 6, 'Làm phần topping: Dàn đều lên mặt đế mỳ tôm một lớp tương cà, thêm xúc xích, bò khô xé sợi, hành lá, phô mai và đậy vung để phô mai tan chảy.', 10);
INSERT INTO public.recipe_steps VALUES (5020, '2025-11-20 17:12:37.864733', '2025-11-20 17:12:37.864733', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 769, 5, 'Khi mặt dưới đế vàng giòn đều, thì lật ngược để làm giòn phần mặt còn lại.', 10);
INSERT INTO public.recipe_steps VALUES (5021, '2025-11-20 17:12:37.866337', '2025-11-20 17:12:37.866337', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 769, 8, 'Lấy pizza mì tôm ra đĩa, cắt thành miếng nhỏ và thưởng thức nóng.', 10);
INSERT INTO public.recipe_steps VALUES (5024, '2025-11-20 17:12:38.067511', '2025-11-20 17:12:38.067511', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 770, 7, 'Nếu muốn để được lâu vẫn giòn rụm thì nên chiên 2 lần lửa: Chiên lần 1 khi khoai săn lại và có bột trắng thì vớt ra để nguội, sau đó chiên lần 2 cho tới khi vàng giòn ở lửa nhỏ vừa.', 10);
INSERT INTO public.recipe_steps VALUES (5025, '2025-11-20 17:12:38.069754', '2025-11-20 17:12:38.069754', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 770, 9, 'Về hỗn hợp bột gia vị: Trộn 1 thìa cà phê bột ớt Hàn Quốc, 1 thìa cà phê bột canh gia vị, 2 thìa canh đường, 1/2 thìa cà phê bột tỏi, 1 thìa cà phê lá thơm của Ý hoặc rau mùi chiên giòn (tùy chọn).', 10);
INSERT INTO public.recipe_steps VALUES (5026, '2025-11-20 17:12:38.070825', '2025-11-20 17:12:38.070825', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 770, 6, 'Nếu ăn luôn thì bạn chiên một lần lửa vừa, cho tới khi vàng giòn.', 10);
INSERT INTO public.recipe_steps VALUES (5027, '2025-11-20 17:12:38.072412', '2025-11-20 17:12:38.072412', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 770, 4, 'Vớt khoai ra thấm khô hoặc để ráo nước hoàn toàn.', 10);
INSERT INTO public.recipe_steps VALUES (5028, '2025-11-20 17:12:38.07401', '2025-11-20 17:12:38.07401', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 770, 3, 'Nếu không chọn được khoai tây màu vàng, bạn có thể tạo màu hấp dẫn bằng cách: cho khoai vào chần sơ 1-2 phút với nước sôi có pha chút bột nghệ hoặc nghệ tươi giã dập. Vớt khoai ra ngâm nước lạnh, rửa sạch. Nếu thích màu nguyên sơ của khoai thì bỏ qua bước này.', 10);
INSERT INTO public.recipe_steps VALUES (5029, '2025-11-20 17:12:38.075632', '2025-11-20 17:12:38.075632', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 770, 2, 'Rửa khoai cho hết phần nước đục, giúp khi chiên khoai giòn hơn.', 10);
INSERT INTO public.recipe_steps VALUES (5030, '2025-11-20 17:12:38.077238', '2025-11-20 17:12:38.077238', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 770, 1, 'Khoai tây gọt bỏ vỏ, cắt hoặc bào mỏng đều hoặc tạo hình tùy thích, ngâm nước muối loãng.', 10);
INSERT INTO public.recipe_steps VALUES (5031, '2025-11-20 17:12:38.078827', '2025-11-20 17:12:38.078827', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 770, 8, 'Vớt khoai chiên ra đặt lên giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (5032, '2025-11-20 17:12:38.329254', '2025-11-20 17:12:38.329254', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 771, 1, 'Ngô hộp bỏ ra gạn khô nước.', 10);
INSERT INTO public.recipe_steps VALUES (5033, '2025-11-20 17:12:38.330839', '2025-11-20 17:12:38.330839', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 771, 4, 'Cho ra xóc cùng một chút bơ là bạn đã có đĩa ngô vàng ươm, ăn béo ngậy và giòn.', 10);
INSERT INTO public.recipe_steps VALUES (5034, '2025-11-20 17:12:38.332439', '2025-11-20 17:12:38.332439', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 771, 2, 'Cho một chút đường, một chút nước cốt dừa sau đó cho một chút bột sư tử và một lòng đỏ trứng gà quấy đều lên.', 10);
INSERT INTO public.recipe_steps VALUES (5035, '2025-11-20 17:12:38.334035', '2025-11-20 17:12:38.334035', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 771, 3, 'Tất cả các nguyên liệu bột (trừ bột sư tử thì chỉ cho một ít) pha 1/1 trộn đều, cho vào ngô xong lọc cho bớt bột. Tiếp theo, cho vào chảo dầu nóng chiên giòn.', 10);
INSERT INTO public.recipe_steps VALUES (5036, '2025-11-20 17:12:38.754725', '2025-11-20 17:12:38.754725', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 772, 1, 'Sên nhân:Đậu đỏ ngâm 3-4 giờ, cho vào nồi nấu chín mềm (lượng nước nhiều chút khoảng 400 ml vì đậu đỏ lâu chín), xay nhuyễn, rây mịn. Đổ ra chảo chống dính, thêm 70gr đường, 40ml dầu ăn, 10gr bột bắp (hoặc bột mì), 15ml nước, trộn đều và sên trên lửa nhỏ, đảo thật đều tay, trở lật thường xuyên để không bị bén, cháy. Sên tới khi nặng tay thêm mạch nha, sên tiếp cho tới khi thành khối mịn dẻo, không bị khô, không dính tay, thử lấy một ít vo viên tròn giữ nguyên dáng, không bị chảy mềm là đạt. Thời gian sên khoảng 30 phút. Chia nhân thành 8 phần bằng nhau, vo tròn.', 10);
INSERT INTO public.recipe_steps VALUES (5037, '2025-11-20 17:12:38.75633', '2025-11-20 17:12:38.75633', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 772, 3, 'Phần bột vỏ (bột nước):Trộn đều 120 g bột mì đa dụng, 25 ml dầu ăn, 25 g bơ lạt, 30 g đường, 50-60 ml nước, 1/2 muỗng cà phê muối, trộn đều rồi nhồi thành khối, bọc màng bọc thực phẩm cho bột nghỉ 30 phút, nhào mịn, chia thành 8 phần bằng nhau. Nên ủ bột khi sên nhân để giảm thời gian chờ.', 10);
INSERT INTO public.recipe_steps VALUES (5038, '2025-11-20 17:12:38.75849', '2025-11-20 17:12:38.75849', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 772, 4, 'Phần bột dầu: Trộn đều 100gr bột mì đa dụng, 50 g bơ lạt, nhào mịn, để bột nghỉ 30 phút, chia 8 phần bằng nhau.', 10);
INSERT INTO public.recipe_steps VALUES (5039, '2025-11-20 17:12:38.76007', '2025-11-20 17:12:38.76007', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 772, 8, 'Nướng bánh lần 2 + phết lòng đỏ trứng: Đánh tan 1 lòng đỏ trứng và chút dầu ăn rồi phết đều lên bề mặt bánh, thêm mè đen. Bật trước lò nướng 10 phút ở 200 độ C rồi cho bánh vào nướng lần 2 khoảng 7-8 phút khi vỏ vàng xốp là đạt.', 10);
INSERT INTO public.recipe_steps VALUES (5040, '2025-11-20 17:12:38.761668', '2025-11-20 17:12:38.761668', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 772, 6, 'Nặn và bao nhân bánh:Cho vỏ bánh vào lòng bàn tay khum lại, đặt nhân đậu đỏ trứng muối vào giữa rồi miết nhẹ để vỏ bánh bám, bao nhân kín (tránh hở nhân), rồi vo tròn bánh lại. Làm lần lượt cho tới hết.', 10);
INSERT INTO public.recipe_steps VALUES (5041, '2025-11-20 17:12:38.763259', '2025-11-20 17:12:38.763259', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 772, 2, 'Trứng muối ngâm/ hoặc rửa qua rượu khử tanh, phết chút dầu mè, rồi đem nướng 3-4 phút ở 180 độ. Ấn dẹt cho trứng muối vào, vo tròn.', 10);
INSERT INTO public.recipe_steps VALUES (5042, '2025-11-20 17:12:38.7654', '2025-11-20 17:12:38.7654', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 772, 5, 'Tạo vỏ bánh:Vo tròn bột vỏ, cán hình oval, thêm bột dầu dàn đều rồi cuộn tròn lại như bánh ốc quế. Làm lần lượt cho tới hết, để bột nghỉ 5 phút. Tiếp tục cán dẹt theo chiều dọc, gấp 2 đầu mép vào tạo thành hình vuông, cán sơ lần 1, làm lần lượt cho tới hết, rồi quay trở lại cán lần nữa.', 10);
INSERT INTO public.recipe_steps VALUES (5043, '2025-11-20 17:12:38.766979', '2025-11-20 17:12:38.766979', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 772, 9, 'Yêu cầu thành phẩm:Bánh vỏ ngoài vàng xốp nhẹ, tách thành nhiều lớp mềm bên trong, nhân đậu đỏ bùi bùi, ngọt dịu quyện với trứng muối thơm ngon.', 10);
INSERT INTO public.recipe_steps VALUES (5044, '2025-11-20 17:12:38.76856', '2025-11-20 17:12:38.76856', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 772, 7, 'Nướng bánh lần 1: Bật trước lò nướng trước 10 phút ở 200 độ, rồi cho bánh vào nướng lần 1 trong 15-16 phút.', 10);
INSERT INTO public.recipe_steps VALUES (5045, '2025-11-20 17:12:39.094764', '2025-11-20 17:12:39.094764', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 773, 3, 'Tạo hình: Với bánh trôi miền Bắc, bạn chia bột thành các khối nhỏ, cán dẹt và đặt viên đường vào trong, bọc và vê tròn lại. Với chè trôi nước miền Nam thì cách làm tương tự, cho nhân đậu xanh vào bên trong.', 10);
INSERT INTO public.recipe_steps VALUES (5046, '2025-11-20 17:12:39.096476', '2025-11-20 17:12:39.096476', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 773, 1, 'Pha màu và nhào bột: Mỗi màu lấy 5 g pha với 50-60ml nước nóng cho tan ra. Sau đó, rót từng màu đã pha nước vào 100 g bột nếp và nhào, miết đến khi bột dẻo mịn, không dính tay thì đậy kín để bột nghỉ 5 phút. Sau đó, lấy ra nhào lại cho mịn là được.', 10);
INSERT INTO public.recipe_steps VALUES (5090, '2025-11-20 17:12:41.238393', '2025-11-20 17:12:41.238393', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 780, 1, 'Gạo nếp vo sạch, ngâm với nước ấm một giờ, xả nước lạnh, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (5047, '2025-11-20 17:12:39.098093', '2025-11-20 17:12:39.098093', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 773, 5, 'Luộc chè trôi nước cũng tương tự bánh trôi. Nấu nước dùng: Đun sôi 200ml nước, thêm lượng đường theo khẩu vị. Sau đó, hòa tan 1,5 thìa canh bột năng với chút nước và cho từ từ vào nồi nước, khuấy đều cho nước sánh lại. Thêm dừa nạo, gừng cắt sợi (tùy chọn) để vài phút, múc ra chan vào là được chè trôi nước. Thêm nước cốt dừa tùy chọn.', 10);
INSERT INTO public.recipe_steps VALUES (5048, '2025-11-20 17:12:39.099672', '2025-11-20 17:12:39.099672', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 773, 6, 'Yêu cầu thành phẩm: Bánh trôi, chè trôi với vỏ bánh dẻo mềm, rực rỡ sắc màu tự nhiên, vị ngọt của đường hòa cùng vị bùi của đậu xanh giúp cho Tết Hàn thực thêm phần vẹn tròn.', 10);
INSERT INTO public.recipe_steps VALUES (5049, '2025-11-20 17:12:39.10127', '2025-11-20 17:12:39.10127', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 773, 2, 'Đường nâu cắt thành khối vuông nhỏ 1 cm, dừa nạo sợi (để cho vào chè trôi nước miền Nam), vừng rang chín. Đậu xanh ngâm đãi vỏ, hấp chín, giã nhuyễn và xào cùng chút đường, dừa nạo nhỏ cho tới khi không dính tay là được, vê viên tròn nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (5050, '2025-11-20 17:12:39.102892', '2025-11-20 17:12:39.102892', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 773, 4, 'Luộc bánh trôi: Đun sôi nồi nước, cho các viên bột vào luộc ở lửa vừa. Khi bánh trôi nổi lên là đã chín, vớt ra thả vào nước lạnh khoảng 2 - 3 phút để không dính nhau. Vớt ra đĩa, chấm vừng rang lên.', 10);
INSERT INTO public.recipe_steps VALUES (5051, '2025-11-20 17:12:39.470515', '2025-11-20 17:12:39.470515', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 774, 2, 'Bạn có thể dùng thêm ly nước quả hoặc bổ sung ly sữa tươi cho bữa sáng của mình.', 10);
INSERT INTO public.recipe_steps VALUES (5052, '2025-11-20 17:12:39.47209', '2025-11-20 17:12:39.47209', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 774, 5, 'Nấu nước dùng sôi, cho thịt viên vào nước, khoảng 3 phút sau cho thêm cà rốt, hành bôrô, cải ngọt, gia vị, nấm rơm, nấm linh chi. Nêm lại nước cho vừa ăn, chú ý nêm gia vị đậm đà để khi chan vào mì nước lèo trung hòa lại là vừa.', 10);
INSERT INTO public.recipe_steps VALUES (5053, '2025-11-20 17:12:39.473701', '2025-11-20 17:12:39.473701', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 774, 8, 'Thực hiện:Thái thịt xông khói thành từng sợi mỏng. Tráng trứng thật mỏng rồi cắt sợi, để riêng. Phi tỏi thơm rồi cho cơm đã nấu chín vào đảo đều.', 10);
INSERT INTO public.recipe_steps VALUES (5054, '2025-11-20 17:12:39.475292', '2025-11-20 17:12:39.475292', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 774, 10, 'Bún tươi, bò bít tết
INSERT INTO public.recipe_steps VALUES (5055, '2025-11-20 17:12:39.476352', '2025-11-20 17:12:39.476352', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 774, 3, 'Thịt viên nấu mì
INSERT INTO public.recipe_steps VALUES (5056, '2025-11-20 17:12:39.477939', '2025-11-20 17:12:39.477939', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 774, 6, 'Trần mì qua nước sôi, trần lại bằng nước lạnh để sợi mì giòn và không bị dính. Chan nước lèo vào bát mì, trần thêm một lượt để đảm bảo độ nóng. Nên ăn ngay vì mì rất nhanh bị mềm.', 10);
INSERT INTO public.recipe_steps VALUES (5057, '2025-11-20 17:12:39.479001', '2025-11-20 17:12:39.479001', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 774, 4, 'Thực hiện:Băm hoặc xay thịt rồi ướp gia vị. Sau đó, viên lại thành từng viên vừa ăn.', 10);
INSERT INTO public.recipe_steps VALUES (5058, '2025-11-20 17:12:39.480643', '2025-11-20 17:12:39.480643', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 774, 9, 'Nêm gia vị, hành bô rô, hành tây, tôm, thịt xông khói, trứng, hạt tiêu, gia vị rồi đảo đều cho đến khi cơm săn vàng lại là ăn được.', 10);
INSERT INTO public.recipe_steps VALUES (5059, '2025-11-20 17:12:39.481737', '2025-11-20 17:12:39.481737', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 774, 7, 'Cơm chiên
INSERT INTO public.recipe_steps VALUES (5060, '2025-11-20 17:12:39.482794', '2025-11-20 17:12:39.482794', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 774, 11, 'Thực hiện:Ướp bò khoảng vài tiếng trước khi xào. Phi tỏi thơm, xào thịt bò thật nhanh bằng lửa lớn. Để thịt bò ra đĩa riêng.', 10);
INSERT INTO public.recipe_steps VALUES (5061, '2025-11-20 17:12:39.484398', '2025-11-20 17:12:39.484398', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 774, 12, 'Nấu nước dùng sôi, cho dưa leo và nêm nếm gia vị sao cho vừa ăn. Bún để sẵn ở bát, trần qua nước dùng, sau đó để thịt bò xào lên trên, rắc hành, ngò, đậu phộng rồi chan nước lèo, dùng nóng.', 10);
INSERT INTO public.recipe_steps VALUES (5062, '2025-11-20 17:12:39.485477', '2025-11-20 17:12:39.485477', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 774, 1, 'Dưa cuộn thịt xông khói
INSERT INTO public.recipe_steps VALUES (5063, '2025-11-20 17:12:39.979541', '2025-11-20 17:12:39.979541', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 775, 3, 'Cho bún ra tô, cho sườn non chặt miếng vừa, chả viên, chả quế vào. Chan nước dùng, rải hành ngò, hành phi, tiêu lên trên.', 10);
INSERT INTO public.recipe_steps VALUES (5064, '2025-11-20 17:12:39.981121', '2025-11-20 17:12:39.981121', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 775, 1, 'Cho sườn vào nấu với 2 lít nước. Nêm gia vị. Khi nước dùng nấu xong thì lấy thịt băm nấu tan vào trong nước dùng.', 10);
INSERT INTO public.recipe_steps VALUES (5065, '2025-11-20 17:12:39.982709', '2025-11-20 17:12:39.982709', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 775, 4, 'Dùng chung với ớt, mắm tôm, satế, rau sống, chanh.', 10);
INSERT INTO public.recipe_steps VALUES (5066, '2025-11-20 17:12:39.984311', '2025-11-20 17:12:39.984311', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 775, 2, 'Giò sống trộn với đầu hành băm, tiêu. Lấy 1/2 vo viên mang chiên vàng. 1/2 còn lại trộn với nấm mèo, vo viên, thả vào nồi nước dùng nấu chín.', 10);
INSERT INTO public.recipe_steps VALUES (5067, '2025-11-20 17:12:40.465913', '2025-11-20 17:12:40.465913', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 776, 3, 'Hấp chín và sốt xíu mại
INSERT INTO public.recipe_steps VALUES (5091, '2025-11-20 17:12:41.241028', '2025-11-20 17:12:41.241028', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 780, 2, 'Đậu xanh rửa sạch, ngâm nước nóng (nếu còn vỏ) trong 1 giờ, đãi sạch, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (5068, '2025-11-20 17:12:40.467519', '2025-11-20 17:12:40.467519', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 776, 2, 'Làm nước sốt xíu mại
INSERT INTO public.recipe_steps VALUES (5069, '2025-11-20 17:12:40.468583', '2025-11-20 17:12:40.468583', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 776, 1, 'Chuẩn bị, tạo hình xíu mại
INSERT INTO public.recipe_steps VALUES (5070, '2025-11-20 17:12:40.665429', '2025-11-20 17:12:40.665429', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 777, 6, 'Xới xôi ra đĩa, thưởng thức cùng muối vừng hoặc chả lụa, chả mỡ đều ngon.', 10);
INSERT INTO public.recipe_steps VALUES (5071, '2025-11-20 17:12:40.667021', '2025-11-20 17:12:40.667021', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 777, 3, 'Trộn gạo nếp và lạc, thêm 1/2 thìa cà phê muối, 1 thìa canh mỡ gà (hoặc dầu ăn), đảo đều.', 10);
INSERT INTO public.recipe_steps VALUES (5072, '2025-11-20 17:12:40.668618', '2025-11-20 17:12:40.668618', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 777, 5, 'Cho gạo nếp và lạc vào, thêm lượng nước xâm xấp mặt gạo. Bật chế độ nấu lần 1, khi nồi chuyển sang chế độ giữ ấm thì đảo nhẹ xôi. Tiếp tục bật chế độ nấu lần 2, khi nồi chuyển chế độ giữ ấm để thêm tầm 15 phút là xôi chín.', 10);
INSERT INTO public.recipe_steps VALUES (5073, '2025-11-20 17:12:40.670181', '2025-11-20 17:12:40.670181', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 777, 1, 'Gạo nếp vo sạch, ngâm trước đó 1 giờ rồi xả nước lạnh, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (5074, '2025-11-20 17:12:40.671771', '2025-11-20 17:12:40.671771', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 777, 4, 'Lót lá dứa dưới đáy nồi cơm điện để tạo mùi thơm và chống bén đáy. Nếu không có lá nếp, có thể dùng giấy bạc thay thế.', 10);
INSERT INTO public.recipe_steps VALUES (5075, '2025-11-20 17:12:40.673922', '2025-11-20 17:12:40.673922', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 777, 2, 'Lạc rửa sạch, luộc chín (khoảng 25-30 phút), vớt ra để ráo. Nếu ngâm qua đêm thì thời gian luộc lạc nhanh mềm hơn.', 10);
INSERT INTO public.recipe_steps VALUES (5076, '2025-11-20 17:12:40.841938', '2025-11-20 17:12:40.841938', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 778, 2, 'Nấm đùi gà thái lát chéo dày khoảng 0,3 - 0,4 cm rồi thái chân hương, đem chần sơ vớt ra ngâm vào nước lạnh, dùng khăn xô vắt ráo nước. Miến ngâm mềm, chần sơ cho mềm, vớt ra tráng qua nước lọc sạch, để rổ thưa cho ráo nước và không dính sợi, cắt khúc khoảng 5 -  6 cm vừa ăn. Ớt thái lát, lá chanh thái chỉ. Bột thính gạo có thể mua hoặc làm sẵn trước gồm gạo tẻ: đỗ xanh: gạo nếp tỷ lệ 1:1:3 (50 gr gạo tẻ, 50 gr đậu xanh không vỏ, 150 gr gạo nếp), rang vàng thơm từng loại, xay riêng mịn, lọc qua rây rồi trộn chung.', 10);
INSERT INTO public.recipe_steps VALUES (5077, '2025-11-20 17:12:40.843534', '2025-11-20 17:12:40.843534', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 778, 3, 'Đun nóng dầu ăn, cho nấm đùi gà đã vắt khô vào chiên để sợi nấm dai giòn và ngả màu hanh hanh vàng đẹp mắt. Vớt nấm ra để lên giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (5078, '2025-11-20 17:12:40.845108', '2025-11-20 17:12:40.845108', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 778, 1, 'Nấm đùi gà cắt bỏ phần cứng ở cuống, rửa qua nước muối loãng rồi rửa lại nước sạch, để ráo nước. Trong các món chay nấm đùi gà được sử dụng nhiều vừa cung cấp protein vừa có vị giòn ngọt tự nhiên.', 10);
INSERT INTO public.recipe_steps VALUES (5079, '2025-11-20 17:12:40.846801', '2025-11-20 17:12:40.846801', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 778, 4, 'Cho nấm cùng miến vào âu, nêm chút muối, hạt nêm chay, hạt tiêu cùng chút lá chanh thái chỉ, ớt rồi đeo găng tay đảo đều cho thấm vị. Từ từ xuống thính gạo, đảo dong tay là được.', 10);
INSERT INTO public.recipe_steps VALUES (5080, '2025-11-20 17:12:40.848402', '2025-11-20 17:12:40.848402', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 778, 5, 'Các loại rau sống ăn kèm rửa sạch, bày ra đĩa bên cạnh nem thính chay. Trên cùng rắc thêm lá chanh, ớt thái lát tăng thêm phần bắt mắt.', 10);
INSERT INTO public.recipe_steps VALUES (5081, '2025-11-20 17:12:41.03427', '2025-11-20 17:12:41.03427', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 779, 8, 'Phết một lớp dầu ăn mỏng lên chảo chống dính, khi chảo nóng thì cho bánh vào rán vàng đều hai mặt trên lửa nhỏ vừa.', 10);
INSERT INTO public.recipe_steps VALUES (5082, '2025-11-20 17:12:41.036934', '2025-11-20 17:12:41.036934', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 779, 7, 'Tiếp tục cán các miếng bột xoắn ốc thành hình tròn mỏng. Làm lần lượt cho tới khi hết bột.', 10);
INSERT INTO public.recipe_steps VALUES (5083, '2025-11-20 17:12:41.039016', '2025-11-20 17:12:41.039016', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 779, 6, 'Phết một lớp bơ và hành lá lên bề mặt và cuộn tròn dài lại. Sau đó, cuộn như hình xoắn ốc, gập các mép dính lại.', 10);
INSERT INTO public.recipe_steps VALUES (5084, '2025-11-20 17:12:41.040587', '2025-11-20 17:12:41.040587', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 779, 2, 'Trộn 200 gram bột mì với 1/2 thìa cà phê muối, 1 thìa canh dầu ăn và rót từ từ nước ấm vào từng chút bột và vừa nhào. Nhào bột cho tới khi hỗn hợp dẻo mềm, không còn dính tay.', 10);
INSERT INTO public.recipe_steps VALUES (5085, '2025-11-20 17:12:41.042191', '2025-11-20 17:12:41.042191', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 779, 5, 'Thoa nhẹ lớp bột ở bề mặt, lần lượt lấy từng phần bột vê tròn, dùng cán để cán mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (5086, '2025-11-20 17:12:41.044321', '2025-11-20 17:12:41.044321', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 779, 1, 'Bơ cho vào lò vi sóng cho tan chảy, thêm 1 thìa canh bột mì cùng hành lá xắt nhỏ, chút muối và hạt nêm đảo đều, cho vào lò vi sóng quay 20 giây. Để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (5087, '2025-11-20 17:12:41.046452', '2025-11-20 17:12:41.046452', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 779, 3, 'Thoa nhẹ lớp dầu dưới tô, cho bột mì vào, bọc màng bọc thực phẩm kín để bột nghỉ 30 phút.', 10);
INSERT INTO public.recipe_steps VALUES (5088, '2025-11-20 17:12:41.048039', '2025-11-20 17:12:41.048039', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 779, 9, 'Bánh chín lấy ra, cắt miếng và thưởng thức cùng tương ớt hoặc xì dầu đều ngon.', 10);
INSERT INTO public.recipe_steps VALUES (5089, '2025-11-20 17:12:41.049601', '2025-11-20 17:12:41.049601', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 779, 4, 'Sau đó, tiếp tục nhào bột dẻo mịn, chia thành 4 phần đều nhau.', 10);
INSERT INTO public.recipe_steps VALUES (5092, '2025-11-20 17:12:41.243143', '2025-11-20 17:12:41.243143', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 780, 4, 'Lót lá dứa dưới đáy nồi cơm điện (vừa tạo mùi thơm, vừa chống bén nồi). Nếu không có lá dứa, bạn có thể lót đáy bằng giấy bạc.', 10);
INSERT INTO public.recipe_steps VALUES (5093, '2025-11-20 17:12:41.24641', '2025-11-20 17:12:41.24641', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 780, 5, 'Cho gạo và đỗ xanh vào nồi, thêm 480 ml nước và bật chế độ nấu cơm bình thường.', 10);
INSERT INTO public.recipe_steps VALUES (5094, '2025-11-20 17:12:41.249094', '2025-11-20 17:12:41.249094', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 780, 6, 'Xôi chín, xới xôi ra đĩa thưởng thức cùng muối vừng hoặc chả lụa tùy chọn.', 10);
INSERT INTO public.recipe_steps VALUES (5095, '2025-11-20 17:12:41.251797', '2025-11-20 17:12:41.251797', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 780, 3, 'Trộn gạo và đậu xanh, thêm 1/2 thìa cà phê muối, 1 thìa canh dầu hành (hoặc dầu ăn), đảo nhẹ đều tránh hạt nếp vỡ.', 10);
INSERT INTO public.recipe_steps VALUES (5096, '2025-11-20 17:12:41.385684', '2025-11-20 17:12:41.385684', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 781, 1, 'Đập trứng ra bát, cho một thìa muối, đánh đều. Hành tây, cà rốt thái hạt lựu cho vào bát trứng, đánh cho các nguyên liệu quyện vào nhau.', 10);
INSERT INTO public.recipe_steps VALUES (5097, '2025-11-20 17:12:41.387794', '2025-11-20 17:12:41.387794', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 781, 4, 'Cho trứng ra đĩa, dùng dao cắt chéo thành nhiều miếng mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (5098, '2025-11-20 17:12:41.38937', '2025-11-20 17:12:41.38937', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 781, 2, 'Đặt chảo lên bếp, đun nóng dầu ăn rồi đổ trứng vào rán. Để lửa mức trung bình để các loại rau củ chín cùng với trứng.', 10);
INSERT INTO public.recipe_steps VALUES (5099, '2025-11-20 17:12:41.390979', '2025-11-20 17:12:41.390979', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 781, 3, 'Khi thấy mặt trứng se lại thì đặt một lá rong biển lên, chờ một phút rồi dùng bàn xảm hoặc thìa lật nhẹ nhàng mép miếng trứng lên, giữ một lúc. Sau đó lật tiếp tục, cuộn miếng trứng lại, úp mép trứng xuống mặt chảo rán thêm 1 phút rồi tắt bếp.', 10);
INSERT INTO public.recipe_steps VALUES (5100, '2025-11-20 17:12:41.738768', '2025-11-20 17:12:41.738768', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 782, 1, 'Các món phô mai đút lò luôn có sức hấp dẫn vì vừa ngậy vừa thơm, và phổ biến nhất là pasta đút lò, nui đút lò... Tuy nhiên, bạn cũng có thể biến tấu tô cơm nguội của mình thành chiếc bánh phô mai đút lò ngon lành, tiết tiệm mà lại dễ làm.', 10);
INSERT INTO public.recipe_steps VALUES (5101, '2025-11-20 17:12:41.740514', '2025-11-20 17:12:41.740514', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 782, 4, 'Bạn nấu tới khi phô mai tan chảy hết là xong món phô mai đút lò nhưng không cần lò nướng. Thời gian nấu và chuẩn bị chỉ tầm 30 phút là xong thố cơm như chiếc bánh phô mai lạ miệng, nhưng cũng khá quen thuộc vì hương vị phần cơm ở giữa hơi giống cơm chiên Dương Châu. Hạt cơm mềm, lẫn với đậu Hà Lan, bắp ngọt, cà rốt..., có một chút vị chua của cà, nước sốt ketchup, kèm thịt nguội và phô mai béo ngậy, thích hợp cho cả người lớn lẫn trẻ em.', 10);
INSERT INTO public.recipe_steps VALUES (5102, '2025-11-20 17:12:41.743205', '2025-11-20 17:12:41.743205', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 782, 3, 'Cho một chút dầu ăn vào chảo nóng. Lưu ý, không nên dùng nhiều dầu ăn, dễ bị ngấy. Đổ cơm vào, ấn chặt xuống đáy chảo. Tráng một lớp mỏng ketchup hoặc tương cà. Xếp đều giăm bông hay xúc xích tùy ý. Cuối cùng, bạn phủ một lớp phô mai mozzarella bào sợi lên trên cùng, đậy nắp, nấu trên lửa thật nhỏ, tránh bị cháy.', 10);
INSERT INTO public.recipe_steps VALUES (5103, '2025-11-20 17:12:41.745345', '2025-11-20 17:12:41.745345', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 782, 2, 'Đầu tiên, bạn cho trứng gà vào cơm. Bạn nên dùng cơm nấu hơi khô một chút thì món ăn sẽ ngon hơn so với cơm nấu nhão, mềm. Tiếp đến, bạn đổ cà chua và hành tây thái hạt lựu, rồi hỗn hợp cà rốt, bắp, đậu vào. Trộn đều. Nêm một chút muối vừa ăn, tiếp tục trộn cho gia vị thấm.', 10);
INSERT INTO public.recipe_steps VALUES (5104, '2025-11-20 17:12:42.167466', '2025-11-20 17:12:42.167466', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 783, 4, 'Đun sôi nồi nước (lượng nước ngập rau muống), thêm 1 thìa cà phê muối tinh. Khi nước sôi, cho rau muống vào chần khoảng 2 phút, đảo và nhấn chìm cho rau chín đều các mặt. Vớt rau muống ra cho vào âu nước sôi để nguội thêm đá viên để hãm nhiệt, giúp rau xanh và giòn sần sật. Sau đó, vớt ra rổ, ép cho ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (5105, '2025-11-20 17:12:42.170751', '2025-11-20 17:12:42.170751', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 783, 2, 'Đậu phụ cắt ngang khoảng 2,5 - 3cm, cho vào chảo dầu nóng, rán vàng, vớt ra giấy thấm dầu. Để nguội cắt chân hương. Đậu phụ tăng vị bùi béo và chất đạm cho món ăn thêm phần hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (5106, '2025-11-20 17:12:42.172864', '2025-11-20 17:12:42.172864', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 783, 5, 'Trộn nộm để khô ráo và thấm vị cần trộn nộm 2 lần sốt. Lần 1: Cho rau muống, giá đỗ, đậu phụ vào âu lớn, cho 1/2 hỗn hợp nước sốt vào trộn đều để 5 - 6 phút cho thấm. Sau đó, chắt bỏ nước đi. Lần 2: Tiếp tục, cho 1/2 lượng nước sốt nộm còn lại vào đảo đều cho thấm trọn vị chua cay mặn ngọt. Sau đó, tiếp tục chắt nước cho nộm khô ráo. Cuối cùng, mới cho rau thơm, 1/2 lượng lạc rang giã dập vào đảo đều. Trình bày nộm ra đĩa, rắc phần lạc rang còn lại lên trên và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (5107, '2025-11-20 17:12:42.174456', '2025-11-20 17:12:42.174456', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 783, 1, 'Rau muống nhặt lấy phần cọng non, bỏ gốc và ngắt bớt bớt lá. Rửa sạch rau muống, để ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (5108, '2025-11-20 17:12:42.177138', '2025-11-20 17:12:42.177138', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 783, 6, 'Yêu cầu thành phẩm: Rau muống xanh giòn, đậu phụ vỏ giòn bên trong mềm bùi, quyện với lạc rang giòn thơm, vị chua cay mặn ngọt hài hòa. Món ăn chay dân dã này vừa đủ dinh dưỡng lại làm phong phú thêm thực đơn dịp Vu Lan.', 10);
INSERT INTO public.recipe_steps VALUES (5109, '2025-11-20 17:12:42.179467', '2025-11-20 17:12:42.179467', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 783, 3, 'Lạc rang vàng, xoa bỏ vỏ, giã dập. Giá đỗ rửa sạch, chần sơ, vớt ra để ráo. Rau thơm (kinh giới hoặc rau răm tùy chọn) rửa sạch, vẩy ráo, thái rối. Pha hỗn hợp nước sốt nộm gồm: 2 thìa canh nước mắm chay (30 - 40 độ đạm), 1,5 - 2 thìa canh đường, 1 thìa canh giấm (hoặc nước cốt chanh) khuấy đều cho tan, thêm ớt băm nhỏ (tùy chọn). Nêm nếm điều chỉnh vị chua - cay - mặn - ngọt theo khẩu vị cá nhân.', 10);
INSERT INTO public.recipe_steps VALUES (5113, '2025-11-20 17:12:42.443669', '2025-11-20 17:12:42.443669', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 784, 3, 'Pha hỗn hợp nước sốt gồm 1,5 thìa canh nước mắm chay, 1 thìa canh nước tương, 1 thìa canh tương ớt, 1 thìa canh nước màu, 1 thìa cà phê hạt nêm chay, 1 thìa cà phê hạt tiêu và 100ml nước khuấy đều.', 10);
INSERT INTO public.recipe_steps VALUES (5114, '2025-11-20 17:12:42.44575', '2025-11-20 17:12:42.44575', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 784, 1, 'Cà tím cắt bỏ cuống, thái vát dày khoảng 2 cm, giữ nguyên cả vỏ để khi kho không bị nhũn. Ngâm cà vào chậu nước muối loãng, pha thêm nước cốt chanh để cà không bị thâm đen và khử bớt độc tố.', 10);
INSERT INTO public.recipe_steps VALUES (5115, '2025-11-20 17:12:42.447899', '2025-11-20 17:12:42.447899', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 784, 6, 'Yêu cầu thành phẩm: Cà mềm dẻo, giữ nguyên hình dáng, thấm vị mặn ngọt hài hòa, nước sốt sóng sánh màu hổ phách kích thích vị giác.', 10);
INSERT INTO public.recipe_steps VALUES (5116, '2025-11-20 17:12:42.698518', '2025-11-20 17:12:42.698518', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 785, 2, 'Cho bơ, đường, muối đánh bông bằng máy, đầu tiên chậm rồi nhanh dần. Sau đó cho trứng gà vào (khi máy đang chạy) đánh tiếp cho bông.', 10);
INSERT INTO public.recipe_steps VALUES (5117, '2025-11-20 17:12:42.700692', '2025-11-20 17:12:42.700692', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 785, 3, 'Cho bột mỳ, baking powder trộn lẫn với nhau cho vào hỗn hợp trên. Sau đó trộn đều với hỗn hợp trên (đánh một chiều với tốc độ chậm).', 10);
INSERT INTO public.recipe_steps VALUES (5118, '2025-11-20 17:12:42.70231', '2025-11-20 17:12:42.70231', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 785, 1, 'Lưu ý: Bánh mềm, độ xốp vừa phải, thơm mùi chuối, màu vàng đậm, ăn mát.', 10);
INSERT INTO public.recipe_steps VALUES (5119, '2025-11-20 17:12:42.703886', '2025-11-20 17:12:42.703886', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 785, 4, 'Chuối thái hạt lựu nhỏ hoặc băm nát vừa, cho vào trộn với hỗn hợp trên (không nên đánh lâu).', 10);
INSERT INTO public.recipe_steps VALUES (5120, '2025-11-20 17:12:42.705482', '2025-11-20 17:12:42.705482', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 785, 5, 'Khuôn quét bơ hoặc dầu, rắc qua bột mỳ (đổ hỗn hợp trên vào nướng ở nhiệt độ 200 độ C. Thời gian nướng với bánh to khoảng 45-50 phút.', 10);
INSERT INTO public.recipe_steps VALUES (5121, '2025-11-20 17:12:43.069939', '2025-11-20 17:12:43.069939', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 786, 5, 'Trình bày và thưởng thức:Bày bánh ít trần ra đĩa, thêm mỡ hành, hành phi, tôm sấy (tùy chọn) và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (5122, '2025-11-20 17:12:43.07155', '2025-11-20 17:12:43.07155', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 786, 1, 'Phần vỏ bánh:Cho 2 chén cơm nguội và 2 chén nước nóng vào máy xay nhuyễn, lọc qua rây cho mịn. Thêm 1/2 thìa cà phê muối, 1 thìa canh dầu ăn sên bột gạo trên lửa nhỏ cho tới khi sôi nhẹ. Tắt bếp, cho từ từ 2 chén bột gạo nếp vào trộn đều, để nguội bớt và nhào bột cho tới khi thành khối, không dính tay, chia bột thành các khối bằng nhau khoảng 50 gram, vê tròn.', 10);
INSERT INTO public.recipe_steps VALUES (5123, '2025-11-20 17:12:43.073193', '2025-11-20 17:12:43.073193', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 786, 3, 'Tạo hình bánh: Ấn dẹt viên bột vỏ bánh, đặt viên nhân vào rồi miết nhẹ để bao chặt nhân rồi vo tròn lại. Cắt lá chuối hoặc giấy nến thành các miếng vuông nhỏ để lót bánh, thoa chút dầu ăn và đặt bánh lên.', 10);
INSERT INTO public.recipe_steps VALUES (5124, '2025-11-20 17:12:43.075928', '2025-11-20 17:12:43.075928', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 786, 2, 'Phần nhân bánh:Đậu xanh hấp chín. Phi thơm hành củ, cho thịt băm vào xào săn, thêm mộc nhĩ đã ngâm nở thái nhỏ vào, nêm mắm, muối, hạt nêm, hạt tiêu theo khẩu vị, cho đậu xanh vào trộn đều. Múc từng thìa canh và vo thành các viên nhỏ làm nhân khoảng 30 gram.', 10);
INSERT INTO public.recipe_steps VALUES (5125, '2025-11-20 17:12:43.077012', '2025-11-20 17:12:43.077012', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 786, 4, 'Hấp bánh: Cho bánh vào xửng hấp chín. Phủ thêm khăn xô để tránh nước bị rơi xuống làm nhão bánh.', 10);
INSERT INTO public.recipe_steps VALUES (5126, '2025-11-20 17:12:43.413579', '2025-11-20 17:12:43.413579', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 787, 3, 'Chiên bánh:Cho dầu vào chảo sâu lòng (lượng dầu ngập bánh), thử đầu đũa sủi tăm là dầu đạt độ nóng, hạ lửa nhỏvừa và cho từng bánh vào chiên. Khi chiên, một tay dùng đũa xoay, một tay dùng vá (muôi)ấn xuống. Khi thấy bong bóng nổi nhỏ thì múc dầu nóngđổ lên liên tụcgiữa bánh đều để đủ độ nóng sẽ giúp bánh nở phồng to. Trở đều các mặt rồi chiên vàng đều. Làm lần lượt các bánh cho tới khi hết. Vớt bánh ra để đứng trên giấy thấm dầu, không để bánh nằm ngang dễ bị xẹp.', 10);
INSERT INTO public.recipe_steps VALUES (5127, '2025-11-20 17:12:43.415729', '2025-11-20 17:12:43.415729', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 787, 1, 'Trộn bột:Cho sữa, nước, đường, muối vào nồi khuấy tan đường và đun sôi lăn tăn rồi tắt bếp. Từ từ cho hỗn hợp này vào tô đựng bột mì và trộn đều. Điều chỉnh lượng nước theo độ hút nước nhiều hay ít của bột mì cũ hay mới. Trộn đều tay để thành khối kết dính là được, không nên nhồi lâu sẽ làm bánh bị dai.', 10);
INSERT INTO public.recipe_steps VALUES (5128, '2025-11-20 17:12:43.417359', '2025-11-20 17:12:43.417359', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 787, 2, 'Tạo hình bánh:Thoa chút dầu ăn lên bề mặt khối bột và mặt phẳng. Chia bột thành các khối đều nhau. Vê tròn từng khối bột, rồi lăn qua mè (vừng) để lớp mè bám đều các mặt. Đặt lên mặt phẳng rồi cán bột thành hình tròn mỏng. Tùy theo sở thích mỗi người thích ruột dày hay rỗng để điều chỉnh độ mỏng của bột (cán mỏng thì ruột càng rỗng).', 10);
INSERT INTO public.recipe_steps VALUES (5129, '2025-11-20 17:12:43.419026', '2025-11-20 17:12:43.419026', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 787, 4, 'Thành phẩm:Vỏ bánh vàng giòn, nở phồng, ruột xốp, dậy mùi thơm của mè, vị ngọt nhẹ rất hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (5130, '2025-11-20 17:12:43.691685', '2025-11-20 17:12:43.691685', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 788, 1, 'Hấp khoai, nhào bột: Khoai gọt vỏ, cắt miếng, hấp chín mềm, nghiền nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (5131, '2025-11-20 17:12:43.69435', '2025-11-20 17:12:43.69435', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 788, 3, 'Nặn bánh: Chia khoai thành các khối bằng nhau. Vê tròn các khối, ấn dẹt, cho phô mai mozzarella cắt nhỏ vào giữa, miết mép và vê tròn, ấn hơi dẹt.', 10);
INSERT INTO public.recipe_steps VALUES (5132, '2025-11-20 17:12:43.696459', '2025-11-20 17:12:43.696459', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 788, 5, 'Chiên hoặc nướng bánh: Cho dầu vào chảo, thử đầu đũa sủi tăm thì hạ lửa nhỏ vừa, cho bánh vào chiên. Trở đều các mặt cho chín vàng đều. Bạn có thể nướng bằng nồi chiên không dầu.', 10);
INSERT INTO public.recipe_steps VALUES (5133, '2025-11-20 17:12:43.698811', '2025-11-20 17:12:43.698811', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 788, 2, 'Thêm 4 thìa canh bột mì, 3 thìa canh đường, 1/4 thìa cà phê muối trộn đều, đeo găng tay nhào cho tới khi trở thành hỗn hợp bột mịn dẻo. Nếu bột khô, bạn thêm ít sữa tươi hoặc nước cốt dừa vào nhào bột. Nếu muốn màu vàng ươm đẹp hơn, bạn có thể thêm chút bột nghệ vào.', 10);
INSERT INTO public.recipe_steps VALUES (5134, '2025-11-20 17:12:43.701565', '2025-11-20 17:12:43.701565', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 788, 4, 'Phết chút lòng đỏ trứng lên bề mặt bánh, rắc mè để bánh đẹp và hấp dẫn hơn.', 10);
INSERT INTO public.recipe_steps VALUES (5135, '2025-11-20 17:12:43.703675', '2025-11-20 17:12:43.703675', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 788, 6, 'Yêu cầu thành phẩm: Bánh khoai vỏ vàng, bùi bùi, vị ngọt vừa phải, nhân phô mai tan chảy, béo ngậy hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (5136, '2025-11-20 17:12:45.095598', '2025-11-20 17:12:45.095598', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 789, 5, 'Gói nem: Đặt 1 tấm bánh tráng bò bía đậu xanh lên mặt phẳng, đặt thêm 1/2 bánh tráng nữa lên lót để tránh bị vỡchả giòkhi rán. Múc lượng nhân vừa phải cho vào giữa, gập hai bên mép, rồi cuốn đều tay. Cuối cùng phết nước bột mì dính mép lại. Chú ý không nên gói chặt quá làmchả giòbị vỡ khi chiên.', 10);
INSERT INTO public.recipe_steps VALUES (5138, '2025-11-20 17:12:45.104243', '2025-11-20 17:12:45.104243', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 789, 2, 'Đậu phụ chần sơ, cho vào khăn xô vắt ráo nước rồi xào sơ cho săn, nêm chút mắm chay, hạt nêm chay cho đậm vị. Khoai lang, cà rốt bào sợi, cắt nhỏ. Miến (bún tàu) ngâm nước ấm, để ráo, cắt nhỏ. Mộc nhĩ (nấm mèo) ngâm nở, rửa sạch, để ráo nước rồi cắt nhỏ. Củ đậu thái sợi, thêm chút muối cho ra nước, vắt ráo, cắt nhỏ. Hành lá hoặc hành boa-rô cắt nhỏ. Hành khô phi thơm.', 10);
INSERT INTO public.recipe_steps VALUES (5139, '2025-11-20 17:12:45.108031', '2025-11-20 17:12:45.108031', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 789, 4, 'Cho tất cả nguyên liệu vào âu lớn, thêm 1/2 muỗng canh dầu hành phi, hành phi, 1 muỗng cà phê nước mắm chay, 1 muỗng cà phê hạt nêm chay, 1 muỗng cà phê hạt tiêu, 1 muỗng cà phê đường (tùy chọn nếu thích ngọt), 1/4 muỗng cà phê muối (bột canh), trộn đều dong tay để các nguyên liệu khô ráo.', 10);
INSERT INTO public.recipe_steps VALUES (5140, '2025-11-20 17:12:45.11103', '2025-11-20 17:12:45.11103', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 789, 1, 'Đậu xanh vorửa sạch, ngâm 3-4 giờ cho nở rồi hấp hoặc cho lượng nước xâm xấp nấu lửa nhỏ, mở vung cho tới khi đậu cạn nước, mềm khô là được.', 10);
INSERT INTO public.recipe_steps VALUES (5141, '2025-11-20 17:12:45.113196', '2025-11-20 17:12:45.113196', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 789, 8, 'Trước khi ăn,cho chả giò vàochiên ở lửa vừa, lật trở các mặt cho chín đều. Khiđã đạt độ giòn mong muốn thì tăng lửa cho thoát dầu.', 10);
INSERT INTO public.recipe_steps VALUES (5142, '2025-11-20 17:12:45.115872', '2025-11-20 17:12:45.115872', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 789, 9, 'Chả giòđạt yêu cầu là vỏ bên ngoài lên màu vàng ươm, giòn rụm, bên trong nhân rau củ quả mềm ngọt mà không bị chảy nước. Vị giòn, ngọt, bùi đan xen hấp dẫn. Khi ăn chấm đẫm nước mắm chay chua ngọt, ăn cùng rau sống, bún rất hao.', 10);
INSERT INTO public.recipe_steps VALUES (5143, '2025-11-20 17:12:45.118011', '2025-11-20 17:12:45.118011', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 789, 3, 'Pha 2 thìa canh bột mì với chút nước cho sền sệt để dán mép khi cuốn chả giò.', 10);
INSERT INTO public.recipe_steps VALUES (5144, '2025-11-20 17:12:45.119819', '2025-11-20 17:12:45.119819', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 789, 7, 'Ránchả giòlần 1vừachín, se lại: Cho dầu ăn vào chảo, đợi dầu nóng (thử đầu đũa sủi tăm là đạt), hạ lửa nhỏ vừa và chochả giòvào chiên. Khichả giòse mặt và chín khoảng 70 - 80% thì vớt ra để giấy thấm dầu cho nguội hẳn. Nếu làm nhiều thì chia ra các mẻ cho mỗi bữa ăn rồi đem cấp đông.', 10);
INSERT INTO public.recipe_steps VALUES (5145, '2025-11-20 17:12:45.912411', '2025-11-20 17:12:45.912411', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 790, 5, 'Chiên bánh:Cho dầu vào chảo sâu lòng, lượng dầu ngập bánh, đun nóng, lấy đũa thử nếu đầu đũa sủi tăm là đạt, hạ lửa nhỏ vừa. Lần lượt chia các mẻ cho bánh vào chiên cho đến khi vàng đều hai mặt. Gắp ra đặt lên giấy thấm dầu.', 10);
INSERT INTO public.recipe_steps VALUES (5146, '2025-11-20 17:12:45.914661', '2025-11-20 17:12:45.914661', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 790, 6, 'Làm nước chấm:Pha nước mắm: đường: chanh: nước lọc theo tỷ lệ 1:1:1:5 (2 thìa canh nước mắm 30 độ đạm, 2 thìa canh đường, 2 thìa canh nước cốt chanh, 10 thìa canh nước lọc, khuấy tan hẳn đường thì cho tỏi, ớt băm nhuyễn vào).', 10);
INSERT INTO public.recipe_steps VALUES (5147, '2025-11-20 17:12:45.916238', '2025-11-20 17:12:45.916238', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 790, 7, 'Làm dưa góp:Đu đủ và cà rốt gọt vỏ, xắt lát mỏng, ngâm muối rồi rửa sạch. Thêm đường, giấm hoặc chanh, chút muối, tỏi, ớt vừa vị.', 10);
INSERT INTO public.recipe_steps VALUES (5148, '2025-11-20 17:12:45.917831', '2025-11-20 17:12:45.917831', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 790, 8, 'Các loại rau sống, rửa sạch, ngâm nước muối loãng, vẩy ráo nước.', 10);
INSERT INTO public.recipe_steps VALUES (5149, '2025-11-20 17:12:45.919936', '2025-11-20 17:12:45.919936', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 790, 2, 'Lấy bột đã ủ ra, thoa một lớp bột lên mặt phẳng, dùng chai thủy tinh dài hoặc cán chuyên dụng để cán bột mỏng. Lấy một khuôn hoặc vật hình tròn (cái bát nhỏ) ấn nhẹ tạo hình tròn và lấy ra. Làm lần lượt cho tới hết, phần bột thừa tiếp tục cán và tạo hình tròn. Khi xếp các vỏ bánh, bạn nhớ thoa 1 lớp bột để tránh dính vào nhau.', 10);
INSERT INTO public.recipe_steps VALUES (5150, '2025-11-20 17:12:45.921563', '2025-11-20 17:12:45.921563', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 790, 3, 'Làm phần nhân:Trộn đều thịt nạc vai xay (có chút mỡ) với mộc nhĩ ngâm mềm xắt nhỏ, hành tây xắt hạt lựu nhỏ, miến ngâm mềm cắt nhỏ, hành lá xắt nhỏ, nêm chút nước mắm, hạt tiêu, hạt nêm, trộn đều, để ướp 15 phút. Trứng gà (hoặc trứng cút) luộc chín, bóc vỏ, nếu trứng gà thì cắt thành 4 hoặc 6 phần bằng nhau.', 10);
INSERT INTO public.recipe_steps VALUES (5151, '2025-11-20 17:12:45.923676', '2025-11-20 17:12:45.923676', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 790, 1, 'Làm vỏ bánh:Cho  250 gr bột mì, 50 gr bột gạo nếp, 1 thìa dầu ăn, 1 thìa cà phê muối, 1 quả trứng gà, 1/2 thìa cà phê bột nghệ vào tô trộn đảo đều. Từ từ vừa cho nước, vừa nhào bột (căn chỉnh lượng nước tùy thuộc bột mới hay cũ sẽ hút khác nhau). Nhào cho tới khi thành khối mịn dẻo, không dính tay là đạt, vê tròn và dùng màng bọc thực phẩm bọc kín miệng bát, ủ bột trong 30 phút.', 10);
INSERT INTO public.recipe_steps VALUES (5152, '2025-11-20 17:12:45.925903', '2025-11-20 17:12:45.925903', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 790, 4, 'Nặn bánh:Múc nhân cho vào bánh, đặt trứng ở giữa, thoa nhẹ ít nước và gập mép lại hình bán nguyệt, miết dính lại để khi rán dầu không bị thấm vào trong. Làm lần lượt cho đến hết.', 10);
INSERT INTO public.recipe_steps VALUES (5153, '2025-11-20 17:12:45.92749', '2025-11-20 17:12:45.92749', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 790, 9, 'Trình bày và thưởng thức: Bày bánh ra đĩa, bên cạnh là bát nước chấm thêm dưa góp vào, rau thơm. Khi ăn, cắt bánh cho vào rau xà lách cuốn lại và chấm nước mắm chua ngọt rất hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (5154, '2025-11-20 17:12:46.559001', '2025-11-20 17:12:46.559001', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 791, 7, 'Sau đó, thêm xúc xúc, rau cải thảo, hành tây vào đảo đều cho chín.', 10);
INSERT INTO public.recipe_steps VALUES (5155, '2025-11-20 17:12:46.561076', '2025-11-20 17:12:46.561076', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 791, 8, 'Nấu Tobokki cho tới khi nước sốt sền sệt là được, thêm trứng luộc, múc ra bát, rắc mè rang, hành lá xắt nhỏ và thưởng thức.', 10);
INSERT INTO public.recipe_steps VALUES (5156, '2025-11-20 17:12:46.563419', '2025-11-20 17:12:46.563419', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 791, 6, 'Cho bánh gạo vào hỗn hợp nước sốt đun sôi 1- 2 phút cho ngấm gia vị.', 10);
INSERT INTO public.recipe_steps VALUES (5157, '2025-11-20 17:12:46.565509', '2025-11-20 17:12:46.565509', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 791, 5, 'Sốt bánh gạo (điều chỉnh theo khẩu vị mỗi người): Phi thơm đầu hành, cho 1 muỗng canh đường, 1 muỗng canh tương ớt, 1 muỗng canh tương cà, 1 muỗng cà phê xì dầu, 1 muỗng cà phê ớt bột Hàn Quốc, 1/2 muỗng cà phê hạt nêm, 150 - 200ml nước lọc vào đun sôi.', 10);
INSERT INTO public.recipe_steps VALUES (5158, '2025-11-20 17:12:46.567572', '2025-11-20 17:12:46.567572', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 791, 9, 'Yêu cầu thành phẩm: Bánh gạo dẻo mềm, quyện đẫm trong nước sốt màu đỏ cam hài hòa vị mặn - ngọt - cay hấp dẫn.', 10);
INSERT INTO public.recipe_steps VALUES (5159, '2025-11-20 17:12:46.56964', '2025-11-20 17:12:46.56964', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 791, 2, 'Cho bột năng và cơm nguội đã nghiền, đeo găng tay thoa chút dầu ăn hoặc thoa bột năng rồi nhồi đều tay cho tới khi tạo thành khối dẻo mịn, không dính tay.', 10);
INSERT INTO public.recipe_steps VALUES (5160, '2025-11-20 17:12:46.572768', '2025-11-20 17:12:46.572768', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 791, 3, 'Chia bột thành các khối, lăn đều tay trên mặt phẳng để tạo thành các sợi dài. Sau đó, cắt thành từng khúc và phủ lớp bột để tránh dính nhau.', 10);
INSERT INTO public.recipe_steps VALUES (5161, '2025-11-20 17:12:46.575079', '2025-11-20 17:12:46.575079', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 791, 1, 'Cho cơm nguội vào túi zip (hoặc cối) rồi dùng chày giã nhuyễn.', 10);
INSERT INTO public.recipe_steps VALUES (5162, '2025-11-20 17:12:46.577986', '2025-11-20 17:12:46.577986', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 791, 4, 'Đun sôi nước, cho bánh gạo vào luộc. Khi bánh gạo nổi lên là chín, vớt ra cho vào bát nước lạnh để không bị dính chùm.', 10);
INSERT INTO public.recipe_steps VALUES (5163, '2025-11-20 17:12:47.35322', '2025-11-20 17:12:47.35322', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 792, 4, 'Củ hành tím bóc vò, cắt lát, phơi cho ráo mặt, phi vàng.', 10);
INSERT INTO public.recipe_steps VALUES (5164, '2025-11-20 17:12:47.355358', '2025-11-20 17:12:47.355358', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 792, 6, 'Lần thứ nhất: Hòa 1 lít nước lọc với 1 muỗng cà phê vôi ăn trầu, để lắng lấy nước trong rồi đổ nước vôi trong này vào nồi, sâm sấp mặt bắp, nấu khoảng 30 phút cho vỏ hạt bắp bong lên hết. Cho bắp ra một cái rổ có lỗ nhỏ, đợi cho bắp nguội, dùng tay chà cho hạt bắp rớt mày và bong vỏ. Xả bắp với nước nhiều lần cho hạt bắp thật sạch, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (5165, '2025-11-20 17:12:47.356959', '2025-11-20 17:12:47.356959', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 792, 9, 'Múc xôi ra đĩa, rắc đậu xanh, hành phi, đường và một chút muối đậu.', 10);
INSERT INTO public.recipe_steps VALUES (5166, '2025-11-20 17:12:47.358608', '2025-11-20 17:12:47.358608', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 792, 5, 'Muối đậu mè gồm có đậu phộng rang giã nát, trộn với mè trắng rang vàng gĩa dập và 1-2 muỗng cà phê muối trắng rang.', 10);
INSERT INTO public.recipe_steps VALUES (5167, '2025-11-20 17:12:47.360714', '2025-11-20 17:12:47.360714', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 792, 2, 'Nếp ngon, vo sạch, ngâm nước 2 giờ, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (5168, '2025-11-20 17:12:47.361793', '2025-11-20 17:12:47.361793', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 792, 3, 'Đậu xanh không vỏ, vo sạch, nấu lửa nhỏ cho chín ráo, giã từng ít một cho mịn nhuyễn, rời rạc.', 10);
INSERT INTO public.recipe_steps VALUES (5169, '2025-11-20 17:12:47.363396', '2025-11-20 17:12:47.363396', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 792, 8, 'Trộn đều bắp đã nấu mềm với nếp và 2 muỗng cà phê muối, rồi cho vào xửng hong cho xôi chín. Khoảng 10-15 phút mở nắp xửng ra, dùng đũa trộn xôi cho chín đều từ trên xuống dưới.', 10);
INSERT INTO public.recipe_steps VALUES (5170, '2025-11-20 17:12:47.365004', '2025-11-20 17:12:47.365004', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 792, 1, 'Bắp hạt khô, chọn bắp mới, vo sạch, vớt bỏ hạt nổi, ngâm nước 12 giờ.', 10);
INSERT INTO public.recipe_steps VALUES (5171, '2025-11-20 17:12:47.36723', '2025-11-20 17:12:47.36723', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 792, 7, 'Lần thứ hai: Cho bắp vào nồi, đổ nước ngang mặt bắp, thêm vào khoảng 1 muỗng cà phê muối, nấu lửa nhỏ cho bắp nở mềm rồi đổ bắp ra rổ, xả nước một lần nữa cho bắp sạch nhớt.', 10);
INSERT INTO public.recipe_steps VALUES (5172, '2025-11-20 17:12:48.099358', '2025-11-20 17:12:48.099358', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 793, 3, 'Vỏ bánh: chuẩn bị 1 thau nước hơi ấm, thêm chút dầu ăn và nước cốt chanh, lấy từng cái bánh tráng cho vào chậu nước. Sau 2 phút, bánh mềm và chuyển màu hơi đục thì đeo găng tay lấy ra trải lên khay thoa sẵn dầu, múc 1 thìa nhân thịt mộc nhĩ và gấp 2 cạnh, cuộn lại. Cho bánh dàn đều lên 1 cái đĩa đã thoa một lớp dầu mỏng.', 10);
INSERT INTO public.recipe_steps VALUES (5173, '2025-11-20 17:12:48.101471', '2025-11-20 17:12:48.101471', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 793, 4, 'Hấp bánh: Đun sôi nồi nước, cho đĩa bánh cuốn vào, phủ 1 lớp khăn xô, đậy nồi hấp 3-4 phút là bánh chín.', 10);
INSERT INTO public.recipe_steps VALUES (5174, '2025-11-20 17:12:48.10305', '2025-11-20 17:12:48.10305', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 793, 6, 'Trình bày và thưởng thức: Lấy bánh cuốn hấp chín ra, rắc thêm hành phi, dầu hành lá, rau mùi và thưởng thức kèm dưa chuột, chả lụa (tùy chọn). Khi ăn chấm với nước mắm chua ngọt.', 10);
INSERT INTO public.recipe_steps VALUES (5175, '2025-11-20 17:12:48.104613', '2025-11-20 17:12:48.104613', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 793, 7, 'Yêu cầu thành phẩm: Bánh mềm dai vừa phải, nhân thịt mộc nhĩ giòn sần sật, thơm ngon; nước mắm chấm hài hòa vị chua - cay - mặn - ngọt.', 10);
INSERT INTO public.recipe_steps VALUES (5176, '2025-11-20 17:12:48.106182', '2025-11-20 17:12:48.106182', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 793, 2, 'Xào nhân trước: Phi thơm hành tím, cho thịt vào xào săn trước, rồi cho mộc nhĩ vào sau. Cuối cùng thêm hành tây (hoặc củ sắn/củ đậu), hành lá, nêm lại gia vị phù hợp và tắt bếp, múc ra để riêng.', 10);
INSERT INTO public.recipe_steps VALUES (5177, '2025-11-20 17:12:48.107602', '2025-11-20 17:12:48.107602', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 793, 5, 'Nước chấm: Pha theo tỷ lệ nước mắm: đường: chanh: nước lọc là 1:1:1:3 (chú ý tỷ lệ này dành cho nước mắm 30 độ đạm, nếu nước mắm độ đạm cao hơn thì tăng tỷ lệ nước lên). Khuấy tan trước đường, chanh, nước lọc cho tới khi đường tan hoàn toàn thì mới thêm nước mắm, rồi tỏi, ớt băm nhỏ vào. Điều này giúp tỏi ớt nổi lên bề mặt bát nước chấm hấp dẫn hơn.', 10);
INSERT INTO public.recipe_steps VALUES (5178, '2025-11-20 17:12:48.108643', '2025-11-20 17:12:48.108643', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 793, 1, 'Thịt vai xay ướp với chút nước mắm, hạt nêm, hạt tiêu. Mộc nhĩ ngâm mềm, rửa sạch, thái nhỏ. Hành tây thái hạt lựu, hành lá thái nhỏ.', 10);
INSERT INTO public.recipe_steps VALUES (5179, '2025-11-20 17:12:48.380894', '2025-11-20 17:12:48.380894', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 794, 1, 'Rửa xà lách, rau thơm, thái sợi lớn.', 10);
INSERT INTO public.recipe_steps VALUES (5180, '2025-11-20 17:12:48.382464', '2025-11-20 17:12:48.382464', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 794, 4, 'Rán vàng một nửa số cá, phần còn lại cho ra bát.', 10);
INSERT INTO public.recipe_steps VALUES (5181, '2025-11-20 17:12:48.384593', '2025-11-20 17:12:48.384593', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 794, 5, 'Cho xương cá rô vào nồi nước dùng nấu tiếp, nêm gia vị vừa ăn, lược sạch nước.', 10);
INSERT INTO public.recipe_steps VALUES (5182, '2025-11-20 17:12:48.386202', '2025-11-20 17:12:48.386202', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 794, 2, 'Làm sạch cá rô, để ráo.', 10);
INSERT INTO public.recipe_steps VALUES (5183, '2025-11-20 17:12:48.387777', '2025-11-20 17:12:48.387777', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 794, 3, 'Đun sôi nước dùng, cho cá vào luộc chín, vớt cá ra, lọc lấy thịt.', 10);
INSERT INTO public.recipe_steps VALUES (5184, '2025-11-20 17:12:48.390018', '2025-11-20 17:12:48.390018', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 794, 6, 'Lấy bún ra bát, cho cá luộc và cá rán lên trên, rắc hành, ớt cắt khoanh, chan nước dùng ngập bún. Ăn với rau thơm, xà lách.', 10);
INSERT INTO public.recipe_steps VALUES (5185, '2025-11-20 17:12:49.306986', '2025-11-20 17:12:49.306986', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 795, 1, '*Cách làm nhân sữa dừa:
INSERT INTO public.recipe_steps VALUES (5186, '2025-11-20 17:12:49.30915', '2025-11-20 17:12:49.30915', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 795, 2, '*Cách làm phần vỏ và đóng bánh:
INSERT INTO public.recipe_steps VALUES (5187, '2025-11-20 17:12:49.311263', '2025-11-20 17:12:49.311263', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 795, 3, '* Cách nướng bánh
INSERT INTO public.recipe_steps VALUES (5188, '2025-11-20 17:12:49.801872', '2025-11-20 17:12:49.801872', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 796, 4, 'Phần nước ninh xương, lọc bỏ cặn và xương dăm, vớt bớt váng mỡ rồi cho phần gạo đã chuẩn bị ở bước 1 vào và khuấy đều.', 10);
INSERT INTO public.recipe_steps VALUES (5189, '2025-11-20 17:12:49.803475', '2025-11-20 17:12:49.803475', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 796, 5, 'Khi cháo sôi được tầm 5 phút, hạ nhỏ lửa đun liu riu đến khi cháo sánh mịn, nếu cháo đặc quá bạn có thể thêm nước. Thỉnh thoảng khuấy để cháo ko bị dính nồi và cháy khét.', 10);
INSERT INTO public.recipe_steps VALUES (5190, '2025-11-20 17:12:49.805581', '2025-11-20 17:12:49.805581', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 796, 7, 'Múc cháo ra tô, cho một ít quẩy cắt nhỏ lên trên và rắc thêm một ít tiêu xay, một ít ớt bột nữa là hoàn tất. Nếu thích bạn có thể ăn kèm rau thơm và hành phi cũng rất ngon.', 10);
INSERT INTO public.recipe_steps VALUES (5191, '2025-11-20 17:12:49.807193', '2025-11-20 17:12:49.807193', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 796, 1, 'Gạo nếp lẫn tẻ đem xay vỡ, vo sạch rồi ngâm nước 2-3 tiếng giúp cháo nhanh mềm và sánh mịn hơn.', 10);
INSERT INTO public.recipe_steps VALUES (5192, '2025-11-20 17:12:49.808796', '2025-11-20 17:12:49.808796', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 796, 2, 'Sườn sụn heo rửa sạch, chặt miếng mỏng vừa ăn, sau đó chần khoảng 2-3 phút trong nước sôi rồi vớt ra, rửa lại lần nữa cho thật sạch. Cho sườn heo vào nồi cùng 1 lít nước lọc, bật lửa nhỏ hầm khoảng 1 giờ để sườn mềm và ra nước ngọt.', 10);
INSERT INTO public.recipe_steps VALUES (5193, '2025-11-20 17:12:49.811051', '2025-11-20 17:12:49.811051', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 796, 3, 'Sườn sụn sau khi đã mềm, vớt ra bát. Ướp vào sườn 1 thìa café nước mắm để món ăn được thơm và đậm đà hơn.', 10);
INSERT INTO public.recipe_steps VALUES (5194, '2025-11-20 17:12:49.812788', '2025-11-20 17:12:49.812788', 'ledinhloc7@gmail.com', 'ledinhloc7@gmail.com', false, 796, 6, 'Khi cháo đã mềm nhừ và sánh nhựa, bạn cho phần sườn sụn vào, có thể chừa lại một ít để rắc lên trên cho hấp dẫn. Nêm nếm thêm bột canh, bột ngọt và chút nước mắm cho thơm, khuấy đều, đậy nắp nồi nấu thêm 5 phút nữa rồi tắt bếp.', 10);
